window.MODSPEC={"ung-buou": {"sections": [{"n": 1, "title": "Tổng quan", "desc": "Giới thiệu chuyên khoa, mục tiêu cần đạt (thấp đến cao), các bệnh và vấn đề cần học.", "type": "overview"}, {"n": 2, "title": "Nền tảng", "desc": "Cơ chế sinh ung thư, nguyên nhân, giải phẫu bệnh, xâm lấn – di căn, miễn dịch, phòng ngừa và tầm soát.", "type": "groups", "groups": [{"key": "Cơ chế"}, {"key": "Nguyên nhân"}, {"key": "Giải phẫu bệnh, xâm lấn, di căn, miễn dịch", "page": "Đặc điểm – giải phẫu bệnh, xâm lấn, di căn, miễn dịch", "side": "Đặc điểm"}, {"key": "Phòng ngừa và tầm soát"}, {"key": "Điều trị và chăm sóc"}]}, {"n": 3, "title": "Triệu chứng học", "desc": "Trình bày khái quát: các triệu chứng gợi ý ung thư và cách tiếp cận.", "type": "notes", "byDisease": [4], "overviewLabel": "Khái quát", "genTitle": "Bài khái quát", "disTitle": "Triệu chứng học theo từng bệnh", "tree": "list"}, {"n": 4, "title": "Cận lâm sàng", "desc": "Trình bày khái quát các phương tiện và vai trò: hình ảnh, giải phẫu bệnh, dấu ấn, phân giai đoạn.", "type": "notes", "byDisease": [5, 6], "overviewLabel": "Khái quát phương tiện, vai trò", "genTitle": "Bài khái quát: phương tiện và vai trò", "disTitle": "Cận lâm sàng và chẩn đoán theo từng bệnh", "tree": "list"}, {"n": 5, "title": "Bệnh học", "desc": "Chi tiết từng bệnh: tổng quan, triệu chứng học, cận lâm sàng, chẩn đoán, điều trị, theo dõi, tiên lượng – dự phòng.", "type": "diseases"}, {"n": 6, "title": "Cấp cứu", "desc": "Nhận diện và xử trí ban đầu các cấp cứu ung thư: chuyển hóa – huyết học, chèn ép, xuất huyết – hô hấp – thận.", "type": "notes"}, {"n": 7, "title": "Bệnh án", "desc": "Cách làm một bệnh án ung thư: hành chính, bệnh sử, tiền sử, khám, cận lâm sàng, chẩn đoán, điều trị, tiên lượng.", "type": "notes", "openAll": true}, {"n": 8, "title": "Tóm tắt", "desc": "Tổng hợp trong một trang, từng bệnh theo nguyên lý Pareto (20% kiến thức mang 80% điểm).", "type": "summary"}, {"n": 9, "title": "Nguồn", "desc": "Tài liệu trong nước, văn bản Bộ Y tế và nguồn ngoài đã dùng cho từng bài.", "type": "sources"}, {"n": 10, "title": "Tự đánh giá", "desc": "Các thẻ tự kiểm tra đã tạo (được lưu lại, tạm thời chưa xây dựng thêm).", "type": "cards"}]}, "ngoai-tong-quat": {"sections": [{"n": 1, "title": "Tổng quan", "desc": "Giới thiệu module, cấu trúc học tập và danh mục bài.", "type": "overview", "c": 1}, {"n": 2, "title": "Ngoại khoa cơ sở", "desc": "Nhiễm khuẩn, vết thương, bỏng, chuẩn bị và theo dõi quanh phẫu thuật.", "type": "groups", "c": 2, "groups": [{"key": "Nhiễm khuẩn và vết thương"}]}, {"n": 3, "title": "Tiếp cận theo vấn đề", "desc": "Từ triệu chứng hoặc hội chứng đến chẩn đoán: đau bụng, nôn ói, vàng da, xuất huyết tiêu hóa, khối phồng…", "type": "notes", "c": 3, "tree": "list", "overviewLabel": "Xem cả mục"}, {"n": 4, "title": "Bệnh học tiêu hóa", "desc": "Từng bệnh ngoại khoa tiêu hóa: bệnh học, triệu chứng, cận lâm sàng, chẩn đoán, điều trị, tiên lượng.", "type": "diseases", "c": 5}, {"n": 5, "title": "Cấp cứu ngoại", "desc": "Cấp cứu ngoại tiêu hóa và chấn thương: nhận diện và xử trí ban đầu.", "type": "notes", "c": 6}, {"n": 6, "title": "Tóm tắt", "desc": "Tổng hợp trong một trang, từng bệnh theo nguyên lý Pareto.", "type": "summary", "c": 8}, {"n": 7, "title": "Nguồn", "desc": "Giáo trình và tài liệu đã dùng cho từng bài.", "type": "sources", "c": 9}, {"n": 8, "title": "Tự đánh giá", "desc": "Các thẻ tự kiểm tra của module.", "type": "cards", "c": 10}]}};
window.NOTES=[{"kind": "disease", "disease": "ung-thu-da-day-ngoai", "short": "Ung thư dạ dày", "group": "", "section": 0, "order": 21, "khung": [], "id": "ngoai-ung-thu-da-day", "title": "Ung thư dạ dày (ngoại khoa)", "layer": "benh", "module": "ngoai-tong-quat", "tags": ["ngoại khoa", "tiêu hóa", "dạ dày", "ung thư dạ dày", "Borrmann", "Lauren", "TNM", "cắt dạ dày", "nạo hạch D2", "Siewert", "giải phẫu mạch máu hạch"], "source": "BHNgTH tr.193–207 (chương Ung thư dạ dày, in tr.184–198); Notion ([GP] Dạ dày, TNK’s Notebook)", "body": "> [!key] Ung thư dạ dày dưới góc nhìn ngoại khoa\n> - Phẫu thuật vẫn là phương pháp quan trọng nhất trong điều trị đa mô thức; hóa trị, xạ trị, miễn dịch/đích đóng vai trò hỗ trợ hoặc dành cho bệnh không còn mổ được {{BHNgTH tr.202}}\n> - ==Cắt dạ dày tiêu chuẩn = cắt ít nhất 2/3 dạ dày + nạo hạch D2==; hạch di căn rất thường gặp nên phải nạo hạch hệ thống {{BHNgTH tr.203}} {{BHNgTH tr.204}}\n> - Phân giai đoạn TNM (AJCC/UICC), cần nạo và phân tích tối thiểu 15 hạch để đánh giá N {{BHNgTH tr.201}}\n> - CT ngực – bụng – chậu cản quang là phương tiện quan trọng nhất để đánh giá giai đoạn {{BHNgTH tr.199}}\n> - Liên kết: [Ung thư dạ dày (module Ung bướu)](#/n/ung-thu-da-day)\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Ung thư dạ dày thường phát hiện muộn; nguy cơ chính: ăn muối/xông khói, H. pylori, viêm teo/chuyển sản, tiền sử gia đình {{BHNgTH tr.193}} {{BHNgTH tr.194}}\n> - Phân loại đại thể Borrmann (type 0–5), vi thể Lauren (ruột / lan tỏa), phân tử TCGA (4 nhóm) {{BHNgTH tr.194}} {{BHNgTH tr.196}} {{BHNgTH tr.197}}\n\n### Định nghĩa & dịch tễ\n- GLOBOCAN 2022: hạng 5 các ung thư thường gặp toàn cầu, tử vong hạng 4; cao nhất ở Đông Á; nam:nữ khoảng 2:1 {{BHNgTH tr.193}}\n- Số ca mắc mới toàn cầu: sách ghi \"968,350 triệu\", gần 659.853 ca tử vong/năm (đơn vị \"triệu\" trong sách có vẻ nhầm, nên đối chiếu nguồn gốc) {{BHNgTH tr.193}}\n- Việt Nam: 16.277 ca mới; thuộc 1 trong 5 ung thư thường gặp, tử vong hạng 3; người bệnh trẻ (dưới 40 tuổi) tăng dần, khoảng 20–25%; thường phát hiện giai đoạn muộn {{BHNgTH tr.193}}\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Làm tăng nguy cơ\n- Dinh dưỡng: ít đạm/chất béo, ít rau quả; thức ăn ngâm tẩm, muối, xông khói (nhiều nitrate); nhiều tinh bột phức tạp; nghiện rượu nặng; thức ăn nhiễm aflatoxin {{BHNgTH tr.193}}\n- Môi trường: bảo quản thức ăn kém, nước ô nhiễm, phóng xạ, khói thuốc lá, sản xuất cao su/than đá {{BHNgTH tr.194}}\n- Di truyền: người thân trực hệ bị ung thư dạ dày; khoảng 10% có yếu tố di truyền; liên quan thể thâm nhiễm lan tỏa di truyền, FAP, Li-Fraumeni, Lynch, HBOC {{BHNgTH tr.194}}\n- Tiền căn: ==nhiễm H. pylori (nguy cơ 3,6–17, nhất là chủng cagA)==; phẫu thuật dạ dày trên 10 năm; viêm teo và viêm chuyển sản niêm mạc; polyp dạ dày (trừ polyp tuyến đáy vị) {{BHNgTH tr.194}}\n- Khác: nam giới, thiếu máu ác tính, nhóm máu A {{BHNgTH tr.194}}\n@@tab Làm giảm nguy cơ\n- Aspirin; ăn nhiều rau xanh, trái cây tươi; vitamin C và E {{BHNgTH tr.194}}\n- Nhiễm H. pylori ở người có tiền sử loét tá tràng {{BHNgTH tr.194}}\n@@end\n\n### Giải phẫu ứng dụng: mạch máu, bạch huyết, liên quan\n@@tabs\n@@tab Động mạch\n- Cấp máu từ động mạch thân tạng (từ động mạch chủ bụng, ngay dưới cơ hoành), chia 3 nhánh: vị trái, gan chung, lách {{Notion}}\n- Hai vòng động mạch dọc hai bờ cong: bờ cong nhỏ gồm vị trái (từ thân tạng) và vị phải (từ gan riêng); bờ cong lớn gồm vị mạc nối phải (từ vị tá tràng) và vị mạc nối trái (từ lách) {{Notion}}\n- Vị ngắn (phần trên bờ cong lớn) và vị sau (mặt sau đáy vị) từ động mạch lách; tâm vị còn nhận nhánh hoành dưới {{Notion}}\n- Ý nghĩa mổ: cắt dạ dày phải kiểm soát các cuống mạch này, đặc biệt khi nạo hạch dọc động mạch (xem bảng nhóm hạch ở 7.2) {{Notion}}\n@@tab Tĩnh mạch\n- Đi song song động mạch, hầu hết đổ về tĩnh mạch cửa; vị ngắn và vị mạc nối trái đổ về tĩnh mạch lách; vị mạc nối phải đổ về tĩnh mạch mạc treo tràng trên {{Notion}}\n- Tĩnh mạch trước môn vị là mốc xác định môn vị trong phẫu thuật {{Notion}}\n@@tab Bạch huyết\n- Mạch bạch huyết đi dọc các động mạch dạ dày, đổ về chuỗi hạch bờ cong nhỏ và chuỗi hạch vị mạc nối ở bờ cong lớn, rồi về hạch thân tạng {{Notion}}\n- Thông nối với bạch huyết thực quản (chỗ nối thực quản – dạ dày) và với tá tràng, tụy (vùng môn vị) {{Notion}}\n- Giải thích tỷ lệ di căn hạch cao và lý do phải nạo hạch hệ thống {{BHNgTH tr.203}} {{BHNgTH tr.204}}\n@@tab Liên quan và thần kinh\n- Sau thân vị là hậu cung mạc nối; qua đó liên quan đuôi tụy, động mạch và tĩnh mạch lách; bờ cong lớn liên quan lách và mạc nối vị lách, mạc nối lớn {{Notion}}\n- Phía bờ cong nhỏ có mạc nối nhỏ bám; sau đó là động mạch chủ bụng, thân tạng và đám rối tạng {{Notion}}\n- Đáy vị và tâm vị liên quan trụ trái cơ hoành; phần trước liên quan thùy trái gan và đại tràng ngang, giải thích các kiểu cắt dạ dày kèm cơ quan khác {{Notion}} {{BHNgTH tr.205}}\n- Thần kinh: giao cảm T6–T9 qua thần kinh tạng lớn; đối giao cảm từ thân lang thang trước và sau chạy dọc bờ cong nhỏ {{Notion}}\n@@end\n\n### Giải phẫu bệnh\n@@tabs\n@@tab Đại thể (Borrmann, JGCA 2011)\n| Type | Hình ảnh |\n|---|---|\n| 0 | Ung thư bề mặt (T1); chia 0-I (polyp), 0-IIa (nhô nhẹ, dưới 3 mm), 0-IIb (phẳng), 0-IIc (lõm nhẹ), 0-III (loét sâu) |\n| 1 | Khối u dạng polyp, trồi lên niêm mạc |\n| 2 | Loét, bờ nhô cao, ranh giới rõ |\n| 3 | Loét thâm nhiễm, bờ nhô cao, ranh giới không rõ |\n| 4 | Thâm nhiễm lan tỏa, thành dạ dày cứng dày (linitis plastica) |\n| 5 | Không phân loại được |\n\n- T1 là ung thư bề mặt (type 0); T2–T4 là giai đoạn tiến triển (type 1–5) {{BHNgTH tr.194}} {{BHNgTH tr.195}}\n@@tab Vi thể (Lauren)\n| | Loại chuyển sản ruột | Loại lan tỏa |\n|---|---|---|\n| Yếu tố | Môi trường; viêm teo, chuyển sản ruột | Gia đình; nhóm máu A |\n| Tuổi | Tăng dần theo tuổi | Trẻ hơn |\n| Tế bào | Dạng tuyến | Biệt hóa kém, tế bào nhẫn |\n| Lan tràn | Đường mạch máu | Xâm lấn xung quanh, bạch huyết |\n| Gen | Bất hoạt P53, P16 | Mất E-cadherin; bất hoạt P53, P16 |\n\n- JGCA chia ung thư biểu mô tuyến: dạng nhú, dạng ống (biệt hóa tốt/trung bình), biệt hóa kém (đặc/rời rạc), tế bào nhẫn, dạng nhầy {{BHNgTH tr.196}} {{BHNgTH tr.197}}\n@@tab Phân tử (TCGA)\n- EBV dương: PD-L1 cao, nhạy miễn dịch, đột biến PIK3CA {{BHNgTH tr.197}}\n- MSI cao: nhạy pembrolizumab, nivolumab {{BHNgTH tr.197}}\n- Ổn định gen (GS): CDH1, RHOA, thể lan tỏa, tiên lượng xấu {{BHNgTH tr.197}}\n- Bất ổn nhiễm sắc thể (CIN): TP53, khuếch đại HER2, MET, FGFR2; nhạy trastuzumab nếu HER2 dương {{BHNgTH tr.197}}\n@@end\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Giai đoạn sớm không có triệu chứng đặc hiệu; sớm nhất là nặng bụng mơ hồ sau ăn; thường gặp nhất là sụt cân (khoảng 6 kg) {{BHNgTH tr.197}}\n> - Dấu hiệu di căn: hạch Virchow, u Krukenberg, hạch Sister Joseph, mảng Blumer {{BHNgTH tr.198}}\n\n### Triệu chứng cơ năng\n- Nặng bụng sau ăn, khó tiêu mơ hồ lâu năm nhưng thay đổi tần suất và mức độ; chán ăn sớm (hay gặp nhất là chán thịt); sụt cân {{BHNgTH tr.197}}\n- Đau sau ăn có thể giống loét lành tính nên dễ nhầm {{BHNgTH tr.197}}\n- Nôn là triệu chứng chính nếu tắc môn vị; đi cầu phân bã cà phê nếu chảy máu rỉ rả; nuốt khó khi tổn thương vùng tâm vị {{BHNgTH tr.197}} {{BHNgTH tr.198}}\n\n### Triệu chứng thực thể và biến chứng\n- Giai đoạn trễ: khối u thượng vị (khoảng 25%), gan to (khoảng 10%) {{BHNgTH tr.198}}\n- Chảy máu tiêu hóa cấp khoảng 5%; mất máu mạn thường gặp (thiếu máu thiếu sắt, máu ẩn trong phân ở khoảng một nửa số ca) {{BHNgTH tr.198}}\n\n### Dấu hiệu di căn xa\n| Dấu hiệu | Ý nghĩa |\n|---|---|\n| Hạch Virchow (thượng đòn trái) | Di căn theo ống ngực |\n| Khối u Krukenberg (buồng trứng to) | Liên quan di căn phúc mạc |\n| Hạch Sister Joseph (nốt cứng ở rốn) | Bệnh tiến triển |\n| Mảng Blumer (thăm trực tràng, khối cứng trước trực tràng) | Di căn phúc mạc |\n| Gan, phổi, não, xương | Di căn xa khác |\n\n{{BHNgTH tr.198}}\n\n> [!red] Dấu hiệu cần xử trí ngay\n> {r|Chảy máu tiêu hóa cấp, thủng gây viêm phúc mạc, tắc môn vị} là các biến chứng của u; chỉ khi có các biến chứng này mới có chỉ định phẫu thuật giảm khối/giảm nhẹ {{BHNgTH tr.203}} {{BHNgTH tr.204}}\n\n## 5. Cận lâm sàng\n\n> [!key] Chỉ định gì khi nào\n> - Nội soi + sinh thiết nhiều mẫu: chẩn đoán xác định; EUS: đánh giá độ sâu T; CT ngực – bụng – chậu: phân giai đoạn; PET/CT: giá trị hạn chế {{BHNgTH tr.198}} {{BHNgTH tr.199}}\n\n### Nội soi và siêu âm nội soi\n- Nội soi thực quản dạ dày tá tràng ống mềm là chính; sinh thiết 6–8 mẫu: ==1 mẫu độ nhạy 70%, 7 mẫu đạt 98%== {{BHNgTH tr.198}}\n- Tổn thương nghi ngờ dưới 2 cm: có thể cắt trọn bằng EMR hoặc ESD, vừa chẩn đoán vừa điều trị ung thư sớm khu trú niêm mạc {{BHNgTH tr.198}}\n- EUS (7,5–12 MHz): thấy 5 lớp thành dạ dày, đánh giá T và phần nào hạch vùng; có lợi nhất khi cần biết u đã qua lớp cơ hay chưa; không đánh giá chính xác TNM và không làm được mọi bệnh nhân {{BHNgTH tr.198}}\n\n### CT ngực – bụng – chậu cản quang\n- Phương tiện quan trọng nhất để phân giai đoạn; độ nhạy/đặc hiệu về xâm lấn và hạch vùng tương đương EUS; ==đầu tay để tìm di căn trong ổ bụng (phát hiện đến 85%)==; di căn phúc mạc: độ nhạy 51%, đặc hiệu 96% {{BHNgTH tr.199}}\n- Quy trình riêng: nhịn đói 8 giờ; làm căng dạ dày (thuốc chống co thắt + uống 1000–1200 ml nước trước 10 phút, hoặc muối tạo khí); nằm ngửa; các thì: trước tiêm, động mạch (30 giây), tĩnh mạch (75 giây), xả thuốc (180 giây); thành dạ dày thấy rõ nhất ở thì động mạch {{BHNgTH tr.199}}\n- Máy đa lát cắt: độ đặc hiệu 93–97%, độ chính xác 90–92,5%; đánh giá được đáp ứng hóa trị tân hỗ trợ {{BHNgTH tr.199}}\n\n### PET/CT, dấu ấn, ctDNA\n- PET/CT: chỉ khoảng 50% bệnh nhân bắt PET; những ca bắt thường đã tiến triển và cần hóa trị tân hỗ trợ {{BHNgTH tr.199}}\n- Dấu ấn phân tử (xem bảng) và CA 19-9, CEA, CA 72-4: không đủ đặc hiệu để chẩn đoán sớm, chủ yếu theo dõi đáp ứng điều trị {{BHNgTH tr.199}} {{BHNgTH tr.200}}\n- ctDNA, ctRNA: còn ở mức tiềm năng, chưa có bộ chuẩn để áp dụng lâm sàng {{BHNgTH tr.200}}\n\n| Dấu ấn | Tỷ lệ | Ứng dụng |\n|---|---|---|\n| HER2 (IHC, FISH) | 10–20% | Trastuzumab nếu dương |\n| PD-L1 (IHC, CPS) | 15–20% | Pembrolizumab, nivolumab nếu CPS ≥1 |\n| MSI cao (PCR/IHC) | khoảng 20% | Nhạy miễn dịch |\n| TP53 | Trên 50% nhóm CIN | Tiên lượng xấu |\n| CDH1 | 50% thể lan tỏa | Cân nhắc cắt dạ dày dự phòng nếu có đột biến |\n| FGFR2 | 5–10% | Bemarituzumab |\n| Claudin 18.2 | khoảng 30% | Zolbetuximab (thử nghiệm) |\n\n{{BHNgTH tr.199}} {{BHNgTH tr.200}}\n\n### Phân giai đoạn TNM (AJCC/UICC)\n@@tabs\n@@tab T, N, M\n| T | Xâm lấn |\n|---|---|\n| Tis | In situ, chưa xâm lấn lamina propria |\n| T1a / T1b | Lamina propria hoặc cơ niêm / dưới niêm |\n| T2 | Lớp cơ |\n| T3 | Mô liên kết dưới thanh mạc, chưa xâm lấn phúc mạc tạng hoặc cơ quan lân cận |\n| T4a / T4b | Thanh mạc (phúc mạc tạng) / cấu trúc lân cận |\n\n| N | Số hạch di căn |\n|---|---|\n| N0 | Không |\n| N1 | 1–2 |\n| N2 | 3–6 |\n| N3a / N3b | 7–15 / trên 15 |\n\nM0: không di căn xa; M1: có di căn xa {{BHNgTH tr.201}}\n@@tab Giai đoạn\n| | N0 | N1 | N2 | N3a | N3b |\n|---|---|---|---|---|---|\n| T1a/T1b | IA | IB | IIA | IIB | IIIB |\n| T2 | IB | IIA | IIB | IIIA | IIIB |\n| T3 | IIA | IIB | IIIA | IIIB | IIIC |\n| T4a | IIB | IIIA | IIIA | IIIB | IIIC |\n| T4b | IIIA | IIIB | IIIB | IIIC | IIIC |\n\nM1 (bất kể T, N): giai đoạn IV {{BHNgTH tr.201}}\n@@tab Vùng tâm vị – thực quản\n- Siewert (u cách chỗ nối thực quản – dạ dày EGJ trong 5 cm) và Nishi, đều dựa vào vị trí u so với EGJ {{BHNgTH tr.202}}\n- Type I: ung thư phần xa thực quản, tâm u trên EGJ 1 cm; Type II: ung thư tâm vị thật sự, tâm u từ dưới EGJ 1 cm đến trên 2 cm; Type III: ung thư dưới tâm vị, tâm u dưới EGJ 2 cm {{BHNgTH tr.202}}\n@@end\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Nguyên tắc chẩn đoán\n> - Chẩn đoán xác định bằng nội soi + sinh thiết (6–8 mẫu); chẩn đoán giai đoạn bằng CT ngực – bụng – chậu cản quang ± EUS {{BHNgTH tr.198}} {{BHNgTH tr.199}}\n> - Giáo trình không có bảng chẩn đoán phân biệt riêng; chỉ lưu ý đau sau ăn có thể là loét lành tính nên dễ nhầm {{BHNgTH tr.197}}\n\n### Chẩn đoán phân biệt\n| Bệnh | Ghi chú |\n|---|---|\n| Loét dạ dày lành tính | Đau sau ăn giống nhau; phân biệt bằng nội soi và sinh thiết nhiều mẫu {{BHNgTH tr.197}} {{BHNgTH tr.198}} |\n| Các bệnh khác | Giáo trình không nêu |\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n- Ung thư còn mổ được và chưa di căn xa: phẫu thuật triệt căn (cắt dạ dày mang tổn thương + nạo hạch hệ thống); ung thư sớm chưa di căn hạch: cắt qua nội soi {{BHNgTH tr.203}}\n- Ung thư có biến chứng và không còn chỉ định triệt căn: phẫu thuật giảm nhẹ {{BHNgTH tr.203}}\n- Hóa trị tái phát/không cắt được: điều trị triệu chứng và kéo dài sống còn, chưa chữa khỏi {{BHNgTH tr.206}}\n\n### 7.2 Các phương pháp\n@@tabs\n@@tab Nguyên tắc phẫu thuật triệt căn\n- Chỉ định: tổn thương còn cắt được và không di căn xa; người bệnh phải được chuẩn bị đầy đủ về tinh thần và thể chất vì là phẫu thuật lớn {{BHNgTH tr.204}}\n- Cắt mạc nối lớn và mạc nối nhỏ {{BHNgTH tr.204}}\n- Nạo vét hạch hệ thống thành một khối, theo phạm vi và phương pháp cắt dạ dày {{BHNgTH tr.204}}\n- ==Bờ cắt dưới: dưới môn vị khoảng 2 cm== (ung thư rất hiếm khi ăn xuống tá tràng quá giới hạn này) {{BHNgTH tr.204}}\n- ==Bờ cắt trên cách tổn thương: ung thư sớm ít nhất 2 cm; type 1, 2 ít nhất 3 cm; type 3, 4 ít nhất 5 cm== {{BHNgTH tr.204}}\n- T4b: cắt thành khối cùng cơ quan bị xâm lấn; chỉ cắt lách khi lách hoặc rốn lách bị xâm lấn {{BHNgTH tr.204}}\n@@tab Định nghĩa các loại phẫu thuật\n- {b|Cắt dạ dày tiêu chuẩn}: cắt triệt căn ít nhất 2/3 dạ dày + nạo hạch D2 {{BHNgTH tr.204}}\n- {b|Không theo tiêu chuẩn}: thay đổi tùy tổn thương; ==cải tiến== (ít hơn tiêu chuẩn) và ==mở rộng== (kèm cắt cơ quan kế cận bị xâm lấn hoặc nạo hạch hơn D2) {{BHNgTH tr.204}}\n@@tab Các kiểu cắt dạ dày\n| Kiểu cắt | Chỉ định | Tái lập lưu thông |\n|---|---|---|\n| Cắt phần xa | Tổn thương 1/3 dưới, hoặc 1/3 giữa mà bờ trên u cách tâm vị trên 5 cm; cắt phần lớn đoạn xa, môn vị, mạc nối lớn | Mỏm dạ dày với tá tràng (Billroth I) hoặc hỗng tràng (Billroth II, Roux-en-Y); mỏm tá tràng khâu tay hoặc máy cắt nối thẳng |\n| Cắt phần gần | Ung thư sớm ở 1/3 trên, phần còn lại ít nhất 1/2 dạ dày; cắt kèm tâm vị và mạc nối lớn | Nối thực quản bụng với phần dạ dày còn lại |\n| Cắt toàn bộ | 1/3 giữa mà bờ trên u cách tâm vị dưới 5 cm, hoặc 1/3 trên hay toàn bộ dạ dày | Thực quản bụng với hỗng tràng (Roux-en-Y hoặc Omega) |\n| Cắt mở rộng | Kèm cơ quan bị xâm lấn: lách; đuôi tụy và lách; đại tràng ngang; thùy gan trái; khối tá tụy | Tùy kiểu cắt |\n\n{{BHNgTH tr.204}} {{BHNgTH tr.205}}\n@@tab Nạo hạch D1, D1+, D2\n- Mức nạo hạch tùy theo kiểu cắt (toàn bộ hay bán phần), không tùy vị trí u nguyên phát {{BHNgTH tr.205}}\n\n| Kiểu cắt | D1 | D1+ | D2 |\n|---|---|---|---|\n| Toàn bộ | 1–7 | D1 + 8a, 9, 11p | D1 + 8a, 9, 11p, 11d, 12a |\n| Bán phần dưới | 1, 3, 4sb, 4d, 5, 6, 7 | D1 + 8a, 9 | D1 + 8a, 9, 11p, 12a |\n| Bán phần trên | 1, 2, 3a, 4sa, 4sb, 7 | D1 + 8a, 9, 11p | Không |\n\n- Cần nạo và phân tích tối thiểu 15 hạch để đánh giá giai đoạn N {{BHNgTH tr.201}}\n- Nhóm 16a2/b1 (quanh động mạch chủ bụng) nghi di căn: chỉ định hóa trị tân hỗ trợ trước mổ {{BHNgTH tr.206}}\n@@tab Nội soi (EMR, ESD)\n- Chỉ định cho ung thư sớm chưa di căn hạch; tổn thương dưới 2 cm có thể cắt trọn, ung thư sớm khu trú ở niêm mạc không cần điều trị bổ sung {{BHNgTH tr.203}} {{BHNgTH tr.206}}\n- Theo lưu đồ JGCA 2021: cT1a(M) N0 đủ chỉ định cắt nội soi; sau cắt, nếu eCuraC thì cắt dạ dày vét hạch D1/D1+, eCuraA/B thì theo dõi {{BHNgTH tr.203}}\n@@tab Hóa trị, đích, miễn dịch, xạ trị\n- Hóa trị tân hỗ trợ: u cắt được nhưng hạch to (đường kính trên 3 cm) hoặc nghi di căn hạch 16a2/b1 (trên 1 cm); 3–6 đợt trước mổ; sống còn sau mổ tốt hơn không hóa trị tân hỗ trợ {{BHNgTH tr.206}}\n- Hóa trị hỗ trợ sau mổ: giai đoạn II và III theo JGCA (mục nguyên tắc điều trị lại ghi giai đoạn III, IV, chương không thống nhất); phác đồ HER2 âm: S-1 + cisplatin, capecitabine + cisplatin, S-1 + docetaxel, 5FU + cisplatin + docetaxel; HER2 dương: trastuzumab + cisplatin + capecitabine hoặc 5FU, hoặc trastuzumab + S-1 + cisplatin {{BHNgTH tr.204}} {{BHNgTH tr.206}}\n- Đích/miễn dịch: trastuzumab (HER2 dương); ramucirumab (VEGFR-2, giai đoạn tiến triển); pembrolizumab, nivolumab (MSI cao hoặc PD-L1 dương) {{BHNgTH tr.206}} {{BHNgTH tr.207}}\n- Xạ trị: chủ yếu kết hợp hóa trị, khuyến cáo ở phương Tây; Nhật hạn chế, chỉ giảm nhẹ. Chăm sóc giảm nhẹ: kiểm soát đau, hỗ trợ dinh dưỡng, tư vấn tâm lý {{BHNgTH tr.207}}\n@@end\n\n### 7.3 Chỉ định – hướng xử trí\n> [!doc] Lưu đồ JGCA 2021 trong giáo trình\n> | Tình huống | Hướng xử trí |\n> |---|---|\n> | M0, cT1a(M) N0, đủ chỉ định cắt nội soi | Cắt nội soi; theo dõi nếu eCuraA/B, cắt dạ dày vét hạch D1/D1+ nếu eCuraC |\n> | M0, cT1a không đủ chỉ định nội soi; cT1b(SM) N0 | Cắt dạ dày vét hạch D1/D1+ |\n> | M0, cT1 N+ | Cắt dạ dày vét hạch D2 |\n> | M0, cT2–4 không hạch bulky | Cắt dạ dày vét hạch D2 |\n> | M0, cT2–4 có hạch bulky | Cân nhắc hóa trị tân hỗ trợ + cắt dạ dày vét hạch D2 kèm hạch nhóm 16 |\n> | M1: nhóm 16a2/b1; di căn gan cắt được; phúc mạc; khác | Nhóm 16: cân nhắc hóa trị tân hỗ trợ; di căn gan cắt được: cân nhắc cắt gan với số lượng nhỏ; phúc mạc: hóa trị; yếu tố không triệt căn khác: hóa xạ trị, phẫu thuật hoặc chăm sóc giảm nhẹ |\n> | Sau mổ giai đoạn I | Theo dõi |\n> | Sau mổ giai đoạn II, III (trừ T1, T3N0) | Hóa trị bổ trợ |\n> | Sau mổ giai đoạn IV | Hóa trị, chăm sóc giảm nhẹ |\n> {{BHNgTH tr.203}}\n\n- Cắt dạ dày mang tổn thương là lựa chọn đầu tiên khi còn chỉ định triệt căn; phẫu thuật giảm khối không chỉ định nếu u không có biến chứng (thủng, xuất huyết) {{BHNgTH tr.203}} {{BHNgTH tr.204}}\n- Chọn kiểu cắt theo vị trí u và khoảng cách đến tâm vị (xem bảng ở phần các phương pháp, tab Các kiểu cắt dạ dày); chọn bờ cắt theo type đại thể {{BHNgTH tr.204}} {{BHNgTH tr.205}}\n\n> [!warn] Giáo trình không nêu\n> Biến chứng sau cắt dạ dày (rò miệng nối, hội chứng dumping, thiếu máu…), lịch theo dõi sau mổ, kỹ thuật nội soi/robot: chương không đề cập riêng. Chỉ có \"biến chứng sau mổ\" được nhắc là yếu tố tiên lượng {{BHNgTH tr.207}}\n\n## 8. Tiên lượng – Dự phòng / theo dõi sau mổ\n\n### Tiên lượng\n- Yếu tố ảnh hưởng sống thêm: mức độ xâm lấn, mô bệnh học, vị trí tổn thương, tình trạng di căn hạch, biến chứng của khối u và biến chứng sau mổ {{BHNgTH tr.207}}\n- Bệnh thường phát hiện muộn nên sống thêm thấp {{BHNgTH tr.193}}\n- TP53 đột biến: tiên lượng xấu; thể GS (CDH1, RHOA): tiên lượng xấu, ít đích điều trị {{BHNgTH tr.197}} {{BHNgTH tr.200}}\n\n### Theo dõi sau điều trị\n- Giai đoạn I sau mổ: theo dõi; giai đoạn II, III: hóa trị bổ trợ; giai đoạn IV: hóa trị, chăm sóc giảm nhẹ {{BHNgTH tr.203}}\n- CA 19-9, CEA, CA 72-4 hữu ích theo dõi đáp ứng điều trị; CT đánh giá đáp ứng hóa trị tân hỗ trợ {{BHNgTH tr.199}} {{BHNgTH tr.200}}\n- Lịch tái khám cụ thể: giáo trình không nêu\n\n### Dự phòng\n- Giảm yếu tố nguy cơ (thức ăn muối, xông khói, rượu, thuốc lá), ăn rau quả tươi; aspirin, vitamin C, E là yếu tố giảm nguy cơ {{BHNgTH tr.193}} {{BHNgTH tr.194}}\n- Đột biến CDH1: cân nhắc cắt dạ dày dự phòng {{BHNgTH tr.200}}\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] Ung thư dạ dày ngoại khoa thi nhấn mạnh gì\n> - **Nhận diện**: nặng bụng sau ăn, chán ăn, sụt cân; hạch Virchow, Krukenberg, Sister Joseph, Blumer là di căn {{BHNgTH tr.197}} {{BHNgTH tr.198}}\n> - **Chẩn đoán**: nội soi + sinh thiết 6–8 mẫu; CT cản quang phân giai đoạn; nạo đủ 15 hạch để xác định N {{BHNgTH tr.198}} {{BHNgTH tr.201}}\n> - **Điều trị**: cắt dạ dày tiêu chuẩn = ≥2/3 + D2; bờ cắt dưới môn vị 2 cm; bờ cắt trên 2/3/5 cm theo type {{BHNgTH tr.204}}\n\n@@tabs\n@@tab Nhận diện\n- Triệu chứng sớm mơ hồ; sụt cân hay gặp nhất {{BHNgTH tr.197}}\n- Linitis plastica = Borrmann 4 {{BHNgTH tr.195}}\n- Xem [mục 4](#/n/ngoai-ung-thu-da-day/4)\n@@tab Chẩn đoán\n- Sinh thiết 1 mẫu nhạy 70%, 7 mẫu 98% {{BHNgTH tr.198}}\n- CT: đầu tay cho di căn ổ bụng; EUS: phân biệt xâm lấn qua lớp cơ {{BHNgTH tr.198}} {{BHNgTH tr.199}}\n- Xem [mục 5](#/n/ngoai-ung-thu-da-day/5)\n@@tab Điều trị\n- Nội soi cho ung thư sớm chưa di căn hạch; triệt căn cắt dạ dày + D2 {{BHNgTH tr.203}}\n- Cắt phần xa / phần gần / toàn bộ theo vị trí u và khoảng cách đến tâm vị 5 cm {{BHNgTH tr.204}} {{BHNgTH tr.205}}\n- Xem [mục 7.3](#/n/ngoai-ung-thu-da-day/7)\n@@tab Tiên lượng – Dự phòng\n- Phụ thuộc xâm lấn, mô bệnh học, vị trí, hạch, biến chứng {{BHNgTH tr.207}}\n- Xem [mục 8](#/n/ngoai-ung-thu-da-day/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Con số |\n|---|---|\n| Sinh thiết | ==6–8 mẫu==; 1 mẫu nhạy 70%, 7 mẫu 98% {{BHNgTH tr.198}} |\n| Số hạch tối thiểu để xác định N | ==15 hạch== {{BHNgTH tr.201}} |\n| N1 / N2 / N3a / N3b | 1–2 / 3–6 / 7–15 / trên 15 hạch {{BHNgTH tr.201}} |\n| Cắt dạ dày tiêu chuẩn | ==≥2/3 dạ dày + D2== {{BHNgTH tr.204}} |\n| Bờ cắt dưới | ==dưới môn vị khoảng 2 cm== {{BHNgTH tr.204}} |\n| Bờ cắt trên | ==2 cm (sớm), 3 cm (type 1, 2), 5 cm (type 3, 4)== {{BHNgTH tr.204}} |\n| Cắt phần xa | 1/3 dưới, hoặc 1/3 giữa cách tâm vị trên 5 cm {{BHNgTH tr.204}} |\n| Cắt toàn bộ | 1/3 giữa cách tâm vị dưới 5 cm, 1/3 trên, toàn bộ {{BHNgTH tr.205}} |\n| Cắt phần gần | Ung thư sớm 1/3 trên, còn lại ít nhất 1/2 dạ dày {{BHNgTH tr.205}} |\n| Hóa trị tân hỗ trợ | Hạch trên 3 cm hoặc nhóm 16a2/b1 trên 1 cm; 3–6 đợt {{BHNgTH tr.206}} |\n| HER2 / PD-L1 / MSI | 10–20% / 15–20% / khoảng 20% {{BHNgTH tr.199}} {{BHNgTH tr.200}} |\n| EMR/ESD | Tổn thương dưới 2 cm {{BHNgTH tr.198}} |\n\n> [!warn] Bẫy thi thường gặp\n> - Hạch D1/D1+/D2 tùy kiểu cắt (toàn bộ hay bán phần), không tùy vị trí u nguyên phát {{BHNgTH tr.205}}\n> - Cắt lách chỉ khi lách hoặc rốn lách bị xâm lấn, không cắt thường quy {{BHNgTH tr.204}}\n> - Không mổ giảm khối nếu u không biến chứng {{BHNgTH tr.203}}\n> - Sách ghi hóa trị hỗ trợ sau mổ ở giai đoạn III, IV (phần nguyên tắc điều trị) và giai đoạn II, III (phần hóa trị) — nội dung không thống nhất trong chương {{BHNgTH tr.204}} {{BHNgTH tr.206}}\n> - Không có mâu thuẫn giữa giáo trình và Notion ở phần giải phẫu; Notion chỉ bổ sung mạch máu, bạch huyết, thần kinh\n\n@@fold Nguồn tài liệu\n- BHNgTH tr.193–207 (chương Ung thư dạ dày; in tr.184–198), lưu đồ JGCA 2021 tr.203 và bảng nạo hạch tr.205 đọc từ ảnh trang\n@@end\n\n@@fold Nguồn ngoài\n- Từ Notion (giáo trình cũ, trang \"[GP] Dạ dày\", TNK’s Notebook): động mạch, tĩnh mạch, bạch huyết, liên quan và thần kinh của dạ dày (mục 3)\n- Không có nguồn: biến chứng sau cắt dạ dày, lịch theo dõi sau mổ, giải phẫu từng nhóm hạch (số hiệu 1–16) — giáo trình mới và Notion trong TNK’s Notebook đều không nêu; Notion TNK’s Notebook không có trang riêng về ung thư dạ dày ngoại khoa\n@@end\n\n@@fold! Tự kiểm tra (12 thẻ)\n- Cắt dạ dày tiêu chuẩn là gì? :: Cắt triệt căn ít nhất 2/3 dạ dày kèm nạo hạch D2\n- Bờ cắt dưới trong cắt dạ dày triệt căn? :: Dưới môn vị khoảng 2 cm\n- Bờ cắt trên theo type đại thể? :: Sớm ≥2 cm; type 1, 2 ≥3 cm; type 3, 4 ≥5 cm\n- Khi nào cắt lách trong ung thư dạ dày? :: Chỉ khi lách hoặc rốn lách bị xâm lấn\n- Cần nạo tối thiểu bao nhiêu hạch để đánh giá N? :: 15 hạch\n- N2 và N3a là bao nhiêu hạch? :: N2: 3–6 hạch; N3a: 7–15 hạch\n- Cắt phần xa dạ dày chỉ định khi nào? :: Tổn thương 1/3 dưới, hoặc 1/3 giữa mà bờ trên u cách tâm vị trên 5 cm\n- Cắt toàn bộ dạ dày tái lập lưu thông thế nào? :: Nối thực quản bụng với hỗng tràng kiểu Roux-en-Y hoặc Omega\n- Borrmann type 4 còn gọi là gì? :: Thâm nhiễm lan tỏa (linitis plastica)\n- Sinh thiết mấy mẫu để nhạy 98%? :: 7 mẫu (1 mẫu chỉ nhạy 70%)\n- Hạch Virchow nằm ở đâu? :: Thượng đòn trái\n- Mốc xác định môn vị trong mổ? :: Tĩnh mạch trước môn vị\n@@end"}, {"kind": "disease", "disease": "ung-thu-dai-trang", "short": "Ung thư đại tràng", "group": "", "section": 0, "order": 22, "khung": [], "id": "ngoai-ung-thu-dai-trang", "title": "Ung thư đại tràng (ngoại khoa)", "layer": "benh", "module": "ngoai-tong-quat", "tags": ["ngoại khoa", "tiêu hóa", "đại tràng", "ung thư đại tràng", "cắt đại tràng phải", "cắt đại tràng trái", "CME", "TNM", "tắc ruột do ung thư", "thủng đại tràng", "stent đại tràng", "hậu môn nhân tạo", "CEA"], "source": "BHNgTH tr.210–235 (chương Ung thư đại tràng), tr.95, 113–114 (chương Tắc ruột); Notion \"[BHNgK] Ung thư đại tràng\" (giáo trình cũ)", "body": "> [!key] Ung thư đại tràng (UTĐT) trong một nhìn\n> - Phẫu thuật là điều trị chủ yếu; hóa trị, xạ trị, miễn dịch chỉ hỗ trợ {{BHNgTH tr.210}} {{BHNgTH tr.229}}\n> - ==Nguyên tắc mổ: cắt trọn đoạn đại tràng mang u cùng mạc treo, mạch nuôi, bạch huyết; thắt mạch tận gốc; bờ cắt cách u khoảng 5 cm==; kỹ thuật không chạm {{BHNgTH tr.229}}\n> - Chọn kiểu cắt (phải, phải mở rộng, ngang, trái, chậu hông, cắt trước) theo **vị trí u** và **động mạch nuôi** {{BHNgTH tr.232}}\n> - Biến chứng cấp cứu: **tắc ruột** (UTĐT chiếm 60% tắc ruột ở người lớn tuổi), **thủng**, chảy máu (ít khi nặng) {{BHNgTH tr.233}} {{BHNgTH tr.234}}\n> - Theo dõi sau mổ: nội soi đại tràng, CEA, siêu âm/CLVT bụng theo giai đoạn {{BHNgTH tr.235}}\n> - Phần nội khoa – hóa trị, tầm soát: xem [Ung thư đại trực tràng (module Ung bướu)](#/n/ung-thu-daitruc-trang)\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Từ đại tràng bình thường đến ung thư kéo dài vài năm qua nhiều bước có thể ngăn chặn; polyp tuyến cần khoảng 5–10 năm để thành ung thư {{BHNgTH tr.210}} {{BHNgTH tr.213}}\n> - Phẫu thuật cần nắm **hướng lan rộng**: dọc thành ruột ít (5 cm là an toàn), qua phúc mạc, bạch huyết theo mạch nuôi, máu theo tĩnh mạch cửa lên gan {{BHNgTH tr.220}}\n\n### Định nghĩa & dịch tễ\n- UTĐT là ác tính tiêu hóa thường gặp; Mỹ: hạng ba ở nam, hạng tư ở nữ, khoảng 11% các ung thư mới chẩn đoán; nguy cơ mắc suốt đời khoảng ==1/20== {{BHNgTH tr.210}}\n- Việt Nam 2010–2018: hạng tư ở nam, hạng hai ở nữ {{BHNgTH tr.210}}\n- Xu hướng 30 năm gần đây: giảm ở người lớn tuổi (hiệu quả sàng lọc), tăng ở người trẻ {{BHNgTH tr.211}}\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Từ bên ngoài\n- Chế độ ăn nhiều mỡ động vật bão hòa, nhiều thịt đỏ (sắt tăng gốc tự do); mối liên quan chế độ ăn nói chung chưa xác định rõ {{BHNgTH tr.211}}\n- Bảo vệ: chất xơ, canxi, vitamin D; folate (thiếu folate làm gián đoạn tổng hợp và sửa chữa DNA) {{BHNgTH tr.212}}\n- Hút thuốc lâu năm: nguy cơ ==gấp 2–3 lần==; rượu: rối loạn hấp thu folate, tác động qua lại với thuốc lá {{BHNgTH tr.212}}\n- Aspirin/NSAID và hormone thay thế có tác dụng bảo vệ nhưng **không dùng để phòng bệnh** vì tác dụng phụ {{BHNgTH tr.212}} {{BHNgTH tr.213}}\n@@tab Nội tại\n- Tuổi: tăng sau 40, rõ sau 50; ==trên 90% ca ở người trên 50 tuổi== {{BHNgTH tr.213}}\n- **Polyp tuyến** là tổn thương tiền ung: tuyến ống 60–80%, ống–nhánh 10–25%, nhánh 5–10%; polyp tuyến nhánh nguy cơ cao hơn, ==50% polyp tuyến nhánh trên 2 cm có tế bào ung thư== {{BHNgTH tr.213}}\n- Béo phì, cắt túi mật (tăng acid mật thứ phát, nhất là đại tràng gần), bệnh viêm ruột (viêm loét đại tràng, Crohn) {{BHNgTH tr.213}} {{BHNgTH tr.214}}\n- Tiền sử gia đình: người thân thế hệ thứ nhất làm nguy cơ cao ==2–4 lần==; 5–10% do di truyền (FAP, HNPCC) {{BHNgTH tr.214}}\n- Khác: tia xạ, bệnh to đầu chi {{BHNgTH tr.214}}\n@@end\n\n### Giải phẫu ứng dụng cho phẫu thuật\n- Đại tràng chia bốn phần: phải (manh tràng và đại tràng lên), giữa (đại tràng ngang), trái (đại tràng xuống), đại tràng chậu hông; AJCC 8 chia thêm góc gan, góc lách {{BHNgTH tr.222}}\n- Chiều dài (giáo trình cũ): manh tràng 6–9 cm, đại tràng lên 15–20 cm, ngang 18–22 cm, xuống 10–15 cm; đại tràng chậu hông ở người châu Á dài hơn người phương Tây {{Notion}}\n- **Đoạn di động** (manh tràng, đại tràng ngang, đại tràng chậu hông): u dễ gieo rắc vào khoang phúc mạc; **đoạn có mạc Toldt** (đại tràng lên, xuống): u xâm lấn tạng sau phúc mạc như thận, niệu quản, tụy {{BHNgTH tr.220}}\n- Bạch huyết dẫn lưu dọc theo động mạch nuôi, nên mạch nuôi phải thắt tận gốc để nạo hạch {{BHNgTH tr.229}}\n- Hầu hết đoạn đại tràng dẫn lưu bạch huyết một hướng; **góc gan, góc lách, 1/3 phải và 1/3 trái đại tràng ngang có hai hướng** {{BHNgTH tr.220}}\n  - Góc gan và 1/3 phải đại tràng ngang: hạch theo bó hồi đại tràng và đại tràng giữa {{BHNgTH tr.220}}\n  - Góc lách và 1/3 trái đại tràng ngang: hạch theo bó đại tràng giữa và đại tràng trái {{BHNgTH tr.220}}\n- Hạch vùng chia 3 nhóm (JSCCR): cạnh đại tràng, trung gian, chính {{BHNgTH tr.225}}\n\n### Sinh học phân tử\n- Sinh ung là quá trình nhiều bước tích tụ rối loạn gen; chuỗi: biểu mô bình thường, u tuyến sớm, trung gian, muộn, carcinôm, di căn (APC, K-ras, DCC, p53) {{BHNgTH tr.215}}\n- **K-ras**: gen sinh ung (nhiễm sắc thể 12), đột biến khoảng một nửa ung thư đại–trực tràng, các ca này **không nhạy thuốc đích** {{BHNgTH tr.215}}\n- Gen ức chế u quan trọng: APC, DCC, p53, MCC {{BHNgTH tr.215}}\n\n### Giải phẫu bệnh\n- Đại thể giai đoạn tiến triển 4 dạng: polyp, loét bờ rõ, loét bờ không xác định, thâm nhiễm lan tỏa {{BHNgTH tr.215}}\n- Vi thể: ==carcinôm tuyến không đặc hiệu khoảng 90%==; tuyến nhầy 5–20%, tế bào nhẫn 1% (WHO 2019) {{BHNgTH tr.216}}\n- Độ mô học theo thành phần kém biệt hóa nhất: WHO 2019 hai bậc (thấp, cao); AJCC 8 bốn bậc G1–G4 {{BHNgTH tr.217}}\n\n### Thể lâm sàng đặc biệt\n| Thể | Điểm cần nhớ |\n|---|---|\n| FAP (đa polyp tuyến gia đình) | Di truyền trội, gen APC; hàng trăm đến hàng ngàn polyp; ung thư ở tuổi 40–45; khoảng 1% UTĐT; sau cắt đại tràng, ung thư hang vị và hành tá tràng là nguyên nhân tử vong chính {{BHNgTH tr.214}} {{BHNgTH tr.217}} |\n| HNPCC (hội chứng Lynch) | Di truyền trội, gen MLH1, MSH2; 4–6% UTĐT; hay ở đại tràng phải, người trẻ 35–45 tuổi, nhiều u cùng lúc {{BHNgTH tr.214}} {{BHNgTH tr.217}} |\n| Đa polyp hamartoma (Peutz-Jeghers...) | Polyp hamartoma + mảng hắc tố niêm mạc miệng; 2–3% thành ung thư {{BHNgTH tr.218}} |\n\n### Lan rộng và gieo rắc (nền của chiến lược mổ)\n- **Trong thành ruột**: lan ngang nhanh hơn dọc (¼ chu vi trong 6 tháng); trên vi thể tế bào ung thư đi xa hơn đại thể hơn 1 cm {{BHNgTH tr.220}}\n- **Qua phúc mạc**: khoảng 10% có gieo rắc phúc mạc; di căn phúc mạc là nguyên nhân tử vong thứ hai sau di căn gan, tiên lượng xấu {{BHNgTH tr.220}}\n- **Bạch huyết**: tỉ lệ di căn hạch ở carcinôm biệt hóa tốt, trung bình, kém lần lượt ==25%, 50%, 80%== {{BHNgTH tr.220}}\n- **Đường máu**: theo tĩnh mạch cửa; tạng hay di căn nhất là ==gan (77%)== {{BHNgTH tr.220}}\n- **Gieo rắc do phẫu thuật**: tế bào bong tróc vào vết cắt u, vết mổ lấy bệnh phẩm; vì vậy cần kỹ thuật không chạm {{BHNgTH tr.221}} {{BHNgTH tr.229}}\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Giai đoạn sớm thường không triệu chứng; phát hiện tình cờ hoặc qua tầm soát {{BHNgTH tr.227}}\n> - Triệu chứng thường gặp nhất: **đau bụng** (âm ỉ, mơ hồ); thứ hai: **thay đổi thói quen đi cầu** {{BHNgTH tr.227}}\n> - Triệu chứng khác nhau giữa **đại tràng phải** và **đại tràng trái** {{BHNgTH tr.227}}\n\n### Triệu chứng theo vị trí u\n| | Đại tràng phải | Đại tràng trái |\n|---|---|---|\n| Lòng ruột | Rộng | Hẹp hơn {{BHNgTH tr.227}} |\n| Dạng u | Chồi sùi | Vòng nhẫn (hẹp) {{BHNgTH tr.227}} |\n| Phân | Lỏng | Cứng {{BHNgTH tr.227}} |\n| Biểu hiện | Muộn hơn | Sớm hơn {{BHNgTH tr.227}} |\n\n- Đi cầu ra máu: khoảng ==25%==; máu đỏ tươi gặp ở u đoạn cuối khung đại tràng; **dễ nhầm với trĩ** nên chẩn đoán chậm, nhất là người trẻ {{BHNgTH tr.227}}\n- Triệu chứng không đặc hiệu không được bỏ qua: sụt cân không rõ nguyên nhân, mệt mỏi, đổi tính chất phân; giáo trình cũ thêm thiếu máu, tiêu nhầy máu, táo bón xen lẫn tiêu chảy {{BHNgTH tr.227}} {{Notion}}\n\n### Khám thực thể\n- Sờ được khối u; gan to (di căn gan); bụng chướng, nhu động tăng (tắc hoặc bán tắc) {{BHNgTH tr.227}}\n- Phản ứng phúc mạc tại vị trí u gợi ý viêm quanh u hoặc thủng u; hạch thượng đòn trái là dấu hiệu trễ {{BHNgTH tr.227}}\n- Thăm hậu môn: tìm sang thương trực tràng, đánh giá phân và máu {{BHNgTH tr.228}}\n\n> [!red] Dấu hiệu cần xử trí cấp cứu\n> - Đau quặn từng cơn, chướng bụng, nôn, bí trung đại tiện ở người trên 50 tuổi chưa từng mổ bụng: nghĩ **tắc ruột do UTĐT** {{BHNgTH tr.233}}\n> - Đau dữ dội khắp bụng, sốt lạnh run, bụng cứng hoặc cảm ứng phúc mạc: **thủng** {{BHNgTH tr.233}}\n> - Đi cầu ra máu nhiều, ồ ạt: cần hồi sức và phẫu thuật cấp cứu (giáo trình cũ) {{Notion}}\n\n## 5. Cận lâm sàng\n\n### Chẩn đoán và đánh giá giai đoạn\n- **Nội soi đại tràng + sinh thiết**: tiêu chuẩn vàng; còn điều trị được polyp và ung thư giai đoạn sớm {{BHNgTH tr.228}}\n- **CLVT** (bụng chậu có cản quang): phương tiện thường quy; chẩn đoán và xếp giai đoạn; độ nhạy ==85%== với di căn gan {{BHNgTH tr.228}} {{BHNgTH tr.229}}\n- X quang đại tràng: định vị u trên khung đại tràng; độ nhạy 50% (u dưới 1 cm), 90% (trên 1 cm); ít dùng ngày nay {{BHNgTH tr.228}}\n- PET scan: không thường quy (đắt, ít hơn CLVT); tốt cho di căn, nhất là ngoài gan {{BHNgTH tr.229}}\n- **CEA**: không có giá trị chẩn đoán; dùng tiên lượng và theo dõi; CEA trước mổ cao gợi ý nguy cơ di căn; sau mổ triệt căn không hạ gợi ý di căn chưa phát hiện {{BHNgTH tr.229}}\n- Máu ẩn trong phân (miễn dịch): chỉ gợi ý chảy máu rỉ rả, phải tìm nguồn {{BHNgTH tr.229}}\n\n### Khi có biến chứng\n- **Tắc ruột**: X quang bụng không sửa soạn thấy mức khí–dịch, đại tràng giãn; thăm trực tràng bóng rỗng; CLVT có cản quang tìm nguyên nhân, đánh giá giai đoạn và biến chứng {{BHNgTH tr.233}} {{Notion}}\n- Quy tắc 3–6–9: đường kính giãn ruột non trên 3 cm, đại tràng trên 6 cm, manh tràng trên 9 cm; manh tràng càng to càng nguy cơ vỡ hay hoại tử {{BHNgTH tr.99}} {{Notion}}\n- **Thủng**: X quang bụng thấy khí tự do; CLVT đánh giá u và ổ nhiễm trùng; xét nghiệm bạch cầu, tiểu cầu, chức năng gan, thận {{BHNgTH tr.233}}\n\n### Phân giai đoạn TNM (AJCC 8)\n- Dựa vào độ sâu xâm lấn, số hạch di căn, di căn xa; hạch là yếu tố tiên lượng quan trọng nhất khi bệnh còn khu trú {{BHNgTH tr.221}}\n\n| T | Tiêu chuẩn |\n|---|---|\n| Tis | Trong biểu mô hoặc xâm lấn lớp đệm niêm mạc |\n| T1 / T2 | Xâm lấn lớp dưới niêm / lớp cơ chính |\n| T3 | Xuyên qua lớp cơ vào mô quanh đại tràng |\n| T4a / T4b | Xuyên phúc mạc tạng (kể cả thủng u) / xâm lấn hoặc dính cơ quan lân cận {{BHNgTH tr.222}} |\n\n| N | Tiêu chuẩn |\n|---|---|\n| N1 (a, b, c) | 1–3 hạch vùng (N1a: 1 hạch; N1b: 2–3 hạch); N1c: không có hạch nhưng có nốt u rời rạc |\n| N2 (a, b) | Từ 4 hạch: N2a 4–6 hạch; N2b từ 7 hạch {{BHNgTH tr.223}} |\n\n- M1a: một cơ quan, không di căn phúc mạc; M1b: hai cơ quan trở lên, không di căn phúc mạc; M1c: di căn phúc mạc, có hoặc không kèm cơ quan khác {{BHNgTH tr.223}}\n\n| Giai đoạn | TNM |\n|---|---|\n| 0 | Tis N0 |\n| I | T1–T2 N0 |\n| IIA / IIB / IIC | T3 / T4a / T4b, N0 |\n| IIIA | T1–T2 N1/N1c; T1 N2a |\n| IIIB | T3–T4a N1/N1c; T2–T3 N2a; T1–T2 N2b |\n| IIIC | T4a N2a; T3–T4a N2b; T4b N1–N2 |\n| IVA / IVB / IVC | Bất kỳ T, N; M1a / M1b / M1c {{BHNgTH tr.223}} |\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Tiêu chuẩn chẩn đoán xác định\n> - Nội soi đại tràng thấy u và **sinh thiết** có carcinôm {{BHNgTH tr.228}}\n> - Xếp giai đoạn bằng CLVT bụng chậu có cản quang (và hình ảnh ngực khi cần di căn xa), CEA nền trước mổ {{BHNgTH tr.228}} {{BHNgTH tr.229}}\n> - Người trên 50 tuổi tắc ruột cơ học, chưa mổ bụng: nghĩ UTĐT cho đến khi chứng minh khác {{BHNgTH tr.233}}\n\n### Chẩn đoán phân biệt\n| Bệnh | Điểm cần phân biệt |\n|---|---|\n| Trĩ | Đi cầu ra máu dễ nhầm, làm chẩn đoán ung thư chậm {{BHNgTH tr.227}} |\n| Nguồn chảy máu khác | Máu ẩn trong phân dương tính cũng gặp ở viêm loét dạ dày, polyp, viêm đại tràng {{BHNgTH tr.229}} |\n| U không biểu mô | U mỡ, carcinoid, GIST (CD117 dương tính), lymphoma (hay ở manh tràng), u cơ trơn {{BHNgTH tr.218}} {{BHNgTH tr.219}} |\n| Lạc nội mạc tử cung | Giống ung thư, triệu chứng theo chu kỳ kinh {{BHNgTH tr.219}} |\n| Di căn đến đại tràng | Từ vú, dạ dày, buồng trứng, melanôm, bạch cầu {{BHNgTH tr.219}} |\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n- **Cắt trọn đoạn đại tràng mang u** cùng mạc treo, mạch, bạch huyết, bờ cắt an toàn: điều trị triệt căn khi chưa di căn xa {{BHNgTH tr.229}}\n- Chọn phương pháp theo giai đoạn, kích thước và vị trí u {{BHNgTH tr.229}}\n- Không còn triệt căn được: **phẫu thuật làm sạch** để ngừa biến chứng, kéo dài sống không triệu chứng {{BHNgTH tr.229}}\n- Có biến chứng cấp cứu: trước hết cứu sống, giải quyết tắc và nhiễm trùng; nguyên tắc ung thư học chỉ đặt nặng khi bệnh nhân ổn {{BHNgTH tr.233}} {{Notion}}\n\n### 7.2 Các phương pháp\n@@tabs\n@@tab Phẫu thuật cắt đại tràng\n| Phẫu thuật | Chỉ định | Mạch thắt tận gốc, phạm vi cắt |\n|---|---|---|\n| Cắt đại tràng phải | Manh tràng, đại tràng lên | Hồi tràng cuối đến giữa đại tràng ngang; bó hồi đại tràng + đại tràng phải (nếu không xuất phát trực tiếp từ mạc treo tràng trên thì thắt nhánh phải của đại tràng giữa) {{BHNgTH tr.232}} |\n| Cắt đại tràng phải mở rộng | Góc gan, 2/3 phải đại tràng ngang | Hồi tràng cuối đến góc lách; thắt hồi đại tràng, đại tràng phải, đại tràng giữa {{BHNgTH tr.232}} |\n| Cắt đại tràng ngang | 1/3 giữa đại tràng ngang; **ít áp dụng** | Cắt đại tràng ngang + bó đại tràng giữa; khó vì phải hạ cả hai góc, miệng nối căng do đại tràng lên và xuống cố định {{BHNgTH tr.232}} |\n| Cắt đại tràng trái (mở rộng) | 1/3 trái đại tràng ngang, góc lách | Từ đại tràng ngang đến chậu hông; thắt đại tràng giữa, đại tràng trái {{BHNgTH tr.232}} |\n| Cắt đại tràng trái | Đại tràng xuống, đoạn gần đại tràng chậu hông | Từ góc lách đến chậu hông; thắt nhánh trái đại tràng giữa, đại tràng trái, có thể cả mạc treo tràng dưới {{BHNgTH tr.232}} |\n| Cắt đại tràng chậu hông | 1/3 giữa đại tràng chậu hông, đoạn chậu hông đủ dài để nối | Thắt động mạch mạc treo tràng dưới tận gốc; nếu quai còn dài có thể bảo tồn động mạch để tưới máu miệng nối nhưng phải nạo hạch dọc theo {{BHNgTH tr.232}} |\n| Cắt trước | 1/3 cuối đại tràng chậu hông | Thắt tận gốc động mạch và tĩnh mạch mạc treo tràng dưới; nối đại tràng chậu hông gần với trực tràng {{BHNgTH tr.232}} |\n@@tab Kỹ thuật hiện đại\n- **Nội soi** cắt đại tràng làm được như mổ mở: hỗ trợ (có bàn tay hoặc mở nhỏ để phẫu tích thêm) hoặc hoàn toàn; các thử nghiệm COST, CLASICC, COLOR, JCOG 0404 cho kết quả ung thư học tương đương; nay là điều trị tiêu chuẩn {{Notion}}\n- Nội soi: nằm viện ngắn, ít đau hơn, tai biến không hơn; chuyển mổ mở khoảng 1/5 (COST) và 29% (CLASICC); COLOR cho thấy trung tâm ít ca có thời gian mổ, tỉ lệ chuyển mổ mở và biến chứng cao hơn {{Notion}}\n- **CME/CVL** (cắt toàn bộ mạc treo đại tràng, thắt mạch trung tâm; Hohenberger 2006): giữ mặt phẳng phẫu tích giữa mạc treo và mạc dưới phúc mạc, lấy trọn hạch và hệ bạch huyết; nhiều hạch hơn, ít chảy máu và rò bạch huyết; có tác giả cho là chỉ cải thiện kỹ thuật {{Notion}}\n- **Nạo hạch D2** lấy hạch cạnh đại tràng và trung gian; **D3** thêm hạch gốc (tiêu chuẩn tại Nhật, Hàn, Trung Quốc, Đài Loan); chưa chứng minh D3 tốt hơn về ung thư học và dễ biến chứng ở phẫu thuật viên ít kinh nghiệm; CME/CVL không đồng nghĩa D2/D3 {{Notion}}\n- Tại Việt Nam, CME + CVL với nạo hạch D2 có thể xem là tiêu chuẩn {{Notion}}\n@@tab Nội soi can thiệp\n- Giai đoạn 0 (Tis): cắt polyp bằng thòng lọng, EMR, ESD qua nội soi, vừa chẩn đoán vừa điều trị; tổn thương lớn không cắt rộng được thì cắt đoạn {{BHNgTH tr.230}}\n- JSCCR: cTis và cT1 xâm lấn nhẹ cắt nguyên khối qua nội soi rồi theo dõi; cT1 xâm lấn sâu hoặc không cắt trọn được thì phẫu thuật {{BHNgTH tr.231}}\n@@tab Hỗ trợ\n- Hóa trị: giai đoạn III bắt buộc (FOLFOX hoặc CAPEOX; 3 tháng nguy cơ thấp, 6 tháng nguy cơ cao); giai đoạn II chỉ khi nguy cơ cao; giai đoạn IV là điều trị chính, phác đồ cá thể theo KRAS/NRAS/BRAF, dMMR/MSI-H ưu tiên miễn dịch {{BHNgTH tr.234}}\n- Xạ trị: vai trò rất hạn chế, chỉ khu trú vùng giường u hoặc giảm đau di căn xương {{BHNgTH tr.234}}\n- Chi tiết phác đồ: xem [Ung thư đại trực tràng (module Ung bướu)](#/n/ung-thu-daitruc-trang)\n@@end\n\n### 7.3 Chỉ định – hướng xử trí\n\n#### Theo giai đoạn (NCCN 01.2025 trong giáo trình)\n| Giai đoạn | Hướng xử trí |\n|---|---|\n| 0 | Cắt rộng tại chỗ hoặc cắt polyp bờ an toàn (nội soi); tổn thương lớn thì cắt đoạn {{BHNgTH tr.230}} |\n| I, II | **Cắt đoạn đại tràng**; hóa trị hỗ trợ không thường quy, cân nhắc khi: u gây tắc hoặc thủng, T4, xâm nhiễm mạch/bạch huyết/thần kinh, biệt hóa kém, tumor budding cao, khảo sát ≤12 hạch {{BHNgTH tr.230}} |\n| III | Cắt đoạn đại tràng + hóa trị hỗ trợ thường quy; 5-FU/LV nâng sống còn toàn bộ 5 năm từ 64% lên 71%, sống không bệnh từ 58% lên 67% {{BHNgTH tr.230}} |\n| IV, tái phát | Di căn xa còn cắt được: mổ triệt để cả u nguyên phát và di căn là cách duy nhất có thể trị khỏi; không cắt được: cắt u nguyên phát để cải thiện triệu chứng và tiên lượng; u gây tắc hoặc chảy máu: cắt đoạn hoặc nối tắt; lan tràn toàn thân thì hóa trị là căn bản {{BHNgTH tr.230}} |\n\n#### Biến chứng cấp cứu\n@@tabs\n@@tab Tắc ruột\n- Dịch tễ: UTĐT chiếm ==60% tắc ruột ở người lớn tuổi==; giáo trình cũ: thường do u đại tràng trái {{BHNgTH tr.233}} {{Notion}}\n- Cơ chế nguy hiểm: **tắc quai kín** khi van hồi manh tràng còn hiệu lực; típ A và B còn nguy cơ vỡ đại tràng trên chỗ tắc, hay vỡ ở **manh tràng** (định luật Laplace); típ C van mất hiệu lực, ruột non giãn, bớt nguy cơ vỡ {{BHNgTH tr.95}}\n- **Tắc không hoàn toàn**: không mổ cấp cứu; đặt sonde dạ dày, hồi sức nước điện giải; làm đủ cận lâm sàng xếp giai đoạn rồi lên kế hoạch mổ (giáo trình cũ: mổ một thì) {{BHNgTH tr.233}} {{Notion}}\n- **Tắc hoàn toàn**: chọn theo tình trạng đại tràng, vị trí tắc, khả năng cắt u và mục tiêu chăm sóc sau mổ; có thể mổ triệt để, mổ giảm nhẹ hoặc đặt stent {{BHNgTH tr.233}} {{Notion}}\n- **Tắc do u đại tràng phải còn cắt được**: cắt đại tràng phải, nối hồi tràng – đại tràng ngang; hoặc cắt đưa hai đầu ra da, nối tắt hồi – đại tràng ngang, mở thông hồi tràng {{BHNgTH tr.113}}\n- **Tắc do u đại tràng trái** (từ góc lách trở xuống): cắt đại tràng trái nối ngay kèm rửa đại tràng trong mổ; cắt đưa hai đầu ra làm hậu môn nhân tạo; nối tắt đại tràng ngang – chậu hông; hậu môn nhân tạo trên dòng {{BHNgTH tr.113}}\n  - Giáo trình cũ: tắc do u phải còn cắt được thì cắt nối một thì không còn bàn cãi; u trái thì mổ nhiều thì vẫn phổ biến, mổ một thì chỉ chọn lọc ở bệnh nhân đủ điều kiện, phẫu thuật viên có kinh nghiệm {{Notion}}\n- **Stent kim loại tự bung (SEMS)** qua u bằng nội soi: nếu thành công và u còn cắt được thì chuẩn bị đại tràng, mổ chương trình cắt nối một thì; không cắt được hoặc quá muộn thì giữ stent, điều trị giảm nhẹ {{BHNgTH tr.114}}\n  - Số liệu cũ: thành công kỹ thuật 96%, đáp ứng lâm sàng 92%, lệch stent 11%, thủng 4,5%, tắc lại 12%; sau stent 90% mổ một thì thành công; mổ cấp cứu có biến chứng cao và đa số phải mang hậu môn nhân tạo, 40% suốt đời {{Notion}}\n  - Điều kiện đặt stent: xác định rõ vị trí, mức độ tắc, chiều dài sang thương và loại trừ tắc đã có biến chứng cần mổ cấp cứu {{Notion}}\n- Nơi chưa có stent (như Việt Nam, theo giáo trình cũ): hậu môn nhân tạo trên dòng bằng đường mổ nhỏ ở ca ổn định, sau 1–2 tuần nội soi cắt đại tràng triệt căn ở thì 2; bản chất vẫn là mổ hai thì {{Notion}}\n@@tab Thủng\n- Thủng tại u, hoặc ở đại tràng trên chỗ tắc (nhất là van hồi manh tràng đóng kín); u thủng được bao bọc thì có viêm phúc mạc khu trú, khối u hoặc áp-xe thành bụng {{BHNgTH tr.233}}\n- Điều trị: **cắt u, rửa bụng, dẫn lưu, kháng sinh phổ rộng, hồi sức** {{BHNgTH tr.233}}\n- Ưu tiên kiểm soát nhiễm trùng ổ bụng; bệnh nhân không ổn: mổ sớm để cứu sống, chưa cần theo nguyên tắc ung thư (CME, nạo hạch, diện cắt); ổn định thì cố giữ nguyên tắc ung thư {{Notion}}\n- Hầu hết cần hậu môn nhân tạo, khoảng 50% không thể tái lập lưu thông; thủng đại tràng trên u: có thể cân nhắc cắt gần toàn bộ đại tràng đến qua chỗ thủng {{Notion}}\n@@tab Chảy máu\n- Chảy máu tiêu hóa dưới ở 6–17% ca, nặng rất hiếm, hay biểu hiện phân đen; nội soi đại tràng xác định vị trí; thường điều trị nội khoa và mổ chương trình {{BHNgTH tr.234}}\n- Giáo trình cũ: chảy máu ồ ạt thì hồi sức và mổ cấp cứu; ưu tiên nội soi can thiệp, thất bại thì cắt sang thương; có thể can thiệp nội mạch nếu CLVT thấy đang chảy máu mà bệnh nhân không chịu được mổ lớn {{Notion}}\n@@end\n\n> [!warn] Giáo trình mới không nêu\n> Chương Ung thư đại tràng 2025 không có tiêu chí chọn bệnh nhân đặt stent hay mổ một thì và không nêu liều thuốc hóa trị chi tiết; các ý này chỉ có ở giáo trình cũ (Notion) hoặc module Ung bướu. Cách chọn kiểu mổ trong tắc ruột do ung thư có ở chương Tắc ruột {{BHNgTH tr.113}}\n\n## 8. Tiên lượng – Dự phòng / theo dõi sau mổ\n\n### Tiên lượng\n- Kết quả điều trị cải thiện rõ nhờ mổ an toàn hơn và điều trị hỗ trợ tốt hơn; tiên lượng phụ thuộc chủ yếu vào **giai đoạn** {{BHNgTH tr.210}} {{BHNgTH tr.235}}\n\n| Giai đoạn (AJCC 8) | Sống 5 năm |\n|---|---|\n| I | 90–95% |\n| IIA / IIB / IIC | 85–90% / 80–85% / 70–75% |\n| IIIA / IIIB / IIIC | 65–75% / 60–65% / 40–50% |\n| IV | 12–20% {{BHNgTH tr.235}} |\n\n### Theo dõi sau điều trị\n- **Giai đoạn 0, I**: nội soi đại tràng sau mổ 1 năm; có polyp tuyến thì nội soi lại sau 1 năm; bình thường thì lại sau 3 năm rồi mỗi 5 năm {{BHNgTH tr.235}}\n- **Giai đoạn II, III**: tái khám mỗi 3–6 tháng trong 2 năm đầu, mỗi 6 tháng trong 3 năm tiếp theo; mỗi lần làm siêu âm bụng và CEA {{BHNgTH tr.235}}\n  - CLVT bụng mỗi năm trong 5 năm đầu nếu nguy cơ tái phát cao hoặc siêu âm nghi ngờ {{BHNgTH tr.235}}\n  - Nội soi đại tràng sau mổ 1 năm; nếu chưa soi hết khung đại tràng trước mổ (ví dụ do tắc) thì soi sau mổ 3–6 tháng {{BHNgTH tr.235}}\n- CEA không hạ sau mổ triệt căn: nghĩ di căn chưa phát hiện {{BHNgTH tr.229}}\n\n### Dự phòng\n- Tầm soát tìm và cắt polyp tuyến trước khi ác hóa làm giảm nguy cơ ung thư đại–trực tràng {{BHNgTH tr.210}} {{BHNgTH tr.213}}\n- Aspirin/NSAID, hormone thay thế **không** được dùng để phòng UTĐT vì tác dụng phụ {{BHNgTH tr.212}} {{BHNgTH tr.213}}\n- Việt Nam chưa có chương trình tầm soát quốc gia (giáo trình cũ) {{Notion}}\n- Chương trình tầm soát chi tiết: xem [Ung thư đại trực tràng (module Ung bướu)](#/n/ung-thu-daitruc-trang)\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] UTĐT ngoại khoa thi nhấn mạnh gì\n> - **Nhận diện**: người trên 50 tuổi đổi thói quen đi cầu, đi cầu ra máu (đừng nhầm trĩ), thiếu máu; hoặc tắc ruột cơ học chưa từng mổ bụng {{BHNgTH tr.227}} {{BHNgTH tr.233}}\n> - **Chẩn đoán**: nội soi + sinh thiết; CLVT xếp giai đoạn; CEA chỉ để theo dõi {{BHNgTH tr.228}} {{BHNgTH tr.229}}\n> - **Xử trí**: cắt đoạn đại tràng đúng theo vị trí u; xử trí tắc và thủng như cấp cứu {{BHNgTH tr.232}} {{BHNgTH tr.233}}\n\n@@tabs\n@@tab Nhận diện\n- Đau bụng thường gặp nhất, đổi thói quen đi cầu thứ hai; ra máu khoảng 25% {{BHNgTH tr.227}}\n- Phải: phân lỏng, muộn; trái: phân cứng, vòng nhẫn, biểu hiện sớm hơn {{BHNgTH tr.227}}\n- Trên 50 tuổi, chưa mổ bụng, tắc ruột cơ học: nghĩ UTĐT (60% tắc ruột người già) {{BHNgTH tr.233}}\n- Xem [mục 4](#/n/ngoai-ung-thu-dai-trang/4)\n@@tab Chẩn đoán\n- Nội soi + sinh thiết là tiêu chuẩn vàng; CLVT thường quy; CEA không chẩn đoán {{BHNgTH tr.228}} {{BHNgTH tr.229}}\n- Hạch là yếu tố tiên lượng quan trọng nhất khi bệnh khu trú {{BHNgTH tr.221}}\n- Xem [mục 5](#/n/ngoai-ung-thu-dai-trang/5) và [mục 6](#/n/ngoai-ung-thu-dai-trang/6)\n@@tab Điều trị\n- Cắt phải: manh tràng, đại tràng lên; phải mở rộng: góc gan, 2/3 phải đại tràng ngang {{BHNgTH tr.232}}\n- Cắt trái: góc lách, đại tràng xuống; cắt trước: 1/3 cuối đại tràng chậu hông {{BHNgTH tr.232}}\n- Giai đoạn I–II cắt đoạn; III thêm hóa trị thường quy; IV: cắt cả u và di căn nếu cắt được {{BHNgTH tr.230}}\n- Tắc hoàn toàn: mổ triệt để, giảm nhẹ hoặc stent; thủng: cắt u, rửa bụng, dẫn lưu, kháng sinh, hồi sức {{BHNgTH tr.233}}\n- Xem [mục 7.3](#/n/ngoai-ung-thu-dai-trang/7)\n@@tab Tiên lượng – Dự phòng\n- Sống 5 năm: giai đoạn I 90–95%, IV 12–20% {{BHNgTH tr.235}}\n- Giai đoạn II–III: tái khám 3–6 tháng trong 2 năm đầu, siêu âm và CEA mỗi lần {{BHNgTH tr.235}}\n- Xem [mục 8](#/n/ngoai-ung-thu-dai-trang/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Nguy cơ mắc suốt đời | ==1/20== | {{BHNgTH tr.210}} |\n| Tỉ lệ ca trên 50 tuổi | ==trên 90%== | {{BHNgTH tr.213}} |\n| Thời gian polyp tuyến thành ung thư | ==5–10 năm== | {{BHNgTH tr.213}} |\n| Polyp tuyến nhánh trên 2 cm chứa tế bào ung thư | ==50%== | {{BHNgTH tr.213}} |\n| Bờ cắt an toàn cách u | ==khoảng 5 cm== | {{BHNgTH tr.229}} |\n| Di căn hạch: biệt hóa tốt / vừa / kém | ==25% / 50% / 80%== | {{BHNgTH tr.220}} |\n| Di căn xa hay gặp nhất | ==gan (77%)== | {{BHNgTH tr.220}} |\n| Gieo rắc phúc mạc | ==khoảng 10%== | {{BHNgTH tr.220}} |\n| Đi cầu ra máu | ==khoảng 25%== | {{BHNgTH tr.227}} |\n| Độ nhạy CLVT với di căn gan | ==85%== | {{BHNgTH tr.229}} |\n| Hạch khảo sát đủ (khuyến cáo trong chỉ định hóa trị giai đoạn II) | ==trên 12 hạch== | {{BHNgTH tr.230}} |\n| Hóa trị giai đoạn III | ==3 tháng (nguy cơ thấp) / 6 tháng (cao)== | {{BHNgTH tr.234}} |\n| UTĐT trong tắc ruột người lớn tuổi | ==60%== | {{BHNgTH tr.233}} |\n| Chảy máu tiêu hóa dưới | ==6–17%== | {{BHNgTH tr.234}} |\n| Sống 5 năm giai đoạn I / IV | ==90–95% / 12–20%== | {{BHNgTH tr.235}} |\n| Nội soi sau mổ giai đoạn 0–I: bình thường | ==1 năm, 3 năm, rồi mỗi 5 năm== | {{BHNgTH tr.235}} |\n\n> [!warn] Bẫy thi thường gặp\n> - **Cắt đại tràng phải** cho manh tràng và đại tràng lên; **mở rộng** cho góc gan và 1/3 (2/3) phải đại tràng ngang; góc lách thuộc nhóm cắt đại tràng trái {{BHNgTH tr.232}}\n> - Cắt trước dành cho **1/3 cuối đại tràng chậu hông**, thắt tận gốc mạch mạc treo tràng dưới {{BHNgTH tr.232}}\n> - **CEA** không dùng để chẩn đoán, chỉ để tiên lượng và theo dõi {{BHNgTH tr.229}}\n> - Tắc ruột không hoàn toàn: **không** mổ cấp cứu, hồi sức rồi lên kế hoạch mổ {{BHNgTH tr.233}}\n> - Thủng ở đại tràng **trên chỗ tắc** (manh tràng) khi van hồi manh tràng còn hiệu lực, không chỉ tại u {{BHNgTH tr.233}} {{BHNgTH tr.95}}\n> - Giai đoạn II không hóa trị thường quy, giai đoạn III thì có {{BHNgTH tr.230}}\n> - Sống 5 năm: giáo trình cũ (Notion) ghi giai đoạn I trên 90%, II 65–90%, III 45–75%, IV 9–14%; theo giáo trình 2025 là I 90–95%, IV 12–20% (bảng ở mục 8) {{BHNgTH tr.235}} {{Notion}}\n> - Tần suất UTĐT: giáo trình 2025 nói giảm ở người lớn tuổi, tăng ở người trẻ; giáo trình cũ (Notion) ghi tần suất tăng toàn thế giới rồi giảm dần ở nước phát triển {{BHNgTH tr.211}} {{Notion}}\n\n@@fold Nguồn tài liệu\n- **BHNgTH** Giáo trình Bệnh học ngoại khoa tiêu hóa 2025, chương Ung thư đại tràng, tr.210–235 (số trang PDF; sách in tr.201–226): dịch tễ, yếu tố nguy cơ, giải phẫu bệnh, lan rộng, TNM, lâm sàng, cận lâm sàng, phẫu thuật, biến chứng, theo dõi, tiên lượng\n- **BHNgTH** chương Tắc ruột, tr.95 (3 típ tắc đại tràng), tr.99 (quy tắc 3–6–9, đã đối chiếu), tr.113–114 (xử trí tắc do ung thư đại tràng, stent)\n- Bảng TNM và bảng sống còn 5 năm là chữ trích được từ trang; hình vẽ phân đoạn đại tràng và lưu đồ JSCCR (tr.222, tr.231) không đọc từ ảnh\n@@end\n\n@@fold Nguồn ngoài\n- Từ Notion \"[BHNgK] Ung thư đại tràng\" (giáo trình cũ, ô {{Notion}}): chiều dài các đoạn đại tràng; nội soi so với mổ mở (COST, CLASICC, COLOR, JCOG 0404); CME/CVL; D2/D3; chi tiết xử trí tắc ruột (tắc phải một thì, tắc trái mổ nhiều thì, stent SEMS và số liệu, hậu môn nhân tạo trên dòng); nguyên tắc cứu sống trong thủng; xử trí chảy máu ồ ạt (nội soi, nội mạch); quy tắc 3–6–9; triệu chứng bổ sung; Việt Nam chưa có tầm soát quốc gia\n- Khác biệt: sống 5 năm và xu hướng dịch tễ (xem hộp \"Bẫy thi\"); giáo trình cũ ghi tắc ruột do UTĐT \"gần 1/3\" bệnh nhân nhập viện vì biến chứng tắc, giáo trình mới ghi 60% tắc ruột người lớn tuổi do UTĐT\n- Không có nguồn: liều thuốc hóa trị cụ thể, ngưỡng đường kính manh tràng để mổ cấp cứu\n@@end\n\n@@fold! Tự kiểm tra (12 thẻ)\n- Nguyên tắc phẫu thuật ung thư đại tràng? :: Cắt trọn đoạn đại tràng mang u cùng mạc treo, mạch nuôi, bạch huyết, thắt mạch tận gốc, bờ cắt khoảng 5 cm, kỹ thuật không chạm\n- Vì sao mạch nuôi phải thắt tận gốc? :: Bạch huyết dẫn lưu dọc theo động mạch, thắt tận gốc mới nạo vét hạch được\n- Chỉ định cắt đại tràng phải và cắt đại tràng phải mở rộng? :: Phải: manh tràng, đại tràng lên; mở rộng: góc gan và 2/3 phải đại tràng ngang (thắt thêm đại tràng giữa)\n- Vì sao cắt đại tràng ngang ít được áp dụng? :: Đại tràng ngang không đủ dài để cắt nối, phải hạ cả hai góc, miệng nối căng do đại tràng lên và xuống cố định\n- Phẫu thuật cắt trước dành cho u ở đâu? :: 1/3 cuối đại tràng chậu hông, thắt tận gốc động mạch và tĩnh mạch mạc treo tràng dưới\n- Tiêu chuẩn vàng chẩn đoán UTĐT và vai trò của CEA? :: Nội soi đại tràng + sinh thiết; CEA không chẩn đoán, dùng tiên lượng và theo dõi sau mổ\n- Đại tràng nào dễ gieo rắc phúc mạc, đại tràng nào xâm lấn sau phúc mạc? :: Di động (manh tràng, ngang, chậu hông) gieo rắc phúc mạc; đại tràng lên và xuống có mạc Toldt xâm lấn thận, niệu quản, tụy\n- Xử trí giai đoạn I, II, III? :: I–II: cắt đoạn đại tràng (hóa trị khi nguy cơ cao: tắc, thủng, T4, kém biệt hóa, ≤12 hạch); III: cắt đoạn + hóa trị hỗ trợ thường quy\n- Tắc ruột do UTĐT: khi nào mổ cấp cứu, khi nào không? :: Tắc không hoàn toàn thì hồi sức, không mổ cấp cứu; tắc hoàn toàn thì mổ triệt để, giảm nhẹ hoặc đặt stent\n- Vì sao tắc quai kín dễ vỡ manh tràng? :: Van hồi manh tràng còn hiệu lực, đại tràng giãn giữa hai điểm tắc, áp lực cao nhất ở manh tràng (định luật Laplace)\n- Điều trị thủng đại tràng do UTĐT? :: Cắt u, rửa bụng, dẫn lưu, kháng sinh phổ rộng, hồi sức; đa số cần hậu môn nhân tạo\n- Lịch theo dõi giai đoạn II–III? :: Mỗi 3–6 tháng trong 2 năm đầu, mỗi 6 tháng trong 3 năm sau; siêu âm bụng và CEA mỗi lần; CLVT hằng năm 5 năm nếu nguy cơ cao; nội soi sau mổ 1 năm\n@@end"}, {"kind": "disease", "disease": "ung-thu-gan-hcc", "short": "Ung thư tế bào gan", "group": "", "section": 0, "order": 25, "khung": [], "id": "ngoai-ung-thu-gan-hcc", "title": "Ung thư biểu mô tế bào gan (ngoại khoa)", "layer": "benh", "module": "ngoai-tong-quat", "tags": ["ngoại khoa", "tiêu hóa", "gan", "HCC", "UTBMTBG", "Child-Pugh", "BCLC", "cắt gan", "ghép gan", "Milan", "RFA", "TACE", "phân thùy gan"], "source": "BHNgTH tr.359–381 (chương Ung thư biểu mô tế bào gan; sách in tr.350–372), tr.18 (Child-Turcotte-Pugh, thể tích gan còn lại); TCBN tr.31; Notion (giải phẫu phân thùy gan, nguyên tắc cắt gan)", "body": "> [!key] Ung thư biểu mô tế bào gan (UTBMTBG, HCC) dưới góc nhìn ngoại khoa\n> - Ở Việt Nam là ung thư có tỷ lệ mới mắc và tử vong cao nhất (GLOBOCAN 2018); phần lớn trên nền viêm gan B, C và xơ gan, ít triệu chứng nên phát hiện muộn {{BHNgTH tr.359}} {{BHNgTH tr.360}}\n> - Chẩn đoán xác định chủ yếu dựa vào hình ảnh điển hình (bắt thuốc thì động mạch, thải thuốc thì tĩnh mạch/muộn) mà không cần sinh thiết {{BHNgTH tr.364}}\n> - Chọn điều trị dựa trên ba yếu tố: ==khối u – chức năng gan (Child-Pugh) – thể trạng (ECOG)== {{BHNgTH tr.370}} {{BHNgTH tr.371}}\n> - Điều trị triệt căn: cắt gan (phổ biến nhất), ghép gan, hủy u tại chỗ; không triệt căn: TACE, HAIC, SIRT, thuốc toàn thân {{BHNgTH tr.371}}\n> - Cắt gan khi u đơn độc, xơ gan Child-Pugh A và thể tích gan để lại hơn 30–40% {{BHNgTH tr.371}}\n> - Liên quan: [Ung thư gan (module Ung bướu)](#/n/ung-thu-gan)\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Yếu tố nguy cơ chính: viêm gan B (khoảng 60% ca), viêm gan C (khoảng 20%), rượu, aflatoxin, gan nhiễm mỡ {{BHNgTH tr.360}}\n> - Gan chia thành 2 nửa, 4 phân thùy, 8 hạ phân thùy theo phẫu thuật: nền tảng để hiểu các kiểu cắt gan {{Notion}}\n\n### Định nghĩa & dịch tễ\n- Ung thư gan đứng thứ 6 trong các ung thư thường gặp trên thế giới, nhưng gây tử vong nhiều thứ hai; khoảng 75% ca ở châu Á {{BHNgTH tr.359}} {{BHNgTH tr.360}}\n- Nam nhiều hơn nữ, tỷ lệ khoảng 2/1 đến 4/1 {{BHNgTH tr.360}}\n- Việt Nam: cao nhất về mới mắc khi tính chung hai giới và là nguyên nhân tử vong ung thư nhiều nhất (GLOBOCAN 2018) {{BHNgTH tr.360}}\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Virus viêm gan\n- **HBV**: nguy cơ cao hơn người bình thường 15–20 lần (5–103 lần) {{BHNgTH tr.360}}\n  - Tăng thêm nguy cơ: nam, lớn tuổi, gốc Á/Phi, tiền sử gia đình, lây từ mẹ sang con, HBsAg trên 1000 IU/mL, HBV-DNA trên 2000 IU/mL, genotype C, HBeAg dương kéo dài, đồng nhiễm HCV/HIV/HDV, xơ gan {{BHNgTH tr.360}}\n  - Điều trị kháng virus làm giảm nhưng không loại trừ nguy cơ {{BHNgTH tr.360}}\n- **HCV**: anti-HCV dương có nguy cơ gấp 17 lần; từ khi có xơ gan do HCV, HCC hình thành 1–7% mỗi năm {{BHNgTH tr.360}}\n@@tab Khác\n- **Gan nhiễm mỡ không do rượu (NAFLD)**: OR khoảng 1,8–2,6 {{BHNgTH tr.361}}\n- Mọi bệnh gan dẫn đến xơ gan đều tăng nguy cơ; xơ gan do ứ sắt bẩm sinh nguy cơ gấp 20 lần {{BHNgTH tr.361}}\n- **Aflatoxin B1** (nấm Aspergillus flavus): bền nhiệt, chỉ phân hủy hoàn toàn trên 160 độ C, rang lạc ngô mốc không phá hết độc tố {{BHNgTH tr.361}}\n- **Rượu**: trên 80 g/ngày hơn 10 năm tăng nguy cơ gấp 5 lần {{BHNgTH tr.361}} {{BHNgTH tr.362}}\n- **Thuốc lá**: tăng nguy cơ gấp 1,5 lần (IARC 2004) {{BHNgTH tr.362}}\n@@end\n\n### Giải phẫu gan ứng dụng cho cắt gan\n> [!tip] Phần này từ Notion (giải phẫu và giải phẫu ứng dụng phẫu thuật), giáo trình bệnh học 2025 không trình bày {{Notion}}\n\n- **Theo giải phẫu** (hình thể ngoài): 4 thùy phải, trái, vuông, đuôi; mốc là khe dây chằng liềm, hai rãnh dọc và cửa gan {{Notion}}\n- **Theo phẫu thuật** (theo mạch máu và đường mật, dùng thực tế khi cắt gan): gan phải và gan trái, mỗi nửa chia 2 phân thùy, mỗi phân thùy chia 2 hạ phân thùy {{Notion}}\n\n| Nửa gan | Phân thùy | Hạ phân thùy |\n|---|---|---|\n| Gan trái | Bên | II, III |\n| Gan trái | Giữa (trong) | IV, và I (thùy đuôi, chỉ thấy ở mặt tạng) |\n| Gan phải | Trước | V, VIII |\n| Gan phải | Sau | VI, VII |\n\n- **Khe giữa** (khe chính): từ điểm giữa hố túi mật đến giữa TM chủ dưới, chứa TM gan giữa, chia gan phải/gan trái {{Notion}}\n- **Khe liên phân thùy trái**: theo dây chằng liềm ở mặt hoành, chứa TM gan trái, chia phân thùy giữa và bên {{Notion}}\n- **Khe liên phân thùy phải**: chứa TM gan phải, chia phân thùy trước và sau {{Notion}}\n- Cấp máu: ĐM gan riêng (từ ĐM gan chung, nhánh thân tạng) và TM cửa, cùng chia hai ngành phải/trái ở cửa gan; máu về TM chủ dưới qua 3 TM gan (phải, giữa, trái) {{Notion}}\n- Trong gan, ĐM gan, TM cửa và đường mật đi chung trong bao Glisson; biến thể giải phẫu chỉ xảy ra bên trong bao {{Notion}}\n- Cung cấp máu của u HCC chủ yếu từ ĐM gan, khác nhu mô gan lành cấp máu chủ yếu từ TM cửa: cơ sở của hình ảnh điển hình và của TACE {{BHNgTH tr.363}} {{BHNgTH tr.364}}\n\n### Diễn tiến tự nhiên\n- Hầu hết HCC xuất hiện trên nền gan viêm mạn, xơ hóa, nên chức năng gan và thể trạng quyết định cả giai đoạn lẫn điều trị {{BHNgTH tr.370}}\n- Có thể xâm lấn TM cửa (huyết khối u) và di căn xa (phổi, xương) {{BHNgTH tr.364}} {{BHNgTH tr.370}}\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Giai đoạn sớm gần như không triệu chứng; nếu hỏi kỹ chỉ thấy dấu hiệu viêm gan, xơ gan {{BHNgTH tr.362}}\n> - Giai đoạn muộn: biểu hiện xơ gan mất bù, gan to cứng hoặc sờ thấy khối u dưới sườn phải/thượng vị {{BHNgTH tr.362}}\n\n- **Tiền căn cần hỏi**: viêm gan B, C; uống rượu; tiếp xúc độc chất, aflatoxin; gia đình có viêm gan B, C hoặc ung thư gan {{BHNgTH tr.362}}\n- **Giai đoạn sớm**: vàng da vàng mắt, báng bụng, tuần hoàn bàng hệ, sao mạch, lòng bàn tay son (do viêm gan, xơ gan) {{BHNgTH tr.362}}\n- **Giai đoạn muộn**: báng bụng, phù chân, nôn ra máu do vỡ TM thực quản, suy kiệt; khám gan to cứng chắc, hoặc khối u vùng dưới sườn phải hay thượng vị khi u ở vùng thấp của gan {{BHNgTH tr.362}}\n\n> [!red] Dấu hiệu báo động\n> - Bệnh nhân xơ gan hoặc viêm gan B, C mạn có gan to cứng, khối u hạ sườn phải, hoặc nôn máu: nghĩ HCC trên xơ gan mất bù {{BHNgTH tr.362}}\n> - U gan vỡ gây xuất huyết nội: giáo trình bệnh học 2025 không đề cập, chỉ gặp trong tài liệu tiếp cận bệnh nhân ngoại (đau bụng, mất vỏ bao gan trên CLVT) {{TCBN tr.31}}\n\n## 5. Cận lâm sàng\n\n### Chất chỉ dấu ung thư\n| Chất | Ý nghĩa | Nguồn |\n|---|---|---|\n| **AFP** | Tăng theo kích thước, độ biệt hóa, xâm lấn; kém hữu ích với u nhỏ giai đoạn sớm; tăng cả trong viêm gan mạn, ung thư tinh hoàn, ung thư tế bào ống mật; AFP càng cao tiên lượng càng xấu, AFP tăng dần sau điều trị báo tái phát | {{BHNgTH tr.362}} {{BHNgTH tr.363}} |\n| **DCP (PIVKA-II)** | Ngưỡng đề xuất 40 mAU/mL, đặc hiệu 95–99% với HCC sớm dưới 5 cm | {{BHNgTH tr.363}} |\n| **AFP-L3** | Ngưỡng 15%, đặc hiệu 94–100%; phân biệt AFP tăng do HCC với bệnh gan lành | {{BHNgTH tr.363}} |\n\n- Ngưỡng AFP: 200 ng/mL theo hiệp hội gan châu Á Thái Bình Dương và Âu Mỹ; ==400 ng/mL theo Bộ Y tế 2020 khi phối hợp hình ảnh điển hình== {{BHNgTH tr.363}}\n- Kết hợp ba chất chỉ dấu làm tăng độ nhạy và độ đặc hiệu {{BHNgTH tr.363}}\n\n### Hình ảnh\n- **Siêu âm**: phương tiện chính để tầm soát; độ nhạy 65–80%, độ đặc hiệu trên 90%; nốt tăng âm (sớm), giảm âm (thường nhỏ dưới 2 cm) hoặc hỗn hợp, bờ không đều {{BHNgTH tr.363}}\n- **CLVT hoặc CHT động học có cản quang**: ==tăng bắt thuốc thì động mạch và thải thuốc thì tĩnh mạch/muộn==; ở bệnh nhân gan mạn hoặc xơ gan có đủ tính chất này thì chẩn đoán xác định, không cần sinh thiết {{BHNgTH tr.363}} {{BHNgTH tr.364}}\n- **Sinh thiết gan**: tiêu chuẩn vàng về giải phẫu bệnh nhưng chỉ khi tổn thương không điển hình và lớn hơn 1–2 cm; khó ở vị trí dưới cơ hoành, cạnh mạch lớn, sát bề mặt (nguy cơ chảy máu, thủng u, gieo rắc tế bào u vào ổ bụng) {{BHNgTH tr.364}}\n- **Tìm di căn**: CLVT ngực không cản quang (phổi), xạ hình xương, PET-CT khi nguy cơ cao hoặc nghi ngờ {{BHNgTH tr.364}}\n\n### Đánh giá chức năng gan và khả năng cắt gan\n> [!key] Ba câu hỏi trước khi cắt gan\n> 1. Chức năng gan còn bù không (Child-Pugh, bilirubin, albumin, INR)?\n> 2. Có tăng áp lực TM cửa không (TM thực quản, lách to, tiểu cầu)?\n> 3. Thể tích gan còn lại sau cắt có đủ không?\n\n- **Xét nghiệm**: AST, ALT, bilirubin toàn phần/trực tiếp/gián tiếp, albumin, TQ/INR {{BHNgTH tr.364}}\n- **Thanh lọc ICG** (indocyanine green): đánh giá gián tiếp chức năng thanh lọc của gan {{BHNgTH tr.364}}\n- **Tăng áp cửa**: đánh giá gián tiếp qua độ dãn TM thực quản, kích thước lách, số lượng tiểu cầu {{BHNgTH tr.365}}\n\n@@tabs\n@@tab Bảng điểm Child-Turcotte-Pugh\n| Tiêu chí | 1 điểm | 2 điểm | 3 điểm |\n|---|---|---|---|\n| Bệnh não gan | Không | Giai đoạn I–II | Giai đoạn III–IV |\n| Báng bụng | Không | Ít | Vừa – nhiều |\n| Bilirubin (mg/dL) | < 2 | 2–3 | > 3 |\n| Albumin (g/L) | > 3,5 | 2,8–3,5 | < 2,8 |\n| PT kéo dài (giây) hoặc INR | < 4 hoặc < 1,7 | 4–6 hoặc 1,7–2,3 | > 6 hoặc > 2,3 |\n\n- **CTP A (5–6 điểm)**: xơ gan còn bù, nguy cơ biến chứng thấp\n- **CTP B (7–9 điểm)**: mất bù mức trung bình, ảnh hưởng đáng kể kết quả phẫu thuật\n- **CTP C (10–15 điểm)**: mất bù nặng, nguy cơ phẫu thuật rất cao\n- Tử vong chung của phẫu thuật bụng ở bệnh nhân xơ gan: 10% (A), 20% (B), 60% (C) {{BHNgTH tr.18}}\n@@tab Thể tích gan còn lại\n- Không xơ gan: gan còn lại trên 20% thường đủ {{BHNgTH tr.18}}\n- Xơ gan: tối thiểu khuyến cáo 40% {{BHNgTH tr.18}}\n- Ước tính bằng đo thể tích gan trên CLVT hoặc CHT với phần mềm chuyên dụng {{BHNgTH tr.18}}\n- Chương HCC nêu điều kiện cắt gan: thể tích gan để lại hơn 30–40% {{BHNgTH tr.371}}\n@@end\n\n> [!warn] Điểm khác giữa các nguồn\n> TCBN ghi Child A 5–7, B 8–12, C 13–15 điểm (và albumin theo g/dL) {{TCBN tr.31}}; giáo trình BHNgTH 2025 ghi A 5–6, B 7–9, C 10–15 {{BHNgTH tr.18}}. Bài này dùng bảng của BHNgTH 2025. Thể tích gan còn lại: chương HCC ghi 30–40%, mục đánh giá trước mổ ghi tối thiểu 40% ở xơ gan; nguồn không giải thích sự khác biệt này.\n\n### Phân giai đoạn\n> [!key] HCC không dùng TNM làm trục chính\n> Phân giai đoạn cần cả tình trạng khối u, chức năng gan và thể trạng; bảng **BCLC 2022** được dùng phổ biến nhất {{BHNgTH tr.370}}\n\n| Giai đoạn BCLC | Điều kiện |\n|---|---|\n| Rất sớm (0) | Child-Pugh A, một u dưới 2 cm, ECOG 0–1 |\n| Sớm (A) | Child-Pugh A–B, một hoặc 2–3 u, mỗi u ≤ 3 cm, ECOG 0–1 |\n| Trung gian (B) | Child-Pugh A–B, nhiều hơn 3 u, ECOG 0–1 |\n| Tiến triển (C) | Child-Pugh A–B, xâm lấn TM cửa, N1, M1, ECOG 0–2 |\n| Cuối (D) | Child-Pugh C, bất kể T, N, M, ECOG trên 2 |\n\n{{BHNgTH tr.370}}\n\n- **ECOG**: 0 hoạt động đầy đủ; 1 vài triệu chứng, đi lại bình thường; 2 tự chăm sóc, nằm giường dưới 50% thời gian; 3 tự chăm sóc hạn chế, nằm giường trên 50%; 4 hoàn toàn nằm giường; 5 tử vong {{BHNgTH tr.370}}\n- Bảng phân giai đoạn của AASLD 2022 (theo BCLC) ghi thêm: tiêu chuẩn BCLC 0 là u đơn độc ≤ 2 cm, PS 0; BCLC A là u đơn độc hoặc ≤ 3 u và ≤ 3 cm; BCLC D gồm chức năng gan giai đoạn cuối, PS 3–4 {{BHNgTH tr.380}}\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Tiêu chuẩn chẩn đoán xác định\n> - U gan trên nền viêm gan/xơ gan, **hình ảnh CLVT/CHT điển hình** (bắt thuốc thì động mạch VÀ thải thuốc thì tĩnh mạch/muộn): chẩn đoán HCC không cần sinh thiết {{BHNgTH tr.364}}\n> - Hướng dẫn Bộ Y tế 2020: hình ảnh điển hình + AFP ≥ 400 ng/mL, hoặc AFP tăng nhưng dưới 400 kèm HBV/HCV (+): HCC. Hình ảnh không điển hình (hoặc điển hình mà AFP không tăng): sinh thiết; sinh thiết âm thì sinh thiết lại, vẫn âm thì theo dõi mỗi 2 tháng {{BHNgTH tr.381}}\n> - Sơ đồ AASLD 2022: u dưới 1 cm siêu âm lại sau 3 tháng; u trên 1 cm làm CLVT 4 thì hoặc CHT động học; hình ảnh không điển hình thì làm phương tiện hình ảnh khác hoặc sinh thiết {{BHNgTH tr.368}}\n\n- **LI-RADS** (AASLD 2023) từ LR-1 (lành tính) đến LR-5 (xác định HCC, khoảng 95%); LR-3 khoảng 20–40%, LR-4 khoảng 60–70%, LR-M khả năng ác tính không đặc hiệu HCC khoảng 35%, LR-TIV là khối u trong TM {{BHNgTH tr.368}} {{BHNgTH tr.369}}\n- Tầm soát nhóm nguy cơ: siêu âm kèm chất chỉ dấu mỗi 3–6 tháng {{BHNgTH tr.363}}\n\n### Chẩn đoán phân biệt khối u gan\n| Bệnh | Điểm phân biệt | Nguồn |\n|---|---|---|\n| **U mạch máu gan** | Ngấm thuốc dần từ ngoại vi vào trung tâm, gần như lấp đầy thì mao mạch; tăng sáng ở T2 trên CHT | {{BHNgTH tr.365}} |\n| **Tăng sản dạng nốt (FNH)** | Lành tính hay gặp thứ hai (khoảng 1%), nữ/nam 9/1, tuổi 30–40; tăng bắt thuốc thì động mạch, đồng đậm độ thì tĩnh mạch, sẹo trung tâm | {{BHNgTH tr.365}} {{BHNgTH tr.366}} |\n| **U tuyến gan** | Liên quan thuốc ngừa thai uống, có thể lớn nhanh, xuất huyết, hoại tử, ác tính hóa; thường chẩn đoán bằng sinh thiết; cắt bỏ khi lớn hơn 5 cm | {{BHNgTH tr.366}} |\n| **Ung thư tế bào ống mật trong gan** | Ung thư nguyên phát thường gặp thứ hai; thường không bắt thuốc; co rút vỏ bao Glisson, dãn đường mật ngoại vi, CA19.9 tăng | {{BHNgTH tr.366}} |\n| **Ung thư gan thứ phát** | Thường từ tuyến và ống tiêu hóa qua TM cửa; đa ổ, bắt thuốc kém, tăng quang viền; tiền sử ung thư tiêu hóa, CEA, CA19.9, CA125 | {{BHNgTH tr.367}} |\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n- Chia hai nhóm theo hiệu quả: **triệt căn** (cắt gan, ghép gan, hủy u tại chỗ) và **giảm bệnh, kéo dài sống** (TACE, HAIC, SIRT, thuốc toàn thân) {{BHNgTH tr.371}}\n- Chọn phương pháp theo tiến triển ung thư, chức năng gan và thể trạng {{BHNgTH tr.371}}\n\n### 7.2 Các phương pháp\n\n@@tabs\n@@tab Cắt gan\n- Triệt căn, **phổ biến nhất** ở Việt Nam và thế giới; cắt phần gan mang u, đủ điều kiện khi u còn cắt được và phần gan để lại đủ thể tích và chức năng {{BHNgTH tr.371}}\n- Mức độ cắt lớn hay nhỏ tùy vị trí, kích thước u và chức năng gan còn lại {{BHNgTH tr.371}}\n- Sống thêm 5 năm khoảng 50–70%; tái phát khoảng 50–75% trong thời gian này (do u ban đầu phát hiện muộn hoặc do nền gan viêm mạn, xơ hóa) {{BHNgTH tr.371}}\n- Các bước mấu chốt (Notion): di động gan, hạn chế máu vào gan, hạn chế máu ra khỏi gan, xác định diện cắt nhu mô theo giải phẫu (nơi không có mạch máu lớn) {{Notion}}\n- Cắt gan theo giải phẫu kiểu ngoài bao Glisson (Takasaki) ít ngại biến thể giải phẫu; kiểu trong bao (Lortat-Jacob) cần xác định biến thể trước và trong mổ, thường dùng khi lấy gan người cho sống {{Notion}}\n@@tab Ghép gan\n- Cắt toàn bộ gan mang ung thư rồi thay bằng gan từ người chết não hoặc một phần gan từ người sống; vừa lấy u vừa thay nhu mô gan bệnh nên rất triệt căn {{BHNgTH tr.372}}\n- Người bình thường chỉ cần khoảng 30–40% gan và gan tái sinh nhanh nên ghép bán phần từ người sống khả thi {{BHNgTH tr.373}}\n- Dành cho xơ gan nặng mà ung thư chưa quá muộn; phải dùng thuốc ức chế miễn dịch suốt đời {{BHNgTH tr.373}}\n- Đạt tiêu chuẩn Milan: sống 5 năm khoảng 65–78%, tái phát khoảng 15% {{BHNgTH tr.373}}\n\n| Tiêu chuẩn chọn ghép gan | Milan | UCSF |\n|---|---|---|\n| U đơn độc | nhỏ hơn 5 cm | nhỏ hơn 6,5 cm |\n| Nhiều u | ít hơn 3 u, mỗi u nhỏ hơn 3 cm | tối đa 3 u, u lớn nhất nhỏ hơn 4,5 cm, tổng đường kính nhỏ hơn 8 cm |\n| Xâm lấn mạch máu | chưa có | chưa có |\n\n{{BHNgTH tr.373}}\n@@tab Hủy u tại chỗ\n- Triệt căn cho người có ít hơn 3 u và mỗi u ≤ 3 cm: tiêm cồn tuyệt đối (PEI), sóng cao tần (RFA), vi sóng (MWA) {{BHNgTH tr.373}}\n- Ít xâm hại, ít ảnh hưởng chức năng gan; thời gian sống thêm tương đương phẫu thuật theo nhiều nghiên cứu {{BHNgTH tr.373}}\n- {r|Hạn chế}: u sát bao Glisson (tái phát tại chỗ, gieo rắc khi chọc kim); u gần mạch máu lớn (hiện tượng tải nhiệt); u gần cuống gan hoặc tạng lân cận (hẹp đường mật, thủng tạng rỗng) {{BHNgTH tr.374}}\n@@tab Điều trị tại chỗ, không triệt căn\n- **TACE** (bơm hóa chất và làm tắc ĐM nuôi u): lựa chọn đầu tiên khi không làm được phương pháp triệt căn, chưa di căn ngoài gan hay xâm lấn mạch; Child-Pugh A hoặc B và bilirubin toàn phần dưới 3 mg%; sống 2 năm khoảng 20–60%, trung bình khoảng 20 tháng (AASLD 2010) {{BHNgTH tr.375}}\n- **HAIC** (bơm hóa chất liên tục qua ĐM gan, phác đồ FP liều thấp): chủ yếu cho HCC tiến xa có xâm lấn TM cửa {{BHNgTH tr.375}}\n- **SIRT** (vi cầu phóng xạ Yttrium-90 qua ĐM nuôi u): chỉ định khi không phẫu thuật được, ECOG 1, Child-Pugh A–B, shunt lên phổi dưới 20% trên xạ hình Tc-99m MAA, chưa từng xạ trị gan; {r|chống chỉ định} khi shunt gan-phổi lớn trên 20%, xơ gan mất bù, bệnh não gan, sống thêm dự kiến dưới 3 tháng {{BHNgTH tr.375}} {{BHNgTH tr.376}}\n@@tab Toàn thân\n- Chỉ định cho BCLC C, không còn chỉ định triệt căn hay TACE {{BHNgTH tr.376}}\n- **Sorafenib** 400 mg uống 2 lần/ngày: thuốc đầu tay khi có xâm nhập mạch hay di căn ngoài gan mà chức năng gan còn tốt (Child-Pugh A hoặc B7); dùng đến khi bệnh tiến triển; tác dụng phụ: phản ứng da bàn tay-bàn chân, tiêu chảy, tăng huyết áp {{BHNgTH tr.376}}\n- **Regorafenib** 160 mg/ngày, ngày 1–21, chu kỳ 28 ngày: bước hai sau sorafenib {{BHNgTH tr.376}}\n- **Pembrolizumab** 200 mg truyền tĩnh mạch mỗi 3 tuần: bước hai sau sorafenib; tác dụng phụ mệt, ngứa, phát ban {{BHNgTH tr.376}} {{BHNgTH tr.377}}\n@@end\n\n### 7.3 Chỉ định – hướng xử trí\n\n> [!doc] Hướng dẫn Bộ Y tế 2020 (theo sơ đồ trong BHNgTH tr.381)\n> - **U cắt được, không di căn**: bất kể kích thước, ECOG PS 0–1, Child A/B (đến B7): **cắt gan**; kể cả có huyết khối TM cửa cùng bên với u hoặc di căn ngoài gan lấy được thì xem xét cắt gan\n> - **U cắt được, nhỏ (≤ 3 u, ≤ 3 cm hoặc 1 u ≤ 5 cm), PS 0–2**: Child A/B dễ tiếp cận, có bệnh đi kèm nguy cơ cao khi mổ: **RFA/MWA**; hoặc TACE, DEB-TACE, SIRT; Child C: **ghép gan**\n> - **U không cắt được, không di căn**: nhỏ (≤ 3 u, ≤ 3 cm hoặc 1 u ≤ 5 cm) Child C thì ghép gan; nhiều u rải rác trong gan, PS 0–2, Child A/B thì TACE, DEB-TACE, SIRT\n> - **Huyết khối TM cửa, di căn ngoài gan**: PS 1–2, Child A/B: sorafenib, lenvatinib, sau đó regorafenib, cabozantinib, nivolumab, pembrolizumab; PS trên 2 hoặc Child C: điều trị giảm nhẹ {{BHNgTH tr.381}}\n\n@@tabs\n@@tab Theo BCLC (AASLD 2022)\n| Giai đoạn | Đặc điểm | Điều trị đầu tay |\n|---|---|---|\n| 0 (rất sớm) | U đơn độc ≤ 2 cm | Hủy u (hoặc cắt gan) |\n| A (sớm) | U đơn độc, hoặc ≤ 3 u và ≤ 3 cm | Cắt gan, hủy u, ghép gan: phụ thuộc áp lực TM cửa, bilirubin, chỉ định ghép |\n| B (trung gian) | U đa ổ | TACE khi u xác định rõ, dòng TM cửa bảo tồn; hoặc ghép gan nếu thỏa tiêu chuẩn mở rộng |\n| C (tiến xa) | Xâm lấn TM cửa và/hoặc di căn ngoài gan | Liệu pháp toàn thân |\n| D (cuối) | Chức năng gan giai đoạn cuối, PS 3–4 | Chăm sóc giảm nhẹ |\n\n{{BHNgTH tr.380}}\n@@tab Theo APASL 2017 (châu Á)\n- Không di căn ngoài gan, có thể cắt, Child A/B: u đơn độc hoặc ≤ 3 u ≤ 3 cm cắt gan hoặc hủy u; xâm lấn mạch đại thể hoặc nhiều u thì TACE hoặc liệu pháp toàn thân\n- Child C: ghép gan hoặc điều trị nâng đỡ\n- Có di căn ngoài gan: liệu pháp toàn thân (Child A/B) hoặc điều trị nâng đỡ (Child C)\n- Giáo trình nhận xét phác đồ APASL phù hợp nhất với Việt Nam; hướng dẫn Bộ Y tế 2020 xây dựng trên nền phác đồ châu Á {{BHNgTH tr.377}} {{BHNgTH tr.378}}\n@@end\n\n> [!warn] Lưu ý điều trị\n> - Cắt gan: cần u đơn độc, Child-Pugh A, thể tích gan còn lại đủ {{BHNgTH tr.371}}\n> - Child-Pugh C: không cắt gan; nếu thỏa tiêu chuẩn thì ghép gan, còn lại điều trị nâng đỡ {{BHNgTH tr.378}}\n> - Hủy u tại chỗ không dùng cho u sát bao Glisson, mạch lớn, cuống gan {{BHNgTH tr.374}}\n\n### Biến chứng và tai biến của điều trị\n- **Sau cắt gan** (Notion): di động gan và phẫu tích cuống gan làm mất dẫn lưu bạch huyết nông và sâu của gan nên sau mổ có báng bụng; nếu không điều trị hợp lý dẫn đến suy thận, nhiễm trùng, và ảnh hưởng chức năng phần gan còn lại vốn đã xơ gan, tăng áp cửa {{Notion}}\n- Các nhánh nhỏ từ hạ phân thùy IV hoặc I đổ vào cuống gan phải tìm và khâu cột kỹ để tránh rò mật và hẹp đường mật sau mổ {{Notion}}\n- Tái phát sau cắt gan: khoảng 50–75% {{BHNgTH tr.371}}\n- **Sau ghép gan**: phẫu thuật phức tạp, nhiều nguy cơ tai biến; dùng thuốc ức chế miễn dịch suốt đời {{BHNgTH tr.373}}\n- **Hủy u tại chỗ**: gieo rắc tế bào u theo đường kim, hẹp đường mật, thủng tạng rỗng {{BHNgTH tr.374}}\n- **TACE**: hội chứng sau thuyên tắc (đau hạ sườn phải hoặc thượng vị, nôn, sốt); hiếm gặp nhưng nặng: suy gan, viêm túi mật cấp, áp-xe vô trùng khối u; nằm viện khoảng 2 ngày {{BHNgTH tr.375}}\n- **HAIC**: viêm tắc mạch, loét dạ dày ruột do rò thuốc, nhiễm khuẩn hoặc tắc dây truyền {{BHNgTH tr.375}}\n- **Sorafenib**: phản ứng da bàn tay-bàn chân, tiêu chảy, tăng huyết áp; giảm liều khi có tác dụng phụ {{BHNgTH tr.376}}\n- Tỷ lệ tử vong, biến chứng chu phẫu cụ thể của cắt gan do HCC: giáo trình không nêu\n\n## 8. Tiên lượng – Dự phòng / theo dõi\n\n### Tiên lượng\n- Tiên lượng xấu vì phát hiện muộn và nền xơ gan {{BHNgTH tr.359}}\n- Sống 5 năm sau cắt gan 50–70%; sau ghép gan (đạt Milan) 65–78% {{BHNgTH tr.371}} {{BHNgTH tr.373}}\n- Sống thêm trung bình theo bảng AASLD 2022: TACE (BCLC B) trên 2,5 năm; toàn thân (BCLC C) trên 2 năm; giảm nhẹ (BCLC D) 3 tháng {{BHNgTH tr.380}}\n- AFP càng cao tiên lượng càng xấu {{BHNgTH tr.363}}\n\n### Theo dõi sau điều trị\n- AFP tăng dần sau điều trị: dự báo tái phát, cần tầm soát tái phát và di căn kỹ {{BHNgTH tr.363}}\n- Sau TACE theo dõi mỗi 1–2 tháng, TACE bổ sung nếu u chưa khống chế hoàn toàn {{BHNgTH tr.375}}\n- Khối u nghi ngờ mà sinh thiết âm: theo dõi mỗi 2 tháng (hướng dẫn Bộ Y tế 2020) {{BHNgTH tr.381}}\n- Sau điều trị cần theo dõi định kỳ và tiếp tục điều trị nếu tái phát {{BHNgTH tr.379}}\n\n### Dự phòng và tầm soát\n- Chủng ngừa viêm gan B từ sơ sinh, người lớn chưa chủng hoặc chủng chưa hiệu quả thì chủng; tầm soát viêm gan B, C khi khám định kỳ; điều trị sớm viêm gan B, C {{BHNgTH tr.378}} {{BHNgTH tr.379}}\n\n| Nhóm | Đối tượng | Tầm soát |\n|---|---|---|\n| Nguy cơ rất cao | Xơ gan do HBV hoặc HCV mạn | Mỗi 3 tháng siêu âm + chất chỉ dấu; mỗi 6 tháng CLVT hoặc CHT |\n| Nguy cơ cao | Viêm gan B, C mạn; xơ gan nguyên nhân khác | Mỗi 6 tháng siêu âm + chất chỉ dấu; có bất thường thì CLVT hoặc CHT |\n\n{{BHNgTH tr.379}}\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] HCC thi nhấn mạnh gì\n> - **Nhận diện**: bệnh nhân xơ gan hoặc viêm gan B, C mạn, ít triệu chứng; AFP tăng, u gan trên siêu âm {{BHNgTH tr.362}} {{BHNgTH tr.363}}\n> - **Chẩn đoán**: CLVT/CHT 4 thì thấy bắt thuốc thì động mạch rồi thải thuốc thì tĩnh mạch là đủ, không cần sinh thiết {{BHNgTH tr.364}}\n> - **Điều trị**: chọn theo u, Child-Pugh, ECOG; cắt gan khi Child A, u đơn độc, gan còn lại đủ; ghép theo Milan; hủy u khi ≤ 3 u ≤ 3 cm {{BHNgTH tr.371}} {{BHNgTH tr.373}}\n\n@@tabs\n@@tab Nhận diện\n- Nguy cơ: viêm gan B (khoảng 60%), C (khoảng 20%), rượu, aflatoxin, NAFLD {{BHNgTH tr.360}}\n- Sớm: gần như không triệu chứng; muộn: xơ gan mất bù, gan to cứng, khối u hạ sườn phải {{BHNgTH tr.362}}\n- Xem [mục 4](#/n/ngoai-ung-thu-gan-hcc/4)\n@@tab Chẩn đoán\n- Hình ảnh điển hình (bắt thuốc thì động mạch, thải thuốc thì tĩnh mạch/muộn): xác định, không sinh thiết {{BHNgTH tr.364}}\n- AFP 400 ng/mL (Bộ Y tế 2020) kèm hình ảnh điển hình {{BHNgTH tr.363}}\n- Child-Pugh A 5–6, B 7–9, C 10–15; ECOG; BCLC {{BHNgTH tr.18}} {{BHNgTH tr.370}}\n- Xem [mục 5](#/n/ngoai-ung-thu-gan-hcc/5) và [mục 6](#/n/ngoai-ung-thu-gan-hcc/6)\n@@tab Điều trị\n- Cắt gan: u đơn độc, Child A, gan còn lại trên 30–40% {{BHNgTH tr.371}}\n- Ghép gan: Milan (u đơn độc < 5 cm; < 3 u mỗi u < 3 cm; chưa xâm lấn mạch) {{BHNgTH tr.373}}\n- Hủy u: ≤ 3 u, mỗi u ≤ 3 cm; không dùng cho u sát bao Glisson, mạch lớn, cuống gan {{BHNgTH tr.373}} {{BHNgTH tr.374}}\n- TACE: Child A/B, bilirubin < 3 mg%, chưa di căn hay xâm lấn mạch {{BHNgTH tr.375}}\n- Sorafenib 400 mg x 2/ngày cho BCLC C, Child A hoặc B7 {{BHNgTH tr.376}}\n- Xem [mục 7.3](#/n/ngoai-ung-thu-gan-hcc/7)\n@@tab Tiên lượng – Dự phòng\n- Sống 5 năm: cắt gan 50–70%, ghép (Milan) 65–78% {{BHNgTH tr.371}} {{BHNgTH tr.373}}\n- Tái phát sau cắt gan 50–75% {{BHNgTH tr.371}}\n- Tầm soát: xơ gan HBV/HCV mỗi 3 tháng; nhóm nguy cơ cao mỗi 6 tháng {{BHNgTH tr.379}}\n- Xem [mục 8](#/n/ngoai-ung-thu-gan-hcc/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Tỷ lệ liên quan viêm gan B / C | ==khoảng 60% / 20%== | {{BHNgTH tr.360}} |\n| Nguy cơ HCC: HBV / anti-HCV | ==15–20 lần / 17 lần== | {{BHNgTH tr.360}} |\n| Ngưỡng AFP chẩn đoán (Bộ Y tế 2020) | ==400 ng/mL== kèm hình ảnh điển hình | {{BHNgTH tr.363}} |\n| Siêu âm tầm soát | ==mỗi 3–6 tháng==; độ nhạy 65–80% | {{BHNgTH tr.363}} |\n| Child-Pugh A / B / C | ==5–6 / 7–9 / 10–15 điểm== | {{BHNgTH tr.18}} |\n| Tử vong mổ bụng ở xơ gan A / B / C | ==10% / 20% / 60%== | {{BHNgTH tr.18}} |\n| Thể tích gan còn lại tối thiểu: không xơ / xơ gan | ==20% / 40%== | {{BHNgTH tr.18}} |\n| Điều kiện cắt gan trong chương HCC | ==u đơn độc, Child A, gan còn lại trên 30–40%== | {{BHNgTH tr.371}} |\n| Sống 5 năm sau cắt gan; tái phát | ==50–70%; 50–75%== | {{BHNgTH tr.371}} |\n| Milan: u đơn độc; nhiều u | ==< 5 cm; < 3 u, mỗi u < 3 cm== | {{BHNgTH tr.373}} |\n| UCSF: u đơn độc; nhiều u | ==< 6,5 cm; ≤ 3 u, lớn nhất < 4,5 cm, tổng < 8 cm== | {{BHNgTH tr.373}} |\n| Ghép gan đạt Milan: sống 5 năm; tái phát | ==65–78%; khoảng 15%== | {{BHNgTH tr.373}} |\n| Hủy u tại chỗ | ==≤ 3 u, mỗi u ≤ 3 cm== | {{BHNgTH tr.373}} |\n| TACE: bilirubin; sống 2 năm | ==< 3 mg%; 20–60%== | {{BHNgTH tr.375}} |\n| Sorafenib | ==400 mg x 2/ngày==, Child A hoặc B7 | {{BHNgTH tr.376}} |\n\n> [!warn] Bẫy thi thường gặp\n> - **Không cần sinh thiết** khi hình ảnh điển hình trên nền xơ gan; sinh thiết chỉ khi không điển hình và u lớn hơn 1–2 cm {{BHNgTH tr.364}}\n> - **AFP không dùng để chẩn đoán u nhỏ giai đoạn sớm**; AFP còn tăng trong viêm gan mạn, ung thư tinh hoàn, ung thư ống mật {{BHNgTH tr.362}} {{BHNgTH tr.363}}\n> - **Ghép gan không phải triệt căn cho mọi bệnh nhân**: chỉ khi thỏa tiêu chuẩn chọn bệnh (Milan, UCSF) {{BHNgTH tr.373}} {{BHNgTH tr.384}}\n> - **TACE không triệt căn**: chỉ giảm bệnh, kéo dài sống {{BHNgTH tr.371}} {{BHNgTH tr.384}}\n> - **Điều trị triệt căn gồm cắt gan, ghép gan, hủy u tại chỗ**, không gồm hóa trị toàn thân hay xạ trị {{BHNgTH tr.371}} {{BHNgTH tr.383}}\n> - **Giai đoạn HCC dựa trên u, chức năng gan, thể trạng**, không chỉ TNM {{BHNgTH tr.370}} {{BHNgTH tr.383}}\n> - Giáo trình ghi tỷ lệ viêm gan B là khoảng 60% ở mục dịch tễ nhưng 70% ở mục phòng ngừa {{BHNgTH tr.360}} {{BHNgTH tr.378}}\n> - Phân độ Child-Pugh: TCBN có điểm cắt khác BHNgTH 2025 (xem mục 5), theo BHNgTH 2025 {{TCBN tr.31}} {{BHNgTH tr.18}}\n\n@@fold Nguồn tài liệu\n- **BHNgTH** Giáo trình Bệnh học ngoại khoa tiêu hóa 2025, chương Ung thư biểu mô tế bào gan, tr.359–381 (số trang PDF; sách in tr.350–372); tr.380 (bảng AASLD 2022) và tr.381 (sơ đồ Bộ Y tế 2020) là hình, đọc từ ảnh trang; tr.370 (sơ đồ BCLC) đọc từ ảnh trang; tr.368–369 (sơ đồ chẩn đoán, LI-RADS) từ chữ trích\n- **BHNgTH** tr.18: bảng Child-Turcotte-Pugh và thể tích gan còn lại (chương đánh giá bệnh nhân trước mổ); tr.383–384: câu hỏi lượng giá cuối chương\n- **TCBN** Tiếp cận bệnh nhân ngoại khoa Y3 tr.31: bảng Child-Pugh (trong bài u gan vỡ)\n@@end\n\n@@fold Nguồn ngoài\n- **Từ Notion (giáo trình cũ hơn, có thể lệch bản mới)**: giải phẫu gan phân thùy theo phẫu thuật (trang \"[GP] Gan - Mật & Hệ tĩnh mạch cửa\"); các bước mấu chốt khi cắt gan, tiếp cận trong/ngoài bao Glisson, báng bụng sau cắt gan, nhánh nhỏ hạ phân thùy IV, I (trang \"[GP] Gan - Mật - Tụy ứng dụng cho phẫu thuật\")\n- **Không có nguồn trong giáo trình lẫn Notion**: các kiểu cắt gan cụ thể (cắt gan phải, trái, cắt phân thùy) và chỉ định từng kiểu; tỷ lệ tử vong, biến chứng chu phẫu cắt gan do HCC; chống chỉ định cắt gan ngoài Child-Pugh và thể tích gan; hóa trị, xạ trị ngoài ra\n- Không dùng nguồn ngoài nào khác trong bài này\n@@end\n\n@@fold! Tự kiểm tra (12 thẻ)\n- Tiêu chuẩn hình ảnh điển hình của HCC trên CLVT/CHT? :: Tăng bắt thuốc thì động mạch và thải thuốc thì tĩnh mạch hoặc thì muộn; đủ để chẩn đoán xác định, không cần sinh thiết\n- Ngưỡng AFP theo Bộ Y tế 2020 để chẩn đoán HCC? :: 400 ng/mL, khi kết hợp hình ảnh CLVT/CHT điển hình\n- Tầm soát HCC nhóm xơ gan do HBV, HCV làm thế nào? :: Siêu âm và chất chỉ dấu mỗi 3 tháng, CLVT hoặc CHT mỗi 6 tháng\n- Phân độ Child-Pugh A, B, C theo điểm? :: A 5–6, B 7–9, C 10–15\n- Năm tiêu chí của bảng Child-Pugh? :: Bệnh não gan, báng bụng, bilirubin, albumin, PT hoặc INR\n- Thể tích gan còn lại tối thiểu sau cắt gan? :: Không xơ gan trên 20%; xơ gan tối thiểu 40% (chương HCC ghi 30–40%)\n- Gan chia theo phẫu thuật thế nào? :: 2 nửa (phải, trái), mỗi nửa 2 phân thùy, mỗi phân thùy 2 hạ phân thùy (I–VIII; I là thùy đuôi)\n- Điều kiện chỉ định cắt gan điều trị HCC? :: Khối u cắt được, thường u đơn độc, xơ gan Child-Pugh A, thể tích gan để lại hơn 30–40%\n- Tiêu chuẩn Milan? :: U đơn độc nhỏ hơn 5 cm, hoặc ít hơn 3 u mỗi u nhỏ hơn 3 cm, chưa xâm lấn mạch máu\n- Hủy u tại chỗ chỉ định và chống chỉ định? :: Ít hơn 3 u, mỗi u ≤ 3 cm (RFA, MWA, tiêm cồn); u sát bao Glisson, gần mạch lớn, gần cuống gan hoặc tạng lân cận thì hạn chế\n- TACE chỉ định cho ai? :: Không điều trị triệt căn được, chưa di căn ngoài gan hay xâm lấn mạch; Child-Pugh A hoặc B, bilirubin toàn phần dưới 3 mg%\n- Thuốc đầu tay cho HCC tiến triển (BCLC C) và liều? :: Sorafenib 400 mg uống 2 lần/ngày; Child-Pugh A hoặc B7\n@@end"}, {"kind": "disease", "disease": "ung-thu-quanh-bong-vater", "short": "Ung thư quanh bóng Vater", "group": "", "section": 0, "order": 24, "khung": [], "id": "ngoai-ung-thu-quanh-bong-vater", "title": "Ung thư quanh bóng Vater (ngoại khoa)", "layer": "benh", "module": "ngoai-tong-quat", "tags": ["ngoại khoa", "tiêu hóa", "gan mật tụy", "bóng Vater", "đầu tụy", "vàng da tắc mật", "CA 19-9", "EUS", "TNM AJCC 8", "cắt khối tá tụy", "Whipple", "dẫn lưu mật", "rò tụy", "nối tắt"], "source": "BHNgTH tr.335–355 (chương Ung thư quanh bóng Vater), tr.356–358 (câu hỏi lượng giá); Notion ([BHNgK] Ung thư quanh bóng Vater)", "body": "> [!key] Ung thư quanh bóng Vater trong một nhìn\n> - Là nhóm bốn ung thư biểu mô tuyến trong bán kính 2 cm quanh nhú tá lớn: **đầu tụy, bóng Vater, đoạn cuối ống mật chủ, tá tràng** {{BHNgTH tr.335}}\n> - Biểu hiện nổi bật là **vàng da tắc mật** (khoảng 75%) kèm sụt cân, đau bụng lan ra lưng {{BHNgTH tr.336}} {{BHNgTH tr.337}}\n> - Tại Việt Nam thường đến muộn nên tỉ lệ cắt được chỉ quanh 20% {{BHNgTH tr.335}}\n> - ==Phẫu thuật cắt khối tá tụy (Whipple) là phương pháp triệt căn duy nhất==; biến chứng sau mổ 30–50%, tử vong khoảng 1% {{BHNgTH tr.348}} {{BHNgTH tr.351}}\n> - Tiên lượng theo vị trí: tá tràng tốt nhất, bóng Vater thứ hai, đầu tụy xấu nhất {{BHNgTH tr.353}}\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Bốn loại ung thư gộp chung vì lâm sàng, chẩn đoán và điều trị giống nhau, nhưng tần suất, khả năng cắt được và tiên lượng khác nhau {{BHNgTH tr.335}}\n> - Đầu tụy là loại gặp nhiều nhất và xấu nhất; tá tràng và bóng Vater tiên lượng tốt hơn {{BHNgTH tr.353}} {{Notion}}\n\n### Định nghĩa và dịch tễ\n- Halsted (1898): vùng quanh bóng Vater giới hạn trong bán kính ==2 cm quanh nhú tá lớn==; ông cũng là người đầu tiên mổ cắt u vùng này {{BHNgTH tr.335}}\n- Ung thư quanh bóng Vater = tập hợp bốn tổn thương ác tính: ung thư biểu mô tuyến của đầu tụy, bóng Vater, đoạn cuối ống mật chủ và tá tràng {{BHNgTH tr.335}}\n- Là nguyên nhân tử vong do ung thư xếp hàng thứ 4 trên thế giới, sau phổi, đại tràng, vú {{BHNgTH tr.335}}\n- Việt Nam: ít được phát hiện sớm, người bệnh đến với vàng da, sụt cân, suy mòn; tỉ lệ cắt được khối tá tụy quanh ==20%==, ung thư bóng Vater chiếm đa số trong số cắt được {{BHNgTH tr.335}}\n- Giáo trình giờ nhấn mạnh phối hợp chẩn đoán hình ảnh, hồi sức, ngoại khoa và điều trị đa mô thức, giúp giảm biến chứng, tử vong và tăng tỉ lệ cắt được ở ung thư giáp biên {{BHNgTH tr.335}}\n- Tần suất bốn loại (giáo trình cũ): đầu tụy 40–60%, bóng Vater 10–20%, đoạn cuối ống mật chủ 10%, tá tràng 5–10%; mắc tăng theo tuổi, đa số từ 60 tuổi, nam nhiều hơn nữ {{Notion}}\n\n### Giải phẫu ứng dụng\n- Vùng quanh bóng Vater gồm bốn cấu trúc nguồn gốc u: **đầu tụy, bóng Vater, đoạn cuối ống mật chủ (OMC), tá tràng (D2)**; nên khối u lớn xâm lấn xung quanh thường khó xác định gốc ban đầu, cần hóa mô miễn dịch {{BHNgTH tr.335}} {{BHNgTH tr.341}}\n- Hệ quả giải phẫu của u ở đây: chèn ống mật chủ gây ==tắc mật== (dãn đường mật trong gan, OMC); chèn ống tụy gây dãn ống tụy; u tá tràng gây hẹp, dãn tá tràng và dạ dày {{BHNgTH tr.338}} {{BHNgTH tr.339}}\n- ==Dấu ống đôi== (double duct): dãn đồng thời OMC và ống tụy, hay gặp trong ung thư bóng Vater, kể cả khi u còn nhỏ {{BHNgTH tr.339}}\n- Tụy nằm sau phúc mạc, mạng mạch máu nuôi khối tá tụy phong phú và có biến thể động mạch gan: nền tảng của độ khó phẫu thuật {{BHNgTH tr.349}}\n- Mạch máu quyết định khả năng cắt: động mạch thân tạng, động mạch mạc treo tràng trên (ĐMMTTT), động mạch gan chung; tĩnh mạch mạc treo tràng trên (TMMTTT), tĩnh mạch cửa {{BHNgTH tr.339}} {{BHNgTH tr.340}} {{BHNgTH tr.346}}\n- **Hạch vùng** (N): dọc ống mật chủ, động mạch gan chung, tĩnh mạch cửa, quanh môn vị, mặt trước và sau khối tá tụy, dọc TMMTTT và bờ phải ĐMMTTT; hạch ngoài các nhóm này tính là di căn xa {{BHNgTH tr.341}}\n- Đường tiêu hóa sau cắt khối tá tụy được tái lập bằng ba miệng nối: tụy – hỗng tràng, ống gan chung – hỗng tràng, dạ dày – hỗng tràng {{BHNgTH tr.350}}\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Ung thư đầu tụy\n- **Di truyền**: hội chứng ung thư đại-trực tràng di truyền không đa polyp, ung thư vú mang đột biến BRCA2; đột biến gen liên quan khoảng 20% ca ung thư tụy có tính di truyền {{BHNgTH tr.336}}\n- **Hút thuốc lá**: tăng nguy cơ theo số lượng và thời gian hút; cùng với di truyền chiếm khoảng 5–10% {{BHNgTH tr.336}}\n- **Béo phì**: nguy cơ tăng đến gấp ba lần {{BHNgTH tr.336}}\n- **Đái tháo đường**: tăng ở người mới khởi phát đái tháo đường, nhất là người lớn tuổi sụt cân kèm theo; đái tháo đường lâu năm cũng gợi ý tăng nguy cơ {{BHNgTH tr.336}}\n- **Viêm tụy mạn** {{BHNgTH tr.336}}\n@@tab Bóng Vater và tá tràng\n- Gặp nhiều hơn ở người có hội chứng đa polyp di truyền: ung thư đại-trực tràng di truyền không đa polyp, Peutz – Jeghers, đa polyp tuyến gia đình, hội chứng Gardner {{BHNgTH tr.336}}\n@@tab Đoạn cuối OMC\n- Liên quan: hội chứng ruột kích thích, viêm xơ hóa đường mật, nang ống mật chủ, sỏi mật {{BHNgTH tr.336}}\n@@end\n\n### Mô bệnh học và tiến triển\n- Giáo trình chủ yếu bàn ung thư biểu mô tuyến; ung thư bóng Vater có các dạng ruột, tụy – đường mật, hỗn hợp, tế bào nhẫn hoặc không biệt hóa với tiên lượng khác nhau (xem mục 8) {{BHNgTH tr.354}}\n- Đột biến hay gặp ở ung thư đầu tụy và liên quan tiên lượng xấu: KRAS, CDKN2A/p16, TP53, SMAD4 {{BHNgTH tr.354}}\n- Phân giai đoạn theo AJCC 8 và định nghĩa u giáp biên xem mục 5 và mục 6 {{BHNgTH tr.341}} {{BHNgTH tr.346}}\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Vàng da tắc mật (khoảng 75%) kèm ngứa, tiểu sậm màu, phân bạc màu; sụt cân 51%; đau bụng mơ hồ lan ra lưng {{BHNgTH tr.336}} {{BHNgTH tr.337}}\n> - Khám: kết mạc vàng, vết cào gãi, túi mật to; hạch Virchow, nốt Sister Mary Joseph, Blumer's shelf là dấu di căn {{BHNgTH tr.337}}\n> - Luôn đánh giá dinh dưỡng (PG-SGA) vì ảnh hưởng quyết định mổ {{BHNgTH tr.337}}\n\n### Triệu chứng cơ năng\n- **Vàng da** (khoảng 75%) kèm triệu chứng tắc mật: ngứa, tiểu sậm màu, tiêu phân bạc màu {{BHNgTH tr.336}}\n- **Đau bụng** mơ hồ, nhất là lan ra lưng ngang vị trí tụy; giai đoạn muộn đau liên tục, không đáp ứng paracetamol hay NSAID {{BHNgTH tr.336}}\n- Sụt cân, buồn nôn, nôn, ngứa, sốt, xuất huyết tiêu hóa {{BHNgTH tr.336}}\n\n| Triệu chứng cơ năng | Tần suất (%) |\n|---|---|\n| Vàng da | ==75== |\n| Sụt cân | 51 |\n| Đau bụng | 39 |\n| Nôn / buồn nôn | 13 |\n| Ngứa | 11 |\n| Sốt | 3 |\n| Xuất huyết tiêu hóa | 1 |\n\nNguồn bảng: {{BHNgTH tr.337}}\n\n### Triệu chứng thực thể\n- Hay gặp: **kết mạc mắt vàng**, tổn thương da do cào gãi, **túi mật to sờ thấy** {{BHNgTH tr.337}}\n- Ít gặp (gợi ý di căn): nốt ở gan; **hạch thượng đòn (Virchow)**; **nốt quanh rốn (Sister Mary Joseph)**; di căn hố chậu khi thăm trực tràng (**Blumer's shelf**) {{BHNgTH tr.337}}\n\n### Đánh giá toàn trạng và dinh dưỡng\n- Mức độ sụt cân, tình trạng dinh dưỡng, triệu chứng ảnh hưởng ăn uống (chán ăn, buồn nôn, nôn), tiền căn tim phổi, suy thận, suy giảm miễn dịch; dùng bảng câu hỏi **PG-SGA** {{BHNgTH tr.337}}\n- Dinh dưỡng liên quan giai đoạn bệnh và ảnh hưởng quyết định cắt khối tá tụy {{BHNgTH tr.337}}\n- Tắc mật kéo dài vài tháng luôn kèm suy dinh dưỡng {{BHNgTH tr.337}}\n\n> [!red] Dấu hiệu nặng cần xử trí sớm\n> - Vàng da tắc mật kèm sốt: nguy cơ viêm đường mật cấp, là một chỉ định dẫn lưu mật trước mổ {{BHNgTH tr.346}}\n> - Rối loạn đông máu do tắc mật kéo dài (kém hấp thu vitamin K) {{BHNgTH tr.337}}\n> - Đau liên tục không đáp ứng thuốc giảm đau thông thường: gợi ý giai đoạn muộn {{BHNgTH tr.336}}\n\n## 5. Cận lâm sàng\n\n> [!key] Chỉ định gì khi nào\n> - Xét nghiệm: bilirubin, phosphatase kiềm, đông máu, dinh dưỡng; **CA 19-9** chủ yếu để theo dõi và tiên lượng {{BHNgTH tr.337}} {{BHNgTH tr.338}}\n> - Hình ảnh: **CLVT bụng chậu có cản quang kèm dựng hình** là chủ lực đánh giá giai đoạn và khả năng cắt; EUS và MRCP bổ sung; ERCP hay PTC chủ yếu để giải áp {{BHNgTH tr.340}} {{BHNgTH tr.341}}\n> - Chẩn đoán xác định trước mổ dựa vào giải phẫu bệnh qua sinh thiết nội soi tá tràng hoặc EUS {{BHNgTH tr.341}}\n\n### Xét nghiệm máu\n- Tắc mật: tăng **bilirubin** và **phosphatase kiềm**; men gan thường tăng nhẹ đến trung bình và gần bình thường sau khi giải quyết tắc mật {{BHNgTH tr.337}}\n- Tắc mật lâu: bệnh lý đông máu, kéo dài thời gian đông máu do kém hấp thu vitamin K {{BHNgTH tr.337}}\n- Suy dinh dưỡng: albumin, pre-albumin, ion đồ, công thức máu bất thường {{BHNgTH tr.337}}\n- **CA 19-9** tăng trong 75% ca; độ nhạy 81%, độ đặc hiệu 90%, giá trị tiên đoán dương khoảng 72% ở ngưỡng 37 IU/L; cao hơn CEA về độ nhạy và đặc hiệu {{BHNgTH tr.338}}\n- CA 19-9 trên 100 UI/mL (ung thư tụy): độ nhạy 68%, độ đặc hiệu 98%, giá trị tiên đoán dương 97%, giá trị tiên đoán âm 89% {{BHNgTH tr.338}}\n- CA 19-9 cũng tăng trong bệnh lành tính của tụy, gan, đường mật; vai trò chính là **theo dõi và tiên lượng**: về gần bình thường sau mổ 2 tuần, tăng lại khi tái phát {{BHNgTH tr.338}}\n- Ung thư đầu tụy: (CEA × 85 + CA 19-9) trước mổ lớn hơn 845 có ý nghĩa tiên lượng sống còn sau mổ; ung thư đoạn cuối OMC: CA 19-9 từ 100 U/mL trở lên liên quan khả năng cắt u, giai đoạn và di căn hạch {{BHNgTH tr.338}}\n\n### Chẩn đoán hình ảnh\n@@tabs\n@@tab Siêu âm bụng\n- Độ nhạy chỉ khoảng ==25%== {{BHNgTH tr.338}}\n- Cho biết dãn đường mật, nốt di căn gan, khối u tụy, hạch quanh tụy và rốn gan, dịch báng {{BHNgTH tr.338}}\n@@tab CLVT có cản quang\n- Độ nhạy phát hiện ung thư đầu tụy 90–95% nhờ hình giảm đậm độ ở phase tụy; hình thứ phát: dãn ống tụy và OMC {{BHNgTH tr.338}}\n- Ung thư bóng Vater: khối giảm đậm độ chia thùy hay thâm nhiễm; **dấu ống đôi** {{BHNgTH tr.339}}\n- Ung thư đoạn cuối OMC: dày thành OMC không đều, không đối xứng kèm dãn đường mật trong gan; hoặc khối mô mềm trong lòng; hoặc chít hẹp mất lòng ống {{BHNgTH tr.339}}\n- Ung thư tá tràng: thường muộn; đoạn hẹp ngắn dạng vòng, bờ nhô ra, gây dãn tá tràng và dạ dày {{BHNgTH tr.339}}\n- Hạch được xem là di căn khi có một trong ba: kích thước ≥ 10 mm; hoại tử trung tâm bất kể kích thước; đậm độ HU cao hơn nhu mô gan ở thì tĩnh mạch cửa {{BHNgTH tr.339}}\n- Đánh giá khả năng cắt: di căn gan, xâm lấn mạch máu; giá trị tiên đoán dương cho u **không cắt được** 89–100%, cho u **cắt được** 45–79% {{BHNgTH tr.339}} {{BHNgTH tr.340}}\n- Kỹ thuật (giáo trình cũ): chụp phase tụy 30–40 giây sau tiêm thuốc cản quang, có thể dựng hình mạch máu {{Notion}}\n@@tab MRCP\n- Cho hình cây đường mật, hợp lưu mật – tụy, ống tụy; có tiêm cản từ nhạy hơn CLVT; mạnh ở đánh giá kích thước, hình dạng hẹp đoạn cuối OMC {{BHNgTH tr.340}}\n- Giáo trình cũ: độ nhạy 86% so với 84% của CLVT; phân biệt viêm tụy mạn nhờ ống tụy thông suốt (duct-penetrating sign); không thay được ERCP về tế bào học {{Notion}}\n@@tab ERCP và PTC\n- **ERCP**: hữu ích khi có dấu gián tiếp mà CLVT và MRI không thấy u; ghi nhận hẹp ống tụy, dãn ống tụy hoặc cả OMC; có thể đặt stent giải áp {{BHNgTH tr.340}}\n- **PTC** (chụp đường mật xuyên gan qua da): chỉ định chủ yếu để **dẫn lưu**, ít ý nghĩa chẩn đoán nguyên nhân {{BHNgTH tr.340}}\n@@tab EUS\n- Đánh giá xâm lấn mạch máu, di căn hạch; tin cậy với u dưới 2 cm; **EUS-FNA** lấy mẫu mô bệnh học trước mổ hoặc trước hóa trị tân bổ trợ {{BHNgTH tr.340}}\n- EUS-FNA: độ nhạy 80–95% (ung thư tụy); chính xác giai đoạn T 78–94%, giai đoạn N 64–82% {{BHNgTH tr.340}}\n- Hạn chế: phụ thuộc người thực hiện; nguy cơ chảy máu, thủng tá tràng, viêm tụy (0,1–1%) {{BHNgTH tr.340}}\n@@tab PET-CT\n- Đánh giá di căn: độ nhạy 87–95%, độ đặc hiệu 51–81%; tốt hơn CLVT trong phân giai đoạn và phát hiện di căn xa {{BHNgTH tr.341}}\n@@end\n\n### Mô bệnh học và hóa mô miễn dịch\n- Chẩn đoán xác định trước mổ: giải phẫu bệnh qua **sinh thiết nội soi tá tràng** hoặc **EUS** {{BHNgTH tr.341}}\n- U lớn khó xác định nguồn gốc: hóa mô miễn dịch; **CK17** dương hơn 50% ở ung thư tụy và OMC, dưới 5% ở tá tràng và bóng Vater; **MUC2** và **CDX2** dương nhiều ở ung thư tá tràng (82% và 100%), MUC2 chỉ 2% ở ung thư tụy {{BHNgTH tr.341}}\n\n### Phân giai đoạn TNM (AJCC 8)\n- Hệ thống AJCC/UICC lần 8 (công bố 2016); sau khi có bằng chứng mô học, chụp **CLVT bụng chậu cản quang dựng hình**; **CLVT ngực** để tầm soát di căn phổi; hội tiêu hóa châu Âu khuyến nghị thêm EUS và MRCP {{BHNgTH tr.341}} {{BHNgTH tr.342}}\n- Mỗi loại có tiêu chí T riêng; hạch (N) giống nhau ở tụy, bóng Vater, OMC; tá tràng khác; M giống nhau cho cả bốn {{BHNgTH tr.343}} {{BHNgTH tr.344}}\n\n@@tabs\n@@tab T theo từng loại\n| Loại | T1 | T2 | T3 | T4 |\n|---|---|---|---|---|\n| Đầu tụy | u ≤ 2 cm (T1a ≤ 0,5; T1b 0,5–1; T1c 1–2 cm) | 2 < u ≤ 4 cm | u > 4 cm | xâm lấn động mạch thân tạng, ĐMMTTT, gan chung {{BHNgTH tr.342}} |\n| Bóng Vater | T1a: trong bóng Vater hoặc cơ vòng Oddi; T1b: quá cơ vòng Oddi tới dưới niêm tá tràng | tới lớp cơ niêm tá tràng | T3a: xâm lấn tụy ≤ 0,5 cm; T3b: > 0,5 cm hoặc mô quanh tụy, quanh tá tràng, thanh mạc, chưa xâm lấn mạch | xâm lấn động mạch thân tạng, ĐMMTTT và/hoặc gan chung {{BHNgTH tr.342}} |\n| Đoạn cuối OMC | thành OMC dày < 5 mm | dày 5–12 mm | dày > 12 mm | xâm lấn động mạch thân tạng, ĐMMTTT, gan chung {{BHNgTH tr.343}} |\n| Tá tràng | T1a: lớp niêm; T1b: dưới niêm | lớp cơ | thanh mạc, mạc treo, sau phúc mạc | phá vỡ thanh mạc hoặc xâm lấn cơ quan khác {{BHNgTH tr.343}} |\n@@tab N và M\n| Phân loại | Tụy, bóng Vater, OMC | Tá tràng |\n|---|---|---|\n| N1 | di căn 1–3 hạch | di căn 1–2 hạch |\n| N2 | từ 4 hạch trở lên | từ 3 hạch trở lên |\n| M1 | có di căn xa (chung cho cả bốn loại) | có di căn xa |\n\nNguồn bảng: {{BHNgTH tr.343}} {{BHNgTH tr.344}}\n@@tab Giai đoạn ung thư bóng Vater\n| Giai đoạn | T | N | M |\n|---|---|---|---|\n| 0 | Tis | N0 | M0 |\n| IA | T1a | N0 | M0 |\n| IB | T1b hoặc T2 | N0 | M0 |\n| IIA | T3a | N0 | M0 |\n| IIB | T3b | N0 | M0 |\n| IIIA | T1a, T1b, T2, T3a, T3b | N1 | M0 |\n| IIIB | T4 (N bất kỳ) hoặc T bất kỳ N2 | | M0 |\n| IV | T bất kỳ | N bất kỳ | M1 |\n\nNguồn bảng: {{BHNgTH tr.344}}. Bảng giai đoạn của tụy, OMC và tá tràng: {{BHNgTH tr.344}} {{BHNgTH tr.345}}\n@@end\n\n### Ung thư giáp biên (borderline)\nĐịnh nghĩa dựa CLVT và MRCP, thuộc một trong ba điều kiện {{BHNgTH tr.346}}\n- (a) Giảm trên 50% bán kính tĩnh mạch (tĩnh mạch cửa, hoặc kèm TMMTTT) còn khả năng cắt nối, hoặc tắc một đoạn ngắn mà vẫn cắt nối được\n- (b) Xâm lấn dưới 180 độ chu vi ĐMMTTT\n- (c) Xâm lấn động mạch thân tạng hoặc động mạch gan chung nhưng không làm dãn cấu trúc mạch, không bất thường giải phẫu mạch, không liên quan vị trí chia nhánh\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Nguyên tắc chẩn đoán\n> - Bệnh cảnh gợi ý: vàng da tắc mật tăng dần, sụt cân, đau mơ hồ lan lưng; hình ảnh có u quanh bóng Vater hoặc dãn OMC kèm ống tụy {{BHNgTH tr.336}} {{BHNgTH tr.339}}\n> - Chẩn đoán xác định: giải phẫu bệnh từ sinh thiết qua nội soi tá tràng hoặc EUS {{BHNgTH tr.341}}\n> - Khó khăn chính trước mổ: u còn **cắt được** hay không và thể trạng có cho phép mổ triệt căn không (xem mục 7.3) {{BHNgTH tr.349}} {{Notion}}\n\n### Đánh giá khả năng cắt trước mổ\n| Nhóm | Dấu hiệu trên CLVT/MRCP | Hướng đi |\n|---|---|---|\n| Cắt được | u khu trú, chưa xâm lấn cấu trúc xung quanh, chưa di căn xa {{Notion}} | Cắt khối tá tụy {{BHNgTH tr.348}} |\n| Giáp biên | xâm lấn tĩnh mạch cửa/TMMTTT hoặc động mạch dưới ngưỡng quy định (xem mục 5) {{BHNgTH tr.346}} | Hóa trị tân bổ trợ, rồi đánh giá lại {{BHNgTH tr.348}} |\n| Không cắt được | di căn gan, xâm lấn mạch máu không còn cắt nối được {{BHNgTH tr.352}} | Điều trị giảm nhẹ hoặc nối tắt {{BHNgTH tr.348}} {{BHNgTH tr.352}} |\n\n- Đánh giá khả năng cắt phải dựa nhiều yếu tố: tổng trạng, bệnh đi kèm, hình ảnh học, đánh giá trong mổ; không chỉ dựa CLVT trước mổ {{Notion}}\n\n### Chẩn đoán phân biệt\n| Bệnh lý | Điểm giống | Điểm phân biệt |\n|---|---|---|\n| Sỏi đoạn cuối OMC | vàng da tắc mật, đau thượng vị, dãn OMC | ca lâm sàng của sách (vàng da tăng dần, đôi khi giảm, dãn OMC và ống tụy trên CLVT) cho thấy sỏi, K đoạn cuối OMC, u đầu tụy đều phải nghĩ tới, còn u thân tụy ít nghĩ nhất {{BHNgTH tr.357}} {{BHNgTH tr.358}} |\n| Viêm tụy mạn | hẹp ống tụy, khối vùng đầu tụy, CA 19-9 có thể tăng | MRCP thấy ống tụy thông suốt (giáo trình cũ); u nghi ngờ ác tính vẫn cần giải phẫu bệnh {{Notion}} {{BHNgTH tr.338}} |\n| Hẹp đoạn cuối OMC lành tính (viêm xơ hóa đường mật, nang OMC, sỏi mật) | tắc mật | MRCP đánh giá hình dạng chỗ hẹp gợi ý nguyên nhân {{BHNgTH tr.336}} {{BHNgTH tr.340}} |\n| Tân sinh dạng nang và u thần kinh nội tiết của tụy | khối tụy | CLVT phân biệt theo dạng nang, đậm độ (giáo trình cũ) {{Notion}} |\n\n> [!tip] Tình huống mổ không có giải phẫu bệnh trước mổ\n> Tổn thương rõ trên CLVT/MRCP kèm dãn OMC hoặc ống tụy do u chèn ép vẫn có thể mổ; sinh thiết tức thì trong mổ để quyết định phương pháp {{BHNgTH tr.348}}\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n- **Điều trị triệt căn** cho u cắt được: cắt khối tá tụy kèm nạo hạch, đạt diện cắt R0 {{BHNgTH tr.349}} {{BHNgTH tr.350}} {{Notion}}\n- U giáp biên: điều trị **đa mô thức** (hóa xạ tân bổ trợ, rồi mổ, rồi hóa xạ bổ trợ) {{BHNgTH tr.348}}\n- Giai đoạn tiến xa: điều trị **giảm nhẹ**, cải thiện chất lượng sống chứ không kéo dài sống còn {{BHNgTH tr.348}}\n- Giảm tối đa biến chứng (rò tụy, nhiễm trùng) nhờ chọn bệnh, dẫn lưu mật đúng chỉ định, hỗ trợ dinh dưỡng {{BHNgTH tr.346}} {{BHNgTH tr.347}} {{BHNgTH tr.349}}\n\n### 7.2 Các phương pháp\n\n@@tabs\n@@tab Dẫn lưu mật trước mổ\n- Tắc mật kéo dài gây rối loạn gan, thận, miễn dịch, đông máu, suy dinh dưỡng, nội độc tố, làm tăng nhiễm khuẩn, biến chứng và tử vong sau cắt khối tá tụy {{BHNgTH tr.346}}\n- Hầu hết biểu hiện tắc mật cải thiện sau **10 ngày**; chức năng gan và hàng rào niêm mạc ruột cải thiện sau **4–6 tuần**; dẫn lưu thành công khi bilirubin toàn phần giảm từ 50% trở lên {{BHNgTH tr.346}}\n- **Chỉ định** khi có một trong: bilirubin toàn phần trên ==15 mg/dl==; bilirubin dưới 15 mg/dl kèm suy dinh dưỡng hoặc bệnh nội khoa; viêm đường mật cấp; phải trì hoãn mổ quá hai tuần {{BHNgTH tr.346}}\n- **Cách làm**: dẫn lưu trong qua ERCP (đặt stent) hoặc dẫn lưu ngoài qua PTBD {{BHNgTH tr.346}}\n- Nhược điểm: nhiễm trùng vết mổ, đổi chủng vi khuẩn đường mật, phản ứng viêm quanh stent gây khó bóc tách cuống gan {{BHNgTH tr.346}}\n- Giáo trình cũ: không khuyến cáo dẫn lưu thường quy; sau dẫn lưu bilirubin giảm trung bình 1–2 mg/dL mỗi ngày {{Notion}}\n@@tab Hỗ trợ dinh dưỡng\n- Đánh giá dinh dưỡng trước mổ rất quan trọng vì mổ lớn, nhiều miệng nối {{BHNgTH tr.347}}\n- Căn cứ: khám lâm sàng (sụt cân, BMI, tầm soát nguy cơ dinh dưỡng, NRS) và **prealbumin, albumin** huyết thanh; kết quả quyết định can thiệp dinh dưỡng trước mổ (theo lược đồ trong sách) {{BHNgTH tr.347}}\n@@tab Cắt khối tá tụy (Whipple)\n- **Triệt căn duy nhất**; nên do phẫu thuật viên chuyên sâu, ở trung tâm hồi sức tốt {{BHNgTH tr.348}} {{BHNgTH tr.349}}\n- **Mổ mở là tiêu chuẩn**: cắt phần dưới dạ dày, phần đầu hỗng tràng, túi mật, ống gan chung, đầu tụy ngang bờ trái TMMTTT; tái lập bằng miệng nối tụy – hỗng tràng, ống gan chung – hỗng tràng, dạ dày – hỗng tràng (kiểu Roux-en-Y hoặc chữ C) {{BHNgTH tr.350}}\n- Cắt lạnh các diện cắt tụy, mật và ống tiêu hóa giúp tăng tỉ lệ diện cắt **R0** {{BHNgTH tr.350}}\n- **Nội soi**: ít đau, hồi phục xã hội sớm, sống còn gần tương đương mổ mở; chưa thay thế hoàn toàn mổ mở khi u đã xâm lấn, viêm dính quanh cuống gan và đầu tụy {{BHNgTH tr.350}}\n- **Robot**: tiêu chuẩn chọn bệnh như nội soi; ưu điểm tay robot xoay 540 độ, chính xác từng mm {{BHNgTH tr.350}}\n- Khoét u bóng Vater (u dưới 2 cm, chưa di căn hạch) là lựa chọn cho người trên 75 tuổi có ASA trên mức III {{BHNgTH tr.348}}\n- Cắt nhú nội soi chỉ cho ung thư tại chỗ (Tis) hoặc T1a không di căn hạch {{BHNgTH tr.346}} {{BHNgTH tr.355}}\n@@tab Phẫu thuật nối tắt\n- **Chỉ định**: u vượt khả năng cắt (di căn gan, xâm lấn mạch không còn cắt nối được) tại thời điểm thám sát trong mổ {{BHNgTH tr.352}}\n- **Kỹ thuật**: quai hỗng tràng cách góc Treitz 20 cm nối với dạ dày; nối túi mật – hỗng tràng hoặc OMC – hỗng tràng trên cùng quai (cách miệng nối vị tràng khoảng 40 cm); nối hỗng tràng – hỗng tràng kiểu Braun {{BHNgTH tr.352}} {{BHNgTH tr.353}}\n- Có thể mổ mở hoặc nội soi {{BHNgTH tr.352}}\n@@tab Hóa xạ trị và giảm nhẹ\n- U giáp biên: **Gemcitabine** (có thể phối hợp cisplatin hoặc oxaliplatin) kèm xạ trị 30 Gray trong 2 tuần; đánh giá lại CLVT sau 4–6 tuần; đáp ứng thì mổ {{BHNgTH tr.348}}\n- Sau mổ: tiếp tục Gemcitabine (± cisplatin hoặc oxaliplatin) 4 chu kỳ trong 7 tuần kèm xạ trị 30 Gray {{BHNgTH tr.348}}\n- Giáo trình cũ (theo NCCN 2019): có thể dùng **FOLFIRINOX** thay Gemcitabine; hóa trị bổ trợ trung bình sáu tháng; Gemcitabine kéo dài sống từ 6,9 lên 13,4 tháng {{Notion}}\n- Giảm nhẹ: giảm đau, dẫn lưu đường mật, nối vị – tràng, điều chỉnh rối loạn chức năng {{BHNgTH tr.348}}\n- Giáo trình cũ: phong bế đám rối thần kinh tạng (bơm 20 ml ethanol 50–97%) cho người không còn khả năng cắt {{Notion}}\n@@end\n\n### 7.3 Chỉ định – hướng xử trí\n| Tình huống | Hướng xử trí |\n|---|---|\n| Có giải phẫu bệnh ung thư, còn khả năng cắt | Cắt khối tá tụy {{BHNgTH tr.348}} |\n| Bóng Vater < 2 cm, chưa di căn hạch; > 75 tuổi, ASA > III | Khoét u {{BHNgTH tr.348}} |\n| Tis hoặc T1a không di căn hạch (bóng Vater) | Cắt nhú nội soi hoặc cắt nhú phẫu thuật {{BHNgTH tr.346}} |\n| T1b–T3a (bóng Vater) | Xem xét cắt khối tá tụy vì nguy cơ xâm lấn sâu {{BHNgTH tr.346}} |\n| T3b, T4, N1, N2 hoặc M1 | Tiên lượng xấu, thường cần mở rộng phẫu thuật kèm hóa/xạ trị {{BHNgTH tr.346}} |\n| Chưa có giải phẫu bệnh, hình ảnh nghi ngờ | Thám sát, sinh thiết tức thì rồi quyết định cắt khối tá tụy; nếu sinh thiết là viêm mạn hoặc nghịch sản mà có tắc mật và tổn thương sờ rõ thì phẫu thuật viên cân nhắc cắt hoặc nối tắt {{BHNgTH tr.348}} |\n| Giáp biên | Hóa trị tân bổ trợ + xạ 30 Gray, đánh giá lại sau 4–6 tuần, rồi cắt khối tá tụy; sau mổ tiếp tục hóa xạ {{BHNgTH tr.348}} |\n| Tiến xa, hoặc thám sát thấy không cắt được | Giảm nhẹ; nối tắt mật – ruột và vị – tràng {{BHNgTH tr.348}} {{BHNgTH tr.352}} |\n| Bilirubin > 15 mg/dl, viêm đường mật, trì hoãn mổ > 2 tuần | Dẫn lưu mật trước mổ (ERCP hoặc PTBD) {{BHNgTH tr.346}} |\n\n> [!doc] Biến chứng sớm của cắt khối tá tụy\n> - Tổng quát: biến chứng 30–50%; tử vong dưới 1% tại trung tâm lớn; nguyên nhân tử vong: rò tụy độ C, chảy máu, bệnh tim phổi nền nặng lên, nhiễm trùng huyết {{BHNgTH tr.351}}\n> - **Rò tụy** (10–12%): amylase dịch dẫn lưu từ ngày hậu phẫu thứ 3 gấp 3 lần giá trị bình thường huyết thanh; độ A không triệu chứng; độ B cần can thiệp (kháng sinh, dinh dưỡng, somatostatin, dẫn lưu da); độ C suy đa cơ quan, nhiễm trùng huyết, thường phải mổ lại {{BHNgTH tr.351}}\n> - **Chậm tống xuất dạ dày** (18%): cần lưu thông mũi – dạ dày trên 10 ngày kèm một tiêu chuẩn phụ (nôn sau rút ống, cần thuốc chống nôn sau ngày 10, đặt lại ống, không cải thiện khẩu phần từ ngày 14) {{BHNgTH tr.351}}\n> - **Chảy máu** (5%): sớm trong 24 giờ (dịch ống thông mũi – dạ dày có máu, phân đen) thường do miệng nối, xử trí nội soi hoặc mổ lại; muộn tuần 2–3 do loét miệng nối vị tràng, mỏm động mạch vị tá tràng hoặc mặt cắt tụy do rò {{BHNgTH tr.351}} {{BHNgTH tr.352}}\n> - **Áp-xe ổ bụng**: dưới gan phải hoặc dưới hoành trái; luôn tìm rò tụy bị che lấp; dẫn lưu dưới siêu âm hoặc mổ lại {{BHNgTH tr.352}}\n> - **Nhiễm trùng vết mổ** 5–20%: chăm sóc vết mổ, dẫn lưu, kháng sinh theo cấy {{BHNgTH tr.352}}\n> - **Rò mật** (3%): bilirubin dịch dẫn lưu gấp ba lần huyết thanh từ ngày 3, hoặc viêm phúc mạc mật phải can thiệp {{BHNgTH tr.352}}\n> - **Rò dưỡng trấp** (3%): dịch đục như sữa từ ngày 3, triglycerid từ 110 mg/dl (1,2 mmol/L) trở lên {{BHNgTH tr.352}}\n> - Biến chứng nối tắt: hẹp hoặc tắc quai đi miệng nối vị tràng, chảy máu miệng nối, rò mật do bục miệng nối mật – ruột ở người suy kiệt {{BHNgTH tr.353}}\n\n### Nguy cơ rò tụy (thang điểm FRS, Callery 2013)\n| Yếu tố | Điểm |\n|---|---|\n| Nhu mô tụy: không mềm / mềm | 0 / 2 |\n| Giải phẫu bệnh: adenocarcinoma tụy / ung thư Vater, tá tràng, OMC | 0 / 1 |\n| Đường kính ống tụy: ≥ 5 / 4 / 3 / 2 / ≤ 1 mm | 0 / 1 / 2 / 3 / 4 |\n| Máu mất: ≤ 400 / 401–700 / 701–1000 / > 1000 ml | 0 / 1 / 2 / 3 |\n\n- Diễn giải: 0 điểm không nguy cơ; 1–2 thấp (6,6%); 3–6 trung bình (12,9%); 7–10 cao (28,1%) {{BHNgTH tr.349}}\n- Yếu tố trước mổ liên quan rò tụy: tuổi trên 70, suy dinh dưỡng, BMI trên 25 kg/m2, albumin thấp {{BHNgTH tr.349}}\n\n> [!warn] Chưa có liều thuốc chi tiết\n> Giáo trình chỉ nêu tên thuốc, chu kỳ và liều xạ (30 Gray); không nêu liều gemcitabine, cisplatin, oxaliplatin {{BHNgTH tr.348}}\n\n## 8. Tiên lượng – Dự phòng / theo dõi\n\n### Tiên lượng\n- Tiên lượng theo vị trí: **tá tràng tốt nhất**; bóng Vater cao thứ hai về tỉ lệ cắt được và sống 5 năm; **đầu tụy xấu nhất**, chỉ khoảng 12% sống đến 5 năm sau cắt khối tá tụy {{BHNgTH tr.353}}\n- Sống còn theo giai đoạn (bảng giáo trình, các giai đoạn khớp với phân giai đoạn ung thư tụy) {{BHNgTH tr.345}}\n\n| Giai đoạn | Sống còn (tháng) | Sống 5 năm (%) |\n|---|---|---|\n| IA | 38 | 39 |\n| IB | 24 | 34 |\n| IIA | 18 | 28 |\n| IIB | 17 | 21 |\n| III | 14 | 11 |\n\n- Giáo trình cũ: sống 5 năm (u cắt triệt để) đầu tụy 15%, bóng Vater 39%, OMC 27%, tá tràng 59%; sống 10 năm: tụy 5%, Vater 25%, OMC 21%, tá tràng 59% {{Notion}}\n\n@@tabs\n@@tab Yếu tố lâm sàng\n- Vàng da tắc mật thường chẩn đoán sớm hơn nên tiên lượng tốt hơn; đau bụng, sụt cân, viêm tụy gợi ý bệnh tiến triển hơn {{BHNgTH tr.354}}\n- Nam mắc nhiều hơn nữ (1,5:1); tuổi càng cao tiên lượng càng kém {{BHNgTH tr.354}}\n@@tab Yếu tố mô bệnh học\n- Ung thư bóng Vater: dạng ruột tốt hơn, ít di căn hạch; dạng tụy – đường mật tái phát cao hơn; hỗn hợp trung gian; tế bào nhẫn hoặc không biệt hóa xấu nhất {{BHNgTH tr.354}}\n- Độ biệt hóa kém, u lớn xâm lấn, di căn hạch, xâm lấn thần kinh hoặc mạch, diện cắt R1 hoặc R2: tiên lượng xấu {{BHNgTH tr.354}}\n- Đột biến KRAS, CDKN2A, TP53, SMAD4 và CA 19-9 cao trước mổ: tiên lượng xấu {{BHNgTH tr.354}}\n@@tab Yếu tố điều trị\n- Truyền máu trong mổ và biến chứng sau mổ là yếu tố tiên lượng xấu {{BHNgTH tr.355}}\n- Cắt nhú nội soi chọn sai (u T1b trở lên): nguy cơ tái phát cao {{BHNgTH tr.355}}\n- T3/T4 hoặc N1/N2 có thể hưởng lợi từ hóa trị bổ trợ {{BHNgTH tr.355}}\n- Chỉ số viêm hệ thống (NLR, GPS) có liên quan tiên lượng {{BHNgTH tr.355}}\n@@end\n\n### Theo dõi sau mổ\n- **CA 19-9**: về gần bình thường sau mổ 2 tuần; tăng lại gợi ý tái phát {{BHNgTH tr.338}}\n- **Đái tháo đường sau phẫu thuật tụy** (típ 3c): gặp 20–50% tùy loại mổ và bệnh nền; theo dõi đường huyết {{BHNgTH tr.355}}\n- Giáo trình cũ: đái tháo đường tiến triển trong khoảng 2 năm sau mổ; đa số kiểm soát được; dùng insulin trước mổ làm khó điều chỉnh đường huyết sau mổ {{Notion}}\n- Theo dõi biến chứng sớm (rò tụy, chảy máu, chậm tống xuất dạ dày, áp-xe) đã nêu ở mục 7.3 {{BHNgTH tr.351}} {{BHNgTH tr.352}}\n- Giáo trình không nêu lịch tái khám và tầm soát tái phát cụ thể.\n\n### Dự phòng\n- Giáo trình không nêu biện pháp dự phòng cấp 1; chỉ nêu các yếu tố nguy cơ (hút thuốc, béo phì, đái tháo đường, viêm tụy mạn, hội chứng đa polyp di truyền) {{BHNgTH tr.336}}\n- Phát hiện sớm: tại Việt Nam đa số đến muộn khi đã vàng da, sụt cân; bệnh sớm thì cải thiện tiên lượng và chất lượng sống {{BHNgTH tr.335}} {{Notion}}\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] Ung thư quanh bóng Vater thi nhấn mạnh gì\n> - **Nhận diện**: vàng da tắc mật tăng dần không đau hoặc đau mơ hồ lan lưng, sụt cân, túi mật to {{BHNgTH tr.336}} {{BHNgTH tr.337}}\n> - **Chẩn đoán**: CLVT cản quang dựng hình là chủ lực; EUS-FNA lấy mô; CA 19-9 để theo dõi; đánh giá cắt được, giáp biên, không cắt được {{BHNgTH tr.338}} {{BHNgTH tr.341}} {{BHNgTH tr.346}}\n> - **Xử trí**: dẫn lưu mật khi bilirubin trên 15 mg/dl hoặc viêm đường mật; Whipple là triệt căn; giáp biên hóa xạ tân bổ trợ; không cắt được nối tắt hoặc giảm nhẹ {{BHNgTH tr.346}} {{BHNgTH tr.348}}\n\n@@tabs\n@@tab Nhận diện\n- Vàng da ~75%, sụt cân 51%, đau bụng 39% {{BHNgTH tr.337}}\n- Túi mật to; Virchow, Sister Mary Joseph, Blumer's shelf là dấu di căn {{BHNgTH tr.337}}\n- Dấu ống đôi trên CLVT hay gặp ở ung thư bóng Vater {{BHNgTH tr.339}}\n- Xem [mục 4](#/n/ngoai-ung-thu-quanh-bong-vater/4)\n@@tab Chẩn đoán\n- Xác định bằng giải phẫu bệnh (sinh thiết nội soi tá tràng hoặc EUS) {{BHNgTH tr.341}}\n- CLVT: nhạy 90–95% với u đầu tụy; PPV cho u không cắt được 89–100%, cắt được 45–79% {{BHNgTH tr.338}} {{BHNgTH tr.339}} {{BHNgTH tr.340}}\n- TNM theo AJCC 8; giáp biên: giảm >50% bán kính TM, xâm lấn <180 độ ĐMMTTT {{BHNgTH tr.341}} {{BHNgTH tr.346}}\n- Xem [mục 5](#/n/ngoai-ung-thu-quanh-bong-vater/5) và [mục 6](#/n/ngoai-ung-thu-quanh-bong-vater/6)\n@@tab Điều trị\n- Whipple là triệt căn duy nhất; mổ mở là tiêu chuẩn {{BHNgTH tr.348}} {{BHNgTH tr.350}}\n- Dẫn lưu mật trước mổ khi bilirubin > 15 mg/dl, viêm đường mật, trì hoãn mổ > 2 tuần {{BHNgTH tr.346}}\n- Giáp biên: Gemcitabine ± cisplatin/oxaliplatin + xạ 30 Gray, đánh giá lại sau 4–6 tuần {{BHNgTH tr.348}}\n- Không cắt được: nối mật – ruột và vị – tràng {{BHNgTH tr.352}}\n- Xem [mục 7.3](#/n/ngoai-ung-thu-quanh-bong-vater/7)\n@@tab Tiên lượng – Dự phòng\n- Biến chứng 30–50%, tử vong ~1%; rò tụy 10–12%, chậm tống xuất dạ dày 18% {{BHNgTH tr.351}} {{BHNgTH tr.353}}\n- Tá tràng tốt nhất, đầu tụy xấu nhất (sống 5 năm khoảng 12% sau mổ) {{BHNgTH tr.353}}\n- Theo dõi CA 19-9; đái tháo đường típ 3c 20–50% {{BHNgTH tr.338}} {{BHNgTH tr.355}}\n- Xem [mục 8](#/n/ngoai-ung-thu-quanh-bong-vater/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Bán kính vùng quanh bóng Vater (Halsted) | ==2 cm quanh nhú tá lớn== | {{BHNgTH tr.335}} |\n| Tỉ lệ cắt được tại Việt Nam | ==khoảng 20%== | {{BHNgTH tr.335}} |\n| Vàng da / sụt cân / đau bụng | ==75% / 51% / 39%== | {{BHNgTH tr.337}} |\n| CA 19-9: độ nhạy / đặc hiệu ở ngưỡng 37 IU/L | ==81% / 90%== | {{BHNgTH tr.338}} |\n| Độ nhạy siêu âm / CLVT đầu tụy | ==25% / 90–95%== | {{BHNgTH tr.338}} |\n| Hạch di căn trên CLVT | ==≥ 10 mm== | {{BHNgTH tr.339}} |\n| Độ nhạy EUS-FNA | ==80–95%== | {{BHNgTH tr.340}} |\n| Chỉ định dẫn lưu mật trước mổ | ==bilirubin > 15 mg/dl== | {{BHNgTH tr.346}} |\n| Dẫn lưu thành công | ==bilirubin giảm ≥ 50%== | {{BHNgTH tr.346}} |\n| Giáp biên: xạ trị; đánh giá lại | ==30 Gray / 4–6 tuần== | {{BHNgTH tr.348}} |\n| Biến chứng / tử vong sau Whipple | ==30–50% / ~1%== | {{BHNgTH tr.351}} |\n| Rò tụy / chậm tống xuất dạ dày | ==10–12% / 18%== | {{BHNgTH tr.351}} |\n| FRS: nguy cơ thấp / trung bình / cao | ==6,6% / 12,9% / 28,1%== | {{BHNgTH tr.349}} |\n| Ung thư đầu tụy sống 5 năm sau mổ | ==khoảng 12%== | {{BHNgTH tr.353}} |\n| Đái tháo đường sau phẫu thuật tụy | ==20–50%== | {{BHNgTH tr.355}} |\n\n> [!warn] Bẫy thi thường gặp\n> - **Dẫn lưu mật không thường quy**: chỉ khi bilirubin > 15 mg/dl, hoặc < 15 kèm suy dinh dưỡng hay bệnh nội khoa, viêm đường mật cấp, hoãn mổ > 2 tuần {{BHNgTH tr.346}}\n> - **Dẫn lưu giảm nguy cơ di căn gan liên quan thủ thuật**: đáp án sách là ERCP, không phải PTBD {{BHNgTH tr.357}} {{BHNgTH tr.358}}\n> - **CA 19-9 chủ yếu để theo dõi và tiên lượng**, không phải tầm soát; tăng cả trong bệnh lành tính {{BHNgTH tr.338}}\n> - **Tá tràng tiên lượng tốt nhất; đầu tụy xấu nhất** {{BHNgTH tr.353}} {{BHNgTH tr.356}}\n> - **Ung thư tụy khác ung thư bóng Vater về T**: tụy theo kích thước u; Vater theo độ xâm lấn lớp thành; OMC theo độ dày thành {{BHNgTH tr.342}} {{BHNgTH tr.343}}\n> - **Ngưỡng albumin liên quan rò tụy**: giáo trình mới ghi < 3 g/dl; giáo trình cũ (Notion) ghi < 4 g/dl {{BHNgTH tr.349}} {{Notion}}\n> - **Chảy máu muộn sau mổ**: giáo trình mới ghi tuần 2–3; giáo trình cũ (Notion) ghi tuần 1–2 {{BHNgTH tr.352}} {{Notion}}\n> - **Hóa trị giáp biên**: giáo trình mới nêu Gemcitabine ± cisplatin/oxaliplatin; giáo trình cũ (Notion) nêu thêm FOLFIRINOX {{BHNgTH tr.348}} {{Notion}}\n> - **Sau Whipple chậm tống xuất dạ dày thường gặp (18%)**, hơn rò tụy (10–12%) {{BHNgTH tr.351}}\n\n@@fold Nguồn tài liệu\n- **BHNgTH** Giáo trình Bệnh học ngoại khoa tiêu hóa 2025, chương Ung thư quanh bóng Vater, tr.335–355 (số trang PDF; sách in tr.326–346); câu hỏi lượng giá tr.356–358. Bảng FRS đọc từ chữ trích tr.349; bảng TNM tr.342–345\n- Không dùng TCBN cho bài này\n@@end\n\n@@fold Nguồn ngoài\n- **Notion** (giáo trình cũ hơn): tần suất bốn loại ung thư; tuổi và giới; sống còn 5 và 10 năm theo vị trí; kỹ thuật chụp CLVT phase tụy; độ nhạy MRCP 86% so với 84%, duct-penetrating sign; phối hợp tiêu chí khả năng cắt; FOLFIRINOX thay thế; hóa trị bổ trợ trung bình 6 tháng, Gemcitabine 6,9 lên 13,4 tháng; phong bế đám rối tạng; bilirubin giảm 1–2 mg/dL mỗi ngày sau dẫn lưu; đái tháo đường tiến triển trong 2 năm\n- **Khác biệt Notion và giáo trình mới** (theo giáo trình mới): ngưỡng albumin (< 4 so với < 3 g/dl); chảy máu muộn (tuần 1–2 so với 2–3); Notion không khuyến cáo dẫn lưu mật thường quy, giáo trình mới nêu chỉ định cụ thể; Notion ghi rò tụy 12% và nhiễm khuẩn vết mổ 7%, giáo trình mới 10–12% và 5–20%\n- Không có nguồn ngoài khác; không có liều thuốc, lịch tái khám sau mổ, và dự phòng cấp 1 trong cả hai nguồn\n@@end\n\n@@fold! Tự kiểm tra (12 thẻ)\n- Vùng quanh bóng Vater theo Halsted là gì? :: Trong bán kính 2 cm quanh nhú tá lớn\n- Bốn ung thư của nhóm quanh bóng Vater? :: Đầu tụy, bóng Vater, đoạn cuối ống mật chủ, tá tràng\n- Triệu chứng thường gặp nhất và tần suất? :: Vàng da tắc mật, khoảng 75%; kế đến sụt cân 51%, đau bụng 39%\n- Ba dấu hiệu di căn thực thể có tên riêng? :: Hạch thượng đòn Virchow, nốt quanh rốn Sister Mary Joseph, Blumer's shelf (di căn hố chậu khi thăm trực tràng)\n- Vai trò chính của CA 19-9? :: Theo dõi và tiên lượng: về gần bình thường sau mổ 2 tuần, tăng lại khi tái phát\n- Hạch được xem là di căn trên CLVT khi nào? :: ≥ 10 mm, hoại tử trung tâm bất kể kích thước, hoặc đậm độ HU cao hơn nhu mô gan ở thì tĩnh mạch cửa\n- Hình ảnh CLVT hay gặp ở ung thư bóng Vater? :: Khối giảm đậm độ chia thùy hay thâm nhiễm và dấu ống đôi (dãn OMC và ống tụy)\n- Khi nào dẫn lưu mật trước mổ cắt khối tá tụy? :: Bilirubin > 15 mg/dl; hoặc < 15 kèm suy dinh dưỡng/bệnh nội khoa; viêm đường mật cấp; hoãn mổ > 2 tuần\n- Điều trị u giáp biên? :: Hóa trị tân bổ trợ Gemcitabine ± cisplatin/oxaliplatin + xạ 30 Gray, đánh giá CLVT lại sau 4–6 tuần, rồi cắt khối tá tụy và hóa xạ bổ trợ\n- Chỉ định nối tắt? :: Thám sát trong mổ thấy u không cắt được (di căn gan, xâm lấn mạch không cắt nối được): nối mật – ruột và vị – tràng\n- Ba biến chứng hay gặp nhất sau Whipple và tần suất? :: Chậm tống xuất dạ dày 18%, rò tụy 10–12%, chảy máu 5%\n- Ba mức độ rò tụy? :: A không triệu chứng; B cần can thiệp (kháng sinh, dinh dưỡng, somatostatin, dẫn lưu); C suy đa cơ quan, nhiễm trùng huyết, thường mổ lại\n@@end"}, {"kind": "disease", "disease": "ung-thu-thuc-quan", "short": "Ung thư thực quản", "group": "", "section": 0, "order": 20, "khung": [], "id": "ngoai-ung-thu-thuc-quan", "title": "Ung thư thực quản (ngoại khoa)", "layer": "benh", "module": "ngoai-tong-quat", "tags": ["ngoại khoa", "tiêu hóa", "thực quản", "ung thư tế bào gai", "JES", "TNM", "cắt thực quản", "McKeown", "Ivor-Lewis", "ESD", "nạo hạch 3 vùng", "hóa trị tân hỗ trợ"], "source": "BHNgTH tr.160–177 (chương Ung thư thực quản; lưu đồ điều trị và bảng theo dõi đọc từ ảnh trang). Notion không dùng (trang Ung thư thực quản trong Notion nằm ngoài TNK’s Notebook)", "body": "> [!key] Ung thư thực quản (UTTQ) trong một nhìn\n> - Ung thư biểu mô: tế bào gai ==85%==, biểu mô tuyến ==14%==; Việt Nam và Đông – Nam Á chủ yếu là tế bào gai {{BHNgTH tr.160}}\n> - Thường không triệu chứng đến khi muộn; dấu hiệu chính là ==nuốt khó tăng dần== (đặc rồi đến lỏng), sụt cân >10% trong 6 tháng {{BHNgTH tr.164}}\n> - Chẩn đoán xác định bằng ==nội soi + sinh thiết 6–8 mẫu==; phân giai đoạn bằng CLVT cổ–ngực–bụng–chậu, EUS, PET/CT khi cần {{BHNgTH tr.164}} {{BHNgTH tr.168}}\n> - Điều trị đa mô thức, bàn qua MDT; giai đoạn sớm cắt u qua nội soi (ESD), giai đoạn II–III ưu tiên hóa trị tân hỗ trợ rồi cắt thực quản {{BHNgTH tr.171}} {{BHNgTH tr.176}}\n> - Tại Việt Nam, phẫu thuật ưu tiên: nội soi ngực–bụng, cắt thực quản kiểu McKeown, nạo hạch 3 vùng {{BHNgTH tr.174}}\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Hai type mô học có yếu tố nguy cơ và vị trí khác nhau: tế bào gai (thuốc lá, rượu) và biểu mô tuyến (Barrett, trào ngược) {{BHNgTH tr.160}} {{BHNgTH tr.161}}\n> - Giáo trình trình bày phân loại, giai đoạn và điều trị theo Hội Thực quản Nhật (JES) và chỉ bàn ung thư tế bào gai {{BHNgTH tr.160}} {{BHNgTH tr.170}}\n\n### Định nghĩa và dịch tễ\n- UTTQ là ung thư thường gặp của ống tiêu hóa: đứng thứ 8 trong các ung thư thường gặp và thứ 6 trong các ung thư gây tử vong nhiều nhất thế giới {{BHNgTH tr.160}}\n- Ung thư tế bào gai chiếm hơn 90% UTTQ ở người Đông Á; phương Tây thì ung thư biểu mô tuyến thường gặp hơn {{BHNgTH tr.160}} {{BHNgTH tr.170}}\n- Điều trị có hai trường phái: châu Á (đứng đầu là Nhật) và phương Tây; giáo trình dựa trên hướng dẫn JES {{BHNgTH tr.160}}\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Tế bào gai\n- Hút thuốc lá, uống rượu, nhiễm HPV, hội chứng Plummer-Vinson, co thắt tâm vị, bệnh tylosis, thiếu máu Fanconi, bỏng thực quản do hóa chất {{BHNgTH tr.160}}\n- ==Thuốc lá và rượu== là hai yếu tố được xác nhận rõ nhất {{BHNgTH tr.161}}\n- Hay gặp nhất ở thực quản ngực dưới {{BHNgTH tr.161}}\n@@tab Biểu mô tuyến\n- Thực quản Barrett, tiền căn trào ngược dạ dày thực quản, béo phì, hút thuốc lá {{BHNgTH tr.161}}\n- Chủ yếu ở thực quản ngực dưới {{BHNgTH tr.161}}\n@@end\n\n### Giải phẫu ứng dụng\n- Thực quản là ống nằm giữa hầu và chỗ nối thực quản – dạ dày; theo AJCC lần 8 chia 4 đoạn, tính khoảng cách từ cung răng qua nội soi {{BHNgTH tr.161}}\n\n| Đoạn | Mốc giải phẫu | Cách cung răng (nội soi) |\n|---|---|---|\n| Thực quản cổ | Từ bờ dưới sụn nhẫn đến lỗ trên lồng ngực ngang hõm ức | 15 đến <20 cm |\n| Ngực trên | Từ lỗ vào lồng ngực đến bờ dưới tĩnh mạch đơn | 20 đến <25 cm |\n| Ngực giữa | Từ bờ dưới tĩnh mạch đơn đến tĩnh mạch phổi dưới | 25 đến <30 cm |\n| Ngực dưới và chỗ nối thực quản – dạ dày | Từ tĩnh mạch phổi dưới đến dạ dày, gồm cả chỗ nối | 30 đến <40 cm |\n\n- Vùng 5 cm trên đến 5 cm dưới chỗ nối thực quản – dạ dày là vùng chuyển tiếp; phân loại **Siewert** theo khoảng cách từ tâm u đến chỗ nối {{BHNgTH tr.162}}\n  - Siewert type I: điều trị như UTTQ; type III: điều trị như ung thư dạ dày; type II: phức tạp, chưa thống nhất (giáo trình không bàn) {{BHNgTH tr.162}}\n- Các nhóm hạch của thực quản được nạo theo vùng: cổ hai bên, trung thất, bụng (phần cắt thực quản ở mục bảy) {{BHNgTH tr.173}}\n- Thực quản cổ, ngực trên, ngực giữa: cần loại trừ xâm lấn khí phế quản (CLVT và nội soi phế quản) {{BHNgTH tr.166}} {{BHNgTH tr.169}}\n\n### Đại thể (JES)\n- Khi nội soi chia 5 type: ==0 nông==, 1 lồi, 2 loét khu trú, 3 loét thâm nhiễm, 4 thâm nhiễm lan tỏa, 5 không thể phân loại (5a chưa điều trị, 5b sau điều trị) {{BHNgTH tr.162}}\n- Hai type thường gặp nhất là ==type 2 và type 3==; có thể phối hợp nhiều type, type xâm lấn sâu nhất là type chính {{BHNgTH tr.163}}\n- Type 0 chia: 0-I (lồi; Ip có cuống, Is không cuống), 0-II (phẳng; IIa hơi cao, IIb phẳng, IIc hơi lõm), 0-III (lõm) {{BHNgTH tr.163}}\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> UTTQ thường im lặng đến giai đoạn trễ, người bệnh đến khám sau vài tháng có triệu chứng {{BHNgTH tr.164}}\n\n### Triệu chứng cơ năng\n- ==Nuốt khó tăng dần== (từ thức ăn đặc đến lỏng), nuốt đau, sụt cân >10% trong 6 tháng {{BHNgTH tr.164}}\n- Đau sau xương ức, nấc cụt gợi ý u xuyên thành, ảnh hưởng trung thất và cơ hoành {{BHNgTH tr.164}}\n- Đau ngực hoặc đau lưng khi nuốt có thể là triệu chứng sau cùng {{BHNgTH tr.164}}\n\n### Triệu chứng thực thể\n- Gần như không có cho đến khi bệnh tiến triển; suy kiệt, cần đánh giá dinh dưỡng trước mổ {{BHNgTH tr.164}}\n- Hạch thượng đòn, khàn tiếng, hôi miệng, khối u thượng vị {{BHNgTH tr.164}}\n- Hội chứng Horner một bên (co đồng tử, sụp mi, không đổ mồ hôi một bên mặt và cổ) {{BHNgTH tr.164}}\n- Dấu to đầu chi thường xuất hiện trễ {{BHNgTH tr.164}}\n\n> [!red] Dấu hiệu gợi ý bệnh đã tiến xa\n> - {r|Đau ngực hoặc đau lưng khi nuốt, nấc cụt, khàn tiếng, hội chứng Horner, hạch thượng đòn}: u xâm lấn trung thất, hoành hoặc có di căn hạch {{BHNgTH tr.164}}\n> - Sụt cân và suy kiệt: ảnh hưởng trực tiếp khả năng chịu mổ {{BHNgTH tr.164}}\n\n## 5. Cận lâm sàng\n\n### Nội soi thực quản – dạ dày và sinh thiết\n- Chẩn đoán xác định; quan sát đại thể và sinh thiết, ==nên lấy 6–8 mẫu== {{BHNgTH tr.164}}\n- Nội soi phế quản cho UTTQ cổ, ngực trên, ngực giữa chưa loại trừ xâm lấn khí phế quản {{BHNgTH tr.169}}\n\n### X quang thực quản cản quang\n- Hỗ trợ chẩn đoán, có ích để xác định vị trí và chiều dài u {{BHNgTH tr.164}}\n- Hẹp lòng, niêm mạc không đều, dãn thực quản trên chỗ hẹp; dấu hiệu tiến triển: xoắn vặn, gập góc, lệch trục u, rò vào khí phế quản {{BHNgTH tr.164}} {{BHNgTH tr.165}}\n- Akiyama (1972) mô tả dấu hiệu X quang dự đoán u xâm lấn cơ quan lân cận {{BHNgTH tr.165}}\n\n### Đánh giá giai đoạn\n> [!warn] Dùng tất cả phương tiện vẫn chỉ đúng khoảng ==80–90%== {{BHNgTH tr.165}}\n\n@@tabs\n@@tab CLVT cổ–ngực–bụng–chậu\n- Khuyến cáo cho mọi trường hợp (trừ chống chỉ định); cần thuốc cản quang, độ dày lát cắt ≤2,5 mm {{BHNgTH tr.165}}\n- Thành thực quản bình thường <3 mm khi căng; >5 mm là bất thường {{BHNgTH tr.166}}\n- T1 thường không thấy hoặc dày thành/tăng quang nhẹ; T2–T3 dày thành hoặc khối riêng; T3 thêm thâm nhiễm mỡ quanh thực quản {{BHNgTH tr.166}}\n- Phân biệt T3 với T4 quan trọng nhưng khó; JES chia cT3r (resectable) và cT3br (borderline resectable), cT4 không còn chia a/b ở xếp hạng lâm sàng {{BHNgTH tr.166}}\n- Xâm lấn khí phế quản: mất lớp mỡ tách, đường thở bị đè, lệch hoặc hẹp; cần nội soi phế quản xác nhận {{BHNgTH tr.166}}\n- Xâm lấn động mạch chủ: mất lớp tách; góc Picus ≥110° trên đoạn ≥10 mm, hoặc 90–110° trên đoạn ≥20 mm; u bao quanh hoặc đè ép động mạch chủ {{BHNgTH tr.166}}\n- Hạch: tiêu chuẩn JES là trục ngắn ≥6 mm; tiêu chuẩn 1 cm có độ nhạy 30–60%, độ đặc hiệu 60–80%; 1/3 hạch di căn có trục ngắn <5 mm {{BHNgTH tr.167}}\n- Di căn xa: loại trừ ba vị trí quan trọng nhất là gan, phổi, tuyến thượng thận {{BHNgTH tr.167}}\n@@tab EUS\n- Phương tiện chính xác nhất để đánh giá độ xâm lấn T (thành thực quản thấy 5 lớp) {{BHNgTH tr.169}}\n- Đánh giá hạch lân cận (khoảng 3 cm quanh thực quản) và hướng dẫn sinh thiết hút {{BHNgTH tr.169}}\n- Hạn chế: phụ thuộc kinh nghiệm người làm; khó khi u làm hẹp lòng nhiều {{BHNgTH tr.169}}\n@@tab PET/CT và MRI\n- PET/CT có giá trị cao hơn ở phát hiện di căn hạch và di căn xa; ==không dùng thường quy==, dùng khi nghi di căn xa nhưng chưa rõ {{BHNgTH tr.167}}\n- MRI không hơn CLVT; chủ yếu thay thế khi không chụp được CLVT {{BHNgTH tr.169}}\n@@end\n\n### Phân giai đoạn TNM ung thư tế bào gai (JES, lần 12)\n@@tabs\n@@tab Định nghĩa T, N, M\n- **T1a** xâm lấn niêm mạc: EP (carcinoma in situ), LPM (tấm đệm), MM (cơ niêm) {{BHNgTH tr.170}}\n- **T1b** xâm lấn dưới niêm (SM1, SM2, SM3 theo 1/3 trên, giữa, dưới) {{BHNgTH tr.170}}\n- **T2** xâm lấn lớp cơ; **T3** xâm lấn lớp áo ngoài (T3r: chưa thấy xâm lấn mô lân cận; T3br: chưa loại trừ được); **T4** xâm lấn cấu trúc lân cận {{BHNgTH tr.170}}\n- **N1** 1–2 hạch vùng; **N2** 3–6; **N3** ≥7 {{BHNgTH tr.170}}\n- **M1a** hạch ngoài vùng nhưng có hy vọng nạo được; **M1b** di căn xa hoặc các hạch ngoài vùng nêu trên cùng di căn xa {{BHNgTH tr.170}}\n@@tab Giai đoạn lâm sàng (cTNM)\n| | N0 | N1 | N2–3 hoặc M1a | M1b |\n|---|---|---|---|---|\n| T0–1a | 0 | II | IIIA | IVB |\n| T1b | I | II | IIIA | IVB |\n| T2 | II | IIIA | IIIA | IVB |\n| T3r | II | IIIA | IIIA | IVB |\n| T3br | IIIB | IIIB | IIIB | IVB |\n| T4 | IVA | IVA | IVA | IVB |\n\n{{BHNgTH tr.171}}\n@@tab Giai đoạn bệnh học (pTNM)\n| | N0 | N1 | N2 | N3 hoặc M1a | M1b |\n|---|---|---|---|---|---|\n| T0 | 0 | IIA | IIA | IIIA | IVB |\n| T1a | 0 | IIA | IIB | IIIA | IVB |\n| T1b | I | IIA | IIIA | IIIA | IVB |\n| T2 | IIA | IIB | IIIA | IIIB | IVB |\n| T3 | IIB | IIIA | IIIB | IVA | IVB |\n| T4a | IIIB | IIIB | IVA | IVA | IVB |\n| T4b | IVA | IVA | IVA | IVA | IVB |\n\n{{BHNgTH tr.171}}\n@@end\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Nguyên tắc chẩn đoán\n> - Gồm hai nội dung: ==chẩn đoán xác định và chẩn đoán giai đoạn==, cần phối hợp ung thư, ngoại khoa, nội soi, giải phẫu bệnh, chẩn đoán hình ảnh {{BHNgTH tr.169}}\n> - Nghi ngờ khi nuốt nghẹn tăng dần; xác định bằng nội soi + sinh thiết {{BHNgTH tr.169}}\n\n### Quy trình đánh giá sau khi đã xác định UTTQ\n1. X quang thực quản – dạ dày cản quang {{BHNgTH tr.169}}\n2. CLVT cổ–ngực–bụng–chậu có cản quang {{BHNgTH tr.169}}\n3. EUS nếu nghĩ u giai đoạn sớm {{BHNgTH tr.169}}\n4. PET/CT nếu nghi nhưng chưa chắc di căn hạch hoặc di căn xa {{BHNgTH tr.169}}\n5. Nội soi khí phế quản: UTTQ cổ, ngực trên, ngực giữa chưa loại trừ xâm lấn khí phế quản {{BHNgTH tr.169}}\n\n### Đánh giá khả năng mổ\n- Quyết định điều trị dựa ít nhất vào ba yếu tố: ==giai đoạn bệnh, tổng trạng người bệnh, sự đồng thuận của người bệnh== {{BHNgTH tr.171}}\n- Dự kiến cắt thực quản: làm thêm xét nghiệm tiền phẫu tùy trung tâm, nhưng ==bắt buộc đánh giá chức năng hô hấp== {{BHNgTH tr.169}}\n- Đánh giá dinh dưỡng trước mổ để nhận biết suy dinh dưỡng {{BHNgTH tr.164}}\n- Về mặt khả năng cắt u: cT3r còn cắt được; cT3br ranh giới (nên cân nhắc hóa xạ trị trước mổ); cT4 xâm lấn cấu trúc lân cận; giai đoạn IVB u gần như không còn cắt được {{BHNgTH tr.166}} {{BHNgTH tr.176}}\n- Giáo trình không nêu thang điểm hay ngưỡng cụ thể về chức năng hô hấp, tim mạch hay dinh dưỡng\n\n### Chẩn đoán phân biệt nuốt khó\n| Bệnh lý | Ghi chú |\n|---|---|\n| Trào ngược dạ dày thực quản | Nội soi thực quản – dạ dày giúp phân biệt dễ dàng với UTTQ {{BHNgTH tr.169}} |\n| Rối loạn vận động thực quản | Như trên {{BHNgTH tr.169}} |\n| Co thắt tâm vị | Như trên {{BHNgTH tr.169}} |\n| U từ bên ngoài chèn ép vào thực quản | Như trên {{BHNgTH tr.169}} |\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n- Điều trị ==đa mô thức== với hội chẩn MDT, sau đó chuẩn bị người bệnh (tinh thần, thể chất), điều trị đa mô thức, rồi theo dõi {{BHNgTH tr.171}}\n- Giai đoạn sớm: lấy trọn u ít xâm lấn (nội soi); giai đoạn II–III: phối hợp điều trị toàn thân trước mổ để có sống còn lâu dài tốt hơn; giai đoạn IV: kiểm soát bệnh, nâng đỡ, giải quyết tắc nghẽn {{BHNgTH tr.171}} {{BHNgTH tr.176}}\n- Cắt u qua nội soi cần đánh giá kỹ để tránh sót u (R1, R2) {{BHNgTH tr.172}}\n\n### 7.2 Các phương pháp\n@@tabs\n@@tab Cắt u qua nội soi\n- Dành cho u giai đoạn sớm, ít xâm lấn hơn cắt thực quản {{BHNgTH tr.171}}\n- **EMR** cắt bỏ phần niêm mạc mang u, hiện ít dùng; **ESD** bóc tách dưới niêm, cắt u đến lớp dưới niêm, hiện được dùng nhiều {{BHNgTH tr.171}} {{BHNgTH tr.172}}\n- Chỉ lấy u và một phần mô quanh u nên phải đánh giá kỹ trước và sau thủ thuật để tránh sót u (R1, R2) {{BHNgTH tr.172}}\n@@tab Cắt thực quản\n- Phẫu thuật lớn, phức tạp, nhiều thì; khác nhau ở mức độ nạo hạch, ngả tiếp cận, vật thay thế thực quản, đường đưa vật thay thế lên cổ, cách làm miệng nối {{BHNgTH tr.172}}\n- **Mức độ nạo hạch**\n  - 3 vùng: cắt thực quản + nạo hạch cổ hai bên + nạo hạch trung thất (tiêu chuẩn, mở rộng hoặc toàn bộ) + nạo hạch bụng {{BHNgTH tr.172}}\n  - 2 vùng: nạo hạch trung thất + hạch bụng (không nạo cổ) {{BHNgTH tr.172}}\n  - Cắt thực quản đơn thuần: không chú trọng nạo hạch {{BHNgTH tr.172}}\n- Nội soi và robot, nhất là thì ngực, giảm biến chứng phổi, giảm đau sau mổ, thời gian nằm viện ngắn hơn, quan sát tốt hơn, ít sang chấn mô; nhưng khó, đòi hỏi đội ngũ được huấn luyện kỹ {{BHNgTH tr.174}}\n@@tab Ngả tiếp cận\n| Phương pháp | Các thì | Đặc điểm |\n|---|---|---|\n| ==McKeown== (3 trường mổ) | Ngực, bụng, cổ | Thông dụng nhất ở châu Á; di động thực quản chủ động, nạo hạch triệt căn; miệng nối ở cổ nên khi xì rò hạn chế nhiễm trùng trung thất; xâm lấn nhất; dạ dày hoặc đại tràng tạo hình lên nối với thực quản cổ {{BHNgTH tr.172}} {{BHNgTH tr.173}} |\n| ==Ivor-Lewis== | Bụng, ngực | Cắt thực quản ngực giữa và dưới; dạ dày tạo hình nối với thực quản ngực trên ngay trong ngực {{BHNgTH tr.173}} |\n| Qua khe hoành (Orringer) | Không mở ngực | Thực quản ngực di động bằng phẫu tích tù {{BHNgTH tr.173}} |\n| Ngả ngực trái | Như McKeown hoặc Ivor-Lewis | Khi không vào được từ ngực phải (dày dính nhiều); ít áp dụng vì tim cản trở {{BHNgTH tr.173}} |\n@@tab Phẫu thuật mở nuôi ăn\n- Chỉ định: UTTQ tiến triển gây tắc nghẽn thực quản {{BHNgTH tr.174}}\n- Mở dạ dày hoặc mở hỗng tràng nuôi ăn; nếu u còn cắt được thì ==nên mở hỗng tràng nuôi ăn== để giữ nguyên dạ dày cho việc tạo hình sau này {{BHNgTH tr.174}}\n@@tab Hóa trị, xạ trị\n- Có thể là mô thức chính (không mổ: hóa trị và/hoặc xạ trị điều trị, liều ==≥50 Gy==) hoặc mô thức hỗ trợ (khi cắt thực quản là chính) {{BHNgTH tr.174}}\n- Tân hỗ trợ: hóa trị 3 thuốc docetaxel, cisplatin và 5-fluorouracil/capecitabine {{BHNgTH tr.176}}\n- Giáo trình không nêu liều thuốc cụ thể\n@@end\n\n### 7.3 Chỉ định – hướng xử trí\n> [!doc] Theo lưu đồ JES (hình 12–15) trong giáo trình; đọc từ ảnh trang {{BHNgTH tr.175}} {{BHNgTH tr.176}}\n\n@@tabs\n@@tab Giai đoạn lâm sàng 0–I\n- Để xác định 0–I cần ==EUS, CLVT và PET/CT== nhằm tránh đánh giá sai độ xâm lấn hoặc di căn hạch {{BHNgTH tr.174}}\n- cT1a-EP/LPM: không hết chu vi, hoặc hết chu vi nhưng ≤5 cm: cắt u qua nội soi; hết chu vi và >5 cm: phẫu thuật hoặc hóa xạ trị hoặc xạ trị điều trị {{BHNgTH tr.175}}\n- cT1a-MM: không hết chu vi: cắt u qua nội soi; hết chu vi: chịu được mổ thì phẫu thuật hoặc hóa xạ trị điều trị, không mổ được thì hóa xạ trị hoặc xạ trị điều trị {{BHNgTH tr.175}}\n- cT1bN0M0: chịu được mổ thì phẫu thuật hoặc hóa xạ trị điều trị; không mổ được thì hóa xạ trị hoặc xạ trị điều trị {{BHNgTH tr.175}}\n- Sau cắt u qua nội soi phải đối chiếu bệnh phẩm với giai đoạn; nếu tiến xa hơn thì điều trị tích cực hơn (cắt thực quản, xạ trị…) {{BHNgTH tr.174}}\n@@tab Giai đoạn II–III\n- Tổng trạng cho phép: ==cắt thực quản thường được ưu tiên hơn hóa xạ trị điều trị== {{BHNgTH tr.176}}\n- ==Điều trị tân hỗ trợ trước mổ có kết quả sống lâu dài tốt hơn mổ trước== {{BHNgTH tr.176}}\n- Xâm lấn ≤cT3r: ưu tiên hóa trị tân hỗ trợ 3 thuốc (docetaxel, cisplatin, 5-FU/capecitabine); cT3br: cân nhắc hóa xạ trị trước mổ {{BHNgTH tr.176}}\n- Lưu đồ: chịu được mổ thì hóa trị (hóa xạ trị) rồi phẫu thuật rồi điều trị hỗ trợ sau mổ; hoặc phẫu thuật rồi hóa trị; hoặc hóa xạ trị điều trị {{BHNgTH tr.175}}\n- Không mổ được nhưng chịu được hóa xạ trị: hóa xạ trị điều trị, đáp ứng hoàn toàn thì theo dõi/hóa trị, còn u hoặc tái phát thì điều trị cứu vãn; không mổ và không hóa xạ được: xạ trị hoặc hóa trị hoặc điều trị nâng đỡ {{BHNgTH tr.175}}\n- **Cứu vãn (salvage)**: sau hóa xạ trị u nhỏ lại nhưng không đáp ứng hoàn toàn, nếu được có thể cắt u hoặc cắt u qua nội soi {{BHNgTH tr.176}}\n@@tab Giai đoạn IVA, IVB\n- IVA, tổng trạng tốt: hóa xạ trị, xạ trị hoặc hóa trị; đáp ứng hoàn toàn thì hóa trị/theo dõi; còn u thì phẫu thuật, hóa trị hoặc điều trị nâng đỡ {{BHNgTH tr.176}}\n- IVA, tổng trạng kém: xạ trị hoặc điều trị nâng đỡ {{BHNgTH tr.176}}\n- IVB tương tự IVA nhưng u gần như không còn cắt được; tổng trạng tốt không tắc nghẽn thì hóa trị, có tắc nghẽn thì hóa xạ trị hoặc hóa trị; tổng trạng kém: điều trị nâng đỡ {{BHNgTH tr.176}}\n@@end\n\n### Biến chứng và các điểm cần theo dõi liên quan đến điều trị\n- Giáo trình không có mục riêng về biến chứng phẫu thuật cắt thực quản; chỉ nêu các điểm sau\n- Cắt u qua nội soi: nguy cơ sót mô u (R1 hoặc R2) nên phải đánh giá bệnh phẩm đúng tiêu chuẩn {{BHNgTH tr.172}} {{BHNgTH tr.174}}\n- McKeown: miệng nối ở cổ nên nếu xì rò thì hạn chế nhiễm trùng trung thất {{BHNgTH tr.172}}\n- Nội soi/robot giảm biến chứng phổi so với mổ mở ngực; vì vậy chức năng hô hấp là điều kiện tiền phẫu bắt buộc {{BHNgTH tr.169}} {{BHNgTH tr.174}}\n- Tắc nghẽn do u tiến triển: mở nuôi ăn (ưu tiên mở hỗng tràng nếu u còn cắt được) {{BHNgTH tr.174}}\n\n## 8. Tiên lượng – Dự phòng / theo dõi\n\n### Tiên lượng\n- Giai đoạn II–III điều trị: hóa trị tân hỗ trợ 3 thuốc + nội soi cắt thực quản nạo hạch 3 vùng cho sống thêm toàn bộ 5 năm ==60,6%==, sống không bệnh 5 năm ==57,2%== {{BHNgTH tr.177}}\n- Theo JES: sống toàn thể 5 năm sau cắt thực quản và hóa trị tân hỗ trợ là ==59,9%== {{BHNgTH tr.177}}\n\n### Theo dõi sau mổ\n- ==80–90% tái phát xảy ra trong 2 năm đầu== sau cắt thực quản {{BHNgTH tr.177}}\n- Lịch: mỗi 3 tháng trong 3 năm đầu, mỗi 6 tháng các năm sau; có thể điều chỉnh theo người bệnh và khối u {{BHNgTH tr.177}}\n\n| Khám/xét nghiệm | Mốc theo dõi (đọc từ bảng trong giáo trình) |\n|---|---|\n| Hỏi và khám bệnh | Mỗi mốc: 3, 6, 9, 12, 15, 18, 21, 24, 27, 30, 33, 36, 42, 48, 54, 60 tháng |\n| Nội soi thực quản – dạ dày | Các mốc trên, trừ 27 và 33 tháng |\n| Siêu âm đầu, cổ | Các mốc trên, trừ 27 và 33 tháng |\n| CLVT ngực–bụng–chậu | 6, 12, 18, 24, 30, 36, 48, 60 tháng |\n\n{{BHNgTH tr.177}}\n\n### Dự phòng\n- Giáo trình chỉ nêu yếu tố nguy cơ (thuốc lá, rượu, trào ngược/Barrett, béo phì), không có mục dự phòng hay tầm soát riêng {{BHNgTH tr.160}} {{BHNgTH tr.161}}\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] UTTQ ngoại khoa thi nhấn mạnh gì\n> - **Nhận diện**: nuốt khó tăng dần, sụt cân; tế bào gai ở Việt Nam, vị trí hay gặp ngực dưới {{BHNgTH tr.161}} {{BHNgTH tr.164}}\n> - **Chẩn đoán**: nội soi + sinh thiết 6–8 mẫu; CLVT cổ–ngực–bụng–chậu, EUS đo T, PET/CT không thường quy {{BHNgTH tr.164}} {{BHNgTH tr.167}} {{BHNgTH tr.169}}\n> - **Xử trí**: sớm thì ESD; II–III hóa trị tân hỗ trợ rồi cắt thực quản; Việt Nam ưu tiên McKeown nạo hạch 3 vùng {{BHNgTH tr.174}} {{BHNgTH tr.176}}\n\n@@tabs\n@@tab Nhận diện\n- Nuốt khó tăng dần, nuốt đau, sụt cân >10% trong 6 tháng {{BHNgTH tr.164}}\n- Thuốc lá, rượu (tế bào gai); Barrett, trào ngược, béo phì (biểu mô tuyến) {{BHNgTH tr.160}} {{BHNgTH tr.161}}\n- Dấu muộn: Horner, hạch thượng đòn, khàn tiếng {{BHNgTH tr.164}}\n- Xem [mục 4](#/n/ngoai-ung-thu-thuc-quan/4)\n@@tab Chẩn đoán\n- Nội soi + sinh thiết 6–8 mẫu là xác định; giai đoạn bằng CLVT, EUS, PET/CT {{BHNgTH tr.164}} {{BHNgTH tr.169}}\n- Bắt buộc đánh giá chức năng hô hấp trước cắt thực quản {{BHNgTH tr.169}}\n- Xem [mục 5](#/n/ngoai-ung-thu-thuc-quan/5) và [mục 6](#/n/ngoai-ung-thu-thuc-quan/6)\n@@tab Điều trị\n- 0–I: ESD cho u niêm mạc; vượt tiêu chuẩn thì phẫu thuật hoặc hóa xạ trị {{BHNgTH tr.175}}\n- II–III: hóa trị tân hỗ trợ (docetaxel, cisplatin, 5-FU/capecitabine), rồi cắt thực quản; cT3br: hóa xạ trị trước mổ {{BHNgTH tr.176}}\n- IV: hóa xạ trị/hóa trị, nâng đỡ; tắc nghẽn: mở hỗng tràng nuôi ăn {{BHNgTH tr.174}} {{BHNgTH tr.176}}\n- Xem [mục 7.3](#/n/ngoai-ung-thu-thuc-quan/7)\n@@tab Tiên lượng – Theo dõi\n- 80–90% tái phát trong 2 năm đầu; khám mỗi 3 tháng × 3 năm, sau đó mỗi 6 tháng {{BHNgTH tr.177}}\n- Sống toàn bộ 5 năm khoảng 60% với phác đồ đa mô thức giai đoạn II–III {{BHNgTH tr.177}}\n- Xem [mục 8](#/n/ngoai-ung-thu-thuc-quan/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Tỷ lệ tế bào gai / biểu mô tuyến | ==85% / 14%== | {{BHNgTH tr.160}} |\n| Số mẫu sinh thiết nên lấy | ==6–8== | {{BHNgTH tr.164}} |\n| Sụt cân báo động | ==>10% trong 6 tháng== | {{BHNgTH tr.164}} |\n| Thực quản cổ, ngực trên, ngực giữa, ngực dưới cách cung răng | ==15–<20, 20–<25, 25–<30, 30–<40 cm== | {{BHNgTH tr.161}} |\n| Giá trị chẩn đoán giai đoạn (mọi phương tiện) | ==80–90%== | {{BHNgTH tr.165}} |\n| Hạch di căn trên CLVT (JES) | ==trục ngắn ≥6 mm== | {{BHNgTH tr.167}} |\n| Góc Picus xâm lấn động mạch chủ | ==≥110° trên ≥10 mm; 90–110° trên ≥20 mm== | {{BHNgTH tr.166}} |\n| N1 / N2 / N3 | ==1–2 / 3–6 / ≥7 hạch== | {{BHNgTH tr.170}} |\n| Hóa xạ trị điều trị | ==≥50 Gy== | {{BHNgTH tr.174}} |\n| Tái phát sớm | ==80–90% trong 2 năm đầu== | {{BHNgTH tr.177}} |\n| Sống toàn bộ / không bệnh 5 năm (phác đồ II–III) | ==60,6% / 57,2%== | {{BHNgTH tr.177}} |\n| Sống toàn thể 5 năm theo JES | ==59,9%== | {{BHNgTH tr.177}} |\n\n> [!warn] Bẫy thi thường gặp\n> - **EMR ít dùng, ESD được dùng nhiều**; cả hai đều chỉ cho u sớm {{BHNgTH tr.171}} {{BHNgTH tr.172}}\n> - **cT3r và cT3br**: chỉ cT3br phải cân nhắc hóa xạ trị trước mổ; T4a/T4b chỉ dùng ở pTNM, lâm sàng chỉ có cT4 {{BHNgTH tr.166}} {{BHNgTH tr.176}}\n> - **PET/CT không phải xét nghiệm thường quy** để phân giai đoạn; EUS chính xác nhất cho T, CLVT là phương tiện đầu tay cho di căn xa {{BHNgTH tr.167}} {{BHNgTH tr.169}}\n> - **Mở nuôi ăn khi u còn cắt được**: chọn mở hỗng tràng, giữ dạ dày để tạo hình {{BHNgTH tr.174}}\n> - **McKeown** là 3 thì (ngực, bụng, cổ), miệng nối ở cổ; **Ivor-Lewis** là 2 thì (bụng, ngực), miệng nối trong ngực {{BHNgTH tr.172}} {{BHNgTH tr.173}}\n> - Giáo trình chỉ trình bày ung thư tế bào gai; Siewert II và III không bàn {{BHNgTH tr.162}} {{BHNgTH tr.170}}\n\n@@fold Nguồn tài liệu\n- **BHNgTH** Giáo trình Bệnh học ngoại khoa tiêu hóa 2025, chương Ung thư thực quản, tr.160–177 (số trang PDF; sách in tr.151–168). Các hình lưu đồ điều trị (hình 12–15), bảng cTNM/pTNM và bảng theo dõi là ảnh, đọc từ ảnh trang\n- **TCBN**: không dùng\n@@end\n\n@@fold Nguồn ngoài\n- Notion: không dùng. Trang \"Ung thư thực quản\" trong Notion chỉ có ở vùng \"TLHT - share\", ngoài vùng TNK’s Notebook cho phép đọc, nên không đưa vào bài.\n- Không dùng nguồn ngoài nào khác. Những điều giáo trình không nêu (liều thuốc cụ thể, thang điểm đánh giá khả năng mổ, danh sách biến chứng cắt thực quản, tầm soát) cũng không có trong bài.\n@@end\n\n@@fold Tự kiểm tra\n- Tỷ lệ các type mô học của UTTQ? :: Tế bào gai 85%, biểu mô tuyến 14%; Việt Nam chủ yếu tế bào gai\n- Hai yếu tố nguy cơ xác nhận rõ của ung thư tế bào gai thực quản? :: Hút thuốc lá và uống rượu\n- Dấu hiệu lâm sàng chính của UTTQ? :: Nuốt khó tăng dần (đặc rồi đến lỏng), nuốt đau, sụt cân >10% trong 6 tháng\n- Chẩn đoán xác định UTTQ bằng gì? :: Nội soi thực quản – dạ dày kèm sinh thiết, nên lấy 6–8 mẫu\n- Phương tiện chính xác nhất đánh giá mức xâm lấn T? :: Siêu âm qua nội soi (EUS)\n- PET/CT dùng khi nào? :: Không thường quy; khi nghi di căn hạch hoặc di căn xa nhưng chưa rõ\n- Ba vị trí di căn xa cần loại trừ bằng CLVT? :: Gan, phổi, tuyến thượng thận\n- cT3r và cT3br khác nhau thế nào? :: cT3r: không bằng chứng xâm lấn mô lân cận (cắt được); cT3br: chưa loại trừ được xâm lấn, ranh giới cắt được\n- Phẫu thuật ưu tiên tại Việt Nam? :: Nội soi ngực–bụng cắt thực quản kiểu McKeown, nạo hạch 3 vùng\n- McKeown và Ivor-Lewis khác nhau thế nào? :: McKeown 3 thì (ngực, bụng, cổ), miệng nối ở cổ; Ivor-Lewis 2 thì (bụng, ngực), miệng nối trong ngực\n- Điều trị ưu tiên giai đoạn II–III ≤cT3r? :: Hóa trị tân hỗ trợ 3 thuốc (docetaxel, cisplatin, 5-FU/capecitabine) rồi cắt thực quản\n- Khi mở nuôi ăn mà u còn cắt được thì chọn gì? :: Mở hỗng tràng, để giữ dạ dày nguyên vẹn cho việc tạo hình sau này\n- Lịch theo dõi sau mổ? :: Mỗi 3 tháng trong 3 năm đầu, mỗi 6 tháng sau đó; 80–90% tái phát trong 2 năm đầu\n@@end"}, {"kind": "disease", "disease": "ung-thu-truc-trang", "short": "Ung thư trực tràng", "group": "", "section": 0, "order": 23, "khung": [], "id": "ngoai-ung-thu-truc-trang", "title": "Ung thư trực tràng (ngoại khoa)", "layer": "benh", "module": "ngoai-tong-quat", "tags": ["ngoại khoa", "tiêu hóa", "trực tràng", "TME", "mạc treo trực tràng", "MRF", "cắt trước thấp", "bảo tồn cơ thắt", "Miles", "hóa xạ tân hỗ trợ", "thăm trực tràng", "CEA"], "source": "BHNgTH tr.238–264 (chương Ung thư trực tràng); Notion [BHNgK] Ung thư trực tràng", "body": "> [!key] Ung thư trực tràng (UTTT) trong một nhìn\n> - Trực tràng dài khoảng 15 cm nhưng chiếm gần 40% ung thư đại-trực tràng; triệu chứng không đặc hiệu, dễ nhầm trĩ, kiết lỵ {{BHNgTH tr.238}} {{BHNgTH tr.248}}\n> - Giải phẫu quyết định phẫu thuật: u ở 1/3 dưới, giữa hay trên cách rìa hậu môn bao xa, và mạc treo trực tràng có còn nguyên khi cắt hay không {{BHNgTH tr.243}} {{BHNgTH tr.244}}\n> - ==Thăm trực tràng + nội soi sinh thiết + MRI chậu== là bộ ba chẩn đoán và phân giai đoạn; MRI cho biết MRF (dương khi ≤ 1 mm) {{BHNgTH tr.249}} {{BHNgTH tr.250}}\n> - Điều trị đa mô thức, phẫu thuật là chủ yếu: cắt toàn bộ mạc treo trực tràng (TME), ưu tiên bảo tồn cơ thắt; Miles chỉ còn cho u thấp xâm lấn cơ nâng/cơ thắt {{BHNgTH tr.256}} {{BHNgTH tr.261}}\n> - Giai đoạn II–III: hóa xạ trị tân hỗ trợ toàn phần (TNT) là hướng ưu tiên theo NCCN {{BHNgTH tr.262}}\n> - Phần hóa trị, xạ trị, phác đồ chi tiết xem trang Ung bướu: [Ung thư đại trực tràng (module Ung bướu)](#/n/ung-thu-daitruc-trang)\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Phần lớn UTĐTT là \"lẻ tẻ\" (sporadic); hội chứng di truyền hiếm nhưng nguy cơ rất cao {{BHNgTH tr.239}}\n> - Ung thư biểu mô tuyến chiếm gần 85%; thể loét gặp nhiều nhất {{BHNgTH tr.246}} {{BHNgTH tr.247}}\n> - Lan theo chiều cao chậm, theo chu vi nhanh; hạch trạm đầu nằm trong mạc treo trực tràng {{BHNgTH tr.244}} {{BHNgTH tr.247}}\n\n### Định nghĩa & dịch tễ\n- Số liệu thường gộp với ung thư đại tràng; GLOBOCAN 2022: UTĐTT đứng thứ 3 về ca mới (hơn 1,9 triệu), thứ 2 về tử vong ung thư {{BHNgTH tr.238}}\n- Việt Nam 2022: 16.835 ca mới (9,3% ung thư, hạng 4), 8.454 ca tử vong (hạng 5); nam 53%, nữ 47%; thường trên 50 tuổi nhưng đang trẻ hóa {{BHNgTH tr.238}}\n- Việt Nam chưa có chương trình tầm soát quốc gia; tỷ lệ mắc có xu hướng tăng {{BHNgTH tr.238}}\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Nguy cơ cao (liên quan sàng lọc)\n- Hội chứng di truyền: Lynch (HNPCC, khoảng 3% ca, gen MLH1/MSH2/MSH6/PMS2), FAP (gen APC; không điều trị thì 90% bị ung thư trước 45 tuổi), MAP, Peutz-Jeghers, polyp thiếu niên {{BHNgTH tr.239}} {{BHNgTH tr.240}}\n- Tiền sử cá nhân/gia đình: ung thư mới sau mổ 1,5–3% trong 5 năm; polyp tuyến lớn (>1 cm), nhung mao hoặc loạn sản cao RR 3,5–6,5; người thân bậc một mắc UTĐTT nguy cơ gấp khoảng 2 lần {{BHNgTH tr.240}}\n- Viêm ruột mạn: viêm loét đại tràng toàn bộ tăng 5–15 lần, bắt đầu tăng sau 8–10 năm, đến 30% sau 30 năm {{BHNgTH tr.240}}\n- Chiếu xạ bụng-chậu, xơ nang {{BHNgTH tr.240}} {{BHNgTH tr.241}}\n@@tab Nguy cơ thấp hoặc chưa rõ\n- Béo phì, đái tháo đường, thịt đỏ/thịt chế biến (WHO: nhóm 2A và nhóm 1), hút thuốc, rượu (≥ 2 ly/ngày) {{BHNgTH tr.242}}\n- Ngồi lâu, mất cân bằng vi sinh, cắt túi mật (dữ liệu chưa thống nhất) {{BHNgTH tr.242}} {{BHNgTH tr.243}}\n- Từ Notion (giáo trình cũ): yếu tố giảm nguy cơ gồm rau, chất xơ, canxi, folate, aspirin/NSAID, vận động; Crohn nguy cơ ung thư hóa 1/500–1/200 {{Notion}}\n@@end\n\n### Giải phẫu ứng dụng phẫu thuật\n> [!key] Điểm cần nhớ cho phẫu thuật viên\n> - Trực tràng dài khoảng 15 cm, nằm sát xương cùng-cụt; ống hậu môn theo phẫu thuật: từ bờ hậu môn đến vòng cơ mu-trực tràng, 4–5 cm {{BHNgTH tr.243}}\n> - ==Mạc treo trực tràng== là mô mỡ chứa mạch, bạch huyết, hạch, bọc bởi mạc riêng; lấy trọn nguyên vẹn là yêu cầu bắt buộc của TME {{BHNgTH tr.244}}\n\n@@tabs\n@@tab Chia đoạn\n- Chia 2 phần: trực tràng trong ổ bụng và ngoài ổ bụng, ngăn cách bởi nếp phúc mạc, cách rìa hậu môn 7–9 cm {{BHNgTH tr.243}}\n- Chia 3 phần: 1/3 dưới 0–5 cm; 1/3 giữa 6–10 cm; 1/3 trên 11–15 cm tính từ bờ hậu môn {{BHNgTH tr.243}}\n@@tab Mạc treo và các mạc\n- Các mạc chậu: mạc nội chậu, mạc trước xương cùng, mạc riêng trực tràng, dây chằng bên, mạc Waldeyer, mạc Denonvilliers {{BHNgTH tr.244}}\n- Heald (1982): mạc riêng bao mạc treo; giữa mạc treo và xương cùng là khoang lỏng lẻo gần như vô mạch (\"holy plane\"), thấy rõ khi phẫu tích {{BHNgTH tr.244}}\n- Giới hạn: sau-bên dính xương cùng; trước là phúc mạc (trên) và mạc Denonvilliers (dưới); dưới mỏng dần và hết ở chỗ nối ống hậu môn; hai bên là dây chằng bên và đám rối hạ vị {{BHNgTH tr.244}}\n- Hạch trạm đầu trong ung thư trực tràng nằm ngay trong mạc treo trực tràng {{BHNgTH tr.244}}\n@@tab Mạch máu và bạch huyết\n- Động mạch: trực tràng trên (từ mạc treo tràng dưới, nuôi thành sau và 1/3 trên), giữa (từ hạ vị, 1/3 giữa), dưới (từ thẹn trong, 1/3 dưới), cùng giữa {{BHNgTH tr.244}} {{BHNgTH tr.245}}\n- Tĩnh mạch: trực tràng trên về tĩnh mạch cửa (thuận lợi cho di căn gan); giữa và dưới về tĩnh mạch chủ dưới qua hạ vị {{BHNgTH tr.245}}\n- Bạch huyết: 2/3 trên về hạch mạc treo tràng dưới và cạnh động mạch chủ; 1/3 dưới và trên đường lược theo hai hướng (mạc treo tràng dưới, chậu trong); dưới đường lược về hạch bẹn nông {{BHNgTH tr.245}}\n@@tab Thần kinh và cơ thắt\n- Bóng trực tràng do thần kinh thực vật chi phối; ống hậu môn do thần kinh gai sống (thần kinh hậu môn từ S3, S4: vận động cơ thắt, cảm giác quanh hậu môn) {{BHNgTH tr.245}}\n- Phó giao cảm từ S2–S4 đến đám rối hạ vị chi phối tạng niệu-sinh dục {{BHNgTH tr.245}}\n- Nhiều vị trí khi mổ dễ tổn thương thần kinh tự trị chậu, gây rối loạn đại tiện, tiểu tiện, sinh dục {{BHNgTH tr.246}}\n@@end\n\n### Giải phẫu bệnh – phân loại\n- Đại thể: chồi sùi, loét, thâm nhiễm, vòng nhẫn (thường phối hợp); thể loét hay gặp nhất {{BHNgTH tr.246}}\n- Vi thể (WHO): ung thư biểu mô tuyến gần 85%; còn lại tuyến nhầy, tế bào nhẫn, tế bào nhỏ, tế bào gai, tuyến gai, dạng tủy, không biệt hóa {{BHNgTH tr.247}}\n- Độ biệt hóa theo tỷ lệ tuyến hình thành: độ 1 trên 95%; độ 2 50–95%; độ 3 dưới 50%; độ 4 gần như không có tuyến {{BHNgTH tr.247}}\n\n### Diễn tiến tự nhiên – lan tràn\n- Tại chỗ: lan theo chiều cao chậm (khoảng 3–4 cm/năm), theo chu vi nhanh (6 tháng có thể được 1/4 chu vi) {{BHNgTH tr.247}}\n- Xâm lấn cơ quan lân cận: trước (âm đạo, tử cung hoặc tiền liệt tuyến, túi tinh, bàng quang), sau (xương cùng), hai bên (mỡ chậu hông-trực tràng, hố ngồi-trực tràng, cơ nâng hậu môn) {{BHNgTH tr.247}} {{BHNgTH tr.248}}\n- Hạch: lên theo động mạch trực tràng trên, hạch chậu, hạ vị; dưới đường lược theo hạch bẹn {{BHNgTH tr.248}}\n- Di căn xa: gan, phổi (qua tĩnh mạch mạc treo tràng dưới, cửa); cột sống qua tĩnh mạch chậu; não, buồng trứng {{BHNgTH tr.248}}\n- Từ Notion: tế bào ung thư hiếm lan bạch huyết xuống dưới u ở giai đoạn sớm (Dukes 1930; Gholigher: 2% ca Miles); đây là cơ sở của diện cắt dưới u ngắn lại {{Notion}}\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Triệu chứng đầu tiên thường nhẹ: chảy máu tiêu hóa dưới 60%, đổi thói quen đi cầu 43% {{BHNgTH tr.248}}\n> - ==Thăm trực tràng== xác định chẩn đoán khi u thấp và cho biết u có xâm lấn cơ thắt hay không {{BHNgTH tr.249}}\n\n### Triệu chứng cơ năng\n- Chảy máu tiêu hóa dưới: máu bầm lẫn phân, rỉ rả, ít khi ồ ạt {{BHNgTH tr.248}}\n- Đổi thói quen đi cầu (thường tiêu chảy); buốt mót hậu môn; đi nhiều lần, phân nhỏ dẹt, cảm giác đi không hết phân {{BHNgTH tr.248}}\n- Đau bụng khoảng 20% (chú ý cơn đau của tắc ruột) {{BHNgTH tr.248}}\n- Ít gặp: tiểu lắt nhắt, tiểu gấp, gắt (u xâm lấn bàng quang, tiền liệt tuyến); mệt, chán ăn, sụt cân (muộn); đau vùng chậu (xâm lấn thần kinh) {{BHNgTH tr.248}}\n- {r|Ỉa són, ỉa dầm dề thường báo hiệu u đã xâm lấn cơ nâng, cơ thắt hậu môn} {{BHNgTH tr.248}}\n\n### Thăm trực tràng\n> [!tip] Cần ghi lại khi thăm trực tràng\n> - Bờ dưới u cách rìa hậu môn bao nhiêu cm; vị trí theo chu vi (trước, sau, trái, phải hoặc theo kim đồng hồ); bờ trên nếu với tới {{BHNgTH tr.249}}\n> - U có xâm lấn cơ thắt không; kích thước (nếu sờ được cực trên); có chít hẹp lòng không {{BHNgTH tr.249}}\n> - Mức độ di động: gợi ý khả năng xâm lấn cơ quan lân cận {{BHNgTH tr.249}}\n\n- Thông tin này quyết định có làm được bảo tồn cơ thắt hay không (xem mục 7.3)\n- Từ Notion: u thấp tiếp cận được bằng ống soi cứng (khoảng 60 mm từ hậu môn) {{Notion}}\n\n### Biểu hiện di căn và biến chứng\n- Di căn: hạch bẹn, hạch thượng đòn trái (Troisier); gan to lổn nhổn, vàng da, bụng báng; ho, khó thở; đau xương cùng-cột sống; nhức đầu, ói {{BHNgTH tr.249}}\n- Biến chứng đến viện: {r|tắc ruột (thường nhất, tắc thấp hoặc quai kín), viêm phúc mạc do vỡ u hoặc vỡ đại tràng trên u, rò trực tràng-bàng quang (nam) hoặc trực tràng-âm đạo (nữ)} {{BHNgTH tr.249}}\n\n> [!red] Cần xử trí cấp\n> - Tắc ruột thấp hoặc tắc quai kín; dấu viêm phúc mạc toàn thể (vỡ u hoặc vỡ đại tràng ngay trên u, có thể ở manh tràng) {{BHNgTH tr.249}}\n> - Tài liệu không nêu chi tiết xử trí cấp cứu cho các biến chứng này\n\n## 5. Cận lâm sàng\n\n> [!key] Tóm tắt\n> - Nội soi + sinh thiết cho chẩn đoán; MRI chậu tốt nhất để đánh giá trước mổ, MRF, theo dõi tái phát {{BHNgTH tr.250}}\n> - CEA không dùng chẩn đoán, dùng để tiên lượng và theo dõi {{BHNgTH tr.251}} {{BHNgTH tr.252}}\n\n### Nội soi và hình ảnh\n@@tabs\n@@tab Nội soi\n- Xác định dạng đại thể, kích thước, có gây tắc không, khoảng cách bờ dưới u đến rìa hậu môn; sinh thiết {{BHNgTH tr.250}}\n- Soi toàn bộ khung đại tràng để tìm u đồng thời hoặc tổn thương kèm theo {{BHNgTH tr.250}}\n@@tab CLVT\n- Cho hình toàn khung chậu, liên quan với cơ quan lân cận, nhất là u tiến triển; dùng cản quang tĩnh mạch {{BHNgTH tr.250}}\n- Hạn chế: kém với u còn trong thành, xác định cân mạc treo kém, đánh giá hạch mạc treo kém (nhất là hạch dưới 1 cm) {{BHNgTH tr.250}}\n@@tab MRI chậu\n- Tốt nhất để đánh giá trước mổ và theo dõi tái phát; thấy được các lớp thành, hạch nhỏ 2–3 mm {{BHNgTH tr.250}}\n- ==MRF dương tính khi khoảng cách từ u hoặc hạch đến mạc riêng ≤ 1 mm==; MRF dự báo tái phát tại chỗ, nhất là sau TME {{BHNgTH tr.250}}\n- Báo cáo MRI gồm: hình thái, vị trí (bờ dưới u đến chỗ nối hậu môn-trực tràng, liên quan nếp phúc mạc), kích thước, cT, MRF, EMVI, cN, tumor deposit {{BHNgTH tr.250}} {{BHNgTH tr.251}}\n- cT3 chia a–d theo độ xâm lấn mỡ quanh trực tràng: dưới 1 mm; 1–5 mm; 5–15 mm; trên 15 mm {{BHNgTH tr.251}}\n- Từ Notion: MRI là phương tiện tốt nhất đánh giá xâm lấn cơ nâng và cơ thắt hậu môn {{Notion}}\n@@tab Siêu âm qua lòng trực tràng\n- An toàn, rẻ; tốt hơn MRI đánh giá xâm lấn thành ở u nhỏ, còn tại chỗ {{BHNgTH tr.251}}\n- Hạn chế: trường khảo sát nhỏ, không làm được khi u gây hẹp; khoảng 5% đánh giá giai đoạn muộn hơn thực tế; làm trước khi xạ trị tân hỗ trợ vì xơ sẹo làm giảm chính xác {{BHNgTH tr.251}}\n- MRI chính xác hơn cho hạch và CRM {{BHNgTH tr.251}}\n@@end\n\n### Xét nghiệm CEA\n- Độ nhạy thấp ở giai đoạn sớm, độ đặc hiệu thấp: ít giá trị chẩn đoán nguyên phát {{BHNgTH tr.251}}\n- CEA > 5 ng/ml tiên lượng xấu hơn cùng giai đoạn; giảm sau mổ phản ánh hiệu quả mổ; tăng liên tiếp sau mổ cần đánh giá lại đầy đủ; ASCO khuyến cáo thử trước và sau mổ {{BHNgTH tr.252}}\n\n### Giải phẫu bệnh, CRM, sinh học phân tử\n- Báo cáo GPB đủ: loại mô học, độ biệt hóa, pT, pN (số hạch lấy và số hạch di căn), diện cắt trên/dưới, CRM, xâm nhập mạch và thần kinh, tumor deposit, tumor budding, MMR/MSI, đáp ứng sau tân hỗ trợ {{BHNgTH tr.252}}\n- IHC: NCCN 2025 bắt buộc cho mọi ca UTTT lúc đánh giá ban đầu, để phát hiện dMMR/MSI (hướng liệu pháp miễn dịch) {{BHNgTH tr.253}}\n- CRM là yếu tố tiên lượng độc lập cho tái phát tại chỗ sau TME; chất lượng bệnh phẩm mạc treo chia tốt, trung bình, kém {{BHNgTH tr.253}}\n\n| Chất lượng mạc treo | Đặc điểm |\n|---|---|\n| Tốt | Nguyên vẹn, trơn láng, khiếm khuyết không sâu quá 5 mm, hình trụ, CRM rõ |\n| Trung bình | Khiếm khuyết vừa, chưa lộ cơ trực tràng, hình nón, CRM không rõ |\n| Kém | Khiếm khuyết lộ đến cơ trực tràng, không đánh giá được CRM |\n{{BHNgTH tr.253}}\n\n- Sinh học phân tử: RAS wild-type hoặc BRAF V600E (cetuximab/panitumumab); MSI-H/dMMR hoặc POLE/POLD1 (ức chế PD-1/PD-L1); MSI-H/dMMR tiên lượng tốt, giúp giảm hóa trị sau mổ giai đoạn II {{BHNgTH tr.254}}\n- ctDNA phát hiện bệnh tồn dư, dương tính thường trước hình ảnh 3–6 tháng; NCCN 1.2025 chưa khuyến cáo thường quy ngoài thử nghiệm {{BHNgTH tr.254}} {{BHNgTH tr.255}}\n\n### Phân giai đoạn (AJCC 8)\n@@tabs\n@@tab T – N – M\n| Ký hiệu | Định nghĩa |\n|---|---|\n| Tis | Carcinoma in situ (niêm mạc, lamina propria) |\n| T1 / T2 | Xâm lấn lớp dưới niêm / lớp cơ |\n| T3 | Vượt qua lớp cơ đến lớp dưới thanh mạc |\n| T4a / T4b | Xâm lấn lá phúc mạc tạng / cơ quan lân cận (u dưới nếp phúc mạc không có T4a) |\n| N1 / N2 | 1–3 hạch vùng / từ 4 hạch vùng (N2a 4–6, N2b từ 7) |\n| N1c | Nhân u trong mỡ quanh ruột, không có hạch vùng |\n| M1a / M1b / M1c | 1 tạng hoặc vùng / nhiều hơn 1 tạng / phúc mạc |\n{{BHNgTH tr.255}}\n@@tab Nhóm giai đoạn\n| Giai đoạn | T N M |\n|---|---|\n| 0 | Tis N0 M0 |\n| I | T1–T2 N0 M0 |\n| IIA / IIB / IIC | T3 / T4a / T4b, N0 M0 |\n| IIIA | T1–2 N1/N1c; T1 N2a |\n| IIIB | T3–4a N1/N1c; T2–3 N2a; T1–2 N2b |\n| IIIC | T4a N2a; T3–4a N2b; T4b N1–2 |\n| IVA / IVB / IVC | Bất kỳ T N, M1a / M1b / M1c |\n{{BHNgTH tr.256}}\n@@end\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Tiêu chuẩn chẩn đoán\n> - ==Chẩn đoán xác định: sinh thiết qua nội soi có ung thư biểu mô==; thăm trực tràng đủ để nghĩ tới khi u thấp {{BHNgTH tr.249}} {{BHNgTH tr.250}}\n> - Chẩn đoán giai đoạn: MRI chậu (cT, cN, MRF, EMVI) + hình ảnh tìm di căn xa; kết quả mổ cho pTNM và CRM {{BHNgTH tr.250}} {{BHNgTH tr.252}}\n\n| Bệnh | Điểm giống | Cách phân biệt |\n|---|---|---|\n| Trĩ | Đi cầu ra máu; UTTT gây đi cầu khó có thể gây trĩ có triệu chứng | Có thể có cả hai: phải thăm trực tràng và soi, không dừng ở trĩ |\n| Viêm loét đại-trực tràng, hội chứng lỵ | Đi cầu ra máu, đổi thói quen đi cầu | Thăm trực tràng, nội soi, sinh thiết |\n| Polyp trực tràng lành tính | Triệu chứng tương tự; xem như UTTT giai đoạn sớm | Nghĩ polyp ung thư hóa khi lớn, chảy máu, bề mặt sần sùi, kém di động |\n{{BHNgTH tr.249}}\n\n- Trực tràng thấp, sờ và soi được nên phân biệt được trong hầu hết trường hợp {{BHNgTH tr.249}}\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n- Điều trị đa mô thức (phẫu thuật, hóa trị, xạ trị, nâng đỡ); phẫu thuật là chủ yếu {{BHNgTH tr.256}}\n- Cắt bỏ triệt để u, bảo tồn tối đa chức năng hậu môn, sinh dục, tiết niệu {{BHNgTH tr.261}}\n- Khác với đại tràng: trọng tâm là ==kiểm soát tái phát tại chỗ==; MRF là tiêu chí chính chỉ định xạ trị trước mổ ở hầu hết giai đoạn {{BHNgTH tr.257}}\n\n### 7.2 Các phương pháp\n@@tabs\n@@tab Cắt u tại chỗ\n- Chỉ định: T1 N0, độ mô học 1–2, không xâm lấn mạch; thuận lợi khi u dưới 30% chu vi, dưới 3 cm, diện cắt trên 2 mm, di động, u thấp {{BHNgTH tr.259}}\n- Cách làm: cắt polyp, EMR, ESD qua nội soi; cắt qua ngả hậu môn (TAE, Fairve); TEM/TEO/TAMIS {{BHNgTH tr.259}}\n- Ngả sau (Kraske, York-Mason): ít dùng vì xâm lấn hơn, nhiều biến chứng {{BHNgTH tr.260}}\n@@tab Cắt trước (bảo tồn cơ thắt)\n- Nguyên tắc: cắt rộng u, hạch vùng và cơ quan xâm lấn; TME; phục hồi lưu thông ruột nếu có thể; có thể nội soi {{BHNgTH tr.260}}\n- Dùng cho u 1/3 trên và giữa: cắt đại tràng chậu hông và trực tràng, diện cắt trên và dưới ít nhất 2 cm; cắt dưới nếp phúc mạc gọi là cắt trước thấp {{BHNgTH tr.260}}\n- U thấp chưa xâm lấn cơ thắt: cắt trước cực thấp (nối ống hậu môn) hoặc cắt gian cơ thắt; miệng nối tận bên, túi J hoặc tạo hình đại tràng {{BHNgTH tr.260}}\n- ==Chỉ định đưa ruột trên dòng bảo vệ miệng nối==: miệng nối thấp (dưới 4 cm), ruột căng, béo phì, xạ trị trước đó, ức chế miễn dịch, hoặc phẫu thuật viên thấy không an toàn {{BHNgTH tr.260}}\n@@tab Miles (APR)\n- Lấy toàn bộ trực tràng, mạc treo, hạch, mỡ, cơ nâng và cơ thắt hậu môn; hậu môn nhân tạo vĩnh viễn ở hố chậu trái (Miles 1908) {{BHNgTH tr.261}}\n- Chỉ định thu hẹp: u thấp xâm lấn cơ nâng, cơ thắt; u xâm lấn rộng; u sát rìa hậu môn; ung thư ống hậu môn {{BHNgTH tr.261}}\n- Từ Notion: tai biến chảy máu, nhiễm khuẩn vùng tầng sinh môn có thể nguy hiểm; Golligher dự đoán Miles chỉ còn khoảng 20% ca {{Notion}}\n@@tab Nội soi, robot, TaTME\n| Tiêu chí | Nội soi | Robot | TaTME |\n|---|---|---|---|\n| Tiếp cận | Từ bụng xuống | Từ bụng (robot) | Từ hậu môn lên + từ bụng |\n| CRM dương | 7–10% | 5–8% | 3–7% |\n| Cắt trọn TME | 85–90% | 90–95% | trên 90% |\n| Chuyển mổ mở | 10–15% | 4–8% | dưới 5% |\n| Chi phí | Trung bình | Cao (gấp 2–3 lần nội soi) | Cao, cần đào tạo |\n{{BHNgTH tr.261}}\n- TaTME hữu ích cho u rất thấp (dưới 5 cm từ hậu môn), chậu hẹp, béo phì {{BHNgTH tr.261}}\n@@end\n\n### 7.3 Chỉ định – hướng xử trí\n\n> [!key] Xử trí theo giai đoạn và vị trí\n> - Tis–T1 N0 nguy cơ thấp: cắt tại chỗ (nội soi hoặc ngả hậu môn) {{BHNgTH tr.256}}\n> - Rất sớm nguy cơ cao (biệt hóa kém, xâm lấn mạch/thần kinh, xâm lấn sâu, diện cắt nghi ngờ): phẫu thuật ngả bụng tiêu chuẩn {{BHNgTH tr.257}}\n> - T1–2 N0: phẫu thuật cắt toàn bộ mạc treo trực tràng là triệt căn, chủ đạo {{BHNgTH tr.257}}\n> - Tiến triển (T4, N+, MRF dương, EMVI dương, không cắt được): hóa xạ tân hỗ trợ rồi phẫu thuật nếu cắt được {{BHNgTH tr.258}}\n\n| Tình huống | Hướng xử trí (theo BYT, lưu đồ 1) |\n|---|---|\n| cT1 N0 M0, biệt hóa cao/vừa | Cắt u qua ngả hậu môn, diện cắt âm, rồi theo dõi |\n| cT2 N0 M0 hoặc cT3 N0 M0 trực tràng cao | Cắt trực tràng + nạo vét hạch; nếu pT ≥ 3 hoặc N > 0: hóa xạ bổ trợ |\n| cT4 N0 M0 trực tràng cao | Hóa xạ tân bổ trợ, rồi cắt trực tràng + nạo vét hạch |\n| cT ≥ 3 trực tràng giữa-dưới hoặc N > 0 | Sơ đồ BYT không vẽ tiếp nhánh này; NCCN: hóa xạ tân hỗ trợ rồi phẫu thuật (xem dưới) |\n{{BHNgTH tr.257}}\n\n- NCCN 2025 (u cách rìa hậu môn dưới 12 cm): u cao, T ≤ 3, N0, nguy cơ thấp (MRF âm, EMVI âm, G1–2) có thể phẫu thuật PME/TME ngay; T4, N+, MRF dương, EMVI dương, hạch chậu bên thì hóa xạ tân hỗ trợ; u thấp làm TME; hóa trị bổ trợ nếu có chỉ định {{BHNgTH tr.258}}\n- Giai đoạn trung gian: ESMO cho mổ ngay nhóm T3a/b không xâm lấn mạch ngoại thành, trực tràng cao, còn lại tân hỗ trợ; BYT tương tự nhưng chưa đề cập MRF {{BHNgTH tr.257}}\n\n> [!tip] Chọn bảo tồn cơ thắt hay Miles\n> - Dựa vào thăm trực tràng và MRI: u cách rìa hậu môn bao xa, có xâm lấn cơ nâng/cơ thắt không, MRF {{BHNgTH tr.249}} {{BHNgTH tr.250}}\n> - Chưa xâm lấn cơ thắt: bảo tồn (cắt trước thấp, cực thấp, gian cơ thắt); đã xâm lấn: Miles {{BHNgTH tr.260}} {{BHNgTH tr.261}}\n> - Từ Notion: diện cắt dưới u an toàn 2 cm (William 1984), riêng T1–2 N0 chỉ cần 1 cm; miệng nối thấp tới khoảng 3 cm cách rìa hậu môn {{Notion}}\n\n### Hóa xạ trị tiền phẫu và theo dõi đáp ứng\n- Hóa xạ tân hỗ trợ toàn phần (TNT): làm toàn bộ hóa và xạ trước mổ; mục tiêu tăng đáp ứng, tăng bảo tồn cơ thắt, giảm tái phát; NCCN khuyến cáo ưu tiên cho giai đoạn II–III {{BHNgTH tr.262}}\n- Đáp ứng hoàn toàn: lâm sàng (cCR: khám, nội soi, hình ảnh không thấy u) hoặc mô bệnh học (pCR); một số người có thể tránh mổ và theo dõi-chờ đợi (watch and wait) {{BHNgTH tr.262}}\n- Nghiên cứu nêu trong sách: RAPIDO, PRODIGE 23, OPRA; Việt Nam cCR 31,4% (BV 108, 2024) {{BHNgTH tr.262}}\n- Liều, phác đồ hóa xạ cụ thể: giáo trình không nêu; xem trang Ung bướu\n\n### Biến chứng cần lưu ý\n- Tổn thương thần kinh tự trị chậu: rối loạn đại tiện, tiểu tiện, sinh dục {{BHNgTH tr.246}}\n- Xì/ nguy cơ miệng nối thấp: là lý do làm hậu môn nhân tạo bảo vệ (xem 7.2) {{BHNgTH tr.260}}\n- Từ Notion: cắt trực tràng, nối thấp tận-tận làm suy giảm chức năng hậu môn-trực tràng (đi cầu gấp, són phân, tiêu không tự chủ); Kraske có nhiều biến chứng nặng (nhiễm trùng, xì miệng nối, tái phát sớm) {{Notion}}\n- Giáo trình mới không có mục biến chứng sau mổ riêng và không nêu tỷ lệ xì miệng nối\n\n## 8. Tiên lượng – Dự phòng\n\n### Tiên lượng\n| Giai đoạn | Sống 5 năm (theo giáo trình) |\n|---|---|\n| Khu trú tại thành ruột | 90% |\n| Xâm lấn tại chỗ hoặc di căn hạch | 73,8% |\n| Di căn xa | 18% |\n| Chung | 67% (số liệu 2014–2020) |\n{{BHNgTH tr.263}}\n\n- Nhật Bản: sống còn I 90,6%; II 83,1%; IIIa 73%; IIIb 53,5%; IV 14,8%; chung 71,3% {{BHNgTH tr.263}}\n- Yếu tố tiên lượng: CEA > 5 ng/ml xấu hơn; MRF và CRM liên quan tái phát tại chỗ; đạt CR tiên lượng tốt hơn; MSI-H/dMMR tiên lượng tốt {{BHNgTH tr.252}} {{BHNgTH tr.254}} {{BHNgTH tr.262}}\n\n### Theo dõi sau điều trị\n- CEA trước và sau mổ; CEA giảm phản ánh hiệu quả mổ, tăng liên tiếp cần đánh giá lại; MRI dùng theo dõi tái phát và đánh giá sau tân hỗ trợ {{BHNgTH tr.250}} {{BHNgTH tr.252}}\n- Sau điều trị bảo tồn bằng watch and wait: theo dõi cCR bằng khám, nội soi, hình ảnh {{BHNgTH tr.262}}\n- Lịch theo dõi cụ thể (tần suất, nội soi sau mổ): giáo trình không nêu; Notion cũng không nêu lịch sau mổ\n\n### Dự phòng và tầm soát\n- Phương tiện: FOBT/FIT (dương tính thì soi toàn bộ đại tràng), DNA phân, soi trực tràng, nội soi toàn bộ đại tràng (tốt nhất), CT colonography {{BHNgTH tr.263}} {{BHNgTH tr.264}}\n- Nguy cơ trung bình: 45–75 tuổi không triệu chứng; nguy cơ cao: tiền sử gia đình, đa polyp gia đình, viêm ruột, u tuyến, từ 40 tuổi hoặc trước 10 năm so với tuổi khởi phát trong gia đình; nguy cơ cao cần soi toàn bộ đại tràng {{BHNgTH tr.264}}\n- Không cần tầm soát trên 75 tuổi hoặc tuổi thọ kỳ vọng dưới 10 năm {{BHNgTH tr.264}}\n- Từ Notion: khoảng cách theo dõi soi toàn bộ 10 năm; FS, DCBE, CTC mỗi 5 năm; FOBT mỗi năm {{Notion}}\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] UTTT thi nhấn mạnh gì\n> - **Nhận diện**: đi cầu ra máu bầm, đổi thói quen đi cầu, mót rặn; thăm trực tràng ghi bờ dưới u, cơ thắt, di động {{BHNgTH tr.248}} {{BHNgTH tr.249}}\n> - **Chẩn đoán**: nội soi sinh thiết; MRI chậu cho cT, cN, MRF; CEA để theo dõi {{BHNgTH tr.250}} {{BHNgTH tr.252}}\n> - **Xử trí**: TME; bảo tồn cơ thắt khi chưa xâm lấn cơ thắt; Miles khi đã xâm lấn; MRF dương hoặc giai đoạn II–III thì hóa xạ trước mổ {{BHNgTH tr.257}} {{BHNgTH tr.261}} {{BHNgTH tr.262}}\n\n@@tabs\n@@tab Nhận diện\n- Chảy máu tiêu hóa dưới 60%, đổi thói quen đi cầu 43%, đau bụng 20% {{BHNgTH tr.248}}\n- Ỉa són, ỉa dầm dề: xâm lấn cơ nâng, cơ thắt {{BHNgTH tr.248}}\n- Biến chứng hay gặp nhất: tắc ruột {{BHNgTH tr.249}}\n- Xem [mục 4](#/n/ngoai-ung-thu-truc-trang/4)\n@@tab Chẩn đoán\n- MRI: tốt nhất trước mổ; MRF dương khi ≤ 1 mm {{BHNgTH tr.250}}\n- Siêu âm qua lòng trực tràng: u nhỏ tại chỗ, làm trước xạ trị {{BHNgTH tr.251}}\n- CEA > 5 ng/ml tiên lượng xấu {{BHNgTH tr.252}}\n- Xem [mục 5](#/n/ngoai-ung-thu-truc-trang/5) và [mục 6](#/n/ngoai-ung-thu-truc-trang/6)\n@@tab Điều trị\n- Cắt u tại chỗ: T1 N0, G1–2, dưới 3 cm, dưới 30% chu vi {{BHNgTH tr.259}}\n- Cắt trước: u 1/3 trên-giữa, diện cắt ít nhất 2 cm, TME; ruột trên dòng khi miệng nối dưới 4 cm {{BHNgTH tr.260}}\n- Miles: u thấp xâm lấn cơ nâng, cơ thắt; hậu môn nhân tạo vĩnh viễn {{BHNgTH tr.261}}\n- TNT ưu tiên cho giai đoạn II–III {{BHNgTH tr.262}}\n- Xem [mục 7.3](#/n/ngoai-ung-thu-truc-trang/7)\n@@tab Tiên lượng – Dự phòng\n- Sống 5 năm: 90% / 73,8% / 18% theo khu trú / hạch / di căn xa {{BHNgTH tr.263}}\n- Tầm soát: 45–75 tuổi; nguy cơ cao từ 40 tuổi, soi toàn bộ đại tràng {{BHNgTH tr.264}}\n- Xem [mục 8](#/n/ngoai-ung-thu-truc-trang/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Chiều dài trực tràng / ống hậu môn (phẫu thuật) | ==15 cm / 4–5 cm== | {{BHNgTH tr.243}} |\n| Chia 3 đoạn (cách rìa hậu môn) | ==0–5 / 6–10 / 11–15 cm== | {{BHNgTH tr.243}} |\n| Nếp phúc mạc cách rìa hậu môn | ==7–9 cm== | {{BHNgTH tr.243}} |\n| Ung thư biểu mô tuyến | ==gần 85%== | {{BHNgTH tr.247}} |\n| Lan theo chiều cao mỗi năm | ==3–4 cm== | {{BHNgTH tr.247}} |\n| Chảy máu tiêu hóa dưới / đổi thói quen đi cầu | ==60% / 43%== | {{BHNgTH tr.248}} |\n| MRF dương | ==≤ 1 mm== | {{BHNgTH tr.250}} |\n| CEA tiên lượng xấu | ==> 5 ng/ml== | {{BHNgTH tr.252}} |\n| Cắt u tại chỗ | ==T1 N0, < 3 cm, < 30% chu vi, diện cắt > 2 mm== | {{BHNgTH tr.259}} |\n| Diện cắt trên và dưới trong cắt trước | ==ít nhất 2 cm== | {{BHNgTH tr.260}} |\n| Ruột trên dòng bảo vệ miệng nối | ==miệng nối < 4 cm== | {{BHNgTH tr.260}} |\n| Miles ra đời | ==1908== | {{BHNgTH tr.261}} |\n| Sống 5 năm: khu trú / hạch / di căn xa / chung | ==90% / 73,8% / 18% / 67%== | {{BHNgTH tr.263}} |\n| Tuổi bắt đầu tầm soát nguy cơ trung bình | ==45–75== | {{BHNgTH tr.264}} |\n\n> [!warn] Bẫy thi thường gặp\n> - **Thăm trực tràng không thay thế MRI**: MRI mới cho MRF, hạch, xâm lấn cơ thắt chính xác; CLVT kém với u trong thành và hạch dưới 1 cm {{BHNgTH tr.250}}\n> - **MRF dương khi ≤ 1 mm** (không phải < 1 mm); là tiêu chí chính chỉ định xạ trị trước mổ {{BHNgTH tr.250}} {{BHNgTH tr.257}}\n> - **Miles không còn là mổ mặc định**: chỉ khi đã xâm lấn cơ nâng/cơ thắt hoặc u sát rìa hậu môn; còn lại ưu tiên bảo tồn cơ thắt {{BHNgTH tr.261}}\n> - **Cắt trước thấp** là cắt trực tràng dưới nếp phúc mạc, vẫn là bảo tồn cơ thắt {{BHNgTH tr.260}}\n> - **CEA không dùng chẩn đoán**, chỉ tiên lượng và theo dõi {{BHNgTH tr.251}}\n> - **Siêu âm qua lòng trực tràng làm trước xạ trị** vì xơ sẹo làm giảm chính xác {{BHNgTH tr.251}}\n> - Giáo trình cũ (Notion) ghi tầm soát từ 50 tuổi, sống 5 năm 89%/71%/15% (số liệu 2009–2015) và UTTT nhiều gấp 1,5 lần đại tràng; giáo trình 2025: từ 45 tuổi, 90%/73,8%/18% và trực tràng chiếm gần 40% UTĐTT {{BHNgTH tr.238}} {{BHNgTH tr.263}} {{BHNgTH tr.264}}\n\n@@fold Nguồn tài liệu\n- **BHNgTH** Giáo trình Bệnh học ngoại khoa tiêu hóa 2025, chương Ung thư trực tràng, tr.238–264 (trang PDF; sách in tr.229–255); lưu đồ 1 (BYT) đọc từ ảnh trang 257\n- **TCBN** không dùng trong trang này\n@@end\n\n@@fold Nguồn ngoài\n- Từ Notion \"[BHNgK] Ung thư trực tràng\" (chép từ giáo trình cũ), gắn ô Notion trong bài: yếu tố giảm nguy cơ; Crohn 1/500–1/200; ống soi cứng 60 mm; lịch sử phẫu thuật (Dukes, Dixon, diện cắt 2 cm và 1 cm, miệng nối thấp 3 cm); MRI tốt nhất cho cơ nâng/cơ thắt; tai biến Miles; suy giảm chức năng sau nối thấp; khoảng cách tầm soát\n- Notion khác giáo trình mới: tuổi tầm soát 50–75 (mới 45–75); sống 5 năm 89%/71%/15% (mới 90%/73,8%/18%); trực tràng nhiều gấp 1,5 lần đại tràng (mới gần 40%); bài đã theo giáo trình mới\n- Không có nguồn nào nêu: liều và phác đồ hóa xạ cụ thể, lịch theo dõi sau mổ, tỷ lệ xì miệng nối, biến chứng sau mổ theo tỷ lệ\n@@end\n\n@@fold! Tự kiểm tra (10 thẻ)\n- MRF dương tính khi nào? :: Khi khoảng cách ngắn nhất từ u hoặc hạch đến mạc riêng trực tràng ≤ 1 mm\n- Chia trực tràng thành 3 đoạn theo khoảng cách từ rìa hậu môn? :: 1/3 dưới 0–5 cm; giữa 6–10 cm; trên 11–15 cm\n- Hạch trạm đầu của UTTT nằm ở đâu? :: Trong mạc treo trực tràng\n- Cần ghi gì khi thăm trực tràng ở người nghi UTTT? :: Bờ dưới u cách rìa hậu môn, vị trí theo chu vi, xâm lấn cơ thắt, kích thước, chít hẹp, độ di động\n- Phương tiện tốt nhất đánh giá trước mổ và theo dõi tái phát? :: MRI chậu\n- Chỉ định cắt u tại chỗ? :: T1 N0, độ mô học 1–2, không xâm lấn mạch; u dưới 3 cm, dưới 30% chu vi, diện cắt trên 2 mm, di động, u thấp\n- Khi nào đưa ruột trên dòng bảo vệ miệng nối? :: Miệng nối dưới 4 cm, ruột căng, béo phì, xạ trị trước, ức chế miễn dịch, hoặc phẫu thuật viên thấy không an toàn\n- Chỉ định hiện nay của phẫu thuật Miles? :: U thấp đã xâm lấn cơ nâng, cơ thắt; xâm lấn rộng; sát rìa hậu môn; ung thư ống hậu môn\n- TNT là gì và ưu tiên cho giai đoạn nào? :: Làm toàn bộ hóa và xạ trị trước mổ; ưu tiên cho UTTT giai đoạn II–III (NCCN)\n- Ý nghĩa của CEA trong UTTT? :: Không dùng chẩn đoán; CEA > 5 ng/ml tiên lượng xấu; theo dõi hiệu quả mổ và tái phát\n@@end"}, {"kind": "disease", "disease": "viem-ruot-thua", "short": "Viêm ruột thừa cấp", "group": "", "section": 0, "order": 1, "khung": [], "id": "viem-ruot-thua-cap", "title": "Viêm ruột thừa cấp", "layer": "benh", "module": "ngoai-tong-quat", "tags": ["ngoại khoa", "tiêu hóa", "ruột thừa", "bụng ngoại khoa", "Alvarado", "AIR", "PAS", "cắt ruột thừa nội soi", "đám quánh", "áp-xe ruột thừa", "viêm phúc mạc"], "source": "BHNgTH tr.29–50 (chương Viêm ruột thừa); TCBN tr.25–26, 46, 48", "body": "> [!key] Viêm ruột thừa cấp (VRT) trong một nhìn\n> - Là cấp cứu bụng ngoại khoa thường gặp nhất; nguy cơ mắc suốt đời 8,6% ở nam, 6,9% ở nữ {{BHNgTH tr.29}}\n> - Cơ chế chính: tắc nghẽn lòng ruột thừa, tăng áp lực lòng, huyết khối tiểu tĩnh mạch, rồi hoại tử và thủng {{BHNgTH tr.31}}\n> - Đau quanh rốn rồi chuyển xuống hố chậu phải sau 6–12 giờ, kèm chán ăn; chẩn đoán trước hết dựa vào bệnh sử và khám, thang điểm Alvarado/AIR và hình ảnh để hỗ trợ {{BHNgTH tr.33}} {{BHNgTH tr.38}}\n> - ==Tiêu chuẩn vàng điều trị là cắt ruột thừa, càng sớm càng tốt==; nội soi là lựa chọn ưu tiên; đám quánh thì không mổ cấp cứu {{BHNgTH tr.47}} {{BHNgTH tr.48}} {{BHNgTH tr.49}}\n> - Chẩn đoán sớm và mổ kịp thời: tử vong 0,1–0,2%; đến trễ hoặc mổ khi đã biến chứng: có thể đến 10% {{BHNgTH tr.29}}\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Gốc ruột thừa cố định ở đáy manh tràng nhưng đầu tự do xoay 360 độ, nên vị trí đau và biểu hiện lâm sàng rất đa dạng {{BHNgTH tr.30}}\n> - Hai cơ chế: **tắc nghẽn** (diễn tiến nhanh đến thủng) và **xuất tiết/không tắc nghẽn** (diễn tiến đa dạng hơn) {{BHNgTH tr.31}} {{BHNgTH tr.32}}\n\n### Định nghĩa & dịch tễ\n- VRT là cấp cứu bụng ngoại khoa thường gặp nhất trên toàn thế giới {{BHNgTH tr.29}}\n- Nước phát triển: xuất độ 5,7–50/100.000 dân/năm; tuổi thường gặp nhất 10–20 {{BHNgTH tr.29}}\n- Nước kém phát triển xuất độ thấp hơn nhiều, gợi ý chế độ ăn kiểu phương Tây (ít chất xơ, nhiều chất béo) có thể có vai trò {{BHNgTH tr.29}}\n- Tại Việt Nam, từ tuyến huyện đến tuyến trung ương, VRT luôn chiếm tỉ lệ cao trong cấp cứu ngoại tổng quát {{BHNgTH tr.29}}\n- Chẩn đoán nhầm VRT vẫn ở mức 15,3% (tương đương tỉ lệ thủng ruột thừa); nữ 22,2%, nam 9,3% {{BHNgTH tr.29}}\n\n### Giải phẫu ứng dụng\n- Ruột thừa hình thành từ tuần 8 như phần trồi ra từ nụ manh tràng; manh tràng phát triển nhanh hơn nên ruột thừa lệch vào phía van hồi manh tràng {{BHNgTH tr.30}}\n- ==Ba dải cơ dọc đại tràng hội tụ ở đáy manh tràng== tạo lớp cơ dọc của ruột thừa: mốc chắc chắn nhất để tìm gốc ruột thừa {{BHNgTH tr.30}}\n- Có thể có nếp niêm mạc bán nguyệt ở lỗ ruột thừa gọi là van Gerlach {{BHNgTH tr.30}}\n- Máu nuôi: động mạch ruột thừa (nhánh động mạch hồi đại tràng, chạy ở bờ tự do mạc treo); có thể thêm nhánh phụ từ động mạch manh tràng sau {{BHNgTH tr.30}}\n- Tĩnh mạch ruột thừa đổ vào tĩnh mạch hồi đại tràng, tĩnh mạch mạc treo tràng trên, rồi về tĩnh mạch cửa {{BHNgTH tr.30}}\n- Bạch huyết đổ vào hạch hồi đại tràng trên và dưới {{BHNgTH tr.31}}\n- Cảm giác đau tạng đi theo thần kinh giao cảm vào tủy ngang mức ngực 10; phúc mạc thành vùng hố chậu phải do thần kinh gian sườn 10 chi phối {{BHNgTH tr.31}}\n- Ruột thừa có chức năng miễn dịch: chất nhày giàu IgA và các nang bạch huyết chế tiết kháng thể {{BHNgTH tr.31}}\n\n### Bệnh sinh\n@@tabs\n@@tab VRT tắc nghẽn\n- **Tắc nghẽn lòng ruột thừa** được xem là sự kiện chính ở hầu hết người bệnh {{BHNgTH tr.31}}\n- Nguyên nhân tắc: sỏi phân, tăng sản mô bạch huyết, dị vật (hạt trái cây, sợi rau, barium), ký sinh trùng, khối u, khối hạch phì đại {{BHNgTH tr.31}}\n- Chuỗi biến cố: ứ đọng dịch, áp lực lòng tăng đến ==50–65 mmHg==, vi khuẩn tăng sinh và sinh độc tố {{BHNgTH tr.31}}\n- Áp lực vượt áp lực tĩnh mạch: tiểu tĩnh mạch xẹp và huyết khối, tiểu động mạch vẫn cấp máu nên thành ruột thừa sung huyết, ứ huyết {{BHNgTH tr.31}}\n- Niêm mạc thiếu oxy, loét, mất hàng rào; vi khuẩn xâm nhập thành, rồi hoại tử và thủng {{BHNgTH tr.31}}\n- Đa số VRT tắc nghẽn tiến triển đến thủng/vỡ và viêm phúc mạc {{BHNgTH tr.32}}\n@@tab VRT xuất tiết (không tắc nghẽn)\n- Nghiên cứu gần đây: tắc nghẽn lòng không gặp ở 90% người bệnh VRT mủ, chỉ gặp ở VRT hoại tử {{BHNgTH tr.32}}\n- Tổn thương viêm bắt đầu ở niêm mạc hoặc nang bạch huyết, lan xuyên thành đến cơ và thanh mạc {{BHNgTH tr.32}}\n- Phù nề nặng gây tắc các nhánh tận động mạch ruột thừa, dẫn đến thiếu máu và hoại tử {{BHNgTH tr.32}}\n- Tắc lòng nếu có là hậu quả của viêm, không phải yếu tố khởi phát {{BHNgTH tr.32}}\n- Diễn tiến đa dạng, phụ thuộc sức đề kháng: hoại tử gây viêm phúc mạc, đám quánh, áp-xe; hoặc về bình thường, hoặc để lại xơ hóa, dính, gập góc, u nhầy ruột thừa {{BHNgTH tr.32}}\n@@end\n\n### Diễn tiến và biến chứng\n- Phân loại để chọn cách điều trị: **chưa biến chứng** và **có biến chứng** (hoại tử, thủng tạo khối viêm, áp-xe, viêm phúc mạc) {{BHNgTH tr.45}}\n\n| Biến chứng | Đặc điểm chính |\n|---|---|\n| Viêm phúc mạc tức thì (trong 24 giờ) | Vài giờ sau khởi đau đã đau khắp bụng, đề kháng lan tỏa; hay gặp ở trẻ nhỏ; ở người lớn phân biệt thủng loét dạ dày tá tràng {{BHNgTH tr.45}} |\n| Viêm phúc mạc sau 24 giờ | Khoảng 24–48 giờ sau đau, đau trội lên; khu trú (đau và đề kháng chỉ ở ¼ dưới phải) hoặc toàn thể {{BHNgTH tr.45}} |\n| Viêm phúc mạc hai thì | Giảm đau giả (\"thời gian giảm đau dối trá\"), sau 4–5 ngày đau trở lại đột ngột; dễ chẩn đoán trễ {{BHNgTH tr.45}} |\n| Viêm phúc mạc ba thì | VRT, rồi áp-xe, rồi áp-xe vỡ; dễ nhầm với tắc ruột {{BHNgTH tr.45}} |\n| Đám quánh ruột thừa | Mạc nối lớn và ruột non bao bọc, hình thành sau khoảng 4–5 ngày, to nhất khoảng ngày 10, thường biến mất trước tuần 4 {{BHNgTH tr.45}} {{BHNgTH tr.46}} |\n| Áp-xe ruột thừa | Ổ mủ giới hạn rõ với xoang bụng; triệu chứng VRT khoảng 3–5 ngày trước nhập viện {{BHNgTH tr.46}} |\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Đau bụng khởi đầu quanh rốn hoặc trên rốn, sau 6–12 giờ chuyển xuống hố chậu phải; kiểu đau di chuyển là triệu chứng đáng tin cậy {{BHNgTH tr.33}}\n> - Chán ăn gặp hơn 90%: nếu không chán ăn thì phải xem lại chẩn đoán {{BHNgTH tr.33}}\n> - Dấu hiệu thực thể quan trọng nhất: ấn đau ¼ dưới phải; phản ứng dội cho thấy kích thích phúc mạc khu trú {{BHNgTH tr.33}} {{BHNgTH tr.34}}\n\n### Triệu chứng cơ năng\n- **Đau bụng**: xuất hiện đầu tiên, gặp hơn 95%; âm ỉ, ít khi dữ dội hay thành cơn {{BHNgTH tr.33}}\n- Khoảng 25% đau ngay từ đầu ở hố chậu phải, không có đau di chuyển {{BHNgTH tr.33}}\n- Vị trí đau bất thường: hông lưng (sau manh tràng), hạ vị (tiểu khung), hạ sườn phải (dưới gan) {{BHNgTH tr.33}}\n- Chán ăn gặp ==hơn 90%==; buồn nôn, nôn gặp 60–80%, xuất hiện sau đau, thường nôn khan 1–2 lần {{BHNgTH tr.33}}\n- Tiêu chảy ít gặp, thường ở thể sau hồi tràng; ở trẻ em có thể là biểu hiện thể nhiễm độc {{BHNgTH tr.33}}\n- Trình tự **tam chứng Murphy**: đau bụng dưới phải, rồi nôn, sau đó mới sốt; nếu trình tự thay đổi thì phải nghi ngờ chẩn đoán VRT {{BHNgTH tr.33}}\n\n### Triệu chứng thực thể\n- Đa số có đau khi ấn ở ¼ dưới phải; điểm đau thường nhắc: McBurney, Lanz, Clado, nhưng không có điểm cố định chính xác cho mọi trường hợp {{BHNgTH tr.33}}\n- Dấu hiệu ngón tay chỉ; tam giác tăng cảm da Sherren (rốn, gai chậu trước trên phải, củ mu) khi ruột thừa hoại tử áp vào thành bụng trước {{BHNgTH tr.33}}\n\n| Dấu hiệu / nghiệm pháp | Cách làm hoặc ý nghĩa |\n|---|---|\n| Phản ứng dội trực tiếp (Blumberg) | Ấn sâu rồi buông đột ngột, đau chói khi buông {{BHNgTH tr.34}} |\n| Dấu Rovsing | Ấn hố chậu trái gây đau hố chậu phải {{BHNgTH tr.34}} |\n| Dấu Dunphy, nghiệm pháp Markle | Đau bụng dưới phải khi ho; khi dập gót chân; nhảy lò cò chân phải cũng xem như phản ứng dội gián tiếp {{BHNgTH tr.34}} |\n| Đề kháng thành bụng rõ | Thường đã có biến chứng viêm phúc mạc; ít khi co cứng như gỗ như thủng dạ dày {{BHNgTH tr.34}} |\n| Thăm âm đạo – trực tràng | Gợi ý VRT tiểu khung {{BHNgTH tr.34}} |\n| Nghiệm pháp cơ thắt lưng chậu | VRT sau manh tràng {{BHNgTH tr.34}} |\n| Nghiệm pháp cơ bịt | VRT tiểu khung {{BHNgTH tr.34}} |\n\n> [!warn] Phản ứng dội chưa phải viêm phúc mạc\n> Phản ứng dội chỉ chứng tỏ kích thích phúc mạc khu trú, không hẳn đã có viêm phúc mạc {{BHNgTH tr.34}}\n\n### Triệu chứng toàn thân\n- Sốt thường nhẹ 37,5–38 độ C; 25–50% có thân nhiệt bình thường (dưới 37,5) khi vào viện {{BHNgTH tr.35}}\n- {r|Sốt cao từ 39 độ C trở lên gợi ý VRT đã có biến chứng} {{BHNgTH tr.35}}\n- Đến trễ hoặc thể nhiễm độc: môi khô, lưỡi dơ, vẻ mặt nhiễm trùng nhiễm độc, thở nhanh, mạch nhanh, huyết áp tụt {{BHNgTH tr.35}}\n\n### Các thể lâm sàng\n@@tabs\n@@tab Theo cơ chế và diễn biến\n- **VRT xuất tiết**: đau tạng quanh rốn hoặc trên rốn, âm ỉ; sau 4–6 giờ viêm lan ra thanh mạc, kích thích phúc mạc thành, ấn đau rõ ở hố chậu phải {{BHNgTH tr.41}}\n- **VRT tắc nghẽn**: đau khởi đầu có thể quặn cơn quanh rốn, diễn tiến nhanh, thường đưa nhanh đến viêm phúc mạc toàn thể do vỡ {{BHNgTH tr.41}}\n- **Diễn biến nhanh**: viêm phúc mạc tức thì trong 24 giờ đầu, dễ nhầm thủng loét dạ dày tá tràng {{BHNgTH tr.41}}\n- **Thể nhiễm độc**: toàn thân nặng nhưng triệu chứng tại chỗ kín đáo; thường ở trẻ nhỏ {{BHNgTH tr.41}}\n@@tab Theo vị trí giải phẫu\n- **Sau manh tràng**: đau cao ở hông phải, ấn đau hố thắt lưng phải; dấu hiệu cơ thắt lưng chậu (nằm ưỡn hông phải, co nhẹ đùi phải, duỗi đùi thì đau) {{BHNgTH tr.41}}\n- **Tiểu khung**: tiểu lắt nhắt, tiểu gắt, mót rặn; ấn đau thấp gần khớp mu; thăm trực tràng hoặc âm đạo đau bên phải; nghiệm pháp cơ bịt dương tính {{BHNgTH tr.42}}\n- **Sau hồi tràng**: tiêu chảy, hoặc triệu chứng tắc ruột do liệt các quai hồi tràng kế cận {{BHNgTH tr.42}}\n- **Dưới gan**: đau cao gần gan, dễ nhầm viêm túi mật cấp hoặc viêm đường mật {{BHNgTH tr.42}}\n- Đảo ngược phủ tạng (0,2% người lớn): đau ở hố chậu trái {{BHNgTH tr.42}}\n@@tab Theo lứa tuổi\n- **Trẻ em**: là cấp cứu ngoại khoa bụng thường gặp nhất; triệu chứng cơ năng điển hình chỉ 50–68%, thực thể điển hình 17–69% {{BHNgTH tr.42}}\n- **Người già**: 15% người trên 50 tuổi đau bụng cấp là VRT; triệu chứng không rõ, bạch cầu tăng ít, viêm phúc mạc ruột thừa có thể đến 50% ở người trên 65 tuổi {{BHNgTH tr.43}}\n- Hai thể hay gặp ở người già: bán tắc ruột và giả u {{BHNgTH tr.43}}\n@@tab Theo cơ địa\n- **Có thai** (1/1.400 thai phụ): ruột thừa bị đẩy lên cao và ra ngoài; những tháng cuối khám nằm nghiêng trái hoặc tìm dấu Rovsing {{BHNgTH tr.44}}\n- **Béo phì**: thành bụng dày, khó đánh giá đề kháng; nên thăm trực tràng hoặc tìm dấu Rovsing {{BHNgTH tr.44}}\n- **Báng bụng**: rất khó chẩn đoán, đôi khi cần chọc dò dịch báng hoặc nội soi ổ bụng chẩn đoán {{BHNgTH tr.44}}\n- **Suy giảm miễn dịch**: sốt và bạch cầu tăng có thể không rõ; CLVT bụng có thể giúp {{BHNgTH tr.44}} {{BHNgTH tr.45}}\n@@end\n\n### Áp-xe và đám quánh: dấu hiệu khi khám\n- **Đám quánh**: đau hố chậu phải vài ngày, giảm nhưng không hết, xuất hiện mảng chắc, giới hạn không rõ, không di động, ít đau; nhiễm trùng toàn thân không rầm rộ {{BHNgTH tr.46}}\n- **Áp-xe**: nhiễm trùng rõ, sốt cao; khối giới hạn khá rõ, không di động, mềm, ấn rất đau {{BHNgTH tr.46}}\n- Ruột thừa vị trí bất thường: khó sờ thấy khối, nên thăm trực tràng hoặc âm đạo, làm nghiệm pháp cơ thắt lưng chậu {{BHNgTH tr.46}} {{BHNgTH tr.47}}\n\n> [!tip] Tiếp cận đau bụng\n> Nôn xuất hiện sau khi đau gợi ý VRT, còn nôn trước khi đau hay gặp trong viêm dạ dày ruột, ngộ độc thức ăn {{TCBN tr.48}}\n\n## 5. Cận lâm sàng\n\n> [!key] Chỉ định gì khi nào\n> - Xét nghiệm máu chỉ xác định có viêm, không đặc hiệu; hình ảnh bổ sung khi bệnh cảnh không điển hình {{BHNgTH tr.38}}\n> - Siêu âm là bước đầu (ưu tiên ở thai phụ và trẻ nhỏ); CLVT khi lâm sàng và siêu âm không kết luận được; MRI cho trường hợp khó ở trẻ, thai phụ hoặc chống chỉ định CLVT {{BHNgTH tr.36}} {{BHNgTH tr.38}}\n\n### Xét nghiệm máu\n- **Bạch cầu**: tăng vừa phải, đa nhân trung tính chiếm đa số (thường trên 75% trong 78% trường hợp); trên 18.000/mm3 gợi ý đã biến chứng {{BHNgTH tr.35}}\n- Bạch cầu tăng: độ nhạy 76%, độ đặc hiệu 52%, giá trị tiên đoán dương 42%, giá trị tiên đoán âm 82%; không có ngưỡng nào xác định hay loại trừ chắc chắn {{BHNgTH tr.35}}\n- **CRP**: tăng trong 6–12 giờ sau viêm cấp; triệu chứng kéo dài hơn 24 giờ mà CRP bình thường thì giá trị tiên đoán âm 100% {{BHNgTH tr.35}} {{BHNgTH tr.36}}\n\n### Chẩn đoán hình ảnh\n@@tabs\n@@tab Siêu âm\n- Rẻ, sẵn có, không xâm hại; nên áp dụng rộng rãi; ưu tiên ở thai phụ và trẻ nhỏ {{BHNgTH tr.36}}\n- Hình ảnh: cấu trúc ống thành dày, đường kính ngoài ==trên 6 mm==, không xẹp khi ép đầu dò; dấu ngón tay (cắt dọc), hình bia (cắt ngang) {{BHNgTH tr.36}}\n- Có thể thấy mỡ quanh ruột thừa echo dày (50%), sỏi phân, tụ dịch quanh manh tràng khi vỡ {{BHNgTH tr.36}}\n- Độ nhạy 83%, độ đặc hiệu 93%, giá trị tiên đoán dương 86%, giá trị tiên đoán âm 94% {{BHNgTH tr.36}}\n- Hạn chế: phụ thuộc người khảo sát; khó ở người béo phì, đến trễ, bụng trướng hơi {{BHNgTH tr.36}}\n- Ở người già: độ nhạy 86%, độ đặc hiệu 81%, không hữu ích khi cần loại trừ VRT {{BHNgTH tr.43}}\n@@tab CLVT ổ bụng\n- Dùng khi siêu âm không kết luận hoặc cần phân biệt các nguyên nhân bụng cấp ngoại khoa khác {{BHNgTH tr.36}}\n- Dấu hiệu: ruột thừa căng đường kính trên 6 mm, thành dày trên 2 mm, tăng đậm độ mỡ quanh ruột thừa {{BHNgTH tr.36}}\n- Khi vỡ: gián đoạn thành, ổ áp-xe hoặc dịch tự do, có khi sỏi phân rơi ra ngoài {{BHNgTH tr.37}}\n- Độ nhạy 91–94%, độ đặc hiệu 94–95%, giá trị tiên đoán dương 93%, giá trị tiên đoán âm 99%; giảm tỉ lệ cắt ruột thừa sai từ 20% xuống 7% {{BHNgTH tr.37}}\n- Hạn chế: nhiễm tia xạ (tránh ở thai phụ và trẻ nhỏ); chống chỉ định ở suy thận, dị ứng cản quang (nếu chụp có cản quang) {{BHNgTH tr.37}}\n- Hội Phẫu thuật cấp cứu thế giới và châu Âu: chỉ chụp khi cần; có thể dùng liều thấp bằng 1/4 liều chuẩn, không cần uống cản quang {{BHNgTH tr.38}}\n@@tab MRI\n- Độ nhạy 97–100%, độ đặc hiệu 95–99% {{BHNgTH tr.38}}\n- Nhược điểm: đắt, không sẵn có, cần chuyên gia đọc; chỉ nên dùng khi có điều kiện, cho ca khó ở bệnh nhi, thai phụ hoặc chống chỉ định CLVT {{BHNgTH tr.38}}\n@@end\n\n### Nội soi ổ bụng chẩn đoán\n- Chỉ khi theo dõi lâm sàng và hình ảnh vẫn chưa xác định hay loại trừ được VRT mà còn nghi bụng ngoại khoa; có thể kết hợp điều trị {{BHNgTH tr.39}} {{BHNgTH tr.40}}\n- Vẫn là một cuộc mổ gây mê toàn thể nên là giải pháp sau cùng {{BHNgTH tr.40}}\n\n### Phân độ VRT cấp (Gomes 2015)\nDựa trên hình ảnh đại thể qua nội soi kết hợp lâm sàng và hình ảnh, liên quan đến lựa chọn xử trí {{BHNgTH tr.40}}\n\n| Độ | Mô tả |\n|---|---|\n| 0 | Ruột thừa trông bình thường (viêm nội mạc/viêm quanh ruột thừa) {{BHNgTH tr.40}} |\n| 1 | Ruột thừa viêm (sung huyết, phù nề, có thể có giả mạc), không hay ít dịch {{BHNgTH tr.40}} |\n| 2A / 2B | Hoại tử một đoạn thân / hoại tử ở gốc {{BHNgTH tr.40}} |\n| 3A / 3B / 3C | Đám quánh / áp-xe ≤5 cm / áp-xe >5 cm, không có hơi tự do ổ bụng {{BHNgTH tr.40}} |\n| 4 | Thủng gây viêm phúc mạc toàn thể, có hay không có hơi tự do ổ bụng {{BHNgTH tr.40}} |\n\nĐộ 0–1 là VRT chưa biến chứng; độ 2–4 là có biến chứng {{BHNgTH tr.40}}\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Nguyên tắc chẩn đoán\n> - Chẩn đoán dựa trước hết vào hỏi bệnh sử chi tiết, triệu chứng toàn thân và thực thể; triệu chứng điển hình chỉ có ở khoảng 60–70% trường hợp {{BHNgTH tr.38}}\n> - Triệu chứng chưa rõ: theo dõi nhiều giờ, khám lại nhiều lần, kết hợp cận lâm sàng; đau bụng cấp ở người khỏe, nhất là kèm sốt, không bao giờ xem nhẹ nguy cơ VRT {{BHNgTH tr.34}}\n\n### Thang điểm\n@@tabs\n@@tab Alvarado (MANTRELS)\n- Do Alvarado đề xuất năm 1986; 8 thành tố, tối đa 10 điểm {{BHNgTH tr.38}}\n\n| Đặc tính | Điểm |\n|---|---|\n| Đau di chuyển (đến bụng dưới phải) | 1 |\n| Chán ăn | 1 |\n| Buồn nôn/nôn | 1 |\n| Ấn đau bụng dưới phải | 2 |\n| Có phản ứng dội | 1 |\n| Sốt | 1 |\n| Bạch cầu tăng | 2 |\n| Công thức bạch cầu chuyển trái | 1 |\n\n- Nguồn bảng: {{BHNgTH tr.39}}\n- Diễn giải: ==9–10 rất nhiều khả năng VRT; 7–8 có lẽ VRT; 5–6 không chắc VRT; dưới 5 (0–4) dường như không phải VRT== {{BHNgTH tr.38}}\n@@tab AIR\n- Do Andersson đề xuất năm 2008; chi tiết hơn về mức đau, bạch cầu, thêm CRP; tối đa 12 điểm {{BHNgTH tr.38}}\n- Diễn giải: 0–4 khả năng thấp; 5–8 trung bình; 9–12 rất cao {{BHNgTH tr.38}}\n- Các thành tố: nôn, đau hố chậu phải, phản ứng dội/đề kháng (nhẹ 1, vừa 2, nhiều 3), sốt từ 38,5 độ C, bạch cầu, tỉ lệ đa nhân, CRP {{BHNgTH tr.39}}\n@@tab PAS (trẻ em)\n- Samuel đề xuất 2002; 8 thành tố như Alvarado, tổng 10 điểm; phản ứng dội gián tiếp (ho, nhảy lò cò, gõ) được 2 điểm; tăng bạch cầu giảm còn 1 điểm {{BHNgTH tr.42}}\n- PAS ≤5: theo dõi; ≥6: nghĩ đến VRT; PAS >7 thì khả năng VRT >70%; PAS <2 loại trừ VRT cấp đúng 99% {{BHNgTH tr.42}} {{BHNgTH tr.43}}\n@@end\n\n> [!doc] Phân tầng theo hướng dẫn Hội Phẫu thuật cấp cứu thế giới 2016\n> Điểm Alvarado/AIR chia ba nhóm nguy cơ: thấp (dưới 5) có thể theo dõi ngoại trú; trung bình (5–8) giữ lại theo dõi, làm chẩn đoán; cao (trên 8) nhập viện ngay. Thang điểm chỉ có tính tham khảo, không thay thế khám đi khám lại kỹ {{BHNgTH tr.39}}\n\n### Cách tiếp cận theo nhóm bệnh nhân\n- **Trên 60 tuổi**: thang điểm chưa đủ chứng cứ; chỉ định sớm hình ảnh để khỏi bỏ sót bệnh nguy hiểm như u manh tràng; CLVT có cản quang nếu nghi VRT, Alvarado từ 5 trở lên và siêu âm không có dấu hiệu gợi ý {{BHNgTH tr.43}} {{BHNgTH tr.44}}\n- **Béo phì**: siêu âm trước; khó đánh giá thì chụp CLVT sớm {{BHNgTH tr.44}}\n\n### Chẩn đoán phân biệt\n| Nhóm | Bệnh cần phân biệt |\n|---|---|\n| Người lớn nói chung | Thủng loét dạ dày tá tràng, ung thư manh tràng, lao hồi manh tràng, viêm dạ dày ruột, viêm ruột, herpes {{BHNgTH tr.39}} |\n| Phụ nữ tuổi sinh đẻ | Xuất huyết giữa hai kỳ kinh (Mittelschmerz), nang trứng vỡ, u nang buồng trứng xoắn, thai ngoài tử cung vỡ, lạc nội mạc tử cung, viêm phần phụ {{BHNgTH tr.39}} |\n| Thai phụ | Thêm các cấp cứu sản khoa: thai ngoài tử cung, viêm màng nuôi, dọa sinh non {{BHNgTH tr.44}} |\n| Trẻ em | Lồng ruột, viêm túi thừa Meckel, xoắn tinh hoàn, viêm phổi thùy phải, viêm hạch mạc treo cấp, viêm dạ dày ruột cấp; thêm sốt xuất huyết {{BHNgTH tr.39}} {{BHNgTH tr.42}} |\n| Người già | U manh tràng đại tràng phải, bệnh túi thừa đại tràng, xoắn đại tràng chậu hông, đau sau nhiễm herpes {{BHNgTH tr.43}} |\n| Đám quánh, áp-xe | Ung thư manh tràng, lao hồi manh tràng; viêm quanh khối u manh tràng {{BHNgTH tr.46}} |\n| VRT dưới gan | Viêm túi mật cấp, viêm đường mật {{BHNgTH tr.42}} |\n| Cơ địa suy giảm miễn dịch | Viêm gan, viêm tụy, viêm túi mật không do sỏi, nhiễm trùng cơ hội (CMV, lao), lymphoma, thương hàn {{BHNgTH tr.44}} {{BHNgTH tr.45}} |\n\n> [!tip] Đau hố chậu phải ở tiếp cận bệnh nhân ngoại khoa\n> Đau ¼ dưới phải: nguyên nhân đường ruột (viêm ruột thừa, viêm túi thừa, viêm hạch mạc treo, thiếu máu ruột), sản phụ khoa (thai ngoài tử cung, viêm hoặc xoắn phần phụ, lạc nội mạc tử cung) và cơ thắt lưng chậu (viêm, áp-xe) {{TCBN tr.26}}\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n- **Cắt bỏ ruột thừa** là tiêu chuẩn vàng cho VRT cấp, tiến hành càng sớm càng tốt, tránh trì hoãn không cần thiết {{BHNgTH tr.47}}\n- Chỉ định mổ là đương nhiên (không bàn cãi) khi có biến chứng hoại tử hoặc thủng gây viêm phúc mạc {{BHNgTH tr.47}}\n- Với áp-xe: kiểm soát ổ nhiễm bằng kháng sinh phối hợp dẫn lưu; với đám quánh: kiểm soát nhiễm trùng và theo dõi diễn tiến {{BHNgTH tr.48}} {{BHNgTH tr.49}}\n\n### 7.2 Các phương pháp\n@@tabs\n@@tab VRT cấp\n- Đến sớm, không bệnh nội khoa cần chỉnh: không cần nhiều thời gian chuẩn bị trước mổ {{BHNgTH tr.47}}\n- Đến muộn, có viêm phúc mạc: hồi sức đủ trước mổ gồm bù nước điện giải và kháng sinh điều trị {{BHNgTH tr.47}}\n- Thể sung huyết: có thể chỉ cần 1 liều kháng sinh dự phòng trước mổ {{BHNgTH tr.47}}\n- Viêm phúc mạc do vỡ: sau cắt phải làm sạch xoang phúc mạc, dẫn lưu khi cần, tiếp tục kháng sinh ít nhất 4–7 ngày; kháng sinh phải bao phủ vi trùng gram âm và kỵ khí đường ruột {{BHNgTH tr.47}}\n@@tab Mổ mở và nội soi\n- Có thể cắt ruột thừa mổ mở; hiện nay nội soi được áp dụng phổ biến, kể cả khi đã viêm phúc mạc {{BHNgTH tr.47}}\n- Ưu điểm nội soi: ít đau, phục hồi nhanh, ít nhiễm khuẩn vết mổ và dính ruột; cần trang bị và phẫu thuật viên được huấn luyện {{BHNgTH tr.47}}\n- Hội Phẫu thuật cấp cứu thế giới và châu Âu: cắt ruột thừa nội soi vẫn là điều trị ưu tiên {{BHNgTH tr.48}}\n@@tab Điều trị không mổ\n- Kháng sinh và theo dõi: thành công ngay 77–95%, sau 1 năm còn 62–71% {{BHNgTH tr.48}}\n- Nguy cơ để sót u ruột thừa (0,6–0,9% trường hợp) {{BHNgTH tr.48}}\n- Có thể chỉ định cho VRT cấp không biến chứng ở vùng xa xôi, người có nhiều nguy cơ cho cuộc mổ hoặc từ chối mổ {{BHNgTH tr.48}}\n@@tab Áp-xe ruột thừa\n- Xu hướng: kháng sinh, có thể kèm chọc hút hoặc dẫn lưu qua da; mổ khi không đáp ứng hoặc áp-xe quá lớn {{BHNgTH tr.48}}\n- Dẫn lưu qua da được trên CLVT thì chọc hút/dẫn lưu kết hợp kháng sinh; áp-xe tiểu khung dẫn lưu qua trực tràng hoặc âm đạo {{BHNgTH tr.48}}\n- Mổ nội soi vừa dẫn lưu mủ vừa cắt ruột thừa nếu bóc tách thuận lợi; đòi hỏi kỹ năng cao hơn {{BHNgTH tr.48}} {{BHNgTH tr.49}}\n@@tab Đám quánh\n- Là hàng rào cơ học và sinh học nên **không có chỉ định mổ cấp cứu**; mổ có nguy cơ tổn thương quai ruột dính và lan nhiễm trùng {{BHNgTH tr.49}}\n- Áp-xe hóa thì can thiệp thủ thuật hoặc phẫu thuật {{BHNgTH tr.49}}\n- Triệu chứng giảm dần (88–95%): có thể mổ \"nguội\" cắt ruột thừa sau khoảng 6–12 tuần; gần đây có đề nghị xem lại việc cắt thường quy vì tái phát chỉ 7–15% {{BHNgTH tr.49}}\n- Nội soi đại tràng kiểm tra sau 1 tháng để tránh bỏ sót ung thư manh tràng hoặc đại tràng {{BHNgTH tr.49}}\n@@end\n\n### 7.3 Chỉ định – hướng xử trí\n| Tình huống | Hướng xử trí |\n|---|---|\n| VRT cấp chưa biến chứng | Cắt ruột thừa, ưu tiên nội soi; kháng sinh trước mổ (một liều dự phòng nếu thể sung huyết) {{BHNgTH tr.47}} {{BHNgTH tr.48}} |\n| VRT hoại tử, thủng, viêm phúc mạc | Mổ cấp cứu sau hồi sức; làm sạch ổ bụng, dẫn lưu khi cần; kháng sinh ít nhất 4–7 ngày sau mổ {{BHNgTH tr.47}} |\n| Áp-xe nhỏ ≤4 cm | Kháng sinh trước; không đỡ thì xem xét phối hợp chọc hút/dẫn lưu qua da {{BHNgTH tr.48}} |\n| Áp-xe >4–6 cm | Kháng sinh phối hợp chọc hút/dẫn lưu; không đỡ thì mổ {{BHNgTH tr.48}} |\n| Áp-xe ≥7 cm, áp-xe giữa các quai ruột | Nhiều khả năng thất bại với bảo tồn, nên mổ {{BHNgTH tr.48}} |\n| Đám quánh | Không mổ cấp cứu; theo dõi; áp-xe hóa thì can thiệp; mổ nguội sau 6–12 tuần có thể cân nhắc {{BHNgTH tr.49}} |\n| Nghi VRT, chưa loại trừ được sau theo dõi và hình ảnh | Nội soi ổ bụng chẩn đoán (giải pháp sau cùng) {{BHNgTH tr.40}} |\n\n> [!doc] Biến chứng sau mổ\n> - **Nhiễm khuẩn vết mổ**: biến chứng thường gặp nhất của mổ mở; mổ sớm kèm kháng sinh dự phòng thì dưới 5%; nội soi thấp hơn mổ mở (0,34% so với 0,59%) {{BHNgTH tr.49}}\n> - **Liên quan lỗ trocar**: thoát vị, chảy máu lỗ trocar, tụ máu thành bụng do xuyên bó mạch thượng vị dưới {{BHNgTH tr.49}}\n> - **Chảy máu trong ổ bụng**: do tụt chỉ hoặc clip động mạch ruột thừa; đa số phải mổ lại {{BHNgTH tr.49}}\n> - **Xì mỏm ruột thừa**: tụt nơ chỉ, bung clip; gây viêm phúc mạc hậu phẫu, phải mổ lại; muộn thì áp-xe tồn lưu hoặc rò manh tràng {{BHNgTH tr.50}}\n> - **Áp-xe tồn lưu**: đa số do không làm sạch xoang phúc mạc; sau nội soi cao hơn mổ mở (4,6% so với 1%) {{BHNgTH tr.50}}\n> - **Tắc ruột sau mổ**: sớm do không làm sạch xoang phúc mạc hoặc áp-xe tồn lưu; muộn xảy ra sau nhiều tháng đến nhiều năm; phòng bằng làm sạch ổ bụng và vận động sớm {{BHNgTH tr.50}}\n\n> [!warn] Giáo trình không nêu liều và tên kháng sinh cụ thể\n> Giáo trình chỉ nêu nguyên tắc: bao phủ gram âm và kỵ khí, thời gian ít nhất 4–7 ngày sau mổ khi viêm phúc mạc {{BHNgTH tr.47}}\n\n## 8. Tiên lượng – Dự phòng / theo dõi sau mổ\n\n### Tiên lượng\n- Chẩn đoán sớm, mổ kịp thời: tử vong ==0,1–0,2%==, biến chứng không nhiều {{BHNgTH tr.29}}\n- Đến trễ, chẩn đoán trễ, mổ khi đã biến chứng: tử vong có thể đến ==10%==; nguy cơ tắc ruột do dính sau mổ gắn với phần đời còn lại {{BHNgTH tr.29}}\n- Người già có tỉ lệ viêm phúc mạc ruột thừa cao hơn do đề kháng yếu và ruột thừa được cấp máu kém {{BHNgTH tr.43}}\n- Đám quánh là diễn biến thuận lợi; có thể tự khỏi nhưng ruột thừa có thể viêm lại hoặc thành áp-xe {{BHNgTH tr.46}}\n\n### Theo dõi sau mổ\n- Theo dõi phát hiện các biến chứng sau mổ (xem mục 7.3): nhiễm khuẩn vết mổ, chảy máu, xì mỏm, áp-xe tồn lưu, tắc ruột {{BHNgTH tr.49}} {{BHNgTH tr.50}}\n- Khuyến khích người bệnh vận động sớm để tránh tắc ruột sớm {{BHNgTH tr.50}}\n- Sau điều trị đám quánh: nội soi đại tràng sau 1 tháng {{BHNgTH tr.49}}\n\n### Dự phòng\n- Dự phòng cấp 1: giáo trình chỉ gợi ý chế độ ăn kiểu phương Tây có thể liên quan bệnh sinh, không nêu biện pháp phòng bệnh cụ thể {{BHNgTH tr.29}}\n- Dự phòng nhiễm khuẩn vết mổ: kháng sinh dự phòng trước mổ {{BHNgTH tr.49}}\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] VRT cấp thi nhấn mạnh gì\n> - **Nhận diện**: đau quanh rốn rồi chuyển hố chậu phải, chán ăn, nôn sau đau, sốt sau cùng (tam chứng Murphy) {{BHNgTH tr.33}}\n> - **Chẩn đoán**: lâm sàng là chính; Alvarado/AIR phân tầng; siêu âm trước, CLVT khi cần; chú ý nhóm đặc biệt (trẻ, già, thai, nữ tuổi sinh đẻ) {{BHNgTH tr.38}} {{BHNgTH tr.39}}\n> - **Xử trí**: cắt ruột thừa (ưu tiên nội soi); áp-xe theo kích thước; đám quánh không mổ cấp cứu {{BHNgTH tr.47}} {{BHNgTH tr.48}} {{BHNgTH tr.49}}\n\n@@tabs\n@@tab Nhận diện\n- Đau di chuyển 6–12 giờ, chán ăn trên 90%, nôn 60–80% {{BHNgTH tr.33}}\n- Ấn đau ¼ dưới phải; phản ứng dội trực tiếp (Blumberg) và gián tiếp (Rovsing, Dunphy, Markle) {{BHNgTH tr.34}}\n- Sốt thường nhẹ; {r|sốt từ 39 độ C hoặc bạch cầu trên 18.000/mm3 gợi ý biến chứng} {{BHNgTH tr.35}}\n- Vị trí bất thường: sau manh tràng (cơ thắt lưng chậu), tiểu khung (cơ bịt, thăm trực tràng), dưới gan {{BHNgTH tr.41}} {{BHNgTH tr.42}}\n- Xem [mục 4](#/n/viem-ruot-thua-cap/4)\n@@tab Chẩn đoán\n- Alvarado: 9–10 rất nhiều khả năng, 7–8 có lẽ, 5–6 không chắc, dưới 5 dường như không {{BHNgTH tr.38}}\n- Siêu âm: ruột thừa trên 6 mm, không xẹp; CLVT khi siêu âm không kết luận {{BHNgTH tr.36}}\n- Chẩn đoán phân biệt theo nhóm: nữ tuổi sinh đẻ (thai ngoài tử cung, u nang xoắn), trẻ em (lồng ruột, viêm hạch mạc treo), người già (u manh tràng) {{BHNgTH tr.39}} {{BHNgTH tr.43}}\n- Xem [mục 5](#/n/viem-ruot-thua-cap/5) và [mục 6](#/n/viem-ruot-thua-cap/6)\n@@tab Điều trị\n- Cắt ruột thừa sớm; kháng sinh bao phủ gram âm và kỵ khí; viêm phúc mạc: tiếp tục 4–7 ngày sau mổ {{BHNgTH tr.47}}\n- Áp-xe: ≤4 cm kháng sinh trước; >4–6 cm kèm chọc hút/dẫn lưu; ≥7 cm nên mổ {{BHNgTH tr.48}}\n- Đám quánh: không mổ cấp cứu; mổ nguội sau 6–12 tuần có thể cân nhắc; nội soi đại tràng sau 1 tháng {{BHNgTH tr.49}}\n- Xem [mục 7.3](#/n/viem-ruot-thua-cap/7)\n@@tab Tiên lượng – Dự phòng\n- Mổ sớm: tử vong 0,1–0,2%; trễ: đến 10% {{BHNgTH tr.29}}\n- Biến chứng sau mổ hay gặp: nhiễm khuẩn vết mổ; áp-xe tồn lưu cao hơn sau nội soi {{BHNgTH tr.49}} {{BHNgTH tr.50}}\n- Xem [mục 8](#/n/viem-ruot-thua-cap/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Nguy cơ mắc suốt đời nam / nữ | ==8,6% / 6,9%== | {{BHNgTH tr.29}} |\n| Tử vong: mổ sớm / đến trễ | ==0,1–0,2% / đến 10%== | {{BHNgTH tr.29}} |\n| Áp lực lòng ruột thừa khi tắc | ==50–65 mmHg== | {{BHNgTH tr.31}} |\n| Đau di chuyển xuống hố chậu phải sau | ==6–12 giờ== | {{BHNgTH tr.33}} |\n| Chán ăn / buồn nôn, nôn | ==trên 90% / 60–80%== | {{BHNgTH tr.33}} |\n| Bạch cầu gợi ý biến chứng | ==trên 18.000/mm3== | {{BHNgTH tr.35}} |\n| Siêu âm: đường kính ruột thừa viêm | ==trên 6 mm, không xẹp== | {{BHNgTH tr.36}} |\n| CLVT: đường kính / bề dày thành | ==trên 6 mm / trên 2 mm== | {{BHNgTH tr.36}} |\n| Độ nhạy siêu âm / CLVT / MRI | ==83% / 91–94% / 97–100%== | {{BHNgTH tr.36}} {{BHNgTH tr.37}} {{BHNgTH tr.38}} |\n| Alvarado: tối đa; ngưỡng cao | ==10 điểm; 9–10 rất nhiều khả năng== | {{BHNgTH tr.38}} |\n| AIR: tối đa; ngưỡng cao | ==12 điểm; 9–12 rất cao== | {{BHNgTH tr.38}} |\n| PAS: theo dõi / nghĩ VRT | ==≤5 / ≥6 điểm== | {{BHNgTH tr.42}} |\n| Kháng sinh sau mổ khi viêm phúc mạc | ==ít nhất 4–7 ngày== | {{BHNgTH tr.47}} |\n| Áp-xe: ngưỡng kích thước xử trí | ==≤4 cm; >4–6 cm; ≥7 cm== | {{BHNgTH tr.48}} |\n| Đám quánh: mổ nguội / nội soi đại tràng | ==sau 6–12 tuần / sau 1 tháng== | {{BHNgTH tr.49}} |\n| Áp-xe tồn lưu: nội soi / mổ mở | ==4,6% / 1%== | {{BHNgTH tr.50}} |\n\n> [!warn] Bẫy thi thường gặp\n> - **Sốt không bắt buộc**: 25–50% có thân nhiệt bình thường khi vào viện; chán ăn mới gặp trên 90% {{BHNgTH tr.33}} {{BHNgTH tr.35}}\n> - **Phản ứng dội không đồng nghĩa viêm phúc mạc**; thành bụng co cứng như gỗ ít gặp trong VRT, gặp ở thủng dạ dày {{BHNgTH tr.34}}\n> - **Rovsing, Dunphy, Markle** là phản ứng dội gián tiếp; Blumberg là trực tiếp {{BHNgTH tr.34}}\n> - **Đám quánh không mổ cấp cứu**; đừng nhầm với áp-xe (khối mềm, sốt cao, nhiễm trùng rõ) {{BHNgTH tr.46}} {{BHNgTH tr.49}}\n> - **Tắc lòng ruột thừa không phải lúc nào cũng khởi phát bệnh**: ở thể xuất tiết, tắc là hậu quả của viêm {{BHNgTH tr.32}}\n> - **Cách đọc Alvarado**: 5–6 là \"không chắc\", chưa đến mức loại trừ; nhóm nguy cơ cao theo WSES là trên 8 điểm {{BHNgTH tr.38}} {{BHNgTH tr.39}}\n> - **Nôn sau đau** gợi ý VRT; nôn trước đau hay gặp ở viêm dạ dày ruột {{TCBN tr.48}}\n\n@@fold Nguồn tài liệu\n- **BHNgTH** Giáo trình Bệnh học ngoại khoa tiêu hóa 2025, chương Viêm ruột thừa, tr.29–50 (số trang PDF); riêng hai bảng điểm Alvarado và AIR là hình trên tr.39, đọc từ ảnh trang\n- **TCBN** Tiếp cận bệnh nhân ngoại khoa Y3: tr.25–26 (đau ¼ dưới phải, siêu âm và CLVT trong viêm phúc mạc), tr.46 (đau tạng và đau thành), tr.48 (nôn kèm đau bụng)\n@@end\n\n@@fold Nguồn ngoài\n- Không dùng nguồn ngoài trong bài này.\n@@end\n\n@@fold! Tự kiểm tra (12 thẻ)\n- Kiểu đau điển hình của VRT cấp? :: Đau âm ỉ quanh rốn hoặc trên rốn, sau 6–12 giờ chuyển xuống bụng dưới bên phải\n- Tam chứng Murphy là gì? :: Trình tự: đau bụng dưới phải, rồi nôn, sau đó mới sốt\n- Dấu Rovsing là gì? :: Ấn hố chậu trái gây đau hố chậu phải (phản ứng dội gián tiếp)\n- Kể ba phản ứng dội gián tiếp ngoài Rovsing? :: Dấu Dunphy (đau khi ho), nghiệm pháp Markle (dập gót chân), nhảy lò cò chân phải ở trẻ\n- Dấu hiệu siêu âm của ruột thừa viêm? :: Cấu trúc ống thành dày, đường kính ngoài trên 6 mm, không xẹp khi ép đầu dò; dấu ngón tay hoặc hình bia\n- Điểm Alvarado 9–10 và dưới 5 có ý nghĩa gì? :: 9–10: rất nhiều khả năng VRT; dưới 5: dường như không phải VRT\n- Nhóm nguy cơ theo Alvarado/AIR (WSES 2016) và xử trí? :: Thấp (dưới 5): theo dõi ngoại trú; trung bình (5–8): giữ lại theo dõi; cao (trên 8): nhập viện ngay\n- Ngưỡng PAS ở trẻ em? :: ≤5 theo dõi, ≥6 nghĩ VRT; PAS dưới 2 loại trừ VRT cấp đúng 99%\n- Tiêu chuẩn vàng điều trị VRT cấp và lựa chọn ưu tiên? :: Cắt ruột thừa; nội soi là điều trị ưu tiên\n- Viêm phúc mạc do VRT vỡ cần kháng sinh thế nào? :: Bao phủ gram âm và kỵ khí, tiếp tục ít nhất 4–7 ngày sau mổ\n- Xử trí áp-xe ruột thừa theo kích thước? :: ≤4 cm: kháng sinh trước; >4–6 cm: kháng sinh + chọc hút/dẫn lưu; ≥7 cm hoặc giữa các quai ruột: nên mổ\n- Đám quánh ruột thừa xử trí ra sao? :: Không mổ cấp cứu, theo dõi; mổ nguội sau 6–12 tuần có thể cân nhắc; nội soi đại tràng sau 1 tháng\n@@end"}, {"kind": "foundation", "disease": "", "short": "Nhiễm khuẩn ngoại khoa", "group": "Nhiễm khuẩn và vết thương", "section": 2, "order": 1, "khung": [], "id": "nhiem-khuan-ngoai-khoa", "title": "Nhiễm khuẩn ngoại khoa", "layer": "nen", "module": "ngoai-tong-quat", "tags": ["nhiễm khuẩn vết mổ", "kháng sinh dự phòng", "phân loại phẫu thuật", "vết thương nhiễm trùng", "áp-xe", "viêm phúc mạc"], "source": "BHNgTH tr.23–26, 47, 49–50, 54–55, 111, 352, 413–426; TCBN tr.99–105", "body": "> [!key] Nhiễm khuẩn ngoại khoa trong một nhìn\n> - **Nhiễm khuẩn vết mổ (NKVM)** là nhiễm khuẩn tại hoặc gần vết mổ trong ==30 ngày== (==90 ngày== nếu có vật liệu cấy ghép) và là **nhiễm khuẩn bệnh viện phổ biến nhất** {{BHNgTH tr.24}}\n> - Nguy cơ NKVM được xếp theo **4 loại phẫu thuật**: sạch, sạch nhiễm, nhiễm, bẩn; loại phẫu thuật quyết định **dùng kháng sinh dự phòng hay kháng sinh điều trị** {{BHNgTH tr.24–25}}\n> - Dự phòng: kháng sinh đúng lúc (==trong 60 phút== trước rạch da), sát khuẩn da bằng **chlorhexidine**, **không cạo lông** bằng dao cạo {{BHNgTH tr.25–26}}\n> - Ổ nhiễm khuẩn có mủ (áp-xe) thì điều trị chính là **rạch dẫn lưu** {{BHNgTH tr.424}}\n> - Vết thương nhiễm trùng được nhận biết bằng đáy vết thương, dịch, mùi, mô quanh vết thương; cấy dịch để chọn kháng sinh {{TCBN tr.100–105}}\n\n> [!doc] Phạm vi nguồn\n> Bài dựa trên giáo trình bệnh học ngoại tiêu hóa và bài tiếp cận vết thương nhiễm trùng của giáo trình tiếp cận bệnh nhân ngoại khoa. Các nội dung chưa có trong hai giáo trình này (cơ chế đề kháng, tác nhân, nhiễm khuẩn bệnh viện từng vị trí, áp-xe lạnh, nhiễm khuẩn dụng cụ cấy ghép, nhiễm khuẩn mô mềm hoại tử) chưa được đưa vào bài.\n\n### 1. Định nghĩa nhiễm khuẩn vết mổ\n- NKVM: nhiễm khuẩn liên quan thủ thuật, phẫu thuật, xảy ra **tại hoặc gần vết mổ** trong ==30 ngày==, hoặc ==90 ngày== nếu có vật liệu cấy ghép, tính từ ngày mổ {{BHNgTH tr.24}}\n- Là nhiễm khuẩn bệnh viện phổ biến nhất; làm tăng bệnh tật, tử vong và chi phí điều trị {{BHNgTH tr.24}}\n- Phẫu thuật bụng, nhất là phẫu thuật tiêu hóa, **luôn tiềm ẩn nguy cơ cao** nhiễm khuẩn và biến chứng hậu phẫu {{BHNgTH tr.24}}\n- Tần suất tham khảo: sau cắt khối tá tụy, nhiễm trùng vết mổ chiếm khoảng ==5–20%== {{BHNgTH tr.352}}\n\n### 2. Phân loại phẫu thuật theo nguy cơ nhiễm khuẩn\n\nHệ thống phân loại của Trung tâm kiểm soát bệnh tật Hoa Kỳ (CDC) từ năm 1964, chia **4 mức** {{BHNgTH tr.24}}\n\n| Loại | Đặc điểm | Ví dụ trong nguồn |\n|---|---|---|\n| **Sạch** | Vết mổ không viêm, không chấn thương, **không gián đoạn kỹ thuật**, không thông vào cơ quan nội tạng (hô hấp, tiêu hóa, sinh dục, tiết niệu) {{BHNgTH tr.24}} | Phẫu thuật tuyến giáp, thoát vị bẹn {{BHNgTH tr.24}} |\n| **Sạch nhiễm** | Vết mổ **có thông vào cơ quan nội tạng** nhưng không chảy dịch đáng kể {{BHNgTH tr.24}} | Cắt ruột thừa, cắt dạ dày {{BHNgTH tr.24}} |\n| **Nhiễm** | Vết thương hở, tai nạn mới, **chảy nhiều dịch** tiêu hóa, thông vào đường niệu hay mật có nước tiểu hoặc dịch mật nhiễm khuẩn; viêm cấp tính, không có mủ {{BHNgTH tr.24–25}} | Cắt túi mật do viêm túi mật cấp, khâu thủng dạ dày {{BHNgTH tr.25}} |\n| **Bẩn** | Vết thương chấn thương có mô hoại tử, dị vật, nhiễm bẩn phân, hay thông vào ổ mủ {{BHNgTH tr.25}} | Viêm phúc mạc phân do thủng đại tràng, áp-xe trong ổ bụng {{BHNgTH tr.25}} |\n\n> [!tip] Cách nhớ: sạch thì **không mở tạng**; sạch nhiễm thì **mở tạng nhưng không tràn dịch**; nhiễm thì **tràn dịch hoặc viêm cấp**; bẩn thì **có mủ, phân hoặc mô hoại tử**\n\n> [!warn] Thủng loét dạ dày tá tràng mổ **sau 12 giờ** kể từ khởi phát phải coi là phẫu thuật **nhiễm hoặc bẩn**, vì sau 12–24 giờ đã có nhiễm trùng ổ bụng {{BHNgTH tr.55}}\n\n### 3. Kháng sinh dự phòng trước mổ\n\n> [!key] Kháng sinh dự phòng là dùng kháng sinh **trước khi có nhiễm trùng**, nhằm giảm tỷ lệ NKVM mà **không làm tăng đề kháng kháng sinh** hay tác dụng phụ {{BHNgTH tr.25}}\n\n| Loại phẫu thuật | Xử trí kháng sinh |\n|---|---|\n| Sạch | **Chỉ dùng khi nguy cơ cao**: có bệnh nền, phẫu thuật vùng bụng, mổ kéo dài ==trên 2 giờ==, hoặc đặt vật liệu cấy ghép {{BHNgTH tr.25}} |\n| Sạch nhiễm | **Cần** kháng sinh dự phòng {{BHNgTH tr.25}} |\n| Nhiễm và bẩn | Dùng kháng sinh **điều trị**, không chỉ dự phòng {{BHNgTH tr.25}} |\n\n- Chọn thuốc theo **vị trí mổ** và hệ vi khuẩn thường trú (thường là gram dương) {{BHNgTH tr.25}}\n- {g|Cefazolin} (cephalosporin thế hệ 1): chọn cho nhiều phẫu thuật vì phổ phù hợp, hiệu quả, an toàn, rẻ; cefuroxime (thế hệ 2) phủ gram âm rộng hơn {{BHNgTH tr.25}}\n- Dị ứng cephalosporin: thay bằng ciprofloxacin, vancomycin hoặc clindamycin {{BHNgTH tr.25}}\n- **Thời điểm**: bắt đầu trong ==60 phút== trước khi rạch da {{BHNgTH tr.25}}\n- **Lặp liều** trong mổ nếu mổ quá ==2 lần thời gian bán hủy== của thuốc hoặc mất máu trên ==1.500 ml== {{BHNgTH tr.25}}\n- Viêm ruột thừa cấp thể sung huyết: có thể chỉ cần ==1 liều== kháng sinh dự phòng trước mổ {{BHNgTH tr.47}}\n- Mở bụng thám sát: có chỉ định kháng sinh dự phòng; tắc ruột không biến chứng thì **không** dùng kháng sinh {{BHNgTH tr.111}}\n\n> [!warn] Giáo trình nêu thời điểm là **trong 60 phút** trước rạch da. Nếu tài liệu khác ghi mốc khác (ví dụ 30 phút) thì ghi rõ nguồn khi dùng, không trộn lẫn.\n\n### 4. Chuẩn bị người bệnh để giảm nhiễm khuẩn\n\n@@tabs\n@@tab Sát khuẩn da\n- Sát khuẩn giúp giảm lượng vi khuẩn thường trú trên da {{BHNgTH tr.26}}\n- {g|Chlorhexidine} được khuyến cáo vì hiệu quả hơn povidone-iodine {{BHNgTH tr.26}}\n- Phân tích tổng hợp 9 thử nghiệm, 2479 người bệnh: chlorhexidine giảm NKVM tốt hơn, ==RR 0,70 (KTC 95% 0,52–0,92)== {{BHNgTH tr.26}}\n@@tab Tẩy lông\n- Tẩy lông không đúng cách có thể **làm tăng** NKVM {{BHNgTH tr.26}}\n- {r|Tránh cạo bằng dao cạo}; nếu thật cần thì dùng tông đơ hoặc chất làm rụng lông {{BHNgTH tr.26}}\n- Phân tích tổng hợp 19 thử nghiệm: không tẩy lông giảm NKVM so với cạo, ==RR 0,56 (KTC 95% 0,34–0,96)== {{BHNgTH tr.26}}\n- Nếu cần tẩy, thời điểm tối ưu là **ngay trước khi rạch da** {{BHNgTH tr.26}}\n@@tab Bệnh nền\n- Đái tháo đường làm tổn thương cơ quan đích, **ảnh hưởng lành vết thương**, tăng biến chứng sau mổ {{BHNgTH tr.23}}\n- Mục tiêu trước mổ: đường huyết dưới ==180 mg/dL== và tránh hạ đường huyết chu phẫu {{BHNgTH tr.23}}\n- Cần ngưng thuốc hạ đường huyết uống tác dụng kéo dài (sulfonylurea, metformin), chuyển sang thuốc tác dụng ngắn hoặc insulin {{BHNgTH tr.23}}\n@@tab Chuẩn bị ruột\n- Chế độ ăn lỏng 1–2 ngày trước phẫu thuật tiêu hóa, gan mật {{BHNgTH tr.26}}\n@@end\n\n> [!key] Kiểm soát nhiễm khuẩn gồm: **chuẩn bị người bệnh trước mổ, vô khuẩn phòng mổ, dụng cụ mổ và chăm sóc hậu phẫu** {{BHNgTH tr.25}}\n\n### 5. Nhiễm khuẩn vết mổ sau các phẫu thuật tiêu hóa\n- **Cắt ruột thừa**: NKVM là biến chứng thường gặp nhất của mổ mở; mổ sớm khi ruột thừa chưa thủng và có kháng sinh dự phòng thì NKVM ==dưới 5%== {{BHNgTH tr.49}}\n- Mổ nội soi có tỷ lệ NKVM thấp hơn mổ mở: ==0,34% so với 0,59%==, vì vết đặt trocar ngắn và da, thành bụng được cách ly khỏi dịch bẩn {{BHNgTH tr.49}}\n- **Cắt khối tá tụy**: điều trị NKVM bằng chăm sóc vết mổ, dẫn lưu, kháng sinh **theo kết quả cấy** tại vết mổ; nhiễm trùng sâu hoặc trong ổ bụng xử trí như áp-xe trong ổ bụng {{BHNgTH tr.352}}\n\n> [!red] Viêm phúc mạc do ruột thừa vỡ: sau cắt ruột thừa phải **làm sạch ổ bụng**, dẫn lưu khi cần và tiếp tục kháng sinh **ít nhất ==4–7 ngày==**, phủ cả gram âm và vi trùng kỵ khí đường ruột {{BHNgTH tr.47}}\n\n### 6. Áp-xe trong ổ bụng và sau mổ\n- Áp-xe tồn lưu sau cắt ruột thừa: đa số do **không làm sạch xoang phúc mạc**; hay gặp hơn sau mổ nội soi (==4,6% so với 1%==) {{BHNgTH tr.50}}\n- Vị trí hay gặp sau cắt khối tá tụy: vùng **dưới gan phải** hoặc **dưới hoành trái**; xử trí bằng dẫn lưu dưới hướng dẫn siêu âm, đôi khi phải mổ lại; cần tìm **rò tụy** bị che lấp {{BHNgTH tr.352}}\n- Áp-xe ruột thừa: điều trị bảo tồn bằng kháng sinh, có thể kèm chọc hút hoặc dẫn lưu qua da trước; không đáp ứng hoặc ổ quá lớn mới mổ {{BHNgTH tr.48}}\n  - Ổ nhỏ ==≤ 4 cm==: kháng sinh trước; ổ ==> 4–6 cm==: kháng sinh phối hợp chọc hút hoặc dẫn lưu {{BHNgTH tr.48}}\n\n### 7. Áp-xe quanh hậu môn, quanh trực tràng: nguyên tắc rạch dẫn lưu\n\n> [!key] **Điều trị chính là phẫu thuật dẫn lưu**, làm sớm; không có dấu hiệu phập phều không phải lý do trì hoãn {{BHNgTH tr.424}}\n\n- Bệnh sinh: một **tuyến trong khe hậu môn** bị tắc nghẽn và nhiễm khuẩn, tạo ổ mủ ở dưới da, gian cơ thắt hoặc các khoang sâu hơn {{BHNgTH tr.413}}\n- Không dẫn lưu thì áp-xe lan sang khoang liền kề, tiến triển thành **nhiễm khuẩn toàn thân**, hoặc vỡ tự nhiên rồi thành rò mủ mạn tính {{BHNgTH tr.413}}\n- ==40–50%== áp-xe được rạch ở giai đoạn cấp chuyển thành **rò hậu môn** {{BHNgTH tr.413}}\n- Đường rạch da **càng gần rìa hậu môn càng tốt** để rút ngắn đường rò {{BHNgTH tr.424}}\n- Nhét gạc chặt sau rạch: chỉ áp dụng khi cần (khoang áp-xe lớn, nguy cơ chảy máu cao), vì gạc gây đau, kéo dài nhiễm khuẩn và có thể gây mất tự chủ hậu môn {{BHNgTH tr.425}}\n- **Kháng sinh** theo kinh nghiệm một đợt sau rạch dẫn lưu, thường amoxicillin-clavulanate 4–5 ngày hoặc ciprofloxacin phối hợp metronidazole {{BHNgTH tr.425}}\n- Cấy vết thương **không cần thường quy**; cân nhắc khi sẽ dùng kháng sinh, đã dùng nhiều đợt kháng sinh hoặc suy giảm miễn dịch {{BHNgTH tr.426}}\n\n### 8. Tiếp cận vết thương nhiễm trùng\n\n@@tabs\n@@tab Hỏi bệnh\n- Xác định nguyên nhân và **loại vết thương**: chấn thương, vết mổ, loét tì đè, loét tĩnh mạch, bàn chân tiểu đường {{TCBN tr.99}}\n- **Cấp tính** (mới do mổ hoặc chấn thương) khác **mạn tính** (loét chân, loét tì đè, loét do đái tháo đường, vết thương từ mô ác tính), vết thương mạn dễ có đợt nhiễm trùng {{TCBN tr.99}}\n- Triệu chứng tại chỗ: đau, dịch (lượng, màu, mùi); toàn thân: sốt, mệt {{TCBN tr.99}}\n- Yếu tố làm chậm lành: tuổi, bệnh mạn tính, nhiễm trùng, suy dinh dưỡng, hút thuốc, thuốc (steroid, NSAID, ức chế miễn dịch) {{TCBN tr.99–100}}\n@@tab Khám vết thương\n- **Mô hoại tử** (nâu hoặc đen) và **mô mục** (vàng, dính): làm chậm lành, tạo ổ nhiễm trùng, cần cắt lọc nếu nhiều {{TCBN tr.100}}\n- **Mô hạt tốt**: hồng nhạt, chắc, không đau, khó chảy máu; mô hạt đỏ tươi dễ chảy máu có thể là dấu hiệu nhiễm trùng {{TCBN tr.101}}\n- **Mô nhiễm trùng**: đỏ đáy hoặc quanh vết thương, dễ chảy máu, phù nề, tiết dịch hoặc mủ, **mùi hôi**, thâm tím, đau {{TCBN tr.101}}\n- Mô quanh vết thương: đỏ sậm và rộng, **nhiệt độ da tăng** gợi ý nhiễm trùng; sờ nhiệt chủ quan nên phối hợp dấu hiệu khác {{TCBN tr.104}}\n- Vết thương có hóc, khoang hoặc đường hầm dưới da làm thoát dịch kém, tăng nguy cơ nhiễm trùng, phải thăm dò kỹ {{TCBN tr.102–103}}\n- Vết thương có mùi hôi: cắt lọc mô chết, loại bỏ chất tiết và tưới rửa {{TCBN tr.103}}\n@@tab Cận lâm sàng\n- **Công thức máu**: bạch cầu tăng gặp trong nhiễm trùng vết mổ; bạch cầu **thấp** có thể do rối loạn miễn dịch hoặc nhiễm trùng quá nặng {{TCBN tr.104}}\n- **Đường huyết, HbA1c**: đường huyết cao ảnh hưởng tế bào miễn dịch, tăng nguy cơ nhiễm trùng và chậm lành {{TCBN tr.105}}\n- **Albumin** thấp: dễ phù, rỉ dịch; phản ánh dinh dưỡng kém, vết thương khó lành {{TCBN tr.105}}\n- X quang: tìm dị vật, gãy xương, viêm xương {{TCBN tr.105}}\n@@end\n\n#### Các cách cấy vết thương {{TCBN tr.105}}\n\n| Kỹ thuật | Ưu điểm | Nhược điểm |\n|---|---|---|\n| **Sinh thiết mô** (mô mềm hoặc xương) | Kết quả đáng tin hơn cấy gạc | Xâm lấn: nguy cơ chảy máu, gieo rắc vi khuẩn vào mô |\n| **Cấy gạc** (swab) | Dùng nhiều nhất, dễ làm, không tổn thương mô | Có thể chỉ phản ánh dây nhiễm bề mặt |\n| **Cấy dịch chọc hút** | Phản ánh vi khuẩn trong mô vết thương | Cần đủ dịch; nguy cơ đưa vi trùng theo đường kim, tạo đường rò |\n\n> [!tip] Cấy vết thương nhằm tìm tác nhân **và làm kháng sinh đồ** để chọn thuốc nhạy {{TCBN tr.105}}\n\n### Điểm hay thi\n> [!warn] Những điểm dễ nhầm\n> - Phân loại phẫu thuật quyết định hướng kháng sinh: **sạch** (chỉ khi nguy cơ cao), **sạch nhiễm** (dự phòng), **nhiễm và bẩn** (điều trị) {{BHNgTH tr.25}}\n> - Kháng sinh dự phòng bắt đầu **trong 60 phút trước rạch da**; lặp liều khi mổ quá 2 lần thời gian bán hủy hoặc mất máu trên 1.500 ml {{BHNgTH tr.25}}\n> - Dự phòng bằng **cefazolin**; dị ứng cephalosporin thì ciprofloxacin, vancomycin hoặc clindamycin {{BHNgTH tr.25}}\n> - Sát khuẩn bằng **chlorhexidine** hơn povidone-iodine; **không cạo lông** bằng dao cạo {{BHNgTH tr.26}}\n> - Đường huyết chu phẫu **dưới 180 mg/dL**, tránh hạ đường huyết {{BHNgTH tr.23}}\n> - Áp-xe quanh hậu môn: **dẫn lưu sớm**, không chờ phập phều; kháng sinh theo kinh nghiệm dùng sau dẫn lưu {{BHNgTH tr.424–425}}\n> - Thủng dạ dày tá tràng mổ sau 12 giờ: tính là phẫu thuật nhiễm hoặc bẩn {{BHNgTH tr.55}}\n> - NKVM trong **30 ngày** (**90 ngày** nếu có vật liệu cấy ghép) {{BHNgTH tr.24}}\n\n### Tự kiểm tra\n- Nhiễm khuẩn vết mổ được tính trong bao lâu sau mổ? :: ==30 ngày==, hoặc ==90 ngày== nếu có vật liệu cấy ghép {{BHNgTH tr.24}}\n- Bốn loại phẫu thuật theo nguy cơ nhiễm khuẩn là gì? :: Sạch, sạch nhiễm, nhiễm, bẩn {{BHNgTH tr.24}}\n- Cắt ruột thừa và cắt dạ dày thuộc loại nào? :: Phẫu thuật **sạch nhiễm** {{BHNgTH tr.24}}\n- Phẫu thuật loại nhiễm và bẩn dùng kháng sinh dạng nào? :: Kháng sinh **điều trị**, không chỉ dự phòng {{BHNgTH tr.25}}\n- Phẫu thuật sạch khi nào mới cần kháng sinh dự phòng? :: Khi nguy cơ cao: bệnh nền, mổ vùng bụng, mổ trên 2 giờ hoặc đặt vật liệu cấy ghép {{BHNgTH tr.25}}\n- Kháng sinh dự phòng dùng vào lúc nào? :: Bắt đầu trong ==60 phút== trước khi rạch da {{BHNgTH tr.25}}\n- Khi nào phải lặp liều kháng sinh trong mổ? :: Mổ quá ==2 lần thời gian bán hủy== của thuốc hoặc mất máu trên ==1.500 ml== {{BHNgTH tr.25}}\n- Thuốc dự phòng thường chọn và thuốc thay thế khi dị ứng cephalosporin? :: Cefazolin; thay bằng ciprofloxacin, vancomycin hoặc clindamycin {{BHNgTH tr.25}}\n- Thuốc sát khuẩn da được khuyến cáo và cách tẩy lông? :: Chlorhexidine; tránh dao cạo, dùng tông đơ hoặc chất làm rụng lông nếu cần {{BHNgTH tr.26}}\n- Mục tiêu đường huyết trước mổ ở người đái tháo đường? :: Dưới ==180 mg/dL==, tránh hạ đường huyết chu phẫu {{BHNgTH tr.23}}\n- Điều trị chính của áp-xe quanh hậu môn? :: **Rạch dẫn lưu sớm**; kháng sinh theo kinh nghiệm sau dẫn lưu {{BHNgTH tr.424–425}}\n- Dấu hiệu gợi ý mô nhiễm trùng ở vết thương? :: Đỏ, dễ chảy máu, phù nề, tiết dịch hoặc mủ, mùi hôi, đau {{TCBN tr.101}}"}, {"kind": "overview", "disease": "", "short": "", "group": "", "section": 0, "order": 0, "khung": [], "id": "ngoai-tong-quat-tong-quan", "title": "Tổng quan module Ngoại tổng quát", "layer": "nen", "module": "ngoai-tong-quat", "tags": ["ngoại tổng quát", "tổng quan", "danh mục bài", "ngoại tiêu hóa"], "source": "Trang module \"NGOẠI TỔNG QUÁT\" trong Notion (danh mục giáo trình); Giáo trình Bệnh học ngoại khoa tiêu hóa 2025; TCBN ngoại khoa Y3", "body": "> [!note] Module đang được xây dựng. Ưu tiên hiện nay: các bài tiếp cận vấn đề và các ung thư ngoại khoa tiêu hóa, vì phục vụ module Ung bướu. Bài ở mục 2: [Nhiễm khuẩn ngoại khoa](#/n/nhiem-khuan-ngoai-khoa). Danh mục dưới đây theo cấu trúc giáo trình bạn đã dùng trong Notion; mục chưa có bài sẽ được bổ sung dần.\n\n### 1. Cấu trúc học tập\n- **2 Ngoại khoa cơ sở**: một số vấn đề cơ bản của ngoại khoa (nhiễm khuẩn, sốc chấn thương, phòng mổ, đánh giá trước phẫu thuật, phụ mổ…).\n- **3 Tiếp cận theo vấn đề**: đi từ triệu chứng hoặc hội chứng đến chẩn đoán.\n- **4 Bệnh học tiêu hóa**: từng bệnh, mỗi bệnh một trang có tab (bệnh học, triệu chứng, cận lâm sàng, chẩn đoán, điều trị, tiên lượng, tóm tắt).\n- **5 Cấp cứu ngoại**: cấp cứu ngoại tiêu hóa và chấn thương, nhận diện và xử trí ban đầu.\n\n### 2. Danh mục theo giáo trình\n@@tabs\n@@tab Tiếp cận theo vấn đề\n| Vấn đề | Trạng thái |\n|---|---|\n| Đau bụng cấp | [Đã có](#/n/dau-bung-cap) |\n| Khối u vùng bụng | [Đã có](#/n/khoi-u-bung) |\n| Vàng da | [Đã có](#/n/vang-da) |\n| Nuốt nghẹn – nôn ói | [Đã có](#/n/nuot-nghen-non-oi) |\n| Xuất huyết tiêu hóa | [Đã có](#/n/xuat-huyet-tieu-hoa) |\n| Bí trung đại tiện | [Đã có](#/n/bi-trung-dai-tien) |\n| Than phiền vùng hậu môn | [Đã có](#/n/than-phien-vung-hau-mon) |\n| Bỏng; chấn thương và vết thương bụng; khối phồng vùng bẹn, bìu | Chưa có |\n| Hội chứng chảy máu trong ổ bụng; viêm phúc mạc; nhiễm trùng vết thương | Chưa có |\n@@tab Bệnh học tiêu hóa\n| Bệnh | Trạng thái |\n|---|---|\n| Viêm ruột thừa cấp | [Đã có](#/n/viem-ruot-thua-cap) |\n| Ung thư thực quản | [Đã có](#/n/ngoai-ung-thu-thuc-quan) |\n| Ung thư dạ dày | [Đã có](#/n/ngoai-ung-thu-da-day) |\n| Ung thư đại tràng | [Đã có](#/n/ngoai-ung-thu-dai-trang) |\n| Ung thư trực tràng | [Đã có](#/n/ngoai-ung-thu-truc-trang) |\n| Ung thư quanh bóng Vater | [Đã có](#/n/ngoai-ung-thu-quanh-bong-vater) |\n| Ung thư biểu mô tế bào gan | [Đã có](#/n/ngoai-ung-thu-gan-hcc) |\n| Thủng ổ loét dạ dày – tá tràng; hội chứng ứ đọng dạ dày – hẹp môn vị; tắc ruột cơ học | Chưa có |\n| Chấn thương – vết thương bụng; chấn thương lách; co thắt tâm vị; bệnh túi thừa đại tràng | Chưa có |\n| Sỏi đường mật chính; sỏi túi mật; thoát vị thành bụng | Chưa có |\n| Áp-xe và rò quanh hậu môn; trĩ; bệnh đa polyp; u mô đệm đường tiêu hóa; polyp túi mật | Chưa có |\n@@end"}, {"kind": "foundation", "disease": "", "short": "Bí trung đại tiện", "group": "", "section": 3, "order": 6, "khung": [], "id": "bi-trung-dai-tien", "title": "Tiếp cận bí trung đại tiện", "layer": "trieuchung", "module": "ngoai-tong-quat", "tags": ["bí trung đại tiện", "tắc ruột", "liệt ruột", "giả tắc đại tràng", "ung thư đại trực tràng", "xoắn đại tràng chậu hông", "thoát vị nghẹt", "táo bón"], "source": "TCBN tr.1–7, Notion", "body": "> [!key] Bí trung đại tiện = hội chứng tắc nghẽn đường tiêu hóa dưới cho đến khi chứng minh khác\n> - **Hội chứng tắc nghẽn đường tiêu hóa dưới**: bế tắc hoặc ứ trệ lưu thông ống tiêu hóa **từ hỗng tràng trở xuống**; gồm **tắc ruột cơ học** (có vật cản) và **liệt ruột** (mất nhu động, không có vật cản) {{TCBN tr.2}}\n> - Ở bệnh nhân bí trung đại tiện là chính, nguyên nhân thường gặp nhất là **ung thư đại trực tràng** (ít nhất trên 50%), hay gặp ở đại tràng chậu hông rồi góc lách; kế đến là dính ruột, thoát vị, xoắn ruột {{TCBN tr.3}}\n> - Việc đầu tiên: **phân biệt với táo bón bằng thăm trực tràng** (táo bón: bóng trực tràng đầy phân cứng; tắc ruột: bóng trực tràng rỗng) {{TCBN tr.6}}\n> - Liên quan nguyên nhân hay gặp nhất: [Ung thư đại tràng](#/n/ngoai-ung-thu-dai-trang), [Ung thư trực tràng](#/n/ngoai-ung-thu-truc-trang); khung 128 vấn đề [STT 61](#/khung/61) (táo bón, thay đổi thói quen đi tiêu)\n\n### 1. Đại cương và phạm vi\n- Tắc nghẽn đường tiêu hóa là **cấp cứu thường gặp** trong ngoại khoa; biểu hiện thay đổi theo vị trí tắc và nguyên nhân {{TCBN tr.1}}\n- Ranh giới trên/dưới có nhiều cách chia (phôi thai học; cổ điển ở van hồi manh tràng; xuất huyết tiêu hóa ở **góc tá–hỗng tràng**). Tài liệu chọn **góc Treitz** vì tắc trên và dưới góc này khác nhau về lâm sàng và điều trị {{TCBN tr.1}}\n- **Trên** góc Treitz: tắc thực quản và tắc đường thoát dạ dày. **Dưới** góc Treitz: ruột non và đại trực tràng, gọi chung là tắc ruột {{TCBN tr.1}}\n- Bí trung đại tiện là biểu hiện chung của tắc ruột cơ học lẫn liệt ruột {{Notion}}\n- Thường đi kèm **đau bụng quặn cơn, nôn, chướng bụng** (tứ chứng); có khi chỉ bí trung đại tiện đơn độc, các triệu chứng còn lại ít hoặc không rõ nên khó chẩn đoán {{TCBN tr.2}}\n\n### 2. Nguyên nhân\n#### 2.1. Tắc ruột cơ học\nPhân theo vị trí gây tắc, {{TCBN tr.3}} chia ba nhóm:\n\n| Nhóm | Nguyên nhân | Nguồn |\n|---|---|---|\n| **Trong lòng ruột** | Bã thức ăn khó tiêu (trẻ em, đã mổ cắt dạ dày, rối loạn tâm thần); bã phân (hiếm khi gây tắc và thủng ở người suy nhược, lớn tuổi); **sỏi mật** qua đường rò túi mật – tá tràng, hay kẹt ở van hồi manh tràng (kẹt ở tá tràng: hội chứng Bouveret) | {{TCBN tr.3}} |\n| **Trên thành ruột** (chít hẹp lòng ruột) | Ác tính là thường gặp nhất ở người lớn: **ung thư đại trực tràng**. Lành tính: bệnh viêm ruột (Crohn thường gặp nhất), bệnh túi thừa đại tràng, viêm mạn, thuốc NSAID, sau xạ trị hoặc phẫu thuật | {{TCBN tr.3}} |\n| **Ngoài thành ruột** | **Dính ruột** (nguyên nhân thường gặp nhất của tắc ruột nói chung, tỉ lệ đang giảm nhờ găng không bột và phẫu thuật nội soi); **thoát vị**; **xoắn ruột** | {{TCBN tr.3}} |\n\n- **Thoát vị**: thoát vị bẹn gây đa số trường hợp tắc ruột do thoát vị; thoát vị đùi hay gây tắc vì ống đùi sâu và chắc, gặp ở người mới sụt cân nhiều; hiếm: thoát vị lỗ bịt ở nữ lớn tuổi, gầy {{TCBN tr.3}}\n- **Xoắn ruột**: một đoạn ruột xoay quanh trục mạc treo, thành **tắc ruột quai kín** (tắc cả đầu gần và đầu xa, không có đường giải áp). Hay gặp nhất ở **đại tràng chậu hông** (đại tràng chậu hông dài, chân mạc treo ngắn, chứa phân đóng khuôn); cũng có xoắn dạ dày, ruột non, manh tràng {{TCBN tr.3}}\n- Thoát vị, dây dính, thoát vị nội, xoắn ruột là nguyên nhân chủ yếu của **tắc ruột do thắt** {{TCBN tr.3}}\n- Theo cơ chế tắc, Notion chia: **tắc đơn thuần** (chỉ tắc lòng ruột), **thắt nghẹt** (kèm thắt mạch máu mạc treo: dây thắt, xoắn ruột non/đại tràng, lồng ruột, thoát vị nghẹt, thoát vị nội), **quai kín** (tắc hai đầu: ung thư đại tràng khi van hồi manh tràng còn hiệu lực, và các tắc do thắt trừ lồng ruột) {{Notion}}\n- Nguyên nhân từ ngoài ruột còn có khối u tạng lân cận, u di căn, áp xe (ruột thừa, túi thừa thủng, tồn lưu sau mổ) đè vào; ở trẻ sơ sinh có phân su, màng ngăn, teo ruột {{Notion}}\n\n#### 2.2. Liệt ruột và giả tắc đại tràng\n- Liệt ruột: mất nhu động do rối loạn dẫn truyền thần kinh, gây ứ dịch và hơi; ở đại tràng gọi là **giả tắc ruột, hội chứng Ogilvie** {{TCBN tr.3}}\n- Hay gặp nhất **sau phẫu thuật ổ bụng**, thường không quá **48–72 giờ**. Kéo dài hơn phải nghĩ nhiễm trùng ổ bụng, chảy máu trong ổ bụng, rối loạn chuyển hóa, thoát vị lỗ trocar (mổ nội soi) {{TCBN tr.3}}\n- Nguyên nhân khác: viêm phổi, rối loạn điện giải, tổn thương cột sống, chấn thương hoặc chảy máu sau phúc mạc, thiếu máu mạc treo, viêm tụy cấp, thuốc ức chế ba vòng {{TCBN tr.3}}\n- Cơ chế giả tắc đại tràng (Notion): kích thích giao cảm quá mức kết hợp ức chế phó giao cảm gây liệt đại tràng {{Notion}}\n\n### 3. Sinh lý bệnh (tóm tắt)\n- **Tại chỗ**: ứ dịch hơi gây tăng sinh vi trùng và độc tố; áp lực lòng ruột tăng đè xẹp tiểu tĩnh mạch thành ruột, gây phù nề, thoát dịch vào phúc mạc, giảm tưới máu, **hoại tử rồi thủng**. Tắc thắt nghẹt diễn tiến nhanh hơn vì nghẹt mạch máu mạc treo và thường là quai kín {{Notion}}\n- **Toàn thân**: dịch tiêu hóa 7–8 lít/ngày không được hấp thu nên mất nước, điện giải, cô đặc máu, có thể suy thận trước thận; trướng ruột đè cơ hoành gây thở nông, nhanh; muộn thì nhiễm trùng, sốc nhiễm trùng nhiễm độc {{Notion}}\n\n### 4. Lâm sàng\n#### 4.1. Hỏi bệnh\n- **Vị trí tắc quyết định bệnh cảnh**: tắc ruột non đoạn gần thì rầm rộ, nôn là chính; tắc thấp thì chậm hơn; tắc **nửa đại tràng trái hoặc trực tràng** thì khởi phát **âm thầm**, bí trung đại tiện là chính {{TCBN tr.4}}\n- Tắc cao trong **24 giờ đầu** còn có thể trung tiện, đại tiện được nhờ hơi phân còn sót dưới chỗ tắc, nên bí trung đại tiện thường xét từ **24 giờ sau khởi phát đau**; mỗi lần khám lại phải hỏi lại triệu chứng này {{TCBN tr.4}}, {{Notion}}\n- Trong bí trung và bí đại tiện thì **bí trung tiện quan trọng hơn** (người táo bón có thể 2 lần/tuần nhưng ngày nào cũng trung tiện); cần hỏi thói quen đi cầu, số ngày không đại tiện và không trung tiện, hoàn toàn hay còn ra ít, có dễ chịu hơn sau khi ra phân/hơi {{Notion}}\n- Người già, lú lẫn có thể khai không chính xác: hỏi người chăm sóc; **lồng ruột** có thể khai vẫn đi cầu nhưng phân có máu hoặc nhầy máu {{Notion}}\n- **Chướng bụng** đi kèm bí trung đại tiện; rõ ở tắc đại tràng hoặc phần thấp ruột non, ít ở tắc cao hoặc tắc quai kín {{TCBN tr.4}}\n- **Đau**: quặn cơn (đau tạng), không tư thế giảm đau; cơn kéo dài khoảng 30 giây, cách nhau vài ba phút ở tắc ruột non và **15–20 phút ở tắc đại tràng**; về sau cơn dày hơn và dài hơn {{TCBN tr.4}}\n- Vị trí đau: tắc ruột giữa thường đau **quanh rốn**; ruột cuối đau **hạ vị**; tắc rất cao đau thượng vị liên tục kèm nôn nhiều {{TCBN tr.4}}\n- **Nôn**: là dấu hiệu sớm của tắc cao; tắc càng thấp thì nôn càng trễ, tắc đại tràng thấp hoặc liệt ruột có thể không nôn; tắc lâu thì chất nôn đục, lợn cợn, giống dịch phân {{TCBN tr.4}}\n- **Tiền sử cần hỏi ngay**: mổ bụng trước đây, khối phồng thành bụng hoặc bẹn bìu, thoát vị đã biết; **sụt cân, thiếu máu, thay đổi thói quen đi cầu**; hô hấp; chấn thương, thuốc đang dùng {{TCBN tr.4}}\n- Notion bổ sung: khoảng 60% tắc ruột cơ học do dính sau mổ; mổ cắt dạ dày, cắt thần kinh X, nối vị tràng là cơ địa tắc do bã thức ăn; đã biết ung thư đại trực tràng nhưng từ chối mổ; sỏi túi mật chưa điều trị; thuốc opioid, thuốc COPD gây táo bón dễ nhầm {{Notion}}\n\n> [!red] Dấu hiệu nguy hiểm: nghĩ tắc ruột thắt nghẹt, thiếu máu ruột, thủng\n> - Đau **chuyển từ quặn cơn sang liên tục hoặc dữ dội hơn**; phát hiện trễ có thể thủng ruột {{TCBN tr.4}}\n> - **Sốt, mạch nhanh, bụng ấn đau, khối thoát vị đau, tăng bạch cầu** {{TCBN tr.3}}\n> - Ấn đau khu trú hoặc phản ứng thành bụng khu trú; khối thoát vị đỏ da hoặc ấn đau (thoát vị nghẹt) {{TCBN tr.5}}\n> - Mất nước, nhịp tim nhanh, hạ huyết áp; toan chuyển hóa, tăng amylase máu {{TCBN tr.4, 6}}\n> - Nếu nghi thiếu máu ruột hoặc viêm phúc mạc: **cân nhắc mổ sớm**, có thể không cần xác định nguyên nhân hay vị trí tắc {{TCBN tr.7}}\n\n#### 4.2. Thăm khám\n- **Toàn thân**: vào sớm thì tổng trạng và sinh hiệu có thể bình thường; muộn thì mất nước (véo da mất nhanh, khô niêm mạc, mạch nhanh, huyết áp giảm). Sốt gợi ý thiếu máu hoặc thủng, nhưng viêm túi thừa cấp, áp xe quanh đại tràng, bệnh viêm ruột cũng sốt; **sốt nhẹ 37,5–38,5°C** có thể chỉ do mất nước {{TCBN tr.4}}\n- **Nhìn**: sẹo mổ cũ, khối thoát vị thành bụng hoặc bẹn bìu (dính và thoát vị là hai nguyên nhân hay gặp nhất) {{TCBN tr.4}}; chướng bụng, **xoắn ruột thì sớm chỉ chướng khu trú một vùng**; người gầy thấy quai ruột nổi, **dấu rắn bò** (nhìn tiếp tuyến thành bụng, hoặc đặt tay thấy nổi gò khi lên cơn đau) {{TCBN tr.5}}\n- **Sờ**: ấn đau nhẹ thường gặp; có thể thấy khối u (tắc do u hoặc lồng ruột); khám kỹ bẹn đùi {{TCBN tr.5}}\n- **Nghe**: tiếng ruột mạnh, âm sắc cao, nhiều trong tắc ruột; **không nghe được** trong liệt ruột {{TCBN tr.5}}. Tắc thắt nghẹt hoặc đến muộn âm ruột có thể giảm, mất {{Notion}}\n- **Gõ**: vang vì quai ruột giãn đầy hơi {{TCBN tr.5}}\n- **Thăm hậu môn trực tràng** (bắt buộc): bóng trực tràng **rỗng** trong đa số tắc ruột; có thể thấy **u trực tràng gây tắc**, phân cứng, hoặc bóng giãn trống trong liệt ruột {{TCBN tr.5}}. Notion bổ sung: máu theo găng gợi lồng ruột, túi cùng Douglas phồng đau gợi viêm phúc mạc {{Notion}}\n\n### 5. Cận lâm sàng\n| Phương tiện | Vai trò và dấu hiệu | Nguồn |\n|---|---|---|\n| **X quang bụng đứng không sửa soạn** | **Lựa chọn đầu tiên**; cho biết có tắc không và ở ruột non hay đại tràng; **mức nước hơi xuất hiện sau 2 giờ**; kết hợp lâm sàng chẩn đoán được tắc cơ học 50–60%. Dấu hiệu: ruột non giãn **>3 cm**, đại tràng xẹp, mực nước hơi, thành ruột dày, chuỗi tràng hạt. Nhạy khoảng 80%, đặc hiệu khoảng 60%; đại tràng giãn ≥5 cm | {{TCBN tr.5}}, {{Notion}} |\n| Phân biệt ruột non và đại tràng trên phim | Ruột non nằm giữa bụng, nếp van chạy hết ngang lòng, san sát; đại tràng nằm rìa, van thưa, không hết ngang. **Xoắn đại tràng chậu hông**: một quai giãn lớn từ hố chậu lên bụng trên | {{TCBN tr.5}} |\n| Chụp nhiều phim cách vài giờ | Khi phim không điển hình; không đứng được thì nằm nghiêng hoặc nằm ngửa đầu cao 45° | {{TCBN tr.6}} |\n| X quang ngực thẳng | Hơi tự do dưới hoành khi thủng ruột | {{TCBN tr.6}} |\n| Chụp cản quang | Tài liệu nêu trước đây có dùng thuốc tan trong nước để tìm vị trí tắc đại tràng hoặc ruột non thấp; Notion: uống/qua ống thông cho tắc cao hoặc bán tắc ruột non ổn định, thụt qua hậu môn cho tắc đại tràng chưa biến chứng; ngày càng ít dùng | {{TCBN tr.6}}, {{Notion}} |\n| **Siêu âm** | Quai ruột giãn **≥2,5 cm** chứa dịch cạnh quai xẹp; **dấu máy giặt**; tắc đại tràng: nhiều đốm echo, ít nhu động; Doppler đánh giá tưới máu. Làm tại giường; nhạy ≥85% với tắc hoàn toàn (tùy người đọc) | {{TCBN tr.6}}, {{Notion}} |\n| **CT bụng chậu** | Phân biệt tắc và liệt ruột, vị trí, **nguyên nhân**, biến chứng thủng hoặc thiếu máu; ung thư thì xếp giai đoạn. **Vùng chuyển tiếp** giữa ruột giãn và xẹp là dấu chỉ điểm tắc, là dấu hiệu cần can thiệp phẫu thuật. Thiếu máu: thành dày, dấu bia, dịch bụng, không bắt thuốc, hơi thành ruột, xoắn mạch mạc treo. Nhạy và đặc hiệu >90% với tắc hoàn toàn; chỉ chụp khi huyết động ổn | {{TCBN tr.6}}, {{Notion}} |\n| **Xét nghiệm** | Bạch cầu, CRP tăng: nguyên nhân viêm hoặc biến chứng; mất nước: tăng urea, creatinin; hạ Cl, hạ K; **toan chuyển hóa hoặc tăng amylase máu: nghĩ thiếu máu ruột**; Hct tăng do cô đặc | {{TCBN tr.6}}, {{Notion}} |\n\n> [!tip] Phân biệt tắc ruột cơ học với liệt ruột\n> - **Cơ học**: đau quặn cơn, tiếng ruột tăng, dấu rắn bò; X quang chướng lệch hoặc khu trú, mực nước hơi chênh và đổi qua nhiều phim, mất hơi phân đại tràng (tắc ruột non); siêu âm dấu máy giặt; CT cần để xác định và tìm nguyên nhân {{Notion}}\n> - **Liệt ruột**: đau âm ỉ căng tức, tiếng ruột giảm hoặc mất, bối cảnh hậu phẫu, chấn thương cột sống, rối loạn chuyển hóa, thuốc an thần; X quang trướng đều dạ dày, ruột non, đại tràng, mực nước hơi không chênh; CT có thể không cần hoặc chỉ để loại trừ tắc cơ học {{Notion}}\n> - Liệt ruột cũng gặp trong viêm phúc mạc thứ phát, viêm tụy cấp {{Notion}}\n\n### 6. Lưu đồ tiếp cận\n1. **Xác định có bí trung đại tiện thật**: hỏi (nhất là trung tiện), **thăm trực tràng** để phân biệt táo bón (bóng trực tràng đầy phân cứng, thường vẫn trung tiện, không đau quặn, chướng, nôn) với tắc ruột (bóng rỗng) {{TCBN tr.6}}\n2. **Hỏi bệnh, tiền căn, khám** (mục 4); chỉ định hình ảnh bước đầu: X quang bụng đứng không sửa soạn, siêu âm bụng, CT bụng chậu cản quang khi cần {{TCBN tr.5–7}}\n3. **Trả lời sáu câu hỏi** {{TCBN tr.6–7}}:\n   - Tắc ruột cơ học hay liệt ruột? Nếu liệt ruột thì tìm nguyên nhân (hậu phẫu, giả tắc Ogilvie, viêm phúc mạc, nhiễm trùng ổ bụng, chảy máu trong ổ bụng, rối loạn điện giải, chấn thương cột sống, thiếu máu mạc treo, viêm tụy cấp, thuốc ức chế ba vòng) và xử trí theo nguyên nhân {{TCBN tr.7}}\n   - Cơ học: có nghi thiếu máu ruột hoặc viêm phúc mạc không? Có thì cân nhắc **mổ sớm**.\n   - Nếu tắc đơn thuần: tắc hoàn toàn hay bán tắc?\n   - Vị trí: ruột non hay ruột già?\n   - Nguyên nhân nghi ngờ?\n   - Đã có biến chứng toàn thân chưa?\n4. **Nhánh theo lưu đồ**: nghi thiếu máu hoặc thủng gồm tắc quai kín (do dây dính, do u đại tràng khi van hồi manh tràng đóng), xoắn (đại tràng chậu hông, ruột xoay bất toàn), thoát vị nghẹt (bẹn, đùi, bịt, thành bụng, vết mổ), lồng ruột; **tắc đơn thuần** gồm trong lòng ruột (bã thức ăn hoặc phân cứng, sỏi mật), trên thành ruột (u đại trực tràng, Crohn, viêm mạn, túi thừa, sau xạ trị hoặc phẫu thuật), ngoài thành (dính); **liệt ruột** gồm liệt ruột sau mổ, Ogilvie, viêm phúc mạc, nhiễm trùng hoặc chảy máu trong ổ bụng, rối loạn điện giải, chấn thương cột sống, thiếu máu mạc treo, viêm tụy cấp, thuốc chống trầm cảm {{TCBN tr.7}}\n5. **Hồi sức song song**: đánh giá mất nước, điện giải, nhiễm trùng, sốc (xét nghiệm máu giúp hồi sức điều chỉnh rối loạn sinh lý) {{Notion}}\n\n### 7. Gợi ý theo nguyên nhân thường gặp\n| Nguyên nhân | Gợi ý lâm sàng | Nguồn |\n|---|---|---|\n| **Ung thư đại trực tràng** | Khởi phát âm thầm, bí trung đại tiện là chính, chướng bụng; sụt cân, thiếu máu, **thay đổi thói quen đi cầu**, đi cầu máu; thăm trực tràng có thể sờ u; ít sờ được u dọc khung đại tràng vì bụng trướng; CT xếp giai đoạn | {{TCBN tr.3–5}}, {{Notion}} |\n| **Xoắn đại tràng chậu hông** | Chướng khu trú sớm; X quang một quai giãn lớn từ hố chậu lên bụng trên; tắc quai kín | {{TCBN tr.3, 5}} |\n| **Thoát vị nghẹt** | Khối phồng bẹn, đùi, thành bụng, vết mổ, ấn đau, đỏ da | {{TCBN tr.3, 5}} |\n| **Dính ruột** | Tiền căn mổ bụng, sẹo mổ cũ | {{TCBN tr.3–4}} |\n| **Sỏi mật gây tắc** | Hơi trong đường mật, tắc đoạn cuối ruột non, sỏi cản quang hố chậu phải (khoảng 10%): tam chứng Rigler | {{TCBN tr.5–6}} |\n| **Liệt ruột, giả tắc** | Hậu phẫu, bệnh nặng; âm ruột giảm hoặc mất; chướng đều | {{TCBN tr.3, 5}} |\n\n### Điểm hay thi\n> [!warn]\n> - Hội chứng tắc nghẽn đường tiêu hóa dưới: từ **hỗng tràng trở xuống**, hai nhóm tắc cơ học và liệt ruột {{TCBN tr.2}}\n> - Bí trung đại tiện là chính: nguyên nhân thường gặp nhất **ung thư đại trực tràng** (>50%), nhiều nhất ở đại tràng chậu hông {{TCBN tr.3}}\n> - Dính ruột là nguyên nhân thường gặp nhất của tắc ruột nói chung; thoát vị đùi hay gây tắc vì ống đùi sâu và chắc {{TCBN tr.3}}\n> - Xoắn đại tràng chậu hông là tắc quai kín {{TCBN tr.3}}\n> - Bí trung đại tiện xét từ **24 giờ** sau khởi phát đau; tắc cao sớm vẫn còn trung tiện được {{TCBN tr.4}}\n> - Đổi từ đau quặn cơn sang liên tục: nghĩ thắt nghẹt hoặc thiếu máu ruột {{TCBN tr.4}}\n> - X quang bụng đứng không sửa soạn là phương tiện **đầu tiên**; mực nước hơi sau 2 giờ; ruột non giãn >3 cm {{TCBN tr.5}}\n> - Táo bón thì bóng trực tràng đầy phân cứng, tắc ruột thì rỗng {{TCBN tr.6}}\n> - Liệt ruột sau mổ thường không quá 48–72 giờ {{TCBN tr.3}}\n> - Khác biệt số liệu: giáo trình mới (TCBN) chỉ nêu ngưỡng giãn của ruột non >3 cm; ngưỡng đại tràng ≥5 cm, độ nhạy và đặc hiệu X quang, CT chỉ có ở Notion (giáo trình cũ), không mâu thuẫn\n\n### Tự kiểm tra\n- Hội chứng tắc nghẽn đường tiêu hóa dưới là gì? :: Bế tắc hoặc ứ trệ lưu thông ống tiêu hóa từ hỗng tràng trở xuống; gồm tắc ruột cơ học và liệt ruột\n- Ranh giới tiêu hóa trên và dưới trong bài? :: Góc tá–hỗng tràng (góc Treitz)\n- Nguyên nhân thường gặp nhất của bí trung đại tiện là chính? :: Ung thư đại trực tràng (ít nhất trên 50%), nhiều nhất ở đại tràng chậu hông rồi góc lách\n- Nguyên nhân thường gặp nhất của tắc ruột nói chung? :: Dính ruột (kế đến thoát vị)\n- Xoắn ruột hay gặp nhất ở đâu và là loại tắc gì? :: Đại tràng chậu hông; tắc ruột quai kín\n- Vì sao bí trung đại tiện tính từ 24 giờ sau khởi phát đau? :: Tắc cao trong 24 giờ đầu còn trung tiện, đại tiện nhờ hơi phân sót dưới chỗ tắc\n- Dấu hiệu gợi ý tắc ruột thắt nghẹt? :: Sốt, mạch nhanh, bụng ấn đau, khối thoát vị đau, tăng bạch cầu; đau chuyển từ quặn cơn sang liên tục\n- Phân biệt táo bón với tắc ruột bằng gì? :: Thăm trực tràng: táo bón đầy phân cứng; tắc ruột bóng trực tràng rỗng\n- Phương tiện hình ảnh đầu tiên và dấu hiệu chính? :: X quang bụng đứng không sửa soạn: mực nước hơi, ruột non giãn >3 cm, chuỗi tràng hạt\n- Dấu hiệu CT chỉ điểm tắc ruột và cần can thiệp? :: Vùng chuyển tiếp giữa ruột giãn phía trên và ruột xẹp phía dưới\n- Liệt ruột sau mổ thường kéo dài bao lâu, kéo dài hơn nghĩ gì? :: Không quá 48–72 giờ; nghĩ nhiễm trùng hoặc chảy máu ổ bụng, rối loạn chuyển hóa, thoát vị lỗ trocar\n- Khi nghi thiếu máu ruột hoặc viêm phúc mạc thì xử trí thế nào? :: Cân nhắc mổ sớm, có thể không cần xác định nguyên nhân hay vị trí tắc"}, {"kind": "foundation", "disease": "", "short": "Đau bụng cấp", "group": "", "section": 3, "order": 1, "khung": [], "id": "dau-bung-cap", "title": "Tiếp cận đau bụng cấp", "layer": "trieuchung", "module": "ngoai-tong-quat", "tags": ["đau bụng cấp", "bụng ngoại khoa", "viêm phúc mạc", "tắc ruột", "chảy máu ổ bụng", "đau tạng", "đau thành", "đau quy chiếu"], "source": "TCBN tr.3–7, 22–29, 32–33, 41–42, 45–55", "body": "> [!key] Việc đầu tiên: có cần can thiệp ngoại khoa khẩn hay không\n> - **Đau bụng cấp** = đau vùng bụng xuất hiện **trong vòng 7 ngày**, không liên quan chấn thương, cần chăm sóc khẩn cấp; là lý do nhập viện thường gặp nhất ở khoa cấp cứu {{TCBN tr.22}}\n> - Việc quan trọng nhất của người tiếp nhận ban đầu: xác định bệnh nhân có cần **can thiệp ngoại khoa khẩn cấp** hay không {{TCBN tr.22}}\n> - Ba hội chứng bụng ngoại khoa cần can thiệp khẩn: **chảy máu ổ bụng, tắc ruột, viêm phúc mạc** {{TCBN tr.23}}\n> - Chẩn đoán dựa vào **tam giác**: hỏi bệnh sử, thăm khám lâm sàng, cận lâm sàng thích hợp; bụng ngoại khoa phải chẩn đoán bằng **lâm sàng** {{TCBN tr.22, 25}}\n\n### 1. Định nghĩa và phân loại theo thời gian\n- Đau **cấp**: vài ngày, tiến triển nhanh đến mức nhiều; đau **mạn**: vài tháng, vài năm, ít thay đổi; không thuộc hai loại trên là đau **bán cấp**, cần phân biệt với cả hai {{TCBN tr.22}}\n- Người đau bụng mạn có **toàn thân không ổn định** thì xem như đau bụng cấp (có thể do nặng lên của nguyên nhân cũ hoặc nguyên nhân mới) {{TCBN tr.22}}\n- Không phải mọi đau bụng cấp đều cần mổ, nhưng **chỉ định ngoại khoa luôn phải được nghĩ tới** {{TCBN tr.45}}\n\n### 2. Ba hội chứng bụng ngoại khoa\nBụng ngoại khoa là những trường hợp sẽ **diễn tiến nặng nhanh** nếu không can thiệp ngoại khoa {{TCBN tr.23}}.\n\n| Hội chứng | Gợi ý lâm sàng | Nguồn |\n|---|---|---|\n| **Chảy máu ổ bụng** | Vỡ phình động mạch chủ bụng: nam >65 tuổi, đau thượng vị hoặc quanh rốn lan sau lưng, có thể sốc. Thai ngoài tử cung vỡ: nữ tuổi sinh sản, trễ kinh, có thể ra máu âm đạo, đau hạ vị, có thể sốc | {{TCBN tr.23}} |\n| **Tắc ruột** | Tứ chứng **đau, nôn, bí, chướng**; vết mổ cũ, chướng bụng, nhu động tăng hoặc mất hẳn, gõ vang hoặc sờ thấy u | {{TCBN tr.23}} |\n| **Viêm phúc mạc** | Vẻ mặt nhiễm trùng, đừ, nằm im, mạch nhanh nhỏ, sốt; dấu hiệu từ nhẹ đến nặng: phản ứng dội, đề kháng, co cứng thành bụng, cảm ứng phúc mạc | {{TCBN tr.23}} |\n\n- Bệnh nhân bán tắc chuyển thành tắc ruột có thể **đau mơ hồ hằng tuần rồi bất ngờ nặng lên** {{TCBN tr.23}}\n- Chỉ khi **loại trừ hẳn** bụng ngoại khoa mới xét các chẩn đoán khác; trong lúc xác định, bệnh nhân được **nhịn ăn uống** {{TCBN tr.24}}\n\n### 3. Dấu hiệu nguy hiểm: chuyển ngay phòng cấp cứu\n> [!red] Chuyển ngay tới phòng cấp cứu khi có\n> - **Rối loạn sinh hiệu** {{TCBN tr.23}}\n> - **Dấu hiệu viêm phúc mạc** trên lâm sàng: đề kháng, co cứng thành bụng, cảm ứng phúc mạc {{TCBN tr.23}}\n> - Nghi ngờ **tắc ruột, thủng tạng rỗng, tắc mạch mạc treo, thai ngoài tử cung vỡ, nhồi máu cơ tim** {{TCBN tr.23}}\n> - Bệnh nhân **sốc hoặc dọa sốc**: hồi sức tích cực và **mổ ngay** để chẩn đoán và xử trí tổn thương {{TCBN tr.25}}\n\n- Những trường hợp này có thể cần giảm đau ngay cả khi khó xác định chẩn đoán {{TCBN tr.23}}\n- Đặc biệt cẩn trọng ở **suy giảm miễn dịch** (mắc phải hoặc dùng thuốc ức chế miễn dịch kéo dài, suy thận, đái tháo đường) và **người lớn tuổi**: triệu chứng viêm phúc mạc có thể không rõ {{TCBN tr.24}}\n\n### 4. Cơ chế đau bụng\n| Loại đau | Đặc điểm | Ví dụ | Nguồn |\n|---|---|---|---|\n| **Đau tạng** | Mơ hồ, sâu, khó định vị; do viêm, thiếu máu nuôi, xoắn, căng chướng, co kéo; không nhất thiết cần mổ | Mơ hồ quanh rốn của ruột giữa | {{TCBN tr.46}} |\n| **Đau thành** | Có vị trí rõ, dữ dội; do kích thích phúc mạc thành; thường kèm dấu hiệu viêm phúc mạc, thường (không phải luôn luôn) có chỉ định ngoại khoa | Viêm ruột thừa kích thích phúc mạc thành gây đau hố chậu phải | {{TCBN tr.46}} |\n| **Đau quy chiếu** | Xuất phát từ tạng sâu nhưng biểu hiện nông ở vị trí khác | Đường mật: lan dưới bả vai phải; áp xe dưới hoành: lan một bên vai | {{TCBN tr.46}} |\n\n- Vị trí đau tạng theo **nguồn gốc phôi**: ruột trước (dạ dày đến phần hai tá tràng, gan, đường mật, tụy, lách) đau **thượng vị**; ruột giữa đau **quanh rốn**; ruột cuối đau **trên xương mu** {{TCBN tr.46}}\n- Vị trí đau chỉ để **gợi ý chẩn đoán**; cảm giác đau là chủ quan, tính chất đau cũng chỉ có giá trị gợi ý {{TCBN tr.47}}\n\n### 5. Hỏi bệnh\n#### 5.1. Chuỗi câu hỏi về cơn đau\n- Đau ở đâu, quặn cơn hay liên tục, khởi phát lúc nào và thế nào, mức độ, lan đi đâu {{TCBN tr.24}}\n- Yếu tố tăng giảm đau (ăn uống, thuốc kháng acid, gắng sức, đi cầu), tính chất có đổi không, đã từng đau tương tự chưa {{TCBN tr.24}}\n- Triệu chứng đi kèm: sốt, lạnh run, buồn nôn, nôn, tiêu chảy, táo bón, trung tiện, tiêu máu, phân đen, vàng da, đổi màu phân hoặc nước tiểu {{TCBN tr.24}}\n- Tiền căn nội ngoại khoa (nhất là nguy cơ tim mạch, mổ bụng trước đó), thuốc đang dùng (acetaminophen, aspirin, NSAID); **chu kỳ kinh, cách tránh thai** ở bệnh nhân nữ {{TCBN tr.24}}\n\n#### 5.2. Kiểu khởi phát gợi ý nguyên nhân\n| Khởi phát | Gợi ý | Nguồn |\n|---|---|---|\n| **Đột ngột (vài giây)** | Thủng hoặc vỡ (thủng ổ loét dạ dày tá tràng, vỡ túi phình động mạch chủ bụng); nhồi máu (nhồi máu cơ tim, tắc mạch mạc treo cấp) | {{TCBN tr.47}} |\n| **Tăng nhanh (vài phút)** | Co thắt (cơn đau quặn thận, tắc ruột non); viêm (viêm tụy cấp, viêm túi thừa cấp); thiếu máu (nhồi máu mạc treo, xoắn ruột non, lồng ruột) | {{TCBN tr.47}} |\n| **Tăng dần (vài giờ)** | Viêm túi thừa cấp, viêm phần phụ; tắc ruột không thắt nghẹt, bí tiểu; thai ngoài tử cung, u bị thủng hoặc vỡ | {{TCBN tr.47}} |\n\n#### 5.3. Tính chất, yếu tố tăng giảm, triệu chứng kèm\n- Đau **quặn lúc tăng lúc giảm**: tăng nhu động cơ trơn trước chỗ tắc cơ học (tắc ruột non, sỏi thận); ngoại lệ là cơn đau quặn mật, có xu hướng **liên tục, dữ dội, kéo dài ít nhất 30 phút đến vài giờ** {{TCBN tr.48}}\n- Đau nhiều, nặng, liên tục, ngày càng tăng: quá trình viêm hoặc nhiễm trùng {{TCBN tr.48}}\n- **Viêm phúc mạc toàn thể**: đau tăng khi vận động, giảm khi nằm im; **cơn đau quặn thận**: quằn quại không nằm im được {{TCBN tr.48}}\n- Tắc ruột: đau tạng, thường giảm tạm thời sau nôn {{TCBN tr.48}}\n- Thứ tự đau và nôn: nôn **sau** đau gặp trong viêm ruột thừa; nôn **trước** đau rất thường gặp trong viêm dạ dày ruột, ngộ độc thức ăn {{TCBN tr.48}}\n- Nôn ra mật gợi ý bệnh lý đoạn cuối tá tràng; nôn ra máu có thể do loét hoặc viêm dạ dày tá tràng {{TCBN tr.48}}\n- Hướng lan: vỡ túi phình động mạch chủ bụng và viêm tụy cấp thường lan ra sau lưng; cơn đau quặn thận từ hông lưng lan xuống bẹn cùng bên {{TCBN tr.48}}\n\n#### 5.4. Tiền căn và thuốc cần lưu ý\n- Bệnh mạch vành, bệnh mạch máu ngoại biên: có thể có bệnh lý mạch máu trong bụng (phình động mạch chủ bụng, nhồi máu mạc treo) {{TCBN tr.48}}\n- Tiền căn ung thư: có thể tái phát gây tắc hoặc thủng ruột {{TCBN tr.48}}\n- Đái tháo đường, bệnh mạch vành: đau mơ hồ ở thượng vị có thể là **nhồi máu cơ tim** {{TCBN tr.48}}\n- NSAID làm tăng nguy cơ biến chứng loét dạ dày tá tràng (chảy máu, hẹp môn vị, thủng) {{TCBN tr.49}}\n- **Corticosteroid** có thể che mờ dấu hiệu viêm (sốt, kích thích phúc mạc) {{TCBN tr.49}}\n- Nữ: nang buồng trứng vỡ, thai ngoài tử cung, viêm vùng chậu {{TCBN tr.49}}\n\n### 6. Thăm khám\n#### 6.1. Nhìn tổng quát và sinh hiệu\n- Áp dụng trình tự cấp cứu **ABC**; đa số bệnh nhân xin giảm đau, nên dùng thuốc hợp lý để không che lấp dấu hiệu viêm phúc mạc {{TCBN tr.24}}\n- **Nằm im**, tư thế bào thai, hạn chế vận động, nét mặt lừ đừ: gần như là viêm phúc mạc; **đau quằn quại, đổi tư thế liên tục**: đau tạng, gặp trong tắc ruột hoặc viêm dạ dày ruột {{TCBN tr.24}}\n- Thở nhanh có thể là toan chuyển hóa do sốc; **rung nhĩ** (khám hoặc điện tim) gợi ý huyết khối động mạch mạc treo {{TCBN tr.24}}\n- Sốt cao >39°C gợi ý áp xe, viêm phúc mạc hoặc viêm phổi; huyết áp thấp và/hoặc mạch nhanh gợi ý giảm thể tích hoặc nhiễm trùng huyết {{TCBN tr.49}}\n- Xem chất thải (phân, chất nôn, nước tiểu); tri giác, da niêm, sốc, hội chứng nhiễm trùng, mất nước {{TCBN tr.24}}\n\n#### 6.2. Khám bụng\n- Bộc lộ toàn bộ ổ bụng, **từ núm vú đến đùi**; bắt đầu bằng nhìn (chướng, sẹo mổ cũ, chỗ phồng bất thường) {{TCBN tr.25, 49}}\n- **Nghe trước khi sờ và gõ**; kết luận không nghe được âm ruột khi nghe **ít nhất 2 phút** và ở **ít nhất 2 vị trí** phần tư {{TCBN tr.25}}\n- Âm ruột réo rắt, âm sắc cao: tắc ruột cơ học; mất âm ruột: liệt ruột do viêm phúc mạc toàn thể {{TCBN tr.49}}\n- Sờ bụng ở tư thế nằm ngửa, gối co; **bắt đầu xa chỗ đau**; vừa sờ vừa quan sát mặt bệnh nhân {{TCBN tr.25, 50}}\n- Dấu nghi ngờ viêm phúc mạc: lắc vùng chậu hoặc lắc giường để thành bụng va chạm với tạng trong phúc mạc {{TCBN tr.50}}\n- Đau ngoài lúc khám bụng gợi ý **nhồi máu mạc treo** {{TCBN tr.50}}\n- Khám kỹ các **lỗ thoát vị** (vết mổ cũ, thành bụng, rốn, bẹn, đùi) {{TCBN tr.50}}\n\n#### 6.3. Khám trực tràng, sinh dục, vùng chậu\n- Khám cơ quan vùng chậu và sinh dục ngoài; thăm trực tràng và âm đạo cho thêm đường tiếp cận các tạng vùng chậu; loại trừ bệnh phụ khoa ở nữ {{TCBN tr.25}}\n- Khám hậu môn trực tràng thường quy khi nghi chảy máu tiêu hóa, tắc ruột, bệnh lý bụng dưới và vùng chậu {{TCBN tr.50}}\n- Khám vùng chậu **bắt buộc** ở phụ nữ tuổi mang thai có đau bụng dưới {{TCBN tr.50}}\n- Khám tinh hoàn, bìu ở **mọi bệnh nhân nam** đau bụng (xoắn tinh hoàn, viêm mào tinh) {{TCBN tr.50}}\n\n### 7. Cận lâm sàng\n#### 7.1. Xét nghiệm ban đầu\n- Công thức máu; điện giải đồ, BUN, creatinine, đường huyết; AST, ALT, bilirubin; amylase, lipase máu; tổng phân tích nước tiểu {{TCBN tr.25}}\n- **Thử thai nhanh hoặc beta hCG** ở phụ nữ tuổi sinh sản; cấy máu hoặc nước tiểu khi sốt hoặc sinh hiệu không ổn định {{TCBN tr.25}}\n- Xét nghiệm ban đầu **không xác định** được bụng ngoại khoa; chẩn đoán dựa vào lâm sàng {{TCBN tr.25}}\n- Amylase, lipase khi nghi viêm tụy cấp; mức tăng **không tương quan** độ nặng; lipase đặc hiệu hơn amylase {{TCBN tr.51}}\n- **Lactate** huyết thanh khi nghi nhồi máu ruột; lactate tăng kéo dài dù đã hồi sức báo hiệu thiếu máu mô tiến triển {{TCBN tr.51}}\n- Nước tiểu: vi trùng, mủ, bạch cầu gợi ý nhiễm trùng tiểu; tiểu máu gặp trong sỏi thận, ung thư thận, biểu mô đường tiết niệu {{TCBN tr.51}}\n- Beta hCG nước tiểu (+) thì định lượng huyết thanh; <4000 mIU thường gặp trong thai ngoài tử cung, >4000 mIU thường là thai trong tử cung {{TCBN tr.51}}\n\n#### 7.2. Chẩn đoán hình ảnh\n| Tình huống | Chọn | Nguồn |\n|---|---|---|\n| Chảy máu ổ bụng | Siêu âm bụng tốt cho phình bóc tách động mạch chủ; sinh hiệu ổn định thì **CT** để xác định | {{TCBN tr.25}} |\n| Tắc ruột | CT nhạy và đặc hiệu hơn X quang, còn tìm nguyên nhân tắc; X quang bụng đứng không sửa soạn là phương tiện đầu tiên | {{TCBN tr.5–6, 25}} |\n| Viêm phúc mạc | Siêu âm (viêm ruột thừa, áp xe trong ổ bụng, bệnh vùng chậu, hữu ích ở người có thai); CT khi siêu âm không rõ | {{TCBN tr.25–26}} |\n| Không giải thích được, khó khai thác bệnh sử, nghi nhồi máu mạc treo, viêm tụy hoại tử, bệnh ác tính | **CT** (CT mạch máu cho nhồi máu mạc treo) | {{TCBN tr.53}} |\n| Thai, đau vùng chậu | Siêu âm (qua ngả âm đạo cho buồng trứng, thai ngoài tử cung); MRI có lợi nhất ở người có thai | {{TCBN tr.53}} |\n\n- Bệnh nhân đau bụng cấp cần 3 phim: X quang ngực đứng, X quang bụng đứng và nằm ngửa {{TCBN tr.51}}\n- **Hơi tự do** trong phúc mạc rõ nhất trên phim ngực đứng (liềm hơi dưới hoành); khoảng 50% thủng nội tạng không thấy hơi tự do {{TCBN tr.52}}\n- Hơi trong thành ruột (pneumatosis) là biểu hiện nhồi máu ruột; hơi trong tĩnh mạch mạc treo hoặc tĩnh mạch cửa đi kèm nhồi máu ruột: tử vong >75% {{TCBN tr.52}}\n- Nội soi ổ bụng chẩn đoán đôi khi dùng khi các xét nghiệm không xác định được nguyên nhân {{TCBN tr.26}}\n- Nếu cần cản quang đường hậu môn hay khi nghi thủng: dùng **thuốc cản quang tan trong nước** {{TCBN tr.53}}\n\n> [!warn] Lưu ý chọn cận lâm sàng\n> - Chọn theo tính hợp lý, mức độ xâm hại, yếu tố nguy cơ, chi phí, hiệu quả; khả năng ứng dụng khác nhau giữa các cơ sở {{TCBN tr.25}}\n> - Nếu bệnh nhân sốc hoặc dọa sốc thì **không chờ hình ảnh**: hồi sức và mổ {{TCBN tr.25}}\n\n### 8. Đau bụng theo vị trí\n| Vị trí đau | Nguyên nhân thường gặp | Nguồn |\n|---|---|---|\n| **¼ dưới phải** | Đường ruột: viêm ruột thừa, viêm túi thừa, viêm hạch mạc treo, thiếu máu ruột. Sản phụ khoa: thai ngoài tử cung, viêm phần phụ, xoắn phần phụ, lạc nội mạc tử cung. Cơ thắt lưng chậu: viêm hoặc áp xe | {{TCBN tr.26}} |\n| **¼ trên phải** | Gan (áp xe gan, u gan có biến chứng vỡ hay áp xe hóa); đường mật (viêm túi mật cấp, viêm đường mật cấp); dạ dày, tá tràng (viêm loét, ung thư dạ dày); đại tràng (viêm túi thừa, viêm đại tràng, u biến chứng); tụy (viêm tụy cấp, u đầu tụy); thận, niệu quản (viêm đài bể thận cấp, sỏi niệu quản, áp xe quanh thận); u sau phúc mạc | {{TCBN tr.28–29}} |\n| **Các vị trí khác** | Thủng dạ dày tá tràng, viêm túi thừa cấp, tắc ruột, nhồi máu mạc treo, phình động mạch chủ bụng vỡ | {{TCBN tr.54}} |\n| **Nguyên nhân ngoài ổ bụng và nhóm khác** | Sản phụ khoa (viêm vùng chậu, thai ngoài tử cung, nang buồng trứng vỡ); tiết niệu (sỏi tiết niệu, viêm bọng đái, viêm thận bể thận); nội khoa (nhồi máu cơ tim cấp, viêm dạ dày ruột, viêm phổi, nhiễm ketoacid đái tháo đường, viêm tụy cấp) | {{TCBN tr.54}} |\n\n- Chẩn đoán đau bụng cấp phụ thuộc vị trí đau, giúp **thu hẹp** chẩn đoán phân biệt {{TCBN tr.26}}\n\n#### Theo tính chất đau\n| Kiểu đau | Nguyên nhân | Nguồn |\n|---|---|---|\n| **Từng cơn** | Tắc ruột cơ học, sỏi tiết niệu, viêm dạ dày tá tràng, viêm ruột non, viêm đại trực tràng | {{TCBN tr.54}} |\n| **Liên tục** | Thủng dạ dày tá tràng, thủng ruột non hoặc đại trực tràng, nhồi máu mạc treo, phình động mạch chủ bụng vỡ, viêm tụy cấp, viêm túi thừa cấp | {{TCBN tr.54}} |\n| **Từng cơn hoặc liên tục** | Tắc ruột thắt nghẹt mạch máu, xoắn ruột, lồng ruột, viêm vùng chậu, thai ngoài tử cung, nang buồng trứng vỡ, viêm bọng đái, viêm thận bể thận | {{TCBN tr.54–55}} |\n\n### 9. Nối sang các hội chứng cụ thể\n@@fold Tắc ruột: các câu hỏi cần trả lời\n- Phải phân biệt với **táo bón** bằng thăm trực tràng: táo bón đầy phân cứng trong bóng trực tràng, tắc ruột bóng trực tràng rỗng {{TCBN tr.6}}\n- Các câu hỏi: tắc cơ học hay liệt ruột; có thiếu máu ruột hoặc viêm phúc mạc không (tắc thắt nghẹt: cân nhắc mổ sớm, có thể không cần xác định nguyên nhân); tắc hoàn toàn hay bán tắc; ruột non hay ruột già; nguyên nhân; biến chứng toàn thân {{TCBN tr.6–7}}\n- Đau chuyển từ **quặn cơn sang liên tục hoặc dữ dội hơn** gợi ý tắc ruột do thắt hoặc thiếu máu ruột {{TCBN tr.4}}\n- Nghĩ tắc thắt nghẹt khi sốt, mạch nhanh, bụng ấn đau, khối thoát vị đau, tăng bạch cầu {{TCBN tr.3}}\n- Khối thoát vị đỏ da hoặc ấn đau: nghĩ thoát vị nghẹt {{TCBN tr.5}}\n@@end\n\n@@fold Viêm túi mật cấp và viêm tụy cấp\n- Viêm túi mật cấp (Tokyo 2018): **nghi ngờ** khi 1 tiêu chuẩn A (viêm khu trú: Murphy, ¼ trên phải có khối, ấn đau, đề kháng) + 1 tiêu chuẩn B (viêm toàn thân: sốt, tăng CRP, tăng bạch cầu); **xác định** khi A + B + C (hình ảnh đặc trưng) {{TCBN tr.33}}\n- Viêm tụy cấp: chẩn đoán khi có **2 trong 3** tiêu chuẩn: cơn đau điển hình (trên rốn, lan sau lưng); amylase hoặc lipase máu >3 lần giới hạn trên; hình ảnh điển hình {{TCBN tr.42}}\n- Viêm tụy cấp nặng: có dấu Cullen (quanh rốn) và Grey Turner (hông) do xuất huyết dưới da {{TCBN tr.41}}\n@@end\n\n### 10. Bệnh nhân đặc biệt\n- **Nữ tuổi sinh sản**: nang buồng trứng, u xơ tử cung, nhiễm trùng tai vòi, lạc nội mạc tử cung; luôn đưa **có thai, thai ngoài tử cung, sẩy thai** vào chẩn đoán phân biệt; khi có thai, tránh tia X để chẩn đoán {{TCBN tr.27}}\n- **Người lớn tuổi**: nhiễm trùng tiểu không triệu chứng, **thủng tạng rỗng, thiếu máu ruột** thường bị bỏ sót, chẩn đoán muộn vì biểu hiện không điển hình {{TCBN tr.27}}\n- **HIV** (nhất là CD4 <100 tế bào/µL): thêm nhiễm trùng cơ hội (viêm hạch mạc treo do CMV, MAC, cryptosporidium) và u tân sinh (Kaposi sarcoma, lymphoma) {{TCBN tr.27}}\n\n### 11. Lưu đồ tiếp cận\n1. **Ổn định**: ABC, sinh hiệu; bệnh nhân sốc hoặc dọa sốc thì hồi sức tích cực và mổ ngay {{TCBN tr.24–25}}\n2. **Tìm dấu hiệu nguy hiểm**: rối loạn sinh hiệu, viêm phúc mạc, nghi tắc ruột, thủng tạng rỗng, tắc mạch mạc treo, thai ngoài vỡ, nhồi máu cơ tim; có thì chuyển cấp cứu {{TCBN tr.23}}\n3. **Hỏi bệnh sử** theo chuỗi câu hỏi (vị trí, kiểu khởi phát, tính chất, lan, triệu chứng kèm, tiền căn, thuốc, kinh nguyệt) {{TCBN tr.24}}\n4. **Khám** toàn thân, bụng (nhìn, nghe, gõ, sờ), lỗ thoát vị, trực tràng, vùng chậu, bìu {{TCBN tr.25, 50}}\n5. **Xét nghiệm ban đầu** (kèm beta hCG ở nữ tuổi sinh sản) {{TCBN tr.25}}\n6. **Phân loại hội chứng**: chảy máu ổ bụng, tắc ruột, viêm phúc mạc; chọn hình ảnh phù hợp (siêu âm, CT, X quang) {{TCBN tr.23, 25}}\n7. **Hội chẩn ngay** bác sĩ ngoại khoa khi nghi bụng ngoại khoa; bệnh nhân cần hồi sức hoặc giảm đau ngoài đường uống được theo dõi nơi có đủ phương tiện hồi sức, xét nghiệm, hình ảnh {{TCBN tr.22}}\n8. **Nhịn ăn uống** cho đến khi xác định hoặc loại trừ bụng ngoại khoa; bệnh nhân ít khẩn cấp: gửi chuyên khoa sau khi hỏi bệnh, khám, xử trí ban đầu {{TCBN tr.23–24}}\n9. Khi đã ổn định: chẩn đoán phân biệt theo **nhóm triệu chứng hoặc hội chứng** để chọn cận lâm sàng {{TCBN tr.23}}\n\n### Điểm hay thi\n> [!warn]\n> - Định nghĩa: đau bụng xuất hiện **trong vòng 7 ngày**, không do chấn thương {{TCBN tr.22}}\n> - Ba hội chứng bụng ngoại khoa: **chảy máu ổ bụng, tắc ruột, viêm phúc mạc** {{TCBN tr.23}}\n> - Xét nghiệm ban đầu **không** xác định được bụng ngoại khoa; bụng ngoại khoa chẩn đoán bằng lâm sàng {{TCBN tr.25}}\n> - Nữ tuổi sinh sản: luôn thử thai (beta hCG) {{TCBN tr.25}}\n> - Giảm đau, tài liệu nêu hai ý, nhớ cả hai: dùng hợp lý để không che dấu viêm phúc mạc {{TCBN tr.24}}; thuốc giảm đau gây nghiện trước khi khám làm đổi triệu chứng thực thể nhưng không giảm độ chính xác chẩn đoán {{TCBN tr.49}}\n> - Nôn sau đau: nghĩ ngoại khoa (viêm ruột thừa); nôn trước đau: nghĩ viêm dạ dày ruột, ngộ độc thức ăn {{TCBN tr.48}}\n> - Corticosteroid, suy giảm miễn dịch, người lớn tuổi: dấu hiệu bụng **mờ**, dễ bỏ sót {{TCBN tr.24, 49}}\n\n### Tự kiểm tra\n- Định nghĩa đau bụng cấp? :: Đau vùng bụng xuất hiện trong vòng 7 ngày, không liên quan chấn thương, cần chăm sóc khẩn cấp\n- Việc quan trọng nhất khi tiếp nhận bệnh nhân đau bụng cấp? :: Xác định có cần can thiệp ngoại khoa khẩn cấp hay không\n- Ba hội chứng bụng ngoại khoa cần can thiệp khẩn? :: Chảy máu ổ bụng, tắc ruột, viêm phúc mạc\n- Tứ chứng của tắc ruột? :: Đau, nôn, bí, chướng\n- Thứ tự dấu hiệu viêm phúc mạc từ nhẹ đến nặng? :: Phản ứng dội, đề kháng thành bụng, co cứng thành bụng, cảm ứng phúc mạc\n- Các dấu hiệu nguy hiểm cần chuyển ngay phòng cấp cứu? :: Rối loạn sinh hiệu; dấu hiệu viêm phúc mạc; nghi tắc ruột, thủng tạng rỗng, tắc mạch mạc treo, thai ngoài tử cung vỡ, nhồi máu cơ tim\n- Đau tạng khác đau thành thế nào? :: Đau tạng mơ hồ, sâu, khó định vị; đau thành rõ, dữ dội, dễ định vị do kích thích phúc mạc thành\n- Đau tạng của ruột trước, ruột giữa, ruột cuối nằm ở đâu? :: Thượng vị; quanh rốn; trên xương mu\n- Muốn kết luận không nghe được âm ruột phải nghe bao lâu? :: Ít nhất 2 phút ở ít nhất 2 vị trí phần tư\n- Khởi phát đau đột ngột trong vài giây gợi ý gì? :: Thủng hoặc vỡ (thủng ổ loét dạ dày tá tràng, vỡ túi phình động mạch chủ bụng); nhồi máu (nhồi máu cơ tim, tắc mạch mạc treo cấp)\n- Bệnh nhân viêm phúc mạc nằm thế nào, cơn đau quặn thận thì sao? :: Viêm phúc mạc nằm im; đau quặn thận quằn quại không nằm im được\n- Hơi tự do trong phúc mạc thấy rõ nhất trên phim nào? :: X quang ngực đứng (liềm hơi dưới hoành)"}, {"kind": "foundation", "disease": "", "short": "Khối u bụng", "group": "", "section": 3, "order": 2, "khung": [], "id": "khoi-u-bung", "title": "Tiếp cận khối u vùng bụng", "layer": "trieuchung", "module": "ngoai-tong-quat", "tags": ["khối u bụng", "sờ bụng", "9 vùng bụng", "u giả", "khối u thành bụng", "u trong ổ bụng", "đập theo mạch", "ung thư"], "source": "TCBN tr.67–75; Notion [TCHNgK] Khối u vùng bụng (nội dung trùng TCBN)", "body": "> [!key] Khối u bụng là triệu chứng, chẩn đoán bằng lâm sàng rồi xác định bằng hình ảnh\n> - **Khối u bụng** = các loại u trong ổ bụng; nguyên nhân gồm **viêm, nang, khối tân sinh (lành, có khuynh hướng ác, ác) và phì đại tạng** {{TCBN tr.67–68}}\n> - Chẩn đoán lâm sàng phải mô tả đủ các tính chất khối: **vị trí, kích thước, mật độ, bề mặt, giới hạn, di động, biến mất, ấn đau, đập theo mạch** {{TCBN tr.70–71}}\n> - Việc đầu tiên: khối ở **thành bụng** hay **trong khoang bụng**; sau đó viêm hay không viêm, lành hay ác {{TCBN tr.71–72}}\n> - Ở giai đoạn sớm triệu chứng thường mơ hồ hoặc không có; nguyên nhân khối u bụng **không có triệu chứng đặc hiệu** {{TCBN tr.75}}\n> - Liên kết ung thư ngoại khoa: [Ung thư dạ dày](#/n/ngoai-ung-thu-da-day), [Ung thư đại tràng](#/n/ngoai-ung-thu-dai-trang), [Ung thư trực tràng](#/n/ngoai-ung-thu-truc-trang), [Ung thư tế bào gan](#/n/ngoai-ung-thu-gan-hcc); Khung 128: [STT 54](#/khung/54) (khối ở bụng)\n\n### 1. Khái niệm và nguyên nhân\n- **Khối tân sinh**: đám tổ chức mới từ nhóm tế bào bất thường, không còn bị cơ thể kiểm soát, tự phát triển dù hết tác nhân kích thích; có thể lành, có khuynh hướng ác tính hoặc ung thư {{TCBN tr.67}}\n- **Nang (bọc)**: tổ chức chứa dịch, đôi khi máu hoặc mủ. **U đặc**: thành phần đặc là chủ yếu; nang chỉ chiếm phần nhỏ hoặc do phần đặc hoại tử tạo dịch {{TCBN tr.67}}\n- Khối u bụng đôi khi là **túi khí**: quai đại tràng chậu hông hoặc manh tràng dãn to chứa đầy khí {{TCBN tr.67}}\n- Vùng bụng gồm thành bụng, trong khoang phúc mạc, ngoài hoặc sau phúc mạc; không tính phần xương {{TCBN tr.67}}\n- Bệnh ruột thừa, túi mật, tụy, túi thừa có thể biểu hiện là khối; **u tụy và u đại tràng** thường chỉ thành khối sờ được ở **giai đoạn tiến triển** {{TCBN tr.68}}\n- Khối đặc, chứa khí hay chứa dịch cho cảm giác khác nhau khi sờ {{TCBN tr.68}}\n\n#### Khối u giả (khối u ma)\n- Tạng rỗng bị tắc làm đoạn phía trên dãn lớn: **tắc môn vị hoặc tá tràng thì dạ dày dãn; tắc ống túi mật hoặc đoạn cuối ống mật chủ thì túi mật căng; hẹp cổ bàng quang thì cầu bàng quang; tắc ở chỗ nối đại tràng chậu hông và trực tràng thì quai đại tràng chậu hông dãn** {{TCBN tr.68}}\n- Khi tháo được dịch, hơi, thức ăn, hoặc túi phình động mạch **vỡ**, khối không còn sờ được: gọi là **khối u giả hay u ma** {{TCBN tr.68}}\n\n### 2. Hỏi bệnh: bốn tính chất quan trọng\n| Tính chất | Ý nghĩa | Nguồn |\n|---|---|---|\n| **Khởi phát** | Đột ngột thì bệnh lý càng cấp, thường là biến chứng: sỏi gây tắc ống túi mật hoặc đường mật ngoài gan, cầu bàng quang do tắc đường tiểu dưới, xoắn nang buồng trứng, xoắn đại tràng chậu hông gây bụng méo. Từ từ: khối nhỏ, ít khó chịu, to dần; có khối không đổi nhiều tháng rồi **to nhanh kèm đau bụng** | {{TCBN tr.68}} |\n| **Vị trí** | Nhất là **vị trí ban đầu** theo vùng thành bụng trước hoặc sau: giúp xác định tạng rồi nguyên nhân | {{TCBN tr.68}} |\n| **Biến mất** | Hiện ẩn gặp nhất ở **thoát vị thành bụng** (tăng áp lực ổ bụng thì hiện, nằm nghỉ thì mất). Khối nhỏ lại sau khi tháo dịch, hơi, thức ăn. **Khối biến mất kèm đau bụng dữ dội lan khắp bụng: nghĩ khối hoặc tạng liên quan bị vỡ** | {{TCBN tr.68–69}} |\n| **Triệu chứng đi kèm** | Đa số mơ hồ: đau âm ỉ, đầy nặng bụng, sốt, sụt cân, chán ăn, đầy bụng, khó tiêu | {{TCBN tr.69}} |\n\n- Khối nông và to thì bệnh nhân tự sờ thấy; khối sâu và lớn thì thấy **bụng méo**; càng nông và lớn càng dễ chẩn đoán {{TCBN tr.68}}\n\n#### Triệu chứng chỉ điểm tạng bị u xâm lấn hoặc chèn ép\n| Triệu chứng | Gợi ý | Nguồn |\n|---|---|---|\n| Ói máu đỏ hoặc đen | Thương tổn hoặc xâm lấn vào thành dạ dày | {{TCBN tr.69}} |\n| Ói thức ăn, nhất là thức ăn cũ | Hẹp hoặc tắc môn vị, tá tràng | {{TCBN tr.69}} |\n| Vàng da, túi mật to | Khối u đoạn đường mật ngoài gan | {{TCBN tr.69}} |\n| Bán tắc hoặc tắc ruột cao | Tổn thương ruột non hoặc đại tràng | {{TCBN tr.69}} |\n| Táo bón, tiêu chảy, tiêu đàm máu | Đại tràng, trực tràng; tiêu chảy còn gặp ở bệnh lý vùng tụy | {{TCBN tr.69}} |\n| Mắc rặn | Tổn thương vùng trực tràng | {{TCBN tr.69}} |\n| Khối đổi kích thước theo chu kỳ kinh | Bệnh lý buồng trứng | {{TCBN tr.69}} |\n| Cơn đau quặn thận | Bế tắc đường tiểu trên | {{TCBN tr.69}} |\n| Tiểu buốt, tiểu gắt | Kích thích bàng quang hoặc cổ bàng quang | {{TCBN tr.69}} |\n\n- Phải hỏi có hay không triệu chứng cơ năng của **tiêu hóa, gan mật tụy, sinh dục, tiết niệu** {{TCBN tr.69}}\n\n### 3. Khám bụng\n- **Nhìn**: hình dạng thành bụng trước (chướng, méo, phẳng đều), sẹo, tổn thương da nông, chỗ phồng {{TCBN tr.69}}\n- **Nghe**: nhu động ruột tăng, âm sắc cao khi lòng ruột hẹp hoặc tắc; **âm thổi** trong phình động mạch; vừa lắc vừa nghe tìm **dấu óc ách** (hẹp môn vị) {{TCBN tr.69}}\n- **Sờ**: tìm điểm đau, phản ứng thành bụng và mô tả tính chất khối {{TCBN tr.70}}\n\n#### 3.1. Sờ theo vị trí: chín vùng bụng và các tạng cần nghĩ tới\nBảng nguyên nhân khối u theo phân khu thành bụng {{TCBN tr.74}}.\n\n| | **Bên phải** | **Giữa** | **Bên trái** |\n|---|---|---|---|\n| **Trên (hạ sườn)** | Gan (nang, u, phì đại); túi mật (ứ mật, u, túi mật nước, sỏi); đại tràng (u, amip, lồng ruột, túi thừa, lao hồi manh tràng); tá tràng (ứ dịch, u); mạc treo (hạch, u); thận (chướng nước, u, sỏi); u sau phúc mạc, phình mạch | **Thượng vị**: dạ dày; đại tràng; tụy (nang giả, nang, u); lách; mạc treo; phình mạch | Lách; dạ dày; đại tràng; gan; tụy; mạc treo; u sau phúc mạc |\n| **Giữa (hông, quanh rốn)** | **Hông phải**: đại tràng (u, amip, lồng ruột, túi thừa); mạc treo (hạch, u); thận (chướng nước, u, sỏi); manh tràng; u sau phúc mạc | **Quanh rốn**: đại tràng; ruột non (u, búi phân, khối lồng); tụy (nang giả, nang, u); mạc treo; phình mạch; u sau phúc mạc | **Hông trái**: đại tràng (u, amip, lồng ruột, túi thừa, khối phân); mạc treo (hạch, u); thận (chướng nước, u, sỏi); u sau phúc mạc; phình mạch |\n| **Dưới** | **Hố chậu phải**: manh tràng (u, amip, lồng ruột, túi thừa); lao hồi manh tràng; mạc treo (hạch, u); ruột thừa (viêm, u); bướu buồng trứng; tinh hoàn; u sau phúc mạc; phình mạch | **Hạ vị**: bàng quang; tử cung; đại tràng; phần phụ (lạc nội mạc); bướu buồng trứng; khoang ngoài phúc mạc | **Hố chậu trái**: bướu đại tràng; bướu chỗ nối đại tràng chậu hông và trực tràng; khối phân; bướu buồng trứng; tinh hoàn; u sau phúc mạc; phình mạch |\n\n> [!tip] Cách dùng bảng\n> Xác định **vị trí ban đầu** và vị trí khi khám, đối chiếu vùng để ra danh sách tạng, rồi dùng triệu chứng đi kèm (mục 2) và tính chất khối (mục 3.2) để thu hẹp {{TCBN tr.70}}\n\n#### 3.2. Tính chất khối khi sờ\nTài liệu nêu \"tám tính chất\" nhưng liệt kê nhiều hơn; nhớ nhóm sau {{TCBN tr.70–71}}.\n\n| Tính chất | Nội dung | Nguồn |\n|---|---|---|\n| **Kích thước** | Vài đến hàng chục cm; nhỏ thì khó phát hiện, lớn thì khó xác định loại u | {{TCBN tr.70}} |\n| **Mật độ** | U đặc: **chắc đến cứng**; chứa khí hoặc dịch: **căng đến căng cứng** | {{TCBN tr.70}} |\n| **Bề mặt** | Chứa dịch hoặc khí: trơn láng. **U đặc ác tính: thường gồ ghề** | {{TCBN tr.70}} |\n| **Giới hạn** | Rõ nếu lớn và không quá sâu. Đám quánh ruột thừa (khối viêm) giới hạn **không rõ**; áp xe ruột thừa giới hạn **rõ** | {{TCBN tr.70}} |\n| **Di động** | U trong khoang phúc mạc, không quá lớn, có chân hoặc cuống: **di động dễ** khi đổi tư thế hoặc dồn đẩy. Dễ di động: u mạc treo ruột non, lách, nang buồng trứng | {{TCBN tr.70}} |\n| **Biến mất** | Đổi tư thế hoặc đổi áp lực ổ bụng (thoát vị); tự biến mất khi tháo dịch, hơi (u giả); kèm đau dữ dội: vỡ. Khối viêm tiến triển tốt thì **nhỏ dần, bệnh nhân giảm đau** | {{TCBN tr.70–71}} |\n| **Ấn đau** | Khối xoắn quanh chân, thắt, viêm nhiễm hoặc quá to dọa vỡ. Ấn đau toàn bề mặt: u hoại tử (xoắn hoặc không), khối viêm, dọa vỡ. Điển hình nhất: cổ túi thoát vị bẹn hoặc đùi nghẹt | {{TCBN tr.71}} |\n| **Đập theo mạch** | Xem bên dưới | {{TCBN tr.71}} |\n\n- **Gồng thành bụng** (nâng đầu, nhổm dậy): khối **mờ đi hoặc biến mất** thì nằm **trong khoang bụng**; khối **rõ hơn** thì nằm trong các lớp thành bụng hoặc trong ổ bụng nhưng dính vào thành bụng {{TCBN tr.70}}\n- **Đập theo mạch (thì tâm thu)**: u dính vào thành động mạch lớn (động mạch chủ, động mạch chậu) thì **nảy lên xuống**; **phình động mạch thì bung ra** (tăng kích thước nhẹ) theo mạch, thường kèm âm thổi khi nghe {{TCBN tr.69, 71}}\n\n> [!red] Khối bụng cần xử trí ngay\n> - Khối **biến mất kèm đau bụng dữ dội lan khắp bụng**: nghĩ khối hoặc tạng liên quan **bị vỡ** {{TCBN tr.69, 71}}\n> - Khối **to nhanh đột ngột kèm đau bụng** sau một thời gian không đổi {{TCBN tr.68}}\n> - Khối **ấn đau nhiều** do xoắn, thắt, hoại tử hoặc dọa vỡ; thoát vị bẹn hoặc đùi nghẹt đau ở cổ túi {{TCBN tr.71}}\n> - Khối **đập theo mạch** hoặc có âm thổi: nghĩ **phình động mạch** {{TCBN tr.69, 71}}\n> - Khởi phát đột ngột kèm bụng méo: có thể xoắn đại tràng chậu hông hoặc xoắn nang buồng trứng {{TCBN tr.68}}\n\n### 4. Lưu đồ tiếp cận\n1. **Hỏi và khám** xác định khối ở **thành bụng** hay **trong khoang bụng** (gồng thành bụng, xem mục 3.2) {{TCBN tr.70–71}}\n2. Khối **thành bụng**: chia **do viêm** hay **không do viêm**; không viêm thì chia **lành** hay **ác** {{TCBN tr.71}}\n3. Khối **trong khoang bụng**: xác định **trong** hay **ngoài khoang phúc mạc**; rồi viêm hay không viêm, lành hay ác {{TCBN tr.71–72}}\n4. Theo vùng: **trên rốn** và **trên bên phải** bụng, hỏi triệu chứng tiêu hóa trên, vàng da, sốt, đau, ói máu, phân đen {{TCBN tr.73}}\n5. Chọn **cận lâm sàng** (mục 6) để xác định tạng, bản chất và giai đoạn {{TCBN tr.75}}\n\n#### Nhánh vùng trên rốn và vùng trên bên phải\n| Bối cảnh | Hướng nghĩ | Nguồn |\n|---|---|---|\n| Vàng da, sốt, đau bụng | Viêm, sỏi, áp xe, u của **gan, mật, tụy** | {{TCBN tr.73}} |\n| Triệu chứng tiêu hóa trên (đau, đầy bụng, chán ăn), ói máu, phân đen, hẹp môn vị, tiền căn đau vùng trên rốn | **U dạ dày, u đại tràng** (vùng trên rốn); hẹp hoặc u dạ dày, tá tràng, đại tràng (vùng trên bên phải) | {{TCBN tr.73}} |\n| Vùng trên bên phải, phân đen hoặc đỏ, nhày máu | Hẹp, u dạ dày, tá tràng, đại tràng | {{TCBN tr.73}} |\n| Loại khác | U của tụy, mạc treo, lách, mạch máu; mạc treo, mạch máu, thận | {{TCBN tr.73}} |\n\n### 5. Chẩn đoán phân biệt u lành và ác, khi nào nghĩ ung thư\n#### 5.1. Khối u thành bụng\n| | **Do viêm** | **Không do viêm, lành** | **Không do viêm, ác** |\n|---|---|---|---|\n| Khởi phát | **Đột ngột** | Từ từ | Từ từ giai đoạn đầu |\n| Đặc điểm | Dấu hiệu nhiễm trùng lâm sàng và cận lâm sàng; có thể bội nhiễm trên khối có sẵn | **Không xâm lấn** xung quanh, mật độ không cứng, không dấu viêm | **Xâm lấn xung quanh**, **loét giai đoạn muộn**, đổi màu da (nếu nông), bờ không đều, mật độ **chắc đến cứng** |\n| Ví dụ | Viêm nang lông, nhọt, cụm nhọt (vi khuẩn); siêu vi; nấm | Nang bọc bã đậu, bướu mỡ, bướu mạch máu | Ung thư tế bào đáy, ung thư biểu mô da, ung thư hắc tố |\n| Nguồn | {{TCBN tr.72}} | {{TCBN tr.72}} | {{TCBN tr.72}} |\n\n- Mỗi nhóm có đặc điểm trên ở khoảng **90%** các khối u thành bụng cùng loại {{TCBN tr.72}}\n\n#### 5.2. Khối u trong ổ bụng: gợi ý hướng ác tính\nTài liệu không có bảng riêng \"lành và ác\" cho u trong ổ bụng; dưới đây tổng hợp các dấu hiệu đã nêu rải rác.\n\n| Dấu hiệu | Gợi ý ác | Gợi ý lành, viêm hoặc nang | Nguồn |\n|---|---|---|---|\n| Bề mặt | **Gồ ghề** (u đặc) | Trơn láng (nang, khí, dịch) | {{TCBN tr.70}} |\n| Mật độ | **Chắc đến cứng** | Căng đến căng cứng (khí, dịch) | {{TCBN tr.70}} |\n| Diễn tiến | Triệu chứng mơ hồ lúc sớm; u tụy, u đại tràng thường thành khối ở **giai đoạn tiến triển** | Khối viêm tiến triển tốt nhỏ dần, giảm đau; viêm khởi phát cấp | {{TCBN tr.68, 71, 75}} |\n| Toàn thân | Sụt cân, chán ăn, đầy bụng, khó tiêu | Sốt, đau, dấu nhiễm trùng (viêm) | {{TCBN tr.69, 72}} |\n| Chỉ điểm tạng | Ói máu, phân đen, đàm máu, vàng da, hẹp môn vị, bán tắc | | {{TCBN tr.69, 73}} |\n\n> [!warn] Giới hạn của lâm sàng\n> Mật độ cứng và bề mặt gồ ghề chỉ **gợi ý**; tài liệu chỉ xác định bản chất bằng **hình ảnh và sinh thiết** {{TCBN tr.75}}. Khối viêm (đám quánh ruột thừa) cũng có thể chắc và giới hạn không rõ {{TCBN tr.70}}\n\n### 6. Cận lâm sàng\n| Phương tiện | Giá trị | Nguồn |\n|---|---|---|\n| **Siêu âm bụng** | Chỉ định rộng rãi, rẻ; phân biệt **u từ tạng đặc** với **u chứa dịch**; hướng dẫn sinh thiết vi thể | {{TCBN tr.75}} |\n| **CT bụng hoặc MRI** | Chẩn đoán nguyên nhân và **giai đoạn nếu là ung thư**; CT hướng dẫn sinh thiết | {{TCBN tr.75}} |\n| **Nội soi dạ dày hoặc đại tràng** | Tìm nguyên nhân u dạ dày hoặc đại tràng; **sinh thiết** mô học; nội soi mềm đại tràng còn giải xoắn đại tràng chậu hông | {{TCBN tr.75}} |\n| Chụp dạ dày hoặc đại tràng | Nguyên nhân u dạ dày hoặc đại tràng | {{TCBN tr.75}} |\n| Chụp lưu thông ruột non | U ruột non | {{TCBN tr.75}} |\n| Chụp bụng không chuẩn bị | Sỏi hệ niệu, tắc ruột, lồng ruột | {{TCBN tr.75}} |\n| Chụp động mạch chọn lọc | Bệnh mạch máu lớn, chủ yếu động mạch | {{TCBN tr.75}} |\n| Xét nghiệm hỗ trợ | Công thức máu (thiếu máu, nhiễm trùng), chức năng gan, thận: đánh giá **ảnh hưởng** của khối u | {{TCBN tr.75}} |\n\n- Hình ảnh cho biết **bản chất và nguồn gốc** u; xét nghiệm khác cho biết ảnh hưởng lên người bệnh {{TCBN tr.75}}\n\n### 7. Phần tài liệu không nêu\n- Tài liệu **không nêu** dấu ấn ung thư, tỷ lệ ác tính của từng loại khối, hay chỉ định phẫu thuật; phần điều trị xem từng bệnh: [Ung thư dạ dày](#/n/ngoai-ung-thu-da-day), [Ung thư đại tràng](#/n/ngoai-ung-thu-dai-trang), [Ung thư trực tràng](#/n/ngoai-ung-thu-truc-trang), [Ung thư tế bào gan](#/n/ngoai-ung-thu-gan-hcc)\n- Nhóm ung thư ổ bụng di căn (carcinomatosis) và mạc nối lớn được nêu ở câu thảo luận cuối bài nhưng **không có đáp án** {{TCBN tr.75}}\n\n### Điểm hay thi\n> [!warn]\n> - Phân loại nguyên nhân: **viêm, nang, khối tân sinh, phì đại tạng** {{TCBN tr.67–68}}\n> - **Khối u giả**: dạ dày dãn (tắc môn vị), túi mật căng (tắc ống túi mật hoặc đoạn cuối ống mật chủ), cầu bàng quang (hẹp cổ bàng quang); biến mất khi tháo dịch, hơi hoặc túi phình vỡ {{TCBN tr.68}}\n> - Bốn tính chất khai thác: **khởi phát, vị trí, biến mất, triệu chứng đi kèm** {{TCBN tr.68}}\n> - U đặc ác tính: **bề mặt gồ ghề**, mật độ chắc đến cứng; nang, khí, dịch: trơn láng {{TCBN tr.70}}\n> - **Gồng thành bụng** làm khối mờ: trong ổ bụng; khối rõ hơn: ở thành bụng hoặc ổ bụng nhưng dính thành bụng {{TCBN tr.70}}\n> - Phình động mạch **bung ra** theo mạch; u dính động mạch lớn **nảy lên xuống** {{TCBN tr.71}}\n> - 90% khối u thành bụng ác tính: khởi phát từ từ, xâm lấn, loét muộn; nguyên nhân thường gặp: ung thư tế bào đáy, biểu mô da, hắc tố {{TCBN tr.72}}\n> - Khối biến mất kèm đau dữ dội lan khắp bụng: nghĩ **vỡ** {{TCBN tr.69}}\n> - Siêu âm là chỉ định đầu tay (rẻ, phân biệt đặc và dịch); CT hoặc MRI để chẩn đoán giai đoạn ung thư {{TCBN tr.75}}\n> - Giáo trình cũ (Notion) và TCBN: cùng nội dung, không có khác biệt\n\n### Tự kiểm tra\n- Các nhóm nguyên nhân của khối u bụng? :: Viêm, nang, khối tân sinh (lành, có khuynh hướng ác, ác, túi phình mạch máu), phì đại tạng\n- Khối u giả (u ma) là gì? :: Phần tạng rỗng dãn phía trên chỗ tắc (dạ dày, túi mật, cầu bàng quang...) sờ như khối, biến mất khi tháo dịch, hơi hoặc túi phình vỡ\n- Bốn tính chất của khối cần khai thác khi hỏi bệnh? :: Khởi phát, vị trí, biến mất, triệu chứng đi kèm\n- Khối u biến mất kèm đau bụng dữ dội lan khắp bụng gợi ý gì? :: Khối hoặc tạng liên quan bị vỡ\n- Tính chất hiện ẩn thường gặp nhất ở bệnh nào? :: Thoát vị thành bụng (hiện khi tăng áp lực ổ bụng, mất khi nằm nghỉ)\n- Gồng thành bụng làm khối mờ đi nói lên điều gì? :: Khối nằm trong khoang bụng; khối rõ hơn thì ở lớp thành bụng hoặc dính vào thành bụng\n- Mật độ và bề mặt gợi ý bản chất khối thế nào? :: U đặc: chắc đến cứng, ác tính thường gồ ghề; chứa dịch hoặc khí: căng, bề mặt trơn láng\n- Phân biệt đám quánh ruột thừa và áp xe ruột thừa? :: Đám quánh giới hạn không rõ; áp xe (hóa mủ) giới hạn rõ\n- Khối đập theo mạch: u dính động mạch và phình động mạch khác nhau thế nào? :: U dính động mạch lớn nảy lên xuống; phình động mạch bung ra (tăng kích thước nhẹ) theo mạch tâm thu\n- Đặc điểm khối u thành bụng ác tính? :: Khởi phát từ từ, xâm lấn xung quanh, loét muộn, đổi màu da, bờ không đều, chắc đến cứng; thường là ung thư tế bào đáy, biểu mô da, hắc tố\n- Khối u thành bụng do viêm có đặc điểm gì? :: Khởi phát đột ngột kèm dấu nhiễm trùng (nhọt, viêm nang lông...)\n- Cận lâm sàng nào chỉ định rộng rãi, và nào cho giai đoạn ung thư? :: Siêu âm bụng chỉ định rộng rãi; CT hoặc MRI cho nguyên nhân và giai đoạn"}, {"kind": "foundation", "disease": "", "short": "Nuốt nghẹn – nôn ói", "group": "", "section": 3, "order": 4, "khung": [], "id": "nuot-nghen-non-oi", "title": "Tiếp cận nuốt nghẹn và nôn ói", "layer": "trieuchung", "module": "ngoai-tong-quat", "tags": ["nuốt nghẹn", "nuốt khó", "nôn ói", "tắc nghẽn đường tiêu hóa trên", "tắc thực quản", "tắc đường thoát dạ dày", "hẹp môn vị", "co thắt tâm vị", "ung thư thực quản", "nội soi", "X quang cản quang"], "source": "TCBN tr.47–48, 77–87; Notion (TCHNgK Nuốt nghẹn - Nôn ói)", "body": "> [!key] Nuốt nghẹn và nôn ói là hai triệu chứng chính của tắc nghẽn đường tiêu hóa trên\n> - **Tắc nghẽn đường tiêu hóa trên** = tắc từ miệng đến **góc tá–hỗng tràng** (Treitz), do cơ học hoặc cơ năng; gồm **tắc thực quản** và **tắc đường thoát dạ dày** (hẹp môn vị, tắc tá tràng) {{TCBN tr.77–78}}\n> - **Nuốt nghẹn** khá đặc hiệu cho tắc từ hầu họng đến tâm vị; tắc từ thân vị đến góc Treitz thì **không nghẹn mà nôn** {{TCBN tr.79}}\n> - Trên 90% người lớn nhập viện vì nuốt nghẹn là do **u (chủ yếu ung thư thực quản, tâm vị)** và **co thắt tâm vị** {{TCBN tr.84}}\n> - **Nôn ói** rất không đặc hiệu: nên bám vào triệu chứng đặc hiệu hơn (đau bụng, vàng da, bí trung đại tiện) để biện luận {{TCBN tr.86}}\n> - Chẩn đoán xác định: **nội soi** và **X quang thực quản–dạ dày cản quang**; MSCT để tìm nguyên nhân, đánh giá giai đoạn {{TCBN tr.80–83}}\n> - Liên quan: [Ung thư thực quản](#/n/ngoai-ung-thu-thuc-quan), [Ung thư dạ dày](#/n/ngoai-ung-thu-da-day), Khung 128 [STT 50](#/khung/50) (nghẹn, nuốt khó)\n\n### 1. Định nghĩa\n- **Tắc nghẽn đường tiêu hóa trên**: tắc từ miệng đến góc tá–hỗng tràng, gồm cả cơ học lẫn cơ năng, gây **ứ đọng thức ăn và dịch tiêu hóa** phía trên chỗ tắc {{TCBN tr.78}}\n- Tắc nghẽn đường tiêu hóa là cấp cứu thường gặp trong ngoại khoa; triệu chứng tùy vị trí và nguyên nhân {{TCBN tr.77}}\n- Giới hạn trên/dưới theo xuất huyết tiêu hóa: **góc tá–hỗng tràng**; bài giảng chia theo ranh giới này vì tắc trên và dưới góc Treitz khác nhau về lâm sàng lẫn điều trị {{TCBN tr.77}}\n- **Nuốt khó/nuốt nghẹn**: cảm giác khó khăn hoặc chậm trễ khi nuốt thức ăn đặc hay lỏng, xảy ra ngay khi bắt đầu động tác nuốt {{Notion}}\n  - **Hầu họng**: khó ngay từ khi bắt đầu nuốt; **thực quản**: cảm giác thức ăn \"tắc\" hay \"treo\" ở giữa ngực {{Notion}}\n  - **Nuốt đau** là khác: nóng rát hoặc đau sau xương ức khi thức ăn, nước đi qua thực quản {{Notion}}\n- **Buồn nôn**: khó chịu ở dạ dày, thôi thúc muốn nôn; thường có trước nôn nhưng có khi riêng lẻ {{TCBN tr.79}}\n- **Trớ** (tắc thực quản): thức ăn ứ ở thực quản, đầy quá thì trào ra; **không phải nôn** vì không có cơ bụng và cơ trơn dạ dày tham gia {{TCBN tr.79}}\n- **Nôn vọt**: nôn bất ngờ, không kiểm soát, không buồn nôn báo trước {{Notion}}\n\n### 2. Nguyên nhân tắc nghẽn: cơ học và cơ năng\n| | Tắc thực quản | Tắc đường thoát dạ dày |\n|---|---|---|\n| **Cơ năng** | **Co thắt tâm vị**; rối loạn vận động thực quản (co thắt, liệt) | Co thắt cơ môn vị; liệt dạ dày |\n| **Cơ học, trong lòng** | U thực quản (ung thư, polyp, GIST); u tâm vị; **hẹp do hóa chất**; teo thực quản bẩm sinh | **Tắc môn vị**: loét lành tính dạ dày hoặc hành tá tràng, ung thư dạ dày. **Tắc tá tràng**: u tá tràng, u đầu tụy, hội chứng động mạch mạc treo tràng trên, teo tá tràng bẩm sinh |\n| **Cơ học, từ ngoài đè vào** | U trung thất (ung thư, lymphoma, hạch di căn) | (u đầu tụy chèn tá tràng, xem trên) |\n{{TCBN tr.78–79}}\n\n- Tắc đường thoát dạ dày: **đa số là cơ học**, rất ít do rối loạn cơ năng {{TCBN tr.78}}\n- Tắc thực quản: có thể cơ năng (co thắt tâm vị) bên cạnh cơ học từ thực quản hoặc từ ngoài chèn vào {{TCBN tr.78–79}}\n- Cơ chế nuốt khó (hầu họng hay thực quản) quy về **tắc nghẽn cơ học** hoặc **khiếm khuyết thần kinh vận động** {{Notion}}\n\n### 3. Nuốt nghẹn: đặc điểm gợi ý nguyên nhân\n#### Nghẹn đặc, nghẹn lỏng và diễn tiến\n- **Chỉ nghẹn thức ăn đặc**: gợi ý **tắc nghẽn cơ học**; nghẹn **cả đặc lẫn lỏng** ngay từ đầu: gợi ý **rối loạn nhu động** thực quản (co thắt tâm vị) {{Notion}}\n- **Tăng dần** từ đặc sang lỏng, cuối cùng uống nước cũng nghẹn: nguyên nhân đang phát triển (u thực quản–tâm vị, u từ ngoài chèn vào) {{TCBN tr.79}}\n- Nghẹn đặc tăng dần kèm **sụt cân**: nghĩ **ác tính**; từ đặc sang lỏng: tắc nghẽn trầm trọng {{Notion}}\n- **Lúc tăng lúc giảm, có lúc hết hẳn**: co thắt tâm vị; có thể tăng khi gặp nước lạnh/nóng, đồ cay {{TCBN tr.79}}\n- Nghẹn nhẹ, thoáng qua: gặp ở rối loạn tâm lý hoặc **GERD** {{TCBN tr.79}}\n- Người bệnh thường định vị chỗ nghẹn không chính xác; khi than vướng ở cổ hay giữa ngực, nguyên nhân ở thực quản chiếm khoảng **80%** {{Notion}}\n\n#### Hai nhóm nguyên nhân thường gặp\n| | Tắc nghẽn do u | Co thắt tâm vị |\n|---|---|---|\n| Đối tượng | Nam, lớn tuổi | Nữ, trẻ tuổi |\n| Diễn tiến | Nghẹn **tăng dần** | **Lúc tăng lúc giảm**, có khi tự khỏi |\n| Yếu tố khởi phát | Thường không liên quan thức ăn cay, nóng/lạnh | Có thể liên quan |\n| Tổng trạng | Thường **suy kiệt** | Ít bị ảnh hưởng |\n| Nguy cơ | Hút thuốc lá nhiều, tiền căn gia đình ung thư tiêu hóa | Rối loạn tâm lý, hysteria |\n| Triệu chứng kèm | Khó thở, ho ra máu (u rò vào phế quản hoặc di căn phổi), đi cầu phân đen (u xuất huyết), đau bụng (di căn ổ bụng) | Thường không có |\n{{TCBN tr.84}}\n\n- Số ít còn lại: **hẹp thực quản do bỏng hóa chất** (hỏi bệnh sử là ra), rối loạn tâm lý, GERD (thường nhẹ, thoáng qua, tự khỏi hoặc đáp ứng nội khoa) {{TCBN tr.84}}\n- Khai thác: thời điểm khởi phát, mức độ nghẹn theo thời gian, yếu tố làm tăng/giảm; triệu chứng kèm **sụt cân, mất nước, đau ngực, đau bụng, nôn trớ, khó thở, ho ra máu, đi cầu phân đen** {{TCBN tr.83–84}}\n\n@@fold Phân biệt nuốt khó hầu họng và thực quản (Notion)\n| Hầu họng | Thực quản |\n|---|---|\n| Khó ngay giây đầu tiên khi nuốt | Khó khi thức ăn đến giữa ngực |\n| Ngạt thở, ho ngay khi bắt đầu nuốt | Ợ nóng |\n| Trào thức ăn ra mũi | Nôn ói |\n| Loạn vận ngôn, nhìn đôi; yếu cơ mặt (sụp mi, méo miệng) | Đau ngực |\n| Khó phát âm, nói giọng mũi; hơi thở hôi, tiếng óc ách (túi thừa) | Ho |\n- Nghi nuốt khó hầu họng: cho uống **30 ml nước** ở tư thế đứng, quan sát khó nuốt, trào ra mũi, ho trong khoảng 1 phút, kiểm tra phát âm {{Notion}}\n- Nghi hầu họng thì **videofluoroscopy** (chiếu X quang ghi hình) là tốt nhất; nghẹn không do tắc nghẽn thì **đo áp lực thực quản** {{Notion}}\n@@end\n\n### 4. Nôn ói: đặc điểm gợi ý nguyên nhân\n- **Tắc từ thân vị đến góc Treitz**: biểu hiện bằng buồn nôn/nôn, không nghẹn {{TCBN tr.79}}\n- Đau bụng nếu có: quặn cơn trên rốn (dạ dày co thắt đẩy qua chỗ hẹp), hiếm khi âm ỉ liên tục do u xâm lấn; **không nổi bật** {{TCBN tr.79}}\n- Hỏi: số lần, thể tích; trước nôn có ợ nóng, buồn nôn, đầy bụng không; **sau nôn có dễ chịu, giảm đau không**; thời điểm nôn so với bữa ăn {{Notion}}\n\n#### Chất nôn và thời điểm\n| Tính chất | Gợi ý | Nguồn |\n|---|---|---|\n| **Nôn sau ăn** (ngay hoặc 1–2 giờ), **sau nôn dễ chịu, giảm đau** | Tắc nghẽn ống tiêu hóa | {{TCBN tr.86}} {{Notion}} |\n| **Thức ăn cũ chưa tiêu**, có khi muộn 2–4 giờ sau ăn; người bệnh tự móc họng; **không đắng miệng** (chất nôn không có mật) | Hội chứng tắc đường thoát dạ dày: hẹp môn vị, tắc tá tràng trên bóng Vater; giai đoạn đầu chỉ ăn không tiêu, đầy bụng, ợ chua, buồn nôn sau ăn | {{Notion}} |\n| **Nôn mật** | Bệnh lý đoạn cuối tá tràng | {{TCBN tr.48}} |\n| **Dịch giống phân** (nâu đục, hôi) | Tắc ruột thấp hoặc đến muộn | {{Notion}} |\n| **Nôn ra máu** | Có thể do loét hoặc viêm dạ dày tá tràng; nôn máu đỏ tươi sau nhiều lần nôn thức ăn: **hội chứng Mallory–Weiss** (rách niêm mạc vùng thực quản–tâm vị) | {{TCBN tr.48}} {{Notion}} |\n| **Nôn vọt**, rối loạn tri giác, dấu thần kinh định vị | Tăng áp lực nội sọ | {{TCBN tr.84}} |\n| **Nôn sau khi đau** | Viêm ruột thừa | {{TCBN tr.48}} |\n| **Nôn trước khi đau** | Viêm dạ dày ruột, ngộ độc thức ăn | {{TCBN tr.48}} |\n| **Nôn xong không giảm đau bụng**, luôn kèm đau | Phản ứng của đau bụng (viêm ruột thừa sớm, cơn đau quặn mật, viêm tụy cấp, viêm phúc mạc) | {{TCBN tr.85}} |\n\n- Tắc ruột: nôn là dấu sớm của tắc cao, vị trí tắc càng thấp thì nôn càng trễ; tứ chứng **đau, nôn, bí, chướng** {{TCBN tr.4}} {{Notion}}\n\n#### Các nhóm nguyên nhân nôn ói\n| Nhóm | Ví dụ và đặc điểm | Nguồn |\n|---|---|---|\n| Thần kinh trung ương | Tăng áp lực nội sọ; tiền đình, tai giữa; mắt (tăng nhãn áp); migraine; tâm lý | {{TCBN tr.84}} |\n| Tiêu hóa | Tắc ruột cơ học; liệt dạ dày–ruột; viêm loét dạ dày tá tràng, GERD, thiếu máu nuôi ruột, Crohn; u (ung thư dạ dày, u đầu tụy, u tá tràng); phản ứng của đau bụng | {{TCBN tr.85}} |\n| Thai kỳ | Thai nghén, thai trứng (trễ kinh, tiền căn sản khoa) | {{TCBN tr.85}} |\n| Nhiễm trùng | Nhiễm trùng huyết, ngộ độc thức ăn, viêm gan cấp, viêm dạ dày ruột | {{TCBN tr.85}} |\n| Nội tiết, chuyển hóa | Đái tháo đường nhiễm ceton, toan chuyển hóa, urê huyết cao, tăng canxi, rối loạn Na/K, bệnh tuyến giáp, suy thượng thận | {{TCBN tr.85}} |\n| Niệu dục | Viêm đài bể thận cấp, bệnh thận tắc nghẽn, viêm tai vòi, lạc nội mạc tử cung | {{TCBN tr.85}} |\n| Thuốc, độc chất | Kháng sinh, thuốc phiện, thuốc tránh thai, thuốc chống loạn nhịp, hóa trị; rượu, CO, kim loại nặng | {{TCBN tr.85}} |\n| Khác | Nhồi máu cơ tim cấp, suy tim sung huyết, xạ trị | {{TCBN tr.85}} |\n\n> [!red]\n> - **Nôn kèm rối loạn tri giác, dấu thần kinh định vị, co giật, chấn thương đầu** (nôn vọt): nghĩ tăng áp lực nội sọ {{TCBN tr.84, 86}} {{Notion}}\n> - **Nôn ra máu**; **đau bụng không giảm sau nôn**; **bí trung đại tiện**: nghĩ bụng ngoại khoa, tắc ruột {{TCBN tr.85–86}}\n> - **Mất nước nặng, sốc giảm thể tích** (mạch nhanh, huyết áp tụt); **hạ kali máu** gây yếu cơ hô hấp, loạn nhịp, liệt ruột {{TCBN tr.80}}\n> - **Viêm phổi hít** ở người lớn tuổi, tri giác kém, nằm liệt giường: tiên lượng xấu, tử vong cao {{Notion}}\n> - **Nghẹn tăng dần kèm sụt cân, nghẹn đặc rồi lỏng**: nghĩ ác tính {{TCBN tr.79}} {{Notion}}\n\n#### Hậu quả của nôn kéo dài\n- **Mất nước**: da khô, dấu véo da (+), khát, tiểu ít; nặng thì sốc giảm thể tích {{TCBN tr.80}}\n- **Mất điện giải**: hạ Na (buồn nôn nặng thêm, lừ đừ, co giật, hôn mê do phù não); hạ K (yếu cơ, đau cơ, mạch yếu, loạn nhịp, liệt ruột); trong nôn ói, mất K gặp nhiều nhất {{TCBN tr.80}} {{Notion}}\n- **Kiềm chuyển hóa** do mất HCl: tụt huyết áp tư thế, hạ K, hạ canxi (tetani), toan hô hấp bù trừ {{TCBN tr.80}}\n- Sốt chỉ nhẹ do mất nước; sốt cao, lạnh run gợi ý nguyên nhân khác hoặc biến chứng (thủng, viêm phổi hít) {{TCBN tr.79}}\n\n### 5. Cận lâm sàng\n| Phương tiện | Vai trò | Nguồn |\n|---|---|---|\n| **X quang bụng đứng không sửa soạn** | Ít giá trị trong tắc đường tiêu hóa trên; có thể thấy bóng dạ dày dãn to. Chỉ định khi nghi tắc ruột (quai ruột dãn, mực nước hơi chênh nhau; phim bình thường không loại trừ) | {{TCBN tr.80}} {{Notion}} |\n| **X quang thực quản–dạ dày cản quang** (barit hoặc cản quang tan trong nước) | **Giá trị chẩn đoán cao**. Tắc thực quản: phân biệt ung thư (**hình lõi táo**), u chèn từ ngoài, co thắt tâm vị; vị trí, chiều dài đoạn tắc. Hẹp môn vị, tắc tá tràng: xác định hẹp/tắc (hình **3 lớp** trong hẹp môn vị), vị trí, dự đoán nguyên nhân | {{TCBN tr.80–81}} |\n| **Nội soi dạ dày–thực quản** | Cùng X quang cản quang là **tiêu chuẩn vàng** chẩn đoán xác định tắc thực quản và tắc đường thoát dạ dày; **sinh thiết**; can thiệp (đặt stent chỗ hẹp, nong tâm vị). Ứ đọng nhiều thì **đặt thông rửa dạ dày trước nội soi** | {{TCBN tr.81}} |\n| **Siêu âm bụng** | Phát hiện dạ dày dãn, tăng nhu động; chủ yếu tìm nguyên nhân (u dạ dày, u đầu tụy) và bất thường kèm (tắc mật, di căn gan, dịch ổ bụng) | {{TCBN tr.82}} |\n| **MSCT ngực hoặc bụng** (có cản quang) | Nguyên nhân, vị trí, **giai đoạn TNM**, biến chứng, tiên lượng; tiêu chuẩn vàng đánh giá giai đoạn u vùng bụng. Hạn chế duy nhất: **không đánh giá nhu động** | {{TCBN tr.83}} |\n| **Xét nghiệm máu** | Cô đặc máu (Hct, Hgb tăng), urê, creatinine tăng; điện giải giảm Na, K, Cl, Ca; khí máu kiềm chuyển hóa. Tìm nguyên nhân: amylase/lipase, đường huyết, hormon giáp, beta hCG | {{Notion}} |\n\n> [!warn]\n> - **Tắc ruột**: nội soi dạ dày là **chống chỉ định** (bơm hơi làm các quai ruột dưới căng thêm); X quang dạ dày cản quang cũng chống chỉ định khi tắc ruột hoàn toàn {{Notion}}\n> - **Nghi có thai**: không chỉ định MSCT và X quang bụng trừ trường hợp đặc biệt, phải loại trừ thai trước {{Notion}}\n> - X quang cản quang chỉ thấy chỗ hẹp, khó xác định lành hay ác và không can thiệp được; nội soi làm được cả hai {{Notion}}\n\n@@fold Cận lâm sàng riêng cho nuốt khó (Notion)\n- **X quang nuốt barit**: đánh giá làm trống thực quản, thoát vị khe hoành, chít hẹp, vòng Schatzki, nhu động, trào ngược; có thể cho nuốt viên barit 13 mm hay thức ăn hay gây nghẹn {{Notion}}\n- **Đo áp lực thực quản (manometry), HRM**: nghẹn không do tắc nghẽn, phân loại co thắt tâm vị {{Notion}}\n- **Nội soi tiêu hóa trên**: nghẹn do bất thường cấu trúc hoặc tổn thương niêm mạc; nuốt đau để tìm loét; viêm thực quản tăng bạch cầu ái toan cần sinh thiết ít nhất 5 mẫu {{Notion}}\n@@end\n\n### 6. Bước tiếp cận\n**Nuốt nghẹn**\n1. **Xác định đúng triệu chứng**: nuốt nghẹn (hầu họng hay thực quản) hay nuốt đau; khai thác khởi phát, diễn tiến, đặc hay lỏng, yếu tố tăng giảm, **sụt cân** và triệu chứng kèm {{TCBN tr.83–84}} {{Notion}}\n2. **Nghĩ nhóm chính**: u (nam, lớn tuổi, nghẹn tăng dần, suy kiệt) hay co thắt tâm vị (nữ, trẻ, lúc tăng lúc giảm, tổng trạng tốt); hẹp do hóa chất qua bệnh sử {{TCBN tr.84}}\n3. **Khám và tiền căn**: thuốc đang dùng, xạ trị, phẫu thuật; khám miệng, đầu cổ, hạch, giáp, thần kinh {{Notion}}\n4. **X quang thực quản cản quang và nội soi** (sinh thiết nếu có tổn thương); **MSCT ngực** khi cần đánh giá nguyên nhân từ ngoài, giai đoạn {{TCBN tr.80–83}}\n5. Chuyển hướng điều trị theo nguyên nhân: ung thư thực quản, co thắt tâm vị (nong, stent qua nội soi) {{TCBN tr.81}}\n\n**Nôn ói**\n1. **Đánh giá toàn thân**: mất nước, điện giải, kiềm chuyển hóa; xử trí rối loạn trước khi tìm nguyên nhân {{TCBN tr.79–80}}\n2. **Có đau bụng không** (đau trước hoặc cùng lúc nôn, loại trừ đau cơ bụng do nôn nhiều) {{TCBN tr.86–87}}\n   - **Có đau bụng**: **sau nôn dễ chịu, giảm đau** thì nghĩ tắc ruột cơ học hoặc hẹp môn vị, tắc tá tràng; **nôn xong không giảm đau** thì nghĩ phản ứng của đau bụng hoặc nhiễm trùng tiêu hóa, ngộ độc thức ăn {{TCBN tr.86–87}}\n   - **Không đau bụng, nôn sau ăn** (liên quan tắc nghẽn): **bí trung đại tiện** thì tắc ruột; không thì **hội chứng tắc nghẽn đường thoát dạ dày** {{TCBN tr.86–87}}\n   - **Không đau bụng, nôn không liên quan bữa ăn**: hỏi nôn vọt, dấu thần kinh định vị, chấn thương đầu; tiền đình, tai giữa, nhãn áp; trễ kinh; uống rượu; thuốc, hóa trị, xạ trị; bệnh nội tiết, chuyển hóa, suy thận {{TCBN tr.86}}\n3. **Nguyên tắc loại trừ** khi nôn là triệu chứng duy nhất: loại dần nguyên nhân thường gặp và kinh điển; nhiều trường hợp cần hình ảnh, xét nghiệm máu, có khi không tìm ra nguyên nhân {{TCBN tr.86}}\n4. **Cận lâm sàng có chọn lọc**: nội soi nếu nghi tắc đường thoát dạ dày; X quang bụng, siêu âm, MSCT bụng nếu nghi tắc ruột hay bụng ngoại khoa; loại trừ thai trước khi chụp {{Notion}}\n\n### Điểm hay thi\n> [!warn]\n> - **Nuốt nghẹn** đặc hiệu cho tắc từ hầu họng đến tâm vị; **nôn** gặp khi tắc từ thân vị đến góc Treitz {{TCBN tr.79}}\n> - **Hai nguyên nhân chiếm trên 90%** nuốt nghẹn: u (đa số ung thư thực quản, tâm vị) và co thắt tâm vị {{TCBN tr.84}}\n> - **Tắc nghẽn do u**: nam lớn tuổi, nghẹn **tăng dần**, suy kiệt; **co thắt tâm vị**: nữ trẻ, **lúc tăng lúc giảm**, tổng trạng ít ảnh hưởng {{TCBN tr.84}}\n> - **Trớ** không phải nôn, vì không có cơ bụng và cơ trơn dạ dày tham gia {{TCBN tr.79}}\n> - Tắc đường thoát dạ dày: nguyên nhân **đa số cơ học**; thực quản có thêm nguyên nhân cơ năng (co thắt tâm vị) {{TCBN tr.78}}\n> - **X quang bụng đứng không sửa soạn** ít giá trị; **X quang cản quang** và **nội soi** mới là chẩn đoán xác định; MSCT không đánh giá được nhu động {{TCBN tr.80–83}}\n> - Ứ đọng nhiều: **đặt thông rửa dạ dày trước nội soi** {{TCBN tr.81}}\n> - Nôn sau đau: nghĩ viêm ruột thừa; nôn trước đau: nghĩ viêm dạ dày ruột, ngộ độc thức ăn {{TCBN tr.48}}\n> - Khác biệt thuật ngữ: giáo trình mới dùng \"nuốt nghẹn\", tài liệu Notion dùng \"nuốt khó\", cùng nội dung; Notion cũng ghi hẹp môn vị nôn \"2–4 giờ sau ăn\", giáo trình mới không nêu số giờ {{Notion}}\n\n### Tự kiểm tra\n- Tắc nghẽn đường tiêu hóa trên được định nghĩa từ đâu đến đâu? :: Từ miệng đến góc tá–hỗng tràng, gồm cả cơ học và cơ năng\n- Hai nhóm bệnh chính của tắc nghẽn đường tiêu hóa trên? :: Tắc thực quản và tắc đường thoát dạ dày (hẹp môn vị, tắc tá tràng)\n- Nuốt nghẹn hay nôn gặp khi tắc từ thân vị đến góc Treitz? :: Nôn, không nuốt nghẹn\n- Hai nguyên nhân chiếm trên 90% người lớn nhập viện vì nuốt nghẹn? :: U (chủ yếu ung thư thực quản, tâm vị) và co thắt tâm vị\n- Nghẹn tăng dần từ đặc sang lỏng, kèm sụt cân, gợi ý gì? :: Tắc nghẽn do u (ung thư thực quản, tâm vị)\n- Nghẹn lúc tăng lúc giảm, có khi tự khỏi, nữ trẻ, gợi ý gì? :: Co thắt tâm vị\n- Vì sao trớ không gọi là nôn? :: Không có sự tham gia của cơ bụng và cơ trơn dạ dày\n- Hình ảnh X quang cản quang đặc trưng của ung thư thực quản và hẹp môn vị? :: Hình lõi táo (ung thư thực quản); hình 3 lớp (hẹp môn vị)\n- Chẩn đoán xác định tắc thực quản và tắc đường thoát dạ dày dựa vào đâu? :: Nội soi (sinh thiết) và X quang thực quản–dạ dày cản quang\n- Việc cần làm trước nội soi khi dạ dày ứ đọng nhiều? :: Đặt thông rửa dạ dày\n- Nôn sau ăn, sau nôn dễ chịu và giảm đau gợi ý gì? :: Tắc nghẽn ống tiêu hóa (tắc ruột, hẹp môn vị, tắc tá tràng)\n- Nôn thức ăn cũ, không đắng miệng, gợi ý vị trí tắc nào? :: Tắc môn vị hoặc tá tràng trên bóng Vater (chất nôn không có mật)"}, {"kind": "foundation", "disease": "", "short": "Than phiền hậu môn", "group": "", "section": 3, "order": 7, "khung": [], "id": "than-phien-vung-hau-mon", "title": "Tiếp cận than phiền vùng hậu môn", "layer": "trieuchung", "module": "ngoai-tong-quat", "tags": ["hậu môn", "tiêu ra máu", "đau hậu môn", "khối sa", "trĩ", "nứt hậu môn", "áp-xe hậu môn", "rò hậu môn", "sa trực tràng", "thăm trực tràng", "nội soi đại tràng"], "source": "TCBN tr.88–98; BHNgTH tr.422, 434, 463–464; Notion", "body": "> [!key] Bảy triệu chứng đều phải thăm hậu môn trực tràng bằng ngón tay\n> - Bảy triệu chứng thường gặp: **tiêu ra máu, đau hậu môn, phân có nhầy nhớt, mót rặn, ngứa hậu môn, khối sa ở hậu môn, thay đổi thói quen đại tiện** {{TCBN tr.88}}\n> - Đến khám vì **một trong bảy** triệu chứng này thì **bắt buộc thăm hậu môn trực tràng bằng ngón tay**; mục tiêu là tìm nguyên nhân chữa được {{TCBN tr.88, 91}}\n> - Đa số nguyên nhân **lành tính** (trĩ, nứt hậu môn, áp-xe), nhưng **không được bỏ sót ung thư trực tràng**, nhất là người lớn tuổi {{TCBN tr.97–98}}\n> - Dấu hiệu nghi ung thư (sụt cân, thiếu máu, phân nhỏ dẹt, tiền sử gia đình, >50 tuổi đổi thói quen đại tiện) là chỉ định **nội soi đại tràng** {{TCBN tr.91, 96}}\n> - Chi tiết ung thư: [Ung thư trực tràng](#/n/ngoai-ung-thu-truc-trang); khung thi: [Khung 128 STT 57](#/khung/57)\n\n### 1. Các than phiền thường gặp\n| Than phiền | Gợi ý nguyên nhân | Nguồn |\n|---|---|---|\n| **Tiêu ra máu** (máu đỏ ít, dính giấy, nhỏ giọt bồn cầu, bọc ngoài khối phân) | Trĩ, nứt hậu môn, polyp, viêm ống hậu môn, loét trực tràng, ung thư | {{TCBN tr.88–90}} |\n| **Đau hậu môn** | Nứt hậu môn, trĩ tắc mạch, áp-xe; ít gặp: viêm ống hậu môn, rối loạn đại tiện; hiếm: u | {{TCBN tr.95}} |\n| **Khối sa ở hậu môn** | Trĩ, polyp, sùi mào gà, nhú gai tăng sản, da thừa, sa trực tràng, ung thư | {{TCBN tr.92}} |\n| **Ngứa hậu môn** | Trĩ, nứt hậu môn (ngứa rát), nhú gai tăng sản; rò hậu môn (rỉ dịch hôi kèm ngứa). Tài liệu không có mục riêng cho ngứa | {{TCBN tr.89, 92}}; {{BHNgTH tr.422}} |\n| **Phân có nhầy, mót rặn** | Viêm ống hậu môn (nhầy, phân lỏng hoặc sệt <4 lần/ngày), loét trực tràng (nhầy, mót rặn, đi không hết phân) | {{TCBN tr.90}} |\n| **Chảy dịch, chảy mủ** | Áp-xe (chảy mủ cạnh hậu môn, khối sưng nóng đỏ đau), rò hậu môn (rò mủ mạn, rỉ dịch hôi) | {{TCBN tr.92}}; {{BHNgTH tr.422}} |\n| **Đổi thói quen đại tiện** | Phân nhỏ dẹt gợi u trực tràng hậu môn | {{TCBN tr.91}} |\n\n### 2. Hỏi bệnh sử\n- **Câu hỏi mở** cho than phiền đau: tình trạng đau hoặc khó chịu, sự kiện xảy ra cùng lúc, khi nào xuất hiện, bệnh nhân nghĩ nguyên nhân là gì {{TCBN tr.95}}\n- Đau có **liên quan đại tiện** không; có máu chảy ra trước, cùng lúc hay riêng lẻ với đại tiện; có sờ thấy khối không, khối **tự tụt lên hay phải dùng tay đẩy vào** {{TCBN tr.95–96}}\n- Tính chất đau: cứa rách, liên tục hay từng cơn. Đau **sắc, cấp, khu trú rõ** thường do nguyên nhân tại chỗ; đau **mơ hồ** thường từ trực tràng hoặc lan từ cơ quan khác {{TCBN tr.97}}\n- Chấn thương gần đây (sinh thiết tiền liệt tuyến xuyên trực tràng, quan hệ tình dục ngã hậu môn), **xạ trị vùng chậu** (viêm ống hậu môn hoặc viêm trực tràng do xạ trị thường gặp và rất khó điều trị) {{TCBN tr.91}}\n- Tiền sử polyp tiêu hóa hoặc viêm ruột kéo dài; **tiền sử gia đình ung thư đại trực tràng**; tuổi (nguy cơ tăng đáng kể sau 40–50 tuổi) {{TCBN tr.91}}\n\n#### Cách xác định nguồn gốc máu\n| Dạng tiêu ra máu | Gợi ý nguồn chảy máu | Nguồn |\n|---|---|---|\n| Lẫn trong phân | Từ phía trên đại tràng chậu hông | {{TCBN tr.90}} |\n| Dính bề mặt khối phân | Dưới trực tràng và hậu môn | {{TCBN tr.90}} |\n| Riêng biệt với phân (nhỏ xuống bồn cầu trước hoặc sau đại tiện) | Dưới trực tràng và hậu môn | {{TCBN tr.90}} |\n| Dính giấy vệ sinh | Da hậu môn | {{TCBN tr.90}} |\n\n> [!red]\n> - **Dấu hiệu báo động** (nghĩ ung thư, viêm ruột, nhiễm trùng ruột): **sụt cân, thiếu máu mạn, tiêu máu lẫn trong phân hoặc phân màu nâu, sốt, đau bụng, đau tăng dần từng ngày, mất cảm giác hoặc yếu cơ** (nhiễm trùng hoặc u xâm lấn tủy, rễ thần kinh), **đổi thói quen đại tiện ở người >50 tuổi** {{TCBN tr.96}}\n> - Sốt, sụt cân, đổ mồ hôi ban đêm gợi nguyên nhân ác tính hoặc viêm mạn, thường kèm phân nhầy, mót rặn hoặc đau bụng hạ vị {{TCBN tr.91}}\n> - Tiêu ra máu: bước đầu tiên của sơ đồ 5 bước là **đánh giá huyết động** {{TCBN tr.91}}\n\n### 3. Thăm khám hậu môn trực tràng\n- **Quan sát** hậu môn, rồi **thăm trực tràng bằng ngón tay**; khám thêm toàn thân (thiếu máu, hạch) {{TCBN tr.91}}\n- Tư thế khám thường dùng: **gối khuỷu** hoặc **nằm nghiêng trái** {{BHNgTH tr.463}}\n- Nhìn có thể thấy trĩ ngoại, nứt hậu môn, trĩ nội sa, huyết khối trĩ ngoại, ung thư hậu môn {{BHNgTH tr.463}}\n- Thăm bằng ngón tay là động tác **quan trọng nhất để loại trừ ung thư hậu môn trực tràng** và phát hiện đau do trĩ thuyên tắc; bắt buộc vì đau hậu môn có thể lan từ bệnh lý cơ quan khác {{BHNgTH tr.463}}; {{TCBN tr.97}}\n- Nội soi hậu môn trực tràng sau thăm khám giúp thấy trĩ nội độ 1–2, nứt hậu môn, polyp, ung thư trực tràng {{BHNgTH tr.463}}\n- Nghi áp-xe khoang sâu: thăm bằng ngón tay là cách tốt nhất để phát hiện vì nhìn ngoài da có thể không thấy {{BHNgTH tr.431}}\n\n### 4. Chẩn đoán phân biệt\n#### Tiêu ra máu: nguyên nhân sau khi đã làm đầy đủ\n| Tỷ lệ | Nguyên nhân | Nguồn |\n|---|---|---|\n| 20% | Không tìm được nguyên nhân (có thể rách mô đã tự lành khi khám) | {{TCBN tr.90}} |\n| 50% | Bệnh lành tính hậu môn trực tràng: trĩ, nứt hậu môn, chấn thương nông (giấy vệ sinh) | {{TCBN tr.90}} |\n| 20–40% | Polyp (tăng sản hoặc tuyến) | {{TCBN tr.90}} |\n| 2–7% | Ung thư trực tràng (tăng theo tuổi) | {{TCBN tr.90}} |\n| 5–15% | Viêm ruột (IBD) | {{TCBN tr.90}} |\n| 2–5% | Tổn thương mạch máu (AVM) | {{TCBN tr.90}} |\n| 1% | Loét lành tính (NSAID, táo bón kéo dài) | {{TCBN tr.90}} |\n\nTiêu ra máu chiếm **15–20%** ở mọi lứa tuổi {{TCBN tr.89}}.\n\n#### Đặc điểm từng bệnh\n| Bệnh | Chìa khóa bệnh sử, khám | Xử trí | Nguồn |\n|---|---|---|---|\n| **Trĩ** | Máu đỏ tươi không lẫn phân, **không đau hậu môn**, chảy khi rặn hoặc vài giọt sau đại tiện; khối mềm trong ống hậu môn; có thể ngứa. Đau nhiều khi có huyết khối hoặc nghẹt | Chất xơ, thuốc bền thành tĩnh mạch, thuốc bôi, chống táo bón; thắt trĩ vòng cao su, quang đông hồng ngoại; cắt trĩ hoặc Longo | {{TCBN tr.89, 92}}; {{BHNgTH tr.463}} |\n| **Trĩ tắc mạch** | Đau cấp kèm khối ở hậu môn, sưng đau | Nội dung điều trị tài liệu không nêu trong bài này | {{TCBN tr.96–97}} |\n| **Nứt hậu môn** | Đau **như dao cứa** khi đi tiêu phân cứng, máu đỏ dính giấy, táo bón, có thể ngứa rát. Vết rách da dưới đường lược, hay ở **đường giữa sau** | Bài không nêu | {{TCBN tr.89, 97}}; {{BHNgTH tr.422}} |\n| **Áp-xe hậu môn** | Chảy mủ cạnh hậu môn, khối **sưng nóng đỏ đau**; đau **liên tục**, ít liên quan đại tiện | **Rạch dẫn lưu** | {{TCBN tr.92}}; {{BHNgTH tr.422}} |\n| **Rò hậu môn** | Rò mủ mạn, lỗ rò ngoài dạng mụn mủ; đau tái lại, rỉ dịch hôi, ngứa. Đường hầm nối trong hậu môn với da quanh hậu môn, là dạng mạn của cùng quá trình với áp-xe | Bài không nêu | {{BHNgTH tr.422, 434}} |\n| **Polyp** | Tiền sử polyp, thường phát hiện khi nội soi; u tuyến là tổn thương tiền ung thư | Nội soi đại tràng tìm polyp nơi khác; cắt polyp và sinh thiết | {{TCBN tr.89, 92–93}} |\n| **Nhú gai tăng sản** | Ngứa; ở đường lược, trắng hơn, cứng hơn polyp; dễ nhầm polyp | Chắc chắn thì không cần điều trị; nghi ngờ thì cắt trọn để sinh thiết | {{TCBN tr.92–93}} |\n| **Da thừa hậu môn** | Trước đây là trĩ ngoại, mẫu da riêng cạnh hậu môn | Phẫu thuật cắt bỏ | {{TCBN tr.93}} |\n| **Sùi mào gà** | Quan hệ tình dục ngã hậu môn; **HPV type 6 và 11** | Trichloracetic acid, đốt laser, đốt điện | {{TCBN tr.93}} |\n| **Sa trực tràng** | Phụ nữ mãn kinh, táo bón kéo dài, sa sàn chậu (kèm sa sinh dục, bàng quang); sa toàn bộ thành hoặc niêm mạc qua ống hậu môn | Phẫu thuật | {{TCBN tr.93}} |\n| **Ung thư trực tràng** | Tiền sử gia đình, sụt cân, thiếu máu, **phân nhỏ dẹt**; khối **cứng** ở trực tràng hoặc hậu môn | Phẫu thuật | {{TCBN tr.93}} |\n\n@@fold Đau hậu môn: ba nhóm nguyên nhân và lưu đồ\n- **Tại chỗ**: nứt hậu môn, áp-xe, trĩ tắc mạch (thường gặp); rối loạn đại tiện hoặc anismus, viêm ống hậu môn (ít gặp); u (hiếm) {{TCBN tr.95}}\n- **Lan theo thần kinh từ tạng khác**: viêm xương cụt, chèn ép rễ cùng, viêm tiền liệt tuyến, bệnh tử cung và vùng chậu {{TCBN tr.95}}\n- **Rối loạn chức năng**: proctalgia fugax (thường gặp), hội chứng cơ nâng hậu môn (hiếm) {{TCBN tr.95}}\n- **Đau khi đại tiện**: đau khu trú rõ, như xé do phân cứng thì khám tìm nứt hậu môn; đau cấp kèm khối thì khám tìm trĩ tắc mạch; đau mơ hồ vùng trực tràng thì tách theo tiêu chảy, mót rặn (viêm ống hậu môn) hay táo bón (kẹt phân, sa trực tràng, trĩ sa) {{TCBN tr.96}}\n- **Đau không liên quan đại tiện**: đau thành cơn kéo dài vài giây đến vài phút là proctalgia fugax, trên 20 phút là hội chứng cơ nâng hậu môn; đau liên tục kèm chảy mủ hoặc máu thì nghĩ rò hậu môn, áp-xe trước xương cùng; đau sau ngồi lâu hoặc kích thích xương cụt là viêm xương cụt; không có triệu chứng thể chất thì nghĩ bướu tân sinh {{TCBN tr.97}}\n- Proctalgia fugax: cơn đau ngắn, ít triệu chứng khác; viêm xương cụt: sau té hoặc chấn thương, xương cụt cứng, viêm, ấn đau {{TCBN tr.97–98}}\n@@end\n\n### 5. Khi nào nghi ung thư và cần nội soi\n- Ung thư chiếm **2–7%** nguyên nhân tiêu ra máu, tăng theo tuổi; thường kèm đau bụng dưới hoặc đổi thói quen đại tiện {{TCBN tr.90}}\n- Ung thư hiếm gây đau hậu môn nên ít được nghĩ tới, nhưng **không được loại trừ**, nhất là người lớn tuổi {{TCBN tr.97}}\n- Nội soi theo tuổi (tiêu ra máu): {{TCBN tr.91}}\n  - **<40 tuổi**: theo dõi, đánh giá lại lâm sàng hoặc nội soi trực tràng\n  - **40–49 tuổi**: nội soi trực tràng hoặc nội soi đại tràng\n  - **≥50 tuổi**: nội soi đại tràng\n- **Bắt buộc nội soi đại tràng** khi có tiền sử gia đình ung thư đại trực tràng hoặc triệu chứng toàn thân (thiếu máu, sụt cân) {{TCBN tr.91}}\n- Có thể nội soi toàn bộ đại tràng ở mọi bệnh nhân; dữ liệu so sánh nội soi trực tràng với đại tràng còn ít {{TCBN tr.91}}\n- Chỉ định nội soi đại tràng (trong bài trĩ): ≥50 tuổi chưa nội soi trong 10 năm; ≥40 tuổi (hoặc trẻ hơn 10 năm so với tuổi người thân) khi có thân nhân thế hệ 1 bị ung thư đại trực tràng hoặc u tuyến tiến triển <60 tuổi; thử máu ẩn trong phân dương tính {{BHNgTH tr.463}}\n- Nghi polyp hoặc nhú gai: cắt và sinh thiết {{TCBN tr.92–93}}\n\n### 6. Lưu đồ tiếp cận\n1. **Tiêu ra máu**: đánh giá huyết động trước tiên {{TCBN tr.91}}\n2. Xác định **bản chất máu** (lẫn phân, dính phân, riêng biệt, dính giấy) {{TCBN tr.90–91}}\n3. Hỏi có **đau bụng hoặc đau vùng chậu** không {{TCBN tr.91}}\n4. **Thăm hậu môn trực tràng**, quan sát hậu môn (mọi than phiền hậu môn) {{TCBN tr.88, 91}}\n5. Tìm dấu hiệu báo động và yếu tố nguy cơ ung thư (tuổi, tiền sử gia đình, toàn thân) {{TCBN tr.91, 96}}\n6. Chọn nội soi trực tràng hoặc đại tràng theo tuổi và nguy cơ; sinh thiết khi nghi u {{TCBN tr.91–92}}\n7. Một số trường hợp xem xét xuất huyết tiêu hóa ẩn {{TCBN tr.91}}\n\n### Điểm hay thi\n> [!warn]\n> - Than phiền hậu môn nào cũng cần **thăm trực tràng bằng ngón tay**; không quy mọi đau hậu môn cho trĩ rồi bỏ qua cận lâm sàng {{TCBN tr.88, 97}}\n> - Trĩ **không đau** khi chảy máu; nứt hậu môn **đau như dao cứa** khi đi tiêu {{TCBN tr.89, 97}}\n> - Áp-xe: đau liên tục, ít liên quan đại tiện, xử trí **rạch dẫn lưu** {{TCBN tr.92}}; {{BHNgTH tr.422}}\n> - Phân nhỏ dẹt, sụt cân, thiếu máu, tiền sử gia đình: nghĩ ung thư, nội soi đại tràng bắt buộc {{TCBN tr.91, 93}}\n> - Nội soi theo tuổi: <40, 40–49, ≥50 {{TCBN tr.91}}\n> - Sùi mào gà do HPV **type 6 và 11** {{TCBN tr.93}}\n> - Giáo trình cũ (Notion) trùng nội dung TCBN, không có điểm khác cần ghi\n\n### Tự kiểm tra\n- Bảy triệu chứng thường gặp của bệnh lý vùng hậu môn trực tràng? :: Tiêu ra máu, đau hậu môn, phân có nhầy nhớt, mót rặn, ngứa hậu môn, khối sa ở hậu môn, thay đổi thói quen đại tiện\n- Khi bệnh nhân có một trong bảy triệu chứng đó thì bắt buộc làm gì? :: Thăm hậu môn trực tràng bằng ngón tay\n- Máu dính giấy vệ sinh gợi chảy máu từ đâu? :: Da hậu môn\n- Trĩ khác nứt hậu môn thế nào về đau? :: Trĩ chảy máu không đau; nứt hậu môn đau như dao cứa khi đi tiêu phân cứng\n- Ba nguyên nhân thường gặp nhất gây đau hậu môn? :: Nứt hậu môn, trĩ tắc mạch, áp-xe hậu môn trực tràng\n- Xử trí áp-xe hậu môn? :: Rạch dẫn lưu\n- Sùi mào gà sinh dục do tác nhân nào? :: HPV type 6 và 11\n- Tỷ lệ ung thư trực tràng trong nguyên nhân tiêu ra máu? :: 2–7%, tăng theo tuổi\n- Nội soi trong tiêu ra máu theo tuổi? :: <40: theo dõi hoặc nội soi trực tràng; 40–49: nội soi trực tràng hoặc đại tràng; ≥50: nội soi đại tràng\n- Hai tình huống bắt buộc nội soi đại tràng? :: Tiền sử gia đình ung thư đại trực tràng; triệu chứng toàn thân (thiếu máu, sụt cân)\n- Triệu chứng báo động trong đau hậu môn? :: Sụt cân, thiếu máu mạn, tiêu máu lẫn phân hoặc phân nâu, sốt, đau bụng, đau tăng dần, mất cảm giác hoặc yếu cơ, đổi thói quen đại tiện ở người >50 tuổi\n- Nhú gai tăng sản dễ nhầm với gì và xử trí khi nghi ngờ? :: Dễ nhầm polyp hậu môn; nghi ngờ thì cắt trọn để sinh thiết"}, {"kind": "foundation", "disease": "", "short": "Vàng da", "group": "", "section": 3, "order": 3, "khung": [], "id": "vang-da", "title": "Tiếp cận vàng da", "layer": "trieuchung", "module": "ngoai-tong-quat", "tags": ["vàng da", "tắc mật", "bilirubin", "sỏi ống mật chủ", "u quanh bóng Vater", "tam chứng Charcot", "siêu âm", "MRI", "ERCP"], "source": "TCBN tr.107–117; BHNgTH tr.285–287, 336–340", "body": "> [!key] Ba câu hỏi liên tiếp: có vàng da thật không, thuộc nhóm nào, nguyên nhân là gì\n> - **Vàng da** = da, kết mạc, niêm mạc vàng do bilirubin tích tụ trong mô; thường thấy khi bilirubin huyết tương tăng trên ==34,2 µmol/L (2 mg/dL)== {{TCBN tr.107}}\n> - Chia 3 nhóm theo sinh lý bệnh: **trước gan** (phân hủy hemoglobin), **tại gan** (tổng hợp, bài tiết bilirubin ở gan), **sau gan** (bài tiết mật, tức tắc mật ngoài gan) {{TCBN tr.108}}\n> - **Phân bạc màu**: rất đặc hiệu cho tắc mật nhưng độ nhạy thấp; vàng da tắc mật nặng mới có {{TCBN tr.109, 112}}\n> - Lâm sàng khó phân biệt tại gan với sau gan, nên cần **bilirubin, ALP, GGT và hình ảnh**; siêu âm là phương tiện đầu tay {{TCBN tr.112, 115}}\n> - Tắc mật do **sỏi**: cấp, hay có Charcot; do **u**: chậm, ít đau, ít sốt, vàng sậm tăng dần {{TCBN tr.110}}\n> - Liên kết: [Ung thư quanh bóng Vater](#/n/ngoai-ung-thu-quanh-bong-vater); Khung 128 [STT 62](#/khung/62) (vàng da)\n\n### 1. Sinh lý bệnh ngắn gọn\n- Hem của hồng cầu → **bilirubin gián tiếp** (phải gắn protein vận chuyển) → vào gan, **liên hợp** thành bilirubin trực tiếp → bài tiết qua mật xuống tá tràng {{TCBN tr.108}}\n- Trong ống tiêu hóa, bilirubin trực tiếp thải qua phân khoảng 85% (stercobilin, tạo màu vàng của phân), qua nước tiểu 1% (urobilin), phần còn lại tái hấp thu về gan {{TCBN tr.108}}\n- Tăng bilirubin toàn phần có thể do tăng gián tiếp, tăng trực tiếp hoặc hỗn hợp; từ đó hướng chẩn đoán nhóm nguyên nhân {{TCBN tr.108}}\n\n### 2. Nguyên nhân theo ba nhóm\n| Nhóm | Nguyên nhân thường gặp | Bilirubin |\n|---|---|---|\n| **Trước gan** | Bệnh lý hemoglobin (hồng cầu hình liềm, hình bia, thalassemia), cường lách nguyên phát và thứ phát, sốt rét, thiếu men G6PD, truyền máu nhiều lần {{TCBN tr.110}} | Gián tiếp ưu thế {{TCBN tr.113}} |\n| **Tại gan** | Viêm gan cấp (thuốc, siêu vi), xơ gan (rượu, siêu vi), áp xe gan do vi trùng; ít gặp: hội chứng Gilbert, Crigler-Najjar {{TCBN tr.110}} | Gián tiếp, trực tiếp hoặc hỗn hợp {{TCBN tr.113}} |\n| **Sau gan** | Sỏi ống mật chủ, giun chui ống mật, viêm hẹp Oddi lành tính, **u quanh bóng Vater** (u bóng Vater, u đoạn cuối ống mật chủ, u đầu tụy, u tá tràng), **u ngã ba đường mật (Klatskin)** {{TCBN tr.110}} | Trực tiếp ưu thế {{TCBN tr.113}} |\n\n- Trước gan: đa phần là bệnh huyết học, hay gặp nhất là tán huyết mạn do bất thường bẩm sinh hemoglobin; bệnh nhân thường **10–30 tuổi**, vàng da sậm, gan to lách to, thiếu máu mạn phải truyền máu nhiều lần, có tiền căn gia đình {{TCBN tr.110}}\n- Tại gan: thường gặp nhất viêm gan cấp, xơ gan (vàng da là triệu chứng của hội chứng suy tế bào gan), kế đến áp xe gan; ung thư tế bào gan thường vàng da do **xơ gan đi kèm**, rất hiếm do u gan to chèn ép {{TCBN tr.110}}\n- Sau gan: tắc nghẽn đường mật ngoài gan, lành tính (sỏi, giun, hẹp Oddi, u lành) hoặc ác tính (ung thư quanh bóng Vater, ung thư đường mật rốn gan) {{TCBN tr.110}}\n\n> [!red] Cần nghĩ tới tình huống nặng\n> - **Viêm đường mật do tắc nghẽn** (sỏi, giun): đau hạ sườn phải, sốt cao lạnh run, vàng da {{TCBN tr.110, 112}}; ERCP hoặc PTC vừa chẩn đoán vừa dẫn lưu mật {{TCBN tr.116}}\n> - **Tán huyết nội mạch cấp** (truyền nhầm nhóm máu, sốt rét ác tính thể tiểu Hb): ít vàng da rõ nhưng thường nguy kịch, sốc phản vệ, tiểu Hb, hoại tử ống thận cấp {{TCBN tr.110}}\n\n### 3. Lâm sàng\n#### 3.1. Dấu hiệu nhận biết vàng da\n| Biểu hiện | Lưu ý | Nguồn |\n|---|---|---|\n| Da vàng sậm | Người châu Á thường phát hiện trễ; dễ thấy ở lòng bàn tay bàn chân | {{TCBN tr.108}} |\n| Niêm mạc mắt, đáy lưỡi vàng | Khó nhận khi thiếu máu nhiều hoặc đa hồng cầu | {{TCBN tr.109}} |\n| Kết mạc mắt vàng | Dễ thấy do nền trắng | {{TCBN tr.109}} |\n| Nước tiểu vàng sậm như nước trà | Phân biệt với cô đặc nước tiểu do thiếu nước hoặc do thuốc | {{TCBN tr.109}} |\n| **Phân bạc màu** | Chỉ gặp trong vàng da **tắc mật nặng** (trong gan và ngoài gan); rất đặc hiệu, độ nhạy rất thấp | {{TCBN tr.109}} |\n| **Ngứa toàn thân** | Gặp trong tắc mật (sau gan hoặc tại gan); cơ chế chưa rõ (muối mật ứ ở da hay các chất trung gian gây ngứa) | {{TCBN tr.109}} |\n\n- Khám ở nơi **đủ ánh sáng** để phát hiện vàng da kín đáo {{TCBN tr.109}}\n- Hỏi: thời điểm phát hiện, tốc độ nhanh hay chậm, từng đợt không, tiền căn vàng da; triệu chứng kèm (đau bụng, sốt, chán ăn sụt cân, mệt, chóng mặt, nôn, bụng to) {{TCBN tr.108–109}}\n\n#### 3.2. Bước 1: có thật sự vàng da không\n- Loại trừ vàng giả: **beta caroten** (chỉ lòng bàn tay bàn chân vàng cam), **hút thuốc lá nhiều** (đốm vàng ở mắt), nước tiểu sậm do cô đặc hoặc thuốc {{TCBN tr.109, 111}}\n- Vàng da kín đáo, lâm sàng không chắc: dùng **bilirubin toàn phần** huyết tương (tiêu chuẩn vàng) để khẳng định {{TCBN tr.111}}\n\n#### 3.3. Bước 2: trước gan, tại gan hay sau gan\n- Nghĩ **trước gan** khi: dưới 30 tuổi, vàng da mạn từ lâu, gan lách to, thiếu máu (vàng trên nền xanh), tiền căn bản thân hoặc người thân trực hệ có bệnh huyết học {{TCBN tr.112}}\n- Nghĩ **sau gan** khi có **phân bạc màu** (đặc hiệu, kém nhạy) hoặc **túi mật to** (chỉ gợi ý) {{TCBN tr.112}}\n- **Túi mật to** không đặc hiệu: còn do viêm túi mật, ung thư; ngược lại tắc phía trên chỗ đổ của ống túi mật (u ngã ba đường mật) không làm túi mật to {{TCBN tr.112}}\n- Phân biệt sau gan với tại gan trên lâm sàng **đa số rất khó**, thường phải nghĩ tới cả hai nhóm, rồi dựa cận lâm sàng {{TCBN tr.112}}\n\n#### 3.4. Bước 3: nguyên nhân (gợi ý lâm sàng cho tại gan và sau gan)\n| Nguyên nhân | Gợi ý | Nguồn |\n|---|---|---|\n| Xơ gan | Nghiện rượu, viêm gan B, C, hội chứng tăng áp tĩnh mạch cửa, hội chứng suy tế bào gan | {{TCBN tr.112}} |\n| Viêm gan | Tiền căn nhiễm siêu vi, đang dùng thuốc hại gan, ngộ độc rượu, suy tế bào gan | {{TCBN tr.112}} |\n| Áp xe gan do vi trùng | Đau tức hạ sườn phải, rung gan (+), sốt cao lạnh run, yếu tố nguy cơ | {{TCBN tr.112}} |\n| Sỏi ống mật chủ | Tiền căn sỏi mật, đau tức hạ sườn phải, sốt cao lạnh run (Charcot) | {{TCBN tr.112}} |\n| Giun chui ống mật | Tiền căn nhiễm giun hoặc đã điều trị, vùng dịch tễ, thói quen ăn uống, uống thuốc sổ giun, Charcot | {{TCBN tr.112}} |\n| U quanh bóng Vater | Lớn tuổi, chán ăn sụt cân, vàng da tăng dần từ từ, vàng sậm, túi mật căng to, có thể sờ được u | {{TCBN tr.112}} |\n\n### 4. Cận lâm sàng chọn lọc\n#### 4.1. Xét nghiệm\n@@tabs\n@@tab Bilirubin\n- Bình thường: toàn phần ==0,8–1,2 mg/dL==; gián tiếp 0,6–0,8; trực tiếp 0,2–0,4 {{TCBN tr.113}}\n- Vàng da rõ khi toàn phần **>2,5 mg/dL**; từ 2–2,5 mg/dL chưa thấy rõ, gọi là vàng da dưới lâm sàng {{TCBN tr.113}}\n- Tỉ số trực tiếp / toàn phần: **<20%** gián tiếp ưu thế; **>50%** trực tiếp ưu thế; **20–50%** hỗn hợp. Một số tài liệu khác dùng mốc 15% {{TCBN tr.113}}\n- Trước gan: gián tiếp ưu thế; sau gan: trực tiếp ưu thế; tại gan: có thể gián tiếp, trực tiếp hoặc hỗn hợp {{TCBN tr.113}}\n@@tab ALP, GGT\n- **ALP** (bình thường 25–85 U/L) rất nhạy với tắc mật, kém đặc hiệu; **tăng sớm** cả khi tắc không hoàn toàn, lúc đó bilirubin có thể còn bình thường; ALP bình thường thì ít nghĩ do tắc mật {{TCBN tr.114}}\n- ALP tăng nhẹ vừa (khoảng 2 lần) gặp trong viêm gan, xơ gan, di căn hoặc thâm nhiễm gan; **tăng 3–10 lần** thường do tắc mật trong hoặc ngoài gan; còn tăng trong bệnh xương (Paget, di căn xương), tăng PTH {{TCBN tr.114}}\n- **GGT** (khoảng 30 U/L nữ, 50 U/L nam) nhạy nhưng không đặc hiệu: nghiện rượu mạn, tắc mật, thuốc cảm ứng enzym, gan nhiễm mỡ không do rượu {{TCBN tr.114}}\n@@tab Nước tiểu\n- Trước gan: bilirubin niệu **âm tính**, urobilinogen **tăng cao** {{TCBN tr.114}}\n- Có tắc mật (bilirubin trực tiếp tăng): có sắc tố mật và muối mật trong nước tiểu, urobilinogen giảm hoặc âm tính {{TCBN tr.114}}\n@@end\n\n#### 4.2. Hình ảnh học\n| Phương tiện | Giá trị | Nguồn |\n|---|---|---|\n| **Siêu âm** | **Đầu tay** để phân biệt tắc mật ngoài gan với nhóm còn lại; rẻ, nhanh, lặp lại được, an toàn khi có thai. Dấu hiệu: đường mật trong và ngoài gan giãn, túi mật to, có thể thấy sỏi, giun, u. Phụ thuộc người làm; độ nhạy tắc mật ngoài gan 55–91%, kém khi tắc ở đoạn ống mật chủ sau tá tràng | {{TCBN tr.115}} |\n| **EUS** | Nhạy hơn CT và siêu âm bụng khi xếp giai đoạn ung thư đầu tụy, ung thư nhú Vater; hữu ích với u tụy nhỏ (<2 cm); kèm chọc hút kim nhỏ (FNA) lấy mô; đòi hỏi trang bị, không sẵn ở mọi nơi | {{TCBN tr.115}} |\n| **CT** | Nhạy và đặc hiệu hơn siêu âm; **không thấy sỏi không cản quang**; với u giúp xếp giai đoạn TNM | {{TCBN tr.115}} |\n| **MRI (MRCP)** | Nhạy và đặc hiệu cao nhất trong các phương tiện không xâm lấn (có thể 90–100%); dựng hình cây đường mật, định vị tổn thương; đắt, lâu, chống chỉ định khi có kim loại, máy tạo nhịp | {{TCBN tr.116}} |\n| **ERCP, PTC** | Xâm lấn, vừa chẩn đoán vừa **dẫn lưu mật**; cân nhắc khi hình ảnh không xâm lấn không xác định được hoặc cần dẫn lưu | {{TCBN tr.116}} |\n| **Sinh thiết gan** | Khi nghi sau gan mà hình ảnh và huyết thanh không tìm ra nguyên nhân; phân biệt ứ mật tế bào gan với ứ mật do tắc nghẽn | {{TCBN tr.117}} |\n\n### 5. Phân biệt tắc mật do sỏi và do u\n| Tiêu chí | Sỏi ống mật chủ, giun | U (quanh bóng Vater, đường mật) |\n|---|---|---|\n| Diễn tiến | Vàng da **cấp**, trong bệnh cảnh viêm đường mật do tắc nghẽn {{TCBN tr.110}} | Vàng da **chậm**, tăng dần, vàng sậm; phần lớn không đau bụng, không sốt {{TCBN tr.110, 112}} |\n| Triệu chứng | Tam chứng **Charcot**: đau hạ sườn phải, sốt, vàng da; sốt cao lạnh run {{TCBN tr.110, 112}} | Chán ăn, sụt cân; vàng da khoảng 75%, sụt cân 51%, đau bụng 39%, ngứa 11%, sốt 3% {{BHNgTH tr.336–337}} |\n| Đau | Cơn đau quặn mật đột ngột, liên tục nhiều giờ, lan vai phải hoặc ra sau lưng; sốt, vàng da xuất hiện sau đau 12–24 giờ. Tắc mạn: đau nhẹ, đôi khi chỉ có vàng da {{BHNgTH tr.285}} | Đau mơ hồ lan ra lưng; giai đoạn muộn đau liên tục, không đáp ứng paracetamol hay NSAID {{BHNgTH tr.336}} |\n| Túi mật | Định luật Courvoisier **thường không đúng** với sỏi ống mật chủ ở Việt Nam {{BHNgTH tr.285}} | Túi mật to sờ thấy là triệu chứng hay gặp; có thể sờ được u {{TCBN tr.112; BHNgTH tr.337}} |\n| Tiền căn | Sỏi mật, nhiễm giun, thói quen ăn uống, uống thuốc sổ giun {{TCBN tr.112}} | Tuổi lớn {{TCBN tr.112}} |\n| Cận lâm sàng | Siêu âm: nhạy 73%, đặc hiệu 91% với sỏi ống mật chủ. CT: nhạy 65% (không cản quang), 84% (có cản quang) {{BHNgTH tr.287}} | CA 19-9 tăng khoảng 75% nhưng không đặc hiệu; CT có cản quang nhạy 90–95% với u đầu tụy; siêu âm bụng nhạy khoảng 25% với u quanh bóng Vater {{BHNgTH tr.338}} |\n\n- **Charcot**: độ nhạy thấp (khoảng 26,4%), độ đặc hiệu cao (95,6%); đủ ba triệu chứng thì gần như chắc viêm đường mật cấp, thiếu thì không loại trừ được (có tiêu chuẩn Tokyo) {{BHNgTH tr.286}}\n- Vàng da chỉ có ở khoảng 70% viêm đường mật do sỏi {{BHNgTH tr.286}}\n- Hai bệnh có thể phối hợp (sỏi mật ở bệnh nhân thalassemia, ung thư đường mật trên xơ gan), cần hội chẩn nhiều chuyên khoa {{TCBN tr.117}}\n- Hình ảnh gợi ý u trên CT: thành ống mật chủ đoạn cuối dày không đều không đối xứng kèm giãn đường mật trong gan; hình ống đôi (double duct sign) hay gặp trong ung thư bóng Vater {{BHNgTH tr.339}}\n\n### 6. Lưu đồ tiếp cận\n1. **Có thật vàng da không?** Loại vàng giả; nghi ngờ thì đo bilirubin toàn phần {{TCBN tr.111}}\n2. **Đặc điểm trước gan?** (dưới 30 tuổi, mạn, gan lách to, thiếu máu, tiền căn huyết học): có thì nhóm trước gan, tìm nguyên nhân tán huyết {{TCBN tr.111–112}}\n3. **Đặc điểm sau gan?** (phân bạc màu, túi mật to): có thì nhóm sau gan {{TCBN tr.111–112}}\n4. Không rõ: **nhóm tại gan hoặc sau gan**, dựa bilirubin (trực tiếp ưu thế hướng sau gan), ALP, GGT và hình ảnh {{TCBN tr.111–114}}\n5. **Siêu âm** trước tiên tìm dấu tắc mật ngoài gan (đường mật giãn, túi mật to, sỏi, giun, u) {{TCBN tr.115}}\n6. Cần rõ nguyên nhân và vị trí: **CT** (u, xếp giai đoạn), **MRI/MRCP**, **EUS** (u nhỏ vùng đầu tụy, bóng Vater) {{TCBN tr.115–116}}\n7. Còn chưa rõ hoặc cần dẫn lưu mật: **ERCP hoặc PTC**; vẫn chưa rõ: sinh thiết gan {{TCBN tr.116–117}}\n\n### Điểm hay thi\n> [!warn]\n> - Vàng da hiện rõ khi bilirubin toàn phần **>2,5 mg/dL**; tiêu chuẩn vàng xác nhận là bilirubin huyết tương. Tài liệu cũng nêu ngưỡng 2 mg/dL (34,2 µmol/L) ở phần định nghĩa; hai mốc cùng nằm trong bài {{TCBN tr.107, 113}}\n> - **Phân bạc màu**: đặc hiệu cho tắc mật, độ nhạy thấp; **túi mật to**: chỉ gợi ý, không đặc hiệu {{TCBN tr.109, 112}}\n> - Sau gan = tắc mật ngoài gan = bilirubin **trực tiếp** ưu thế; trước gan = **gián tiếp** ưu thế {{TCBN tr.113}}\n> - Siêu âm đầu tay; **MRI** có độ nhạy, đặc hiệu cao nhất trong phương tiện không xâm lấn; **CT không thấy sỏi không cản quang** {{TCBN tr.115–116}}\n> - Sỏi: Charcot, cấp; u: chậm, ít đau, ít sốt, vàng sậm, sụt cân. Đề trắc nghiệm hỏi \"không điển hình cho u\" thì đáp án là **diễn tiến cấp, nặng nề** {{TCBN tr.110}}\n> - Ung thư tế bào gan vàng da thường do **xơ gan kèm theo**, hiếm do u chèn ép {{TCBN tr.110}}\n> - Giáo trình 2025 (BHNgTH) nhắc Charcot **nhạy thấp (26,4%)**, đặc hiệu cao; thiếu đủ ba triệu chứng vẫn không loại trừ viêm đường mật {{BHNgTH tr.286}}\n\n### Tự kiểm tra\n- Ngưỡng bilirubin huyết tương khi vàng da thường xuất hiện (định nghĩa)? :: Trên 34,2 µmol/L (2 mg/dL); vàng da rõ khi toàn phần >2,5 mg/dL\n- Ba nhóm nguyên nhân vàng da? :: Trước gan (phân hủy hemoglobin), tại gan (tổng hợp, bài tiết bilirubin), sau gan (bài tiết mật, tắc mật ngoài gan)\n- Triệu chứng đặc hiệu nhưng kém nhạy của tắc mật? :: Phân bạc màu (thiếu stercobilin khi mật không xuống ruột)\n- Vì sao túi mật to chỉ là dấu gợi ý? :: Còn gặp trong viêm túi mật, ung thư; tắc phía trên ống túi mật (u ngã ba đường mật) thì không to\n- Vàng da trước gan hay gặp ở ai, kèm gì? :: Khoảng 10–30 tuổi, tán huyết mạn do bất thường hemoglobin, gan to lách to, thiếu máu mạn, tiền căn huyết học\n- Bilirubin trong vàng da sau gan? :: Trực tiếp ưu thế\n- Nước tiểu vàng da trước gan? :: Bilirubin âm tính, urobilinogen tăng cao\n- Dấu hiệu ALP gợi ý tắc mật? :: Tăng 3–10 lần bình thường; ALP bình thường thì ít nghĩ tắc mật\n- Phương tiện hình ảnh đầu tay trong tắc mật ngoài gan? :: Siêu âm\n- Phương tiện không xâm lấn nhạy và đặc hiệu nhất? :: MRI (MRCP), có thể 90–100%\n- Tam chứng Charcot gồm gì, giá trị? :: Đau hạ sườn phải, sốt, vàng da; nhạy khoảng 26,4%, đặc hiệu 95,6%\n- Phân biệt diễn tiến vàng da do sỏi và do u? :: Sỏi: cấp, kèm viêm đường mật; u: chậm, tăng dần, thường không đau, không sốt, sụt cân\n- Ung thư tế bào gan vàng da vì sao? :: Thường do xơ gan đi kèm, hiếm do u chèn ép"}, {"kind": "foundation", "disease": "", "short": "Xuất huyết tiêu hóa", "group": "", "section": 3, "order": 5, "khung": [], "id": "xuat-huyet-tieu-hoa", "title": "Tiếp cận xuất huyết tiêu hóa", "layer": "trieuchung", "module": "ngoai-tong-quat", "tags": ["xuất huyết tiêu hóa", "chảy máu tiêu hóa trên", "chảy máu tiêu hóa dưới", "ói máu", "phân đen", "tiêu ra máu", "vỡ giãn tĩnh mạch thực quản", "loét dạ dày tá tràng", "Forrest", "Rockall"], "source": "TCBN tr.1, 24, 48, 88–91; BHNgTH tr.71, 198, 234, 248, 264, 462; Notion", "body": "> [!key] Việc đầu tiên: có xuất huyết thật không, nguồn trên hay dưới góc Treitz, mất bao nhiêu máu, rồi hồi sức trước khi tìm nguyên nhân\n> - Xuất huyết tiêu hóa (XHTH) **trên** là chảy máu từ nguồn **phía trên góc Treitz** (góc tá–hỗng tràng); **dưới** là nguồn phía dưới góc này. Ranh giới này dùng riêng cho XHTH {{TCBN tr.1}}\n> - XHTH trên gặp nhiều gấp khoảng 4 lần XHTH dưới và là nguyên nhân chính gây biến chứng, tử vong {{Notion}}\n> - Hai nguyên nhân hàng đầu của XHTH trên: **loét dạ dày tá tràng** và **vỡ giãn tĩnh mạch thực quản** {{Notion}}\n> - Mức độ nặng đánh giá bằng **tri giác, mạch, huyết áp, nhịp thở, nước tiểu**, KHÔNG dựa vào Hct lúc đầu {{Notion}}\n> - Có sốc thì **hồi sức trước, nội soi cấp cứu sau**; nội soi vừa chẩn đoán vừa cầm máu. Mổ khi nội soi và điều trị nội khoa thất bại, chảy máu tái phát hoặc đang tiếp diễn, và khi nguyên nhân là ung thư {{Notion}}\n> - Liên quan khung 128 vấn đề: [STT 56](#/khung/56) (XHTH trên), [STT 57](#/khung/57) (XHTH dưới). Nguyên nhân ung thư: [Ung thư dạ dày](#/n/ngoai-ung-thu-da-day), [Ung thư đại tràng](#/n/ngoai-ung-thu-dai-trang)\n\n### 1. Định nghĩa và phân biệt trên – dưới\n- **Chảy máu tiêu hóa trên**: chảy máu trong lòng ống tiêu hóa do tổn thương ở miệng, thực quản, dạ dày hoặc tá tràng, tức phía trên góc Treitz {{Notion}}\n- Dịch tễ (giáo trình cũ): XHTH trên thường gặp ở nam gấp đôi nữ; tăng ở người >60 tuổi có nhiều bệnh kèm; tử vong XHTH trên từng báo cáo giảm từ 11% xuống 7% {{Notion}}\n- XHTH dưới chiếm khoảng 1–2% ca nhập viện cấp cứu, khoảng 15% chảy nhiều, khoảng 5% cần phẫu thuật; hay gặp ở người lớn tuổi {{Notion}}\n- Phân biệt trên – dưới dựa vào **tính chất nôn và phân**:\n\n| Triệu chứng | XHTH trên | XHTH dưới |\n|---|---|---|\n| **Ói ra máu** | Gần như chắc chắn | Hiếm |\n| **Tiêu phân đen** | Nhiều khả năng | Có thể |\n| **Tiêu ra máu** | Có thể | Nhiều khả năng |\n| **Máu ẩn trong phân** | Có thể | Có thể |\n\n- Ngoại lệ cần nhớ: chảy máu ồ ạt từ thực quản, dạ dày, tá tràng (từ khoảng 1000 mL) luôn gây **tiêu máu đỏ**, ít nhất lúc đầu, thường kèm sốc {{Notion}}\n- Phân đen cần máu lưu lại trong ruột **>8 giờ**: nguồn thường là thực quản, dạ dày, tá tràng, đôi khi hỗng tràng, hồi tràng, đại tràng lên. Mất khoảng 60 mL máu đã đủ cho một lần phân đen; mất cấp nhiều hơn thì phân đen kéo dài tới 3 ngày {{Notion}}\n- Màu máu nôn tùy HCl: nôn sớm máu đỏ; nôn muộn đỏ thẫm, nâu hoặc đen {{Notion}}\n\n### 2. Có xuất huyết tiêu hóa thật không\n- XHTH khi có một trong: **ói ra máu**, thăm trực tràng thấy **máu tươi hoặc máu bầm**, **phân đen** hôi tanh sệt như bã cà phê, xét nghiệm **máu ẩn trong phân** dương tính {{Notion}}\n- Phân biệt với: chảy máu cam hoặc vùng hàm mặt (nuốt rồi nôn ra), ăn tiết canh; **ho ra máu** (máu đỏ tươi có bọt, không lẫn thức ăn, pH kiềm) {{Notion}}\n- Phân đen thật phải phân biệt với phân đen do dùng sắt, bismuth, than, thực phẩm, hoặc phân đen cứng do táo bón {{TCBN tr.88–89; Notion}}\n- Sốc mất máu sớm có thể **chưa thấy máu ra đường tiêu hóa**: dễ lầm với chảy máu ổ bụng như vỡ thai ngoài tử cung, vỡ phình động mạch chủ bụng. Hỏi bệnh sử và nội soi giúp xác định {{Notion}}\n\n> [!red] Dấu hiệu cần xử trí ngay\n> - **Sốc mất máu** (mạch nhanh, huyết áp tụt, thở nhanh, ít nước tiểu, lơ mơ hoặc vật vã); mất ≥40% thể tích máu là sốc {{Notion}}\n> - **Tilt test dương** (đứng mạch tăng >20 lần/phút, huyết áp tối đa giảm >10 mmHg): đã mất ít nhất 20% thể tích máu {{Notion}}\n> - Nôn hoặc tiêu **nhiều máu đỏ lẫn máu cục**: chảy máu dữ dội, cần can thiệp ngay không trì hoãn {{Notion}}\n> - Bệnh cảnh xơ gan hoặc tăng áp cửa kèm ói máu đỏ tươi: nghĩ vỡ giãn tĩnh mạch thực quản, tử vong cao {{Notion}}\n\n### 3. Đánh giá mức độ mất máu\n| Chỉ số | Độ 1 | Độ 2 | Độ 3 | Độ 4 |\n|---|---|---|---|---|\n| Máu mất (mL) | <750 | 750–1500 | 1500–2000 | >2000 |\n| % thể tích máu | <15% | 15–30% | 30–40% | >40% |\n| Mạch (lần/phút) | <100 | >100 | >120 | >140 |\n| Huyết áp | Không đổi | Không đổi | Giảm | Giảm |\n| Nhịp thở (lần/phút) | 14–20 | 20–30 | 30–40 | >40 |\n| Nước tiểu (mL/giờ) | >30 | 20–30 | 5–15 | <5 |\n| Tri giác | Lo lắng ít | Lo lắng vừa | Kích thích, vật vã | Lơ mơ, hôn mê |\n{{Notion}} (phân độ mất máu cấp của Hội Ngoại khoa Hoa Kỳ)\n\n- **Không** đánh giá độ nặng bằng Hct: Hct chưa giảm ngay vì phải chờ dịch gian bào vào lòng mạch (có thể tới 24 giờ); ngược lại chảy rỉ rả mạn thì Hct rất thấp dù mạch, huyết áp bình thường (hồng cầu nhỏ nhược sắc). Dù vậy vẫn làm công thức máu cho mọi bệnh nhân để theo dõi {{Notion}}\n- Mất <500 mL ít triệu chứng toàn thân {{Notion}}\n- Xét nghiệm thêm: BUN, creatinin; khí máu động mạch nếu nặng; đông máu và chức năng gan {{Notion}}\n\n### 4. Hỏi bệnh và khám\n- **Hỏi**: tính chất ói, tính chất phân, hoàn cảnh khởi phát; đợt chảy máu trước; tiền căn loét và đau thượng vị; bệnh gan, giãn tĩnh mạch thực quản; thuốc **NSAID, aspirin, kháng đông**; nôn lẫn thức ăn, mật hoặc rượu trước khi chảy máu {{TCBN tr.24, 48; Notion}}\n- **Khám**: tri giác, sinh hiệu, nước tiểu; dấu suy tế bào gan (vàng da, sao mạch, lòng bàn tay son, báng bụng) và tăng áp cửa (tuần hoàn bàng hệ, lách to, trĩ) gợi ý xơ gan; đau thượng vị khi ấn {{Notion}}\n- **Thăm trực tràng bắt buộc** để xác định tính chất phân, có thể thấy ung thư hậu môn, trực tràng, trĩ. Thấy bệnh lành tính hậu môn trực tràng vẫn chưa loại trừ nguồn chảy máu phía trên {{Notion}}\n- Tại giường: **thăm trực tràng** và **đặt thông mũi–dạ dày** xem máu ứ đọng, theo dõi diễn tiến chảy máu {{Notion}}\n\n### 5. Hồi sức ban đầu\n1. **ABC**, đánh giá nhanh mức độ sốc {{Notion}}\n2. Chích **catheter hoặc kim lớn** vào tĩnh mạch ngoại biên; lấy máu làm Hct, nhóm máu, chức năng gan {{Notion}}\n3. **Truyền dịch muối đẳng trương**; truyền máu khi cần, đánh giá lại bằng mạch, huyết áp, nước tiểu {{Notion}}\n4. Chỉnh rối loạn đông máu nếu có (tiểu cầu, PT, aPTT) {{Notion}}\n5. Nhập viện cơ sở chuyên khoa; ổn định huyết động rồi **nội soi** {{Notion}}\n\n### 6. Nguyên nhân XHTH trên\n| Nguyên nhân | Tỷ lệ (giáo trình cũ) | Gợi ý lâm sàng |\n|---|---|---|\n| **Loét dạ dày tá tràng** | 35–62% | Tiền căn loét, NSAID, đau thượng vị; ói máu lẫn thức ăn hoặc phân đen; không có dấu xơ gan {{Notion}} |\n| **Vỡ giãn tĩnh mạch thực quản** | 4–31% | Xơ gan, tăng áp cửa; nôn máu đỏ tươi nhiều {{Notion}} |\n| **Mallory–Weiss** | 4–13% (bài khác ghi 15%) {{Notion}} | Nôn ói nhiều rồi mới ra máu đỏ tươi; rách niêm mạc tâm vị; nôn nhiều kéo dài do hẹp môn vị có thể gây {{BHNgTH tr.71}} |\n| Viêm trợt dạ dày tá tràng | 3–11% | Stress, NSAID {{Notion}} |\n| Viêm trợt thực quản | 2–8% | {{Notion}} |\n| **U ác tính** | 1–4% | Chảy rỉ rả, thiếu máu; ung thư dạ dày chảy máu cấp chỉ khoảng 5%, nhưng mất máu mạn, thiếu máu thiếu sắt và máu ẩn trong phân thường gặp {{Notion; BHNgTH tr.198}} |\n| Không rõ nguyên nhân | 7–25% | {{Notion}} |\n\n- **Loét**: hay gặp loét tá tràng hơn loét dạ dày nhưng tần suất chảy máu tương đương; khoảng 80% tự cầm; ổ loét >2 cm nguy cơ tái phát cao nhất; mạch chảy >1,5 mm dễ thất bại nội soi cầm máu {{Notion}}\n- **Tái phát hoặc tử vong cao** khi: >60 tuổi, sốc lúc nhập viện, rối loạn đông máu, chảy máu từ động mạch, bệnh tim mạch kèm {{Notion}}\n- **Vỡ giãn tĩnh mạch thực quản**: chênh áp cửa–chủ >10 mmHg gây giãn, >12 mmHg có thể vỡ; khoảng 90% xơ gan có giãn tĩnh mạch thực quản, 25–30% trong số này chảy máu; tử vong mỗi đợt khoảng 25%, tái phát khoảng 70% {{Notion}}\n- **Mallory–Weiss**: vết rách dọc, thường dọc bờ cong nhỏ sát tâm vị sau nôn, ho, rặn dữ dội; có khi chảy rất nhiều nhưng sau khi cầm máu tiên lượng thường tốt, ít khi phải mổ {{Notion; BHNgTH tr.71}}\n- **Viêm dạ dày do stress** (sốc, đa chấn thương, suy hô hấp, nhiễm trùng huyết, bỏng rộng): loét nông đa ổ, thường nhẹ; điều trị chính là xử trí bệnh nặng nền {{Notion}}\n- **NSAID** hằng ngày làm tăng nguy cơ loét dạ dày khoảng 40 lần và loét tá tràng khoảng 8 lần {{Notion}}\n- Hiếm: **Dieulafoy** (mạch lớn dưới niêm mạc, thường gần tâm vị), rò động mạch chủ–ruột (sau mổ ghép mạch), chảy máu đường mật (sỏi, giun đũa) {{Notion}}\n\n### 7. Nguyên nhân XHTH dưới và tiêu ra máu\n| Nguyên nhân | Tỷ lệ (giáo trình cũ) | Đặc điểm |\n|---|---|---|\n| **Bệnh túi thừa** | 60% | Thường gặp nhất; chảy nhiều, không do viêm túi thừa; nguy cơ: ít chất xơ, táo bón, lớn tuổi, NSAID, aspirin {{Notion}} |\n| Bệnh viêm ruột | 13% | Crohn, viêm loét đại tràng hiếm chảy nhiều {{Notion}} |\n| Bệnh lành tính hậu môn trực tràng | 11% | Trĩ, nứt, rò: chảy từng đợt, lượng ít {{Notion}} |\n| **U tân sinh** | 9% | Polyp, ung thư; chảy rỉ rả {{Notion}} |\n| Rối loạn đông máu | 4% | {{Notion}} |\n| Dị sản mạch máu | 3% (có nguồn ghi 20–30%) | Ở đại tràng, người lớn tuổi; khoảng 80% tự cầm nhưng hay tái phát {{Notion}} |\n\n- **Trĩ** là nguyên nhân thường gặp nhất ở người <50 tuổi, lượng ít; máu đỏ tươi không lẫn phân, nhỏ giọt hoặc dính giấy, hoặc chảy thành tia lúc đi tiêu {{Notion; BHNgTH tr.462}}\n- **Ung thư đại trực tràng**: chảy máu tiêu hóa dưới gặp ở 6–17% bệnh nhân ung thư đại tràng, chảy nặng rất hiếm, điều trị nội khoa rồi mổ theo chương trình; ung thư trực tràng có chảy máu là triệu chứng đầu thường gặp nhất (60%), rỉ rả, máu bầm lẫn phân, kèm thay đổi thói quen đi cầu (43%), phân nhỏ dẹt, mót rặn {{BHNgTH tr.234, 248}}\n- Ung thư đại tràng chiếm khoảng 10% nguyên nhân chảy máu trực tràng ở người >50 tuổi {{Notion}}\n- Ở **tiêu ra máu đỏ lượng ít sau đại tiện** (bệnh hậu môn trực tràng) nguyên nhân sau khi khảo sát đủ: 50% bệnh lành tính hậu môn trực tràng, 20–40% polyp, 5–15% viêm ruột, 2–7% ung thư trực tràng, 2–5% tổn thương mạch; 20% không tìm ra nguyên nhân {{TCBN tr.90}}\n- Nhận định theo vị trí máu: **lẫn trong phân** (từ trên đại tràng chậu hông); **dính mặt phân** (dưới trực tràng và hậu môn); **dính giấy hoặc nhỏ bồn cầu** (da hậu môn, ống hậu môn) {{TCBN tr.90}}\n- Triệu chứng toàn thân (sốt, sụt cân, mồ hôi đêm), thay đổi thói quen đại tiện, phân nhỏ dẹt gợi ý ác tính hoặc viêm mạn {{TCBN tr.91}}\n- Bắt buộc **thăm trực tràng bằng ngón tay**. 5 bước tiếp cận tiêu ra máu: đánh giá huyết động; xác định bản chất máu; có đau bụng hoặc đau vùng chậu không; khám hậu môn trực tràng; cân nhắc XHTH ẩn {{TCBN tr.88, 91}}\n\n### 8. Các hình thức XHTH\n- **Có nguyên nhân cụ thể**: ói máu, phân đen hoặc tiêu ra máu và đã xác định nguyên nhân {{Notion}}\n- **Tiềm ẩn**: không triệu chứng chảy máu, nhưng thiếu máu thiếu sắt hoặc máu ẩn trong phân dương tính {{Notion}}\n- **Không rõ nguyên nhân**: có triệu chứng hoặc máu ẩn dương tính nhưng không tìm ra nguyên nhân {{Notion}}\n\n### 9. Nội soi và phương tiện chẩn đoán\n- **Nội soi là phương tiện đầu tay**, vừa chẩn đoán vừa cầm máu. Có sốc: hồi sức tích cực rồi nội soi cấp cứu; không sốc: có thể nội soi theo chương trình {{Notion}}\n- Nội soi thực quản–dạ dày–tá tràng nên làm sớm, **trong 12 giờ đầu**, khi đã điều trị sốc, có đường truyền an toàn, tại phòng soi có phương tiện hồi sức {{Notion}}\n- XHTH dưới: **nội soi đại tràng** làm trước; trĩ, nứt, polyp đại trực tràng thấy được qua nội soi hậu môn trực tràng; người >50 tuổi nên soi đại tràng, có tiền sử gia đình ung thư đại trực tràng hoặc thiếu máu, sụt cân thì bắt buộc soi đại tràng {{TCBN tr.91}}\n- Nội soi **không thấy nguyên nhân**: nếu huyết động ổn định soi lần 2 trong 24 giờ, rồi chụp mạch hoặc CTA; nếu không ổn định: tiếp tục hồi sức, **chụp mạch cấp cứu** có thể kèm thuyên tắc mạch (TAE) {{Notion}}\n- **Nguồn ruột non** (máu từ van hồi manh tràng hoặc không thấy ở trên và dưới): huyết động không ổn định thì chụp mạch cấp cứu; ổn định thì nội soi viên nang hoặc CTA (có tắc, bán tắc ruột thì CTA, không dùng viên nang) {{Notion}}\n\n| Phương tiện | Điểm mạnh | Hạn chế |\n|---|---|---|\n| **Chụp mạch (angiography)** | Thấy vị trí chảy máu (tốc độ khoảng 0,5–1 mL/phút), kết hợp TAE; hợp với huyết động không ổn định | Có thể bỏ sót khi chảy từng đợt; biến chứng khoảng 10% {{Notion}} |\n| **CT mạch máu (CTA)** | Không xâm lấn; thấy khi chảy khoảng 0,3 mL/phút | Chỉ thấy khi đang chảy; thuốc cản quang nặng thêm suy thận {{Notion}} |\n| **Nội soi viên nang** | Không xâm lấn, dùng được khi suy thận | Không sinh thiết, không cầm máu; chống chỉ định khi hẹp, tắc ruột {{Notion}} |\n| **Nội soi ruột non** | Sinh thiết, cầm máu | Xâm lấn; có thể gây tắc, thủng ruột {{Notion}} |\n\n- **Phân độ giãn tĩnh mạch thực quản (nội soi)**: độ I búi nhỏ <5 mm, mất khi bơm hơi; độ II 5–9 mm, dưới 1/3 lòng; độ III >9 mm, trên 1/3 lòng. Giãn tĩnh mạch dạ dày theo Sarin: GOV-1, GOV-2, IGV-1, IGV-2 {{Notion}}\n- **Phân loại Forrest** (loét dạ dày tá tràng) và nguy cơ chảy máu tái phát: IA máu chảy thành tia 85–100%; IB máu rịn 10–27%; IIA ngòi mạch 50%; IIB cục máu đông 30–35%; IIC phủ hematin <8%; III đáy sạch <3% {{Notion}}\n\n### 10. Tiên lượng\n- **Thang Rockall** (tuổi, sốc, bệnh kèm, chẩn đoán, dấu hiệu chảy máu gần đây): 0–2 điểm nguy cơ thấp, 3–5 trung bình, >5 cao {{Notion}}\n- Tử vong tăng theo điểm: 3 điểm 2,9%; 5 điểm 10,8%; 7 điểm 27%; ≥8 điểm 41,1% {{Notion}}\n- Yếu tố xấu của loét chảy máu: chảy nhanh và nhiều lúc đầu, tiếp diễn hoặc tái phát khi nằm viện, >60 tuổi, bệnh kèm {{Notion}}\n- Tiên lượng vỡ giãn tĩnh mạch thực quản: **Child–Pugh**, kích thước búi giãn, **vạch đỏ** khi nội soi {{Notion}}\n- XHTH **đã ổn**: mạch huyết áp ổn, da niêm hồng, nước tiểu tăng, phân vàng, Hct tăng sau truyền. **Còn diễn tiến**: sau vài giờ chưa cải thiện, sonde dạ dày còn máu đỏ, Hct không tăng. **Tái phát** thì đánh giá lại đông máu rồi nội soi lại {{Notion}}\n\n### 11. Điều trị theo nguyên nhân và khi nào mổ\n- **Loét chảy máu**: nội soi cầm máu (đốt điện, laser, kẹp clip, chích adrenaline, polidocanol hoặc cồn tuyệt đối, keo) cho ổ loét có dấu vết chảy; đang chảy ồ ạt thì khó, thường phải mổ cấp cứu {{Notion}}\n- **Vỡ giãn tĩnh mạch thực quản**: thuốc co mạch (vasopressin, octreotide), chèn bóng Sengstaken–Blakemore hoặc Minnesota, **nội soi chích xơ hoặc thắt búi** (chích xơ được xem là lựa chọn), TIPSS; mổ khi thất bại hoặc không có chỉ định (cầu nối cửa–chủ, nối lách–thận xa, Sugiura) {{Notion}}\n- **Mallory–Weiss**: nội soi đốt điện, chích epinephrine, kẹp clip, ít khi phải mổ {{Notion}}\n- **Dieulafoy**: nội soi, làm tắc mạch bằng Gelfoam, hoặc cắt dạ dày hình chêm {{Notion}}\n- **Ung thư thực quản, dạ dày**: chảy rỉ rả, mổ theo chương trình, hiếm mổ cấp cứu. **Ung thư đại trực tràng chảy máu**: điều trị nội khoa rồi phẫu thuật theo kế hoạch {{Notion; BHNgTH tr.234}}\n- **Chỉ định mổ trong loét chảy máu**: nội soi thất bại hoặc không có chỉ định; chảy máu tạm ngừng rồi chảy lại; đang tiếp diễn; nặng cần truyền tới 1500 mL máu trong 24 giờ đầu; dữ dội cần can thiệp ngay (nôn hay tiêu nhiều máu đỏ lẫn cục) {{Notion}}\n- Phẫu thuật cho loét: khâu cầm máu ổ loét, mở rộng môn vị kèm cắt thần kinh X tại thân (Weinberg, cho người lớn tuổi), cắt 2/3 dạ dày xa, hoặc cắt thần kinh X kèm cắt hang vị {{Notion}}\n- Phòng tái phát loét: ức chế bơm proton và tiệt trừ *H. pylori* {{Notion}}\n\n### 12. Lưu đồ tiếp cận\n1. **Ổn định**: ABC, sinh hiệu, 2 đường truyền lớn, lấy máu Hct, nhóm máu, đông máu, chức năng gan; truyền dịch đẳng trương {{Notion}}\n2. **Xác nhận** có XHTH (ói máu, phân đen, máu qua hậu môn, máu ẩn), loại trừ ho ra máu, chảy máu cam, ăn tiết canh {{Notion}}\n3. **Đánh giá mức độ** theo bảng phân độ và Tilt test; không dựa vào Hct {{Notion}}\n4. **Xác định trên hay dưới** qua triệu chứng, thăm trực tràng, đặt sonde dạ dày {{Notion}}\n5. **Hướng nguyên nhân**: xơ gan, tăng áp cửa → giãn tĩnh mạch; tiền căn loét, NSAID → loét; ói nhiều rồi ra máu → Mallory–Weiss; >50 tuổi, phân nhỏ dẹt, sụt cân → ung thư {{Notion}}\n6. **Nội soi** (trong 12 giờ đầu khi XHTH trên) để chẩn đoán và cầm máu; không thấy thì soi lại hoặc chụp mạch, CTA {{Notion}}\n7. **Theo dõi** ổn, đang diễn tiến hay tái phát; thất bại nội soi hoặc chảy dữ dội thì **mổ** {{Notion}}\n\n### Điểm hay thi\n> [!warn]\n> - Phân định trên, dưới tại **góc Treitz** {{TCBN tr.1}}\n> - Nguyên nhân hàng đầu XHTH trên: **loét dạ dày tá tràng**; kế đó **vỡ giãn tĩnh mạch thực quản** {{Notion}}\n> - Hct lúc đầu có thể bình thường: **không** dùng Hct đánh giá độ nặng {{Notion}}\n> - Tilt test dương: mạch tăng >20 lần/phút, huyết áp giảm >10 mmHg, mất ≥20% thể tích máu {{Notion}}\n> - Có sốc: **hồi sức trước rồi mới nội soi** {{Notion}}\n> - Nội soi XHTH trên nên làm trong **12 giờ đầu** {{Notion}}\n> - Ổ loét có **cục máu đông** là Forrest IIB; Forrest IA (chảy thành tia) tái phát 85–100% {{Notion}}\n> - Ung thư dạ dày hiếm gây chảy máu cấp (khoảng 5%), thường thiếu máu thiếu sắt mạn; ung thư đại trực tràng chảy rỉ rả {{BHNgTH tr.198, 234}}\n> - Khác biệt giữa các giáo trình: giáo trình cũ (Notion) ghi Mallory–Weiss 4–13% ở bài này và 15% ở bài khác; cả hai đều từ Notion, giáo trình mới không nêu số\n\n### Tự kiểm tra\n- XHTH trên khác dưới ở ranh giới nào? :: Góc Treitz (góc tá–hỗng tràng); trên là nguồn phía trên góc Treitz\n- Hai nguyên nhân thường gặp nhất của XHTH trên? :: Loét dạ dày tá tràng và vỡ giãn tĩnh mạch thực quản\n- Triệu chứng nào gần như chắc chắn là XHTH trên? :: Ói ra máu\n- Phân đen cần máu lưu trong ruột bao lâu? :: Trên 8 giờ\n- Tilt test dương tính khi nào, nghĩa là gì? :: Mạch tăng >20 lần/phút và huyết áp giảm >10 mmHg khi đứng; mất ít nhất 20% thể tích máu\n- Mất máu độ 3 theo Hội Ngoại khoa Hoa Kỳ? :: 1500–2000 mL, 30–40% thể tích, mạch >120, huyết áp giảm\n- Vì sao không dựa vào Hct đánh giá độ nặng ban đầu? :: Hct chưa giảm ngay vì dịch gian bào vào lòng mạch chậm (có thể tới 24 giờ)\n- Việc làm bắt buộc khi khám bệnh nhân XHTH? :: Thăm trực tràng bằng ngón tay\n- Nội soi XHTH trên khi nào? :: Sớm, trong 12 giờ đầu, sau khi điều trị sốc và có đường truyền an toàn\n- Forrest IA là gì và nguy cơ tái phát? :: Máu chảy thành tia; 85–100%\n- Khi nào mổ loét chảy máu? :: Nội soi thất bại hoặc không có chỉ định, chảy lại, đang tiếp diễn, cần truyền ~1500 mL trong 24 giờ, hoặc chảy dữ dội\n- Mallory–Weiss có bệnh cảnh gì? :: Nôn ói nhiều rồi ra máu đỏ tươi, rách niêm mạc tâm vị, thường cầm bằng nội soi\n- Nguyên nhân thường gặp nhất của XHTH dưới? :: Bệnh túi thừa (người trẻ <50 tuổi: trĩ, lượng ít)"}, {"kind": "disease", "disease": "buong-trung", "short": "Ung thư buồng trứng", "group": "", "section": 0, "order": 6, "khung": [53, 54, 55, 87, 91, 99], "id": "ung-thu-buong-trung", "title": "Ung thư buồng trứng", "layer": "benh", "module": "ung-buou", "tags": ["ung bướu", "buồng trứng", "khối vùng chậu", "CA-125", "HE4", "ROMA", "FIGO 2018", "BRCA", "PARP", "bevacizumab", "tế bào mầm", "báng bụng"], "source": "Y5 tr.25–38; SY5 tr.190, 194–201, 209–210; QĐ1514 Bài 43 (tr. PDF 348–358); ĐC Y5 tr.6; 128VĐ mục 63, 64, 96; QĐ 22 STT 53, 54, 55, 87, 91, 99 (trọng số tr.8)", "body": "> [!key] Ung thư buồng trứng (UTBT) trong một nhìn\n> - Khó phát hiện sớm: đa số được chẩn đoán muộn, ==59%== ở giai đoạn tiến xa/di căn xa {{Y5 tr.30}}\n> - Ung thư biểu mô chiếm phần lớn UTBT (Y5 ==85–90%==; QĐ1514 80–90%, xem mục 9) {{Y5 tr.27}} {{QĐ1514 tr.PDF 348}}\n> - Chẩn đoán xác định = **mô bệnh học** (sinh thiết nội soi ổ bụng hoặc phẫu thuật) {{QĐ1514 tr.PDF 350}}; CA-125 **không dùng để tầm soát** {{Y5 tr.34}} (QĐ1514 tr.PDF 348 liệt kê CA-125 trong sàng lọc, lệch nguồn, xem mục 9) {{QĐ1514 tr.PDF 348}}\n> - Điều trị: phẫu thuật (giai đoạn I: cắt tử cung + 2 phần phụ + mạc nối; II–IV: giảm tối ưu, còn lại nhỏ hơn 1 cm) + hóa trị platinum–taxane; PARP khi có BRCA {{Y5 tr.35}} {{Y5 tr.36}} {{QĐ1514 tr.PDF 355}}\n> - Sống 5 năm: giai đoạn I ==90–100%==, IV ==0–15%== {{Y5 tr.38}}\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Nguy cơ chính: **không sinh con / ít con**, mãn kinh muộn (sau 52 tuổi), **BRCA1/2** và hội chứng Lynch II {{Y5 tr.26}} {{Y5 tr.27}}\n> - Gieo rắc trong xoang bụng là đường lan sớm và hay gặp nhất; biểu hiện muộn: báng bụng, khối ổ bụng {{Y5 tr.30}} {{Y5 tr.32}}\n\n### Định nghĩa & dịch tễ\n- UTBT là ung thư phụ khoa hay gặp; tuổi chẩn đoán trung bình **60–65** (Y5) hoặc **63** (QĐ1514); có thể gặp cả ở trẻ em {{Y5 tr.25}} {{QĐ1514 tr.PDF 348}}\n- Nguy cơ tăng 2% mỗi năm ở phụ nữ dưới 50 tuổi và 11% mỗi năm ở từ 50 tuổi trở lên {{Y5 tr.25}}\n- Hoa Kỳ: chiếm gần 30% ung thư đường sinh dục nữ, là ung thư gây tử vong hàng đầu trong nhóm này {{Y5 tr.25}}\n\n| Nguồn | Thế giới | Việt Nam | Ghi chú |\n|---|---|---|---|\n| Y5 (GLOBOCAN 2018) | 295.414 ca mới; chuẩn tuổi ==6,1/100.000==; 184.799 tử vong (tử suất 3,4/100.000) {{Y5 tr.25}} | ~1.500 ca mới, 856 tử vong; chuẩn tuổi ==2,7/100.000==, tử suất 1,5; hạng 12 ở nữ {{Y5 tr.25}} | TP.HCM 2014: chuẩn tuổi 6,4/100.000, hạng 6 ở nữ (4,8%) {{Y5 tr.25}} |\n| QĐ1514 (GLOBOCAN 2018) | chuẩn tuổi ==6,6/100.000==; khoảng 185.000 tử vong/năm {{QĐ1514 tr.PDF 348}} | ~1.500 ca mới, ~850 tử vong; chuẩn tuổi 2,7/100.000 {{QĐ1514 tr.PDF 348}} | **khác Y5 ở tỷ lệ thế giới**, xem mục 9 |\n| SY5 (GLOBOCAN 2022) | chuẩn tuổi mắc ==6,7==; tử vong ==4,0== {{SY5 tr.209}} | chuẩn tuổi mắc ==2,5==; tử vong ==1,6== {{SY5 tr.210}} | số liệu 2022, mới nhất trong tài liệu |\n\n> [!warn] Lệch số liệu dịch tễ (ghi cả hai)\n> - Chuẩn tuổi thế giới 2018: Y5 ghi 6,1, QĐ1514 ghi 6,6 {{Y5 tr.25}} {{QĐ1514 tr.PDF 348}}\n> - Tỷ lệ ung thư biểu mô: Y5 85–90%, QĐ1514 80–90% {{Y5 tr.27}} {{QĐ1514 tr.PDF 348}}\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Nội tiết – sinh sản\n- Không sinh con là yếu tố nguy cơ chính; **vô sinh và thuốc điều trị vô sinh không phải** yếu tố nguy cơ {{Y5 tr.26}}\n- Mỗi lần mang thai giảm 8% nguy cơ (nghiên cứu EPIC) {{Y5 tr.26}}\n- Mãn kinh muộn (sau 52 tuổi) làm tăng nguy cơ; có kinh sớm (<12 tuổi) tăng nguy cơ ở một số nghiên cứu, không thấy ở số khác {{Y5 tr.26}}\n- Thuốc tránh thai uống và sinh đẻ nhiều **giảm** nguy cơ {{Y5 tr.26}}\n- Số lần rụng trứng tăng nguy cơ; có thai trước 25 tuổi và mãn kinh sớm liên quan giảm tỷ lệ mắc {{QĐ1514 tr.PDF 348}}\n- Liệu pháp nội tiết sau mãn kinh (estrogen–progestin) **không** làm tăng nguy cơ (WHI) {{Y5 tr.26}} {{QĐ1514 tr.PDF 349}}\n- Hội chứng buồng trứng đa nang: vai trò chưa rõ {{Y5 tr.26}}\n@@tab Di truyền – gia đình\n- Yếu tố di truyền–gia đình liên quan khoảng **5–10%** UTBT (Y5) {{Y5 tr.26}}\n- **HBOC** (BRCA1/2) chiếm **75%** UTBT di truyền; nguy cơ trọn đời: BRCA1 ==40–50%==, BRCA2 ==10–20%== {{Y5 tr.27}}\n- Hội chứng đặc hiệu vị trí (10–15% UTBT di truyền): nguy cơ trọn đời khoảng 5%, gấp 3 lần dân số chung (1,6%) {{Y5 tr.26}}\n- **Lynch II** (10–15%): khởi phát sớm (43–50 tuổi so với 60); đột biến gen sửa chữa sai ghép (MMR) nguy cơ trọn đời ==9–12%== {{Y5 tr.27}}\n- QĐ1514 ghi có khoảng 7% UTBT mang tính gia đình; mẹ hoặc chị em gái mắc thì nguy cơ tăng \"gấp 20 lần\" (chép nguyên văn) {{QĐ1514 tr.PDF 348}}\n- Gen cần xét nghiệm: BRCA1/2, MLH1, MSH2, MSH6, PMS2, EPCAM, MUTYH, TP53, STK11, PALB2 {{QĐ1514 tr.PDF 350}}\n@@tab Lối sống – môi trường\n- Hút thuốc lá làm tăng loại tiết dịch nhầy (RR 2,1; 95% CI 1,7–2,7); các loại khác không liên quan {{Y5 tr.27}}\n- Béo phì (BMI ≥30): hai phân tích cho OR 1,3 và 1,1, các phân tích khác không thấy khác biệt có ý nghĩa {{Y5 tr.27}}\n- Lạc nội mạc tử cung làm tăng nguy cơ loại tế bào sáng (OR 3,05), dạng nội mạc (OR 2,04), thanh dịch độ thấp (OR 2,11); chuyển ác tính ~1% (chưa mãn kinh) và 1–2,5% (mãn kinh) {{Y5 tr.26}}\n- Chế độ ăn giàu vitamin A và chất xơ: một số nghiên cứu cho thấy giảm nguy cơ {{QĐ1514 tr.PDF 348}}\n- Amiăng (asbestos) được liệt kê ở mục buồng trứng trong bảng tác nhân môi trường–nghề nghiệp {{SY5 tr.190}}\n@@end\n\n### Sinh bệnh học & sinh học phân tử\n- Cơ chế phân tử sinh ung thư: **tài liệu không nêu chi tiết**; trọng tâm là yếu tố di truyền và nội tiết {{QĐ1514 tr.PDF 349}}\n- Đột biến BRCA1 (NST 17) và TP53 làm tăng nguy cơ {{QĐ1514 tr.PDF 349}}\n- Hội chứng Lynch II liên quan gen sửa chữa bắt cặp sai (MMR) {{Y5 tr.27}}\n\n### Giải phẫu bệnh – phân loại\n@@tabs\n@@tab Phân loại WHO 2014\n| Nguồn gốc mô học | Tỷ lệ | Ghi chú |\n|---|---|---|\n| **Biểu mô** | 65% | nhóm lớn nhất; ung thư biểu mô là 85–90% UTBT ác tính {{Y5 tr.28}} {{Y5 tr.27}} |\n| **Tế bào mầm** | 15% | ung thư tế bào mầm 5–10% UTBT (QĐ1514: mẫu số ung thư ác tính) {{QĐ1514 tr.PDF 348}}; 15% của Y5 tính trên toàn bộ bướu buồng trứng {{Y5 tr.28}} |\n| **Dây sinh dục – mô đệm** | 10% | {{Y5 tr.28}} |\n| **Di căn** | 5% | {{Y5 tr.28}} |\n@@tab Biểu mô (thường gặp nhất)\n- Carcinôm tuyến tiết dịch trong **độ mô học cao** ==70–80%== {{Y5 tr.28}}\n- Carcinôm tuyến dạng nội mạc 10%; tế bào sáng 10%; tiết nhầy 3%; tiết dịch trong độ thấp <5% {{Y5 tr.28}} {{Y5 tr.29}}\n- Bướu ác tính thấp (giáp biên) chiếm 14–15% ung thư biểu mô, có đặc điểm cả lành lẫn ác {{Y5 tr.27}}\n@@tab Tế bào mầm – mô đệm\n- Tế bào mầm: gặp ở phụ nữ dưới 20–30 tuổi, rất nhạy hóa chất, tiên lượng tốt {{QĐ1514 tr.PDF 348}}\n- Mô đệm–dây sinh dục: thường một bên, độ ác tính thấp, có thể tiết kích tố; người trẻ có thể bảo tồn {{Y5 tr.37}}\n@@end\n\n### Diễn tiến tự nhiên – lan tràn\n- Chẩn đoán muộn: ==59%== tiến xa/di căn xa; ==20%== có di căn hạch; ==15%== khu trú tại chỗ–vùng {{Y5 tr.30}}\n- Bốn đường lan: (1) **trực tiếp** qua vỏ bao (cùng đồ, đại tràng sigma, tử cung, vách chậu, niệu quản); (2) **hạch sau phúc mạc** cạnh động mạch chủ; (3) **theo máu** (phổi, gan, xương, não); (4) **gieo rắc trong ổ bụng**, sớm nhất và hay gặp nhất {{Y5 tr.30}}\n- Gieo rắc theo dịch phúc mạc đến cùng đồ sau, rãnh đại tràng, bao gan–lách, mạc nối lớn; mạc nối dày co rút có thể tiết nhiều dịch báng {{Y5 tr.30}}\n- Liên quan báng bụng: ung thư buồng trứng, vòi trứng, phúc mạc nguyên phát là một nguyên nhân gây báng bụng {{128VĐ mục 63}}\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Giai đoạn sớm gần như không có triệu chứng; triệu chứng mơ hồ (khó tiêu, mệt, chán ăn) dễ nhầm bệnh nội hoặc phụ khoa khác {{QĐ1514 tr.PDF 349}}\n> - Triệu chứng thường xuất hiện **muộn**: đau hạ vị âm ỉ, bụng chướng, khối ổ bụng, báng bụng, chảy máu âm đạo {{Y5 tr.32}} {{QĐ1514 tr.PDF 349}}\n> - Chèn ép ruột–tiết niệu do khối u; di căn phổi–màng phổi {{QĐ1514 tr.PDF 349}} {{Y5 tr.32}}\n\n### Triệu chứng cơ năng\n- Sớm: khó tiêu, mệt mỏi, chán ăn {{QĐ1514 tr.PDF 349}}\n- Đau vùng bụng dưới mơ hồ, âm ỉ; bướu ổ bụng có hay không kèm báng bụng {{Y5 tr.32}}\n- Chèn ép: cảm giác nặng hạ vị, khối vùng hạ vị, tắc đại tràng sigma–trực tràng; triệu chứng ruột, tiết niệu {{Y5 tr.32}} {{QĐ1514 tr.PDF 349}}\n- Gieo rắc trong ổ bụng: đau bụng âm ỉ, bụng căng to do báng bụng {{Y5 tr.32}}\n- Nội tiết (bướu mô đệm–dây sinh dục): xuất huyết âm đạo bất thường, nam hóa {{Y5 tr.32}}; chảy máu âm đạo {{QĐ1514 tr.PDF 349}}\n\n### Khám thực thể & di căn\n- Khám bụng: gan, lách, báng bụng và mọi khối bất thường {{Y5 tr.32}}\n- Khám phụ khoa (mỏ vịt và bằng tay): sờ khối vùng chậu; đánh giá kích thước, vị trí, mật độ, di động, xâm lấn vùng chậu {{Y5 tr.32}}\n- Khám hạch ngoại biên để đánh giá di căn hạch; khám toàn thân tìm di căn xa {{Y5 tr.32}}\n- Di căn xa: phổi, màng phổi; tràn dịch màng phổi có tế bào học dương tính là giai đoạn IVA {{Y5 tr.31}}\n\n> [!red] Dấu hiệu báo động\n> - Khối vùng chậu hoặc ổ bụng **kèm báng bụng** ở phụ nữ quanh hoặc sau mãn kinh {{Y5 tr.25}} {{Y5 tr.32}}\n> - **Xuất huyết âm đạo bất thường** hoặc nam hóa (bướu nội tiết) {{Y5 tr.32}}\n> - Đau bụng dưới mơ hồ kéo dài kèm bụng chướng, triệu chứng ruột–tiết niệu {{QĐ1514 tr.PDF 349}}\n> - Tràn dịch màng phổi hoặc di căn phổi–gan {{Y5 tr.32}} {{QĐ1514 tr.PDF 351}}\n\n### Tiếp cận các triệu chứng (khung 128 vấn đề)\n| STT | Vấn đề | Nguyên nhân cần nghĩ tới |\n|---|---|---|\n| [91](#/khung/91) | **Khối vùng chậu** | ung thư buồng trứng; u nang và u xơ tử cung; áp xe vòi–buồng trứng; thuật toán IOTA/O-RADS được nêu để phân loại khối buồng trứng {{128VĐ mục 96}} {{QĐ1514 tr.PDF 350}} |\n| [54](#/khung/54) | **Khối ở bụng** | khối u phụ khoa (buồng trứng, tử cung); u ổ bụng; lymphoma, sarcoma ổ bụng {{128VĐ mục 64}} |\n| [53](#/khung/53) | **Báng bụng (cổ trướng)** | carcinôm ổ bụng do ung thư buồng trứng, vòi trứng, phúc mạc nguyên phát {{128VĐ mục 63}} |\n| [55](#/khung/55) | **Trướng bụng** | bụng chướng là triệu chứng muộn {{QĐ1514 tr.PDF 349}} |\n| [87](#/khung/87) | **Xuất huyết âm đạo bất thường** | rối loạn nội tiết do bướu mô đệm–dây sinh dục {{Y5 tr.32}} |\n| [99](#/khung/99) | **Sụt cân** | triệu chứng gợi ý tái phát khi theo dõi {{Y5 tr.37}} |\n\n### Thể lâm sàng liên quan\n@@fold Di căn từ đường tiêu hóa đến buồng trứng (Krukenberg)\n- Gặp khối buồng trứng: cần nội soi dạ dày và đại trực tràng thường quy để loại trừ u tiêu hóa di căn {{QĐ1514 tr.PDF 349}}\n- Chẩn đoán phân biệt: ung thư di căn buồng trứng phải đánh giá toàn diện trước khi điều trị {{QĐ1514 tr.PDF 350}}\n@@end\n\n## 5. Cận lâm sàng\n\n> [!key] Tóm tắt\n> - Siêu âm (đầu dò âm đạo) là **lựa chọn đầu tay**; CT/MRI đánh giá xâm lấn, hạch và di căn {{Y5 tr.32}} {{Y5 tr.33}}\n> - **Mô bệnh học là xét nghiệm quyết định**; sinh thiết qua nội soi ổ bụng hoặc phẫu thuật {{QĐ1514 tr.PDF 350}}\n> - CA-125 tăng ở ~80% UTBT biểu mô không tiết nhầy; dùng để **theo dõi**, không dùng tầm soát {{Y5 tr.34}}\n> - Phân giai đoạn: FIGO 2018 (Y5); QĐ1514 ghi AJCC/FIGO phiên bản 8 (2017) {{Y5 tr.30}} {{QĐ1514 tr.PDF 350}}\n\n### Chẩn đoán hình ảnh\n@@tabs\n@@tab Siêu âm\n- Siêu âm là lựa chọn đầu tay; siêu âm qua ngã âm đạo có ưu điểm hơn qua ngã bụng; độ nhạy ==80–100%==, độ đặc hiệu ==94–99%== {{Y5 tr.32}}\n- Gợi ý ác tính: nhiều nang–hốc, phần đặc, lớn trên 5 cm, nhiều chồi sùi hoặc vách trên 2–3 mm, khối hai bên, dịch ổ bụng, nốt phúc mạc hoặc mạc nối {{Y5 tr.33}}\n- Siêu âm còn gợi ý xâm lấn trực tràng, bàng quang, di căn gan, ứ nước thận do chèn ép niệu quản {{Y5 tr.33}}\n@@tab CT – MRI – PET\n- Dấu gợi ý ác tính trên CT: đường kính trên 4 cm, nhú bắt thuốc cao, vách dày trên 3 mm, phần nang–phần đặc, khối rắn chia thùy, mạch máu tương phản cao; **không có dấu hiệu nào đủ để chẩn đoán xác định** {{Y5 tr.33}}\n- CT/MRI bụng–chậu đánh giá xâm lấn quanh u, hạch sau phúc mạc, tình trạng ổ bụng {{Y5 tr.33}} {{QĐ1514 tr.PDF 349}}\n- PET/CT: xâm lấn vùng chậu, ổ bụng và lan tràn toàn thân {{Y5 tr.34}}\n- X-quang phổi: di căn phổi–màng phổi {{QĐ1514 tr.PDF 349}}\n- Xạ hình xương (99mTc-MDP) để đánh giá di căn xương và giai đoạn {{QĐ1514 tr.PDF 349}}\n- X-quang đại tràng cản quang, nội soi đại tràng, soi bàng quang–trực tràng khi nghi xâm lấn {{Y5 tr.34}}\n@@end\n\n### Dấu ấn sinh học\n| Dấu ấn | Tham chiếu và ý nghĩa theo nguồn |\n|---|---|\n| **CA-125** | bình thường <35 U/mL; tăng ở ~80% UTBT biểu mô không tiết nhầy; 75% UTBT có CA-125 tăng được chẩn đoán ở IIIC–IV; **không dùng tầm soát** {{Y5 tr.34}} |\n| **HE4** | bình thường ≤70 pmol/L (chưa mãn kinh), ≤140 (mãn kinh); tăng ở dịch trong 90%, nội mạc ~100%, tế bào sáng 50%; chủ yếu theo dõi {{Y5 tr.34}} |\n| **ROMA** | kết hợp CA-125 và HE4, tăng độ nhạy–đặc hiệu, phụ thuộc tình trạng kinh; FDA chấp thuận đánh giá khối cạnh phần phụ {{Y5 tr.34}} {{Y5 tr.35}} |\n| **CEA** | tỉ số CA-125/CEA >25 gặp ở 82% UTBT, giúp phân biệt với ung thư ngoài buồng trứng {{Y5 tr.35}} |\n| **AFP** | bình thường <20 ng/mL; tăng ở tế bào mầm (u xoang nội bì), cũng tăng ở ung thư gan {{Y5 tr.35}} |\n| **β-hCG** | bình thường <5 mU/mL; tăng ở carcinôm đệm nuôi, carcinôm phôi, tế bào hỗn hợp {{Y5 tr.35}} |\n| CA 72-4, Inhibin B, AMH, LH | QĐ1514 ghi thường tăng; giá trị đánh giá đáp ứng và theo dõi tái phát–di căn {{QĐ1514 tr.PDF 350}} |\n\n### Giải phẫu bệnh và lấy mẫu\n- Mổ thăm dò, cắt lạnh; hoặc nội soi ổ bụng thám sát và sinh thiết {{Y5 tr.35}}\n- Tế bào học dịch báng hoặc dịch rửa ổ bụng; chọc hút dịch màng phổi, hạch nếu có {{Y5 tr.35}} {{QĐ1514 tr.PDF 350}}\n- Sinh thiết hạch ngoại biên hoặc tổn thương xâm lấn cổ tử cung, đại tràng khi có di căn {{Y5 tr.35}}\n- Xét nghiệm gen BRCA1/2 và các gen Lynch để tiên lượng và chọn thuốc đích {{QĐ1514 tr.PDF 350}}\n\n### Phân giai đoạn FIGO 2018 (Y5)\n| Giai đoạn | Mô tả (chép theo Y5) |\n|---|---|\n| **I** | khu trú buồng trứng: IA một bên, không vỡ vỏ, không sùi, không tế bào ác trong dịch; IB hai bên, điều kiện như IA; IC vỡ vỏ (IC1 trong mổ, IC2 trước mổ) hoặc có tế bào ác trong dịch báng/rửa (IC3) {{Y5 tr.30}} |\n| **II** | một hoặc hai bên, lan vùng chậu: IIA tử cung, vòi, buồng trứng còn lại; IIB các mô khác trong chậu {{Y5 tr.30}} |\n| **III** | di căn phúc mạc ngoài chậu và/hoặc hạch sau phúc mạc: IIIA1 chỉ hạch (i) ≤1 cm, (ii) >1 cm; IIIA2 di căn vi thể phúc mạc; IIIB đại thể ≤2 cm; IIIC đại thể >2 cm, kể cả bao gan, lách {{Y5 tr.30}} {{Y5 tr.31}} |\n| **IV** | di căn xa: IVA tràn dịch màng phổi có tế bào học dương; IVB di căn nhu mô gan–lách hoặc ngoài ổ bụng (kể cả hạch bẹn) {{Y5 tr.31}} |\n\n> [!warn] Lệch phiên bản phân giai đoạn\n> - Y5 dùng FIGO 2018; QĐ1514 ghi \"AJCC và FIGO phiên bản 8 năm 2017\", kích thước hạch ghi 10 mm (tương đương 1 cm của Y5) {{Y5 tr.30}} {{QĐ1514 tr.PDF 351}}\n\n### Chỉ định cận lâm sàng theo tình huống\n- Nghi UTBT: siêu âm đầu dò âm đạo và bụng; CT hoặc MRI bụng–chậu; X-quang ngực {{Y5 tr.32}} {{QĐ1514 tr.PDF 349}}\n- Đánh giá giai đoạn và trước điều trị: nội soi ổ bụng, CT, PET/CT, xạ hình xương; nội soi dạ dày–đại trực tràng {{QĐ1514 tr.PDF 349}}\n- Khi nghi ung thư tế bào mầm: AFP và β-hCG {{QĐ1514 tr.PDF 350}}\n- Khi có khối và nguy cơ di truyền: xét nghiệm BRCA1/2 {{QĐ1514 tr.PDF 350}}\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Chẩn đoán xác định\n> - **Mô bệnh học** (sinh thiết nội soi ổ bụng hoặc phẫu thuật) là xét nghiệm quyết định chẩn đoán {{QĐ1514 tr.PDF 350}}\n> - Chẩn đoán đầy đủ gồm: mô bệnh học, giai đoạn FIGO/TNM và tình trạng gen BRCA {{QĐ1514 tr.PDF 350}}\n> - Trường hợp chưa có mô bệnh học sau mổ: có thể sinh thiết cắt lạnh, sau đó hóa trị và phẫu thuật gian kỳ {{Y5 tr.36}}\n\n### Chẩn đoán phân biệt khối vùng chậu – ổ bụng\n| Bệnh lý | Điểm chung | Điểm phân biệt / cận lâm sàng |\n|---|---|---|\n| U lành buồng trứng, nang buồng trứng | khối vùng chậu | không có đặc điểm nào đủ để chẩn đoán ác tính; đánh giá siêu âm theo tiêu chí gợi ý ác tính {{QĐ1514 tr.PDF 350}} {{Y5 tr.33}} {{128VĐ mục 96}} |\n| U xơ tử cung, u tử cung | khối vùng chậu | khám phụ khoa, siêu âm, đánh giá nguồn gốc khối {{128VĐ mục 96}} {{QĐ1514 tr.PDF 350}} |\n| Viêm nhiễm, áp xe vòi–buồng trứng, viêm vùng chậu | đau hạ vị, khối | viêm nhiễm và áp xe vùng tiểu khung {{QĐ1514 tr.PDF 350}} {{128VĐ mục 96}} |\n| Lao sinh dục, lao màng bụng | báng bụng, khối | {{QĐ1514 tr.PDF 350}} |\n| U đường tiêu hóa, tiết niệu, u sau phúc mạc, u mạc treo | khối ổ bụng | {{QĐ1514 tr.PDF 350}} |\n| Ung thư di căn đến buồng trứng (dạ dày, đại trực tràng) | khối hai bên | nội soi dạ dày–đại trực tràng; đánh giá toàn diện trước điều trị {{QĐ1514 tr.PDF 349}} {{QĐ1514 tr.PDF 350}} |\n| Lymphoma, sarcoma ổ bụng | khối ổ bụng không điển hình | định hướng bằng cận lâm sàng phù hợp {{128VĐ mục 64}} |\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n\n> [!key] Mục tiêu theo giai đoạn\n> - **Điều trị chủ yếu là phẫu trị và hóa trị**; xạ trị ít có vai trò {{Y5 tr.35}} {{Y5 tr.37}}\n> - Giai đoạn I: phẫu thuật triệt để là đủ với mô bệnh học biệt hóa tốt–trung bình {{QĐ1514 tr.PDF 352}}\n> - Giai đoạn II–IV: giảm tổng khối u tối ưu (không còn u đại thể hoặc còn nhỏ hơn 1 cm), rồi hóa trị {{Y5 tr.36}} {{QĐ1514 tr.PDF 352}}\n> - Điều trị đa mô thức (phẫu, xạ, hóa, đích, miễn dịch) tùy thể mô bệnh học, giai đoạn, tuổi và tình trạng bệnh nhân {{QĐ1514 tr.PDF 351}}\n\n### 7.2 Các phương pháp\n\n@@tabs\n@@tab Phẫu thuật\n- **Giai đoạn I**: mổ bụng thăm dò, đánh giá giai đoạn; triệt để là cắt tử cung, hai phần phụ, mạc nối lớn; sinh thiết hệ thống phúc mạc (cùng đồ, rãnh đại tràng, bàng quang, mạc treo) {{Y5 tr.35}} {{Y5 tr.36}}\n- **Bảo tồn sinh sản** (trẻ, còn muốn có con): Y5 cho phép ở IA hoặc IC một bên, mọi độ mô học; QĐ1514 chỉ IA–IB và độ mô học thấp (độ I) {{Y5 tr.36}} {{QĐ1514 tr.PDF 352}}\n- **Giai đoạn II–IV**: giảm tối đa khối u; cắt khối nghi di căn nếu bệnh nhân chịu được mổ; nạo hạch chậu–cạnh động mạch chủ không thường quy {{Y5 tr.36}}\n- Kiểm tra vòm hoành, toàn bộ phúc mạc, hạch chậu–chủ bụng; lấy dịch rửa ổ bụng làm tế bào học {{QĐ1514 tr.PDF 352}}\n- Khối u dạng nhầy cần khảo sát thêm ống tiêu hóa và cắt ruột thừa {{Y5 tr.36}}\n- **Phẫu thuật gian kỳ**: sau hóa trị tân hỗ trợ, nếu đáp ứng thì mổ lại để cắt đúng mức {{Y5 tr.36}}\n- Nội soi ổ bụng: ưu điểm giảm thời gian mổ, chảy máu, thời gian nằm viện và thẩm mỹ; nhược điểm: có thể làm vỡ u, khảo sát hạch sau phúc mạc hạn chế, nguy cơ gieo rắc qua trocart {{Y5 tr.36}}\n@@tab Hóa trị\n- **Hóa trị hỗ trợ** chỉ định cho: giai đoạn IC trở lên, hoặc bướu tế bào sáng, hoặc độ mô học cao {{Y5 tr.37}}\n- Ung thư biểu mô: nền platinum; phác đồ chuẩn hiện nay là **Carboplatin + Paclitaxel**; cải thiện rõ tiên lượng {{Y5 tr.37}}\n- **Tân hỗ trợ** (giai đoạn III–IV không mổ giảm khối u được ngay, hoặc nguy cơ mổ rất cao) {{Y5 tr.36}} {{QĐ1514 tr.PDF 352}}\n- Tế bào mầm: BEP (cisplatin, etoposide, bleomycin) {{Y5 tr.37}}; BEP có tỷ lệ đáp ứng cao hơn cả {{QĐ1514 tr.PDF 357}}\n- Thuốc mới có hiệu quả: taxane, gemcitabine, lipo-doxorubicin, topotecan {{QĐ1514 tr.PDF 352}}\n@@tab Đích – PARP – nội tiết – miễn dịch – xạ\n- **Bevacizumab** (kháng VEGF): cải thiện khi phối hợp PC ở giai đoạn III–IV hoặc khi khối u tồn dư sau mổ lớn hơn 1 cm {{QĐ1514 tr.PDF 354}} {{Y5 tr.37}}\n- **PARP** (olaparib): cải thiện tiên lượng khi có BRCA {{Y5 tr.37}}; chi tiết [mục 7.3](#/n/ung-thu-buong-trung/7) {{QĐ1514 tr.PDF 355}}\n- **Nội tiết**: tamoxifen hoặc letrozole cho tái phát không triệu chứng hoặc cần nghỉ hóa trị {{QĐ1514 tr.PDF 356}}\n- **Miễn dịch**: pembrolizumab, atezolizumab đang thử nghiệm; tài liệu không nêu chỉ định chuẩn {{QĐ1514 tr.PDF 356}}\n- **Xạ trị**: ít áp dụng; giảm nhẹ toàn ổ bụng ở giai đoạn muộn (44 Gy); di căn não đa ổ xạ toàn não; 1–3 ổ dưới 3 cm dùng dao gamma {{Y5 tr.37}} {{QĐ1514 tr.PDF 356}}\n@@end\n\n#### Theo giai đoạn\n@@tabs\n@@tab Giai đoạn I\n- Phẫu thuật triệt để + đánh giá giai đoạn đầy đủ {{Y5 tr.35}} {{Y5 tr.36}}\n- IC trở lên, tế bào sáng hoặc độ cao: hóa trị hỗ trợ (Carboplatin + Paclitaxel) {{Y5 tr.37}}\n- IA–IB, biệt hóa tốt–trung bình: phẫu thuật triệt để là đủ {{QĐ1514 tr.PDF 352}}\n- Trẻ, muốn có con: bảo tồn ([xem 7.2](#/n/ung-thu-buong-trung/7)); IA/IC theo Y5, IA/IB độ I theo QĐ1514 {{Y5 tr.37}} {{QĐ1514 tr.PDF 352}}\n@@tab Giai đoạn II–IV\n- Giảm tối đa khối u, sau đó hóa trị platinum–taxane ± bevacizumab {{Y5 tr.36}} {{Y5 tr.37}} {{QĐ1514 tr.PDF 354}}\n- Lan rộng không lấy hết được: sinh thiết cắt lạnh → hóa trị → phẫu thuật gian kỳ {{Y5 tr.36}}\n- Giai đoạn IV: phác đồ hóa trị di căn ([mục 7.3](#/n/ung-thu-buong-trung/7)); tài liệu không nêu hướng dẫn riêng theo vị trí di căn {{QĐ1514 tr.PDF 353}}\n@@tab Tái phát\n- Nhạy platinum: bevacizumab–carboplatin–gemcitabine; duy trì PARP nếu có BRCA {{QĐ1514 tr.PDF 354}} {{QĐ1514 tr.PDF 355}}\n- Kháng platinum: paclitaxel hàng tuần + bevacizumab; lipo-doxorubicin + bevacizumab; topotecan ± bevacizumab {{QĐ1514 tr.PDF 355}}\n- Theo dõi tái phát: đau vùng chậu, sụt cân, CA-125 tăng, hình ảnh học {{Y5 tr.37}}\n@@end\n\n### 7.3 Phác đồ – Y lệnh\n\n> [!doc] QĐ 1514/QĐ-BYT (ngày 1/4/2020), Bài 43 \"Ung thư buồng trứng\" (tr. PDF 348–358). Liều và chu kỳ chép đúng nguồn. {{QĐ1514 tr.PDF 348–358}}\n\n@@tabs\n@@tab Hóa trị tân–bổ trợ (biểu mô)\n| Phác đồ | Thuốc – liều | Chu kỳ | Ghi chú |\n|---|---|---|---|\n| **Carboplatin – paclitaxel** (tân hỗ trợ) | Carboplatin AUC 5–6 TM ngày 1 + Paclitaxel 175 mg/m² TM ngày 1 | 21 ngày | phác đồ chuẩn {{Y5 tr.37}} {{QĐ1514 tr.PDF 352}} |\n| Carboplatin – docetaxel (tân hỗ trợ) | Carboplatin AUC 5 ngày 1 + Docetaxel 75 mg/m² ngày 1 | 21 ngày | {{QĐ1514 tr.PDF 352}} |\n| Paclitaxel – carboplatin (bổ trợ) | Paclitaxel 175 mg/m² ngày 1 + Carboplatin AUC 5–6 ngày 1 | 21 ngày × 3–6 | {{QĐ1514 tr.PDF 352}} |\n| Paclitaxel tuần – carboplatin (bổ trợ) | Paclitaxel 80 mg/m² ngày 1, 8, 15 + Carboplatin AUC 5–6 ngày 1 | 21 ngày × 6 | {{QĐ1514 tr.PDF 352}} |\n| Paclitaxel tuần – carboplatin AUC 2 | Paclitaxel 60 mg/m² + Carboplatin AUC 2, hàng tuần | 18 tuần | {{QĐ1514 tr.PDF 352}} |\n| Docetaxel – carboplatin (bổ trợ) | Docetaxel 60–75 mg/m² ngày 1 + Carboplatin AUC 5–6 ngày 1 | 21 ngày × 3–6 | {{QĐ1514 tr.PDF 352}} |\n| Carboplatin + liposomal doxorubicin | Carboplatin AUC 5 + Pegylated liposomal doxorubicin 30 mg/m² | 28 ngày × 6 | {{QĐ1514 tr.PDF 352}} |\n\n@@tab Di căn – tái phát (hóa trị)\n| Phác đồ | Thuốc – liều | Chu kỳ | Ghi chú |\n|---|---|---|---|\n| Carboplatin – cyclophosphamide | Carboplatin 300 mg/m² TM ngày 1 + Cyclophosphamide 600 mg/m² ngày 1 | 21 ngày | đơn vị carboplatin khác AUC, xem lưu ý {{QĐ1514 tr.PDF 353}} |\n| CP | Cisplatin 75 mg/m² + Cyclophosphamide 600 mg/m² ngày 1 | 21 ngày | {{QĐ1514 tr.PDF 353}} |\n| PAC | Cisplatin 50 mg/m² + Doxorubicin 50 mg/m² + Cyclophosphamide 750 mg/m² ngày 1 | 21 ngày | {{QĐ1514 tr.PDF 353}} |\n| Gemcitabine – carboplatin | Gemcitabine 1.000 mg/m² ngày 1, 8 + Carboplatin AUC 4 | 21 ngày | {{QĐ1514 tr.PDF 353}} |\n| Paclitaxel đơn | 175 mg/m² ngày 1 hoặc 80 mg/m² hàng tuần | 21 ngày / tuần | {{QĐ1514 tr.PDF 353}} |\n| Docetaxel đơn | 100 mg/m² ngày 1 | 21 ngày | {{QĐ1514 tr.PDF 353}} |\n| Topotecan | 1,5 mg/m² TM ngày 1–5 | 21 ngày | {{QĐ1514 tr.PDF 353}} |\n| Etoposide uống | 50 mg/m² uống ngày 1–21 | 28 ngày | {{QĐ1514 tr.PDF 353}} |\n| Liposomal doxorubicin | 50 mg/m² TM ngày 1 | 28 ngày | bệnh dai dẳng sau phác đồ có cisplatin; đáp ứng khoảng 26% {{QĐ1514 tr.PDF 354}} |\n| Paclitaxel + carboplatin + bevacizumab | Paclitaxel 175 mg/m² (3 giờ) + Carboplatin AUC 5–6 + Bevacizumab 15 mg/kg, ngày 1 | 3 tuần × 6; bevacizumab đến 12 chu kỳ | giai đoạn III–IV {{QĐ1514 tr.PDF 354}} |\n| Bevacizumab – gemcitabine – carboplatin | Bevacizumab 15 mg/kg ngày 1; Gemcitabine 1.000 mg/m² ngày 1, 8; Carboplatin AUC 4 | 3 tuần × 6–10 liệu trình | nhạy platinum; sau đó bevacizumab mỗi 3 tuần {{QĐ1514 tr.PDF 354}} |\n| Paclitaxel tuần + bevacizumab | Paclitaxel 80 mg/m² hàng tuần + Bevacizumab 10 mg/kg mỗi 2 tuần | tài liệu không nêu | kháng platinum {{QĐ1514 tr.PDF 354}} |\n| Lipo-doxorubicin + bevacizumab; topotecan ± bevacizumab | Lipo-doxorubicin 50 mg/m² mỗi 3 tuần + Bevacizumab 10 mg/kg mỗi 2 tuần; Topotecan 1,25–1,5 mg/m² ngày 1–5 mỗi 3 tuần ± Bevacizumab 15 mg/kg | tài liệu không nêu | kháng platinum {{QĐ1514 tr.PDF 355}} |\n\n@@tab Đích – PARP – nội tiết – xạ\n| Nhóm | Thuốc – liều | Chỉ định / ghi chú |\n|---|---|---|\n| **Olaparib** (PARP, duy trì) | 2 viên 150 mg × 2 lần/ngày (tổng 600 mg/ngày) | UT biểu mô độ cao, FIGO III–IV, đột biến BRCA1/2, đang đáp ứng sau hóa trị bước 1 có platinum; đến khi tiến triển, hoặc 2 năm với bước 1 có BRCA {{QĐ1514 tr.PDF 355}} |\n| Rucaparib | 600 mg × 2 lần/ngày | tái phát có đột biến BRCA {{QĐ1514 tr.PDF 355}} |\n| Niraparib | 300 mg/ngày | nhạy platinum trước đó; thất bại với ít nhất 2 bước hóa trị {{QĐ1514 tr.PDF 355}} |\n| Tamoxifen | 20 mg × 2 lần/ngày | tái phát không triệu chứng hoặc cần nghỉ hóa trị {{QĐ1514 tr.PDF 356}} |\n| Letrozole | 2,5 mg/ngày | như trên {{QĐ1514 tr.PDF 356}} |\n| Miễn dịch | — | pembrolizumab, atezolizumab đang thử nghiệm; tài liệu không nêu chỉ định chuẩn {{QĐ1514 tr.PDF 356}} |\n| Xạ trị giảm nhẹ | toàn ổ bụng 44 Gy | giai đoạn muộn, tái phát lan tràn ổ bụng {{QĐ1514 tr.PDF 356}} |\n| Xạ trị não / dao gamma | toàn não 40–45 Gy; dao gamma 18–26 Gy | di căn não đa ổ (>3); dao gamma cho 1–3 ổ dưới 3 cm {{QĐ1514 tr.PDF 356}} |\n\n@@tab Tế bào mầm – mô đệm\n| Phác đồ | Thuốc – liều | Chu kỳ | Ghi chú |\n|---|---|---|---|\n| **BEP** | Cisplatin 20 mg/m² ngày 1–5; Etoposide 100 mg/m² ngày 1–5; Bleomycin 20 mg/m² ngày 2, 9, 16 (tối đa 30 mg) | 21 ngày × 4 | phác đồ có đáp ứng cao nhất {{QĐ1514 tr.PDF 357}} |\n| PVB | Cisplatin 20 mg/m² ngày 1–5; Vinblastine 12 mg/m² ngày 1; Bleomycin 20 mg/m² ngày 1, 8, 15 | 21 ngày × 3–4 | {{QĐ1514 tr.PDF 357}} |\n| VAC | Vincristine 1,5 mg/m² ngày 1, 15; Dactinomycin 0,3 mg/m² ngày 1–5; Cyclophosphamide 150 mg/m² ngày 1–5 | 28 ngày | {{QĐ1514 tr.PDF 357}} |\n| PEI | Ifosfamide 1.200 mg/m² ngày 1–5 (có mesna); Etoposide 75 mg/m² ngày 1–5; Cisplatin 20 mg/m² ngày 1–5 | 21–28 ngày | {{QĐ1514 tr.PDF 357}} |\n| Mô đệm–dây sinh dục | hóa trị hỗ trợ theo PVB hoặc BEP cho giai đoạn II–IV và giai đoạn I trên 40 tuổi | theo phác đồ | {{QĐ1514 tr.PDF 357}} |\n@@end\n\n> [!warn] Theo dõi & độc tính cần nhớ\n> - Carboplatin và taxane: độc tủy xương; cần thuốc hỗ trợ, dự phòng hạ bạch cầu và theo dõi chặt sau truyền {{QĐ1514 tr.PDF 352}}\n> - Tế bào mầm: độc tủy và thận; khuyến cáo dùng thuốc kích thích tăng sinh dòng bạch cầu (Filgrastim) sau truyền {{QĐ1514 tr.PDF 357}}\n> - Bevacizumab và olaparib: tài liệu không nêu tác dụng phụ hay lịch theo dõi cụ thể\n> - Carboplatin 300 mg/m² (tr.353) khác đơn vị AUC ở các phác đồ khác; chép nguyên văn, nghi lỗi chép, đối chiếu bản gốc {{QĐ1514 tr.PDF 353}}\n> - Tamoxifen 20 mg hai lần/ngày: liều chép nguyên văn từ QĐ1514 tr.356, không có nguồn đối chiếu trong Y5 {{QĐ1514 tr.PDF 356}}\n\n## 8. Tiên lượng – Dự phòng\n\n> [!key] Tóm tắt\n> - Tiên lượng phụ thuộc giai đoạn và mức độ giảm khối u; **giảm tối ưu** (còn lại nhỏ hơn 1 cm) cho thời gian sống còn tốt hơn {{QĐ1514 tr.PDF 358}} {{Y5 tr.36}}\n> - Sống 5 năm: giai đoạn I ==90–100%==, II ==70–80%==, III ==40%==, IV ==0–15%== {{Y5 tr.38}}\n> - Không có lịch tầm soát thường quy được nêu trong tài liệu; dự phòng và tư vấn dựa vào nguy cơ di truyền {{QĐ1514 tr.PDF 358}} {{Y5 tr.34}}\n\n### Tiên lượng\n@@tabs\n@@tab Yếu tố tiên lượng\n- **Giai đoạn** là yếu tố chính; khối u càng nhỏ, chưa di căn hạch thì khả năng khỏi bệnh càng cao {{QĐ1514 tr.PDF 358}}\n- Mức độ giảm khối u sau mổ: giảm tối ưu cho sống còn tốt hơn giảm dưới tối ưu {{Y5 tr.36}}\n- BRCA đột biến: dùng để tiên lượng và chọn PARP {{QĐ1514 tr.PDF 350}} {{Y5 tr.37}}\n- Tế bào mầm: tiên lượng rất tốt, tỷ lệ chữa khỏi cao {{QĐ1514 tr.PDF 348}}\n@@tab Sống còn 5 năm\n| Giai đoạn | Sống 5 năm (Y5) |\n|---|---|\n| I | 90–100% |\n| II | 70–80% |\n| III | 40% |\n| IV | 0–15% |\n\n{{Y5 tr.38}}\n@@tab Tái phát\n- Phát hiện: triệu chứng lâm sàng (đau vùng chậu, sụt cân), CA-125 tăng, hoặc hình ảnh học {{Y5 tr.37}}\n- Chỉ dùng CA-125 theo dõi nếu đã tăng trước điều trị; HE4 chủ yếu cho bệnh nhân đã tăng HE4 trước điều trị {{Y5 tr.37}} {{Y5 tr.34}}\n- Chụp X-quang ngực, CT, MRI, PET/CT chỉ khi có triệu chứng nghi ngờ trên lâm sàng {{Y5 tr.37}}\n@@end\n\n### Theo dõi sau điều trị\n| Nguồn | Lịch khám | Ghi chú |\n|---|---|---|\n| Y5 | mỗi 2–4 tháng trong 2 năm đầu; mỗi 3–6 tháng năm thứ 3–5; sau đó mỗi năm {{Y5 tr.37}} | khám vùng chậu bắt buộc mỗi lần |\n| QĐ1514 | mỗi 3 tháng trong 5 năm; mỗi lần khám lâm sàng, phụ khoa và cận lâm sàng {{QĐ1514 tr.PDF 358}} | **khác Y5**, xem mục 9 |\n\n### Dự phòng\n@@tabs\n@@tab Cấp 1 (phòng bệnh)\n- Tránh yếu tố nguy cơ; khám sức khỏe định kỳ hoặc khi có bất thường để phát hiện bệnh sớm {{QĐ1514 tr.PDF 358}}\n- Thuốc tránh thai uống và sinh đẻ nhiều: giảm nguy cơ {{Y5 tr.26}}\n- Không hút thuốc lá (tăng loại tiết dịch nhầy); chế độ ăn giàu vitamin A và chất xơ {{Y5 tr.27}} {{QĐ1514 tr.PDF 348}}\n@@tab Cấp 2 (tầm soát – nguy cơ cao)\n- Tầm soát thường quy: **tài liệu không nêu** lịch tầm soát UTBT; QĐ1514 ghi phát hiện sớm \"còn rất hạn chế\" {{QĐ1514 tr.PDF 348}}\n- CA-125 **không dùng** tầm soát (Y5); QĐ1514 liệt kê CA-125, HE4 và siêu âm đầu dò âm đạo là phương pháp sàng lọc thường dùng, xem mục 9 {{Y5 tr.34}} {{QĐ1514 tr.PDF 348}}\n- Phụ nữ nguy cơ cao: xét nghiệm gen BRCA1/2 và tư vấn di truyền {{QĐ1514 tr.PDF 358}} {{SY5 tr.194}}\n@@tab Cấp 3 (phẫu thuật phòng ngừa, giảm nhẹ)\n- Phẫu thuật phòng ngừa (cắt 2 phần phụ) ở người lành mang gen BRCA có độ thấm cao {{SY5 tr.198}} {{SY5 tr.201}}\n- Chỉ mổ phòng ngừa khi: gen độ thấm cao, test đáng tin, giảm tối đa nguy cơ, nguy cơ mổ tối thiểu, có thay thế chức năng, có chương trình theo dõi sau mổ, đã tư vấn kỹ {{SY5 tr.199}}\n- Giảm nhẹ giai đoạn muộn: xạ toàn ổ bụng 44 Gy {{QĐ1514 tr.PDF 356}}\n@@end\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] Bệnh này thi nhấn mạnh gì\n> - Trọng số QĐ 22 (tr.8): \"Cận lâm sàng / XN chẩn đoán\" 45–60 và \"Liệu pháp thuốc\" 35–50; văn bản không nói rõ là trọng số dòng hay nhóm {{QĐ22 tr.8}}\n> - Nhận diện và chẩn đoán (mô bệnh học + giai đoạn FIGO + gen BRCA) là phần nặng nhất; sau đó là xử trí phẫu thuật + hóa trị {{Y5 tr.36}} {{QĐ1514 tr.PDF 350}}\n> - Đề cương: ca lâm sàng \"Ung thư buồng trứng\" (MT 2,3,4,5,7,8,9,10,12,13,14,15,17), trình bệnh án và thi cuối kỳ {{ĐC Y5 tr.6}}\n> - Câu hỏi tình huống: \"phụ nữ sau mãn kinh có khối vùng chậu kèm báng bụng thì làm gì\" {{Y5 tr.32}} {{Y5 tr.33}}\n\n@@tabs\n@@tab Nhận diện\n- Nguy cơ then chốt: **không sinh con**, mãn kinh muộn (sau 52 tuổi), HBOC (BRCA1 ==40–50%==), Lynch II {{Y5 tr.26}} {{Y5 tr.27}}\n- Đa số chẩn đoán muộn: ==59%== tiến xa/di căn xa; gieo rắc trong ổ bụng sớm và hay gặp nhất {{Y5 tr.30}}\n- Triệu chứng muộn: bụng chướng, báng bụng, khối ổ bụng, đau hạ vị, chảy máu âm đạo {{QĐ1514 tr.PDF 349}} {{Y5 tr.32}}\n- {r|Báo động}: khối vùng chậu kèm báng bụng; xuất huyết âm đạo bất thường; nam hóa {{Y5 tr.32}}\n- Nội soi dạ dày–đại trực tràng khi có khối buồng trứng (Krukenberg) {{QĐ1514 tr.PDF 349}}\n[Xem mục 4](#/n/ung-thu-buong-trung/4) · [mục 3](#/n/ung-thu-buong-trung/3)\n@@tab Chẩn đoán\n- **Mô bệnh học** (sinh thiết nội soi/phẫu thuật) là chẩn đoán xác định {{QĐ1514 tr.PDF 350}}\n- Siêu âm đầu dò âm đạo là đầu tay; gợi ý ác tính: trên 5 cm, nhiều vách–chồi, hai bên, dịch ổ bụng {{Y5 tr.32}} {{Y5 tr.33}}\n- {g|CA-125 (tăng ~80%), HE4, ROMA} hỗ trợ theo dõi, {r|không dùng tầm soát} {{Y5 tr.34}}\n- Phân giai đoạn FIGO: I (khu trú buồng trứng) → IV (di căn xa, tràn dịch màng phổi tế bào học dương) {{Y5 tr.30}} {{Y5 tr.31}}\n- Gen BRCA1/2 và các gen Lynch để tiên lượng, chọn PARP {{QĐ1514 tr.PDF 350}}\n[Xem mục 5](#/n/ung-thu-buong-trung/5) · [mục 6](#/n/ung-thu-buong-trung/6)\n@@tab Điều trị\n- **Giai đoạn I**: phẫu triệt để; bảo tồn ở người trẻ muốn có con, tiêu chuẩn khác nhau giữa Y5 và QĐ1514 {{Y5 tr.36}} {{QĐ1514 tr.PDF 352}}\n- **II–IV**: giảm tối đa khối u (còn nhỏ hơn 1 cm) + {g|hóa trị Carboplatin AUC 5–6 + Paclitaxel 175 mg/m²} (21 ngày) {{Y5 tr.36}} {{QĐ1514 tr.PDF 352}}\n- Bevacizumab cho III–IV; {p|PARP (olaparib 600 mg/ngày)} khi BRCA đột biến sau hóa trị bước 1 có platinum {{QĐ1514 tr.PDF 354}} {{QĐ1514 tr.PDF 355}}\n- {r|Xạ trị ít vai trò} ở biểu mô; xạ toàn ổ bụng 44 Gy chỉ giảm nhẹ {{Y5 tr.37}} {{QĐ1514 tr.PDF 356}}\n- Tế bào mầm: {p|BEP} (cisplatin–etoposide–bleomycin) 4 đợt; người trẻ, đa số giai đoạn I {{Y5 tr.37}} {{QĐ1514 tr.PDF 356}}\n- Tái phát nhạy platinum: bevacizumab–carboplatin–gemcitabine; kháng: paclitaxel tuần + bevacizumab {{QĐ1514 tr.PDF 354}}\n[Xem mục 7.2](#/n/ung-thu-buong-trung/7) · [mục 7.3](#/n/ung-thu-buong-trung/7)\n@@tab Tiên lượng – Dự phòng\n- Sống 5 năm: I ==90–100%==, IV ==0–15%== {{Y5 tr.38}}\n- Giảm tối ưu (còn nhỏ hơn 1 cm) cho sống còn tốt hơn {{Y5 tr.36}}\n- Theo dõi: Y5 khám 2–4 tháng trong 2 năm đầu; QĐ1514 khám 3 tháng trong 5 năm {{Y5 tr.37}} {{QĐ1514 tr.PDF 358}}\n- Dự phòng: BRCA1/2 cho nguy cơ cao; phẫu thuật phòng ngừa cắt 2 phần phụ khi có BRCA độ thấm cao {{QĐ1514 tr.PDF 358}} {{SY5 tr.201}}\n- Tránh yếu tố nguy cơ; thuốc tránh thai uống giảm nguy cơ {{Y5 tr.26}}\n[Xem mục 8](#/n/ung-thu-buong-trung/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Chuẩn tuổi mắc thế giới | ==6,1 (2018, Y5) / 6,6 (2018, QĐ1514) / 6,7 (2022, SY5)== | {{Y5 tr.25}} {{QĐ1514 tr.PDF 348}} {{SY5 tr.209}} |\n| Chuẩn tuổi mắc Việt Nam | ==2,7 (2018) → 2,5 (2022)== | {{Y5 tr.25}} {{SY5 tr.210}} |\n| Tuổi chẩn đoán trung bình | ==60–65 (Y5) / 63 (QĐ1514)== | {{Y5 tr.25}} {{QĐ1514 tr.PDF 348}} |\n| BRCA1 / BRCA2 (nguy cơ trọn đời) | ==40–50% / 10–20%== | {{Y5 tr.27}} |\n| Lynch II: nguy cơ trọn đời (MMR) | ==9–12%== | {{Y5 tr.27}} |\n| Giai đoạn tiến xa khi chẩn đoán | ==59%== | {{Y5 tr.30}} |\n| CA-125 bình thường / tăng ở UTBT biểu mô | ==<35 U/mL / ~80%== | {{Y5 tr.34}} |\n| CA-125 tăng khi chẩn đoán ở IIIC–IV | ==75%== | {{Y5 tr.34}} |\n| Siêu âm gợi ý ác tính | ==trên 5 cm; vách/chồi trên 2–3 mm== | {{Y5 tr.33}} |\n| Giảm khối u tối ưu | ==còn nhỏ hơn 1 cm== | {{Y5 tr.36}} |\n| Hóa trị hỗ trợ (chỉ định) | ==từ IC, tế bào sáng, độ cao== | {{Y5 tr.37}} |\n| Carboplatin – paclitaxel | ==AUC 5–6 + 175 mg/m², 21 ngày== | {{QĐ1514 tr.PDF 352}} |\n| Olaparib duy trì (BRCA) | ==600 mg/ngày (2 viên 150 mg × 2)== | {{QĐ1514 tr.PDF 355}} |\n| Theo dõi sau điều trị | ==Y5: 2–4 tháng/2 năm đầu; QĐ1514: 3 tháng/5 năm== | {{Y5 tr.37}} {{QĐ1514 tr.PDF 358}} |\n| Sống 5 năm I / IV | ==90–100% / 0–15%== | {{Y5 tr.38}} |\n\n> [!warn] Bẫy thi thường gặp (lệch nguồn: ghi cả hai)\n> - **Bảo tồn sinh sản**: Y5 IA/IC một bên, mọi độ mô học; QĐ1514 IA/IB, độ thấp {{Y5 tr.36}} {{QĐ1514 tr.PDF 352}}\n> - **Tầm soát**: Y5 nói CA-125 không dùng tầm soát; QĐ1514 liệt kê CA-125, HE4, siêu âm đầu dò âm đạo là phương pháp thường dùng {{Y5 tr.34}} {{QĐ1514 tr.PDF 348}}\n> - **Theo dõi**: Y5 2–4 tháng/2 năm rồi 3–6 tháng/3 năm; QĐ1514 3 tháng/5 năm {{Y5 tr.37}} {{QĐ1514 tr.PDF 358}}\n> - **Dịch tễ thế giới 2018**: 6,1 (Y5) và 6,6 (QĐ1514); ung thư biểu mô 85–90% (Y5) và 80–90% (QĐ1514) {{Y5 tr.25}} {{QĐ1514 tr.PDF 348}}\n> - **Nguy cơ gia đình**: Y5 hội chứng đặc hiệu vị trí gấp 3 lần; QĐ1514 mẹ/chị em gái gấp 20 lần (nguyên văn) {{Y5 tr.26}} {{QĐ1514 tr.PDF 348}}\n> - **Phiên bản phân giai đoạn**: Y5 FIGO 2018; QĐ1514 AJCC/FIGO 8 (2017). Ngưỡng hạch 1 cm (Y5) = 10 mm (QĐ1514) {{Y5 tr.30}} {{QĐ1514 tr.PDF 351}}\n> - Olaparib: QĐ1514 chỉ rõ BRCA đột biến và đang đáp ứng sau hóa trị bước 1; Y5 chỉ nêu \"liên quan BRCA\" {{QĐ1514 tr.PDF 355}} {{Y5 tr.37}}\n> - Liều carboplatin 300 mg/m² ở phác đồ di căn là đơn vị khác AUC; nghi lỗi chép {{QĐ1514 tr.PDF 353}}\n\n@@fold Nguồn tài liệu\n- **Y5**: TEXT UNG BƯỚU Y5, bài \"Ung thư buồng trứng\", tr.25–38 (`_work/text-ung-buou-y5.txt`; đọc toàn bộ)\n- **QĐ1514**: QĐ 1514/QĐ-BYT, Bài 43 \"Ung thư buồng trứng\", tr. PDF 348–358 (`_work/qd-1514-byt-ung-buou.txt`; đọc toàn bộ)\n- **SY5**: slide tổng hợp Y5, tr.190 (bảng tác nhân môi trường), tr.194–201 (phòng ngừa và BRCA), tr.209–210 (GLOBOCAN 2022, đối chiếu ảnh render `_work/img-sy5-buongtrung/`)\n- **ĐC Y5**: đề cương Y5, tr.6, bảng ca lâm sàng gắn MT (đối chiếu ảnh `_work/img-decuong-y5/p006.png`)\n- **128VĐ**: mục 63 (báng bụng), 64 (khối ở bụng), 96 (khối vùng chậu) (`data/book-items.json`)\n- **QĐ 22**: STT 53, 54, 55, 87, 91, 99 (`data/qd22.json`); trọng số tr.8 (`_work/qd22.txt`)\n@@end\n\n@@fold Nguồn ngoài\n- Không dùng nguồn ngoài cho bài này; mọi số liệu, phác đồ lấy từ Y5, SY5, QĐ1514, 128VĐ, QĐ 22 và đề cương.\n@@end\n\n@@fold Tự kiểm tra (14 thẻ)\n- Tuổi chẩn đoán trung bình UTBT theo Y5 và QĐ1514? :: Y5: 60–65 tuổi; QĐ1514: 63 tuổi\n- Tỷ lệ UTBT được chẩn đoán ở giai đoạn tiến xa/di căn xa? :: 59% (Y5)\n- Chẩn đoán xác định ung thư buồng trứng dựa vào gì? :: Mô bệnh học (sinh thiết nội soi ổ bụng hoặc phẫu thuật)\n- CA-125 có dùng để tầm soát UTBT không? :: Không (Y5); CA-125 tăng ở ~80% UTBT biểu mô không tiết nhầy, chủ yếu để theo dõi\n- Siêu âm gợi ý ác tính khối buồng trứng (Y5)? :: Nhiều nang–hốc, phần đặc, trên 5 cm, nhiều chồi/vách, hai bên, dịch ổ bụng\n- Phẫu thuật tiêu chuẩn giai đoạn I (Y5)? :: Cắt tử cung + 2 phần phụ + mạc nối lớn, sinh thiết hệ thống, rửa ổ bụng\n- Giảm khối u tối ưu nghĩa là gì? :: Không còn u đại thể hoặc kích thước lớn nhất còn lại nhỏ hơn 1 cm\n- Hóa trị hỗ trợ được chỉ định cho ai (Y5)? :: Từ giai đoạn IC trở lên, hoặc bướu tế bào sáng, hoặc độ mô học cao\n- Phác đồ chuẩn ung thư biểu mô buồng trứng? :: Carboplatin + paclitaxel (Y5); QĐ1514: Carboplatin AUC 5–6 + Paclitaxel 175 mg/m², 21 ngày\n- Olaparib duy trì (QĐ1514) áp dụng khi nào? :: FIGO III–IV, BRCA1/2 đột biến, đang đáp ứng sau hóa trị bước 1 có platinum; 600 mg/ngày\n- Ung thư tế bào mầm buồng trứng: phác đồ thường dùng? :: BEP (cisplatin, etoposide, bleomycin), 21 ngày × 4 đợt\n- Lịch theo dõi sau điều trị theo QĐ1514? :: Khám 3 tháng/lần trong 5 năm (Y5 khác: 2–4 tháng trong 2 năm đầu)\n- Nguy cơ suốt đời mắc UTBT của BRCA1 và BRCA2 (Y5)? :: BRCA1 40–50%; BRCA2 10–20%\n- Phẫu thuật phòng ngừa ở người mang BRCA (SY5)? :: Cắt 2 phần phụ phòng ngừa; chỉ khi đột biến có độ thấm cao và đã tư vấn kỹ\n@@end"}, {"kind": "disease", "disease": "cotucung", "short": "Ung thư cổ tử cung", "group": "", "section": 0, "order": 2, "khung": [87, 91, 92], "id": "ung-thu-cotucung", "title": "Ung thư cổ tử cung", "layer": "benh", "module": "ung-buou", "tags": ["ung bướu", "cổ tử cung", "HPV", "CIN", "Pap", "FIGO 2018", "hóa xạ trị đồng thời", "tầm soát"], "source": "Y5 tr.56–75; SY5 tr.82–116; QĐ1514 Bài 44 (tr. PDF 360–370); 128VĐ mục 91, 92, 96, 97; nguồn ngoài NCI PDQ, WHO", "body": "> [!key] Tóm tắt bệnh\n> - Nguyên nhân gần như tất cả ca: **HPV nguy cơ cao kéo dài** (típ 16, 18 gây ~70%) → CIN → ung thư xâm lấn sau **hàng chục năm** nên rất hợp để ==tầm soát==. {{Y5 tr.57}}\n> - Triệu chứng hay gặp nhất: {r|xuất huyết âm đạo bất thường} (sau giao hợp, sau mãn kinh, giữa kỳ kinh). Chẩn đoán xác định = **sinh thiết**. {{Y5 tr.61–62}}\n> - Phân giai đoạn **FIGO 2018** (lâm sàng + hình ảnh, MRI tốt nhất cho bướu); IA–IIA1 mổ hoặc xạ; ==IB3, IIA2, IIB–IVA: hóa xạ trị đồng thời cisplatin==; IVB: hóa trị. {{Y5 tr.64–69}}\n> - Diễn tiến chủ yếu tại chỗ, tại vùng; tử vong nhiều nhất do **suy thận sau thận** (chu cung siết niệu quản). {{Y5 tr.58}}\n> - Khung thi: [STT 87 Xuất huyết âm đạo–tử cung bất thường](#/khung/87), [STT 91 Khối vùng chậu](#/khung/91), [STT 92 Tầm soát ung thư cổ tử cung](#/khung/92).\n\n## 3. Bệnh học\n\n### Định nghĩa và dịch tễ\n@@tabs\n@@tab Thế giới\n- Globocan 2018: ung thư thường gặp **hàng thứ tư ở nữ**; ==569.847 ca mới== (chuẩn tuổi 13,1/100.000), ==311.365 tử vong== (6,9/100.000), cũng hàng thứ tư về tử vong. {{Y5 tr.56}}\n- Trên ==85%== ca mới ở nước đang phát triển (Châu Phi hạ Sahara, Mỹ La tinh, Nam Á, Đông Nam Á); ít ở nước giàu và nơi cắt bao quy đầu sớm cho bé trai. {{Y5 tr.56; SY5 tr.84}}\n- Tuổi thường gặp ==40–60==, trung bình 48–52. {{Y5 tr.56}}\n@@tab Việt Nam\n- Tần suất giảm **20,3 (2002) → 7,1/100.000 (2018)**; từ hàng đầu ở nữ xuống hàng thứ bảy; tử suất 11,2 → 4/100.000. {{Y5 tr.56}}\n- TP.HCM: 28,6 (1996) → 16,2/100.000 (2016), vẫn hàng thứ hai sau ung thư vú. {{Y5 tr.56}}\n- Slide (Globocan): 2002 – 6224 ca, 20,2/100.000, 3334 tử vong; 2008 – 5174 ca; 2012 – 5146 ca; 2018 – 4177 ca, 7,1, 2420 tử vong. {{SY5 tr.85}}\n- QĐ1514: sàng lọc tế bào học giảm 70% tử vong trong 30 năm. {{QĐ1514 tr.PDF 360}}\n@@end\n\n> [!warn] Khác biệt nguồn (dịch tễ)\n> Y5 ghi 20,3 và 11,2/100.000 cho 2002, slide ghi 20,2 và 10,6. QĐ1514 nói \"hàng thứ 2 sau ung thư vú ở nhiều nước\", Y5 nói hàng thứ tư toàn cầu. Thi theo giáo trình (Y5).\n\n> [!ext] Số liệu mới hơn của WHO: ~604.000 ca mới, ~280.000 tử vong năm 2024, hạng năm ở nữ. {{+WHO 2025}}\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab HPV (nguyên nhân)\n- DNA HPV trong ==99,7%== mô UTCTC (932 mẫu, 22 nước). {{Y5 tr.57}}\n- ~30–40 típ gây nhiễm sinh dục, **15–20 típ nguy cơ cao**: 16, 18, 31, 33, 35, 39, 45, 51, 52, 56, 58, 59, 66, 68, 73, 82. {{Y5 tr.57}}\n- Thứ tự gặp: 16, 18, 45, 31, 33, 52, 58; HPV 16 ~50%; 16+18 ~70%; 16, 18, 31, 45 > 80%. {{Y5 tr.57}}\n- HPV 6, 11 (không sinh ung): > 90% mụn cóc/mồng gà sinh dục. {{SY5 tr.86}}\n- HPV16 dương tính làm nguy cơ tăng 434 lần; DNA virút gắn vào bộ gen, ức chế **p53 và Rb**. {{SY5 tr.87}}\n@@tab Yếu tố thuận lợi\n- Lập gia đình sớm, sinh đẻ nhiều.\n- Quan hệ tình dục sớm, nhiều bạn tình (hoặc bạn tình nhiều người).\n- Thiếu vệ sinh sinh dục.\n- Hút thuốc lá, thiếu vitamin C, HSV-2, **HIV**. {{Y5 tr.57; SY5 tr.88}}\n@@end\n\n> [!warn] Mâu thuẫn Y5 và QĐ1514 về HPV\n> Y5: HPV trong 99,7% ca, 15–20 típ sinh ung, típ 6/11 **không** sinh ung. QĐ1514: HPV gây \"70% trường hợp\", 140 típ, 20 típ liên quan ung thư \"đặc biệt 6, 11, 16, 18\"; HPV16 liên quan vảy tế bào lớn, HPV18 liên quan ít biệt hóa và tuyến. {{QĐ1514 tr.PDF 361}} Khi thi chọn theo ngữ cảnh đề (giáo trình trường: Y5).\n\n### Sinh bệnh học và tổn thương tiền ung thư\n- Phần lớn xuất phát từ **vùng chuyển tiếp** (cổ ngoài–cổ trong, nối biểu mô gai–trụ). {{Y5 tr.57}}\n- HPV vào tế bào lớp đáy qua chỗ tổn thương; ==> 80%== nhiễm ban đầu tự khỏi trong 6 tháng; số còn lại nhiễm kéo dài → ức chế Rb, p53 → tiền ung thư sau vài năm. {{Y5 tr.57}}\n- Từ tiền ung thư đến xâm lấn: **hàng chục năm**. Mốc: nhiễm kéo dài 3–6 tháng; CIN 2/3 sau 4–5 năm; ung thư sau 9–15 năm; tuổi: nhiễm 20–25, CIN 2/3 hoặc AIS 32–35, ung thư 40–60. {{Y5 tr.60; SY5 tr.89, 91}}\n\n| CIN | Tế bào dị dạng chiếm | Ghi chú |\n|---|---|---|\n| CIN 1 | 1/3 dưới biểu mô | CIN grad thấp; 10 năm: 10% xâm lấn, 60% thoái triển |\n| CIN 2 | 2/3 dưới | Tiền ung thư (grad cao) |\n| CIN 3 | Toàn bộ chiều dày; = carcinôm tại chỗ (Cis) | Grad cao; > 30% xâm lấn, 25% thoái triển |\n\n*(Y5 tr.59; SY5 tr.91)*\n\n@@fold Phân loại Bethesda cho Pap (TBS 2014)\n- Không tổn thương trong biểu mô/không ác tính (viêm, phản ứng, nhiễm trùng).\n- Tế bào gai: **ASC-US**, **ASC-H**, **LSIL**, **HSIL**, carcinôm tế bào gai.\n- Tế bào tuyến: không điển hình; carcinôm tuyến cổ trong tại chỗ (AIS); carcinôm tuyến.\n- {r|Từ ASC-H trở lên: soi cổ tử cung.} {{Y5 tr.59–60; SY5 tr.107}}\n@@end\n\n### Giải phẫu bệnh\n- **Đại thể**: sùi (như bông cải), loét, thâm nhiễm/ăn cứng (CTC giữ hình dạng nhưng cứng); muộn có thể phối hợp. {{Y5 tr.58}}\n- **Vi thể (Y5)**: carcinôm tế bào **gai 80–85%** (biệt hóa cao/vừa); **tuyến 15–20%** (nhầy, tế bào sáng…); tế bào nhỏ thần kinh nội tiết 1–2% (di căn xa rất cao); hiếm sarcôm, lymphôm, mêlanôm. {{Y5 tr.58–59; SY5 tr.93}}\n\n> [!warn] Mâu thuẫn tỉ lệ vảy\n> Y5: gai 80–85%. QĐ1514: biểu mô vảy **trên 90%**. {{QĐ1514 tr.PDF 362}} Ghi cả hai.\n\n### Diễn tiến tự nhiên – lan tràn\n| Hướng | Đặc điểm |\n|---|---|\n| Xuống túi cùng, âm đạo | Thường gặp nhất |\n| Lên thân tử cung | Thường gặp |\n| **Sang bên: chu cung, vách chậu** | {r|Thường gặp và nguy hiểm nhất}: siết niệu quản → thận ứ nước, vô niệu, suy thận |\n| Trước (bàng quang), sau (trực tràng) | Ít gặp, muộn; gieo rắc phúc mạc rất hiếm |\n| Hạch | Chậu ngoài, chậu trong → bịt, chậu chung, cạnh ĐM chủ bụng → trung thất, trên đòn; 1/3 dưới âm đạo → hạch bẹn |\n| Di căn xa (~5%) | Phổi, gan, xương |\n\n*(Y5 tr.58; SY5 tr.94–95)* Nền tảng: [[ung-thu-xam-lan-di-can]], [[ung-thu-co-che-sinh-ung]].\n\n## 4. Triệu chứng học\n\n> [!key] Triệu chứng hay gặp nhất: xuất huyết âm đạo bất thường; có thể hoàn toàn không triệu chứng ở giai đoạn sớm (phát hiện nhờ tầm soát). {{Y5 tr.61}}\n\n@@tabs\n@@tab Sớm / thường gặp\n- **Xuất huyết âm đạo**: sau giao hợp, sau mãn kinh, giữa hai kỳ kinh, hành kinh kéo dài; máu đỏ tươi, ít–vừa, có thể có máu cục. {{Y5 tr.61}}\n- **Huyết trắng/ra dịch**: ban đầu ít, rỉ rả, tăng dần, về sau hôi do hoại tử/bội nhiễm, đôi khi lẫn máu. {{Y5 tr.61}}\n- QĐ1514 thêm: ra máu **sau đại tiện gắng sức**; đau hạ vị, đau ngang thắt lưng. {{QĐ1514 tr.PDF 360}}\n@@tab Muộn\n- Huyết trắng lẫn máu hôi; đau bụng dưới.\n- Phù chân/mặt, tiểu ít (**tăng urê máu** do tắc niệu quản, suy thận).\n- **Dò** bàng quang–âm đạo, trực tràng–âm đạo (nước tiểu/phân ra âm đạo).\n- Biếng ăn, sụt cân; hạch trên đòn, hạch bẹn. {{Y5 tr.61}}\n@@end\n\n> [!red] Dấu hiệu báo động\n> Xuất huyết âm đạo nhiều gây thiếu máu cấp (cấp cứu); suy thận cấp/vô niệu do tắc niệu quản; dò phân/nước tiểu ra âm đạo. Xuất huyết âm đạo bất thường phải **khám phụ khoa ngay**, không chần chờ. {{Y5 tr.61}}\n\n### Khám lâm sàng\n- Hỏi bệnh sử; **mỏ vịt** (âm hộ, âm đạo, túi cùng, CTC); **khám tay** phối hợp thăm trực tràng (thân tử cung, chu cung, vách âm đạo–trực tràng, xâm lấn chậu); hạch bẹn, trên đòn; toàn thân. {{Y5 tr.62; SY5 tr.97}}\n- QĐ1514: mô tả u sùi/loét/sùi loét/thâm nhiễm, kích thước, xâm lấn âm đạo/túi cùng; **thăm trực tràng** đánh giá dây chằng rộng; u không rõ thì nạo/hút ống CTC. {{QĐ1514 tr.PDF 360}}\n\n### Liên hệ khung 128 vấn đề\n| STT | Vấn đề | Cần nghĩ tới ung thư CTC khi |\n|---|---|---|\n| [87](#/khung/87) | Xuất huyết âm đạo–tử cung bất thường (sách mục 91, 92) | Chảy máu sau giao hợp/sau mãn kinh/giữa kỳ kinh; CTC sùi, loét, dễ chảy máu |\n| [91](#/khung/91) | Khối vùng chậu (sách mục 96) | UTCTC lan chu cung, vách chậu, hạch chậu; nội mạc, buồng trứng, trực tràng xâm lấn |\n| [92](#/khung/92) | Tầm soát ung thư CTC/Pap (sách mục 97) | Phụ nữ không triệu chứng: xem mục 8 |\n\nHub chi tiết: [xuất huyết âm đạo bất thường](#/n/ung-thu-cotucung/4), [khối vùng chậu](#/n/ung-thu-cotucung/4), [tầm soát cổ tử cung](#/n/ung-thu-cotucung/8).\n\n## 5. Cận lâm sàng\n\n### Giải phẫu bệnh – chẩn đoán xác định\n- **Sinh thiết** bằng kềm bấm, lấy ở **bờ tổn thương**, tránh vùng hoại tử; **không cần gây tê** (CTC không có thần kinh cảm giác đau); chảy máu cầm bằng nhét gạc; nghi ngờ thì sinh thiết lại. {{Y5 tr.62; SY5 tr.98}}\n- QĐ1514: sinh thiết rìa u; Pap nghi ngờ → **soi CTC + sinh thiết**; **khoét chóp** vừa chẩn đoán vừa điều trị giai đoạn tại chỗ; nghiệm pháp **Schiller (Lugol)**: vùng không bắt màu nâu → sinh thiết. {{QĐ1514 tr.PDF 360–361}}\n\n### Hình ảnh – xét nghiệm đánh giá xâm lấn và di căn\n| Phương tiện | Vai trò |\n|---|---|\n| Siêu âm bụng | Bướu CTC, thân tử cung, bàng quang, hạch, gan, **thận ứ nước**, dịch ổ bụng |\n| CT/MRI bụng chậu | Kích thước, xâm lấn chậu, hạch; ==MRI tốt nhất đánh giá bướu==; hạch CT ≈ MRI (nhạy 50–60%, đặc hiệu 90–95%); khuyến cáo làm thường quy |\n| PET/CT | ==Tốt nhất đánh giá hạch== (nhạy > 80%, đặc hiệu > 95%) và di căn xa; khi nghi di căn xa/đã có hạch |\n| X quang ngực | Di căn phổi |\n| Soi bàng quang, soi trực tràng | Khi nghi xâm lấn (tiểu máu, mót rặn, dò) hoặc giai đoạn trễ IIIB |\n| Xạ hình xương | Đau xương nghi di căn |\n| Thường quy | Công thức máu, chức năng gan thận, ECG, nước tiểu |\n\n*(Y5 tr.63; SY5 tr.99)* QĐ1514 thêm: CEA, CA12-5, **SCC** (theo dõi đáp ứng/tái phát), SPECT xương 99mTc-MDP, xạ hình thận 99mTc-DTPA, PET/CT 18F-FDG, giải trình tự nhiều gen. {{QĐ1514 tr.PDF 361, 365}}\n\n### Phân giai đoạn FIGO 2018\n@@tabs\n@@tab Giai đoạn I\n| Giai đoạn | Định nghĩa (Y5) |\n|---|---|\n| I | Bướu khu trú ở CTC |\n| IA | Xâm lấn chỉ thấy trên vi thể, sâu tối đa < 5 mm |\n| IA1 | Mô đệm < 3 mm |\n| IA2 | ≥ 3 và < 5 mm |\n| IB | Sâu ≥ 5 mm, còn ở CTC |\n| IB1 / IB2 / IB3 | Bướu lớn nhất < 2 cm / ≥ 2 và < 4 cm / ≥ 4 cm |\n\nTổn thương nhìn thấy được (kể cả xâm lấn bề mặt) xếp IB. {{Y5 tr.64}}\n@@tab Giai đoạn II\n| Giai đoạn | Định nghĩa |\n|---|---|\n| II | Xâm lấn quá CTC vào chu cung (chưa tới vách chậu) hoặc âm đạo chưa tới 1/3 dưới |\n| IIA1 / IIA2 | Không xâm lấn chu cung; bướu < 4 cm / ≥ 4 cm |\n| IIB | Có xâm lấn chu cung |\n\n{{Y5 tr.64–65}}\n@@tab Giai đoạn III\n| Giai đoạn | Định nghĩa |\n|---|---|\n| IIIA | Lan 1/3 dưới âm đạo, chưa tới vách chậu |\n| IIIB | Lan tới vách chậu và/hoặc **thận ứ nước/mất chức năng** |\n| IIIC1 | Di căn hạch **chậu** (r: hình ảnh; p: GPB) |\n| IIIC2 | Di căn hạch **cạnh ĐM chủ bụng** |\n\n{{Y5 tr.65}}\n@@tab Giai đoạn IV\n| Giai đoạn | Định nghĩa |\n|---|---|\n| IVA | Xâm lấn niêm mạc bàng quang/trực tràng và/hoặc lan xa hơn vùng chậu |\n| IVB | Di căn xa |\n\nHạch **trung thất, trên đòn, bẹn** = di căn xa; hạch vùng: quanh CTC, chu cung, bịt, trước xương cùng, chậu ngoài/trong/chung, cạnh ĐM chủ bụng. {{Y5 tr.65–66}}\n@@end\n\n- **Nhóm giai đoạn (Y5)**: vi xâm lấn IA; xâm lấn sớm IB1, IB2, IIA1; **tiến xa tại chỗ** IB3, IIA2, IIB, IIIA, IIIB, IIIC1, IIIC2, IVA; di căn IVB. {{Y5 tr.65}}\n\n@@fold TNM – bảng QĐ1514 (FIGO 2018 + AJCC 2017)\n| TNM | FIGO | Tổn thương |\n|---|---|---|\n| Tis | 0 | Tại chỗ |\n| T1a1 / T1a2 | IA1 / IA2 | Sâu ≤ 3 mm / ≤ 5 mm, rộng ≤ 7 mm |\n| T1b | IB | Khu trú CTC, lớn hơn IA2; IB1 ≤ 2 cm, IB2 2–4 cm, IB3 > 4 cm |\n| T2a / T2b | IIA / IIB | Chưa / đã xâm lấn dây chằng rộng; IIA1 ≤ 4 cm, IIA2 > 4 cm |\n| T3a / T3b | IIIA / IIIB | 1/3 dưới âm đạo / vách chậu, ứ nước thận |\n| T4 | IVA | Bàng quang, trực tràng (GPB) hoặc ngoài khung chậu |\n| M1 | IVB | Di căn xa (phúc mạc, hạch ĐM chủ, trung thất, thượng đòn, gan, phổi, xương) |\n\nN0 / N0(i+) (≤ 0,2 mm) / N1. Bảng nhóm QĐ1514 xếp theo T, M; **không có IIIC**. {{QĐ1514 tr.PDF 362–363}}\n@@end\n\n> [!warn] Mâu thuẫn và lỗi in\n> - **Ngưỡng FIGO**: Y5 dùng \"< 2 cm\", \"< 3 mm\", \"< 4 cm\"; QĐ1514 dùng \"≤ 2 cm\", \"≤ 3 mm\", \"≤ 4 cm\" (IB2 \"2–4 cm\"). Khi thi lưu ý đề dựa nguồn nào.\n> - **IIIA**: bảng TNM Y5 ghi \"T2aN0M0\", trùng IIA ngay trong giáo trình, nghi lỗi in; theo QĐ1514 IIIA = **T3a**. {{Y5 tr.65–66}}\n> - IIIC (di căn hạch) có trong Y5 (FIGO 2018) nhưng **không có** trong bảng nhóm QĐ1514.\n\n> [!ext] Phân giai đoạn FIGO 2018 theo NCI PDQ\n> Giai đoạn FIGO 2018 cho phép dùng hình ảnh và bệnh học để xếp giai đoạn; di căn hạch tự động là IIIC. Tóm tắt điều trị theo giai đoạn của NCI khớp với bảng Y5 (mục 7). {{+NCI PDQ 2025}}\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Chẩn đoán xác định\n> **Giải phẫu bệnh** từ sinh thiết (hoặc khoét chóp) ở bệnh nhân có tổn thương nghi ngờ/Pap bất thường; sau đó **xếp giai đoạn FIGO 2018** bằng khám phụ khoa + MRI/CT/PET-CT ± soi bàng quang–trực tràng. {{Y5 tr.62–66}}\n\n- **Nhóm điều trị theo giai đoạn**: vi xâm lấn (IA); xâm lấn sớm (IB1, IB2, IIA1); tiến xa tại chỗ (IB3, IIA2, IIB–IVA); di căn (IVB). {{Y5 tr.65}}\n- **Chẩn đoán sớm khi tầm soát bất thường** (Pap ≥ ASC-H, HPV 16/18 (+), nghi ngờ khi khám): soi CTC + sinh thiết; nạo cổ trong; khoét chóp. {{Y5 tr.73}}\n\n### Bảng chẩn đoán phân biệt\n| Bệnh lý | Điểm giống | Điểm phân biệt | Nguồn |\n|---|---|---|---|\n| Viêm lộ tuyến, loét CTC (sớm); lộ tuyến nhiễm khuẩn | Chảy máu tiếp xúc, huyết trắng, CTC loét | Pap/sinh thiết không có tế bào ác tính | {{QĐ1514 tr.PDF 361}} |\n| Polyp CTC, u nhú CTC, mồng gà | Khối sùi, dễ chảy máu | Sinh thiết GPB | {{Y5 tr.63; QĐ1514 tr.PDF 361}} |\n| Lao CTC, giang mai CTC | Loét, sùi muộn | Sinh thiết, tìm tác nhân | {{QĐ1514 tr.PDF 361}} |\n| Sa sinh dục | Loét CTC, có thể kèm ung thư | Sinh thiết vùng loét | {{Y5 tr.63}} |\n| Ung thư nội mạc tử cung | Xuất huyết, xâm lấn CTC | Sinh thiết nội mạc/nạo; hình ảnh nguồn gốc u từ thân | {{Y5 tr.63; 128VĐ mục 91–92}} |\n| Ung thư buồng trứng, trực tràng xâm lấn CTC | Khối vùng chậu, xâm lấn | Hình ảnh, nội soi, GPB; IOTA/O-RADS cho u buồng trứng | {{Y5 tr.63; 128VĐ mục 96}} |\n| Nguyên nhân AUB khác (PALM-COEIN: polyp, adenomyosis, u xơ, tăng sinh nội mạc, rối loạn đông máu, phóng noãn, thuốc) | Xuất huyết tử cung bất thường | Khám mỏ vịt (CTC bình thường), siêu âm, xét nghiệm đông máu, nội tiết | {{128VĐ mục 92}} |\n\nChẩn đoán phân biệt chủ yếu dựa vào khám lâm sàng và **giải phẫu bệnh**; cần thì sinh thiết lại, hội chẩn, hóa mô miễn dịch. {{Y5 tr.63–64}}\n\n> [!ext] Bổ sung ngoài tài liệu\n> Ở phụ nữ có xuất huyết bất thường, cần loại trừ **thai kỳ** trước, đánh giá huyết động, và sinh thiết tổn thương nghi ung thư; tổn thương khó thấy bằng mắt thường hơn khi ung thư tuyến nằm trong ống cổ. (Tổng hợp kiến thức lâm sàng chung, thống nhất với 128VĐ mục 91–92; chưa đối chiếu một nguồn ngoài cụ thể.)\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n\n> [!key] Mục tiêu theo giai đoạn\n> - **Tiền ung thư/vi xâm lấn**: điều trị triệt để bảo tồn tối đa (khoét chóp, LEEP, cắt tử cung đơn giản), giữ khả năng sinh sản nếu cần. {{Y5 tr.67; QĐ1514 tr.PDF 363–364}}\n> - **Xâm lấn sớm (IA2, IB1, IB2, IIA1)**: **chữa khỏi** bằng phẫu thuật tận gốc hoặc xạ trị (kết quả tương đương), hạn chế phối hợp cả hai để giảm biến chứng. {{Y5 tr.69}}\n> - **Tiến xa tại chỗ (IB3, IIA2, IIB–IVA)**: chữa khỏi bằng **hóa xạ trị đồng thời**. {{Y5 tr.69}}\n> - **IVB/tái phát**: kéo dài sống còn, giảm triệu chứng (hóa trị ± bevacizumab/miễn dịch), săn sóc giảm nhẹ. {{Y5 tr.68–69; QĐ1514 tr.PDF 368–369}}\n\n- Nguyên tắc: bệnh chủ yếu **tại chỗ, tại vùng** nên **phẫu trị và xạ trị là mô thức chính**; hóa trị cho di căn, tái phát, hoặc phối hợp xạ/phẫu. {{Y5 tr.67; SY5 tr.113}}\n\n> [!ext] Mục tiêu theo NCI PDQ\n> NCI nêu khỏi bệnh là mục tiêu cho bệnh khu trú/tiến xa tại chỗ (IB1–IB2 cả hai cách đạt khoảng 85–90%); hóa xạ trị cisplatin làm giảm 30–50% nguy cơ tử vong do ung thư cổ tử cung; bệnh IVB/tái phát điều trị toàn thân, miễn dịch hoặc đoạn chậu khi đủ điều kiện. {{+NCI PDQ 2025}}\n\n### 7.2 Các phương pháp\n\n@@tabs\n@@tab Tiền ung thư – IA\n- **Tiền xâm nhập (QĐ1514)**: đốt lạnh, laser, **LEEP**, khoét chóp, cắt tử cung toàn bộ. {{QĐ1514 tr.PDF 363}}\n- **Khoét chóp**: tiền ung thư; IA1 ở phụ nữ trẻ muốn sinh con. **Cắt tử cung đơn giản**: tiền ung thư/IA1. {{Y5 tr.67; QĐ1514 tr.PDF 364}}\n- IA2: phẫu thuật tận gốc (cắt tử cung tận gốc + nạo hạch chậu) hoặc xạ áp sát (QĐ1514: xạ áp sát đơn thuần cho giai đoạn 0, IA1, IA2). {{Y5 tr.67; QĐ1514 tr.PDF 364}}\n@@tab IB1–IIA1 (xâm lấn sớm)\n- **Phẫu thuật tiêu chuẩn**: cắt tử cung tận gốc (**Wertheim**: cắt tử cung toàn phần + chu cung + mô cạnh âm đạo + 1/2–1/3 trên âm đạo) + nạo hạch chậu hai bên (**Meigs**); giữ hay cắt phần phụ tùy tuổi. {{Y5 tr.67}}\n- Bảo tồn sinh sản (bướu < 2 cm): cắt CTC tận gốc + nạo hạch chậu. {{Y5 tr.68}}\n- **Hoặc xạ đơn thuần** (xạ ngoài + xạ áp sát), **hoặc** xạ áp sát tiền phẫu (bướu 2–4 cm) + phẫu sau 4–6 tuần. {{Y5 tr.69}}\n- **Sau mổ**: nguy cơ **trung bình** (bướu > 4 cm; xâm lấn > 1/2 cơ CTC; xâm lấn khoang mạch/bạch huyết) → ==xạ bổ túc==; nguy cơ **cao** (di căn hạch IIIC1p; xâm lấn chu cung; diện cắt âm đạo còn bướu) → ==hóa xạ trị đồng thời==. {{Y5 tr.69}}\n@@tab IB3, IIA2, IIB–IVA\n- ==**Hóa xạ trị đồng thời**== là tiêu chuẩn; không hóa trị được → xạ trị đơn thuần. {{Y5 tr.69}}\n- **Xạ triệt để** = xạ ngoài (toàn chậu, 2–4 trường, Cobalt 60 hoặc máy gia tốc; IMRT/IGRT giảm liều mô lành) + **xạ trong/áp sát** (tăng liều tại bướu, giữ liều bàng quang, trực tràng). {{Y5 tr.68}}\n- QĐ1514: **IMRT không thay thế xạ áp sát**; dự phòng hạch 45 Gy. {{QĐ1514 tr.PDF 365–366}}\n- **Đoạn chậu** (trước/sau/toàn phần): bệnh khu trú chậu, tái phát/tồn tại sau xạ, không di căn xa. {{Y5 tr.67}}\n@@tab IVA – IVB, tái phát\n- IVA: còn mổ được → vét đáy chậu + hóa xạ trị; không mổ được → hóa xạ trị. {{QĐ1514 tr.PDF 369}}\n- **IVB**: hóa trị (cisplatin-based) ± **bevacizumab**; pembrolizumab cho PD-L1 dương tính. {{Y5 tr.68–69; QĐ1514 tr.PDF 368–369}}\n- **Giảm nhẹ**: mở niệu quản ra da (dò bàng quang–âm đạo, thận ứ nước, suy thận), mở đại tràng ra da (dò trực tràng–âm đạo, tắc ruột); xạ trị triệu chứng 30–50 Gy cho chèn ép/chảy máu; di căn xương: thuốc chống hủy xương + xạ giảm đau; di căn não: xạ phẫu. {{Y5 tr.67–68; QĐ1514 tr.PDF 369}}\n@@tab Thể đặc biệt\n- **Carcinôm tế bào nhỏ thần kinh nội tiết**: hóa trị quan trọng, **cisplatin + etoposide mỗi 3 tuần**; sớm: mổ đầu tiên rồi 4 chu kỳ cisplatin + etoposide ± xạ bổ túc; không mổ được/tiến xa: hóa xạ trị đồng thời. {{Y5 tr.69–70}}\n- **Lymphôm CTC**: hóa trị như lymphôm + xạ trị. **Mêlanôm ác**: mổ nếu được + xạ bổ túc; xạ đơn thuần phân liều cao, tổng liều tới 90 Gy. {{Y5 tr.70}}\n@@end\n\n@@fold Chi tiết xạ trị theo QĐ1514\n- Xạ triệt căn đơn thuần: giai đoạn 0, I, IIA, IIB; xạ áp sát đơn thuần 0, IA1, IA2; xạ ngoài + áp sát IIA, IIB.\n- Tổng liều: xạ ngoài **50 Gy** tiểu khung + áp sát tử cung–âm đạo **20 Gy**.\n- Tiền phẫu IB, IIA: < 4 cm xạ áp sát 60 Gy điểm A, Wertheim sau 6 tuần; > 4 cm xạ ngoài chậu 20–30 Gy + áp sát 65–70 Gy điểm A.\n- Hậu phẫu (hạch, diện cắt dây chằng rộng/âm đạo dương): áp sát mỏm cụt 25–30 Gy hoặc xạ ngoài 30–50 Gy; nâng liều hạch chậu 50–55 Gy.\n- EBRT: dự phòng hạch **45 Gy** (1,8–2,0 Gy/ngày); hạch di căn không mổ được thêm 10–15 Gy; mở rộng đến ĐM thận nếu hạch chậu chung/cạnh ĐM chủ.\n- IORT: một liều duy nhất ở nền u sau mổ/u không cắt hết/tái phát. {{QĐ1514 tr.PDF 364–366}}\n@@end\n\n> [!warn] Y5 và QĐ1514 khác nhau ở phẫu thuật\n> Y5: phẫu thuật tiêu chuẩn cho IA2, IB1, IIA1. QĐ1514: Wertheim Meigs \"giai đoạn I, IIa\" gồm cắt tử cung + **2 phần phụ** + vét hạch chậu; khoét chóp chỉ IA1 ở người trẻ muốn sinh con. QĐ1514 còn cho xạ trị đơn thuần cả giai đoạn IIB.\n\n### 7.3 Phác đồ – Y lệnh\n\n> [!doc] Văn bản Bộ Y tế\n> **QĐ 1514/QĐ-BYT ngày 01/04/2020**, Bài 44, tr. PDF 363–369 (liều chép đúng văn bản). Chỉ định hóa trị: giai đoạn IIB, III, IV; từ chối mổ/xạ. Hóa chất đơn thuần: IVB; tiền phẫu: IIB; hậu phẫu (hạch, diện cắt dương) kết hợp xạ; kết hợp xạ trị: IIB, III, IV (IB2, IIA từ chối mổ có thể cân nhắc).\n\n@@tabs\n@@tab Hóa xạ trị đồng thời (tiêu chuẩn)\n| Phác đồ | Thuốc – liều | Chu kỳ/cách dùng | Chỉ định | Ghi chú |\n|---|---|---|---|---|\n| {p|Cisplatin hàng tuần} + xạ ngoài | Cisplatin ==40 mg/m2== TM | Hàng tuần x **5 tuần** (Y5: 5–6 chu kỳ) | IB3, IIA2, IIB–IVA; bổ túc sau mổ nguy cơ cao; không mổ được | Tiêu chuẩn |\n| {p|PF} + xạ | Cisplatin 75 mg/m2 ngày 1 + 5-FU 750 mg/m2 ngày 1–5 | 21 ngày | Không mổ được | Thay thế cisplatin đơn |\n| Capecitabine + xạ | 825 mg/m2/lần x 2 lần/ngày, ngày 1–5 | 21 ngày | Kết hợp xạ | |\n| Cisplatin đơn | 50 mg/m2 TM ngày 1 | 21 ngày | Hóa trị đơn | |\n\n{{Y5 tr.68–69; QĐ1514 tr.PDF 365–367}}\n@@tab Hóa trị đơn chất\n| Thuốc | Liều | Chu kỳ |\n|---|---|---|\n| Cisplatin | 50 mg/m2 TM ngày 1 | 21 ngày |\n| Capecitabine | 1.000–1.250 mg/m2/lần x 2 lần/ngày, ngày 1–14 | 21 ngày |\n| UFT | 100–125 mg/m2 uống x 3 lần/ngày, ngày 1–14 | 21 ngày |\n| Docetaxel | 100 mg/m2 TM ngày 1 | 21 ngày |\n| Paclitaxel | 175 mg/m2 TM ngày 1 | 21 ngày |\n| Vinorelbine | 30 mg/m2 TM ngày 1, 8 (hoặc 60–80 mg/m2 uống) | 21 ngày |\n| Topotecan | 1,5 mg/m2 TM | 3–4 tuần |\n| Irinotecan | 125 mg/m2 TM ngày 1, 8, 15, 28 | 42 ngày |\n| Pemetrexed | 900 mg/m2 TM ngày 1 | 21 ngày |\n| Gemcitabine | 800 mg/m2 TM ngày 1, 8, 15 | 21 ngày |\n| 5-FU/Leucovorin | 5-FU 370 + leucovorin 200 mg/m2 TM bolus | 4 tuần |\n\n{{QĐ1514 tr.PDF 366–367}}\n@@tab Đa hóa trị\n| Phác đồ | Thuốc – liều | Chu kỳ | Ghi chú |\n|---|---|---|---|\n| Gemcitabine–cisplatin | Cisplatin 30 mg/m2 ngày 1, 8 + gemcitabine 800 mg/m2 ngày 1, 8 | 28 ngày | |\n| PF | Cisplatin 50–75 mg/m2 ngày 1 + 5-FU 750–1.000 mg/m2 ngày 1–4 | 21–28 ngày | Có thể kèm xạ |\n| {p|PC} (a) | Paclitaxel 135 mg/m2 TM 24 giờ ngày 1 + cisplatin 50–75 mg/m2 ngày 2 | 21 ngày | |\n| PC (b) | Paclitaxel 175 mg/m2 + cisplatin 75 mg/m2, ngày 1 | 21 ngày | **Phác đồ chuẩn** cho tái phát/di căn (Y5) |\n| PC (c) | Paclitaxel 175 mg/m2 + carboplatin 300 mg/m2, ngày 1 | 21 ngày | |\n| Topotecan–cisplatin | Topotecan 0,75 mg/m2 TM 30 phút ngày 1–3 + cisplatin 50 mg/m2 ngày 1 | 21 ngày | |\n| Topotecan–paclitaxel | Topotecan 0,75 mg/m2 ngày 1–3 + paclitaxel 175 mg/m2 ngày 1 | 21 ngày | |\n| Vinorelbine–cisplatin | Vinorelbine 30 mg/m2 TM (hoặc 60–80 mg/m2 uống) hàng tuần + cisplatin 75 mg/m2 TM 4 giờ ngày 1 | 28 ngày | |\n| **EP** | Etoposide 40 mg/m2 + cisplatin 25 mg/m2, ngày 1–5 | 2 tuần (văn bản gốc) | Tế bào nhỏ thần kinh nội tiết (Y5: mỗi 3 tuần) |\n| IP (a) | Ifosfamide 5.000 mg/m2 TM 24 giờ + cisplatin 50 mg/m2, ngày 1 | 21 ngày | Dùng **mesna** |\n| IP (b) | Cisplatin 20 mg/m2 + ifosfamide 1.200 mg/m2, ngày 1–5 | 21 ngày | |\n| IP (c) | Ifosfamide 5.000 mg/m2 24 giờ + carboplatin 300 mg/m2, ngày 1 | 28 ngày | |\n| TIP | Paclitaxel 175 ngày 1 + cisplatin 50 ngày 1 + ifosfamide 5.000 mg/m2 24 giờ ngày 2 | 28 ngày | |\n\n{{QĐ1514 tr.PDF 367–368}}\n@@tab Điều trị đích – miễn dịch\n| Phác đồ | Thuốc – liều | Chu kỳ | Chỉ định |\n|---|---|---|---|\n| Bevacizumab | **15 mg/kg** TM phối hợp hóa chất | Mỗi 3 tuần, đến khi tiến triển/không dung nạp | UTCTC dai dẳng, tái phát, di căn |\n| {p|BPC} | Bevacizumab 15 mg/kg + paclitaxel 175 mg/m2 + cisplatin 50 mg/m2, ngày 1 | 21 ngày | Như trên (GOG 240: sống còn ~17 tháng vs 10–13 tháng) |\n| {p|BTP} | Bevacizumab 15 mg/kg ngày 1 + topotecan 0,75 mg/m2 ngày 1–3 + paclitaxel 175 mg/m2 ngày 1 | 21 ngày | Như trên |\n| Pembrolizumab | Văn bản ghi \"200 mg/m2 TM ngày 1\" (chép đúng) | 21 ngày, tới 2 năm | PD-L1 (+), tái phát/di căn/tiến triển sau hóa trị (FDA 6/2018) |\n\n{{QĐ1514 tr.PDF 368–369; Y5 tr.68}}\n@@end\n\n> [!warn] Theo dõi và tác dụng phụ cần nhớ\n> - **Ifosfamide phải kèm mesna** 50–100% liều ifosfamide, truyền trước và sau. {{QĐ1514 tr.PDF 368}}\n> - Cisplatin: độc thận, buồn nôn–nôn; theo dõi chức năng thận, công thức máu mỗi chu kỳ. (Chung, tài liệu không nêu riêng.)\n> - Bevacizumab (kháng VEGF): thận trọng khi có nguy cơ rò/tắc ruột, chảy máu (kiến thức chung, tài liệu BYT không nêu chi tiết).\n> - Pembrolizumab: đơn vị \"mg/m2\" là chép nguyên văn QĐ1514, cần đối chiếu nhãn thuốc khi áp dụng.\n\n> [!warn] Mâu thuẫn Y5 và QĐ1514 về phác đồ\n> Cisplatin hàng tuần: Y5 \"5–6 chu kỳ\", QĐ1514 \"x 5 tuần\". EP: Y5 \"mỗi 3 tuần\", QĐ1514 \"chu kỳ 2 tuần\".\n\n> [!ext] Tham khảo (không phải văn bản BYT)\n> NCI PDQ: hóa xạ trị đồng thời có cisplatin là tiêu chuẩn cho IB3, IIA2–IVA; bệnh IVB/tái phát dùng miễn dịch hoặc hóa trị giảm nhẹ, đoạn chậu khi phù hợp. {{+NCI PDQ 2025}}\n\n## 8. Tiên lượng – Dự phòng\n\n### Tiên lượng\n@@tabs\n@@tab Sống còn\n| Giai đoạn | Sống còn 5 năm (Y5 tr.70) |\n|---|---|\n| I | ==80–90%== |\n| II | 50–65% |\n| III | 25–35% |\n| IV | 0–15% |\n\n- BV Ung Bướu TP.HCM (sống còn không bệnh 5 năm): IB1+IB2 88%; IIA1 70%; IB3 50–60%; IIB 63%; IIIB 40%; ~65% ca đến ở giai đoạn tiến xa, hay gặp nhất IIB. {{Y5 tr.74}}\n@@tab Yếu tố tiên lượng\n- **Giai đoạn**, **kích thước bướu** (độc lập), **di căn hạch** (số lượng, vị trí, kích thước).\n- Xâm nhiễm sâu mô đệm, chu cung, khoang mạch.\n- GPB xấu: không biệt hóa, tế bào nhỏ thần kinh nội tiết, mêlanôm; carcinôm tuyến grad cao.\n- **Hb thấp** (giảm hiệu quả xạ); tuổi < 30 (một số nghiên cứu). {{Y5 tr.70}}\n@@end\n\n### Theo dõi sau điều trị\n- Y5: mỗi **3 tháng x 2 năm đầu**, mỗi 6 tháng x 3 năm tiếp, sau 5 năm mỗi năm. {{Y5 tr.70}}\n- QĐ1514: mỗi **3 tháng x 5 năm đầu**, sau đó mỗi năm (lâm sàng, cận lâm sàng, phụ khoa). {{QĐ1514 tr.PDF 370}}\n- ==80% tái phát trong 2–3 năm đầu==; bướu lớn tái phát sớm hơn. {{Y5 tr.70}}\n\n> [!ext] Theo dõi theo NCI PDQ\n> Khám mỗi 3–4 tháng trong 2 năm đầu rồi mỗi 6 tháng; đa số tái phát trong 2 năm đầu và thường được phát hiện nhờ triệu chứng mới của bệnh nhân. Hơi khác lịch Y5 và QĐ1514 (ưu tiên BYT). {{+NCI PDQ 2025}}\n\n### Dự phòng\n@@tabs\n@@tab Cấp 1: vắc xin HPV\n- Cấp phép từ 2006; típ 16, 18 > 70% UTCTC. {{Y5 tr.71}}\n- **Tứ giá** (6, 11, 16, 18): nữ 9–26 tuổi; **nhị giá** (16, 18): nữ 10–25; **chín giá** (6, 11, 16, 18, 31, 33, 45, 52, 58): nam/nữ 9–45 tuổi (nước cấp phép). VN: tứ giá và nhị giá từ 2007. {{Y5 tr.71; SY5 tr.115}}\n- Vắc xin VLP (vỏ L1, không có bộ gen virút). {{SY5 tr.114}}\n- Lịch ==3 liều trong 6 tháng==; trước 15 tuổi có thể 2 liều cách 6 tháng. {{Y5 tr.71}}\n- **Đã tiêm vẫn phải tầm soát**. QĐ1514: tiêm cho nữ 9–25 tuổi. {{Y5 tr.71, 74; QĐ1514 tr.PDF 369}}\n- Khác: hạn chế quan hệ sớm/nhiều bạn tình, vệ sinh sinh dục.\n@@tab Cấp 2: tầm soát\n- Giảm tần suất và tử suất 40–80%; là xét nghiệm **tầm soát**, không phải chẩn đoán; chỉ hiệu quả khi tổn thương tiền ung thư được điều trị. {{SY5 tr.105; Y5 tr.72}}\n\n| | Pap | HPV-DNA | VIA |\n|---|---|---|---|\n| Ưu | Rẻ, đơn giản, chi phí–hiệu quả | VPP âm rất cao; giãn khoảng cách 5–10 năm; tự lấy mẫu | Đơn giản, rẻ, có kết quả ngay |\n| Nhược | Cần đào tạo; âm tính giả nên phải định kỳ | Dương tính cao ở người trẻ; chi phí | Dương tính giả → điều trị quá mức |\n| Nhạy/đặc hiệu (Y5) | 50–60%/90–95% | Nhạy tới 90% | 81%/83% |\n| Theo slide | 37–84%/86–100% | > 90% | 65–96%/64–98% |\n\n{{Y5 tr.72; SY5 tr.106–109}} (hai nguồn khác nhau, ghi cả hai.)\n- **Lịch ACS/ACOG 2012**: từ **21 tuổi**; 21–29: Pap mỗi 3 năm; 30–65: HPV + tế bào học mỗi 5 năm (ưu tiên) hoặc Pap mỗi 3 năm; ngưng sau 65 nếu tiền căn đủ. 2016: đề xuất HPV DNA làm xét nghiệm chính từ 25 tuổi mỗi 5 năm. {{Y5 tr.72–73; SY5 tr.110}}\n- Xử trí bất thường: **Pap ≥ ASC-H hoặc HPV 16/18 (+)** → soi CTC + sinh thiết; Pap cổ trong bất thường → nạo cổ trong; khoét chóp vừa chẩn đoán vừa điều trị (CIN 3/ung thư tại chỗ khoét đủ; xâm lấn màng đáy phải điều trị tiếp). {{Y5 tr.73}}\n- Nơi chưa đủ điều kiện Pap cộng đồng: **VIA** tăng độ phủ; người lấy mẫu có thể là điều dưỡng/nữ hộ sinh được huấn luyện (WHO). {{Y5 tr.73–74}}\n@@tab Theo nguồn lực 2016 (slide)\n| Nguồn lực | Phương pháp | Số lần/đời | Tuổi |\n|---|---|---|---|\n| Tối đa | HPV | 9 | 25–64, mỗi 5 năm |\n| Nâng cao | HPV | 5 | 30–64 |\n| Hạn chế | HPV | 2–3 | 30–49, mỗi 10 năm |\n| Cơ bản | HPV (VIA nếu chưa có) | 1–3 | 30–49 |\n\n{{SY5 tr.111}} (bố cục cột đọc từ text, chưa chắc chắn.)\n@@end\n\n> [!ext] WHO (khuyến cáo và mục tiêu loại trừ)\n> - Mục tiêu 2030 **90-70-90**: 90% bé gái tiêm HPV trước 15 tuổi; 70% phụ nữ sàng lọc bằng xét nghiệm hiệu năng cao ở tuổi 35 và 45; 90% tổn thương tiền ung thư/ung thư được điều trị. {{+WHO 2025}}\n> - Sàng lọc từ 30 tuổi, mỗi 5–10 năm (HPV); phụ nữ HIV từ 25 tuổi, mỗi 3–5 năm; tự lấy mẫu HPV cho độ tin cậy tương đương. Tiêm ưu tiên nữ 9–14 tuổi, 1–2 liều. {{+WHO 2025}}\n> - **Khác Y5/QĐ1514**: giáo trình (ACS/ACOG 2012) bắt đầu 21 tuổi bằng Pap, 3 liều vắc xin, 9–26 tuổi; ưu tiên BYT/giáo trình khi thi nhưng nêu cả hai.\n\n> [!warn] Mâu thuẫn tuổi vắc xin\n> Y5 tứ giá 9–26 tuổi (một số nước 26–45), nhị giá 10–25; QĐ1514 \"trẻ em gái 9–25 tuổi\"; WHO ưu tiên 9–14 tuổi.\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] Bệnh này thi nhấn mạnh gì\n> - Khung thi: [STT 87](#/khung/87) (xuất huyết âm đạo–tử cung), [STT 91](#/khung/91) (khối vùng chậu), [STT 92](#/khung/92) (**tầm soát**). Nhóm tầm soát: nhấn mạnh ==sàng lọc==, xử trí kết quả bất thường.\n> - Trọng số thi: **chẩn đoán nặng nhất** (cận lâm sàng/chẩn đoán QĐ 22 45–60), rồi **xử trí** (35–50); câu từ mức Áp dụng trở lên là tình huống lâm sàng.\n> - Cách nghĩ: gặp xuất huyết âm đạo bất thường → khám mỏ vịt, **sinh thiết**; gặp Pap/HPV bất thường → soi CTC; có GPB → xếp **FIGO 2018** → chọn điều trị theo giai đoạn.\n> - Hay bị hỏi: sàng lọc, nguy cơ sau mổ, hóa xạ trị đồng thời cisplatin, và các chỗ Y5 khác QĐ1514 (xem hộp bẫy cuối mục).\n\n@@tabs\n@@tab Nhận diện\n- Nguyên nhân: **HPV nguy cơ cao kéo dài**; DNA HPV trong ==99,7%== ca; típ 16 ~50%, **16 + 18 ~70%**. {{Y5 tr.57}}\n- Từ nhiễm HPV đến ung thư **hàng chục năm** (CIN 2/3 sau 4–5 năm, ung thư sau 9–15 năm) → có thời gian để tầm soát. {{Y5 tr.60; SY5 tr.89}}\n- Yếu tố thuận lợi: quan hệ sớm, nhiều bạn tình, sinh đẻ nhiều, hút thuốc, **HIV**. {{Y5 tr.57}}\n- Triệu chứng gợi ý nhất: {r|xuất huyết âm đạo bất thường} (sau giao hợp, sau mãn kinh, giữa kỳ kinh); huyết trắng, về sau hôi. Sớm có thể **không triệu chứng**. {{Y5 tr.61}}\n- Muộn: phù chân, tiểu ít (suy thận), **dò** bàng quang/trực tràng–âm đạo, sụt cân. {{Y5 tr.61}}\n- {r|Báo động}: chảy máu nhiều gây thiếu máu cấp, vô niệu/suy thận do tắc niệu quản; tử vong chủ yếu do **suy thận sau thận**. {{Y5 tr.58, 61}}\n- Lan sang bên (chu cung, vách chậu) là thường gặp và nguy hiểm nhất. {{Y5 tr.58}}\n\n[xem mục 3](#/n/ung-thu-cotucung/3) · [xem mục 4](#/n/ung-thu-cotucung/4)\n@@tab Chẩn đoán\n- Xác định = **sinh thiết** ở bờ tổn thương, {g|không cần gây tê}; Pap nghi ngờ → soi CTC + sinh thiết; khoét chóp vừa chẩn đoán vừa điều trị. {{Y5 tr.62; QĐ1514 tr.PDF 360}}\n- Pap **≥ ASC-H** hoặc **HPV 16/18 (+)** → soi CTC + sinh thiết; Pap cổ trong bất thường → nạo cổ trong. {{Y5 tr.73}}\n- Đánh giá xâm lấn/di căn: ==MRI tốt nhất cho bướu==; ==PET/CT tốt nhất cho hạch== và di căn xa; siêu âm tìm thận ứ nước. {{Y5 tr.63}}\n- Soi bàng quang, trực tràng khi nghi xâm lấn (tiểu máu, mót rặn, dò). {{Y5 tr.63}}\n- FIGO 2018: IA1 < 3 mm, IA2 3–< 5 mm; IB1/IB2/IB3 theo 2 cm/4 cm; IIB xâm lấn chu cung; IIIB vách chậu/ứ nước thận; IIIC hạch (C1 chậu, C2 ĐM chủ); IVA bàng quang/trực tràng; IVB di căn xa. {{Y5 tr.64–65}}\n- Hạch **trung thất, trên đòn, bẹn** = di căn xa. {{Y5 tr.65}}\n- CĐPB chính: viêm lộ tuyến/loét CTC, polyp, lao–giang mai CTC, ung thư nội mạc tử cung, buồng trứng/trực tràng xâm lấn → phân biệt bằng **GPB**. {{Y5 tr.63}}\n\n[xem mục 5](#/n/ung-thu-cotucung/5) · [xem mục 6](#/n/ung-thu-cotucung/6)\n@@tab Điều trị\n- **Tiền ung thư, IA1**: khoét chóp/LEEP/cắt tử cung đơn giản (khoét chóp giữ sinh sản). {{Y5 tr.67; QĐ1514 tr.PDF 363–364}}\n- **IA2, IB1–IIA1**: {g|Wertheim–Meigs} (cắt tử cung tận gốc + nạo hạch chậu) **hoặc xạ trị**, kết quả tương đương. {{Y5 tr.67, 69}}\n- **IB3, IIA2, IIB–IVA**: ==hóa xạ trị đồng thời== là tiêu chuẩn; không hóa trị được → xạ đơn thuần. {{Y5 tr.69}}\n- {p|Cisplatin} ==40 mg/m2== TM hàng tuần x **5 tuần** + xạ ngoài (QĐ1514); thay thế {p|PF}: cisplatin 75 + 5-FU 750 mg/m2, 21 ngày. {{QĐ1514 tr.PDF 365–367}}\n- **Sau mổ**: nguy cơ trung bình (bướu > 4 cm, xâm lấn > 1/2 cơ CTC, mạch) → xạ bổ túc; **cao** (hạch, chu cung, diện cắt âm đạo) → hóa xạ đồng thời. {{Y5 tr.69}}\n- Xạ triệt để = xạ ngoài + **xạ áp sát**; IMRT không thay thế xạ áp sát. {{Y5 tr.68; QĐ1514 tr.PDF 365}}\n- **IVB/tái phát**: hóa trị cisplatin ± {p|bevacizumab} 15 mg/kg; {p|BPC} (bevacizumab + paclitaxel 175 + cisplatin 50, 21 ngày); pembrolizumab nếu PD-L1 (+). {{QĐ1514 tr.PDF 368–369}}\n- {r|Ifosfamide phải kèm mesna.} {{QĐ1514 tr.PDF 368}}\n- Giảm nhẹ: mở niệu quản/đại tràng ra da khi dò, suy thận; xạ giảm đau. {{Y5 tr.67–68}}\n\n[xem mục 7.2](#/n/ung-thu-cotucung/7) · [xem mục 7.3](#/n/ung-thu-cotucung/7)\n@@tab Tiên lượng – Dự phòng\n- Sống còn 5 năm: I ==80–90%==, II 50–65%, III 25–35%, IV 0–15%. {{Y5 tr.70}}\n- Tiên lượng theo **giai đoạn**, kích thước bướu, di căn hạch; ==80% tái phát trong 2–3 năm đầu==. {{Y5 tr.70}}\n- **Vắc xin HPV** (cấp 1): 3 liều trong 6 tháng; {r|đã tiêm vẫn phải tầm soát}. {{Y5 tr.71, 74}}\n- **Tầm soát** (cấp 2): từ ==21 tuổi==; 21–29 Pap mỗi 3 năm; 30–65 HPV + Pap mỗi 5 năm (hoặc Pap mỗi 3 năm). {{Y5 tr.72–73}}\n- Nơi thiếu điều kiện: **VIA**; tầm soát chỉ hiệu quả khi tổn thương tiền ung thư được điều trị. {{Y5 tr.72–74}}\n- Theo dõi sau điều trị: Y5 mỗi 3 tháng x 2 năm đầu; QĐ1514 mỗi 3 tháng x 5 năm. {{Y5 tr.70; QĐ1514 tr.PDF 370}}\n\n[xem mục 8](#/n/ung-thu-cotucung/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| HPV trong mô UTCTC | ==99,7%==; 16 + 18 ~==70%== | {{Y5 tr.57}} |\n| Nhiễm HPV tự khỏi trong 6 tháng | > ==80%== | {{Y5 tr.57}} |\n| Từ CIN 2/3 đến ung thư | 4–5 năm; ung thư sau 9–15 năm | {{Y5 tr.60}} |\n| Tuổi thường gặp | ==40–60== | {{Y5 tr.56}} |\n| GPB | Gai 80–85%, tuyến 15–20% (QĐ1514: vảy > 90%) | {{Y5 tr.58–59; QĐ1514 tr.PDF 362}} |\n| IA1 / IA2 | < ==3 mm== / 3–< ==5 mm== | {{Y5 tr.64}} |\n| IB1 / IB2 / IB3 | < ==2 cm== / 2–< ==4 cm== / ≥ ==4 cm== | {{Y5 tr.64}} |\n| Hóa xạ trị đồng thời | Cisplatin ==40 mg/m2== hàng tuần x 5 tuần | {{QĐ1514 tr.PDF 365–367}} |\n| Bevacizumab | ==15 mg/kg== mỗi 3 tuần | {{QĐ1514 tr.PDF 368–369}} |\n| Dự phòng hạch (EBRT) | ==45 Gy== | {{QĐ1514 tr.PDF 365–366}} |\n| Sống còn 5 năm I / II / III / IV | 80–90 / 50–65 / 25–35 / 0–15% | {{Y5 tr.70}} |\n| Tái phát | ==80%== trong 2–3 năm đầu | {{Y5 tr.70}} |\n| Bắt đầu tầm soát | ==21 tuổi== (Pap mỗi 3 năm); 30–65: HPV + Pap mỗi 5 năm | {{Y5 tr.72–73}} |\n| Vắc xin HPV | 3 liều trong 6 tháng | {{Y5 tr.71}} |\n\n> [!warn] Bẫy thi thường gặp\n> - **Y5 và QĐ1514 mâu thuẫn**: cisplatin hàng tuần 5–6 chu kỳ (Y5) vs x 5 tuần (QĐ1514); EP mỗi 3 tuần (Y5) vs 2 tuần (QĐ1514); theo dõi 3 tháng x 2 năm vs x 5 năm; vảy 80–85% vs > 90%; ngưỡng FIGO \"<\" vs \"≤\". Chọn theo nguồn của đề.\n> - Y5: phẫu thuật tiêu chuẩn cho IA2–IIA1; QĐ1514: khoét chóp chỉ IA1 ở người trẻ, Wertheim Meigs kèm 2 phần phụ.\n> - IIIC (hạch) có trong Y5 nhưng **không có** trong bảng nhóm QĐ1514; bảng TNM Y5 ghi IIIA = T2aN0M0 là nghi lỗi in (đúng: T3a).\n> - Sinh thiết CTC **không cần gây tê**; ASC-US khác **≥ ASC-H** (từ ASC-H mới soi CTC).\n> - MRI cho **bướu**, PET/CT cho **hạch**; hạch bẹn/trên đòn/trung thất là IVB, không phải hạch vùng.\n> - IB3–IVA: **hóa xạ trị đồng thời**, không phải phẫu thuật; đã tiêm vắc xin **vẫn phải tầm soát**.\n> - Tuổi vắc xin: Y5 9–26 (tứ giá), QĐ1514 9–25, WHO ưu tiên 9–14.\n\n@@fold Nguồn tài liệu\n- Y5: `_work/text-ung-buou-y5.txt` tr.56–75 (dịch tễ tr.56–57; GPB 57–60; lâm sàng 61–64; CLS, FIGO 62–66; điều trị 67–70; tầm soát 71–74).\n- SY5: `_work/slide-y5.txt` tr.82–116.\n- QĐ1514 Bài 44: `_work/qd-1514-byt-ung-buou.txt` tr. PDF 360–370 (bảng FIGO/TNM tr.362–363 đối chiếu ảnh trang).\n- 128VĐ: `data/book-items.json` mục 91, 92, 96, 97; QĐ 22 STT 87, 91, 92.\n- Bài cũ tái cấu trúc: `_old/ung-thu-cotucung-*.md`, `tc-tam-soat-co-tu-cung`, `tc-xuat-huyet-am-dao-bat-thuong`, `tc-khoi-vung-chau`.\n@@end\n\n@@fold Nguồn ngoài\n- NCI PDQ, Cervical Cancer Treatment (Health Professional Version), cancer.gov, truy cập 2026: https://www.cancer.gov/types/cervical/hp/cervical-treatment-pdq\n- WHO, Cervical cancer fact sheet (chiến lược loại trừ 90-70-90, khuyến cáo sàng lọc), truy cập 2026: https://www.who.int/news-room/fact-sheets/detail/cervical-cancer\n- Ghi chú: StatPearls (https://www.ncbi.nlm.nih.gov/books/NBK431093/) không truy cập được trong lần soạn này nên không dùng làm nguồn.\n@@end\n\n@@fold Tự kiểm tra (15 thẻ)\n- UTCTC xếp hàng thứ mấy ở nữ trên thế giới theo Globocan 2018 (Y5)? :: Hàng thứ tư (cả mắc mới lẫn tử vong)\n- Tuổi thường gặp và tỉ lệ mô UTCTC có DNA HPV (nghiên cứu 932 mẫu)? :: 40–60 tuổi (trung bình 48–52); HPV 99,7%\n- Cơ chế HPV gây ung thư? :: DNA HPV gắn vào bộ gen, ức chế gen đè nén bướu p53 và Rb; > 80% nhiễm ban đầu tự khỏi trong 6 tháng\n- CIN 1, 2, 3 khác nhau thế nào và tổn thương nào là tiền ung thư? :: Dị dạng chiếm 1/3 dưới, 2/3 dưới, toàn bộ lớp biểu mô; CIN 2–3 (grad cao) là tiền ung thư\n- Triệu chứng thường gặp nhất và dấu hiệu muộn? :: Xuất huyết âm đạo bất thường; muộn: huyết trắng hôi, phù chân/tiểu ít (suy thận), dò, sụt cân\n- Chẩn đoán xác định UTCTC? :: Sinh thiết ở bờ tổn thương (không cần gây tê), giải phẫu bệnh\n- Phương tiện tốt nhất đánh giá bướu và hạch? :: Bướu: MRI; hạch/di căn xa: PET/CT\n- Phân biệt IA1, IA2 và IB1/IB2/IB3 theo FIGO 2018 (Y5)? :: IA1 < 3 mm, IA2 3–< 5 mm; IB1 < 2 cm, IB2 2–< 4 cm, IB3 ≥ 4 cm\n- IIB, IIIB, IIIC, IVA khác nhau thế nào? :: IIB xâm lấn chu cung; IIIB vách chậu/ứ nước thận; IIIC di căn hạch chậu (C1)/cạnh ĐM chủ (C2); IVA bàng quang/trực tràng\n- Điều trị IA1 và IB1–IIA1? :: IA1: khoét chóp/cắt tử cung đơn giản; IB1–IIA1: cắt tử cung tận gốc + nạo hạch chậu (Wertheim–Meigs) hoặc xạ trị\n- Điều trị tiêu chuẩn IB3, IIA2, IIB–IVA và liều? :: Hóa xạ trị đồng thời cisplatin 40 mg/m2 mỗi tuần (x 5 tuần theo QĐ1514)\n- Chỉ định bổ túc sau mổ theo nguy cơ? :: Trung bình (bướu > 4 cm, xâm lấn > 1/2 cơ CTC, mạch): xạ; cao (hạch, chu cung, diện cắt âm đạo): hóa xạ đồng thời\n- Phác đồ BPC gồm gì? :: Bevacizumab 15 mg/kg + paclitaxel 175 mg/m2 + cisplatin 50 mg/m2, ngày 1, mỗi 21 ngày (UTCTC dai dẳng/tái phát/di căn)\n- Lịch tầm soát ACS/ACOG 2012? :: Từ 21 tuổi; 21–29 Pap mỗi 3 năm; 30–65 HPV + Pap mỗi 5 năm hoặc Pap mỗi 3 năm; ngưng sau 65 nếu đủ tiền căn\n- Sống còn 5 năm theo giai đoạn I đến IV và nguyên nhân tử vong chính? :: 80–90%, 50–65%, 25–35%, 0–15%; suy thận sau thận\n@@end"}, {"kind": "disease", "disease": "da-day", "short": "Ung thư dạ dày", "group": "", "section": 0, "order": 7, "khung": [7, 49, 50, 52, 54, 56, 99], "id": "ung-thu-da-day", "title": "Ung thư dạ dày", "layer": "benh", "module": "ung-buou", "tags": ["ung bướu", "dạ dày", "carcinôm tuyến", "Helicobacter pylori", "Lauren", "TNM", "pTNM", "nội soi", "cắt dạ dày", "nạo hạch", "trastuzumab", "xuất huyết tiêu hóa"], "source": "Y5 tr.253–268; SY5 tr.11, 36–38, 77–78, 174, 193, 195, 200; QĐ1514 tr.PDF 33, 71–74, 439, 443, 513; ĐC Y5 tr.6; 128VĐ mục 59, 60, 62, 64, 67, 75; QĐ22 STT 7, 49, 50, 52, 54, 56, 99", "body": "> [!key] Ung thư dạ dày (UTDD) trong một nhìn\n> - Trên 90% ung thư ác tính dạ dày là **carcinôm tuyến** {{Y5 tr.253}} {{Y5 tr.254}}\n> - Việt Nam (Globocan 2018): hạng 3 về số ca mới, ==17.527 ca== {{Y5 tr.254}}\n> - Nguy cơ chính: nhiễm ==H. pylori== (viêm teo dạ dày mạn) và **hút thuốc lá**; HDGC ~1–3% {{Y5 tr.254}}\n> - Chẩn đoán: **nội soi tiêu hóa trên + sinh thiết** là phương tiện đầu tiên {{Y5 tr.258}}\n> - Điều trị theo giai đoạn: sớm → cắt dạ dày + nạo hạch (hoặc cắt qua nội soi); tiến xa → hóa–xạ trị; di căn → hóa trị toàn thân {{Y5 tr.261}} {{Y5 tr.262}}\n> - Sống 5 năm pTNM: giai đoạn IA ==94%==, giai đoạn IV ==5%== {{Y5 tr.260}} {{Y5 tr.261}}\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Carcinôm tuyến (>90%) {{Y5 tr.254}}; phân loại Lauren (ruột / lan tỏa / hỗn hợp) {{Y5 tr.255}} {{Y5 tr.256}}; WHO 5 loại, độ mô học G1–G4 {{Y5 tr.256}}\n> - Di căn: **hạch** thường gặp nhất; gieo rắc ổ bụng (kiểu lan tỏa); di căn gan (kiểu ruột) {{Y5 tr.256}}\n\n### Định nghĩa & dịch tễ\n- UT dạ dày = carcinôm tuyến dạ dày vì hơn 90% UT ác tính dạ dày là carcinôm tuyến {{Y5 tr.253}}\n- Thế giới (Globocan 2012): ==952 ngàn ca mới/năm== (thứ 5), ==723 ngàn tử vong/năm== (thứ 3) {{Y5 tr.253}}\n- Thế giới (Globocan 2018): 1.033.701 ca mới (5,7%), 782.685 tử vong (8,2%) {{SY5 tr.36}} — số liệu khác Y5, xem [mục 9](#/n/ung-thu-da-day/9) (Bẫy thi thường gặp)\n- Xuất độ chuẩn tuổi /100.000: nam 17,4; nữ 7,5; tử suất nam 12,8, nữ 5,7 (Globocan 2012) {{Y5 tr.253}}\n- Cao ở Đông Á và Trung–Đông Âu; thấp ở Nam Á, Tây Âu, Mỹ; khoảng 60% bệnh nhân ở Đông Á {{Y5 tr.253}}\n- Đang giảm theo tỉ lệ nhiễm H. pylori giảm {{Y5 tr.253}}\n- Việt Nam: Globocan 2018 ==17.527 ca mới== (hạng 3); nam thường gặp hạng 3, nữ hạng 4 {{Y5 tr.254}} {{SY5 tr.38}}\n- TP.HCM 2016: nam hạng 4 (xuất độ 10,0), nữ hạng 9 (3,5 /100.000) {{Y5 tr.254}}\n- BV Ung Bướu TP.HCM 2000–2004 (n = 358): nam/nữ 1,6; tuổi thường gặp 50–69; ==80% nhập viện giai đoạn III–IV==; ==47% mổ được== {{Y5 tr.266}}\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Nhiễm khuẩn – ăn uống – thuốc lá\n- **Rõ ràng**: nhiễm **H. pylori** và **hút thuốc lá** {{Y5 tr.254}}\n- Viêm teo dạ dày mạn do H. pylori (chủng CagA) là yếu tố sinh ung quan trọng ở phần xa dạ dày {{Y5 tr.254}}\n- **Có thể**: thực phẩm bảo quản bằng muối, thói quen ăn mặn, thịt chế biến sẵn, thịt xông khói, thịt nướng, ớt {{Y5 tr.254}}\n- Khuyến cáo WHO: ăn dưới 6 g muối/ngày (2,4 g natri) {{SY5 tr.174}}\n@@tab Di truyền\n- UT dạ dày di truyền gặp trong **hội chứng Lynch** hoặc **HDGC** (UT dạ dày lan tỏa di truyền), chiếm ~1–3% {{Y5 tr.254}}\n- HDGC: đột biến **CDH1 (E-cadherin)** trong gia đình → theo dõi sát bằng nội soi hoặc cắt dạ dày dự phòng {{Y5 tr.254}} {{SY5 tr.200}}\n- Tài liệu không nêu tỉ số nguy cơ (RR) của từng yếu tố nguy cơ\n@@end\n\n### Sinh bệnh học & sinh học phân tử\n- Nền tảng sinh ung: viêm teo mạn do H. pylori; HDGC do đột biến CDH1 {{Y5 tr.254}}\n- HER2 (+) là yếu tố tiên lượng và là chỉ định trastuzumab {{Y5 tr.261}} {{Y5 tr.266}}\n- Tài liệu không nêu chi tiết cơ chế phân tử khác của UT dạ dày (xem [[ung-thu-co-che-sinh-ung]], [[ung-thu-sinh-hoc-phan-tu]])\n\n### Giải phẫu bệnh – phân loại\n\n| Kiểu (Lauren) | Mô học | Lâm sàng / vị trí | Đại thể | Di căn hay gặp |\n|---|---|---|---|---|\n| **Ruột** | biểu mô tuyến giống tế bào trụ ruột; ranh giới rõ | người lớn tuổi; phần xa dạ dày | Borrmann I–II | **gan** (theo tĩnh mạch cửa) |\n| **Lan tỏa** | tế bào rải rác, liên kết lỏng, tế bào nhẫn; ranh giới không rõ | người trẻ; phần gần dạ dày | Borrmann III–IV | **gieo rắc ổ bụng** |\n| **Hỗn hợp** | có cả cấu trúc ruột và lan tỏa | lâm sàng xếp cùng nhóm lan tỏa | — | — |\n\n{{Y5 tr.255}} {{Y5 tr.256}}\n\n- Hình thái đa dạng, có thể không đồng nhất ngay trong một khối bướu {{Y5 tr.255}}\n- WHO (vi thể): ống, nhú, kém kết dính (gồm tế bào nhẫn), tiết nhày, hỗn hợp {{Y5 tr.256}}\n- Độ mô học: G1 biệt hóa tốt, G2 vừa, G3 kém, G4 không biệt hóa; G1–2 = grad thấp, G3–4 = grad cao {{Y5 tr.256}}\n- Dạng đại thể thường gặp (BV Ung Bướu TP.HCM): **dạng loét** {{Y5 tr.266}}\n- UT khác của dạ dày: lymphôm, **GIST**, carcinoid, sarcôm cơ trơn {{Y5 tr.254}}\n- UT dạ dày **sớm** = bướu khu trú ở niêm mạc và dưới niêm; ở phương Tây <5%, ở Nhật 3,8% (1955–56) → 45% (1989) sau tầm soát {{Y5 tr.254}}\n\n### Diễn tiến tự nhiên – lan tràn\n- Xuất phát từ niêm mạc; hiếm di căn khi chưa xâm lấn qua lớp cơ niêm {{Y5 tr.256}}\n- **Di căn hạch** là hình thức thường gặp nhất; bắt đầu khi xâm lấn lớp dưới niêm; càng sâu càng nhiều hạch {{Y5 tr.256}}\n- Đường hạch: quanh dạ dày → quanh động mạch thân tạng và nhánh (gan chung, lách, vị trái) → cạnh động mạch chủ bụng → ống ngực {{Y5 tr.257}}\n- Xâm lấn tại chỗ: thực quản, tá tràng, mạc nối; qua thanh mạc → gan, tụy, đại tràng, cơ hoành; khoang sau phúc mạc → tuyến thượng thận trái, niệu quản {{Y5 tr.256}} {{Y5 tr.257}}\n- Xuyên thanh mạc → **gieo rắc ổ bụng** (đặc biệt kiểu lan tỏa); khoang sau phúc mạc → chậu xơ cứng gây tắc niệu quản {{Y5 tr.256}}\n- Di căn xa: gan (theo tĩnh mạch cửa), phổi, xương, da; xâm lấn trực tiếp phổi, màng phổi {{Y5 tr.257}}\n- Tái phát: phần lớn trong **2 năm đầu** sau cắt triệt căn; thường lan theo nhiều đường cùng lúc {{Y5 tr.262}} {{Y5 tr.263}}\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Triệu chứng **không đặc hiệu**; thường gặp: ==đau thượng vị==, sụt cân, chán ăn, buồn nôn {{Y5 tr.266}}\n> - Giai đoạn trễ: khối thượng vị, hạch thượng đòn trái, dịch ổ bụng, di căn buồng trứng {{Y5 tr.258}}\n\n### Triệu chứng cơ năng\n- Đau kiểu **viêm loét** (đau khi đói, giảm sau ăn), đầy bụng, chán ăn, đau bụng, buồn nôn, **nuốt khó** {{Y5 tr.257}}\n- Sụt cân, sờ thấy bướu thượng vị, thiếu máu, đau lưng, **tiêu phân đen**, phù chân, vàng da niêm {{Y5 tr.257}}\n- Ăn không tiêu, đầy bụng, đau thượng vị: nằm trong nhóm viêm–loét hoặc ung thư dạ dày {{SY5 tr.77}}\n\n### Triệu chứng thực thể\n- Thường **không có** dấu hiệu thực thể; giai đoạn trễ có thể gặp {{Y5 tr.258}}:\n  - Bướu thượng vị, gan to, bụng báng\n  - Khối sượng cứng ở rốn (**Sister Mary Joseph**); mảng sượng túi cùng sau (**Blumer shelf**)\n  - Bướu đặc buồng trứng (**Krukenberg**) {{Y5 tr.258}} {{SY5 tr.11}}\n  - Hạch thượng đòn trái (**Virchow**); hạch nách trái (**Irish**) {{Y5 tr.258}}\n\n> [!red] Dấu hiệu báo động\n> - **Chảy máu**: nôn ra máu, đi ngoài phân đen; sonde dạ dày ra máu tươi là dấu hiệu nặng {{QĐ1514 tr.PDF 71}} {{QĐ1514 tr.PDF 72}}\n> - **Sụt cân** >5% trọng lượng trong 6–12 tháng: cần đánh giá toàn diện {{128VĐ mục 75}}\n> - Khối thượng vị, hạch Virchow/Irish, khối rốn Sister Mary Joseph {{Y5 tr.258}}\n\n### Tiếp cận các triệu chứng (khung 128 vấn đề)\n\n| STT | Vấn đề | Nguyên nhân cần nghĩ tới |\n|---|---|---|\n| [56](#/khung/56) | **Xuất huyết tiêu hóa trên** (nôn ra máu, phân đen) | **ung thư dạ dày**, loét dạ dày–tá tràng, hội chứng Mallory–Weiss, vỡ giãn tĩnh mạch thực quản {{128VĐ mục 67}} {{QĐ1514 tr.PDF 71}} |\n| [52](#/khung/52) | **Đau bụng mạn / ợ nóng / ợ trớ / khó tiêu** | viêm loét dạ dày–tá tràng, trào ngược, **ung thư dạ dày**, khó tiêu chức năng; chú ý tầm soát bệnh ác tính ổ bụng {{128VĐ mục 62}} |\n| [50](#/khung/50) | **Nghẹn, nuốt khó** | ung thư dạ dày (nuốt khó) {{Y5 tr.257}}; u lớn dạ dày/tâm vị (GIST) {{QĐ1514 tr.PDF 513}}; ung thư thực quản (nuốt khó tăng dần) {{128VĐ mục 60}} |\n| [54](#/khung/54) | **Khối ở bụng** | khối u đường tiêu hóa (dạ dày, đại tràng, tụy, gan) {{128VĐ mục 64}} |\n| [49](#/khung/49) | **Buồn nôn / nôn** | tắc nghẽn đường thoát dạ dày; khối u tân sinh dạ dày {{128VĐ mục 59}} |\n| [99](#/khung/99) | **Sụt cân / suy dinh dưỡng** | ung thư ống tiêu hóa, tụy, gan–mật {{128VĐ mục 75}} |\n| [7](#/khung/7) | **Thiếu máu** | Y5 liệt kê thiếu máu cùng tiêu phân đen trong triệu chứng {{Y5 tr.257}} |\n\n## 5. Cận lâm sàng\n\n> [!key] Tóm tắt\n> - **Nội soi tiêu hóa trên + sinh thiết** là phương tiện đầu tiên; **CT + siêu âm bụng**; **nội soi ổ bụng** để xếp giai đoạn {{Y5 tr.258}}\n> - Phân giai đoạn **pTNM UICC/AJCC (bản 8, 2017)**; cần ==≥16 hạch== để xếp N {{Y5 tr.259}}\n> - CEA, CA19-9, CA72-4 **không dùng tầm soát**, có ích khi theo dõi tái phát/di căn {{Y5 tr.259}}\n\n### Chẩn đoán hình ảnh – nội soi\n@@tabs\n@@tab Nội soi & siêu âm nội soi\n- **Nội soi tiêu hóa trên + sinh thiết** giải phẫu bệnh: chẩn đoán đầu tiên, xác định UT dạ dày {{Y5 tr.258}}\n- Nội soi cho hình: dày nếp gấp, thâm nhiễm (Borrmann III) {{Y5 tr.258}}\n- Siêu âm qua nội soi: đánh giá khối u và hạch quanh dạ dày; phân biệt T1a (lớp cơ niêm) và T1b (dưới niêm) khi cân nhắc cắt rộng qua nội soi {{Y5 tr.258}} {{Y5 tr.259}}\n@@tab X quang – CT – MRI – PET\n- X quang dạ dày đối quang kép: hữu ích cho thể **linitis plastica**, không luôn cần {{Y5 tr.258}}\n- **CT** và **siêu âm bụng**: đánh giá di căn {{Y5 tr.258}}\n- MRI: tổn thương di căn gan và xương, không luôn cần {{Y5 tr.258}}\n- PET: ít giá trị, độ nhạy kém ở thể lan tỏa {{Y5 tr.258}}\n@@tab Nội soi ổ bụng & dịch\n- Hình ảnh **chưa phát hiện được** nốt gieo rắc phúc mạc (hay gặp khi T3–T4) {{Y5 tr.258}}\n- **Nội soi ổ bụng** sinh thiết hoặc tế bào học dịch ổ bụng để chẩn đoán giai đoạn {{Y5 tr.258}}\n- Trước điều trị, nội soi ổ bụng để loại trừ gieo rắc ổ bụng (điều trị tân hỗ trợ) {{Y5 tr.262}}\n@@end\n\n### Đánh giá trước mổ & trước hóa trị\n- Trước mổ: đánh giá nguy cơ theo ASA; ECG và thử nghiệm gắng sức; X quang ngực thẳng; đo chức năng hô hấp {{Y5 tr.259}}\n- Trước hóa trị: thang KPS hoặc ECOG; bạch cầu neutrophil; độ thanh thải creatinine; sinh hóa thường quy {{Y5 tr.259}}\n\n### Chất đánh dấu u\n\n| Chất | Ý nghĩa |\n|---|---|\n| CEA, CA19-9, CA72-4 | thường tăng khi giai đoạn muộn; **không có vai trò tầm soát**; có ích xác định tái phát và di căn xa {{Y5 tr.259}} |\n| CA125 | thường tăng khi có gieo rắc ổ bụng {{Y5 tr.259}} |\n\n### Phân giai đoạn TNM (UICC/AJCC 2017, bản 8)\n\n@@tabs\n@@tab T\n| T | Mô tả (Y5) |\n|---|---|\n| TX | bướu nguyên phát không thể xác định |\n| T0 | không có bướu nguyên phát |\n| Tis | bướu còn khu trú ở lớp biểu mô |\n| T1a | xâm lấn lớp cơ niêm |\n| T1b | xâm lấn lớp dưới niêm |\n| T2 | xâm lấn lớp cơ |\n| T3 | xâm lấn lớp mô liên kết dưới thanh mạc |\n| T4a | xâm lấn lớp thanh mạc |\n| T4b | xâm lấn các cấu trúc lân cận |\n\n{{Y5 tr.259}}\n@@tab N\n| N | Mô tả (Y5) |\n|---|---|\n| NX | hạch vùng không thể xác định |\n| N0 | không di căn hạch vùng |\n| N1 | di căn 1–2 hạch vùng |\n| N2 | di căn 3–6 hạch vùng |\n| N3a | di căn 7–15 hạch vùng |\n| N3b | di căn ≥16 hạch vùng |\n\n{{Y5 tr.260}}\n@@tab M\n- M0: không di căn xa\n- M1: có di căn xa **hoặc dịch rửa ổ bụng có tế bào ác tính**\n- Di căn hạch **ngoài hạch vùng** (ví dụ hạch sau tụy, hạch cạnh động mạch chủ bụng) → **M1** {{Y5 tr.259}}\n@@end\n\n#### Nhóm giai đoạn pTNM và sống còn 5 năm (Y5 Bảng 2)\n\n| Giai đoạn | Tổ hợp T–N (M0, trừ IV) | Sống 5 năm |\n|---|---|---|\n| 0 | Tis N0 | ==100%== |\n| IA | T1 N0 | ==94%== |\n| IB | T2 N0; T1 N1 | 88% |\n| IIA | T3 N0; T2 N1; T1 N2 | 82% |\n| IIB | T4a N0; T3 N1; T2 N2; T1 N3a | 68% |\n| IIIA | T4b N0; T4a N1–2; T3 N2; T2 N3a | 54% |\n| IIIB | T4b N1–2; T3–4a N3a; T1–2 N3b | 36% |\n| IIIC | T3–4a N3b; T4b N3 | 18% |\n| IV | T bất kỳ, N bất kỳ, **M1** | ==5%== |\n\n{{Y5 tr.260}} {{Y5 tr.261}}\n\n> [!warn] Lưu ý phân giai đoạn\n> - Y5 chỉ trình bày **pTNM sau mổ**; tài liệu không nêu phân giai đoạn lâm sàng (cTNM) cho UT dạ dày\n> - Phân biệt **T1a/T1b** khi cân nhắc cắt rộng qua nội soi {{Y5 tr.259}}\n> - Cần ==≥16 hạch== để xếp N chính xác (sau cắt dạ dày D1) {{Y5 tr.259}} {{Y5 tr.262}}\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Chẩn đoán xác định\n> - Nội soi tiêu hóa trên + **sinh thiết giải phẫu bệnh** → carcinôm tuyến {{Y5 tr.254}} {{Y5 tr.258}}\n> - Xếp giai đoạn: CT/siêu âm bụng + **nội soi ổ bụng** (sinh thiết hoặc tế bào dịch) {{Y5 tr.258}}\n> - Trước hóa trị đánh giá thêm KPS/ECOG, neutrophil, creatinine {{Y5 tr.259}}\n\n### Chẩn đoán phân biệt\n\n| Bệnh lý | Giống | Khác / cách phân biệt | Nguồn |\n|---|---|---|---|\n| Viêm loét dạ dày–tá tràng | đau thượng vị, khó tiêu, có thể chảy máu | cùng nằm trong nhóm nguyên nhân \"ăn không tiêu, đau thượng vị\"; tài liệu không nêu tiêu chí riêng để phân biệt bằng lâm sàng; cần nội soi có sinh thiết | {{SY5 tr.77}} {{128VĐ mục 62}} |\n| Trào ngược dạ dày–thực quản; khó tiêu chức năng | ợ nóng, ợ trớ, khó tiêu | khó tiêu chức năng là không kèm loét dạ dày | {{128VĐ mục 62}} |\n| U mô đệm đường tiêu hóa (GIST) | khối, nuốt vướng, xuất huyết tiêu hóa cao, buồn nôn | dạ dày chiếm ~60% GIST; ==c-KIT (CD117) 85–95%==; sarcôm mô mềm | {{QĐ1514 tr.PDF 513}} |\n| U lympho dạ dày (MALT) | u sùi và/hoặc loét khi nội soi | sinh thiết để chẩn đoán mô bệnh học; thể MALT ở dạ dày: có thể phối hợp phẫu thuật, xét nghiệm và điều trị H. pylori | {{QĐ1514 tr.PDF 439}} {{QĐ1514 tr.PDF 443}} |\n| Carcinoid, sarcôm cơ trơn | — | Y5 chỉ liệt kê; tài liệu không nêu đặc điểm phân biệt | {{Y5 tr.254}} |\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n\n> [!key] Mục tiêu theo giai đoạn\n> - **Sớm**: có thể khỏi chỉ bằng **phẫu thuật**, thậm chí cắt rộng qua nội soi {{Y5 tr.253}}\n> - **Khu trú / tiến xa chưa di căn**: phẫu thuật triệt để với **R0** + hóa trị hoặc hóa–xạ hỗ trợ/tân hỗ trợ {{Y5 tr.261}}\n> - **Tiến xa không cắt được / di căn xa**: **hóa trị trước**; phẫu thuật chỉ **giảm nhẹ** (chảy máu, tắc nghẽn) {{Y5 tr.261}} {{Y5 tr.262}}\n- Phẫu thuật không triệt để không kéo dài sống và có thể làm giảm chất lượng sống, giảm chấp nhận hóa trị {{Y5 tr.262}}\n- Nguyên tắc chung: cắt dạ dày với diện cắt thích hợp và nạo hạch hợp lý; đánh giá giai đoạn bởi nhóm đa chuyên khoa {{Y5 tr.261}}\n- Hóa trị hỗ trợ hoặc tân hỗ trợ cải thiện sống còn ở bệnh nhân T2–4 có diện cắt R0 {{Y5 tr.261}}\n\n### 7.2 Các phương pháp\n\n@@tabs\n@@tab Phẫu thuật\n- **Cắt qua nội soi** (EMR/ESD): tiêu chuẩn tuyệt đối — carcinôm tuyến biệt hóa, không loét, xâm lấn niêm mạc (khẳng định qua GPB), đường kính ≤2 cm; không cần nạo hạch {{Y5 tr.264}}\n  - Tiêu chuẩn mở rộng (một số nhà nội soi): T1a biệt hóa không loét >2 cm; T1a biệt hóa có loét ≤3 cm; T1a không biệt hóa không loét ≤2 cm {{Y5 tr.264}}\n- **Cắt dạ dày + nạo hạch D1/D1+** (sớm): phần xa khi bướu ở 2/3 xa; toàn bộ khi xâm lấn 1/3 gần; phần gần khi ở 1/3 gần; bảo tồn môn vị khi ở 1/3 giữa {{Y5 tr.263}}\n- **Cắt dạ dày + nạo hạch D2** (tiến xa chưa di căn xa): phẫu thuật viên có kinh nghiệm tại trung tâm lớn; diện cắt khoảng 5 cm; cắt thêm thực quản đoạn cuối khi xâm lấn {{Y5 tr.264}}\n  - Cắt lách hoặc tụy–lách chỉ khi u xâm lấn trực tiếp và cần để đạt R0 (biến chứng và tử vong cao) {{Y5 tr.264}}\n- **Cắt D0/D1 + hóa–xạ hỗ trợ**: khi không nạo hạch D2 an toàn {{Y5 tr.264}}\n- **Tân hỗ trợ**: hóa trị → cắt dạ dày + nạo hạch → hóa trị tiếp sau mổ {{Y5 tr.262}}\n- **Giảm nhẹ** (chỉ cân nhắc khi cấp cứu chảy máu hoặc tắc): cắt dạ dày triệu chứng; nối vị–tràng; nối tắt; mở hồi tràng/đại tràng ra da khi tắc ruột; **stent** hẹp môn vị hoặc tâm vị {{Y5 tr.262}} {{Y5 tr.264}} {{Y5 tr.265}}\n- Di căn gan đơn ổ: phẫu thuật triệt để có chỉ định giới hạn {{Y5 tr.262}}\n@@tab Xạ trị\n- Hóa–xạ hỗ trợ sau cắt R0 kèm nạo hạch giới hạn (D0/D1): ==4500 cGy trong 25 phân liều, 5 ngày/tuần== {{Y5 tr.265}}\n- Kèm fluorouracil 425 mg/m² + leucovorin 20 mg/m² trong 5 ngày, trước và sau hóa–xạ {{Y5 tr.265}}\n- Hóa–xạ tiền phẫu: đang thử nghiệm, **chưa có kết quả rõ ràng** {{Y5 tr.265}}\n- Xạ triệu chứng: chảy máu mạn từ bướu không mổ được; đau do bướu xâm lấn hoặc di căn (đặc biệt xương) {{Y5 tr.265}}\n@@tab Hóa trị\n- **Chu phẫu** (tiến triển chưa di căn xa): 3 chu kỳ trước và 3 chu kỳ sau mổ; {p|ECF} (epirubicin + cisplatin + fluorouracil); cải biên: EOF (oxaliplatin thay cisplatin), ECX (capecitabine thay fluorouracil), EOX {{Y5 tr.265}}\n- **Sau mổ D2 (giai đoạn IB–III)**: {p|CapeOx} hoặc {p|S-1}, mỗi loại 8 chu kỳ {{Y5 tr.265}}\n- **Di căn xa**: phác đồ hai thuốc thường dùng; ba thuốc chỉ khi tổng trạng tốt, không có bệnh nội khoa nặng {{Y5 tr.265}}\n  - Bước một: {p|DCF}, ECF và cải biên, {p|FP} (cisplatin + fluorouracil), {p|XP} (cisplatin + capecitabine) {{Y5 tr.265}} {{Y5 tr.266}}\n  - Bước hai: chọn theo thuốc bước một và tổng trạng: {p|docetaxel}, {p|paclitaxel}, {p|irinotecan} {{Y5 tr.266}}\n- Tiến triển tại vùng hoặc di căn xa: trung vị sống còn chỉ ==16 tháng== dù dùng hóa chất mới và thuốc đích {{Y5 tr.266}}\n@@tab Đích – miễn dịch\n- **HER2 (+)**: {p|trastuzumab} + XP hoặc FP; trung vị sống còn ==16 tháng== so với <12 tháng nếu chỉ hóa trị {{Y5 tr.266}}\n- Các thuốc nhắm trúng đích và miễn dịch khác: tài liệu không nêu chi tiết chỉ định, liều (Y5 chỉ ghi chung \"thuốc nhắm trúng đích\") {{Y5 tr.266}}\n@@end\n\n> [!doc] QĐ 1514/QĐ-BYT (Bài 11 \"Xuất huyết tiêu hóa do ung thư\", tr. PDF 71–74) — xử trí cấp cứu chảy máu do ung thư dạ dày\n> - Mất máu nặng: ước lượng >500 ml hoặc phải truyền >5 đơn vị máu/24 giờ {{QĐ1514 tr.PDF 72}}\n> - Hồi sức: bù thể tích; đặt sonde dạ dày rửa máu; nội soi dạ dày–tá tràng cấp để vừa xác định vừa cầm máu {{QĐ1514 tr.PDF 71}} {{QĐ1514 tr.PDF 73}}\n> - Cầm máu tại chỗ qua nội soi: tiêm xơ hoặc tiêm adrenalin 1 mg trong chảy máu do ung thư dạ dày–ruột {{QĐ1514 tr.PDF 73}}\n> - Truyền máu khi chảy máu nặng, tiến triển: đưa Hct >25% (>30% với người già, bệnh tim mạch, suy hô hấp) {{QĐ1514 tr.PDF 73}}\n> - Ức chế bơm proton: omeprazol/esomeprazol/pantoprazol 80 mg/24 giờ, rồi 8 mg/giờ trong 72 giờ; bơm nước lạnh qua sonde dạ dày {{QĐ1514 tr.PDF 74}}\n> - Phẫu thuật cắt dạ dày một phần hoặc toàn phần trong ung thư dạ dày–ruột {{QĐ1514 tr.PDF 74}}\n\n### 7.3 Phác đồ – Y lệnh\n\n> [!doc] QĐ 1514/QĐ-BYT (tr. PDF 33) chỉ **liệt kê tên phác đồ** cho ung thư dạ dày–thực quản: irinotecan/cisplatin; epirubicin/cisplatin/5-FU; epirubicin/cisplatin/capecitabine (không ghi liều). {{QĐ1514 tr.PDF 33}}\n\n> [!warn] Chưa có văn bản Bộ Y tế trong tài liệu đã cung cấp về liều hóa trị UT dạ dày. Liều chỉ ghi khi có trong giáo trình Y5; còn lại ghi \"tài liệu không nêu\". Độc tính cụ thể của phác đồ: tài liệu không nêu.\n\n| Phác đồ | Thuốc – liều | Chu kỳ / cách dùng | Chỉ định | Ghi chú |\n|---|---|---|---|---|\n| Hóa–xạ hỗ trợ | xạ 4500 cGy; fluorouracil 425 mg/m² + leucovorin 20 mg/m² ×5 ngày | 25 phân liều, 5 ngày/tuần; 5-FU/LV trước và sau hóa–xạ | sau cắt R0, nạo hạch D0/D1 | {{Y5 tr.265}} |\n| ECF (chu phẫu) | epirubicin + cisplatin + fluorouracil — liều: tài liệu không nêu | 3 chu kỳ trước + 3 sau mổ | tiến triển, chưa di căn xa | {{Y5 tr.265}}; cải biên EOF, ECX, EOX |\n| CapeOx | capecitabine + oxaliplatin — liều: tài liệu không nêu | 8 chu kỳ | sau mổ D2, giai đoạn IB–III | {{Y5 tr.265}} |\n| S-1 | liều: tài liệu không nêu | 8 chu kỳ | sau mổ D2, giai đoạn IB–III | {{Y5 tr.265}} |\n| DCF (bước một) | docetaxel + cisplatin + fluorouracil — liều: tài liệu không nêu | tài liệu không nêu | di căn xa | {{Y5 tr.265}} |\n| FP / XP (bước một) | cisplatin + fluorouracil / cisplatin + capecitabine — liều: tài liệu không nêu | tài liệu không nêu | di căn xa | {{Y5 tr.266}} |\n| Bước hai | docetaxel, paclitaxel, irinotecan — liều: tài liệu không nêu | tài liệu không nêu | di căn xa, sau bước một | {{Y5 tr.266}} |\n| Trastuzumab + XP hoặc FP | trastuzumab + hóa trị (XP/FP) — liều: tài liệu không nêu | tài liệu không nêu | HER2 (+) | {{Y5 tr.266}} |\n| Cầm máu cấp cứu (không phải hóa trị) | pantoprazol 80 mg/24 giờ, rồi 8 mg/giờ trong 72 giờ; adrenalin 1 mg tại chỗ khi nội soi | — | chảy máu do ung thư dạ dày | {{QĐ1514 tr.PDF 73}} {{QĐ1514 tr.PDF 74}} |\n\n## 8. Tiên lượng – Dự phòng\n\n> [!key] Tóm tắt\n> - Tiên lượng gắn với **giai đoạn pTNM** (đặc biệt di căn hạch), R0 và HER2 {{Y5 tr.261}}\n> - Tầm soát có hiệu quả ở các nước có chương trình (Nhật, Hàn); Việt Nam: tài liệu không nêu {{Y5 tr.254}}\n\n### Tiên lượng\n@@tabs\n@@tab Yếu tố tiên lượng (Bảng 3)\n| Nhóm | Yếu tố |\n|---|---|\n| Thiết yếu | phân loại T, N, M; tình trạng **HER2**; **UT còn lại sau mổ: R0, R1, R2** {{Y5 tr.261}} |\n| Phụ trợ thêm | vị trí (tâm vị hoặc phần xa dạ dày); loại mô học; xâm lấn mạch máu; tuổi; độ rộng phẫu thuật {{Y5 tr.261}} |\n| Mới và hứa hẹn | sinh học phân tử của bướu; chủng tộc (Á châu hay không) {{Y5 tr.261}} |\n\n- Nhiều nghiên cứu: bệnh nhân Á châu sống còn tốt hơn dù cùng giai đoạn và điều trị như nhau {{Y5 tr.261}}\n@@tab Sống còn\n- Sống 5 năm theo pTNM: IA ==94%== … IV ==5%== (xem bảng mục 5) {{Y5 tr.260}} {{Y5 tr.261}}\n- BV Ung Bướu TP.HCM 2000–2004 (n = 358): sống toàn bộ 5 năm ==53%==; sống không bệnh 5 năm ==18%== {{Y5 tr.266}}\n- Tiến xa/di căn: trung vị sống còn ~16 tháng {{Y5 tr.266}}\n@@end\n\n### Theo dõi sau điều trị\n\n| Tình huống | Theo dõi |\n|---|---|\n| Cắt rộng qua nội soi, T1a | nội soi mỗi năm; siêu âm hoặc CT bụng (tái phát tại vùng) {{Y5 tr.263}} |\n| Phẫu thuật R0, giai đoạn I | thử chất đánh dấu, siêu âm hoặc CT bụng mỗi năm; nội soi dạ dày mỗi 2 năm {{Y5 tr.263}} |\n| Phẫu thuật R0, giai đoạn II–III | chất đánh dấu + siêu âm hoặc CT bụng mỗi 6 tháng; nội soi mỗi 2 năm {{Y5 tr.263}} |\n\n- Đa số tái phát trong **2 năm đầu** sau cắt triệt căn; nguy cơ giảm dần các năm sau {{Y5 tr.263}}\n\n### Dự phòng\n\n@@tabs\n@@tab Cấp 1 (phòng bệnh)\n- **Tiệt trừ H. pylori**; vệ sinh ăn uống {{SY5 tr.193}}\n- Hạn chế muối: dưới 6 g/ngày {{SY5 tr.174}}\n- Hóa phòng ngừa (NSAID/COX) giảm ung thư đường tiêu hóa, chủ yếu đại trực tràng, ít hơn ở thực quản và dạ dày {{SY5 tr.195}}\n@@tab Cấp 2 (tầm soát)\n- Nhật và Hàn Quốc: tầm soát từ **40 tuổi**; Nhật mỗi năm, Hàn Quốc mỗi 2 năm {{Y5 tr.254}}\n- Phương tiện: chụp thực quản–dạ dày–tá tràng có cản quang đường uống, hoặc nội soi tiêu hóa trên {{Y5 tr.254}}\n- Nguy cơ cao: huyết thanh dương tính H. pylori; viêm teo dạ dày có pepsinogen dương tính {{Y5 tr.254}}\n- HDGC (đột biến CDH1): nội soi sát hoặc cắt dạ dày dự phòng {{Y5 tr.254}} {{SY5 tr.200}}\n- Chương trình tầm soát tại Việt Nam: tài liệu không nêu\n@@tab Cấp 3 (giảm biến chứng, giảm nhẹ)\n- Tài liệu không nêu nội dung dự phòng cấp 3 riêng cho UT dạ dày\n- Phẫu thuật giảm nhẹ khi chảy máu hoặc tắc nghẽn; cân nhắc ở bệnh nhân cấp cứu {{Y5 tr.264}}\n- Stent cho hẹp môn vị/tâm vị; nối vị–tràng khi tắc {{Y5 tr.262}} {{Y5 tr.265}}\n@@end\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] Bài này thi nhấn mạnh gì\n> - Trọng số QĐ 22 (test blueprint, tr.8): **Cận lâm sàng/XN chẩn đoán 45–60** (dòng 3); **Liệu pháp thuốc 35–50** (dòng 7); văn bản không nói rõ là trọng số dòng hay nhóm {{QĐ22 tr.8}}. Suy luận của bài, không có trong QĐ22: chẩn đoán (nội soi + GPB + TNM) là phần cốt lõi, rồi xử trí theo giai đoạn\n> - Đề cương Y5 gắn ca lâm sàng dạ dày với MT 2, 3, 4, 5, 7, 8, 9, 10, 12, 13, 14, 15, 17 (1 tiết lên lớp, 2 tiết tự học) {{ĐC Y5 tr.6}}\n> - Câu hỏi tình huống: \"đau thượng vị kéo dài ở người lớn tuổi, sụt cân, nôn ra máu → làm gì?\"\n\n@@tabs\n@@tab Nhận diện\n- **Nguy cơ then chốt**: H. pylori (viêm teo mạn), hút thuốc, ăn mặn {{Y5 tr.254}} {{SY5 tr.174}}\n- **Triệu chứng hay gặp**: đau thượng vị, sụt cân, chán ăn, buồn nôn; nuốt khó; tiêu phân đen {{Y5 tr.266}} {{Y5 tr.257}}\n- {r|Báo động}: nôn/đi ngoài ra máu; khối thượng vị, hạch Virchow/Irish, khối rốn {{QĐ1514 tr.PDF 71}} {{Y5 tr.258}}\n- Sụt cân >5% trong 6–12 tháng có ý nghĩa lâm sàng {{128VĐ mục 75}}\n- Gia đình HDGC (CDH1): nội soi sát hoặc cắt dạ dày dự phòng {{SY5 tr.200}}\n[Xem mục 4](#/n/ung-thu-da-day/4) · [mục 3](#/n/ung-thu-da-day/3)\n@@tab Chẩn đoán\n- {g|Nội soi tiêu hóa trên + sinh thiết}: phương tiện đầu tiên; xác định bằng mô bệnh học (carcinôm tuyến >90%) {{Y5 tr.258}} {{Y5 tr.254}}\n- Xếp giai đoạn: CT/siêu âm bụng; **nội soi ổ bụng** (sinh thiết, tế bào dịch) {{Y5 tr.258}}\n- {r|M1}: di căn xa **hoặc dịch rửa ổ bụng có tế bào ác**; hạch ngoài hạch vùng (cạnh động mạch chủ bụng, sau tụy) {{Y5 tr.259}}\n- **N**: cần ==≥16 hạch== để xếp đúng {{Y5 tr.259}}\n- CEA, CA19-9, CA72-4 **không tầm soát**; theo dõi tái phát và di căn {{Y5 tr.259}}\n- CĐPB: viêm loét, trào ngược, khó tiêu chức năng {{128VĐ mục 62}}; GIST (c-KIT) {{QĐ1514 tr.PDF 513}}; lymphôm MALT {{QĐ1514 tr.PDF 441}} {{QĐ1514 tr.PDF 443}}\n[Xem mục 5](#/n/ung-thu-da-day/5) · [mục 6](#/n/ung-thu-da-day/6)\n@@tab Điều trị\n- **Sớm** (T1, biệt hóa, không loét, ≤2 cm): cắt qua nội soi {{Y5 tr.264}}\n- **Cắt dạ dày + nạo hạch** D1/D1+ hoặc D2 theo vị trí và giai đoạn; mục tiêu **R0** {{Y5 tr.262}} {{Y5 tr.263}}\n- **Sau mổ** giai đoạn IB–III: {p|CapeOx} hoặc {p|S-1}, 8 chu kỳ {{Y5 tr.265}}\n- **Hóa–xạ hỗ trợ** sau R0: ==4500 cGy/25 phân liều== + fluorouracil 425 mg/m² + leucovorin 20 mg/m² {{Y5 tr.265}}\n- **Tiến xa/di căn**: hóa trị toàn thân; phẫu thuật chỉ giảm nhẹ {{Y5 tr.261}} {{Y5 tr.262}}\n- **HER2 (+)**: {p|trastuzumab} + XP/FP; trung vị sống còn ==16 vs <12 tháng== {{Y5 tr.266}}\n- {r|Cấp cứu chảy máu}: hồi sức, truyền máu khi Hct >25%, ức chế bơm proton, cầm máu nội soi {{QĐ1514 tr.PDF 73}} {{QĐ1514 tr.PDF 74}}\n[Xem mục 7.2](#/n/ung-thu-da-day/7) · [mục 7.3](#/n/ung-thu-da-day/7)\n@@tab Tiên lượng – Dự phòng\n- Sống 5 năm theo pTNM: IA ==94%== → IV ==5%== {{Y5 tr.260}} {{Y5 tr.261}}\n- Yếu tố: **hạch**, R0, HER2, mô học, vị trí; bệnh nhân Á châu sống còn tốt hơn {{Y5 tr.261}}\n- Theo dõi: 2 năm đầu nguy cơ tái phát cao; giai đoạn I: chất đánh dấu và siêu âm/CT hằng năm, nội soi mỗi 2 năm {{Y5 tr.263}}\n- Dự phòng: {o|tiệt trừ H. pylori}, giảm muối; tầm soát từ 40 tuổi ở nước có chương trình (Nhật, Hàn) {{SY5 tr.193}} {{SY5 tr.174}} {{Y5 tr.254}}\n[Xem mục 8](#/n/ung-thu-da-day/8)\n@@end\n\n### Con số và mốc phải nhớ\n\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Ca mới Việt Nam (Globocan 2018) | ==17.527 ca== (hạng 3) | {{Y5 tr.254}} |\n| Tầm soát Nhật / Hàn | từ ==40 tuổi==; Nhật mỗi năm, Hàn mỗi 2 năm | {{Y5 tr.254}} |\n| HDGC | ~1–3% UT dạ dày; đột biến ==CDH1== | {{Y5 tr.254}} |\n| Muối khuyến cáo WHO | ==dưới 6 g/ngày== (2,4 g natri) | {{SY5 tr.174}} |\n| Số hạch tối thiểu để xếp N | ==≥16 hạch== | {{Y5 tr.259}} |\n| Di căn hạch ngoài hạch vùng | ==M1== | {{Y5 tr.259}} |\n| Cắt qua nội soi (tiêu chuẩn tuyệt đối) | biệt hóa, không loét, ==≤2 cm== | {{Y5 tr.264}} |\n| Diện cắt khi cắt dạ dày D2 | khoảng ==5 cm== | {{Y5 tr.264}} |\n| Hóa–xạ hỗ trợ | ==4500 cGy / 25 phân liều==, 5 ngày/tuần | {{Y5 tr.265}} |\n| Sau mổ D2 (IB–III) | ==CapeOx hoặc S-1, 8 chu kỳ== | {{Y5 tr.265}} |\n| Trastuzumab (HER2+) | trung vị ==16 tháng== (vs <12 tháng) | {{Y5 tr.266}} |\n| Sống 5 năm pTNM | IA ==94%==; IIIC 18%; IV ==5%== | {{Y5 tr.260}} {{Y5 tr.261}} |\n| Truyền máu cấp cứu | Hct ==>25%== (>30% người già, tim mạch) | {{QĐ1514 tr.PDF 73}} |\n| Ức chế bơm proton truyền | ==80 mg/24 giờ, rồi 8 mg/giờ trong 72 giờ== | {{QĐ1514 tr.PDF 74}} |\n| Sụt cân có ý nghĩa | ==>5% trong 6–12 tháng== | {{128VĐ mục 75}} |\n\n> [!warn] Bẫy thi thường gặp\n> - Nguồn lệch về dịch tễ: Y5 tr.253 (Globocan 2012: 952 ngàn ca mới, 723 ngàn tử vong) so với SY5 tr.36 (Globocan 2018: 1.033.701 ca, 782.685 tử vong). Ghi cả hai, nguồn ưu tiên là Y5 cho bài này {{Y5 tr.253}} {{SY5 tr.36}}\n> - Y5 tr.253 xếp UT dạ dày thứ 5 toàn bộ UT; Y5 tr.266 gọi là \"thường gặp thứ hai\" trong UT đường tiêu hóa: cách nói khác nhau {{Y5 tr.253}} {{Y5 tr.266}}\n> - Hạch cạnh động mạch chủ bụng, hạch sau tụy = **M1**, không phải N {{Y5 tr.259}}\n> - Lauren: **ruột → gan**; **lan tỏa → gieo rắc ổ bụng**; hỗn hợp xếp cùng lan tỏa khi lâm sàng {{Y5 tr.255}} {{Y5 tr.256}}\n> - Nuốt nghẹn **tăng dần** gợi ý ung thư thực quản; ung thư dạ dày điển hình là đau thượng vị, sụt cân, chán ăn {{SY5 tr.77}} {{128VĐ mục 60}}\n> - {r|Trastuzumab chỉ dùng khi HER2 (+)}; {r|PPI truyền và cầm máu nội soi là cấp cứu chảy máu} {{Y5 tr.266}} {{QĐ1514 tr.PDF 74}}\n> - Y5 bảng pTNM: IIIA có T4a N1–2; IIIB có T4b N1–2 — đọc đúng hàng, không gộp {{Y5 tr.260}} {{Y5 tr.261}}\n\n@@fold Tự kiểm tra (12 thẻ)\n- Đa số ung thư ác tính dạ dày là mô bệnh học nào? :: Carcinôm tuyến (trên 90%)\n- Hai yếu tố nguy cơ \"rõ ràng\" theo Y5? :: Nhiễm Helicobacter pylori và hút thuốc lá\n- Gen liên quan HDGC và tỉ lệ UT dạ dày do hội chứng này? :: CDH1 (E-cadherin); khoảng 1–3%\n- Phương tiện chẩn đoán đầu tiên của UT dạ dày? :: Nội soi tiêu hóa trên kết hợp sinh thiết giải phẫu bệnh\n- Cần khảo sát tối thiểu bao nhiêu hạch để xếp N? :: 16 hạch\n- Di căn hạch cạnh động mạch chủ bụng được xếp mục nào? :: M1\n- Bướu xâm lấn lớp cơ, 3 hạch (+) trên 20 hạch khảo sát: giai đoạn pTNM? :: T2 N2 M0, giai đoạn IIB (Y5 Bảng 2)\n- Bướu xâm lấn lớp cơ, 2 hạch (+) trên 16 hạch khảo sát: giai đoạn pTNM? :: T2 N1 M0, giai đoạn IIA (Y5 Bảng 2)\n- Sống 5 năm theo pTNM giai đoạn IA và giai đoạn IV? :: IA 94%; IV 5%\n- Tiêu chuẩn tuyệt đối cắt qua nội soi (EMR/ESD)? :: Biệt hóa, không loét, xâm lấn niêm mạc, đường kính ≤2 cm\n- Hóa–xạ hỗ trợ sau cắt R0 theo Y5? :: 4500 cGy trong 25 phân liều, 5 ngày/tuần, kèm fluorouracil 425 mg/m² và leucovorin 20 mg/m²\n- Sau mổ D2 giai đoạn IB–III, hóa trị gì? :: CapeOx hoặc S-1, 8 chu kỳ\n@@end\n\n@@fold Nguồn tài liệu\n- **Y5** tr.253–268: `_work/text-ung-buou-y5.txt` (đọc toàn chương); bảng TNM và pTNM (tr.259–261) đối chiếu ảnh trang\n- **SY5** tr.11, 36, 37–38, 77–78, 174, 193, 195, 200 (`_work/slide-y5.txt`)\n- **QĐ 1514/QĐ-BYT** tr. PDF 33, 71–74, 439, 443, 513 (`_work/qd-1514-byt-ung-buou.txt`; bảng tr.33 đối chiếu ảnh)\n- **ĐC Y5** tr.6: bảng ca lâm sàng dạ dày (1 tiết lên lớp, 2 tiết tự học; MT 2,3,4,5,7,8,9,10,12,13,14,15,17), đối chiếu ảnh trang\n- **128VĐ** mục 59, 60, 62, 64, 67, 75 (`data/book-items.json`)\n- **QĐ 22** STT 7, 49, 50, 52, 54, 56, 99 (`data/qd22.json`); trọng số tr.8\n@@end\n\n@@fold Nguồn ngoài\n- Không dùng nguồn ngoài. Mọi số liệu lấy từ tài liệu đã cung cấp.\n@@end"}, {"kind": "disease", "disease": "daitruc", "short": "Ung thư đại trực tràng", "group": "", "section": 0, "order": 3, "khung": [57, 61, 64], "id": "ung-thu-daitruc-trang", "title": "Ung thư đại trực tràng", "layer": "benh", "module": "ung-buou", "tags": ["ung bướu", "tiêu hóa", "đại trực tràng", "tầm soát", "Lynch", "FAP", "TME", "FOLFOX", "QĐ 2549"], "source": "Y5 tr. 269–300; SY5 tr. 57–63; QĐ 2549/QĐ-BYT (2018) tr. 2–23; 128VĐ mục 126, 72, 68", "body": "> [!key] Tóm tắt\n> - ==Carcinôm tuyến ~90–98%==; tiến triển âm thầm từ pôlyp u tuyến sang ung thư (UT) trong **10–15 năm** nên **tầm soát hiệu quả** {{128VĐ 126}}.\n> - **Đại tràng** (phải: thiếu máu, im lặng; trái: đổi thói quen, tắc ruột) khác **trực tràng** (tiêu máu, mót rặn; tái phát tại chỗ gấp 3 lần) {{Y5 tr.272, 286}}.\n> - Chẩn đoán xác định: **nội soi + sinh thiết**; xếp giai đoạn TNM. Đại tràng: mổ cắt đoạn + hạch ± hóa trị bổ trợ (III, II nguy cơ cao). Trực tràng: **TME** ± hóa-xạ trị tiền phẫu (giữa/thấp T3–4 hoặc N+).\n> - Khung thi: [STT 64 tầm soát](#/khung/64) · [STT 61 thay đổi thói quen đi tiêu](#/khung/61) · [STT 57 XHTH dưới](#/khung/57).\n\n## 3. Bệnh học\n\n### Định nghĩa – dịch tễ\n- \"UT đại tràng\" và \"UT trực tràng\" thường chỉ carcinôm tuyến. **Trực tràng** = đoạn ruột già cách rìa hậu môn 15 cm: ==thấp <5 cm, giữa 5–10 cm, cao >10 cm== {{Y5 tr.285}}.\n- Nguồn Y5 nhấn mạnh trực tràng khác đại tràng về giải phẫu, triệu chứng, điều trị, kiểu tái phát và sinh học phân tử nên xem là thực thể riêng {{Y5 tr.285}}.\n\n| | Đại tràng | Trực tràng |\n|---|---|---|\n| Thế giới | UT đại-trực tràng ~1 triệu ca/năm, 9–10% các UT; cao nhất Âu, Mỹ, Úc, New Zealand {{Y5 tr.269}} | Châu Âu 125.000 ca/năm, 35% UT đại-trực tràng {{Y5 tr.286}} |\n| Hoa Kỳ | UT gây tử vong hàng 2; tần suất hàng 3; đỉnh 1985 rồi giảm nhờ tầm soát {{Y5 tr.269}} | không nêu riêng |\n| Tuổi | >94% trên 44 tuổi; trung vị 68 {{Y5 tr.269}} | trung vị 70 {{Y5 tr.286}} |\n| Việt Nam | Globocan 2018: hàng thứ 5, 14.733 ca mới; TP.HCM 2016 hàng 3 (nam), 4 (nữ) {{Y5 tr.269}} | dùng chung |\n- {{QĐ2549 tr.2}}: Globocan 2012: **thứ 3** về mắc (10%), **thứ 4** về tử vong (8,5%); VN tỷ lệ mắc chuẩn tuổi 10,1/100.000, hàng thứ 6; Hà Nội 7,5/100.000.\n\n> [!warn] Số liệu VN khác nhau giữa nguồn: Y5 (Globocan 2018) hàng thứ **5**; QĐ 2549 (Globocan 2012) hàng thứ **6**. Ghi rõ năm nguồn khi trả lời.\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Không thay đổi được\n- **Tuổi** (>94% >44 tuổi) {{Y5 tr.269}}.\n- **Tiền sử gia đình**: người thân cấp 1 bị UT <50 tuổi nguy cơ ==gấp 2 lần==; hai người thân cấp 1: ==gấp 3–4 lần== {{Y5 tr.270}}.\n- ~5% có nguồn gốc di truyền rõ. **Hội chứng di truyền**:\n  - **Lynch** (HNPCC, gen MMR): thường gặp nhất; 70% bị UT, 40% trong số đó <40 tuổi {{Y5 tr.270}}.\n  - **FAP** (gen APC): 100% bị UT, trung vị 39 tuổi; 100–1000 pôlyp từ <20 tuổi {{Y5 tr.270}}.\n  - PPAP (<100 pôlyp), **MAP** (MutYH; nguy cơ ×28), NAP (NATH1): 10–50 pôlyp ở tuổi 40 {{Y5 tr.271}}.\n  - QĐ 2549 còn nêu Peutz-Jeghers, Gardner {{QĐ2549 tr.2}}.\n- **Tổn thương tiền UT**: pôlyp tân sinh (u tuyến), **viêm loét đại tràng** (nguy cơ tích lũy 2%/8%/18% sau 10/20/30 năm), **Crohn** (×1,5–2) {{Y5 tr.270}}; QĐ nêu viêm đại trực tràng chảy máu, Crohn, pôlyp {{QĐ2549 tr.2}}.\n@@tab Thay đổi được\n- **Ăn kiểu Tây hóa** (nhiều béo, nhiều thịt/mỡ động vật, ít xơ; thiếu canxi, vitamin) {{Y5 tr.270}} {{QĐ2549 tr.2}}; thực phẩm chứa benzopyren, nitrosamin {{QĐ2549 tr.2}}.\n- **Hút thuốc** 20 năm: nguy cơ u tuyến ×2–3 {{Y5 tr.271}}.\n- Yếu tố **bảo vệ**: canxi, vitamin D, aspirin/NSAID (đại tràng); vitamin A, C, E, beta caroten **không** giảm nguy cơ {{Y5 tr.270}}.\n- **Pôlyp** nguy cơ hóa ác cao: ==>1 cm==, dị sản độ cao, thành phần nhánh (villous). Cắt pôlyp qua nội soi giảm nguy cơ UT tới 90% {{Y5 tr.270}}.\n@@tab Khác biệt ở trực tràng\n- Vận động, BMI thấp **không** giảm nguy cơ UT trực tràng; aspirin **không** phòng ngừa; Lynch **ít gặp hơn** {{Y5 tr.286}}.\n@@end\n\n### Sinh bệnh học – sinh học phân tử\n- Chuỗi u tuyến → carcinôm, tích lũy đột biến. <10% do hội chứng di truyền, 25% có người thân bị UT, 70% không có yếu tố di truyền rõ {{Y5 tr.273}}.\n\n| Con đường | Đặc điểm |\n|---|---|\n| **CIN / APC** | Mất ổn định nhiễm sắc thể; **mất APC** là biến cố sớm (~80% ca không di truyền); còn RAS, TP53, mất NST 18; đột biến mầm APC = FAP {{Y5 tr.273}} |\n| **MMR → MSI-H** | Đột biến mầm gen MMR = **Lynch** (~3–5% UT đại-trực tràng); MSI-H cũng gặp ở ca không di truyền do methyl hóa MLH1 {{Y5 tr.273}} |\n| **CIMP** | Tăng methyl hóa → mất MMR → MSI-H; hay có đột biến **BRAF**, tiên lượng xấu {{Y5 tr.274}} |\n\n| Kiểu hình | Trực tràng | Đại tràng |\n|---|---|---|\n| CIN, TP53 | thường | ít |\n| MSI, CIMP, KRAS, BRAF | ít | thường |\n*(Y5 tr.290 bảng 1)*\n\n### Giải phẫu bệnh\n- Đại thể: sùi, thâm nhiễm, loét; vòng nhẫn {{QĐ2549 tr.3}}. Độ biệt hóa grade 1–4 (1 tốt … 4 không biệt hóa) {{QĐ2549 tr.4}}.\n- Vi thể: **carcinôm tuyến** (đại tràng ~98% {{Y5 tr.271}}; trực tràng 90–95% {{Y5 tr.286}}; QĐ nêu 80% typ Lieberkühn, 10–20% dạng nhầy {{QĐ2549 tr.3}}); **tuyến nhày** (>50% chất nhày, người trẻ, tiên lượng xấu); **tế bào nhẫn** ~1%; UT không biểu mô (lymphoma, carcinoid…) ~5% {{QĐ2549 tr.3}}.\n\n### Diễn tiến tự nhiên – lan tràn\n- Xâm lấn theo chiều sâu thành ruột → hạch bạch huyết → cơ quan lân cận (chủ yếu **gan**) {{QĐ2549 tr.3}}. Di căn hạch vùng 40–70% lúc mổ {{Y5 tr.271}}.\n- Di căn xa: **gan, phúc mạc, phổi**; ít: buồng trứng, thượng thận, xương; não hiếm {{Y5 tr.272}}.\n\n| | Đại tràng | Trực tràng |\n|---|---|---|\n| Dẫn lưu | tĩnh mạch cửa → hay di căn **gan** | tĩnh mạch chủ dưới **và** cửa → di căn **phổi** nhiều hơn |\n| Tái phát tại chỗ | thấp hơn | ==gấp 3 lần==: nằm khung chậu, khó cắt rộng, 2/3 dưới không có thanh mạc {{Y5 tr.286}} |\n\n## 4. Triệu chứng học\n\n### Triệu chứng cơ năng – thực thể\n@@tabs\n@@tab Đại tràng phải\n- Thường **im lặng**; khi có triệu chứng thì bệnh đã nặng: đau bụng, XHTH, **thiếu máu thiếu sắt** (mệt, sụt cân), hiếm tắc ruột {{Y5 tr.272}}.\n- QĐ 2549: u đại tràng phải đau kiểu Koernig {{QĐ2549 tr.2}}.\n@@tab Đại tràng trái\n- **Đổi thói quen đi tiêu**, xuất huyết, đau, **giảm khẩu kính phân**, tắc ruột {{Y5 tr.272}}.\n- QĐ 2549: u trái đau kiểu tắc ruột; sigma đau hạ vị kèm đi ngoài nhiều lần {{QĐ2549 tr.2}}.\n@@tab Trực tràng\n- **Tiêu ra máu**, đổi thói quen/khẩu kính phân nhỏ, đau và cảm giác nặng trực tràng, sụt cân {{Y5 tr.286}}.\n- ==Mót rặn==: bướu to, nghĩ giai đoạn II–III xâm lấn vách chậu/xương cùng/tạng lân cận; **đau, són phân**: tổn thương cơ thắt {{Y5 tr.287}}.\n- Hỏi chức năng cơ thắt và tình dục trước mổ {{Y5 tr.287}}.\n@@end\n- Chung (QĐ 2549): rối loạn lưu thông (táo bón hoặc ỉa chảy), **đi ngoài ra nhầy máu là triệu chứng hay gặp nhất** {{QĐ2549 tr.2}}.\n- Khám: sờ u qua thành bụng (lổn nhổn, cứng, di động, không đau); **thăm trực tràng** thấy u trực tràng thấp và giữa {{QĐ2549 tr.2}}.\n- Toàn thân: thiếu máu, gầy sút 5–10 kg/2–4 tháng, suy nhược {{QĐ2549 tr.2}}.\n- Di căn/biến chứng: **hạch thượng đòn (trái)**, báng bụng, gan to, vàng da, di căn buồng trứng; bán tắc/tắc ruột, thủng u gây viêm phúc mạc {{QĐ2549 tr.2}} {{Y5 tr.272}}.\n\n> [!red] Dấu hiệu báo động: tiêu máu kéo dài, thay đổi thói quen đi tiêu mới ở người lớn tuổi, phân nhỏ dẹt, **thiếu máu thiếu sắt không rõ nguyên nhân**, sụt cân, khối bụng, mót rặn, tắc ruột/thủng.\n\n### Tiếp cận theo khung 128 vấn đề\n| STT | Vấn đề | Cần nghĩ tới UT đại trực tràng khi |\n|---|---|---|\n| [57](#/khung/57) | XHTH dưới (dưới góc Treitz; túi thừa 30% là thường nhất; u tân sinh đại-trực tràng 5–15% {{128VĐ 68}}) | tiêu máu đỏ tươi/bầm lẫn phân kèm đổi thói quen, phân nhỏ, thiếu máu; **luôn thăm trực tràng** + nội soi |\n| [61](#/khung/61) | Táo bón, thay đổi thói quen đi tiêu {{128VĐ 72}} | cơ chế **hẹp lòng ruột (u ác tính)** thuộc nhóm \"rối loạn làm đầy trực tràng\"; có triệu chứng báo động → nội soi đại trực tràng |\n| [64](#/khung/64) | Tầm soát UT đại trực tràng {{128VĐ 126}} | xem mục 8 |\n\n## 5. Cận lâm sàng\n\n### Nội soi – hình ảnh – dấu ấn\n| Phương tiện | Vai trò |\n|---|---|\n| **Nội soi đại tràng ống mềm** | Xác định vị trí, **sinh thiết (giải phẫu bệnh)**; phát hiện UT đồng thời (~3%) hoặc pôlyp {{Y5 tr.272}} {{QĐ2549 tr.2}} |\n| **Soi trực tràng ống cứng** + thăm trực tràng | Sinh thiết; khoảng cách rìa hậu môn, chu vi, liên quan cơ thắt/âm đạo/tiền liệt tuyến; DRE **không dùng đơn độc** để xếp giai đoạn {{Y5 tr.287}} |\n| X quang bụng không chuẩn bị | Cấp cứu: tắc ruột, thủng {{QĐ2549 tr.3}} |\n| **CT bụng-chậu + X quang/CT ngực** | Di căn xa (CT chẩn đoán 99% di căn gan, 33% di căn phúc mạc); hạch nghi ngờ: >8 mm, tròn, bờ không đều {{Y5 tr.272}} |\n| **MRI** | Di căn gan chưa rõ; ở trực tràng: **MRI vùng chậu** đánh giá diện cắt bên (≤1 mm, MERCURY), mạc treo, hạch; nên dùng xếp giai đoạn tại chỗ trước điều trị tiền phẫu {{Y5 tr.289}} |\n| Siêu âm qua nội trực tràng | Mức xâm lấn T (chính xác 87%), hạch cạnh trực tràng (74%) {{Y5 tr.289}} {{QĐ2549 tr.3}} |\n| PET/CT | Tái phát, di căn xa; CEA tăng mà hình ảnh âm tính {{Y5 tr.289}} {{QĐ2549 tr.3}} |\n| Xạ hình xương/gan, SPECT | Di căn xương (Tc99m-MDP), gan (Tc99m-SC) {{QĐ2549 tr.3}} |\n| **CEA** (± CA 19-9) | Định lượng trước mổ (cao = tiên lượng xấu; không về bình thường sau mổ = còn bệnh); theo dõi tái phát (nhạy 70–80%) {{Y5 tr.273}} {{QĐ2549 tr.3}} |\n\n### Mô bệnh học – sinh học phân tử\n- Sau mổ triệt căn: độ mô học, T, **số hạch vét ≥ 12**, hạch (+), các diện cắt, xâm lấn thần kinh/mạch máu/bạch huyết, nhân mạc treo ngoài hạch {{QĐ2549 tr.3}}.\n- **MSI (PCR) hoặc MMR (hóa mô miễn dịch)** ở UT đại tràng giai đoạn II: dMMR/MSI-H tiên lượng tốt và **không lợi** từ 5-FU bổ trợ {{QĐ2549 tr.3}}.\n- UT di căn: xét nghiệm **KRAS, NRAS, BRAF** (tiên lượng, chọn thuốc đích); KRAS không đột biến thì làm thêm NRAS {{QĐ2549 tr.3, 13}}.\n\n### Phân giai đoạn TNM\n@@tabs\n@@tab Theo QĐ 2549 (UICC/AJCC 2010)\n- **T**: Tis tại chỗ; T1 dưới niêm; T2 lớp cơ; T3 quá cơ vào dưới thanh mạc/mô quanh ruột không phủ phúc mạc; T4a xuyên thanh mạc/thủng phúc mạc tạng; T4b xâm lấn cơ quan kế cận {{QĐ2549 tr.4}}.\n- **N**: N1a (1 hạch), N1b (2–3), N1c (nốt lắng đọng không hạch); N2a (4–6), N2b (≥7) {{QĐ2549 tr.4}}.\n- **M**: M1a một cơ quan; M1b ≥2 cơ quan/vùng **hoặc** lan tràn phúc mạc {{QĐ2549 tr.5}}.\n\n| GĐ | T | N | M | Dukes |\n|---|---|---|---|---|\n| 0 | Tis | N0 | M0 | |\n| I | T1–2 | N0 | M0 | A |\n| IIA | T3 | N0 | M0 | B |\n| IIB | T4a | N0 | M0 | B |\n| IIC | T4b | N0 | M0 | B |\n| IIIA | T1–2 | N1/N1c | M0 | C |\n| IIIA | T1 | N2a | M0 | C |\n| IIIB | T3–4a | N1/N1c | M0 | C |\n| IIIB | T2–3 | N2a | M0 | C |\n| IIIB | T1–2 | N2b | M0 | C |\n| IIIC | T4a | N2a | M0 | C |\n| IIIC | T3–4a | N2b | M0 | C |\n| IIIC | T4b | N1–2 | M0 | C |\n| IVA | bất kỳ | bất kỳ | M1a | |\n| IVB | bất kỳ | bất kỳ | M1b | |\n*(QĐ2549 tr.5)*\n@@tab Theo Y5 (UICC 2017, bản 8)\n- **T**: T1 dưới niêm; T2 cơ; T3 qua cơ; T4a bề mặt phúc mạc tạng; T4b cơ quan/cấu trúc lân cận {{Y5 tr.274}}.\n- **N**: N1a 1 hạch; N1b 2–3; **N1c** nốt vệ tinh; N2a 4–6; N2b ≥7 {{Y5 tr.275}}.\n- **M**: M1a một vị trí/cơ quan; M1b ≥2 vị trí **không** lan phúc mạc; ==M1c di căn phúc mạc== (± nội tạng) {{Y5 tr.275}}.\n\n| GĐ | T | N | M |\n|---|---|---|---|\n| 0 | Tis | N0 | M0 |\n| I | T1–2 | N0 | M0 |\n| IIA / IIB / IIC | T3 / T4a / T4b | N0 | M0 |\n| IIIA | T1; T1–2 | N2a; N1 | M0 |\n| IIIB | T1–2; T2–3; T3–4a | N2b; N2a; N1 | M0 |\n| IIIC | T3; T4a; T4b | N2b; N2; N1–2 | M0 |\n| IVA / IVB / IVC | bất kỳ | bất kỳ | M1a / M1b / M1c |\n*(Y5 tr.275, 290; trực tràng dùng cùng bảng)*\n@@end\n\n> [!warn] Hai nguồn dùng hai phiên bản TNM: QĐ 2549 (2010) chỉ có M1a/M1b (phúc mạc nằm trong M1b) và có cột Dukes; Y5 (2017) có **M1c = phúc mạc** và giai đoạn IVC. Bẫy thi: xem đề hỏi theo nguồn nào.\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Chẩn đoán xác định = **tổn thương qua nội soi + mô bệnh học (sinh thiết)**; mô bệnh học là phương pháp **quyết định nhất**. Lâm sàng và hình ảnh (siêu âm, CT, MRI, SPECT, PET/CT) dùng để đánh giá giai đoạn {{QĐ2549 tr.4}} {{Y5 tr.272}}.\n\n- Quy trình: triệu chứng/tầm soát dương tính → thăm trực tràng → **nội soi toàn bộ đại tràng + sinh thiết** (loại trừ UT đồng thời 2–8%) → CT bụng-chậu + ngực ± MRI vùng chậu (trực tràng), CEA → TNM.\n\n### Chẩn đoán phân biệt\n| Bệnh lý | Điểm giống | Phân biệt |\n|---|---|---|\n| Bệnh Crohn {{QĐ2549 tr.4}} | đau bụng, tiêu chảy, thiếu máu, hẹp ruột | loét dọc/\"lát đường\", tổn thương nhảy cóc, u hạt trên sinh thiết; cũng là yếu tố nguy cơ UT |\n| Viêm loét đại trực tràng {{QĐ2549 tr.4}} | tiêu nhầy máu | viêm lan tỏa liên tục từ trực tràng; sinh thiết viêm mạn, không có tế bào ác |\n| Lao manh tràng {{QĐ2549 tr.4}} | khối hố chậu phải, thiếu máu | bệnh học lao (u hạt hoại tử bã đậu), lao nơi khác |\n| Lymphoma, GIST, UT khác xâm lấn đại trực tràng {{QĐ2549 tr.4}} | khối thành ruột | hóa mô miễn dịch (CD20…, CD117/DOG1) trên sinh thiết |\n| Khối u lành, pôlyp {{QĐ2549 tr.4}} | chảy máu, thấy khi nội soi | mô bệnh học không xâm lấn; pôlyp tân sinh là tổn thương tiền UT |\n| UT ống hậu môn {{QĐ2549 tr.4}} | khối hậu môn, chảy máu | thường carcinôm tế bào gai, vị trí ở ống hậu môn |\n| Trĩ, nứt hậu môn {{+Kiến thức lâm sàng chung}} | máu đỏ tươi quanh phân | nhìn/soi hậu môn thấy; **không loại trừ UT** nếu có triệu chứng báo động hoặc >45 tuổi |\n| Bệnh túi thừa {{+Kiến thức lâm sàng chung}} | XHTH dưới (nguyên nhân hàng đầu 30% {{128VĐ 68}}), đau hố chậu trái | nội soi/CT thấy túi thừa; có thể đồng tồn tại UT |\n| Thiếu máu thiếu sắt do nguyên nhân khác, hội chứng ruột kích thích {{+Kiến thức lâm sàng chung}} | mệt, đổi thói quen đi tiêu | IBS: không có dấu báo động, nội soi bình thường |\n\n> [!ext] Mục chẩn đoán phân biệt: ba dòng cuối và các điểm phân biệt cụ thể là kiến thức lâm sàng thông dụng do người soạn tổng hợp, **chưa đối chiếu nguồn mở cụ thể**; danh sách bệnh có pill QĐ lấy từ QĐ 2549 tr.4.\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n- **Giai đoạn sớm/tại chỗ (0–III)**: ==điều trị triệt căn== (cắt hết u + hạch, **R0**), lập lại lưu thông tiêu hóa; bảo tồn cơ thắt ở trực tràng {{QĐ2549 tr.10, 20}}.\n- **Bổ trợ/tân bổ trợ**: giảm tái phát và di căn, tăng sống còn; ở trực tràng thêm **giảm tái phát tại chỗ**, giảm bướu để tăng bảo tồn cơ thắt {{Y5 tr.276, 296}}.\n- **Giai đoạn IV**: cắt di căn nếu có thể (gan/phổi); không mổ được: hóa trị ± đích để **kiểm soát bệnh, giảm triệu chứng, kéo dài sống còn** (nhóm 1 thu nhỏ u để đạt R0; nhóm 2 kiểm soát bệnh) {{QĐ2549 tr.7}}.\n- **Giảm nhẹ**: giảm đau, giải quyết biến chứng (tắc, chảy máu, thủng), chăm sóc nâng đỡ {{QĐ2549 tr.7, 9}}.\n- Điều trị **đa mô thức** và hội chẩn; chất lượng phẫu thuật là yếu tố tiên lượng chính {{Y5 tr.291}}.\n\n### 7.2 Các phương pháp\n\n@@tabs\n@@tab UT đại tràng\n#### Phẫu thuật {{QĐ2549 tr.10}} {{Y5 tr.276}}\n- Nguyên tắc: lấy rộng u + vét hạch vùng, lập lại lưu thông. Diện cắt cách u ==5 cm==; **cắt rộng mạc treo**; vét **≥ 12 hạch** {{QĐ2549 tr.10}}.\n- **Pôlyp ung thư hóa**: giai đoạn 0 và T1N0 nguy cơ thấp (G1–2, không xâm lấn mạch bạch huyết, nguy cơ di căn hạch <4%) → chỉ cắt pôlyp nội soi (R0). Nguy cơ cao (G>2, xâm lấn mạch/bạch huyết, diện cắt <1 mm, pôlyp không cuống xâm lấn) hoặc >T1N0 → **cắt đại tràng + vét hạch** {{QĐ2549 tr.10}}.\n- Cắt theo vị trí: đại tràng lên → **cắt đại tràng phải**; góc gan → phải mở rộng; ngang → cắt đại tràng ngang (hoặc cắt mở rộng); xuống → **cắt đại tràng trái**; sigma → cắt đại tràng sigma (thắt ĐM mạc treo tràng dưới) {{QĐ2549 tr.10}}.\n- Mổ nội soi là lựa chọn có thể thay mổ mở {{Y5 tr.277}}. Mổ \"no touch\" không ưu thế sống còn {{QĐ2549 tr.10}}.\n- **Biến chứng** {{QĐ2549 tr.11}}:\n  - Tắc ruột do u phải/góc gan: cắt đại tràng nối ngay 1 thì. Do u trái: **Hartmann** (hoặc mổ 2 thì, hậu môn nhân tạo kép).\n  - Thủng viêm phúc mạc toàn thể: cắt đại tràng + hậu môn nhân tạo. Chảy máu: cắt u cầm máu hoặc **tắc mạch**.\n- **Giai đoạn IV**: cắt di căn gan/phổi chỉ khi u nguyên phát triệt căn được và không có di căn cơ quan khác; có thể cắt cùng thì hoặc hai thì; nút nhánh tĩnh mạch cửa để phì đại gan còn lại; đốt sóng cao tần, tiêm cồn, áp lạnh. Đánh giá lại khả năng cắt sau **2 tháng** hóa trị {{QĐ2549 tr.10–11}}.\n#### Xạ trị {{QĐ2549 tr.11–12}}\n- Ít đặt ra ở đại tràng; chủ yếu **xạ trị di căn/triệu chứng**: SIRT Y-90 (≤3 ổ gan, mỗi ổ ≤3 cm, PS ≤2), SBRT, xạ di căn phổi, xương (giảm đau), não (xạ phẫu ≤3 ổ).\n#### Hóa trị bổ trợ {{QĐ2549 tr.12–13}}\n- **Chỉ định**: giai đoạn **III** và giai đoạn **II có yếu tố nguy cơ cao** (nhập viện do tắc/thủng, <12 hạch, diện cắt (+), kém biệt hóa, xâm lấn mạch máu/bạch huyết/thần kinh). Giai đoạn II T3N0 không nguy cơ cao: cân nhắc nếu MSI-L/MSS.\n- Phác đồ ưa chuộng: **FOLFOX, CapeOX**; còn FUFA (Mayo), capecitabine, FOLFOX4/6/7. Thể trạng rất yếu: capecitabine đơn thuần.\n- **Bắt đầu càng sớm càng tốt, sau mổ 4–8 tuần** {{QĐ2549 tr.23}}; **duy trì trong vòng 6 tháng** {{QĐ2549 tr.13}}.\n#### Giai đoạn di căn {{QĐ2549 tr.13–14, 17}}\n- Bước 1: hóa trị (FOLFOX/CapeOX/FOLFIRI) **+ đích**: bevacizumab; hoặc kháng EGFR (cetuximab/panitumumab) **chỉ khi RAS hoang dã và u bên trái**. FOLFOXIRI ± bevacizumab khi cần co u hoặc BRAF đột biến. Không phối kháng EGFR với capecitabine/5-FU viên.\n- Duy trì: sau 6 chu kỳ CAPOX/8 chu kỳ FOLFOX → **fluoropyrimidine + bevacizumab** (không đơn trị bevacizumab).\n- Bước 2: đổi oxaliplatin ↔ irinotecan; aflibercept/ramucirumab chỉ với FOLFIRI. Bước 3–4: **regorafenib** hoặc **trifluridine/tipiracil**. **Pembrolizumab/nivolumab** chỉ khi **MSI-H/dMMR**.\n@@tab UT trực tràng\n#### Phẫu thuật {{QĐ2549 tr.20–21}} {{Y5 tr.292–294}}\n- Rất sớm (cT1N0 sm1/2, G1–2): **cắt u qua hậu môn (TEM)**. Y5: giai đoạn I nguy cơ thấp (<3 cm, <30% chu vi, biệt hóa cao/trung bình) cắt tại chỗ.\n- cT1 (sm2 hoặc G3–4, xâm lấn mạch) và cT2N0: **cắt trực tràng + TME**.\n- **TME** chuẩn cho trực tràng **giữa và thấp**; trực tràng **cao**: cắt một phần mạc treo (5 cm dưới u). Mạc treo phải nguyên vẹn, vét **≥12 hạch**, **diện cắt bên** quan trọng nhất; nghi diện cắt (+): cắt thêm đến R0.\n- **Miles (cắt cụt bụng–tầng sinh môn)**: u xâm lấn cơ thắt hoặc rất thấp không bảo tồn được cơ thắt (QĐ: rìa u cách mép hậu môn **<4 cm**, T3–4 hoặc N+; Y5: diện cắt xa <1 cm).\n- Bảo tồn cơ thắt: diện cắt dưới cách u 1 cm thường bảo tồn được; chuyển lưu phân tạm thời khi nối thấp.\n- **Mổ nội soi**: QĐ 2549 – kết quả ung thư học tương đương ở trung tâm có kinh nghiệm; Y5 – **chưa** thay được mổ mở.\n- **Thời điểm mổ**: sau xạ ngắn ngày 2–4 ngày (nơi khác trong QĐ: 1–2 tuần); sau hóa-xạ tiền phẫu **4–8 tuần**; >80 tuổi hoặc PS 3–4: trì hoãn 8 tuần sau xạ ngắn ngày {{QĐ2549 tr.20–21}}.\n#### Xạ trị – hóa xạ trị {{QĐ2549 tr.21–22}}\n- **Tiền phẫu**: (1) **ngắn ngày** 25 Gy/5 lần (5 Gy/lần) cho trực tràng trung bình T3b hoặc thấp T2; (2) **dài ngày** 45 Gy/25 lần (1,8 Gy) + 5-FU/capecitabine, mổ sau 4–8 tuần.\n- ==Hóa-xạ tiền phẫu== cho trực tràng thấp/trung bình **T3–4, N±** {{QĐ2549 tr.22}} (Y5: giữa/thấp T3–4 hoặc cN+ trên MRI {{Y5 tr.295}}).\n- **Hậu phẫu**: 45 Gy (+ boost 5,4–9 Gy), tối đa ruột non 45 Gy; chỉ khi chưa xạ tiền phẫu và có diện cắt (+), thủng, nguy cơ tái phát cao (≥pT3b và/hoặc N+). Xạ đơn thuần bổ trợ **không** áp dụng.\n- Xạ tiền phẫu giảm tái phát tại chỗ, **không cải thiện sống còn** {{Y5 tr.295}}.\n- Giảm nhẹ (không mổ được/tái phát): >54 Gy nếu kỹ thuật cho phép {{QĐ2549 tr.22}}.\n#### Hóa trị bổ trợ {{QĐ2549 tr.22–23}}\n- Dữ liệu còn hạn chế/tranh cãi (Y5: **chưa chắc chắn**). QĐ chỉ định cho giai đoạn II–III nguy cơ cao: FOLFOX4 12 chu kỳ hoặc XELOX 6 chu kỳ; bắt đầu **4–8 tuần** sau mổ; tổng thời gian 5,5–6 tháng (nếu đã hóa-xạ tiền phẫu: bổ trợ 4–4,5 tháng).\n- **Không cần** bổ trợ: giai đoạn II nguy cơ thấp (UTTT cao pT3N0, TME, >12 hạch, diện cắt âm), hoặc không đáp ứng hóa-xạ tiền phẫu.\n#### Giai đoạn M1 {{QĐ2549 tr.20–21}}\n- Mổ được ngay: TME + cắt di căn; T3–4N+M1: hóa trị trước, rồi TME, sau đó hóa-xạ bổ trợ. Có tiềm năng mổ: hóa trị, **sau 3 đợt** đánh giá lại. Hết khả năng: hóa trị triệu chứng, mổ giảm nhẹ (hậu môn nhân tạo kiểu Mickulicz, nối tắt).\n@@tab Theo giai đoạn\n| Giai đoạn | Đại tràng | Trực tràng |\n|---|---|---|\n| 0, I | Cắt pôlyp/cắt niêm mạc; T2: cắt đại tràng + vét hạch | TEM (cT1 thấp nguy cơ); T2N0: TME |\n| II | Cắt đại tràng; hóa trị bổ trợ nếu **nguy cơ cao** | cT3N0 giữa/thấp: hóa-xạ tiền phẫu + TME; cao: mổ ngay |\n| III | Cắt đại tràng + **hóa trị bổ trợ** (FOLFOX/CapeOX 6 tháng) | Hóa-xạ tiền phẫu + TME ± hóa trị bổ trợ |\n| IV | Cắt di căn khi được; hóa trị ± đích | Mổ/can thiệp di căn + hóa trị; không mổ: hóa trị, xạ giảm nhẹ |\n@@end\n\n> [!doc] Lược đồ QĐ 2549 (sơ đồ 1 và 5, ảnh tr.6, 18)\n> - Đại tràng M0: pTis–2N0 hoặc pT3N0 không nguy cơ → theo dõi; **pT3N0 có yếu tố nguy cơ hoặc N+ → hóa trị bổ trợ**; chống chỉ định mổ → hóa trị.\n> - Đại tràng M1: di căn gan/phổi can thiệp tại chỗ được → can thiệp + hóa trị; phúc mạc có tắc → cắt đại tràng/hậu môn nhân tạo; xương/não → cân nhắc xạ trị.\n> - Trực tràng: cT1N0 biệt hóa cao/vừa → cắt qua hậu môn; cT2N0 hoặc cT3N0 cao → TME, pT3–4/N+ → hóa-xạ bổ trợ; cT3N0 thấp–trung bình hoặc N+ → **hóa-xạ đồng thời trước mổ**.\n\n### 7.3 Phác đồ – Y lệnh\n\n> [!doc] Theo **QĐ 2549/QĐ-BYT ngày 19/4/2018**, mục 4.1.4 (PDF tr.14–17) và 4.2.4 (tr.22). Liều chép theo văn bản; thực tế điều chỉnh theo diện tích da, chức năng gan-thận, độc tính.\n\n@@fold! Hóa trị (PDF tr.14–16)\n| Phác đồ | Thuốc – liều | Chu kỳ | Chỉ định / ghi chú |\n|---|---|---|---|\n| **FOLFOX4** | Oxaliplatin 85 mg/m² TTM ngày 1; Leucovorin 200 mg/m² ngày 1, 2; 5-FU 400 mg/m² tiêm TM ngày 1, 2; 5-FU 600 mg/m² truyền 22 giờ ngày 1, 2 | 2 tuần | Bổ trợ, di căn |\n| **FOLFOX6** | Oxaliplatin 100 mg/m² ngày 1; LV 200 mg/m² ngày 1, 2; 5-FU 400 mg/m² tiêm ngày 1, 2; 5-FU 600 mg/m² truyền 22 giờ ngày 1, 2 | 2 tuần | |\n| **mFOLFOX6** | Oxaliplatin 85 mg/m²; LV 350 mg/m² ngày 1; 5-FU 400 mg/m² tiêm ngày 1, sau đó 5-FU 2,4 g/m² truyền 46 giờ | 2 tuần | Phổ biến nhất |\n| **FOLFOX7** | Oxaliplatin 130 mg/m²; LV 400 mg/m² ngày 1; 5-FU 2,4 g/m² truyền 46 giờ | 2 tuần | |\n| **FOLFIRI** | Irinotecan 180 mg/m² ngày 1; LV 200 mg/m² ngày 1, 2; 5-FU 400 mg/m² tiêm chậm ngày 1, 2; 5-FU 600 mg/m² truyền ngày 1, 2 | 2 tuần | Di căn |\n| **FOLFOXIRI** | Irinotecan 165 mg/m²; Oxaliplatin 85 mg/m²; LV 200 mg/m² ngày 1; 5-FU 3200 mg/m² truyền 48 giờ | 2 tuần | Cần co u; BRAF đột biến |\n| **XELOX/CapeOX** | Oxaliplatin 130 mg/m² ngày 1; Capecitabine 1000 mg/m² uống 2 lần/ngày × 14 ngày | 3 tuần | Bổ trợ (6 chu kỳ), di căn |\n| **XELIRI** | Irinotecan 240–250 mg/m² (90 phút) ngày 1 + Capecitabine 1000 mg/m² × 14 ngày; hoặc Irinotecan 175 mg/m² (30 phút) + Capecitabine 1000 mg/m² × 7 ngày | 3 tuần; hoặc 2 tuần | |\n| **Capecitabine** | 1250 mg/m² uống 2 lần/ngày × 14 ngày | 3 tuần | Thể trạng yếu |\n| **FuFa Mayo** | LV 20 mg/m²/ngày + 5-FU 425 mg/m²/ngày, TM ngày 1–5 | (QĐ không ghi) | Bổ trợ |\n| TS-1 | 60–80 mg/m² uống ngày 1–14 (21 ngày) hoặc ngày 1–28 (42 ngày) | 3 hoặc 6 tuần | |\n| UFT | UFT 100 mg/m²/lần × 3 lần/ngày + folinic 30 mg/m²/lần × 3 lần/ngày, ngày 1–28; hoặc UFT 100–125 mg/m²/lần × 3 lần/ngày ngày 1–14 | 5 tuần; 21 ngày | |\n| ILF | Irinotecan 125 mg/m² + LV 20 mg/m² + 5-FU 500 mg/m², hằng tuần × 4, nghỉ 2 tuần | 6 tuần | |\n| Irinotecan đơn | 350 mg/m² (30 phút) ngày 1; hoặc 125 mg/m² (90 phút) hằng tuần × 4 | 21 ngày; 6 tuần | |\n| Oxaliplatin đơn | 130 mg/m² truyền 2 giờ ngày 1 | 21 ngày | |\n| 5-FU đơn | 3500 mg/m² truyền 48 giờ hằng tuần | hằng tuần | |\n| IRINOX | Irinotecan 180 mg/m² (90 phút) + Oxaliplatin 85 mg/m² (2 giờ) ngày 1 | 14 ngày | |\n| **Trifluridine/tipiracil** | 35 mg/m² (tối đa 80 mg/lần) uống 2 lần/ngày, ngày 1–5 và 8–12 | 28 ngày | Bước 3–4 |\n@@end\n\n@@fold! Thuốc đích – miễn dịch (PDF tr.16–17)\n| Thuốc | Liều | Chỉ định / ghi chú |\n|---|---|---|\n| **Bevacizumab** | 5–15 mg/kg TTM, phối hợp hóa trị 14–21 ngày/lần | Di căn; duy trì sau ổn định bệnh (cùng fluoropyrimidine) |\n| **Cetuximab** | 400 mg/m² ngày 1, sau đó 250 mg/m² hằng tuần; hoặc 500 mg/m² mỗi 2 tuần | Di căn, **KRAS và NRAS không đột biến** (RAS−) |\n| **Panitumumab** | 6 mg/kg TTM 60–90 phút mỗi 2 tuần; hoặc 2,5 mg/kg hằng tuần | RAS−, tương tự cetuximab |\n| **Regorafenib** | 40 mg × 4 viên/ngày (160 mg), uống 1 lần, ngày 1–21 | Chu kỳ 28 ngày; sau thất bại fluoropyrimidine, oxaliplatin, irinotecan, bevacizumab ± cetuximab |\n| **Ziv-aflibercept** | 4 mg/kg TTM >1 giờ mỗi 2 tuần | Kết hợp FOLFIRI, sau thất bại oxaliplatin |\n| **Ramucirumab** | 8 mg/kg TTM >1 giờ mỗi 2 tuần | Kết hợp FOLFIRI, sau thất bại bevacizumab/oxaliplatin/fluorouracil |\n| **Pembrolizumab** | 200 mg (hoặc 2 mg/kg) TTM >30 phút mỗi 3 tuần | **MSI-H/dMMR** đã thất bại hóa trị; đến khi tiến triển/độc tính |\n| **Nivolumab** | 240 mg (hoặc 3 mg/kg) TTM >60 phút mỗi 2 tuần | Như trên |\n@@end\n\n@@fold! Hóa trị tiền phẫu cùng xạ trị – trực tràng (PDF tr.22)\n- Mọi phác đồ dựa vào **5-FU làm nhạy xạ**; **capecitabine** thay 5-FU được (tiện, hiệu quả tương đương).\n- Phác đồ nêu: (1) 5-FU 325–350 mg/m² + LV 20 mg/m² ngày 1–5, tuần 1 và 5; (2) 5-FU 400 + LV 100 mg/m² ngày 1, 2, 11, 12, 21, 22; (3) 5-FU 1000 mg/m² ngày 1–5, tuần 1 và 5; (4) 5-FU 250 mg/m² ngày 1–14, 22–35 + oxaliplatin 50 mg/m² ngày 1, 8, 22, 29; (5) 5-FU 225 mg/m² 5 ngày/tuần; (6) capecitabine 800–825 mg/m² uống 2 lần/ngày, 5–7 ngày/tuần; (7) UFT 300–350 mg/m²/ngày + LV 22,5–90 mg/ngày, 5–7 ngày/tuần.\n- Phác đồ ở một số bệnh viện: xạ 45 Gy + **capecitabine 850 mg/m² uống 2 lần/ngày, 5 ngày/tuần × 5 tuần**.\n@@end\n\n@@fold Điều trị phối hợp – hỗ trợ (PDF tr.14)\n- **Huyết khối tĩnh mạch sâu**: enoxaparin 40 mg/ngày tiêm dưới da, duy trì acenocoumarol 1 mg/ngày uống, INR 2–3 (có thể kéo dài suốt đời).\n- **Di căn xương**: pamidronate 90 mg hoặc acid zoledronic 4 mg TTM mỗi 21–28 ngày, hoặc xạ giảm đau; xạ chuyển hóa P-32 / Sm-153 hoặc xạ ngoài 17 Gy/4 lần {{QĐ2549 tr.12}}.\n- Di căn não: xạ phẫu 16–18 Gy hoặc xạ toàn não 30 Gy/10 lần (hoặc 40 Gy/20 lần) kèm chống phù não, corticoid {{QĐ2549 tr.12}}.\n- Tràn dịch màng phổi/bụng: chọc tháo, bơm 5-FU hoặc cisplatin vào khoang.\n@@end\n\n> [!warn] Theo dõi/nhớ: **oxaliplatin** – bệnh thần kinh ngoại biên, giảm bạch cầu (FOLFOX); **irinotecan** – tiêu chảy, rụng tóc (FOLFIRI); **capecitabine** – hội chứng bàn tay-bàn chân {{Y5 tr.280, 297}}. Ngưng oxaliplatin khi có độc tính thần kinh. Cetuximab/panitumumab: chỉ RAS hoang dã, u **bên trái**; không dùng cùng capecitabine. Miễn dịch: chỉ MSI-H/dMMR.\n\n> [!warn] Điểm không nhất quán trong QĐ 2549: liều 5-FU FOLFIRI không ghi thời gian truyền; \"giai đoạn II > 30%\" ở mục 5.2 (đúng ra là giai đoạn III); thời điểm mổ sau xạ ngắn ngày ghi cả \"2–4 ngày\" (tr.20) và \"1–2 tuần\" (tr.21). Mục 3.1.4 chỉ dẫn trong sơ đồ tương ứng mục 4.x của văn bản.\n\n## 8. Tiên lượng – Dự phòng\n\n### Tiên lượng\n- **Sống còn 5 năm theo giai đoạn**:\n\n| Giai đoạn | Đại tràng (Y5, UICC 2017) {{Y5 tr.275}} | Trực tràng (Y5) {{Y5 tr.290}} | QĐ 2549 {{QĐ2549 tr.23}} |\n|---|---|---|---|\n| 0 | 100% | 100% | |\n| I | 92% | 92% | >90% |\n| II | IIA 87%; IIB–C 61% | 60–85% | >60% |\n| III | IIIA 88%; IIIB 72%; IIIC 54% | 27–60% | >30% |\n| IV | 11% | 5–10% | <5% |\n- QĐ 2549: tỷ lệ khỏi bệnh sau 5 năm **40–60%**; UT đại tràng được xem là bệnh **ưu tiên chữa khỏi** {{QĐ2549 tr.23}}.\n- Yếu tố tiên lượng: **T, N, M** (T4N0 thấp hơn T1–2N1–2); xâm lấn mạch/thần kinh, grad, thủng; **CEA** trước mổ cao; tuyến nhày; **KRAS** (quan trọng nhất), **BRAF** (xấu); **MSI-H/dMMR** giai đoạn I–II tốt hơn {{Y5 tr.275–276, 281}}. Trực tràng: **diện cắt bên** và chất lượng TME {{Y5 tr.291–294}}.\n- Số liệu BV Ung bướu TP.HCM (213 ca đại tràng 1995–2000): sigma 38%; sống 5 năm ước tính 56% {{Y5 tr.283}}.\n- Ngoài: tiên lượng xấu khi tắc/thủng, CEA cao, kém biệt hóa; MSI và đủ ≥12 hạch tốt hơn {{+NCI PDQ}}.\n\n### Theo dõi sau điều trị\n@@tabs\n@@tab Theo QĐ 2549\n- Khám lâm sàng **3–6 tháng/lần trong 2 năm đầu**, 6 tháng/lần 3 năm tiếp; CEA 3–6 tháng/lần (2 năm đầu), 6 tháng/lần đến 3–5 năm.\n- CT ngực/bụng/tiểu khung 3–6 tháng/lần (2 năm đầu), 6–12 tháng/lần đến 5 năm; PET/CT khi nghi tái phát (CEA tăng, hình ảnh âm tính).\n- **Nội soi đại trực tràng** trong năm đầu nếu chưa soi đủ lúc chẩn đoán (ví dụ tắc ruột); sau đó 3–5 năm/lần đến 75 tuổi. Sau 1 năm: u tuyến tiến triển lặp lại sau 1 năm; không tiến triển: sau 3 năm rồi 5 năm/lần {{QĐ2549 tr.23}}.\n@@tab Theo Y5\n- **Mỗi 6 tháng trong 3 năm đầu, sau đó mỗi năm đến 5 năm**: khám, độc tính (thần kinh sau oxaliplatin), **CT ngực-bụng**, **CEA**. Soi đại tràng trong **6 tháng** sau mổ nếu trước mổ không soi toàn bộ được {{Y5 tr.282, 298}}.\n@@end\n> [!ext] NCI PDQ (2026): bằng chứng ủng hộ theo dõi định kỳ còn hạn chế (chưa có thử nghiệm lớn chứng minh lợi ích sống còn); khuyến cáo soi đại tràng giám sát; CEA cho ứng viên có thể cắt di căn. Khác biệt lịch với QĐ 2549 là bình thường; **ưu tiên lịch QĐ 2549/Y5** khi thi.\n\n### Dự phòng và tầm soát\n- **Cấp 1**: ăn nhiều xơ, giảm thịt đỏ/mỡ, bỏ thuốc lá; aspirin/NSAID: chứng cớ chưa đủ để khuyến cáo rộng {{Y5 tr.282, 298}}.\n- **Cấp 2**: 70% UT qua pôlyp u tuyến → **soi đại tràng – cắt pôlyp**; cửa sổ tầm soát 10–15 năm {{Y5 tr.298}} {{128VĐ 126}}.\n- **Cấp 3**: theo dõi, phát hiện sớm tái phát.\n- Hiệu quả: FOBT hằng năm giảm 33% tử vong (Minnesota); soi sigma 1 lần giảm 31% mắc, 38% tử vong; NordICC (2022): giảm 18% mắc, không giảm tử vong toàn bộ {{128VĐ 126}}.\n\n| Nhóm | Mô tả | Cách tầm soát |\n|---|---|---|\n| **Nguy cơ trung bình** | ≥45 tuổi (128VĐ, NCCN/ACS), không tiền sử đặc biệt {{128VĐ 126}} | **FOBT/FIT hằng năm**; DNA phân mỗi 3 năm; **soi toàn bộ đại tràng mỗi 10 năm**; CT đại tràng ảo, soi sigma, đối quang kép mỗi 5 năm {{SY5 tr.57–63}} |\n| **Nguy cơ cao** | Tiền sử pôlyp tuyến/UT/viêm đại tràng; gia đình UT hoặc pôlyp tuyến tiến triển; Lynch; FAP | Chủ yếu **soi đại tràng**, bắt đầu sớm hơn, thường xuyên hơn {{128VĐ 126}} |\n- 76–85 tuổi: cân nhắc từng người; >85: không khuyến khích. Test tầm soát khác dương tính → **soi đại tràng** {{SY5 tr.57–63}}.\n- Khai thác: tuổi, tiền sử bản thân/gia đình, thuốc lá, rượu bia, thuốc, ăn uống; **khám bụng và hậu môn trực tràng**; giáo dục bệnh nhân {{128VĐ 126}}.\n\n> [!warn] Mâu thuẫn trong tài liệu: SY5 ghi \">50 tuổi\" ở slide đầu nhưng khuyến cáo ACS ở các slide sau là **45–75 tuổi**; 128VĐ ghi ≥45. Câu tự lượng giá Y5 tr.299 (nguy cơ cao) không in đáp án.\n\n> [!ext] USPSTF 2021: 45–49 (hạng B), 50–75 (hạng A), 76–85 (hạng C, cá nhân hóa), ≥86 không khuyến cáo; FIT/gFOBT hằng năm, soi đại tràng 10 năm, CT ảo và soi sigma 5 năm, DNA phân–FIT 1–3 năm; **phù hợp mốc 45 tuổi**.\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] Bệnh này thi nhấn mạnh gì\n> - Đề cương: **nguyên tắc chẩn đoán** nặng nhất (~40%), rồi **xử trí** (~20%); QĐ 22: cận lâm sàng/chẩn đoán 45–60, xử trí 35–50. Câu hỏi từ mức Áp dụng: tình huống lâm sàng.\n> - Bệnh thuộc nhóm **tầm soát**: [STT 64](#/khung/64) (tầm soát), [STT 61](#/khung/61) (đổi thói quen đi tiêu), [STT 57](#/khung/57) (XHTH dưới).\n> - Phải **tách ĐẠI TRÀNG vs TRỰC TRÀNG**: triệu chứng, tái phát, phẫu thuật (cắt đại tràng vs **TME**), xạ trị tiền phẫu, hóa trị bổ trợ.\n> - Hai nguồn lệch nhau (TNM 2010 vs 2017; tuổi tầm soát; xếp hạng VN): xem hộp \"Bẫy thi\" bên dưới.\n\n@@tabs\n@@tab Nhận diện\n- **Nguy cơ then chốt**: tuổi >44 (>94% ca); người thân cấp 1 UT <50 tuổi ==×2==; **Lynch** (thường gặp nhất), **FAP** 100% UT; **pôlyp u tuyến** >1 cm, viêm loét đại tràng, Crohn {{Y5 tr.269–271}}.\n- Ăn kiểu Tây hóa, hút thuốc là yếu tố thay đổi được; canxi, vitamin D, aspirin/NSAID bảo vệ (đại tràng) {{Y5 tr.270}}.\n- **Đại tràng phải**: im lặng, đau bụng, {r|thiếu máu thiếu sắt}. **Đại tràng trái**: đổi thói quen đi tiêu, phân nhỏ, tắc ruột {{Y5 tr.272}}.\n- **Trực tràng**: tiêu máu, đau/nặng trực tràng, ==mót rặn== (u to, nghĩ GĐ II–III); đau, són phân = tổn thương cơ thắt {{Y5 tr.286–287}}.\n- Gặp **XHTH dưới / táo bón mới** kèm dấu báo động: nghĩ UT đại trực tràng → {g|thăm trực tràng + nội soi}.\n- {r|Báo động}: tiêu máu kéo dài, đổi thói quen mới ở người lớn tuổi, thiếu máu thiếu sắt không rõ nguyên nhân, sụt cân, khối bụng, tắc ruột/thủng {{QĐ2549 tr.2}}.\n- Triệu chứng hay gặp nhất (QĐ): **đi ngoài ra nhầy máu** {{QĐ2549 tr.2}}.\n\n[xem mục 4](#/n/ung-thu-daitruc-trang/4) · [xem mục 3](#/n/ung-thu-daitruc-trang/3)\n@@tab Chẩn đoán\n- {g|CLS đầu tay}: thăm trực tràng + **nội soi toàn bộ đại tràng + sinh thiết**; mô bệnh học **quyết định nhất** {{QĐ2549 tr.4}}.\n- Xếp giai đoạn: **CT bụng-chậu + ngực**; trực tràng thêm **MRI vùng chậu** (diện cắt bên ≤1 mm) ± siêu âm nội trực tràng; **CEA** trước mổ và theo dõi {{Y5 tr.272, 289}}.\n- X quang bụng không chuẩn bị khi cấp cứu (tắc, thủng) {{QĐ2549 tr.3}}; PET/CT khi nghi tái phát (CEA tăng, hình ảnh âm tính).\n- Di căn: xét nghiệm **KRAS, NRAS, BRAF**; giai đoạn II: **MSI/MMR** (dMMR/MSI-H không lợi từ 5-FU) {{QĐ2549 tr.3}}.\n- Sau mổ: vét **≥ 12 hạch**, đánh giá diện cắt, xâm lấn mạch/thần kinh {{QĐ2549 tr.3}}.\n- **TNM**: T1 dưới niêm, T2 cơ, T3 qua cơ, T4a thanh mạc, T4b cơ quan lân cận; N1 1–3, N2 ≥4 hạch. QĐ 2549 (2010): M1a/M1b; Y5 (2017): thêm {o|M1c = phúc mạc}.\n- **CĐPB**: Crohn, viêm loét đại trực tràng, lao manh tràng, lymphoma/GIST, pôlyp, UT ống hậu môn; trĩ/túi thừa/IBS **không loại trừ UT** nếu có dấu báo động {{QĐ2549 tr.4}}.\n\n[xem mục 5](#/n/ung-thu-daitruc-trang/5) · [xem mục 6](#/n/ung-thu-daitruc-trang/6)\n@@tab Điều trị\n- **Đại tràng 0–I**: cắt pôlyp nội soi (T1N0 nguy cơ thấp), T2: cắt đại tràng + vét hạch. **II–III**: cắt đại tràng theo vị trí, diện cắt ==5 cm==, vét ≥12 hạch {{QĐ2549 tr.10}}.\n- **Hóa trị bổ trợ đại tràng**: GĐ **III** và GĐ **II nguy cơ cao** (<12 hạch, T4, tắc/thủng, kém biệt hóa); {p|FOLFOX/CapeOX} bắt đầu sau mổ ==4–8 tuần== {{QĐ2549 tr.23}}, kéo dài ==6 tháng== {{QĐ2549 tr.13}}.\n- **Trực tràng**: cT1 thấp nguy cơ → TEM; cT2N0 → **TME**; giữa/thấp {r|T3–4 hoặc N+} → **hóa-xạ tiền phẫu** rồi TME {{QĐ2549 tr.20–22}}.\n- **TME** chuẩn cho giữa/thấp; cao: cắt mạc treo 5 cm dưới u. **Miles** khi xâm lấn cơ thắt/rất thấp (<4 cm cách mép hậu môn).\n- Xạ tiền phẫu: ngắn ngày ==25 Gy/5 lần==; dài ngày ==45 Gy/25 lần== + 5-FU/capecitabine, mổ sau 4–8 tuần; **giảm tái phát tại chỗ, không tăng sống còn** {{Y5 tr.295}}.\n- **GĐ IV**: cắt di căn gan/phổi nếu được; hóa trị {p|FOLFOX/CapeOX/FOLFIRI} + đích; kháng EGFR chỉ {r|RAS hoang dã + u bên trái}; miễn dịch chỉ {r|MSI-H/dMMR} {{QĐ2549 tr.13–14}}.\n- Liều cốt lõi: {p|FOLFOX4} oxaliplatin 85 mg/m², chu kỳ 2 tuần; {p|CapeOX} oxaliplatin 130 mg/m² + capecitabine 1000 mg/m² × 14 ngày, 3 tuần {{QĐ2549 tr.14–16}}.\n- Biến chứng: tắc u trái → Hartmann/mổ 2 thì; thủng → cắt đại tràng + hậu môn nhân tạo {{QĐ2549 tr.11}}.\n- Độc tính: oxaliplatin (thần kinh ngoại biên), irinotecan (tiêu chảy), capecitabine (bàn tay-bàn chân) {{Y5 tr.280, 297}}.\n\n[xem mục 7.2](#/n/ung-thu-daitruc-trang/7) · [xem mục 7.3](#/n/ung-thu-daitruc-trang/7)\n@@tab Tiên lượng – Dự phòng\n- Sống 5 năm (Y5, đại tràng): I ==92%==, IIIA 88%, IIIC 54%, IV ==11%==; QĐ: khỏi bệnh sau 5 năm 40–60% {{Y5 tr.275}} {{QĐ2549 tr.23}}.\n- Tiên lượng xấu: T4, N+, CEA cao, KRAS/BRAF đột biến, tuyến nhày; MSI-H giai đoạn I–II tốt; trực tràng: **diện cắt bên** {{Y5 tr.275–276}}.\n- **Tầm soát nguy cơ trung bình**: {g|FOBT/FIT hằng năm} hoặc {g|soi toàn bộ đại tràng mỗi 10 năm} (CT ảo, soi sigma mỗi 5 năm); test khác dương tính → soi đại tràng {{SY5 tr.57–63}}.\n- **Nguy cơ cao** (tiền sử pôlyp/UT/viêm đại tràng, gia đình, Lynch, FAP): soi đại tràng, **bắt đầu sớm hơn**, thường xuyên hơn {{128VĐ 126}}.\n- Cắt pôlyp qua nội soi giảm nguy cơ UT tới 90%; ~70% UT qua pôlyp, cửa sổ 10–15 năm {{Y5 tr.270, 298}}.\n- Theo dõi (QĐ): khám + CEA 3–6 tháng/lần × 2 năm đầu; CT 3–6 tháng; nội soi trong năm đầu nếu chưa soi đủ {{QĐ2549 tr.23}}.\n\n[xem mục 8](#/n/ung-thu-daitruc-trang/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Carcinôm tuyến | ==90–98%== | {{Y5 tr.271, 286}} |\n| Thời gian pôlyp → UT | ==10–15 năm== | {{128VĐ 126}} |\n| Trực tràng thấp / giữa / cao (cách rìa hậu môn) | ==<5 / 5–10 / >10 cm== | {{Y5 tr.285}} |\n| Người thân cấp 1 UT <50 tuổi / hai người thân | ==×2 / ×3–4== | {{Y5 tr.270}} |\n| Tái phát tại chỗ trực tràng so với đại tràng | ==gấp 3 lần== | {{Y5 tr.286}} |\n| Số hạch vét tối thiểu | ==≥ 12== | {{QĐ2549 tr.10}} |\n| Diện cắt đại tràng cách u | ==5 cm== | {{QĐ2549 tr.10}} |\n| Xạ tiền phẫu ngắn ngày / dài ngày | ==25 Gy/5 lần / 45 Gy/25 lần== | {{QĐ2549 tr.21}} |\n| Mổ sau hóa-xạ tiền phẫu | ==4–8 tuần== | {{QĐ2549 tr.21}} |\n| Hóa trị bổ trợ đại tràng: bắt đầu / thời gian | ==sau mổ 4–8 tuần / 6 tháng== | {{QĐ2549 tr.23; tr.13}} |\n| FOLFOX4: oxaliplatin / chu kỳ | ==85 mg/m² / 2 tuần== | {{QĐ2549 tr.14}} |\n| Sống 5 năm giai đoạn I / IV (Y5, đại tràng) | ==92% / 11%== | {{Y5 tr.275}} |\n| FOBT hằng năm giảm tử vong | ==33%== | {{128VĐ 126}} |\n| Soi toàn bộ đại tràng tầm soát | ==mỗi 10 năm== | {{SY5 tr.57–63}} |\n\n> [!warn] Bẫy thi thường gặp\n> - **Tuổi bắt đầu tầm soát**: SY5 ghi >50 ở slide đầu, ACS/128VĐ ghi **45**; đọc kỹ đề theo nguồn nào ({{SY5 tr.57–63}}).\n> - **TNM**: QĐ 2549 (2010) không có M1c (phúc mạc thuộc M1b) và có cột Dukes; Y5 (2017) có **M1c** và GĐ IVC.\n> - **Xếp hạng VN**: Y5 (Globocan 2018) hạng **5**; QĐ 2549 (Globocan 2012) hạng **6**.\n> - Xạ tiền phẫu trực tràng **không cải thiện sống còn** (chỉ giảm tái phát tại chỗ); xạ bổ trợ đơn thuần không áp dụng.\n> - Kháng EGFR cần {r|RAS hoang dã + u bên trái}, không phối với capecitabine; miễn dịch chỉ **MSI-H/dMMR**; GĐ II dMMR **không** dùng 5-FU bổ trợ.\n> - Mổ nội soi trực tràng: QĐ cho là tương đương ở trung tâm có kinh nghiệm, Y5 nói **chưa** thay được mổ mở; thời điểm mổ sau xạ ngắn ngày QĐ ghi cả 2–4 ngày và 1–2 tuần.\n> - DRE không dùng đơn độc để xếp giai đoạn; trĩ/túi thừa/IBS không loại trừ UT khi có dấu báo động.\n\n@@fold Nguồn tài liệu\n- Y5: `text-ung-buou-y5.txt` tr.269–300 (đại tràng 269–284; trực tràng 285–300; bảng tr.275, 290 đọc từ ảnh).\n- SY5: `slide-y5.txt` tr.57–63 (tầm soát).\n- **QĐ 2549/QĐ-BYT (19/4/2018)**: `qd-2549-ung-thu-dai-truc-trang.txt` (24 tr.; sơ đồ tr.6, 9, 18 đọc từ ảnh `_work/img-qd2549/`); PDF `Tài liệu/Ung bướu/Phác đồ BYT/2549_QD-BYT_m_380054.pdf`.\n- Khung thi: 128VĐ mục 126 (STT 64), 72 (STT 61), 68 (STT 57) trong `data/book-items.json`.\n- Các bài cũ đã kiểm tra: `_old/ung-thu-daitruc-trang-*.md`, `tc-tam-soat-dai-truc-trang.md`, `tc-thay-doi-thoi-quen-di-tieu.md`, `tc-xuat-huyet-tieu-hoa-duoi.md`.\n@@end\n\n@@fold Nguồn ngoài\n- {{+NCI PDQ}} Colon Cancer Treatment (Health Professional): https://www.cancer.gov/types/colorectal/hp/colon-treatment-pdq (tiên lượng, theo dõi, mục tiêu theo giai đoạn).\n- {{+USPSTF 2021}} Colorectal Cancer Screening: https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/colorectal-cancer-screening\n- Chẩn đoán phân biệt các bệnh trĩ, túi thừa, IBS: kiến thức lâm sàng chung, chưa gắn nguồn mở cụ thể (StatPearls không truy cập được).\n@@end\n\n@@fold Tự kiểm tra (14 thẻ)\n- Chẩn đoán xác định ung thư đại trực tràng dựa vào đâu? :: Nội soi kèm sinh thiết, mô bệnh học là quyết định nhất.\n- Ba phần của trực tràng theo khoảng cách từ rìa hậu môn? :: Thấp <5 cm, giữa 5–10 cm, cao >10 cm.\n- Vì sao UT trực tràng tái phát tại chỗ gấp 3 lần đại tràng? :: Nằm khung chậu khó cắt rộng, 2/3 dưới không có thanh mạc.\n- Hội chứng di truyền thường gặp nhất và đặc điểm của FAP? :: Lynch (HNPCC); FAP 100% bị UT, trung vị 39 tuổi, 100–1000 pôlyp.\n- Phẫu thuật chuẩn cho UT trực tràng giữa/thấp? :: Cắt toàn bộ mạc treo trực tràng (TME).\n- Chỉ định hóa-xạ trị tiền phẫu trực tràng và liều xạ? :: Giữa/thấp T3–4 hoặc N+; 45 Gy/25 lần (dài ngày) hoặc 25 Gy/5 lần (ngắn ngày).\n- Chỉ định hóa trị bổ trợ UT đại tràng? :: Giai đoạn III và giai đoạn II nguy cơ cao; FOLFOX hoặc CapeOX, bắt đầu sau mổ 4–8 tuần (QĐ2549), kéo dài 6 tháng.\n- Số hạch tối thiểu cần vét? :: Ít nhất 12 hạch.\n- Cetuximab/panitumumab dùng khi nào? :: Di căn, KRAS-NRAS không đột biến (RAS hoang dã), u bên trái.\n- Thuốc miễn dịch dùng cho nhóm nào? :: MSI-H/dMMR (pembrolizumab 200 mg/3 tuần; nivolumab 240 mg/2 tuần).\n- FOLFOX4 liều oxaliplatin và chu kỳ? :: Oxaliplatin 85 mg/m² ngày 1, nhắc lại mỗi 2 tuần (kèm LV và 5-FU).\n- Tầm soát nguy cơ trung bình (ACS/SY5)? :: FOBT/FIT hằng năm hoặc soi toàn bộ đại tràng mỗi 10 năm (CT ảo, soi sigma mỗi 5 năm), 45–75 tuổi.\n- Nguyên nhân thường gặp nhất của XHTH dưới? :: Bệnh túi thừa đại tràng (30%); u tân sinh đại-trực tràng 5–15%.\n- Khi nào làm phẫu thuật Miles? :: Khối u xâm lấn cơ thắt hoặc rất thấp (QĐ: rìa u cách mép hậu môn <4 cm).\n@@end"}, {"kind": "disease", "disease": "gan", "short": "Ung thư gan", "group": "", "section": 0, "order": 8, "khung": [53, 54, 55, 56, 62, 63, 99], "id": "ung-thu-gan", "title": "Ung thư gan", "layer": "benh", "module": "ung-buou", "tags": ["ung bướu", "gan", "HCC", "xơ gan", "viêm gan B", "viêm gan C", "AFP", "PIVKA-II", "BCLC", "Child-Pugh", "TNM", "nút mạch", "sorafenib", "Y-90", "tầm soát"], "source": "Y5 tr.310–328 (chương UNG THƯ GAN); SY5 tr.18, 27, 36, 38, 133, 193; QĐ1514 tr.PDF 713–722 (Bài 82), 71–73 (Bài 11), 282 (Bài 36); ĐC Y5 tr.1–7; QĐ22 tr.8 và STT 53–63, 99; 128VĐ mục 63, 64, 73, 74", "body": "> [!key] Ung thư gan (UTG) trong một nhìn\n> - Phần lớn là carcinôm tế bào gan (HCC), khoảng 90% xuất phát từ tế bào gan; khoảng 80% có nền xơ gan {{Y5 tr.310}}\n> - Nguyên nhân chính: viêm gan B, viêm gan C (UTG do HCV chỉ xảy ra khi có xơ gan), xơ gan do rượu; nghĩ UTG khi bệnh gan + AFP tăng {{Y5 tr.311}} {{Y5 tr.314}}\n> - Chẩn đoán chủ yếu bằng hình ảnh: CT có cản quang hoặc MRI có cản từ (ngấm thuốc thì động mạch, thoát thuốc thì tĩnh mạch cửa) + AFP; không đủ tiêu chuẩn thì sinh thiết {{Y5 tr.315}} {{QĐ1514 tr.PDF 714}}\n> - ==Chỉ định điều trị phụ thuộc trước hết vào chức năng gan và thể trạng, rồi mới đến mức lan rộng== {{Y5 tr.320}}\n> - Hóa trị và xạ trị có vai trò rất ít; trụ cột là cắt/ghép gan, hủy u tại chỗ, nút động mạch gan và sorafenib {{Y5 tr.326}}\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Tỉ lệ tử vong/mới mắc rất cao (0,95); nhiều BN chết vì biến chứng của bệnh gan nền hơn là vì UT {{Y5 tr.310}}\n> - Dạng **phiến sợi** (~1%) khác hẳn về lâm sàng (AFP thường bình thường, không xơ gan) và về điều trị {{Y5 tr.313}}\n\n### Định nghĩa & dịch tễ\n- UTG nguyên phát xuất phát từ nhu mô gan; UTG thứ phát là di căn từ nơi khác (đại trực tràng, phổi, dạ dày...) {{QĐ1514 tr.PDF 713}}\n- Thời gian nhân đôi của bướu thay đổi từ vài tuần đến nhiều tháng; tiên lượng xấu nếu không điều trị, kể cả giai đoạn sớm {{Y5 tr.310}}\n- Phân bố: tỉ lệ mắc cao ở Đông Á, Đông Nam Á, Bắc Phi và Tây Phi; khoảng 50% BN ở Trung Quốc {{Y5 tr.311}}\n- Chợ Rẫy 2010–2016 (24.091 BN): nam chiếm 82%; tuổi 41–70 chiếm 72% {{Y5 tr.326}}\n\n| Nguồn | Mới mắc | Tử vong | Ghi chú |\n|---|---|---|---|\n| Y5 (GLOBOCAN 2012, thế giới) | 782 nghìn/năm | 746 nghìn/năm | thứ 6 về mới mắc, thứ 2 về tử vong (sau phổi) {{Y5 tr.310}} |\n| Y5 (xuất độ chuẩn-tuổi, 2012) | nam 15,3; nữ 5,3 /100.000 | nam 14,3; nữ 5,1 /100.000 | {{Y5 tr.310}} |\n| SY5 (GLOBOCAN 2018, thế giới) | 841.080 (4,7%) | 781.631 (8,2%) | {{SY5 tr.36}} |\n| Y5 (GLOBOCAN 2018, Việt Nam) | 25.335 ca | — | \"thường gặp nhất tại Việt Nam\" (xem bẫy mục 9) {{Y5 tr.311}} |\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Bệnh gan nền & virus\n- **Xơ gan** (do rượu và nguyên nhân khác): khoảng 80% BN UTG có xơ gan {{Y5 tr.310}} {{Y5 tr.311}}\n- **HBV**: nguy cơ 0,02–0,6%/năm khi không xơ gan, 2,2–3,7%/năm khi có xơ gan; HBV-DNA cao (>10.000 copies/mL) làm nguy cơ cao hơn {{Y5 tr.311}}\n- **HCV**: UTG chỉ xảy ra ở người nhiễm HCV có xơ gan; liên quan mức viêm và hoại tử tế bào gan {{Y5 tr.311}}\n- Chợ Rẫy: 62% có viêm gan B, 26% viêm gan C, 3% cả hai; xơ gan 30–40% {{Y5 tr.326}}\n@@tab Độc tố & nội tiết\n- Aflatoxin, dioxin {{Y5 tr.311}} {{QĐ1514 tr.PDF 713}}\n- Các nội tiết tố nam {{Y5 tr.311}}\n- Chất bảo quản thức ăn \"N-nisotryl\" (chép nguyên Y5, nghi lỗi chính tả), thảo mộc chứa alkaloid pyrrolizidine, chất đồng vị thorotrast {{Y5 tr.311}}\n@@tab Bệnh chuyển hóa\n- Bệnh thừa sắt; thiếu alpha-1-antitrypsin; bệnh Wilson; vàng da ứ mật di truyền; viêm gan nhiễm mỡ không do rượu {{Y5 tr.311}}\n@@end\n\n### Sinh bệnh học & sinh học phân tử\n- Khối u được nuôi chủ yếu bởi động mạch gan (90%), ít hơn từ tĩnh mạch cửa (10%) {{QĐ1514 tr.PDF 715}}; vì vậy đưa thuốc qua động mạch gan có tính chọn lọc (cơ sở của nút động mạch gan) {{Y5 tr.324}}\n- Nền sinh ung: [[ung-thu-co-che-sinh-ung]]; sinh học phân tử: [[ung-thu-sinh-hoc-phan-tu]]\n- QĐ1514 đưa vào bộ xét nghiệm: MSI, NGS, giải trình tự nhiều gen (không nêu kết quả cụ thể) {{QĐ1514 tr.PDF 714}}\n\n### Giải phẫu bệnh – phân loại\n@@tabs\n@@tab Mô học\n- Các dạng: bè, giả tuyến, đặc, xơ (scirrhous), tế bào sáng, phiến sợi (fibrolamellar) {{Y5 tr.312}}\n- Tiểu loại ít ảnh hưởng quyết định điều trị, **trừ dạng phiến sợi**; độ mô học và dạng đại thể giúp tiên lượng {{Y5 tr.312}}\n- Xâm lấn mạch vi thể thường gặp ở các tiểu loại {{Y5 tr.312}}\n@@tab Đại thể\n| Dạng | Đặc điểm | Xâm lấn mạch vi thể |\n|---|---|---|\n| Nốt đơn độc | giới hạn rõ | 14% {{Y5 tr.312}} |\n| Nốt đơn độc | giới hạn không rõ | 25% {{Y5 tr.312}} |\n| Nhiều nốt | kết cụm | 70% {{Y5 tr.312}} |\n| Dạng khối | >10 cm, không giới hạn; thường gặp ở BN trẻ, không xơ gan, có thuyên tắc TM cửa | — {{Y5 tr.312}} |\n| Dạng lan tỏa | nhiều bướu ≤1 cm khắp nhu mô; hay gặp trong xơ gan có thuyên tắc TM cửa (70%), di căn hạch cuống gan (50%) | {{Y5 tr.312–313}} |\n\n@@tab Phiến sợi (fibrolamellar)\n- Chỉ chiếm ~1% UTG; bướu thường lớn (80–90%), giới hạn rõ, có sẹo trung tâm (75%) {{Y5 tr.313}}\n- Thường gặp ở nữ trẻ, không có xơ gan; AFP máu thường bình thường, theo Y5 tr.317 là luôn bình thường {{Y5 tr.313}} {{Y5 tr.317}}\n- Xử trí khác: di căn hạch thì cắt gan và nạo hạch; tái phát ở gan, phổi hoặc hạch đều có chỉ định phẫu thuật {{Y5 tr.321}} {{Y5 tr.322}}\n@@end\n\n### Diễn tiến tự nhiên – lan tràn\n- **Lan theo TM cửa** thường gặp nhất: di căn trong gan; thuyên tắc nhánh TM cửa gây tăng áp TM cửa {{Y5 tr.313}}\n- **Xâm lấn TM gan** gây thuyên tắc; lên tới TM chủ có thể gây **hội chứng Budd–Chiari** (phù chân, báng bụng, gan lớn, đau) {{Y5 tr.313}} {{Y5 tr.314}}\n- Xâm lấn cơ quan lân cận: túi mật, cơ hoành, dạ dày, đại tràng {{Y5 tr.314}}\n- Hạch: thân tạng, cuống gan, cạnh động mạch chủ bụng, tâm–hoành {{Y5 tr.314}}\n- Di căn xa: phổi, xương (cột sống, xương sườn, xương sọ), tuyến thượng thận, não, phúc mạc {{Y5 tr.314}}\n- Ung thư đường tiêu hóa thường di căn gan qua TM cửa; gan là một trong các cơ quan hay bị di căn nhất {{SY5 tr.18}} {{SY5 tr.27}}\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Triệu chứng muộn, phần lớn là **của bệnh gan nền**; ngày càng nhiều BN được phát hiện tình cờ khi khám sức khỏe, chưa có triệu chứng {{Y5 tr.314}}\n> - Hỏi: nhiễm HBV/HCV, truyền máu, dùng chung kim, rượu bia, tiếp xúc độc chất; khám: vàng da niêm, gan to, báng bụng {{Y5 tr.314}} {{Y5 tr.315}}\n\n### Triệu chứng cơ năng\n- Chán ăn, đau hạ sườn phải, bụng to, sụt cân, vàng da niêm {{Y5 tr.314}}\n- Rất hiếm nhập viện vì xuất huyết nội do UT vỡ {{Y5 tr.314}}\n- Lý do đến khám: đau bụng, vàng da, bụng to, hoặc chỉ là kiểm tra sức khỏe {{Y5 tr.314}} {{Y5 tr.315}}\n\n### Hỏi bệnh\n- Nhiễm HBV, HCV hoặc cả hai; truyền máu hoặc dùng chung kim tiêm {{Y5 tr.314}}\n- Rượu bia (số lượng, tần suất, thời gian); tiếp xúc độc tố, hóa chất (loại, thời gian tiếp xúc) {{Y5 tr.314}}\n- Các bệnh lý khác đi kèm (nếu có) {{Y5 tr.315}}\n\n### Khám thực thể\n- Sao mạch, lòng bàn tay đỏ, **gan to**, báng bụng, vàng da niêm, lách to, dãn tĩnh mạch thực quản; thường là dấu của bệnh gan nền {{Y5 tr.314}}\n- Khám: đánh giá thể trạng, sinh hiệu, vàng da niêm; khám tổng quát, chú ý khám bụng và sờ xem gan to hay không {{Y5 tr.315}} {{QĐ1514 tr.PDF 713}}\n\n> [!red] Dấu hiệu báo động\n> - **Nôn máu đỏ tươi, đi ngoài phân đen**: ở UTG có xơ gan thường do giãn vỡ tĩnh mạch thực quản, cần cấp cứu {{QĐ1514 tr.PDF 71}}\n> - **Vàng da, cổ trướng tăng nhanh** sau xạ Y-90: đe dọa suy gan tối cấp {{QĐ1514 tr.PDF 719}}\n> - **Vỡ khối u** (hiếm nhưng tỉ lệ tử vong cao trong quá khứ; TACE có tác dụng cầm máu) {{Y5 tr.324}}\n> - **Budd–Chiari**: phù chân, báng bụng, gan lớn, đau {{Y5 tr.314}}\n\n### Tiếp cận các triệu chứng (khung 128 vấn đề)\n| STT | Vấn đề | Nguyên nhân cần nghĩ tới (liên quan UTG) |\n|---|---|---|\n| [53](#/khung/53) | Báng bụng (cổ trướng) | xơ gan mất bù (phổ biến nhất); tắc TM trên gan (Budd–Chiari); suy gan cấp {{128VĐ mục 63}} {{Y5 tr.314}} |\n| [54](#/khung/54) | Khối ở bụng | gan to; khối u đường tiêu hóa (dạ dày, đại tràng, tụy, **u gan**) {{128VĐ mục 64}} |\n| [55](#/khung/55) | Trướng bụng | bụng to là triệu chứng cơ năng của UTG; báng bụng do xơ gan hoặc Budd–Chiari {{Y5 tr.314}} |\n| [56](#/khung/56) | Xuất huyết tiêu hóa trên | giãn vỡ tĩnh mạch thực quản ở UTG có xơ gan; UT dạ dày, UT đường mật {{QĐ1514 tr.PDF 71}} |\n| [62](#/khung/62) | Vàng da | bệnh thâm nhiễm gan (**ung thư gan**), xơ gan mất bù, tắc mật do UT đường mật {{128VĐ mục 73}} |\n| [63](#/khung/63) | Bất thường chức năng gan/men gan | xơ gan và ung thư biểu mô tế bào gan là nguyên nhân tử vong chủ yếu của bệnh gan {{128VĐ mục 74}} |\n| [99](#/khung/99) | Sụt cân / suy dinh dưỡng | sụt cân là triệu chứng cơ năng của UTG {{Y5 tr.314}} |\n\n## 5. Cận lâm sàng\n\n> [!key] Tóm tắt\n> - Hình ảnh: **CT bụng có cản quang / MRI bụng có cản từ** là chẩn đoán hình ảnh chính; siêu âm để theo dõi nốt và tầm soát {{Y5 tr.315}} {{Y5 tr.317}}\n> - **AFP** là dấu ấn dùng nhiều nhất; AFP-L3 và DCP (PIVKA-II) hỗ trợ chẩn đoán sớm {{Y5 tr.316}} {{Y5 tr.317}}\n> - Phân giai đoạn: **TNM** khi có chỉ định mổ, **BCLC** khi không mổ; kèm Child-Pugh {{Y5 tr.317}} {{Y5 tr.318}}\n\n### Hình ảnh\n- Siêu âm Doppler mạch máu gan; X-quang tim phổi (phổi thẳng) {{Y5 tr.315}} {{QĐ1514 tr.PDF 714}}\n- CT bụng có cản quang hoặc MRI bụng có cản từ (khi cần) {{Y5 tr.315}}\n- Xạ hình gan 99mTc-phytate (cấu trúc gan) và 99mTc-HIDA (bài tiết mật, lưu thông đường mật) {{QĐ1514 tr.PDF 714}}\n- PET/CT đánh giá di căn, xếp giai đoạn; ở UTG thứ phát, tổn thương tăng hấp thu FDG mạnh (maxSUV >2,5) nếu có điều kiện {{QĐ1514 tr.PDF 714}} {{QĐ1514 tr.PDF 715}}\n- Nội soi dạ dày, đại trực tràng (tìm ổ nguyên phát) {{QĐ1514 tr.PDF 714}}\n\n### Dấu ấn\n| Dấu ấn | Thông tin | Nguồn |\n|---|---|---|\n| AFP | >20 ng/mL: nhạy 41–65%, đặc hiệu 80–94%; >400 ng/mL ở người nguy cơ cao gợi ý UTG; 20–40% UT nhỏ có AFP bình thường; xơ gan có thể làm AFP tăng | {{Y5 tr.316}} |\n| AFP-L3 | bình thường <10%; AFP 10–200 ng/mL với AFP-L3 >10%: nhạy 71%, đặc hiệu 63%; AFP-L3 >35%: nhạy 33%, đặc hiệu 100% | {{Y5 tr.317}} |\n| DCP (PIVKA-II) | có ở 90% BN UTG; bình thường <40 mAU/mL; >250 mAU/mL: nhạy 95% | {{Y5 tr.317}} |\n| CA 19-9 | tăng cao trong UT đường mật trong gan (không phải HCC) | {{Y5 tr.316}} {{QĐ1514 tr.PDF 715}} |\n\n### Xét nghiệm máu & virus\n- Công thức máu, đông máu toàn bộ; chức năng gan thận: AST, ALT, bilirubin, albumin, creatinin {{Y5 tr.315}}\n- Viêm gan B/C: HBsAg, HBeAg, HBeAb, HBV-DNA, anti-HCV, HCV-RNA {{Y5 tr.315}}\n- QĐ1514 liệt kê thêm CEA, CA 19-9, CA 72-4, CA-125, CA 15-3, PSA; không nêu chỉ định cụ thể cho UTG {{QĐ1514 tr.PDF 714}}\n\n### Mô bệnh học & sinh thiết\n- Sinh thiết gan khi không đủ tiêu chuẩn không xâm lấn; bệnh phẩm sinh thiết nhỏ đọc bởi chuyên gia GPB; nếu chẩn đoán không rõ thì làm hóa mô miễn dịch {{Y5 tr.315}} {{Y5 tr.317}}\n- Báo cáo GPB: typ và độ mô học theo WHO; xâm lấn mạch, thần kinh, hạch; pTNM AJCC 2017 {{QĐ1514 tr.PDF 714}}\n\n### Phân giai đoạn\nChỉ phân giai đoạn TNM cho người có chỉ định mổ; BCLC cho người không có chỉ định mổ {{Y5 tr.317}} {{Y5 tr.318}}\n\n@@tabs\n@@tab TNM (UICC 2017, bản 8)\n| T | Mô tả |\n|---|---|\n| T1a | bướu đơn độc ≤2 cm |\n| T1b | bướu đơn độc >2 cm, không xâm lấn mạch máu |\n| T2 | bướu đơn độc >2 cm xâm lấn mạch máu, hoặc nhiều bướu (không >5 cm) |\n| T3 | nhiều bướu, tối thiểu một bướu >5 cm |\n| T4 | một hoặc nhiều bướu bất kể kích thước, xâm lấn nhánh chính TM cửa hoặc TM gan, hoặc xâm lấn cấu trúc lân cận (trừ túi mật) |\n| N0 / N1 | không di căn hạch vùng / có di căn hạch vùng |\n| M0 / M1 | không di căn xa / có di căn xa |\n\n| Giai đoạn | T | N | M |\n|---|---|---|---|\n| IA | T1a | N0 | M0 |\n| IB | T1b | N0 | M0 |\n| II | T2 | N0 | M0 |\n| IIIA | T3 | N0 | M0 |\n| IIIB | T4 | N0 | M0 |\n| IVA | T bất kỳ | N1 | M0 |\n| IVB | T bất kỳ | N bất kỳ | M1 |\n\n{{Y5 tr.318}} {{Y5 tr.319}}\n@@tab BCLC\n| Giai đoạn | ECOG | Child-Pugh | Bướu | Hướng điều trị |\n|---|---|---|---|---|\n| 0 (rất sớm) | 0 | A | 1 ổ <2 cm hoặc carcinôm tại chỗ | cắt gan |\n| A (sớm) | 0 | A–B | 1 ổ hoặc 3 ổ ≤3 cm | ghép gan hoặc RFA |\n| B (trung gian) | 0 | A–B | đa ổ | TACE |\n| C (trễ) | 1–2 | A–B | thuyên tắc TM cửa, di căn hạch, di căn xa | sorafenib |\n| D (cuối) | 3–4 | C | — | chăm sóc giảm nhẹ |\n\n{{Y5 tr.319}}\n@@tab Child-Pugh\n| Thông số | 1 điểm | 2 điểm | 3 điểm |\n|---|---|---|---|\n| Bệnh lý não gan | không | kiểm soát được bằng thuốc | khó kiểm soát |\n| Báng bụng | không | kiểm soát được bằng thuốc | khó kiểm soát |\n| Albumin (g/dL) | >3,5 | 2,8–3,5 | <2,8 |\n| Bilirubin (mg/dL) | <2,0 | 2,0–3,0 | >3,0 |\n| INR | <1,7 | 1,7–2,3 | >2,3 |\n\nXếp loại: A 5–6 điểm; B 7–9 điểm; C 10–15 điểm {{Y5 tr.319}}\n@@end\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Chẩn đoán xác định UTG (một trong các tiêu chuẩn)\n> - ==Hình ảnh điển hình trên CT có cản quang / MRI có cản từ + AFP >400 ng/mL== {{Y5 tr.315}} {{QĐ1514 tr.PDF 714}}\n> - Hình ảnh điển hình + AFP tăng nhưng dưới 400 ng/mL + nhiễm HBV hoặc HCV; có thể sinh thiết nếu cần {{Y5 tr.315}}\n> - Có bằng chứng giải phẫu bệnh là ung thư tế bào gan nguyên phát {{QĐ1514 tr.PDF 714}}\n> - Không đủ các tiêu chuẩn trên: **sinh thiết gan** để có bằng chứng mô bệnh học {{Y5 tr.315}} {{QĐ1514 tr.PDF 714}}\n\n### Hình ảnh điển hình (CT/MRI)\n- Tăng quang **thì động mạch gan** và **thoát thuốc (wash-out)** thì tĩnh mạch cửa hoặc thì chậm; hoặc giảm quang thì chưa tiêm và tăng quang thì động mạch gan {{Y5 tr.315}} {{QĐ1514 tr.PDF 714}}\n\n### Theo dõi nốt gan (AASLD, theo Y5)\n- Nốt ≤1 cm trên siêu âm: siêu âm mỗi 3–6 tháng; nếu không lớn sau 2 năm thì theo dõi như người bình thường {{Y5 tr.317}}\n- Nốt >1 cm: CT có cản quang hoặc MRI có cản từ; hình ảnh không điển hình thì chụp phương tiện khác hoặc sinh thiết {{Y5 tr.317}}\n- Kết quả sinh thiết không phải UT: theo dõi mỗi 3–6 tháng; bướu lớn lên mà không có hình ảnh điển hình thì sinh thiết lại {{Y5 tr.317}}\n\n### Chẩn đoán phân biệt\n| Bệnh lý | Giống | Khác / cận lâm sàng phân biệt |\n|---|---|---|\n| U máu gan | khối ngấm thuốc | tăng quang **dần** từ thì động mạch đến thì chậm, **không thoát thuốc**; AFP bình thường; SPECT hồng cầu đánh dấu {{Y5 tr.316}} {{QĐ1514 tr.PDF 715}} |\n| U lành gan (bướu tuyến, tăng sinh dạng nốt, áp xe, nốt vôi hóa) | khối ở gan | hình ảnh không điển hình, chủ yếu xác định bằng MRI hoặc sinh thiết; xạ hình 99mTc-HIDA có giá trị với tăng sinh dạng nốt {{Y5 tr.316}} {{QĐ1514 tr.PDF 715}} |\n| UT đường mật trong gan | ngấm thuốc không đồng đều | không thoát thuốc; CA 19-9 tăng cao; AFP, AFP-L3, PIVKA-II không tăng {{Y5 tr.316}} {{QĐ1514 tr.PDF 282}} |\n| Di căn gan của UT khác | tăng quang viền | có tổn thương nguyên phát; dấu ấn tương ứng tăng {{Y5 tr.316}} |\n\n- UTG thứ phát: đã có ung thư nguyên phát (dạ dày, đại trực tràng, phổi, vú...), tổn thương ngấm thuốc mạnh, dấu ấn tương ứng tăng; không điển hình thì sinh thiết {{QĐ1514 tr.PDF 715}}\n\n## 7. Điều trị\n\n> [!key] Mục tiêu theo tình trạng gan và thể trạng\n> - Gan còn bù: cắt gan nếu phần gan còn lại đủ; nếu không đủ thì điều trị tại chỗ hoặc sorafenib. Gan mất bù: ghép gan nếu đạt Milan, còn lại nút động mạch gan hoặc sorafenib. Thể trạng kém: chăm sóc giảm nhẹ {{Y5 tr.320}} {{Y5 tr.321}}\n> - Nhiều BN tử vong dù điều trị gì (xơ gan nặng, teo gan, báng bụng, tăng áp TM cửa): chăm sóc giảm nhẹ là phù hợp nhất {{Y5 tr.320}}\n\n### 7.1 Mục tiêu điều trị\n- **Chữa khỏi** khả thi bằng cắt gan hoặc ghép gan; điều trị tại chỗ–tại vùng kiểm soát bệnh và đôi khi (hiếm) chữa khỏi ở người không mổ được {{Y5 tr.320}}\n- Điều trị tại chỗ–tại vùng có thể dùng để trợ giúp hoặc chuẩn bị trước khi cắt hoặc ghép gan {{Y5 tr.320}}\n- Ghép gan dành cho UT giai đoạn sớm trên nền gan nặng; không dành cho UT muộn (xâm lấn mạch máu, lan tỏa trong gan, xâm lấn ngoài gan) {{Y5 tr.320}}\n\n### 7.2 Các phương pháp\nCác phương pháp theo QĐ1514: phẫu thuật cắt và ghép gan; hủy u tại chỗ (RFA, vi sóng, điện đông, tiêm cồn); TACE; 188Re-Lipiodol; xạ trị chọn lọc bằng vi cầu 90Y (SIRT) {{QĐ1514 tr.PDF 713}}\n\n@@tabs\n@@tab Phẫu thuật\n- Cắt gan: chỉ 13–35% BN có chỉ định; tử vong sau mổ <5% (thường do suy gan); sống 5 năm có thể lên đến 90% {{Y5 tr.322}}\n- Chỉ định: đủ sức mổ lớn; Child-Pugh A, không tăng áp TM cửa; một bướu không xâm lấn mạch máu trên hình ảnh; phần gan còn lại đủ chức năng {{Y5 tr.322}}\n- Còn tranh cãi: Child-Pugh B hoặc tăng áp TM cửa kiểm soát được; nhiều bướu nhưng phần gan còn lại đủ; xâm lấn mạch máu lớn {{Y5 tr.322}}\n- Cắt gan lớn (ba phân thùy): thuyên tắc TM cửa trước mổ để tăng thể tích gan còn lại {{Y5 tr.322}} {{Y5 tr.323}}\n- Ghép gan: tử vong sau mổ 2% (thường do thải ghép); sống 5 năm đến 75%; tiêu chuẩn Milan {{Y5 tr.323}}\n- Trong lúc chờ ghép, 15–33% BN vượt tiêu chuẩn Milan; khi đó dùng hủy u hoặc nút động mạch gan {{Y5 tr.323}}\n@@tab Tại chỗ–tại vùng\n| Phương pháp | Chỉ định / đặc điểm | Nguồn |\n|---|---|---|\n| Tiêm cồn qua da | bướu <2 cm, gần mạch máu lớn; lâu đời, ít tốn kém nhất nhưng ít dùng vì phải làm nhiều lần | {{Y5 tr.323}} |\n| Sóng cao tần (RFA) | thông dụng nhất; bướu <3 cm; bướu 3–5 cm kết hợp nút động mạch gan; biến chứng và chi phí cao hơn tiêm cồn | {{Y5 tr.323}} {{Y5 tr.324}} |\n| Vi sóng (microwave) | chỉ định như RFA; tạo vùng hoại tử lớn hơn trong thời gian ngắn hơn | {{Y5 tr.324}} |\n\n- Ưu điểm: ít biến chứng, xuyên da; nhược điểm: hầu như luôn tái phát tại chỗ vì khó đánh giá bờ {{Y5 tr.323}}\n@@tab Nút động mạch gan\n- **TACE**: doxorubicin hoặc cisplatin (hoặc cả hai) + lipiodol + vật liệu gây tắc mạch (hạt PVA 150–500 µ, cuộn kim loại, spongel); đặc biệt hiệu quả cầm máu khi UT vỡ {{Y5 tr.324}}\n- **Chống chỉ định TACE**: thuyên tắc TM cửa nhánh chính; bilirubin máu >3 mg/dL {{Y5 tr.324}}\n- **DEB-TACE**: vi hạt 100–300 µ chứa hóa chất, phóng thích trong 14 ngày; ít biến chứng hơn TACE {{Y5 tr.324}}\n- **Y-90 (vi cầu phóng xạ)**: vi cầu 20–30 µ phát tia beta nên chủ yếu là xạ trị; dùng được khi đã có thuyên tắc TM cửa; chống chỉ định khi bilirubin máu >2 mg/dL {{Y5 tr.324}} {{Y5 tr.325}} {{QĐ1514 tr.PDF 715}}\n- Chỉ định SIRT theo QĐ1514: ECOG 0–2 hoặc Karnofsky ≥70; bilirubin toàn phần <2,0 mg/dL; albumin >3,0 g/dL; tiên lượng sống ≥3 tháng {{QĐ1514 tr.PDF 715}} {{QĐ1514 tr.PDF 716}}\n@@tab Xạ trị\n- UTG nhạy xạ nhưng gan lành cũng nhạy: 20 Gy toàn gan đủ gây viêm gan do xạ nhưng chưa có tác dụng điều trị đáng kể lên khối u {{Y5 tr.325}}\n- Xạ ngoài kỹ thuật mới (máy gia tốc) tập trung liều vào khối u, có thể điều trị cả khi đã có thuyên tắc TM cửa nhánh chính {{Y5 tr.325}}\n- Xạ bằng chùm proton và Y-90 là hướng hứa hẹn {{Y5 tr.325}}\n@@tab Toàn thân\n- **Sorafenib**: dùng cho BN không có chỉ định phẫu thuật hoặc điều trị tại chỗ; cải thiện sống còn đáng kể so với chăm sóc giảm nhẹ khi di căn xa mà gan còn bù (Child-Pugh A hoặc B) {{Y5 tr.321}} {{Y5 tr.325}}\n- Hóa trị doxorubicin hoặc phác đồ PIAF (platinum + interferon-α 2b + adriamycin + fluorouracil) ở một ít BN có thể trạng tốt và gan còn duy trì; ít đáp ứng {{Y5 tr.325}}\n- Nhìn chung hóa trị và xạ trị có rất ít vai trò trong điều trị UTG {{Y5 tr.326}}\n@@end\n\n#### Theo tình trạng (tổng hợp mục 8 của Y5)\n| Tình huống | Xử trí | Nguồn |\n|---|---|---|\n| Khu trú, gan bù, thể trạng còn | cắt một phần gan nếu phần gan còn lại đủ; nếu không đủ: điều trị tại chỗ, phối hợp (cắt + hủy), hoặc sorafenib | {{Y5 tr.320}} {{Y5 tr.321}} |\n| Khu trú, gan bù, thể trạng kém | điều trị tại chỗ, sorafenib hoặc chăm sóc giảm nhẹ | {{Y5 tr.321}} |\n| Khu trú, gan mất bù, thể trạng còn | ghép gan nếu 1 bướu ≤5 cm hoặc tối đa 3 bướu ≤3 cm, không xâm lấn mạch máu; ngoài tiêu chuẩn: nút động mạch gan hoặc sorafenib | {{Y5 tr.321}} |\n| Gan mất bù, thể trạng kém | chăm sóc giảm nhẹ | {{Y5 tr.321}} |\n| Di căn hạch (trừ dạng phiến sợi) | xử trí như UTG di căn xa | {{Y5 tr.321}} |\n| Di căn xa, gan bù (Child-Pugh A–B) | sorafenib | {{Y5 tr.321}} |\n| Di căn xa, gan mất bù | chăm sóc giảm nhẹ | {{Y5 tr.321}} {{Y5 tr.322}} |\n| Tái phát | cắt gan hoặc điều trị tại chỗ nếu gan và thể trạng cho phép; không làm được thì sorafenib hoặc chăm sóc giảm nhẹ | {{Y5 tr.322}} |\n| Dạng phiến sợi (di căn hoặc tái phát) | cắt gan và cắt ổ di căn (ví dụ phổi) nếu có thể | {{Y5 tr.321}} {{Y5 tr.322}} |\n\n### 7.3 Phác đồ – Y lệnh\n\n> [!doc] QĐ 1514/QĐ-BYT ngày 1/4/2020 – Bài 82 \"Xạ trị trong chọn lọc ung thư gan bằng hạt vi cầu phóng xạ 90Y\": quy trình SIRT, chỉ định, chống chỉ định, theo dõi. Không có liều cố định; liều tính theo công thức. {{QĐ1514 tr.PDF 713–722}}\n\n| Phác đồ | Thuốc – liều | Chu kỳ / cách dùng | Chỉ định | Ghi chú |\n|---|---|---|---|---|\n| Sorafenib | tài liệu không nêu liều | tài liệu không nêu | UTG không có chỉ định mổ hoặc tại chỗ; di căn xa, Child-Pugh A–B; BCLC C {{Y5 tr.319}} {{Y5 tr.325}} | cải thiện sống còn so với chăm sóc giảm nhẹ {{Y5 tr.325}} |\n| TACE | doxorubicin hoặc cisplatin (hoặc cả hai) + lipiodol; tài liệu không nêu liều | tài liệu không nêu | BCLC B (đa ổ) {{Y5 tr.319}} {{Y5 tr.324}} | CCĐ: thuyên tắc TM cửa nhánh chính; bilirubin >3 mg/dL {{Y5 tr.324}} |\n| DEB-TACE | vi hạt chứa hóa chất; tài liệu không nêu liều | phóng thích trong 14 ngày {{Y5 tr.324}} | như TACE | ít biến chứng hơn TACE {{Y5 tr.324}} |\n| Hóa chất toàn thân | doxorubicin; PIAF (platinum + interferon-α 2b + adriamycin + fluorouracil); tài liệu không nêu liều | tài liệu không nêu | BN thể trạng tốt, gan còn bù; ít đáp ứng {{Y5 tr.325}} | ít vai trò {{Y5 tr.326}} |\n| Y-90 SIRT | vi cầu 90Y; liều tính theo thể tích gan/diện tích da hoặc partition model, không có liều cố định {{QĐ1514 tr.PDF 718}} | bơm qua động mạch gan (pha 2); theo dõi 48 giờ; tái khám sau 1 tháng rồi 3 tháng/lần {{QĐ1514 tr.PDF 719}} | ECOG 0–2 hoặc Karnofsky ≥70; bilirubin <2,0 mg/dL; albumin >3,0 g/dL; shunt phổi <20%; sống ≥3 tháng {{QĐ1514 tr.PDF 715}} {{QĐ1514 tr.PDF 716}} | CCĐ tuyệt đối: shunt phổi >20%; trào ngược hạt phóng xạ vào động mạch nuôi tiêu hóa không kiểm soát được bằng coils {{QĐ1514 tr.PDF 716}} |\n\n> [!warn] Chưa có văn bản Bộ Y tế về phác đồ UTG trong tài liệu đã cung cấp\n> - Y5 dẫn Hướng dẫn chẩn đoán và điều trị UT tế bào gan nguyên phát (QĐ 5250/QĐ-BYT, 28/12/2012) {{Y5 tr.328}}, nhưng văn bản này không có trong bộ tài liệu; sorafenib, TACE và PIAF chỉ có tên, không có liều: ghi \"tài liệu không nêu\", không suy đoán.\n\n> [!warn] Theo dõi & độc tính cần nhớ\n> - Sau SIRT: hội chứng sau tắc mạch (sốt, đau vùng gan, mệt, chán ăn, nôn, men gan tăng), thường nhẹ hơn TACE {{QĐ1514 tr.PDF 719}}\n> - Viêm gan, viêm đường mật do xạ: xảy ra trong 4–8 tuần sau can thiệp, tần suất 0–4%; xử trí corticoid liều cao (hydrocortison 40–80 mg tiêm/truyền TM) {{QĐ1514 tr.PDF 719}}\n> - Viêm phổi do xạ dưới 1%, nguy cơ cao khi shunt phổi >13%; biến chứng tiêu hóa ≤5% nếu bơm chậm và có tắc dự phòng bằng coils {{QĐ1514 tr.PDF 719}} {{QĐ1514 tr.PDF 720}}\n> - Trước SIRT dùng ức chế bơm proton 2 tuần, kéo dài 6 tuần sau điều trị {{QĐ1514 tr.PDF 717}}\n> - Xạ 20 Gy toàn gan gây viêm gan do xạ {{Y5 tr.325}}\n\n## 8. Tiên lượng – Dự phòng\n\n> [!key] Tóm tắt\n> - Tiên lượng xấu nếu không điều trị, kể cả giai đoạn sớm; chức năng gan và xơ gan nền là yếu tố quyết định {{Y5 tr.310}} {{Y5 tr.320}}\n> - Dự phòng hiệu quả: tiêm vắcxin HBV; tầm soát định kỳ ở người nhiễm HBV/HCV và nhóm nguy cơ {{Y5 tr.325}} {{Y5 tr.326}}\n\n### Tiên lượng\n@@tabs\n@@tab Yếu tố tiên lượng\n| Nhóm | Yếu tố |\n|---|---|\n| Thiết yếu – bướu | xâm lấn mạch máu lớn; xâm lấn mạch máu trên vi thể; kích thước >5 cm; nhiều bướu; độ biệt hóa |\n| Thiết yếu – bệnh nhân | xơ gan; tốc độ tăng trưởng bướu; thể trạng; chức năng gan; mức tăng áp TM cửa |\n| Thiết yếu – môi trường | UT còn lại sau điều trị: R0, R1 hoặc R2 |\n| Phụ trợ | AFP; DCP (PIVKA-II); mức độ viêm gan |\n| Mới, hứa hẹn | sinh học phân tử bướu; micro RNA, DNA, tế bào bướu trong máu; IGF-1; C-reactive protein, interleukin 10, VEGF, tỉ số N/L |\n\n{{Y5 tr.320}}\n@@tab Sống còn\n| Điều trị | Sống 5 năm (Y5) | Ghi chú |\n|---|---|---|\n| Cắt gan | hơn 50% | có thể lên đến 90% {{Y5 tr.310}} {{Y5 tr.322}} |\n| Ghép gan | gần 70% | có thể lên đến 75% {{Y5 tr.310}} {{Y5 tr.323}} |\n\n- Tử vong sau cắt gan <5%; sau ghép gan 2% {{Y5 tr.322}} {{Y5 tr.323}}\n- Chợ Rẫy 2010–2016: 41% BN đến điều trị ở giai đoạn trễ theo BCLC; 49% BN có AFP >400 ng/mL; 23% có AFP <20 ng/mL {{Y5 tr.326}}\n@@end\n\n### Theo dõi sau điều trị\n| Tình huống | Lịch theo dõi | Nguồn |\n|---|---|---|\n| Sau cắt gan, ghép gan, điều trị tại chỗ–tại vùng | CT hoặc MRI cùng chất đánh dấu bướu mỗi 3 tháng trong 2 năm, sau đó mỗi 6 tháng | {{Y5 tr.322}} |\n| Đang dùng sorafenib | chẩn đoán hình ảnh mỗi 2–3 tháng | {{Y5 tr.322}} |\n| Sau SIRT (Y-90) | khám sau 1 tháng rồi mỗi 3 tháng: lâm sàng, công thức máu, chức năng gan thận, AFP, AFP-L3, PIVKA-II, siêu âm, CT/MRI; đáp ứng theo mRECIST | {{QĐ1514 tr.PDF 719}} |\n\n### Dự phòng\n@@tabs\n@@tab Cấp 1 (phòng bệnh)\n- Tiêm vắcxin HBV. Trẻ sơ sinh 4 mũi (trong 24 giờ đầu, rồi lúc 2, 3, 4 tháng); trẻ nhẹ cân (<2.000 g) trì hoãn đến 1 tháng tuổi {{Y5 tr.325}}\n- Trẻ lớn và người lớn 3 mũi: mũi 2 cách mũi 1 một tháng, mũi 3 cách mũi 1 sáu tháng; chỉ tiêm khi HBsAg âm và anti-HBs âm {{Y5 tr.325}}\n- Anti-HBs <10 mIU/mL (khoảng 5%): tiêm tiếp 3 mũi, xét nghiệm lại sau 1–2 tháng; 44–100% đạt miễn dịch sau đợt 2; không đạt thì ngừng tiêm và tư vấn phòng lây nhiễm; phơi nhiễm thì tiêm HBIG {{Y5 tr.325}} {{Y5 tr.326}}\n- Tuyên truyền phòng tránh lây nhiễm HBV và HCV {{Y5 tr.326}} {{QĐ1514 tr.PDF 720}} {{SY5 tr.193}}\n@@tab Cấp 2 (tầm soát)\n- Đối tượng theo AASLD: nam gốc Á >40 tuổi; nữ gốc Á >50 tuổi; nhiễm HBV có xơ gan; có tiền sử gia đình UT gan; xơ gan {{Y5 tr.312}}\n- Phương tiện: siêu âm gan mỗi 6 tháng (AASLD); AFP máu (AASLD không khuyến cáo nhưng NCCN, Hội Gan châu Á–Thái Bình Dương và Bộ Y tế VN ủng hộ); CT bụng không khuyến khích {{Y5 tr.312}}\n- Người nhiễm HBV hoặc HCV: chủ động sàng lọc định kỳ UT gan {{Y5 tr.326}} {{QĐ1514 tr.PDF 720}}\n- Hiệu quả của tầm soát làm giảm tử vong còn tranh cãi, nhưng đa số đồng ý là hữu ích {{Y5 tr.311}}\n- Nguyên tắc chung: [[ung-thu-tam-soat-nguyen-tac]]\n@@tab Cấp 3 (biến chứng & chăm sóc)\n- Xuất huyết do giãn vỡ tĩnh mạch thực quản: tiêm xơ, thắt bằng vòng cao su, kẹp clip, keo dán trộn lipiodol; bóng Sengstaken–Blakemore chỉ tạm thời; truyền khối tiểu cầu nếu tiểu cầu <50 G/L {{QĐ1514 tr.PDF 73}}\n- Chăm sóc giảm nhẹ khi xơ gan nặng, gan teo nhỏ, báng bụng, tăng áp TM cửa, hoặc gan mất bù (Child-Pugh C) {{Y5 tr.320}} {{Y5 tr.321}}\n@@end\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] UTG thi nhấn mạnh gì\n> - **Chẩn đoán nặng nhất**: hình ảnh điển hình trên CT/MRI + AFP (>400 ng/mL) + bệnh gan nền; sinh thiết khi không rõ. Trọng số chung của đề thi (có thể thay đổi theo kỳ thi): nhóm cận lâm sàng/chẩn đoán 45–60, nhóm xử trí 35–50 {{QĐ22 tr.8}}\n> - **Phân giai đoạn rồi chọn điều trị theo Child-Pugh và BCLC** (dễ nhầm, hay ra đề) {{Y5 tr.319}}\n> - Đề cương gắn UTG với MT2–5, MT7–10, MT12–15, MT17: diễn tiến tự nhiên, chẩn đoán và cận lâm sàng, nguyên lý điều trị, triệu chứng báo động {{ĐC Y5 tr.1–4}} {{ĐC Y5 tr.7}}\n\n@@tabs\n@@tab Nhận diện\n- Nguy cơ then chốt: **viêm gan B, viêm gan C**, xơ gan (rượu), aflatoxin {{Y5 tr.311}}\n- Triệu chứng: đau hạ sườn phải, bụng to, sụt cân, vàng da niêm, chán ăn {{Y5 tr.314}}\n- Bệnh gan nền: sao mạch, gan to, báng bụng, lách to, dãn tĩnh mạch thực quản {{Y5 tr.314}}\n- {r|Báo động}: nôn máu, đi ngoài phân đen (vỡ giãn tĩnh mạch thực quản) {{QĐ1514 tr.PDF 71}}\n- {r|Sau xạ Y-90}: vàng da, cổ trướng tăng nhanh là dấu hiệu đe dọa suy gan tối cấp {{QĐ1514 tr.PDF 719}}\n- Tầm soát: nam gốc Á >40, nữ gốc Á >50, nhiễm HBV có xơ gan: siêu âm gan mỗi 6 tháng (AASLD); AFP: AASLD không khuyến cáo, nhưng NCCN, Hội Gan châu Á–Thái Bình Dương và Bộ Y tế VN ủng hộ {{Y5 tr.312}}\n[Xem mục 4](#/n/ung-thu-gan/4) · [mục 3](#/n/ung-thu-gan/3)\n@@tab Chẩn đoán\n- {g|Hình ảnh điển hình (CT/MRI) + AFP >400 ng/mL}: xác định; AFP tăng dưới 400 + HBV/HCV + hình ảnh điển hình cũng xác định {{Y5 tr.315}}\n- Nốt ≤1 cm: siêu âm mỗi 3–6 tháng; nốt >1 cm: CT/MRI {{Y5 tr.317}}\n- DCP (PIVKA-II) >250 mAU/mL có độ nhạy 95%; AFP-L3 hỗ trợ {{Y5 tr.317}}\n- Chẩn đoán phân biệt: u máu (không thoát thuốc, AFP bình thường), UT đường mật (CA 19-9 tăng), di căn gan {{Y5 tr.316}}\n- {g|TNM chỉ dùng khi có chỉ định mổ; BCLC khi không mổ} {{Y5 tr.317}} {{Y5 tr.318}}\n[Xem mục 5](#/n/ung-thu-gan/5) · [mục 6](#/n/ung-thu-gan/6)\n@@tab Điều trị\n- **BCLC**: 0 → cắt gan; A → ghép gan hoặc RFA; B → TACE; C → {p|sorafenib}; D → chăm sóc giảm nhẹ {{Y5 tr.319}}\n- Cắt gan: Child-Pugh A, không tăng áp TM cửa, một bướu không xâm lấn mạch máu {{Y5 tr.322}}\n- {r|CCĐ TACE}: thuyên tắc TM cửa nhánh chính, bilirubin >3 mg/dL {{Y5 tr.324}}\n- {p|Sorafenib}: Child-Pugh A–B khi di căn xa; cải thiện sống còn {{Y5 tr.325}}\n- Y-90: bilirubin <2,0 mg/dL, albumin >3,0 g/dL, shunt phổi <20%; {r|shunt phổi >20% là CCĐ tuyệt đối} {{QĐ1514 tr.PDF 715}} {{QĐ1514 tr.PDF 716}}\n- Hóa chất và xạ trị có rất ít vai trò {{Y5 tr.326}}\n[Xem mục 7.2](#/n/ung-thu-gan/7) · [mục 7.3](#/n/ung-thu-gan/7)\n@@tab Tiên lượng – Dự phòng\n- Tiên lượng xấu nhất khi xơ gan nặng, bướu lớn, nhiều bướu, xâm lấn mạch máu, chức năng gan kém {{Y5 tr.320}}\n- Sống 5 năm: cắt gan hơn 50%, ghép gan gần 70% (trung bình) {{Y5 tr.310}}\n- {g|Vắcxin HBV}: người lớn 3 mũi (mũi 2 sau 1 tháng, mũi 3 sau 6 tháng); {o|anti-HBs <10 cần tiêm tiếp} {{Y5 tr.325}}\n- Theo dõi: CT/MRI cùng chất đánh dấu mỗi 3 tháng trong 2 năm, sau đó mỗi 6 tháng {{Y5 tr.322}}\n- Tầm soát nhóm nguy cơ: siêu âm gan mỗi 6 tháng (AASLD); AFP: AASLD không khuyến cáo, nhưng NCCN, Hội Gan châu Á–Thái Bình Dương và Bộ Y tế VN ủng hộ {{Y5 tr.312}}\n[Xem mục 8](#/n/ung-thu-gan/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Tỉ lệ tử vong / mới mắc | ==0,95== | {{Y5 tr.310}} |\n| Nền xơ gan | ==khoảng 80%== | {{Y5 tr.310}} |\n| Nguồn máu u: động mạch gan / tĩnh mạch cửa | ==90% / 10%== | {{QĐ1514 tr.PDF 715}} |\n| AFP (kèm hình ảnh điển hình, chẩn đoán xác định) | ==>400 ng/mL== | {{Y5 tr.315}} |\n| AFP-L3 | ==>10% (nhạy 71%)==; ==>35% (đặc hiệu 100%)== | {{Y5 tr.317}} |\n| DCP (PIVKA-II) | ==>250 mAU/mL (nhạy 95%)== | {{Y5 tr.317}} |\n| Nốt ≤1 cm trên siêu âm | ==theo dõi mỗi 3–6 tháng== | {{Y5 tr.317}} |\n| Cắt gan: BN có chỉ định / tử vong sau mổ | ==13–35% / <5%== | {{Y5 tr.322}} |\n| Tiêu chuẩn Milan (ghép gan) | ==1 bướu ≤5 cm hoặc tối đa 3 bướu ≤3 cm== | {{Y5 tr.323}} |\n| Cồn / RFA: kích thước bướu | ==<2 cm / <3 cm== | {{Y5 tr.323}} {{Y5 tr.324}} |\n| Child-Pugh A / B / C | ==5–6 / 7–9 / 10–15 điểm== | {{Y5 tr.319}} |\n| TNM: T1a / T2 / T3 | ==≤2 cm / >2 cm có xâm lấn mạch máu hoặc nhiều bướu không >5 cm / nhiều bướu có ít nhất một bướu >5 cm== | {{Y5 tr.318}} |\n| TACE: CCĐ bilirubin | ==>3 mg/dL== | {{Y5 tr.324}} |\n| Y-90: CCĐ bilirubin / tỉ lệ shunt phổi | ==>2 mg/dL (Y5); >20% (QĐ1514)== | {{Y5 tr.325}} {{QĐ1514 tr.PDF 716}} |\n| Y-90: chỉ định bilirubin / albumin | ==<2,0 mg/dL / >3,0 g/dL== | {{QĐ1514 tr.PDF 715}} |\n| Sorafenib | ==Child-Pugh A–B== | {{Y5 tr.321}} |\n| Tầm soát AASLD | ==nam gốc Á >40; nữ gốc Á >50; siêu âm mỗi 6 tháng== | {{Y5 tr.312}} |\n| Chợ Rẫy: giai đoạn trễ theo BCLC | ==41%== | {{Y5 tr.326}} |\n\n> [!warn] Bẫy thi thường gặp\n> - **Milan** (1 bướu ≤5 cm, hoặc tối đa 3 bướu ≤3 cm) khác **BCLC A** (1 ổ hoặc 3 ổ ≤3 cm) {{Y5 tr.319}} {{Y5 tr.323}}\n> - **Bilirubin**: TACE chống chỉ định khi >3 mg/dL; Y-90 khi >2 mg/dL (Y5); chỉ định Y-90 theo QĐ1514 là <2,0 mg/dL {{Y5 tr.324}} {{Y5 tr.325}} {{QĐ1514 tr.PDF 715}}\n> - **Mâu thuẫn dịch tễ**: Y5 nói UTG là ung thư thường gặp nhất tại VN (GLOBOCAN 2018); SY5 xếp gan thứ 2 ở nam, thứ 5 ở nữ; QĐ1514 nói \"đứng đầu\" về mắc và tử vong mà không nêu phạm vi {{Y5 tr.311}} {{SY5 tr.38}} {{QĐ1514 tr.PDF 713}}\n> - **Số liệu toàn cầu khác năm**: Y5 GLOBOCAN 2012 (782 nghìn ca mới) và SY5 GLOBOCAN 2018 (841.080 ca mới); đừng trộn hai năm {{Y5 tr.310}} {{SY5 tr.36}}\n> - **Sống 5 năm**: Y5 nêu cả mức trung bình (cắt gan hơn 50%, ghép gần 70%) lẫn mức cao nhất (90%, 75%); đọc đúng ngữ cảnh {{Y5 tr.310}} {{Y5 tr.322}} {{Y5 tr.323}}\n> - **Hình ảnh**: SY5 chẩn đoán \"dựa trên MRI ± AFP\", Y5 và QĐ1514 dùng CT có cản quang hoặc MRI có cản từ {{SY5 tr.133}} {{Y5 tr.315}}\n> - **AFP bình thường không loại trừ UTG**: 20–40% UT nhỏ có AFP bình thường; dạng phiến sợi luôn bình thường {{Y5 tr.316}} {{Y5 tr.317}}\n> - {r|UT chỉ xảy ra ở HCV khi có xơ gan}; HBV không xơ gan vẫn có nguy cơ nhưng thấp hơn nhiều {{Y5 tr.311}}\n> - **Tầm soát bằng AFP**: AASLD không khuyến cáo AFP (chỉ siêu âm gan 6 tháng); NCCN, Hội Gan châu Á–Thái Bình Dương và Bộ Y tế VN ủng hộ {{Y5 tr.312}}\n> - **Kích thước vi cầu 90Y**: Y5 nêu 20–30 µ; QĐ1514 nêu 20–40 micromet {{Y5 tr.324}} {{QĐ1514 tr.PDF 715}}\n\n@@fold Nguồn tài liệu\n- **Y5** `_work/text-ung-buou-y5.txt`, chương UNG THƯ GAN tr.310–328 (đối chiếu bằng ảnh tr.311, 318, 319, 320: `_work/img-gan-y5/`). Trong decuong không có tiêu đề đúng \"GAN (ung thư biểu mô tế bào gan, HCC)\"; chương tương ứng là \"UNG THƯ GAN\" của Y5\n- **SY5** `_work/slide-y5.txt` tr.18, 27, 36, 38, 133, 193\n- **QĐ1514** `_work/qd-1514-byt-ung-buou.txt`: Bài 82 tr.PDF 713–722 (chính); Bài 11 tr.PDF 71–73; Bài 36 tr.PDF 282\n- **ĐC Y5** `_work/decuong-y5.txt`: MT1–17 (dòng 36–200); bảng ca lâm sàng gắn MT: \"Ung thư gan\", mt 2,3,4,5,7,8,9,10,12,13,14,15,17 (tr.7)\n- **QĐ22** `_work/qd22.txt`: STT 53, 54, 55, 56, 62, 63, 99; trọng số tr.8 (mục 4.2)\n- **128VĐ** `_work/128-van-de.txt`: mục 63 (báng bụng), 64 (khối ở bụng), 73 (vàng da), 74 (bất thường chức năng gan)\n@@end\n\n@@fold Nguồn ngoài\n- Không dùng nguồn ngoài trong bài này. Văn bản BYT mà Y5 trích (QĐ 5250/QĐ-BYT, 2012) không có trong bộ tài liệu nên không dùng.\n@@end\n\n@@fold! Tự kiểm tra (15 thẻ)\n- Ngưỡng AFP để chẩn đoán xác định UTG khi có hình ảnh điển hình trên CT hoặc MRI? :: AFP trên 400 ng/mL\n- Tỉ lệ UTG có nền xơ gan là bao nhiêu? :: Khoảng 80%\n- Tăng quang nào trên CT gợi ý UTG? :: Tăng quang thì động mạch gan và thoát thuốc (wash-out) thì tĩnh mạch cửa hoặc thì chậm\n- Nốt gan ≤1 cm phát hiện trên siêu âm theo dõi thế nào? :: Siêu âm mỗi 3–6 tháng; không tăng sau 2 năm thì theo dõi như người bình thường\n- Nốt gan >1 cm được xử trí chẩn đoán ra sao? :: CT có cản quang hoặc MRI có cản từ; hình ảnh không điển hình thì chụp phương tiện khác hoặc sinh thiết\n- Đối tượng tầm soát UTG theo AASLD (gốc Á)? :: Nam trên 40 tuổi, nữ trên 50 tuổi; nhiễm HBV có xơ gan; tiền sử gia đình; xơ gan\n- Phương tiện tầm soát được khuyến cáo và phương tiện không khuyến khích? :: Siêu âm gan mỗi 6 tháng; CT bụng không khuyến khích vì dương tính giả và nhiễm xạ\n- Child-Pugh C có bao nhiêu điểm? :: 10–15 điểm (A: 5–6; B: 7–9)\n- BCLC giai đoạn A điều trị thế nào? :: 1 ổ hoặc 3 ổ ≤3 cm: ghép gan hoặc RFA\n- BCLC giai đoạn C điều trị thế nào? :: Sorafenib; ECOG 1–2, Child-Pugh A–B\n- Tiêu chuẩn Milan để ghép gan? :: 1 bướu ≤5 cm hoặc tối đa 3 bướu ≤3 cm, không xâm lấn mạch máu, không di căn xa\n- TACE chống chỉ định khi nào? :: Thuyên tắc tĩnh mạch cửa nhánh chính; bilirubin máu trên 3 mg/dL\n- Y-90 (SIRT) theo QĐ1514: ngưỡng shunt phổi? :: Dưới 20% để chỉ định; trên 20% là chống chỉ định tuyệt đối\n- Viêm gan do xạ sau Y-90 xử trí bằng gì? :: Hydrocortison liều cao 40–80 mg tiêm truyền tĩnh mạch\n- Vắcxin HBV người lớn: lịch và xử trí khi anti-HBs dưới 10 mIU/mL? :: 3 mũi (mũi 2 sau 1 tháng, mũi 3 sau 6 tháng); anti-HBs dưới 10 thì tiêm tiếp 3 mũi, xét nghiệm lại sau 1–2 tháng\n@@end"}, {"kind": "disease", "disease": "hoc-mieng-luoi", "short": "Ung thư hốc miệng", "group": "", "section": 0, "order": 10, "khung": [23, 50, 96, 105], "id": "ung-thu-hoc-mieng-luoi", "title": "Ung thư hốc miệng (ung thư lưỡi)", "layer": "benh", "module": "ung-buou", "tags": ["ung bướu", "hốc miệng", "lưỡi", "carcinôm tế bào gai", "thuốc lá", "nhai trầu", "HPV", "DOI", "TNM AJCC 8", "nạo hạch cổ", "hóa xạ trị đồng thời", "cetuximab"], "source": "Y5 tr.150–165 (chương Ung thư hốc miệng, đọc toàn bộ; Bảng 1 và Bảng 2 đối chiếu ảnh); QĐ1514 Bài 27 tr. PDF 198–204; SY5 tr.68, 71–72; ĐC Y5 tr.1–4, 7; 128VĐ mục 60, 114, 123; QĐ22 tr.8", "body": "> [!key] Ung thư hốc miệng (lưỡi) trong một nhìn\n> - Hơn ==90%== ung thư hốc miệng là **carcinôm tế bào gai**; hay gặp ở **môi, lưỡi, sàn miệng, nướu răng** {{Y5 tr.150}}\n> - Tổn thương dễ thấy khi khám thường quy nhưng **chỉ 30% được chẩn đoán giai đoạn đầu**, 50% ở giai đoạn III–IV {{Y5 tr.151}}\n> - Chẩn đoán xác định = **mô bệnh học** (sinh thiết); phân giai đoạn **TNM AJCC 8**, trong đó **DOI** (độ sâu xâm lấn) là yếu tố tiên lượng quan trọng khi xếp giai đoạn {{Y5 tr.156}} {{Y5 tr.157}}\n> - Giai đoạn sớm: **phẫu thuật** được ưu tiên (xạ triệt để cho kết quả tương tự); giai đoạn III–IV: **đa mô thức** (phẫu + xạ ± hóa) {{Y5 tr.158}} {{Y5 tr.162}}\n> - Yếu tố nguy cơ chính: **thuốc lá, rượu, nhai trầu**; tái phát 80–90% trong 2–4 năm đầu {{Y5 tr.151}} {{Y5 tr.164}}\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Trên 90% là carcinôm tế bào gai; độ ác tính tăng dần theo vị trí: môi → má → nướu răng → lưỡi → sàn miệng {{Y5 tr.153}}\n> - Nguy cơ: **thuốc lá** (quan trọng nhất), **rượu**, **nhai trầu**; HPV được coi là nguyên nhân ở amidan và đáy lưỡi, vai trò trong ung thư miệng **chưa xác định** {{Y5 tr.151}} {{Y5 tr.152}}\n\n### Định nghĩa & dịch tễ\n- **Hốc miệng**: từ ranh giới da–môi đỏ tới vòm khẩu cái, eo hầu trước và hai phần ba trước lưỡi; gồm môi, niêm mạc má, nướu răng, lưỡi, sàn miệng, khẩu cái cứng, tam giác sau hàm {{Y5 tr.150}}\n- **Thế giới (GLOBOCAN 2018)**: hạng **16** trong các ung thư thường gặp; hơn 350.000 ca mới, hơn 170.000 tử vong; Châu Á chiếm 64,2%; dự đoán tăng 52% đến năm 2040 {{Y5 tr.151}}\n- **Giới**: nam nhiều hơn nữ; tỉ lệ nam:nữ giảm từ 6:1 (năm 1950) còn 2:1, có thể do hút thuốc ở phụ nữ tăng {{Y5 tr.151}}\n- **Tuổi**: 95% trên 40 tuổi; tuổi trung bình phát hiện 60; có xu hướng tăng ở người trẻ {{Y5 tr.151}}\n- **Tử vong**: trên 50% trong 35 năm qua dù đã có điều trị mới {{Y5 tr.151}}\n- **QĐ1514 (phạm vi không nêu)**: ghi **1.877 ca mới**, đứng hạng **18** (theo GLOBOCAN 2018), không nêu rõ phạm vi (Việt Nam hay thế giới); Y5 không có số liệu Việt Nam, xem lưu ý {{QĐ1514 tr.PDF 198}}\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Thói quen – lối sống\n- **Thuốc lá**: yếu tố quan trọng nhất; nguy cơ tăng đáng kể khi hút **trên 20 năm** và **trên 20 điếu/ngày** {{Y5 tr.151}}\n- **Rượu**: 7–19% ung thư hốc miệng do nghiện rượu; uống **trên 100 g/ngày** làm tăng **30 lần** nguy cơ; cộng gộp với thuốc lá còn tăng thêm; suy dinh dưỡng do rượu cũng ảnh hưởng {{Y5 tr.151}}\n- **Nhai trầu** (Ấn Độ, Đông Nam Á, thường kèm thuốc lá): vôi tác động lên hạt cau gây bỏng và xơ hóa niêm mạc; tổn thương tiền ung hóa ác **7,6%** {{Y5 tr.151}}\n- **Vệ sinh răng miệng kém**, nấm Candida mạn, Herpes, suy giảm miễn dịch (HIV, Fanconi): tăng nguy cơ **2–3 lần** {{Y5 tr.152}}\n- **Tia UV**: nguy cơ của ung thư **môi** {{Y5 tr.152}}\n@@tab Virus – di truyền – tổn thương tiền ung\n- **HPV**: được coi là nguyên nhân của ung thư đầu cổ, chủ yếu amidan và đáy lưỡi; ung thư HPV âm tính thường liên quan hút thuốc và uống rượu {{Y5 tr.151}}\n- Vai trò HPV trong ung thư **miệng** chưa được xác định, liên quan hành vi tình dục đường miệng; **không nên tiêm vaccine HPV để phòng ung thư miệng** do ít bằng chứng {{Y5 tr.152}}\n- Tổn thương tiền ung: hồng sản, bạch sản, xơ hóa dưới niêm mạc, lichen phẳng, viêm da do ánh sáng {{Y5 tr.158}}\n@@end\n\n### Sinh bệnh học & sinh học phân tử\n- Thuốc lá, rượu, HPV là tác nhân môi trường chính, gây rối loạn di truyền (thụ thể yếu tố tăng trưởng biểu bì, TP53, NOTCH1, Cyclin D1…) làm biến đổi tế bào niêm mạc {{Y5 tr.151}}\n- Khói thuốc kích hoạt EGFR, tăng PGE2 và Cyclin D1; methyl hóa ức chế **p16**, DAPkinase, E-cadherin, RAR-beta {{Y5 tr.154}}\n- Biến đổi sớm: mất đoạn 3p, 9p và hoạt hóa telomerase; biến đổi muộn: 17p (p53), 13q, 18q; protein HPV E6/E7 ức chế p53 và retinoblastoma {{Y5 tr.154}}\n- Nền tảng: [[ung-thu-co-che-sinh-ung]], [[ung-thu-sinh-hoc-phan-tu]], [[ung-thu-nguyen-nhan]]\n\n### Giải phẫu bệnh – phân loại\n- **Carcinôm tế bào gai** khoảng 90%; carcinôm tuyến ít gặp (tuyến nhầy, tuyến nước bọt); hiếm gặp: carcinôm tế bào đáy, mêlanôm, sarcôm {{Y5 tr.153}}\n- Carcinôm tuyến nước bọt phụ thường gặp ở vùng khẩu cái; carcinôm không biệt hóa, mêlanôm, sarcôm, lymphôm ít gặp hơn và thường ở người trẻ {{Y5 tr.153}}\n\n| Dạng đại thể | Đặc điểm | Vị trí thường gặp |\n|---|---|---|\n| **Loét** | bờ không đều, gồ cứng; đáy có hạt, dễ hoại tử, chảy máu, dính mô quanh | **lưỡi, sàn miệng** |\n| **Chồi sùi** (như bông cải) | dễ lở loét, chảy máu | môi, má, khẩu cái, nướu răng |\n| **Mụn cóc** | phát triển chậm, lan bề mặt hơn xâm lấn sâu, ít di căn xa; dễ nhầm với lành tính | niêm mạc má, nướu răng |\n| **Thâm nhiễm** | bề mặt không loét hoặc loét không rõ, thâm nhiễm xuống nền cứng dính | tài liệu không nêu |\n\n{{Y5 tr.153}} {{Y5 tr.154}}\n\n- Độ biệt hóa giảm dần (độ ác tính tăng) từ trước ra sau: môi, má, nướu răng, lưỡi, sàn miệng {{Y5 tr.153}}\n\n### Diễn tiến tự nhiên – lan tràn\n@@tabs\n@@tab Xâm lấn tại chỗ\n- Lưng lưỡi, khẩu cái cứng, sàn miệng: lan nông trên bề mặt trước, xâm lấn sâu ở giai đoạn muộn; **bờ lưỡi** xâm lấn sâu theo cơ nội tại của lưỡi {{Y5 tr.152}}\n- **Xương**: là hàng rào; xâm lấn thật sự thường ở giai đoạn muộn, dù khối u có thể xâm lấn sớm màng xương {{Y5 tr.152}}\n- **Xương hàm dưới**: lan tràn chủ yếu tại điểm tiếp xúc với khối u, hoặc từ mặt nhai (vùng hậu hàm, vùng mất răng); lan theo thần kinh huyệt răng dưới hiện không còn giá trị {{Y5 tr.152}}\n@@tab Hạch cổ\n- Thường di căn nhóm hạch trên cơ vai móng; vị trí nguyên phát định hướng nhóm hạch {{Y5 tr.152}} {{Y5 tr.153}}\n\n| Vị trí nguyên phát | Nhóm hạch thường gặp | Ghi chú |\n|---|---|---|\n| **Lưỡi** | nhóm II rồi đến hạch cảnh giữa | có thể di căn nhóm III, IV **mà không có nhóm II** |\n| **Sàn miệng** | nhóm IB nhiều nhất; có thể nhóm II | di căn hạch sớm |\n| Niêm mạc má, nướu răng hàm dưới | nhóm IB (đầu tiên) | |\n| Tam giác sau hàm | nhóm IB và II | |\n| Môi | 1/3 giữa: nhóm IA; 1/3 ngoài: nhóm IB | ung thư môi di căn hạch muộn |\n| Nhóm V | hiếm gặp | |\n| Nhóm IIB | hiếm đơn độc, thường sau nhóm IIA; nhiều nhất ở lưỡi và tam giác sau hàm | |\n\n{{Y5 tr.153}}\n\n@@tab Di căn xa\n- Ít gặp; thường đến **phổi, gan, xương** {{Y5 tr.153}}\n@@end\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Tổn thương điển hình: **khối sùi hoặc vết loét không lành, thường không đau**, dễ chảy máu, hay gặp ở lưỡi và sàn miệng {{Y5 tr.154}}\n> - Khám: đèn soi (thành sau và sàn miệng), sờ, vận động lưỡi; **khám hạch cổ hai bên là bắt buộc** {{Y5 tr.155}}\n> - Giai đoạn muộn: đau lan lên tai, khít hàm, nói khó; nhiều bệnh nhân đến khám vì **hạch cổ** {{QĐ1514 tr.PDF 198}} {{Y5 tr.155}}\n\n### Triệu chứng cơ năng\n@@tabs\n@@tab Giai đoạn sớm\n- Cảm giác **vướng trong miệng**, có thể kèm **nuốt đau**; tăng tiết nước bọt, đôi khi có máu {{QĐ1514 tr.PDF 198}}\n- Nói khó; nhức đầu âm ỉ, thường một bên, đau lan lên tai {{QĐ1514 tr.PDF 198}}\n- Có thể chảy máu từ tổn thương; nhiều trường hợp **không triệu chứng**, được phát hiện khi khám định kỳ, nhất là khám răng miệng {{Y5 tr.154}}\n@@tab Giai đoạn muộn\n- Nhức đầu liên tục, có lúc dữ dội, đau nhói lan lên tai; nói khó và đau; khạc đờm lẫn máu, có mùi hôi {{QĐ1514 tr.PDF 198}}\n- Khít hàm; nói khó do lưỡi kém di động; nước bọt lẫn máu hoặc mủ {{Y5 tr.155}}\n- Bướu lớn, loét xâm nhiễm cơ, thần kinh, bội nhiễm gây đau nhức {{Y5 tr.154}}\n- Nhiều bệnh nhân đến khám vì **có hạch cổ** {{QĐ1514 tr.PDF 198}}\n@@end\n\n### Thực thể\n- **Tổn thương**: nụ sùi, loét, hoặc vừa sùi vừa loét; dễ chảy máu; bờ không đều, thâm nhiễm cứng; bệnh nhân đau khi thăm khám chạm vào {{QĐ1514 tr.PDF 198}}\n- **Đánh giá xâm lấn bằng tay**: vào đường giữa; lưỡi di động và lưỡi cố định; xương hàm; thâm nhiễm qua da {{QĐ1514 tr.PDF 199}}\n- **Quan sát**: đèn soi tỉ mỉ; vị trí hay bỏ sót là thành sau và sàn miệng; độ di động lưỡi để biết đã lan tới cơ vận động lưỡi; có thể lệch răng, lệch xương {{Y5 tr.155}}\n- **Hạch**: góc hàm và dưới cằm hai bên; chắc, bờ không đều, đôi khi thâm nhiễm, không di động {{QĐ1514 tr.PDF 199}}\n\n### Tiếp cận các triệu chứng (khung 128 vấn đề)\n| STT | Vấn đề | Liên hệ với ung thư hốc miệng |\n|---|---|---|\n| [96](#/khung/96) | **Khối ở cổ** (128VĐ mục 114) | hạch cổ là biểu hiện thường gặp; ung thư môi và hốc miệng thường di căn nhóm hạch I–III; khối không triệu chứng vẫn có thể là ung thư vùng đầu cổ {{128VĐ mục 114}} |\n| [50](#/khung/50) | **Nghẹn, nuốt khó** {{128VĐ mục 60}} | cảm giác vướng và nuốt đau ở giai đoạn sớm {{QĐ1514 tr.PDF 198}} |\n| [105](#/khung/105) | **Cứng hàm** {{128VĐ mục 123}} (nhiều nguyên nhân; cứng hàm là biểu hiện đầu tiên và thường gặp nhất của uốn ván) | khít hàm do ung thư là dấu hiệu **muộn**, cần phân biệt với uốn ván {{Y5 tr.155}} {{128VĐ mục 123}} |\n| [23](#/khung/23) | **Ù tai/đau tai/chảy dịch tai** | đau lan lên tai ở giai đoạn sớm và muộn {{QĐ1514 tr.PDF 198}} |\n\n> [!red] Dấu hiệu báo động (nghĩ đến ung thư hốc miệng)\n> - **Vết loét không lành** ở môi, lưỡi, niêm mạc má, sàn miệng, vòm khẩu cái {{SY5 tr.68}} {{SY5 tr.71}}\n> - Tổn thương niêm mạc kéo dài **trên 2 tuần**: nên đánh giá lại hoặc sinh thiết {{Y5 tr.156}}\n> - Khối sùi hoặc loét, bờ không đều, cứng, dễ chảy máu {{QĐ1514 tr.PDF 198}}\n> - Hạch cổ chắc, bờ không đều, không di động {{QĐ1514 tr.PDF 199}}\n> - Mất độ bóng, loét, đỏ, cứng khi khám lâm sàng: phải sinh thiết {{Y5 tr.155}}\n\n## 5. Cận lâm sàng\n\n> [!key] Tóm tắt\n> - **Mô bệnh học** là xét nghiệm bắt buộc để xác định; sinh thiết trực tiếp qua ống soi cứng hoặc mềm, có thể gây tê {{QĐ1514 tr.PDF 199}}\n> - **CT/MRI** cản quang (có cửa sổ xương) đánh giá nguyên phát; **PET/CT** cho giai đoạn và theo dõi; **siêu âm cổ** tìm hạch {{QĐ1514 tr.PDF 199}} {{Y5 tr.155}}\n> - **DOI** (độ sâu xâm lấn) quyết định T và dự đoán di căn hạch cổ; phân giai đoạn theo **TNM AJCC 8** {{Y5 tr.156}} {{Y5 tr.161}}\n\n### Chẩn đoán hình ảnh\n@@tabs\n@@tab CT – MRI – PET\n- **CT cản quang**: phát hiện nguyên phát trong hốc miệng với độ nhạy **61%**, đặc hiệu **100%**, chính xác **66%**; hữu ích với tam giác sau hàm, nướu răng, môi, niêm mạc má (dễ xâm lấn xương) {{Y5 tr.155}}\n- CT tương đương MRI trong phát hiện hạch cổ di căn {{Y5 tr.155}}\n- **MRI**: ưu thế đánh giá xâm lấn mô mềm và xương; độ dày khối trên MRI thường lớn hơn mô học sau mổ {{Y5 tr.155}}\n- **PET**: giai đoạn tiến triển; phát hiện hạch vùng, di căn xa, ung thư thứ hai và tái phát; hạn chế đánh giá lan rộng tại chỗ; đánh giá xâm lấn tủy xương hàm {{Y5 tr.155}}\n- QĐ1514: CT/MRI cản quang có cửa sổ xương để đánh giá xâm lấn; **PET/CT 18F-FDG** trước điều trị (u nguyên phát, giai đoạn), sau điều trị để theo dõi, và mô phỏng xạ trị {{QĐ1514 tr.PDF 199}}\n- X-quang Hirtz, Blondeaux: ít làm vì giá trị chẩn đoán thấp {{QĐ1514 tr.PDF 199}}\n@@tab Siêu âm – khác\n- Siêu âm tin cậy để tìm hạch cổ, kết hợp chọc hút; nhạy **84%** (cao nhất) nhưng đặc hiệu **68%** (thấp nhất) so với PET, CT, MRI {{Y5 tr.155–156}}\n- Doppler mạch giúp dự đoán mức lan tràn của bướu nguyên phát và hạch cổ ở ung thư lưỡi {{Y5 tr.155}}\n- Khối dày **dưới 7 mm**: nguy cơ di căn hạch **12%**; **trên 7 mm**: **57%**; siêu âm trong miệng đánh giá diện cắt sâu trong mổ {{Y5 tr.156}}\n- Siêu âm ổ bụng và chụp phổi thẳng tìm di căn; xạ hình xương SPECT/CT 99mTc-MDP {{QĐ1514 tr.PDF 199}}\n@@tab Tế bào – dấu ấn – gen\n- Quệt tế bào bong ở tổn thương; chọc hút kim nhỏ hạch cổ để chẩn đoán tế bào {{QĐ1514 tr.PDF 199}}\n- **Chất chỉ điểm** (theo dõi đáp ứng, tái phát, di căn xa): SCC, Cyfra 21-1, CEA, CA 19-9 {{QĐ1514 tr.PDF 199}}\n- Miễn dịch tìm EBV (IgA/VCA, IgA/EBNA); công thức máu, sinh hóa, điện tim đánh giá toàn thân {{QĐ1514 tr.PDF 199}}\n- Giải trình tự nhiều gen được nêu trong nguồn; ứng dụng cụ thể cho ung thư hốc miệng: tài liệu không nêu {{QĐ1514 tr.PDF 199}}\n@@end\n\n### Sinh thiết và đo DOI\n- Sinh thiết **tại rìa** tổn thương, lấy cả bướu và niêm mạc bình thường; sinh thiết đủ sâu để đánh giá DOI; gây tê, khó thì gây mê {{Y5 tr.156}}\n- Nếu mẫu sinh thiết xâm lấn **trên 2 mm** thì độ sâu thực thường **trên 3,5 mm** {{Y5 tr.156}}\n- **DOI**: khoảng cách từ mặt phẳng ngang qua màng đáy tới điểm sâu nhất của khối u; khác với **độ dày bướu** (tumor thickness) đo từ bề mặt tới điểm xâm lấn sâu nhất {{Y5 tr.156}} {{Y5 tr.157}}\n\n### Phân giai đoạn TNM (AJCC 8)\nY5 dùng AJCC 8 (2018); QĐ1514 ghi AJCC 2017; T1–T2 khớp, T3 và N3 khác (xem lưu ý).\n\n@@tabs\n@@tab T\n| T | Tiêu chuẩn |\n|---|---|\n| Tis | ung thư biểu mô tại chỗ |\n| T1 | u **≤2 cm** và **DOI ≤5 mm** (ảnh Bảng 1 Y5 in \">=2 cm\", xem lưu ý) |\n| T2 | u ≤2 cm với DOI trên 5–10 mm; hoặc trên 2–4 cm với DOI ≤10 mm |\n| T3 | trên 2–4 cm với DOI trên 10 mm; hoặc trên 4 cm với DOI ≤10 mm (ngưỡng DOI khác QĐ1514, xem lưu ý) |\n| T4a | trên 4 cm với DOI trên 10 mm; hoặc xâm lấn xương hàm trên/dưới, xoang hàm trên, da mặt |\n| T4b | xâm lấn khoang cơ nhai, mỏm chân bướm, đáy sọ và/hoặc động mạch cảnh |\n\n{{Y5 tr.157}} {{QĐ1514 tr.PDF 200}}\n\n@@tab N\n| N | Tiêu chuẩn |\n|---|---|\n| N0 | không di căn hạch vùng |\n| N1 | 1 hạch cùng bên ≤3 cm, ENE(–) |\n| N2a | 1 hạch cùng bên trên 3 cm đến ≤6 cm, ENE(–) |\n| N2b | nhiều hạch cùng bên ≤6 cm, ENE(–) |\n| N2c | hạch đối bên hoặc hai bên ≤6 cm, ENE(–) |\n| N3 | 1 hạch trên 6 cm, ENE(–); hoặc bất kỳ hạch có ENE(+) |\n\nENE = xâm lấn ngoài vỏ hạch. {{Y5 tr.157}} {{QĐ1514 tr.PDF 200}}\n\n@@tab Nhóm giai đoạn\n| Giai đoạn | T | N | M |\n|---|---|---|---|\n| 0 | Tis | N0 | M0 |\n| I | T1 | N0 | M0 |\n| II | T2 | N0 | M0 |\n| III | T3 | N0 | M0 |\n| III | T1–T3 | N1 | M0 |\n| IVA | T4a | N0–N1 | M0 |\n| IVA | T1–T3, T4a | N2 | M0 |\n| IVB | T4b | bất kỳ | M0 |\n| IVB | bất kỳ | N3 | M0 |\n| IVC | bất kỳ | bất kỳ | M1 |\n\n{{Y5 tr.157}} {{QĐ1514 tr.PDF 200–201}}\n@@end\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Chẩn đoán xác định\n> - Lâm sàng (tổn thương niêm mạc không lành, hạch cổ) + **mô bệnh học ung thư** là bắt buộc {{QĐ1514 tr.PDF 199}}\n> - Tổn thương niêm mạc kéo dài **trên 2 tuần** nên đánh giá lại hoặc sinh thiết; mọi sang thương nên được sinh thiết {{Y5 tr.156}} {{Y5 tr.158}}\n> - Mô bệnh học nguyên phát âm tính → sinh thiết hạch cổ (chẩn đoán gián tiếp) {{QĐ1514 tr.PDF 199}}\n> - Xác định **giai đoạn** TNM để tiên lượng và lập kế hoạch điều trị {{QĐ1514 tr.PDF 201}}\n\n### Chẩn đoán phân biệt\n| Bệnh lý | Điểm giống | Điểm khác / cách phân biệt |\n|---|---|---|\n| Hạch cổ do lao; tổn thương lao | hạch cổ | chẩn đoán chủ yếu dựa mô bệnh học {{QĐ1514 tr.PDF 201}} |\n| Hạch di căn của ung thư vùng đầu cổ khác | hạch cổ | tìm nguyên phát; mô bệnh học {{QĐ1514 tr.PDF 201}} |\n| Lymphôm (ung thư hạch hệ thống) biểu hiện ở hạch cổ | hạch cổ | mô bệnh học {{QĐ1514 tr.PDF 201}} |\n| Tổn thương tiền ung: hồng sản, bạch sản, xơ hóa dưới niêm mạc, lichen phẳng, viêm da do ánh sáng | tổn thương niêm mạc | không phải ung thư nhưng có thể tiến triển; sinh thiết và theo dõi thường xuyên {{Y5 tr.158}} |\n| Loét lành tính (nhiễm, chấn thương) | loét | tài liệu không nêu cách phân biệt |\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n\n> [!key] Mục tiêu theo giai đoạn\n> - **Giai đoạn sớm (I–II)**: chữa khỏi; phẫu thuật được ưu tiên vì ít di chứng hơn xạ trị (kết quả hồi cứu tương tự) {{Y5 tr.158}}\n> - **Giai đoạn III–IV (tiến xa tại chỗ–tại vùng)**: tiến triển nhanh, tái phát cao nếu chỉ mổ hoặc chỉ xạ → **kết hợp hai mô thức** và ê kíp đa chuyên khoa (phẫu thuật, xạ, hóa, dinh dưỡng) {{Y5 tr.162}}\n> - **Bảo tồn chức năng nói–nuốt và thẩm mỹ**; tạo hình sau mổ là điều kiện bắt buộc {{Y5 tr.159}} {{Y5 tr.164}}\n> - **Không mổ được**: giai đoạn IVB hóa xạ đồng thời; IVC hóa trị toàn thân hoặc chăm sóc giảm nhẹ {{QĐ1514 tr.PDF 202}}\n\n### 7.2 Các phương pháp\n\n@@tabs\n@@tab Phẫu thuật\n- **Nguyên tắc**: cắt rộng, **diện cắt cách bướu ≥1 cm mọi phía**; diện cắt sát **dưới 5 mm** tiên lượng xấu; diện cắt dương ưu tiên cắt rộng lại hơn xạ bổ túc {{Y5 tr.158}}\n- **Lưỡi**: cắt rộng với bờ âm tính giúp bảo tồn nói–nuốt; cắt bán phần làm giảm vận động và cảm giác; khó đánh giá diện cắt cơ sâu {{Y5 tr.159}}\n- **Lưỡi tiến xa**: bướu lan tới động mạch lưỡi hai bên → cắt lưỡi toàn phần; cân nhắc hóa xạ đồng thời vì cắt toàn phần hiệu quả kém và mất chức năng lưỡi; theo dõi viêm phổi hít {{Y5 tr.163}}\n- **Sàn miệng**: cắt rộng qua miệng, tránh tổn thương thần kinh lưỡi; u lớn cần tạo hình để sàn miệng giữ nước, tránh dò nước bọt {{Y5 tr.159}}\n- **Tam giác sau hàm và nướu răng hàm dưới**: thường cắt kèm một phần bản xương hàm dưới; răng tốt chỉ cắt bờ xương, răng kém cắt đoạn xương hàm {{Y5 tr.160}} {{Y5 tr.163}}\n- **Nướu răng hàm trên và vòm khẩu cái cứng**: phẫu thuật là lựa chọn đầu tiên khi tiến triển; tránh hoại tử xương hàm {{Y5 tr.160}} {{Y5 tr.164}}\n- **Niêm mạc má**: tổn thương nhỏ cắt rộng qua miệng; xâm lấn sâu tới da ngoài phải tạo hình {{Y5 tr.160}}\n- **Môi**: cắt rộng là chọn lựa đầu tiên; xạ triệt để đôi khi được ưa chuộng về thẩm mỹ {{Y5 tr.159}} {{Y5 tr.163}}\n- **Hỗ trợ sau mổ**: khai khí quản dự phòng (trừ nướu hàm trên và vòm); ống thông dạ dày để bảo đảm dinh dưỡng {{Y5 tr.163}}\n- **Biến chứng**: nhiễm trùng, chảy máu, viêm phổi hít, chậm lành, hoại tử vạt da, dò {{Y5 tr.159}}\n@@tab Nạo hạch cổ\n- Nạo hạch **phòng ngừa** được khuyến cáo ở giai đoạn sớm, **trừ ung thư môi** {{Y5 tr.161}}\n- **Chọn lọc**: giai đoạn I có DOI **trên 3 mm**, và mọi giai đoạn II (trừ xâm lấn tối thiểu) {{Y5 tr.161}}\n- Phạm vi: lưỡi di động nhóm I–IV (văn bản; Bảng 2 ghi I–VI, xem lưu ý); các vị trí khác nhóm I–III; bướu gần đường giữa hoặc nằm đường giữa cân nhắc nạo **hai bên** {{Y5 tr.161}}\n- **Hạch lính gác**: thay thế nạo chọn lọc khi DOI dưới 3 mm, nguy cơ trung bình, hoặc bướu lớn lan tới đường giữa; giá trị tiên đoán âm **95%** (châu Âu, Mỹ) {{Y5 tr.161}}\n- Giai đoạn muộn: nạo hạch thường quy, rộng tùy mức lan rộng; bướu ăn lan hoặc gần đường giữa nạo hai bên {{Y5 tr.164}}\n\nBảng 2 (nạo hạch phòng ngừa, giai đoạn sớm):\n\n| Bướu nguyên phát | Nạo hạch cổ phòng ngừa |\n|---|---|\n| Môi dưới T1 | không |\n| Môi dưới T2 | nhóm I |\n| Lưỡi (xâm lấn sâu trên 3 mm) | nhóm I, II, III, IV, V, VI |\n| Nướu răng hàm dưới; tam giác sau hàm | nhóm I, II, III |\n| Nướu răng hàm trên; vòm khẩu cái cứng | không |\n| Niêm mạc má | nhóm không ghi; chú ý hạch kế cận động và tĩnh mạch mặt, chỗ nhánh thần kinh bờ hàm dưới |\n\n{{Y5 tr.162}}\n\n@@tab Xạ trị\n- Giai đoạn sớm: **xạ ngoài** (bao gồm hạch cổ) hoặc **áp sát** (chỉ cho u nhỏ, nguy cơ hạch vi thể rất thấp) {{Y5 tr.160}}\n- Xạ triệt căn, chiếu ngoài (QĐ1514): nguy cơ cao **66 Gy** (2,2 Gy/ngày) hoặc **70 Gy** (2 Gy/ngày), 5 buổi/tuần, hoặc 81,6 Gy (1,2 Gy/ngày); nguy cơ thấp–trung bình **44–50 Gy** (2 Gy/ngày) hoặc **54–63 Gy** (1,6–1,8 Gy/ngày) {{QĐ1514 tr.PDF 202}}\n- Áp sát (QĐ1514): suất liều thấp (0,4–0,5 Gy/giờ): chiếu ngoài 50 Gy rồi thêm 20–35 Gy, hoặc 60–70 Gy; suất liều cao: 40–50 Gy rồi thêm 21 Gy (3 Gy/ngày), hoặc đơn thuần 45–60 Gy (3–6 Gy/ngày) {{QĐ1514 tr.PDF 202}}\n- Xạ hậu phẫu (QĐ1514): nguy cơ cao **60–66 Gy** (2 Gy/ngày, 5 buổi/tuần); nguy cơ thấp–trung bình như trên {{QĐ1514 tr.PDF 202}}\n- Hóa xạ đồng thời (nguy cơ cao): **70 Gy** (2 Gy/ngày, 5 buổi/tuần) {{QĐ1514 tr.PDF 202}}\n- Kỹ thuật điều biến cường độ hoặc dưới hướng dẫn hình ảnh giúp giảm khô miệng {{Y5 tr.161}}\n- Biến chứng cấp: viêm niêm mạc miệng, kích ứng da, mất vị giác, khó nuốt; muộn: xơ teo mô mềm, hoại tử xương (đặc biệt với xạ áp sát), khít hàm; khô miệng thường gặp {{Y5 tr.161}}\n@@tab Hóa trị – đích – miễn dịch\n- **Tân hỗ trợ (trước mổ)**: giảm thể tích phẫu thuật và xạ nhưng **không cải thiện tiên lượng sống**; chỉ áp dụng hạn chế hoặc trong thử nghiệm {{Y5 tr.162}}\n- **Hóa xạ đồng thời** (không mổ được hoặc chống chỉ định mổ): cisplatin, cetuximab, CF, PC, PP, DC ([chi tiết mục 7.3](#/n/ung-thu-hoc-mieng-luoi/7)) {{QĐ1514 tr.PDF 202}}\n- Ung thư tế bào vảy phối hợp xạ với cetuximab hoặc nimotuzumab hàng tuần giúp giảm độc tính hơn {{QĐ1514 tr.PDF 203}}\n- **Tái phát/di căn**: cisplatin (± cetuximab hoặc nimotuzumab), PC, DC, PP, pembrolizumab (PD-1) {{QĐ1514 tr.PDF 203–204}}\n@@end\n\n#### Điều trị bổ túc sau mổ\n- **Xạ bổ túc** khi diện cắt dương hoặc sát mà không mổ lại được, bướu xâm lấn xương, hoặc hạch dương khi nạo phòng ngừa {{Y5 tr.162}}\n- **DOI trên 3 mm** và **không nạo hạch phòng ngừa** → xạ bổ túc sau mổ {{Y5 tr.162}}\n- **DOI trên 4 mm**: xem xét xạ bổ túc, kể cả khi hạch âm tính; xâm lấn mạch bạch huyết hoặc quanh thần kinh: cân nhắc {{Y5 tr.162}}\n- **Hóa xạ đồng thời bổ túc**: diện cắt dương, xâm lấn ngoài hạch, xâm lấn quanh thần kinh–mạch máu {{Y5 tr.164}}\n- **T3–T4 không có yếu tố nguy cơ**: có thể chỉ xạ đơn thuần {{Y5 tr.164}}\n- Yếu tố nguy cơ tái phát: bờ phẫu thuật dương, xâm lấn quanh thần kinh, mạch máu, ngoài hạch, hạch N2/N3, di căn nhóm IV/V {{Y5 tr.164}}\n- QĐ1514 (giai đoạn III, IVa): không nguy cơ cao → xạ bổ trợ; nguy cơ cao (diện cắt dương, còn hạch ngoại vi hoặc yếu tố khác) → toàn thân kết hợp xạ bổ trợ {{QĐ1514 tr.PDF 201–202}}\n\n#### Theo giai đoạn\n@@tabs\n@@tab I–II\n- Phẫu thuật cắt u và vét hạch cổ cùng bên hoặc đối bên; hạch dương cân nhắc xạ bổ trợ; diện cắt dương cân nhắc hóa xạ bổ trợ {{QĐ1514 tr.PDF 201}}\n- Hóa xạ đồng thời khi chống chỉ định phẫu thuật {{QĐ1514 tr.PDF 201}}\n- Y5: phẫu thuật được ưu tiên; xạ triệt để khi chống chỉ định, không thích hợp mổ, hoặc mổ gây suy giảm chức năng đáng kể; tam giác sau hàm sớm dễ chấp nhận xạ hơn {{Y5 tr.158}}\n@@tab III–IVA\n- Phẫu thuật cắt u nguyên phát và vét hạch cổ cùng bên hoặc hai bên {{QĐ1514 tr.PDF 201}}\n- Không nguy cơ cao: xạ bổ trợ; nguy cơ cao: toàn thân kết hợp xạ bổ trợ {{QĐ1514 tr.PDF 202}}\n- Y5: kết hợp hai mô thức trở lên; tạo hình sau cắt bướu để duy trì chức năng ở mức chấp nhận được {{Y5 tr.162}}\n@@tab IVB\n- Chống chỉ định phẫu thuật: **hóa xạ đồng thời** {{QĐ1514 tr.PDF 202}}\n- Y5: bệnh không mổ được → xạ đơn thuần hoặc hóa xạ đồng thời {{Y5 tr.162}}\n@@tab IVC\n- Hóa trị toàn thân hoặc chăm sóc giảm nhẹ {{QĐ1514 tr.PDF 202}}\n@@end\n\n### 7.3 Phác đồ – Y lệnh\n\n> [!doc] QĐ 1514/QĐ-BYT (1/4/2020), chương \"Ung thư khoang miệng\": các phác đồ chép theo nguồn; liều tính theo mg/m² và truyền tĩnh mạch nếu không ghi khác. {{QĐ1514 tr.PDF 202–204}}\n\n| Phác đồ | Thuốc – liều | Chu kỳ / cách dùng | Bối cảnh | Ghi chú |\n|---|---|---|---|---|\n| **Cisplatin đơn** | cisplatin **100 mg/m²** TM ngày 1 | 3 tuần | hóa xạ đồng thời; hóa trị hậu phẫu | nguồn ghi cùng liều cho hậu phẫu và tái phát |\n| **Cetuximab + xạ** | cetuximab **400 mg/m²** ngày 1, rồi bắt đầu xạ và **250 mg/m²** hàng tuần | cùng thời gian xạ | đồng thời | cho ung thư tế bào vảy; nguồn ghi giảm độc tính hơn |\n| **Nimotuzumab + xạ** (thay thế) | nimotuzumab 200 mg hàng tuần trong 6 tuần xạ; sau đó duy trì 200 mg mỗi 15 ngày | | đồng thời | thay cho cetuximab |\n| **CF cisplatin–5-FU** | cisplatin **100 mg/m²** ngày 1 + 5-FU **1.000 mg/m²** TM ngày 1–5 | 3–4 tuần | đồng thời; tái phát/di căn | có thể kèm cetuximab |\n| **CF carboplatin–5-FU** (đồng thời) | carboplatin **70 mg/m²** bolus ngày 1–4 + 5-FU **600 mg/m²** ngày 1–4 | 3 tuần | đồng thời | |\n| **CF carboplatin–5-FU** (tái phát/di căn) | carboplatin **70 mg/m²** bolus ngày 1 + 5-FU **1.000 mg/m²** ngày 1–5 | 3–4 tuần | tái phát/di căn | |\n| **PC paclitaxel–carboplatin** | paclitaxel **135 mg/m²** ngày 1 + carboplatin AUC-2 ngày 1–4 | 6 tuần | đồng thời; tái phát/di căn | |\n| **PP paclitaxel–cisplatin** | paclitaxel **175 mg/m²** TM 3 giờ ngày 1 + cisplatin **75 mg/m²** TM 30 phút ngày 2 | 3 tuần | đồng thời; tái phát/di căn | |\n| **DC docetaxel–cisplatin** | docetaxel **75 mg/m²** TM 1 giờ ngày 1 + cisplatin **75 mg/m²** TM 3 giờ ngày 1 | 3 tuần | đồng thời; tái phát/di căn | |\n| **DCU** (trước xạ) | docetaxel 36 mg/m² + cisplatin 30 mg/m² ngày 1, 8; UFT 300 mg/m²/ngày ngày 1–14 | 21 ngày; 2 chu kỳ trước xạ | trước xạ | |\n| **UFT duy trì** | 400 mg/ngày, chia 2 lần | liên tục 1–2 năm sau xạ | sau xạ | |\n| **Pembrolizumab** | 200 mg/m² TM (nguồn ghi như vậy) | 3 tuần | tái phát/di căn | đối chiếu bản gốc đơn vị liều |\n| **Hóa trị hậu phẫu** | cisplatin **100 mg/m²** ngày 1 | 3 tuần | sau mổ | |\n\n{{QĐ1514 tr.PDF 202}} {{QĐ1514 tr.PDF 203}} {{QĐ1514 tr.PDF 204}}\n\n> [!warn] Lưu ý phác đồ\n> - Y5 không ghi liều thuốc hay phác đồ hóa xạ: chỉ dùng liều từ QĐ1514 {{Y5 tr.162}}\n> - Chương khoang miệng có đoạn chép từ **ung thư vòm mũi họng** (tr. PDF 201) và **hạ họng–thanh quản** (tr. PDF 204): không áp dụng cho hốc miệng {{QĐ1514 tr.PDF 201}} {{QĐ1514 tr.PDF 204}}\n> - Độc tính cần theo dõi khi hóa chất: giảm bạch cầu, tiểu cầu, thiếu máu, nôn, suy kiệt {{QĐ1514 tr.PDF 204}}\n\n## 8. Tiên lượng – Dự phòng\n\n> [!key] Tóm tắt\n> - Tiên lượng phụ thuộc **vị trí nguyên phát, DOI, giai đoạn, độ mô học, di căn hạch và di căn xa** {{Y5 tr.164}}\n> - Còn khu trú trong niêm mạc: sống còn 5 năm trên 80%; có di căn hạch vùng: khoảng 40%; di căn xa: khoảng 20% {{Y5 tr.164}}\n> - Tái phát **80–90%** trong 2–4 năm đầu; tiếp tục hút thuốc làm tăng nguy cơ {{Y5 tr.164}}\n\n### Tiên lượng\n@@tabs\n@@tab Yếu tố\n| Yếu tố | Nội dung (nguồn) |\n|---|---|\n| Vị trí nguyên phát | yếu tố tiên lượng {{Y5 tr.164}} |\n| DOI | yếu tố tiên lượng quan trọng khi xếp giai đoạn carcinôm tế bào gai, đặc biệt ở lưỡi {{Y5 tr.156}} |\n| Di căn hạch cổ | liên quan sống còn ở giai đoạn sớm {{Y5 tr.161}} |\n| Diện cắt | diện cắt là yếu tố ảnh hưởng tái phát tại chỗ; diện cắt sát dưới 5 mm tiên lượng xấu {{Y5 tr.158}} |\n| Độ mô học, giai đoạn | yếu tố tiên lượng {{Y5 tr.164}} |\n| Yếu tố tái phát | bờ dương, xâm quanh thần kinh, mạch máu, ngoài hạch, hạch N2/N3, di căn nhóm IV/V {{Y5 tr.164}} |\n@@tab Tỷ lệ sống\n- Còn khu trú trong niêm mạc: sống còn 5 năm **trên 80%**; có di căn hạch: **khoảng 40%**; có di căn xa: **khoảng 20%** {{Y5 tr.164}}\n- Theo giai đoạn: I **59,8%**, II **43,6%**, III **36,3%**, IV **13,3%** (Y5 không ghi mốc thời gian, xem lưu ý) {{Y5 tr.164}}\n- Tiên lượng tốt khi bệnh giai đoạn sớm được phẫu thuật triệt để và đánh giá đa chuyên khoa; xấu khi bệnh tiến triển, di căn {{QĐ1514 tr.PDF 204}}\n@@tab Tái phát\n- **80–90%** tái phát trong 2–4 năm đầu sau điều trị ban đầu {{Y5 tr.164}}\n- Dấu hiệu tái phát tại chỗ: khàn tiếng, đau, khó nuốt, chảy máu, hạch cổ to; ung thư nguyên phát thứ hai ở đầu cổ, thực quản, phổi {{Y5 tr.164}} {{Y5 tr.155}}\n@@end\n\n### Theo dõi sau điều trị (QĐ1514)\n| Thời điểm | Tần suất | Nội dung |\n|---|---|---|\n| Năm đầu | 1–3 tháng/lần | khám tái phát tại chỗ và hạch; siêu âm vùng cổ, chọc hút kim nhỏ nếu nghi ngờ |\n| Năm thứ 2 | 4–6 tháng/lần | như trên |\n| Các năm sau | 8 tháng/lần | |\n| Sau 5 năm | 1 năm/lần | |\n\n{{QĐ1514 tr.PDF 204}}\n\n- CT/MRI khi nghi tái phát nhưng khó xác định trên lâm sàng; PET/CT đánh giá di căn xa {{QĐ1514 tr.PDF 204}}\n\n### Dự phòng\n@@tabs\n@@tab Cấp 1 – phòng bệnh\n- Không hút thuốc lá, hạn chế rượu, không ăn trầu và tránh các yếu tố nguy cơ khác; khi có bất thường vùng miệng–họng đến khám sớm {{QĐ1514 tr.PDF 204}}\n- Vệ sinh răng miệng (kém là yếu tố nguy cơ); điều trị bệnh răng miệng trong quá trình điều trị ung thư {{Y5 tr.152}} {{QĐ1514 tr.PDF 201}}\n- Hạn chế tia UV (nguy cơ của ung thư môi) {{Y5 tr.152}}\n- **Không** tiêm vaccine HPV để phòng ung thư miệng vì ít bằng chứng {{Y5 tr.152}}\n@@tab Cấp 2 – phát hiện sớm\n- **Khám lâm sàng kỹ** (đèn soi, sờ, khám hạch) có thể giảm **32%** tử vong ở nhóm nguy cơ cao, tương đương khoảng 40.000 trường hợp {{Y5 tr.157}}\n- **Tự kiểm tra** răng miệng; đi khám khi bất thường niêm mạc kéo dài **trên 2 tuần** {{Y5 tr.158}}\n- Vẫn bỏ sót **4,5–15,3%** tổn thương dù khám kỹ; cần bổ sung phương tiện như nhuộm mô sống, phát hiện bằng ánh sáng, phân tích tế bào nước bọt và máu {{Y5 tr.158}}\n- Mọi sang thương nên được sinh thiết; tổn thương tiền ung cần theo dõi thường xuyên {{Y5 tr.158}}\n- Chương trình sàng lọc cho nhóm nguy cơ cao (rượu, thuốc lá) có thể giảm tử vong {{Y5 tr.158}}\n- Lịch tầm soát theo tuổi và tần suất: tài liệu không nêu\n@@tab Cấp 3 – phục hồi\n- Tạo hình và phục hồi chức năng để giữ nuốt và nói sau mổ; cắt bán phần lưỡi có thể làm giảm cảm giác và vận động {{Y5 tr.158}} {{Y5 tr.159}}\n- Dùng kỹ thuật xạ phù hợp mô đích để hạn chế khô miệng {{Y5 tr.162}}\n- Ống thông dạ dày để bảo đảm dinh dưỡng; chăm sóc răng miệng trong điều trị {{Y5 tr.163}} {{QĐ1514 tr.PDF 201}}\n@@end\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] Trọng số thi\n> - **Đề cương** (ĐC Y5): ca lâm sàng ung thư lưỡi gắn các MT 2, 3, 4, 5, 7, 8, 9, 10, 12, 13, 14, 15, 17; trong đó MT chẩn đoán là 3, 7, 14 và MT điều trị là 5, 8, 15 {{ĐC Y5 tr.1–4}} {{ĐC Y5 tr.7}}\n> - **QĐ 22** (tr.8): cận lâm sàng/xét nghiệm chẩn đoán trọng số **45–60**; xử trí (liệu pháp thuốc) **35–50** {{QĐ22 tr.8}}\n> - **Chẩn đoán**: sinh thiết mô bệnh học, khám hạch cổ hai bên, phân giai đoạn TNM (đặc biệt DOI) {{QĐ1514 tr.PDF 199}} {{Y5 tr.155}} {{Y5 tr.156}}\n\n@@tabs\n@@tab Nhận diện\n- Nguy cơ then chốt: **thuốc lá** (trên 20 năm, trên 20 điếu/ngày), **rượu** (trên 100 g/ngày: tăng 30 lần), **nhai trầu** {{Y5 tr.151}}\n- Gợi ý: **khối sùi hoặc vết loét không lành**, thường không đau ở giai đoạn sớm, dễ chảy máu, ở **lưỡi, sàn miệng** là chủ yếu {{Y5 tr.154}} {{Y5 tr.153}}\n- {r|Báo động}: vết loét không lành trên 2 tuần; hạch cổ chắc, không di động; đau lan tai và khít hàm ở giai đoạn muộn {{SY5 tr.68}} {{Y5 tr.155}} {{Y5 tr.156}} {{QĐ1514 tr.PDF 198}}\n- Hạch: lưỡi và sàn miệng di căn sớm; lưỡi có thể di căn nhóm III–IV mà không có nhóm II {{Y5 tr.153}}\n- [Xem mục 4](#/n/ung-thu-hoc-mieng-luoi/4) · [mục 3](#/n/ung-thu-hoc-mieng-luoi/3)\n@@tab Chẩn đoán\n- **Mô bệnh học** là tiêu chuẩn; sinh thiết tại rìa, đủ sâu để đo **DOI** {{QĐ1514 tr.PDF 199}} {{Y5 tr.156}}\n- Hình ảnh: CT/MRI cản quang (xương, mô mềm); PET/CT giai đoạn; siêu âm vùng cổ {{QĐ1514 tr.PDF 199}} {{Y5 tr.155}}\n- TNM AJCC 8: T1 ≤2 cm và DOI ≤5 mm; T4a trên 4 cm với DOI trên 10 mm; N1 ≤3 cm; N3 trên 6 cm hoặc ENE(+); M1 là IVC {{Y5 tr.157}} {{QĐ1514 tr.PDF 200}}\n- Siêu âm: khối dày trên 7 mm có nguy cơ di căn hạch **57%** (dưới 7 mm: 12%) {{Y5 tr.156}}\n- Tổn thương tiền ung: sinh thiết và theo dõi {{Y5 tr.158}}\n- [Xem mục 5](#/n/ung-thu-hoc-mieng-luoi/5) · [mục 6](#/n/ung-thu-hoc-mieng-luoi/6)\n@@tab Điều trị\n- **I–II**: phẫu thuật (diện cắt ≥1 cm) ± nạo hạch chọn lọc (giai đoạn I: DOI trên 3 mm; giai đoạn II: tất cả) {{Y5 tr.158}} {{Y5 tr.161}}\n- **III–IVA**: phẫu thuật + nạo hạch, rồi xạ hoặc hóa xạ bổ trợ theo nguy cơ {{QĐ1514 tr.PDF 201–202}}\n- **IVB** không mổ được: {p|hóa xạ đồng thời}; {p|cisplatin 100 mg/m²} ngày 1, chu kỳ 3 tuần; {p|cetuximab 400 mg/m²} rồi 250 mg/m² hàng tuần {{QĐ1514 tr.PDF 202}}\n- Xạ triệt căn: nguy cơ cao {r|66–70 Gy}; nguy cơ thấp–trung bình 44–50 Gy {{QĐ1514 tr.PDF 202}}\n- {r|DOI trên 3 mm không nạo hạch → xạ bổ túc}; {r|diện cắt dương hoặc xâm lấn ngoài hạch/quanh thần kinh–mạch máu → hóa xạ bổ túc} {{Y5 tr.162}} {{Y5 tr.164}}\n- Tân hỗ trợ: {o|không cải thiện tiên lượng sống} {{Y5 tr.162}}\n- [Xem mục 7.2](#/n/ung-thu-hoc-mieng-luoi/7) · [mục 7.3](#/n/ung-thu-hoc-mieng-luoi/7)\n@@tab Tiên lượng – Dự phòng\n- Còn khu trú niêm mạc: sống 5 năm trên 80%; có hạch: khoảng 40%; có di căn xa: khoảng 20% {{Y5 tr.164}}\n- Tái phát **80–90%** trong 2–4 năm đầu {{Y5 tr.164}}\n- Theo dõi (QĐ1514): năm đầu 1–3 tháng/lần; năm thứ 2 4–6 tháng/lần; các năm sau 8 tháng/lần; sau 5 năm 1 năm/lần {{QĐ1514 tr.PDF 204}}\n- Dự phòng: bỏ thuốc lá, hạn chế rượu, không ăn trầu; {o|không tiêm vaccine HPV để phòng ung thư miệng} {{Y5 tr.152}}\n- Khám lâm sàng kỹ giảm **32%** tử vong ở nhóm nguy cơ cao {{Y5 tr.157}}\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Carcinôm tế bào gai | ==trên 90%== | {{Y5 tr.150}} |\n| Chẩn đoán giai đoạn đầu / giai đoạn III–IV | ==30% / 50%== | {{Y5 tr.151}} |\n| Thuốc lá: nguy cơ tăng rõ khi | ==trên 20 năm và trên 20 điếu/ngày== | {{Y5 tr.151}} |\n| Rượu trên 100 g/ngày | ==tăng 30 lần nguy cơ== | {{Y5 tr.151}} |\n| Nhai trầu: tổn thương tiền ung hóa ác | ==7,6%== | {{Y5 tr.151}} |\n| Tổn thương niêm mạc kéo dài | ==trên 2 tuần: sinh thiết== | {{Y5 tr.156}} |\n| Hạng toàn cầu (GLOBOCAN 2018) | ==hạng 16== | {{Y5 tr.151}} |\n| T1 | ==≤2 cm và DOI ≤5 mm== | {{Y5 tr.157}} {{QĐ1514 tr.PDF 200}} |\n| T4a | ==trên 4 cm với DOI trên 10 mm, hoặc xâm lấn xương hàm/da mặt== | {{Y5 tr.157}} {{QĐ1514 tr.PDF 200}} |\n| N1 / N3 | ==≤3 cm / trên 6 cm hoặc ENE(+)== | {{Y5 tr.157}} |\n| Siêu âm: nhạy / đặc hiệu | ==84% / 68%== | {{Y5 tr.155–156}} |\n| Khối dày trên 7 mm: di căn hạch | ==57%== | {{Y5 tr.156}} |\n| Nạo hạch chọn lọc giai đoạn I | ==DOI trên 3 mm== | {{Y5 tr.161}} |\n| Diện cắt | ==cách bướu ≥1 cm; dưới 5 mm tiên lượng xấu== | {{Y5 tr.158}} |\n| Xạ bổ túc theo DOI | ==trên 3 mm (không nạo); trên 4 mm (xem xét)== | {{Y5 tr.162}} |\n| Cisplatin đồng thời | ==100 mg/m², ngày 1, chu kỳ 3 tuần== | {{QĐ1514 tr.PDF 202}} |\n| Cetuximab | ==400 mg/m² rồi 250 mg/m² hàng tuần== | {{QĐ1514 tr.PDF 202}} |\n| Xạ triệt căn nguy cơ cao | ==66 Gy (2,2 Gy/ngày) hoặc 70 Gy== | {{QĐ1514 tr.PDF 202}} |\n| Tái phát | ==80–90% trong 2–4 năm đầu== | {{Y5 tr.164}} |\n| Theo dõi năm đầu | ==1–3 tháng/lần== | {{QĐ1514 tr.PDF 204}} |\n| Tỷ lệ theo giai đoạn I / IV | ==59,8% / 13,3%== (mốc thời gian không nêu) | {{Y5 tr.164}} |\n\n> [!warn] Bẫy thi và mâu thuẫn giữa các nguồn\n> - **T1 trên ảnh Bảng 1 (Y5)** ghi \"kích thước >=2 cm\", có thể là lỗi chép; theo AJCC 8 và QĐ1514 là **≤2 cm** {{Y5 tr.157}} {{QĐ1514 tr.PDF 200}}\n> - **Ngưỡng DOI giữa T3 và T4a**: ảnh Bảng 1 Y5 xếp T3 khi trên 4 cm và DOI ≤10 mm; QĐ1514 xếp T3 khi DOI ≥10 mm. Ghi cả hai, khi thi dùng theo nguồn đề bài {{Y5 tr.157}} {{QĐ1514 tr.PDF 200}}\n> - **Nạo hạch lưỡi**: văn bản Y5 (tr.161) nhóm I–IV; Bảng 2 Y5 (tr.162) nhóm I–VI. Ghi cả hai {{Y5 tr.161}} {{Y5 tr.162}}\n> - **Xạ bổ túc theo DOI**: Y5 nêu DOI trên 3 mm khi không nạo hạch, và DOI trên 4 mm là xem xét (kể cả khi hạch âm tính) {{Y5 tr.162}}\n> - **Thứ hạng và số ca**: Y5 hạng 16 toàn cầu (GLOBOCAN 2018); QĐ1514 hạng 18, 1.877 ca mới, phạm vi không nêu; không so sánh trực tiếp {{Y5 tr.151}} {{QĐ1514 tr.PDF 198}}\n> - **Đau tổn thương**: Y5 nêu tổn thương giai đoạn sớm **không đau**; QĐ1514 ghi bệnh nhân **đau khi chạm** vào tổn thương {{Y5 tr.154}} {{QĐ1514 tr.PDF 198}}\n> - **Nhóm N3**: Y5 (AJCC 8) gộp N3; QĐ1514 (AJCC 2017) tách N3a/N3b, cùng nội dung {{Y5 tr.157}} {{QĐ1514 tr.PDF 200}}\n> - **Tỷ lệ sống theo giai đoạn** (Y5 tr.164) không ghi mốc thời gian và cách tính; không đặt cạnh tỷ lệ \"trên 80%\" như cùng một chỉ số {{Y5 tr.164}}\n> - {r|Thuốc lá tiếp tục sau điều trị làm tăng nguy cơ tái phát} {{Y5 tr.164}}\n\n@@fold Nguồn tài liệu\n- Y5: TEXT UNG BƯỚU Y5.pdf, chương Ung thư hốc miệng (tr.150–165), đọc toàn bộ; Bảng 1 (tr.157) và Bảng 2 (tr.162) đối chiếu ảnh render\n- QĐ1514/QĐ-BYT: Bài 27 \"Ung thư khoang miệng\" (tr. PDF 198–204), đọc toàn bộ chương (`_work/qd-1514-byt-ung-buou.txt`)\n- Slide Y5 (`_work/slide-y5.txt`): tr.68, 71–72 (dấu hiệu báo động; slide không có chương riêng về hốc miệng)\n- Đề cương Y5 (`_work/decuong-y5.txt`): MT1–MT17 (tr.1–4); ca lâm sàng ung thư lưỡi (tr.7)\n- QĐ 22 (`_work/qd22.txt`, tr.8): trọng số đề mục năng lực\n- Sách 128 vấn đề: mục 60 (nghẹn, nuốt khó), 114 (khối ở cổ), 123 (cứng hàm)\n- Khung QĐ 22: STT 23, 50, 96, 105 (`data/qd22.json`, STT = thứ tự 1–128)\n@@end\n\n@@fold Nguồn ngoài\n- Không dùng nguồn ngoài trong bài này: số liệu và phác đồ lấy từ các nguồn nội bộ ở trên; mục nào nguồn không nêu được ghi \"tài liệu không nêu\"\n@@end\n\n@@fold Tự kiểm tra (14 thẻ)\n- Yếu tố nguy cơ hàng đầu của ung thư hốc miệng? :: Thuốc lá (đặc biệt trên 20 năm, trên 20 điếu/ngày)\n- Rượu trên 100 g/ngày làm nguy cơ tăng bao nhiêu lần? :: 30 lần; cộng gộp với thuốc lá còn tăng thêm\n- Tỷ lệ carcinôm tế bào gai trong ung thư hốc miệng? :: Trên 90%\n- Vị trí nào di căn hạch sớm? :: Lưỡi và sàn miệng (lưỡi: nhóm II trước, có thể nhóm III–IV mà không có nhóm II)\n- Tổn thương niêm mạc kéo dài bao lâu thì phải sinh thiết? :: Trên 2 tuần\n- Chẩn đoán xác định ung thư hốc miệng dựa vào gì? :: Mô bệnh học (sinh thiết; bắt buộc)\n- DOI là gì? :: Khoảng cách từ mặt phẳng ngang qua màng đáy đến điểm sâu nhất của khối u\n- T1 theo AJCC 8 (Y5, QĐ1514)? :: Khối u ≤2 cm và DOI ≤5 mm\n- Khối dày trên 7 mm trên siêu âm có nguy cơ di căn hạch bao nhiêu? :: 57% (dưới 7 mm: 12%)\n- Ngưỡng DOI để nạo hạch chọn lọc giai đoạn I? :: Trên 3 mm\n- Liều cisplatin trong hóa xạ đồng thời (QĐ1514)? :: 100 mg/m² truyền tĩnh mạch ngày 1, chu kỳ 3 tuần\n- Theo dõi năm đầu sau điều trị (QĐ1514)? :: 1–3 tháng/lần\n- Tái phát thường xảy ra khi nào? :: 80–90% trong 2–4 năm đầu\n- Lưỡi di căn hạch cổ nhóm nào trước? :: Nhóm II, rồi hạch cảnh giữa\n@@end"}, {"kind": "disease", "disease": "noi-mac-tu-cung", "short": "Ung thư nội mạc tử cung", "group": "", "section": 0, "order": 5, "khung": [87, 89, 91], "id": "ung-thu-noi-mac-tu-cung", "title": "Ung thư nội mạc tử cung", "layer": "benh", "module": "ung-buou", "tags": ["ung bướu", "nội mạc tử cung", "thân tử cung", "ra máu âm đạo sau mãn kinh", "estrogen", "progestin", "FIGO 2018", "AJCC 8", "nội tiết", "phác đồ BYT"], "source": "Y5 tr.40–55; QĐ 1514/QĐ-BYT Bài 45 (tr. PDF 371–377); ĐC Y5 tr.1–4, 6; SY5 tr.7, 180, 183; 128VĐ mục 91–92; QĐ 22 STT 87, 89, 91", "body": "> [!key] Ung thư nội mạc tử cung (UNMTC) trong một nhìn\n> - Ung thư phụ khoa thường gặp nhất ở các nước phát triển, tần suất đang tăng {{Y5 tr.40}}\n> - Triệu chứng hay gặp nhất: ==ra máu âm đạo bất thường==, chiếm tới 90% trường hợp {{QĐ1514 tr.PDF 371}}\n> - Chẩn đoán xác định = **mô bệnh học** từ nạo/sinh thiết lòng tử cung {{Y5 tr.48}} {{QĐ1514 tr.PDF 372}}\n> - Điều trị chủ yếu **phẫu thuật** (cắt tử cung toàn bộ + hai phần phụ); xạ trị bổ trợ theo nguy cơ; giai đoạn tiến xa thêm hóa trị, nội tiết {{Y5 tr.51}} {{QĐ1514 tr.PDF 374}}\n> - Kiểu I (~80%): liên quan estrogen không đối kháng, grad thấp, tiên lượng tốt; kiểu II (~20%): grad cao, tiên lượng xấu hơn {{Y5 tr.41}}\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Đa số là carcinôm tuyến dạng nội mạc, do **estrogen không đối kháng progestin** kéo dài; béo phì và đái tháo đường là nguy cơ chính {{Y5 tr.42}} {{Y5 tr.44}}\n> - Bảo vệ then chốt: **progestin** (thuốc ngừa thai uống kết hợp, progestin đơn thuần), sinh con, cho con bú {{Y5 tr.44}} {{Y5 tr.45}}\n> - Diễn tiến chủ yếu tại chỗ nhờ lớp cơ tử cung dày; di căn hạch và di căn xa ít gặp {{Y5 tr.46}} {{SY5 tr.7}}\n\n### Định nghĩa & dịch tễ\n- Ung thư thân tử cung gồm chủ yếu ung thư **nội mạc tử cung**; phần nhỏ là sarcôm mô đệm nội mạc và sarcôm cơ trơn thân tử cung {{Y5 tr.40}}\n- Thế giới (Globocan 2018, Y5): ==382.069 ca mới/năm==, xuất độ ==8,4/100.000==; ==89.929 ca tử vong/năm==, tử suất 1,8/100.000 {{Y5 tr.40}}\n- Bắc Mỹ xuất độ tới 20,5/100.000 {{Y5 tr.40}}\n- Tuổi: gặp chủ yếu ở đã mãn kinh (75%, thường ≥55 tuổi); tần suất tăng từ dưới 30 tuổi đến đỉnh khoảng 65 tuổi; tuổi trung bình 60–70; 2–5% dưới 40 tuổi (Y5); QĐ1514 ghi 5% {{Y5 tr.41}} {{QĐ1514 tr.PDF 371}}\n- Mỹ (QĐ1514, 2018): 63.230 ca mới, 11.350 tử vong; chiếm 6% ung thư nữ {{QĐ1514 tr.PDF 371}}\n\n| Nguồn | Ca mới | Tử vong | Ghi chú |\n|---|---|---|---|\n| Y5 (Globocan 2018) | 4177 ca; 7,1/100000 | 2420 ca; 2/100000 | hàng 8 trong ung thư nữ VN {{Y5 tr.40}} |\n| QĐ1514 (Globocan 2018) | 4.150 ca | 1.156 ca | hàng 11 về tỷ lệ mắc {{QĐ1514 tr.PDF 371}} |\n| Y5 (TP.HCM 2014) | 6,0/100000 | — | hàng 8 ở nữ TP.HCM {{Y5 tr.40}} |\n\n> [!warn] Mâu thuẫn số liệu Việt Nam\n> - Y5 ghi **4177 ca, hàng 8**; QĐ1514 ghi **4.150 ca, 1.156 tử vong, hàng 11** (cùng là Globocan 2018). Ghi cả hai nguồn, không coi một con số là chuẩn tuyệt đối {{Y5 tr.40}} {{QĐ1514 tr.PDF 371}}\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Estrogen không đối kháng\n- Liệu pháp estrogen toàn thân (uống, dán, đặt âm đạo) **không kèm progestin**: OR tăng sản ==8,4== (liều trung bình đến cao, 1 năm), ==10,7==; liều thấp 18–24 tháng OR 2,4 {{Y5 tr.41}}\n- Nguy cơ tuyệt đối khoảng 1/1000 phụ nữ, có thể lên 1/100 khi dùng estrogen không đối kháng {{Y5 tr.41}}\n- Estrogen âm đạo liều thấp: ít hấp thu toàn thân, hầu như không bất lợi cho nội mạc {{Y5 tr.41–42}}\n- **Tamoxifen**: đồng vận estrogen ở nội mạc phụ nữ đã mãn kinh, tăng nguy cơ tùy liều và thời gian; nguy cơ ở tiền mãn kinh chưa rõ; không có khuyến cáo tầm soát định kỳ {{Y5 tr.42}}\n- Không rụng trứng kéo dài (tiền mãn kinh, hội chứng buồng trứng đa nang): estrogen nội sinh không đối kháng {{Y5 tr.42}}\n- Bướu tế bào hạt buồng trứng: 25–50% có tăng sản, 5–10% có ung thư nội mạc {{Y5 tr.43}}\n- Có kinh sớm làm tăng nguy cơ; mãn kinh trễ ít liên quan hơn {{Y5 tr.43}}\n@@tab Chuyển hóa – thể trạng\n- **Béo phì**: mô mỡ chuyển androstenedione thành estrone và androgen thành estradiol (aromatase); kháng insulin {{Y5 tr.42}}\n- OR theo BMI, kiểu I: thừa cân (BMI 25–<30) 1,5; béo phì độ 1 (30–<35) 2,5; độ 2 (35–39,9) 4,5; độ 3 (≥40) ==7,1== {{Y5 tr.42–43}}\n- Kiểu II cũng tăng theo béo phì nhưng yếu hơn: OR 1,2 / 1,7 / 2,2 / 3,1 {{Y5 tr.43}}\n- Đái tháo đường và tăng huyết áp: tăng nguy cơ, chủ yếu qua béo phì; một vài nghiên cứu cho thấy là yếu tố độc lập {{Y5 tr.44}}\n- Hút thuốc lá: giảm nguy cơ ở phụ nữ mãn kinh, **không** giảm ở người còn kinh; hại do thuốc lá lớn hơn nhiều so với lợi ích {{Y5 tr.45}}\n- Đậu nành: phân tích gộp quan sát OR 0,70; một thử nghiệm isoflavone 150 mg/ngày trong 5 năm ghi tăng sản 3,8% so với 0% (chưa đủ kết luận) {{Y5 tr.44}}\n@@tab Di truyền – gia đình\n- **Hội chứng Lynch**: nguy cơ trọn đời đến ==70%==; chỉ chiếm 2–5% phụ nữ UNMTC; tuổi chẩn đoán 46–54 (dân số chung 61) {{Y5 tr.43}}\n- Hội chứng Cowden (đột biến PTEN): nguy cơ trọn đời 13–19% {{Y5 tr.43}}\n- Quan hệ gia đình cấp 1: RR 1,82 (95% CI 1,65–1,98); nguy cơ tích lũy đến tuổi 70 là 3,1% so với dưới 2% {{Y5 tr.43}}\n- Đột biến BRCA: nguy cơ không rõ hoặc tăng ít; phần lớn có thể do tamoxifen dùng dự phòng hoặc điều trị ung thư vú {{Y5 tr.43}}\n- Tiền sử gia đình ung thư buồng trứng, đại trực tràng, Lynch II, nội mạc và vú cũng làm tăng nguy cơ {{QĐ1514 tr.PDF 371}}\n- Tiền căn ung thư vú (do điều trị tamoxifen, chung yếu tố béo phì hoặc di truyền Cowden) {{Y5 tr.44}}\n@@tab Yếu tố bảo vệ\n- **Thuốc ngừa thai uống phối hợp** estrogen–progestin: giảm 30–40% nguy cơ trong nghiên cứu dịch tễ lớn; lợi ích kéo dài nhiều năm sau khi ngưng {{Y5 tr.44}}\n- Progestin đơn thuần (medroxyprogesterone acetate tác dụng kéo dài, cấy dưới da, dụng cụ tử cung phóng thích progestin): lợi ích bảo vệ mạnh hơn {{Y5 tr.44}}\n- Có thai và sinh nhiều lần: nguy cơ tỉ lệ nghịch với số lần sinh (vai trò progesterone trong thai kỳ) {{Y5 tr.44}}\n- **Cho con bú**: giảm 11% nguy cơ (OR 0,8) so với có con nhưng không cho bú {{Y5 tr.45}}\n- Hoạt động thể chất tăng: giảm nguy cơ; uống cà phê, trà: có giảm nguy cơ {{Y5 tr.45}}\n@@end\n\n### Sinh bệnh học & sinh học phân tử\n- **Kiểu I** (liên quan estrogen, khoảng 80%): carcinôm dạng nội mạc grad 1–2, thường xuất hiện trên nền tăng sản không điển hình; tiên lượng tốt {{Y5 tr.41}}\n- **Kiểu II** (không liên quan nội tiết, khoảng 20%): thường trên nội mạc teo, grad 3 hoặc dạng không phải nội mạc; tiên lượng xấu hơn kiểu I {{Y5 tr.41}}\n- Progesterone từ tuyến thượng thận rất thấp (dưới 0,05 ng/mL) và giảm theo tuổi, làm tăng nguy cơ ở người lớn tuổi {{Y5 tr.41}}\n- Nền tảng: [[ung-thu-nguyen-nhan]], [[ung-thu-co-che-sinh-ung]]\n\n### Giải phẫu bệnh – phân loại\n@@tabs\n@@tab Tiền ung thư\n- Tăng sản dạng nang: lành tính, không có tiềm năng ác tính; hiếm thấy hình ảnh phân bào {{Y5 tr.45}}\n- Tăng sản tuyến ± không điển hình (nhẹ, vừa, nặng): tăng sản không điển hình **nặng** diễn tiến thành ung thư ở ==25%== các trường hợp {{Y5 tr.45}}\n- Tăng sản không điển hình là tổn thương nền của kiểu I {{Y5 tr.41}}\n@@tab Carcinôm nội mạc\n- Carcinôm tuyến dạng nội mạc: trên 95% theo Y5; QĐ1514 ghi 90% ung thư thân tử cung (xem lưu ý mục 3) {{Y5 tr.45}} {{QĐ1514 tr.PDF 371}}\n- Thường kèm vùng chuyển sản lành, nhất là chuyển sản gai {{Y5 tr.45}}\n- Độ mô học: ==grad 1== biệt hóa tốt (dưới 5% không gai hoặc không tạo tuyến); ==grad 2== trung bình (6–50%); ==grad 3== kém (trên 50%) {{Y5 tr.45}}\n- Đa số biệt hóa tốt đến trung bình (grad 1–2), tiên lượng tốt {{Y5 tr.45}}\n@@tab Thể khác\n- Nhú thanh dịch, tế bào sáng, nhầy, tế bào vảy, không biệt hóa, thần kinh nội tiết: xâm lấn mạnh, di căn nhiều hơn, tiên lượng xấu hơn carcinôm nội mạc {{Y5 tr.46}} {{QĐ1514 tr.PDF 372}}\n- Dạng hỗn hợp: có từ 2 loại giải phẫu bệnh trở lên, mỗi loại chiếm ít nhất 10% {{Y5 tr.46}}\n- Sarcôm tử cung chiếm 3% ung thư thân tử cung (sarcôm cơ trơn, sarcôm mô đệm nội mạc, bướu hỗn hợp trung mô–biểu mô) {{Y5 tr.46}}\n@@end\n\n### Diễn tiến tự nhiên – lan tràn\n- **Tại chỗ lâu dài**: lớp cơ tử cung dày là rào cản tự nhiên; khi xâm lấn qua màng đáy vào cơ thì vào mạch bạch huyết, mạch máu rồi di căn hạch, xa {{Y5 tr.46}} {{SY5 tr.7}}\n- Xâm lấn trực tiếp vùng chậu: buồng trứng, vòi trứng, cổ tử cung (làm tăng di căn hạch), âm đạo, chu cung, bàng quang, trực tràng {{Y5 tr.46}}\n- Gieo rắc ổ bụng: ung thư ăn thủng cơ tử cung rơi vào phúc mạc, hoặc lan theo vòi trứng {{Y5 tr.46}}\n- Di căn hạch tỉ lệ thấp, đặc biệt ở giai đoạn sớm và carcinôm grad 1–2; hạch chậu, chậu trong, cạnh động mạch chủ; đáy tử cung có thể di căn thẳng đến hạch cạnh động mạch chủ {{Y5 tr.46}}\n- Di căn xa ít: phổi, gan, xương, não; QĐ1514 thêm hạch bẹn, hạch thượng đòn, âm đạo {{Y5 tr.46}} {{QĐ1514 tr.PDF 372}}\n- Nền tảng: [[ung-thu-xam-lan-di-can]]\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Triệu chứng chính: ==ra máu âm đạo bất thường== (chiếm tới 90%); **mọi phụ nữ đã mãn kinh có chảy máu âm đạo cần khám phụ khoa kỹ** {{QĐ1514 tr.PDF 371}}\n> - Chưa mãn kinh: kinh kéo dài, ra máu nhiều hơn bình thường, ra máu giữa kỳ kinh → **sinh thiết nội mạc tử cung**; phụ nữ đang dùng tamoxifen có ra máu âm đạo cũng cần sinh thiết {{QĐ1514 tr.PDF 371}}\n\n### Triệu chứng cơ năng & hoàn cảnh phát hiện\n- Điển hình: lượng ít, rỉ rả, máu đỏ sậm, không đông (máu cũ đọng trong lòng tử cung); đôi khi ra nhiều máu đỏ tươi và có cục máu đông {{Y5 tr.46}}\n- Kèm theo: ra dịch âm đạo (huyết trắng); đau hạ vị hoặc đau lưng do thân tử cung xơ hóa hoặc thâm nhiễm thần kinh quanh tử cung {{Y5 tr.46}}\n- Muộn: tử cung to, gồ ghề, có thể ứ dịch hoặc ứ mủ trong lòng tử cung {{Y5 tr.46}}\n- Muộn: đau bụng dưới (đôi khi, thường gặp ở giai đoạn muộn hơn) {{QĐ1514 tr.PDF 371}}\n- Rất muộn: tắc ruột, vàng da, dịch ổ bụng {{QĐ1514 tr.PDF 371}}\n- Nền tảng: [[ung-thu-bay-trieu-chung]]\n\n### Hỏi bệnh – khám\n- Hỏi bệnh sử kỹ: chu kỳ kinh, thuốc ngừa thai, bệnh nội khoa (tiểu đường, cao huyết áp); tiền sử gia đình ung thư nội mạc, đại tràng, vú, buồng trứng {{Y5 tr.47}}\n- Khám phụ khoa bằng mỏ vịt và bằng tay, lưu ý mọi bất thường; giai đoạn sớm đa phần không thấy bất thường; tử cung to ra hoặc bớt di động là giai đoạn trễ {{Y5 tr.47}}\n- Khám hạch bẹn và hạch trên đòn; khám toàn thân tìm bệnh kèm theo và di căn xa {{Y5 tr.47}}\n\n> [!red] Dấu hiệu báo động\n> - Ra máu âm đạo bất thường ở phụ nữ **đã mãn kinh** → khám phụ khoa kỹ và sinh thiết {{QĐ1514 tr.PDF 371}}\n> - Tử cung to, gồ ghề, bớt di động, ứ dịch hoặc ứ mủ lòng tử cung → giai đoạn trễ {{Y5 tr.46}} {{Y5 tr.47}}\n> - Hạch bẹn, hạch thượng đòn; đau bụng dưới, tắc ruột, vàng da, dịch ổ bụng (muộn) {{Y5 tr.47}} {{QĐ1514 tr.PDF 371}}\n\n### Phát hiện sớm – nhóm nguy cơ\n- Chưa có chương trình tầm soát đại trà; nhóm nguy cơ nên siêu âm định kỳ đánh giá độ dày nội mạc, và nạo sinh thiết khi nghi ngờ trên siêu âm {{Y5 tr.47}}\n- Nhóm cần theo dõi: béo phì, tăng huyết áp, tiểu đường đã mãn kinh, estrogen ngoại sinh kéo dài, tiền căn gia đình, mãn kinh trễ, chu kỳ không rụng trứng kéo dài {{Y5 tr.47}}\n- Ngưỡng độ dày nội mạc (mm) và tuổi bắt đầu tầm soát: **tài liệu không nêu**\n\n### Tiếp cận các triệu chứng (khung 128 vấn đề)\n\n| STT | Vấn đề | Nguyên nhân cần nghĩ |\n|---|---|---|\n| [87](#/khung/87) | **Xuất huyết âm đạo-tử cung bất thường** | ác tính (UNMTC, sarcôm thân tử cung); tăng sản nội mạc; polyp nội mạc, polyp cổ tử cung; u xơ cơ tử cung; rối loạn phóng noãn (hội chứng buồng trứng đa nang, tăng prolactin); rối loạn đông máu; viêm nội mạc, cổ tử cung, âm đạo; nội tiết ngoại sinh; bướu tiết estrogen của buồng trứng {{128VĐ mục 91}} {{128VĐ mục 92}} {{Y5 tr.43}} |\n| [89](#/khung/89) | **Tiết dịch âm đạo bất thường** | ra dịch (huyết trắng) đi kèm UNMTC {{Y5 tr.46}}; viêm nhiễm âm đạo, cổ tử cung {{128VĐ mục 91}} |\n| [91](#/khung/91) | **Khối vùng chậu** | tử cung to, gồ ghề, ứ dịch hoặc ứ mủ lòng tử cung {{Y5 tr.46}}; bướu buồng trứng có thể gây xuất huyết âm đạo bất thường {{Y5 tr.47}} |\n\nNền tảng: [[ung-thu-tiep-can-chan-doan]]\n\n## 5. Cận lâm sàng\n\n> [!key] Tóm tắt\n> - ==Nạo/sinh thiết lòng tử cung== là xét nghiệm quyết định chẩn đoán {{Y5 tr.48}}\n> - Siêu âm đầu dò âm đạo và **MRI** đánh giá xâm lấn tại chỗ và vùng chậu; CT, X-quang, xạ hình xương, PET/CT khi nghi di căn {{Y5 tr.47}} {{QĐ1514 tr.PDF 372}}\n> - Phân giai đoạn **sau phẫu thuật**: FIGO 2018 (Y5) hoặc AJCC 8 (QĐ1514) {{Y5 tr.48}} {{QĐ1514 tr.PDF 372}}\n\n### Chẩn đoán hình ảnh\n@@tabs\n@@tab Siêu âm – MRI\n- Siêu âm bụng: kích thước tử cung, độ dày nội mạc, ứ dịch lòng tử cung, khối vùng chậu, di căn gan, thận ứ nước do chèn ép niệu quản {{Y5 tr.47}}\n- Siêu âm đầu dò qua âm đạo: đánh giá xâm lấn quanh u chính xác hơn {{Y5 tr.47}}\n- **MRI**: phương tiện tốt nhất đánh giá mức độ xâm lấn tại chỗ và vùng chậu; CT/MRI khi bệnh tiến xa để đánh giá bàng quang, trực tràng, hạch chậu, hạch cạnh động mạch chủ {{Y5 tr.47}}\n- Soi bàng quang, soi trực tràng khi nghi xâm lấn {{Y5 tr.47}}\n- QĐ1514: chụp buồng tử cung–vòi trứng (hiện ít làm); nội soi buồng tử cung kết hợp sinh thiết {{QĐ1514 tr.PDF 371}}\n@@tab Đánh giá di căn & xét nghiệm khác\n- Nghi di căn xa: X-quang phổi, xạ hình xương, PET/CT {{Y5 tr.47}}\n- QĐ1514: CT/MRI ổ bụng–tiểu khung; xạ hình xương SPECT/CT 99mTc-MDP; xạ hình thận SPECT/CT 99mTc-DTPA; PET/CT 18F-FDG trước và sau điều trị; MRI sọ nếu nghi di căn não {{QĐ1514 tr.PDF 371–372}}\n- Công thức máu, chức năng gan–thận, đường huyết {{Y5 tr.48}}\n- QĐ1514: xét nghiệm đột biến/giải trình tự nhiều gen (xem phần dấu ấn)\n@@end\n\n### Giải phẫu bệnh – sinh thiết\n- **Nạo sinh thiết lòng tử cung** là xét nghiệm quan trọng nhất: nong cổ tử cung, nạo kênh tử cung, đo lòng tử cung và sinh thiết mọi vị trí; nạo lại nếu nghi ngờ; thủ thuật đau nhiều nên cần giảm đau đúng mức {{Y5 tr.48}}\n- Nội soi buồng tử cung kết hợp sinh thiết; nạo hoặc hút buồng tử cung lấy bệnh phẩm làm tế bào học và giải phẫu bệnh {{QĐ1514 tr.PDF 371}}\n- Mô bệnh học quyết định chẩn đoán, đánh giá độ ác tính, di căn hạch và xâm lấn mạch {{QĐ1514 tr.PDF 372}}\n- Các thể mô học (QĐ1514): ung thư biểu mô tuyến nội mạc; nhú thanh dịch; tế bào sáng; nhầy; tế bào vảy {{QĐ1514 tr.PDF 372}}\n- **ER và PR** làm kèm để chọn điều trị nội tiết về sau {{QĐ1514 tr.PDF 372}}\n- Nền tảng: [[ung-thu-giai-phau-benh]]\n\n### Dấu ấn & gen\n- **CA 125**: có thể tăng nhưng **không giúp chẩn đoán**; dùng để theo dõi {{Y5 tr.48}}\n- QĐ1514: CEA, \"CA 12-5\", CA 15-3 tăng trong một số trường hợp; có giá trị theo dõi đáp ứng, phát hiện tái phát và di căn {{QĐ1514 tr.PDF 372}}\n- Gen (QĐ1514): MLH1, MSH2, MSH6, PMS2, EPCAM, PTEN, TP53, STK11, và giải trình tự nhiều gen {{QĐ1514 tr.PDF 372}}\n\n> [!warn] Mâu thuẫn về dấu ấn\n> - Y5: CA 125 không dùng để chẩn đoán, chỉ theo dõi {{Y5 tr.48}}\n> - QĐ1514 liệt kê \"CA 12-5\" có giá trị theo dõi; có thể là lỗi chép của CA 125, cần đối chiếu bản gốc {{Y5 tr.48}} {{QĐ1514 tr.PDF 372}}\n\n### Phân giai đoạn\n- Đánh giá chính xác nhất **sau phẫu thuật** và sau khi thực hiện đủ các bước xếp giai đoạn {{Y5 tr.48}}\n- QĐ1514: đánh giá giai đoạn sớm theo độ sâu xâm lấn lớp cơ tử cung; dùng AJCC 2017 (bảng 1 và 2) {{QĐ1514 tr.PDF 372–373}}\n\nBảng FIGO 2018 (Y5):\n\n| Giai đoạn | Nội dung (Y5) |\n|---|---|\n| I | Khu trú thân tử cung. **IA**: khu trú ở nội mạc hoặc xâm lấn không quá ½ cơ; **IB**: xâm lấn quá ½ cơ |\n| II | Lan đến mô đệm cổ tử cung nhưng chưa vượt tử cung (chỉ lan tuyến cổ trong vẫn là I) |\n| III | **IIIA** xâm lấn thanh mạc và/hoặc phần phụ; **IIIB** xâm lấn âm đạo và/hoặc chu cung; **IIIC1** di căn hạch chậu; **IIIC2** di căn hạch cạnh động mạch chủ ± hạch chậu |\n| IV | **IVA** xâm lấn niêm mạc bàng quang hoặc trực tràng; **IVB** di căn xa, gồm hạch trong ổ bụng hoặc hạch bẹn |\n\n{{Y5 tr.48–49}} Tế bào học dịch ổ bụng dương tính được ghi riêng và **không đổi giai đoạn** {{Y5 tr.48}}\n\nBảng AJCC 8 (QĐ1514, bảng 2):\n\n| Giai đoạn | T | N | M |\n|---|---|---|---|\n| I / IA / IB | T1 / T1a / T1b | N0 | M0 |\n| II | T2 | N0 | M0 |\n| III / IIIA / IIIB | T3 / T3a / T3b | N0 | M0 |\n| IIIC1 / IIIC2 | T1–3 | N1 / N2 | M0 |\n| IVA | T4 | bất kỳ | M0 |\n| IVB | bất kỳ | bất kỳ | M1 |\n\n{{QĐ1514 tr.PDF 374}}\n\n- N theo QĐ1514: N0(+) tế bào u tách biệt ở hạch ≤0,2 cm; N1mi hạch chậu >0,2–≤2 cm; N1a hạch chậu >2 cm; N2mi/N2a hạch cạnh động mạch chủ tương ứng {{QĐ1514 tr.PDF 373}}\n- M1 theo QĐ1514 (IVB): di căn hạch bẹn, phúc mạc; **không** tính di căn hạch chủ bụng, âm đạo, phần phụ hoặc phúc mạc tiểu khung {{QĐ1514 tr.PDF 373}}\n\n> [!warn] Mâu thuẫn về IVB\n> - Y5: IVB gồm di căn xa, **kể cả** hạch trong ổ bụng hoặc hạch bẹn {{Y5 tr.48}}\n> - QĐ1514 (AJCC 8): M1 không tính hạch chủ bụng; hạch bẹn và phúc mạc được tính {{QĐ1514 tr.PDF 373}}\n> - Ghi cả hai hệ thống; khi làm bài, theo đúng hệ thống mà đề nêu\n\nPhân nhóm nguy cơ (Y5; LVSI = xâm lấn mạch máu–bạch huyết) {{Y5 tr.50–51}}:\n\n| Nhóm | Tiêu chí |\n|---|---|\n| Thấp | Giai đoạn I, grad 1–2, xâm lấn không quá ½ cơ, không LVSI |\n| Trung bình | Giai đoạn I, grad 1–2, xâm lấn trên ½ cơ, không LVSI |\n| Trung bình–cao | Giai đoạn I grad 3 xâm lấn không quá ½ cơ (bất kể LVSI), **hoặc** grad 1–2 có LVSI (bất kể độ sâu) |\n| Cao | Giai đoạn I grad 3 xâm lấn trên ½ cơ (bất kể LVSI); **hoặc** giai đoạn II; **hoặc** giai đoạn III sau phẫu trị không còn mô bướu; **hoặc** giải phẫu bệnh không phải dạng nội mạc (nhú thanh dịch, tế bào sáng, không biệt hóa, carcinosarcoma) |\n| Tiến xa tại chỗ–vùng | Giai đoạn III còn mô bướu sau mổ, **hoặc** IVA |\n| Di căn | IVB |\n\n- Nền tảng: [[ung-thu-phan-giai-doan-tnm]]\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Chẩn đoán xác định UNMTC\n> - Ra máu âm đạo bất thường + **mô bệnh học** có ung thư biểu mô tuyến nội mạc (nạo hoặc sinh thiết lòng tử cung) {{QĐ1514 tr.PDF 372}} {{Y5 tr.48}}\n> - Chẩn đoán đầy đủ: mô học + giai đoạn phẫu thuật + nhóm nguy cơ + ER/PR {{Y5 tr.50–51}} {{QĐ1514 tr.PDF 372}}\n> - Xuất huyết tử cung chức năng: phải tìm và **loại trừ ác tính** (ung thư nội mạc, tăng sản) trước khi kết luận {{128VĐ mục 92}}\n\n### Chẩn đoán phân biệt xuất huyết âm đạo – tử cung bất thường\n| Nhóm nguyên nhân | Bệnh cần nghĩ tới | Điểm từ nguồn |\n|---|---|---|\n| **M** – ác tính, tăng sản | UNMTC; sarcôm thân tử cung; tăng sản nội mạc | tăng sản không điển hình nặng → ung thư ở 25% {{Y5 tr.45}} {{128VĐ mục 92}} |\n| **P** – polyp | polyp nội mạc; polyp cổ tử cung (bướu lành) | mồng gà, polyp cổ tử cung là bướu lành {{128VĐ mục 91}} |\n| **L** – u cơ trơn | u xơ cơ tử cung (bướu lành cơ trơn) | {{128VĐ mục 91}} |\n| **A** – adenomyosis | adenomyosis | chi tiết: tài liệu không nêu {{128VĐ mục 92}} |\n| **O** – rối loạn phóng noãn | hội chứng buồng trứng đa nang; tăng prolactin máu; rối loạn trục hạ đồi–tuyến yên–buồng trứng | chẩn đoán thường là loại trừ, hay gặp ở tuổi tiền mãn kinh {{128VĐ mục 92}} |\n| **C** – rối loạn đông máu | rối loạn đông máu | {{128VĐ mục 92}} |\n| **E** – nội mạc, viêm | viêm nội mạc tử cung, cổ tử cung, âm đạo, âm hộ | {{128VĐ mục 91}} |\n| **I** – do nội tiết/điều trị | nội tiết ngoại sinh; tamoxifen | tamoxifen tăng nguy cơ ở phụ nữ đã mãn kinh {{Y5 tr.42}} {{128VĐ mục 91}} |\n| Ngoài tử cung | bướu tế bào hạt buồng trứng; khối buồng trứng | 25–50% có tăng sản, 5–10% có ung thư nội mạc {{Y5 tr.43}} |\n| Ung thư lân cận | sarcôm thân tử cung; ung thư cổ tử cung, âm đạo, âm hộ | {{128VĐ mục 91}} |\n\nGhi chú: Y5 ghi \"chẩn đoán phân biệt\" không có bảng riêng; bảng trên tổng hợp từ 128VĐ mục 91–92 (phân loại PALM-COEIN) và Y5.\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n\n> [!key] Mục tiêu theo giai đoạn\n> - Đa số chẩn đoán ở giai đoạn còn khu trú ở thân tử cung: **phẫu thuật** là chính, xạ trị bổ trợ theo nguy cơ {{QĐ1514 tr.PDF 374}} {{Y5 tr.51}}\n> - Tiến xa, tái phát hoặc di căn: hóa trị, nội tiết, điều trị đích, miễn dịch; chọn theo thụ thể ER/PR và grad {{Y5 tr.53}} {{QĐ1514 tr.PDF 377}}\n> - Tiên lượng phụ thuộc giai đoạn: khối u càng nhỏ, chưa di căn hạch thì khả năng khỏi càng cao {{QĐ1514 tr.PDF 377}}\n\n### 7.2 Các phương pháp\n\n@@tabs\n@@tab Phẫu thuật\n- Phẫu thuật tiêu chuẩn theo Y5: cắt tử cung toàn bộ + hai phần phụ ± nạo hạch chậu hai bên {{Y5 tr.51}}\n- QĐ1514 ghi: cắt tử cung toàn bộ, vòi–buồng trứng hai bên, vét hạch chậu và hạch cạnh động mạch chủ {{QĐ1514 tr.PDF 374}}\n- Phẫu thuật vừa đánh giá giai đoạn vừa là điều trị ban đầu; khi vào ổ bụng phải thám sát kỹ {{Y5 tr.51}}\n- Tiến xa: cố gắng mổ nếu lấy hết được mô bướu trên đại thể, sau đó hóa trị và xạ trị; không lấy hết thì hóa trị và xạ trị {{Y5 tr.53}}\n@@tab Xạ trị\n- Xạ trị đơn thuần (xạ ngoài kết hợp áp sát) cho giai đoạn I, II, III còn khu trú tại chỗ–tại vùng {{Y5 tr.51}}\n- Xạ bổ túc sau mổ giúp giảm tái phát và tăng sống còn {{Y5 tr.51}}\n- Chiếu ngoài: bổ trợ sau mổ với ung thư xâm lấn tiểu khung ± di căn hạch vùng {{QĐ1514 tr.PDF 374}}\n- Áp sát: vào diện u khi không phẫu thuật triệt căn hoặc tăng liều sau chiếu ngoài {{QĐ1514 tr.PDF 375}}\n- Kỹ thuật: 3D, IMRT, VMAT, hạt nặng; xạ phẫu (dao gamma, CyberKnife) cho di căn ít ổ, đặc biệt di căn não {{QĐ1514 tr.PDF 375}}\n- Liều xạ (Gy), số phân liều: **tài liệu không nêu**\n@@tab Hóa trị\n- Giai đoạn tiến xa không có thụ thể nội tiết: đa hóa trị dựa trên Adriamycin và cisplatin {{Y5 tr.51}}\n- Giai đoạn tiến triển và di căn xa: hóa trị (điều trị hệ thống gồm hóa trị, đích và nội tiết) {{QĐ1514 tr.PDF 374}}\n- Phác đồ chi tiết: xem mục 7.3\n@@tab Nội tiết\n- Khoảng 33% bệnh nhân tiến xa hoặc tái phát đáp ứng nội tiết; tamoxifen đáp ứng 20–30% {{Y5 tr.51}}\n- Progestin thường dùng: medroxyprogesterone acetate, hydroxyprogesterone caproate, megestrol acetate {{Y5 tr.51}}\n- Yếu tố dự đoán đáp ứng: mật độ thụ thể ER/PR, mức biệt hóa, thời gian không bệnh; các nghiên cứu chưa thống nhất liều và thời gian {{QĐ1514 tr.PDF 377}}\n- Chỉ định theo Y5: thụ thể nội tiết dương tính và grad thấp → điều trị nội tiết {{Y5 tr.53}}\n@@tab Đích – miễn dịch\n- Bevacizumab kết hợp hóa chất: đang nghiên cứu, thử nghiệm bước đầu hứa hẹn {{QĐ1514 tr.PDF 377}}\n- Pembrolizumab kết hợp lenvatinib: tiến xa, MSI-H hoặc dMMR, đã điều trị toàn thân trước đó, không có chỉ định phẫu thuật hoặc xạ trị {{QĐ1514 tr.PDF 377}}\n- Y5 không nêu điều trị đích và miễn dịch: **tài liệu không nêu**\n@@tab Theo giai đoạn\n@@tabs\n@@tab Giai đoạn I\n- Phẫu thuật; xạ bổ trợ (áp sát và/hoặc chiếu ngoài) khi có yếu tố xấu: mô học độ 2 hoặc 3, hoặc u xâm lấn ≥50% cơ tử cung {{QĐ1514 tr.PDF 374}}\n- Bảng theo nguy cơ (Y5, ESMO–ESGO–ESTRO): xem bảng dưới {{Y5 tr.52}}\n@@tab Giai đoạn II\n- Phẫu thuật, sau đó xạ áp sát và/hoặc chiếu ngoài {{QĐ1514 tr.PDF 374}}\n- Độ mô học 3: cân nhắc hóa trị bổ trợ {{QĐ1514 tr.PDF 374}}\n@@tab III – IV tiến xa\n- Hệ thống: hóa trị, điều trị đích và nội tiết, có hoặc không kết hợp xạ chiếu ngoài và xạ áp sát {{QĐ1514 tr.PDF 374}}\n- Y5 tr.51: tiến xa tại chỗ–vùng gồm giai đoạn III sau mổ còn bướu và IVA. Y5 tr.52: giai đoạn III sau mổ không còn bướu, phối hợp hóa trị + xạ tốt hơn đơn lẻ {{Y5 tr.51}} {{Y5 tr.52}}\n@@tab Tái phát – di căn\n- Y5: thụ thể nội tiết dương tính và grad thấp → nội tiết; thụ thể âm tính và grad cao → hóa trị {{Y5 tr.53}}\n- Y5: tái phát chủ yếu tại chỗ–vùng chậu ở giai đoạn I–II; ngoài vùng chậu và di căn xa ở giai đoạn III–IV {{Y5 tr.53}}\n@@end\n@@end\n\nBổ túc theo nguy cơ (Y5 Bảng 1, ESMO–ESGO–ESTRO) {{Y5 tr.52}}:\n\n| Nhóm nguy cơ | Đề nghị bổ túc |\n|---|---|\n| Thấp | Không điều trị thêm |\n| Trung bình | Xạ áp sát vào diện cắt âm đạo, hoặc không điều trị thêm (dưới 60 tuổi) |\n| Trung bình–cao, mổ có nạo hạch, hạch âm tính | Xạ áp sát vào diện cắt âm đạo, hoặc không điều trị thêm |\n| Trung bình–cao, mổ không nạo hạch | Xạ ngoài nếu có xâm lấn mạch–bạch huyết; xạ áp sát nếu không có |\n| Cao (giai đoạn I grad 3 xâm lấn trên ½ cơ, hoặc có LVSI) | Mổ có nạo hạch, hạch âm tính: xạ ngoài, xạ áp sát là lựa chọn thay thế; mổ không nạo: xạ ngoài hoặc hóa–xạ đồng thời |\n| Giai đoạn II | Mổ có nạo hạch, hạch âm tính: xạ áp sát vào diện cắt âm đạo, hoặc xạ ngoài trường chiếu nhỏ |\n| Giai đoạn III sau mổ không còn mô bướu | Hóa trị + xạ ngoài (IIIA, IIIB, IIIC1); IIIC2 hóa trị + xạ ngoài trường mở rộng |\n\n> [!warn] Khác nhau về nhóm nguy cơ giai đoạn I\n> - Y5: grad 1–2 xâm lấn trên ½ cơ (không LVSI) là nguy cơ trung bình; grad 3 xâm lấn không quá ½ cơ là trung bình–cao; grad 3 xâm lấn trên ½ cơ là cao {{Y5 tr.50}}\n> - QĐ1514: giai đoạn I cần xạ bổ trợ khi độ mô học 2 hoặc 3, hoặc xâm lấn ≥50% cơ — tiêu chí khác Y5 {{QĐ1514 tr.PDF 374}}\n> - Ghi cả hai; khi làm bài, theo nguồn đề nêu\n\n### 7.3 Phác đồ – Y lệnh\n\n> [!doc] QĐ 1514/QĐ-BYT (ngày 1/4/2020), Bài 45 \"Ung thư nội mạc tử cung\", tr. PDF 375–377. Chép theo nguồn, không tự thêm liều. Chu kỳ ghi theo nguồn; \"tài liệu không nêu\" khi nguồn không có. {{QĐ1514 tr.PDF 375–377}}\n\n| Phác đồ | Thuốc – liều | Chu kỳ | Ghi chú |\n|---|---|---|---|\n| **Carboplatin – paclitaxel** | Paclitaxel 175 mg/m² TM ngày 1; carboplatin AUC 5–6 TM ngày 1 | 21 ngày | Nhóm \"các phác đồ thường sử dụng\" (mục 3.3.2); nguồn không ghi chỉ định riêng {{QĐ1514 tr.PDF 375}} |\n| **Cisplatin – doxorubicin** | Doxorubicin 60 mg/m² TM ngày 1; cisplatin 50 mg/m² TM ngày 1 | 21 ngày | {{QĐ1514 tr.PDF 375}} |\n| **Cisplatin – doxorubicin – paclitaxel** | Doxorubicin 45 mg/m² ngày 1; cisplatin 50 mg/m² ngày 1; paclitaxel 160 mg/m² ngày 2 | 21 ngày | {{QĐ1514 tr.PDF 375}} |\n| **Carboplatin – docetaxel** | Docetaxel 60–75 mg/m² ngày 1; carboplatin AUC 5–6 ngày 1 | 21 ngày | {{QĐ1514 tr.PDF 376}} |\n| **Ifosfamide – paclitaxel** | Paclitaxel 135 mg/m² ngày 1; ifosfamide 1,6 g/m² ngày 1–3 | 21 ngày | {{QĐ1514 tr.PDF 376}} |\n| **Cisplatin – ifosfamide** | Cisplatin 20 mg/m² ngày 1–4; ifosfamide 1,5 g/m² ngày 1–4; mesna 120 mg/m² bolus và 1,5 g/m² truyền ngày 1–5 | 21 ngày | {{QĐ1514 tr.PDF 376}} |\n| **Carboplatin – paclitaxel – bevacizumab** | Paclitaxel 175 mg/m² ngày 1; carboplatin AUC 5 ngày 1; bevacizumab 15 mg/kg ngày 1 | tài liệu không nêu | {{QĐ1514 tr.PDF 376}} |\n| **Everolimus – letrozole** | Everolimus 10 mg/ngày uống; letrozole 2,5 mg/ngày uống | tài liệu không nêu | {{QĐ1514 tr.PDF 376}} |\n| Cisplatin đơn chất | 50 mg/m² TM ngày 1 | 21 ngày | {{QĐ1514 tr.PDF 376}} |\n| Carboplatin đơn chất | 400 mg/m² TM ngày 1 | 21 ngày | {{QĐ1514 tr.PDF 376}} |\n| Doxorubicin; doxorubicin liposomal | 60 mg/m² ngày 1; 50 mg/m² ngày 1 | 28 ngày | {{QĐ1514 tr.PDF 376}} |\n| Paclitaxel đơn chất | 110–200 mg/m² TM ngày 1 | 21 ngày | {{QĐ1514 tr.PDF 376}} |\n| Topotecan | 1,5 mg/m² TM ngày 1–5 | 21 ngày | {{QĐ1514 tr.PDF 376}} |\n| Docetaxel đơn chất | 36 mg/m² TM ngày 1, 8, 15 | 28 ngày | {{QĐ1514 tr.PDF 376}} |\n| Ifosfamide đơn chất | 2 g/m² TM ngày 1–3, kèm mesna tổng 2 g chia 4 lần | 21 ngày | {{QĐ1514 tr.PDF 377}} |\n| Gemcitabine đơn chất | 1.000 mg/m² TM ngày 1, 8, 15 | 28 ngày | {{QĐ1514 tr.PDF 377}} |\n| Bevacizumab đơn chất | 15 mg/m² TM ngày 1 | 21 ngày | {{QĐ1514 tr.PDF 376}} |\n| Temsirolimus | 25 mg TM hàng tuần (chữ trích từ PDF bị lỗi ký tự, cần đối chiếu) | hàng tuần | {{QĐ1514 tr.PDF 376}} |\n| **Megestrol xen tamoxifen** | Megestrol acetate 80 mg uống 2 lần/ngày, hàng ngày trong 3 tuần, xen kẽ với tamoxifen 20 mg uống 2 lần/ngày, hàng ngày trong 3 tuần | xen kẽ 3 tuần | {{QĐ1514 tr.PDF 377}} |\n| **Ức chế aromatase (Arimidex)** | 1 mg uống hàng ngày; ung thư nội mạc có thụ thể nội tiết dương | hàng ngày | {{QĐ1514 tr.PDF 377}} |\n| **Fulvestrant** | 500 mg tiêm bắp sâu mỗi 2 tuần trong tháng đầu, sau đó mỗi tháng 1 lần | theo lịch trên | {{QĐ1514 tr.PDF 377}} |\n| **Pembrolizumab + lenvatinib** | Liều: tài liệu không nêu | tài liệu không nêu | Tiến xa, MSI-H hoặc dMMR {{QĐ1514 tr.PDF 377}} |\n| **Bevacizumab + hóa chất** | Liều: tài liệu không nêu | tài liệu không nêu | Đang nghiên cứu {{QĐ1514 tr.PDF 377}} |\n\n> [!warn] Lưu ý phác đồ\n> - Bevacizumab: QĐ1514 ghi **15 mg/kg** trong phối hợp nhưng **15 mg/m²** trong đơn chất, cùng trang 376; nghi lỗi chép, đối chiếu bản gốc {{QĐ1514 tr.PDF 376}}\n> - Temsirolimus: chữ trích lỗi ký tự; liều ghi 25 mg mỗi tuần {{QĐ1514 tr.PDF 376}}\n> - Y5 chỉ nêu Adriamycin và cisplatin; liều xạ (Gy), độc tính và tác dụng phụ của thuốc: **tài liệu không nêu** trong hai nguồn\n- Nền tảng: [[ung-thu-mien-dich-tri-lieu]]\n\n## 8. Tiên lượng – Dự phòng\n\n> [!key] Tóm tắt\n> - Yếu tố tiên lượng chủ yếu là giai đoạn {{QĐ1514 tr.PDF 377}}; kèm grad, loại mô học và xâm lấn mạch {{Y5 tr.50}}; ER/PR dự đoán đáp ứng nội tiết {{QĐ1514 tr.PDF 377}}\n> - Nhóm nguy cơ cao: theo dõi sát và xạ bổ trợ theo nguồn {{Y5 tr.50–51}} {{QĐ1514 tr.PDF 374}}\n\n### Tiên lượng\n@@tabs\n@@tab Yếu tố tiên lượng\n| Yếu tố | Nội dung |\n|---|---|\n| Giai đoạn | quan trọng nhất; khối u càng nhỏ, chưa di căn hạch thì khả năng khỏi bệnh càng cao {{QĐ1514 tr.PDF 377}} |\n| Độ mô học (grad) | grad 1–2 tốt; grad 3 hoặc loại không phải nội mạc thì xấu hơn {{Y5 tr.45}} {{Y5 tr.50–51}} |\n| Xâm lấn cơ | xâm lấn trên ½ cơ làm tăng nhóm nguy cơ {{Y5 tr.50}} |\n| Xâm lấn mạch–bạch huyết (LVSI) | nâng nhóm nguy cơ {{Y5 tr.50}} |\n| Thụ thể ER/PR | cùng với grad và thời gian không bệnh, quyết định đáp ứng nội tiết {{QĐ1514 tr.PDF 377}} |\n| Tuổi | tài liệu không nêu |\n@@tab Sống 5 năm theo giai đoạn\nBảng 2 (Y5): tỉ lệ sống 5 năm theo giai đoạn FIGO {{Y5 tr.53}}\n\n| Giai đoạn | Sống 5 năm |\n|---|---|\n| 0 | 90% |\n| IA | 88% |\n| IB | 75% |\n| II | 69% |\n| IIIA | 58% |\n| IIIB | 50% |\n| IIIC | 47% |\n| IVA | 17% |\n| IVB | 15% |\n\n- QĐ1514 không nêu tỉ lệ sống 5 năm: **tài liệu không nêu** {{QĐ1514 tr.PDF 377}}\n@@end\n\n### Tái phát và theo dõi sau điều trị\n- Đa số tái phát trong 2 năm đầu; vị trí: chỉ vùng chậu 50%, chỉ di căn xa 28%, cả hai 22% {{Y5 tr.53}}\n\n> [!warn] Mâu thuẫn về lịch theo dõi\n> - Y5: 3 tháng/lần trong 2 năm đầu; 6 tháng/lần trong 3 năm kế tiếp; sau 5 năm mỗi năm/lần {{Y5 tr.53}}\n> - QĐ1514: khám lại 3 tháng/lần trong suốt 5 năm sau điều trị, gồm lâm sàng, phụ khoa và cận lâm sàng {{QĐ1514 tr.PDF 377}}\n> - Ghi cả hai; khi làm bài, theo nguồn đề nêu\n\n### Dự phòng\n@@tabs\n@@tab Cấp 1 (phòng bệnh)\n- Tránh các yếu tố nguy cơ; khám sức khỏe định kỳ hoặc khi có bất thường để phát hiện sớm {{QĐ1514 tr.PDF 377}}\n- Thuốc ngừa thai uống phối hợp (giảm 30–40%) hoặc progestin đơn thuần; hạn chế estrogen không đối kháng {{Y5 tr.44}}\n- Cho con bú; vận động thể chất giảm nguy cơ; hút thuốc lá: hại lớn hơn lợi ích {{Y5 tr.45}}\n- Tamoxifen làm tăng nguy cơ ở phụ nữ đã mãn kinh: tư vấn kỹ, theo dõi triệu chứng {{Y5 tr.42}}\n@@tab Cấp 2 (phát hiện sớm)\n- Nhóm nguy cơ (mục 4): siêu âm định kỳ đo độ dày nội mạc; nạo sinh thiết khi nghi ngờ {{Y5 tr.47}}\n- Ra máu âm đạo bất thường → khám phụ khoa, sinh thiết nội mạc {{QĐ1514 tr.PDF 371}}\n- Hội chứng Lynch: nguy cơ trọn đời đến 70%; lịch tầm soát riêng: tài liệu không nêu {{Y5 tr.43}}\n@@tab Cấp 3 (hạn chế biến chứng)\n- Tài liệu không nêu\n@@end\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] Bệnh này thi nhấn mạnh gì\n> - **Chẩn đoán trước**: ra máu âm đạo bất thường (đặc biệt sau mãn kinh) → khám phụ khoa, nạo/sinh thiết nội mạc có mô bệnh học; khung [STT 87](#/khung/87) {{QĐ1514 tr.PDF 371–372}} {{Y5 tr.48}}\n> - **Xử trí sau**: phẫu thuật là chính; xạ, hóa, nội tiết theo giai đoạn và nhóm nguy cơ {{Y5 tr.51}} {{QĐ1514 tr.PDF 374}}\n> - Trọng số thi (theo tools/quy-uoc-v2.md, QĐ 22): chẩn đoán–cận lâm sàng 45–60, xử trí 35–50\n> - Đề cương gắn MT cho bệnh này: MT2–5, MT7–10, MT12–15, MT17 {{ĐC Y5 tr.6}}\n> - Câu hỏi tình huống: \"phụ nữ đã mãn kinh ra máu âm đạo thì làm gì? giai đoạn nào cần xạ bổ trợ?\"\n\n@@tabs\n@@tab Nhận diện\n- Nguy cơ then chốt: **estrogen không đối kháng** (kinh sớm, mãn kinh trễ, béo phì, bướu tế bào hạt, nội tiết ngoại sinh) {{Y5 tr.41}} {{Y5 tr.43}}\n- Tamoxifen tăng nguy cơ ở phụ nữ đã mãn kinh {{Y5 tr.42}}\n- Triệu chứng: ra máu âm đạo bất thường, chiếm tới 90% trường hợp {{QĐ1514 tr.PDF 371}}\n- Hội chứng Lynch: nguy cơ trọn đời đến 70% {{Y5 tr.43}}\n- Thể lâm sàng: tử cung to gồ ghề, ứ dịch; giai đoạn trễ có đau bụng, tắc ruột {{Y5 tr.46}} {{QĐ1514 tr.PDF 371}}\n- [Xem mục 4](#/n/ung-thu-noi-mac-tu-cung/4) · [mục 3](#/n/ung-thu-noi-mac-tu-cung/3)\n@@tab Chẩn đoán\n- **Mô bệnh học** từ nạo/sinh thiết lòng tử cung là tiêu chuẩn xác định {{QĐ1514 tr.PDF 372}} {{Y5 tr.48}}\n- Siêu âm bụng và đầu dò âm đạo đo nội mạc; MRI đánh giá xâm lấn tốt nhất {{Y5 tr.47}}\n- CA 125 không dùng chẩn đoán (Y5); ER/PR cần làm để điều trị nội tiết {{Y5 tr.48}} {{QĐ1514 tr.PDF 372}}\n- Phân giai đoạn sau phẫu thuật, dùng FIGO 2018 (Y5) hoặc AJCC 8 (QĐ1514) {{Y5 tr.48–49}} {{QĐ1514 tr.PDF 374}}\n- Phân nhóm nguy cơ: grad, xâm lấn cơ, LVSI, loại mô học {{Y5 tr.50–51}}\n- [Xem mục 5](#/n/ung-thu-noi-mac-tu-cung/5) · [mục 6](#/n/ung-thu-noi-mac-tu-cung/6)\n@@tab Điều trị\n- Giai đoạn I: phẫu thuật; xạ bổ trợ khi mô học độ 2–3 hoặc xâm lấn ≥50% cơ (QĐ1514) {{QĐ1514 tr.PDF 374}}\n- Giai đoạn III sau mổ không còn bướu: hóa trị + xạ {{Y5 tr.52}}; còn bướu hoặc IVA (tiến xa): mổ nếu lấy hết được, rồi hóa + xạ {{Y5 tr.53}}\n- Tiến xa: hóa trị, nội tiết tùy thụ thể ER/PR và grad {{Y5 tr.53}}\n- Carboplatin–paclitaxel: paclitaxel ==175 mg/m²== + carboplatin AUC 5–6, chu kỳ ==21 ngày== {{QĐ1514 tr.PDF 375}}\n- Nội tiết: ==megestrol 80 mg== và tamoxifen 20 mg, uống 2 lần/ngày, xen kẽ 3 tuần {{QĐ1514 tr.PDF 377}}\n- [Xem mục 7.2](#/n/ung-thu-noi-mac-tu-cung/7) · [mục 7.3](#/n/ung-thu-noi-mac-tu-cung/7)\n@@tab Tiên lượng – Dự phòng\n- Tiên lượng theo giai đoạn: sống 5 năm IA ==88%==, IVA ==17%== {{Y5 tr.53}}\n- Tái phát: ==50%== chỉ vùng chậu, ==28%== chỉ xa, ==22%== cả hai {{Y5 tr.53}}\n- Theo dõi: Y5 giảm dần 3 tháng → 6 tháng → năm; QĐ1514 3 tháng × 5 năm (xem mục 8) {{Y5 tr.53}} {{QĐ1514 tr.PDF 377}}\n- Dự phòng: thuốc ngừa thai uống kết hợp giảm ==30–40%== nguy cơ {{Y5 tr.44}}\n- [Xem mục 8](#/n/ung-thu-noi-mac-tu-cung/8)\n@@end\n\n### Con số và mốc phải nhớ\n\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Ca mới toàn cầu/năm; xuất độ | ==382.069; 8,4/100.000== | {{Y5 tr.40}} |\n| Tuổi đỉnh; tuổi TB chẩn đoán | ==~65; 60–70== | {{Y5 tr.41}} |\n| Kiểu I / kiểu II | ==~80% / ~20%== | {{Y5 tr.41}} |\n| OR tăng sản (estrogen không đối kháng, 1 năm) | ==8,4 (liều TB–cao); 10,7== | {{Y5 tr.41}} |\n| OR béo phì độ 3 (kiểu I) | ==7,1== | {{Y5 tr.43}} |\n| Hội chứng Lynch: nguy cơ trọn đời | ==70%== | {{Y5 tr.43}} |\n| Thuốc ngừa thai uống kết hợp | ==giảm 30–40%== | {{Y5 tr.44}} |\n| Cho con bú | ==giảm 11% (OR 0,8)== | {{Y5 tr.45}} |\n| Tăng sản không điển hình nặng → ung thư | ==25%== | {{Y5 tr.45}} |\n| Grad 1 / 2 / 3 (không tạo tuyến hoặc gai) | ==dưới 5% / 6–50% / trên 50%== | {{Y5 tr.45}} |\n| Sống 5 năm: giai đoạn IA / IVA | ==88% / 17%== | {{Y5 tr.53}} |\n| Tái phát: vùng chậu / xa / cả hai | ==50% / 28% / 22%== | {{Y5 tr.53}} |\n| Xạ bổ trợ giai đoạn I (QĐ1514) | ==mô học độ 2–3 hoặc xâm lấn ≥50% cơ== | {{QĐ1514 tr.PDF 374}} |\n| Carboplatin–paclitaxel | ==paclitaxel 175 mg/m², carboplatin AUC 5–6, 21 ngày== | {{QĐ1514 tr.PDF 375}} |\n| Megestrol / tamoxifen | ==80 mg và 20 mg, 2 lần/ngày, xen kẽ 3 tuần== | {{QĐ1514 tr.PDF 377}} |\n| Theo dõi sau điều trị | ==Y5: 3 tháng ×2 năm; QĐ1514: 3 tháng ×5 năm== | {{Y5 tr.53}} {{QĐ1514 tr.PDF 377}} |\n\n> [!warn] Bẫy thi thường gặp\n> - Số liệu VN: Y5 4177 ca, hạng 8 vs QĐ1514 4.150 ca, hạng 11 {{Y5 tr.40}} {{QĐ1514 tr.PDF 371}}\n> - Mô bệnh học nội mạc: Y5 trên 95% vs QĐ1514 90% {{Y5 tr.45}} {{QĐ1514 tr.PDF 371}}\n> - Theo dõi: Y5 giảm dần theo thời gian; QĐ1514 3 tháng suốt 5 năm {{Y5 tr.53}} {{QĐ1514 tr.PDF 377}}\n> - CA 125: Y5 không dùng chẩn đoán; QĐ1514 liệt kê \"CA 12-5\" có giá trị theo dõi {{Y5 tr.48}} {{QĐ1514 tr.PDF 372}}\n> - IVB: Y5 gồm hạch ổ bụng; QĐ1514 M1 không gồm hạch chủ bụng {{Y5 tr.48}} {{QĐ1514 tr.PDF 373}}\n> - Tế bào học dịch ổ bụng dương tính **không đổi giai đoạn** {{Y5 tr.48}}\n> - Phẫu thuật hạch: Y5 nạo hạch chậu hai bên; QĐ1514 vét hạch chậu và cạnh động mạch chủ {{Y5 tr.51}} {{QĐ1514 tr.PDF 374}}\n> - {r|Carcinosarcoma, nhú thanh dịch, tế bào sáng}: nhóm nguy cơ cao dù ở giai đoạn I (Y5) {{Y5 tr.50–51}}\n> - {r|Tamoxifen}: tăng ung thư nội mạc ở phụ nữ đã mãn kinh, tùy liều và thời gian dùng {{Y5 tr.42}}\n> - {o|Thuốc lá}: giảm nguy cơ ở người mãn kinh, nhưng không giảm ở người còn kinh {{Y5 tr.45}}\n\n@@fold Nguồn tài liệu\n- **Y5**: TEXT UNG BƯỚU Y5 (`_work/text-ung-buou-y5.txt`), chương \"UNG THƯ NỘI MẠC TỬ CUNG\", tr. 40–55, đọc đầy đủ\n- **QĐ1514**: QĐ 1514/QĐ-BYT (`_work/qd-1514-byt-ung-buou.txt`), Bài 45, tr. PDF 371–377, đọc đầy đủ; tr. PDF 378 là tài liệu tham khảo\n- **ĐC Y5**: đề cương (`_work/decuong-y5.txt`) tr. 1–4 (định nghĩa MT2–MT17), tr. 6 (bảng ca lâm sàng gắn MT)\n- **SY5**: slide chỉ nhắc chung ở tr. 7, 180, 183; không có mục riêng cho ung thư nội mạc tử cung\n- **128VĐ** mục 91 (xuất huyết âm đạo bất thường) và mục 92 (xuất huyết tử cung bất thường)\n- **QĐ 22** STT 87, 89, 91 (`_work/qd22.txt`)\n@@end\n\n@@fold Nguồn ngoài\n- Không dùng nguồn ngoài trong bài này; mọi số liệu và nội dung lấy từ các nguồn trên\n@@end\n\n@@fold Tự kiểm tra (14 thẻ)\n- Triệu chứng hay gặp nhất của UNMTC là gì? :: Ra máu âm đạo bất thường, chiếm tới 90%; phụ nữ đã mãn kinh có chảy máu âm đạo cần khám phụ khoa kỹ\n- Chưa mãn kinh có kinh kéo dài, hoặc phụ nữ đang dùng tamoxifen có ra máu âm đạo thì làm gì? :: Sinh thiết nội mạc tử cung\n- Xét nghiệm nào quyết định chẩn đoán UNMTC? :: Nạo hoặc sinh thiết lòng tử cung để có mô bệnh học\n- Kiểu I và kiểu II khác nhau thế nào? :: Kiểu I (khoảng 80%) liên quan estrogen, grad 1–2, tiên lượng tốt; kiểu II (khoảng 20%) không liên quan nội tiết, grad 3, tiên lượng xấu hơn\n- Thuốc nào làm tăng nguy cơ UNMTC ở phụ nữ đã mãn kinh? :: Tamoxifen, do đồng vận estrogen ở nội mạc; tăng theo liều và thời gian\n- Thuốc ngừa thai uống kết hợp giảm nguy cơ bao nhiêu? :: Khoảng 30–40%, lợi ích kéo dài nhiều năm sau khi ngưng\n- OR béo phì độ 3 (kiểu I) là bao nhiêu? :: 7,1 (BMI từ 40 trở lên), so với thừa cân 1,5\n- Hội chứng Lynch có nguy cơ UNMTC trọn đời bao nhiêu? :: Đến 70%; chỉ chiếm 2–5% phụ nữ UNMTC\n- Phẫu thuật tiêu chuẩn UNMTC theo Y5 gồm những gì? :: Cắt tử cung toàn bộ + hai phần phụ, ± nạo hạch chậu hai bên; QĐ1514 ghi thêm hạch cạnh động mạch chủ\n- Giai đoạn I cần xạ bổ trợ khi nào theo QĐ1514? :: Mô học độ 2 hoặc 3, hoặc u xâm lấn ≥50% cơ tử cung\n- Phác đồ carboplatin–paclitaxel theo QĐ1514? :: Paclitaxel 175 mg/m² TM ngày 1 + carboplatin AUC 5–6 TM ngày 1; chu kỳ 21 ngày\n- Nội tiết megestrol xen tamoxifen theo QĐ1514? :: Megestrol 80 mg và tamoxifen 20 mg, mỗi thuốc uống 2 lần/ngày trong 3 tuần, xen kẽ\n- Sống 5 năm giai đoạn IA và IVA theo Y5? :: IA 88%, IVA 17%\n- Theo dõi sau điều trị theo Y5? :: 3 tháng/lần trong 2 năm đầu; 6 tháng/lần trong 3 năm kế; sau 5 năm mỗi năm/lần\n@@end"}, {"kind": "disease", "disease": "phoi", "short": "Ung thư phổi", "group": "", "section": 0, "order": 4, "khung": [40, 41, 46, 47], "id": "ung-thu-phoi", "title": "Ung thư phổi", "layer": "benh", "module": "ung-buou", "tags": ["ung bướu", "phổi", "NSCLC", "SCLC", "ung thư phổi tế bào nhỏ", "không tế bào nhỏ", "ho ra máu", "nốt phổi đơn độc", "TNM", "EGFR", "ALK"], "source": "Y5 tr. 104–126; QĐ1514 Bài 33 (tr. PDF 242–254), Bài 9–10 (tr. PDF 64–70); QĐ4825 (tr. PDF 1–18); 128VĐ mục 49, 50, 56, 57; nguồn ngoài có gắn nhãn", "body": "> [!key] Ung thư phổi (UT phổi) trong một cái nhìn\n> - Hai nhóm: **UT phổi tế bào nhỏ (SCLC / UTPTBN)** và **không tế bào nhỏ (NSCLC / UTPKTBN)** vì diễn tiến và điều trị khác nhau {{Y5 tr.104}}.\n> - Thuốc lá là nguyên nhân chính (QĐ1514: ==~90%==); ==nguy cơ gấp 20 lần== người không hút {{Y5 tr.105}}.\n> - **Không có triệu chứng đặc hiệu** nên đa số phát hiện muộn: >70% NSCLC đã ở giai đoạn tiến xa; yếu tố tiên lượng quan trọng nhất là **giai đoạn** {{Y5 tr.104}}.\n> - NSCLC: mổ (I–II), hóa-xạ (III), đích/miễn dịch theo đột biến và PD-L1 (IV) {{QĐ4825 tr.10–17}}. SCLC: **hóa trị chủ đạo** (cisplatin/carboplatin + etoposide), xạ lồng ngực + xạ dự phòng não {{Y5 tr.116}} {{QĐ1514 tr.PDF 247}}.\n> - Khung thi: [Ho đàm – ho khan (STT 40)](#/khung/40), [Ho ra máu (STT 41)](#/khung/41), [Tràn dịch màng phổi (STT 46)](#/khung/46), [Bất thường X quang ngực (STT 47)](#/khung/47).\n\n## 3. Bệnh học\n\n### Định nghĩa và dịch tễ\n- UT phổi là nguyên nhân tử vong do UT hàng đầu ở cả nam và nữ, tại Hoa Kỳ và trên toàn cầu. Từ 1987 vượt UT vú ở phụ nữ Hoa Kỳ (do phụ nữ hút thuốc tăng) {{Y5 tr.104}}.\n- Hoa Kỳ 2012 (Y5): 226.160 ca mới (116.470 nam, 109.690 nữ), 160.340 ca tử vong {{Y5 tr.104}}.\n- Hút thuốc giảm ở Hoa Kỳ nhưng **tăng đáng báo động ở các nước đang phát triển (có Việt Nam)** {{Y5 tr.104}}.\n- **Việt Nam:** Globocan 2018 hàng ==thứ hai== (sau UT gan), ==23.667== ca mới. TPHCM 2016: hàng đầu ở nam, thứ năm ở nữ; tần suất chuẩn tuổi ==35,1 và 11,6== /100.000 dân {{Y5 tr.105}}.\n- QĐ1514: bệnh thường gặp ở nam, liên quan mật thiết với hút thuốc {{QĐ1514 tr.PDF 242}}.\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Thuốc lá (chính)\n- Thuốc lá: đại đa số tử vong; QĐ1514 ==~90%== các ca. Hút càng lâu, càng nhiều thì nguy cơ càng cao {{Y5 tr.105}} {{QĐ1514 tr.PDF 246}}.\n- Chất sinh ung: **hydrocarbon thơm đa vòng, amin thơm, nitrosamin** tạo **DNA adduct**; người hút nhiều có thể có tới ==100 đột biến== trong hệ gen tế bào {{Y5 tr.105}}.\n- Nguy cơ ở người hút ==gấp 20 lần== người chưa bao giờ hút; ngưng hút làm giảm nguy cơ {{Y5 tr.105}}.\n- Hút thuốc thụ động: ~3.000 ca tử vong/năm tại Hoa Kỳ {{Y5 tr.105}}.\n- {g|Hơn 90%} bệnh nhân sẽ không mắc nếu không hút thuốc {{Y5 tr.105}}.\n@@tab Môi trường – nghề nghiệp\n- **Radon** (từ phân rã radium 226, phóng hạt alpha; trong nhà kín, kém thông thoáng): nguyên nhân thứ hai tại Hoa Kỳ, 6.000–36.000 tử vong/năm {{Y5 tr.105}}.\n- Bệnh nghề nghiệp: **amiăng, arsenic, muối silicat, chlormethyl ether, nickel, hydrocarbon thơm đa vòng**: ==9–15%== UT phổi. Hút thuốc + amiăng làm nguy cơ tăng thêm (khói thuốc làm bít phế quản, sợi amiăng bị giữ lâu) {{Y5 tr.105}}.\n- QĐ1514: arsenic, asbestos, hydrocarbon, khí mustard, tia phóng xạ {{QĐ1514 tr.PDF 246}}.\n@@tab Khác\n- Di truyền: vai trò ít rõ hơn các UT khác (có thể do thuốc lá quá mạnh làm lu mờ) {{Y5 tr.105}}.\n- Dinh dưỡng: ăn nhiều rau quả (vitamin A, C, E chống oxy hóa) giảm nguy cơ {{QĐ1514 tr.PDF 247}}.\n- Bổ sung beta-carotene, retinoid, selenium: các thử nghiệm lớn thập niên 1990 **không** cho thấy hiệu quả phòng ngừa {{Y5 tr.105}}.\n@@end\n\n### Giải phẫu bệnh – phân loại\n> [!warn] **Y5 tự mâu thuẫn tỉ lệ mô học.** Chữ trong bài: SCLC **15%**, NSCLC **85%** {{Y5 tr.106–107}}. Hình 1 cùng bài: SCLC **20%**, NSCLC **80%** (tuyến 35–40%, tế bào gai ~30%, tế bào lớn 10–15%) {{Y5 tr.108}}. Ghi nhớ cả hai; làm bài Y5 ưu tiên số trong chữ.\n\n@@tabs\n@@tab NSCLC\n- Gồm: **carcinôm tuyến** (==50–60%== NSCLC), **carcinôm tế bào gai** (==20–25%==), **tế bào lớn** và loại khác {{Y5 tr.107}}.\n- **Tuyến:** thường ở **người không hút thuốc**, nhất là phụ nữ trẻ (cũng gặp ở người hút); thường ngoại vi hơn tế bào gai; hơn nửa có khối ngoại vi + di căn hạch vùng; lan máu đến xương, gan, thượng thận, não.\n- **Tế bào gai:** trước kia cho là trung tâm, nay phân bố tương tự tuyến; thường còn khu trú giai đoạn đầu, tái phát tại chỗ sau mổ/xạ.\n- **Tế bào lớn:** bệnh sử tự nhiên giống tuyến; thể có đặc điểm thần kinh-nội tiết được chẩn đoán nhiều hơn nhờ hóa mô miễn dịch (**chromogranin, NSE**).\n@@tab SCLC\n- Chiếm {o|15%} (chữ Y5) UT phổi; vị trí **trung tâm, vùng rốn phổi (95%)** {{Y5 tr.106}}.\n- Thường **đã lan tràn lúc nhập viện**, lâm sàng xấu nhanh; di căn não, xương, thượng thận, gan; **tràn dịch màng phổi** hay gặp; tái phát sau xạ/hóa ở vị trí cũ hoặc mới.\n- Tiến triển nhanh tới di căn xa nhưng **nhạy hóa chất** nên hóa trị là chủ đạo {{QĐ1514 tr.PDF 247}}.\n@@end\n\n@@fold Hội chứng cận u theo loại mô học {{Y5 tr.106–107}}\n| Loại | Hội chứng cận u |\n|---|---|\n| SCLC | **SIADH** thường nhất; tăng đông thường gặp; tăng ACTH không thường gặp; Eaton-Lambert hiếm; tăng canxi máu hiếm |\n| Tế bào gai | **Tăng canxi máu** (peptide liên quan hormon cận giáp, PTHrP) thường nhất; phì đại xương khớp đôi khi; tăng bạch cầu đa nhân, tăng đông |\n| Tuyến, tế bào lớn | Phì đại xương khớp, tăng đông, tăng canxi máu, nữ hóa tuyến vú |\n@@end\n\n### Sinh bệnh học và sinh học phân tử\n- Diễn tiến nhiều bước: niêm mạc phế quản bình thường, loạn sản, carcinôm tại chỗ, UT xâm lấn; kích hoạt gen sinh ung, bất hoạt gen đè nén bướu, mất ổn định hệ gen; biến đổi trong gen (mất đoạn, đột biến) và ngoài gen (methyl hóa) {{Y5 tr.108}}.\n- Đột biến là **dấu ấn sinh học phân tử** để chọn thuốc nhắm đích cho NSCLC {{Y5 tr.108}}.\n\n| Thay đổi phân tử NSCLC (Y5 Bảng 1) | Tỉ lệ % |\n|---|---|\n| Đột biến **KRAS** | 15–25 |\n| Đột biến **EGFR** | 10–35 |\n| Đột biến PTEN | 4–8 |\n| Chuyển đoạn **ALK** | 3–7 |\n| Đột biến HER2 | 2–4 |\n| Đột biến PIK3CA, AKT, BRAF | 1–3 mỗi loại |\n| Đột biến NRAS; tái sắp xếp **ROS** | 1 mỗi loại |\n\n### Diễn tiến tự nhiên – lan tràn\n- Lan tại chỗ (thành ngực, trung thất, màng phổi), qua hạch (rốn phổi, trung thất, thượng đòn) và qua máu: **não, xương, gan, thượng thận** {{Y5 tr.106–107}}.\n- Sau mổ triệt để R0 khoảng **một nửa** vẫn tái phát; di căn xa gấp 2–3 lần tái phát tại chỗ-vùng {{Y5 tr.117}}.\n- Kiến thức nền: [[ung-thu-xam-lan-di-can]], [[ung-thu-giai-phau-benh]], [[ung-thu-co-che-sinh-ung]].\n\n## 4. Triệu chứng học\n\n> [!key] **Không có triệu chứng cơ năng hay thực thể nào đặc hiệu** nên chẩn đoán thường muộn; có thể phát hiện **tình cờ** qua X quang phổi. Triệu chứng do bướu nguyên phát, do di căn, hoặc do hội chứng cận u {{Y5 tr.109}}.\n\n### Triệu chứng theo vị trí (Y5 Bảng 2)\n| Vị trí | Biểu hiện |\n|---|---|\n| Bướu **trung tâm** | Ho, khó thở, **ho ra máu**, thở rít, viêm phổi (sốt, ho đàm do tắc phế quản) |\n| Bướu **ngoại vi** | Đau (xâm lấn màng phổi/thành ngực), ho, khó thở, viêm phổi |\n| Hạch vùng, xâm lấn tại chỗ | Khàn tiếng (**thần kinh quặt ngược**); nuốt nghẹn (thực quản); khó thở (TDMP, tắc khí/phế quản, TDMP tim, liệt thần kinh hoành, tắc mạch lymphô, **chèn ép TM chủ trên**); **hội chứng Horner** (giao cảm) |\n| Di căn xa | Xương: đau tăng khi vận động/mang vật nặng, tăng về đêm, gãy xương. Gan: đau hạ sườn phải, vàng da, lú lẫn. Não: lú lẫn, động kinh, giảm vận động/cảm giác |\n| Cận ung thư | Phì đại xương khớp (ngón tay dùi trống), tăng canxi máu, viêm da-cơ, tăng đông, nữ hóa tuyến vú |\n*Nguồn: {{Y5 tr.109–110}}*\n\n@@fold Tình huống không điển hình {{Y5 tr.112}}\n- Sốt, ho, khạc đàm mủ giống viêm phổi.\n- Khàn tiếng do chèn thần kinh quặt ngược ở trung thất.\n- **Bướu Pancoast** (đỉnh phổi): đau vai nhiều do xâm lấn đám rối thần kinh cánh tay, hủy xương sườn 1.\n@@end\n\n@@fold! Hội chứng trung thất (QĐ1514, mô tả cho SCLC) {{QĐ1514 tr.PDF 242}}\n| Chèn ép | Biểu hiện |\n|---|---|\n| TM chủ trên | Phù áo khoác, TM cổ nổi, tuần hoàn bàng hệ |\n| Thực quản | Khó nuốt, nuốt đau |\n| Thần kinh quặt ngược trái | Khàn tiếng, giọng đôi |\n| Giao cảm cổ | Khe mắt hẹp, đồng tử co, gò má đỏ bên tổn thương (Horner) |\n| Thần kinh phế vị | Hồi hộp, tim nhanh |\n| Thần kinh hoành | Nấc, đau vùng hoành, khó thở |\n| Đám rối cánh tay | Đau vai lan mặt trong cánh tay, rối loạn cảm giác |\n| Ống ngực chủ | Tràn dưỡng chấp màng phổi |\nThêm: TDMP, tràn dịch màng tim, rối loạn nhịp; toàn thân mệt, gầy sút, sốt.\n@@end\n\n@@tabs\n@@tab Giai đoạn sớm (QĐ1514)\n- Âm thầm, nghèo hoặc không triệu chứng.\n- Gợi ý: **nam >40 tuổi, nghiện thuốc lá/thuốc lào, ho khan kéo dài, có thể đờm lẫn máu, kháng sinh không kết quả** {{QĐ1514 tr.PDF 242}}.\n@@tab Di căn\n- Hạch thượng đòn, nốt di căn da thành ngực.\n- Não: tăng áp lực nội sọ, liệt khu trú. Xương: đau, gãy bệnh lý.\n- Phổi đối bên và gan: thường **không triệu chứng** {{QĐ1514 tr.PDF 243}}.\n@@tab Cận ung thư (QĐ1514)\n- Ngón tay dùi trống; \"đái tháo nhạt\" do chất giống ADH; Cushing (giống ACTH); tăng canxi (giống PTH); vú to, giọng cao, teo tinh hoàn (giống gonadotropin); giả nhược cơ; viêm da cơ {{QĐ1514 tr.PDF 243}}.\n@@end\n\n> [!warn] **Mâu thuẫn nguồn (giữ để thi).** QĐ1514 ghi hội chứng cận ung thư \"thường gặp hơn trong NSCLC\" và nêu **đái tháo nhạt**; Y5 ghi **SIADH** thường nhất ở **SCLC** {{Y5 tr.106}}. Theo Y5 (giảng dạy): SCLC = SIADH, tế bào gai = tăng canxi máu.\n\n> [!red]\n> - {r|Ho ra máu} nhiều (>200 ml/24 giờ), nhất là u rốn phổi hoặc xâm lấn mạch lớn: cầm máu, giữ đường thở, nút ĐM phế quản {{QĐ1514 tr.PDF 64–67}} (xem mục Phác đồ – Y lệnh ở tab 5.5).\n> - {r|Hội chứng chèn ép TM chủ trên}: phù áo khoác, TM cổ nổi, khó thở; NSCLC đặt stent trước rồi xạ ± hóa; SCLC nhạy hóa chất nên hóa trị ngay (có thể đặt stent trước) {{QĐ1514 tr.PDF 68–70}}.\n> - {r|Chèn ép tủy}, tăng áp lực nội sọ (di căn não), tăng canxi máu nặng, thở rít.\n\n### Tiếp cận các triệu chứng theo khung 128 vấn đề\n| STT | Vấn đề | Khi nghĩ đến UT phổi |\n|---|---|---|\n| [40](#/khung/40) | Ho đàm – ho khan (128VĐ mục 49) | Ho **mạn >8 tuần** (cấp <3 tuần; bán cấp 3–8 tuần); UT phổi, UT vòm hầu nằm trong nhóm ho mạn. Gợi ý: nam >40, hút thuốc, ho khan kéo dài, kháng sinh không đáp ứng |\n| [41](#/khung/41) | Ho ra máu (mục 50) | Nguyên nhân thường gặp ở VN: lao, di chứng lao, giãn phế quản, **UT phổi**...; nhóm UT: UT biểu mô phế quản, di căn nội phế quản, carcinoid, Kaposi; do điều trị: **bevacizumab**. Tử vong khi ho nhiều 9–38% |\n| [46](#/khung/46) | Tràn dịch màng phổi (mục 56) | Dịch tiết ác tính; TDMP ác tính trong UT phổi = **M1a (giai đoạn IV)**; sau chọc hết dịch chụp lại thấy khối u |\n| [47](#/khung/47) | Bất thường X quang ngực (mục 57) | Nốt/khối, thâm nhiễm, xóa bờ tim, hạch/u trung thất, TDMP, khí quản lệch; nốt phổi đơn độc (xem mục 5–6) |\n*Nguồn: 128VĐ mục 49, 50, 56, 57 {{128VĐ}}; Y5 tr.109–112; QĐ1514 tr.PDF 242–244*\n\n> [!tip] Khối phổi ở nam hút thuốc + ho khan kéo dài + kháng sinh không đáp ứng + X quang không sáng lên sau 1 tháng: nghĩ ung thư đến khi chứng minh ngược lại {{QĐ1514 tr.PDF 242–244}}.\n\n## 5. Cận lâm sàng\n\n> [!key] Việc đầu tiên: có **giải phẫu bệnh** (NSCLC hay SCLC); kế đó **chẩn đoán giai đoạn**. Giai đoạn muộn cần **đột biến gen** và **PD-L1 (chốt kiểm miễn dịch)** {{Y5 tr.110}}.\n\n### Hình ảnh\n- **X quang ngực thẳng, nghiêng:** đám mờ, TDMP, vị trí, hình thái, kích thước; đánh giá khả năng mổ {{QĐ1514 tr.PDF 243}}.\n- **CT ngực + bụng có cản quang** (thấy rõ hai tuyến thượng thận): khối u, hạch trung thất, mức lan {{Y5 tr.111}}.\n- **Nội soi phế quản:** thường thể sùi, chít hẹp; sinh thiết/chải-rửa (==97%== chẩn đoán GPB tổn thương trung tâm) {{Y5 tr.110}}.\n- **PET/CT:** phát hiện sớm, xếp giai đoạn, đáp ứng, tái phát, mô phỏng xạ trị, chọn vị trí sinh thiết {{QĐ1514 tr.PDF 243}}.\n- **Xạ hình xương** (nếu đau xương); **CT/MRI sọ não** (MRI cho số lượng, kích thước, kế hoạch dao gamma); siêu âm bụng tìm di căn; xạ hình thận chức năng trước/sau điều trị {{QĐ1514 tr.PDF 243}}.\n- **Không cần MRI não thường quy** ở bệnh nhân không triệu chứng {{Y5 tr.111}}.\n\n### Giải phẫu bệnh – sinh học phân tử – dấu ấn\n- Sinh thiết xuyên thành ngực dưới CT (ngoại vi), soi phế quản (trung tâm), **soi trung thất** (hạch, bướu trung tâm); PET-CT + soi trung thất xếp giai đoạn chính xác hơn {{Y5 tr.111}}.\n- {o|FNA} qua soi phế quản/xuyên thành ngực khó xác định loại mô học và **không làm được hóa mô miễn dịch**; sinh thiết lõi kim hoặc mẫu lớn cho nhiều thông tin hơn {{Y5 tr.106}}.\n- Không sinh thiết được u phổi: sinh thiết hạch thượng đòn/di căn khác + hóa mô miễn dịch để xác định nguồn gốc phổi; tế bào học đờm, dịch màng phổi, dịch rửa phế quản {{QĐ1514 tr.PDF 244}}.\n- Dấu ấn u (SCLC): **NSE, CEA, ProGRP** theo dõi đáp ứng, tái phát {{QĐ1514 tr.PDF 244}}. Sinh học phân tử: giải trình tự nhiều gen (EGFR, ALK, ROS1, NTRK, PD-L1).\n- Trước mổ: **FEV1 ≥ 2 L** (cắt phổi), **1 L** (cắt thùy), **0,6 L** (cắt phân thùy); FVC ≥ 1,7 L {{Y5 tr.112}}.\n\n### Phân giai đoạn TNM (AJCC/UICC lần 8, 2017) {{Y5 tr.112–114}} {{QĐ1514 tr.PDF 244–246}}\n@@fold! Bảng T–N–M (Y5 Bảng 3)\n| Mã | Tiêu chuẩn |\n|---|---|\n| Tis | Carcinôm tại chỗ |\n| T1mi | ≤3 cm, tuyến xâm nhập tối thiểu |\n| T1a / T1b / T1c | ≤1 cm / >1–2 cm / >2–3 cm |\n| T2 | >3–5 cm, hoặc phế quản gốc chưa đến carina, xâm lấn màng phổi tạng, xẹp/viêm phổi tắc nghẽn đến rốn phổi. **T2a** >3–4 cm; **T2b** >4–5 cm |\n| T3 | >5–7 cm; hoặc xâm lấn màng phổi thành; hoặc nốt cùng thùy |\n| T4 | >7 cm; hoặc xâm lấn cơ hoành, trung thất, tim, mạch lớn, khí quản, thần kinh quặt ngược, thực quản, thân đốt sống, carina; hoặc nốt thùy khác cùng bên |\n| N1 | Hạch quanh phế quản, rốn phổi cùng bên |\n| N2 | Hạch trung thất cùng bên / dưới carina |\n| N3 | Hạch trung thất hoặc rốn phổi đối bên; hạch cơ bậc thang; hạch trên đòn |\n| M1a | Nốt phổi đối bên; **TDMP/màng tim ác tính** |\n| M1b | Di căn ngoài ngực **đơn độc** |\n| M1c | Di căn ngoài ngực **nhiều ổ/nhiều cơ quan** |\n@@end\n\n| Giai đoạn | TNM |\n|---|---|\n| 0 | Tis N0 M0 |\n| IA1 / IA2 / IA3 | T1mi–T1a / T1b / T1c, N0 M0 |\n| IB | T2a N0 M0 |\n| IIA | T2b N0 M0 |\n| IIB | T1–2 N1 M0; T3 N0 M0 |\n| IIIA | T1–2 N2; T3–4 N1; T4 N0 (M0) |\n| IIIB | T1–2 N3; T3–4 N2 (M0) |\n| IIIC | T3–4 N3 M0 |\n| IVA | M1a hoặc M1b |\n| IVB | M1c |\n\n> [!warn] **QĐ1514 và Y5 khác chữ ở mốc T:** QĐ1514 xếp xâm lấn thành ngực, thần kinh hoành, màng phổi trung thất, màng ngoài tim hoặc nốt cùng thùy vào **T3**; T2 ghi \"phế quản gốc cách carina ≥2 cm\"; N3 ghi \"hạch cơ bậc thang cùng hoặc đối bên\". Thi Y5 theo Bảng 3 ở trên; nhóm giai đoạn hai nguồn trùng nhau.\n\n@@tabs\n@@tab SCLC (2 giai đoạn lâm sàng)\n- **Khu trú:** giới hạn một bên lồng ngực, trung thất, hạch thượng đòn cùng bên, bao được trong **một trường chiếu xạ** (giai đoạn I–III, trừ T3–4 quá lan rộng hoặc khối/hạch quá lớn).\n- **Lan tràn:** vượt giới hạn trên (giai đoạn IV và T3–4 quá lớn) {{Y5 tr.113}} {{QĐ1514 tr.PDF 246}}.\n@@tab NSCLC\n- Xếp TNM đầy đủ; **giai đoạn pTNM sau mổ** để tiên lượng và xét điều trị hỗ trợ {{Y5 tr.112}}.\n- Giai đoạn I–II: còn khu trú một phổi. Giai đoạn III rất đa dạng. Giai đoạn IV: di căn phổi đối bên, TDMP/tim ác tính hoặc di căn xa.\n@@end\n\n### Chỉ định gì khi nào (tóm tắt)\n| Tình huống | Làm gì |\n|---|---|\n| Nốt phổi đơn độc | Xem phim cũ, CT cản quang, PET-CT; tăng kích thước thì sinh thiết (mục 6) |\n| Nghi UT phổi | CT ngực-bụng, sinh thiết (soi phế quản hoặc xuyên thành ngực), xếp giai đoạn |\n| Chuẩn bị mổ | PET-CT + soi trung thất, hô hấp ký (FEV1) |\n| NSCLC giai đoạn muộn | Đột biến EGFR, ALK, ROS1, NTRK; PD-L1 |\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] **Chẩn đoán xác định = giải phẫu bệnh** (mô bệnh học ± hóa mô miễn dịch) của u nguyên phát hoặc tổn thương di căn; kèm xếp giai đoạn và đột biến/PD-L1 (NSCLC) {{Y5 tr.110}} {{QĐ1514 tr.PDF 244}}.\n\n### Nốt phổi đơn độc {{Y5 tr.110–111}}\n- Khối đơn độc, giới hạn rõ, mô phổi bao quanh, ==<3 cm==, không hạch trung thất/rốn phổi; thường phát hiện tình cờ.\n- Xem phim cũ: tổn thương **không tăng kích thước trong 2 năm** thường không phải UT.\n- **PET-CT:** nhạy ==96%==, đặc hiệu ==75%==, giá trị tiên đoán dương và âm ~90%. {r|Dương tính giả:} lao, bệnh mô bào (histoplasmosis). {o|Âm tính giả:} tổn thương <1 cm, UT chuyển hóa thấp (phế quản-phế nang).\n- Tăng kích thước: **sinh thiết** (FNA/lõi kim xuyên thành ngực hoặc mở ngực); soi phế quản ống mềm cho tổn thương trung tâm.\n- Nguy cơ thấp (<40 tuổi, không hút, <2 cm, không đổi, không chuyển hóa PET): theo dõi định kỳ bằng CT cản quang.\n\n### Chẩn đoán phân biệt\n| Bệnh | Điểm giống | Điểm phân biệt |\n|---|---|---|\n| **Viêm phổi** (kéo dài/không đáp ứng) | Ho, sốt, đàm, đám mờ; UT phổi có thể biểu hiện như viêm phổi | Chụp lại X quang **sau kháng sinh 1 tháng**; UT: tổn thương không biến mất, tái phát cùng vị trí {{QĐ1514 tr.PDF 244}} |\n| **Áp xe phổi** | Hình hang, ho đàm | Hội chứng nhiễm trùng, hình hang thành mỏng-đáy dịch khí, **đáp ứng kháng sinh** {{QĐ1514 tr.PDF 244}}; UT dạng hang: thành dày, không đều {{+StatPearls}} |\n| **Lao phổi / u lao** | Ho, ho ra máu, nốt/hang, hạch; PET dương tính giả | AFB/Xpert đờm, tổn thương thùy trên, nhiễm lao; sinh thiết khi nghi; lao và UT có thể **cùng tồn tại** {{128VĐ}} {{+NCI PDQ}} |\n| **Tràn dịch màng phổi** do nguyên nhân khác | Khó thở, mờ góc sườn hoành | Sau chọc hết dịch chụp lại: UT thấy khối u {{QĐ1514 tr.PDF 244}}; phân tích dịch, tế bào học |\n| **U lành tính** (u mô thừa/hamartoma, u xơ...) | Nốt đơn độc | Bờ đều, vôi hóa dạng bỏng ngô hoặc mỡ trên CT, ổn định ≥2 năm {{+StatPearls}} |\n| **Di căn phổi** (đại tràng, vú, thận, sarcoma...) | Nhiều nốt hoặc nốt đơn độc, thả bóng/kê | Tiền sử UT khác, nhiều nốt hai phổi, hóa mô miễn dịch xác định nguồn gốc {{128VĐ}} {{+NCI PDQ}} |\n| **Nấm phổi, u hạt, bệnh mô bào** | Nốt/khối, PET dương tính giả | Huyết thanh, dịch tễ, sinh thiết {{Y5 tr.110}} |\n| **Giãn phế quản, nhồi máu phổi** | Ho ra máu | CT ngực, bối cảnh lâm sàng {{128VĐ}} |\n| **UT trung biểu mô màng phổi** | TDMP, nốt/dày màng phổi | Amiăng 70–80%; IHC calretinin, D2-40, CK5/6 (+), CEA, TTF1 (-) {{QĐ1514 tr.PDF 255–256}} |\n\n> [!ext] Chẩn đoán phân biệt hình ảnh (hang thành dày, hamartoma vôi hóa, lao cùng tồn tại) lấy ý từ StatPearls (Lung Cancer/NSCLC) và NCI PDQ, diễn đạt lại, không phải văn bản Y5/BYT. URL mục 9. {{+StatPearls}}\n\n> [!warn] Tổn thương không tan sau kháng sinh, ho khan kéo dài ở người hút thuốc, TDMP tái phát nhanh sau chọc: phải tìm tế bào/giải phẫu bệnh, không điều trị kháng sinh kéo dài.\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n\n> [!doc] **Mục tiêu theo giai đoạn:** NSCLC: triệt căn ở I, II, IIIA; giảm nhẹ, kéo dài sống ở IIIB, IIIC, IV {{QĐ4825 tr.10}}. SCLC: hóa-xạ cho khu trú và lan tràn; hóa chất giảm tái phát, kéo dài sống thêm {{QĐ1514 tr.PDF 247}}.\n\n@@tabs\n@@tab NSCLC\n- **I–II (+ IIIA mổ được):** {g|điều trị khỏi} (phẫu thuật triệt để), giảm tái phát bằng hóa trị hỗ trợ khi có chỉ định {{Y5 tr.117}} {{QĐ4825 tr.10}}.\n- **III không mổ:** kiểm soát tại chỗ-vùng, có thể khỏi một phần; hóa-xạ đồng thời rồi củng cố miễn dịch {{Y5 tr.116}}. {o|QĐ4825 xếp IIIB–C vào giảm nhẹ, kéo dài sống} {{QĐ4825 tr.10}}.\n- **IV:** không khỏi; **kéo dài sống còn, kiểm soát triệu chứng, giữ chất lượng sống**; chọn thuốc theo đột biến, PD-L1, tổng trạng {{Y5 tr.120}}.\n@@tab SCLC\n- **Khu trú:** mục tiêu điều trị **tận gốc** (hóa-xạ đồng thời + xạ dự phòng não); chỉ hóa trị thì tái phát 80% {{Y5 tr.124}}.\n- **Lan tràn:** hóa trị kéo dài sống, giảm triệu chứng; xạ dự phòng não nếu đáp ứng {{QĐ1514 tr.PDF 247}}.\n@@tab Giảm nhẹ\n- Cầm máu, giảm đau xương (xạ), giảm khó thở, xử trí chèn ép TM chủ trên, di căn não; chăm sóc giảm nhẹ tích cực khi tổng trạng kém hoặc hết đáp ứng {{Y5 tr.120}} {{QĐ1514 tr.PDF 253}}.\n@@end\n\n### 7.2 Các phương pháp\n\n> [!warn] **Đã có văn bản Bộ Y tế cho NSCLC: QĐ 4825/QĐ-BYT (06/08/2018), \"Hướng dẫn chẩn đoán và điều trị ung thư phổi không tế bào nhỏ\"** (tr. PDF 1–18; điều trị tr. PDF 10–18). Phần NSCLC dưới đây ưu tiên QĐ4825; nội dung QĐ4825 không nêu giữ nhãn **Y5 (giáo trình)**; phần tham khảo ngoài đặt trong hộp hộp cam. Chỗ QĐ4825 và Y5 khác nhau được ghi \"mâu thuẫn, nêu cả hai\".\n\n@@tabs\n@@tab NSCLC theo giai đoạn\n@@tabs\n@@tab I–II\n- Giai đoạn sớm (25–30% bệnh nhân); sống 5 năm 58–73% (I), 36–46% (II) {{Y5 tr.117}}. QĐ4825: sống 5 năm sau VATS 70–80% (IA), 60% (IB), 40–50% (II) {{QĐ4825 tr.10}}.\n- **Phẫu thuật** (chọn lựa): **cắt trọn thùy hoặc cắt phổi** mang u, diện cắt âm tính, lấy 16–20 hạch từ ≥3 nhóm, rửa màng phổi cùng bên {{QĐ4825 tr.10}}. Nội soi lồng ngực (VATS) cho sống còn và tái phát tương đương mổ hở ở u nhỏ-vừa ngoại biên; cắt robot còn đang nghiên cứu {{QĐ4825 tr.10}}. Nội soi lồng ngực chấp nhận như mổ hở; luôn nạo/sinh thiết hạch trung thất {{Y5 tr.117–118}}.\n- {o|Hình chêm}: QĐ4825 chấp nhận cho u ngoại biên <3 cm, mô học AIS/MIA, bờ âm tính; u trung tâm hình chêm tái phát tại chỗ cao hơn 3–5 lần cắt thùy {{QĐ4825 tr.10}}. {r|Y5: cắt phân thùy/hình chêm không khuyến cáo} {{Y5 tr.117–118}}. **Mâu thuẫn, nêu cả hai.**\n- **Hóa trị hỗ trợ sau mổ:** QĐ4825 chỉ định từ **giai đoạn IB**, thường 4 chu kỳ có platin, cisplatin ưu tiên hơn carboplatin {{QĐ4825 tr.11}}. {r|Y5: không chỉ định giai đoạn I; là lựa chọn giai đoạn II} (LACE: giảm nguy cơ tử vong 5 năm 5,4%, HR 0,89) {{Y5 tr.117}}. **Mâu thuẫn ở IB, nêu cả hai.**\n- {o|Xạ trị sau mổ I–II}: QĐ4825 **không xác nhận có lợi**; chỉ cân nhắc khi nguy cơ cao tái phát tại chỗ-vùng; liều thường 54 Gy, 27–30 phân liều {{QĐ4825 tr.11}}. Y5 ghi làm giảm sống còn {{Y5 tr.117}}.\n- Không mổ được: **xạ trị triệt căn** quy ước (thường ≤70 Gy, kiểm soát bướu ~50%) hoặc **SBRT** (chưa là thường quy): u ngoại biên 18–20 Gy/phân liều; u trung tâm hay gây độc tính độ 3, khuyến cáo 10–12 Gy x 3–4 phân liều {{QĐ4825 tr.11}}. Y5: SBRT cho bướu ==<5 cm==; xạ liều ngắn 54 Gy/12 ngày có OS 4 năm tốt hơn 60 Gy/6 tuần {{Y5 tr.118}}.\n@@tab IIIA\n- OS 5 năm 24% (tr.118); đa mô thức, nhiều tranh cãi {{Y5 tr.118}}.\n- {g|Hóa trị tân bổ trợ là lựa chọn tiêu chuẩn} (QĐ4825): cisplatin + vinorelbine, etoposide, gemcitabine, docetaxel hoặc pemetrexed (không tế bào vẩy), 4 chu kỳ; carboplatin khi không dung nạp cisplatin {{QĐ4825 tr.10–11}} {{QĐ4825 tr.16}}.\n- Tình cờ N2 trong mổ: nạo hạch + **hóa trị hỗ trợ** (IALT 44,5% vs 40,4%; ANITA IIIA 42% vs 26%) {{Y5 tr.118}}. {r|Xạ trị sau mổ:} Y5 không khuyến cáo (PORT: nguy cơ tử vong tăng 1,21); QĐ4825 chỉ cân nhắc khi nguy cơ cao tái phát tại chỗ-vùng (xâm lấn trung thất, nhiều hạch, vỡ vỏ hạch, bờ cắt dương tính) {{QĐ4825 tr.11}}. **Mâu thuẫn, nêu cả hai.**\n- N2 lớn hoặc xác định bằng soi trung thất: **không mổ ngay**, **hóa-xạ đồng thời** (hơn tuần tự); sau đó củng cố bằng thuốc ức chế chốt kiểm nếu không tiến triển {{Y5 tr.116}}; QĐ4825 dùng durvalumab {{QĐ4825 tr.12}} {{QĐ4825 tr.17}}.\n- N2 nhỏ (<2 cm): có thể mổ rồi hóa trị hỗ trợ; hoặc hóa trị tiền phẫu rồi mổ. Tân hỗ trợ: bướu nhỏ đi, nhưng trì hoãn mổ, tăng tai biến; EORTC 08941 và Intergroup 0196 không khác OS so với hóa-xạ đơn thuần. {{Y5 tr.119}}\n@@tab IIIB–C\n- N3 hoặc T3–4N2; OS 5 năm ==3–7%==; đa số không khỏi bằng mổ {{Y5 tr.119}}.\n- {g|Theo QĐ4825:} hóa-xạ trị đồng thời là chuẩn cho III không mổ được, ECOG 0–1, sụt cân ≤5%; xạ 1 phân liều/ngày, tổng 60 Gy (74 Gy cho sống còn thấp hơn 60 Gy); platin + taxane hoặc vinorelbine; cetuximab, gefitinib chưa rõ vai trò; lợi ích sống còn tuyệt đối 3 năm 6% {{QĐ4825 tr.12}}. Phác đồ đồng thời: cisplatin + etoposide; cisplatin + vinblastine; carboplatin hoặc cisplatin + pemetrexed (không tế bào vẩy); paclitaxel tuần + carboplatin AUC 2 (không tế bào vẩy) {{QĐ4825 tr.16–17}}.\n- PS 0–1, sụt cân <5%: **hóa-xạ trị đồng thời** phác đồ platinum (etoposide, vinblastine, paclitaxel + cisplatin/carboplatin; chưa phác đồ nào vượt trội); ASCO: 2–4 chu kỳ, 2 chu kỳ đồng thời với xạ. {{Y5 tr.119}}\n- Củng cố sau hóa-xạ: **durvalumab** 10 mg/kg TM mỗi 2 tuần đến 12 tháng, khi chưa tiến triển sau 2 chu kỳ hóa-xạ đồng thời {{QĐ4825 tr.17}}. Y5 ghi **miễn dịch** {{Y5 tr.116}} hoặc **hóa trị** {{Y5 tr.119}}; ghi nhớ cả hai. Không hóa trị được: xạ trị.\n@@tab IV / tái phát\n- Chăm sóc giảm nhẹ đơn thuần: trung vị 16–17 tuần; hóa trị nâng OS 1 năm từ 10–15% lên >35% {{Y5 tr.120}}.\n- {g|Bước một theo QĐ4825} (tr.14, 17): EGFR hoạt động → gefitinib 250 mg/ngày, erlotinib 150 mg/ngày, afatinib 40 mg/ngày hoặc osimertinib 80 mg/ngày, dùng đến khi tiến triển; T790M (+) sau TKI → osimertinib. ALK → crizotinib, ceritinib hoặc alectinib; BRAF V600E → dabrafenib + trametinib; PD-L1 >50% không có đột biến đích → pembrolizumab {{QĐ4825 tr.14–17}}. Không có đột biến: hóa trị platin theo mô học; tuyến thêm bevacizumab nếu u ngoại biên, không ho ra máu, không hủy hang trung tâm, không xâm lấn mạch lớn {{QĐ4825 tr.14}}.\n- Bước một chọn theo tuổi, tổng trạng, bệnh kèm, bất thường gen, mô học (xem bảng ở 7.3).\n- Di căn xương/não (theo QĐ4825): acid zoledronic 4 mg TM mỗi 2–4 tuần, xạ tại chỗ; di căn não: xạ dao gamma ± xạ toàn não (20 Gy/5 hoặc 30 Gy/10 buổi) {{QĐ4825 tr.15}}.\n- **Duy trì** sau đáp ứng/không tiến triển: pemetrexed (không tế bào gai), bevacizumab, gemcitabine, cetuximab; erlotinib (lợi nhất ở EGFR đột biến). **Bước hai:** docetaxel, pemetrexed, erlotinib; miễn dịch (nivolumab, pembrolizumab, atezolizumab) hơn docetaxel; bước sau theo đích QĐ4825: osimertinib (EGFR sau TKI), alectinib/brigatinib/ceritinib (ALK) {{QĐ4825 tr.17}}. **Bước ba:** erlotinib, thử nghiệm lâm sàng, giảm nhẹ {{Y5 tr.120–123}}.\n@@end\n@@tab NSCLC: tóm tắt (QĐ4825, Y5)\n| Giai đoạn | Điều trị (QĐ4825 ưu tiên; Y5 khi QĐ4825 không nêu) {{QĐ4825 tr.10–17}} {{Y5 tr.116–117}} |\n|---|---|\n| I | Mổ (cắt thùy/cắt phổi; hình chêm chỉ u ngoại biên <3 cm, AIS/MIA); xạ nếu không mổ được |\n| II | Mổ + hóa trị hỗ trợ cisplatin (QĐ4825: từ IB); xạ sau mổ chỉ khi nguy cơ cao |\n| IIIA | Hóa trị tân bổ trợ rồi mổ; hoặc hóa-xạ đồng thời ± củng cố durvalumab |\n| IIIB–C | Hóa-xạ đồng thời platin (ECOG 0–1) rồi củng cố durvalumab (QĐ4825); Y5: củng cố miễn dịch hoặc hóa trị |\n| IV | Không đột biến: platin theo mô học; **EGFR**: TKI (osimertinib, ...); **ALK**: crizotinib, ceritinib, alectinib; **BRAF V600E**: dabrafenib + trametinib; **PD-L1 >50%**: pembrolizumab |\n@@end\n\n@@tabs\n@@tab NSCLC: nội dung ngoài tài liệu\n> [!ext] **Không có trong QĐ4825 hay Y5.** Theo các hướng dẫn công khai (NCI PDQ, ESMO, ASCO, StatPearls), diễn đạt lại: (1) ALK dùng thuốc thế hệ mới như lorlatinib (QĐ4825 chưa nêu); (2) giai đoạn IV không đột biến, PD-L1 thấp: **pembrolizumab ± hóa trị** (QĐ4825 chỉ nêu pembrolizumab bước một khi PD-L1 >50%; pembrolizumab + carboplatin/pemetrexed có cho u tuyến thể trạng tốt, tr.17); (3) giai đoạn sớm có đột biến EGFR/PD-L1 có thể dùng đích/miễn dịch hỗ trợ sau mổ (QĐ4825 không nêu). **Mâu thuẫn:** Y5 ghi erlotinib, gefitinib, crizotinib; QĐ4825 có thêm osimertinib, alectinib, ceritinib; nêu cả hai. {{+NCI PDQ}} {{+ESMO}} {{QĐ4825 tr.14–17}}\n@@end\n\n#### SCLC\n@@tabs\n@@tab Nguyên tắc\n- Hóa trị + xạ trị chủ yếu; **hóa trị chủ đạo** vì tiến triển nhanh và nhạy hóa chất; hóa chất giảm tái phát, di căn xa, kéo dài sống. Thuốc đích (erlotinib, gefitinib) hiệu quả kém hơn NSCLC {{QĐ1514 tr.PDF 247}}.\n- **Phẫu thuật không là điều trị chuẩn** {{Y5 tr.124}}; QĐ1514: chỉ giai đoạn **I–IIA (T1–2N0M0)** cắt thùy + vét hạch trung thất. Hạch di căn: hóa + xạ sau mổ; không: hóa trị {{QĐ1514 tr.PDF 247}}.\n- Chẩn đoán tình cờ sau mổ: hóa trị cisplatin + xạ dự phòng não {{Y5 tr.124}}.\n@@tab Xạ trị\n- **Dự phòng di căn não:** chỉ định IIB–IV có đáp ứng toàn thân; {r|CCĐ: thể trạng yếu, suy giảm nhận thức TKTW}; ==25 Gy/10 buổi== (lan tràn có thể 20 Gy/5 buổi); dùng **memantine** (tuần 1: 5 mg sáng; tuần 2: 5 mg sáng, tối; tuần 3: 10 mg sáng, 5 mg tối; tuần 4: 10 mg sáng, tối) {{QĐ1514 tr.PDF 247–248}}.\n- **Lồng ngực, khu trú:** hóa-xạ **đồng thời** là chuẩn; xạ sớm ngay chu kỳ 1–2; PET/CT mô phỏng; ==60–70 Gy, 2 Gy/lần, 1 lần/ngày==; xạ định vị cắt bỏ cho I–IIA rồi hóa chất. {{QĐ1514 tr.PDF 248}}\n- **Lan tràn:** khi đáp ứng hoàn toàn/tốt: 30 Gy/10 buổi hoặc 60 Gy/30 buổi. {{QĐ1514 tr.PDF 248}}\n@@tab Hóa trị – miễn dịch\n- Hóa trị mọi giai đoạn; khu trú đồng thời hoặc tuần tự tùy thể trạng; đánh giá đáp ứng sau **2–3 chu kỳ** {{QĐ1514 tr.PDF 248}}.\n- {r|CCĐ hóa trị:} PS 3–4, suy gan, suy thận. {{QĐ1514 tr.PDF 249}}\n- **Miễn dịch:** atezolizumab (kháng PD-L1; lan tràn, kết hợp hóa chất + duy trì); nivolumab, ipilimumab (giai đoạn IV sau thất bại platin); pembrolizumab (lan tràn sau thất bại hóa chất, PD-L1 CPS ≥1) {{QĐ1514 tr.PDF 252–253}}.\n@@tab Di căn & đặc biệt\n- **Di căn xương:** xạ ngoài 30 Gy/10, 40 Gy/20, 20 Gy/5 hoặc 8 Gy/1 buổi; hoặc xạ trong (P-32, Sr-89, Sm-153).\n- **Di căn não:** ưu tiên xạ toàn não 30 Gy/10 buổi (Y5: 20–37,5 Gy/5–15 phân liều; sau xạ dự phòng: 20 Gy/10); **dao gamma** 16–24 Gy nếu ≤3 tổn thương, mỗi tổn thương ≤3 cm {{QĐ1514 tr.PDF 253}} {{Y5 tr.124}}.\n- Điều trị không đặc hiệu: kháng sinh/giảm ho khi bội nhiễm, chống xuất tiết, nâng thể trạng.\n@@end\n\n### 7.3 Phác đồ – Y lệnh\n\n@@tabs\n@@tab NSCLC (QĐ4825 + Y5)\n> [!warn] **QĐ 4825/QĐ-BYT (2018) là văn bản BYT cho NSCLC; bảng dưới ưu tiên QĐ4825, phần còn lại theo Y5 (giáo trình).** Y5 **không phải y lệnh chính thức BYT**. QĐ1514 chỉ nhắc cặp thuốc NSCLC trong bảng nguy cơ giảm bạch cầu, không phải phác đồ điều trị {{QĐ1514 tr.PDF 32–33}} {{QĐ4825 tr.14–18}}.\n\n| Tình huống (giai đoạn IV) | Thuốc – liều | Chu kỳ / cách dùng | Chỉ định | Ghi chú |\n|---|---|---|---|---|\n| Đột biến **EGFR** hoạt động | {p|Gefitinib 250 mg/ngày; erlotinib 150 mg/ngày; afatinib 40 mg/ngày; osimertinib 80 mg/ngày} (uống) | Đến khi tiến triển | Bước một | Ban da, tiêu chảy. T790M (+) sau TKI: osimertinib. Y5 chỉ nêu erlotinib, gefitinib; IPASS gefitinib đáp ứng 43% vs 32,2% {{QĐ4825 tr.14}} {{Y5 tr.119–123}} |\n| Chuyển vị **ALK** | {p|Alectinib, ceritinib, crizotinib} (Y5 chỉ nêu crizotinib) | Không nêu | Bước một | Y5: đáp ứng >50% với crizotinib (pha I). ROS1: ceritinib, crizotinib {{QĐ4825 tr.14}} {{QĐ4825 tr.17}} {{Y5 tr.119–123}} |\n| Không đột biến đích, thể trạng tốt | {p|Cặp platin} theo mô học: tuyến gồm nhiều cặp với pemetrexed, docetaxel, etoposide, gemcitabine, paclitaxel (albumin-bound), vinorelbine; tế bào vẩy gồm cặp với gemcitabine, docetaxel, paclitaxel, etoposide {{QĐ4825 tr.17–18}} | **4–6 chu kỳ** (Y5) | Bước một | Y5: các phác đồ tương đương; thêm thuốc thứ ba không lợi {{Y5 tr.119–123}} |\n| Carcinôm **tuyến** | {p|Cisplatin + pemetrexed} | 4–6 chu kỳ (Y5) | Bước một | OS 12,6 vs 10,9 tháng so với cis-gemcitabine (Y5). QĐ4825 tr.17 thêm pembrolizumab + carboplatin + pemetrexed cho thể trạng tốt {{QĐ4825 tr.17}} {{Y5 tr.119–123}} |\n| Carcinôm **tế bào gai** | {p|Cisplatin + gemcitabine} | 4–6 chu kỳ (Y5) | Bước một | OS 10,8 vs 9,4 tháng (Y5). Các cặp platin khác theo QĐ4825 tr.17 (paclitaxel, docetaxel, etoposide) {{QĐ4825 tr.17}} {{Y5 tr.119–123}} |\n| Carcinôm **không tế bào vẩy** | Thêm {p|bevacizumab} (kháng VEGF) | Cùng hóa trị | Bước một | Y5: OS 12,3 vs 10,3 tháng (ECOG 4599); {r|nguy cơ tử vong liên quan điều trị, ho ra máu}. QĐ4825: chỉ khi u ngoại biên, không ho ra máu, không hủy hang trung tâm, không xâm lấn mạch lớn {{QĐ4825 tr.14}} {{Y5 tr.119–123}} |\n| EGFR (+) trên mô, PS 0–1 | {p|Cetuximab} | Cùng hóa trị | Tùy chọn | FLEX 11,3 vs 10,1 tháng; BMS099 không khác biệt |\n| **PD-L1 >50%**, không có đột biến đích (~1/3) | {p|Pembrolizumab} | Bước một | Miễn dịch | {{QĐ4825 tr.14}} {{Y5 tr.116–117}} |\n| Duy trì | Pemetrexed (không gai), bevacizumab, gemcitabine, cetuximab, erlotinib | Sau đáp ứng/không tiến triển | Duy trì | Erlotinib lợi nhất ở EGFR đột biến |\n| Bước hai | {p|Docetaxel 75 mg/m2 TM mỗi 21 ngày}; {p|pemetrexed 500 mg/m2 mỗi 21 ngày} (không gai); {p|erlotinib 150 mg/ngày} | PS 0–2 | Sau thất bại | Pemetrexed tương đương docetaxel, ít tác dụng phụ |\n| Bước sau theo đích (QĐ4825) | {p|Osimertinib} (EGFR sau TKI); {p|alectinib, brigatinib, ceritinib} (ALK) | Không nêu | Sau thất bại | Bảng QĐ4825 (bố cục bản quét không rõ) {{QĐ4825 tr.17}} |\n| Miễn dịch bước hai | Nivolumab, pembrolizumab (PD-1), atezolizumab (PD-L1) {{QĐ4825 tr.17}} | Theo thử nghiệm | Sau thất bại | Hơn docetaxel về sống còn (Y5) |\n*Nguồn: {{QĐ4825 tr.14, 17–18}} (ưu tiên khi có); {{Y5 tr.119–123}} (phần còn lại). Liều chỉ ghi khi văn bản nêu.*\n\n> [!warn] Theo dõi: tác dụng phụ EGFR TKI (ban da, tiêu chảy); bevacizumab: nguy cơ tử vong liên quan điều trị cao hơn {{Y5 tr.121}}, chỉ cân nhắc khi u ngoại biên, không ho ra máu, không xâm lấn mạch lớn {{QĐ4825 tr.14}}; xét nghiệm đột biến/PD-L1 **trước** khi chọn thuốc bước một. Liều EGFR-TKI lấy từ QĐ4825 {{QĐ4825 tr.14}}; liều pembrolizumab, nivolumab, atezolizumab không có trong QĐ4825 hay Y5: tài liệu không nêu.\n@@tab SCLC (QĐ1514 Bài 33)\n> [!doc] **QĐ 1514/QĐ-BYT (01/04/2020), Bài 33 \"Ung thư phổi tế bào nhỏ\", tr. PDF 242–254** (phác đồ tr. 249–253). Bảng đọc từ văn bản; khi ôn thi đối chiếu lại trang gốc.\n\n**Khu trú (4–6 chu kỳ, kết hợp đồng thời hoặc tuần tự với xạ; chu kỳ 28 ngày)** {{QĐ1514 tr.PDF 249}}\n| Phác đồ | Thuốc – liều | Chu kỳ | Chỉ định | Ghi chú |\n|---|---|---|---|---|\n| EP (1) | {p|Cisplatin 75 mg/m2} TM ngày 1 + {p|etoposide 100 mg/m2} TM ngày 1–3 | 28 ngày | Khu trú | Phác đồ chuẩn |\n| EP (2) | Cisplatin 25 mg/m2 ngày 1–3 + etoposide 100 mg/m2 ngày 1–3 | 28 ngày | Khu trú | |\n| EP (3) | Cisplatin 60 mg/m2 ngày 1 + etoposide 120 mg/m2 ngày 1–3 | 28 ngày | Khu trú | |\n| Carbo-E | {p|Carboplatin AUC 5–6} ngày 1 + etoposide 100 mg/m2 ngày 1–3 | 28 ngày | Khu trú | Thay cisplatin (người yếu) |\n\n**Lan tràn (4–6 chu kỳ)** {{QĐ1514 tr.PDF 250–251}}\n| Phác đồ | Thuốc – liều | Chu kỳ | Chỉ định | Ghi chú |\n|---|---|---|---|---|\n| **Carbo-E + atezolizumab** | Carboplatin AUC 5 ngày 1; etoposide 100 mg/m2 ngày 1–3; {p|atezolizumab 1.200 mg} TM ngày 1 | 21 ngày x 4 | Lan tràn | Sau đó **duy trì atezolizumab 1.200 mg** mỗi 21 ngày |\n| Carbo-E | AUC 5–6 ngày 1; etoposide 100 mg/m2 ngày 1–3 | 28 ngày | Lan tràn | |\n| Cis-E | Cisplatin 75 + etoposide 100; hoặc 80/80; hoặc 25 (ngày 1–3)/100 (ngày 1–3) mg/m2 | 28 ngày | Lan tràn | |\n| Irinotecan + cisplatin | Irinotecan 60 mg/m2 ngày 1, 8, 15 + cisplatin 60 mg/m2 ngày 1; hoặc irinotecan 65 ngày 1, 8 + cisplatin 30 ngày 1, 8 | 28 ngày | Lan tràn | |\n| Irinotecan + carboplatin | Irinotecan 50 mg/m2 ngày 1, 8, 15 + carboplatin AUC 5 ngày 1 | 28 ngày | Lan tràn | |\n| CAV | Cyclophosphamide 1.000 + doxorubicin 45 + vincristine 1,4 mg/m2 ngày 1 | 21 ngày | Lan tràn | |\n| CAE | Cyclophosphamide 1.000 + doxorubicin 45 mg/m2 ngày 1 + etoposide 80–100 mg/m2 ngày 1–3 (hoặc 1, 3, 5) | 21 ngày | Lan tràn | |\n| CEV | Cyclophosphamide 1.000 + epirubicin 70 + vincristine 2 mg/m2 ngày 1 | 21 ngày | Lan tràn | |\n| ICE | Ifosfamide 5.000 mg/m2 TM 24 giờ ngày 1 (mesna) + carboplatin 300 ngày 1 + etoposide 120 ngày 1, 2 và 240 ngày 3 + vincristine 1,0 ngày 15 | 28 ngày | Lan tràn | |\n| VIP | Etoposide 75 + ifosfamide 1.200 (mesna) + cisplatin 20 mg/m2, ngày 1–4 | Theo nguồn: tài liệu không ghi chu kỳ | Lan tràn | |\n\n**Tái phát** {{QĐ1514 tr.PDF 251–252}}\n| Tình huống | Phác đồ |\n|---|---|\n| ≤6 tháng, PS 0–1 | CAV; CAE; hoặc topotecan 1,0 mg/m2 ngày 1–5 + cisplatin 60 mg/m2 ngày 1 (21 ngày) |\n| Đơn chất | Topotecan 1,0–1,5 mg/m2 TM ngày 1–5 (21 ngày) hoặc 2,3 mg/m2 uống; irinotecan 300 mg/m2 (21 ngày) hoặc 100 mg/m2 hàng tuần; paclitaxel 175–250 mg/m2 24 giờ ngày 1, 8, 15 hoặc 80 mg/m2 hàng tuần x 6 tuần nghỉ 2 tuần; docetaxel 100 mg/m2 (3 tuần); temozolomide 75 mg/m2 uống (4 tuần); vinorelbine 25–30 mg/m2 hàng tuần; etoposide uống 50 mg/m2 (4–5 tuần); gemcitabine 1.000 mg/m2 ngày 1, 8, 15 (4 tuần) |\n| >6 tháng | Dùng lại như phác đồ ban đầu |\n| PS = 2 | Giảm liều hoặc dùng yếu tố kích thích tủy |\n\n**Miễn dịch** {{QĐ1514 tr.PDF 252–253}}\n| Thuốc | Cơ chế | Chỉ định – cách dùng |\n|---|---|---|\n| {p|Atezolizumab} | Kháng PD-L1 | Lan tràn; 1.200 mg TM mỗi 3 tuần; kết hợp hóa chất rồi duy trì |\n| {p|Nivolumab} (*) | Kháng PD-1 | Giai đoạn IV sau thất bại platin; đơn chất 3 mg/kg mỗi 2 tuần; phối hợp ipilimumab: nivolumab 1 + ipilimumab 3 mg/kg (hoặc 3 + 1) mỗi 3 tuần x 4, rồi nivolumab 3 mg/kg mỗi 2 tuần |\n| {p|Ipilimumab} (*) | Kháng CTLA-4 | Giai đoạn IV sau thất bại platin; phối hợp nivolumab |\n| {p|Pembrolizumab} | Nguồn ghi \"kháng PD-L1\" (nguyên văn) | Lan tràn, sau thất bại hóa chất, PD-L1 dương (CPS ≥1); 200 mg mỗi 3 tuần |\n(*) Dấu sao trong nguồn.\n\n> [!warn] Hóa trị SCLC: {r|CCĐ PS 3–4, suy gan, suy thận}; đánh giá đáp ứng sau 2–3 chu kỳ; PS=2 giảm liều hoặc yếu tố kích thích tủy. Theo dõi sau điều trị: **3 tháng/lần trong 2 năm đầu, sau đó 6 tháng/lần** {{QĐ1514 tr.PDF 254}}. Tác dụng phụ cần nhớ (cisplatin: độc thận, nôn; irinotecan: tiêu chảy; ifosfamide: viêm bàng quang, dùng mesna) là kiến thức ngoài văn bản, xem sách dược.\n\n**Xử trí cấp cứu liên quan UT phổi (QĐ1514 Bài 9–10)** {{QĐ1514 tr.PDF 64–70}}\n@@fold! Ho ra máu do ung thư (Bài 9)\n| Mức độ | Lượng | Xử trí |\n|---|---|---|\n| Ít | <50 ml/24 giờ | Nghỉ yên, diazepam, acid tranexamic |\n| Trung bình | 50–200 ml/24 giờ | Glanduitrine **tiêm bắp** ({r|không tiêm TM: co thắt mạch não}), morphin, sandostatin, dịch cao phân tử/truyền máu (HA tối đa không <110 mmHg) |\n| Nặng | >200 ml/24 giờ (>500 ml nguy kịch) | Đường truyền, nằm **Trendelenburg sang bên chảy máu**, oxy/đặt NKQ, truyền máu, vận mạch, vasopressin/glypressin, soi phế quản cầm máu, **nút ĐM phế quản** (>200 ml, thất bại nội khoa), mổ cấp cứu khi đủ điều kiện |\n| Sét đánh | Đột ngột, lượng lớn, ngạt thở, sốc | Cấp cứu hồi sức tích cực |\n- Ngưỡng glanduitrine: QĐ1514 ghi dùng khi >150 ml, trong khi bảng trên xếp trung bình 50–200 ml; nêu cả hai. {{QĐ1514 tr.PDF 64–65}}\n- Nguyên tắc: **xử trí triệu chứng trước, ổn định rồi điều trị nguyên nhân**. CCĐ mổ: UT phổi giai đoạn không mổ được hoặc chức năng hô hấp kém. Chi tiết liều: xem tr. PDF 65–67.\n@@end\n@@fold Chèn ép TM chủ trên (Bài 10)\n- NSCLC: **đặt stent trước**, rồi xạ đơn thuần hoặc phối hợp hóa trị, đích, miễn dịch. SCLC: nhạy hóa chất, hóa trị ngay theo phác đồ (có thể đặt stent trước) {{QĐ1514 tr.PDF 70}}.\n@@end\n@@end\n\n## 8. Tiên lượng – Dự phòng\n\n### Tiên lượng và sống còn\n- >70% NSCLC chẩn đoán muộn; OS 5 năm ==18,5%== (so với 13,7% những năm 1970). SCLC: không điều trị trung vị ==2–4 tháng==, OS 5 năm ==5–10%==; xấu hơn NSCLC {{Y5 tr.104}} {{QĐ1514 tr.PDF 242}}.\n- Yếu tố xấu: giai đoạn muộn (**quan trọng nhất**), tuổi già, nam giới, sụt cân, tổng trạng kém.\n\n| Giai đoạn | OS 5 năm (Y5 Bảng 4) |\n|---|---|\n| 0 | 100% |\n| IA1 / IA2 / IA3 | 92% / 83% / 77% |\n| IB / IIA / IIB | 68% / 60% / 53% |\n| IIIA / IIIB / IIIC | 36% / 26% / 13% |\n| IVA / IVB | 10% / 0% |\n{{Y5 tr.114}}\n\n> [!warn] **Y5 tự mâu thuẫn:** Bảng 4 ghi IIIA ==36%==, nhưng phần điều trị ghi IIIA (N2) ==24%==; giai đoạn I 58–73%, II 36–46%, IIIB–C 3–7% (khác Bảng 4) {{Y5 tr.114, 117–119}}. Ghi nhớ cả hai, nêu rõ nguồn.\n\n@@tabs\n@@tab Yếu tố tiên lượng\n| Nhóm | Thiết yếu | Phụ trợ |\n|---|---|---|\n| NSCLC mổ được | T, N, xâm lấn ngoài vỏ hạch; sụt cân, tổng trạng; R0/R1/R2; mức nạo hạch | Mô học, grad, xâm lấn mạch, kích thước; giới |\n| NSCLC tiến xa | Giai đoạn, tắc TM chủ trên, số vị trí di căn; sụt cân, tổng trạng; hóa trị, đích | TDMP, di căn gan, Hb, LDH, albumin |\n| SCLC | Giai đoạn; tổng trạng, tuổi, bệnh kèm; hóa trị, xạ trị, xạ dự phòng não | LDH, ALP, Cushing, hạch trung thất, số vị trí di căn, di căn não/xương, bạch cầu, tiểu cầu |\n{{Y5 tr.114–116}}\n@@end\n\n### Theo dõi sau điều trị\n- Nhiều ca tái phát tại chỗ hoặc di căn xa, hiếm khi khỏi; mục đích: phát hiện bướu tái phát khi còn nhỏ, còn điều trị được {{Y5 tr.124}}.\n| Nhóm | Lịch theo dõi |\n|---|---|\n| NSCLC giai đoạn sớm | Y5: khám 3–6 tháng; CT ngực cản quang mỗi 6 tháng trong 2 năm, sau đó mỗi năm {{Y5 tr.124}}. QĐ4825: mỗi 2 tháng năm đầu, mỗi 3 tháng 2 năm sau, mỗi 6 tháng từ năm thứ 4 {{QĐ4825 tr.15}}. **Mâu thuẫn, nêu cả hai.** |\n| NSCLC giai đoạn III | Y5: CT mỗi 3–6 tháng trong 2 năm đầu, thưa hơn sau; mỗi năm sau 5 năm {{Y5 tr.124}}. QĐ4825 (IIIA/IIIB, tiến xa tại chỗ): mỗi 2 tháng năm đầu, mỗi 3 tháng các năm sau {{QĐ4825 tr.15}}. **Mâu thuẫn, nêu cả hai.** |\n| NSCLC giai đoạn IV | Y5: CT mỗi 2–3 chu kỳ hóa trị; **không có vai trò PET-CT**; mỗi 3 tháng khi duy trì {{Y5 tr.124}}. QĐ4825 (di căn): mỗi tháng năm đầu, mỗi 2 tháng các năm sau {{QĐ4825 tr.15}}. **Mâu thuẫn, nêu cả hai.** |\n| SCLC (QĐ1514) | **3 tháng/lần trong 2 năm đầu, rồi 6 tháng/lần** {{QĐ1514 tr.PDF 254}} |\n\n### Dự phòng\n- **Cấp 1:** không hút thuốc lá, thuốc lào (hiệu quả nhất; >90% ca không mắc nếu không hút); khuyên người đang hút ngưng hút; tránh phóng xạ, bụi, khói, amiăng, radon; ăn rau quả {{Y5 tr.105}} {{QĐ1514 tr.PDF 254}}. Bổ sung vitamin/khoáng không có hiệu quả {{Y5 tr.105}}.\n- **Cấp 2 (tầm soát):** X quang phổi ± tế bào học đàm **không giảm tử vong**; **CT liều thấp** có thể có lợi ở nhóm nguy cơ cao {{Y5 tr.106}}.\n\n| Chương trình Hoa Kỳ (Y5) | Nội dung |\n|---|---|\n| Đối tượng | ==55–74 tuổi==, hút ≥==30 gói-năm== hoặc ngưng hút <15 năm |\n| Phương tiện | CT liều thấp (2 mSv, thấp hơn chuẩn 7 mSv) |\n| Thời gian | Hàng năm đến 74 tuổi |\n| Kết quả NLST (53.454 người) | Giảm **20%** tử vong do UT phổi (247 vs 309/100.000 ca-năm; p=0,004); tử vong chung giảm 6,7% |\n{{Y5 tr.106}}\n\nQĐ4825 (BYT) mục 6.1: CT liều thấp 1,5 mSv (so với 8 mSv) cho người nguy cơ cao (lớn tuổi, hút trên 30 gói-năm); Y5 ghi 2 mSv (chuẩn 7 mSv). **Nêu cả hai.** {{QĐ4825 tr.15}}\n\n> [!ext] **USPSTF 2021:** mở rộng đối tượng tầm soát LDCT hằng năm: **50–80 tuổi**, hút ≥**20 gói-năm**, đang hút hoặc ngưng <15 năm (khác Y5: 55–74 tuổi, 30 gói-năm). {{+USPSTF 2021}}\n\n- **Cấp 3:** theo dõi tái phát, chăm sóc giảm nhẹ, hỗ trợ cai thuốc.\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] Thi UT phổi nhấn mạnh gì\n> - Đề cương: **nguyên tắc chẩn đoán** nặng nhất (~40%), rồi **xử trí** (~20%); QĐ 22: dòng 3 cận lâm sàng/XN chẩn đoán 45–60, dòng 7 liệu pháp thuốc 35–50 (văn bản không nói rõ là trọng số dòng hay nhóm). Khung: [STT 40](#/khung/40), [41](#/khung/41), [46](#/khung/46), [47](#/khung/47).\n> - Câu hỏi từ mức Áp dụng: gặp **ho ra máu, bất thường X quang ngực, TDMP, nốt phổi** thì nghĩ gì, chỉ định gì, làm gì.\n> - Luôn tách **NSCLC** và **SCLC**. Cả hai có văn bản BYT: NSCLC QĐ 4825/QĐ-BYT (2018) {{QĐ4825 tr.1–18}} (chi tiết ở mục 7); SCLC QĐ1514 Bài 33 {{QĐ1514 tr.PDF 242–254}}.\n\n@@tabs\n@@tab Nhận diện\n- Nguy cơ then chốt: **thuốc lá** (==~90%== ca, ==gấp 20 lần==); radon, amiăng, nghề nghiệp {{Y5 tr.105}} {{QĐ1514 tr.PDF 246}}.\n- {o|Không có triệu chứng đặc hiệu}, thường muộn; gợi ý: nam >40, hút thuốc, ho khan kéo dài, kháng sinh không đáp ứng {{QĐ1514 tr.PDF 242}}.\n- Trung tâm: ho, **ho ra máu**, khó thở, viêm phổi tắc nghẽn. Ngoại vi: đau ngực, ho. Pancoast: đau vai {{Y5 tr.109–112}}.\n- Chèn ép: khàn tiếng (quặt ngược), **Horner**, phù áo khoác (TM chủ trên), nuốt nghẹn.\n- Cận u: SCLC = **SIADH**; tế bào gai = **tăng canxi máu**; ngón tay dùi trống {{Y5 tr.106–107}}.\n- {r|Báo động:} ho ra máu >200 ml/24 giờ, chèn ép TM chủ trên, chèn ép tủy, tăng áp lực nội sọ.\n- Nốt/khối ở người hút thuốc không tan sau kháng sinh 1 tháng: nghĩ ung thư.\n\n[xem mục 4](#/n/ung-thu-phoi/4)\n@@tab Chẩn đoán\n- **Xác định = giải phẫu bệnh** (NSCLC hay SCLC); sau đó xếp giai đoạn; NSCLC muộn thêm đột biến + PD-L1 {{Y5 tr.110}}.\n- Đầu tay: **X quang ngực**, rồi **CT ngực-bụng cản quang**; nội soi phế quản (==97%== GPB u trung tâm); u ngoại vi: sinh thiết xuyên thành ngực dưới CT.\n- Xếp giai đoạn/trước mổ: **PET-CT + soi trung thất**; CT/MRI sọ khi có triệu chứng, không MRI thường quy; FEV1 trước mổ.\n- Phân tử NSCLC: **EGFR, ALK, ROS1, NTRK, PD-L1**; dấu ấn SCLC: NSE, CEA, ProGRP.\n- TNM lần 8: T1 ≤3 cm; T2 >3–5; T3 >5–7; T4 >7 cm hoặc xâm lấn; TDMP ác tính = **M1a**; SCLC: **khu trú** (một trường xạ) vs **lan tràn**.\n- Nốt phổi đơn độc ==<3 cm==: xem phim cũ (ổn định 2 năm), PET-CT nhạy ==96%==/đặc hiệu ==75%==; tăng kích thước thì sinh thiết {{Y5 tr.110–111}}.\n- CĐPB: viêm phổi/áp xe (chụp lại sau KS 1 tháng), **lao** (AFB/Xpert; có thể cùng tồn tại), TDMP khác, u lành, di căn phổi.\n\n[xem mục 6](#/n/ung-thu-phoi/6)\n@@tab Điều trị\n- {g|NSCLC I–II:} **cắt thùy/cắt phổi** + nạo hạch trung thất; {r|Y5: không cắt phân thùy/hình chêm}; QĐ4825 chấp nhận hình chêm u ngoại biên <3 cm AIS/MIA; hóa trị hỗ trợ: {r|Y5 không ở I}, lựa chọn ở II, QĐ4825 từ IB (mâu thuẫn, nêu cả hai); không mổ: xạ, SBRT <5 cm {{Y5 tr.117–118}} {{QĐ4825 tr.10–11}}.\n- {g|NSCLC IIIA:} N2 tình cờ: mổ + hóa trị hỗ trợ ({r|Y5 không khuyến cáo xạ sau mổ}; QĐ4825 tr.11 thường chỉ định xạ khi nguy cơ cao tái phát; mâu thuẫn, nêu cả hai); N2 lớn/soi trung thất: **hóa-xạ đồng thời** ± củng cố miễn dịch {{Y5 tr.118}} {{QĐ4825 tr.11}}.\n- {g|NSCLC IIIB–C:} hóa-xạ đồng thời platinum (PS 0–1).\n- {g|NSCLC IV:} {p|EGFR TKI} (EGFR), {p|crizotinib} (ALK), {p|pembrolizumab} (PD-L1 >50%); không đột biến: cặp platin 4–6 chu kỳ; tuyến: {p|cisplatin + pemetrexed}; gai: {p|cisplatin + gemcitabine}; thêm {p|bevacizumab} (không gai) {{Y5 tr.119–123}}.\n- {g|SCLC khu trú:} {p|cisplatin 75 mg/m2 ngày 1 + etoposide 100 mg/m2 ngày 1–3}, 28 ngày, 4–6 chu kỳ + xạ ngực đồng thời (60–70 Gy); mổ chỉ I–IIA. {g|SCLC lan tràn:} {p|carbo-etoposide + atezolizumab 1.200 mg} 21 ngày x 4, duy trì atezolizumab {{QĐ1514 tr.PDF 247–250}}.\n- **Xạ dự phòng não** (đáp ứng): ==25 Gy/10 buổi== + memantine; {r|CCĐ hóa trị PS 3–4, suy gan, suy thận}.\n- {r|Ho ra máu:} triệu chứng trước; nặng >200 ml: Trendelenburg bên chảy máu, hồi sức, nút ĐM phế quản; {r|glanduitrine không tiêm TM đẩy}; tiêm bắp hoặc truyền TM pha loãng 200 ml {{QĐ1514 tr.PDF 64–67}}.\n- {r|Chèn ép TM chủ trên:} NSCLC đặt stent rồi xạ ± hóa; SCLC hóa trị ngay {{QĐ1514 tr.PDF 70}}.\n\n> [!warn] **Thuốc mới NSCLC:** osimertinib (EGFR sau TKI) và durvalumab (củng cố sau hóa-xạ) có trong QĐ4825 {{QĐ4825 tr.17}}; phần còn lại theo Y5 khi QĐ4825 không nêu.\n\n[xem mục 7.3](#/n/ung-thu-phoi/7)\n@@tab Tiên lượng – Dự phòng\n- Yếu tố tiên lượng quan trọng nhất: **giai đoạn**; >70% NSCLC phát hiện muộn.\n- OS 5 năm toàn bộ ==18,5%==; SCLC không điều trị ==2–4 tháng==, 5 năm ==5–10%==.\n- Bảng 4 Y5: IA 77–92%, IIIA ==36%==, IIIB 26%, IVA 10%, IVB 0%.\n- Theo dõi: SCLC **3 tháng/lần x 2 năm, rồi 6 tháng/lần**; NSCLC sớm CT mỗi 6 tháng x 2 năm {{QĐ1514 tr.PDF 254}}.\n- Dự phòng cấp 1: **không hút thuốc**, tránh radon/amiăng; vitamin/khoáng không hiệu quả.\n- Tầm soát: X quang không giảm tử vong; **CT liều thấp** (Y5: 55–74 tuổi, ≥30 gói-năm) giảm 20% tử vong; QĐ4825 (BYT) mục 6.1 cũng nêu CT liều thấp cho nhóm nguy cơ cao.\n\n[xem mục 8](#/n/ung-thu-phoi/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Nguy cơ hút thuốc / tỉ lệ ca do thuốc lá | ==gấp 20 lần==; ==~90%== | {{Y5 tr.105}} {{QĐ1514 tr.PDF 246}} |\n| SCLC vị trí / hội chứng cận u | trung tâm ==95%==; SIADH | {{Y5 tr.106}} |\n| Tuyến / tế bào gai (trong NSCLC) | ==50–60%== / ==20–25%== | {{Y5 tr.107}} |\n| Nốt phổi đơn độc | ==<3 cm==; ổn định ==2 năm== | {{Y5 tr.110}} |\n| PET-CT: nhạy / đặc hiệu | ==96%== / ==75%== | {{Y5 tr.110}} |\n| Nội soi phế quản chẩn đoán GPB u trung tâm | ==97%== | {{Y5 tr.110}} |\n| FEV1 cắt phổi / thùy / phân thùy | ==2 L / 1 L / 0,6 L== | {{Y5 tr.112}} |\n| TDMP ác tính | ==M1a (IVA)== | {{Y5 tr.113}} |\n| SBRT không mổ được | bướu ==<5 cm== | {{Y5 tr.118}} |\n| OS 5 năm IIIA / IIIB / IIIC (Bảng 4) | ==36% / 26% / 13%== | {{Y5 tr.114}} |\n| EP khu trú | ==Cis 75 mg/m2 ngày 1 + etoposide 100 mg/m2 ngày 1–3==, 28 ngày | {{QĐ1514 tr.PDF 249}} |\n| Atezolizumab (SCLC lan tràn) | ==1.200 mg== mỗi 21 ngày | {{QĐ1514 tr.PDF 250}} |\n| Xạ dự phòng não | ==25 Gy/10 buổi== + memantine | {{QĐ1514 tr.PDF 247–248}} |\n| Ho ra máu nặng | ==>200 ml/24 giờ== | {{QĐ1514 tr.PDF 64–67}} |\n| Theo dõi SCLC | ==3 tháng x 2 năm, rồi 6 tháng== | {{QĐ1514 tr.PDF 254}} |\n\n> [!warn] Bẫy thi thường gặp\n> - **Tỉ lệ mô học:** chữ Y5 SCLC 15%/NSCLC 85%; hình Y5 20%/80%. Làm bài Y5 ưu tiên số trong chữ.\n> - **Sống còn IIIA:** Bảng 4 = 36% nhưng phần điều trị = 24%; IIIB–C 3–7% khác Bảng 4. Nêu rõ nguồn.\n> - **Mốc T:** QĐ1514 xếp xâm lấn thành ngực/màng phổi trung thất/nốt cùng thùy vào T3; Y5 Bảng 3 khác; thi Y5 theo Bảng 3.\n> - **Cận u:** Y5 SCLC = SIADH, gai = tăng canxi; QĐ1514 ghi thường gặp ở NSCLC và nêu đái tháo nhạt.\n> - **Củng cố sau hóa-xạ III:** Y5 tr.116 ghi miễn dịch, tr.119 ghi hóa trị; nêu cả hai.\n> - {r|Y5: không cắt phân thùy/hình chêm}; QĐ4825 chấp nhận hình chêm u ngoại biên <3 cm; hóa trị hỗ trợ: {r|Y5 không ở giai đoạn I}, QĐ4825 từ IB; {r|Y5 không xạ sau mổ IIIA}, QĐ4825 thường chỉ định xạ khi nguy cơ cao. **Mâu thuẫn, nêu cả hai.**\n> - **Phẫu thuật SCLC:** không là chuẩn (Y5); QĐ1514 chỉ I–IIA.\n> - Glanduitrine {r|không tiêm TM}; NSCLC IV: xét nghiệm đột biến/PD-L1 **trước** khi chọn thuốc.\n\n@@fold Nguồn tài liệu\n- **Y5** `TEXT UNG BƯỚU Y5.pdf` (chữ: `_work/text-ung-buou-y5.txt`) tr. 104–126.\n- **QĐ1514** `QĐ BYT Hướng dẫn chẩn đoán và điều trị một số bệnh ung bướu.pdf` Bài 33 tr. PDF 242–254; Bài 9–10 tr. PDF 64–70; tr. PDF 32–33; Bài 34 tr. PDF 255–256.\n- **128VĐ** mục 50, 57, 49, 56 (`data/book-items.json`); QĐ 22 STT 41, 47, 40, 46.\n- Bài cũ đã kiểm tra nguồn: `_old/ung-thu-phoi-*.md`, `tc-ho-ra-mau`, `tc-bat-thuong-xq-nguc`, `tc-ho-dam-ho-khan`, `tc-tran-dich-mang-phoi`.\n@@end\n\n@@fold Nguồn ngoài\nDiễn đạt lại, không phải văn bản BYT/Y5; chỉ để tham khảo.\n- NCI PDQ, Non-Small Cell Lung Cancer Treatment (Health Professional): https://www.cancer.gov/types/lung/hp/non-small-cell-lung-treatment-pdq\n- NCI PDQ, Small Cell Lung Cancer Treatment: https://www.cancer.gov/types/lung/hp/small-cell-lung-treatment-pdq\n- StatPearls, Non-Small Cell Lung Cancer (NCBI Bookshelf): https://www.ncbi.nlm.nih.gov/books/NBK562307/\n- USPSTF 2021, Lung Cancer: Screening: https://uspreventiveservicestaskforce.org/uspstf/recommendation/lung-cancer-screening\n- ESMO Clinical Practice Guidelines, Metastatic NSCLC (tham khảo chung): https://www.esmo.org/guidelines/guidelines-by-topic/esmo-clinical-practice-guidelines-lung-and-chest-tumours\n@@end\n\n@@fold Tự kiểm tra (15 thẻ)\n- UT phổi nào chiếm 15% (chữ Y5) và thường ở đâu? :: SCLC (tế bào nhỏ), trung tâm vùng rốn phổi (95%)\n- Hội chứng cận u thường nhất của SCLC và của tế bào gai? :: SCLC: SIADH; tế bào gai: tăng canxi máu (PTHrP)\n- Nguy cơ UT phổi ở người hút so với người không hút? :: Gấp 20 lần; thuốc lá gây ~90% ca (QĐ1514)\n- Định nghĩa nốt phổi đơn độc và PET-CT? :: Nốt <3 cm, giới hạn rõ, mô phổi bao quanh, không hạch; PET nhạy 96%, đặc hiệu 75%; dương tính giả: lao, histoplasmosis\n- TDMP ác tính thuộc phân loại nào? :: M1a (giai đoạn IVA)\n- Phẫu thuật chuẩn NSCLC giai đoạn I–II? :: Cắt thùy hoặc cắt phổi. Y5: không khuyến cáo cắt phân thùy, hình chêm; QĐ4825: chấp nhận hình chêm u ngoại biên <3 cm (mâu thuẫn)\n- Hóa trị hỗ trợ giai đoạn I và II? :: Y5: không ở I, là lựa chọn ở II; QĐ4825: từ IB (mâu thuẫn)\n- Giai đoạn IIIB–C PS 0–1 dùng gì? :: Hóa-xạ đồng thời phác đồ platinum, củng cố miễn dịch hoặc hóa trị\n- NSCLC IV: EGFR, ALK, PD-L1 >50% dùng thuốc gì (Y5)? :: EGFR TKI (erlotinib, gefitinib); crizotinib; pembrolizumab\n- Carcinôm tuyến và tế bào gai ưu tiên cặp hóa chất nào? :: Tuyến: cisplatin-pemetrexed; tế bào gai: cisplatin-gemcitabine\n- Phác đồ BYT chuẩn SCLC khu trú và liều? :: Cisplatin 75 mg/m2 ngày 1 + etoposide 100 mg/m2 ngày 1–3, 28 ngày, 4–6 chu kỳ, kèm xạ đồng thời\n- Xạ dự phòng não SCLC: chỉ định, liều, thuốc đi kèm? :: IIB–IV có đáp ứng; 25 Gy/10 buổi; memantine\n- Phẫu thuật SCLC theo QĐ1514? :: Chỉ I–IIA (T1–2N0M0): cắt thùy + vét hạch trung thất\n- Mức ho ra máu nặng và cách xử trí? :: >200 ml/24 giờ; Trendelenburg bên chảy máu, hồi sức, nút ĐM phế quản\n- Lịch theo dõi SCLC (QĐ1514)? :: 3 tháng/lần trong 2 năm đầu, sau đó 6 tháng/lần\n@@end"}, {"kind": "disease", "disease": "thanh-quan", "short": "Ung thư thanh quản", "group": "", "section": 0, "order": 13, "khung": [38, 39, 40, 41, 43, 44, 50, 96], "id": "ung-thu-thanh-quan", "title": "Ung thư thanh quản", "layer": "benh", "module": "ung-buou", "tags": ["ung bướu", "thanh quản", "hạ họng", "khàn tiếng", "carcinôm tế bào gai", "thuốc lá", "rượu", "HPV", "TNM AJCC", "bảo tồn thanh quản", "hóa xạ trị đồng thời", "cetuximab", "TEP"], "source": "Y5 tr.180–197 (chương UNG THƯ THANH QUẢN); Y5 tr.130, 135 (ung thư đầu cổ); QĐ1514 Bài 24 tr. PDF 174–182; SY5 tr.79–80; ĐC Y5 tr.2–4, 7; 128VĐ mục 48; QĐ 22 STT 38, 39, 40, 41, 43, 44, 50, 96 (trọng số tr.8)", "body": "> [!key] Ung thư thanh quản (UTQ) trong một nhìn\n> - Carcinôm tế bào gai chiếm ==85–95%==; **thuốc lá** và **rượu** là nguy cơ chính, có mặt ở ==trên 95%== bệnh nhân {{Y5 tr.180}} {{Y5 tr.182}}\n> - Phần lớn bướu ở **thanh môn** (gấp ==3 lần== thượng thanh môn); triệu chứng báo động sớm là **khàn tiếng kéo dài trên 3 tuần** {{Y5 tr.182}} {{Y5 tr.185}} {{SY5 tr.79}}\n> - Chẩn đoán xác định: **nội soi + sinh thiết** (mô bệnh học là tiêu chuẩn vàng); phân giai đoạn TNM {{QĐ1514 tr.PDF 175}}\n> - Điều trị theo vị trí và giai đoạn: sớm → phẫu thuật bảo tồn hoặc xạ trị; tiến xa → **hóa–xạ trị đồng thời** bảo tồn, cắt toàn bộ khi thất bại {{Y5 tr.191}} {{Y5 tr.193}}\n> - Yếu tố tiên lượng quan trọng nhất: **tình trạng bướu và hạch di căn** {{Y5 tr.195}}\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Đa số là carcinôm tế bào gai; ==98%== khởi từ thanh môn và thượng thanh môn {{Y5 tr.182}}\n> - Nguy cơ chính: **thuốc lá** (liên quan tuyến tính với liều), **rượu**; HPV (khoảng 20–30% ca) và trào ngược dạ dày–thực quản (còn bàn cãi) là yếu tố bổ sung {{Y5 tr.180}} {{Y5 tr.181}}\n\n### Định nghĩa & dịch tễ\n- UTQ là ác tính của niêm mạc phủ thanh quản; khi lan rộng thường gọi chung với hạ họng (\"thanh quản – hạ họng\") {{QĐ1514 tr.PDF 174}}\n- Thế giới (GLOBOCAN 2018): thứ ==22== về mắc (177.422 ca) và thứ ==19== về tử vong (94.771 ca) {{Y5 tr.180}}\n- Việt Nam: thứ 19 về mắc (==1.685 ca==) và thứ 20 về tử vong (==859 ca==); ước tính 2040: 3.064 ca mới, 1.681 tử vong {{Y5 tr.180}}\n- Nam gấp ==7 lần== nữ về mắc và tử vong; tỉ lệ nam:nữ 4:1 đến 7:1; tuổi thường gặp 50–70, trung bình 65; chỉ 4% dưới 40 tuổi {{Y5 tr.180}}\n- Trong ung thư đầu cổ, thanh quản chiếm ==25%== (sau hốc miệng 40%, hạ hầu 10%) {{Y5 tr.130}}\n- QĐ1514 ghi GLOBOCAN 2018 \"thanh quản – hạ họng\" đứng thứ 16 và 19; nam chiếm 90% (xem bẫy thi) {{QĐ1514 tr.PDF 174}}\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Thuốc lá – rượu\n- **Thuốc lá**: nguy cơ cao gấp ==10–15 lần== người không hút; nghiện nặng gấp 30 lần {{Y5 tr.180}}\n- Bỏ thuốc trên 5 năm thì nguy cơ giảm; ngừng trên 10 năm thì tương đương người không hút {{Y5 tr.180}}\n- **Rượu**: yếu tố đứng hàng thứ hai; trên 95% bệnh nhân có cả hút thuốc và uống rượu; ngừng rượu có thể ngăn ==4%== ung thư do rượu {{Y5 tr.180}}\n@@tab Virus – môi trường – khác\n- **HPV** (týp 6, 11, 16, 18, 33) tăng nguy cơ, thường gặp ở phụ nữ; HPV có mặt khoảng ==20–30%== ung thư thanh quản {{Y5 tr.181}}\n- Tiếp xúc môi trường: amiăng (asbestos), niken, hơi mù tạt {{Y5 tr.180}}\n- Trào ngược dạ dày–thực quản: vai trò trong bệnh sinh còn bàn cãi và đang nghiên cứu {{Y5 tr.181}}\n- Khẩu phần nhiều rau củ, trái cây (caroten, vitamin C) có thể giảm nguy cơ {{Y5 tr.181}}\n@@end\n\n### Sinh bệnh học & sinh học phân tử\n- Cơ chế phân tử (gen, đột biến, đường tín hiệu): tài liệu không nêu\n- Hướng bệnh sinh được nêu: thuốc lá, rượu và HPV (một phần ca) là các yếu tố tác động lên niêm mạc thanh quản {{Y5 tr.180}} {{Y5 tr.181}}\n\n### Giải phẫu bệnh – phân loại\n@@tabs\n@@tab Mô bệnh học\n| Loại | Đặc điểm |\n|---|---|\n| **Carcinôm tế bào gai** | ==85–95%==; phần lớn biệt hóa tốt hoặc trung bình; carcinôm tại chỗ thường ở dây thanh {{Y5 tr.182}} |\n| Carcinôm dạng mụn cóc | 1–2%; xâm lấn tại chỗ mạnh nhưng thường không di căn; chẩn đoán GPB đôi khi khó {{Y5 tr.182}} |\n| Thần kinh nội tiết tế bào nhỏ | rất hiếm, hay ở thượng thanh môn; tiến triển nhanh, di căn xa sớm nhưng đáp ứng tốt hóa trị {{Y5 tr.182}} |\n| Carcinôm tuyến nước bọt phụ | hiếm; thường ở thượng và hạ thanh môn {{Y5 tr.182}} |\n| Sarcôm, lymphôm, u tương bào | hiếm hơn {{Y5 tr.182}} |\n| Ung thư biểu mô vảy (QĐ1514) | trên ==95%== (gộp thanh quản – hạ họng); số ít là sarcoma, ung thư biểu mô tuyến {{QĐ1514 tr.PDF 175}} |\n@@tab Giải phẫu vùng\n- Chia 3 vùng theo phôi thai: **thượng thanh môn** (từ đầu nắp thanh môn đến mặt phẳng qua đỉnh tiền đình); **thanh môn** (đến dưới nếp thanh âm thật khoảng 1 cm); **hạ thanh môn** (đến tận cùng sụn nhẫn) {{Y5 tr.181}}\n- Hàng rào: **nón đàn hồi** (ngăn thanh môn và hạ thanh môn), **màng tứ giác** (ngăn thượng thanh môn và thanh môn), màng quanh thất {{Y5 tr.182}}\n- Khoang nguyên phát: khoang trước nắp và khoang cạnh thanh môn; khối u trong hai khoang này xếp ít nhất T3 {{Y5 tr.182}}\n- Dây thanh gồm biểu mô lát tầng, lớp nông (gel), lớp giữa và sâu (dây chằng thanh âm) {{Y5 tr.181}}\n@@end\n\n### Diễn tiến tự nhiên – lan tràn\n@@tabs\n@@tab Bướu nguyên phát\n- Ung thư thanh môn gấp ==3 lần== thượng thanh môn; hạ thanh môn chỉ ==2%== {{Y5 tr.182}}\n| Vị trí | Diễn tiến |\n|---|---|\n| Thượng thanh môn | lan ra ngoài, hủy sụn; xâm lấn xuống hạ thanh môn chỉ khi tiến xa; xâm lấn mép trước thường là dấu hiệu muộn {{Y5 tr.183}} |\n| Thanh môn | ==2/3== trường hợp còn ở một dây thanh khi chẩn đoán, thường phía trước; lan mép trước, thanh thất; khi chạm sụn giáp thì ăn lan lên hoặc xuống {{Y5 tr.184}} |\n| Hạ thanh môn | hiếm; sụn nhẫn bị xâm lấn sớm; bất động dây thanh thường gặp; tái phát cao, tiên lượng kém {{Y5 tr.185}} |\n@@tab Hạch vùng\n- Thượng thanh môn: di căn hạch ==25–75%== (mọi giai đoạn), thường hai bên {{Y5 tr.185}}\n- Thanh môn: T1–T2 di căn ==0–10%==; T3–T4 ==10–35%==; nhóm hạch nguy cơ (T3–T4): II, III, IV, VI {{Y5 tr.185}}\n- Hạ thanh môn: đầu tiên hạch cạnh và trước khí quản, hạch Delphian, hạch dọc thần kinh hồi thanh quản; sau đó hạch nhóm thấp dọc tĩnh mạch hầu trong {{Y5 tr.185}}\n@@tab Di căn xa\n- Hiếm; đến **phổi, gan, xương**; di căn hạch là yếu tố nguy cơ liên quan đến di căn xa {{Y5 tr.185}}\n@@end\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Triệu chứng sớm điển hình: **khàn tiếng tăng dần, kéo dài** (thanh môn) {{Y5 tr.135}} {{QĐ1514 tr.PDF 174}}\n> - Khàn tiếng **không cải thiện sau 3 tuần** → khám chuyên khoa tai mũi họng, soi thanh quản {{Y5 tr.185}} {{128VĐ mục 48}}\n> - Triệu chứng muộn: nuốt khó, nuốt đau lan tai, ho mãn tính, ho ra máu, tiếng rít thanh quản, hạch cổ {{Y5 tr.135}}\n\n### Triệu chứng cơ năng – theo vị trí\n@@tabs\n@@tab Thượng thanh môn\n- Đau họng, nuốt khó, nuốt đau lan lên tai; thay đổi giọng nói; hạch cổ to ở giai đoạn trễ {{Y5 tr.185}}\n@@tab Thanh môn\n- Khàn tiếng là triệu chứng sớm; bướu tiến triển gây khó thở {{Y5 tr.185}}\n- Xâm lấn lớp màng đáy và cơ dây thanh làm yếu rung động → khàn; xâm lấn khớp nhẫn phễu làm dây thanh hạn chế, thanh môn không khít, giọng như hơi thở {{Y5 tr.185}} {{Y5 tr.186}}\n- Muộn: ho mãn tính, ho ra máu, tiếng rít thanh quản, khó nuốt {{Y5 tr.135}}\n@@tab Hạ thanh môn\n- Giai đoạn sớm ít gặp; đôi khi có khàn tiếng, khó thở hay thở rít {{Y5 tr.186}}\n- Thường phát hiện trễ với tắc nghẽn đường thở (tiếng rít, khó thở thanh quản) và hạch cổ di căn {{Y5 tr.135}}\n- Xâm lấn sụn hoặc lan ra ngoài thanh quản là dấu hiệu thường gặp trên lâm sàng {{Y5 tr.186}}\n@@end\n\n### Biểu hiện muộn\n- Khó thở nhẹ rồi nặng dần, khó thở thì hít vào; giọng ông ổng \"như nói qua ống thổi\" {{QĐ1514 tr.PDF 174}}\n- Giai đoạn muộn: sụn giáp to, chắc, gồ như \"mai rùa\"; gầy, sút cân, da xanh {{QĐ1514 tr.PDF 174}}\n\n### Khám thực thể\n- Soi thanh quản trực tiếp hoặc gián tiếp: vị trí, cử động dây thanh, sụn phễu; ==bất động dây thanh là dấu hiệu tiên lượng xấu== {{Y5 tr.186}}\n- Bệnh nhân giai đoạn trễ: đánh giá màng giáp–móng, màng giáp–nhẫn, sụn giáp; mất dấu click thanh quản gợi ý xâm lấn vùng sau nhẫn {{Y5 tr.186}}\n- Hạch cổ: cùng bên lúc đầu, muộn hai bên; hạch giữa và dưới; hạch rắn, lúc sớm còn di động, về sau cố định {{QĐ1514 tr.PDF 174}}\n- Khám hạch lâm sàng có tỉ lệ âm giả ==20–51%== {{Y5 tr.186}}\n- Khám kỹ hốc miệng, khẩu hầu, tuyến giáp và hạch cổ kèm theo {{Y5 tr.186}}\n\n> [!red] Dấu hiệu báo động (nghi ung thư thanh quản)\n> - {r|Khàn tiếng kéo dài trên 3 tuần}, nhất là nam giới hút thuốc, uống rượu {{SY5 tr.79}} {{128VĐ mục 48}}\n> - {r|Khó thở thanh quản, thở rít, khó thở thì hít vào}: cần đánh giá khẩn {{QĐ1514 tr.PDF 174}} {{128VĐ mục 52}}\n> - {r|Ho ra máu} hoặc ho khạc máu {{Y5 tr.135}} {{128VĐ mục 50}}\n> - {r|Hạch cổ rắn, cố định; sụn giáp gồ cứng} {{QĐ1514 tr.PDF 174}}\n\n### Tiếp cận các triệu chứng (khung 128 vấn đề)\n| STT | Vấn đề | Nguyên nhân cần nghĩ tới (thanh quản) |\n|---|---|---|\n| [39](#/khung/39) | **Khàn tiếng** | ung thư thanh quản (khàn trên 3 tuần); polyp, hạt, viêm dây thanh; viêm thanh quản cấp; lao thanh quản; u nhú; tổn thương thần kinh quặt ngược (ngoài thanh quản) {{128VĐ mục 48}} {{Y5 tr.188}} |\n| [41](#/khung/41) | **Ho ra máu** | triệu chứng muộn của ung thư thanh quản; cần đánh giá khẩn {{Y5 tr.135}} {{128VĐ mục 50}} |\n| [43](#/khung/43) | **Thở rít** | tắc nghẽn thanh quản, thường gặp ở ung thư hạ thanh môn giai đoạn trễ {{Y5 tr.135}} {{Y5 tr.186}} |\n| [44](#/khung/44) | **Khó thở mạn** | nhẹ rồi nặng dần, thì hít vào: tắc nghẽn đường thở do khối u {{QĐ1514 tr.PDF 174}} |\n| [40](#/khung/40) | **Ho đàm – ho khan** | ho mãn tính là triệu chứng muộn {{Y5 tr.135}} |\n| [38](#/khung/38) | **Đau họng** | ung thư thượng thanh môn {{Y5 tr.185}} |\n| [50](#/khung/50) | **Nghẹn, nuốt khó** | ung thư thượng thanh môn (nuốt đau lan tai) và ung thư hạ họng {{Y5 tr.135}} {{QĐ1514 tr.PDF 174}} |\n| [96](#/khung/96) | **Khối ở cổ** | hạch cổ di căn của ung thư thanh quản–hạ họng {{QĐ1514 tr.PDF 174}} {{Y5 tr.185}} |\n\n## 5. Cận lâm sàng\n\n> [!key] Tóm tắt\n> - **Nội soi thanh quản + sinh thiết** là chẩn đoán xác định; mô bệnh học là tiêu chuẩn vàng {{QĐ1514 tr.PDF 175}}\n> - CT/MRI đánh giá xâm lấn sụn, mô mềm và hạch; PET/CT dùng cho giai đoạn, theo dõi đáp ứng {{Y5 tr.187}} {{QĐ1514 tr.PDF 175}}\n> - Phân giai đoạn TNM theo AJCC; xét nghiệm tìm di căn xa khi có chỉ định {{Y5 tr.187}} {{QĐ1514 tr.PDF 176}}\n\n### Nội soi – sinh thiết – mô bệnh học\n@@tabs\n@@tab Nội soi & sinh thiết\n- Nội soi hạ họng–thanh quản: quan sát tổn thương, sinh thiết chẩn đoán xác định {{QĐ1514 tr.PDF 174}}\n- Soi thanh quản trực tiếp hoặc gián tiếp đánh giá dây thanh và sụn phễu {{Y5 tr.186}}\n- Soi thực quản, phế quản: đánh giá xâm lấn hoặc tổn thương ác tính kèm theo {{Y5 tr.187}}\n- Soi treo thanh quản: lập kế hoạch phẫu thuật, xác định độ lan rộng và phần thanh quản không xâm lấn {{Y5 tr.187}}\n- Nội soi thực quản–dạ dày–tá tràng tìm tổn thương kèm (ung thư có thể lan xuống thực quản) {{QĐ1514 tr.PDF 175}}\n@@tab Đo hoạt nghiệm & mô học\n- Đo hoạt nghiệm dây thanh: nhạy ==96,8%==, đặc hiệu ==92,8%==; tiên đoán khả năng xâm lấn {{Y5 tr.187}}\n- Mô bệnh học bắt buộc; trên 95% là ung thư biểu mô vảy; nhuộm hóa mô miễn dịch khi cần {{QĐ1514 tr.PDF 175}}\n- Tế bào học (FNA) khi có hạch sờ thấy: cho biết hạch có di căn hay không {{QĐ1514 tr.PDF 175}}\n- Có xét nghiệm giải trình tự nhiều gen (chỉ định cụ thể: tài liệu không nêu) {{QĐ1514 tr.PDF 175}}\n@@end\n\n### Chẩn đoán hình ảnh\n@@tabs\n@@tab CT & MRI\n- CT lát 1–2 mm: xâm lấn sụn (đặc biệt sụn giáp), khoảng trước sụn giáp, lan ngoài thanh quản; chẩn đoán hạch cổ chính xác ==87–93%== {{Y5 tr.187}}\n- MRI nhạy hơn CT với xâm lấn sụn và mô mềm, khoang cạnh thanh môn, khoang trước sụn nắp; hình giả nhiều hơn {{Y5 tr.187}}\n- Độ nhạy / đặc hiệu: CT ==60% / 85,7%==; MRI ==80% / 92,9%== {{Y5 tr.187}}\n- CT và MRI có cản quang là thường quy: đánh giá xâm lấn phần mềm, chít hẹp thanh quản, tiên lượng mở khí quản, mô phỏng xạ trị {{QĐ1514 tr.PDF 175}}\n@@tab PET & siêu âm\n- PET/CT: phân biệt tái phát tại chỗ với dư chứng sau xạ; phát hiện di căn hoặc u nguyên phát thứ hai {{Y5 tr.187}}\n- PET/CT trước điều trị để chẩn đoán u nguyên phát và giai đoạn; sau điều trị để theo dõi đáp ứng và mô phỏng xạ trị {{QĐ1514 tr.PDF 175}}\n- Siêu âm cổ kèm FNA: nhạy trong tìm di căn hạch cổ, chính xác ==89–97%== {{Y5 tr.187}}\n@@end\n\n### Bilan di căn & chức năng\n- Tìm di căn xa: X-quang phổi, siêu âm gan, phosphatase kiềm {{Y5 tr.187}}\n- Xạ hình xương SPECT/CT 99mTc-MDP; xạ hình thận 99mTc-DTPA (chức năng thận); PET/CT 18F-FDG {{QĐ1514 tr.PDF 175}}\n- Đo thông khí phổi, chức năng hô hấp: tiên lượng khả năng dung nạp hít sặc sau mổ và mở khí quản {{Y5 tr.187}} {{QĐ1514 tr.PDF 175}}\n- Chất chỉ điểm (SCC, Cyfra 21-1, CEA, CA 19-9): theo dõi đáp ứng, phát hiện tái phát và di căn {{QĐ1514 tr.PDF 175}}\n- Công thức máu, sinh hóa, chức năng đông máu, các bệnh kèm {{QĐ1514 tr.PDF 175}}\n\n### Phân giai đoạn TNM\n\n> [!warn] Hai nguồn ghi bản AJCC khác nhau và gộp nhóm IV khác nhau\n> - Y5 ghi \"theo AJCC 2018\" {{Y5 tr.189}}; QĐ1514 ghi \"AJCC lần thứ 8 năm 2017\" {{QĐ1514 tr.PDF 176}}\n> - Bảng so sánh giai đoạn bên dưới: ghi cả hai, không trộn lẫn\n\n@@tabs\n@@tab T (thanh môn)\n| T | Mô tả (Y5) |\n|---|---|\n| Tis | carcinôm tại chỗ {{Y5 tr.189}} |\n| T1 | khu trú ở một (T1a) hoặc cả hai dây thanh (T1b), có xâm lấn mép trước hoặc sau, hai dây thanh cử động bình thường {{Y5 tr.189}} |\n| T2 | lan sang thượng hoặc hạ thanh môn, hoặc giới hạn cử động dây thanh {{Y5 tr.189}} |\n| T3 | khu trú ở thanh quản, ==bất động dây thanh== và/hoặc xâm lấn khoang cạnh thanh môn và/hoặc mặt trong sụn giáp {{Y5 tr.189}} |\n| T4a | xâm lấn mặt ngoài sụn giáp và/hoặc ra khỏi thanh quản (khí quản, sụn nhẫn, mô mềm cổ, cơ dưới móng, tuyến giáp, thực quản) {{Y5 tr.189}} |\n| T4b | xâm lấn khoang trước cột sống, bao động mạch cảnh hoặc cấu trúc trung thất {{Y5 tr.189}} |\nMô tả thượng thanh môn và hạ thanh môn khác về chi tiết {{Y5 tr.189}} {{QĐ1514 tr.PDF 176–177}}.\n@@tab N & M\n| N | Y5 (tr.190) | QĐ1514 (tr.PDF 177–178) |\n|---|---|---|\n| N1 | 1 hạch cùng bên ≤3 cm, ENE(–) {{Y5 tr.190}} | 1 hạch ≤3 cm, chưa phá vỡ vỏ hạch {{QĐ1514 tr.PDF 177}} |\n| N2a | 1 hạch cùng bên >3–6 cm, ENE(–) {{Y5 tr.190}} | 1 hạch >3–6 cm, chưa phá vỡ vỏ hạch {{QĐ1514 tr.PDF 177}} |\n| N2b | nhiều hạch cùng bên ≤6 cm, ENE(–) {{Y5 tr.190}} | nhiều hạch cùng bên ≤6 cm, chưa phá vỡ vỏ hạch {{QĐ1514 tr.PDF 177}} |\n| N2c | hạch hai bên hoặc đối bên ≤6 cm, ENE(–) {{Y5 tr.190}} | hạch hai bên hoặc đối bên ≤6 cm, chưa phá vỡ vỏ hạch {{QĐ1514 tr.PDF 178}} |\n| N3a | 1 hạch >6 cm, ENE(–) {{Y5 tr.190}} | hạch >6 cm, chưa phá vỡ vỏ hạch {{QĐ1514 tr.PDF 178}} |\n| N3b | bất kỳ hạch nào có ENE(+) lâm sàng {{Y5 tr.190}} | bất kỳ hạch nào đã phá vỡ vỏ hạch lâm sàng {{QĐ1514 tr.PDF 178}} |\nM0: không di căn xa; M1: có di căn xa {{Y5 tr.190}} {{QĐ1514 tr.PDF 178}}\n@@tab Nhóm giai đoạn (so sánh)\n| Giai đoạn | Y5 (tr.190) | QĐ1514 (tr.PDF 178) |\n|---|---|---|\n| 0 | Tis N0 M0 | Tis N0 M0 |\n| I | T1 N0 M0 | T1 N0 M0 |\n| II | T2 N0 M0 | T2 N0 M0 |\n| III | T3 N0 M0; T1, T2, T3 với N1 (M0) | T3 N0 M0; \"I-T3\" N1 M0 (ký hiệu nghi là T1–T3) |\n| IVA | (không tách) | T4a N0–N1 M0; \"I-T4a\" N2 M0 (nghi là T1–T4a) |\n| IVB | (không tách) | bất kỳ T với N3 M0; T4b với bất kỳ N M0 |\n| IV (gộp) | T4 N0–N1 M0; bất kỳ T với N2 hoặc N3 M0 | (không tách) |\n| IVC | bất kỳ T, N với M1 | bất kỳ T, N với M1 |\n@@end\n\n> [!warn] Bẫy ký hiệu\n> - Bảng TNM QĐ1514 tr. 178 ghi \"I-T3\" và \"I-T4a\" (đã đối chiếu ảnh trang): không rõ, nghi là T1–T3 và T1–T4a; cần đối chiếu bản gốc {{QĐ1514 tr.PDF 178}}\n\n### Đánh giá di căn xa – khi nào\n- Điều kiện chỉ định: tài liệu không nêu. Rà di căn xa bằng X-quang phổi, siêu âm gan, ALP; xạ hình xương và PET/CT {{Y5 tr.187}} {{QĐ1514 tr.PDF 175}}\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Chẩn đoán xác định ung thư thanh quản\n> - **Lâm sàng** (khàn tiếng kéo dài, nuốt khó, khó thở/rít, hạch cổ) + **nội soi** + **mô bệnh học** từ sinh thiết nội soi {{QĐ1514 tr.PDF 174}}\n> - Chẩn đoán dựa vào hỏi bệnh sử và khám lâm sàng; yếu tố nguy cơ (thuốc lá, rượu, bệnh kèm) ảnh hưởng chọn điều trị {{Y5 tr.185}}\n> - Sau xác định: vị trí và độ lan rộng, di căn hạch và xa, phân giai đoạn TNM, chức năng hô hấp và thể trạng {{Y5 tr.186}} {{QĐ1514 tr.PDF 175}}\n\n### Chẩn đoán phân biệt khàn tiếng và khối ở thanh quản\n| Bệnh lý | Điểm giống | Điểm khác / cách phân biệt |\n|---|---|---|\n| Viêm thanh quản cấp (cúm) | khàn tiếng đột ngột | sau cảm cúm; hai dây thanh phù, đỏ; chống viêm giảm phù nề thì khỏi; soi không có u {{QĐ1514 tr.PDF 176}} {{Y5 tr.188}} |\n| Viêm sụn thanh thiệt cấp; áp xe quanh tuyến mang tai hoặc amidan | nghẹt giọng, đau họng | đau họng và sốt; rối loạn đường thở có thể gây tử vong nếu không phát hiện sớm {{Y5 tr.186}} {{Y5 tr.188}} |\n| Polyp dây thanh | khàn kéo dài | nguyên nhân thường gặp nhất gây khàn giọng; hay gặp ở 1/3 trước dây thanh; liên quan hút thuốc, nói nhiều {{Y5 tr.188}} |\n| Hạt dây thanh | khàn kéo dài | do kích thích cơ học lặp lại; thường hai bên, hay gặp ở phụ nữ trẻ {{Y5 tr.188}} |\n| U nhú thanh quản | khối sùi | do HPV týp 6 và 11; hay tái phát sau cắt {{Y5 tr.188}} |\n| Lao thanh quản | khàn kéo dài, tăng dần | soi thấy chất tiết ứ đọng; sốt chiều; X-quang phổi thường có lao phổi {{QĐ1514 tr.PDF 176}} |\n| U xơ dây thanh, polyp, u nhú lành | khối trên dây thanh | chẩn đoán chủ yếu bằng sinh thiết mô bệnh học {{QĐ1514 tr.PDF 176}} |\n| Bệnh thoái hóa dạng bột | khối sùi mềm, rời rạc | hiếm; chẩn đoán xác định bằng mô bệnh học {{Y5 tr.188}} |\n| Ung thư amidan, miệng–thực quản, u lympho | khối vùng họng | phân biệt xuất phát điểm khi lan xuống hạ họng {{QĐ1514 tr.PDF 176}} |\n| Liệt thần kinh quặt ngược (ngoài thanh quản) | khàn tiếng | do phẫu thuật, chèn ép, chấn thương vùng cổ {{128VĐ mục 48}} |\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n\n> [!key] Mục tiêu theo giai đoạn\n> - **Giai đoạn sớm (I–II)**: chữa khỏi, giảm tối thiểu dư chứng; **bảo tồn chức năng thanh quản** (nói, nuốt, thở) {{Y5 tr.190}}\n> - **Tiến xa tại chỗ–tại vùng (III–IV)**: bảo tồn thanh quản bằng hóa–xạ trị đồng thời; chức năng tốt hơn nhưng không cải thiện sống còn so với cắt toàn bộ {{Y5 tr.193}}\n> - **Di căn**: platinum là điều trị bước 1; cetuximab với nhóm chọn lọc; miễn dịch khi tiến triển {{Y5 tr.195}}\n\n- Cá thể hóa theo vị trí, giai đoạn, tuổi, bệnh kèm, chức năng phổi và nuốt, sở thích bệnh nhân {{Y5 tr.190}} {{Y5 tr.191}}\n- Yếu tố tiên đoán tốt: ngừng hút thuốc, chỉ số hoạt động cơ thể tốt, ít bệnh kèm, hỗ trợ tốt từ gia đình {{Y5 tr.191}}\n- Bệnh nhân cần đội ngũ đa chuyên khoa (phẫu thuật, hóa trị, xạ trị) trước khi điều trị {{Y5 tr.193}}\n\n### 7.2 Các phương pháp\n\n@@tabs\n@@tab Phẫu thuật\n- **Thanh môn**: cắt dây thanh (nội soi laser hoặc mổ hở), cắt thanh quản trán bên, cắt thanh quản trên sụn nhẫn khi dây thanh còn di động; **cắt toàn bộ khi dây thanh cố định** {{QĐ1514 tr.PDF 178}} {{Y5 tr.191}}\n- **Thượng và hạ thanh môn** (QĐ1514 ghi chung): cắt thanh quản toàn bộ {{QĐ1514 tr.PDF 178}} (xem bẫy: Y5 nêu cho giai đoạn sớm khác)\n- **Sớm, thượng thanh môn (Y5)**: phẫu thuật laser qua miệng được chọn hơn mổ hở, kiểm soát tương đương nhưng chức năng thanh quản tốt hơn; cắt trên thanh môn cho T2; cắt trên sụn nhẫn khi hạn chế cử động dây thanh {{Y5 tr.191}}\n- **Sớm, thanh môn (Y5)**: cắt dây thanh qua nội soi là lựa chọn tối ưu cho bướu 1/3 giữa dây thanh; bướu xâm lấn mép trước cần CT/MRI xem sụn giáp {{Y5 tr.191}}\n- Không nên phối hợp phẫu thuật bảo tồn và xạ trị vì làm giảm kết quả bảo tồn chức năng {{Y5 tr.191}}\n- **Nạo hạch cổ**: không thấy hạch hoặc hạch <2 cm: vét chức năng; hạch >2 cm: vét triệt căn {{QĐ1514 tr.PDF 179}}; T3–T4 cN0 hoặc cN1: nạo hạch chọn lọc hai bên nhóm II–IV {{Y5 tr.194}}\n- Thanh môn sớm T1–T2N0: không có chỉ định nạo hạch hay xạ phòng ngừa vùng cổ {{Y5 tr.192}}\n- **Cắt toàn bộ**: cho T3 hoặc T4a và/hoặc chức năng thanh quản trước điều trị kém; cho kết quả sống còn và chất lượng sống cao hơn ở nhóm này {{Y5 tr.193}}\n- **Cứu vớt**: tái phát sau xạ ban đầu, cắt thanh quản cứu vớt; tái phát tại chỗ sau xạ có thể mổ bảo tồn hoặc cắt toàn bộ với một số ca T2 {{Y5 tr.192}} {{Y5 tr.191}}\n@@tab Xạ trị\n- **Xạ sau mổ** (QĐ1514): thực hiện 15–20 ngày sau mổ, khi vết mổ ổn định; kỹ thuật 3D, hai trường bên, photon + electron {{QĐ1514 tr.PDF 179}}\n- Liều sau mổ: ==60 Gy== nếu cắt thuận lợi, ==65–70 Gy== nếu cắt chưa triệt để; hạch dương như liều u; hạch dự phòng ==50 Gy==; 2 Gy/ngày, 10 Gy/tuần {{QĐ1514 tr.PDF 179}}\n- Chỉ định xạ sau mổ (Y5): T3, T4, diện cắt dương, xâm lấn mạch hoặc thần kinh, hạch cổ dương tính; thực hiện trong ==6 tuần== sau mổ {{Y5 tr.194}}\n- Hóa–xạ đồng thời sau mổ ưu tiên hơn xạ đơn thuần nếu diện cắt dương hoặc hạch xâm vỏ bao {{Y5 tr.194}}\n- Xạ triệt căn tổn thương sớm: ưu tiên ở T1–T2N0 và hạ thanh môn; trường chiếu phải phủ mép trước {{Y5 tr.192}}\n- Kỹ thuật IMRT hoặc VMAT để giảm tác dụng phụ trên mô lành {{Y5 tr.191}}\n- Liều triệt căn (xem bẫy: Y5 và QĐ1514 khác nhau): Y5 ghi 70 Gy cho u nguyên phát, 60 Gy cho vùng hạch và nguy cơ, 50 Gy cho hạch âm nguy cơ thấp {{Y5 tr.191}}\n- Tổn thương nhỏ khu trú, xạ đơn thuần (QĐ1514): IMRT cùng cisplatin 40 mg/m² tuần, 65 Gy, hạch dự phòng 50 Gy {{QĐ1514 tr.PDF 179}}\n- Hạ thanh môn sớm: xạ trị ưu tiên hơn cắt thanh quản (bảo tồn thanh quản, không ảnh hưởng sống còn dài hạn) {{Y5 tr.192}}\n@@tab Hóa trị – đích – miễn dịch\n- **Hóa đồng thời với xạ** (QĐ1514): cisplatin ==100 mg/m²== mỗi 3 tuần; hoặc carboplatin + 5-FU; hoặc cisplatin + 5-FU {{QĐ1514 tr.PDF 179}}\n- Mục đích: tăng nhạy cảm tế bào với tia, giảm liều xạ, chống tái phát và vi di căn {{QĐ1514 tr.PDF 179}}\n- Hóa–xạ đồng thời cho tiến xa tại chỗ–tại vùng là phổ biến; giữ thanh quản, không cải thiện sống còn so với cắt toàn bộ {{Y5 tr.193}}\n- **Cetuximab** hoặc **nimotuzumab** hàng tuần cùng xạ: giảm độc tính so với hóa xạ {{QĐ1514 tr.PDF 180}}\n- Miễn dịch PD-1/PD-L1 (pembrolizumab, nivolumab) khi tái phát hoặc di căn: kết quả khả quan hơn hóa chất (QĐ1514) {{QĐ1514 tr.PDF 180}}\n- Di căn (Y5): platinum là điều trị tiêu chuẩn bước 1; cetuximab hiệu quả ở nhóm chọn lọc; miễn dịch đã được chấp thuận khi tiến triển đang dùng platinum {{Y5 tr.195}}\n@@end\n\n#### Theo giai đoạn\n@@tabs\n@@tab Giai đoạn sớm (I–II)\n- **Thượng thanh môn**: phẫu thuật (ưu tiên laser qua miệng, kèm nạo hạch chọn lọc II–IV) hoặc xạ trị {{Y5 tr.191}}\n- **Thanh môn**: phẫu thuật bảo tồn và xạ trị cho tỉ lệ kiểm soát tương đương; T1–T2N0 thường xạ triệt căn {{Y5 tr.191}} {{Y5 tr.192}}\n- Kiểm soát tại chỗ khoảng ==90%== giai đoạn I và khoảng ==80%== giai đoạn II; sống còn 5 năm ==55–75%== {{Y5 tr.191}}\n- **Hạ thanh môn**: ưu tiên xạ trị; sống còn 5 năm xạ trị GĐ I ==71–86%==, GĐ II ==42–50%== {{Y5 tr.192}}\n@@tab Giai đoạn III–IV\n- **Bảo tồn thanh quản** bằng hóa–xạ trị đồng thời là phổ biến; cải thiện chức năng thanh quản nhưng không cải thiện tiên lượng sống còn so với cắt toàn bộ {{Y5 tr.193}}\n- Phẫu thuật bảo tồn kết hợp xạ sau mổ: chọn lọc cho bướu nguyên phát nhỏ với hạch cổ lớn {{Y5 tr.193}}\n- **Cắt toàn bộ**: T3–T4a, chức năng kém trước điều trị, bệnh tái phát sau hóa xạ đồng thời {{Y5 tr.193}}\n- Hóa xạ đồng thời tiến xa không mổ được (QĐ1514): xạ 3D tổng liều 70 Gy, kết hợp đa hóa chất chu kỳ 21 ngày × 4 nếu sức khỏe cho phép {{QĐ1514 tr.PDF 179}}\n- Sau cắt toàn bộ: phục hồi giọng bằng thanh–thực quản nhân tạo (TEP), là lựa chọn tốt nhất {{Y5 tr.194}}\n- Hạch cổ tồn lưu sau hóa xạ: đáp ứng hoàn toàn thì theo dõi; không đáp ứng thì nạo hạch cứu vớt {{Y5 tr.194}}\n@@tab Tái phát – di căn\n- Tái phát sau xạ ban đầu: phẫu thuật cắt thanh quản cứu vớt {{Y5 tr.192}}\n- Di căn: hóa trị platinum bước 1; cetuximab/nimotuzumab kết hợp hóa chất; PD-1/PD-L1 {{Y5 tr.195}} {{QĐ1514 tr.PDF 180}}\n- Điều trị triệu chứng và chất lượng sống; hóa chất ± kháng thể đơn dòng để kéo dài sống thêm {{QĐ1514 tr.PDF 181}}\n@@end\n\n### 7.3 Phác đồ – Y lệnh\n\n> [!doc] QĐ 1514/QĐ-BYT (1/4/2020), chương \"Ung thư thanh quản – hạ họng\", mục 3.1.2–3.1.3 (tr. PDF 179–182). Chép theo nguồn; chu kỳ ghi như nguồn. Truyền tĩnh mạch (TM) trừ khi ghi khác. QĐ1514 gộp hạ họng trong các phác đồ này. {{QĐ1514 tr.PDF 179–182}}\n\n@@tabs\n@@tab Đồng thời với xạ trị\n| Phác đồ | Thuốc – liều | Chu kỳ / cách dùng | Ghi chú |\n|---|---|---|---|\n| Cisplatin đơn | Cisplatin ==100 mg/m²== | mỗi 3 tuần | phối hợp xạ trị {{QĐ1514 tr.PDF 179}} |\n| Cisplatin tuần (tổn thương nhỏ) | Cisplatin 40 mg/m², truyền 1 ngày trong tuần | 4–6 chu kỳ; IMRT, tổng 65 Gy | {{QĐ1514 tr.PDF 179}} |\n| Carboplatin + 5-FU | Carboplatin 70 mg/m² + 5-FU 600 mg/m² | TM ngày 1–4 | {{QĐ1514 tr.PDF 179}} |\n| CF | Cisplatin 100 mg/m² ngày 1; 5-FU 1.000 mg/m² ngày 1–5 | 3–4 tuần × 4 chu kỳ | {{QĐ1514 tr.PDF 179}} |\n| PC | Paclitaxel 135 mg/m² ngày 1; Carboplatin AUC-2 ngày 1–4 | 6 tuần × 4 chu kỳ (nguyên văn) | phần hạ họng ghi AUC 5–6 (xem bẫy) {{QĐ1514 tr.PDF 180}} |\n| PP | Paclitaxel 175 mg/m² TM 3 giờ ngày 1; Cisplatin 75 mg/m² TM 30 phút ngày 2 | 3 tuần × 4 chu kỳ | {{QĐ1514 tr.PDF 180}} |\n| DC | Docetaxel 75 mg/m² ngày 1; Carboplatin AUC 5–6 ngày 1 | TM | {{QĐ1514 tr.PDF 180}} |\n| DP | Docetaxel 75 mg/m² ngày 1; Cisplatin 75 mg/m² TM 3 giờ ngày 1 | TM | {{QĐ1514 tr.PDF 180}} |\n| TCF | Docetaxel 75 mg/m² + Cisplatin 75 mg/m² ngày 1; 5-FU 750–1.000 mg/m² ngày 1–4 | TM | {{QĐ1514 tr.PDF 180}} |\n| DCU | Docetaxel 36 mg/m² ngày 1, 8; Cisplatin 30 mg/m² ngày 1, 8; Ufur (UFT) 300 mg/m²/ngày ngày 1–14 | 21 ngày; 2 chu kỳ trước xạ | {{QĐ1514 tr.PDF 180}} |\n| Ufur (UFT) duy trì | Ufur (UFT) 400 mg/ngày chia 2 lần | liên tục 1–2 năm sau xạ | {{QĐ1514 tr.PDF 180}} {{QĐ1514 tr.PDF 182}} |\n| Cetuximab | Tải 400 mg/m² tuần đầu, sau 250 mg/m² mỗi tuần | cùng xạ trị | {{QĐ1514 tr.PDF 180}} |\n| Nimotuzumab | 200 mg TM hàng tuần | cùng xạ trị | {{QĐ1514 tr.PDF 180}} {{QĐ1514 tr.PDF 182}} |\n@@tab Tái phát – di căn\n| Phác đồ | Thuốc – liều | Chu kỳ / cách dùng | Ghi chú |\n|---|---|---|---|\n| Hóa chất + kháng thể | PC, DC, PP, DP phối hợp cetuximab 400 → 250 mg/m² hoặc nimotuzumab 200 mg | cetuximab trong 6–7 tuần | tăng hiệu quả khi tái phát di căn {{QĐ1514 tr.PDF 181}} {{QĐ1514 tr.PDF 182}} |\n| PD-1/PD-L1 | Pembrolizumab 200 mg/m² TM (nguyên văn) | mỗi 3 tuần | đơn vị ghi mg/m², đối chiếu bản gốc {{QĐ1514 tr.PDF 180}} {{QĐ1514 tr.PDF 182}} |\n| Platinum (Y5) | không nêu liều trong Y5 | - | điều trị tiêu chuẩn bước 1 {{Y5 tr.195}} |\n@@end\n\n> [!warn] Theo dõi và độc tính cần nhớ\n> - Biến chứng của điều trị ung thư thanh quản tiến triển: phát âm, nuốt, bảo vệ đường thở, dò hầu–da, tổn thương thần kinh sọ và tủy, tổn thương mạch, xơ hóa da, suy giáp {{Y5 tr.195}}\n> - Đánh giá đáp ứng sau hóa xạ đồng thời: không chụp CT/PET quá sớm, trước 12 tuần; cắt cứu vớt khi còn bệnh hoặc tái phát được xác nhận mô học {{Y5 tr.195}}\n> - Đối chiếu liều và phác đồ với bản gốc khi dùng thực tế (xem bẫy) {{QĐ1514 tr.PDF 179}} {{QĐ1514 tr.PDF 180}}\n\n## 8. Tiên lượng – Dự phòng\n\n> [!key] Tóm tắt\n> - Tiên lượng quyết định bởi **tình trạng bướu và hạch di căn**; giai đoạn sớm không di căn hạch có thể khỏi ==75–95%== {{Y5 tr.195}}\n> - Dự phòng chính: **không hút thuốc, không uống rượu**; khám chuyên khoa sớm khi có bất thường vùng họng–miệng {{QĐ1514 tr.PDF 182}}\n> - Tầm soát ung thư thanh quản thường quy: tài liệu không nêu\n\n### Tiên lượng\n@@tabs\n@@tab Yếu tố tiên lượng\n| Yếu tố | Nội dung |\n|---|---|\n| Bướu và hạch | **quan trọng nhất**; hạch và tình trạng bướu quyết định tiên lượng {{Y5 tr.195}} |\n| Vị trí | hạ thanh môn: tái phát cao, tiên lượng kém hơn các vị trí khác {{Y5 tr.185}}; QĐ1514 ghi 30% sống 5 năm với hạ thanh môn {{QĐ1514 tr.PDF 182}} |\n| Khác | giới, tuổi, tình trạng sức khỏe, grade mô học, độ sâu xâm lấn {{Y5 tr.195}} |\n| Hemoglobin | Hb ==trên 13 g/dl== trước xạ: kiểm soát tại chỗ và sống còn tốt hơn so với thiếu máu {{Y5 tr.196}} |\n| Yếu tố tiên đoán tốt | ngừng hút thuốc, chỉ số hoạt động cơ thể tốt, ít bệnh kèm, hỗ trợ gia đình {{Y5 tr.191}} |\n@@tab Sống 5 năm (theo từng nguồn)\n- QĐ1514: ==90%== sống 5 năm với T1–T2; ==60%== với tiền đình thanh quản và hạ họng T1; ==30%== với hạ thanh môn; T3–T4 tiên lượng rất xấu {{QĐ1514 tr.PDF 182}}\n- Y5 (sớm): sống 5 năm ==55–75%==; kiểm soát tại chỗ khoảng 90% GĐ I và khoảng 80% GĐ II {{Y5 tr.191}}\n- Y5 (hạ thanh môn, xạ trị): sống 5 năm GĐ I ==71–86%==, GĐ II ==42–50%== {{Y5 tr.192}}\n- Các số đo khác nhau (khỏi bệnh, kiểm soát tại chỗ, sống còn), xem bẫy thi\n@@end\n\n### Theo dõi sau điều trị\n| Thời điểm | Lịch / nội dung | Nguồn |\n|---|---|---|\n| 2–4 năm đầu | theo dõi tích cực; ==80–90%== tái phát xảy ra trong thời gian này | {{Y5 tr.195}} |\n| Đến 5 năm | tiếp tục theo dõi: tái phát muộn, ung thư thứ hai, biến chứng muộn | {{Y5 tr.195}} |\n| 3 năm đầu (QĐ1514) | khám lại ==3 tháng/lần== | {{QĐ1514 tr.PDF 182}} |\n| Các năm sau (QĐ1514) | khám lại ==6–12 tháng/lần== | {{QĐ1514 tr.PDF 182}} |\n- Hướng dẫn bệnh nhân nhận biết tái phát: khàn tiếng, đau, nuốt khó, chảy máu, hạch cổ to {{Y5 tr.195}}\n- Nhóm theo dõi: phẫu thuật viên, bác sĩ xạ trị, ung bướu nội khoa, nha sĩ, chuyên viên phục hồi chức năng {{Y5 tr.195}}\n\n### Dự phòng\n@@tabs\n@@tab Cấp 1 (phòng bệnh)\n- **Không hút thuốc, không uống rượu** để giảm nguy cơ {{QĐ1514 tr.PDF 182}}; ngừng rượu có thể ngăn 4% ung thư do rượu {{Y5 tr.180}}\n- Khẩu phần nhiều rau củ, trái cây (caroten, vitamin C) có thể giảm nguy cơ {{Y5 tr.181}}\n- Tiếp xúc amiăng, niken, hơi mù tạt được nêu là yếu tố nguy cơ môi trường {{Y5 tr.180}}\n- Biện pháp phòng HPV cho thanh quản: tài liệu không nêu\n@@tab Cấp 2 (tầm soát – phát hiện sớm)\n- Tầm soát thường quy: tài liệu không nêu\n- Phát hiện sớm qua **triệu chứng báo động**: khàn tiếng trên 3 tuần → khám tai mũi họng hoặc ung bướu đầu cổ {{Y5 tr.185}} {{SY5 tr.79}}\n- Yếu tố đi kèm khi khàn tiếng: nam giới, hút thuốc, uống rượu {{SY5 tr.79}}\n- Khi có bất thường vùng họng–miệng: đến khám chuyên khoa để phát hiện sớm {{QĐ1514 tr.PDF 182}}\n@@tab Cấp 3 (phục hồi)\n- Phục hồi giọng sau cắt toàn bộ bằng TEP; đội ngũ phục hồi giọng là then chốt {{Y5 tr.194}}\n- Tập phục hồi phát âm cho tất cả bệnh nhân; thay đổi phát âm là vấn đề thường gặp nhất {{Y5 tr.196}}\n- Theo dõi và điều trị biến chứng muộn (xem phần Y lệnh) {{Y5 tr.195}}\n@@end\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] Bệnh này thi nhấn mạnh gì\n> - **Nhận diện và chẩn đoán** là trọng tâm: khàn tiếng kéo dài trên 3 tuần ở nam hút thuốc, uống rượu → soi thanh quản và sinh thiết {{SY5 tr.79}} {{128VĐ mục 48}}\n> - **Phân giai đoạn TNM** theo vị trí (thượng thanh môn, thanh môn, hạ thanh môn) và bản AJCC đang dùng (xem bẫy) {{Y5 tr.189}} {{QĐ1514 tr.PDF 176}}\n> - **Xử trí** theo vị trí và giai đoạn: sớm → phẫu thuật bảo tồn hoặc xạ trị; tiến xa → hóa–xạ trị đồng thời {{Y5 tr.190}} {{Y5 tr.193}}\n> - Trọng số thi chung (QĐ 22 tr.8): cận lâm sàng/chẩn đoán 45–60; xử trí 35–50\n> - Câu hỏi tình huống: người nam hút thuốc, khàn tiếng kéo dài trên 3 tuần thì làm gì? (soi thanh quản, sinh thiết, phân giai đoạn TNM, khám chuyên khoa)\n\n@@tabs\n@@tab Nhận diện\n- Nguy cơ then chốt: **thuốc lá** (gấp 10–15 lần), **rượu**; trên 95% có cả hai {{Y5 tr.180}}\n- Triệu chứng sớm: khàn tiếng tăng dần kéo dài; muộn: nuốt đau lan tai, ho ra máu, tiếng rít thanh quản {{Y5 tr.135}}\n- {r|Báo động}: khàn trên 3 tuần; khó thở thanh quản; ho ra máu; hạch cổ rắn, cố định {{SY5 tr.79}} {{QĐ1514 tr.PDF 174}}\n- Phân biệt: viêm thanh quản cấp, polyp và hạt dây thanh, lao thanh quản, u nhú {{Y5 tr.188}} {{QĐ1514 tr.PDF 176}}\n- Soi thanh quản: bất động dây thanh là dấu hiệu tiên lượng xấu {{Y5 tr.186}}\n[Xem mục 4](#/n/ung-thu-thanh-quan/4) · [mục 6](#/n/ung-thu-thanh-quan/6)\n@@tab Chẩn đoán\n- **Chẩn đoán xác định** = nội soi + sinh thiết mô bệnh học ({g|tiêu chuẩn vàng}) {{QĐ1514 tr.PDF 175}}\n- CT/MRI: xâm lấn sụn, hạch, chít hẹp; PET/CT: giai đoạn, tái phát hay dư chứng {{Y5 tr.187}} {{QĐ1514 tr.PDF 175}}\n- TNM: T3 là ==bất động dây thanh==; N theo số hạch, kích thước, ENE {{Y5 tr.189}} {{Y5 tr.190}}\n- Nhóm giai đoạn: III là T3 N0 hoặc T1–T3 N1 (Y5); IV gộp (Y5) hoặc chia IVA/IVB/IVC (QĐ1514) {{Y5 tr.190}} {{QĐ1514 tr.PDF 178}}\n- Rà di căn xa: X-quang phổi, siêu âm gan, ALP {{Y5 tr.187}}\n[Xem mục 5](#/n/ung-thu-thanh-quan/5) · [mục 6](#/n/ung-thu-thanh-quan/6)\n@@tab Điều trị\n- **Sớm (I–II)**: phẫu thuật bảo tồn (laser qua miệng, cắt dây thanh) hoặc xạ triệt căn; T1–T2N0 thường xạ {{Y5 tr.191}} {{Y5 tr.192}}\n- **Hạ thanh môn sớm**: ưu tiên xạ trị {{Y5 tr.192}}\n- **III–IV**: {g|hóa–xạ trị đồng thời} để bảo tồn; cắt toàn bộ khi T3–T4a hoặc thất bại; xạ sau mổ khi T3–T4, diện cắt dương, hạch dương {{Y5 tr.193}} {{Y5 tr.194}}\n- **Xạ liều sau mổ (QĐ1514)**: ==60 Gy== nếu cắt tốt; ==65–70 Gy== nếu chưa triệt để; hạch dự phòng ==50 Gy== {{QĐ1514 tr.PDF 179}}\n- **Hóa (QĐ1514)**: {p|cisplatin 100 mg/m²} mỗi 3 tuần; {p|cetuximab} 400 → 250 mg/m²; {p|nimotuzumab 200 mg} hàng tuần {{QĐ1514 tr.PDF 179}} {{QĐ1514 tr.PDF 180}}\n- **Di căn**: {p|platinum} bước 1; {p|PD-1/PD-L1} khi tái phát {{Y5 tr.195}} {{QĐ1514 tr.PDF 180}}\n[Xem mục 7.2](#/n/ung-thu-thanh-quan/7) · [mục 7.3](#/n/ung-thu-thanh-quan/7)\n@@tab Tiên lượng – Dự phòng\n- Tiên lượng quyết định bởi **bướu và hạch di căn** {{Y5 tr.195}}\n- Sống 5 năm (QĐ1514): T1–T2 ==90%==; hạ thanh môn ==30%== {{QĐ1514 tr.PDF 182}}; Y5 ghi số khác (xem bẫy)\n- Theo dõi: 3 tháng/lần trong 3 năm đầu (QĐ1514); theo dõi tích cực 2–4 năm đầu (Y5) {{QĐ1514 tr.PDF 182}} {{Y5 tr.195}}\n- Dự phòng: {o|bỏ thuốc lá và bỏ rượu}; khám khi có bất thường vùng họng–miệng {{QĐ1514 tr.PDF 182}}\n[Xem mục 8](#/n/ung-thu-thanh-quan/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Ca mới / tử vong VN (GLOBOCAN 2018) | ==1.685 / 859== | {{Y5 tr.180}} |\n| Carcinôm tế bào gai | ==85–95%== | {{Y5 tr.182}} |\n| Nguy cơ hút thuốc | ==10–15 lần== (nghiện nặng 30 lần) | {{Y5 tr.180}} |\n| Di căn hạch thượng thanh môn | ==25–75%== | {{Y5 tr.185}} |\n| Di căn hạch thanh môn T1–T2 / T3–T4 | ==0–10% / 10–35%== | {{Y5 tr.185}} |\n| Khàn tiếng cần khám chuyên khoa | ==trên 3 tuần== | {{Y5 tr.185}} {{SY5 tr.79}} |\n| Khám hạch cổ lâm sàng: âm giả | ==20–51%== | {{Y5 tr.186}} |\n| CT: nhạy / đặc hiệu (xâm lấn, hạch) | ==60% / 85,7%== | {{Y5 tr.187}} |\n| MRI: nhạy / đặc hiệu | ==80% / 92,9%== | {{Y5 tr.187}} |\n| Đo hoạt nghiệm dây thanh: nhạy / đặc hiệu | ==96,8% / 92,8%== | {{Y5 tr.187}} |\n| Xạ sau mổ: cắt tốt / chưa triệt để | ==60 Gy / 65–70 Gy== | {{QĐ1514 tr.PDF 179}} |\n| Xạ sau mổ: thời điểm | ==15–20 ngày== (QĐ1514) / ==6 tuần== (Y5) | {{QĐ1514 tr.PDF 179}} {{Y5 tr.194}} |\n| Cisplatin đồng thời với xạ | ==100 mg/m² mỗi 3 tuần== | {{QĐ1514 tr.PDF 179}} |\n| Sống 5 năm T1–T2 (QĐ1514) | ==90%== | {{QĐ1514 tr.PDF 182}} |\n| Hemoglobin trước xạ | ==trên 13 g/dl== | {{Y5 tr.196}} |\n\n> [!warn] Bẫy thi thường gặp\n> - **Nhóm IV**: Y5 gộp IV (T4 N0–N1; mọi T với N2 hoặc N3) {{Y5 tr.190}}; QĐ1514 chia IVA/IVB/IVC {{QĐ1514 tr.PDF 178}}; bản AJCC: Y5 ghi 2018, QĐ1514 ghi bản 8 (2017) {{QĐ1514 tr.PDF 176}}\n> - **Sống 5 năm**: QĐ1514 ghi T1–T2 ==90%== và hạ thanh môn ==30%== {{QĐ1514 tr.PDF 182}}; Y5 ghi sống 5 năm ==55–75%== (sớm) {{Y5 tr.191}}, khỏi bệnh ==75–95%== (sớm, không di căn hạch) {{Y5 tr.195}}, hạ thanh môn xạ trị ==71–86%== (GĐ I) {{Y5 tr.192}}; không trộn các số đo khác nhau\n> - **Liều xạ triệt căn tổn thương nhỏ**: Y5 ghi 70 Gy cho u nguyên phát {{Y5 tr.191}}; QĐ1514 ghi 65 Gy kèm cisplatin tuần {{QĐ1514 tr.PDF 179}}; mâu thuẫn, đối chiếu bản gốc\n> - **Carboplatin trong phác đồ PC**: QĐ1514 ghi AUC-2 (tr.180) và AUC 5–6 (tr.181) cho cùng phác đồ {{QĐ1514 tr.PDF 180}} {{QĐ1514 tr.PDF 181}}\n> - **Thượng và hạ thanh môn sớm**: QĐ1514 ghi chung cắt toàn bộ {{QĐ1514 tr.PDF 178}}; Y5 ưu tiên laser qua miệng và xạ cho giai đoạn sớm {{Y5 tr.191}}; phạm vi khác nhau\n> - **Miễn dịch trong tuyến điều trị**: Y5 nêu sau platinum {{Y5 tr.195}}; QĐ1514 so với hóa chất, không nêu tuyến {{QĐ1514 tr.PDF 180}}\n> - **Pembrolizumab** ghi \"200 mg/m²\" (nguyên văn), đơn vị cần đối chiếu {{QĐ1514 tr.PDF 180}}\n> - **Theo dõi**: Y5 nhấn mạnh 2–4 năm đầu, đến 5 năm {{Y5 tr.195}}; QĐ1514 3 tháng/lần trong 3 năm đầu {{QĐ1514 tr.PDF 182}}\n> - **Carcinôm tế bào gai**: Y5 ghi 85–95% {{Y5 tr.182}}; QĐ1514 ghi trên 95% (gộp hạ họng) {{QĐ1514 tr.PDF 175}}\n> - **Dịch tễ GLOBOCAN 2018**: Y5 ghi thanh quản thứ 22 (mắc) và 19 (tử vong) {{Y5 tr.180}}; QĐ1514 ghi thanh quản – hạ họng thứ 16 và 19 {{QĐ1514 tr.PDF 174}}\n> - **Y5 tr.182** ghi \"ba khoang nguyên phát\" nhưng chỉ mô tả hai (trước nắp, cạnh thanh môn) {{Y5 tr.182}}\n\n@@fold Tự kiểm tra (15 thẻ)\n- Khàn tiếng bao lâu thì phải khám chuyên khoa và soi thanh quản? :: Trên 3 tuần, không cải thiện\n- Yếu tố nguy cơ chính và mức tăng nguy cơ? :: Thuốc lá (gấp 10–15 lần, nghiện nặng 30 lần); rượu; trên 95% có cả hai\n- Chẩn đoán xác định ung thư thanh quản dựa vào gì? :: Nội soi và sinh thiết; mô bệnh học là tiêu chuẩn vàng\n- Ba vùng giải phẫu thanh quản? :: Thượng thanh môn, thanh môn, hạ thanh môn\n- Di căn hạch thanh môn T1–T2 và T3–T4? :: 0–10% và 10–35%\n- Mô bệnh học thường gặp nhất? :: Carcinôm tế bào gai, 85–95%\n- Hạch vùng đầu tiên của ung thư hạ thanh môn? :: Hạch cạnh và trước khí quản, Delphian, dọc thần kinh hồi thanh quản\n- T1–T2N0 thanh môn điều trị gì? :: Xạ trị triệt căn (ưu tiên) hoặc phẫu thuật bảo tồn; không nạo hạch phòng ngừa\n- Hạ thanh môn giai đoạn sớm ưu tiên gì? :: Xạ trị, bảo tồn thanh quản\n- Chỉ định xạ sau mổ? :: T3–T4, diện cắt dương, xâm lấn mạch hoặc thần kinh, hạch dương tính\n- Liều xạ sau mổ theo QĐ1514? :: 60 Gy nếu cắt tốt; 65–70 Gy nếu chưa triệt để; hạch dự phòng 50 Gy\n- Cisplatin đồng thời với xạ theo QĐ1514? :: 100 mg/m² mỗi 3 tuần (hoặc 40 mg/m² tuần cho tổn thương nhỏ)\n- Thanh môn: vì sao không kết hợp phẫu thuật bảo tồn và xạ? :: Làm giảm kết quả bảo tồn chức năng\n- Phục hồi giọng sau cắt toàn bộ thanh quản? :: Thanh–thực quản nhân tạo (TEP)\n- Lịch theo dõi 3 năm đầu theo QĐ1514? :: 3 tháng/lần; các năm sau 6–12 tháng/lần\n@@end\n\n@@fold Nguồn tài liệu\n- **QĐ 1514/QĐ-BYT** (1/4/2020), Bài 24, tr. PDF 174–182 (đọc toàn bộ; bảng TNM tr. PDF 178 đối chiếu ảnh `_work/img-thanhquan-qd1514/p178.png`)\n- **Y5** (TEXT UNG BƯỚU Y5), tr.180–197 (chương UNG THƯ THANH QUẢN, đọc toàn bộ); tr.130, 135 (ung thư đầu cổ: tỉ lệ vị trí và triệu chứng thanh quản)\n- **SY5** tr.79–80 (triệu chứng báo động: khàn tiếng trên 3 tuần)\n- **ĐC Y5** tr.2–4 (mục tiêu MT), tr.7 (bảng ca lâm sàng ung thư thanh quản; MT 2,3,4,5,7,8,9,10,12,13,14,15,17)\n- **128VĐ mục 48** (Khàn tiếng; PDF 106–107)\n- **QĐ 22** tr.8 (trọng số chung); STT 38, 39, 40, 41, 43, 44, 50, 96 (khung)\n@@end\n\n@@fold Nguồn ngoài\n- Không dùng nguồn ngoài trong bài này; mọi số liệu lấy từ tài liệu người dùng đã cung cấp.\n@@end"}, {"kind": "disease", "disease": "tien-liet", "short": "Ung thư tuyến tiền liệt", "group": "", "section": 0, "order": 9, "khung": [65, 66, 67, 99], "id": "ung-thu-tien-liet", "title": "Ung thư tuyến tiền liệt", "layer": "benh", "module": "ung-buou", "tags": ["ung bướu", "tuyến tiền liệt", "PSA", "Gleason", "TNM", "tầm soát", "nhóm nguy cơ", "cấy hạt phóng xạ", "nội tiết", "kháng cắt tinh hoàn"], "source": "Y5 tr.329–345 (chương TIỀN LIỆT); QĐ 1514/QĐ-BYT (1/4/2020) Bài 81, tr. PDF 703–711; SY5 tr.18, 36, 144; ĐC Y5 tr.2–4, 7; 128VĐ mục 75, 80–82; QĐ 22 mục 4.2 (tr.8), STT 65–67, 99", "body": "> [!key] Ung thư tuyến tiền liệt (UTTL) trong một nhìn\n> - Ung thư biểu mô tuyến chiếm đa số (>95% Y5; >90% QĐ1514); thường gặp **thứ 2 ở nam** (sau phổi) {{Y5 tr.329}} {{Y5 tr.334}} {{QĐ1514 tr.PDF 703}}\n> - Giai đoạn sớm thường **không có triệu chứng**; tầm soát bằng **PSA + thăm trực tràng** từ **50 tuổi** {{Y5 tr.332}} {{QĐ1514 tr.PDF 711}}\n> - Chẩn đoán xác định = **sinh thiết** (qua trực tràng, dưới siêu âm, 12 lõi) → mô bệnh học + **Gleason** {{Y5 tr.333–334}}\n> - Điều trị theo **nhóm nguy cơ** (T, Gleason, PSA): thấp → theo dõi tích cực; TB/cao → phẫu thuật hoặc xạ + nội tiết {{Y5 tr.339}} {{Y5 tr.341}}\n> - Di căn (chủ yếu xương): **nội tiết** là chính; kháng cắt tinh hoàn → abiraterone, enzalutamide, docetaxel, cabazitaxel {{Y5 tr.342–345}}\n> - Ca lâm sàng UTTL trong đề cương gắn các mục tiêu MT2,3,4,5,7,8,9,10,13,14,15,17 {{ĐC Y5 tr.7}}\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Tiến triển chậm; khởi phát quanh 50 tuổi, triệu chứng thường ~70 tuổi; tuổi TB chẩn đoán **66** {{Y5 tr.329}} {{Y5 tr.332}}\n> - Nguy cơ chính: **tuổi**, **gen** (BRCA1/2, HOXB13), chủng tộc, **chế độ ăn nhiều mỡ, béo phì, lười vận động** {{Y5 tr.330}}\n\n### Định nghĩa & dịch tễ\n- Ung thư **thường gặp thứ 2 ở nam** (sau phổi); nguyên nhân tử vong ung thư **thứ 5** trên thế giới {{Y5 tr.329}}\n- Tuổi TB chẩn đoán **66**; gặp nhiều ở nước phát triển (phản ánh khác biệt về phương tiện chẩn đoán) {{Y5 tr.329}}\n- Sống 5 năm (Y5 đặt trong bối cảnh bướu khu trú): Mỹ ==98%==, châu Âu 2003–2007 ==83%== {{Y5 tr.329}}\n\n| Nguồn | Mới mắc | Tử vong | Ghi chú |\n|---|---|---|---|\n| GLOBOCAN 2018 (thế giới) | 1.276.106 | 358.989 | Y5: 3,8% tử vong do ung thư ở nam; SY5 ghi 7,1% và 3,8% (không ghi rõ mẫu số) {{Y5 tr.329}} {{SY5 tr.36}} |\n| Việt Nam 2018 | 3.959 (xếp thứ 11) | 1873 (xếp thứ 13) | {{Y5 tr.329}} |\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Không thay đổi được\n- **Tuổi**: tăng theo tuổi, đặc biệt sau 50 tuổi (người da trắng) và sau 40 tuổi (người da đen có tiền căn gia đình) {{Y5 tr.329}}\n- Khoảng 30% nam trên 50 tuổi tử vong do bệnh khác vẫn có bằng chứng UTTL trên mẫu tử thiết {{Y5 tr.329–330}}\n- **Chủng tộc**: cao nhất ở người Mỹ gốc Phi ==157,6/100.000==; da trắng 93,9; Mỹ gốc Á 52,4; Mỹ gốc Ấn/Alaska 46,9 {{Y5 tr.330}}\n- **Di truyền**: đột biến gen chỉ chiếm **5–9%**; trường hợp di truyền khởi phát sớm hơn 6–7 năm, diễn tiến hung hãn hơn {{Y5 tr.330}}\n- Khoảng ==11,8%== trường hợp di căn có đột biến dòng mầm ở gen sửa chữa DNA (**BRCA1/2**, **HOXB13**); mang BRCA thường tiên lượng xấu hơn {{Y5 tr.330}}\n@@tab Thay đổi được\n- Chế độ ăn nhiều mỡ động vật, **béo phì**, **lười vận động** liên quan tăng nguy cơ {{Y5 tr.330}}\n- Chưa có bằng chứng rõ về biện pháp phòng ngừa hữu hiệu; có thể giảm nguy cơ bằng cắt giảm chế độ ăn giàu năng lượng, tăng rau quả, tập thể dục thường xuyên {{Y5 tr.329}}\n@@end\n\n### Sinh bệnh học & giải phẫu\n- **Giải phẫu**: vùng ngoại vi chiếm ==70%== thể tích tuyến, là nơi phát sinh hầu hết ung thư; vùng trung tâm 25%; vùng chuyển tiếp bao quanh niệu đạo {{Y5 tr.330}}\n- **Trục androgen**: testosterone (chủ yếu từ tinh hoàn) → DHT → gắn thụ thể androgen (AR) → kích thích sao mã protein giúp tế bào bướu sống sót, tăng trưởng, kháng apoptosis; giảm androgen hoặc chặn AR → kìm hãm phát triển {{Y5 tr.331}}\n- Nền tảng: [[ung-thu-sinh-hoc-phan-tu]], [[ung-thu-giai-phau-benh]]\n\n### Giải phẫu bệnh – phân loại\n- **Carcinôm tuyến** chiếm phần lớn, chủ yếu biệt hóa tốt; ít gặp: carcinôm tế bào nhỏ, dạng nhầy, tế bào đáy, sarcôm {{Y5 tr.334}} {{QĐ1514 tr.PDF 703}}\n- **Gleason**: 5 mức (1 = tuyến nhỏ đồng nhất, biệt hóa tốt; 5 = không còn cấu trúc tuyến); là yếu tố tiên lượng quan trọng {{Y5 tr.334–335}}\n\n| Trường hợp | Cách tính điểm Gleason | Nguồn |\n|---|---|---|\n| Sinh thiết lõi kim | mức chiếm tỷ lệ **nhiều nhất** + mức **cao nhất** | {{Y5 tr.334}} |\n| Phẫu thuật tận gốc | mức nhiều nhất + mức **nhiều thứ 2**; mức cao hơn nhưng <5% thì ghi \"kèm tỷ lệ nhỏ độ X\" (ví dụ 3+3 kèm tỷ lệ nhỏ độ 4) | {{Y5 tr.335}} |\n\n- Gleason **6 (3+3)**: biệt hóa tốt nhất, tiên lượng tốt; **10 (5+5)**: xấu nhất, thường tử vong do di căn xa {{Y5 tr.335–336}}\n- Gleason 7 có hai kiểu: **(3+4)** và **(4+3)** với mức hung hãn khác nhau {{Y5 tr.336}}\n- Phân nhóm 2016 (5 nhóm): 1 = Gleason ≤6; 2 = 3+4; 3 = 4+3; 4 = 8; 5 = 9–10 {{Y5 tr.336}}\n\n### Diễn tiến tự nhiên – lan tràn\n- Tiến triển chậm; triệu chứng thường xuất hiện ~70 tuổi, phần lớn tử vong sau 75 tuổi {{Y5 tr.332}}\n- **Hạch**: hạch bịt, quanh bàng quang, hạch hạ vị, hạch trước xương cùng, hạch cạnh đại động mạch; khi hạch vùng bị xâm lấn thì hầu như đã có di căn xa {{Y5 tr.332}}\n- **Di căn xa**: **xương** nhiều nhất (tổn thương tạo xương, tăng đậm độ); gan, não; phổi và mô mềm hiếm {{Y5 tr.332}}\n- UTTL thường di căn xương {{SY5 tr.18}}\n\n> [!warn] Nguồn khác nhau về lan tràn\n> - **Di căn phổi**: Y5 ghi phổi là vị trí **hiếm**; QĐ1514 ghi di căn vào xương, phổi là **hay gặp** {{Y5 tr.332}} {{QĐ1514 tr.PDF 703}}\n> - **Thời điểm phát hiện**: Y5 ghi ở Âu–Mỹ phần lớn bệnh khu trú khi chẩn đoán; QĐ1514 ghi **một nửa** số bệnh nhân đã có di căn xa khi chẩn đoán (không nêu địa điểm). Ghi cả hai, không trộn số liệu {{Y5 tr.329}} {{QĐ1514 tr.PDF 703}}\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Giai đoạn sớm thường **không triệu chứng**, phát hiện qua thăm trực tràng hoặc PSA; khi đã có triệu chứng tiết niệu thường đã tiến triển {{Y5 tr.333}} {{QĐ1514 tr.PDF 703}}\n> - Triệu chứng muộn: **rối loạn đi tiểu, tiểu máu, bí tiểu**, sụt cân; di căn: **đau xương, lưng, vùng chậu** {{Y5 tr.333}} {{QĐ1514 tr.PDF 703–704}}\n> - **Yếu liệt hai chân, tiểu không tự chủ** → nghĩ đến di căn cột sống chèn ép tủy (cấp cứu) {{Y5 tr.333}} {{Y5 tr.343}}\n\n### Triệu chứng cơ năng & toàn thân\n- **Tiết niệu** (Y5): tiểu ngập ngừng, tiểu vội, tiểu đêm, tiểu nhỏ giọt, dòng nước tiểu yếu, tiểu máu cuối dòng {{Y5 tr.333}}\n- **Tiết niệu – sinh dục** (QĐ1514): đái rắt, đái khó, bí đái, đái ngắt quãng, đái máu; có khi đau khi xuất tinh {{QĐ1514 tr.PDF 704}}\n- **Toàn thân**: sụt cân, chán ăn, thiếu máu {{QĐ1514 tr.PDF 703}}\n- Khởi phát đột ngột và tiến triển nhanh các triệu chứng tắc nghẽn đường tiểu ở nam trung niên trở lên cũng gợi ý bệnh {{Y5 tr.333}}\n\n### Triệu chứng di căn\n- Đau lưng, đau vùng chậu, đau xương; gãy xương bệnh lý, đau ngực, khó thở {{Y5 tr.333}} {{QĐ1514 tr.PDF 704}}\n- Thần kinh: yếu liệt hai chân, tiểu không tự chủ (gợi ý di căn cột sống chèn ép tủy) {{Y5 tr.333}}\n\n> [!red] Chèn ép tủy do di căn\n> - Yếu liệt hai chân, tiểu không tự chủ → xạ trị chống chèn ép tủy là **cấp cứu** {{Y5 tr.333}} {{Y5 tr.343}}\n\n### Khám thực thể\n@@tabs\n@@tab Thăm trực tràng\n- TTL **to, cứng, dính, hạn chế di động** khi u đã xâm lấn ra ngoài {{QĐ1514 tr.PDF 704}}\n- Bệnh thường biểu hiện bằng tổn thương nhân trong mô tuyến, mật độ cứng chắc, **không đau**; khám TTL bình thường **vẫn không loại trừ** ung thư {{Y5 tr.333}}\n- Đánh giá thêm túi tinh và rãnh giữa (bất thường) {{Y5 tr.333}}\n@@tab Hạch & di căn\n- Khám **hạch bẹn, hạch trên đòn** để đánh giá di căn hạch (đây là vị trí di căn ít gặp) {{Y5 tr.333}}\n- Đánh giá vị trí di căn xa, đặc biệt hệ xương; chú ý đau nhức xương, dấu thần kinh, dấu chèn ép tủy sống {{Y5 tr.333}}\n@@end\n\n### Tiếp cận các triệu chứng (khung 128 vấn đề)\n| STT | Vấn đề | Nguyên nhân cần nghĩ |\n|---|---|---|\n| [65](#/khung/65) | **Tắc nghẽn đường tiết niệu, bí tiểu** | ung bướu tuyến tiền liệt (tăng sinh lành tính, ung thư); sỏi tuyến tiền liệt; viêm tuyến tiền liệt cấp, áp xe tuyến tiền liệt {{128VĐ mục 80}} |\n| [66](#/khung/66) | **Rối loạn đi tiểu** | ung thư tuyến tiền liệt; tăng sinh lành tính tuyến tiền liệt; ung thư bàng quang; sỏi bàng quang; hẹp niệu đạo {{128VĐ mục 81}} |\n| [67](#/khung/67) | **Tiểu máu** | bệnh lý ung bướu tiết niệu (chung), nhiễm trùng, sỏi, chấn thương {{128VĐ mục 82}} |\n| [99](#/khung/99) | **Sụt cân / suy dinh dưỡng** | sụt cân không chủ ý có thể liên quan ung thư; trong UTTL là triệu chứng toàn thân {{128VĐ mục 75}} {{QĐ1514 tr.PDF 703}} |\n\n## 5. Cận lâm sàng\n\n> [!key] Tóm tắt\n> - **Sinh thiết** qua trực tràng dưới siêu âm (tiêu chuẩn vàng) → mô bệnh học + Gleason {{Y5 tr.333–334}}\n> - **PSA**: ngưỡng 4 ng/ml; khi nghi ngờ đánh giá thêm mật độ, tốc độ, tỷ lệ PSA tự do {{Y5 tr.336–337}}\n> - **Phân giai đoạn** TNM (AJCC 8) và nhóm nguy cơ; xạ hình xương chỉ khi nguy cơ TB/cao {{Y5 tr.337–339}} {{QĐ1514 tr.PDF 704–706}}\n\n### Chẩn đoán hình ảnh\n@@tabs\n@@tab Siêu âm – MRI – CT\n- **Siêu âm ổ bụng**: đánh giá sơ bộ khối u, hạch và tổn thương di căn tạng ổ bụng {{QĐ1514 tr.PDF 704}}\n- **Siêu âm nội soi trực tràng**: xâm lấn tạng lân cận trực tràng, bàng quang {{QĐ1514 tr.PDF 704}}\n- **MRI vùng chậu**: nhạy và đặc hiệu hơn CT trong đánh giá xâm lấn vỏ bao và túi tinh; ước lượng kích thước; hữu ích trước phẫu thuật {{Y5 tr.337}}\n- **CT ngực–bụng–chậu**: phát hiện di căn hạch, di căn xương và các di căn ít gặp {{Y5 tr.338}}\n- **CT/cộng hưởng từ**: phát hiện u, mức xâm lấn và di căn hạch {{QĐ1514 tr.PDF 704}}\n@@tab Xạ hình xương – PET\n- **Xạ hình xương 99mTc-MDP**: di căn xương (cột sống, sườn, cánh chậu, sọ) {{QĐ1514 tr.PDF 704}}\n- PSA <10 ng/ml và không đau xương: di căn xương trên xạ hình <1%; PSA 10–50 ng/ml: 10%; PSA >50 ng/ml: 50% {{Y5 tr.337}}\n- Chỉ định xạ hình xương **chỉ khi nguy cơ trung bình hoặc cao** {{Y5 tr.337–338}}\n- **PET/CT 18F-FDG**: ít giá trị phát hiện u nguyên phát (u chậm, hấp thu FDG kém); giúp phát hiện di căn, tái phát, đánh giá điều trị; 11C-acetate cho hình u nguyên phát rõ hơn {{QĐ1514 tr.PDF 704}}\n@@end\n\n### Sinh thiết & mô bệnh học\n@@tabs\n@@tab Kỹ thuật\n- Qua trực tràng dưới hướng dẫn siêu âm, gây tê tại chỗ; **12 lõi** (2 đáy, 2 đỉnh, 2 giữa mỗi bên) {{Y5 tr.334}}\n- Có thể sinh thiết qua tầng sinh môn hoặc thành trực tràng dưới siêu âm {{QĐ1514 tr.PDF 704}}\n- Chuẩn bị: làm sạch đại tràng, uống kháng sinh dự phòng {{Y5 tr.334}}\n- Biến chứng thường nhẹ: đau vùng chậu, tiểu máu, nhiễm trùng, đi cầu ra máu, xuất tinh ra máu {{Y5 tr.334}}\n@@tab Chỉ định & thông tin mẫu\n- Chỉ định khi TTL rắn hoặc PSA **>4 ng/ml** {{QĐ1514 tr.PDF 711}}\n- Chỉ định **không đơn thuần dựa vào PSA**; kết hợp động học PSA, tuổi, tiền căn gia đình, chủng tộc, sức khỏe và ý kiến bệnh nhân {{Y5 tr.332}}\n- Mẫu sinh thiết cho: chẩn đoán xác định, Gleason, xâm lấn vỏ bao hay thần kinh (hiếm quan sát trên mẫu sinh thiết), **độ lan rộng** = số lõi dương/tổng số lõi {{Y5 tr.333–334}}\n- Cắt đốt TTL qua niệu đạo (TURP) vì tăng sản lành tính: khoảng 5% trường hợp tình cờ phát hiện ung thư {{Y5 tr.334}}\n@@end\n\n### Dấu ấn PSA\n- **PSA** (kháng nguyên đặc hiệu TTL): dùng để chẩn đoán, xác định lan rộng, đánh giá đáp ứng, theo dõi tái phát và di căn; vai trò tầm soát còn nhiều tranh cãi {{Y5 tr.336}}\n- QĐ1514: PSA có giá trị sàng lọc, chẩn đoán, đánh giá điều trị, theo dõi tái phát và di căn; PSA toàn phần, liên hợp thường tăng {{QĐ1514 tr.PDF 704}}\n- Nguy cơ ung thư theo PSA: <4 \"bình thường\"; 4–10: ==20–30%==; 10–20: ==50–75%==; >20: đến ==90%== {{Y5 tr.336}}\n- Dương tính giả: khoảng 15% tăng sản lành tính có PSA tăng; viêm TTL, sau nội soi hoặc phẫu thuật có thể tăng; **không tăng sau thăm trực tràng**; sau sinh thiết PSA tăng (Y5: \"tối thiểu từ 6 đến 8 tuần\") {{Y5 tr.336}}\n- **Mật độ PSA** (PSA / thể tích TTL): trên 0,15 báo động nguy cơ cao {{Y5 tr.337}}\n- **Tốc độ tăng PSA**: ≥0,75 ng/ml/năm gặp ở khoảng 70% nam có ung thư (khi PSA ban đầu 4–10); cần đo PSA ≥3 lần trong 2 năm {{Y5 tr.337}}\n- **Tỷ lệ PSA tự do** thấp làm tăng nguy cơ ung thư (Y5: ≤25%; QĐ1514: <20%) {{Y5 tr.337}} {{QĐ1514 tr.PDF 704}}\n- Sinh học phân tử: giải trình tự nhiều gen {{QĐ1514 tr.PDF 704}}\n- Máu: calci và phosphatase kiềm tăng khi có di căn xương {{QĐ1514 tr.PDF 704}}\n\n### Phân giai đoạn TNM (AJCC 8, 2017)\n- QĐ1514 dùng TNM AJCC lần thứ 8 (2017); Y5 ghi AJCC 2017 cho định nghĩa T/N/M {{QĐ1514 tr.PDF 704–705}} {{Y5 tr.338}}\n\n@@tabs\n@@tab T\n| T | Định nghĩa |\n|---|---|\n| Tx / T0 | không đánh giá được / không có bằng chứng u nguyên phát {{QĐ1514 tr.PDF 704–705}} |\n| T1 | không biểu hiện lâm sàng, không sờ thấy: **T1a** ≤5% mẫu mô là ung thư (phát hiện tình cờ qua TURP); **T1b** >5%; **T1c** phát hiện qua sinh thiết kim (do PSA tăng) {{Y5 tr.338}} {{QĐ1514 tr.PDF 705}} |\n| T2 | sờ thấy, còn khu trú trong TTL: **T2a** ≤½ một thùy; **T2b** >½ một thùy; **T2c** cả hai thùy {{QĐ1514 tr.PDF 705}} {{Y5 tr.338}} |\n| T3 | xâm lấn qua vỏ bao: **T3a** ngoài vỏ bao (một hoặc hai bên); **T3b** xâm lấn túi tinh {{QĐ1514 tr.PDF 705}} {{Y5 tr.338}} |\n| T4 | dính hoặc xâm lấn cơ quan lân cận ngoài túi tinh: cơ thắt ngoài, bàng quang, trực tràng, cơ nâng hậu môn, thành chậu {{QĐ1514 tr.PDF 705}} |\n@@tab N và M\n| Mã | Định nghĩa |\n|---|---|\n| N0 / N1 | không có / có di căn hạch vùng {{QĐ1514 tr.PDF 705}} |\n| M0 / M1 | không có / có di căn xa |\n| M1a | di căn hạch ngoài nhóm hạch vùng (hạch trên đòn) {{Y5 tr.338}} |\n| M1b | di căn xương {{QĐ1514 tr.PDF 705}} |\n| M1c | di căn cơ quan khác (gan, phổi…), có hoặc không có di căn xương {{Y5 tr.338}} {{QĐ1514 tr.PDF 705}} |\n@@tab Nhóm giai đoạn (Y5)\n| Giai đoạn | T | N, M | PSA (ng/ml) | Gleason |\n|---|---|---|---|---|\n| I | cT1a–c, cT2a, pT2 | N0 M0 | <10 | 1 |\n| IIA | cT1a–c, cT2a, pT2; cT2b, cT2c | N0 M0 | ≥10–<20 (cT1a–c, cT2a, pT2); <20 (cT2b, cT2c) | 1 |\n| IIB | T1–2 | N0 M0 | <20 | 2 |\n| IIC | T1–2 | N0 M0 | <20 | 3 hoặc 4 |\n| IIIA | T1–2 | N0 M0 | ≥20 | 1–4 |\n| IIIB | T3–4 | N0 M0 | bất kỳ | 1–4 |\n| IIIC | bất kỳ | N0 M0 | bất kỳ | 5 |\n| IVA | bất kỳ | N1 M0 | bất kỳ | bất kỳ |\n| IVB | bất kỳ | bất kỳ | M1 | bất kỳ |\n\n{{Y5 tr.339}}\n@@end\n\n> [!warn] Bảng nhóm giai đoạn chỉ có trong Y5 (xem {{Y5 tr.339}}). QĐ1514 chỉ đưa định nghĩa T/N/M, không có bảng nhóm giai đoạn; không trộn hai nguồn.\n\n### Nhóm nguy cơ (điều trị tại chỗ)\n| Nhóm | Y5 | QĐ1514 | SY5 |\n|---|---|---|---|\n| Rất thấp | không nêu {{Y5 tr.339}} | T1a; Gleason ≤6; PSA <10; mật độ PSA <0,15; sinh thiết <3 lõi (+), <50% tế bào (+) mỗi lõi {{QĐ1514 tr.PDF 705}} | không nêu {{SY5 tr.144}} |\n| Thấp | bướu <T2b **và** PSA ≤10 **và** Gleason ≤6 {{Y5 tr.339}} | T1, T2a; Gleason 2–6; PSA <10 {{QĐ1514 tr.PDF 706}} | T1, T2a; Gleason ≤6; PSA <10 {{SY5 tr.144}} |\n| Trung bình | bướu T2b–T2c **hoặc** PSA 10–20 **hoặc** Gleason 7 {{Y5 tr.339}} | T2b, T2c **hoặc** Gleason =7 **hoặc** PSA 10–20 {{QĐ1514 tr.PDF 706}} | T2b ± Gleason 7 ± PSA 10–20 {{SY5 tr.144}} |\n| Cao | bướu ≥T3 **hoặc** PSA ≥20 **hoặc** Gleason ≥8 {{Y5 tr.339}} | T3a **hoặc** Gleason 8–10 **hoặc** PSA >20 {{QĐ1514 tr.PDF 706}} | ≥T2c **hoặc** Gleason 8–10 **hoặc** PSA >20 {{SY5 tr.144}} |\n| Rất cao | không nêu | T3b, T4, N1 {{QĐ1514 tr.PDF 706}} | không nêu |\n\nTái phát sau điều trị theo nhóm (Y5): thấp ==5%==, trung bình ==20–30%==, cao ==50%== {{Y5 tr.339}}\n\n> [!warn] Ba nguồn không thống nhất phân nhóm nguy cơ. Ghi cả ba khi thi: T2c (SY5 xếp cao; Y5 và QĐ1514 xếp trung bình); T3 (Y5: ≥T3 là cao; QĐ1514: T3a là cao, T3b/T4 là rất cao). Chỉ QĐ1514 có nhóm \"rất thấp\" và \"rất cao\". {{Y5 tr.339}} {{SY5 tr.144}} {{QĐ1514 tr.PDF 705–706}}\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Chẩn đoán xác định UTTL\n> - **Mô bệnh học** từ sinh thiết (carcinôm tuyến), kèm Gleason {{Y5 tr.333–334}}\n> - Sinh thiết khi TTL rắn hoặc PSA >4 ng/ml; không chẩn đoán chỉ bằng PSA {{QĐ1514 tr.PDF 711}} {{Y5 tr.332}}\n> - Sau xác định: Gleason + độ lan rộng + TNM + nhóm nguy cơ (T, Gleason, PSA) {{Y5 tr.334}} {{Y5 tr.339}}\n\n### Chẩn đoán phân biệt\n| Bệnh lý | Giống | Khác / cận lâm sàng phân biệt |\n|---|---|---|\n| Viêm tuyến tiền liệt cấp hoặc mạn | triệu chứng tiết niệu tương tự; tài liệu không nêu chi tiết giống nhau | PSA có thể tăng trong viêm; tài liệu không nêu tiêu chí phân biệt riêng {{Y5 tr.333}} {{Y5 tr.336}} |\n| Tăng sản lành tính TTL | TTL to, tắc nghẽn đường tiểu | PSA tăng ở khoảng 15%; ung thư làm **tăng mật độ PSA** cao hơn tăng sản lành tính {{Y5 tr.336–337}} |\n| Lao tuyến tiền liệt | TTL to, triệu chứng tiết niệu | tài liệu không nêu tiêu chí phân biệt {{QĐ1514 tr.PDF 704}} |\n| Sỏi tuyến tiền liệt | tắc nghẽn, bí tiểu | tài liệu không nêu cận lâm sàng phân biệt {{128VĐ mục 80}} |\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n\n> [!key] Mục tiêu theo giai đoạn\n> - **Khu trú (tại chỗ)**: phẫu thuật hoặc xạ trị kết hợp nội tiết; nhóm nguy cơ thấp có thể theo dõi tích cực {{QĐ1514 tr.PDF 706}} {{Y5 tr.341}}\n> - **Tiến triển / di căn**: **nội tiết** là phương pháp chủ yếu; hóa chất khi nội tiết thất bại; xạ trị giảm triệu chứng {{QĐ1514 tr.PDF 706}} {{Y5 tr.342}}\n> - Cân nhắc: nhóm nguy cơ, kỳ vọng sống thêm (theo EAU 2008), nguyện vọng bệnh nhân, phương tiện sẵn có, lợi ích – tác dụng phụ – chống chỉ định {{Y5 tr.341}}\n\n### 7.2 Các phương pháp\n\n@@tabs\n@@tab Theo dõi tích cực\n- Dành cho nguy cơ thấp có **kỳ vọng sống trên 10 năm**; bệnh tiến triển rất chậm, tránh được tác dụng phụ điều trị {{Y5 tr.341}}\n- **PSA mỗi 6 tháng trong 18 tháng**; PSA tăng → xem xét sinh thiết lại; chuyển nhóm nguy cơ cao hơn → bắt đầu điều trị triệt để {{Y5 tr.341}}\n- Phần lớn ca phát hiện qua tầm soát không cần điều trị ngay → theo dõi tích cực {{Y5 tr.332}}\n@@tab Phẫu thuật\n- Phẫu thuật tiêu chuẩn cho nguy cơ **trung bình và cao**: cắt TTL tận gốc + túi tinh + nạo hạch chậu {{Y5 tr.340}}\n- Nạo hạch chậu khi nguy cơ di căn hạch **trên 2%** (theo toán đồ Briganti) {{Y5 tr.340}}\n- Mổ mở, nội soi hoặc robot; ưu điểm: lấy hết mô tuyến và dễ theo dõi bằng PSA {{Y5 tr.340}}\n- Biến chứng: đi tiểu không kiểm soát, rối loạn cương dương; chỉ nên chỉ định cho bệnh nhân không có bệnh nội khoa nặng {{Y5 tr.340}}\n- Nguy cơ cao: nếu chọn phẫu thuật cần bàn bạc kỹ trong hội chẩn đa chuyên khoa, lưu ý các tình huống cần xạ và nội tiết hỗ trợ sau mổ; có thể ưu tiên phẫu thuật cho bệnh nhân trẻ tuổi {{Y5 tr.341}}\n- Cắt đốt TTL qua niệu đạo (TURP): giảm nhẹ triệu chứng tắc nghẽn đường tiểu (cổ bàng quang) {{Y5 tr.343}}\n- Cắt 2 tinh hoàn: làm giảm testosterone nhanh; là lựa chọn hàng đầu ở giai đoạn tiến triển, di căn {{Y5 tr.342}}\n@@tab Xạ trị\n- **Xạ ngoài**: TTL ==74–80 Gy==, hạch chậu ==46 Gy==; kỹ thuật điều biến liều (IMRT) {{Y5 tr.340}}\n- Chỉ định xạ ngoài: xạ triệt căn; **xạ bổ túc sau phẫu thuật** ở nguy cơ cao (diện cắt dương, xâm lấn vỏ bao, xâm lấn túi tinh); xạ cứu vớt khi tái phát sinh hóa sau phẫu thuật {{Y5 tr.340}}\n- **Xạ trong (cấy hạt)**: nguồn I-125 hoặc Iridium-192 (Y5). Phần xạ trị chỉ định cho nguy cơ thấp, nhưng phần nhóm nguy cơ giới hạn ở TB \"thấp\" (PSA <15 hoặc Gleason 3+4); nguy cơ TB–cao cần phối hợp xạ trong với xạ ngoài {{Y5 tr.340–341}}\n- Cấy hạt vĩnh viễn I-125 hoặc Pd-103, phương pháp áp sát suất liều thấp; liều xem bảng Phác đồ bên dưới {{QĐ1514 tr.PDF 706–707}}\n- Xạ giảm đau di căn xương; **chống chèn ép tủy (cấp cứu)**; giảm đau vùng chậu; cầm máu khi tiểu máu nhiều {{Y5 tr.343}}\n@@tab Nội tiết (ADT)\n- Chỉ định: TTL tiến triển hoặc di căn; testosterone là yếu tố tăng trưởng chính của tế bào TTL ác tính {{Y5 tr.342}}\n- **LHRH** (leuprolide, goserelin): hồi phục, hiệu quả tương đương cắt 2 tinh hoàn; cắt 2 tinh hoàn không hồi phục {{Y5 tr.342}}\n- Kháng androgen: flutamide, bicalutamide; **ức chế androgen toàn bộ** (LHRH hoặc cắt tinh hoàn + kháng androgen) có lợi về sống còn cho nhiều bệnh nhân tiến triển {{Y5 tr.342}}\n- Điều trị **gián đoạn**: sau 6–7 tháng, nếu PSA <4 ng/ml thì ngừng và theo dõi PSA mỗi 3 tháng; PSA >10 ng/ml thì điều trị lại. Tử vong và thời gian không tiến triển tương đương với liên tục; gián đoạn cải thiện chất lượng sống và giảm chi phí {{Y5 tr.342–343}}\n- Nội tiết kèm xạ (nguy cơ TB–cao): kéo dài **6 tháng** (TB) đến **2–3 năm** (cao) {{Y5 tr.340}}\n- Tác dụng phụ: bừng mặt, tăng cân, liệt dương, loãng xương, tăng nguy cơ tim mạch và tiểu đường {{Y5 tr.342}}\n@@tab Hóa chất & thuốc (di căn, kháng cắt tinh hoàn)\n- **Docetaxel** chu kỳ mỗi 3 tuần: cải thiện sống còn, giảm triệu chứng; sau thất bại chuyển **cabazitaxel** (hóa trị bước 2) {{Y5 tr.343}}\n- **Abiraterone** (ức chế CYP17, enzyme tổng hợp testosterone); **enzalutamide** (ức chế thụ thể androgen) {{Y5 tr.345}}\n- Thuốc hướng di căn xương: acid zoledronic, denosumab, radium-223 {{Y5 tr.345}}\n@@end\n\n### 7.3 Phác đồ – Y lệnh\n\n> [!doc] Văn bản Bộ Y tế đã cung cấp: **QĐ 1514/QĐ-BYT** (1/4/2020), Bài 81 \"Cấy hạt phóng xạ điều trị ung thư tuyến tiền liệt\". Chỉ có **cấy hạt phóng xạ**; liều ghi dưới đây. {{QĐ1514 tr.PDF 703–711}}\n\n> [!warn] Chưa có văn bản Bộ Y tế trong tài liệu đã cung cấp cho **phác đồ nội khoa** (nội tiết, hóa chất, thuốc xương) của UTTL. Liều các thuốc trong Y5: **tài liệu không nêu**.\n\n| Phác đồ | Thuốc – liều | Chu kỳ / cách dùng | Chỉ định | Ghi chú |\n|---|---|---|---|---|\n| Cấy hạt **I-125** đơn trị | ==145 Gy== {{QĐ1514 tr.PDF 707}} | cấy vĩnh viễn, liều phát chậm trong vài tháng {{QĐ1514 tr.PDF 706}} | nguy cơ **thấp** | cấy áp sát đơn thuần {{QĐ1514 tr.PDF 707}} |\n| Cấy hạt **Pd-103** đơn trị | ==125 Gy== {{QĐ1514 tr.PDF 707}} | như trên | nguy cơ thấp | {{QĐ1514 tr.PDF 707}} |\n| Cấy I-125 sau xạ ngoài 40–50 Gy | ==110 Gy== {{QĐ1514 tr.PDF 707}} | ± nội tiết 4–6 tháng {{QĐ1514 tr.PDF 707}} | nguy cơ **trung bình** | xạ ngoài 40–50 Gy + cấy {{QĐ1514 tr.PDF 707}} |\n| Cấy Pd-103 sau xạ ngoài 40–50 Gy | ==100 Gy== {{QĐ1514 tr.PDF 707}} | ± nội tiết 4–6 tháng | nguy cơ trung bình | {{QĐ1514 tr.PDF 707}} |\n| Lập kế hoạch: liều PTV | 108–110 Gy {{QĐ1514 tr.PDF 709}} | theo kế hoạch siêu âm | — | CTV V100 ≥95%, V150 ≤50%; trực tràng D2cc < liều chỉ định, D0.1cc <200 Gy; niệu đạo D10% <150% liều chỉ định, D30% <130% liều chỉ định {{QĐ1514 tr.PDF 709}} |\n\nThuốc và xạ trong Y5 (giáo trình, không phải văn bản Bộ Y tế):\n\n| Thuốc / phương pháp | Liều – chu kỳ | Ghi chú |\n|---|---|---|\n| Xạ ngoài TTL + hạch chậu | ==74–80 Gy== + ==46 Gy== hạch chậu {{Y5 tr.340}} | IMRT |\n| LHRH (leuprolide, goserelin) | tài liệu không nêu liều {{Y5 tr.342}} | hồi phục |\n| Flutamide, bicalutamide | tài liệu không nêu liều {{Y5 tr.342}} | kháng androgen |\n| Docetaxel | tài liệu không nêu liều; chu kỳ 3 tuần {{Y5 tr.343}} | bước 1 khi di căn |\n| Cabazitaxel | tài liệu không nêu liều {{Y5 tr.343}} | sau docetaxel |\n| Abiraterone; enzalutamide | tài liệu không nêu liều {{Y5 tr.345}} | kháng cắt tinh hoàn |\n| Acid zoledronic; denosumab; radium-223 | tài liệu không nêu liều {{Y5 tr.345}} | di căn xương |\n\n> [!warn] Tác dụng phụ sau cấy hạt (QĐ1514): tiểu nhiều lần, tiểu dắt, tiểu buốt (hết sau 4–6 tuần); bí tiểu, tiểu không tự chủ; tiểu máu (thường hết sau 3–5 ngày); đau rát và chảy máu trực tràng, tiêu chảy. Muộn: viêm trực tràng mạn, viêm bàng quang mạn, tiểu khó do hẹp niệu đạo, rối loạn cương dương (ít gặp). {{QĐ1514 tr.PDF 710–711}}\n\n> [!warn] Mâu thuẫn trong QĐ1514: cấy I-125 đơn trị ghi liều **145 Gy** ở phần chỉ định, nhưng phần lập kế hoạch ghi liều lên PTV **108–110 Gy**. Ghi cả hai, đối chiếu bản gốc trước khi dùng. {{QĐ1514 tr.PDF 707}} {{QĐ1514 tr.PDF 709}}\n\n@@fold Chống chỉ định cấy hạt (QĐ1514)\n- Ung thư tổn thương rộng, di căn, thể trạng kém; tắc nghẽn đường bài niệu nặng; chống chỉ định gây mê {{QĐ1514 tr.PDF 707}}\n- Suy tim, suy hô hấp nặng; thời gian sống thêm dưới 5 năm {{QĐ1514 tr.PDF 707}}\n- TTL lớn hoặc thùy giữa lớn: cân nhắc nội tiết trước rồi đánh giá lại {{QĐ1514 tr.PDF 707}}\n@@end\n\n## 8. Tiên lượng – Dự phòng\n\n> [!key] Tóm tắt\n> - Tiên lượng chính: **giai đoạn và nhóm nguy cơ** (Gleason, PSA, T); khi hạch vùng bị xâm lấn thì thường đã có di căn xa {{Y5 tr.332}} {{Y5 tr.335}}\n> - Tầm soát: **PSA + thăm trực tràng** định kỳ ở nam trên 50 tuổi; chi phí – lợi ích chưa thuyết phục {{QĐ1514 tr.PDF 711}} {{Y5 tr.345}}\n\n### Tiên lượng\n@@tabs\n@@tab Yếu tố tiên lượng\n| Yếu tố | Nội dung |\n|---|---|\n| Gleason | 6 (3+3) tốt; 10 (5+5) xấu nhất; độ mô học cao thường di căn hạch và di căn xa {{Y5 tr.334–335}} |\n| Giai đoạn T/N/M | khi hạch vùng bị xâm lấn thì hầu như đã có di căn xa {{Y5 tr.332}} |\n| PSA | một trong ba yếu tố xếp nhóm nguy cơ (cùng T và Gleason) {{Y5 tr.339}}; sau tái phát, PSA tăng gấp đôi trong <6 tháng là yếu tố xấu {{Y5 tr.342}} |\n| Gen mầm (BRCA) | mang đột biến BRCA thường tiên lượng xấu hơn {{Y5 tr.330}} |\n| Tuổi | kỳ vọng sống thêm là căn cứ chọn điều trị (tài liệu không nêu yếu tố tuổi là tiên lượng độc lập) {{Y5 tr.341}} |\n@@tab Sống còn & kiểm soát\n- Sống 5 năm (Mỹ ==98%==, châu Âu 2003–2007 ==83%==) {{Y5 tr.329}}\n- Nhóm nguy cơ thấp: các mô thức điều trị đạt kiểm soát bệnh ==90–95%== trong 5 năm {{Y5 tr.341}}\n- Tái phát theo nhóm nguy cơ: thấp ==5%==; trung bình ==20–30%==; cao ==50%== {{Y5 tr.339}}\n- Nội tiết giảm nhẹ triệu chứng ở ==80%== trường hợp {{Y5 tr.342}}\n@@tab Theo dõi\n- **Sau điều trị triệt để**: theo dõi bằng PSA và khám lâm sàng; hình ảnh không thường quy nếu không nghi tái phát {{Y5 tr.341}}\n- **Tái phát sinh hóa**: sau phẫu thuật PSA ≥0,2 ng/ml hai lần liên tiếp; sau xạ trị PSA tăng >2 ng/ml so với nadir {{Y5 tr.342}}\n- **Nội tiết gián đoạn**: PSA mỗi 3 tháng khi ngừng thuốc; PSA >10 ng/ml thì điều trị lại {{Y5 tr.342–343}}\n- **Kháng cắt tinh hoàn**: testosterone <50 ng/ml đang ADT + PSA tăng 3 lần liên tiếp (tăng >50% và ≥2 ng/ml so với nadir) **hoặc** ≥2 tổn thương xương/mô mềm mới; tiến triển triệu chứng đơn thuần không đủ {{Y5 tr.343}}\n@@end\n\n### Dự phòng\n@@tabs\n@@tab Cấp 1 (phòng bệnh)\n- Chưa có bằng chứng rõ về biện pháp phòng ngừa hữu hiệu; có thể giảm nguy cơ bằng chế độ ăn ít năng lượng, nhiều rau quả, tập thể dục đều {{Y5 tr.329}}\n- Tránh béo phì và lối sống ít vận động (liên quan tăng nguy cơ) {{Y5 tr.330}}\n@@tab Cấp 2 (tầm soát)\n- Đối tượng: **nam trên 50 tuổi**; khám thăm trực tràng, siêu âm TTL và định lượng PSA định kỳ {{QĐ1514 tr.PDF 711}} {{Y5 tr.332}}\n- Không tầm soát PSA cho người không có triệu chứng và có kỳ vọng sống ngắn; trên 75 tuổi chỉ tầm soát trong tình huống đặc biệt (ví dụ PSA đo trước tuổi 70 cao hơn trị số trung bình theo tuổi, hoặc sức khỏe rất tốt) {{Y5 tr.332}}\n- PSA <1 ng/ml: giãn khoảng cách (ví dụ 5 năm); kết thúc tầm soát lúc 60 tuổi nếu PSA duy trì <1 ng/ml {{Y5 tr.332}}\n- Chưa là chương trình y tế chính thức ở quốc gia nào; cân nhắc chi phí – lợi ích {{Y5 tr.332}} {{Y5 tr.345}}\n@@tab Cấp 3 (xử trí biến chứng)\n- Xạ trị giảm đau di căn xương; xạ trị cấp cứu khi chèn ép tủy; cắt đốt TTL qua niệu đạo giảm tắc nghẽn {{Y5 tr.343}}\n- Điều trị triệt để khi chuyển nhóm nguy cơ cao hơn sau theo dõi tích cực {{Y5 tr.341}}\n@@end\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] Bệnh này thi nhấn mạnh gì (nhóm điều trị theo nguy cơ)\n> - **Chẩn đoán**: sinh thiết qua trực tràng dưới siêu âm → carcinôm tuyến + Gleason; PSA và TNM là nền để xếp nhóm nguy cơ {{Y5 tr.333–334}} {{Y5 tr.339}}\n> - **Xếp nhóm nguy cơ** (T, Gleason, PSA) quyết định điều trị tại chỗ {{Y5 tr.339}} {{QĐ1514 tr.PDF 706}}\n> - **Điều trị** theo nhóm: thấp → theo dõi tích cực; TB/cao → phẫu thuật hoặc xạ + nội tiết; di căn → nội tiết, kháng cắt tinh hoàn {{Y5 tr.341}} {{Y5 tr.343}}\n> - Trọng số thi theo QĐ 22 (mục 4.2): dòng Cận lâm sàng / XN chẩn đoán 45–60; dòng Liệu pháp thuốc 35–50; nguồn không nêu là trọng số dòng hay nhóm {{QĐ22 tr.8}}\n\n@@tabs\n@@tab Nhận diện\n- Nguy cơ then chốt: **tuổi trên 50**, gen (BRCA1/2, HOXB13), chủng tộc (Mỹ gốc Phi cao nhất), béo phì và lười vận động {{Y5 tr.329}} {{Y5 tr.330}}\n- Triệu chứng: rối loạn đi tiểu, tiểu máu, bí tiểu; sụt cân, thiếu máu {{Y5 tr.333}} {{QĐ1514 tr.PDF 703}}\n- {r|Báo động}: yếu liệt hai chân, tiểu không tự chủ → di căn chèn ép tủy {{Y5 tr.333}}\n- Di căn: đau xương, lưng, vùng chậu; gãy xương bệnh lý {{Y5 tr.333}} {{QĐ1514 tr.PDF 704}}\n- Khám trực tràng: TTL to, cứng, không đau; khám bình thường **không loại trừ** ung thư {{Y5 tr.333}}\n[Xem mục 4](#/n/ung-thu-tien-liet/4) · [mục 3](#/n/ung-thu-tien-liet/3)\n@@tab Chẩn đoán\n- Xác định = **mô bệnh học** (sinh thiết 12 lõi qua trực tràng) {{Y5 tr.333–334}}\n- Gleason: sinh thiết = mức nhiều nhất + mức cao nhất; phẫu thuật = mức nhiều nhất + mức nhiều thứ 2 {{Y5 tr.334–335}}\n- {g|Sinh thiết khi TTL rắn hoặc PSA >4 ng/ml} {{QĐ1514 tr.PDF 711}}\n- PSA: ngưỡng 4; nguy cơ ung thư 20–30% (4–10), 50–75% (10–20), đến 90% (>20) {{Y5 tr.336}}\n- TNM: T1 tình cờ/ sinh thiết, T2 khu trú (a/b/c theo thùy), T3 ngoài vỏ bao/túi tinh, T4 cơ quan lân cận {{QĐ1514 tr.PDF 705}}\n- Xạ hình xương chỉ khi nguy cơ trung bình/cao; PET/CT ít giá trị cho u nguyên phát {{Y5 tr.337–338}} {{QĐ1514 tr.PDF 704}}\n[Xem mục 5](#/n/ung-thu-tien-liet/5) · [mục 6](#/n/ung-thu-tien-liet/6)\n@@tab Điều trị\n- **Nhóm thấp**: {g|theo dõi tích cực} (kỳ vọng sống trên 10 năm; PSA mỗi 6 tháng trong 18 tháng) {{Y5 tr.341}}\n- **Nhóm trung bình**: phẫu thuật hoặc xạ ngoài + nội tiết 6 tháng; cấy hạt (Y5) giới hạn ở TB \"thấp\" (PSA <15 hoặc Gleason 3+4) {{Y5 tr.341}}\n- **Nhóm cao**: xạ ngoài + nội tiết 2–3 năm (ưu tiên); phẫu thuật tận gốc khi chọn {{Y5 tr.341}}\n- **Phẫu thuật**: cắt tận gốc + túi tinh + nạo hạch chậu (khi nguy cơ hạch >2%) {{Y5 tr.340}}\n- **Xạ ngoài**: TTL ==74–80 Gy==, hạch chậu ==46 Gy== {{Y5 tr.340}}\n- **Di căn**: {p|nội tiết} (cắt tinh hoàn/LHRH + kháng androgen); kháng cắt tinh hoàn → {p|abiraterone}, {p|enzalutamide}, {p|docetaxel}, {p|cabazitaxel} {{Y5 tr.342–345}}\n- {r|Chèn ép tủy}: xạ trị cấp cứu {{Y5 tr.343}}\n[Xem mục 7.2](#/n/ung-thu-tien-liet/7) · [mục 7.3](#/n/ung-thu-tien-liet/7)\n@@tab Tiên lượng – Dự phòng\n- Tiên lượng: giai đoạn, Gleason, PSA; mang BRCA thường xấu hơn {{Y5 tr.330}} {{Y5 tr.334–335}}\n- Sống 5 năm (Mỹ ==98%==; châu Âu ==83%==) {{Y5 tr.329}}\n- Tái phát: thấp ==5%==, trung bình ==20–30%==, cao ==50%== {{Y5 tr.339}}\n- **Tầm soát**: {g|PSA + thăm trực tràng từ 50 tuổi}; PSA <1 → giãn 5 năm, dừng 60 tuổi {{Y5 tr.332}} {{QĐ1514 tr.PDF 711}}\n- {o|Dự phòng bậc 1 chưa có bằng chứng rõ} {{Y5 tr.329}}\n[Xem mục 8](#/n/ung-thu-tien-liet/8)\n@@end\n\n> [!warn] Bẫy thi thường gặp\n> - **Nhóm nguy cơ lệch giữa ba nguồn** (T2c, T3): xem mục 5; Y5 không có nhóm \"rất cao\" {{Y5 tr.339}} {{SY5 tr.144}} {{QĐ1514 tr.PDF 705–706}}\n> - **Tỷ lệ PSA tự do**: Y5 ≤25% nguy cơ tăng; QĐ1514 <20% nghi ngờ nhiều hơn {{Y5 tr.337}} {{QĐ1514 tr.PDF 704}}\n> - **Di căn phổi**: Y5 hiếm; QĐ1514 hay gặp {{Y5 tr.332}} {{QĐ1514 tr.PDF 703}}\n> - **Thời điểm phát hiện**: Y5 (Âu–Mỹ) phần lớn khu trú; QĐ1514 một nửa đã có di căn xa {{Y5 tr.329}} {{QĐ1514 tr.PDF 703}}\n> - **Đồng vị cấy hạt**: Y5 I-125 hoặc Iridium-192; QĐ1514 I-125 hoặc Pd-103 {{Y5 tr.340}} {{QĐ1514 tr.PDF 706–707}}\n> - **Cấy hạt cho nhóm nào**: phần xạ trị của Y5 chỉ nguy cơ thấp, phần nhóm nguy cơ giới hạn TB \"thấp\"; QĐ1514 đơn trị cho nguy cơ thấp, kèm xạ ngoài cho TB {{Y5 tr.340–341}} {{QĐ1514 tr.PDF 707}}\n> - **Nội tiết kèm xạ nguy cơ TB**: Y5 6 tháng; QĐ1514 4–6 tháng {{Y5 tr.340}} {{QĐ1514 tr.PDF 707}}\n> - **Liều I-125**: 145 Gy (đơn trị) và 108–110 Gy (PTV) trong cùng QĐ1514 — đối chiếu bản gốc {{QĐ1514 tr.PDF 707}} {{QĐ1514 tr.PDF 709}}\n> - **GLOBOCAN %**: Y5 ghi 3,8% trong ung thư nam; SY5 không ghi rõ mẫu số — không trộn {{Y5 tr.329}} {{SY5 tr.36}}\n> - **Bảng nhóm giai đoạn** chỉ có ở Y5 (bảng nhóm giai đoạn cuối mục 5); QĐ1514 không có {{Y5 tr.339}}\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Tuổi bắt đầu tầm soát PSA + thăm trực tràng | ==trên 50 tuổi== | {{Y5 tr.332}} {{QĐ1514 tr.PDF 711}} |\n| Ngưỡng PSA chỉ định sinh thiết | ==>4 ng/ml hoặc TTL rắn== | {{QĐ1514 tr.PDF 711}} |\n| PSA <1 ng/ml khi tầm soát | ==giãn 5 năm; dừng lúc 60 tuổi== | {{Y5 tr.332}} |\n| Nguy cơ ung thư theo PSA | ==4–10: 20–30%; 10–20: 50–75%; >20: 90%== | {{Y5 tr.336}} |\n| Gleason 6 / 10 | ==6 (3+3) tốt; 10 (5+5) xấu nhất== | {{Y5 tr.335}} |\n| Sinh thiết | ==12 lõi== (2 đáy, 2 đỉnh, 2 giữa mỗi bên) | {{Y5 tr.334}} |\n| Xạ hình xương khi PSA cao | ==PSA 10–50: 10%; >50: 50%== | {{Y5 tr.337}} |\n| Nhóm thấp (Y5) | ==<T2b, PSA ≤10, Gleason ≤6== | {{Y5 tr.339}} |\n| Xạ ngoài TTL / hạch chậu | ==74–80 Gy / 46 Gy== | {{Y5 tr.340}} |\n| Nạo hạch chậu | ==khi nguy cơ di căn hạch >2%== | {{Y5 tr.340}} |\n| Cấy hạt I-125 đơn trị | ==145 Gy== | {{QĐ1514 tr.PDF 707}} |\n| Nội tiết kèm xạ (nguy cơ cao) | ==2–3 năm== | {{Y5 tr.340}} |\n| Theo dõi tích cực | ==PSA mỗi 6 tháng trong 18 tháng== | {{Y5 tr.341}} |\n| Tái phát sinh hóa sau phẫu thuật | ==PSA ≥0,2 ng/ml, hai lần liên tiếp== | {{Y5 tr.342}} |\n| Kháng cắt tinh hoàn (tiêu chuẩn PSA) | ==>50% và ≥2 ng/ml so với nadir, tăng 3 lần== | {{Y5 tr.343}} |\n| Sống 5 năm (khu trú, Mỹ) | ==98%== | {{Y5 tr.329}} |\n\n@@fold Nguồn tài liệu\n- **Y5**: TEXT UNG BƯỚU Y5.pdf, tr.329–345 (`_work/text-ung-buou-y5.txt`); nhóm nguy cơ và bảng TNM đối chiếu ảnh tr.338–339 (`_work/img-tien-liet-y5/`)\n- **QĐ 1514/QĐ-BYT** (1/4/2020), Bài 81, tr. PDF 703–711 (`_work/qd-1514-byt-ung-buou.txt`)\n- **SY5** tr.18, 36, 144 (`_work/slide-y5.txt`)\n- **ĐC Y5** tr.2–4 (mô tả MT), tr.7 (ca lâm sàng UTTL) (`_work/decuong-y5.txt`)\n- **128VĐ** mục 75, 80, 81, 82 (`data/book-items.json`)\n- **QĐ 22** mục 4.2 tr.8; STT 65, 66, 67, 99 (`data/qd22.json`)\n@@end\n\n@@fold Nguồn ngoài\n- Không sử dụng nguồn ngoài; mọi số liệu, phác đồ và nhãn lấy từ các tài liệu trên.\n@@end\n\n@@fold Tự kiểm tra (15 thẻ)\n- Ung thư tuyến tiền liệt đứng thứ mấy ở nam về tần suất? :: Thứ 2 (sau ung thư phổi) {{Y5 tr.329}}\n- Tuổi bắt đầu tầm soát PSA và thăm trực tràng? :: Nam trên 50 tuổi {{QĐ1514 tr.PDF 711}} {{Y5 tr.332}}\n- Khi nào sinh thiết (theo QĐ1514)? :: TTL rắn hoặc PSA >4 ng/ml {{QĐ1514 tr.PDF 711}}\n- Chẩn đoán xác định UTTL dựa vào gì? :: Sinh thiết qua trực tràng dưới siêu âm, 12 lõi; mô bệnh học carcinôm tuyến {{Y5 tr.333–334}}\n- Gleason sinh thiết tính thế nào? :: Mức nhiều nhất + mức cao nhất {{Y5 tr.334}}\n- Gleason 6 (3+3) và 10 (5+5) tiên lượng ra sao? :: 6 (3+3) tốt nhất; 10 (5+5) xấu nhất, thường tử vong do di căn xa {{Y5 tr.335–336}}\n- Nguy cơ ung thư theo PSA 4–10, 10–20 và >20? :: 20–30%, 50–75%, đến 90% {{Y5 tr.336}}\n- Nhóm nguy cơ thấp theo Y5 gồm gì? :: Bướu <T2b, PSA ≤10, Gleason ≤6 {{Y5 tr.339}}\n- Điều trị nguy cơ thấp? :: Theo dõi tích cực; PSA mỗi 6 tháng trong 18 tháng {{Y5 tr.341}}\n- Nguy cơ cao điều trị ra sao? :: Xạ ngoài + nội tiết 2–3 năm (ưu tiên); phẫu thuật tận gốc khi chọn {{Y5 tr.341}}\n- Liều xạ ngoài TTL và hạch chậu? :: TTL 74–80 Gy; hạch chậu 46 Gy {{Y5 tr.340}}\n- Cấy hạt I-125 đơn trị liều? :: 145 Gy; Pd-103 125 Gy {{QĐ1514 tr.PDF 707}}\n- Tái phát sinh hóa sau phẫu thuật? :: PSA ≥0,2 ng/ml hai lần liên tiếp {{Y5 tr.342}}\n- Tiêu chuẩn kháng cắt tinh hoàn? :: Testosterone <50 ng/ml khi ADT + PSA tăng 3 lần (>50%, ≥2 ng/ml so với nadir) hoặc ≥2 tổn thương mới {{Y5 tr.343}}\n- Chèn ép tủy do di căn xử trí thế nào? :: Xạ trị cấp cứu {{Y5 tr.343}}\n@@end"}, {"kind": "disease", "disease": "tuyen-giap", "short": "Ung thư tuyến giáp", "group": "", "section": 0, "order": 11, "khung": [95, 96], "id": "ung-thu-tuyen-giap", "title": "Ung thư tuyến giáp", "layer": "benh", "module": "ung-buou", "tags": ["ung bướu", "tuyến giáp", "nhân giáp", "TIRADS", "Bethesda", "FNA", "thyroglobulin", "iod phóng xạ", "RET", "MEN2", "thể nhú", "thể nang", "thể tủy", "không biệt hóa", "TNM AJCC 8"], "source": "Y5 tr.215–238 (chương UNG THƯ TUYẾN GIÁP, đọc toàn bộ; Bảng 14–21 đối chiếu ảnh tr.223, 226–227, 230, 236–237); SY5 tr.36–38, 126, 132, 200; QĐ1514 Bài 29 (tr. PDF 217–224); ĐC Y5 tr.2–4, 7; 128VĐ mục 113, 114; QĐ 22 STT 95, 96 (tr.6), trọng số tr.8", "body": "> [!key] Ung thư tuyến giáp (UTTG) trong một nhìn\n> - Đa số là **thể biệt hóa** (nhú 80–90%, nang, Hürthle): tiến triển chậm, tiên lượng tốt; thể tủy và không biệt hóa hiếm (1–2%) nhưng ác hơn {{Y5 tr.218}} {{Y5 tr.220}} {{Y5 tr.221}}\n> - Triệu chứng nghèo nàn: thường là **khối ở cổ** (nhân giáp) phát hiện khi khám hoặc siêu âm tình cờ; muộn: khàn tiếng, khó nuốt, khó thở {{QĐ1514 tr.PDF 217}}\n> - Chẩn đoán: **siêu âm + FNA (Bethesda)**; mọi khối cổ nên được xem là ác tính cho đến khi được loại trừ bằng các bằng chứng chắc chắn {{Y5 tr.222}} {{Y5 tr.224}} {{128VĐ mục 114}}\n> - Điều trị: **phẫu thuật** là chủ đạo; iod phóng xạ (I-131) cho nhóm nguy cơ cao; levothyroxine ức chế TSH sau mổ {{QĐ1514 tr.PDF 221–222}} {{Y5 tr.231}}\n> - Tiên lượng: sống còn 10 năm có thể 95–99% ở thể biệt hóa {{Y5 tr.238}}\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Ung thư biểu mô tuyến giáp gồm 4 nhóm mô học: **nhú, nang** (biệt hóa, khoảng 90%), **tủy** (từ tế bào C, tiết calcitonin), **không biệt hóa** {{QĐ1514 tr.PDF 219}} {{Y5 tr.215}}\n> - Nguy cơ chính: **tia xạ vùng đầu cổ** lúc trẻ, di truyền (**RET** trong MEN2), béo phì; hút thuốc liên quan giảm nguy cơ {{Y5 tr.217}}\n\n### Định nghĩa & dịch tễ\n- Thế giới (GLOBOCAN 2018): khoảng ==567.000 ca mới/năm==, đứng thứ 11 trong ung thư cả hai giới {{QĐ1514 tr.PDF 217}}\n- Toàn cầu: tuyến giáp có 567.233 ca mới (3,1% tổng ung thư) và 41.071 tử vong (0,4%) {{SY5 tr.36}}\n- Xếp hạng theo giới: nữ thứ năm, nam thứ mười một (Y5; QĐ1514 ghi nam thứ 15, xem ô Bẫy ở mục 9) {{Y5 tr.216}}\n- Tần suất tăng (SEER): 4,8/100.000 (1975) lên 15/100.000 (2014), chủ yếu do phát hiện thể nhú \"tình cờ\" {{Y5 tr.216}}\n- Giới và tuổi: nữ cao gấp ~3 lần nam (EU: 9,3 so với 3,1/100.000); hay gặp nhất 45–54 tuổi {{Y5 tr.216}}\n- Tử suất thấp: 0,7/100.000 (nữ), 0,5/100.000 (nam); khác nhau lớn giữa các thể {{Y5 tr.216}}\n- Việt Nam: tuyến giáp là ung thư nữ thường gặp hạng 6 và thuộc nhóm \"phát hiện sớm\" {{SY5 tr.38}}. Số ca mắc/tử vong riêng của VN: tài liệu không nêu.\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Phóng xạ – di truyền\n- **Xạ trị vùng đầu cổ lúc trẻ** (thập niên 40–50 điều trị mụn, viêm khẩu cái, viêm mũi xoang): nguyên nhân rõ nhất của thể nhú; tác hại vẫn thấy sau hơn 60 năm {{Y5 tr.217}}\n- Phơi nhiễm phóng xạ khác: bom nguyên tử Hiroshima–Nagasaki, Chernobyl; tiền sử bướu đơn nhân hoặc đa nhân {{QĐ1514 tr.PDF 217}}\n- Thể nhú gia đình (FNMTC, di truyền trội, không rõ locus) chiếm **dưới 5%**; có 2 người bậc 1 mắc: 40–60% là ngẫu nhiên, **3 người bậc 1: 96% là di truyền** {{Y5 tr.217}}\n- **Tủy di truyền**: MEN2A và MEN2B do đột biến hoạt hóa gen **RET** (trội); đột biến de novo gặp ở 5–9% MEN2A và 75% MEN2B {{Y5 tr.217}}\n- Thể tủy: 75% là ngẫu nhiên, 25% có tính gia đình {{Y5 tr.220}}\n@@tab Môi trường – lối sống\n- **Béo phì** làm tăng nguy cơ; cơ chế chưa rõ {{Y5 tr.217}}\n- **Hút thuốc lá** liên quan với giảm nguy cơ; có ý kiến cho rằng giảm hút thuốc làm mất \"hiệu quả bảo vệ\" {{Y5 tr.217}}\n- Chất chống cháy PBDE có cấu trúc giống thyroxine: vai trò gây bệnh **chưa được chứng minh** {{Y5 tr.218}}\n- Tia xạ gây tái sắp xếp RET/PTC (đang giảm dần); đột biến BRAF và RAS không liên quan tia xạ ngày càng nhiều {{Y5 tr.217}}\n@@end\n\n### Sinh bệnh học & sinh học phân tử\n- Lộ trình **MAPK** được kích hoạt ở phần lớn UTTG: đột biến **BRAF**, **RAS**, hoặc tái sắp xếp **RET/PTC**, **NTRK** {{Y5 tr.218}}\n- Thể nhú chia 2 nhóm phân tử: \"giống **BRAF-V600E**\" hoặc \"giống **RAS**\"; thể nang thường liên quan RAS hoặc **PAX8–PPARγ** {{Y5 tr.225}}\n- Thể tủy: gen tiền ung thư **RET** (nhiễm sắc thể số 10) hoạt hóa MAPK và PI3K/AKT, dẫn đến tăng sinh tế bào {{Y5 tr.217}}\n\n### Giải phẫu bệnh – phân loại\n| Thể | Tỷ lệ | Đặc điểm chính |\n|---|---|---|\n| **Nhú** | 80–90% {{Y5 tr.218}} | Đa ổ 32–39% bệnh phẩm cắt {{Y5 tr.219}}; nhân \"mắt Annie mồ côi\" (pseudoinclusion) giúp chẩn đoán bằng FNA {{Y5 tr.219}}; hay di căn hạch |\n| **Nang** | 10–15% {{Y5 tr.220}} | Đơn ổ, có vỏ; xâm lấn tối thiểu (tiên lượng tốt), trung bình (1–4 ổ mạch), rộng (≥4 ổ mạch hoặc >4 cm, sống 10 năm kém) {{Y5 tr.220}}; di căn hạch khoảng 20% {{Y5 tr.220}} |\n| **Tủy** | 1–2% {{Y5 tr.220}} | Từ tế bào C tiết **calcitonin**; thấm amyloid; nhuộm calcitonin và CEA giúp phân biệt {{Y5 tr.220}} |\n| **Không biệt hóa** | 1–2% {{Y5 tr.221}} | Ác nhất; dễ nhầm với lymphôm, sarcôm; cần sinh thiết lõi và bác sĩ GPB nội tiết giàu kinh nghiệm {{Y5 tr.221}} |\n\n### Diễn tiến tự nhiên – lan tràn\n- **Nhú**: tiến triển rất chậm; di căn hạch sớm, khoảng một nửa lúc chẩn đoán (một số nghiên cứu đến 85%) {{Y5 tr.219}}\n- Xâm lấn ngoài hạch có tỷ lệ tái phát **15–30%** {{Y5 tr.219}}\n- Di căn xa **<5%** lúc chẩn đoán; **phổi** là vị trí hay gặp nhất và thường là nguyên nhân tử vong chính {{Y5 tr.220}}\n- **Nang**: lan theo đường máu đến phổi, xương, thần kinh trung ương; di căn xa lúc chẩn đoán đến 20% {{Y5 tr.220}}\n- **Tủy**: di căn hạch đến 50%, di căn xa thường gặp, tiên lượng xấu hơn thể biệt hóa {{Y5 tr.221}}\n- **Không biệt hóa**: xâm lấn tại chỗ gây ngạt thở nếu không điều trị; hóa–xạ trị thì tử vong do di căn xa {{Y5 tr.221}}\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Triệu chứng **nghèo nàn**; thường gặp nhất là **khối ở cổ** (nhân giáp) hoặc phát hiện tình cờ qua siêu âm {{QĐ1514 tr.PDF 217}}\n> - Gợi ý ác tính: nhân **cứng, dính, lớn nhanh, khàn tiếng, có hạch cổ** cùng bên {{QĐ1514 tr.PDF 218}} {{Y5 tr.221}}\n\n### Triệu chứng cơ năng\n- Giai đoạn đầu: thường không có triệu chứng; thường phát hiện khi tự sờ hoặc khám sức khỏe định kỳ {{QĐ1514 tr.PDF 217}}\n- Giai đoạn muộn: **khàn tiếng** (chèn ép hoặc xâm lấn dây thần kinh quặt ngược; u lành hiếm gây khàn), khó nuốt (chèn thực quản), khó thở (xâm lấn khí quản) {{QĐ1514 tr.PDF 217}}\n- Triệu chứng hay gặp: khối vùng cổ, cảm giác chèn ép, đau vùng cổ, ho, khó thở, khó nuốt {{Y5 tr.221}}\n- Bệnh sử **tiến triển nhanh** của nhân hoặc hạch gợi ý không biệt hóa hoặc lymphôm {{Y5 tr.221}}\n- Một số bệnh nhân đến khám vì di căn (phổi, xương) trước khi sờ thấy bướu giáp {{Y5 tr.221}}\n\n### Thực thể\n- Nhân: thường **đơn độc** ở một thùy hoặc eo giáp; ít khi đa ổ hoặc cả hai thùy {{QĐ1514 tr.PDF 218}}\n- Hạch cổ: đa số nhóm VI, cùng bên; rắn, không đau; còn di động khi chưa xâm lấn, hạn chế khi to hoặc xâm lấn {{QĐ1514 tr.PDF 218}}\n- Dấu hiệu nghi ác: **lớn nhanh, mật độ cứng, dính cấu trúc lân cận, tiền sử gia đình UTTG, khàn tiếng, khó nuốt, da thâm nhiễm hoặc loét chảy máu, kèm hạch cổ** {{QĐ1514 tr.PDF 218}}\n- Cứng, không đàn hồi, dính, có hạch: chỉ gợi ý, không đủ để chẩn đoán xác định {{Y5 tr.221}}\n\n### Tiếp cận các triệu chứng (khung 128 vấn đề)\n| STT | Vấn đề | Nguyên nhân cần nghĩ |\n|---|---|---|\n| [96](#/khung/96) | **Khối ở cổ** | Ung thư tuyến giáp, hạch di căn từ ung thư tế bào gai vùng đầu cổ, lymphôm; bướu lành (nhân giáp, bướu mỡ, nang giáp lưỡi, u tuyến cận giáp); nhiễm trùng {{128VĐ mục 114}} |\n| [95](#/khung/95) | **Rối loạn chức năng tuyến giáp** | Cường giáp (bướu nhân độc, Basedow), suy giáp (Hashimoto, sau phẫu thuật hoặc xạ trị tuyến giáp); TSH định hướng xạ hình, nhân giáp cần TIRADS và FNA {{128VĐ mục 113}} |\n\n## 5. Cận lâm sàng\n\n> [!key] Tóm tắt\n> - **Siêu âm** vùng cổ (tuyến giáp và hạch hai bên) là hình ảnh hàng đầu; phân loại **TIRADS** để chỉ định FNA {{Y5 tr.222}} {{Y5 tr.223}}\n> - **FNA** (Bethesda) là xét nghiệm chính xác nhất với nhân giáp; FNA không đủ thông tin thì sinh thiết lõi hoặc sinh thiết mở {{Y5 tr.224}} {{128VĐ mục 114}}\n> - **TSH** cho mọi bệnh nhân; **calcitonin** khi nghi thể tủy; **Tg** là chỉ điểm theo dõi sau mổ {{Y5 tr.222}} {{QĐ1514 tr.PDF 219}}\n\n### Chẩn đoán hình ảnh\n@@tabs\n@@tab Siêu âm\n- Đặc điểm nghi ác: nhân **đặc, vi vôi hóa, phản âm kém, bờ không đều, cao > rộng**, tăng sinh mạch {{Y5 tr.222}} {{QĐ1514 tr.PDF 218}}\n- Hạch nghi di căn: tròn, tỷ lệ trục trước–sau >0,5, vi vôi hóa, dạng nang, tăng sinh mạch quanh hạch {{Y5 tr.222}}\n- Thể nang: thường đồng hoặc tăng phản âm, tăng sinh mạch trong nhân; thể tủy: phản âm kém, có vôi hóa {{Y5 tr.222}}\n- Khi sờ thấy 1 nhân, siêu âm thấy nhiều nhân ở 48% trường hợp; 72% nhân mới phát hiện có kích thước <1 cm {{Y5 tr.222}}\n- Siêu âm hướng dẫn FNA chính xác hơn, nhất là với u nhỏ hoặc nhân sau thùy {{Y5 tr.224}} {{QĐ1514 tr.PDF 218}}\n@@tab TIRADS (ACR)\n| Điểm | TIRADS | Phân loại | Chỉ định FNA | Theo dõi siêu âm |\n|---|---|---|---|---|\n| 0 | TR1 | Lành tính | Không | Không cần thiết {{Y5 tr.223}} |\n| 2 | TR2 | Không nghi ngờ | Không | Không cần thiết {{Y5 tr.223}} |\n| 3 | TR3 | Nghi ngờ ít | ≥2,5 cm | Nếu ≥1,5 cm: theo dõi năm 1, 3, 5 {{Y5 tr.223}} |\n| 4–6 | TR4 | Nghi ngờ trung bình | ≥1,5 cm | Nếu ≥1 cm: theo dõi mỗi năm {{Y5 tr.223}} |\n| ≥7 | TR5 | Rất nghi ngờ | ≥1 cm | Nếu ≥0,5 cm: mỗi năm trong 5 năm {{Y5 tr.223}} |\n\nĐiểm TIRADS cộng từ 5 yếu tố (cấu thành, độ phản âm, hình dạng, giới hạn, nốt tăng âm) theo Bảng 14 {{Y5 tr.223}}.\n@@tab Xạ hình – PET – CT/MRI\n- Xạ hình iod (hoặc 99mTc): tế bào ung thư ít bắt iod, thể hiện là **nhân lạnh**; nhân nóng hiếm ác tính, nhưng nếu siêu âm nguy cơ cao thì vẫn cần sinh thiết {{Y5 tr.224}} {{QĐ1514 tr.PDF 218}}\n- Chỉ 5–10% nhân sờ thấy là nhân nóng: phải phối hợp với siêu âm khi quyết định {{Y5 tr.224}}\n- CT/MRI: đánh giá xâm lấn khí quản, thực quản, phần mềm cổ và di căn xa; **không phân biệt được lành hay ác** {{Y5 tr.224}}\n- 18FDG-PET: **không khuyến cáo** chẩn đoán UTTG {{Y5 tr.224}}; dùng theo dõi khi Tg tăng cao mà siêu âm và CT/MRI âm tính (Tg >10 ng/mL) {{QĐ1514 tr.PDF 223}} {{Y5 tr.237}}\n@@end\n\n### Tế bào – mô bệnh học\n- **FNA** dưới hướng dẫn siêu âm là tiêu chuẩn hiện nay; độ chính xác khoảng 90–95% (QĐ1514) hoặc 85–100% (trung bình 95%, Y5) {{QĐ1514 tr.PDF 218}} {{Y5 tr.225}}\n- Y5: FNA không kèm xét nghiệm phân tử có độ nhạy 65–98% (trung bình 83%), đặc hiệu 72–100% (trung bình 92%), âm giả 1–11% {{Y5 tr.225}}\n- **Bethesda** (6 nhóm): nguy cơ ác tính Bethesda III 5–15%, IV 15–30%, V 60–75% {{Y5 tr.225}}; Bethesda V là nghi ngờ ác tính, VI là ác tính {{Y5 tr.224}}\n- **Xét nghiệm phân tử** cho Bethesda III và IV, giá trị tiên đoán âm cao để loại trừ ung thư; Bethesda V không cần vì nguy cơ đã cao {{Y5 tr.225}}\n- **Sinh thiết lõi kim** cần khi nghi không biệt hóa (FNA dễ nhầm); sinh thiết mở khi FNA không đủ thông tin {{Y5 tr.221}} {{128VĐ mục 114}}\n- **Sinh thiết tức thì** trong mổ giúp phẫu thuật viên chọn phương pháp mổ {{QĐ1514 tr.PDF 219}}\n\n### Sinh hóa – chỉ điểm\n- **TSH** ở mọi bệnh nhân; TSH thấp thì làm xạ hình để tìm nhân tăng chức năng; TSH bình thường không loại trừ nhân tăng hoạt {{Y5 tr.222}}\n- **Calcitonin** huyết thanh giúp phát hiện sớm thể tủy (FNA không luôn phân biệt được tủy và nang); không đo thường quy cho mọi nhân giáp vì tăng giả trong Hashimoto, hút thuốc và bệnh thận {{Y5 tr.222}}\n- Thể tủy theo dõi thêm **CEA** cùng calcitonin {{QĐ1514 tr.PDF 223}}\n- **Thyroglobulin (Tg)**: chỉ định đầu tiên khi theo dõi thể biệt hóa; khoảng tham chiếu 3–40 ng/mL (tuyến giáp còn nguyên, TSH bình thường) {{Y5 tr.235}}\n- Anti-Tg có ở khoảng 25% bệnh nhân làm kết quả Tg khó diễn giải; phải đo anti-Tg trước khi tin kết quả Tg {{Y5 tr.235}}\n- Tg thường xét nghiệm 4–6 tuần sau mổ để quyết định điều trị iod phóng xạ {{Y5 tr.236}}\n\n### Phân giai đoạn TNM (AJCC/UICC 8, 2017)\n- Y5 và QĐ1514 đều dùng AJCC 8; **ngưỡng tuổi 55** (trước đây 45) quyết định nhóm giai đoạn {{Y5 tr.225}} {{QĐ1514 tr.PDF 220}}\n| T | Mô tả (Bảng 16 Y5) |\n|---|---|\n| T1a | ≤1 cm, giới hạn trong tuyến giáp {{Y5 tr.226}} |\n| T1b | >1–2 cm, giới hạn trong tuyến giáp {{Y5 tr.226}} |\n| T2 | >2–4 cm, giới hạn trong tuyến giáp {{Y5 tr.226}} |\n| T3a | >4 cm, giới hạn trong tuyến giáp {{Y5 tr.226}} |\n| T3b | Xâm lấn ngoài tuyến giáp chỉ đến cơ strap (ức móng, ức giáp, giáp móng, vai móng), kích thước bất kỳ {{Y5 tr.226}} (khác QĐ1514, xem ô Bẫy ở mục 9) |\n| T4a | Xâm lấn đại thể: mô mềm dưới da, thanh quản, khí quản, thực quản, thần kinh thanh quản quặt ngược {{Y5 tr.226}} {{QĐ1514 tr.PDF 220}} |\n| T4b | Xâm lấn đại thể: cân mạc trước sống, động mạch cảnh hoặc mạch máu trung thất {{Y5 tr.226}} {{QĐ1514 tr.PDF 220}} |\n\n- **N**: N0a (≥1 hạch lành tính đã xác định bằng tế bào hoặc mô học); N0b (không có hạch di căn trên hình ảnh hoặc lâm sàng); N1a (di căn nhóm VI hoặc VII: trước khí quản, cạnh khí quản, trước thanh quản Delphian, trung thất trên); N1b (di căn cổ một bên, hai bên, đối bên nhóm I–V, hoặc hạch sau thanh quản) {{Y5 tr.226}} {{QĐ1514 tr.PDF 220}}\n- **M**: M0 không di căn xa; M1 có di căn xa {{Y5 tr.226}}\n\n| Nhóm tuổi | Giai đoạn (AJCC 8) | Nguồn |\n|---|---|---|\n| <55 tuổi | I: mọi T, mọi N, M0. II: mọi T, mọi N, M1 | {{Y5 tr.226}} {{QĐ1514 tr.PDF 220}} |\n| ≥55 tuổi | I: T1a/b hoặc T2, N0/NX, M0. II: T1a/b hoặc T2 với N1a/b, T3a/b với mọi N, M0. III: T4a, mọi N, M0. IVa: T4b, mọi N, M0. IVb: mọi T, mọi N, M1 | {{Y5 tr.226}} {{Y5 tr.227}} {{QĐ1514 tr.PDF 220}} |\n\n@@fold Phân giai đoạn thể tủy và không biệt hóa (QĐ1514)\n- Thể tủy (mọi tuổi): I: T1 N0; II: T2–3 N0; III: T1–3 N1a; IVa: T4a mọi N, hoặc T1–3 N1b; IVb: T4b mọi N; IVc: mọi T, mọi N, M1 {{QĐ1514 tr.PDF 220–221}}\n- Thể không biệt hóa: **tất cả xếp giai đoạn IV** (IVa, IVb, IVc) {{QĐ1514 tr.PDF 221}}\n@@end\n\n### Nhóm nguy cơ tái phát (ATA, tóm tắt Bảng 18)\n| Nhóm | Tiêu chí tiêu biểu | Nguồn |\n|---|---|---|\n| **Thấp** | Thể nhú, cắt hết bướu đại thể, không xâm lấn mô hay mạch, không mô học ác cao; không di căn hoặc vi di căn <0,2 cm (dưới 5 hạch) | {{Y5 tr.227}} |\n| **Trung bình** | Xâm lấn vi thể mô quanh tuyến giáp; ổ hấp thu iod ở cổ sau liều đầu; mô học ác cao; thể nhú xâm mạch; N1 (lâm sàng hoặc GPB) >5 hạch, và hạch di căn <3 cm | {{Y5 tr.228}} |\n| **Cao** | Xâm lấn đại thể; không cắt hết bướu; di căn xa; Tg gợi ý di căn xa; hạch N1 ≥3 cm; thể nang xâm mạch >4 ổ | {{Y5 tr.228}} |\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Chẩn đoán xác định\n> - Chẩn đoán chủ yếu dựa trên **siêu âm và chọc hút tế bào kim nhỏ**; giải phẫu bệnh phân loại thể mô học {{Y5 tr.238}} {{QĐ1514 tr.PDF 219}}\n> - FNA Bethesda V (nghi ngờ ác) và VI (ác tính); Bethesda III–IV cần xét nghiệm phân tử, còn V thì không {{Y5 tr.224}} {{Y5 tr.225}}\n> - Sau chẩn đoán: phân giai đoạn TNM AJCC 8 và phân nhóm nguy cơ ATA để quyết định điều trị {{QĐ1514 tr.PDF 219}} {{Y5 tr.227}}\n\n### Chẩn đoán phân biệt khối cổ và nhân giáp\n| Bệnh lý | Giống | Khác / cách phân biệt |\n|---|---|---|\n| Nhân giáp lành, bướu nhân | sờ được ở tuyến giáp | Không có đặc điểm nghi ác trên siêu âm; TR1–2 không cần FNA, TR3 chỉ FNA khi ≥2,5 cm {{Y5 tr.223}} {{Y5 tr.224}} |\n| Cường giáp (Basedow, bướu nhân độc) | rối loạn chức năng tuyến giáp | TSH thấp, xạ hình nhân nóng (hiếm ác); UTTG kèm Basedow thường ác tính hơn {{Y5 tr.224}} {{128VĐ mục 113}} |\n| Viêm giáp Hashimoto | tuyến giáp không đồng nhất | Calcitonin có thể tăng giả; không đo thường quy {{Y5 tr.222}} {{128VĐ mục 113}} |\n| Hạch di căn từ ung thư tế bào gai vùng đầu cổ | khối cổ | Tìm nguyên phát vùng mũi, hốc miệng, khẩu hầu, hạ hầu, thanh quản, da {{128VĐ mục 114}} |\n| Lymphôm, sarcôm, UTTG không biệt hóa | khối cổ tiến triển nhanh | Bệnh sử nhanh; cần sinh thiết lõi và GPB chuyên sâu {{Y5 tr.221}} |\n| Bướu lành tuyến cận giáp, bướu mỡ, u sợi, nang giáp lưỡi | khối cổ | Liệt kê trong nhóm bướu lành; phân biệt bằng hình ảnh và sinh thiết khi nghi {{128VĐ mục 114}} |\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n\n> [!key] Mục tiêu theo nhóm\n> - **Thể biệt hóa**: lấy bướu nguyên phát và hạch lâm sàng, giảm tái phát và di căn, tạo điều kiện điều trị iod và theo dõi Tg, **giảm biến chứng** do điều trị {{Y5 tr.233}}\n> - **Thể tủy, không biệt hóa**: phẫu thuật kết hợp toàn thân; không biệt hóa được coi là kháng trị, hiếm khi chữa khỏi {{QĐ1514 tr.PDF 222}} {{Y5 tr.234}}\n\n### 7.2 Các phương pháp\n\n@@tabs\n@@tab Phẫu thuật\n- Phẫu thuật là phương pháp đầu tiên cho mọi thể, thường khỏi ở nhóm nguy cơ thấp {{Y5 tr.228}}\n- **Cắt toàn phần**: bướu đa ổ hai thùy, bướu lớn, xâm lấn, di căn hạch, hoặc chỉ định iod sau mổ {{Y5 tr.228}}\n- QĐ1514 chỉ định cắt toàn phần khi: tiền sử xạ trị vùng cổ, T3–T4, tổn thương thùy đối bên, di căn hạch cổ, di căn xa, tái phát {{QĐ1514 tr.PDF 221}}\n- **Cắt thùy** đủ cho nhú không xâm lấn, nhỏ, đơn ổ, không di căn, không có tiền sử xạ vùng đầu cổ; biến chứng thấp hơn nhưng tái phát có thể cao hơn {{Y5 tr.228}} {{Y5 tr.229}}\n- Sống 10 năm cắt thùy 90,8% so với cắt toàn phần 90,4% (23.605 bệnh nhân) {{Y5 tr.229}}\n- Nạo hạch cổ: nhóm VI dự phòng khi T3–T4 N0 hoặc có hạch cổ bên lâm sàng (cN1b); nạo điều trị khi có bằng chứng hạch trên lâm sàng {{Y5 tr.233}} {{QĐ1514 tr.PDF 221}}\n- Biến chứng: suy cận giáp 5–52% sau mổ (hạ canxi thoáng qua 1–16%); tổn thương thần kinh hồi thanh quản thoáng qua 2–5%, vĩnh viễn 0,5–2%; phẫu thuật viên làm dưới 10 ca/năm có biến chứng 24%, trên 100 ca/năm là 14,5% {{Y5 tr.229}}\n@@tab Iod phóng xạ (I-131)\n- Mục tiêu: diệt mô giáp còn sót sau cắt toàn phần, điều trị mô ung thư còn lại (không lấy hết, hạch đại thể, di căn xa) {{Y5 tr.230}}\n- Phải cắt toàn bộ tuyến giáp trước khi điều trị I-131 {{QĐ1514 tr.PDF 222}}\n- Chỉ định theo ATA: không còn khuyến cáo điều trị thường quy cho mọi bệnh nhân; nguy cơ trung bình (15–30%) xem xét diệt giáp 30–50 mCi; nguy cơ cao (40–70%) dùng 100–200 mCi {{Y5 tr.230}}\n- QĐ1514: chỉ định cho thể biệt hóa nguy cơ cao (đa ổ, T3–T4, di căn hạch, di căn xa, Tg cao sau mổ) {{QĐ1514 tr.PDF 222}}\n- Có thể thực hiện bất kỳ lúc nào, không bắt buộc ngay sau mổ {{Y5 tr.231}}\n@@tab Nội tiết (levothyroxine)\n- Sau cắt toàn phần: bổ sung levothyroxine 1,6–2,0 mcg/kg/ngày {{Y5 tr.231}}\n- Y5 phân 3 mức mục tiêu TSH: không ức chế 0,5–2 mU/L; ức chế nhẹ 0,1–0,5 mU/L; ức chế trung bình hoặc hoàn toàn <0,1 mU/L; chọn theo nguy cơ tái phát, đáp ứng và nguy cơ cường giáp {{Y5 tr.231}}\n- Ức chế TSH sâu làm tăng nguy cơ rung nhĩ, loãng xương, tử vong tim mạch ở người lớn tuổi {{Y5 tr.231}}\n- QĐ1514: nguy cơ tái phát cao thì TSH dưới 0,1 mU/L; nguy cơ thấp thì 0,1 đến giới hạn dưới của tham chiếu {{QĐ1514 tr.PDF 222}}\n@@tab Xạ trị – hóa chất – đích\n- **Xạ trị ngoài** vai trò hạn chế: cho bướu không mổ được hoặc không hấp thu iod, giảm đau xương di căn, xạ phẫu não {{Y5 tr.232}}\n- Thể không biệt hóa: xạ sau mổ gần như bắt buộc để kiểm soát tái phát tại chỗ và hạch {{QĐ1514 tr.PDF 222}}\n- **Hóa chất**: chỉ định cho thể không biệt hóa (doxorubicin, paclitaxel, docetaxel, cisplatin, carboplatin) {{QĐ1514 tr.PDF 222}}\n- **Ức chế kinase (TKI)**: dành cho bệnh tiến triển toàn thân hoặc có nguy cơ tử vong trong 6 tháng; lenvatinib kéo dài PFS đến 14,7 tháng so với giả dược {{Y5 tr.232}}\n- Đích cho thể không biệt hóa: dabrafenib + trametinib (BRAF), larotrectinib (NTRK); cho thể biệt hóa và tủy: sorafenib, pazopanib, cabozantinib, sunitinib, axitinib, lenvatinib {{QĐ1514 tr.PDF 223}}\n- Thể tủy tiến triển: vandetanib hoặc cabozantinib (MKI) {{Y5 tr.234}}\n@@end\n\n#### Theo nhóm bệnh\n| Nhóm | Điều trị đề nghị | Nguồn |\n|---|---|---|\n| Biệt hóa, <1 cm, đơn ổ, không di căn | Cắt thùy là đủ; có thể theo dõi chủ động nếu nhỏ, nguy cơ thấp | {{Y5 tr.233}} |\n| Biệt hóa, 1–4 cm, không xâm lấn, N0 | Cắt thùy hoặc cắt toàn phần, tùy bệnh nhân | {{Y5 tr.233}} |\n| Biệt hóa, >4 cm, T4, hạch lâm sàng, di căn xa | Cắt toàn phần và lấy bướu đại thể (khuyến cáo mạnh) | {{Y5 tr.233}} |\n| Thể tủy, mọi kích thước | Cắt toàn phần kèm nạo hạch cổ trung tâm; cN1 nạo hạch có bằng chứng di căn | {{Y5 tr.233}} {{QĐ1514 tr.PDF 222}} |\n| Không biệt hóa | Cắt toàn phần và vét hạch nếu còn mổ được; thường đến muộn, chỉ mổ triệu chứng (mở khí quản, mở thông dạ dày), rồi hóa–xạ | {{QĐ1514 tr.PDF 222}} {{Y5 tr.234}} |\n| Biệt hóa, di căn xa | I-131 theo chỉ định; TKI khi tiến triển hoặc không đáp ứng iod | {{Y5 tr.232}} {{QĐ1514 tr.PDF 223}} |\n\n### 7.3 Phác đồ – Y lệnh\n\n> [!doc] QĐ1514 (Bài 29) chỉ nêu tên thuốc, không nêu liều hay chu kỳ. Liều dưới đây lấy từ Y5 (levothyroxine, iod phóng xạ) hoặc ghi \"tài liệu không nêu\". {{QĐ1514 tr.PDF 217–224}}\n\n| Nhóm | Thuốc – liều | Chỉ định | Ghi chú |\n|---|---|---|---|\n| Levothyroxine | 1,6–2,0 mcg/kg/ngày {{Y5 tr.231}} | Sau cắt toàn phần, thể biệt hóa | TSH mục tiêu theo nguy cơ |\n| I-131 diệt giáp | 30–50 mCi {{Y5 tr.229–230}} | Nguy cơ trung bình, xem xét | Sau cắt toàn phần |\n| I-131 điều trị | 100–200 mCi {{Y5 tr.229–230}} | Nguy cơ cao (di căn xa, xâm lấn đại thể, hạch >3 cm) | Liều theo ATA (Y5) |\n| Lenvatinib, sorafenib | Tài liệu không nêu liều {{Y5 tr.232}} | Biệt hóa tiến triển, toàn thân; khi không có thử nghiệm lâm sàng | Hai thuốc được FDA chấp thuận (Y5) |\n| Doxorubicin, paclitaxel, docetaxel, cisplatin, carboplatin | Tài liệu không nêu liều {{QĐ1514 tr.PDF 222}} | Không biệt hóa | Phối hợp hoặc đơn trị tùy tình trạng |\n| Dabrafenib + trametinib; larotrectinib | Tài liệu không nêu liều {{QĐ1514 tr.PDF 223}} | Không biệt hóa (BRAF, NTRK) | Tham khảo |\n| Vandetanib, cabozantinib | Tài liệu không nêu liều {{Y5 tr.234}} | Thể tủy tiến triển, có triệu chứng | Y5 ghi FDA 2011 và 2012 |\n\n> [!warn] Theo dõi và độc tính cần nhớ\n> - Ức chế TSH quá mức: rung nhĩ, loãng xương, tử vong tim mạch ở người lớn tuổi {{Y5 tr.231}}\n> - Thể tủy di truyền (RET): cắt toàn phần sớm; đột biến M918T mổ trong năm đầu; đột biến nguy cơ cao mổ tại hoặc trước 5 tuổi {{Y5 tr.234}}\n> - Chưa có văn bản Bộ Y tế chi tiết phác đồ hóa chất, TKI hay đích cho UTTG trong tài liệu đã cung cấp; không suy đoán liều {{QĐ1514 tr.PDF 221–223}}\n\n## 8. Tiên lượng – Dự phòng\n\n> [!key] Tóm tắt\n> - Tiên lượng tốt nhất ở thể nhú, nang biệt hóa; không biệt hóa rất xấu {{Y5 tr.216}} {{Y5 tr.221}}\n> - Theo dõi: Tg kết hợp siêu âm vùng cổ, xạ hình khi có chỉ định {{Y5 tr.236}} {{Y5 tr.237}}\n\n### Tiên lượng\n@@tabs\n@@tab Yếu tố tiên lượng\n- Tuổi, loại mô học, vị trí và mức độ lan rộng, đáp ứng iod quyết định tiên lượng khi có di căn xa {{Y5 tr.220}}\n- Di căn hạch: số lượng, kích thước và xâm lấn ngoài hạch đều có ý nghĩa quan trọng {{Y5 tr.219}}\n- Thể nang xâm mạch nhiều (≥4 ổ) hoặc bướu >4 cm: sống 10 năm kém hơn, hay di căn xa {{Y5 tr.220}}\n- AJCC 8 không tính mô học ác cao, đột biến BRAF hay mức lan rộng ngoài hạch: dùng thêm phân tầng ATA {{Y5 tr.227}}\n- AJCC 8 dự kiến hạ giai đoạn cho 30–40% bệnh nhân {{Y5 tr.225}}\n@@tab Sống còn\n- Thể biệt hóa: sống còn 10 năm cao, có thể 95–99% {{Y5 tr.216}} {{Y5 tr.238}}\n- Không biệt hóa: sống còn 10 năm 14%; sống 1 năm khoảng 19%; trung bình 4–5 tháng {{Y5 tr.216}} {{Y5 tr.221}}\n- Thể tủy: hay di căn hạch và di căn xa, tiên lượng xấu hơn biệt hóa {{Y5 tr.221}}\n@@end\n\n### Theo dõi sau điều trị (Bảng 21 Y5)\n| Đáp ứng / nhóm | Tg | Hình ảnh | TSH mục tiêu | Nguồn |\n|---|---|---|---|---|\n| Tốt, nguy cơ thấp hoặc trung bình | mỗi 12–24 tháng | Siêu âm mỗi 6–12 tháng sau mổ; không khuyến cáo xạ hình toàn thân (trừ nguy cơ cao) | 0,5–2 mU/L | {{Y5 tr.236}} |\n| Tốt, nguy cơ cao | mỗi 6–12 tháng, xem xét Tg kích thích | Siêu âm mỗi năm; xem xét chụp cắt lớp | 0,1–0,5 mU/L | {{Y5 tr.236}} {{Y5 tr.237}} |\n| Trung gian | mỗi 6–12 tháng, xem xét Tg kích thích | Siêu âm mỗi 6–12 tháng | 0,5–2 nếu nguy cơ thấp; 0,1–0,5 nếu nguy cơ cao | {{Y5 tr.237}} |\n| Không hoàn toàn về sinh hóa | mỗi 6–12 tháng, xem xét Tg kích thích | Xạ hình toàn thân, PET-CT hoặc cắt lớp để tìm nguồn Tg | 0,1–0,5 mU/L | {{Y5 tr.237}} |\n| Không hoàn toàn về cấu trúc | mỗi 6–12 tháng, xem xét Tg kích thích | Xét theo từng cá thể; nếu theo dõi thì sát | <0,1 mU/L | {{Y5 tr.237}} |\n\n- Xạ hình toàn thân sau iod: 6–12 tháng sau liều iod đầu, ở nguy cơ cao hoặc nghi tái phát {{Y5 tr.237}}\n- Đáp ứng tốt khi Tg không kích thích <0,2 ng/mL hoặc Tg kích thích <1 ng/mL; Tg ức chế >1 ng/mL hoặc Tg kích thích >10 ng/mL cần chụp hình ảnh {{Y5 tr.236}} {{Y5 tr.237}}\n- QĐ1514: FT4, TSH, Tg; siêu âm vùng cổ; xạ hình; X-quang phổi; thể tủy thêm calcitonin và CEA; Tg >10 ng/mL và hình ảnh âm tính thì PET-CT {{QĐ1514 tr.PDF 223}}\n\n### Dự phòng\n@@tabs\n@@tab Phòng ngừa – tầm soát\n- Yếu tố nguy cơ đã biết: tia xạ ion hóa, nhất là thời thơ ấu (nguyên nhân được hiểu rõ nhất của thể nhú); Y5 không nêu biện pháp dự phòng cấp 1 cụ thể {{Y5 tr.217}}\n- Tầm soát thường quy: tài liệu không nêu lịch cụ thể; Y5 ghi không bắt buộc đo calcitonin thường quy cho mọi nhân giáp {{Y5 tr.222}}\n- Slide xếp ung thư tuyến giáp vào nhóm \"phát hiện sớm\" (cùng ung thư vú) {{SY5 tr.38}}\n- Khi có 3 người họ hàng bậc 1 mắc: 96% khả năng là bệnh lý di truyền {{Y5 tr.217}}\n@@tab Phòng biến chứng\n- Sau cắt toàn phần: bổ sung levothyroxine; biến chứng cần nhớ là suy cận giáp và tổn thương thần kinh hồi thanh quản {{Y5 tr.229}} {{Y5 tr.231}}\n- Di căn xương, não: xạ trị giảm đau xương hoặc xạ phẫu di căn não {{Y5 tr.232}}\n@@end\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] Trọng số thi và cách nhớ\n> - Nguyên tắc: **mọi khối cổ nên được xem là ác tính cho đến khi được loại trừ bằng các bằng chứng chắc chắn**; chẩn đoán bằng **siêu âm + FNA (Bethesda)** rồi phân loại thể, giai đoạn, nguy cơ {{128VĐ mục 114}} {{Y5 tr.223}}\n> - Đề cương: bài \"Ca LS: ung thư tuyến giáp\" gắn MT2–MT17 {{ĐC Y5 tr.7}} {{ĐC Y5 tr.2–4}}\n> - Khung QĐ 22: STT 96 khối ở cổ và STT 95 rối loạn chức năng tuyến giáp {{QĐ22 tr.6}}\n> - QĐ 22: cận lâm sàng và chẩn đoán trọng số 45–60; xử trí 35–50 {{QĐ22 tr.8}}\n> - Điều trị phụ thuộc nhóm nguy cơ: phẫu thuật, iod phóng xạ, levothyroxine {{Y5 tr.233}} {{Y5 tr.230}}\n> - Câu hỏi tình huống: \"khối ở cổ, nhân giáp TR4 hoặc Bethesda V thì làm gì\"\n\n@@tabs\n@@tab Nhận diện\n- Nhân giáp nghi ác: nhân cứng, dính, lớn nhanh, khàn tiếng, có hạch cổ {{QĐ1514 tr.PDF 218}}\n- Nguy cơ then chốt: tia xạ vùng đầu cổ lúc trẻ, RET (MEN2), tiền sử gia đình ba thân nhân bậc 1 {{Y5 tr.217}}\n- Khối cổ không triệu chứng vẫn có thể là biểu hiện của ung thư vùng đầu cổ {{128VĐ mục 114}}\n- Đến muộn: khàn tiếng, khó nuốt, khó thở {{QĐ1514 tr.PDF 217}}; một số trường hợp hiếm gặp phát hiện qua di căn phổi, xương {{Y5 tr.221}}\n[Xem mục 4](#/n/ung-thu-tuyen-giap/4) · [mục 3](#/n/ung-thu-tuyen-giap/3)\n@@tab Chẩn đoán\n- Siêu âm: nhân đặc, vi vôi hóa, bờ không đều, cao > rộng; TR4 FNA ≥1,5 cm, TR5 FNA ≥1 cm {{Y5 tr.222}} {{Y5 tr.223}}\n- FNA Bethesda: III và IV làm xét nghiệm phân tử; V nguy cơ ác 60–75%, không cần phân tử {{Y5 tr.225}}\n- Calcitonin khi nghi thể tủy; TSH cho mọi bệnh nhân; Tg theo dõi sau mổ {{Y5 tr.222}} {{Y5 tr.235}}\n- TNM AJCC 8: T3b theo Y5 là xâm lấn cơ strap; ngưỡng tuổi 55 {{Y5 tr.226}} {{Y5 tr.225}}\n[Xem mục 5](#/n/ung-thu-tuyen-giap/5) · [mục 6](#/n/ung-thu-tuyen-giap/6)\n@@tab Điều trị\n- **Cắt thùy** khi nhú nhỏ, nguy cơ thấp; **cắt toàn phần** khi >4 cm, T4, hạch lâm sàng, di căn xa {{Y5 tr.233}}\n- Thể tủy: cắt toàn phần kèm nạo hạch cổ trung tâm {{Y5 tr.233}}\n- I-131 cho nguy cơ cao: 100–200 mCi; nguy cơ trung bình 30–50 mCi (xem xét) {{Y5 tr.229–230}}\n- Levothyroxine 1,6–2,0 mcg/kg/ngày; TSH mục tiêu theo nguy cơ {{Y5 tr.231}}\n- Không biệt hóa: phẫu thuật triệu chứng, hóa–xạ sớm; liều thuốc không có trong nguồn {{QĐ1514 tr.PDF 221–222}} {{Y5 tr.235}}\n[Xem mục 7.2](#/n/ung-thu-tuyen-giap/7) · [mục 7.3](#/n/ung-thu-tuyen-giap/7)\n@@tab Tiên lượng – Dự phòng\n- Di căn hạch có ý nghĩa tiên lượng quan trọng (số lượng, kích thước, xâm lấn ngoài hạch) {{Y5 tr.219}}\n- Biệt hóa sống còn 10 năm 95–99% {{Y5 tr.238}}\n- Không biệt hóa: sống 1 năm khoảng 19%, trung bình 4–5 tháng {{Y5 tr.221}}\n- Theo dõi: Tg mỗi 6–24 tháng tùy nguy cơ; siêu âm mỗi 6–12 tháng {{Y5 tr.236}}\n[Xem mục 8](#/n/ung-thu-tuyen-giap/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Thể nhú / nang / tủy / không biệt hóa | ==80–90% / 10–15% / 1–2% / 1–2%== | {{Y5 tr.218}} {{Y5 tr.220}} {{Y5 tr.221}} |\n| Tuổi phân nhóm TNM AJCC 8 | ==55 tuổi== (trước là 45) | {{Y5 tr.225}} |\n| Tg tham chiếu (tuyến nguyên vẹn, TSH bình thường) | ==3–40 ng/mL== | {{Y5 tr.235}} |\n| FNA Bethesda III / IV / V nguy cơ ác | ==5–15% / 15–30% / 60–75%== | {{Y5 tr.225}} |\n| TIRADS chỉ định FNA: TR3 / TR4 / TR5 | ==≥2,5 / ≥1,5 / ≥1 cm== | {{Y5 tr.223}} |\n| Nhân sờ thấy là nhân nóng | ==5–10%== | {{Y5 tr.224}} |\n| Tái phát khi xâm lấn ngoài hạch | ==15–30%== | {{Y5 tr.219}} |\n| Di căn hạch thể nhú | ==khoảng một nửa; đến 85%== | {{Y5 tr.219}} |\n| Levothyroxine sau cắt toàn phần | ==1,6–2,0 mcg/kg/ngày== | {{Y5 tr.231}} |\n| I-131 diệt giáp / điều trị | ==30–50 mCi / 100–200 mCi== | {{Y5 tr.229–230}} |\n| TSH mục tiêu ức chế hoàn toàn | ==<0,1 mU/L== | {{Y5 tr.231}} |\n| Tg sau mổ, thời điểm xét nghiệm | ==4–6 tuần== | {{Y5 tr.236}} |\n| Tg đáp ứng hoàn toàn | ==<0,2 ng/mL (kích thích <1)== | {{Y5 tr.236}} |\n| Tg cao cần PET-CT (nếu hình ảnh âm) | ==>10 ng/mL== | {{QĐ1514 tr.PDF 223}} |\n| Cắt thùy so với toàn phần, sống 10 năm | ==90,8% so với 90,4%== | {{Y5 tr.229}} |\n| Biến chứng: TK hồi thanh quản vĩnh viễn | ==0,5–2%== | {{Y5 tr.229}} |\n| Biệt hóa, sống 10 năm | ==95–99%== | {{Y5 tr.238}} |\n| Không biệt hóa, sống trung bình | ==4–5 tháng== | {{Y5 tr.221}} |\n\n> [!warn] Bẫy thi và mâu thuẫn giữa nguồn\n> - **Tỷ lệ mắc**: QĐ1514 ghi 3,1/100.000 cho cả hai giới {{QĐ1514 tr.PDF 217}}; Y5 ghi nữ 9,3 và nam 3,1/100.000 {{Y5 tr.216}}; SY5 ghi \"3,1\" là phần trăm tổng ung thư, không phải tỷ lệ {{SY5 tr.36}}\n> - **Thứ hạng nam**: Y5 thứ 11 {{Y5 tr.216}}; QĐ1514 thứ 15 {{QĐ1514 tr.PDF 217}}\n> - **TIRADS**: Y5 dùng TR1–TR5 theo điểm ACR {{Y5 tr.223}}; QĐ1514 ghi \"TIRADS I–VI theo ACR 2017\" {{QĐ1514 tr.PDF 218}}\n> - **T3b**: Y5 là xâm lấn cơ strap {{Y5 tr.226}}; QĐ1514 là vi xâm lấn ra ngoài tuyến giáp (cơ ức giáp hoặc tổ chức quanh) {{QĐ1514 tr.PDF 219}}\n> - **Thể tủy và không biệt hóa**: Y5 ghi 1–2% {{Y5 tr.220}} {{Y5 tr.221}}; QĐ1514 ghi tủy 1–5% và không biệt hóa khoảng 5% {{QĐ1514 tr.PDF 219}}\n> - **TSH nguy cơ thấp**: QĐ1514 là 0,1 đến giới hạn dưới tham chiếu {{QĐ1514 tr.PDF 222}}; Y5 là 0,5–2 mU/L (không ức chế) {{Y5 tr.231}}\n> - **Hạch N1b**: Y5 ghi hạch sau thanh quản {{Y5 tr.226}}; QĐ1514 ghi hạch sau hầu {{QĐ1514 tr.PDF 220}}\n> - **Độ chính xác FNA**: QĐ1514 90–95% {{QĐ1514 tr.PDF 218}}; Y5 85–100% (trung bình 95%) {{Y5 tr.225}}\n> - **Không biệt hóa**: QĐ1514 xếp tất cả là giai đoạn IV {{QĐ1514 tr.PDF 221}}; Y5 không nêu giai đoạn cho thể này\n> - Phân biệt nhanh: nhú (80–90%, lan tràn chậm) với không biệt hóa (1–2%, ác nhất, sống trung bình 4–5 tháng) {{Y5 tr.218}} {{Y5 tr.221}}\n\n@@fold Nguồn tài liệu\n- **Y5**: TEXT UNG BƯỚU Y5, chương UNG THƯ TUYẾN GIÁP, tr. 215–238 (đọc toàn bộ; Bảng 14–21 đối chiếu ảnh tr. 223, 226, 227, 230, 236, 237)\n- **SY5**: Slide tổng hợp Y5 tr. 36–38, 126, 132, 200 (không có chương tuyến giáp riêng trong slide)\n- **QĐ1514**: QĐ BYT Hướng dẫn chẩn đoán và điều trị một số bệnh ung bướu, Bài 29, tr. PDF 217–224 (đọc toàn bộ)\n- **ĐC Y5**: tr. 2–4 (MT2–MT17), tr. 7 (bảng ca lâm sàng \"Ung thư tuyến giáp\"; MT2,3,4,5,7,8,9,10,12,13,14,15,17)\n- **128VĐ**: mục 113 (bất thường chức năng tuyến giáp), mục 114 (khối ở cổ)\n- **QĐ 22**: STT 95, 96 (tr. 6); trọng số (tr. 8)\n@@end\n\n@@fold Nguồn ngoài\n- Không dùng nguồn ngoài. Mọi số liệu lấy từ tài liệu đã cung cấp.\n@@end\n\n@@fold! Tự kiểm tra (15 thẻ)\n- Dấu hiệu nghi ác của nhân giáp theo QĐ1514? :: Cứng, dính, lớn nhanh, khàn tiếng, có hạch cổ cùng bên {{QĐ1514 tr.PDF 218}}\n- Khối ở cổ có được xem là lành tính ngay không? :: Không; mọi khối cổ nên được xem là ác tính cho đến khi được loại trừ bằng các bằng chứng chắc chắn {{128VĐ mục 114}}\n- TR4 chỉ định FNA khi nhân lớn bao nhiêu? :: Từ 1,5 cm trở lên {{Y5 tr.223}}\n- Bethesda V có làm xét nghiệm phân tử không? :: Không, vì nguy cơ ác tính 60–75% đã cao {{Y5 tr.225}}\n- Bethesda nào cần xét nghiệm phân tử? :: III và IV; giá trị tiên đoán âm cao để loại trừ ung thư {{Y5 tr.225}}\n- Thể mô học nào chiếm 80–90%? :: Thể nhú, tiến triển chậm, tiên lượng tốt {{Y5 tr.218}}\n- Gen nào gây MEN2A, MEN2B và thể tủy di truyền? :: RET, đột biến hoạt hóa, di truyền trội {{Y5 tr.217}}\n- Ngưỡng tuổi phân nhóm TNM AJCC 8? :: 55 tuổi (trước là 45) {{Y5 tr.225}}\n- T3b theo Y5 là gì? :: Xâm lấn ngoài tuyến giáp chỉ đến cơ strap, kích thước bất kỳ {{Y5 tr.226}}\n- Levothyroxine sau cắt toàn phần liều bao nhiêu? :: 1,6–2,0 mcg/kg/ngày {{Y5 tr.231}}\n- Mục tiêu TSH khi nguy cơ tái phát cao theo QĐ1514? :: Dưới 0,1 mU/L {{QĐ1514 tr.PDF 222}}\n- Liều I-131 cho nguy cơ cao và nguy cơ trung bình? :: Nguy cơ cao: 100–200 mCi. Nguy cơ trung bình: diệt giáp 30–50 mCi, xem xét {{Y5 tr.229–230}}\n- Tg đáp ứng hoàn toàn khi nào? :: Tg không kích thích <0,2 ng/mL hoặc kích thích <1 ng/mL {{Y5 tr.236}}\n- Sống còn 10 năm thể biệt hóa? :: 95–99% {{Y5 tr.238}}\n- Thể không biệt hóa: sống trung bình bao lâu? :: 4–5 tháng {{Y5 tr.221}}\n@@end"}, {"kind": "disease", "disease": "vom-hau", "short": "Ung thư vòm hầu", "group": "", "section": 0, "order": 12, "khung": [15, 23, 38, 96], "id": "ung-thu-vom-hau", "title": "Ung thư vòm hầu", "layer": "benh", "module": "ung-buou", "tags": ["ung bướu", "vòm hầu", "EBV", "hạch cổ", "ung thư đầu cổ", "xạ trị", "hóa xạ đồng thời", "TNM", "AJCC"], "source": "Y5 tr.198–213 (chương Ung thư vòm hầu); QĐ1514 tr.PDF 164–172 (Bài 23, Ung thư vòm mũi họng); SY5 tr.74, 75, 190; ĐC Y5 tr.2–7; 128VĐ mục 47, 114; QĐ22 STT 15, 23, 38, 96", "body": "> [!key] Ung thư vòm hầu (UTVH) trong một nhìn\n> - Carcinôm niêm mạc vòm hầu (hay ở hố Rosenmüller); **EBV là nguyên nhân chính**; ==90–95%== là biểu mô {{Y5 tr.199}} {{Y5 tr.201}} {{Y5 tr.202}}\n> - Dấu hiệu gặp nhất: **hạch cổ** (trên 50% trường hợp xuất hiện trước u nguyên phát), kèm ù tai, nghẹt mũi, chảy máu mũi {{Y5 tr.203}}\n> - Chẩn đoán xác định = **mô bệnh học** (sinh thiết vòm); CT đầu cổ bắt buộc; PET-CT khi có triệu chứng, hạch vỡ vỏ hoặc EBV DNA ≥4000 copies/mL {{Y5 tr.204}} {{Y5 tr.205}}\n> - Điều trị: **xạ trị là chính**; từ giai đoạn II là **hóa xạ đồng thời** (cisplatin); IVB hóa trị hoặc chăm sóc giảm nhẹ {{Y5 tr.207}} {{QĐ1514 tr.PDF 167}} {{Y5 tr.208}}\n> - Đề cương gắn bệnh này với MT2–5, 7–10, 12–15, 17 {{ĐC Y5 tr.7}}; trọng tâm: diễn tiến (MT2), chẩn đoán và cận lâm sàng (MT3), điều trị (MT5), triệu chứng báo động (MT13) {{ĐC Y5 tr.2–5}}\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Khác các ung thư đầu cổ khác về nguyên nhân, dịch tễ, diễn tiến và đáp ứng điều trị; **xạ trị** là phương thức chính {{Y5 tr.213}}\n> - Nguy cơ chính: **EBV** (mạnh), tiền sử gia đình (mạnh), cá muối và thức ăn ướp muối/bảo quản, hút thuốc lá {{Y5 tr.199}} {{Y5 tr.201}}\n\n### Định nghĩa & dịch tễ\n- Toàn cầu (Globocan 2018): ==129.079 ca mới, 72.987 ca tử vong==, đứng thứ 23 trong các ung thư thường gặp {{Y5 tr.198}}\n- Hiếm ở Mỹ và Tây Âu (==0,5–2/100.000==); Nam Trung Quốc–Hồng Kông lên đến ==25/100.000== {{Y5 tr.198}}\n- Đông Nam Á: Brunei ==9,9/100.000==, Maldives 6,7/100.000 {{Y5 tr.198}}\n- Việt Nam (Globocan 2018): ==6.212 ca mới, 4.232 tử vong==, đứng thứ 6; mắc 5,7/100.000, tử 3,9/100.000 {{Y5 tr.198}}\n- Nam mắc gấp ==2–3 lần== nữ; nhóm nguy cơ cao đạt đỉnh ở ==50–59 tuổi== {{Y5 tr.198}}\n- Tần suất giảm trong hơn 30 năm ở Hồng Kông, Singapore, Đài Loan (nguyên nhân chưa rõ) {{Y5 tr.198}}\n- QĐ1514 gọi là **ung thư vòm mũi họng (UTVMH)**; đỉnh mắc ==30–50 tuổi==; hay gặp ở người hút thuốc, uống rượu, chiếu xạ, ăn trầu, cá muối, dưa muối, ít rau quả {{QĐ1514 tr.PDF 164}}\n- Tuổi đỉnh khác nhau giữa hai nguồn: xem lưu ý mục 9\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Không thay đổi được\n- **EBV**: nguyên nhân chính; có DNA và gen sinh ung của EBV, cùng protein EBNA1, LMP1, LMP2 trong tế bào ung thư và tổn thương tiền ung {{Y5 tr.199}}\n- Hơn ==90%== người trưởng thành đã nhiễm EBV; ung thư hiếm nên yếu tố gen và môi trường quyết định {{Y5 tr.199}}\n- Vùng nguy cơ cao, trẻ nhiễm EBV rất sớm: khoảng 60% trẻ dưới 2 tuổi, 80% lúc 6 tuổi, 100% lúc 10 tuổi {{Y5 tr.200}}\n- Tiền căn tăng bạch cầu đơn nhân nhiễm khuẩn: tần suất UTVH thấp hơn {{Y5 tr.200}}\n- Gia đình có người mắc UTVH: nguy cơ **mạnh** {{Y5 tr.199}}\n- **HLA nhóm I**: HLA A2, B46, B17 tăng nguy cơ 2–3 lần; HLA A11, B13, B22 ít nguy cơ hơn {{Y5 tr.200}}\n- HPV: vai trò ít rõ; trong nghiên cứu 1.328 ca type III, EBV DNA dương ==91,5%==, HPV ==7,7%==; UTVH liên quan HPV có tiên lượng tốt hơn {{Y5 tr.200}}\n@@tab Thay đổi được\n- **Cá muối** ăn từ nhỏ (thời kỳ ăn dặm); thức ăn ướp muối (nitrosamine) {{Y5 tr.200}}\n- Thực phẩm bảo quản hoặc lên men (thịt, trứng, trái cây, rau củ) {{Y5 tr.200}}\n- **Hút thuốc lá**: tăng ==2–6 lần==, đặc biệt carcinôm tế bào gai {{Y5 tr.201}}\n- Vệ sinh răng miệng kém; uống rượu: chưa khẳng định rõ {{Y5 tr.201}}\n- Nghề nghiệp: bụi gỗ, **formaldehyde** {{Y5 tr.201}} {{SY5 tr.190}}\n- Viêm đường hô hấp trên mạn tính: tăng gấp đôi (vi khuẩn chuyển nitrat thành nitrit) {{Y5 tr.201}}\n- Ăn ít trái cây và rau củ: nguy cơ vừa {{Y5 tr.199}}\n@@tab Mức độ (Bảng 6)\n| Yếu tố | Mức liên quan (Y5) |\n|---|---|\n| EBV; gia đình có người mắc UTVH | mạnh {{Y5 tr.199}} |\n| HLA nhóm I; cá muối | vừa đến mạnh {{Y5 tr.199}} |\n| Thực phẩm bảo quản; ăn ít rau quả; viêm đường hô hấp mạn | vừa {{Y5 tr.199}} |\n| Thuốc lá; thuốc y học cổ truyền; formaldehyde | yếu đến vừa; văn bản ghi hút thuốc tăng 2–6 lần {{Y5 tr.199}} {{Y5 tr.201}} |\n@@end\n\n### Diễn tiến tự nhiên – lan tràn\n- Khởi phát từ niêm mạc vòm, vị trí hay gặp là **hố Rosenmüller** {{Y5 tr.201}}\n- Lan tại chỗ, triệu chứng do xâm lấn:\n  - Lên trên qua lỗ rách: xoang hang, dây III–VI (đau mặt, sụp mi, rối loạn vận nhãn), đáy sọ {{Y5 tr.201}}\n  - Mặt bên: vòi Eustache (viêm tai giữa, ù tai, giảm thính lực); khoang cạnh hầu: hội chứng Horner {{Y5 tr.201}}\n  - Ra sau: xâm lấn cơ trước sống (đau cổ); ra trước: hốc mũi, xoang cạnh mũi (nghẹt mũi, chảy máu mũi) {{Y5 tr.201}}\n- Hạch: ==90%== có di căn hạch vùng lúc chẩn đoán; ==50%== hạch cổ **hai bên**; hạch nhóm II và hạch sau hầu thường là nhóm đầu tiên {{Y5 tr.201}}\n- Di căn xa: ==5%== lúc chẩn đoán, ==20–50%== trong diễn tiến; thường gặp **xương (75%)**, phổi, gan, hạch trung thất trên, hạch rốn phổi {{Y5 tr.201}}\n\n### Giải phẫu bệnh – phân loại\n- **Biểu mô** ==90–95%==; 5–10% còn lại là lymphôm, carcinôm tuyến nước bọt phụ hoặc sarcôm {{Y5 tr.202}}\n- Phân loại WHO 2005:\n\n| Loại | Liên quan EBV | Đặc điểm | Tiên lượng |\n|---|---|---|---|\n| Type I: carcinôm tế bào gai sừng hóa | ít | biệt hóa cao, rất thường gặp, có cầu sừng {{Y5 tr.202}} | xấu {{Y5 tr.202}} |\n| Type II: không sừng hóa, biệt hóa tốt | gần 100% | tế bào lát tầng, giới hạn rõ {{Y5 tr.202}} | tốt hơn các loại khác {{Y5 tr.202}} |\n| Type III: không sừng hóa, không biệt hóa | gần 100% | hợp bào, giới hạn tế bào không rõ {{Y5 tr.202}} | tốt hơn các loại khác {{Y5 tr.202}} |\n| Carcinôm tế bào gai dạng đáy | không nêu | bổ sung vào WHO 2005, chiếm tỉ lệ ít {{Y5 tr.203}} | xấu, diễn tiến nhanh {{Y5 tr.203}} |\n\n- Type III nhạy xạ trị hơn và tỉ lệ sống cao hơn type I, nhưng **chưa đủ bằng chứng để đổi điều trị theo mô học** {{Y5 tr.207}}\n- Hóa mô miễn dịch: CK luôn dương tính, đa số EMA, đôi khi CEA; **CK** là dấu ấn đáng tin cậy nhất {{Y5 tr.203}}\n- DNA và gen sinh ung của EBV có trong cả tổn thương tiền ung lẫn ung thư vòm hầu {{Y5 tr.199}}\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Thường gặp nhất: **hạch cổ** cùng bên (nhóm II và VA), to, thường xuất hiện trước u nguyên phát {{Y5 tr.203}}\n> - Tai – mũi: đau tai, viêm tai giữa, ù tai; nghẹt mũi, chảy máu mũi {{Y5 tr.203}}\n> - Thần kinh sọ: đau mặt, nhức đầu, song thị, sụp mi (dây III, IV, V, VI) {{Y5 tr.203}}\n\n### Triệu chứng cơ năng và thực thể\n@@tabs\n@@tab Giai đoạn sớm\n- Nhức đầu lan tỏa, âm ỉ, thường một bên {{QĐ1514 tr.PDF 164}}\n- Ù tai, đa số một bên, như tiếng ve kêu {{QĐ1514 tr.PDF 164}}\n- Nghẹt mũi một bên, lúc nặng lúc nhẹ, đôi khi chảy máu mũi {{QĐ1514 tr.PDF 164}}\n@@tab Giai đoạn muộn\n- Nhức đầu liên tục, có lúc dữ dội, có điểm đau khu trú {{QĐ1514 tr.PDF 164}}\n- Ù tai tăng, nghe kém, có thể điếc {{QĐ1514 tr.PDF 164}}\n- Nghẹt mũi liên tục, chảy máu mũi, không đáp ứng điều trị thông thường {{QĐ1514 tr.PDF 164}}\n- Mắt: lác, nhìn đôi, sụp mi, giảm hoặc mất thị lực do u chèn ép hoặc tổn thương thần kinh vận nhãn {{QĐ1514 tr.PDF 164}}\n- U đẩy lồi nhãn cầu, xuống họng miệng, hoặc sùi ra ống tai ngoài {{QĐ1514 tr.PDF 164}}\n@@tab Khám (Y5, QĐ1514)\n- Soi gián tiếp hoặc trực tiếp: u đa số ở hai thành bên và nóc vòm; sinh thiết u khi soi {{QĐ1514 tr.PDF 164}}\n- Dây III, IV, V, VI hay tổn thương sớm; giai đoạn muộn có thể tổn thương nhiều dây {{QĐ1514 tr.PDF 165}}\n- Hạch cổ cùng bên với u; **hạch góc hàm** tổn thương sớm và hay gặp; ban đầu nhỏ, di động, về sau chắc và cố định {{QĐ1514 tr.PDF 165}}\n- Dây IX–XII và thần kinh giao cảm ít bị xâm lấn; dây II, VII, VIII rất ít khi tổn thương {{Y5 tr.203}}\n@@end\n\n> [!red] Dấu hiệu báo động\n> - Hạch cổ nghi di căn từ vòm hầu: cần khám vòm và sinh thiết sâu hơn {{Y5 tr.205}}\n> - Liệt dây VI, sụp mi một bên, IgA VCA dương: nghi UTVH {{Y5 tr.205}}\n> - Nghẹt mũi, chảy máu mũi kéo dài, không đáp ứng điều trị thông thường {{QĐ1514 tr.PDF 164}}\n> - Chảy máu mũi có nhiều nguyên nhân: bệnh huyết học, UT vòm hầu, UT hốc mũi {{SY5 tr.74}}\n> - Slide SY5 liệt kê \"khối u ở cổ, nách, bẹn\" trong danh sách dấu hiệu cần khám {{SY5 tr.75}}\n\n### Tiếp cận các triệu chứng (khung 128 vấn đề)\n| STT | Vấn đề | Nghĩ tới UTVH khi |\n|---|---|---|\n| [96](#/khung/96) | **Khối ở cổ** | hạch cổ nhóm cao; vòm hầu hay di căn hạch nhóm II {{128VĐ mục 114}}, hai bên (50% ca) {{Y5 tr.201}} |\n| [38](#/khung/38) | Đau họng và/hoặc chảy mũi | nghẹt mũi, chảy máu mũi một bên kéo dài {{QĐ1514 tr.PDF 164}} |\n| [23](#/khung/23) | U tai/đau tai/chảy dịch tai | ù tai, đau tai, viêm tai giữa do bướu lan vào vòi Eustache {{Y5 tr.201}} {{QĐ1514 tr.PDF 164}} |\n| [15](#/khung/15) | Đau đầu | nhức đầu một bên, kéo dài, dữ dội ở giai đoạn muộn {{QĐ1514 tr.PDF 164}} |\n\n@@fold Khối ở cổ theo 128 vấn đề (mục 114)\n- Mọi khối cổ nên được xem là ác tính cho đến khi loại trừ bằng các bằng chứng chắc chắn {{128VĐ mục 114}}\n- Người lớn: khối cổ cần đánh giá kỹ hơn trẻ em, đặc biệt khi kéo dài trên 2 tuần mà không cải thiện {{128VĐ mục 114}}\n- Nguyên nhân cần nghĩ tới: nhiễm trùng (EBV, CMV, HIV), lymphôm, carcinôm tế bào gai vùng đầu cổ, ung thư tuyến giáp, hạch di căn {{128VĐ mục 114}}\n@@end\n\n## 5. Cận lâm sàng\n\n> [!key] Tóm tắt\n> - **Nội soi** tai mũi họng + **sinh thiết** vòm = chẩn đoán mô bệnh học; NBI giúp định hướng sinh thiết ở giai đoạn sớm {{Y5 tr.204}}\n> - **CT đầu cổ** bắt buộc để đánh giá lan rộng; MRI khi xâm lấn não {{Y5 tr.205}}\n> - **EBV** (VCA-IgA, EA-IgA, EBV DNA) có giá trị chẩn đoán, tiên lượng và theo dõi {{Y5 tr.204}}\n> - **PET-CT** và xạ hình xương khi có triệu chứng, hạch vỡ vỏ hoặc EBV DNA ≥4000 copies/mL {{Y5 tr.205}}\n\n### Huyết thanh và sinh học phân tử\n- VCA-IgA: nhạy ==87–97%==, đặc hiệu 78,5–80,9%; EA-IgA: đặc hiệu ==trên 95%==, nhạy 56,6–69,4% {{Y5 tr.200}}\n- Cặp VCA-IgA + EA-IgA: nhạy trên 90,63%, đặc hiệu 89,17% {{Y5 tr.200}}\n- Nồng độ EBV EA-IgA, VCA-IgA cao trước điều trị: tiên lượng xấu, kém đáp ứng, dễ tái phát {{Y5 tr.200}}\n- Xét nghiệm EBV: IgA/VCA, IgA/EBNA; tumor marker SCC, Cyfra 21-1, CEA, CA 19-9 (theo dõi đáp ứng, tái phát, di căn) {{QĐ1514 tr.PDF 165}}\n- Giải trình tự nhiều gen (sinh học phân tử) {{QĐ1514 tr.PDF 165}}\n\n### Nội soi, sinh thiết và hình ảnh\n@@tabs\n@@tab Nội soi – sinh thiết\n- Nội soi tai mũi họng trực tiếp hoặc gián tiếp tìm bướu vòm; sinh thiết tổn thương nghi ngờ {{Y5 tr.204}}\n- Giai đoạn sớm dễ bị bỏ sót; **NBI** (ánh sáng ==415 nm và 540 nm==) phát hiện tăng sinh vi mạch nông, định hướng sinh thiết {{Y5 tr.204}}\n- Sinh thiết sâu hơn (gây tê tại chỗ hoặc gây mê) khi nghi liệt VI, sụp mi một bên, IgA VCA dương, hạch nghi di căn, hoặc CT có tổn thương nghi ngờ {{Y5 tr.205}}\n- Quệt tế bào bong ở vòm họng; sinh thiết trực tiếp u qua ống soi cứng hoặc mềm; sinh thiết hạch cổ nếu bệnh học vòm âm tính {{QĐ1514 tr.PDF 165}}\n- Siêu âm cổ và FNA hạch nghi ngờ {{Y5 tr.204}} {{QĐ1514 tr.PDF 165}}\n@@tab CT – MRI – PET\n- **CT đầu cổ** bắt buộc: lan đến khẩu hầu, xoang mũi, khoang cạnh hầu; đánh giá xương, đáy sọ, não {{Y5 tr.205}}\n- CT vùng vòm và nền sọ có cửa sổ xương: u làm đầy trần và thành vòm; tiêu xương nền sọ nếu có {{QĐ1514 tr.PDF 165}}\n- CT ổ bụng, lồng ngực tìm di căn; MRI vòm và sọ não khi u xâm lấn phần mềm hoặc nghi di căn não {{QĐ1514 tr.PDF 165}}\n- **PET-CT** khi có triệu chứng lâm sàng, hạch vỡ vỏ bao hoặc EBV DNA ≥4000 copies/mL {{Y5 tr.205}}\n- PET/CT trước điều trị để chẩn đoán u nguyên phát và giai đoạn; mô phỏng lập kế hoạch xạ trị {{QĐ1514 tr.PDF 165}}\n- Xạ hình xương SPECT/CT với Tc-MDP đánh giá di căn xương; X-quang Hirtz, Blondeau ít được làm {{QĐ1514 tr.PDF 165}}\n@@end\n\n### Phân giai đoạn TNM\n- Y5 dùng AJCC (2018), Bảng 7–10 {{Y5 tr.205}} {{Y5 tr.206}}; QĐ1514 dùng AJCC lần 8 (2017) {{QĐ1514 tr.PDF 166}}\n\n| Mục | Y5 (AJCC 2018) | QĐ1514 (AJCC 8, 2017) |\n|---|---|---|\n| T0 | không phát hiện bướu nguyên phát {{Y5 tr.205}} | không thấy u nguyên phát nhưng có hạch cổ và EBV dương tính {{QĐ1514 tr.PDF 166}} |\n| T1 | còn giới hạn ở vòm hầu, hoặc lan khẩu hầu và/hoặc hốc mũi nhưng chưa xâm khoang cạnh hầu {{Y5 tr.205}} | khu trú vòm, hoặc lan họng miệng và/hoặc hốc mũi, chưa xâm khoang cạnh hầu {{QĐ1514 tr.PDF 166}} |\n| T2 | xâm khoang cạnh hầu, hoặc lan cơ chân bướm trong, cơ chân bướm ngoài, cơ trước sống {{Y5 tr.205}} | xâm khoang cạnh hầu và/hoặc phần mềm quanh cơ chân bướm trong, ngoài, cơ trước sống {{QĐ1514 tr.PDF 166}} |\n| T3 | xương đáy sọ, cột sống cổ, xương bướm và/hoặc xoang cạnh mũi {{Y5 tr.205}} | xương nền sọ, cột sống cổ, xoang cạnh mũi, xương chân bướm, đốt sống cổ {{QĐ1514 tr.PDF 166}} |\n| T4 | nội sọ, dây thần kinh sọ, hạ hầu, hốc mắt, **tuyến mang tai**, mô mềm vượt bờ ngoài cơ chân bướm ngoài {{Y5 tr.206}} | nội sọ và/hoặc dây thần kinh sọ, hạ họng, hốc mắt, **tuyến nước bọt**, phần mềm ngoài cơ chân bướm ngoài, **hố thái dương, khoang cơ nhai** {{QĐ1514 tr.PDF 166}} |\n| N1 | hạch trên sụn nhẫn một bên (I, II, III, Va), hoặc hạch sau hầu 1–2 bên; ≤6 cm {{Y5 tr.206}} | một hoặc nhiều hạch cổ cùng bên ≤6 cm trên hố thượng đòn, và/hoặc hạch cạnh hầu một hoặc hai bên ≤6 cm {{QĐ1514 tr.PDF 166}} |\n| N2 | hạch cổ hai bên trên sụn nhẫn, ≤6 cm {{Y5 tr.206}} | hạch hai bên ≤6 cm trên hố thượng đòn {{QĐ1514 tr.PDF 166}} |\n| N3 | >6 cm (một hoặc hai bên) **và/hoặc hạch cổ dưới sụn nhẫn (IV, Vb)** {{Y5 tr.206}} | >6 cm (N3a) **và/hoặc hạch trong hố thượng đòn (N3b)** {{QĐ1514 tr.PDF 166}} |\n| M | M1: di căn xa (xương, phổi, gan...) {{Y5 tr.206}} | M1: có di căn xa {{QĐ1514 tr.PDF 166}} |\n| Nhóm giai đoạn | I: T1N0M0; II: T0–1N1M0 hoặc T2N0–1M0; III: T0–2N2M0 hoặc T3N0–2M0; IVA: T4 N0–3M0 hoặc bất kỳ T, N3, M0; IVB: M1 {{Y5 tr.206}} | I: T1N0M0; II: T0,1N1M0 hoặc T2N0,1M0; III: T0,1,2N2M0 hoặc T3N0,1,2M0; IVA: T4 bất kỳ N, M0 hoặc bất kỳ T, N3, M0; IVB: M1 {{QĐ1514 tr.PDF 166}} {{QĐ1514 tr.PDF 167}} |\n\nNhóm giai đoạn hai nguồn giống nhau; các khác biệt ở T0, T4, N3 được nêu trong lưu ý mục 9.\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Chẩn đoán xác định UTVH\n> - Lâm sàng và cận lâm sàng có **u và/hoặc hạch cổ**, và **mô bệnh học là ung thư** (có thể cần nhuộm hóa mô miễn dịch để xác định typ) {{QĐ1514 tr.PDF 166}}\n> - Mô bệnh học là **bắt buộc** để xác định chẩn đoán {{QĐ1514 tr.PDF 165}}\n> - Tăng kháng thể kháng EBV là tiêu chuẩn trong chẩn đoán UTVH theo Y5 {{Y5 tr.200}}\n\n### Chẩn đoán phân biệt\n| Bệnh lý | Điểm giống | Điểm phân biệt |\n|---|---|---|\n| Hạch cổ viêm lao; tổn thương lao vùng vòm | hạch cổ, tổn thương vòm | chủ yếu dựa vào mô bệnh học {{QĐ1514 tr.PDF 167}} |\n| Hạch cổ di căn ung thư vùng đầu cổ; lymphôm hệ thống | hạch cổ | mô bệnh học và hóa mô miễn dịch {{QĐ1514 tr.PDF 167}} |\n| U lympho ác tính không Hodgkin ở vòm và vòng Waldeyer | tổn thương vòm | mô bệnh học {{QĐ1514 tr.PDF 167}} |\n| Khối cổ bẩm sinh, nhiễm trùng, lành tính (nang giáp lưỡi, nang khe mang, nhiễm EBV/CMV/HIV) | khối ở cổ | cần đánh giá lâm sàng, hình ảnh, sinh thiết khi nghi ngờ {{128VĐ mục 114}} |\n\n## 7. Điều trị\n\n> [!key] Mục tiêu theo giai đoạn\n> - Xạ trị là **phương pháp cơ bản**; phẫu thuật không phải điều trị đầu tay vì vị trí sâu, gần thần kinh và mạch máu quan trọng {{Y5 tr.207}} {{QĐ1514 tr.PDF 167}}\n> - Giai đoạn I: xạ trị đơn thuần; từ giai đoạn II: hóa xạ trị đồng thời với cisplatin {{QĐ1514 tr.PDF 167}} {{Y5 tr.208}}\n> - Hạch cổ: xạ trị **hai bên** cho mọi bệnh nhân; N0 có thể không xạ hạch cổ thấp (vùng trên đòn) {{Y5 tr.207}}\n> - Giai đoạn IVB: hóa trị đơn thuần hoặc chăm sóc giảm nhẹ {{Y5 tr.208}}\n\n### 7.1 Mục tiêu điều trị\n- Giai đoạn sớm có thể điều trị khỏi; giai đoạn tại chỗ–tại vùng: điều trị phối hợp nhiều phương pháp, hóa xạ đồng thời cho kết quả tốt rõ rệt {{QĐ1514 tr.PDF 172}} {{QĐ1514 tr.PDF 167}}\n- Tiến xa tại chỗ–tại vùng: hóa xạ đồng thời cải thiện đáng kể sống còn chung và sống còn không tiến triển {{Y5 tr.208}}\n- Di căn: hóa trị đơn thuần hoặc chăm sóc giảm nhẹ; kiểm soát triệu chứng {{Y5 tr.208}} {{QĐ1514 tr.PDF 169}}\n\n### 7.2 Các phương pháp\n@@tabs\n@@tab Xạ trị\n- Chụp mô phỏng bằng CT, MRI hoặc PET/CT; kỹ thuật IMRT/VMAT giảm biến chứng {{QĐ1514 tr.PDF 167}}\n- **Bắt buộc** cho giai đoạn I–IVA; giai đoạn IVB cân nhắc sau hóa chất nếu di căn đáp ứng hoàn toàn {{QĐ1514 tr.PDF 167}}\n- Liều theo QĐ1514: u nguyên phát và hạch thấy trên lâm sàng trung bình 65–70 Gy, 2 Gy/ngày, 6–7 tuần; hạch dự phòng 50 Gy {{QĐ1514 tr.PDF 167}} {{QĐ1514 tr.PDF 168}}\n- Liều theo Y5: u 65–70 Gy trong 6,5–7 tuần, phân liều 1,8–2 Gy; hạch sờ thấy 65–70 Gy, không sờ thấy 50 Gy {{Y5 tr.208}}\n- Áp sát (Y5): tăng liều 12–15 Gy, phân liều 3–5 Gy {{Y5 tr.208}}\n- Giai đoạn I (QĐ1514): không biệt hóa 66 Gy, biểu mô vảy 70 Gy; hạch dự phòng 50 Gy; 2 Gy/ngày, 10 Gy/tuần {{QĐ1514 tr.PDF 168}}\n- Tái phát khu trú: xạ ngoài 40 Gy (2 Gy/ngày) kết hợp áp sát, tổng 70 Gy; chỉ xét khi tái phát sau trên 6 tháng {{QĐ1514 tr.PDF 169}}\n@@tab Hóa chất\n- Hóa xạ đồng thời (QĐ1514): **cisplatin 30–40 mg/m²** TM mỗi tuần ×6 đợt, hoặc **100 mg/m²** ngày 1, 22, 43 cùng xạ {{QĐ1514 tr.PDF 169}} {{QĐ1514 tr.PDF 170}}\n- Carboplatin hàng tuần khi có chống chỉ định hoặc không dung nạp cisplatin {{QĐ1514 tr.PDF 169}}\n- Y5: cisplatin 30–40 mg/m² hàng tuần hoặc 100 mg/m² mỗi 3 tuần; carboplatin, oxaliplatin, cetuximab, nimotuzumab, bevacizumab đang nghiên cứu {{Y5 tr.207}}\n- Hóa cảm ứng (Y5): chỉ định khi u T4 lớn, hạch N3 lớn hoặc hạch thượng đòn, hoặc không xạ đủ liều vì cấu trúc quan trọng gần u; TPF hoặc gemcitabine + cisplatin; khoảng ==95%== đáp ứng, đa số một phần {{Y5 tr.208}}\n- Hóa cảm ứng làm tăng tổng thời gian, chi phí điều trị và độc tính so với hóa xạ đồng thời đơn thuần {{Y5 tr.208}}\n- Bổ trợ sau hóa xạ đồng thời: cải thiện kết quả ở vài nhóm bệnh nhân trong một số nghiên cứu {{Y5 tr.208}}\n- Hóa trị đơn thuần (tái phát, tiến triển, di căn): bộ đôi chuẩn cisplatin + gemcitabine hoặc cisplatin + 5-FU; tỉ lệ đáp ứng ==60–74%== {{Y5 tr.207}}\n@@tab Đích và miễn dịch\n- Cetuximab (biểu mô vảy tiến triển tại chỗ–vùng, cùng xạ): 400 mg/m² tuần đầu, sau đó 250 mg/m² các tuần tiếp, 6 tuần {{QĐ1514 tr.PDF 168}}\n- Pembrolizumab (tái phát/di căn, PD-L1 dương, theo QĐ1514): **200 mg TM mỗi 3 tuần** đến khi tiến triển hoặc độc tính không chấp nhận; có thể đến 24 tháng nếu bệnh không tiến triển {{QĐ1514 tr.PDF 168}} {{QĐ1514 tr.PDF 172}}\n- Pembrolizumab theo Y5 (KEYNOTE-028, 27 bệnh nhân PD-L1 dương): liều 10 mg/kg mỗi 2 tuần; đáp ứng một phần 26%, bệnh ổn định 52%, PFS trung vị 6,5 tháng {{Y5 tr.211}}\n- Nivolumab: QĐ1514 ghi cho loại không sừng hóa tái phát/di căn (không ghi liều); Y5: nghiên cứu pha II 44 bệnh nhân, 3 mg/kg mỗi 2 tuần, đáp ứng 20,5% {{QĐ1514 tr.PDF 171}} {{Y5 tr.211}}\n- Đang nghiên cứu: cetuximab + carboplatin (đáp ứng 12%), vaccin EBV, tế bào T gây độc đặc hiệu EBV {{Y5 tr.210}} {{Y5 tr.211}}\n- Ức chế TKI (gefitinib, erlotinib): Y5 ghi không có lợi ích {{Y5 tr.210}}; QĐ1514 ghi đang nghiên cứu (gồm afatinib) {{QĐ1514 tr.PDF 168}}\n@@tab Tái phát và di căn\n- **Tái phát tại chỗ–vùng** (==15–58%==): phẫu thuật cứu vớt chọn lọc (tiếp cận phía trước; sống còn 3 năm khoảng 60% ở bệnh nhân chọn lọc), hoặc tái xạ {{Y5 tr.208}} {{Y5 tr.209}}\n- Trước điều trị lại: MRI vùng đầu cổ và PET/CT để tìm di căn xa; gần một nửa tái phát tại chỗ đã có di căn xa {{Y5 tr.209}}\n- Di căn xương (QĐ1514): đa hóa trị mạnh; đáp ứng trên 50% → tiếp tục đến 6 đợt rồi xạ flash 17 Gy ×2 đợt; đáp ứng dưới 50% → xạ 60–66 Gy {{QĐ1514 tr.PDF 169}}\n- Thuốc chống hủy xương: acid zoledronic 4 mg hoặc pamidronat 90 mg pha 250 ml truyền tĩnh mạch 1 giờ, chu kỳ 3–4 tuần {{QĐ1514 tr.PDF 169}}\n- Di căn phổi: hóa trị PC hoặc DC, đánh giá sau 3 đợt; đáp ứng trên 50% thì đủ 6 đợt; dưới 50% thì xạ triệu chứng 65–70 Gy {{QĐ1514 tr.PDF 169}}\n- Di căn não: ổ dưới 3 cm và dưới 3 ổ → xạ phẫu gamma; nhiều ổ → xạ toàn não 40 Gy (2 Gy/ngày) hoặc 30 Gy (3 Gy/ngày) {{QĐ1514 tr.PDF 169}}\n- Di căn gan: tiên lượng rất xấu {{QĐ1514 tr.PDF 169}}\n@@tab Biến chứng điều trị\n- Viêm niêm mạc là độc tính cấp nổi bật của xạ trị; hóa trị làm nặng thêm {{Y5 tr.211}}\n- Độc tính muộn độ 3–4 được báo cáo từ 5 đến 20% trong một số nghiên cứu {{Y5 tr.210}}\n- Muộn: hoại tử thùy thái dương (2–3% bệnh nhân); hoại tử xương nền sọ có thể gây chảy máu từ động mạch cảnh trong; tổn thương tủy 1–18 năm sau xạ; khô miệng, khít hàm {{Y5 tr.211}} {{Y5 tr.212}}\n- Xạ vùng cổ có nguy cơ suy giáp: theo dõi chức năng tuyến giáp; ung thư thứ hai thường là carcinôm tế bào gai vùng đầu cổ {{Y5 tr.212}}\n@@end\n\n### 7.3 Phác đồ – Y lệnh\n> [!doc] QĐ 1514/QĐ-BYT, phần \"Một số phác đồ hóa chất\" và phần phác đồ theo giai đoạn. Chép đúng nguồn; chu kỳ ghi như nguồn. {{QĐ1514 tr.PDF 168}} {{QĐ1514 tr.PDF 170}}\n\n| Phác đồ | Thuốc – liều | Chu kỳ / cách dùng | Chỉ định | Ghi chú |\n|---|---|---|---|---|\n| Hóa xạ đồng thời (cisplatin hàng tuần) | Cisplatin 30–40 mg/m² TM | mỗi tuần ×6 đợt, cùng xạ | giai đoạn II–IVA | carboplatin hàng tuần nếu chống chỉ định cisplatin {{QĐ1514 tr.PDF 170}} |\n| Hóa xạ đồng thời (cisplatin 3 tuần) | Cisplatin 100 mg/m² TM | ngày 1, 22, 43, cùng xạ | giai đoạn II–IVA | {{QĐ1514 tr.PDF 169}} {{QĐ1514 tr.PDF 170}} |\n| Cảm ứng A: cisplatin + 5-FU | Cisplatin 100 mg/m² ngày 1; 5-FU 1.000 mg/m² ngày 1–5 | 3–4 tuần × 4–6 chu kỳ | tiến xa, trước hóa xạ đồng thời | {{QĐ1514 tr.PDF 170}} |\n| Cảm ứng B: docetaxel + cisplatin | Docetaxel 75 mg/m² truyền 1 giờ ngày 1; cisplatin 75 mg/m² truyền 3 giờ ngày 1 | 3 tuần × 4–6 chu kỳ | tiến xa | carboplatin thay cisplatin khi không dung nạp {{QĐ1514 tr.PDF 170}} {{QĐ1514 tr.PDF 171}} |\n| Cảm ứng C: TPF (docetaxel + cisplatin + 5-FU) | tài liệu không nêu liều | tài liệu không nêu | tiến xa; Y5 gọi là phác đồ dẫn đầu được khuyến cáo | {{Y5 tr.208}} {{QĐ1514 tr.PDF 170}} |\n| Cảm ứng D: paclitaxel–epirubicin–cisplatin | tài liệu không nêu liều | tài liệu không nêu | tài liệu không nêu | {{QĐ1514 tr.PDF 170}} |\n| Bổ trợ: cisplatin + 5-FU hoặc carboplatin + 5-FU | tài liệu không nêu liều | tài liệu không nêu | sau điều trị | {{QĐ1514 tr.PDF 170}} |\n| Tái phát/di căn: gemcitabine + cisplatin | Gemcitabine 1.000 mg/m² ngày 1, 8, 15; cisplatin 50–70 mg/m² ngày 1 | chu kỳ 28 ngày | tái phát/di căn | {{QĐ1514 tr.PDF 170}} |\n| Tái phát/di căn: 5-FU + cisplatin | 5-FU 1.000 mg/m² ngày 1–5; cisplatin 100 mg/m² ngày 1 | 3–4 tuần × 4–6 chu kỳ | tái phát/di căn | {{QĐ1514 tr.PDF 170}} |\n| Tái phát/di căn: paclitaxel + cisplatin hoặc carboplatin | Paclitaxel 135 mg/m² ngày 1 + carboplatin AUC-2 ngày 1–4; hoặc paclitaxel 175 mg/m² ngày 1 + cisplatin 75 mg/m² ngày 2 | carboplatin: chu kỳ 6 tuần, 4–6 chu kỳ; cisplatin: 3 tuần × 4–6 | tái phát/di căn | ghi nguyên văn nguồn {{QĐ1514 tr.PDF 171}} |\n| Tái phát/di căn: docetaxel + cisplatin hoặc carboplatin | Docetaxel 75 mg/m² ngày 1 + cisplatin 75 mg/m² ngày 1 | 3 tuần × 4–6 chu kỳ | tái phát/di căn | {{QĐ1514 tr.PDF 171}} |\n| Tái phát/di căn: carboplatin + cetuximab (biểu mô vảy) | Cetuximab 400 mg/m² ngày 1, sau đó 250 mg/m² hàng tuần; carboplatin AUC 5 ngày 1 | 3 tuần × 8 chu kỳ | biểu mô vảy tái phát/di căn | {{QĐ1514 tr.PDF 171}} |\n| Tái phát/di căn: gemcitabine + vinorelbine (ghi \"Phác đồ GV\" trong nguồn) | Gemcitabine 1.000 mg/m² ngày 1, 8; vinorelbine 25 mg/m² ngày 1, 8 | 21 ngày | tái phát/di căn | {{QĐ1514 tr.PDF 171}} |\n| Đơn chất (tái phát/di căn) | Paclitaxel 30 mg/m² ngày 1–5 và 29–33, hoặc 175 mg/m² ngày 1; docetaxel 75 mg/m²; methotrexate 40 mg/m² hàng tuần; gemcitabine 1.000 mg/m² ngày 1, 8, 15 | paclitaxel và docetaxel 3 tuần × 4 chu kỳ; gemcitabine 28 ngày | tái phát/di căn | {{QĐ1514 tr.PDF 171}} |\n| Duy trì: UFT | 400 mg/ngày, chia 2 lần | liên tục 1–2 năm sau xạ trị | sau xạ trị | {{QĐ1514 tr.PDF 171}} |\n| Cetuximab + xạ trị | Cetuximab 400 mg/m² tuần đầu, sau đó 250 mg/m² × 6 tuần | cùng xạ trị | tiến xa tại chỗ–vùng biểu mô vảy | {{QĐ1514 tr.PDF 168}} |\n| Pembrolizumab | 200 mg TM | mỗi 3 tuần đến khi tiến triển hoặc độc tính không chấp nhận; có thể đến 24 tháng nếu không tiến triển | tái phát/di căn PD-L1 dương | {{QĐ1514 tr.PDF 168}} {{QĐ1514 tr.PDF 172}} |\n| Nivolumab | tài liệu không nêu liều | tài liệu không nêu | loại không sừng hóa tái phát/di căn | {{QĐ1514 tr.PDF 171}} |\n\n> [!warn] Theo dõi và độc tính cần nhớ\n> - Hóa chất làm tăng giảm bạch cầu hạt độ 3–4, buồn nôn, nôn và viêm niêm mạc {{Y5 tr.208}}\n> - Trong điều trị hóa chất, theo dõi tác dụng phụ theo loại thuốc: hạ bạch cầu, tiểu cầu, thiếu máu, nôn, suy kiệt {{QĐ1514 tr.PDF 172}}\n> - Phác đồ QĐ1514 không ghi liều ở TPF, paclitaxel–epirubicin–cisplatin, hóa bổ trợ và nivolumab: tra bản gốc khi dùng thực tế {{QĐ1514 tr.PDF 170}}\n\n## 8. Tiên lượng – Dự phòng\n\n> [!key] Tóm tắt\n> - Tiên lượng theo **giai đoạn** (I–II tốt hơn III–IV), kèm tuổi, giới, giải phẫu bệnh, T4, hạch, nồng độ EBV DNA {{Y5 tr.213}}\n> - Chưa có chương trình tầm soát ung thư vòm hầu cho dân số chung; ở gia đình có người mắc, tầm soát bằng EBV DNA hoặc kháng thể EBV kết hợp soi vòm {{Y5 tr.213}}\n\n### Tiên lượng\n@@tabs\n@@tab Yếu tố tiên lượng\n| Yếu tố | Tốt | Xấu |\n|---|---|---|\n| Tuổi | <40 | — {{Y5 tr.213}} |\n| Giới | Nữ | — {{Y5 tr.213}} |\n| Giai đoạn bệnh | I, II | III, IV {{Y5 tr.213}} |\n| T4 | — | có {{Y5 tr.213}} |\n| Bướu | <2 cm | — {{Y5 tr.213}} |\n| Hạch | — | hai bên, xâm lấn; di căn nhóm hạch cổ thấp {{Y5 tr.213}} |\n| Giải phẫu bệnh | không sừng hóa | sừng hóa; tế bào gai dạng đáy {{Y5 tr.213}} |\n| Nồng độ EBV | — | >4000 copies {{Y5 tr.213}} |\n\n@@tab Sống còn 5 năm theo giai đoạn\n| Giai đoạn | Y5 (Bảng 12) | QĐ1514 (tr.168) |\n|---|---|---|\n| I | 90% {{Y5 tr.213}} | 80–90% (giai đoạn I và II) {{QĐ1514 tr.PDF 168}} |\n| II | 84% {{Y5 tr.213}} | 80–90% (giai đoạn I và II) {{QĐ1514 tr.PDF 168}} |\n| III | 75% {{Y5 tr.213}} | 30–40% {{QĐ1514 tr.PDF 168}} |\n| IV | 58% {{Y5 tr.213}} | 15% {{QĐ1514 tr.PDF 168}} |\n\n- QĐ1514: ở Việt Nam ==90–97%== bệnh nhân được phát hiện ở giai đoạn III và IV {{QĐ1514 tr.PDF 168}}\n- Giai đoạn sớm có thể khỏi; giai đoạn muộn tiên lượng xấu {{QĐ1514 tr.PDF 172}}\n@@end\n\n### Theo dõi sau điều trị\n\n| Nội dung | Y5 (tr.212) | QĐ1514 |\n|---|---|---|\n| Đánh giá đáp ứng | MRI vùng nền sọ và hạch cổ sau điều trị làm cơ sở theo dõi; PET/CT sau ==3 tháng== kể từ khi kết thúc điều trị; PET/CT trước 12 tuần dễ cho dương tính giả {{Y5 tr.212}} | chụp PET/CT sau điều trị để theo dõi đáp ứng, tái phát và di căn {{QĐ1514 tr.PDF 165}} |\n| Lịch khám | 3 tháng/lần trong 2 năm đầu; 4–6 tháng/lần từ năm 3 đến năm 5; sau 5 năm mỗi năm {{Y5 tr.212}} | 1–3 tháng/lần năm 1; 3–4 tháng/lần năm 2; 4–6 tháng/lần năm 3–5; sau năm 5 mỗi 6–12 tháng {{QĐ1514 tr.PDF 169}}; và 3 tháng/lần trong 3 năm đầu, sau đó 6–12 tháng/lần {{QĐ1514 tr.PDF 172}} |\n| EBV DNA | có thể có vai trò tiên lượng và xác định tái phát; lợi ích về sống còn chưa rõ {{Y5 tr.212}} | tài liệu không nêu |\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] Bệnh này thi nhấn mạnh gì\n> - **Chẩn đoán**: hạch cổ và triệu chứng tai–mũi–thần kinh; nội soi + **sinh thiết (mô bệnh học)**; phân giai đoạn TNM {{QĐ1514 tr.PDF 166}} {{Y5 tr.203}}\n> - **Điều trị**: xạ trị là chính; hóa xạ đồng thời từ giai đoạn II; hóa cảm ứng ở tiến xa; IVB hóa trị hoặc giảm nhẹ {{QĐ1514 tr.PDF 167}} {{Y5 tr.208}}\n> - Trọng số thi theo QĐ 22 cho bệnh này: tài liệu không nêu; khung liên quan STT 15, 23, 38, 96\n\n@@tabs\n@@tab Nhận diện\n- Nguy cơ: EBV, tiền sử gia đình, cá muối và thức ăn ướp muối, hút thuốc lá (tăng 2–6 lần) {{Y5 tr.199}} {{Y5 tr.201}}\n- Nam mắc gấp 2–3 lần nữ; Nam Trung Quốc–Hồng Kông có tần suất cao nhất (đối chiếu Đông Nam Á ở lưu ý mục 9) {{Y5 tr.198}}\n- Triệu chứng hay gặp: **hạch cổ** nhóm II và VA, trên 50% trước u nguyên phát {{Y5 tr.203}}\n- {r|Báo động}: liệt dây VI, sụp mi một bên, song thị, đau mặt; ù tai, nghẹt hoặc chảy máu mũi kéo dài một bên {{Y5 tr.203}} {{QĐ1514 tr.PDF 164}}\n- Khám: soi vòm thấy u ở hai thành bên và nóc vòm, sinh thiết {{QĐ1514 tr.PDF 164}}\n[Xem mục 4](#/n/ung-thu-vom-hau/4) · [mục 3](#/n/ung-thu-vom-hau/3)\n@@tab Chẩn đoán\n- Mô bệnh học là **tiêu chuẩn**: có u và/hoặc hạch cổ, mô bệnh học là ung thư {{QĐ1514 tr.PDF 166}}\n- CT đầu cổ bắt buộc; MRI khi xâm lấn não; PET-CT khi có triệu chứng, hạch vỡ vỏ hoặc EBV DNA ≥4000 copies/mL {{Y5 tr.205}}\n- EBV: VCA-IgA nhạy 87–97%; cặp VCA + EA nhạy trên 90,63% {{Y5 tr.200}}\n- TNM: T1 khu trú ở vòm, T2 xâm khoang cạnh hầu, N3 >6 cm; giai đoạn I là T1N0M0 {{Y5 tr.205}} {{Y5 tr.206}}\n- Chẩn đoán phân biệt hạch cổ: lao, lymphôm, di căn ung thư vùng đầu cổ; cần mô bệnh học {{QĐ1514 tr.PDF 167}}\n[Xem mục 5](#/n/ung-thu-vom-hau/5) · [mục 6](#/n/ung-thu-vom-hau/6)\n@@tab Điều trị\n- Giai đoạn I: xạ trị đơn thuần 66 Gy (không biệt hóa) hoặc 70 Gy (biểu mô vảy); hạch dự phòng 50 Gy {{QĐ1514 tr.PDF 168}}\n- Giai đoạn II–IVA: {p|cisplatin 30–40 mg/m² hàng tuần ×6} hoặc {p|100 mg/m² ngày 1, 22, 43} cùng xạ {{QĐ1514 tr.PDF 169}} {{QĐ1514 tr.PDF 170}}\n- Tiến xa (T4, N3 lớn, hạch thượng đòn): {g|hóa cảm ứng} (TPF hoặc gemcitabine + cisplatin; cisplatin + 5-FU 1.000 mg/m² ×4–6 chu kỳ) {{Y5 tr.208}} {{QĐ1514 tr.PDF 170}}\n- Hạch cổ: xạ **hai bên**; N0 có thể bỏ hạch cổ thấp {{Y5 tr.207}}\n- Giai đoạn IVB: {p|gemcitabine + cisplatin} hoặc chăm sóc giảm nhẹ {{QĐ1514 tr.PDF 170}} {{Y5 tr.208}}\n- {r|Tái phát}: phẫu thuật cứu vớt chọn lọc hoặc tái xạ; cần MRI và PET/CT trước {{Y5 tr.209}}\n- Tái phát PD-L1 dương: {p|pembrolizumab 200 mg mỗi 3 tuần} {{QĐ1514 tr.PDF 168}} {{QĐ1514 tr.PDF 172}}\n[Xem mục 7](#/n/ung-thu-vom-hau/7) (7.2 Các phương pháp; 7.3 Phác đồ – Y lệnh)\n@@tab Tiên lượng – Dự phòng\n- Tiên lượng xấu: giai đoạn III–IV, T4, hạch hai bên hoặc xâm lấn, di căn hạch cổ thấp, sừng hóa, tế bào gai dạng đáy, EBV DNA trên 4000 copies {{Y5 tr.213}}\n- Sống 5 năm (Y5, Bảng 12): giai đoạn I ==90%==, giai đoạn IV ==58%== {{Y5 tr.213}}\n- Theo dõi: 3 tháng/lần trong 2 năm đầu (Y5) {{Y5 tr.212}}\n- Dự phòng: bỏ thuốc lá, hạn chế cá muối và thức ăn ướp muối; tầm soát EBV ở gia đình có người mắc {{Y5 tr.213}}\n[Xem mục 8](#/n/ung-thu-vom-hau/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Ca mới / tử vong Việt Nam 2018 (Globocan) | ==6.212 / 4.232== | {{Y5 tr.198}} |\n| Hạch cổ là dấu hiệu đầu, trước u nguyên phát | ==trên 50%== | {{Y5 tr.203}} |\n| Di căn hạch vùng lúc chẩn đoán / hạch cổ hai bên | ==90% / 50%== | {{Y5 tr.201}} |\n| Di căn xa lúc chẩn đoán / trong diễn tiến | ==5% / 20–50%== | {{Y5 tr.201}} |\n| EBV DNA gợi ý PET-CT | ==≥4000 copies/mL== | {{Y5 tr.205}} |\n| VCA-IgA nhạy / EA-IgA đặc hiệu | ==87–97% / trên 95%== | {{Y5 tr.200}} |\n| Hút thuốc lá | ==tăng 2–6 lần== | {{Y5 tr.201}} |\n| Xạ trị giai đoạn I (QĐ1514) | ==66 Gy / 70 Gy; hạch dự phòng 50 Gy== | {{QĐ1514 tr.PDF 168}} |\n| Hóa xạ đồng thời cisplatin | ==30–40 mg/m² mỗi tuần ×6, hoặc 100 mg/m² ngày 1, 22, 43== | {{QĐ1514 tr.PDF 169}} {{QĐ1514 tr.PDF 170}} |\n| Sống 5 năm giai đoạn I / IV (Y5) | ==90% / 58%== | {{Y5 tr.213}} |\n| Tái phát tại chỗ–vùng | ==15–58%, thường trong 3 năm đầu== | {{Y5 tr.208}} |\n| Theo dõi 2 năm đầu (Y5) | ==3 tháng/lần== | {{Y5 tr.212}} |\n| Pembrolizumab (QĐ1514) | ==200 mg mỗi 3 tuần== | {{QĐ1514 tr.PDF 172}} |\n\n> [!warn] Bẫy thi thường gặp\n> - **Sống 5 năm khác nhau giữa hai nguồn**: Y5 (I 90%, II 84%, III 75%, IV 58%) khác QĐ1514 (I–II 80–90%, III 30–40%, IV 15%); ghi cả hai nguồn {{Y5 tr.213}} {{QĐ1514 tr.PDF 168}}\n> - **Tuổi đỉnh mắc**: Y5 đỉnh 50–59 tuổi (nhóm nguy cơ cao) khác QĐ1514 30–50 tuổi {{Y5 tr.198}} {{QĐ1514 tr.PDF 164}}\n> - **N3**: Y5 gồm hạch cổ dưới sụn nhẫn (IV, Vb); QĐ1514 gồm hạch trong hố thượng đòn (N3b) {{Y5 tr.206}} {{QĐ1514 tr.PDF 166}}\n> - **Đông Nam Á**: Y5 tr.198 xếp vào vùng nguy cơ trung bình, nhưng Y5 tr.199 ghi tần suất cao gấp nhiều lần khu vực khác {{Y5 tr.198}} {{Y5 tr.199}}\n> - **T0**: Y5 chỉ ghi không phát hiện bướu nguyên phát; QĐ1514 thêm điều kiện có hạch cổ và EBV dương tính {{Y5 tr.205}} {{QĐ1514 tr.PDF 166}}\n> - **T4**: Y5 ghi tuyến mang tai; QĐ1514 ghi tuyến nước bọt, hố thái dương và khoang cơ nhai {{Y5 tr.206}} {{QĐ1514 tr.PDF 166}}\n> - **Pembrolizumab**: Y5 (KEYNOTE-028) ghi 10 mg/kg mỗi 2 tuần; QĐ1514 ghi 200 mg mỗi 3 tuần {{Y5 tr.211}} {{QĐ1514 tr.PDF 172}}\n> - **TKI**: Y5 ghi gefitinib, erlotinib không có lợi ích; QĐ1514 ghi đang nghiên cứu {{Y5 tr.210}} {{QĐ1514 tr.PDF 168}}\n> - **Lịch theo dõi**: Y5 (tr.212) ghi 3 tháng/lần trong 2 năm đầu; QĐ1514 tr.PDF 169 ghi 1–3 tháng/lần năm đầu; QĐ1514 tr.PDF 172 ghi 3 tháng/lần trong 3 năm đầu; ghi cả ba {{Y5 tr.212}} {{QĐ1514 tr.PDF 169}} {{QĐ1514 tr.PDF 172}}\n> - **Tên AJCC**: Y5 ghi AJCC 2018; QĐ1514 ghi AJCC lần 8 năm 2017; nhóm giai đoạn giống nhau {{Y5 tr.205}} {{QĐ1514 tr.PDF 166}}\n> - **Tên gọi**: QĐ1514 dùng \"ung thư vòm mũi họng\", cùng một bệnh {{QĐ1514 tr.PDF 164}}\n\n@@fold Tự kiểm tra (15 thẻ)\n- Vị trí thường gặp của ung thư vòm hầu? :: Hố Rosenmüller (niêm mạc vòm hầu)\n- Yếu tố nguy cơ mạnh nhất theo Y5 Bảng 6? :: EBV và tiền sử gia đình có người mắc UTVH\n- Loại WHO liên quan EBV gần 100%? :: Carcinôm tế bào gai không sừng hóa (type II và III) {{Y5 tr.202}}\n- Triệu chứng nào thường khiến bệnh nhân đi khám? :: Hạch cổ, thường trước u nguyên phát (trên 50% ca), nhóm II và VA {{Y5 tr.203}}\n- Triệu chứng tai và mũi thường gặp? :: Đau tai, viêm tai giữa, ù tai; nghẹt mũi, chảy máu mũi\n- Dây thần kinh sọ hay bị tổn thương nhất? :: III, IV, V, VI (sụp mi, song thị, rối loạn vận nhãn)\n- Chẩn đoán xác định ung thư vòm hầu dựa vào gì? :: Mô bệnh học là ung thư, kèm u và/hoặc hạch cổ\n- Chỉ định PET-CT theo Y5? :: Có triệu chứng lâm sàng, hạch cổ vỡ vỏ bao, hoặc EBV DNA ≥4000 copies/mL {{Y5 tr.205}}\n- Hạch cổ dưới sụn nhẫn (IV, Vb) xếp N mấy theo Y5? :: N3 {{Y5 tr.206}}\n- Giai đoạn IVA theo Y5? :: T4 với N0–3, M0, hoặc bất kỳ T với N3, M0 {{Y5 tr.206}}\n- Hóa xạ đồng thời thường dùng? :: Cisplatin 30–40 mg/m² mỗi tuần ×6 đợt, hoặc 100 mg/m² ngày 1, 22, 43 {{QĐ1514 tr.PDF 169}} {{QĐ1514 tr.PDF 170}}\n- Liều xạ trị giai đoạn I theo QĐ1514? :: 66 Gy (không biệt hóa) hoặc 70 Gy (biểu mô vảy); hạch dự phòng 50 Gy {{QĐ1514 tr.PDF 168}}\n- Tỉ lệ sống 5 năm giai đoạn I theo Y5? :: 90% {{Y5 tr.213}}\n- Tái phát sau điều trị hay gặp khi nào? :: Trong 3 năm đầu; tại chỗ–vùng 15–58%, di căn xa 25–30% (chủ yếu xương) {{Y5 tr.208}}\n- Lịch theo dõi 2 năm đầu theo Y5? :: 3 tháng/lần {{Y5 tr.212}}\n@@end\n\n@@fold Nguồn tài liệu\n- **Y5**: chương \"Ung thư vòm hầu\" (Châu Đức Toàn, Nguyễn Hữu Phúc), tr.198–213 (`_work/text-ung-buou-y5.txt`); bảng 7–12 đối chiếu ảnh trang 205, 206, 213\n- **QĐ 1514/QĐ-BYT** (Bài 23 \"Ung thư vòm mũi họng\", tr. PDF 164–172; `_work/qd-1514-byt-ung-buou.txt`)\n- **SY5** tr.74, 75, 190 (`_work/slide-y5.txt`)\n- **ĐC Y5** tr.2–7: danh sách MT2–MT17 và dòng \"Ung thư vòm hầu\" trong bảng ca lâm sàng (`_work/decuong-y5.txt`)\n- **128 vấn đề**: mục 47 (đau họng và/hoặc chảy mũi), mục 114 (khối ở cổ)\n- **QĐ 22** STT 15, 23, 38, 96 (`_work/qd22.txt`)\n@@end\n\n@@fold Nguồn ngoài\n- Không dùng nguồn ngoài trong bài này. Mọi số liệu lấy từ tài liệu người dùng cung cấp.\n@@end"}, {"kind": "disease", "disease": "vu", "short": "Ung thư vú", "group": "", "section": 0, "order": 1, "khung": [85], "id": "ung-thu-vu", "title": "Ung thư vú", "layer": "benh", "module": "ung-buou", "tags": ["ung bướu", "vú", "khối ở vú", "tầm soát", "nhũ ảnh", "BI-RADS", "ER PR HER2", "TNM", "phác đồ BYT"], "source": "QĐ 3128/QĐ-BYT (17/7/2020); QĐ 3898/QĐ-BYT (18/12/2025); Y5 tr.1–23; SY5 tr.205–297; 128VĐ mục 89, 126", "body": "> [!key] Ung thư vú (UTV) trong một nhìn\n> - Ung thư thường gặp nhất và gây tử vong do ung thư hàng đầu ở nữ; VN 2022: ==24.563 ca mới, 10.008 tử vong== {{QĐ3898 tr.10}}\n> - Phát hiện: nhũ ảnh từ ==40 tuổi, mỗi năm== (nguy cơ trung bình); nguy cơ cao bắt đầu ==25 tuổi== {{QĐ3898 tr.27}}\n> - Chẩn đoán xác định = **mô bệnh học** (kim lõi/FNA); luôn làm ER, PR, HER2, Ki67 {{QĐ3128 tr.11}}\n> - Điều trị đa mô thức theo **giai đoạn + nhóm sinh học** (luminal / HER2 / tam âm) {{QĐ3128 tr.15}}\n> - Giai đoạn sớm sống 5 năm rất cao (stage 0–I ~100%, II 93%, III 72%, IV 22% – số Mỹ 2012) {{QĐ3128 tr.6}}\n\n## 3. Bệnh học\n\n> [!key] Tóm tắt\n> - Đa số là carcinôm ống tuyến xâm lấn NST; phân nhóm sinh học (ER/PR/HER2/Ki67) quyết định điều trị\n> - Nguy cơ chính: **tiếp xúc estrogen kéo dài**, tiền sử gia đình, BRCA1/2, mô vú đặc, xạ trị ngực trẻ\n\n### Định nghĩa & dịch tễ\n- UTV: ung thư thường gặp và **nguyên nhân tử vong do ung thư hàng đầu ở nữ** toàn cầu; nam chiếm ==~1%== {{QĐ3128 tr.6}} {{Y5 tr.1}}\n- Thế giới (GLOBOCAN 2022): >2,3 triệu ca mới, >670.000 tử vong {{QĐ3898 tr.10}}\n- Việt Nam: bảng so sánh các nguồn\n\n| Nguồn | Mới mắc | Tử vong | Ghi chú |\n|---|---|---|---|\n| QĐ3128 (2020) | >15.230/năm | >6.100/năm | {{QĐ3128 tr.6}} |\n| QĐ3898 (GLOBOCAN 2022) | 24.563 (đứng đầu các ung thư) | 10.008 (hạng 4 sau gan, phổi, dạ dày) | hiện mắc 5 năm 146,6/100.000 {{QĐ3898 tr.10}} |\n| Y5 (GLOBOCAN 2018) | xuất độ 26,4/100.000 | 10,5/100.000 | {{Y5 tr.1}} |\n| Slide Y5 (2022) | xuất độ 38,0 | 14,7 | 28,9% ung thư nữ VN {{SY5 tr.207–212}} |\n\n- Nguy cơ mắc suốt đời: Y5 ghi ==12,4%==; slide ghi 1/8 (12,2%) – hai nguồn chênh nhẹ {{Y5 tr.1}} {{SY5 tr.212}}\n- Tuổi: Âu–Mỹ đỉnh 60–70; **châu Á đỉnh 40–50** (sớm ~1 thập niên). Hà Nội 2010–2014: 40–49 (25,4%), 50–59 (33,9%); <40 chỉ 13,5%; <30 chỉ 1,7% {{QĐ3898 tr.12}}\n- Châu Á mắc thấp hơn phương Tây nhưng **tử vong liên quan cao hơn** {{QĐ3898 tr.10}}\n\n### Yếu tố nguy cơ\n@@tabs\n@@tab Nội tiết (thời gian tiếp xúc estrogen)\n- Có kinh sớm (<12 tuổi theo Y5; QĐ3898: trước 13 so với sau 15), mãn kinh muộn (>55) {{Y5 tr.2}} {{QĐ3898 tr.13}}\n- Mãn kinh <45 giảm ~1/2 nguy cơ so với >55; cắt buồng trứng trước mãn kinh giảm nguy cơ {{QĐ3898 tr.13}}\n- Nội tiết thay thế (estrogen ± progesterone) tăng nguy cơ {{QĐ3898 tr.13}}\n- Thuốc tránh thai: tăng tạm thời khi đang dùng/mới ngưng (≤10 năm), về bình thường sau 10 năm; <35 tuổi lợi ích vẫn vượt nguy cơ {{QĐ3898 tr.13}}\n- Không sinh con (nguy cơ gấp 1,4 lần); sinh con đầu >30 tuổi gấp 2–5 lần (Y5: sau 35) {{QĐ3898 tr.13}} {{Y5 tr.2}}\n- Không cho con bú; mỗi **1 năm** cho bú giảm ~4% (Y5: 12 tháng giảm 4,3%) {{QĐ3898 tr.14}} {{Y5 tr.2}}\n- Androgen/testosterone cao cũng tăng nguy cơ (đặc biệt ER+) {{QĐ3898 tr.14}}\n@@tab Di truyền – gia đình\n- **BRCA1/2** (NST 17, 13): nguy cơ đến 70–80 tuổi: BRCA1 ==55–72%==, BRCA2 ==45–69%==; gấp 4–6 lần dân số. Y5: đến 70 tuổi 57% và 40% {{QĐ3898 tr.11}} {{Y5 tr.2}}\n- ~10% UTV do di truyền (Y5: BRCA 5–10%); TP53 (Li-Fraumeni), PTEN (Cowden), STK11 (Peutz-Jeghers), CDH1, PALB2, ATM {{QĐ3898 tr.11}}\n- Mẹ/chị em/con gái mắc: nguy cơ gấp ==2–3 lần==; càng cao nếu mắc <30 tuổi hoặc ≥2 người {{QĐ3898 tr.11}}\n- Tiền sử UTV một bên → nguy cơ đối bên; LCIS, tăng sản không điển hình (ADH) {{QĐ3898 tr.12}}\n- Mô vú đặc (BI-RADS D) nguy cơ gấp **4–6 lần** mô nhiều mỡ (A) {{QĐ3898 tr.13}}\n@@tab Lối sống – môi trường\n- Béo phì sau mãn kinh (estrogen từ mô mỡ); mỗi +5 kg/m² tăng 12% {{Y5 tr.2}} {{SY5 tr.214}}\n- Rượu (+10%; mỗi 10 g/ngày thêm +7,1%); thuốc lá; ít vận động (~10% UTV, +9%) {{QĐ3898 tr.14}} {{SY5 tr.215}}\n- **Xạ trị vùng ngực lúc trẻ** (10–30 tuổi, nhạy nhất 10–14): nguy cơ gấp ~12 lần; thường sau ≥15 năm {{QĐ3898 tr.14}} {{Y5 tr.2}}\n- Hóa chất gây rối loạn nội tiết (BPA, phthalate, PCB, DDT, PFAS…); hydrocarbon thơm đa vòng {{QĐ3898 tr.15}}\n@@tab Phân tầng RR (slide)\n| RR | Yếu tố |\n|---|---|\n| <2 | Có kinh sớm; mãn kinh muộn; không con; rượu; nội tiết thay thế; béo phì sau mãn kinh |\n| 2–4 | CHEK2; sinh con đầu sau 35 tuổi; tăng sản ống tuyến; mô vú đặc >75%; mẹ/chị em mắc |\n| >4 | BRCA1-2; LCIS, ADH; xạ trị thành ngực trước 30 tuổi |\n{{SY5 tr.221}}\n@@end\n\n### Sinh bệnh học & sinh học phân tử\n- UTV khởi phát từ **đơn vị ống tận cùng của tiểu thùy**; có tế bào gốc tuyến vú → tiền thân đa năng {{Y5 tr.2}}\n- Hai dòng biệt hóa: **biểu mô lòng ống** (tiền thân HER2+, ER–; trưởng thành thì ER+) và **cơ biểu mô/đáy** (HER2–, ER–); đột biến ở giai đoạn nào cho nhóm sinh học đó {{Y5 tr.3}}\n- Nền tảng: [[ung-thu-co-che-sinh-ung]], [[ung-thu-sinh-hoc-phan-tu]]\n\n### Giải phẫu bệnh – phân loại\n@@tabs\n@@tab Tại chỗ / tiền ung thư\n| Loại | Đặc điểm |\n|---|---|\n| **DCIS** (ống tại chỗ) | ~15%; vi vôi hóa trên nhũ ảnh; 5 dạng (đặc, nhú, tủy, vi nhú, bã khô); tăng nguy cơ UTV đối bên {{Y5 tr.4}} |\n| **LCIS** (tiểu thùy tại chỗ) | đa ổ, 2 bên, nguy cơ thành xâm lấn thấp; **đã loại khỏi TNM AJCC 8** do tính chất lành tính {{Y5 tr.4}} {{QĐ3128 tr.14}} |\n| Tân sản tiểu thùy, ALH, u nhú nội ống | tổn thương tiền ung thư theo WHO 2012 {{QĐ3128 tr.9}} |\n@@tab Xâm lấn\n- **Carcinôm xâm lấn NST** (ống tuyến): thường gặp nhất (~75%); tiểu thùy xâm lấn 5–10% (đa ổ) {{Y5 tr.4}} {{SY5 tr.227}}\n- Thể đặc biệt (~10%): ống nhỏ, mặt sàng, nhầy, nhú, tủy, vi nhú (xấu hơn NST, ~3%), dị sản, tế bào nhẫn… {{QĐ3128 tr.8}}\n- Biệt hóa tốt, dự hậu tốt: ống nhỏ, nhầy, nhú, tủy {{Y5 tr.4}}\n- **Thể viêm** (T4d): 1–5%, đỏ da lan rộng, da cam, xấu; **Paget**: ~1%, tổn thương núm vú, >50% kèm ung thư trong vú {{Y5 tr.4}} {{Y5 tr.21}}\n- Độ mô học 1–3 (tạo ống tuyến, dị dạng nhân, phân bào) {{Y5 tr.4}}\n@@end\n\n### Phân nhóm sinh học (phân tử)\n| Nhóm | Tỉ lệ (Y5) | ER/PR | HER2 | Ki67 / ghi chú |\n|---|---|---|---|---|\n| Luminal A | 40% | ER+ (PR cao) | – | thấp; xét nghiệm gen nguy cơ thấp |\n| Luminal B – HER2 (–) | ~10% | ER+ | – | cao hoặc PR thấp; gen nguy cơ cao |\n| Luminal B – HER2 (+) | ~10% | ER+ | + | bất kỳ |\n| HER2 (+) không luminal | 15% | ER–, PR– | + | |\n| Tam âm / giống đáy | 15% | ER–, PR–, HER2– | – | gồm cả tủy điển hình, tuyến nang |\n{{QĐ3128 tr.10}} {{Y5 tr.13}}\n- Ngưỡng Ki67 **tùy phòng xét nghiệm**; cut-off PR gợi ý 20% (St. Gallen 2015) {{QĐ3128 tr.10}}. Y5 dùng Ki67 14%; slide dùng PR ≥20% {{Y5 tr.13}} {{SY5 tr.266}}\n\n@@fold Hóa mô miễn dịch: cách đọc ER/PR/HER2\n- ER/PR theo ASCO/CAP: **dương khi ≥1%** nhân bắt màu; Allred: tổng điểm 2–8 {{Y5 tr.12–13}}\n- HER2 (DAKO): 0, 1+ = âm; **2+ → làm ISH/FISH**; 3+ = dương; kết luận dương khi 3+ và/hoặc ISH dương {{Y5 tr.13}}\n- DCIS thuần: không cần HER2, cần ER {{QĐ3128 tr.9}}\n@@end\n\n### Diễn tiến tự nhiên – lan tràn\n- 14–53% UTV tại chỗ thành xâm lấn sau 10–15 năm {{Y5 tr.4}}\n- Hạch: **95% dẫn lưu về hạch nách** (I→II→III) rồi thượng/hạ đòn; còn lại hạch vú trong; **hạch lính gác** âm thì hiếm khi di căn nhảy cóc {{Y5 tr.5}}\n- Di căn xa: xương, phổi, gan, não. Luminal muộn (5–10 năm, hay xương); **giống đáy trong ~2 năm**; não hay gặp ở tam âm/HER2+ {{Y5 tr.5}} {{SY5 tr.230}}\n\n## 4. Triệu chứng học\n\n> [!key] Tóm tắt\n> - Thường gặp nhất: **tự sờ thấy cục ở vú** (không đau); phụ nữ >30 tuổi có cục ở vú phải nghi ung thư {{SY5 tr.235}}\n> - Khám đủ: hỏi, nhìn, sờ hai bên, hạch nách và thượng đòn; tốt nhất tuần đầu sau sạch kinh\n\n### Triệu chứng cơ năng & hoàn cảnh phát hiện\n- Sớm: tầm soát, chưa triệu chứng (DCIS ~0,5–1 ca/1000 lượt chụp) {{Y5 tr.5}}\n- Thường: cục ở vú, tiết dịch núm vú; đau nhẹ như kiến cắn; muộn: căng tức, đau, chảy dịch hôi, chảy máu {{QĐ3128 tr.6}}\n- Trễ: tự điều trị dân gian (đắp lá, chích lể) làm bệnh phức tạp; da cam, co kéo, tụt núm, hạch nách/thượng đòn; lan tràn: khó thở, nhức đầu, đau/gãy xương, báng bụng {{Y5 tr.6}}\n- **10 dấu hiệu báo hiệu** (QĐ3898): cục ở vú; một bên dày chắc/to/xệ; da lồi lõm, co kéo; núm vú tụt; đổi màu da; hạch nách/thượng đòn to; chảy dịch một bên; đau hoặc đỏ vú {{QĐ3898 tr.19}}\n\n### Hỏi bệnh\n- Quá trình phát hiện, can thiệp trước đó; tiền sử bệnh vú, sản phụ khoa, **tình trạng kinh nguyệt** (chọn nội tiết); tiền sử gia đình UTV/buồng trứng {{QĐ3128 tr.6}}\n- Chưa con/muốn sinh thêm: tư vấn trữ phôi/trứng trước hóa trị {{Y5 tr.6}}\n- Hỏi thuốc/đắp lá đã dùng {{Y5 tr.6}}\n\n### Khám thực thể\n@@tabs\n@@tab Quan sát\n- Ngồi, tay buông → giơ tay lên → chống hông (làm nổi vùng co kéo kín đáo); so sánh kích thước, hình dạng hai vú {{QĐ3898 tr.20}}\n- Da: phù **sần da cam**, đỏ, loét, chảy dịch/máu; núm vú: lệch tâm, co kéo, loét {{QĐ3898 tr.20}}\n- **Đỏ da trong UTV thể viêm**: toàn vú, **không đau, không nóng** (khác viêm nhiễm) {{QĐ3898 tr.20}}\n@@tab Sờ vú\n- Ngồi thẳng rồi nằm; dùng **4 ngón tay** (không bóp bằng 2 ngón); vòng xoáy/nan hoa; giới hạn: xương đòn – nếp dưới vú – bờ xương ức – đường nách giữa {{QĐ3898 tr.20–21}} {{Y5 tr.6–7}}\n- Ghi: kích thước, vị trí, mật độ, di động, co kéo da {{QĐ3898 tr.21}}\n- Thời điểm: tuần đầu sau sạch kinh {{QĐ3898 tr.19}}\n@@tab Hạch vùng\n- Khám nách (đỡ tay bệnh nhân), thượng đòn; ghi số lượng, kích thước, mật độ, di động, đau {{QĐ3898 tr.21}}\n- Hạch ≤1 cm, mềm, di động, nhất là hai bên: hiếm ác tính; **hạch thượng đòn sờ được là bất thường** {{QĐ3898 tr.21}}\n- Hạch di căn: tròn, sượng, cứng, dính nhau/dính mô {{Y5 tr.7}}\n@@end\n\n> [!red] Dấu hiệu nghi ngờ ác tính khi khám {{QĐ3898 tr.29}}\n> - U mật độ chắc, ranh giới không rõ, nhiều thùy múi, co kéo da, tụt núm, xâm lấn da, vỡ loét\n> - Hạch nách to, chắc, di động hạn chế; **chảy dịch máu núm vú**\n> - Di căn xa: đau đầu, đau xương, khó thở {{QĐ3128 tr.7}}\n\n### Thể lâm sàng đặc biệt\n@@fold Bệnh Paget vú\n- Tổn thương giống chàm núm vú (đỏ, tiết dịch, đóng mày, tụt núm); hiếm hai bên/nam; chẩn đoán: **sinh thiết da full-thickness** phức hợp quầng–núm {{Y5 tr.21–22}} {{QĐ3128 tr.8}}\n- Có thành phần ung thư thì điều trị như UTV theo giai đoạn tương ứng {{QĐ3128 tr.6}}\n- Chỉ Paget núm vú = Tis (Paget); điều trị kinh điển đoạn nhũ; bảo tồn + xạ tái phát 5–8% {{Y5 tr.22}}\n@@end\n@@fold UTV và thai kỳ\n- Thường gặp nhất trong các ung thư ở thai kỳ; tổn thương lớn nhanh cần sinh thiết; **siêu âm** (nhũ ảnh ít hữu ích); MRI không cản từ khi cần {{Y5 tr.22}}\n- Hóa trị **chống chỉ định quý I**, từ quý II dùng doxorubicin, cyclophosphamide, 5-FU, taxane; **kháng HER2, nội tiết, xạ trị chống chỉ định suốt thai kỳ** {{QĐ3128 tr.18}} {{QĐ3128 tr.21}}\n@@end\n@@fold UTV thể viêm\n- Đỏ da lan rộng, da cam, người trẻ, ER thường âm; **là chẩn đoán lâm sàng**, sinh thiết da lành tính không loại trừ {{QĐ3898 tr.33}}\n- Xử trí như tiến triển tại chỗ: hóa trị tân bổ trợ → đoạn nhũ, **không bảo tồn, không SLNB**, bắt buộc xạ sau mổ {{Y5 tr.23}} {{QĐ3128 tr.37}}\n@@end\n\n### Tiếp cận các triệu chứng (khung 128 vấn đề)\n| STT | Vấn đề | Nguyên nhân cần nghĩ |\n|---|---|---|\n| [85](#/khung/85) | **Khối ở vú** (sách mục 89); chiếm 30–42% triệu chứng vú ở tuyến ban đầu | ung thư (carcinoma, sarcoma, lymphoma, thứ phát); u lành (sợi tuyến, nhú, diệp thể); thay đổi sợi bọc, nang, nang sữa; viêm/áp xe {{128VĐ mục 89}} |\n| [85](#/khung/85) | **Tầm soát UTV** (sách mục 126) | xem mục 8 |\n| | Núm vú tụt / chảy dịch / thay đổi da / đau vú / khối nách / vú nam | xử trí theo sơ đồ 4–9 QĐ3898, xem mục 8 |\n\n@@fold Tiếp cận một khối ở vú theo tuổi (QĐ 3898)\n- **≥30 tuổi**: khám lâm sàng → nghi ngờ thì chuyển chuyên gia + hình ảnh/lấy mẫu; ít nghi ngờ: X-quang ± siêu âm; BI-RADS 1–2 theo dõi 3–6 tháng; **BI-RADS 3**: theo dõi 6, 12, 24 tháng; **BI-RADS 4–5**: sinh thiết kim lõi/VABB {{QĐ3898 tr.29}}\n- **<30 tuổi**: siêu âm; ít nghi ngờ thì theo dõi 1–2 chu kỳ kinh; còn tồn tại thì xử trí như ≥30 {{QĐ3898 tr.30}}\n- Sau chọc hút dịch: khối biến mất, dịch không máu → sàng lọc theo lịch; **dịch máu hoặc khối tái phát/còn** → siêu âm + sinh thiết {{QĐ3898 tr.38}}\n- Nguyên tắc **bộ ba** lâm sàng – hình ảnh – mô/tế bào học: tương hợp lành 0–0,6% ung thư; tương hợp ác lên đến 99% {{Y5 tr.11}}\n@@end\n\n## 5. Cận lâm sàng\n\n> [!key] Tóm tắt\n> - Hình ảnh: **nhũ ảnh** (≥35–40 tuổi), **siêu âm** (trẻ, mô đặc, nang), **MRI** (nguy cơ cao, đa ổ, túi ngực)\n> - **Mô bệnh học là tiêu chuẩn vàng**; sinh thiết kim lõi ưu tiên hơn FNA khi thiếu nhà tế bào học\n> - Phân giai đoạn **TNM AJCC/UICC 8** (2017); xét nghiệm di căn khi có triệu chứng hoặc giai đoạn muộn\n\n### Chẩn đoán hình ảnh\n@@tabs\n@@tab Nhũ ảnh\n- Chụp 2 vú, **mỗi vú ≥2 tư thế (CC, MLO)** {{QĐ3128 tr.7}} {{QĐ3898 tr.22}}\n- Tổn thương: khối, vi vôi hóa, không đối xứng, biến dạng cấu trúc; có thể phát hiện ung thư **1,5–4 năm** trước khi sờ thấy; là biện pháp duy nhất được chứng minh giảm tử vong {{QĐ3898 tr.21–23}}\n- Mô đặc: dùng nhũ ảnh số cản quang, tomosynthesis 3D, chụp ống dẫn sữa {{QĐ3128 tr.7}}. **Âm tính không loại trừ** (~10% khối sờ thấy không thấy) {{Y5 tr.7}}\n- **Chống chỉ định**: đang viêm/áp xe/loét; tuần đầu sau mổ/sinh thiết vú. Túi ngực: kỹ thuật **Eklund** (hoặc thay bằng MRI + siêu âm) {{QĐ3898 tr.22}} {{QĐ3128 tr.7}}\n- Hạn chế: mô đặc, sát thành ngực, túi ngực, tia ion hóa, khó phân biệt lành/ác {{QĐ3898 tr.24}}\n@@tab Siêu âm\n- Vú + hạch vùng; 3D, đàn hồi, AVBS {{QĐ3128 tr.7}}\n- Ác tính: nốt đặc, giảm âm, **trục đứng**, bờ tua gai, không rõ, tăng sinh mạch {{QĐ3898 tr.25}} {{Y5 tr.9}}\n- Hạch nghi di căn: vỏ dày/ổ dãn >2,5 mm, mất rốn hạch {{Y5 tr.9}}\n- Chỉ định: mô đặc, <30–35 tuổi, nang vs đặc, túi ngực, viêm/áp xe, chảy dịch, hướng dẫn sinh thiết. **Không dùng đơn độc** để sàng lọc {{QĐ3898 tr.24}}\n- Hạn chế: phụ thuộc người làm, khó thấy vi vôi hóa, sát thành ngực {{QĐ3898 tr.25}}\n@@tab MRI vú\n- Độ nhạy cao nhất, đặc hiệu thấp (dương giả → sinh thiết/chẩn đoán quá mức) {{QĐ3898 tr.26}}\n- Chỉ định (QĐ3128): không thấy u trên nhũ ảnh, vú đã tạo hình, thể tiểu thùy, nghi đa ổ, **trước bảo tồn, trước tân bổ trợ** {{QĐ3128 tr.7}}\n- Tầm soát nguy cơ cao: BRCA1/2, xạ trị ngực 10–30 tuổi, LCIS/ADH, ≥40 tuổi mô đặc/túi ngực {{QĐ3898 tr.26}}\n- **Chống chỉ định**: máy tạo nhịp, van tim/clip kim loại không tương thích, suy thận nặng (có cản từ), dị ứng thuốc, sợ không gian kín; **thai: không tiêm cản từ** {{QĐ3898 tr.26}}\n@@tab Khác\n- X-quang ngực, siêu âm bụng, CT ngực–bụng–chậu–sọ, MRI sọ/cột sống {{QĐ3128 tr.7}}\n- **Xạ hình xương** SPECT/CT 99mTc-MDP (phát hiện di căn xương sớm hơn CT/MRI); PET/CT; xạ hình hạch cửa 99mTc-nanocolloid {{QĐ3128 tr.7–8}}\n- Siêu âm cổ: hạch cổ; MRI não khi nghi di căn não {{QĐ3898 tr.41}}\n@@end\n\n#### BI-RADS\n| Mức | Ý nghĩa | Xử trí |\n|---|---|---|\n| 0 | Chưa hoàn tất | Hình ảnh khác / so phim cũ |\n| 1 | Bình thường | Kiểm tra định kỳ |\n| 2 | Lành tính | Định kỳ |\n| 3 | Có thể lành (<2%) | Theo dõi **6 tháng** |\n| 4 (4A thấp, 4B vừa, 4C cao) | Nghi ác tính | **Sinh thiết** |\n| 5 | Rất nghi ung thư (>95%) | **Sinh thiết** |\n| 6 | Đã chẩn đoán ung thư | Điều trị |\n{{QĐ3898 tr.23}} {{Y5 tr.9}}\n\n### Giải phẫu bệnh – tế bào – dấu ấn\n@@tabs\n@@tab Lấy mẫu\n- **FNA**: tế bào học khối/hạch/dịch núm vú; cần nhà tế bào học giỏi; **không phân biệt xâm nhập với tại chỗ**; chính xác 77–99% {{QĐ3128 tr.8}} {{Y5 tr.11}}\n- **Sinh thiết kim lõi** (14–18G): cho ER/PR/HER2; VABB (hút chân không); sinh thiết định vị kim dây; mở; tức thì trong mổ {{QĐ3128 tr.8}}\n- Sinh thiết mở sau lõi kim: vôi hóa nghi ngờ không lấy được, ADH, LCIS đa dạng, không tương hợp hình ảnh – mô học, sẹo tỏa tia, tổn thương nhú {{Y5 tr.12}}\n- Báo cáo mô bệnh học: số u, vị trí, đường kính lớn nhất, bờ diện cắt, thể, độ mô học, xâm lấn mạch, hạch di căn/tổng hạch; đánh giá **đáp ứng sau tân bổ trợ** {{QĐ3128 tr.8}}\n@@tab Dấu ấn & gen\n- **ER, PR, HER2, Ki67** (bắt buộc); ISH khi HER2 2+ {{QĐ3128 tr.9}}\n- **BRCA1/2**: HER2 (–) dự định PARP/platin hoặc tiền sử gia đình {{QĐ3128 tr.9}}\n- **PIK3CA**: ER+/HER2– dự kiến ức chế PI3K (alpelisib) {{QĐ3128 tr.9}}\n- **PD-L1**: tam âm dự kiến kháng PD-L1 {{QĐ3128 tr.9}}\n- Bộ gen tiên lượng (RT-PCR/đa gen): luminal A/B HER2– khó quyết định hóa trị; Oncotype Dx (RS) {{QĐ3128 tr.10}} {{Y5 tr.17}}\n- Xét nghiệm lại ER/PR/HER2 ở tái phát/di căn, trước–sau tân bổ trợ {{QĐ3128 tr.10}}\n@@tab Máu & thường quy\n- Chỉ điểm CA15-3, CEA, CA27-29: **không có giá trị sàng lọc**; CA15-3 chỉ hỗ trợ theo dõi đáp ứng bệnh di căn {{QĐ3898 tr.17}} {{Y5 tr.14}}\n- Chuyển hóa, men gan, ALP, **Ca máu** (tăng khi di căn xương), ure/creatinine {{QĐ3128 tr.10}}\n- Estradiol/FSH nếu chưa rõ mãn kinh; **β-hCG** ở tuổi sinh đẻ; trước điều trị: CTM, nhóm máu, đông máu, HIV, viêm gan, ECG, siêu âm tim {{QĐ3128 tr.11}}\n@@end\n\n### Phân giai đoạn TNM (UICC/AJCC 8, 2017)\n- cTNM và pTNM chung T, M; khác ở N. Tiền tố **yc / yp** sau tân bổ trợ {{QĐ3128 tr.11}}\n@@tabs\n@@tab T\n| T | Mô tả |\n|---|---|\n| Tis (DCIS) / Tis (Paget) | tại chỗ; Paget núm vú không kèm ung thư xâm lấn/DCIS nhu mô |\n| T1 | ≤20 mm (T1mi ≤1; T1a >1–5; T1b >5–10; T1c >10–20 mm) |\n| T2 | >20–50 mm |\n| T3 | >50 mm |\n| T4 | xâm lấn thành ngực và/hoặc da (loét, nốt); chỉ xâm lấn hạ bì chưa đủ |\n| T4a | thành ngực (**không tính** chỉ dính/xâm lấn cơ ngực) |\n| T4b | loét, nốt vệ tinh cùng bên, phù da/da cam (chưa đủ thể viêm) |\n| T4c | T4a + T4b |\n| T4d | **thể viêm** |\n{{QĐ3128 tr.12}}\n@@tab N lâm sàng\n| cN | Mô tả |\n|---|---|\n| cN0 | không di căn hạch vùng |\n| cN1 (cN1mi) | hạch nách chặng I–II cùng bên, **di động** (vi di căn >0,2–2 mm) |\n| cN2a | hạch nách I–II **dính nhau/dính cấu trúc khác** |\n| cN2b | chỉ hạch vú trong cùng bên, không hạch nách |\n| cN3a | hạch **hạ đòn** (nách chặng III) |\n| cN3b | hạch vú trong + hạch nách |\n| cN3c | hạch **thượng đòn** |\n{{QĐ3128 tr.12–13}}\n@@tab pN\n| pN | Mô tả |\n|---|---|\n| pN0 (i+) | tế bào ác tính ≤0,2 mm; pN0 (mol+) chỉ PCR |\n| pN1mi | vi di căn (>0,2–2 mm) |\n| pN1a | **1–3** hạch nách (≥1 hạch >2 mm) |\n| pN1b / pN1c | hạch gác vú trong / cả hai |\n| pN2a | **4–9** hạch nách |\n| pN2b | hạch vú trong thấy trên hình ảnh, nách (–) |\n| pN3a | **≥10** hạch nách hoặc hạ đòn |\n| pN3b / pN3c | kèm hạch vú trong / thượng đòn |\n{{QĐ3128 tr.13}}\n@@tab M\n- M0 (cM0(i+): tế bào ≤0,2 mm trong máu/tủy, không triệu chứng); cM1: di căn xa trên lâm sàng/hình ảnh; pM1: chứng minh mô học {{QĐ3128 tr.13–14}}\n@@end\n\n#### Nhóm giai đoạn {{QĐ3128 tr.14}}\n| Giai đoạn | T | N | M |\n|---|---|---|---|\n| 0 | Tis | N0 | M0 |\n| IA | T1 | N0 | M0 |\n| IB | T0, T1 | N1mi | M0 |\n| IIA | T0, T1 | N1 | M0 |\n| IIA | T2 | N0 | M0 |\n| IIB | T2 | N1 | M0 |\n| IIB | T3 | N0 | M0 |\n| IIIA | T0, T1, T2 | N2 | M0 |\n| IIIA | T3 | N1, N2 | M0 |\n| IIIB | T4 | N0, N1, N2 | M0 |\n| IIIC | bất kỳ | N3 | M0 |\n| IV | bất kỳ | bất kỳ | M1 |\n\n> [!warn] Bẫy\n> - **T3N1M0** xếp IIIA nhưng điều trị theo nhóm **giai đoạn I, II và T3N1M0** (QĐ3128 tr.17); giai đoạn III còn lại là \"III trừ T3N1M0\" {{QĐ3128 tr.22}}\n> - AJCC 8 còn có **giai đoạn tiên lượng** (T, N, M + độ mô học + ER/PR/HER2 + Oncotype Dx) {{Y5 tr.17}}\n\n### Đánh giá di căn xa – khi nào?\n- Giai đoạn sớm: **không tầm soát thường quy**; chỉ khi triệu chứng/gợi ý (xạ hình xương, CT, MRI não) {{Y5 tr.14}} {{QĐ3128 tr.30}}\n- Giai đoạn III / IV: CT ngực–bụng–chậu, xạ hình xương, ± MRI não, PET/CT; **sinh thiết ổ di căn** đầu tiên và xét ER/PR/HER2, BRCA, PIK3CA, PD-L1 {{QĐ3128 tr.37–38}}\n\n## 6. Chẩn đoán – Chẩn đoán phân biệt\n\n> [!key] Chẩn đoán xác định UTV\n> - Lâm sàng (u) + hình ảnh (nhũ ảnh/siêu âm/MRI) + **mô bệnh học: có tế bào biểu mô ác tính** {{QĐ3128 tr.11}}\n> - Sinh thiết kim lõi hoặc FNA (FNA không phân biệt xâm nhập/tại chỗ; nơi thiếu nhà tế bào học → ưu tiên kim lõi); kim lõi còn cho thụ thể nội tiết, HER2 {{QĐ3128 tr.11}}\n> - Chẩn đoán đầy đủ: xác định + giai đoạn TNM + nhóm sinh học (ER/PR/HER2/Ki67) + bệnh kèm + thể trạng (ECOG/KPS) {{SY5 tr.267}}\n\n### Nhóm điều trị theo giai đoạn\n| Nhóm | Gồm | Điểm chính |\n|---|---|---|\n| Giai đoạn 0 | DCIS (LCIS) | cắt rộng ± xạ; nội tiết 5 năm nếu ER+ |\n| I, II, T3N1M0 | mổ được | bảo tồn hoặc đoạn nhũ ± hóa trị tân bổ trợ |\n| III (trừ T3N1M0) + thể viêm | tiến triển tại chỗ | **hóa trị tân bổ trợ** rồi mổ + xạ |\n| IV / tái phát xa | di căn | toàn thân, không khỏi, giảm triệu chứng |\n{{QĐ3128 tr.16–25}}\n\n### Chẩn đoán phân biệt khối ở vú\n| Bệnh lý | Giống | Khác / cận lâm sàng phân biệt |\n|---|---|---|\n| U xơ tuyến (fibroadenoma) | khối đặc | nguồn BYT; thường trẻ, bờ rõ, di động (như \"viên bi\"); siêu âm nốt đặc bờ đều; sinh thiết khi nghi {{QĐ3128 tr.11}} {{+StatPearls/ACS}} |\n| Nang vú, biến đổi xơ nang | cục, đau | dao động theo chu kỳ; **siêu âm: nang** (echo trống); chọc hút → khối xẹp, dịch không máu {{QĐ3128 tr.11}} {{QĐ3898 tr.38}} |\n| Nang sữa (galactocele) | cục sau cho con bú | tiền sử cho bú; chọc hút ra sữa {{QĐ3128 tr.11}} |\n| Viêm vú, **áp xe** | đỏ, cục | nóng, đau, sốt, thường liên quan cho bú; **đáp ứng kháng sinh** (khác thể viêm: không đau, không nóng) {{QĐ3898 tr.20}} {{QĐ3898 tr.33}} |\n| Hoại tử mỡ | cục cứng, có thể co kéo da | tiền sử chấn thương/phẫu thuật; hình ảnh có thể giống ác tính → sinh thiết {{QĐ3128 tr.11}} {{+StatPearls}} |\n| U phyllode (diệp thể) | khối đặc lớn nhanh | siêu âm giống sợi tuyến; **khối to nhanh**, cần cắt rộng; khó phân biệt FNA {{QĐ3128 tr.11}} {{+NCI PDQ}} |\n| U nhú trong ống | chảy dịch núm vú | chảy dịch trong/máu, một ống; chụp ống tuyến sữa, mổ cắt ống {{QĐ3898 tr.32}} |\n| U mỡ | khối mềm | bờ rõ, giảm âm, không cần đánh giá thêm {{QĐ3898 tr.25}} |\n| Sarcoma, lymphoma, di căn đến vú | khối | mô bệnh học + hóa mô miễn dịch {{QĐ3128 tr.11}} |\n| UTV | – | chắc, ranh giới không rõ, co kéo, hạch; BI-RADS 4–5; **mô bệnh học** |\n\n> [!ext] Mô tả điển hình từng bệnh lành tính (cột \"Khác\") được diễn đạt lại từ tổng quan chung (StatPearls \"Breast mass\", ACS); danh sách bệnh lý là của QĐ3128 tr.11. Không phải văn bản BYT.\n\n## 7. Điều trị\n\n### 7.1 Mục tiêu điều trị\n\n> [!key] Mục tiêu theo giai đoạn\n> - **Giai đoạn tại chỗ/tại vùng**: điều trị khỏi; phẫu thuật là chủ yếu, bảo tồn luôn kèm xạ; xạ + toàn thân bổ trợ tùy yếu tố nguy cơ {{Y5 tr.18}}\n> - **Di căn (IV)**: không chữa khỏi; giảm triệu chứng, nâng chất lượng sống, **kéo dài sống thêm** bằng phương pháp hiệu quả mà độc tính thấp {{QĐ3128 tr.23}}\n> - Cá thể hóa: giai đoạn, thể mô học, độ mô học, ER/PR/HER2, Ki67, tốc độ lớn, bệnh kèm, **ý muốn bệnh nhân**; chú ý thẩm mỹ, tâm lý, sinh đẻ, đời sống tình dục {{QĐ3128 tr.15}}\n\n- Hóa trị tân bổ trợ: hạ giai đoạn, thuận lợi bảo tồn/tái tạo, biến u không mổ được thành mổ được; **đáp ứng hoàn toàn mô bệnh học** là dấu hiệu tiên lượng tốt {{Y5 tr.21}}\n- Điều trị bổ trợ: tiêu diệt vi di căn, giảm tái phát/di căn và tăng sống thêm {{Y5 tr.20}}\n> [!ext] Theo NCI PDQ (2024–25): giai đoạn sớm nhằm chữa khỏi bằng phối hợp phẫu–xạ–hóa–nội tiết; di căn nhằm kéo dài sống thêm và kiểm soát triệu chứng; điều trị trước mổ giúp hạ giai đoạn và cho biết độ nhạy thuốc. Nhất quán với BYT. {{+NCI PDQ}}\n\n### 7.2 Các phương pháp\n\n@@tabs\n@@tab Phẫu thuật\n- Tại u: cắt tuyến vú vét hạch nách, **tiết kiệm da**, **bảo tồn quầng–núm**, **bảo tồn vú**; kèm tái tạo (túi độn, vạt da cơ có cuống/tự do; tức thì hoặc thì hai) {{QĐ3128 tr.15}}\n- Hạch: vét nách chặng I–II (N0 lâm sàng), thấy di căn I–II thì vét tiếp III; hoặc **sinh thiết hạch cửa** {{QĐ3128 tr.17}}\n- Hạch cửa: nhuộm (xanh methylene/isosulfan) và/hoặc 99mTc; **âm tính khi sinh thiết tức thì → không vét nách**; dương tính → vét nách thường quy {{QĐ3128 tr.17–18}}\n- Nghi hạch (+) lâm sàng: FNA/sinh thiết kim trước; âm tính mới làm hạch cửa {{QĐ3128 tr.17}}\n- Y5: SLNB độ nhạy 95–100%, âm giả 5–10%, giá trị tiên đoán âm 98%; vét nách di chứng đau, tê, phù bạch mạch {{Y5 tr.19}}\n@@tab Bảo tồn vú\n- Cắt rộng u + vét hạch/SLNB + **xạ trị bắt buộc**; kiểm tra diện cắt (dương → cắt lại); đặt clip giường u {{QĐ3128 tr.17}}\n- **Chống chỉ định tuyệt đối**: UTV đa ổ; trong 6 tháng đầu thai kỳ; vi canxi hóa lan tỏa; đã xạ trị ngực/vú; diện cắt dương dai dẳng {{QĐ3128 tr.17}}\n- **Tương đối**: u lớn so với vú; bệnh hệ thống; u dưới núm vú {{QĐ3128 tr.17}}\n- Y5 thêm: đột biến đồng hợp ATM, bệnh mô liên kết (xơ cứng bì, lupus) {{Y5 tr.18}}\n- Thể viêm: không bảo tồn {{QĐ3128 tr.37}}\n@@tab Xạ trị\n- Chiếu ngoài; **áp sát**; **IORT** (u <3 cm, không hạch, bảo tồn, hoặc tái phát) {{QĐ3128 tr.15–16}}\n- Sau bảo tồn: toàn vú **45–50,4 Gy/25–28 phân liều** hoặc **40–42,5 Gy/15–16** (giảm phân liều); **boost 10–16 Gy/4–8** nếu <50 tuổi, độ 3, DCIS lan rộng, xâm lấn mạch, cắt không triệt căn {{QĐ3128 tr.20}}\n- Xạ một phần vú: giai đoạn I, đơn ổ, ER+, **≥60 tuổi** {{QĐ3128 tr.20}}\n- Sau đoạn nhũ: **≥4 hạch (+)** luôn xạ; **1–3 hạch (+)** thiên về xạ; N0 mà u >5 cm hoặc diện cắt (+) bất khả kháng → xạ thành ngực {{QĐ3128 tr.21}}\n- Thành ngực 45–50,4 Gy (boost sẹo mổ tổng ~60 Gy); hạch vùng 45–50,4 Gy; 5 ngày/tuần. Kế hoạch dựa CT; ưu tiên IMRT/VMAT {{QĐ3128 tr.21}}\n- Sau tân bổ trợ: xạ theo **giai đoạn cao nhất** (trước điều trị, sau điều trị, mô bệnh học) {{QĐ3128 tr.21}}\n- **Chống chỉ định khi mang thai** {{QĐ3128 tr.21}}\n- Biến chứng (slide): phù/đỏ da, đau vú 5–10%, viêm phổi/màng tim/gãy sườn <1% {{SY5 tr.286}}\n@@tab Nội tiết\n- Chỉ định: ER dương **hoặc không rõ**; không lợi ích rõ khi ER âm {{QĐ3128 tr.21}} {{QĐ3128 tr.17}}\n- **Chưa mãn kinh**: nguy cơ cao (<35 tuổi): ức chế/cắt buồng trứng + tamoxifen hoặc **AI**; nguy cơ thấp: tamoxifen đơn thuần; sau 5 năm tiếp tamoxifen đến 10 năm hoặc đổi AI nếu mãn kinh {{QĐ3128 tr.21}}\n- **Mãn kinh**: AI 5 năm (có thể thêm 5 năm) hoặc đổi AI↔tamoxifen đủ 5 năm; không dùng AI được thì tamoxifen 5–10 năm {{QĐ3128 tr.22}}\n- **AI đơn thuần vô tác dụng nếu chưa mãn kinh** (không dựa mất kinh sau hóa trị) {{QĐ3128 tr.22}}\n- Nam ER+: tamoxifen (hoặc GnRH + AI); **thai kỳ: chống chỉ định** {{QĐ3128 tr.22}}\n- Tác dụng phụ: tamoxifen → ung thư nội mạc tử cung, huyết khối; AI → loãng xương {{Y5 tr.20}}\n@@tab Hóa trị – Đích – Miễn dịch\n- **Hóa trị**: cho đa số bệnh nhân; hiệu quả cao về sống thêm {{QĐ3128 tr.16}}\n- **Đích** (kháng thể đơn dòng): trastuzumab, pertuzumab, T-DM1; TKI lapatinib; ức chế CDK4/6, mTOR, PI3K, PARP {{QĐ3128 tr.16}} {{QĐ3128 tr.23–24}}\n- **Miễn dịch**: atezolizumab (tam âm PD-L1 ≥1%) {{QĐ3128 tr.24}}\n- **Thuốc tái tạo xương** (di căn xương): zoledronic acid, pamidronate, clodronate, kháng thể ức chế RANK; **bổ trợ**: zoledronic/clodronate ở mãn kinh hoặc đã ức chế buồng trứng {{QĐ3128 tr.22}} {{QĐ3128 tr.25}}\n- Cắt buồng trứng (mổ hoặc xạ) là một dạng nội tiết ở ER+ chưa mãn kinh {{QĐ3128 tr.26}}\n@@end\n\n#### Theo giai đoạn\n@@tabs\n@@tab Giai đoạn 0\n- DCIS: **cắt rộng u** (bờ âm tính ≥**2 mm**), chụp phim bệnh phẩm; không cần vét nách (SLNB chỉ khi nghi xâm nhập) {{QĐ3128 tr.16–17}}\n- Chống chỉ định bảo tồn/u lan rộng (≥2 góc phần tư) → cắt tuyến vú ± tái tạo {{QĐ3128 tr.16}}\n- **Xạ toàn vú** ± boost nếu nguy cơ cao (sờ thấy, lớn, độ cao, diện cắt sát, <50 tuổi); xạ một phần: sàng lọc, độ thấp/trung bình, ≤2,5 cm, bờ >3 mm; nguy cơ rất thấp có thể bỏ xạ {{QĐ3128 tr.17}}\n- Nội tiết **5 năm** nếu ER+ (tamoxifen; AI nếu mãn kinh) {{QĐ3128 tr.17}} {{QĐ3128 tr.42}}\n@@tab I, II, T3N1M0\n- Mổ: bảo tồn + vét hạch/SLNB, hoặc cắt tuyến vú triệt căn biến đổi/tiết kiệm da/bảo tồn núm {{QĐ3128 tr.17}} {{QĐ3128 tr.30}}\n- **Tân bổ trợ** khi T2–T3 đủ tiêu chuẩn bảo tồn trừ u lớn: hóa trị như bổ trợ; clip ranh giới u; đáp ứng → bảo tồn; không đáp ứng/tiến triển → cắt tuyến vú + vét nách {{QĐ3128 tr.18}} {{QĐ3128 tr.36}}\n- HER2 (+): hóa trị + **trastuzumab** trước mổ (+ **pertuzumab** nếu u >2 cm hoặc hạch +); **không dùng đồng thời kháng HER2 với anthracycline** {{QĐ3128 tr.18}}\n- Nội tiết tân bổ trợ đơn thuần: số ít không hóa trị được, luminal nguy cơ thấp {{QĐ3128 tr.18}}\n- Bổ trợ: xem bảng theo thể bệnh bên dưới; xạ theo hạch như trên; nội tiết nếu ER+ {{QĐ3128 tr.19–22}}\n@@tab III (trừ T3N1M0), thể viêm\n- Hầu hết không mổ được → **hóa trị tân bổ trợ**; HER2+ thêm trastuzumab ± pertuzumab; sau đó cắt tuyến vú triệt căn + vét nách, hoặc bảo tồn (**trừ thể viêm**) {{QĐ3128 tr.22}}\n- Sau mổ: **xạ** thành ngực/vú + hạch vùng gồm thượng đòn (± vú trong); nội tiết nếu ER+/không rõ {{QĐ3128 tr.22–23}}\n- Còn bệnh sau tân bổ trợ: **tam âm** → cân nhắc capecitabine 6–8 đợt; **HER2+** → **T-DM1 14 đợt** (không dung nạp → trastuzumab ± pertuzumab đủ 1 năm); không còn bệnh → trastuzumab đủ 1 năm {{QĐ3128 tr.20}} {{QĐ3128 tr.23}}\n- Không mổ được: đổi hóa trị hoặc xạ **50 Gy** + boost 10–26 Gy; tiến triển khi hóa trị → mổ sạch {{QĐ3128 tr.23}}\n@@tab IV / di căn\n- **ER+, HER2–, tiến chậm, không di căn tạng đe dọa** → ưu tiên **nội tiết** (mãn kinh: AI; chưa mãn kinh: ức chế/cắt buồng trứng + thuốc như mãn kinh); thêm **CDK4/6 (ribociclib)**, mTOR (everolimus), fulvestrant; **PIK3CA đột biến + thất bại AI → alpelisib + fulvestrant** {{QĐ3128 tr.23–24}}\n- **ER–, hoặc ER+ nhưng di căn tạng có triệu chứng/tiến nhanh/kháng nội tiết** → **hóa trị**; ưu tiên **đơn chất tuần tự**; đa thuốc khi cần đáp ứng nhanh; metronomic nếu không cần nhanh {{QĐ3128 tr.24}}\n- **HER2+**: hóa trị + trastuzumab (± pertuzumab), T-DM1, lapatinib; không điều kiện kháng HER2 → như HER2– {{QĐ3128 tr.24}} {{QĐ3128 tr.56}}\n- **BRCA1/2 dòng mầm**: ưu tiên **PARP** (olaparib, talazoparib); tam âm: platin; **tam âm PD-L1 (+)**: atezolizumab + nab-paclitaxel {{QĐ3128 tr.24}}\n- Không dùng nội tiết đồng thời với hóa trị ngoài thử nghiệm {{QĐ3128 tr.24}}\n- Liên tục đến khi tiến triển/độc tính không chấp nhận; ECOG 3 hoặc nhiều phác đồ thất bại → chăm sóc hỗ trợ {{QĐ3128 tr.24}} {{QĐ3128 tr.39}}\n- **Di căn xương**: thêm bisphosphonate/ức chế RANK; gãy xương dài/nguy cơ: cố định rồi xạ; **chèn ép tủy: cấp cứu**, mổ giải ép hoặc xạ cấp cứu {{QĐ3128 tr.25}}\n- Di căn não đơn ổ/nhỏ: mổ hoặc xạ phẫu (Gamma, Cyber); tràn dịch màng phổi: chọc tháo, talc/bleomycin; mổ u nguyên phát chọn lọc (nhất là chỉ di căn xương) {{QĐ3128 tr.25}}\n@@tab Tái phát\n- Thành ngực sau đoạn nhũ: cắt u + xạ (nếu chưa xạ/an toàn); sau bảo tồn: **cắt tuyến vú**; chưa vét nách thì vét {{QĐ3128 tr.25}}\n- Hạch nách: vét/lấy hạch + xạ; hạch thượng đòn/vú trong: xạ; sau điều trị tại chỗ cân nhắc toàn thân {{QĐ3128 tr.26}}\n- Tái phát xa: như giai đoạn IV, **xem lại thuốc đã dùng** {{QĐ3128 tr.26}}\n@@end\n\n#### Chỉ định hệ thống bổ trợ theo thể bệnh (St. Gallen 2015)\n| Thể | Điều trị đề nghị | Ghi chú |\n|---|---|---|\n| Luminal A | **Nội tiết đơn thuần** đa số | cân nhắc hóa trị nếu ≥4 hạch (+), ≥T3, độ 3 |\n| Luminal B – HER2 (–) | Nội tiết + hóa trị đa số | hạch (–), u ≤0,5 cm: có thể không hóa trị; u >0,5 cm: xét gen |\n| Luminal B – HER2 (+) | Hóa trị + kháng HER2 + nội tiết | chống chỉ định hóa trị: nội tiết + kháng HER2 |\n| HER2 (+) không luminal | Hóa trị + kháng HER2 | u >1 cm bắt buộc; ≤pT1bN0 cân nhắc |\n| Tam âm | Hóa trị | lợi từ pT1bN0 |\n{{QĐ3128 tr.19}}\n- Trastuzumab chuẩn **1 năm** (nguy cơ thấp/hạn chế kinh tế: tối thiểu **9 tuần**); hạch (+): cân nhắc thêm pertuzumab {{QĐ3128 tr.19–20}}\n- Thể ít gặp: ống nhỏ, nhú, nhầy → chỉ nội tiết (hạch + cân nhắc hóa trị); tủy, dị sản → hóa trị; thiếu niên chế tiết, tuyến nang, tiết rụng đầu → không cần hệ thống nếu không nguy cơ cao {{QĐ3128 tr.20}}\n- Nguy cơ tái phát thấp: AC hoặc TC **4 chu kỳ** {{QĐ3128 tr.20}}\n\n> [!ext] Bổ sung ngoài BYT (diễn đạt lại): xu hướng hiện nay dùng xét nghiệm gen (Oncotype Dx, MammaPrint) để tránh hóa trị thừa ở luminal hạch (–); ức chế CDK4/6 (ribociclib, palbociclib, abemaciclib) là chuẩn bậc 1 ở ER+/HER2– di căn. Nguồn: NCI PDQ, ESMO/ASCO; không phải văn bản BYT. {{+NCI PDQ}}\n\n### 7.3 Phác đồ – Y lệnh\n\n> [!doc] QĐ 3128/QĐ-BYT ngày 17/7/2020 – mục 7 \"Các phác đồ, liệu trình điều trị nội khoa UTV\" (tr. PDF 42–56). Chép đúng nguồn; **chu kỳ ghi theo ngày; truyền tĩnh mạch (TM) trừ khi ghi khác**. {{QĐ3128 tr.42–56}}\n\n@@tabs\n@@tab Nội tiết bổ trợ\n| Phác đồ | Thuốc – thời gian | Đối tượng | Ghi chú |\n|---|---|---|---|\n| DCIS | Tamoxifen **5 năm** (chưa/đã mãn kinh); **AI 5 năm** (đã mãn kinh) | ER+ | {{QĐ3128 tr.42}} |\n| Xâm nhập, **chưa mãn kinh** | Tamoxifen 5–10 năm ± cắt/ức chế buồng trứng (GnRH) | | {{QĐ3128 tr.42}} |\n| | Tamoxifen 5 năm ± ức chế BT → nếu mãn kinh thêm AI 5 năm | | |\n| | **AI 5 năm + cắt/ức chế buồng trứng** đồng thời | | |\n| Xâm nhập, **đã mãn kinh** | AI 5–10 năm | | {{QĐ3128 tr.42}} |\n| | AI 2–3 năm → tamoxifen đến đủ 5 năm | | |\n| | Tamoxifen 2–3 năm → AI đến đủ 5 năm (hoặc +5 năm AI) | | |\n| | Tamoxifen 4,5–6 năm → AI 5 năm (hoặc tamoxifen đủ 10 năm) | | |\n| Chống chỉ định/không dung nạp AI | Tamoxifen 5–10 năm | | |\n@@tab Hóa trị bổ trợ HER2 (–)\n| Phác đồ | Thuốc – liều | Chu kỳ | Ghi chú |\n|---|---|---|---|\n| **4AC → 4P liều dày** (ưu tiên) | Doxorubicin **60 mg/m²** + Cyclophosphamide **600 mg/m²** ngày 1; sau đó Paclitaxel **175 mg/m²** (3 giờ) | 14 ngày × 4 + 14 ngày × 4 | **G-CSF dự phòng nguyên phát** {{QĐ3128 tr.42}} |\n| **4AC liều dày → 12 tuần P** (ưu tiên) | AC như trên; Paclitaxel **80 mg/m²/tuần** (1 giờ) | 14 ngày × 4; P hàng tuần × 12 | G-CSF {{QĐ3128 tr.43}} |\n| **4AC → 4P 3 tuần** (ưu tiên) | AC như trên; Paclitaxel 175 mg/m² | 21 ngày × 4 + 21 ngày × 4 | {{QĐ3128 tr.43}} |\n| **TC** (ưu tiên) | Docetaxel **75 mg/m²** + Cyclophosphamide **600 mg/m²** ngày 1 | 21 ngày × 4 | G-CSF {{QĐ3128 tr.43}} |\n| AC 3 tuần | A 60 + C 600 mg/m² | 21 ngày × 4–6 | {{QĐ3128 tr.43}} |\n| AC 2 tuần | A 60 + C (nguồn ghi \"60\" mg/m², nghi lỗi, các phác đồ khác là 600) | 14 ngày × 4–6 | G-CSF |\n| 4AC → 4D | AC (14 hoặc 21 ngày × 4) → Docetaxel **100 mg/m²** | 21 ngày × 4 | {{QĐ3128 tr.43}} |\n| 4AC (21 ngày) → 12 tuần P | AC; P 80 mg/m²/tuần | 21 ngày × 4; P × 12 | {{QĐ3128 tr.43–44}} |\n| **EC** | Epirubicin **100** + Cyclophosphamide **830 mg/m²** | 21 ngày × 8 | {{QĐ3128 tr.44}} |\n| 4EC → 4D | Epirubicin 90 + C 600; sau Docetaxel 100 mg/m² | 21 ngày × 4 + × 4 | {{QĐ3128 tr.44}} |\n| **FAC** | 5-FU 500 (ngày 1,4 hoặc 1,8) + Doxorubicin 50 + C 500 | 21 ngày × 6 | {{QĐ3128 tr.44}} |\n| 4FAC → 4P / 12 tuần P | FAC (5-FU 500, A 50, C 500) × 4; P 225 mg/m² × 4, hoặc P 80 mg/m²/tuần × 12 | 21 ngày | {{QĐ3128 tr.44}} |\n| **FEC** | 5-FU 600 + Epirubicin 90 + C 600 | 21 ngày | {{QĐ3128 tr.44–45}} |\n| 3FEC → 3D | FEC (5-FU 500, E 100, C 500) × 3; Docetaxel 100 × 3 | 21 ngày | {{QĐ3128 tr.45}} |\n| 4FEC → 4P / 8 tuần P | FEC × 4; P 225 mg/m² × 4 hoặc P 100 mg/m² hàng tuần × 8 | 21 ngày / 7 ngày | {{QĐ3128 tr.45}} |\n| **TAC** | Docetaxel 75 + Doxorubicin 50 + C 500 mg/m² | 21 ngày × 6 | G-CSF {{QĐ3128 tr.45}} |\n| CAF | C 600 + A 60 + 5-FU 600 | 28 ngày × 4 | {{QĐ3128 tr.45–46}} |\n| **CMF** (<60 tuổi) | C **100 mg/m² uống ngày 1–14**; MTX 40 + 5-FU 600 mg/m² TM ngày 1, 8 | 28 ngày × 6 | {{QĐ3128 tr.46}} |\n| CMF (>60 tuổi) | C 100 uống ngày 1–14; MTX 30 + 5-FU 400 ngày 1, 8 | 28 ngày × 6 | {{QĐ3128 tr.46}} |\n| Paclitaxel + carboplatin tuần | P 80 mg/m² ngày 1,8,15 + Carboplatin **AUC 6** ngày 1 | 21 ngày × 4 | {{QĐ3128 tr.46}} |\n| Docetaxel + carboplatin | D 75 + Carbo AUC 6 ngày 1 | 21 ngày × 4–6 | {{QĐ3128 tr.46}} |\n| Paclitaxel đơn | 80 mg/m² mỗi tuần | × 12 tuần | {{QĐ3128 tr.46}} |\n| **Bệnh còn sau tân bổ trợ (tam âm)** | **Capecitabine 2.000–2.500 mg/m² uống ngày 1–14** | 21 ngày × 6–8 | sau anthracycline, taxane, alkyl hóa {{QĐ3128 tr.46}} |\n@@tab HER2 (+) bổ trợ/tân bổ trợ\n| Thuốc | Liều | Chu kỳ | Ghi chú |\n|---|---|---|---|\n| **Trastuzumab hàng tuần** | tải **4 mg/kg** (90 phút) rồi **2 mg/kg** (30 phút) | hàng tuần đủ **1 năm** | {{QĐ3128 tr.47}} |\n| **Trastuzumab 3 tuần** | tải **8 mg/kg** (90 phút) rồi **6 mg/kg** | 21 ngày đủ 1 năm | {{QĐ3128 tr.47}} |\n| **Trastuzumab tiêm dưới da** | cố định **600 mg**, không liều tải, 2–5 phút | 21 ngày | {{QĐ3128 tr.47}} |\n| **Pertuzumab** | khởi đầu **840 mg** (60 phút), sau **420 mg** (30–60 phút) | 21 ngày đủ 1 năm | dùng cùng trastuzumab + hóa trị {{QĐ3128 tr.47}} |\n| **T-DM1** | **3,6 mg/kg**; liều đầu 90 phút, sau 30 phút | 21 ngày × **14 chu kỳ** | còn bệnh sau tân bổ trợ {{QĐ3128 tr.48}} |\n| **TCH** (ưu tiên) | Docetaxel 75 mg/m² + Carboplatin **AUC 6** ngày 1 + Trastuzumab | 21 ngày × 6 | G-CSF; ± pertuzumab {{QĐ3128 tr.47}} |\n| 4AC → 4P (2 hoặc 3 tuần) + trastuzumab | như HER2 (–), thêm trastuzumab | | G-CSF khi liều dày {{QĐ3128 tr.47}} |\n| 4AC → 12 tuần P + trastuzumab (± pertuzumab) | | | {{QĐ3128 tr.47}} |\n| Paclitaxel + trastuzumab | | | {{QĐ3128 tr.47}} |\n| Khác | AC → docetaxel + trastuzumab (± pertuzumab); 4FAC/3FEC/4FEC/4EC kèm trastuzumab; docetaxel/cyclophosphamide/trastuzumab (G-CSF) | | {{QĐ3128 tr.47–48}} |\n@@tab Nội tiết/đích di căn\n| Nhóm | Phác đồ | Ghi chú |\n|---|---|---|\n| ER+/HER2–, **chưa mãn kinh** | Cắt/ức chế buồng trứng (GnRH) + thuốc nội tiết ± ribociclib hoặc everolimus; nếu >1 năm chưa nội tiết: hoặc tamoxifen | {{QĐ3128 tr.48}} |\n| **Ribociclib** | **600 mg/ngày × 3 tuần, nghỉ 1 tuần**, đến khi tiến triển | {{QĐ3128 tr.48}} |\n| ER+/HER2–, **mãn kinh** (ưu tiên) | AI + ribociclib; fulvestrant + ribociclib; **fulvestrant + alpelisib (PIK3CA)**; fulvestrant; AI không steroid (anastrozole, letrozole); tamoxifen; AI steroid (exemestane) | {{QĐ3128 tr.48–49}} |\n| Kết hợp khác | exemestane + everolimus; fulvestrant + everolimus; fulvestrant + anastrozole; tamoxifen + everolimus; ethinyl estradiol | {{QĐ3128 tr.49}} |\n| ER+/HER2+ | nội tiết + kháng HER2 (AI + trastuzumab/lapatinib; fulvestrant + trastuzumab; tamoxifen + trastuzumab) hoặc nội tiết đơn thuần | {{QĐ3128 tr.49}} |\n@@tab Hóa trị di căn HER2 (–)\n| Nhóm | Thuốc – liều | Chu kỳ | Ghi chú |\n|---|---|---|---|\n| Doxorubicin | 60–75 mg/m² ngày 1; hoặc 20 mg/m² hàng tuần; liposomal 50 mg/m² | 21 / 7 / 28 ngày | {{QĐ3128 tr.49}} |\n| Paclitaxel | 175 mg/m² (21 ngày) hoặc 80 mg/m² (7 ngày) | | {{QĐ3128 tr.49}} |\n| Capecitabine | **1.000–1.250 mg/m² uống 2 lần/ngày, ngày 1–14** | 21 ngày | {{QĐ3128 tr.49}} |\n| Gemcitabine | 800–1.200 mg/m² ngày 1, 8, 15 | 28 ngày | {{QĐ3128 tr.50}} |\n| Vinorelbine | 25 mg/m² TM hàng tuần; uống 80 mg/m² (đầu 60) ngày 1 (hoặc 1, 8); metronomic 30–50 mg/ngày ngày 1,3,5 | | {{QĐ3128 tr.50}} |\n| Eribulin | **1,4 mg/m²** ngày 1, 8 | 21 ngày | {{QĐ3128 tr.50}} |\n| **PARP** (BRCA dòng mầm, HER2–) | **Olaparib 300 mg uống 2 lần/ngày**; **Talazoparib 1 mg/ngày** | liên tục | {{QĐ3128 tr.50}} |\n| **Platin** (tam âm, BRCA) | Carboplatin AUC 6 (21–28 ngày); Cisplatin 75 mg/m² (21 ngày) | | {{QĐ3128 tr.50}} |\n| Khác đơn chất | Cyclophosphamide 50 mg uống ngày 1–21; Docetaxel 60–100 mg/m²; Epirubicin 60–90; Etoposide 50 mg uống ngày 1–21; mitoxantron | | {{QĐ3128 tr.50}} |\n| Kết hợp | TA, AT (A 50 + D 75, ≤8 chu kỳ), AC, EC (75/600), CAF, CEF, FAC, FEC, CMF, TAC, PE, gemcitabine/carboplatin (G 1000 + Carbo AUC 2 ngày 1,8), paclitaxel/carboplatin | 21–28 ngày | {{QĐ3128 tr.50–53}} |\n| Paclitaxel/bevacizumab | P 90 mg/m² ngày 1,8,15 + Bevacizumab 10 mg/kg ngày 1,15 | 28 ngày | {{QĐ3128 tr.52}} |\n| Capecitabine/docetaxel; capecitabine/vinorelbine (metronomic: vinorelbine 40 mg ngày 1,3,5 + capecitabine 500 mg × 3 lần/ngày) | | 21 ngày | {{QĐ3128 tr.53}} |\n| Gemcitabine/paclitaxel | G 1250 ngày 1,8 + P 175 | 21 ngày | {{QĐ3128 tr.53}} |\n| **Tam âm PD-L1 ≥1%, chưa hóa trị giai đoạn di căn** | **Atezolizumab 840 mg** ngày 1,15 + **Nab-paclitaxel 100 mg/m²** ngày 1,8,15 | 28 ngày | {{QĐ3128 tr.53}} |\n@@tab Hóa trị + đích di căn HER2 (+)\n| Phác đồ | Liều | Chu kỳ | Ghi chú |\n|---|---|---|---|\n| **Pertuzumab/trastuzumab/docetaxel** | Pertuzumab 840 mg rồi 420 mg; Trastuzumab 8 mg/kg rồi 6 mg/kg; Docetaxel **75–100 mg/m²** | 21 ngày | ưu tiên bậc 1 {{QĐ3128 tr.54}} |\n| Pertuzumab/trastuzumab/paclitaxel | như trên; Paclitaxel 175 (21 ngày) hoặc 80 mg/m² hàng tuần | 21 ngày | {{QĐ3128 tr.54}} |\n| Trastuzumab/docetaxel | Docetaxel 80–100 (21 ngày) hoặc 35 mg/m² hàng tuần; trastuzumab 8→6 mg/kg hoặc 4→2 mg/kg hàng tuần | | {{QĐ3128 tr.54}} |\n| Trastuzumab/vinorelbine | Vinorelbine 25 mg/m² hàng tuần hoặc 30–35 ngày 1,8 | | {{QĐ3128 tr.54}} |\n| Trastuzumab/paclitaxel; /paclitaxel/carboplatin; /capecitabine; /gemcitabine; TCH | Paclitaxel 80–90 hàng tuần; Carbo AUC 6; Capecitabine 1.000–1.250 ngày 1–14; Gemcitabine 1.200 ngày 1,8 | 21 ngày | {{QĐ3128 tr.55–56}} |\n| **Các bước sau: T-DM1** | **3,6 mg/kg** | 21 ngày | {{QĐ3128 tr.56}} |\n| **Lapatinib + capecitabine** | Lapatinib **1.250 mg/ngày** ngày 1–21 + Capecitabine 1.000–1.250 mg/m² × 2 lần, ngày 1–14 | 21 ngày | {{QĐ3128 tr.56}} |\n| Trastuzumab/lapatinib | Lapatinib **1.000 mg/ngày** + trastuzumab | | {{QĐ3128 tr.56}} |\n@@tab Thuốc xương & hỗ trợ\n- **Tái tạo xương**: zoledronic acid, pamidronate, clodronate (biphosphonat); kháng thể ức chế RANK {{QĐ3128 tr.25}} {{QĐ3128 tr.56}}\n- **G-CSF dự phòng nguyên phát** nếu phác đồ nguy cơ giảm BC hạt có sốt **10–20%** (docetaxel; FEC → docetaxel; paclitaxel 21 ngày) **và ≥1 yếu tố**: đã hóa/xạ trị trước, giảm BC hạt dai dẳng, u xâm lấn tủy, mổ/vết thương gần đây, bilirubin >34,2 µmol/L, creatinine clearance <50 mL/ph, >65 tuổi dùng liều đầy đủ {{QĐ3128 tr.26}}\n- Có nguy cơ cao hơn khi phối hợp kháng thể đơn dòng; **dự phòng thứ phát** từ chu kỳ sau nếu đã sốt giảm BC hạt {{QĐ3128 tr.26–27}}\n- Đặt buồng tiêm truyền dưới da khi khó tiếp cận TM {{QĐ3128 tr.26}}\n@@end\n\n> [!warn] Theo dõi & độc tính cần nhớ\n> - **Kháng HER2**: siêu âm tim **mỗi 3 tháng** khi đang điều trị {{QĐ3128 tr.27}}; trastuzumab độc tim ~2–3% sau 2 năm khi phối hợp anthracycline {{Y5 tr.21}}\n> - **Không dùng đồng thời kháng HER2 với anthracycline** {{QĐ3128 tr.18}}\n> - Mỗi đợt: khám, CTM, chức năng gan–thận; đánh giá tổng thể sau mỗi 3–4 đợt (bổ trợ), hình ảnh sau 2–4 đợt (di căn) {{QĐ3128 tr.27}}\n> - Hóa trị đến khi tiến triển hoặc độc tính không chấp nhận (**độc tính tích lũy tim của anthracycline**) {{QĐ3128 tr.24}}\n> - **Thai kỳ**: hóa trị chỉ từ quý II; kháng HER2, nội tiết, xạ trị chống chỉ định {{QĐ3128 tr.18}}\n> - Tamoxifen: siêu âm phụ khoa mỗi năm nếu còn tử cung; AI: theo dõi mật độ xương {{QĐ3128 tr.28}}\n> - Nguồn trích PDF có vài chỗ nghi lỗi chép (ví dụ AC 2 tuần ghi cyclophosphamide 60 mg/m²) – ghi nguyên văn, cần đối chiếu bản gốc khi dùng thực tế.\n\n## 8. Tiên lượng – Dự phòng\n\n> [!key] Tóm tắt\n> - Tiên lượng mạnh nhất: **di căn hạch**; kèm kích thước, độ mô học, ER/PR/HER2, Ki67, tuổi\n> - Tầm soát nguy cơ trung bình: **nhũ ảnh 1 năm/lần từ 40–70 tuổi**; nguy cơ cao: **từ 25 tuổi** {{QĐ3898 tr.27}}\n\n### Tiên lượng\n@@tabs\n@@tab Yếu tố tiên lượng\n| Yếu tố | Nội dung |\n|---|---|\n| Hạch | **mạnh nhất**; tái phát gấp 2,5 lần, tử vong 2–3,3 lần; càng nhiều hạch càng xấu {{Y5 tr.17}} |\n| Kích thước u | tăng theo kích thước {{Y5 tr.17}} |\n| Tuổi | xấu khi <35 và >70 {{Y5 tr.17}} |\n| Thể mô học | tiểu thùy, nhú, ống nhỏ, nhầy, tủy tốt hơn; thể viêm xấu {{Y5 tr.17}} |\n| Độ mô học | quan trọng sau hạch và kích thước {{Y5 tr.18}} |\n| ER/PR | dương tiên lượng tốt hơn (đáp ứng nội tiết); âm: đáp ứng hóa trị tốt {{Y5 tr.18}} |\n| HER2 | quá mức: xấu, nhưng dự đoán đáp ứng trastuzumab/anthracycline {{Y5 tr.18}} |\n| Ki67 | yếu tố độc lập; cao dễ tái phát, đáp ứng hóa trị {{Y5 tr.18}} |\n| Xâm nhập mạch bạch huyết | xấu {{Y5 tr.18}} |\n{{QĐ3128 tr.6}} (QĐ3128 liệt kê: kích thước u, số hạch, thể mô học, độ mô học, ER/PR, HER2, tuổi)\n@@tab Sống 5 năm theo giai đoạn\n| Giai đoạn | Mỹ 2001–2002 | Mỹ 2012 |\n|---|---|---|\n| 0 | 100% | 100% (0 và I) |\n| I | 88% | 100% |\n| II | 74–81% | 93% |\n| III | 41–67% | 72% |\n| IV | 15% | 22% |\n{{QĐ3128 tr.6}}\n- 128VĐ: UTV giai đoạn sớm sống 5 năm **>90%** nếu phát hiện và điều trị kịp thời {{128VĐ mục 126}}\n- Nhóm sinh học: luminal di căn muộn, giống đáy trong ~2 năm {{Y5 tr.5}}\n@@end\n\n### Theo dõi sau điều trị (QĐ 3128)\n| Giai đoạn | Lịch |\n|---|---|\n| 0 – LCIS | khám 6–12 tháng/lần; nhũ ảnh hằng năm {{QĐ3128 tr.27}} |\n| 0 – DCIS | khám 6–12 tháng × 5 năm, sau đó mỗi năm; nhũ ảnh lần đầu 6–12 tháng rồi hằng năm {{QĐ3128 tr.27}} |\n| I–III | **3–4 tháng/lần × 2 năm đầu**, **6 tháng/lần năm 3–5**, sau đó **1 năm/lần**; nhũ ảnh + siêu âm vú hằng năm (bên bệnh nếu bảo tồn, và vú đối bên) {{QĐ3128 tr.27–28}} |\n| IV / tái phát ổn định | khám 1–3 tháng/lần {{QĐ3128 tr.28}} |\n- Tamoxifen: siêu âm phụ khoa hằng năm; AI hoặc mất kinh sau hóa trị: **mật độ xương** {{QĐ3128 tr.28}}\n- Khác tùy trường hợp: CA15-3, CEA, lipid máu, siêu âm bụng, X-quang ngực, CT/MRI, xạ hình xương, PET/CT {{QĐ3128 tr.28}}\n> [!ext] Y5: CA15-3 không dùng theo dõi sau điều trị giai đoạn sớm {{Y5 tr.14}}, trong khi QĐ3128 liệt kê CA15-3 trong xét nghiệm \"tùy trường hợp\" sau điều trị I–III {{QĐ3128 tr.28}} – ưu tiên BYT, nhưng không làm thường quy.\n\n### Dự phòng\n@@tabs\n@@tab Cấp 1 (phòng bệnh)\n- Hạn chế rượu, thuốc lá; **nuôi con bằng sữa mẹ**; tránh béo phì, ăn cân bằng, vận động; hạn chế nội tiết thay thế (estrogen + progesterone); tránh sinh con đầu muộn {{QĐ3898 tr.16}}\n- **Tamoxifen** (chưa/đã mãn kinh) hoặc **AI** (mãn kinh) giảm nguy cơ, nhưng tamoxifen có nguy cơ ung thư nội mạc tử cung, huyết khối → lợi ích chưa vượt trội ở người khỏe mạnh {{QĐ3898 tr.16}}\n- **Cắt tuyến vú dự phòng**: người nguy cơ cao (BRCA1/2), cần tư vấn kỹ {{QĐ3898 tr.16}}\n- Truyền thông giáo dục về tự khám và tầm soát định kỳ {{QĐ3898 tr.16}}\n@@tab Cấp 2 (sàng lọc)\n**Phân nhóm nguy cơ** (mọi lần khám): {{QĐ3898 tr.15}}\n- **Nguy cơ cao** (một trong): người thân bậc 1 mắc UTV; đột biến BRCA1/2, PTEN, TP53, CDH1, PALB2, STK11; tiền sử UTV; LCIS hoặc quá sản không điển hình; **xạ trị ngực lúc 10–30 tuổi**; (mô hình Gail 5 năm ≥1,7% hoặc suốt đời ≥20%)\n- **Nguy cơ trung bình**: không có yếu tố nào ở trên\n\n| Đối tượng | Lịch sàng lọc |\n|---|---|\n| **TB, 25–39 tuổi** | **tự khám hằng tháng** + khám lâm sàng **1–3 năm/lần** |\n| **TB, 40–70 tuổi** | **mỗi năm**: khám lâm sàng + **nhũ ảnh**; thêm **siêu âm** nếu mô vú đặc (C/D) {{QĐ3898 tr.27}} |\n| **TB, >70 tuổi** | dừng khi tuổi thọ kỳ vọng <10 năm hoặc không đủ khả năng điều trị |\n| **Cao – tiền sử xạ ngực 10–30 tuổi** | bắt đầu **8 năm sau xạ**, không trước **25 tuổi**: khám 6–12 tháng, nhũ ảnh + **MRI** hằng năm {{QĐ3898 tr.28}} |\n| **Cao – tiền sử cá nhân/gia đình, gen** | khám 6–12 tháng; nhũ ảnh hằng năm từ **10 năm trước tuổi mắc của người thân trẻ nhất**, không trước 30, chậm nhất 40; MRI từ cùng mốc, không trước **25**; tư vấn di truyền, giảm nguy cơ {{QĐ3898 tr.28}} |\n| **LCIS / quá sản không điển hình** | khám 6–12 tháng; nhũ ảnh từ lúc chẩn đoán (≥30 tuổi); cân nhắc MRI (≥25 tuổi) |\n- Ví dụ: người thân mắc năm 35 → nhũ ảnh từ 30; mắc năm 55 → từ 40 {{QĐ3898 tr.21}}\n- **Tự khám vú**: hằng tháng, **5 ngày sau sạch kinh**, từ **25 tuổi**; **không thay thế** sàng lọc {{QĐ3898 tr.17}}\n- Khám lâm sàng: do bác sĩ được đào tạo, tuần đầu sau sạch kinh {{QĐ3898 tr.19}}\n- **CA15-3, CEA không có giá trị sàng lọc** {{QĐ3898 tr.17}}\n- Cơ sở thiếu phương tiện: siêu âm + khám lâm sàng, hoặc khám + X-quang/MRI; có tổn thương nghi ngờ → chuyển chuyên khoa {{QĐ3898 tr.17}}\n@@tab Tình huống khi sàng lọc\n| Tình huống | Xử trí chính |\n|---|---|\n| Có thai, nguy cơ TB ≥40 | khám vú + **siêu âm**; X-quang không chống chỉ định nhưng có thể hoãn ngắn; MRI **không cản từ** {{QĐ3898 tr.40}} |\n| Cho con bú | nguy cơ cao: khám + X-quang ± siêu âm/MRI; **MRI có cản từ được** (ít vào sữa) {{QĐ3898 tr.40}} |\n| **Núm vú tụt** mới xuất hiện | khám, tìm u dưới núm, dịch, viêm; <30 siêu âm; ≥30 X-quang + siêu âm; BI-RADS 4–5 sinh thiết {{QĐ3898 tr.31}} |\n| **Chảy dịch núm vú** | dịch sữa hai bên → thai/prolactin/thuốc; **một bên, tự chảy, một ống, trong/máu** → hình ảnh, mổ cắt ống nếu nghi {{QĐ3898 tr.32}} |\n| **Thay đổi da** (da cam, đỏ, trầy núm, chàm) | X-quang ± siêu âm; sinh thiết ± da/núm; có thể thử kháng sinh 7–10 ngày hoặc corticoid thử 1–4 tuần nếu ít nghi {{QĐ3898 tr.33}} |\n| **Đau vú** | theo chu kỳ, lan tỏa: trấn an; khu trú: siêu âm (<30) hoặc X-quang + siêu âm (≥30) {{QĐ3898 tr.34}} |\n| **Khối ở nách** | nghi bệnh lý: X-quang vú + siêu âm vú, sinh thiết, MRI nếu ác tính chưa thấy nguồn {{QĐ3898 tr.35}} |\n| **Nam giới** triệu chứng ở vú | vú to hai bên: theo nguyên nhân; bất đối xứng/chảy máu: X-quang ± siêu âm → sinh thiết nếu BI-RADS 4–5 {{QĐ3898 tr.36}} |\n| Sau sinh thiết | lành tính + phù hợp: sàng lọc theo lịch; ADH/LCIS/không phù hợp: **cắt phẫu thuật** {{QĐ3898 tr.37}} |\n@@end\n\n> [!ext] Mục tiêu WHO Sáng kiến toàn cầu về UTV 2022: giảm tử vong 2,5%/năm; **60%** ca xâm lấn chẩn đoán giai đoạn I/II; xác định chẩn đoán **trong 60 ngày**; **80%** điều trị đa mô thức {{QĐ3898 tr.8}}. Về lịch sàng lọc, Y5/slide không nêu; 128VĐ: nhũ ảnh giảm 30–40% tử vong ở 40–69 tuổi {{128VĐ mục 126}}.\n\n### Dự phòng cấp 3\n- Tái tạo vú, điều trị biến chứng (phù bạch mạch sau vét nách), chăm sóc giảm nhẹ giai đoạn muộn; xử trí di căn xương/não/tủy {{QĐ3128 tr.25}}\n\n## 9. Tóm tắt cốt lõi (Pareto 80/20)\n\n> [!key] Bệnh này thi nhấn mạnh gì (nhóm tầm soát)\n> - **Chẩn đoán nặng nhất**: u vú + nhũ ảnh/BI-RADS + **mô bệnh học** (kim lõi) + ER/PR/HER2/Ki67 + TNM; khung [STT 85](#/khung/85) gồm khối ở vú và tầm soát\n> - **Sàng lọc/phát hiện sớm** theo QĐ3898: tuổi bắt đầu, chu kỳ, phương tiện cho nguy cơ trung bình và nguy cơ cao {{QĐ3898 tr.27–28}}\n> - **Xử trí** theo giai đoạn + nhóm sinh học: mổ/bảo tồn, xạ, nội tiết, kháng HER2, hóa trị tân bổ trợ {{QĐ3128 tr.15}}\n> - Câu hỏi tình huống: \"gặp cục ở vú / BI-RADS X / phụ nữ nguy cơ cao thì làm gì\"\n\n@@tabs\n@@tab Nhận diện\n- Nguy cơ then chốt: **estrogen kéo dài** (có kinh sớm, mãn kinh muộn, không con/sinh muộn, không cho bú), mô vú đặc, tiền sử gia đình ==gấp 2–3 lần== {{QĐ3898 tr.11}} {{QĐ3898 tr.13}}\n- Di truyền: **BRCA1 ==55–72%==, BRCA2 ==45–69%==**; xạ ngực lúc 10–30 tuổi gấp ~12 lần {{QĐ3898 tr.11}} {{QĐ3898 tr.14}}\n- Gợi ý: **cục ở vú không đau**; tiết dịch núm vú; da cam, co kéo, tụt núm {{SY5 tr.235}} {{QĐ3128 tr.6}}\n- {r|Báo động}: u chắc, ranh giới không rõ, dính da; hạch nách/thượng đòn cứng; **chảy dịch máu núm vú** {{QĐ3898 tr.29}}\n- {r|Thể viêm}: đỏ lan rộng **không đau, không nóng** (khác viêm vú/áp xe) {{QĐ3898 tr.20}}\n- Di căn xa: đau xương, khó thở, đau đầu {{QĐ3128 tr.7}}\n- Khám: 4 ngón tay, tuần đầu sau sạch kinh; khám cả hạch nách + thượng đòn {{QĐ3898 tr.19–21}}\n[Xem mục 4](#/n/ung-thu-vu/4) · [mục 3](#/n/ung-thu-vu/3)\n@@tab Chẩn đoán\n- **Bộ ba**: lâm sàng – hình ảnh – mô/tế bào học; xác định = **mô bệnh học có tế bào biểu mô ác tính** {{QĐ3128 tr.11}} {{Y5 tr.11}}\n- Hình ảnh: **nhũ ảnh 2 tư thế (CC, MLO)**; siêu âm cho trẻ/mô đặc/nang; MRI cho nguy cơ cao, đa ổ, trước bảo tồn {{QĐ3128 tr.7}}\n- {g|BI-RADS 3: theo dõi 6 tháng; 4–5: sinh thiết}; 0 = chụp thêm; 6 = đã ung thư {{QĐ3898 tr.23}}\n- {g|Ưu tiên kim lõi}: FNA không phân biệt xâm nhập/tại chỗ; kim lõi cho ER/PR/HER2/Ki67 {{QĐ3128 tr.8}}\n- Nhóm sinh học: luminal A/B, HER2, **tam âm**; ER/PR dương khi ≥1%; HER2 2+ → ISH {{Y5 tr.12–13}}\n- TNM AJCC 8: T1 ≤20, T2 >20–50, T3 >50 mm; **T4d = thể viêm**; N3c = thượng đòn {{QĐ3128 tr.12–13}}\n- CĐPB khối vú: u xơ tuyến, nang, nang sữa, áp xe, phyllode, hoại tử mỡ, sarcoma {{QĐ3128 tr.11}}\n- Di căn xa chỉ tìm khi giai đoạn III/IV hoặc có triệu chứng {{QĐ3128 tr.37–38}}\n[Xem mục 5](#/n/ung-thu-vu/5) · [mục 6](#/n/ung-thu-vu/6)\n@@tab Điều trị\n- **0 (DCIS)**: cắt rộng (bờ ≥2 mm) ± xạ; ER+ nội tiết **5 năm** {{QĐ3128 tr.16–17}}\n- **I, II, T3N1M0**: bảo tồn + xạ hoặc đoạn nhũ; N0 lâm sàng → **hạch cửa** (âm tính → không vét nách) {{QĐ3128 tr.17–18}}\n- **III (trừ T3N1M0), thể viêm**: {g|hóa trị tân bổ trợ} → mổ + xạ; thể viêm {r|không bảo tồn, không SLNB} {{QĐ3128 tr.22}} {{QĐ3128 tr.37}}\n- {r|CCĐ bảo tồn}: đa ổ, 6 tháng đầu thai kỳ, đã xạ ngực, diện cắt dương dai dẳng {{QĐ3128 tr.17}}\n- **Xạ**: bắt buộc sau bảo tồn; sau đoạn nhũ **≥4 hạch (+) luôn xạ** {{QĐ3128 tr.20–21}}\n- **Nội tiết** (ER+/không rõ): {p|tamoxifen} 5–10 năm; {p|AI} chỉ khi **đã mãn kinh** (hoặc kèm ức chế buồng trứng) {{QĐ3128 tr.21–22}}\n- **HER2+**: {p|trastuzumab 1 năm} (3 tuần: 8 → 6 mg/kg); {r|không dùng đồng thời anthracycline}; siêu âm tim mỗi 3 tháng {{QĐ3128 tr.47}} {{QĐ3128 tr.18}}\n- Còn bệnh sau tân bổ trợ: **tam âm** → {p|capecitabine}; **HER2+** → {p|T-DM1 14 đợt} {{QĐ3128 tr.20}}\n- **IV**: ER+/HER2– tiến chậm → nội tiết ± {p|ribociclib 600 mg} (3 tuần/nghỉ 1) {{QĐ3128 tr.48}}; ER– hoặc tạng → hóa trị; xương → bisphosphonate {{QĐ3128 tr.23–25}}\n- {r|Thai kỳ}: hóa trị chỉ từ quý II; xạ, nội tiết, kháng HER2 chống chỉ định {{QĐ3128 tr.18}}\n[Xem mục 7.2](#/n/ung-thu-vu/7) · [mục 7.3](#/n/ung-thu-vu/7)\n@@tab Tiên lượng – Dự phòng\n- Tiên lượng mạnh nhất: **di căn hạch**; thêm kích thước, độ mô học, ER/PR/HER2, Ki67, tuổi {{Y5 tr.17}}\n- Sống 5 năm (Mỹ 2012): I ==100%==, II ==93%==, III ==72%==, IV ==22%== {{QĐ3128 tr.6}}\n- **Nguy cơ TB 40–70 tuổi**: mỗi năm khám lâm sàng + **nhũ ảnh**, thêm siêu âm nếu mô đặc {{QĐ3898 tr.27}}\n- **Nguy cơ cao**: từ **25 tuổi**; xạ ngực 10–30 tuổi → bắt đầu **8 năm sau xạ**, không trước 25, nhũ ảnh + MRI {{QĐ3898 tr.28}}\n- Tự khám: hằng tháng, 5 ngày sau sạch kinh, từ 25 tuổi, {o|không thay thế sàng lọc}; CA15-3/CEA {r|không sàng lọc} {{QĐ3898 tr.17}}\n- Theo dõi I–III: 3–4 tháng × 2 năm, 6 tháng năm 3–5, rồi hằng năm; nhũ ảnh + siêu âm hằng năm {{QĐ3128 tr.27–28}}\n[Xem mục 8](#/n/ung-thu-vu/8)\n@@end\n\n### Con số và mốc phải nhớ\n| Nội dung | Giá trị | Nguồn |\n|---|---|---|\n| Ca mới / tử vong VN 2022 | ==24.563 / 10.008== | {{QĐ3898 tr.10}} |\n| Nhũ ảnh sàng lọc, nguy cơ TB | ==40–70 tuổi, mỗi năm== | {{QĐ3898 tr.27}} |\n| Nguy cơ cao bắt đầu sàng lọc | ==25 tuổi== | {{QĐ3898 tr.27–28}} |\n| Sau xạ ngực 10–30 tuổi | ==8 năm sau xạ, không trước 25 tuổi== | {{QĐ3898 tr.28}} |\n| Tự khám vú | ==hằng tháng, 5 ngày sau sạch kinh, từ 25 tuổi== | {{QĐ3898 tr.17}} |\n| BRCA1 / BRCA2 (nguy cơ đến 70–80 tuổi) | ==55–72% / 45–69%== | {{QĐ3898 tr.11}} |\n| Tiền sử gia đình bậc 1 | ==gấp 2–3 lần== | {{QĐ3898 tr.11}} |\n| BI-RADS 3 / 4–5 | ==theo dõi 6 tháng / sinh thiết== | {{QĐ3898 tr.23}} |\n| ER/PR dương | ==≥1% nhân bắt màu== | {{Y5 tr.12–13}} |\n| T1 / T2 / T3 | ==≤20 / >20–50 / >50 mm== | {{QĐ3128 tr.12}} |\n| Hạch pN1a / pN2a / pN3a | ==1–3 / 4–9 / ≥10== | {{QĐ3128 tr.13}} |\n| Xạ sau đoạn nhũ | ==≥4 hạch (+) luôn xạ== | {{QĐ3128 tr.21}} |\n| Trastuzumab | ==1 năm== (tối thiểu 9 tuần) | {{QĐ3128 tr.19–20}} |\n| T-DM1 | ==3,6 mg/kg × 14 chu kỳ== | {{QĐ3128 tr.48}} |\n| Sống 5 năm giai đoạn I / IV (Mỹ 2012) | ==100% / 22%== | {{QĐ3128 tr.6}} |\n\n> [!warn] Bẫy thi thường gặp\n> - Nguồn lệch: nguy cơ suốt đời Y5 ==12,4%== vs slide 1/8 (12,2%); BRCA đến 70 tuổi Y5 57%/40% vs QĐ3898 55–72%/45–69% {{Y5 tr.1}} {{SY5 tr.212}} {{QĐ3898 tr.11}}\n> - Ngưỡng Ki67: Y5 dùng 14%, slide dùng PR ≥20% (St. Gallen 2015) – tùy phòng xét nghiệm {{Y5 tr.13}} {{SY5 tr.266}}\n> - **T3N1M0** xếp giai đoạn IIIA nhưng điều trị theo nhóm **I, II và T3N1M0** {{QĐ3128 tr.17}}\n> - **FNA** không phân biệt tại chỗ/xâm nhập → ưu tiên kim lõi; **DCIS cần ER, không cần HER2**; **LCIS** đã loại khỏi TNM AJCC 8 {{QĐ3128 tr.9}} {{QĐ3128 tr.14}}\n> - {r|AI đơn thuần vô tác dụng nếu chưa mãn kinh}; tamoxifen → ung thư nội mạc tử cung, huyết khối {{QĐ3128 tr.22}}\n> - Thể viêm: chẩn đoán lâm sàng, {r|không bảo tồn, không SLNB}, bắt buộc xạ sau mổ; **đỏ không đau, không nóng** {{QĐ3128 tr.37}}\n> - Tự khám vú và CA15-3 **không thay thế** sàng lọc; Y5 không dùng CA15-3 theo dõi, QĐ3128 để \"tùy trường hợp\" {{Y5 tr.14}} {{QĐ3128 tr.28}}\n> - Nguồn PDF có chỗ nghi lỗi chép (AC 2 tuần ghi cyclophosphamide 60 mg/m²) – đối chiếu bản gốc\n\n@@fold Nguồn tài liệu\n- **QĐ 3128/QĐ-BYT** 17/7/2020 (`_work/qd-3128-ung-thu-vu.txt`, đọc toàn bộ; tr. = trang PDF = số in + 2; Bảng 1, 4 đối chiếu ảnh)\n- **QĐ 3898/QĐ-BYT** 18/12/2025 (`_work/qd-3898-sang-loc-ung-thu-vu.txt`, đọc toàn bộ; tr. PDF = số in + 1; ngày ký xác nhận từ ảnh trang 1)\n- Y5 tr.1–23; SY5 tr.205–297 (qua bài cũ `_old/ung-thu-vu-*`, `tc-khoi-o-vu`, `tc-tam-soat-ung-thu-vu`)\n- 128VĐ mục 89 (khối ở vú) và mục 126 (phần UTV); QĐ22 STT 85\n@@end\n\n@@fold Nguồn ngoài\n- NCI PDQ, Breast Cancer Treatment (Health Professional): https://www.cancer.gov/types/breast/hp/breast-treatment-pdq (đã đọc tóm lược mục tiêu, tân bổ trợ, nội tiết 5–10 năm, yếu tố tiên lượng)\n- StatPearls, \"Breast Cancer\" / \"Breast Mass\" (NCBI Bookshelf): https://www.ncbi.nlm.nih.gov/books/NBK482286/ (không truy cập được toàn văn khi soạn; mô tả chẩn đoán phân biệt là tổng hợp kiến thức chung, cần kiểm tra lại)\n- ACS, \"Breast cancer early detection\": https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection.html (tham khảo chung, chưa đọc lại)\n@@end\n\n@@fold Tự kiểm tra (16 thẻ)\n- Lịch sàng lọc nguy cơ trung bình 40–70 tuổi theo QĐ3898? :: Mỗi năm: khám lâm sàng + nhũ ảnh, thêm siêu âm nếu mô vú đặc\n- Phụ nữ nguy cơ cao bắt đầu sàng lọc từ tuổi nào? :: 25 tuổi, mỗi năm, khám lâm sàng + X-quang vú ± MRI\n- Tiền sử xạ trị ngực lúc 10–30 tuổi: bắt đầu nhũ ảnh/MRI khi nào? :: 8 năm sau xạ trị, không trước 25 tuổi\n- BI-RADS 3 và BI-RADS 4–5 xử trí ra sao? :: BI-RADS 3 (<2% ác tính) theo dõi 6 tháng; 4–5 sinh thiết\n- Tự khám vú khi nào và từ tuổi nào? :: Hằng tháng, 5 ngày sau sạch kinh, từ 25 tuổi (không thay thế sàng lọc)\n- Chẩn đoán xác định ung thư vú dựa vào gì? :: Mô bệnh học có tế bào biểu mô ác tính (kim lõi hoặc FNA)\n- Vì sao ưu tiên sinh thiết kim lõi hơn FNA? :: FNA không phân biệt xâm nhập/tại chỗ, cần nhà tế bào học giỏi; kim lõi còn cho ER/PR/HER2\n- Giai đoạn nào xếp T3N1M0 và điều trị theo nhóm nào? :: Giai đoạn IIIA nhưng điều trị theo nhóm \"I, II và T3N1M0\"\n- Thể phân tử St. Gallen 2015 và điều trị bổ trợ? :: Luminal A: nội tiết; Luminal B HER2–: nội tiết + hóa trị; Luminal B HER2+: hóa trị + kháng HER2 + nội tiết; HER2+ không luminal: hóa trị + kháng HER2; tam âm: hóa trị\n- Chống chỉ định tuyệt đối phẫu thuật bảo tồn vú (QĐ3128)? :: UTV đa ổ; 6 tháng đầu thai kỳ; vi canxi hóa lan tỏa; đã xạ trị ngực/vú; diện cắt dương dai dẳng\n- Chỉ định xạ trị sau cắt tuyến vú? :: ≥4 hạch (+) luôn xạ; 1–3 hạch thiên về xạ; N0 mà u >5 cm hoặc diện cắt (+) không cắt lại được\n- Liều trastuzumab 3 tuần và thời gian dùng? :: Tải 8 mg/kg rồi 6 mg/kg mỗi 21 ngày, đủ 1 năm (tối thiểu 9 tuần nếu nguy cơ thấp)\n- Phác đồ 4AC → 4P liều dày? :: Doxorubicin 60 + cyclophosphamide 600 mg/m² ngày 1, chu kỳ 14 ngày × 4; rồi paclitaxel 175 mg/m² × 4; G-CSF dự phòng\n- Ribociclib liều? :: 600 mg/ngày × 3 tuần, nghỉ 1 tuần, đến khi tiến triển (kèm AI hoặc fulvestrant)\n- Tam âm PD-L1 ≥1% di căn chưa hóa trị: phác đồ nào? :: Atezolizumab 840 mg ngày 1,15 + nab-paclitaxel 100 mg/m² ngày 1,8,15, chu kỳ 28 ngày\n- Theo dõi sau điều trị giai đoạn I–III? :: Khám 3–4 tháng/lần × 2 năm, 6 tháng/lần năm 3–5, sau đó mỗi năm; nhũ ảnh + siêu âm hằng năm\n@@end"}, {"kind": "foundation", "disease": "", "short": "", "group": "Triệu chứng và chẩn đoán chung", "section": 3, "order": 1, "khung": [], "id": "ung-thu-bay-trieu-chung", "title": "Bảy triệu chứng báo động ung thư", "layer": "trieuchung", "module": "ung-buou", "tags": ["triệu chứng báo động", "phát hiện sớm", "CAUTION", "ung thư"], "source": "SY5 tr. 65–81 (bảy triệu chứng); SY5 tr. 119, 121–122 (tình huống phát hiện bệnh)", "body": "> [!key] Tóm tắt\n> - ==7 triệu chứng báo động== theo **CAUTION** (Hội Ung thư Hoa Kỳ, ACS) {{SY5 tr.68, 121}}\n> - Là triệu chứng **thường gặp ở bệnh lành tính** nhưng cũng là **báo động ung thư** → đi khám sớm để xác định hay loại trừ {{SY5 tr.81}}\n> - Mục đích: phát hiện ung thư ở giai đoạn **còn điều trị được**, giảm tử vong {{SY5 tr.67}}\n> - Tài liệu không giải nghĩa từng chữ cái của CAUTION\n\n### Mục đích – ý nghĩa\n- {g|Phổ cập kiến thức cho người dân}; mỗi người tự cảnh giác và đến khám kịp thời {{SY5 tr.67}}\n- Triệu chứng đến khám **điển hình** của ung thư chính là 7 triệu chứng này {{SY5 tr.121}}\n\n### Bảy triệu chứng và ung thư cần nghĩ tới\n| # | Triệu chứng | Biểu hiện / vị trí | Nghĩ tới |\n|---|---|---|---|\n| 1 | **Thay đổi thói quen ruột, bàng quang** | Ruột: táo bón hoặc tiêu chảy kéo dài, xen kẽ, mót rặn kéo dài, **máu lẫn trong phân**. Bàng quang: tiểu khó, buốt, gắt, không hết, **tiểu ra máu** | Đại tràng; tuyến tiền liệt; bàng quang (đái xẹp không hoàn toàn) |\n| 2 | **Vết loét không lành** | Da: mặt, thân, tay chân, núm vú, hậu môn sinh dục, **sẹo phỏng cũ**. Niêm mạc: hốc miệng (môi, lưỡi, má, sàn miệng, vòm khẩu cái, amiđan), kết mạc mắt, sinh dục | Ung thư lưỡi, da mặt, da trên sẹo cũ |\n| 3 | **Chảy máu / tiết dịch bất thường** | Âm đạo: sau giao hợp, sau mãn kinh, rong kinh, rong huyết. Đi cầu ra máu. Núm vú. Chảy máu mũi | Cổ tử cung; đại trực tràng (phân biệt trĩ, viêm, dò); vú (phân biệt viêm ống dẫn sữa, bướu nhú trong ống); mũi: bệnh huyết học, ung thư vòm hầu, hốc mũi |\n| 4 | **Chỗ dày lên, khối u** | Vú (nữ, **đặc biệt > 30 tuổi**); bụng; tay, chân, thành bụng, thành ngực; cổ, nách, bẹn | Tài liệu không nêu tên bệnh |\n| 5 | **Khó tiêu / nuốt khó** | Ăn không tiêu, đầy bụng, đau thượng vị; nuốt vướng, nuốt đau; nuốt nghẹn tăng dần | Dạ dày (phân biệt viêm, loét); amiđan, hạ hầu; **nuốt nghẹn tăng dần → thực quản** |\n| 6 | **Thay đổi rõ nốt ruồi** | Lớn nhanh, đổi màu, ngứa, loét, tiết dịch, chảy máu khi đụng | Tài liệu không nêu tên bệnh |\n| 7 | **Ho dai dẳng / khàn tiếng** | Ho: nam, > 40 tuổi, hút thuốc. Khàn tiếng: **> 3 tuần**, nam, hút thuốc, uống rượu | Ho → phổi; khàn tiếng → thanh quản |\n{{SY5 tr.69–80}}\n\n> [!warn] Bẫy: thứ tự mục 5 và 6\n> Danh sách tổng (SY5 tr.68) xếp 5 = khó tiêu/nuốt khó, 6 = nốt ruồi; các slide chi tiết (tr.75–77) đánh số khác (4 khối u, 5 nốt ruồi, 6 khó tiêu). Nội dung giống nhau; thi thường hỏi **nội dung**, không hỏi số thứ tự.\n\n### Liên hệ hub triệu chứng\n- Xuất huyết âm đạo: [xuất huyết âm đạo bất thường](#/n/ung-thu-cotucung/4) · Khối ở vú: [khối ở vú](#/n/ung-thu-vu/4)\n- Ra máu đường tiêu hóa: [xuất huyết tiêu hóa dưới](#/n/ung-thu-daitruc-trang/4) · Đổi thói quen đi tiêu: [thay đổi thói quen đi tiêu](#/n/ung-thu-daitruc-trang/4)\n- Ho: [ho đàm – ho khan](#/n/ung-thu-phoi/4), [ho ra máu](#/n/ung-thu-phoi/4) · Bệnh: [Ung thư phổi](#/n/ung-thu-phoi/4)\n\n### Tình huống phát hiện bệnh\n@@tabs\n@@tab Điển hình\n- Đến khám vì **7 triệu chứng báo động** (ACS) {{SY5 tr.121}}\n@@tab Không điển hình\n- Triệu chứng ít gặp, thầy thuốc ít nghĩ tới ung thư:\n  - **Sụt cân không rõ nguyên nhân**, sốt tái đi tái lại, xanh xao, mệt mỏi, đau nhức kéo dài\n  - Khám vì **bướu/hạch di căn** mà chưa thấy bướu nguyên phát: hạch cổ, hạch trên đòn, hạch bẹn ác tính\n  - Bỗng đau lưng rồi **yếu dần hai chi dưới**\n  - **Tình cờ** khi khám sức khỏe/tầm soát: khối mờ nhỏ ở phổi trên X-quang ngực, tổn thương nghi bướu gan trên siêu âm\n{{SY5 tr.122}}\n@@end\n\n> [!red] Sai lầm cần tránh\n> Quan niệm \"ung thư phải có chán ăn, sụt cân\" = bệnh đã muộn, **mất cơ hội vàng** điều trị {{SY5 tr.119}}\n\nBước tiếp theo: [[ung-thu-tiep-can-chan-doan]].\n\n### Điểm hay thi\n> [!warn] \n> - Mục đích phổ biến 7 triệu chứng: phát hiện giai đoạn còn điều trị được, giảm tử vong\n> - Nuốt nghẹn **tăng dần** → thực quản; khàn tiếng **> 3 tuần** → thanh quản; ho dai dẳng nam > 40 tuổi hút thuốc → phổi\n> - Xuất huyết âm đạo sau giao hợp/mãn kinh → nghĩ cổ tử cung\n> - Khối ở vú: nữ **> 30 tuổi**\n> - Ung thư không nhất thiết có sụt cân/chán ăn; các dấu này thường là muộn\n\n### Tự kiểm tra\n- Mục đích phổ biến 7 triệu chứng báo động? :: Phát hiện ung thư giai đoạn còn điều trị được, giảm tử vong\n- 7 triệu chứng báo động theo ký hiệu nào, tổ chức nào? :: CAUTION; Hội Ung thư Hoa Kỳ (ACS)\n- Kể 7 triệu chứng. :: Đổi thói quen ruột/bàng quang; loét không lành; chảy máu/tiết dịch bất thường; chỗ dày/khối u; khó tiêu/nuốt khó; đổi nốt ruồi; ho dai dẳng/khàn tiếng\n- Biểu hiện thay đổi thói quen ruột? :: Táo bón/tiêu chảy kéo dài, xen kẽ, mót rặn kéo dài, máu lẫn trong phân\n- Nuốt nghẹn tăng dần gợi ý? :: Ung thư thực quản\n- Khàn tiếng gợi ý ung thư thanh quản khi nào? :: Kéo dài > 3 tuần, nam, hút thuốc, uống rượu\n- Ho dai dẳng gợi ý ung thư phổi ở ai? :: Nam, > 40 tuổi, hút thuốc lá\n- Dấu hiệu nốt ruồi đáng ngờ? :: Lớn nhanh, đổi màu, ngứa, loét, tiết dịch, chảy máu khi đụng\n- Chảy máu núm vú cần phân biệt gì? :: Viêm ống dẫn sữa, bướu nhú trong ống, ung thư vú\n- Chảy máu mũi nghĩ tới? :: Bệnh huyết học, ung thư vòm hầu, ung thư hốc mũi\n- Tình huống phát hiện không điển hình? :: Sụt cân/sốt/xanh xao/mệt/đau kéo dài; hạch hoặc bướu di căn chưa rõ nguyên phát; phát hiện tình cờ\n- Vì sao vẫn phải cảnh giác dù triệu chứng thường do bệnh lành? :: Vì cũng là báo động ung thư; cần khám sớm để xác định hay loại trừ"}, {"kind": "foundation", "disease": "", "short": "", "group": "Cơ chế", "section": 0, "order": 5, "khung": [], "id": "ung-thu-bieu-sinh", "title": "Cơ chế ngoài gen (biểu sinh) và microRNA trong sinh ung thư", "layer": "nen", "module": "ung-buou", "tags": ["ung thư", "epigenetics", "methyl hóa DNA", "histone", "HDAC", "DNMT", "microRNA", "oncomir"], "source": "Y2 tr. 11–14; SY2 tr. 61–86", "body": "> [!key]\n> - **Epigenetics**: đổi biểu hiện gen bằng phản ứng hóa học trên DNA, **không đổi trình tự**\n> - 3 cơ chế: **methyl hóa DNA · biến đổi histone · microRNA**\n> - Methyl hóa promoter đè nén bướu → **câm gen** → ung thư\n> - miRNA: **Onco-miR** (tăng, ức chế gen đè nén) vs **TS-miR** (giảm, mất ức chế gen sinh ung)\n\n### 1. Khái niệm\n- TB có ≥2 dạng thông tin: **tại gen** (tổng hợp protein) và **ngoài gen** (gen biểu hiện ở đâu, khi nào, thế nào)\n- Waddington đưa ra khái niệm; {o|năm: Y2 ghi 1943, SY2 ghi 1942} {{Y2 tr.11}} {{SY2 tr.63–64}}\n- Thay đổi hóa học có thể **kế thừa** hoặc **thu được** do môi trường; ở TB mầm, phôi, người lớn\n- Cần cho: biểu hiện gen, di truyền, biệt hóa, bất hoạt NST X ở nữ, lão hóa {{SY2 tr.65, 71}}\n- Liên quan ung thư: mất biểu hiện gen đè nén bướu do methyl hóa; (slide) điều biến telomere → TB không chết lập trình {{SY2 tr.71}}\n\n### 2. Biến đổi histone\n- DNA ~==1,8 m== cuộn quanh histone (nucleosome, chromatin) còn ~0,09 mm (giảm 20.000 lần)\n\n| NST đóng | NST mở |\n|---|---|\n| Đông đặc, ít hoạt động | Hoạt động |\n| **Nhiều** methyl hóa DNA, ít biến đổi histone | Nhiều biến đổi histone, **ít** methyl hóa DNA |\n| Gen ít biểu hiện | Gen biểu hiện nhiều |\n\n- Biến đổi ở **đuôi đầu N** histone: acetyl hóa Lys; methyl hóa Lys, Arg; phosphoryl hóa Ser, Thr\n- **HAT** gắn acetyl vào Lys, bỏ điện tích dương NH3+ → giảm ái lực histone–DNA → NST tách → gen biểu hiện; **HDAC** khử acetyl → NST cuộn chặt → gen tắt\n\n| Nhóm | Men gắn | Men tháo |\n|---|---|---|\n| Acetyl | HAT | HDAC |\n| Methyl | HMT | HDM |\n\n{{Y2 tr.11–12}} {{SY2 tr.67–70}}\n\n### 3. Methyl hóa DNA\n- Cơ chế ngoài gen **đơn giản nhất**: gắn -CH3 vào **C5 của Cytosine** (vùng CpG, thường ở promoter)\n- Không đổi trình tự, nhưng **chặn RNA polymerase II** → không có mRNA; còn huy động HDAC → NST cuộn chặt → câm gen\n- Men: **DNMT1, DNMT3A, DNMT3B**; men DNMT, HDAC đang thử nghiệm lâm sàng điều trị {{Y2 tr.12}} {{SY2 tr.65–66}}\n- Y2 viết gắn \"methyl hoặc acetyl\" ở C5 Cytosine (giữ đúng nguồn)\n\n### 4. microRNA (miRNA)\n- RNA không mã hóa, nội sinh, mạch đơn, **21–25 nt**; >30% gen người là đích; điều hòa chu kỳ, tăng trưởng, apoptosis, biệt hóa\n\n> [!tip] Hình thành miRNA\n> Pol II phiên mã → **pri-miRNA** → **Drosha** (nhân) → **pre-miRNA** → ra bào tương → **Dicer** → miRNA mạch đôi → 1 mạch vào **RISC** → gắn mRNA đích → thoái biến mRNA hoặc ức chế dịch mã\n\n| Loại | Đặc điểm | Ví dụ (SY2) |\n|---|---|---|\n| **Onco-miR** | Tăng biểu hiện, ức chế mRNA gen đè nén bướu / kiểm soát biệt hóa, apoptosis | miR-10b, -17, -21, -155 |\n| **TS-miR** (đè nén bướu) | Đích là mRNA gen sinh ung; **giảm** biểu hiện thì ung thư mới hình thành | let-7, miR-34b, -145, -205, -200 |\n| Thúc đẩy di căn xa | Tác động lên **EMT** | miR-7, -17/20, -22, -30 |\n\n{{Y2 tr.13}} {{SY2 tr.72–74}}\n\n@@fold Ứng dụng miRNA\n- **Chẩn đoán** (dấu ấn): theo dõi người nguy cơ cao, chẩn đoán sớm, phân biệt lành/ác\n- **Tiên đoán**: đáp ứng điều trị · **Tiên lượng**: sống còn, theo dõi tái phát\n- **Điều trị** (còn khởi đầu, nhiều rủi ro): tăng TS-miRNA (thay thế) hoặc ức chế Onco-miR (kháng miRNA) {{Y2 tr.13}} {{SY2 tr.76–78}}\n@@end\n\n### Điểm hay thi\n> [!warn]\n> - Epigenetics **không đổi trình tự** DNA; methyl hóa ở **C5 Cytosine**, câm gen\n> - HAT mở NST – HDAC đóng NST; NST đóng nhiều methyl hóa\n> - Drosha (nhân) – Dicer (bào tương); RISC\n> - Onco-miR vs TS-miR: hướng biểu hiện **ngược nhau** và đích khác nhau\n\n### Tự kiểm tra\n- Epigenetics là gì? :: Đổi biểu hiện gen qua phản ứng hóa học trên DNA mà không đổi trình tự\n- Ba cơ chế ngoài gen? :: Methyl hóa DNA, biến đổi histone, microRNA\n- Methyl hóa DNA ở vị trí nào, kết quả? :: C5 của Cytosine (CpG); ngăn RNA polymerase II, không mRNA, câm gen\n- Ba men DNMT? :: DNMT1, DNMT3A, DNMT3B\n- HAT và HDAC khác nhau thế nào? :: HAT gắn acetyl → NST mở, gen biểu hiện; HDAC khử acetyl → NST đóng, gen tắt\n- Men cắt pri-miRNA và pre-miRNA? :: Drosha (nhân); Dicer (bào tương)\n- Onco-miR khác miRNA đè nén bướu thế nào? :: Onco-miR tăng và ức chế gen đè nén bướu; miRNA đè nén bướu nhắm gen sinh ung, phải giảm biểu hiện\n- 3 ứng dụng miRNA làm dấu ấn sinh học? :: Chẩn đoán, tiên đoán đáp ứng, tiên lượng/theo dõi tái phát\n- Kích thước miRNA? :: 21–25 nucleotide"}, {"kind": "foundation", "disease": "", "short": "Bệnh án ung thư", "group": "Triệu chứng và chẩn đoán chung", "section": 7, "order": 9, "khung": [], "id": "ung-thu-cach-lam-benh-an", "title": "Cách làm bệnh án ung thư", "layer": "trieuchung", "module": "ung-buou", "tags": ["bệnh án", "hỏi bệnh", "tiền sử", "khám lâm sàng", "cận lâm sàng", "tóm tắt bệnh án", "TNM", "giai đoạn", "ECOG", "KPS"], "source": "Y5 tr.5–7, 14, 17–18, 146 (ung thư vú; tóm tắt bệnh án ở ung thư đầu cổ); SY5 tr.123, 145–146, 217–219, 235–237, 267; QĐ 3128 tr.6, 11, 14–15, 28, 39; Y2 tr.84; ĐC Y5 tr.3–4, 6 (MT11, MT14–17); QĐ 22 mục 4.2 tr.8", "body": "> [!key] Làm bệnh án ung thư trong một nhìn\n> - Bài sắp xếp bệnh án thành **9 phần** theo trình tự (cách sắp xếp của bài, không có trong tài liệu nguồn): hành chính → lý do vào viện → bệnh sử → tiền sử → khám → cận lâm sàng → chẩn đoán → điều trị → tiên lượng\n> - Chẩn đoán đầy đủ gồm **xác định** (mô bệnh học) · **giai đoạn** (TNM) · **bản chất sinh học** · **bệnh kèm**; thêm **thể trạng** (KPS/ECOG) {{SY5 tr.267}} {{QĐ3128 tr.11}} {{SY5 tr.145}}\n> - Trước điều trị phải xác định **M0 hay M1**, nhóm sinh học, yếu tố tiên lượng và tình trạng kinh nguyệt {{Y5 tr.18}}\n> - Ghi tóm tắt **theo giai đoạn** (khu trú → tiến xa tại vùng → di căn; sau mổ; sau tân bổ trợ), xem bảng mục \"Tóm tắt theo giai đoạn\"\n\n### Mục tiêu học tập\n- **MT11 (kỹ năng): làm được hoàn chỉnh bệnh án ung thư** {{ĐC Y5 tr.3}}\n- Lịch đề cương gắn buổi này với **MT 11, 14, 15, 16, 17** {{ĐC Y5 tr.6}}:\n  - MT14: chẩn đoán tuân thủ nguyên tắc, nhất là **tương hợp lâm sàng và xét nghiệm** {{ĐC Y5 tr.4}}\n  - MT15: điều trị theo **đa mô thức, liên chuyên khoa** {{ĐC Y5 tr.4}}\n  - MT16: tôn trọng, đồng cảm với bệnh nhân và thân nhân {{ĐC Y5 tr.4}}\n  - MT17: hợp tác tốt với đồng nghiệp liên chuyên khoa {{ĐC Y5 tr.4}}\n- Sau bài: viết đủ 9 phần bệnh án, tóm tắt đúng theo giai đoạn\n\n### Bệnh án gồm những phần nào\n| Phần | Ghi gì | Nguồn |\n|---|---|---|\n| **Hành chính** | họ tên, tuổi, giới, nghề, địa chỉ, ngày vào viện: tài liệu không nêu mẫu, ghi theo mẫu của cơ sở | — tài liệu không nêu |\n| **Lý do vào viện** | triệu chứng chính + hoàn cảnh phát hiện (tự sờ thấy cục, tiết dịch núm vú, khám tầm soát, đã tự chữa, bệnh đã trễ) | {{Y5 tr.5}} {{Y5 tr.6}} |\n| **Bệnh sử** | lúc bắt đầu triệu chứng, diễn tiến, quá trình đi khám và điều trị trước | {{SY5 tr.123}} {{Y5 tr.6}} |\n| **Tiền sử** | bản thân, gia đình, sản–phụ khoa, nghề và lối sống, tiền sử bệnh vú | {{QĐ3128 tr.6}} {{Y2 tr.84}} |\n| **Khám** | vú hai bên, khối, hạch vùng, cơ quan nghi di căn, toàn trạng | {{SY5 tr.123}} {{Y5 tr.7}} |\n| **Cận lâm sàng** | hình ảnh, mô bệnh học, dấu ấn, xét nghiệm trước điều trị | {{Y5 tr.14}} {{QĐ3128 tr.11}} |\n| **Chẩn đoán** | xác định, giai đoạn, sinh học, bệnh kèm, thể trạng | {{SY5 tr.267}} {{SY5 tr.145}} |\n| **Điều trị** | mục tiêu, phương pháp, theo dõi và tóm tắt gửi bác sĩ gia đình | {{Y5 tr.18}} {{Y5 tr.146}} |\n| **Tiên lượng** | yếu tố tiên lượng, sống còn | {{Y5 tr.17}} |\n\nLưu ý: \"lý do vào viện\" không có định nghĩa trong tài liệu đã cung cấp; bài này dùng nghĩa thông thường (triệu chứng chính + hoàn cảnh phát hiện).\n\n### Cách ghi tiền sử và bệnh sử\n@@tabs\n@@tab Bệnh sử\n- Ghi theo **trình tự thời gian**: lúc có triệu chứng → diễn tiến → đi khám, điều trị ở đâu {{SY5 tr.123}}\n- Hỏi kỹ **điều trị trước đó**: đắp lá, đắp thuốc, chích lể có thể làm bệnh bùng phát hoặc phức tạp {{Y5 tr.6}}\n- Diễn tiến tại chỗ: da dày, da cam, co kéo, núm vú lún, hạch nách hoặc trên đòn; lan tràn: khó thở, nhức đầu, gãy xương, báng bụng {{Y5 tr.5}} {{Y5 tr.6}}\n@@tab Tiền sử bản thân\n- Bệnh vú trước đây; bệnh nội khoa và ngoại khoa {{QĐ3128 tr.6}}\n- Tiền sử sản–phụ khoa; **tình trạng kinh nguyệt hiện tại** (quyết định chọn nội tiết) {{QĐ3128 tr.6}} {{Y5 tr.6}}\n- Chưa có con hoặc muốn sinh thêm: hóa trị có thể gây vô sinh, cần tư vấn trữ phôi hoặc trứng trước hóa trị {{Y5 tr.6}}\n- Ung thư vú: tăng sản không điển hình, carcinôm tiểu thùy tại chỗ, ung thư vú một bên {{SY5 tr.217}}; xạ trị vùng ngực trước 30 tuổi {{SY5 tr.218}}; kinh sớm (<12 tuổi), mãn kinh muộn (>55 tuổi), không con {{SY5 tr.219}}\n@@tab Gia đình – lối sống\n- Tiền sử gia đình, **đặc biệt ung thư vú và buồng trứng**; ghi có từ 2 người trở lên mắc ở tuổi trẻ {{QĐ3128 tr.6}}\n- Tiền sử công việc và lối sống (thói quen sinh hoạt, môi trường sống): thuốc lá, chế độ dinh dưỡng, tắm nắng {{Y2 tr.84}}\n- Mục đích: chỉ ra **yếu tố nguy cơ** (nhóm không đổi được: gia đình, giới, tuổi, nồng độ hormone; nhóm đổi được: thói quen, môi trường) {{Y2 tr.84}}\n@@end\n\n### Khám và cận lâm sàng\n#### Khám\n- **Nhìn**: so sánh hai bên; da có phù, da cam, đỏ, loét, sẹo sinh thiết; núm vú tụt, loét, tiết dịch, mất cân xứng {{Y5 tr.6}}\n- **Sờ**: dùng mặt lòng ngón 2–4; giới hạn vú: trên là bờ dưới xương đòn, dưới là nếp dưới vú, trong là bờ xương ức, ngoài là đường nách giữa {{Y5 tr.7}}\n- **Khối**: vị trí, kích thước, hình dạng, màu, mật độ, giới hạn, độ di động, đau {{SY5 tr.123}}\n- **Hạch**: nách và trên đòn; hạch di căn tròn, sượng, cứng, dính nhau hoặc dính mô quanh {{Y5 tr.7}}\n- **Toàn thân**: thăm khám các cơ quan để tìm di căn xa {{Y5 tr.7}}\n- Thời điểm khám vú tốt nhất: tuần đầu sau sạch kinh {{SY5 tr.237}}\n\n#### Cận lâm sàng\n| Nhóm | Ghi trong bệnh án | Nguồn |\n|---|---|---|\n| Hình ảnh | khám lâm sàng + siêu âm, nhũ ảnh, MRI vú để đánh giá bướu và hạch | {{Y5 tr.14}} |\n| Di căn xa | không tầm soát thường quy ở giai đoạn sớm; chỉ khi có triệu chứng: xạ hình xương, CT bụng chậu, X-quang hoặc CT ngực, MRI não; giai đoạn tiến triển: xạ hình xương, CT ngực bụng hoặc PET/CT | {{Y5 tr.14}} |\n| Mô bệnh học | chẩn đoán xác định khi có tế bào biểu mô ác tính; sinh thiết kim lõi ưu tiên khi thiếu nhà tế bào học | {{QĐ3128 tr.11}} |\n| Dấu ấn (ung thư vú) | CA15-3 không dùng để sàng lọc, chẩn đoán hay theo dõi giai đoạn sớm | {{Y5 tr.14}} |\n| Trước điều trị | công thức máu, nhóm máu, đông máu, HIV, viêm gan, điện tâm đồ, siêu âm tim; β-hCG nếu tuổi sinh đẻ; estradiol và FSH nếu chưa rõ mãn kinh | {{QĐ3128 tr.11}} |\n\n> [!warn] Mâu thuẫn nguồn: CA15-3 khi theo dõi\n> - Y5 tr.14: CA15-3 **không có vai trò** trong theo dõi sau điều trị ung thư vú giai đoạn sớm {{Y5 tr.14}}\n> - QĐ 3128: CA15-3 và CEA được liệt kê trong xét nghiệm theo dõi, \"tùy theo từng trường hợp\" {{QĐ3128 tr.28}}\n> - Ghi cả hai nguồn; không tự chọn một đáp án khi chưa có hướng dẫn của bộ môn\n\n### Chẩn đoán\n- **Bốn nội dung** của chẩn đoán đầy đủ: chẩn đoán xác định · chẩn đoán giai đoạn · chẩn đoán bản chất sinh học · chẩn đoán bệnh đi kèm; sau đó lập kế hoạch điều trị {{SY5 tr.267}}\n- Chẩn đoán xác định cần **bộ ba**: lâm sàng (khối u) + hình ảnh + mô bệnh học {{QĐ3128 tr.11}}\n- Khối ở vú cần chẩn đoán phân biệt với u xơ tuyến, nang, nang sữa, viêm và áp xe, hoại tử mỡ, u phyllode, u nhú trong ống, sarcoma và lymphoma {{QĐ3128 tr.11}}\n- Thể trạng: thang **KPS** (0–100) và **WHO/ECOG** (0–5). Tương quan: ECOG 0–1 ≈ KPS 80–100; ECOG 2 ≈ KPS 60–70; ECOG 3–4 ≈ KPS 10–50 {{SY5 tr.145}} {{SY5 tr.146}}\n- Chi tiết từng nội dung chẩn đoán (bài này đếm 4 nội dung như trên; bài tiếp cận đếm tách thêm cơ quan mang bướu và nhóm nguy cơ thành 5 mục): [[ung-thu-tiep-can-chan-doan]]; thể trạng: [[ung-thu-the-trang-kps-ecog]]; TNM: [[ung-thu-phan-giai-doan-tnm]]\n\n### Tóm tắt theo giai đoạn\n| Tình huống | Tóm tắt phải có | Hướng điều trị ghi kèm |\n|---|---|---|\n| **Khu trú, tại chỗ** | vị trí, kích thước, hạch (cN), mô bệnh học, thể trạng ECOG/KPS | mục tiêu **khỏi bệnh**; phẫu thuật chủ yếu, xạ hoặc toàn thân bổ trợ tùy yếu tố tiên lượng {{Y5 tr.18}} |\n| **Tiến xa tại vùng** | như trên, thêm đánh giá có mổ được không | đa mô thức, liên chuyên khoa; phụ thuộc giai đoạn và đặc điểm khối u {{QĐ3128 tr.15}} {{ĐC Y5 tr.4}} |\n| **Đã di căn (M1)** | vị trí di căn; cM1 (lâm sàng, hình ảnh) hay pM1 (chứng minh mô học) | điều trị toàn thân, **kéo dài sống còn và duy trì chất lượng sống** {{Y5 tr.18}} {{QĐ3128 tr.14}} |\n| **Sau phẫu thuật** | pTNM kèm: loại mô học, độ mô học, xâm nhập mạch và bạch huyết, thụ thể nội tiết, HER2, Ki67, diện cắt, kích thước, đa ổ hay đơn ổ, hạch di căn, thành phần tại chỗ {{Y5 tr.14}} | quyết định bổ trợ theo nhóm nguy cơ {{QĐ3128 tr.19}} {{Y5 tr.20}} |\n| **Sau tân bổ trợ** | tiền tố **yc** (lâm sàng khi kết thúc tân bổ trợ) hoặc **yp** (sau mô bệnh học) {{QĐ3128 tr.11}} | đánh giá đáp ứng {{QĐ3128 tr.8}} |\n\nGhi TNM: cTNM và pTNM dùng chung T và M, chỉ khác ở N {{QĐ3128 tr.11}}.\n\n### Điều trị và tiên lượng\n- **Điều trị**: giai đoạn tại chỗ có mục tiêu **khỏi**; phẫu thuật luôn là chủ yếu với bướu và hạch vùng; bảo tồn vú luôn kèm xạ {{Y5 tr.18}}\n- **Tiên lượng** (ung thư vú làm ví dụ):\n  - Di căn hạch là yếu tố **mạnh nhất**: tái phát cao hơn 2,5 lần, tử vong cao hơn 2–3,3 lần; càng nhiều hạch càng xấu {{Y5 tr.17}}\n  - Kích thước u tăng thì nguy cơ tái phát và tử vong tăng; tuổi dưới 35 và trên 70 tiên lượng xấu {{Y5 tr.17}}\n  - Ki67 cao: tái phát nhiều hơn, sống còn thấp, nhưng đáp ứng hóa trị tốt; xâm nhập mạch bạch huyết hoặc mạch máu xấu {{Y5 tr.18}}\n- **Sau điều trị**: lập và gửi kế hoạch chăm sóc cùng tóm tắt bệnh án cho bệnh nhân và bác sĩ gia đình trong vòng 6 tháng sau khi kết thúc điều trị (ví dụ ung thư đầu cổ) {{Y5 tr.146}}\n\n### Điểm hay thi\n> [!warn]\n> - Bệnh sử phải có **diễn tiến và điều trị trước đó** (đắp lá, chích lể) {{Y5 tr.6}}\n> - Tiền sử gia đình phải ghi **số người và tuổi mắc**; từ 2 người trở lên ở tuổi trẻ là đáng lưu ý {{QĐ3128 tr.6}}\n> - Chẩn đoán đầy đủ = xác định + giai đoạn + sinh học + bệnh kèm + thể trạng {{SY5 tr.267}} {{SY5 tr.145}}\n> - cTNM khác pTNM ở N; sau tân bổ trợ dùng tiền tố yc/yp {{QĐ3128 tr.11}}\n> - pM1 cần chứng minh bằng mô học; cM1 chỉ cần lâm sàng và hình ảnh {{QĐ3128 tr.14}}\n> - Giai đoạn sớm **không** tầm soát di căn xa thường quy {{Y5 tr.14}}\n> - ECOG 3 kèm nhiều phác đồ thất bại: cân nhắc ngừng hóa trị và chăm sóc hỗ trợ {{QĐ3128 tr.39}}\n> - Trọng số đề thi (QĐ 22, mục 4.2 tr. PDF 8, bảng OCR khó đọc, đối chiếu bản gốc): cận lâm sàng/xét nghiệm chẩn đoán 45–60; xử trí và liệu pháp thuốc 35–50\n\n### Tự kiểm tra\n- Các phần của bệnh án ung thư theo thứ tự? :: Hành chính, lý do vào viện, bệnh sử, tiền sử, khám, cận lâm sàng, chẩn đoán, điều trị, tiên lượng\n- Bệnh sử ung thư vú cần ghi những gì? :: Lúc bắt đầu triệu chứng, diễn tiến, quá trình đi khám và điều trị trước (kể cả đắp lá, chích lể)\n- Tiền sử phụ nữ cần hỏi những mục nào? :: Bệnh vú trước đây, bệnh nội–ngoại khoa, sản–phụ khoa, kinh nguyệt hiện tại, tiền sử gia đình (vú, buồng trứng)\n- Chẩn đoán đầy đủ gồm những nội dung nào? :: Xác định, giai đoạn, bản chất sinh học, bệnh kèm; sau đó lập kế hoạch điều trị\n- cTNM khác pTNM ở điểm nào? :: T và M giống nhau; N khác (cN lâm sàng, pN sau mô bệnh học)\n- Khi nào dùng tiền tố yc và yp? :: yc khi kết thúc tân bổ trợ (lâm sàng); yp sau khi có mô bệnh học\n- Giai đoạn sớm có tầm soát di căn xa thường quy không? :: Không; chỉ chụp khi có triệu chứng hoặc gợi ý (xạ hình xương, CT, MRI não)\n- CA15-3 dùng để làm gì ở ung thư vú giai đoạn sớm? :: Không dùng để sàng lọc, chẩn đoán hay theo dõi (Y5); QĐ3128 để tùy trường hợp\n- ECOG 0–1 tương đương KPS bao nhiêu? :: KPS 80–100 (ECOG 2 ≈ KPS 60–70; ECOG 3–4 ≈ KPS 10–50)\n- Mục tiêu điều trị giai đoạn tại chỗ và khi đã di căn? :: Tại chỗ: khỏi bệnh, phẫu thuật chủ yếu; di căn: toàn thân, kéo dài sống còn, giữ chất lượng sống\n- Yếu tố tiên lượng mạnh nhất của ung thư vú? :: Di căn hạch (tái phát cao hơn 2,5 lần, tử vong cao hơn 2–3,3 lần)\n- Sau mổ, bệnh án ghi những yếu tố gì? :: Loại và độ mô học, xâm nhập mạch, thụ thể nội tiết, HER2, Ki67, diện cắt, kích thước, đa ổ, hạch, TNM theo mô bệnh học"}, {"kind": "foundation", "disease": "", "short": "Cấp cứu chèn ép", "group": "", "section": 6, "order": 2, "khung": [], "id": "ung-thu-cap-cuu-chen-ep", "title": "Cấp cứu ung thư do chèn ép: xử trí ban đầu", "layer": "dieutri", "module": "ung-buou", "tags": ["cấp cứu ung thư", "tĩnh mạch chủ trên", "chèn ép tủy", "đuôi ngựa", "tăng áp lực nội sọ", "di căn não", "tràn dịch màng tim", "tràn dịch màng phổi", "đường thở", "corticoid", "xạ trị cấp cứu"], "source": "QĐ1514 tr.PDF 37–40, 53–56, 58–62, 68–70, 81, 85–86, 124–127; Y5 tr.109, 135, 333, 343", "body": "> [!key] Tóm tắt\n> - Năm cấp cứu chèn ép: **TM chủ trên**, **tủy sống/ đuôi ngựa**, **tăng áp lực nội sọ/ di căn não**, **tràn dịch màng tim/ màng phổi ác tính**, **bít tắc đường thở**. {{QĐ1514 tr.PDF 37, 53, 58, 68, 81}}\n> - Cùng một nguyên tắc: **ổn định sinh tồn trước** (oxy, đường thở, tư thế), rồi **giải ép** (corticoid, xạ trị, stent, dẫn lưu), sau đó **điều trị nguyên nhân**. {{QĐ1514 tr.PDF 55, 62, 69}}\n> - Chẩn đoán hình ảnh cấp: **CT sọ não** (tăng áp lực nội sọ), **MRI toàn bộ cột sống trong 24 giờ** (chèn ép tủy), **CT ngực** (TM chủ trên), **siêu âm tim** (tràn dịch màng tim). {{QĐ1514 tr.PDF 54, 59, 68, 40}}\n> - Phần nhận diện lâm sàng chi tiết xem [[ung-thu-hoi-chung-can-u-va-chen-ep]]; bài này tập trung **xử trí**.\n\n### 1. Hội chứng tĩnh mạch chủ trên\n\n> [!red] Phù mặt cổ, phù áo khoác, giãn TM cổ ngực, khó thở: cần xử trí ngay; nếu có khò khè, tổn thương đường hô hấp hoặc phù não thì ưu tiên **stent TM rồi xạ trị**. {{QĐ1514 tr.PDF 68–69}}\n\n@@tabs\n@@tab Nhận diện nhanh\n- **Khó thở** (phổ biến nhất), đau ngực, ho, nuốt khó, căng tức đầu tăng khi cúi hoặc nằm. {{QĐ1514 tr.PDF 68}}\n- **Phù mặt, cổ, phù áo khoác, phù tay**, tuần hoàn bàng hệ cổ ngực; có thể phù não (đau đầu, lẫn, co giật, hôn mê). {{QĐ1514 tr.PDF 68}}\n- Nguyên nhân hay gặp: ung thư phổi, u trung thất, thực quản, thanh quản hạ họng, NHL, vú, hạch di căn. {{QĐ1514 tr.PDF 69}}\n@@tab Cận lâm sàng cần làm ngay\n- Xét nghiệm thường quy (công thức máu, gan thận, điện giải, đông máu cơ bản). {{QĐ1514 tr.PDF 68}}\n- **X-quang tim phổi** (sơ bộ nguyên nhân); **CT lồng ngực**, PET/CT toàn thân. {{QĐ1514 tr.PDF 68}}\n- **Siêu âm Doppler TM chi trên** (tắc nghẽn, huyết khối); chụp mạch cản quang TM hai chi trên (vị trí tắc). {{QĐ1514 tr.PDF 68–69}}\n- **Mô bệnh học** để biết lành hay ác: tế bào đờm/ dịch màng phổi, sinh thiết hạch ngoại vi, tủy xương, nội soi phế quản, soi trung thất, sinh thiết xuyên thành ngực dưới CT. {{QĐ1514 tr.PDF 69}}\n@@end\n\n#### Xử trí ban đầu\n| Tình huống | Xử trí theo QĐ1514 |\n|---|---|\n| Suy hô hấp | **Oxy** mũi kính ==3–4== lít/phút; suy hô hấp nặng: đặt nội khí quản thông khí nhân tạo nhanh {{QĐ1514 tr.PDF 69}} |\n| Khò khè, tổn thương đường hô hấp, chèn ép thần kinh trung ương | **Stent TM** trước, sau đó **xạ trị** liều tùy nguyên nhân {{QĐ1514 tr.PDF 69}} |\n| Đang xạ trị cấp cứu do u chèn ép đường thở | **Corticosteroid liều cao ngắn ngày**: methylprednisolon ==40== mg (==1–1,5== mg/kg) tiêm TM ==2–3== ống/ngày {{QĐ1514 tr.PDF 69}} |\n| Ung thư **nhạy hóa chất**: SCLC, NHL, u tế bào mầm, vú | **Hóa trị ngay** theo phác đồ từng bệnh; có thể đặt stent trước hóa trị {{QĐ1514 tr.PDF 69}} |\n| NSCLC | **Stent trước**, sau đó xạ trị đơn thuần hoặc phối hợp hóa trị, xạ trị, điều trị đích, miễn dịch {{QĐ1514 tr.PDF 70}} |\n| Tái phát/ tiến triển có chèn ép TM chủ trên | **Stent trước**, sau đó điều trị nguyên nhân (xạ, hóa...) {{QĐ1514 tr.PDF 70}} |\n| Sau đặt stent mạch máu | **Chống đông kéo dài**: warfarin (Sintrom 4 mg uống ==1/2–1/4== viên/ngày) {{QĐ1514 tr.PDF 70}} |\n| Chèn ép đường thở | **Xạ trị cấp cứu**: 2 Gy x 20 buổi, 3 Gy x 10 buổi, hoặc 4 Gy x 5 buổi {{QĐ1514 tr.PDF 70}} |\n\n- Mục đích điều trị: **giảm nhẹ triệu chứng và điều trị nguyên nhân**; hướng điều trị nguyên nhân phụ thuộc loại ung thư, mức lan rộng, mô bệnh học, tiên lượng. {{QĐ1514 tr.PDF 69}}\n- **Nhập viện/ chuyển tuyến**: tài liệu không nêu tiêu chuẩn riêng; các biện pháp trên (stent, nội khí quản, xạ trị cấp cứu) đều cần cơ sở chuyên khoa. Y5 chỉ nêu chèn ép TM chủ trên là một nguyên nhân gây khó thở trong ung thư phổi. {{Y5 tr.109}}\n\n### 2. Chèn ép tủy sống và hội chứng đuôi ngựa\n\n> [!red] Ung thư nghi di căn cột sống + **đau lưng, yếu chân hoặc rối loạn cơ tròn**: **MRI toàn bộ cột sống sớm nhất, trong 24 giờ**; đa số bệnh nhân bị chẩn đoán khi đã không còn đi lại được. {{QĐ1514 tr.PDF 58–59}}\n\n@@tabs\n@@tab Nhận diện nhanh\n- **Đau** là biểu hiện đầu tiên (==80–90%==), có trước thiếu hụt thần kinh **nhiều tuần**; sau đó rối loạn cảm giác, vận động, cơ tròn. {{QĐ1514 tr.PDF 58}}\n- **Hội chứng đuôi ngựa**: đau kiểu rễ hai chân, yếu hai chân, mất cảm giác hai chân, rối loạn cơ tròn (chèn ép nhiều rễ vùng đuôi ngựa). {{QĐ1514 tr.PDF 59}}\n- Tủy tận cùng ngang **L1** ở người lớn, dưới đó là đuôi ngựa; chèn ép tủy hay gặp ở đốt sống ngực (==60–70%==), lưng (==20–30%==), thắt lưng hiếm (==10%==). {{QĐ1514 tr.PDF 62–63}}\n- Ung thư hay di căn cột sống: tuyến tiền liệt, phổi, vú, thận, NHL, đa u tủy. {{QĐ1514 tr.PDF 58, 60}}\n- Y5: yếu liệt hai chân đột ngột, tiểu không tự chủ gợi ý di căn cột sống và chèn ép tủy. {{Y5 tr.333}}\n@@tab Cận lâm sàng cần làm ngay\n- **MRI toàn bộ cột sống** (cổ, ngực, thắt lưng cùng) không và có thuốc đối quang từ, **trong vòng 24 giờ** khi nghi chèn ép tủy. {{QĐ1514 tr.PDF 59}}\n- **CT cột sống** khi chống chỉ định MRI (dị vật kim loại, máy tạo nhịp). {{QĐ1514 tr.PDF 60}}\n- Khám vận động (thang cơ lực), cảm giác, cơ tròn (cơ thắt hậu môn, phản xạ hành-hang, bí đái). {{QĐ1514 tr.PDF 59}}\n- Chưa rõ u nguyên phát: **sinh thiết** u di căn cột sống dưới CT trước khi quyết định điều trị cụ thể. {{QĐ1514 tr.PDF 61}}\n@@end\n\n#### Xử trí ban đầu\n- **Corticoid** ngay ở giai đoạn đầu chẩn đoán: chống phù nề tủy, giảm đau; liều thường dùng cao **4–8 ống dexamethason 4 mg mỗi 6 giờ**. {{QĐ1514 tr.PDF 62}}\n- **Xạ trị** là phương pháp **đầu tiên được chọn** cho u di căn cột sống, nhất là u nhạy xạ (lymphoma, đa u tủy); **xạ chống chèn ép** khi chèn ép thần kinh cấp **không thể phẫu thuật**. {{QĐ1514 tr.PDF 62}} Y5 cũng ghi xạ chống chèn ép tủy là **tình huống xử trí cấp cứu**. {{Y5 tr.343}}\n- **Phẫu thuật** (cắt thân đốt, nẹp vít, giải ép qua mở cung sau) khi chèn ép tủy kèm mất vững, còn chèn ép sau xạ trị, hoặc cần làm vững cột sống và lấy mô bệnh học. {{QĐ1514 tr.PDF 61, 63}}\n- **Hóa trị** thường **sau** phẫu thuật/ xạ trị, vì hầu hết u di căn cột sống có chèn ép tủy kém nhạy hóa chất; chỉ ưu tiên với lymphoma, đa u tủy, u nguyên bào thần kinh, u tế bào mầm. {{QĐ1514 tr.PDF 62}}\n- Chọn hướng điều trị theo mô bệnh học, chức năng thần kinh, mức lan rộng, mất vững cột sống và thang điểm tiên lượng (Tokuhashi). {{QĐ1514 tr.PDF 60–61}}\n- **Nhập viện/ chuyển tuyến**: tài liệu không nêu tiêu chuẩn riêng; hướng xử trí phối hợp nội khoa, xạ trị, phẫu thuật. {{QĐ1514 tr.PDF 63}}\n\n### 3. Tăng áp lực nội sọ và di căn não\n\n> [!red] Đau đầu tăng dần + nôn + rối loạn ý thức, **tam chứng Cushing** (tăng huyết áp, mạch chậm, rối loạn nhịp thở), giãn đồng tử: nghi tụt não, xử trí theo từng bước. {{QĐ1514 tr.PDF 53–54}}\n\n@@tabs\n@@tab Nhận diện nhanh\n- Sớm: đau đầu tăng dần (từng cơn buổi sáng), nôn (nôn vọt gợi ý hố sau), rối loạn ý thức, phù gai thị, động kinh, tam chứng Cushing. {{QĐ1514 tr.PDF 53}}\n- Muộn (tụt não): Glasgow tụt nhanh, rối loạn thần kinh thực vật, giãn đồng tử một hoặc hai bên; **Glasgow < 8** là hôn mê sâu. {{QĐ1514 tr.PDF 53–54}}\n- **Di căn não**: đau đầu ==40–50%==, dấu thần kinh khu trú ==20–40%==, đổi tính cách ==30–35%==, động kinh mới ==10–20%==, đột quỵ ==5–10%==. {{QĐ1514 tr.PDF 124}}\n@@tab Cận lâm sàng cần làm ngay\n- **CT sọ não**: lựa chọn đầu tiên vì chụp được cấp cứu. {{QĐ1514 tr.PDF 54}}\n- **MRI sọ não**: ít dùng trong cấp cứu nhưng giá trị hơn để đánh giá phù não, vị trí, bản chất khối u; nhạy hơn CT trong tìm di căn não. {{QĐ1514 tr.PDF 55, 125}}\n- Công thức máu, sinh hóa (rối loạn nước điện giải); soi đáy mắt. {{QĐ1514 tr.PDF 55}}\n- Đo áp lực nội sọ (xâm nhập hoặc siêu âm xuyên sọ); > 20 cmH2O khẳng định tăng áp lực nội sọ. {{QĐ1514 tr.PDF 55}}\n@@end\n\n#### Xử trí ban đầu\n1. **Tư thế** đầu cao ==30== độ (hạ đầu nếu có dấu tụt kẹt não), thông thoáng đường thở; hôn mê thì đặt nội khí quản hoặc mở khí quản thông khí. {{QĐ1514 tr.PDF 55}}\n2. Đủ oxy; giảm đau an thần nếu kích thích hoặc co giật. {{QĐ1514 tr.PDF 55}}\n3. **Huyết áp**: tâm thu < 90 mmHg thì truyền dịch đẳng trương và vận mạch (dopamin, noradrenalin); tăng huyết áp thì phối hợp hạ áp. {{QĐ1514 tr.PDF 56}}\n4. **Thuốc tăng áp lực thẩm thấu**: manitol 20–25% truyền TM nhanh ==1–1,5== g/kg/6 giờ; tác dụng sau ==45== phút, kéo dài ==4–6== giờ; **không dùng quá 72 giờ**; có thể thay bằng muối ưu trương 1,25–3%. {{QĐ1514 tr.PDF 56}}\n5. **Corticosteroid**: dexamethason ==8== mg tiêm TM/ bắp, sau đó ==4== mg/6 giờ; có thể thêm synacthen 1 mg. {{QĐ1514 tr.PDF 56}}\n6. Hạn chế nước (==10–15== ml/kg/24 giờ), chỉnh natri; hạ sốt (paracetamol); **chống động kinh** (diazepam 10 mg tiêm TM/ bắp, depakin, tegretol). {{QĐ1514 tr.PDF 56}}\n7. Tụt kẹt hạnh nhân tiểu não: đặt nội khí quản, thông khí tối ưu, PCO2 ==30–35== mmHg, SpO2 > 90%. Vẫn nặng: thiopental (phải thở máy). {{QĐ1514 tr.PDF 56}}\n\n#### Giải ép và điều trị nguyên nhân\n- **Phẫu thuật**: dẫn lưu dịch não tủy cấp cứu nếu tắc nghẽn lưu thông, mở hộp sọ giảm áp, lấy u; chỉ định khi ICP > 20 cmH2O dù đã điều trị nội khoa tích cực. {{QĐ1514 tr.PDF 56–57}}\n- **Xạ trị** sau khi ổn định để giảm thể tích u (xạ gia tốc, xạ phẫu). {{QĐ1514 tr.PDF 57}}\n- **Di căn não**: xử trí gấp dấu hiệu chèn ép, phù não là ưu tiên hàng đầu; corticoid dùng khi tăng áp lực nội sọ hoặc liệt: dexamethason 4 mg, ==4–8== lọ/ngày tiêm TM, **giảm liều dần** trước khi dừng. {{QĐ1514 tr.PDF 126–127}}\n- Xạ trị toàn não (> 3 ổ, không mổ/ xạ phẫu được, bệnh lan tràn): 30 Gy/10 phân liều. Xạ phẫu: ≤ 3 ổ, u < 5 cm. {{QĐ1514 tr.PDF 126–127}}\n- **Chống động kinh**: không điều trị dự phòng nếu chưa có cơn. {{QĐ1514 tr.PDF 127}}\n- Bevacizumab được nêu cho phù não sau xạ trị/ xạ phẫu khi steroid không đáp ứng. {{QĐ1514 tr.PDF 56}}\n- **Nhập viện/ chuyển tuyến**: tài liệu không nêu tiêu chuẩn riêng; đặt máy đo ICP và quyết định phẫu thuật do chuyên khoa thần kinh. {{QĐ1514 tr.PDF 56}}\n\n### 4. Tràn dịch màng tim và màng phổi ác tính\n\n> [!red] Tràn dịch màng tim số lượng nhiều có ép tim (mạch đảo, TM cổ nổi, tụt huyết áp) là cấp cứu: **chọc dẫn lưu dưới hướng dẫn siêu âm tim** khẩn trương. {{QĐ1514 tr.PDF 39–40}}\n\n@@tabs\n@@tab Tràn dịch màng tim\n- **Nhận diện**: ít thì thường không triệu chứng; nhiều: bồn chồn, khó thở tăng khi nằm, đau ngực; nhịp nhanh, tiếng tim mờ, **mạch đảo** (huyết áp tâm thu giảm > 10 mmHg khi hít sâu), TM cổ nổi, huyết áp giảm. {{QĐ1514 tr.PDF 39}}\n- **Cận lâm sàng**: điện tim (điện thế thấp, luân phiên điện học), X-quang (bóng tim bè rộng), **siêu âm tim** khẳng định, đánh giá đè đẩy các buồng tim; chọc hút làm tế bào học và Cellblock. {{QĐ1514 tr.PDF 39–40}}\n- **Xử trí**: nhẹ, không ép tim: **theo dõi**, không cần chọc. Nhiều, có ép tim: nửa ngồi, oxy, theo dõi huyết áp; **chọc hút/ dẫn lưu qua da dưới siêu âm** (dưới mũi xương ức hoặc khoang liên sườn trái); thận trọng loạn nhịp, tụt huyết áp, tràn khí màng phổi, rách cơ tim. {{QĐ1514 tr.PDF 40}}\n- **Nong màng tim bằng bóng** qua da; **phẫu thuật** (cửa sổ/ cắt màng tim) khi phức tạp hoặc tái phát nhanh. {{QĐ1514 tr.PDF 40}}\n- Nội khoa phối hợp: bồi phụ dịch, vận mạch nếu tụt huyết áp, hỗ trợ thông khí; sau dẫn lưu có thể bơm 5-FU hoặc thiotepa vào màng tim. {{QĐ1514 tr.PDF 41}}\n- Nguyên nhân hay gặp nhất: ung thư phổi, vú, u hắc tố ác tính. {{QĐ1514 tr.PDF 40}}\n@@tab Tràn dịch màng phổi ác tính\n- **Nhận diện**: khó thở, đau tức ngực, ho; hội chứng 3 giảm; ít thì có thể không triệu chứng. {{QĐ1514 tr.PDF 37}}\n- **Cận lâm sàng**: X-quang phổi thẳng nghiêng, CT/ PET-CT ngực, **chọc hút** làm vi khuẩn và tế bào học, Cellblock; **sinh thiết màng phổi** giúp chẩn đoán ở ==20%== ca tế bào học âm tính. {{QĐ1514 tr.PDF 37–38}}\n- **Cấp cứu khi tràn dịch nhiều gây suy hô hấp**: **oxy** 3–4 l/phút (nặng thì đặt nội khí quản, thông khí nhân tạo), **chọc hút hoặc dẫn lưu** ngực. {{QĐ1514 tr.PDF 38}}\n- Làm dính màng phổi: bleomycin, **talc 5 g** (qua nội soi màng phổi), doxycyclin 500 mg (kèm lidocain); bơm sau khi rút hết dịch, chụp X-quang kiểm tra. Tái phát nhanh: mở màng phổi tối thiểu đặt ống dẫn lưu. {{QĐ1514 tr.PDF 38–39}}\n@@end\n\n- Chẩn đoán phân biệt TDMP: phù phổi cấp, viêm phổi, xẹp phổi, lao phổi. {{QĐ1514 tr.PDF 38}}\n- **Nhập viện/ chuyển tuyến**: tài liệu không nêu tiêu chuẩn riêng; thủ thuật chọc dẫn lưu, nong bóng, mở màng tim cần chuyên khoa.\n- Y5 chỉ nêu tràn dịch màng phổi/ màng tim ác tính là tiêu chuẩn giai đoạn IV (ung thư phổi) và nguyên nhân khó thở; **không nêu cách xử trí**. {{Y5 tr.109}} {{Y5 tr.113}}\n\n### 5. Bít tắc đường thở\n\n> [!red] Bít tắc đường thở trên (khoang miệng, thanh quản, hạ họng) hoặc dưới (phế quản, trung thất): đặt nội khí quản thường **khó** vì chít hẹp, cân nhắc **chọc kim lớn qua màng nhẫn giáp**. {{QĐ1514 tr.PDF 81, 85}}\n\n- **Nhận diện**: khối u gây bít tắc đường thở cao (khoang miệng, thanh quản, hạ họng) hoặc thấp (phế quản, trung thất, di căn phổi); là một nguyên nhân suy hô hấp cấp. {{QĐ1514 tr.PDF 81}} Y5: ung thư hạ thanh môn phát hiện trễ với **tiếng rít hoặc khó thở thanh quản**; khó thở còn do tắc nghẽn khí phế quản. {{Y5 tr.135}} {{Y5 tr.109}}\n- **Cận lâm sàng cần làm**: định nghĩa suy hô hấp cấp dựa vào **khí máu động mạch**; nhanh chóng xác định nguyên nhân. {{QĐ1514 tr.PDF 81, 85}} Chi tiết hình ảnh riêng cho tắc nghẽn đường thở: tài liệu không nêu.\n- **Trong khi vận chuyển**: bệnh nhân tỉnh ngồi hoặc nằm; hôn mê thì đặt canuyn Mayo, nội khí quản; bóp bóng/ thở máy oxy ==4–8== l/phút. {{QĐ1514 tr.PDF 85}}\n- **Corticoid**: u chèn ép khí phế quản, trung thất hoặc phù nề thanh môn: methylprednisolon ==0,5–1== mg/kg tiêm TM. {{QĐ1514 tr.PDF 85}}\n- **Tại bệnh viện**: oxy mask 10–12 l/phút hoặc 100% qua nội khí quản; nội khí quản khi suy hô hấp nặng, nguy kịch; **mở khí quản** khi thở máy kéo dài (u hạ họng thanh quản, khoang miệng). {{QĐ1514 tr.PDF 85}}\n- **Giải ép nguyên nhân**: phẫu thuật cắt u, **xạ trị** u chèn ép, **đặt stent khí quản**; methylprednisolon 0,5–1,5 mg/kg tiêm TM chống chèn ép. {{QĐ1514 tr.PDF 86}}\n- **Xạ trị cấp cứu** khi chèn ép đường thở: xem phác đồ ở mục 1. {{QĐ1514 tr.PDF 70}}\n- **Nhập viện/ chuyển tuyến**: tài liệu không nêu tiêu chuẩn riêng; thông khí xâm nhập khi tắc nghẽn đường hô hấp trên, không bảo vệ được đường thở. {{QĐ1514 tr.PDF 86}}\n\n### 6. Bảng so sánh nhanh\n\n| Cấp cứu | Cận lâm sàng đầu tiên | Thuốc/ can thiệp nổi bật | Giải ép lâu dài |\n|---|---|---|---|\n| TM chủ trên | CT ngực, Doppler TM | Oxy; methylprednisolon 40 mg TM | **Stent**, xạ trị cấp cứu, hóa trị nếu nhạy {{QĐ1514 tr.PDF 69–70}} |\n| Tủy sống/ đuôi ngựa | **MRI cột sống ≤ 24 giờ** | **Dexamethason 4–8 ống 4 mg/6 giờ** | Xạ trị, phẫu thuật {{QĐ1514 tr.PDF 59, 62}} |\n| Tăng áp lực nội sọ | **CT sọ não** | Đầu cao 30 độ, manitol, dexamethason 8 mg rồi 4 mg/6 giờ | Phẫu thuật, xạ trị/ xạ phẫu {{QĐ1514 tr.PDF 55–57}} |\n| Tràn dịch màng tim | **Siêu âm tim** | Chọc dẫn lưu dưới siêu âm | Nong bóng, phẫu thuật {{QĐ1514 tr.PDF 40}} |\n| Tràn dịch màng phổi | X-quang, CT ngực | Oxy; chọc hút/ dẫn lưu | Làm dính màng phổi {{QĐ1514 tr.PDF 38}} |\n| Bít tắc đường thở | Khí máu động mạch | Methylprednisolon; nội khí quản/ mở khí quản | Xạ trị, **stent khí quản** {{QĐ1514 tr.PDF 85–86}} |\n\n### Điểm hay thi\n> [!warn]\n> - **TM chủ trên**: có khò khè/ tổn thương đường thở/ chèn ép thần kinh trung ương thì **stent trước, xạ trị sau**; ung thư nhạy hóa chất (**SCLC, NHL, u tế bào mầm, vú**) thì hóa trị ngay.\n> - **Chèn ép tủy**: đau trước (==80–90%==), **MRI toàn bộ cột sống trong 24 giờ**, **dexamethason 4–8 ống 4 mg/6 giờ**, xạ trị là lựa chọn đầu tiên.\n> - **Đuôi ngựa**: đau rễ hai chân, yếu hai chân, rối loạn cơ tròn; tủy tận cùng ngang **L1**.\n> - **Tăng áp lực nội sọ**: **CT sọ não** đầu tiên; đầu cao 30 độ; manitol **không quá 72 giờ**; dexamethason 8 mg rồi 4 mg/6 giờ; Glasgow < 8 là hôn mê sâu.\n> - **Tràn dịch màng tim có ép tim**: chọc dẫn lưu dưới siêu âm; không ép tim thì chỉ theo dõi.\n> - **Mạch đảo**: huyết áp tâm thu giảm > 10 mmHg khi hít sâu.\n> - Đặt nội khí quản khó ở u khoang miệng, hạ họng, thanh quản: cân nhắc chọc kim qua màng nhẫn giáp.\n\n### Tự kiểm tra\n- Chèn ép TM chủ trên có khò khè hoặc chèn ép thần kinh trung ương: ưu tiên can thiệp nào? :: Đặt stent TM rồi xạ trị. {{QĐ1514 tr.PDF 69}}\n- Liều xạ trị cấp cứu khi chèn ép đường thở (TM chủ trên) theo QĐ1514? :: 2 Gy x 20, 3 Gy x 10 hoặc 4 Gy x 5 buổi. {{QĐ1514 tr.PDF 70}}\n- Cận lâm sàng cần làm sớm nhất khi nghi chèn ép tủy? :: MRI toàn bộ cột sống, trong vòng 24 giờ. {{QĐ1514 tr.PDF 59}}\n- Corticoid trong chèn ép tủy do di căn cột sống? :: Dexamethason 4 mg x 4–8 ống, mỗi 6 giờ. {{QĐ1514 tr.PDF 62}}\n- Biểu hiện của hội chứng đuôi ngựa? :: Đau kiểu rễ hai chân, yếu hai chân, mất cảm giác hai chân, rối loạn cơ tròn. {{QĐ1514 tr.PDF 59}}\n- Thăm dò hình ảnh đầu tiên khi nghi tăng áp lực nội sọ ở bệnh nhân ung thư? :: CT sọ não (chụp được cấp cứu). {{QĐ1514 tr.PDF 54}}\n- Giới hạn thời gian dùng manitol trong phù não do u? :: Không quá 72 giờ. {{QĐ1514 tr.PDF 56}}\n- Tràn dịch màng tim nào chỉ cần theo dõi? :: Số lượng ít và không có ép tim. {{QĐ1514 tr.PDF 40}}\n- Mạch đảo là gì? :: Huyết áp tâm thu giảm thấp hơn 10 mmHg khi hít vào sâu. {{QĐ1514 tr.PDF 39}}\n- Khó khăn khi đặt nội khí quản ở bệnh nhân u hạ họng thanh quản, hướng xử lý? :: Cân nhắc chọc kim lớn qua màng nhẫn giáp. {{QĐ1514 tr.PDF 85}}"}, {"kind": "foundation", "disease": "", "short": "Cấp cứu chuyển hóa – huyết học", "group": "", "section": 6, "order": 1, "khung": [], "id": "ung-thu-cap-cuu-chuyen-hoa-huyet-hoc", "title": "Cấp cứu ung thư chuyển hóa và huyết học", "layer": "dieutri", "module": "ung-buou", "tags": ["cấp cứu ung thư", "tăng canxi máu", "hội chứng ly giải u", "sốt giảm bạch cầu hạt", "thuyên tắc huyết khối tĩnh mạch", "hạ đường huyết", "SIADH", "G-CSF", "rasburicase"], "source": "QĐ1514 tr.PDF 16–18, 19–21, 23–25, 26–30, 88–95, 243; Y5 tr.20, 106–107, 109–110", "body": "> [!key] Tóm tắt\n> - QĐ1514 có **4 bài cấp cứu** về chuyển hóa – huyết học: **ly giải u**, **hôn mê hạ đường huyết**, **tăng calci huyết**, **sốt do giảm bạch cầu**; thêm bài **dự phòng thuyên tắc huyết khối tĩnh mạch (TTHKTM)**. {{QĐ1514 tr.PDF 16}} {{QĐ1514 tr.PDF 88}}\n> - **Tăng calci máu**: calci toàn phần ≥ ==2,6–2,7== mmol/l; điều trị khi > ==3== mmol/l; **không dùng digoxin**. {{QĐ1514 tr.PDF 23}}\n> - **Ly giải u**: tăng kali, phospho, acid uric, **hạ calci**, suy thận; phòng bằng **dịch + rasburicase/ allopurinol**. {{QĐ1514 tr.PDF 16–17}}\n> - **Sốt giảm bạch cầu hạt**: sốt kèm BCĐNTT < ==0,5== G/L; **kháng sinh phổ rộng ngay**. {{QĐ1514 tr.PDF 26, 28}}\n> - **SIADH** chỉ được nhắc như hội chứng cận u của SCLC; **xử trí hạ natri: tài liệu không nêu**. {{Y5 tr.106}}\n> - Chuyển tuyến/ nhập viện: nguồn **không có tiêu chí riêng** cho các bài này; xem nguyên tắc chung ở [[ung-thu-chuyen-tuyen]].\n\n### 1. Tăng calci máu\n\n> [!red] Tăng calci huyết là cấp cứu; tiên lượng sống phụ thuộc biến chứng tim mạch. **Không dùng digitalis/ digoxin** vì dễ ngừng tim đột ngột. {{QĐ1514 tr.PDF 23}}\n\n#### Nhận diện nhanh\n- **Tần suất và ngưỡng**: gặp ==20–30%== bệnh nhân ung thư; calci toàn phần ≥ ==2,6–2,7== mmol/l hoặc calci ion hóa > ==1,3== mmol/l; nặng – nguy kịch khi > ==4–5== mmol/l; bắt đầu có biểu hiện lâm sàng khi > ==3== mmol/l. {{QĐ1514 tr.PDF 23}}\n- **Cơ chế (3)**: di căn xương gây tiêu xương; u tiết chất giống hormon cận giáp; u sản xuất **1,25-dihydroxy vitamin D**. {{QĐ1514 tr.PDF 23}}\n- **Lâm sàng không đặc hiệu** (mệt, rối loạn tiêu hóa, đổi hành vi) nên hay chẩn đoán sai nếu không **định lượng calci máu**. {{QĐ1514 tr.PDF 23}}\n\n| Hệ cơ quan | Biểu hiện |\n|---|---|\n| Thần kinh | Đau cơ, chuột rút, co cứng cơ, liệt gốc chi, trầm cảm, đau đầu, ngủ gà, có thể hôn mê |\n| Tiêu hóa | Chán ăn, buồn nôn, đau bụng (có thể dữ dội như viêm tụy cấp hoặc như tắc ruột), táo bón |\n| Tim mạch | Huyết áp cao, rối loạn nhịp |\n| Thận | Đái nhiều, mất nước, suy thận; có thể thiểu niệu, vô niệu do lắng đọng calci |\n{{QĐ1514 tr.PDF 23}}\n\n- **Điện tim**: PR kéo dài, QT ngắn; loạn nhịp (rung nhĩ, rung thất, block nhĩ thất), ngừng tim khi calci > ==7,5== mmol/l. {{QĐ1514 tr.PDF 23}}\n- **Xét nghiệm khác**: albumin, protein máu giảm; creatinin tăng. {{QĐ1514 tr.PDF 24}}\n- **Ung thư hay gặp**: u hệ tạo huyết; u tiết peptid giống PTH (buồng trứng, thận, phổi, vú, đầu cổ, bàng quang); **đa u tủy**; di căn xương. {{QĐ1514 tr.PDF 24}}\n- **Theo Y5 (ung thư phổi)**: tế bào gai có tăng calci máu do peptide liên quan PTH **thường gặp nhất**; SCLC thì tăng calci **hiếm**. {{Y5 tr.106}} {{Y5 tr.107}}\n- **Chẩn đoán phân biệt**: mất nước, suy thận do nguyên nhân khác; rối loạn ý thức do tổn thương thần kinh hoặc chuyển hóa. {{QĐ1514 tr.PDF 24}}\n\n#### Xử trí ban đầu\n@@tabs\n@@tab Mức độ và tăng thải calci\n- **Nhẹ – vừa**: chưa cần điều trị; nghỉ ngơi, ít vận động, ăn ít calci, truyền dịch và lợi tiểu. {{QĐ1514 tr.PDF 24}}\n- **> 3 mmol/l**: bồi phụ thể tích nhanh bằng **NaCl 0,9%** hoặc glucose 5% pha KCl 0,5 g, tốc độ ==200–300== ml/giờ; thận trọng ở bệnh nhân suy tim, suy thận. {{QĐ1514 tr.PDF 24}}\n- **Magie sulfat** 1 g cho mỗi lít NaCl 0,9%. {{QĐ1514 tr.PDF 24}}\n- **Furosemide** 40–80 mg tĩnh mạch mỗi 2–4 giờ, **sau khi** bù đủ thể tích và huyết động ổn định; theo dõi mất muối, điện giải. {{QĐ1514 tr.PDF 24}}\n@@tab Giảm hấp thu và gắn vào xương\n- Không đưa nhiều calci qua đường tiêu hóa (ăn cá, xương). {{QĐ1514 tr.PDF 24}}\n- **Corticoid** nếu thừa vitamin D: solumedrol 40 mg tĩnh mạch 1–2 ống/ngày. {{QĐ1514 tr.PDF 24}}\n- **Calcitonin** 4–8 đơn vị/kg truyền tĩnh mạch 6–8 giờ, theo dõi calci máu; có thể nhắc lại mỗi 6–12 giờ. {{QĐ1514 tr.PDF 25}}\n- **Bisphosphonat**: pamidronat 60–90 mg, tốc độ không quá 60 mg/giờ, tác dụng sau ==1–2== ngày; acid zoledronic truyền tĩnh mạch 3–4 tuần/lần. {{QĐ1514 tr.PDF 25}}\n- **Prednisolon** 20–40 mg/ngày có hiệu quả nếu do u lympho hoặc đa u tủy. {{QĐ1514 tr.PDF 25}}\n- EDTA natri 50 mg/kg truyền 4–6 giờ; gallium nitrat cho ca khó điều trị, thận trọng độc thận. {{QĐ1514 tr.PDF 24}} {{QĐ1514 tr.PDF 25}}\n@@end\n\n#### Khi nào nhập viện hoặc chuyển tuyến\n- **Lọc màng bụng hoặc thận nhân tạo**: tăng calci máu nặng không đáp ứng các điều trị trên, hoặc có suy thận, phù phổi. {{QĐ1514 tr.PDF 24}}\n- Tiêu chí nhập viện hay chuyển tuyến khác: tài liệu không nêu.\n\n### 2. Hội chứng ly giải u\n\n> [!red] Ly giải u là cấp cứu nội khoa: có thể dẫn đến **rung thất và ngừng tim đột ngột**. Cách điều trị tốt nhất là **phòng ngừa**. {{QĐ1514 tr.PDF 16}} {{QĐ1514 tr.PDF 17}}\n\n#### Nhận diện nhanh\n- **Cơ chế**: lượng lớn tế bào u bị ly giải, giải phóng **kali, phospho, acid nhân**; acid nhân dị hóa thành **acid uric**, thải qua ống thận gây **suy thận cấp**; phospho cao cũng góp phần. {{QĐ1514 tr.PDF 16}}\n- **Bối cảnh**: thường sau điều trị gây độc tế bào; hay gặp ở **NHL ác tính cao**, **bạch cầu cấp dòng lympho hoặc dòng tủy**, u phát triển nhanh, u lớn, ung thư nhạy trị liệu; có thể **tự phát**. {{QĐ1514 tr.PDF 16}} {{QĐ1514 tr.PDF 17}}\n- **Lâm sàng**: buồn nôn, tiêu chảy, chán ăn, ngủ lịm, đái máu, thiểu/ vô niệu, co cứng cơ, co giật, suy tim, rối loạn nhịp. {{QĐ1514 tr.PDF 16}}\n- **Điện tim (tăng kali)**: T cao nhọn đối xứng, QRS giãn rộng, nhịp nhanh thất hoặc rung thất. {{QĐ1514 tr.PDF 16}}\n\n| Xét nghiệm | Ngưỡng |\n|---|---|\n| Acid uric | ≥ ==8== mg/dl (476 µmol/l) hoặc tăng 25% |\n| Kali | ≥ ==6== mmol/l hoặc tăng 25% |\n| Phospho | ≥ ==6,5== mg/dl (trẻ em); ≥ ==4,5== mg/dl (người lớn) hoặc tăng > 25% |\n| Calci | ≤ ==7== mg/dl hoặc giảm 25% |\n| Chức năng thận | Ure, creatinin tăng cao |\n{{QĐ1514 tr.PDF 16}}\n\n#### Xử trí ban đầu\n- **Truyền dịch đẳng trương** (NaCl 0,9% hoặc ringer lactat) 3–4 lít/ngày để nước tiểu ==80–100== ml/giờ; **furosemide** 20–40 mg tĩnh mạch; theo dõi sát điện giải và cân bằng nước (tránh phù phổi cấp, suy tim, hạ kali). {{QĐ1514 tr.PDF 17}}\n- **Giảm acid uric**: **rasburicase** 0,2 mg/kg truyền 30 phút, 1 lần/ngày, tối đa 5 ngày, hoặc **allopurinol** 300 mg uống 2–3 viên/ngày. {{QĐ1514 tr.PDF 17}}\n- **Tăng kali kèm hạ calci**: tiêm **calci clorua** 0,5 g tĩnh mạch 1–2 ống, nhắc lại đến khi kali bình thường; truyền **natri bicarbonat** tĩnh mạch. {{QĐ1514 tr.PDF 17}}\n\n| Nhóm nguy cơ | Ví dụ | Xử trí |\n|---|---|---|\n| **Thấp** | NHL tiến triển chậm; bạch cầu mạn dòng tủy hoặc lympho | Truyền dịch 2–3 lít/ngày; có thể furosemide 20 mg tĩnh mạch; **chỉ truyền dịch và theo dõi sát** |\n| **Trung bình** | NHL lan tỏa tế bào lớn; bạch cầu cấp dòng lympho không B có bạch cầu 50–100 G/L; bạch cầu cấp dòng tủy 10–100 G/L | **Allopurinol** 0,3 g, 2–3 viên/ngày; calci clorua hoặc natri bicarbonat 1,4% |\n| **Cao – nặng** | Burkitt; bạch cầu cấp dòng lympho ≥ 100 G/L; dòng tủy ≥ 50 G/L; u lớn, gan lách to, hạch trung thất > 5 cm | **Rasburicase** ưu tiên (người lớn và trẻ em); hạ kali nhanh bằng calci clorua, natri bicarbonat 1,4%, đường ưu trương pha insulin |\n{{QĐ1514 tr.PDF 17}} {{QĐ1514 tr.PDF 18}}\n\n#### Khi nào nhập viện hoặc chuyển tuyến\n- **Lọc máu ngoài thận** (thận nhân tạo hoặc lọc màng bụng) khi điều trị nội khoa thất bại; làm **ngay** ở nhóm nguy cơ cao nếu tăng kali, toan chuyển hóa, suy thận nặng lên. {{QĐ1514 tr.PDF 17}} {{QĐ1514 tr.PDF 18}}\n- Tiêu chí chuyển tuyến cụ thể: tài liệu không nêu.\n\n### 3. Sốt do giảm bạch cầu hạt\n\n> [!red] Bệnh nhân **đang hóa trị có giảm bạch cầu** (kể cả **không sốt**) cần **kháng sinh phổ rộng ngay lập tức**. Người cao tuổi hoặc dùng corticoid kéo dài có thể nhiễm trùng mà **không sốt**. {{QĐ1514 tr.PDF 26}} {{QĐ1514 tr.PDF 28}}\n\n#### Nhận diện nhanh\n- **Định nghĩa**: sốt (miệng ≥ ==38,3== °C một lần, hoặc ≥ ==38== °C kéo dài trên 1 giờ) kèm **BCĐNTT < 0,5 G/L**, hoặc < 1 G/L và dự đoán ≤ 0,5 G/L trong 48 giờ tới. {{QĐ1514 tr.PDF 26}}\n- **Biểu hiện**: sốt 38–39 °C liên tục, môi khô, lưỡi bẩn, toàn thân suy sụp; loét niêm mạc miệng họng; ổ nhiễm hô hấp, tiêu hóa, tiết niệu, da, thần kinh (viêm màng não, co giật, hôn mê). {{QĐ1514 tr.PDF 26}}\n- **Chỉ tìm được ổ nhiễm** ở khoảng ==30%==; chủ yếu vi khuẩn Gram âm, Gram dương, kỵ khí, nấm, virus (nhất là Herpes). {{QĐ1514 tr.PDF 27}}\n- **Cận lâm sàng**: công thức máu, hóa sinh, **cấy máu ngay** (nhiều lần, nhiều vị trí), cấy bệnh phẩm; **X-quang phổi ngay** khi vào viện; chọc dò tủy sống nếu đổi ý thức hoặc dấu thần kinh khu trú. {{QĐ1514 tr.PDF 27}}\n\n| Độ | I | II | III | IV |\n|---|---|---|---|---|\n| BCĐNTT (G/L) | 1,5 – < 2 | 1 – < 1,5 | 0,5 – < 1 | < 0,5 |\n| Nguy cơ nhiễm trùng | Thấp | Trung bình | Cao | Rất cao |\n{{QĐ1514 tr.PDF 27}} {{QĐ1514 tr.PDF 28}}\n\n#### Xử trí ban đầu\n- **Kháng sinh** theo kinh nghiệm, ưu tiên **đường tĩnh mạch**, chỉnh liều theo thanh thải creatinin, chọn theo yếu tố nguy cơ, tiền sử dị ứng, ổ nghi ngờ, dữ liệu vi khuẩn của bệnh viện; xuống thang. {{QĐ1514 tr.PDF 28}}\n- **Chưa rõ ổ nhiễm**: carbapenem hoặc piperacilin–tazobactam, có thể phối hợp quinolon, aminoglycosid hoặc fosmycin; thêm vancomycin/ teicoplanin/ daptomycin nếu nghi **MRSA**. {{QĐ1514 tr.PDF 29}}\n- **Chống nấm theo kinh nghiệm** khi sốt kéo dài **> 5 ngày** dù đã dùng kháng sinh phổ rộng. {{QĐ1514 tr.PDF 29}}\n- **Thay sonde, tháo buồng tiêm truyền** nếu nghi nhiễm trùng; **đánh giá lại sau 48 giờ**; ngừng tùy bạch cầu trung tính phục hồi (≥ 0,5 G/L) và tình trạng sốt. {{QĐ1514 tr.PDF 30}}\n- **G-CSF** khi hóa trị có giảm BCĐNTT **độ III–IV**: filgrastim 300 µg dưới da 1–2 ống/ngày đến khi BCĐNTT bình thường; xét nghiệm công thức bạch cầu 1 lần/ngày (độ I–II), 2 lần/ngày (độ III–IV). {{QĐ1514 tr.PDF 30}}\n- **Truyền khối bạch cầu** (cùng nhóm) khi hạ bạch cầu từ độ II trở lên hoặc G-CSF không hiệu quả mà lâm sàng nặng lên; dùng methylprednisolon 40–80 mg tĩnh mạch trước truyền. {{QĐ1514 tr.PDF 30}}\n- **Hỗ trợ**: bù nước điện giải; paracetamol 0,5 g khi sốt > 38,5 °C, mỗi 4–6 giờ. {{QĐ1514 tr.PDF 30}}\n\n#### Khi nào nhập viện hoặc chuyển tuyến\n- Nguồn mô tả điều trị trong bối cảnh nội trú (thăm khám hàng ngày, theo dõi bạch cầu 1–2 lần/ngày) nhưng **không nêu tiêu chí nhập viện hay chuyển tuyến**. {{QĐ1514 tr.PDF 26}} {{QĐ1514 tr.PDF 30}}\n- Phác đồ ngoại trú/ uống kháng sinh tại nhà: tài liệu không nêu.\n\n### 4. Thuyên tắc huyết khối tĩnh mạch\n\n> [!red] TTHKTM là biến chứng **đe dọa tính mạng**, nguyên nhân tử vong **hàng thứ hai** ở người bệnh ung thư, và có thể là triệu chứng **nhiều tháng đến nhiều năm trước** khi chẩn đoán ung thư. {{QĐ1514 tr.PDF 88}}\n\n#### Nhận diện nhanh\n- **Khái niệm**: gồm **huyết khối tĩnh mạch sâu** và **thuyên tắc động mạch phổi**; gặp ==20%== bệnh nhân ung thư, nguy cơ tăng ==4–7== lần, tăng gấp 3 lần số ca nhập viện. {{QĐ1514 tr.PDF 88}}\n- **Yếu tố nguy cơ** (4 nhóm): bệnh nhân (tuổi, béo phì, tiền sử TTHKTM), khối u (vị trí, giai đoạn, mô học), điều trị (phẫu thuật lớn, nhập viện, hóa trị, hormon, **catheter trung tâm**), dấu ấn sinh học (tiểu cầu, bạch cầu, Hb, D-dimer, CRP). {{QĐ1514 tr.PDF 88}} {{QĐ1514 tr.PDF 89}}\n- **Tamoxifen** tăng nguy cơ huyết khối. {{Y5 tr.20}}\n- **Cận u** (Y5): tăng đông gặp ở SCLC, carcinôm tế bào gai và tuyến của phổi. {{Y5 tr.106}} {{Y5 tr.107}}\n- Dấu hiệu lâm sàng, chẩn đoán hình ảnh, xét nghiệm khẳng định huyết khối/ thuyên tắc phổi: tài liệu không nêu.\n\n| Thang | Dùng cho | Ngưỡng |\n|---|---|---|\n| **PADUA** | Ung thư nội khoa nội trú | < 4 thấp, không dự phòng; ≥ 4 cao, cần dự phòng {{QĐ1514 tr.PDF 90}} |\n| **Khorana** | Ung thư ngoại trú hóa trị | 0 thấp; 1–2 trung bình; ≥ 3 cao (nguy cơ 7,1–41%) {{QĐ1514 tr.PDF 90}} |\n| **IMPROVE** | Nguy cơ chảy máu | Tổng ≥ 7: nguy cơ chảy máu nặng {{QĐ1514 tr.PDF 91}} |\n| **Caprini** | Ung thư phẫu thuật | 0–1 thấp; 2 trung bình; 3–4 cao; ≥ 5 rất cao {{QĐ1514 tr.PDF 93}} |\n\n#### Xử trí ban đầu\nNguồn chỉ trình bày **dự phòng**, không có phác đồ điều trị TTHKTM đã xảy ra (liều chống đông điều trị, tiêu sợi huyết): tài liệu không nêu.\n\n- **Chung**: vận động sớm, thường xuyên; cơ học (bơm hơi ngắt quãng, tất chun 16–20 mmHg). {{QĐ1514 tr.PDF 94}}\n- **Thuốc**: enoxaparin 40 mg dưới da/ngày; dalteparin 5.000 đơn vị/ngày; fondaparinux 2,5 mg/ngày; UFH 5.000 đơn vị mỗi 8–12 giờ. **Chưa khuyến cáo** thuốc chống đông đường uống thế hệ mới để dự phòng. {{QĐ1514 tr.PDF 94}} {{QĐ1514 tr.PDF 95}}\n- **Nội trú**: nên dự phòng khi nhập viện vì bệnh nội khoa cấp hoặc hạn chế đi lại, nếu không chống chỉ định. {{QĐ1514 tr.PDF 91}}\n- **Phẫu thuật**: dự phòng hệ thống, ít nhất 7–10 ngày; phẫu thuật bụng – chậu nguy cơ cao: **4 tuần**. {{QĐ1514 tr.PDF 93}}\n- **Ngoại trú**: không dự phòng thường quy; dự phòng cho đa u tủy dùng thalidomide/ lenalidomide, Khorana ≥ 3 hoặc ung thư tụy tiến triển (LMWH). {{QĐ1514 tr.PDF 94}}\n- **Chống chỉ định tuyệt đối thuốc kháng đông**: xuất huyết não, xuất huyết đang tiến triển, tiền sử giảm tiểu cầu do heparin, dị ứng; khi đó dùng biện pháp **cơ học**. {{QĐ1514 tr.PDF 91}}\n- **Biến chứng chảy máu**: nhẹ thì theo dõi; vừa – nặng thì dừng thuốc, trung hòa UFH bằng **protamine** (1 mg trung hòa 100 UI); fondaparinux **không** trung hòa được bằng protamine. {{QĐ1514 tr.PDF 95}}\n\n#### Khi nào nhập viện hoặc chuyển tuyến\nTài liệu không nêu tiêu chí cho TTHKTM đã xảy ra.\n\n### 5. Hạ đường huyết và SIADH\n\n#### Hôn mê hạ đường huyết\n\n> [!red] **Luôn nghĩ đến hạ đường huyết** ở bệnh nhân ung thư hôn mê không rõ nguyên nhân, nhất là giai đoạn muộn. Xử trí sớm thì hồi phục hoàn toàn; muộn thì di chứng thần kinh nặng, thậm chí tử vong. {{QĐ1514 tr.PDF 19}}\n\n**Nhận diện nhanh**\n- **Bối cảnh**: ung thư kèm đái tháo đường, giai đoạn muộn/ suy kiệt/ nuôi dưỡng kém, sau phẫu thuật, xạ trị, hóa trị dài ngày. {{QĐ1514 tr.PDF 19}}\n- **Sớm**: hoa mắt, run, vã mồ hôi, đói, nhịp nhanh, lẫn lộn, rối loạn thị giác. **Muộn**: dị cảm, nhìn đôi, co giật, Babinski (+), hôn mê yên tĩnh. {{QĐ1514 tr.PDF 19}}\n- **Đường máu mao mạch** thường < ==2,8== mmol/l; lâm sàng không phải luôn tương xứng với trị số. {{QĐ1514 tr.PDF 20}}\n- **Thử glucose điều trị**: tỉnh ngay thì ủng hộ; không tỉnh **không loại trừ**. {{QĐ1514 tr.PDF 19}}\n- **Nguyên nhân**: ung thư tiêu hóa (nuôi dưỡng kém), **ung thư tụy/ NET tụy tăng tiết insulin**, ung thư gan suy gan nặng, u thượng thận, quá liều insulin hoặc sulfamid. {{QĐ1514 tr.PDF 20}}\n\n**Xử trí ban đầu**\n- **Ngừng ngay** insulin hoặc sulfamid hạ đường huyết. {{QĐ1514 tr.PDF 20}}\n- **Tỉnh, không dấu thần kinh – tâm thần**: uống nước đường nhanh, sau đó ăn đường chậm (bánh mì, cơm). {{QĐ1514 tr.PDF 21}}\n- **Hôn mê/ có triệu chứng thần kinh**: tiêm **20 ml glucose 30%** tĩnh mạch, nhắc lại sau vài phút đến khi tỉnh. {{QĐ1514 tr.PDF 21}}\n- **Vật vã, không đặt được đường truyền**: tiêm bắp **glucagon 1 mg**, nhắc lại sau 10 phút nếu không đáp ứng. {{QĐ1514 tr.PDF 21}}\n- **Nặng, kéo dài**: truyền glucose 10% (2.000 ml/24 giờ), giữ đường máu > ==5,5== mmol/l, theo dõi liên tục 24 giờ. {{QĐ1514 tr.PDF 21}}\n- **Lấy máu tĩnh mạch xét nghiệm trước khi cho đường**; dùng đường thử cho mọi ca hôn mê chưa rõ nguyên nhân. {{QĐ1514 tr.PDF 20}}\n\n**Khi nào nhập viện hoặc chuyển tuyến**: tài liệu không nêu; chỉ yêu cầu theo dõi 24 giờ và điều trị nguyên nhân (nuôi dưỡng đầy đủ, nuôi dưỡng tĩnh mạch khi không ăn được, điều trị suy gan, cắt u tăng tiết insulin). {{QĐ1514 tr.PDF 21}}\n\n#### SIADH và hạ natri máu\n\n> [!red] SIADH là hội chứng cận u thường gặp nhất của **SCLC** (Y5). Nguồn **không có** biểu hiện, ngưỡng natri, hay cách xử trí; mọi nội dung đó: tài liệu không nêu. {{Y5 tr.106}}\n\n- QĐ1514 liệt kê hội chứng cận u do u tiết chất giống **ADH** gọi là \"đái tháo nhạt\" (mâu thuẫn với SIADH của Y5). {{QĐ1514 tr.PDF 243}}\n- Chi tiết đối chiếu hai nguồn: xem [[ung-thu-hoi-chung-can-u-va-chen-ep]].\n\n### Điểm hay thi\n> [!warn]\n> - **Tăng calci máu**: ngưỡng ≥ 2,6–2,7 mmol/l, lâm sàng khi > 3; **không digoxin**; **bù NaCl 0,9% trước, furosemide sau**; bisphosphonat tác dụng sau 1–2 ngày.\n> - Cơ chế tăng calci: **di căn xương**, **PTH-like**, **1,25-(OH)2 vitamin D**. Phổi: **tế bào gai** thường nhất (Y5).\n> - **Ly giải u**: tăng K, phospho, acid uric, **hạ calci**; nguy cơ cao dùng **rasburicase**, trung bình **allopurinol**, thấp chỉ truyền dịch.\n> - Ly giải u điển hình: **NHL ác tính cao, bạch cầu cấp**; thất bại nội khoa thì **lọc máu**.\n> - **Sốt giảm bạch cầu hạt**: BCĐNTT < 0,5 G/L; kháng sinh phổ rộng **ngay**; G-CSF khi độ III–IV; chống nấm khi sốt > 5 ngày.\n> - **TTHKTM**: gặp 20%, nguy cơ tăng 4–7 lần; PADUA ≥ 4, Khorana ≥ 3 thì dự phòng; không dùng thuốc chống đông đường uống mới để dự phòng.\n> - **Hôn mê hạ đường huyết**: glucose 30% 20 ml tĩnh mạch hoặc glucagon 1 mg tiêm bắp; nghĩ tới **ung thư tụy/ NET tụy**.\n> - **SIADH** là cận u của SCLC theo Y5; QĐ1514 không bàn xử trí hạ natri.\n\n### Tự kiểm tra\n- Ngưỡng calci máu toàn phần để chẩn đoán tăng calci máu ở bệnh nhân ung thư? :: ≥ 2,6–2,7 mmol/l (ion hóa > 1,3 mmol/l); điều trị khi > 3 mmol/l.\n- Thuốc nào chống chỉ định khi tăng calci máu và vì sao? :: Digitalis/ digoxin, vì dễ gây ngừng tim đột ngột.\n- Thứ tự dịch và lợi tiểu trong tăng calci máu? :: Bù dịch đẳng trương trước (200–300 ml/giờ), furosemide sau khi đủ thể tích và huyết động ổn định.\n- Ba cơ chế tăng calci máu trong ung thư? :: Di căn xương tiêu xương; u tiết chất giống PTH; u sản xuất 1,25-dihydroxy vitamin D.\n- Bốn rối loạn xét nghiệm của hội chứng ly giải u? :: Tăng acid uric, tăng kali, tăng phospho, hạ calci (kèm suy thận).\n- Chọn thuốc giảm acid uric theo nhóm nguy cơ ly giải u? :: Cao: rasburicase; trung bình: allopurinol; thấp: chỉ truyền dịch và theo dõi.\n- Khi nào lọc máu ngoài thận trong ly giải u? :: Điều trị nội khoa thất bại (nhóm cao: làm ngay nếu tăng kali, toan chuyển hóa, suy thận nặng lên).\n- Định nghĩa sốt giảm bạch cầu hạt? :: Sốt ≥ 38,3 °C một lần hoặc ≥ 38 °C trên 1 giờ kèm BCĐNTT < 0,5 G/L (hoặc < 1 G/L và dự đoán ≤ 0,5 trong 48 giờ).\n- G-CSF dùng khi nào và liều? :: Giảm BCĐNTT độ III–IV khi hóa trị; filgrastim 300 µg dưới da 1–2 ống/ngày đến khi bình thường.\n- Xử trí hôn mê hạ đường huyết khi không đặt được đường truyền? :: Tiêm bắp glucagon 1 mg, nhắc lại sau 10 phút nếu không đáp ứng."}, {"kind": "foundation", "disease": "", "short": "Cấp cứu xuất huyết – hô hấp – thận", "group": "", "section": 6, "order": 3, "khung": [], "id": "ung-thu-cap-cuu-xuat-huyet-ho-hap-than", "title": "Cấp cứu ung thư: xuất huyết, hô hấp, thận và bụng", "layer": "dieutri", "module": "ung-buou", "tags": ["cấp cứu ung thư", "ho ra máu", "xuất huyết tiêu hóa", "suy hô hấp cấp", "suy thận cấp sau thận", "tắc ruột", "thủng tạng rỗng", "xử trí ban đầu"], "source": "QĐ1514 tr. PDF 64–67, 71–74, 76–79, 81–86, 435, 513–514, 529, 595; Y5 tr. 58, 61, 68, 109, 244, 256, 262; SY5 tr. 8", "body": "> [!key] Tóm tắt\n> - Bốn cấp cứu chính: **ho ra máu**, **xuất huyết tiêu hóa (XHTH)**, **suy hô hấp cấp**, **suy thận cấp** (do ung thư). Nguyên tắc chung: **xử trí triệu chứng trước** (mất máu, sặc, thiếu oxy, tăng kali), **điều trị nguyên nhân sau** khi ổn định. {{QĐ1514 tr.PDF 65, 72, 79, 84}}\n> - Ho ra máu: nặng khi > ==200== ml/24 giờ; > ==500== ml có thể nguy kịch; **sét đánh** = đột ngột, lượng lớn. {{QĐ1514 tr.PDF 64}}\n> - XHTH nặng: huyết áp tâm thu < ==90== mmHg, mất > ==500== ml, Hb < ==70== g/l. {{QĐ1514 tr.PDF 72}}\n> - Suy hô hấp cấp **nguy kịch**: thở > ==40== hoặc < ==10== lần/phút, rối loạn huyết động, rối loạn ý thức: **can thiệp thở máy ngay**, thuốc sau. {{QĐ1514 tr.PDF 82}}\n> - Suy thận cấp **sau thận**: u/ hạch chèn đường bài xuất, giải quyết bằng **dẫn lưu, stent niệu quản (JJ)**; tăng kali > ==6== mmol/l là chỉ định lọc máu sớm. {{QĐ1514 tr.PDF 77–79}}\n> - Nhận diện chèn ép và hội chứng cận u: xem [[ung-thu-hoi-chung-can-u-va-chen-ep]]; bài này tập trung **xử trí**.\n\n### 1. Ho ra máu do ung thư\n\n**Định nghĩa**: khạc ra máu trong và sau khi ho, máu ra bằng miệng hoặc mũi, tổn thương từ **thanh quản trở xuống**. Nguy cơ tử vong do **mất máu cấp** và **suy hô hấp cấp do tắc nghẽn hoặc sặc đường thở**. {{QĐ1514 tr.PDF 64}}\n\n#### Mức độ nặng\n| Mức độ | Lượng máu / biểu hiện |\n|---|---|\n| **Ít** | Dây máu hoặc đờm lẫn máu, < ==50== ml/24 giờ, huyết động không ảnh hưởng |\n| **Trung bình** | ==50–200== ml/24 giờ, mạch có thể nhanh |\n| **Nặng** | > ==200== ml/24 giờ; > ==500== ml/24 giờ có thể nguy kịch |\n| **Sét đánh** | Đột ngột, lượng lớn: ngập máu phế nang, ngạt thở, sốc mất máu, tử vong |\n{{QĐ1514 tr.PDF 64}}\n\n#### Nhận diện nhanh\n- Cần **hỏi bệnh và khám kỹ** để xác định đúng mức độ; phân biệt với **nôn ra máu sau một trận ho dài**. {{QĐ1514 tr.PDF 64}}\n- Nguyên nhân hay gặp: ung thư **đầu mặt cổ** (hạ họng, thanh quản, khí quản); ung thư **phổi** vùng rốn phổi hoặc xâm lấn mạch lớn; ung thư thực quản, u trung thất có thể vỡ vào khí phế quản. {{QĐ1514 tr.PDF 65}}\n- Ở phổi, ho ra máu gặp trong tổn thương **trung tâm** (cùng ho, khó thở, thở rít). {{Y5 tr.109}}\n- Cận lâm sàng cấp: công thức máu, đông máu, nhóm máu, X-quang/ CT ngực; loại trừ lao, giãn phế quản, bệnh van tim, nhồi máu phổi. {{QĐ1514 tr.PDF 64}}\n\n#### Xử trí ban đầu\n@@tabs\n@@tab Nhẹ\n- Giải thích, trấn an; **nằm nghỉ tuyệt đối**, ăn lỏng, uống nước mát. {{QĐ1514 tr.PDF 65}}\n- **Diazepam** 5 mg uống hoặc 10 mg tiêm bắp. {{QĐ1514 tr.PDF 65}}\n- **Acid tranexamic** 250 mg tĩnh mạch, 1–2 ống/lần, 1–2 lần/ngày khi cấp cứu; ổn định chuyển uống 500 mg × 2–4 viên/ngày. {{QĐ1514 tr.PDF 65}}\n@@tab Trung bình\n- Chỉ định khi lượng máu > ==150== ml: **Glanduitrine** 5 đơn vị tiêm bắp, **không tiêm tĩnh mạch** (co thắt mạch não đột ngột); hoặc pha 200 ml glucose 5% truyền nhỏ giọt, nhắc lại 3 lần/ngày, thận trọng ở người tăng huyết áp. {{QĐ1514 tr.PDF 65}}\n- Không có Glanduitrine: **morphin** 2 mg tiêm bắp/ tĩnh mạch mỗi 4 giờ (hoặc 5 mg uống nếu chưa giảm đau bằng opioid). Phối hợp **sandostatin**. {{QĐ1514 tr.PDF 66}}\n- Mất máu nặng: dịch cao phân tử hoặc truyền máu, giữ huyết áp tối đa **không < 110 mmHg**. {{QĐ1514 tr.PDF 66}}\n@@tab Nặng và nguy kịch\n- **Đường truyền tĩnh mạch ngay**, dịch đẳng trương (NaCl 0,9% hoặc Ringer lactat). {{QĐ1514 tr.PDF 66}}\n- **Nằm Trendelenburg nghiêng về bên chảy máu**, lau sạch máu mũi miệng; thở oxy 2–6 l/phút; có nguy cơ sặc hoặc suy hô hấp thì **đặt nội khí quản thông khí ngay**. {{QĐ1514 tr.PDF 66}}\n- Truyền máu cùng nhóm; vận mạch nếu tụt huyết áp **sau khi đã bù đủ thể tích** (dopamin hoặc noradrenalin); vasopressin/ glypressin 1 mg mỗi 4 giờ (có thể gây tăng huyết áp, hạ natri máu). {{QĐ1514 tr.PDF 66}}\n- **Soi phế quản ống mềm**: đặt ống có bóng chèn hoặc ống Fogarty, rửa NaCl 0,9% lạnh. {{QĐ1514 tr.PDF 66}}\n- **Nút động mạch phế quản** khi > ==200== ml và thất bại nội khoa. {{QĐ1514 tr.PDF 66}}\n@@end\n\n> [!red] Nguyên tắc ho ra máu\n> Tránh **mất máu cấp, sặc phổi, suy hô hấp** trước; **điều trị nguyên nhân** (phẫu thuật, xạ trị, hóa trị, điều trị đích, miễn dịch) chỉ sau khi ho máu ổn định. {{QĐ1514 tr.PDF 65, 67}}\n\n**Chuyển tuyến/ nhập viện**: tài liệu **không nêu** tiêu chí chuyển tuyến riêng cho ho ra máu. Các thủ thuật cần cơ sở chuyên sâu theo nguồn: soi phế quản, chụp và nút mạch phế quản, ống 2 nòng Carlens \"ở nơi có điều kiện\". {{QĐ1514 tr.PDF 66}}\n\n@@fold Chỉ định phẫu thuật cấp cứu ho ra máu {{QĐ1514 tr.PDF 66–67}}\n- Chảy máu nhiều một bên phổi khi **không có điều kiện** chụp và gây bít tắc động mạch phế quản.\n- Ho máu nặng **sau khi** đã gây bít tắc động mạch phế quản.\n- Ho máu nặng ảnh hưởng huyết động, gây suy hô hấp.\n- Chỉ khi tổn thương khu trú và toàn thân, chức năng hô hấp cho phép; **chống chỉ định** ở ung thư phổi không mổ được hoặc chức năng hô hấp kém.\n@@end\n\n### 2. Xuất huyết tiêu hóa do ung thư\n\n**Định nghĩa**: cấp cứu **nội ngoại khoa** do tổn thương mạch máu của u đường tiêu hóa, đường mật, gan; có thể tử vong do **sốc giảm thể tích**. Cần phối hợp hồi sức, cầm máu và điều trị nguyên nhân. {{QĐ1514 tr.PDF 71}}\n\n#### Nhận diện nhanh\n| Dấu hiệu | Gợi ý |\n|---|---|\n| **Nôn máu đỏ tươi** (chảy mới), **nôn máu đen** (chảy cũ) | XHTH trên {{QĐ1514 tr.PDF 71}} |\n| **Phân đen** | XHTH trên do ung thư dạ dày-ruột, đường mật, hoặc ung thư gan có xơ gan giãn vỡ TM thực quản {{QĐ1514 tr.PDF 71}} |\n| **Phân máu đỏ tươi/ đỏ thẫm** | Ung thư tiêu hóa thấp (đại trực tràng, ống hậu môn) {{QĐ1514 tr.PDF 71}} |\n| Đặt sonde dạ dày ra máu tươi; thăm trực tràng phân đen/ máu | Xác nhận chảy máu {{QĐ1514 tr.PDF 71}} |\n| Chóng mặt, ngất, mạch nhanh nhỏ, huyết áp tụt, suy hô hấp | **Sốc mất máu** {{QĐ1514 tr.PDF 71}} |\n- Mất máu cấp **không nôn máu, không phân đen**: sonde dạ dày không máu **không loại trừ**; thăm trực tràng sớm, đôi khi phải nội soi dạ dày-tá tràng cấp. {{QĐ1514 tr.PDF 71}}\n- Nguyên nhân khác ít gặp theo Y5: u thực quản xâm lấn động mạch chủ hoặc động mạch phổi gây XHTH trên cấp, **hiếm gặp** trên lâm sàng. {{Y5 tr.244}}\n\n#### Mức độ nặng\n- **Huyết động không ổn định**: huyết áp tâm thu < ==90== mmHg, đầu chi lạnh, thiểu niệu < ==30== ml/giờ, vật vã hoặc hôn mê. {{QĐ1514 tr.PDF 72}}\n- Mất > ==500== ml hoặc phải truyền > ==5== đơn vị máu/24 giờ; máu đỏ tươi qua sonde hoặc đi ngoài. {{QĐ1514 tr.PDF 72}}\n- Hct < ==0,2== L/L, hồng cầu < ==2,0== T/L, Hb < ==70== g/l; yếu tố tăng nặng: > ==60== tuổi, suy tim. {{QĐ1514 tr.PDF 72}}\n\n#### Xử trí ban đầu\n- **Nằm đầu thấp, nâng chân**; oxy 2–6 l/phút; đặt **nội khí quản** nếu nguy cơ trào ngược vào phổi, suy hô hấp hoặc rối loạn ý thức. {{QĐ1514 tr.PDF 73}}\n- **Hai đường truyền** tĩnh mạch lớn; sonde tiểu theo dõi nước tiểu; **sonde dạ dày rửa sạch máu** nếu XHTH trên; điện tim ở người cao tuổi, bệnh mạch vành. {{QĐ1514 tr.PDF 73}}\n- Bù thể tích: NaCl 0,9%, Ringer lactat hoặc dịch cao phân tử, **hạn chế glucose 5%**. Mục tiêu thoát sốc: huyết áp tâm thu > ==90== mmHg, nước tiểu > ==30== ml/giờ, hết vật vã. {{QĐ1514 tr.PDF 73}}\n- **Truyền máu** khi chảy máu nặng và tiến triển: Hct > ==25%== (> ==30%== ở người già, bệnh tim mạch, suy hô hấp). {{QĐ1514 tr.PDF 73}}\n- **Huyết tương tươi đông lạnh** khi prothrombin < ==30%== và INR > ==1,8==; **khối tiểu cầu** khi tiểu cầu < ==50== G/l (hay gặp ở ung thư gan trên xơ gan nặng). {{QĐ1514 tr.PDF 73}}\n\n#### Cầm máu theo nguyên nhân\n@@tabs\n@@tab Nội soi can thiệp\n- U dạ dày-ruột, đại-trực tràng: **tiêm xơ** (cồn, polidocanol) hoặc tiêm **adrenalin** tại chỗ. {{QĐ1514 tr.PDF 73}}\n- Giãn vỡ TM thực quản (ung thư gan/ xơ gan): keo dán, tiêm xơ, **thắt vòng cao su**, kẹp clip; phối hợp sonde bóng chèn **Sengstaken-Blakemore** (hiệu quả nhưng chỉ **tạm thời**). {{QĐ1514 tr.PDF 73}}\n- Chảy máu đường mật: ERCP can thiệp. {{QĐ1514 tr.PDF 73}}\n@@tab Nội khoa\n- **Ức chế bơm proton** (pantoprazol 80 mg/24 giờ, sau đó 8 mg/giờ trong 72 giờ), bơm nước lạnh qua sonde dạ dày nếu ung thư dạ dày. {{QĐ1514 tr.PDF 74}}\n- Giảm áp lực tĩnh mạch cửa: **terlipressin**, vasopressin, **somatostatin**, **octreotid** trong 3–5 ngày; phối hợp chẹn beta giao cảm. {{QĐ1514 tr.PDF 74}}\n- **Chụp mạch can thiệp**: gây tắc chọn lọc hoặc truyền vasopressin vào động mạch chảy máu. {{QĐ1514 tr.PDF 74}}\n@@tab Phẫu thuật\n- Cắt đoạn thực quản, cắt dạ dày một phần/ toàn phần, cắt u đường mật, cắt đoạn đại-trực tràng. {{QĐ1514 tr.PDF 74}}\n- Vỡ TM thực quản trong ung thư gan có xơ gan: **nối cửa-chủ** cầm máu ==95%==, nhưng nguy cơ tử vong cao và bệnh não gan. {{QĐ1514 tr.PDF 74}}\n@@end\n\n> [!red] Điểm cấp cứu XHTH\n> **Hồi sức trước** (bù thể tích, bù máu, nâng huyết áp), cầm máu và điều trị nguyên nhân phối hợp; điều trị ung thư chỉ khi XHTH ổn định. XHTH nặng còn gây **suy thận chức năng** (ure, creatinin tăng). {{QĐ1514 tr.PDF 72, 74}}\n\n**Chuyển tuyến/ nhập viện**: tài liệu **không nêu** tiêu chí chuyển tuyến; đây là cấp cứu cần **nội soi cấp** và hồi sức tích cực. {{QĐ1514 tr.PDF 71, 73}}\n\n### 3. Suy hô hấp cấp ở bệnh nhân ung thư\n\n**Định nghĩa**: cơ quan hô hấp đột ngột không đảm bảo trao đổi khí, gây **thiếu oxy máu** ± tăng CO2 máu, thể hiện qua **khí máu động mạch**. Là cấp cứu nội khoa; thiếu oxy nặng nhanh dẫn đến tử vong. {{QĐ1514 tr.PDF 81, 84}}\n\n#### Nguyên nhân (theo vị trí)\n| Nhóm | Ví dụ |\n|---|---|\n| **Đường thở** | U bít tắc đường thở cao (khoang miệng, thanh quản, hạ họng) hoặc thấp (phế quản, trung thất, di căn phổi) |\n| **Phế nang, mô kẽ, màng phổi** | Ung thư phổi/ di căn phổi, tràn dịch/ tràn khí màng phổi, xẹp phổi |\n| **Mao mạch phổi** | Tắc mạch phổi do di căn |\n{{QĐ1514 tr.PDF 81}}\n| Ngoài phổi | Ví dụ |\n|---|---|\n| Trung tâm hô hấp | U não, di căn não, tăng áp lực nội sọ |\n| Thần kinh cơ | Chèn ép tủy, u tuyến ức gây nhược cơ |\n| Thành ngực | Gãy xương sườn do di căn, u thành ngực |\n| Chèn ép từ ngoài | Ung thư thực quản chèn ép/ rò khí phế quản, u/ hạch trung thất, **tràn dịch ổ bụng** đè cơ hoành |\n| Chuyển hóa giai đoạn cuối | Rối loạn điện giải, hạ đường huyết, phù phổi, suy thận, suy kiệt, nhiễm trùng |\n{{QĐ1514 tr.PDF 81–82}}\n\n#### Nhận diện nhanh và mức độ nặng\n- **Khó thở** rõ nhất, có thể thở nhanh (> ==25== lần/phút) hoặc **thở chậm** (< ==10== lần/phút) khi suy nặng hoặc u chèn trung tâm hô hấp. {{QĐ1514 tr.PDF 82}}\n- **Ung thư giai đoạn cuối, suy kiệt**: mức khó thở **không tương xứng**, thậm chí ít than phiền nhưng đã suy hô hấp nguy kịch, nên cần **khí máu động mạch**. {{QĐ1514 tr.PDF 82–83}}\n- Tím đầu chi/ môi khi SaO2 < ==85%==; vã mồ hôi, co kéo cơ hô hấp phụ; mạch > ==120== lần/phút. {{QĐ1514 tr.PDF 83}}\n- Khí máu: PaO2 < ==60== mmHg, PaCO2 có thể > ==55== mmHg, pH < ==7,35==; **pH < 7,2 = nguy kịch**, thông khí cơ học ngay. {{QĐ1514 tr.PDF 83}}\n\n@@tabs\n@@tab Loại nặng\nChưa có dấu hiệu đe dọa tính mạng: chủ yếu **thuốc và oxy liệu pháp**, hút đờm, chống tụt lưỡi. {{QĐ1514 tr.PDF 82}}\n@@tab Loại nguy kịch\n- Thở > ==40== hoặc < ==10== lần/phút; mạch nhanh, tụt huyết áp; vật vã, lơ mơ, hôn mê. {{QĐ1514 tr.PDF 82}}\n- **Can thiệp ngay** (nội khí quản, bóp bóng, thở máy), sau đó mới dùng thuốc hoặc làm đồng thời. {{QĐ1514 tr.PDF 82, 84}}\n@@end\n\n#### Xử trí ban đầu\n- **Tư thế**: nghiêng an toàn nếu hôn mê chưa can thiệp; **Fowler** nếu phù não do u hoặc nguyên nhân tại phổi. Thở oxy 2–4 l/phút qua mũi; tụt lưỡi: canuyn Guedel/ Mayo, hút miệng; bóp bóng Ambu có oxy 4–6 l/phút. {{QĐ1514 tr.PDF 84}}\n- **Đặt nội khí quản khó** ở ung thư khoang miệng, hạ họng, thanh quản (chít hẹp): cân nhắc **chọc kim lớn qua màng nhẫn giáp**. {{QĐ1514 tr.PDF 85}}\n- U chèn khí phế quản, trung thất hoặc phù nề thanh môn: **methylprednisolon** 0,5–1 mg/kg tĩnh mạch. {{QĐ1514 tr.PDF 85}}\n- Tăng áp lực nội sọ do u não: **mannitol 20%** 1–1,5 g/kg trong 30 phút, **dexamethason** 10–20 mg tĩnh mạch. {{QĐ1514 tr.PDF 85}}\n- Sốc phản vệ: **adrenalin** 1 mg, 1/2 đến 1 ống tiêm bắp hoặc tĩnh mạch. {{QĐ1514 tr.PDF 85}}\n- Tại bệnh viện: oxy mask 10–12 l/phút; **kèm COPD** bắt đầu oxy thấp 1–3 l/phút rồi tăng dần theo khí máu để tránh ứ CO2. {{QĐ1514 tr.PDF 85}}\n- **Thở BiPAP** khi còn bảo vệ đường thở, ho khạc tốt; **thở máy xâm nhập** khi ngừng thở, không bảo vệ được đường thở, tắc nghẽn hô hấp trên, toan hô hấp nặng, trơ với oxy. {{QĐ1514 tr.PDF 86}}\n- Ngưỡng chỉ định thông khí nhân tạo: thở > ==35== hoặc < ==10== lần/phút; PaO2 < ==60== mmHg; pH < ==7,25==; PaCO2 ≥ ==55== mmHg. {{QĐ1514 tr.PDF 86}}\n\n> [!red] Điều trị nguyên nhân song song\n> Chọc tháo **tràn dịch màng phổi, màng tim, màng bụng**; đặt **stent khí quản** giải phóng chèn ép; xạ trị/ phẫu thuật u chèn ép; chọc dịch cổ trướng giảm áp lực ổ bụng; chống chèn ép tủy; giảm áp lực nội sọ. {{QĐ1514 tr.PDF 86}}\n\n**Nhập viện**: **phần lớn suy hô hấp cấp cần nhập viện ngay**; nguy kịch xử trí ngay tại chỗ, tại nhà, trên xe vận chuyển hoặc tại bệnh viện rồi chuyển tới phòng cấp cứu/ hồi sức tích cực. {{QĐ1514 tr.PDF 84}}\n\n### 4. Suy thận cấp do ung thư (sau thận do chèn ép)\n\n**Định nghĩa**: giảm nhanh mức lọc cầu thận (vài giờ đến vài ngày), tăng ure và creatinin, giữ nước, rối loạn acid-base. Thường nằm trong bệnh cảnh nặng do chính bệnh ác tính. {{QĐ1514 tr.PDF 76}}\n\n#### Nhận diện nhanh\n- **Thiểu niệu, vô niệu, phù**; ure, creatinin tăng nhanh; **tăng kali**; toan chuyển hóa. {{QĐ1514 tr.PDF 76}}\n- **Sau thận**: u hoặc hạch chèn đường bài xuất (đại trực tràng, thận, buồng trứng, **cổ tử cung**, sau phúc mạc, bàng quang, tuyến tiền liệt, hạch di căn); hoặc **thắt nhầm niệu quản** sau mổ u tiểu khung. {{QĐ1514 tr.PDF 77}}\n- **Ung thư cổ tử cung** giai đoạn trễ: phù chân, phù mặt, tiểu ít (tăng urê máu do tắc niệu quản). Suy thận sau thận là **nguyên nhân tử vong nhiều nhất** trong ung thư cổ tử cung. {{Y5 tr.58, 61}}\n- Bướu xâm lấn sau phúc mạc có thể tạo vùng chậu xơ cứng gây tắc nghẽn niệu quản. {{Y5 tr.256}}\n- **Phân biệt**: tăng ure/ creatinin không do suy thận cấp (xuất huyết tiêu hóa, corticoid, đợt tiến triển suy thận mạn); suy **chức năng** (trước thận) khác suy **thực tổn**. {{QĐ1514 tr.PDF 78}}\n\n#### Mức độ nặng (RIFLE)\n| Mức | Creatinin / GFR | Nước tiểu |\n|---|---|---|\n| **R** nguy cơ | Creatinin ×==1,5== hoặc GFR giảm > ==25%== | < 0,5 ml/kg/giờ trong 6 giờ |\n| **I** tổn thương | ×==2== hoặc giảm > ==50%== | < 0,5 ml/kg/giờ trong 12 giờ |\n| **F** suy | ×==3== hoặc giảm > ==75%== | < 0,3 ml/kg/giờ trong 12 giờ hoặc vô niệu 12 giờ |\n| **L** mất chức năng | Mất hoàn toàn > ==4== tuần | |\n| **E** giai đoạn cuối | Cần lọc máu > ==3== tháng | |\n{{QĐ1514 tr.PDF 77}}\n\n#### Xử trí ban đầu\n@@tabs\n@@tab Sau thận / tại thận (thực thể)\n- **Ngừng thuốc có thể gây suy thận**; kháng sinh phổ rộng chỉnh liều theo mức lọc cầu thận nếu nhiễm khuẩn. {{QĐ1514 tr.PDF 78}}\n- **Giải phóng đường bài xuất**: mở thông niệu quản qua da, **đặt stent niệu quản/ sonde JJ**, phẫu thuật cắt u và hạch chèn ép. {{QĐ1514 tr.PDF 78}}\n- Không mổ được: **xạ trị khối chèn ép cấp cứu**; phối hợp hóa trị toàn thân, kháng thể đơn dòng, miễn dịch tùy trường hợp. Liều xạ: tài liệu không nêu rõ. {{QĐ1514 tr.PDF 79}}\n@@tab Trước thận (chức năng)\n- **Cầm máu** nếu có chảy máu (XHTH, âm đạo, đái máu, ho máu). {{QĐ1514 tr.PDF 78}}\n- Bù thể tích bằng dịch đẳng trương hoặc Oresol; truyền máu cùng nhóm nếu mất máu cấp; vận mạch khi cần. {{QĐ1514 tr.PDF 78}}\n- Loại bỏ thuốc độc với thận và thuốc có kali. {{QĐ1514 tr.PDF 78}}\n@@end\n\n#### Nội môi và lọc máu\n- Hạn chế nước, muối, kali. **Tăng kali**: Kayexalat + sorbitol; calci clorua 0,5 g tiêm tĩnh mạch chậm; glucose 10–20% pha insulin; natri bicarbonat 1,4% 250–500 ml nếu toan chuyển hóa nặng. {{QĐ1514 tr.PDF 79}}\n- **Furosemid** liều cao để chuyển vô niệu thành có nước tiểu (tối đa 1.000 mg/24 giờ); không đáp ứng thì **chạy thận nhân tạo ngay**. {{QĐ1514 tr.PDF 79}}\n\n> [!red] Chỉ định thận nhân tạo sớm (khi có 1 hoặc 2 dấu hiệu)\n> Không đáp ứng lợi tiểu; ure > ==30== mmol/l; creatinin > ==500== µmol/l; **kali > ==6== mmol/l** (càng tăng nhanh càng lọc sớm); tăng gánh thể tích, CVP cao, nguy cơ **phù phổi cấp**; toan chuyển hóa **pH < ==7,2==**. {{QĐ1514 tr.PDF 79}}\n\n**Chuyển tuyến/ nhập viện**: tài liệu **không nêu** tiêu chí chuyển tuyến riêng; các can thiệp (stent niệu quản, mở thận qua da, lọc máu, xạ trị cấp cứu) đòi hỏi cơ sở chuyên khoa. Sau khi chức năng thận ổn định mới điều trị nguyên nhân. {{QĐ1514 tr.PDF 78–79}}\n\n### 5. Tắc ruột và thủng tạng rỗng do u\n\n> [!warn] Nguồn không có bài riêng\n> QĐ1514 **không có bài cấp cứu** về tắc ruột hay thủng u; chỉ nêu rải rác. Phần xử trí (dịch, giảm áp, kháng sinh, phẫu thuật cấp cứu...): **tài liệu không nêu**.\n\n| Nội dung | Theo nguồn |\n|---|---|\n| **Nhận diện tắc ruột** | Đau bụng cơn, nôn, buồn nôn, **bí trung đại tiện**; thường gặp ở u ruột non hoặc khối u lớn gây hẹp tắc ống tiêu hóa {{QĐ1514 tr.PDF 513}} |\n| **Nhận diện thủng tạng rỗng** | **Viêm phúc mạc**: sốt, đau bụng như dao đâm, bụng cứng như gỗ, phản ứng thành bụng dương tính {{QĐ1514 tr.PDF 514}} |\n| **Bệnh nhân vào viện vì** | Tắc ruột hoặc viêm phúc mạc do thủng tạng rỗng (u thần kinh nội tiết đường tiêu hóa) {{QĐ1514 tr.PDF 529}} |\n| **Chụp bụng không chuẩn bị** | Khi nghi ngờ tắc ruột {{QĐ1514 tr.PDF 595}} |\n| **Phẫu thuật giảm nhẹ** | Tắc ruột do bướu xâm lấn: **mở đại tràng ra da** (hậu môn nhân tạo) {{Y5 tr.68}}; ung thư dạ dày tái phát có tắc ruột: **nối tắt hoặc mở hồi tràng/ đại tràng ra da** {{Y5 tr.262}} |\n| **Phẫu thuật chủ động** | U lympho đường tiêu hóa có **nguy cơ thủng**; điều trị biến chứng tắc đường mật, tắc niệu quản, tắc ruột, chảy máu {{QĐ1514 tr.PDF 435}} |\n| **Xâm lấn tại chỗ** | Hậu quả: chảy máu, tắc nghẽn (nhiễm trùng, suy chức năng), **thủng** (dò, nhiễm trùng) {{SY5 tr.8}} |\n\n- Nôn do khối u lớn gây tắc tá tràng được mô tả như tắc ruột cao; chuyển tuyến/ nhập viện cho nhóm này: tài liệu **không nêu**.\n\n### Điểm hay thi\n> [!warn]\n> - **Ho ra máu**: ít < 50 ml; trung bình 50–200 ml; nặng > 200 ml; > 500 ml nguy kịch; **sét đánh**. Glanduitrine **không tiêm tĩnh mạch**; **nút động mạch phế quản** khi > 200 ml và thất bại nội khoa.\n> - **XHTH nặng**: HATT < 90 mmHg, mất > 500 ml, Hb < 70 g/l; truyền máu giữ **Hct > 25%** (> 30% người già/ tim mạch); **hạn chế glucose 5%**; Sengstaken-Blakemore chỉ tạm thời.\n> - **Suy hô hấp cấp nguy kịch**: thở > 40 hoặc < 10 lần/phút, huyết động, ý thức; **pH < 7,2** thở máy ngay; ung thư vùng miệng-họng-thanh quản đặt NKQ khó thì **chọc kim lớn qua màng nhẫn giáp**; COPD bắt đầu oxy **1–3 l/phút**.\n> - **Suy thận cấp sau thận**: giải phóng đường bài xuất (**stent niệu quản/ JJ**, mở thận qua da); thận nhân tạo khi **K > 6**, ure > 30, creatinin > 500, **pH < 7,2**, phù phổi.\n> - Suy thận sau thận là **nguyên nhân tử vong nhiều nhất** của ung thư cổ tử cung (Y5).\n> - Tắc ruột, thủng u: nguồn chỉ nêu nhận diện và phẫu thuật giảm nhẹ, **không có phác đồ cấp cứu**.\n\n### Tự kiểm tra\n- Ho ra máu \"nặng\" và \"nguy kịch\" theo ngưỡng thể tích? :: Nặng > 200 ml/24 giờ; > 500 ml/24 giờ có thể nguy kịch. {{QĐ1514 tr.PDF 64}}\n- Vì sao Glanduitrine chỉ tiêm bắp hoặc truyền nhỏ giọt? :: Tiêm tĩnh mạch có thể gây co thắt mạch não đột ngột. {{QĐ1514 tr.PDF 65}}\n- Chỉ định nút động mạch phế quản trong ho ra máu? :: Ho máu > 200 ml và thất bại các phương pháp nội khoa. {{QĐ1514 tr.PDF 66}}\n- Tiêu chuẩn XHTH nặng? :: HATT < 90 mmHg, mất > 500 ml hoặc truyền > 5 đơn vị/24 giờ, Hct < 0,2, Hb < 70 g/l. {{QĐ1514 tr.PDF 72}}\n- Ngưỡng truyền máu trong XHTH? :: Hct > 25% (> 30% ở người già, bệnh tim mạch, suy hô hấp). {{QĐ1514 tr.PDF 73}}\n- Hai loại dịch/ thuốc cần tránh hoặc hạn chế trong hồi sức XHTH, ho ra máu? :: Hạn chế glucose 5% (XHTH); Glanduitrine không tiêm tĩnh mạch (ho máu). {{QĐ1514 tr.PDF 65, 73}}\n- Suy hô hấp cấp loại nguy kịch gồm dấu hiệu nào và xử trí? :: Thở > 40 hoặc < 10 lần/phút, huyết động và ý thức rối loạn; can thiệp ngay (NKQ, bóp bóng, thở máy) rồi mới dùng thuốc. {{QĐ1514 tr.PDF 82}}\n- Ung thư vùng miệng-họng-thanh quản đặt NKQ khó thì làm gì? :: Cân nhắc chọc kim lớn qua màng nhẫn giáp. {{QĐ1514 tr.PDF 85}}\n- Giải quyết suy thận cấp sau thận do u chèn ép? :: Mở thông niệu quản qua da, đặt stent/ sonde JJ, cắt u hạch, hoặc xạ trị cấp cứu nếu không mổ được. {{QĐ1514 tr.PDF 78–79}}\n- Chỉ định thận nhân tạo sớm trong suy thận cấp? :: Không đáp ứng lợi tiểu, ure > 30, creatinin > 500, K > 6, quá tải thể tích, pH < 7,2. {{QĐ1514 tr.PDF 79}}"}, {"kind": "foundation", "disease": "", "short": "Chẩn đoán giải phẫu bệnh", "group": "Giải phẫu bệnh, xâm lấn, di căn, miễn dịch", "section": 4, "order": 2, "khung": [], "id": "ung-thu-chan-doan-giai-phau-benh", "title": "Chẩn đoán giải phẫu bệnh — tế bào học, hóa mô miễn dịch, sinh thiết lỏng", "layer": "nen", "module": "ung-buou", "tags": ["giai-phau-benh", "te-bao-hoc", "fna", "hoa-mo-mien-dich", "ihc", "sinh-thiet-long", "ctdna", "ctc"], "source": "Y2 tr. 43–53; SY2 tr. 308–337", "body": "> [!key] Ý chính\n> - **Xét nghiệm vi thể gần như không thể thiếu** để chẩn đoán và điều trị ung thư {{Y2 tr.43}}; sinh thiết mô ban đầu vẫn cần ở hầu hết ung thư {{Y2 tr.52}}.\n> - Tế bào học (FNA, Pap) = xác định lành/ác, hữu dụng khi **dương tính**; mô bệnh học = loại, độ mô học, độ xâm lấn.\n> - **Hóa mô miễn dịch (IHC)** chỉ **hỗ trợ** H&E: xác định nguồn gốc, ER/PR/HER2, Ki67…\n> - **Sinh thiết lỏng** (CTC, ctDNA): ít xâm lấn, theo dõi được; không thay chẩn đoán xác định ban đầu.\n\n### 1. Nguyên tắc {{Y2 tr.43}} {{SY2 tr.314}}\n- Khám khối bướu + khảo sát dưới kính hiển vi = bước chủ yếu.\n- Mô bệnh học: loại mô học, độ mô học, di căn xa. Tế bào học: bản chất lành/ác. Đặc tính sinh học (IHC, FISH, giải trình tự gen): **cá thể hóa điều trị**.\n- Theo vị trí bướu:\n  - **Da, niêm mạc**: xâm nhập, ăn cứng, loét/chồi sùi lâu không lành → nhìn trực tiếp/nội soi, X-quang cản quang.\n  - **Dưới da (vú)**: chỗ cứng, không đau, không đều; da lõm, da cam, hạch nách/trên đòn.\n  - **Vị trí sâu**: X-quang, đồng vị, siêu âm, CT…; chẩn đoán chính xác thường khó.\n\n### 2. Tế bào học {{Y2 tr.43}} {{SY2 tr.328}}\n- Nguồn: tế bào tróc tự nhiên (phết âm đạo, dịch phế quản); chọc hút dịch tràn dịch (màng phổi, bụng); **FNA** (kim nhỏ) cho vú, giáp, tuyến nước bọt, phần mềm, gan, phổi.\n- {o|Dễ làm nhưng chỉ hữu dụng khi dương tính}; giúp tầm soát, định hướng, xác định nơi di căn.\n- **Pap**: đơn giản, rẻ; có từ thập niên 1920, dùng rộng từ 1950; xét nghiệm tầm soát cổ tử cung hiệu quả nhất từ trước đến nay {{SY2 tr.308}}. Xem [[ung-thu-tam-soat-nguyen-tac]].\n\n> [!warn] Mâu thuẫn nguồn (năm Pap)\n> SY2 nêu Pap \"có từ thập niên 1920\"; SY5 tr.44 ghi **1939** Papanicolaou dùng phết CTC–âm đạo để tầm soát. Giữ cả hai khi ôn.\n\n### 3. Giải phẫu bệnh quy ước (H&E) {{Y2 tr.43}}\n- Xác định ung thư (phân biệt bướu lành, tổn thương dạng bướu), **loại** ung thư, diễn tiến/tiên lượng (độ biệt hóa, phân bào, độ mô học), đôi khi độ lan rộng vi thể.\n@@fold Cố định và gửi bệnh phẩm {{SY2 tr.335}}\n- Dung dịch: ==formol 10%, pH 7==; thể tích ==gấp 20 lần== mẫu mô.\n- Từ lấy mẫu đến vào dung dịch: tối đa ==30 phút==; cố định tối ưu 6–48 giờ; cần 6–8 giờ cho mảnh mô 4 mm.\n- Lợi ích: ngăn thối rữa, giữ mô gần bình thường, tạo tương phản hình thái tốt.\n@@end\n\n### 4. Hóa mô miễn dịch (IHC) {{Y2 tr.44}}\n- Dùng khối nến/kính GPB. Mục đích: phân biệt ung thư kém biệt hóa; xác định nguồn gốc bướu không biệt hóa (carcinôm / sarcôm / lymphôm); dấu ấn lymphôm, thụ thể nội tiết vú, gen sinh ung, hoạt tính tế bào; vi xâm nhập, thâm nhiễm giả, di căn thầm lặng.\n@@tabs\n@@tab Nguồn gốc bướu chưa rõ\n| CK | Vimentin | LCA | S100 | NSE | Kết luận |\n|---|---|---|---|---|---|\n| + | − | − | − | − | {b|Carcinôm} |\n| − | + | − | − | − | {b|Sarcôm} |\n| − | +/− | + | − | − | {b|Lymphôm} |\n| − | +/− | − | + | − | U nguồn mô bào |\n| − | − | − | + | + | U nguồn thần kinh |\n{{Y2 tr.45}} (bảng 3)\n@@tab Nguồn gốc carcinôm\n| Kết luận | Dấu ấn |\n|---|---|\n| Carcinôm tuyến | EMA+, CK8/18+, CEA+, PSA− |\n| Tế bào gai | EMA+, CK8/18−, CK10/13+, CEA−, PSA− |\n| Chuyển tiếp | EMA−, CK8/18+, CK7+, CEA−, PSA− |\n| Tuyến tiền liệt | EMA−, CEA−, **PSA+** |\n| Tuyến giáp | EMA−, CEA−, **thyroglobulin+** |\n| Tuyến vú | **GCDFP-15+** |\n{{Y2 tr.45}} (bảng 4)\n@@tab Sarcôm / khác\n- Vimentin(+): cơ trơn desmin+, actin+; cơ vân desmin+, actin−, myosin+; sợi desmin−, fibronectin+; mạch máu CD31, CD34, yếu tố VIII dương.\n- Mêlanôm HMB45+, S100+; thần kinh S100+, NSE+; thần kinh nội tiết thêm chromogranin+, synaptophysin+. (Bảng 7 hệ tạo huyết không đọc rõ, không chép.) {{Y2 tr.45}}\n@@end\n\n@@fold Các ứng dụng khác của IHC {{Y2 tr.46}}\n- **Vi xâm nhập / thâm nhiễm giả**: kháng thể màng đáy (collagen IV, laminin; mất trong vi xâm nhập). Vú: có tế bào cơ biểu mô (actin) gợi lành tính; tiền liệt: có tế bào đáy (CK trọng lượng phân tử cao) = lành, không bao giờ quanh tuyến ác.\n- **Di căn thầm lặng**: 8–30% ung thư vú di căn hạch không thấy trên GPB thường quy; IHC thấy vi di căn tủy xương ≈ 25–30% carcinôm vú giai đoạn đầu.\n- **Kháng nguyên bướu – 4 loại** {{Y2 tr.47}}: đặc hiệu bướu (gen sinh ung đột biến, p53); đổi vị trí phân bố (CEA, B72.3, EMA); đổi mức biểu hiện (GCDFP-15, thyroglobulin, calcitonin); biến đổi sinh hóa (ABH, Lewis Lex/Ley ở niệu mạc).\n- **Lành – ác**: hạn chế; kappa/lambda (cả hai dương = lành; một dương hoặc cả hai âm = lymphôm).\n@@end\n\n#### Tiên lượng và dự đoán đáp ứng {{Y2 tr.47}}\n- **Ki67** (G1, S, G2, phân bào; ==không có ở G0==) và PCNA: tỷ lệ cao → độ mô học cao, sống thêm ngắn.\n- **ER/PR** (ở **nhân**; dương bào tương là không đặc hiệu): có cả hai → tiên lượng tốt, đáp ứng nội tiết; không có → ít đáp ứng nội tiết {{Y2 tr.48}}.\n- **HER-2/neu**: khuếch đại ở vú, buồng trứng, tiền liệt, nước bọt, phổi, đại tràng. ==25–30%== ung thư vú nguyên phát, ≈ 1/3 buồng trứng: tái phát cao, sống thêm ngắn; tỷ lệ nghịch ER/PR; không có ở vú bình thường.\n- SY2: đột biến cần xác định: Her2 (vú, dạ dày), BRCA1/2 (vú, buồng trứng), EGFR (phổi), Kit/PDGFRA (GIST), KRAS (đại–trực tràng), BRAF (giáp, melanoma), BCR/ABL, FLT3, RB1 {{SY2 tr.316}}.\n\n> [!warn] Giới hạn của IHC {{Y2 tr.49}}\n> Chỉ hỗ trợ H&E; có thể dương/âm tính giả; nhiều trường hợp không phân biệt được lành/ác; đắt tiền.\n\n### 5. Tế bào bướu du hành (CTC) và sinh thiết lỏng {{Y2 tr.49}}\n@@tabs\n@@tab CTC\n- Tế bào từ bướu nguyên phát vào máu/lymphô, được xem là mầm mống ổ di căn; bệnh càng tiến triển CTC càng nhiều.\n- Dạng: tế bào nguyên vẹn (CK+, CD45− = carcinôm); **EMT / tế bào gốc ung thư** (âm cả hai, đề kháng cao, dễ di căn nhất); tế bào chết theo chương trình; **cụm ≥ 2 tế bào** (tiên lượng xấu).\n- Hạn chế: rất ít (≈ 0,01% tế bào tróc thành ổ di căn; 1–10 tế bào/mL máu); mới làm cho vú, tiền liệt, phổi, đại tràng.\n@@tab ctDNA\n- DNA bướu chết rơi vào máu, phản ánh **toàn khối bướu** (sinh thiết mô chỉ một phần).\n- 398 bệnh nhân: 94–100% mẫu máu có cùng đột biến (EGFR, BRAF, KRAS, ALK, RET, ROS1) như mô. 846 bệnh nhân/15 loại: ctDNA ở > 80% ung thư di căn, ≈ 47% ung thư còn tại vùng.\n- Ứng dụng: chọn thuốc đích, phát hiện kháng thuốc, theo dõi tái phát/di căn. Ví dụ **RAS** ở đại–trực tràng di căn: 7–10 mL máu, PCR nhạy cao, ≈ 1 tuần.\n@@end\n- Ưu: ít xâm lấn, lặp lại được. {r|Nhưng ban đầu vẫn phải sinh thiết mô} để chẩn đoán xác định.\n\n> [!ext] Bổ sung (tham khảo)\n> ctDNA ngày càng dùng để theo dõi bệnh còn sót sau mổ (MRD) và chọn thuốc đích; giá trị tầm soát ung thư sớm vẫn đang nghiên cứu, chưa thay thế tầm soát chuẩn. *Nguồn: NCI, \"Liquid Biopsy\" https://www.cancer.gov/publications/dictionaries/cancer-terms/def/liquid-biopsy (khái niệm); nội dung diễn đạt lại.*\n\n### Điểm hay thi\n> [!warn] Bẫy thường gặp\n> - CK+ vimentin−: **carcinôm**; vimentin+ còn lại âm: **sarcôm**; LCA+: **lymphôm**.\n> - ER/PR dương tính **ở nhân**; bào tương = không đặc hiệu.\n> - Ki67 có ở mọi pha **trừ G0**.\n> - HER-2: 25–30% ung thư vú, tiên lượng xấu, **tỷ lệ nghịch** ER/PR.\n> - Formol 10%, ×20 thể tích, ≤ 30 phút.\n> - IHC không độc lập chẩn đoán; sinh thiết lỏng không thay sinh thiết mô ban đầu.\n\n### Tự kiểm tra\n- CK(+), vimentin(−), LCA(−), S100(−), NSE(−) gợi bướu nào? :: Carcinôm\n- Chỉ vimentin dương, còn lại âm gợi bướu nào? :: Sarcôm\n- Kỹ thuật tế bào học dùng rộng rãi cho vú, giáp, nước bọt, gan, phổi? :: Chọc hút kim nhỏ (FNA)\n- Điều kiện cố định bệnh phẩm theo SY2? :: Formol 10% pH 7, thể tích gấp 20 lần, vào dung dịch ≤ 30 phút\n- Ki67 biểu hiện ở pha nào? :: G1, S, G2 và phân bào; không có ở G0\n- Ý nghĩa HER-2/neu dương tính ở ung thư vú? :: ≈ 25–30%; tái phát cao, sống thêm ngắn, tỷ lệ nghịch ER/PR\n- CTC nhóm EMT/tế bào gốc ung thư nhuộm thế nào? :: Âm tính cả cytokeratin và CD45\n- Ưu điểm ctDNA so với sinh thiết mô? :: Phản ánh toàn khối bướu, ít xâm lấn, lặp lại để theo dõi và chọn thuốc đích\n- IHC có độc lập chẩn đoán lành/ác được không? :: Không, chỉ hỗ trợ H&E, có thể dương/âm tính giả\n- Dấu ấn đặc hiệu: tiền liệt, giáp, vú? :: PSA; thyroglobulin; GCDFP-15\n- Kappa và lambda cùng dương nghĩa là gì? :: Phản ứng lành tính (một dương hoặc cả hai âm gợi lymphôm)"}, {"kind": "foundation", "disease": "", "short": "Chuyển tuyến khi nghi ung thư", "group": "Điều trị và chăm sóc", "section": 2, "order": 2, "khung": [], "id": "ung-thu-chuyen-tuyen", "title": "Chuyển tuyến chuyên khoa khi nghi ung thư", "layer": "dieutri", "module": "ung-buou", "tags": ["chuyển tuyến", "chuyên khoa", "nhập viện", "nghi ung thư", "hội chẩn", "lâm sàng nghi ngờ", "BI-RADS", "khàn tiếng", "niêm mạc miệng", "ung thư vú"], "source": "ĐC Y5 tr.3 (MT10); Y5 tr.61, 74, 136, 142, 158, 185–186, 266, 314, 343; SY5 tr.296; QĐ1514 tr.PDF 47, 50, 84, 91, 182, 204, 337, 427; QĐ2549 tr.12; QĐ3898 tr.17, 19, 29", "body": "> [!key] Chuyển đúng tuyến khi nghi ung thư\n> - Mục tiêu **MT10**: chuyển đúng tuyến chuyên khoa các trường hợp nghi ung thư cần xác định chẩn đoán {{ĐC Y5 tr.3}}\n> - Tài liệu **không nêu tiêu chí chuyển tuyến chung** cho mọi ung thư; chỉ có điều kiện theo từng tình huống (mục 1) — tài liệu không nêu chung\n> - Ung thư vú: kết luận bài giảng là **chuyển nhanh đến chuyên khoa ung bướu** {{SY5 tr.296}}\n> - Khám lâm sàng tỉ mỉ, kể cả của bác sĩ tai mũi họng, vẫn bỏ sót 4,5–15,3% tổn thương tiền ung thư và ung thư hốc miệng giai đoạn sớm; do đó cần bổ sung phương tiện chẩn đoán khác {{Y5 tr.136}}\n\n### Mục tiêu học tập\n- **MT10 (kỹ năng): thực hiện được chuyển đúng tuyến chuyên khoa các trường hợp nghi ngờ ung thư cần xác định chẩn đoán** {{ĐC Y5 tr.3}}\n- Sau bài: nêu điều kiện chuyển chuyên khoa theo từng tình huống nghi ung thư; nêu rõ tài liệu không có tiêu chí chuyển tuyến chung\n\n### 1. Tình huống nghi ngờ và việc cần làm\n| Tình huống nghi ngờ | Việc cần làm | Nguồn |\n|---|---|---|\n| **Vú – tổn thương nghi ngờ** (tầm soát) | Có thể chỉ định thêm xét nghiệm chuyên sâu, hoặc **chuyển tới bệnh viện chuyên khoa ung bướu** có đủ phương tiện chẩn đoán | {{QĐ3898 tr.17}} |\n| **Vú – khám lâm sàng thấy u** | Lâm sàng nghi ngờ kèm BI-RADS 1: **giới thiệu đến chuyên gia ung thư vú** (sơ đồ bên dưới) | {{QĐ3898 tr.29}} |\n| **Khàn tiếng** (viêm dây thanh cấp, kèm cúm) | Bác sĩ nội khoa điều trị ban đầu; **không giảm sau 3 tuần → chuyển bác sĩ chuyên khoa**; phân biệt khàn cấp hay mạn, lành hay ác | {{Y5 tr.186}} |\n| **Khàn tiếng tăng dần**, không cải thiện sau 3 tuần (đoạn ung thư thanh quản) | Thăm khám bởi bác sĩ tai mũi họng hoặc bác sĩ ung bướu đầu cổ | {{Y5 tr.185}} |\n| **Bất thường niêm mạc miệng** | Đến khám ngay khi kéo dài **trên 2 tuần** | {{Y5 tr.158}} |\n| **Bất thường vùng họng miệng** | Đến khám chuyên khoa để phát hiện sớm (ghi ở phần phòng bệnh của ung thư thanh quản và khoang miệng) | {{QĐ1514 tr.PDF 182}} {{QĐ1514 tr.PDF 204}} |\n| **Xuất huyết âm đạo bất thường** (cổ tử cung) | Phải khám phụ khoa, **đừng chần chờ** | {{Y5 tr.61}} |\n| **Triệu chứng nghi ngờ** (ung thư vỏ thượng thận) | Khám tư vấn bác sĩ chuyên khoa để chẩn đoán và điều trị kịp thời | {{QĐ1514 tr.PDF 337}} |\n\n@@fold! Sơ đồ 2: khám lâm sàng thấy u, tuổi ≥ 30\nSơ đồ theo nguồn {{QĐ3898 tr.29}}\n| X-quang/ siêu âm vú (BI-RADS) | Lâm sàng nghi ngờ* | Lâm sàng ít nghi ngờ |\n|---|---|---|\n| **1** | **Giới thiệu đến chuyên gia ung thư vú**; đánh giá thêm bằng chẩn đoán hình ảnh và/hoặc lấy mẫu mô | Theo dõi 3–6 tháng/lần; u tăng kích thước đáng kể hoặc lâm sàng nghi ngờ → giới thiệu chuyên gia; ổn định/giảm → sàng lọc theo lịch |\n| **2** | Sinh thiết kim lõi, sinh thiết hỗ trợ hút chân không hoặc chọc hút kim nhỏ (dưới siêu âm nếu u nhỏ), hoặc phẫu thuật lấy u | Theo dõi 3–6 tháng/lần, như BI-RADS 1 |\n| **3** | Sinh thiết kim lõi hoặc hỗ trợ hút chân không (dưới siêu âm nếu u nhỏ), xử trí tiếp theo Sơ đồ 10 | Khám lâm sàng + siêu âm/X-quang, theo dõi sau 6, 12, 24 tháng; u tăng kích thước đáng kể hoặc lâm sàng nghi ngờ → sinh thiết như cột trái; ổn định/giảm → sàng lọc theo lịch |\n| **4–5** (thiên về ác tính) | Sinh thiết kim lõi hoặc hỗ trợ hút chân không, xử trí tiếp theo Sơ đồ 10 | Không tách theo lâm sàng |\n\nGhi chú (*): triệu chứng lâm sàng nghi ngờ gồm u mật độ chắc, ranh giới không rõ, nhiều thùy múi, co kéo da xung quanh, co kéo tụt núm vú, u xâm lấn da, u vỡ loét chảy dịch; hạch nách to, chắc, di động hạn chế; chảy dịch máu đầu vú. {{QĐ3898 tr.29}}\n@@end\n\n### 2. Tuyến chuyên khoa và điều kiện cơ sở\n- **Vú, tầm soát**: một số cơ sở chưa đủ X-quang hoặc MRI vú, có thể chỉ định siêu âm kết hợp khám lâm sàng; khi không có siêu âm thì có thể khám lâm sàng kết hợp X-quang hoặc MRI {{QĐ3898 tr.17}}\n- **Ghép tế bào gốc (đa u tủy xương)**: cần thực hiện ở **tuyến y tế chuyên khoa**; chỉ định: tuổi 18–60, Hb>80G/L, bạch cầu >3G/L, tiểu cầu >100G/L, chức năng hô hấp, gan, thận còn tốt, bệnh còn đáp ứng tốt với hóa trị {{QĐ1514 tr.PDF 427}}\n- **Ung thư đầu cổ phức tạp**: nên điều trị tại **trung tâm lớn**, nơi có chuyên gia ở mỗi chuyên khoa {{Y5 tr.142}}\n- Hội chẩn đa chuyên khoa (MT15, MT17) được trình bày riêng ở [[ung-thu-hoi-chan-lien-chuyen-khoa]]\n\n### 3. Ngoài MT10 (tham khảo): nhập viện và cấp cứu\n> Các dòng dưới đây không phải tiêu chí chuyển tuyến của MT10; chỉ là dữ kiện tham khảo về nhập viện và cấp cứu.\n\n| Tình huống | Ý trong nguồn | Nguồn |\n|---|---|---|\n| Xuất huyết âm đạo lượng nhiều (cổ tử cung) | Dẫn đến thiếu máu cấp, bệnh nhân **phải nhập viện trong tình trạng cấp cứu** | {{Y5 tr.61}} |\n| Suy hô hấp cấp ở bệnh nhân ung thư | Xử trí cấp cứu tại chỗ, rồi **vận chuyển tới bệnh viện, phòng cấp cứu hoặc hồi sức tích cực** | {{QĐ1514 tr.PDF 84}} |\n| Chèn ép tủy do di căn thân sống (ung thư tuyến tiền liệt) | Xạ trị chống chèn ép tủy; **là tình huống xử trí cấp cứu** | {{Y5 tr.343}} |\n| Sốc phản vệ do tiêm truyền thuốc hóa chất | Hội chẩn chuyên khoa cấp cứu, hồi sức và/hoặc chuyên khoa dị ứng (nếu cần); cấp cứu thành công và ổn định → **khám chuyên khoa dị ứng sau 4–6 tuần** | {{QĐ1514 tr.PDF 47}} {{QĐ1514 tr.PDF 50}} |\n| Ung thư đại tràng: nhập viện do u gây tắc hoặc thủng | Là **yếu tố nguy cơ cao** khi chỉ định hóa trị bổ trợ (từ giai đoạn II có yếu tố nguy cơ cao) | {{QĐ2549 tr.12}} |\n| Ung thư dạ dày | Khảo sát 358 bệnh nhân tại Bệnh viện Ung Bướu TP.HCM, 2000–2004: **80% nhập viện ở giai đoạn III và IV** | {{Y5 tr.266}} |\n| Ung thư gan | **Rất hiếm khi** nhập viện vì xuất huyết nội do vỡ bướu; ngày càng nhiều ca phát hiện tình cờ khi khám sức khỏe, không có triệu chứng cơ năng | {{Y5 tr.314}} |\n\n@@fold! Khi đã nhập viện: dự phòng huyết khối tĩnh mạch\n- Ung thư nhập viện vì bệnh nội khoa cấp tính hoặc hạn chế tự đi lại: nên dùng kháng đông phòng ngừa nếu không có chống chỉ định (khuyến cáo 1, chứng cứ A) {{QĐ1514 tr.PDF 91}}\n- Ung thư tiến triển đang nhập viện, không có yếu tố nguy cơ khác: cũng cần xem xét phòng ngừa bằng thuốc nếu không có chống chỉ định kháng đông (khuyến cáo 2, chứng cứ C) {{QĐ1514 tr.PDF 91}}\n- Nhập viện để mổ nhỏ, hóa trị ngắn ngày, ghép tủy hoặc tế bào gốc: **tài liệu chưa có đủ dữ liệu** để phòng ngừa {{QĐ1514 tr.PDF 91}}\n@@end\n\nCác cấp cứu khác của ung thư (ho ra máu, chèn ép tĩnh mạch chủ trên, chèn ép tủy có đau lưng và yếu chi): xem [[ung-thu-trieu-chung-khai-quat]].\n\n### 4. Tài liệu không nêu\n- Tiêu chí chuyển tuyến chung cho mọi ung thư (ngưỡng triệu chứng hoặc thời gian chung): **tài liệu không nêu**\n- Danh mục tuyến cơ sở (trung ương, tỉnh, huyện, xã) và phạm vi chẩn đoán của từng tuyến: **tài liệu không nêu**. Chỉ có các cụm tuyến rời rạc: \"tuyến ban đầu trở lên\" {{QĐ3898 tr.19}}; \"tuyến y tế cơ sở\" {{Y5 tr.74}}; \"bệnh viện chuyên khoa ung bướu\" (vú) {{QĐ3898 tr.17}}; \"tuyến y tế chuyên khoa\" (ghép tế bào gốc) {{QĐ1514 tr.PDF 427}}\n- Tiêu chí nhập viện chung cho người nghi ung thư: **tài liệu không nêu**; chỉ có các tình huống ở mục 3\n\n### Điểm hay thi\n> [!warn]\n> - Không có tiêu chí chuyển tuyến chung: không trả lời \"mọi ung thư chuyển khi…\"; trả lời theo từng tình huống ở mục 1\n> - Khàn tiếng: viêm dây thanh cấp kèm cúm **không giảm sau 3 tuần** thì chuyển chuyên khoa {{Y5 tr.186}}; khàn tiếng **tăng dần, không cải thiện sau 3 tuần** (đoạn ung thư thanh quản) thì thăm khám tai mũi họng hoặc ung bướu đầu cổ {{Y5 tr.185}}\n> - Vú: lâm sàng nghi ngờ thì giới thiệu thẳng tới chuyên gia ung thư vú, **kể cả khi BI-RADS 1** {{QĐ3898 tr.29}}\n> - Thời gian: Y5 ghi bất thường niêm mạc miệng **trên 2 tuần** {{Y5 tr.158}}; QĐ1514 khoang miệng (PDF 204) và thanh quản–hạ họng (PDF 182) chỉ ghi \"khi có bất thường vùng họng miệng\", **không nêu thời gian** {{QĐ1514 tr.PDF 204}} {{QĐ1514 tr.PDF 182}}. Ghi cả hai, không suy ra một ngưỡng chung\n\n### Tự kiểm tra\n- Tài liệu có tiêu chí chuyển tuyến chung cho mọi ung thư không? :: Không; chỉ có điều kiện theo từng tình huống\n- Khàn tiếng do viêm dây thanh cấp kèm cúm: bao lâu không giảm thì chuyển chuyên khoa? :: Sau 3 tuần điều trị ban đầu của bác sĩ nội khoa\n- Bất thường niêm mạc miệng kéo dài bao lâu thì đến khám ngay? :: Trên 2 tuần\n- Vú: lâm sàng nghi ngờ kèm BI-RADS 1 xử trí thế nào? :: Giới thiệu đến chuyên gia ung thư vú; đánh giá thêm bằng chẩn đoán hình ảnh và/hoặc lấy mẫu mô\n- Ghép tế bào gốc trong đa u tủy xương cần thực hiện ở đâu? :: Tuyến y tế chuyên khoa, khi bệnh nhân đủ tiêu chí (tuổi 18–60, đáp ứng tốt hóa trị)\n- Nhập viện do u gây tắc hoặc thủng ở ung thư đại tràng có ý nghĩa gì? :: Là yếu tố nguy cơ cao khi chỉ định hóa trị bổ trợ"}, {"kind": "foundation", "disease": "", "short": "Chọn phương tiện theo tình huống", "group": "Khái quát cận lâm sàng", "section": 4, "order": 4, "khung": [], "id": "ung-thu-cls-chon-phuong-tien", "title": "Chọn phương tiện cận lâm sàng theo tình huống", "layer": "cls", "module": "ung-buou", "tags": ["chọn phương tiện", "tình huống", "sàng lọc", "chẩn đoán", "phân giai đoạn", "theo dõi", "vú", "cổ tử cung", "đại trực tràng", "phổi"], "source": "SY5 tr. 60–62, 105, 147; Y5 tr. 9–14, 62–63, 72–74, 106–112, 124, 272–273, 282, 287–289; QĐ3128 tr. 7, 27–30, 37–38; QĐ3898 tr. 17, 22–24, 27–35, 40–41; QĐ2549 tr. 3, 23; QĐ1514 tr.PDF 243–244, 361", "body": "> [!key] Cách dùng\n> - Đọc theo **tình huống lâm sàng** (một dòng = một câu hỏi \"gặp thế này thì chọn gì\"). Mọi dòng rút từ các trang bệnh và văn bản BYT, có nguồn; ô nào tài liệu không nêu thì **không có dòng** (không suy diễn).\n> - Quy tắc chung: đi từ **không xâm lấn đến xâm lấn**, từ lâm sàng đến cận lâm sàng; không dùng phương tiện tùy tiện; kết quả không tương hợp thì hội chẩn lại {{SY5 tr.119, 136, 147}}\n> - Tổng quan: [[ung-thu-cls-vai-tro]] · hình ảnh: [[ung-thu-hinh-anh-chan-doan]] · lấy mô: [[ung-thu-noi-soi-lay-benh-pham]]\n\n@@tabs\n@@tab Vú\n| Tình huống | Chọn | Lưu ý | Nguồn |\n|---|---|---|---|\n| Sàng lọc, nguy cơ trung bình 25–39 tuổi | Tự khám hằng tháng + khám lâm sàng 1–3 năm/lần | Lịch không nêu hình ảnh | {{QĐ3898 tr.27}} |\n| Sàng lọc, nguy cơ trung bình 40–70 tuổi | Mỗi năm: khám lâm sàng + **nhũ ảnh** | Thêm **siêu âm** nếu mô vú đặc (C/D); siêu âm không thay được nhũ ảnh | {{QĐ3898 tr.23, 27, 40}} |\n| Nguy cơ cao (gen, gia đình, LCIS/ADH) | Nhũ ảnh hằng năm; **MRI** cùng mốc (không trước 25 tuổi) | Từ 25 tuổi, khám 6–12 tháng/lần | {{QĐ3898 tr.26–28}} |\n| Xạ trị ngực 10–30 tuổi | Nhũ ảnh + MRI hằng năm, bắt đầu 8 năm sau xạ, không trước 25 tuổi | | {{QĐ3898 tr.26, 28}} |\n| Sờ thấy khối vú | Khám + nhũ ảnh 2 vú; siêu âm nếu cần; sinh thiết/ chọc hút tổn thương nghi ngờ | Phân biệt **nang với đặc**: siêu âm; <35 tuổi: siêu âm | {{QĐ3128 tr.30; QĐ3898 tr.24; Y5 tr.9}} |\n| BI-RADS 3 | Theo dõi **6 tháng** | Nguy cơ ung thư <2% | {{QĐ3898 tr.23}} |\n| BI-RADS 4, 5 | **Sinh thiết** (kim lõi, VABB hoặc định vị kim dây) | Tổn thương không sờ thấy: định vị dưới hình ảnh | {{QĐ3898 tr.23, 31; Y5 tr.12}} |\n| Có **túi ngực** | Nhũ ảnh kỹ thuật **Eklund**, hoặc thay bằng MRI + siêu âm | Nhũ ảnh thường có thể gây biến dạng, dò, vỡ túi | {{QĐ3898 tr.22; QĐ3128 tr.7}} |\n| Đang **mang thai** | Nguy cơ trung bình ≥40: khám + siêu âm; nguy cơ cao: khám + siêu âm; MRI **không** cản từ | X-quang không chống chỉ định nhưng có thể hoãn ngắn | {{QĐ3898 tr.40}} |\n| Đang **cho con bú**, nguy cơ cao | Khám + nhũ ảnh ± siêu âm hoặc MRI; MRI có cản từ được | Thuốc rất ít bài tiết qua sữa | {{QĐ3898 tr.40}} |\n| Núm vú tụt mới xuất hiện | <30 tuổi: siêu âm; ≥30 tuổi: nhũ ảnh + siêu âm; BI-RADS 4–5 sinh thiết | Xử trí tiếp theo phân loại BI-RADS | {{QĐ3898 tr.31}} |\n| Chảy dịch núm vú một bên, tự chảy, một ống, trong/ máu | <30: siêu âm ± nhũ ảnh; ≥30: nhũ ảnh + siêu âm | Dịch sữa hai bên: tìm thai, prolactin, thuốc | {{QĐ3898 tr.32}} |\n| Thay đổi da (da cam, đỏ, trầy núm vú, chàm) | Nhũ ảnh ± siêu âm; sinh thiết kim lõi/ VABB ± sinh thiết da, núm vú | Ung thư vú thể viêm là chẩn đoán **lâm sàng**, không phụ thuộc sinh thiết dương tính | {{QĐ3898 tr.33}} |\n| Khối ở nách một bên | Nhũ ảnh + siêu âm vú; nếu ác tính nguồn từ vú mà vú không u → **MRI vú** | Ung thư tiềm ẩn: MRI vú | {{QĐ3898 tr.35; Y5 tr.10}} |\n| Chẩn đoán xác định | Sinh thiết **kim lõi** hoặc FNA | Thiếu nhà tế bào học giỏi → ưu tiên kim lõi (cho ER, PR, HER2) | {{QĐ3128 tr.11}} |\n| Trước bảo tồn, trước tân bổ trợ, nghi đa ổ, thể tiểu thùy | **MRI vú** | | {{QĐ3128 tr.7}} |\n| Giai đoạn sớm, không triệu chứng di căn | **Không** tầm soát di căn xa thường quy | Có triệu chứng: xạ hình xương, CT, MRI não | {{Y5 tr.14; QĐ3128 tr.30}} |\n| Giai đoạn III–IV | CT ngực, bụng, chậu; xạ hình xương; ± MRI não, PET/CT; sinh thiết ổ di căn | Xét ER, PR, HER2 tại ổ di căn | {{QĐ3128 tr.37–38}} |\n| Theo dõi sau điều trị I–III | Nhũ ảnh + siêu âm vú hằng năm (bên bảo tồn và vú đối bên) | CA15-3, CEA, CT, xạ hình xương… tùy trường hợp | {{QĐ3128 tr.28}} |\n| Đang điều trị bổ trợ/ tân bổ trợ | Sau 3–4 đợt: khám, siêu âm bụng, X-quang ngực; tân bổ trợ thêm siêu âm vú, MRI vú | Kháng HER2: đánh giá chức năng tim 3 tháng/lần | {{QĐ3128 tr.27}} |\n| Bệnh di căn đang điều trị | Lặp lại hình ảnh sau mỗi 2–4 đợt; CA15-3, CA27-29, CEA trước mỗi đợt | Không có lịch chung, cá thể hóa | {{QĐ3128 tr.27}} |\n| Dùng CA15-3, CEA để sàng lọc | **Sai**, không có giá trị | CA15-3 chỉ hỗ trợ đánh giá đáp ứng bệnh di căn | {{QĐ3898 tr.17; Y5 tr.14}} |\n\n- Chi tiết: [Ung thư vú · 5.3](#/n/ung-thu-vu/5) · [Ung thư vú · 5.4](#/n/ung-thu-vu/6)\n@@tab Cổ tử cung\n| Tình huống | Chọn | Lưu ý | Nguồn |\n|---|---|---|---|\n| Sàng lọc cộng đồng | Pap, HPV-DNA hoặc VIA; ACS/ACOG 2012: từ 21 tuổi, Pap mỗi 3 năm; 30–65 tuổi HPV + tế bào học mỗi 5 năm (ưu tiên) | Là sàng lọc, **không** phải chẩn đoán | {{Y5 tr.72–73; SY5 tr.105}} |\n| Nơi chưa đủ điều kiện Pap cộng đồng | **VIA** (nhạy ==81%==, đặc hiệu ==83%==) | Dương giả → điều trị quá mức; người lấy mẫu có thể là điều dưỡng/ nữ hộ sinh được huấn luyện | {{Y5 tr.72, 74}} |\n| Pap ≥ ASC-H, HPV 16/18 (+), hoặc nghi ngờ khi khám | **Soi cổ tử cung + sinh thiết** (Lugol, acid acetic) | Pap cổ trong bất thường: nạo sinh thiết cổ trong | {{Y5 tr.73}} |\n| Khám mỏ vịt thấy sùi, loét, nhiễm cứng | Sinh thiết kềm **ngay**, ở bờ tổn thương | Không gây tê; kết quả không phù hợp mà vẫn nghi → sinh thiết lại | {{Y5 tr.62}} |\n| Cần vừa chẩn đoán vừa điều trị tổn thương tại chỗ | **Khoét chóp** | Nếu xâm lấn màng đáy → điều trị tiếp | {{Y5 tr.73; QĐ1514 tr.PDF 361}} |\n| Đánh giá kích thước bướu, xâm lấn chậu | **MRI** (tốt nhất cho bướu) hoặc CT bụng chậu cản quang | CT hoặc MRI đơn thuần là đủ trong thực hành | {{Y5 tr.63}} |\n| Hạch, di căn xa | **PET/CT** (hạch nhạy >80%, đặc hiệu >95%) | Khi nghi di căn xa hoặc đã có hạch | {{Y5 tr.63}} |\n| Nghi xâm lấn bàng quang, trực tràng | Soi bàng quang, soi trực tràng | Triệu chứng tiểu máu, mót rặn, dò; hoặc giai đoạn IIIB | {{Y5 tr.63}} |\n| Thận ứ nước, hạch chậu, gan, dịch ổ bụng | Siêu âm bụng | | {{Y5 tr.63}} |\n| Nghi di căn phổi, xương | X-quang ngực; xạ hình xương (đau xương) | | {{Y5 tr.63}} |\n| Theo dõi đáp ứng, tái phát | SCC, CEA, CA12-5; PET/CT; xạ hình xương theo QĐ1514 | Tái phát: 80% trong 2–3 năm đầu (Y5) | {{QĐ1514 tr.PDF 361; Y5 tr.70}} |\n\n- Chi tiết: [Ung thư cổ tử cung · 5.3](#/n/ung-thu-cotucung/5) · [Ung thư cổ tử cung · 5.4](#/n/ung-thu-cotucung/6)\n@@tab Đại trực tràng\n| Tình huống | Chọn | Lưu ý | Nguồn |\n|---|---|---|---|\n| Sàng lọc người 45–75 tuổi nguy cơ trung bình | FIT hoặc máu ẩn nhạy cao mỗi năm; DNA phân mỗi 3 năm; **soi toàn bộ mỗi 10 năm**; CT ảo, soi sigma mỗi 5 năm | Test khác dương tính → **nội soi**; nguy cơ cao: chủ yếu nội soi, bắt đầu sớm hơn | {{SY5 tr.61–62}} |\n| Triệu chứng nghi ngờ | **Nội soi đại tràng ống mềm** + sinh thiết | Thấy UT đồng thời ~3% hoặc polyp | {{Y5 tr.272; QĐ2549 tr.2–3}} |\n| Tắc ruột, thủng (cấp cứu) | X-quang bụng không chuẩn bị | | {{QĐ2549 tr.3}} |\n| U trực tràng thấp/ giữa | Thăm trực tràng + **soi ống cứng** + sinh thiết | Thăm trực tràng **không đơn độc** để xếp giai đoạn | {{Y5 tr.287}} |\n| Xếp giai đoạn tại chỗ, trực tràng | **MRI chậu** (diện cắt bên ≤1 mm, mạc treo, hạch); siêu âm qua trực tràng (T ==87%==, N ==74%==) | CT: nhạy/đặc hiệu xâm lấn 78%/63% → không dùng đơn độc | {{Y5 tr.287–289}} |\n| Tìm di căn xa | CT bụng-chậu + X-quang/CT ngực | CT thấy ==99%== di căn gan, 33% phúc mạc; chưa rõ bản chất tổn thương gan → MRI hoặc PET | {{Y5 tr.273}} |\n| Tiên lượng, theo dõi | **CEA** trước mổ; theo dõi tái phát (nhạy ==70–80%==) | CEA trước mổ cao mà không về bình thường sau mổ → còn bệnh | {{Y5 tr.273}} |\n| Đại tràng giai đoạn II | MSI (PCR) hoặc MMR (hóa mô miễn dịch) | dMMR/MSI-H: tiên lượng tốt, không lợi từ 5-FU bổ trợ | {{QĐ2549 tr.3}} |\n| Ung thư di căn | KRAS, NRAS, BRAF | Tiên lượng và thuốc đích | {{QĐ2549 tr.3}} |\n| Sau mổ triệt căn | Mô bệnh học: độ mô học, T, ≥12 hạch, diện cắt, xâm lấn mạch/thần kinh | | {{QĐ2549 tr.3}} |\n| Bướu tắc, không soi toàn bộ được trước mổ | Soi đại tràng trong **6 tháng** sau mổ | | {{Y5 tr.282}} |\n| CEA tăng, hình ảnh âm tính | **PET/CT** | | {{QĐ2549 tr.23}} |\n| Theo dõi sau điều trị | CEA, CT ngực-bụng-chậu; soi đại trực tràng giám sát 3–5 năm/lần đến 75 tuổi | Lịch chi tiết khác nhau giữa QĐ2549 và Y5 (xem trang bệnh) | {{QĐ2549 tr.23; Y5 tr.282}} |\n\n- Chi tiết: [Ung thư đại trực tràng · 5.3](#/n/ung-thu-daitruc-trang/5) · [Ung thư đại trực tràng · 5.4](#/n/ung-thu-daitruc-trang/6)\n@@tab Phổi\n| Tình huống | Chọn | Lưu ý | Nguồn |\n|---|---|---|---|\n| Sàng lọc | **CT liều thấp** nhóm nguy cơ cao (Y5: 55–74 tuổi, ≥30 gói-năm, hằng năm đến 74) | X-quang ± đờm **không** giảm tử vong | {{Y5 tr.106}} |\n| Phát hiện tình cờ nốt đơn độc | Xem phim cũ; **CT cản quang**; **PET-CT** | Không tăng kích thước 2 năm thường không phải UT | {{Y5 tr.110}} |\n| Nốt tăng kích thước | **Sinh thiết** (xuyên thành ngực FNA/ lõi kim, hoặc mở ngực); soi phế quản nếu trung tâm | Nguy cơ thấp (<40 tuổi, không hút, <2 cm, không đổi): CT theo dõi | {{Y5 tr.110}} |\n| Nghi ung thư phổi | CT ngực + bụng cản quang; X-quang phổi | **Không** MRI não thường quy nếu không triệu chứng | {{Y5 tr.111}} |\n| Đau xương | Xạ hình xương, X-quang vùng đau | | {{Y5 tr.111}} |\n| Tổn thương **trung tâm** | **Soi phế quản** sinh thiết/ chải-rửa (==97%==) | | {{Y5 tr.110–111}} |\n| Tổn thương **ngoại vi** | Sinh thiết xuyên thành ngực dưới CT | | {{Y5 tr.111}} |\n| Cần mô để làm hóa mô miễn dịch | Lõi kim hoặc sinh thiết một phần, không FNA | FNA không làm được hóa mô miễn dịch | {{Y5 tr.106}} |\n| Không sinh thiết được u phổi | Sinh thiết hạch thượng đòn/ ổ di căn + hóa mô miễn dịch; tế bào học đờm, dịch màng phổi | | {{QĐ1514 tr.PDF 244}} |\n| Chuẩn bị mổ, xếp giai đoạn chính xác | **PET-CT + soi trung thất**; FEV1 ≥ 2 L / 1 L / 0,6 L (cắt phổi / thùy / phân thùy) | | {{Y5 tr.111–112}} |\n| Nghi di căn não | CT sọ não, **MRI sọ não** (số lượng, kế hoạch dao gamma) | | {{QĐ1514 tr.PDF 243}} |\n| NSCLC giai đoạn muộn | Đột biến gen, **PD-L1** (chốt kiểm miễn dịch) | | {{Y5 tr.110}} |\n| Nghi viêm phổi / tràn dịch màng phổi | X-quang lại sau kháng sinh 1 tháng / sau chọc hết dịch | UT: không biến mất / thấy khối | {{QĐ1514 tr.PDF 244}} |\n| Theo dõi sau điều trị | NSCLC sớm: CT mỗi 6 tháng × 2 năm; giai đoạn IV: CT mỗi 2–3 chu kỳ hóa trị, **không** PET-CT | SCLC: NSE, CEA, ProGRP | {{Y5 tr.124; QĐ1514 tr.PDF 244}} |\n\n- Chi tiết: [Ung thư phổi · 5.3](#/n/ung-thu-phoi/5) · [Ung thư phổi · 5.4](#/n/ung-thu-phoi/6)\n@@end\n\n> [!warn] Các điểm khác nhau giữa nguồn cần nhớ khi chọn\n> - Tuổi bắt đầu nhũ ảnh: QĐ3898 = **40 tuổi** mỗi năm; SY5 (ACS 2015) = **45 tuổi** (40–44 tùy chọn) {{QĐ3898 tr.21; SY5 tr.56}}.\n> - Tuổi bắt đầu sàng lọc đại trực tràng: SY5 ghi >50 tuổi ở slide đầu nhưng khuyến cáo ACS là **45–75 tuổi** {{SY5 tr.57, 61}}.\n> - Sàng lọc phổi: Y5 = 55–74 tuổi, ≥30 gói-năm; tài liệu không nêu hướng dẫn tầm soát phổi của Bộ Y tế {{Y5 tr.106}}.\n\n### Điểm hay thi\n> [!warn] Bẫy thường gặp\n> - Sàng lọc ung thư vú nguy cơ trung bình 40–70 tuổi: **nhũ ảnh mỗi năm** + khám lâm sàng, thêm **siêu âm** khi mô đặc; **siêu âm không dùng đơn độc**.\n> - BI-RADS 3 → theo dõi 6 tháng; BI-RADS 4–5 → sinh thiết; túi ngực → **Eklund** hoặc MRI + siêu âm.\n> - Mang thai: không tiêm cản từ khi chụp MRI vú; nhũ ảnh không chống chỉ định nhưng có thể hoãn ngắn.\n> - Cổ tử cung: **Pap ≥ ASC-H hoặc HPV 16/18 (+)** → soi cổ tử cung + sinh thiết; MRI cho bướu, PET/CT cho hạch.\n> - Đại trực tràng: nghi ngờ → **nội soi toàn bộ + sinh thiết**; trực tràng: **MRI chậu**; CEA tăng + hình ảnh âm → PET/CT.\n> - Phổi: tổn thương trung tâm → soi phế quản (97%); ngoại vi → xuyên thành ngực dưới CT; cần hóa mô miễn dịch → lõi kim, không FNA.\n> - NSCLC giai đoạn IV theo dõi bằng CT, **không** PET-CT; không MRI não thường quy ở người không triệu chứng.\n> - Dấu ấn máu (CA15-3, CEA…) **không** dùng sàng lọc."}, {"kind": "foundation", "disease": "", "short": "Phương tiện và vai trò CLS", "group": "Khái quát cận lâm sàng", "section": 4, "order": 1, "khung": [], "id": "ung-thu-cls-vai-tro", "title": "Cận lâm sàng trong ung thư: phương tiện và vai trò", "layer": "cls", "module": "ung-buou", "tags": ["cận lâm sàng", "hình ảnh", "nội soi", "sinh thiết", "dấu ấn", "sàng lọc", "phân giai đoạn", "theo dõi", "đáp ứng"], "source": "SY5 tr. 117–149; Y5 (vú tr. 7–14, cổ tử cung tr. 62–74, phổi tr. 106–124, đại trực tràng tr. 272–289); QĐ3128; QĐ3898; QĐ2549; QĐ1514", "body": "> [!key] Tóm tắt\n> - Quy trình chung: **lâm sàng → cận lâm sàng; không xâm lấn → xâm lấn** {{SY5 tr.119}}. Không dùng phương tiện tùy tiện, phải dựa trên bệnh học và diễn tiến tự nhiên của từng ung thư {{SY5 tr.147}}\n> - Mỗi phương tiện phục vụ một hoặc nhiều **vai trò**: sàng lọc · chẩn đoán xác định · phân giai đoạn · lập kế hoạch điều trị · đánh giá đáp ứng · theo dõi, phát hiện tái phát\n> - ==Mô bệnh học là tiêu chuẩn vàng== chẩn đoán xác định; hình ảnh chỉ gợi ý, **không thay thế** bằng chứng mô học {{SY5 tr.128–131}}\n> - Dấu ấn máu: kém nhạy, kém đặc hiệu; {r|tầm soát bằng dấu ấn máu là sai} {{SY5 tr.135}}\n> - Bài này tổng hợp xuyên 4 bệnh (vú, cổ tử cung, đại trực tràng, phổi); chi tiết từng phương tiện: [[ung-thu-hinh-anh-chan-doan]] · [[ung-thu-noi-soi-lay-benh-pham]] · tình huống: [[ung-thu-cls-chon-phuong-tien]]\n\n### Trình tự cận lâm sàng khi nghi ngờ ung thư\n| Bước | Câu hỏi cần trả lời | Phương tiện | Nguồn |\n|---|---|---|---|\n| 1. Lâm sàng | Triệu chứng, tổn thương, hạch, tổng trạng | Hỏi bệnh; khám vùng tổn thương, hạch vùng, toàn thân | {{SY5 tr.123–124}} |\n| 2. Cơ quan mang bướu | Bướu ở đâu, bao nhiêu ổ | Nhìn/sờ được: khám. Sâu: X-quang, CT (phổi); siêu âm, CT, MRI (gan); CT, MRI, nội soi (ống tiêu hóa) | {{SY5 tr.126}} |\n| 3. Bản chất mô học | Ác tính thật không, loại gì | Sinh thiết (trọn bướu, **lõi kim**, kềm bấm qua nội soi); khi chưa có mô: tế bào học (FNAC, rút dịch) | {{SY5 tr.131–132}} |\n| 4. Giai đoạn | T, N, M | Khám + hình ảnh + nội soi (cTNM); sau mổ có GPB (pTNM) | {{SY5 tr.137–141}} |\n| 5. Đặc tính sinh học | Chọn thuốc, tiên lượng | Hóa mô miễn dịch, khảo sát gen | {{SY5 tr.142–143}} |\n| 6. Nhóm nguy cơ, thể trạng | Điều trị cá thể hóa | Tổng hợp bước 1–5 + KPS, WHO/ECOG | {{SY5 tr.144–145}} |\n- Có thể làm đủ nội dung **trước, trong hoặc sau mổ**; khai thác tối đa bệnh phẩm mổ {{SY5 tr.147}}.\n- Ví dụ trình tự theo từng bệnh:\n@@tabs\n@@tab Vú\n- Khám + X-quang vú 2 bên (siêu âm nếu cần) → đánh giá hạch nách → **sinh thiết/ mô bệnh học** → ER, PR, HER2, Ki67 → cân nhắc MRI vú → siêu âm bụng, X-quang ngực; xạ hình xương, CT, PET/CT **chỉ khi** có triệu chứng hoặc giai đoạn muộn {{QĐ3128 tr.30}}\n- Chi tiết: [Ung thư vú · 5.3](#/n/ung-thu-vu/5)\n@@tab Cổ tử cung\n- Khám mỏ vịt + tay → **sinh thiết kềm** ở bờ tổn thương → siêu âm bụng, CT/MRI bụng chậu → PET/CT khi nghi di căn xa hoặc đã có hạch → soi bàng quang, soi trực tràng, xạ hình xương khi có chỉ định {{Y5 tr.62–63}}\n- Chi tiết: [Ung thư cổ tử cung · 5.3](#/n/ung-thu-cotucung/5)\n@@tab Đại trực tràng\n- Thăm trực tràng → **nội soi toàn bộ đại tràng + sinh thiết** {{Y5 tr.272, 287}} → CT bụng-chậu + X-quang/CT ngực (trực tràng: MRI chậu) → CEA → TNM {{Y5 tr.273, 288–289}}\n- Chi tiết: [Ung thư đại trực tràng · 5.3](#/n/ung-thu-daitruc-trang/5)\n@@tab Phổi\n- X-quang, **CT ngực + bụng cản quang** → sinh thiết (soi phế quản hoặc xuyên thành ngực) → GPB; ca mổ được: PET-CT + soi trung thất; giai đoạn muộn: đột biến gen, PD-L1 {{Y5 tr.110–111}}\n- Chi tiết: [Ung thư phổi · 5.3](#/n/ung-thu-phoi/5)\n@@end\n\n### Bảng tổng hợp: phương tiện × vai trò\n> [!tip] Ký hiệu\n> ● vai trò chính, nguồn nêu rõ · ○ có điều kiện / hỗ trợ / hạn chế · ✗ nguồn nói **không** có giá trị · – tài liệu không nêu (để trống, không suy đoán).\n> Viết tắt: **Vú** · **CTC** (cổ tử cung) · **ĐTT** (đại trực tràng) · **Phổi**. Nhũ ảnh = X-quang tuyến vú.\n\n| Phương tiện | Sàng lọc | Chẩn đoán | Phân giai đoạn | Theo dõi / đánh giá đáp ứng | Ung thư thường dùng | Lưu ý |\n|---|---|---|---|---|---|---|\n| **HÌNH ẢNH** | | | | | | |\n| X-quang ngực | ✗ Phổi: X-quang ± tế bào học đờm không giảm tử vong {{Y5 tr.106}} | ● Phổi: đám mờ, TDMP, vị trí, kích thước, khả năng mổ {{QĐ1514 tr.PDF 243}} | ● Vú, CTC, ĐTT: loại trừ di căn phổi {{QĐ3128 tr.7; Y5 tr.63, 288}} | ○ Vú: chụp X-quang ngực sau mỗi 3–4 đợt điều trị bổ trợ {{QĐ3128 tr.27}} | Phổi, vú, CTC, ĐTT | X-quang bụng không chuẩn bị: ĐTT khi tắc ruột, thủng {{QĐ2549 tr.3}} |\n| Nhũ ảnh | ● Vú: duy nhất được chứng minh giảm tử vong; mỗi năm từ 40 tuổi (nguy cơ trung bình) {{QĐ3898 tr.21}} | ● Vú: khối, vi vôi hóa, xáo trộn cấu trúc; xếp BI-RADS {{Y5 tr.7; QĐ3898 tr.23}} | ● Vú: đánh giá bướu và hạch cùng siêu âm, MRI {{Y5 tr.14}} | ● Vú: nhũ ảnh hằng năm sau điều trị {{QĐ3128 tr.27}} | Vú | ==Âm tính không loại trừ== (~10% khối sờ thấy không thấy) {{Y5 tr.7}}; mô đặc C/D thêm siêu âm {{QĐ3898 tr.23}} |\n| Siêu âm vú, bụng | ○ Vú: không dùng đơn độc; thêm khi mô vú đặc {{QĐ3898 tr.24}} | ● Vú: nang hay đặc, <35 tuổi, hướng dẫn sinh thiết {{Y5 tr.9–10}} | ● Vú: hạch nách (ổ dãn >2,5 mm, mất rốn) {{Y5 tr.10}}; ● CTC: ứ nước thận, hạch, gan {{Y5 tr.63}}; ○ ĐTT, phổi, vú: siêu âm bụng tìm di căn {{QĐ2549 tr.3; QĐ1514 tr.PDF 243; QĐ3128 tr.7}} | ○ Vú: siêu âm vú hằng năm sau điều trị I–III {{QĐ3128 tr.28}}; siêu âm bụng sau 3–4 đợt điều trị {{QĐ3128 tr.27}} | Vú, CTC, ĐTT, phổi | Phụ thuộc người làm; khó thấy vi vôi hóa; không bức xạ {{QĐ3898 tr.24–25}} |\n| Siêu âm qua trực tràng | – | – | ● ĐTT (trực tràng): mức xâm lấn T ==87%==, hạch ==74%== (phân tích gộp) {{Y5 tr.288}} | – | ĐTT | Phụ thuộc người thực hiện; MRI hơn về phạm vi, ít phụ thuộc người {{Y5 tr.288–289}} |\n| CT | ○ Phổi: **CT liều thấp** ở nhóm nguy cơ cao (NLST giảm ==20%== tử vong do UT phổi) {{Y5 tr.106}}; ○ ĐTT: CT đại tràng ảo mỗi 5 năm {{SY5 tr.61}} | ● Phổi: CT ngực + bụng cản quang (thấy hai thượng thận) {{Y5 tr.111}} | ● CTC: CT/MRI bụng chậu thường quy {{Y5 tr.63}}; ● ĐTT: CT bụng-chậu + ngực {{Y5 tr.273}}; ● Vú III–IV: CT ngực, bụng, chậu {{QĐ3128 tr.37–38}} | ● Phổi: CT ngực mỗi 6 tháng × 2 năm (giai đoạn sớm); mỗi 2–3 chu kỳ hóa trị (giai đoạn IV) {{Y5 tr.124}}; ● ĐTT: CT 3–6 tháng/lần × 2 năm đầu {{QĐ2549 tr.23}} | Phổi, ĐTT, CTC, vú | ĐTT: CT cho T4 ==86%==, di căn gan ==99%==, phúc mạc 33% {{Y5 tr.273}}; trực tràng: CT không dùng đơn độc đánh giá bướu {{Y5 tr.288}} |\n| MRI | ○ Vú: chỉ nhóm **nguy cơ cao**; nhạy hơn nhũ ảnh, đặc hiệu thấp {{QĐ3898 tr.26}} | ● Vú: khi không tương hợp lâm sàng–nhũ ảnh–siêu âm; ung thư tiềm ẩn (hạch nách) {{Y5 tr.10}} | ● CTC: tốt nhất đánh giá bướu {{Y5 tr.63}}; ● Trực tràng: MRI chậu (diện cắt bên ≤1 mm) {{Y5 tr.289}}; ● Vú: trước bảo tồn, trước tân bổ trợ {{QĐ3128 tr.7}}; ● Phổi: MRI sọ não khi nghi di căn não {{QĐ1514 tr.PDF 243}} | ● Vú: đáp ứng sau tân hỗ trợ; phân biệt tái phát với sẹo {{Y5 tr.10}}; ○ Trực tràng: đánh giá sau hóa-xạ trước mổ {{Y5 tr.288}} | Vú, CTC, trực tràng, phổi | Cần cản từ, giá cao, có chống chỉ định (kim loại không tương thích, thai nếu tiêm cản từ) {{QĐ3898 tr.26}}; phổi: không MRI não thường quy nếu không triệu chứng {{Y5 tr.111}} |\n| PET/CT | – | ● Phổi: nốt đơn độc, nhạy ==96%==, đặc hiệu ==75%== {{Y5 tr.110}} | ● CTC: tốt nhất cho hạch (nhạy >80%, đặc hiệu >95%) và di căn xa {{Y5 tr.63}}; ● ĐTT: di căn khi chẩn đoán ban đầu {{Y5 tr.289}}; ○ Vú: tùy điều kiện, giai đoạn III–IV {{QĐ3128 tr.37–38}} | ● ĐTT: tái phát khi CEA tăng mà hình ảnh âm {{QĐ2549 tr.23}}; đáp ứng bệnh học sau hóa-xạ trước mổ {{Y5 tr.289}}; ✗ NSCLC giai đoạn IV: không có vai trò PET-CT khi theo dõi {{Y5 tr.124}} | Phổi, CTC, ĐTT, vú | Dương giả: lao, bệnh mô bào; âm giả: <1 cm, ung thư chuyển hóa thấp {{Y5 tr.110}}; dùng mô phỏng xạ trị {{QĐ3128 tr.8}} |\n| Xạ hình xương (SPECT/CT 99mTc-MDP), y học hạt nhân khác | – | – | ● Vú: thấy di căn xương sớm hơn CT, MRI {{QĐ3128 tr.7}}; ○ CTC, phổi: khi đau xương {{Y5 tr.63, 111}}; ● ĐTT: xạ hình xương, gan (Tc99m-SC) {{QĐ2549 tr.3}} | ○ Vú, CTC, phổi: theo dõi đáp ứng, tái phát {{QĐ3128 tr.7; QĐ1514 tr.PDF 243}} | Vú, CTC, ĐTT, phổi | Vú: xạ hình hạch cửa 99mTc-nanocolloid {{QĐ3128 tr.8}}; CTC, phổi: xạ hình thận chức năng trước/sau điều trị {{QĐ1514 tr.PDF 243}} |\n| **NỘI SOI VÀ THỦ THUẬT** | | | | | | |\n| Nội soi đại trực tràng | ● ĐTT: toàn bộ đại tràng mỗi ==10 năm== (ưu tiên vì cắt được polyp); mọi test khác dương tính → nội soi {{SY5 tr.60–62}} | ● ĐTT: vị trí, sinh thiết; UT đồng thời ~3% {{Y5 tr.272}} | ● Trực tràng ống cứng: cách rìa hậu môn, chu vi, liên quan cơ thắt {{Y5 tr.287}} | ● ĐTT: soi giám sát, 3–5 năm/lần đến 75 tuổi {{QĐ2549 tr.23}} | ĐTT | Soi toàn bộ loại trừ UT đồng thời 2–8% {{Y5 tr.287}} |\n| Nội soi phế quản, soi trung thất | – | ● Phổi trung tâm: sinh thiết hoặc chải-rửa cho GPB ==97%== {{Y5 tr.110}} | ● Phổi: soi trung thất sinh thiết hạch; PET-CT + soi trung thất chính xác hơn {{Y5 tr.111}} | – | Phổi | Ngoại vi: sinh thiết xuyên thành ngực dưới CT {{Y5 tr.111}} |\n| Soi cổ tử cung (Schiller, acid acetic, nạo cổ trong, khoét chóp) | ○ Không phải test sàng lọc: dùng khi Pap ≥ ASC-H hoặc HPV 16/18 (+) {{Y5 tr.73}} | ● CTC: định hướng sinh thiết; khoét chóp vừa chẩn đoán vừa điều trị tại chỗ {{Y5 tr.73}} | – | – | CTC | Schiller: vùng không bắt màu nâu là vùng nghi ngờ {{Y5 tr.73}} |\n| Soi bàng quang, soi trực tràng (CTC) | – | – | ● CTC: khi nghi xâm lấn (tiểu máu, mót rặn, dò) hoặc giai đoạn IIIB {{Y5 tr.63}} | – | CTC | – |\n| **TẾ BÀO HỌC VÀ SÀNG LỌC CỔ TỬ CUNG** | | | | | | |\n| Pap | ● CTC: từ 21 tuổi, Pap mỗi 3 năm (ACS/ACOG 2012) {{Y5 tr.72}} | ✗ Là xét nghiệm tầm soát, không phải chẩn đoán {{Y5 tr.72}} | – | – | CTC | Nhạy ==50–60%==, đặc hiệu ==90–95%== (Y5); slide: 37–84% / 86–100% {{Y5 tr.72; SY5 tr.107}} |\n| HPV-DNA | ● CTC: giá trị tiên đoán âm rất cao; giãn khoảng cách 5–10 năm {{Y5 tr.72}} | – | – | – | CTC | Dương tính cao ở người trẻ {{SY5 tr.108}} |\n| VIA (acid acetic) | ● CTC: nhạy ==81%==, đặc hiệu ==83%==; hợp nơi thiếu nguồn lực {{Y5 tr.72}} | – | – | – | CTC | Dương giả → điều trị quá mức {{Y5 tr.72}} |\n| FNA, tế bào học đờm / dịch | – | ● Vú: FNA khối, hạch, dịch núm vú {{QĐ3128 tr.8}}; ● Phổi: đờm, dịch màng phổi, dịch rửa phế quản {{QĐ1514 tr.PDF 244}} | ○ Vú: chọc hút hạch nách dưới siêu âm {{Y5 tr.10}} | – | Vú, phổi | FNA vú không phân biệt xâm nhập với tại chỗ; FNA phổi không làm được hóa mô miễn dịch {{Y5 tr.11, 106}} |\n| Sinh thiết mô (kềm bấm, kim lõi, VABB, mở, xuyên thành ngực) | – | ● **Tiêu chuẩn vàng** mọi ung thư {{SY5 tr.131}}; vú: kim lõi 14–18G cho ER/PR/HER2 {{Y5 tr.11}}; CTC: kềm bấm ở bờ tổn thương, không cần gây tê {{Y5 tr.62}} | ● Sinh thiết ổ di căn đầu tiên (vú III–IV) {{QĐ3128 tr.38}}; sinh thiết hạch thượng đòn (phổi) {{QĐ1514 tr.PDF 244}} | ○ Vú: sinh thiết tổn thương tái phát, di căn mỗi khi có thể {{QĐ3128 tr.8}} | Cả 4 bệnh | Chi tiết: [[ung-thu-noi-soi-lay-benh-pham]] |\n| **XÉT NGHIỆM** | | | | | | |\n| Hóa mô miễn dịch, sinh học phân tử | – | ● Gợi ý nguồn gốc mô học {{SY5 tr.134}} | ● Vú: ER, PR, HER2, Ki67 {{QĐ3128 tr.9}}; ● ĐTT: MSI/MMR (giai đoạn II), KRAS/NRAS/BRAF (di căn) {{QĐ2549 tr.3}}; ● Phổi giai đoạn muộn: đột biến gen, chốt kiểm miễn dịch {{Y5 tr.110}} | ○ Vú: xét lại ER/PR/HER2 ở tái phát, di căn; GPB đánh giá đáp ứng sau tân bổ trợ {{QĐ3128 tr.8, 10}} | Vú, ĐTT, phổi | Chọn thuốc đích, tiên lượng: [[ung-thu-dau-an-sinh-hoc]] |\n| Dấu ấn u trong máu | ✗ Tầm soát bằng dấu ấn máu là sai; vú: CA15-3, CEA không có giá trị sàng lọc {{SY5 tr.135; QĐ3898 tr.17}} | ✗ Phần lớn nhạy/đặc hiệu không cao {{SY5 tr.135}} | ○ ĐTT: CEA trước mổ cao = tiên lượng xấu {{Y5 tr.273}} | ● ĐTT: CEA theo dõi tái phát (nhạy ==70–80%==) {{Y5 tr.273}}; ● CTC: SCC, CEA, CA12-5 {{QĐ1514 tr.PDF 361}}; ● SCLC: NSE, CEA, ProGRP {{QĐ1514 tr.PDF 244}}; ○ Vú: CA15-3 chỉ hỗ trợ đánh giá đáp ứng bệnh di căn {{Y5 tr.14}} | ĐTT, CTC, phổi, vú | Vú: CA15-3 không có vai trò chẩn đoán, theo dõi giai đoạn sớm {{Y5 tr.14}} |\n| Máu ẩn trong phân (FOBT/FIT), DNA phân | ● ĐTT: FIT hoặc máu ẩn nhạy cao mỗi năm; DNA phân đa đích mỗi 3 năm {{SY5 tr.62}} | – | – | – | ĐTT | Ít sang chấn nhưng ít phát hiện polyp {{SY5 tr.60}} |\n\n### Vai trò \"lập kế hoạch điều trị\" (ngoài 4 cột trên)\n- **Vú**: MRI trước bảo tồn, trước tân bổ trợ {{QĐ3128 tr.7}}; PET/CT mô phỏng xạ trị {{QĐ3128 tr.8}}; hạch cửa bằng đồng vị phóng xạ {{QĐ3128 tr.8}}.\n- **CTC, phổi**: PET/CT mô phỏng lập kế hoạch xạ trị {{QĐ1514 tr.PDF 243, 361}}; phổi: MRI sọ não lập kế hoạch dao gamma {{QĐ1514 tr.PDF 243}}.\n- **Trực tràng**: MRI chậu xếp giai đoạn tại chỗ để chọn điều trị trước mổ {{Y5 tr.288}}; ĐTT: PET/CT mô phỏng xạ trị (trực tràng) {{QĐ2549 tr.3}}.\n- **Phổi**: FEV1 trước mổ ≥ ==2 L== (cắt phổi), ==1 L== (cắt thùy), ==0,6 L== (cắt phân thùy) {{Y5 tr.112}}.\n- **Mọi bệnh**: đặc tính sinh học → thuốc đích; nhóm nguy cơ + thể trạng → điều trị cá thể hóa {{SY5 tr.142–145}}.\n\n### Vai trò \"đánh giá đáp ứng\" theo thời điểm (tóm tắt)\n- Vú (QĐ3128): bổ trợ/tân bổ trợ đánh giá sau mỗi 3–4 đợt (khám, siêu âm bụng, X-quang ngực; tân bổ trợ thêm siêu âm vú, MRI vú); bệnh di căn: lặp lại hình ảnh sau mỗi 2–4 đợt, CA15-3, CA27-29, CEA trước mỗi đợt {{QĐ3128 tr.27}}.\n- Phổi NSCLC giai đoạn IV: CT ngực mỗi 2–3 chu kỳ hóa trị {{Y5 tr.124}}.\n- Trực tràng sau hóa-xạ trước mổ: MRI và PET/CT đánh giá mức giảm giai đoạn, đáp ứng bệnh học {{Y5 tr.288–289}}.\n- Ví dụ từ ung thư khác trong Y5 (không thuộc 4 bệnh): đầu cổ, hình ảnh đánh giá đáp ứng khoảng **12 tuần** sau xạ/hóa-xạ; chụp PET/CT quá sớm dễ cho dương giả {{Y5 tr.146}}.\n\n### Liên kết sang từng bệnh\n| Bệnh | Cận lâm sàng | Chẩn đoán |\n|---|---|---|\n| Vú | [Ung thư vú · 5.3](#/n/ung-thu-vu/5) | [Ung thư vú · 5.4](#/n/ung-thu-vu/6) |\n| Cổ tử cung | [Ung thư cổ tử cung · 5.3](#/n/ung-thu-cotucung/5) | [Ung thư cổ tử cung · 5.4](#/n/ung-thu-cotucung/6) |\n| Đại trực tràng | [Ung thư đại trực tràng · 5.3](#/n/ung-thu-daitruc-trang/5) | [Ung thư đại trực tràng · 5.4](#/n/ung-thu-daitruc-trang/6) |\n| Phổi | [Ung thư phổi · 5.3](#/n/ung-thu-phoi/5) | [Ung thư phổi · 5.4](#/n/ung-thu-phoi/6) |\n\n### Điểm hay thi\n> [!warn] Bẫy thường gặp\n> - Quy trình chẩn đoán đi **từ lâm sàng đến cận lâm sàng, từ không xâm lấn đến xâm lấn**; chẩn đoán xác định bằng **mô bệnh học**.\n> - **Nhũ ảnh** là biện pháp duy nhất được chứng minh giảm tử vong (QĐ3898), nhưng âm tính không loại trừ ung thư vú; **MRI vú** nhạy nhất, đặc hiệu thấp, chỉ sàng lọc nhóm nguy cơ cao.\n> - Cổ tử cung: **MRI** tốt nhất đánh giá bướu, **PET/CT** tốt nhất đánh giá hạch và di căn xa; Pap, HPV-DNA, VIA là **sàng lọc**, không phải chẩn đoán; Pap ≥ ASC-H hoặc HPV 16/18 (+) → soi cổ tử cung + sinh thiết.\n> - Trực tràng: **MRI chậu** (diện cắt bên) hơn siêu âm qua trực tràng và CT khi xếp giai đoạn T; thăm trực tràng không dùng đơn độc; **CEA** theo dõi tái phát.\n> - Phổi: X-quang ± đờm không dùng sàng lọc, **CT liều thấp** cho nhóm nguy cơ cao; nội soi phế quản chẩn đoán ==97%== tổn thương trung tâm; không MRI não thường quy ở người không triệu chứng.\n> - PET-CT: có dương giả (lao, bệnh mô bào) và âm giả (<1 cm, chuyển hóa thấp); NSCLC giai đoạn IV theo dõi **không** dùng PET-CT.\n> - **Không** tầm soát bằng dấu ấn máu; CA15-3 không có giá trị sàng lọc ung thư vú.\n> - Ung thư vú giai đoạn sớm **không** tầm soát di căn xa thường quy; chỉ khi có triệu chứng hoặc giai đoạn III–IV."}, {"kind": "foundation", "disease": "", "short": "", "group": "Cơ chế", "section": 0, "order": 1, "khung": [], "id": "ung-thu-co-che-sinh-ung", "title": "Cơ chế sinh ung thư (tổng quan)", "layer": "nen", "module": "ung-buou", "tags": ["ung thư", "sinh ung", "đa giai đoạn", "đột biến", "gen sinh ung", "gen đè nén bướu"], "source": "Y2 tr. 1–3, 14–16; SY2 tr. 1–6, 14, 54–59, 79", "body": "> [!key]\n> - Ung thư = rối loạn do **tích lũy tổn thương di truyền** → tế bào có ưu thế tăng trưởng, tăng sinh không kiểm soát {{Y2 tr.1}}\n> - Là tiến trình **đa giai đoạn**: khởi đầu → thúc đẩy → tiến triển; cần ==nhiều loại đột biến hiệp đồng + thời gian== {{SY2 tr.54–55}}\n> - **4 nhóm gen** hay đột biến: sửa chữa DNA, tiền gen sinh ung, đè nén bướu, điều hòa apoptosis {{SY2 tr.14}}\n> - Gen và ngoài gen (biểu sinh) đều chủ yếu do **môi trường**, chỉ số ít do di truyền {{Y2 tr.14}}\n\nBài tổng quan; chi tiết ở [[ung-thu-sua-chua-dna]], [[ung-thu-oncogene-gen-uc-che-u]], [[ung-thu-telomere-chet-te-bao]], [[ung-thu-bieu-sinh]]. Nguyên nhân: [[ung-thu-nguyen-nhan]]. Phân tử và điều trị đích: [[ung-thu-sinh-hoc-phan-tu]].\n\n### Mục tiêu học tập\n- DNA tổn thương – sửa chữa · tiền gen sinh ung/gen sinh ung/đường dẫn truyền · gen đè nén bướu + mất dị hợp tử · telomere/telomerase · chết TB theo lập trình · cơ chế ngoài gen {{Y2 tr.1}}\n\n### Đại cương\n- Toàn cầu 2018: ==18,1 triệu== ca mới, ==9,6 triệu== tử vong {{Y2 tr.1}}\n- Kiểu hình bướu ác: **tăng trưởng quá mức · xâm lấn mô lân cận · di căn xa** {{Y2 tr.1}}\n- Quan điểm Nowell: một số tế bào tích lũy tổn thương di truyền → ưu thế tăng trưởng hơn tế bào bình thường {{SY2 tr.5}}\n\n| Nhóm gen | Kiểu đột biến | Ví dụ trong nguồn |\n|---|---|---|\n| Sửa chữa DNA | **Mất** chức năng | MSH2, MLH1, BRCA1/2 |\n| Tiền gen sinh ung → gen sinh ung | **Tăng** chức năng | RAS, RET, EGFR, HER2, BCR-ABL |\n| Gen đè nén bướu | Mất chức năng (cả 2 alen) | Rb, p53, APC |\n| Điều hòa apoptosis | Tăng **hoặc** mất | Bcl-2 (sinh ung), p53, PTEN (đè nén) |\n\n### Sinh ung đa giai đoạn\n@@tabs\n@@tab 3 pha (Berenblum–Schubik 1948)\n1. **Khởi đầu**: xảy ra đột biến\n2. **Thúc đẩy**: tích lũy đột biến\n3. **Tiến triển**: hình thành ung thư giai đoạn sớm {{SY2 tr.54}}\n- {b|Điều kiện cần}: nhiều loại đột biến (gen sinh ung + đè nén bướu) hiệp đồng\n- {b|Điều kiện đủ}: **thời gian** tích lũy → ung thư hay gặp ở người lớn tuổi {{SY2 tr.55}}\n@@tab 4 giai đoạn (bài Nguyên nhân)\n| Giai đoạn | Nội dung |\n|---|---|\n| Tế bào khơi mào | DNA adduct; hoạt hóa tiền gen sinh ung / bất hoạt gen đè nén bướu |\n| Tổn thương tiền ung | Chọn lọc dòng TB |\n| Tạo thành ung thư | Thêm đột biến, tiềm năng xâm lấn, di căn |\n| Ung thư lâm sàng | Mất ổn định hệ gen, tăng sinh không kiểm soát |\n\n{{Y2 tr.15–16}} · xem [[ung-thu-nguyen-nhan]]\n@@tab Mô hình đại tràng\n- APC mất chức năng → **polyp**\n- K-ras + gen vùng DCC (NST 18) → polyp lớn hơn\n- p53 mất chức năng → **carcinôm ác tính**; cần thêm đột biến để xâm lấn, di căn {{SY2 tr.56–57}}\n- Vì sao chọn đại tràng: tiến triển tuần tự; tiếp cận qua nội soi/sinh thiết\n- Chi tiết bệnh: [Ung thư đại trực tràng](#/n/ung-thu-daitruc-trang/3)\n@@end\n\n> [!tip] Sơ đồ tổng hợp (SY2 tr.59)\n> Tác nhân (hóa chất, phóng xạ, virút) → tổn thương DNA → **sửa chữa thất bại** → hoạt hóa gen sinh ung + bất hoạt đè nén bướu + đổi gen apoptosis → tăng trưởng dòng TB, tăng sinh mạch, thoát miễn dịch → tiến triển, xâm lấn, di căn.\n\n- Rút ra: cần tích lũy nhiều đột biến (cũng là **rào cản** sinh ung); kỹ thuật sinh học phân tử giúp phân biệt bướu nguyên phát với tổn thương di căn và nhận biết bướu nguyên phát dễ di căn xa {{SY2 tr.58}}\n\n> [!warn] Kết luận của nguồn\n> Rối loạn gen + ngoài gen **chủ yếu do môi trường** (lý, hóa, sinh học); chỉ một số ít do di truyền {{Y2 tr.14}} {{SY2 tr.79}}\n\n### Điểm hay thi\n> [!warn]\n> - Nhóm gen nào **mất** chức năng, nhóm nào **tăng** (sinh ung), nhóm nào **tăng hoặc mất** (apoptosis)\n> - Gen đè nén bướu cần mất **cả 2 alen**; gen sinh ung chỉ cần 1 alen đột biến tăng chức năng\n> - Điều kiện cần (nhiều đột biến) vs điều kiện đủ (thời gian)\n> - Thứ tự đại tràng: APC → K-ras/DCC → p53\n\n### Tự kiểm tra\n- Nowell: ung thư là gì ở mức phân tử? :: Tăng trưởng quá mức do tích lũy tổn thương di truyền, tạo ưu thế tăng trưởng\n- Ba pha sinh ung theo Berenblum và Schubik? :: Khởi đầu, thúc đẩy, tiến triển\n- Điều kiện cần và đủ của sinh ung đa giai đoạn? :: Cần: nhiều đột biến hiệp đồng; đủ: thời gian tích lũy\n- Bốn nhóm gen có đột biến gây ung thư và kiểu đột biến? :: Sửa chữa DNA (mất); sinh ung (tăng); đè nén bướu (mất); điều hòa apoptosis (tăng hoặc mất)\n- Trình tự đột biến trong mô hình ung thư đại tràng? :: APC mất chức năng → K-ras/DCC → p53 mất chức năng → thêm đột biến để xâm lấn, di căn\n- Vì sao ung thư đại tràng là mô hình nghiên cứu tốt? :: Tiến triển tuần tự; tiếp cận qua nội soi để quan sát và sinh thiết\n- Rối loạn gen và ngoài gen chủ yếu do gì? :: Môi trường (vật lý, hóa học, sinh học); số ít do di truyền\n- Số ca mới mắc và tử vong ung thư toàn cầu 2018? :: 18,1 triệu mới mắc; 9,6 triệu tử vong\n- Ba đặc trưng kiểu hình của bướu ác? :: Tăng trưởng quá mức, xâm lấn mô lân cận, di căn xa"}, {"kind": "foundation", "disease": "", "short": "", "group": "Triệu chứng và chẩn đoán chung", "section": 4, "order": 4, "khung": [], "id": "ung-thu-dau-an-sinh-hoc", "title": "Dấu ấn sinh học và hóa mô miễn dịch trong ung thư", "layer": "cls", "module": "ung-buou", "tags": ["dấu ấn sinh học", "hóa mô miễn dịch", "biomarker", "thuốc đích", "CEA", "PSA", "AFP"], "source": "SY5 tr. 134–135, 142–143 (đọc từ ảnh)", "body": "> [!key] Tóm tắt\n> - **Hóa mô miễn dịch** (pan-keratin, CD45, S100/HMB45, vimentin) gợi ý **nguồn gốc mô học** {{SY5 tr.134}}\n> - Dấu ấn trong máu: đa số **nhạy/đặc hiệu thấp** → ít giá trị chẩn đoán; {r|tầm soát ung thư sớm bằng dấu ấn máu là SAI} {{SY5 tr.135}}\n> - Biomarker phân tử (HER2, ER, BCR-ABL, BRCA, BRAF, ALK) → chọn **thuốc đích**, tiên đoán đáp ứng {{SY5 tr.142–143}}\n\n@@tabs\n@@tab Hóa mô miễn dịch\n| Loại ung thư | Pan-keratin | CD45 | S100, HMB45 | Vimentin |\n|---|---|---|---|---|\n| **Carcinôm** | + | − | − | −/+ |\n| **Lymphôm** | − | + | − | −/+ |\n| **Mêlanôm** | − | − | + | + |\n| **Sarcôm** | − | − | − | + |\n{{SY5 tr.134}}\n> [!tip] Mẹo nhớ\n> Keratin = carcinôm (biểu mô); CD45 = lymphôm (bạch cầu); S100/HMB45 = mêlanôm; chỉ vimentin dương = sarcôm.\n@@tab Dấu ấn trong máu\n- Một số dấu ấn máu gợi ý bản chất mô học, nhưng đa số **độ nhạy, độ đặc hiệu không cao**\n- ✓ = có vai trò theo slide:\n\n| Loại bướu | Dấu ấn | Tầm soát | Chẩn đoán | Tiên lượng | Theo dõi |\n|---|---|---|---|---|---|\n| Carcinôm tuyến | CEA | | | | ✓ |\n| Carcinôm tế bào gai | SCC | | | | ✓ |\n| Thần kinh nội tiết | NSE, chromogranin A | | | | ✓ |\n| Germinôm | hCG, AFP, LDH | | ✓ | ✓ | ✓ |\n| Phổi | Không khuyến cáo | | | | |\n| Vú | CA 15-3 (không khuyến cáo) | | | | |\n| Tuyến tiền liệt | **PSA** | ✓ | | ✓ | ✓ |\n| Đại tràng | **CEA** | | | ✓ | ✓ |\n| Tụy | **CA 19-9** | | | ✓ | ✓ |\n| Gan | **AFP** | ✓ | ✓ | ✓ | ✓ |\n| Buồng trứng | **CA 125** | | | | ✓ |\n{{SY5 tr.135}}\n> [!warn] Bẫy\n> Bài giảng này ghi tầm soát chỉ có ở **PSA** và **AFP**; nhưng câu kết luận của slide vẫn là tầm soát phát hiện sớm bằng dấu ấn máu nói chung là sai. Tầm soát từng ung thư xem bài riêng ([[ung-thu-tam-soat-nguyen-tac]]).\n@@tab Biomarker – thuốc đích\nXét nghiệm ở mức phân tử nhằm: **phân loại bướu, chọn điều trị, tiên đoán đáp ứng, tiên lượng**.\n\n| Biomarker | Đặc điểm | Ung thư | Thuốc | Đích |\n|---|---|---|---|---|\n| HER2 | Khuếch đại gen, tăng biểu hiện protein | Vú | {p|Trastuzumab} (slide ghi \"Traztuzumab\") | HER2 |\n| ER | Tăng biểu hiện protein | Vú | {p|Tamoxifen} | ER |\n| BCR-ABL | Chuyển vị gen | CML | {p|Imatinib} | BCR-ABL |\n| BRCA1/2 | Đột biến gen | Vú | {p|Olaparib} | PARP |\n| BRAF-V600E | Đột biến gen | Mêlanôm | {p|Vemurafenib} | BRAF |\n| ALK | Tái sắp xếp | Phổi không tế bào nhỏ | {p|Crizotinib} | ALK |\n{{SY5 tr.143}}\n@@end\n\n### Điểm hay thi\n> [!warn]\n> - Tầm soát ung thư sớm bằng dấu ấn sinh học máu = **sai**, nhiều hệ lụy\n> - Cặp biomarker–thuốc: BCR-ABL–imatinib; BRAF–vemurafenib; ALK–crizotinib; BRCA–olaparib (PARP); ER–tamoxifen; HER2–trastuzumab\n> - Pan-keratin(+) carcinôm; CD45(+) lymphôm; S100/HMB45(+) mêlanôm\n> - AFP: có vai trò ở cả 4 cột (gan); CA 125 buồng trứng chỉ theo dõi\n\n### Tự kiểm tra\n- Dấu ấn máu có dùng tầm soát ung thư sớm được không? :: Không; nhạy/đặc hiệu thấp nên tầm soát bằng dấu ấn là sai, gây nhiều hệ lụy\n- Pan-keratin(+) gợi ý? :: Carcinôm\n- CD45(+) gợi ý? :: Lymphôm\n- S100, HMB45(+) gợi ý? :: Mêlanôm\n- Chỉ vimentin (+) gợi ý? :: Sarcôm\n- Dấu ấn có vai trò ở cả tầm soát, chẩn đoán, tiên lượng, theo dõi? :: AFP (ung thư gan)\n- Dấu ấn của tuyến tiền liệt, tụy, buồng trứng? :: PSA, CA 19-9, CA 125\n- BCR-ABL – thuốc? :: Imatinib (CML)\n- BRAF-V600E – thuốc? :: Vemurafenib (mêlanôm)\n- ALK – thuốc? :: Crizotinib (phổi không tế bào nhỏ)\n- BRCA1/2 – thuốc, đích? :: Olaparib, PARP (vú)\n- Mục đích xét nghiệm đặc tính sinh học bướu? :: Phân loại, chọn điều trị, tiên đoán đáp ứng, tiên lượng"}, {"kind": "foundation", "disease": "", "short": "Giải phẫu bệnh ung thư", "group": "Giải phẫu bệnh, xâm lấn, di căn, miễn dịch", "section": 0, "order": 1, "khung": [], "id": "ung-thu-giai-phau-benh", "title": "Giải phẫu bệnh ung thư — bướu lành và bướu ác", "layer": "nen", "module": "ung-buou", "tags": ["giai-phau-benh", "buou-lanh", "buou-ac", "carcinom", "sarcom", "biet-hoa", "G", "tai-cho"], "source": "Y2 tr. 30–39, 42; SY2 tr. 204–302", "body": "> [!key] Ý chính\n> - Đặc tính **đặc hiệu nhất** của ung thư = ==di căn==; xâm nhập là tiêu chí quan trọng nhất để chẩn đoán ác tính {{SY2 tr.280}}.\n> - **Carcinôm** (biểu mô) ≈ ==90%== ung thư; **sarcôm** (trung mô) hiếm hơn.\n> - Phân biệt carcinôm **tại chỗ** / **xâm nhập** = màng đáy còn nguyên hay bị phá vỡ.\n> - Độ biệt hóa **G1–G3**; xếp giai đoạn 0–IV / TNM → [[ung-thu-phan-giai-doan-tnm]].\n\n### 1. Định nghĩa và đặc điểm chung\n- **Bướu** = khối mô tân tạo do tăng sản bất thường, tồn tại lâu dài, ít chịu quy luật cân bằng nội môi; lành hoặc ác {{Y2 tr.30}} {{SY2 tr.211}}.\n  - {b|Bướu lành}: phát triển tại chỗ, không xâm lấn, không di căn.\n  - {b|Ung thư}: xâm lấn + di căn, gieo tế bào đến mô khác.\n- Mọi bướu có 2 thành phần: **mô chủ** (parenchyma, quyết định phân loại và đặc tính sinh học) và **mô nâng đỡ/đệm** (stroma: mô liên kết + mạch máu) {{SY2 tr.213}}.\n@@fold Đặc điểm chung của bướu {{Y2 tr.30}}\n- Tăng trưởng không hài hòa với mô lành, vẫn tiến triển khi nguyên nhân đã hết; chỉ xuất nguồn từ tế bào còn khả năng sinh sản.\n- Tế bào bướu không \"hồi biệt hóa\"; ung thư thường sau thời gian tiềm ẩn dài; hay nhiều ổ cùng loại mô (vd vú hai bên).\n- Tăng sản, dị sản/loạn sản có trước bướu hàng tháng–năm; tế bào ung thư có thể ngủ yên rất lâu; một số ít tự khỏi (≈ 1/100.000).\n@@end\n\n### 2. So sánh bướu lành và ung thư\n| Đặc điểm | Bướu lành | Ung thư |\n|---|---|---|\n| Biệt hóa | Rõ | Kém / không |\n| Phân bào | Hiếm | Nhiều, bất thường |\n| Tốc độ | Chậm | Nhanh |\n| Xâm nhập, phá hủy | Không | {r|Có} |\n| Vỏ bao | Có, giới hạn rõ | Thường không, ranh giới mờ |\n| Tái phát / di căn | Không | Có |\n| Hoại tử, loét | Hiếm | Thường gặp |\n| Nhân | Bình thường | Tăng sắc, méo, nhiều hạt nhân |\n| Hướng tăng trưởng (da, niêm mạc) | Ra ngoài (exophytic) | Vào trong (endophytic) |\n{{Y2 tr.31}} {{SY2 tr.216}}\n\n> [!warn] Ngoại lệ (tiêu chuẩn lành/ác không tuyệt đối) {{Y2 tr.31}}\n> - **Lành nhưng xâm nhập/tái phát**: bướu sợi bó (desmoid), bướu mạch máu da; u tuyến đa dạng tuyến mang tai tái phát ≈ 5% {{SY2 tr.269}}.\n> - **Ác nhưng giới hạn rõ/rất biệt hóa**: carcinôm dạng nang tuyến giáp (chỉ phân biệt nhờ xâm nhập vỏ bao, mạch), ung thư thận, một số ung thư trong ống vú.\n> - Ung thư thần kinh trung ương hầu như không di căn, trừ nguyên bào ống tủy (theo dịch não tủy).\n\n### 3. Phân loại và danh pháp\n@@tabs\n@@tab Theo nguồn gốc mô\n- **Bướu đặc – 5 nhóm** {{Y2 tr.32}}:\n  1. **Carcinôm** (≈ 90%): Malpighi/tế bào gai, tuyến, tế bào chuyển tiếp (niệu mạc).\n  2. **Sarcôm**: trung mô (sợi, cơ vân, cơ trơn, xương…).\n  3. Mô ngoại phôi thần kinh (thần kinh đệm, màng não, Schwann, mêlanôm…).\n  4. Cấu trúc phôi (nguyên bào thần kinh, nguyên bào thận trẻ em, carcinôm đệm nuôi; bướu quái).\n  5. Hỗn hợp (carcinôm–sarcôm).\n- **Cơ quan tạo huyết**: lymphôm (Hodgkin, không Hodgkin), bạch cầu.\n@@tab Danh pháp lành – ác\n| Mô | Lành | Ác |\n|---|---|---|\n| Biểu mô gai | U nhú tế bào gai | Carcinôm tế bào gai |\n| Biểu mô chuyển tiếp | U nhú chuyển tiếp | Carcinôm chuyển tiếp |\n| Biểu mô tuyến | U tuyến (adenoma) | Carcinôm tuyến |\n| Tế bào đáy da | — | Carcinôm tế bào đáy |\n| Tế bào gan | U tế bào gan | Carcinôm tế bào gan |\n| Ngoại bì thần kinh | Nêvi | Mêlanôm |\n| Đệm nuôi | Thai trứng | Carcinôm đệm nuôi |\n| Mỡ / sợi / sụn / xương | U mỡ / sợi / sụn / xương | Sarcôm mỡ / sợi / sụn / xương |\n| Cơ trơn / cơ vân | Leiomyoma / rhabdomyoma | Sarcôm cơ trơn / cơ vân |\n| Mạch máu | U mạch máu | Sarcôm mạch máu |\n- U lành: tên mô + **-oma**; u ác biểu mô = **carcinôm**; u ác trung mô = **sarcôm** {{SY2 tr.231}}.\n- {o|Tên không theo quy tắc}: melanoma, seminoma, mesothelioma, Ewing sarcoma, Hodgkin, bướu Wilms, Kaposi sarcoma, lymphoma {{SY2 tr.238}}.\n- U tế bào mầm (buồng trứng, tinh hoàn): u quái trưởng thành / chưa trưởng thành {{SY2 tr.237}}.\n@@tab Carcinôm so với sarcôm\n| | Carcinôm | Sarcôm |\n|---|---|---|\n| Nguồn | Biểu mô | Mô liên kết |\n| Tần suất | Thường gặp | Hiếm |\n| Đường di căn trước | {b|Lymphô} | {b|Máu} (mạch nhiều, không vách) |\n| Giai đoạn in situ | Có | Không |\n| Tuổi | Thường > 50 | Thường < 50 |\n{{SY2 tr.239}} {{Y2 tr.39}}\n@@end\n- Theo hành vi sinh học: u lành – u giáp biên – u ác tính {{SY2 tr.213}}.\n\n### 4. Hình ảnh đại thể\n| | Lành | Ác |\n|---|---|---|\n| Vỏ bao | Có, rõ | Thường không |\n| Mô quanh u | Bị chèn ép | Bị xâm lấn |\n| Kích thước | Thường nhỏ | Thường lớn |\n| Mặt cắt | Đồng nhất | Không đồng nhất, xuất huyết, hoại tử |\n{{SY2 tr.273}}\n- Hình thái ác trên bề mặt: phẳng, polyp, nhú, nấm (sùi), **loét**, vòng; bờ xâm nhập không đều, xâm nhập mạch {{SY2 tr.274}}.\n- Vú: u ác co kéo da, tụt/loét núm vú, vỏ bao không rõ; u lành không co kéo, vỏ bao rõ {{SY2 tr.278}}.\n- Dạng kinh điển {{Y2 tr.33}}: biểu mô phủ → dạng phủ, loét, ăn cứng, loét sùi; tạng đặc → cục, khối to, bọc/nang, \"não\", ăn cứng.\n@@fold Dạng bắt đầu (tổn thương sớm) {{Y2 tr.33}}\n- Carcinôm tế bào đáy da: tổn thương nhỏ đỏ có vảy, đáy cứng, hoặc cục sẫm màu nhiều mạch.\n- Niêm mạc Malpighi (tiêu hóa, hô hấp trên): vùng loét nhỏ bóng hoặc gồ dạng nhú, đau, dễ chảy máu.\n- Cổ tử cung: vùng nhỏ không đều, tăng sản mạch, chảy máu ít khi đụng, **Schiller âm tính**.\n- Dạ dày: mất bóng láng, sung huyết nhưng vách mềm; hoặc loét chợt nông, bờ bậc thang, quầng đỏ.\n@@end\n\n### 5. Hình ảnh vi thể\n@@tabs\n@@tab Bướu lành\n- Tế bào, mô giống bình thường, không dị dạng, phân bào bình thường; **màng đáy còn nguyên**, có trục liên kết–mạch.\n- Còn chức năng: u tuyến cận giáp → cường PTH; u tủy thượng thận → cơn tăng huyết áp {{Y2 tr.36}} {{SY2 tr.258}}.\n@@tab Tế bào ung thư\n- To nhỏ, hình dạng không đều; nhân tăng sắc, hạt nhân to, **tỉ lệ N/C tăng**, màng nhân dày.\n- Phân bào nhiều, bất thường (đa cực); bào tương kiềm (nhiều RNA); mất cực tính, mất hình thái chuyên biệt.\n- {o|Không phải lúc nào cũng đủ} các đặc tính; chưa có phương pháp hình thái nào khảo sát hết {{Y2 tr.36}}.\n@@tab Mô ung thư\n- **Mô chủ**: biệt hóa (giống mô gốc, vd tuyến Liberkuhn ở trực tràng) hoặc không biệt hóa (đôi khi không phân biệt với sarcôm). Ung thư thoái sản (vd tế bào nhỏ phế quản) thường ác tính cao.\n- **Mô đệm**: viêm, phù, hyaline, canxi, chuyển sản sụn–xương (thường tiên lượng tốt); nhiều mô đệm → bướu cứng {{Y2 tr.37}}.\n@@end\n\n### 6. Từ tiền ung đến xâm nhập\n- Tiền ung thư: phát triển khu trú, **chưa xâm lấn**. Ung thư: xâm lấn + di căn {{SY2 tr.287}}.\n- Biểu mô gai: chuyển sản gai → loạn sản nhẹ → vừa → nặng → **carcinôm tại chỗ** (màng đáy nguyên) → xâm lấn (qua màng đáy vào mô đệm) {{SY2 tr.290}}.\n- Diễn tiến: tiền ung → tại chỗ → xâm nhập → lan rộng → tái phát → di căn {{SY2 tr.297}}.\n\n| Mức độ lan rộng vi thể {{Y2 tr.34}} | Tiêu chuẩn |\n|---|---|\n| Carcinôm **tại chỗ** | Trong biểu mô, không vượt màng đáy |\n| Xâm nhập **vi thể** | Xâm nhập ít xuống mô đệm; thường coi là vi thể nếu cách màng đáy ==< 3 mm== |\n| Carcinôm **xâm nhập** | Qua khỏi màng đáy (thường gặp) |\n\n> [!tip] Mẹo nhớ\n> Màng đáy là ranh giới: còn nguyên = tại chỗ (chữa lành ≈ 100% giai đoạn 0); phá vỡ = xâm nhập.\n\n### 7. Xếp hạng và độ biệt hóa\n- **Giai đoạn 0–IV / TNM** (UICC): T bướu nguyên phát, N hạch vùng, M di căn xa; **pTNM** = sau mổ; đã xếp TNM thì không đổi dù bệnh tiến triển {{Y2 tr.34}}.\n  - 0: tại chỗ · I: nhỏ, không hạch · II: lan tại chỗ + hạch tối thiểu · III: lan rộng/hạch quan trọng · IV: không mổ được, hoặc di căn xa.\n  - Y2: giai đoạn 0 chữa lành ≈ 100%; giai đoạn IV tử vong gần 100%.\n- **Độ biệt hóa G** {{Y2 tr.35}}: {g|G1} rõ · G2 vừa · {r|G3} kém/không · GX không đánh giá. Hạch: N(−)/N(+); sau mổ pN0–pN3.\n- Hệ khác: **Duke / Astler–Coller** (ruột già), **Borrmann** (dạ dày), **FIGO** (cổ tử cung, thân tử cung, buồng trứng), **Ann Arbor** (Hodgkin, lymphôm không Hodgkin) {{Y2 tr.34}}.\n\n### 8. Tiến triển và tốc độ tăng trưởng\n- Bướu lành tăng sản chậm, ít gây chết (trừ vị trí đặc biệt: não, tim — u nhầy nhĩ trái gây hẹp van 2 lá, u màng não, Schwann dây VII); có thể chèn ép, chảy máu, hóa sợi, thoái triển (u mạch bẩm sinh sau 2 năm) {{SY2 tr.252}}.\n- Bướu ác: tế bào chuyển dạng → nốt chưa mạch (≈ 2 mm) → có mạch nhờ **TAF** → hoại tử trung tâm {{SY2 tr.294}} {{Y2 tr.38}}.\n- Thời kỳ **tiền lâm sàng**: Burkitt ≈ 3 tháng; Ewing ≈ 17 tháng; carcinôm tuyến đại tràng ≈ 600 tháng; trung bình ≈ 24 tháng {{SY2 tr.296}}.\n\n> [!ext] Bổ sung (tham khảo)\n> Phân loại hiện hành của WHO dùng \"độ mô học\" riêng cho từng cơ quan (vd Nottingham ở vú, Gleason/ISUP ở tiền liệt tuyến); không thay thế G1–G3 chung của tài liệu. *Nguồn: WHO Classification of Tumours (IARC), https://tumourclassification.iarc.who.int*\n\n### Điểm hay thi\n> [!warn] Bẫy thường gặp\n> - Đặc tính **đặc hiệu nhất** của ung thư là **di căn** (không phải tăng sinh hay nhân dị dạng).\n> - Carcinôm tại chỗ **không** vượt màng đáy; xâm nhập vi thể < 3 mm (Y2).\n> - Carcinôm → di căn **lymphô trước**; sarcôm → **máu** sớm, không có giai đoạn in situ.\n> - Ung thư rất biệt hóa vẫn có thể có giới hạn rõ (thận, giáp dạng nang) — lành/ác không tuyệt đối.\n> - Borrmann = dạ dày; Duke = ruột già; FIGO = phụ khoa; Ann Arbor = lymphôm.\n> - Đã xếp TNM thì **không đổi** khi bệnh tiến triển.\n\n### Tự kiểm tra\n- Đặc tính đặc hiệu nhất của ung thư là gì? :: Khả năng di căn\n- Carcinôm chiếm bao nhiêu % ung thư, xuất nguồn từ mô nào? :: Khoảng 90%, từ biểu mô\n- Carcinôm tại chỗ khác xâm nhập ở điểm nào? :: Tại chỗ không vượt màng đáy; xâm nhập là qua khỏi màng đáy\n- Ngưỡng xâm nhập vi thể theo Y2? :: Phần xâm nhập cách màng đáy dưới 3 mm\n- G1, G2, G3 nghĩa là gì? :: Biệt hóa rõ, vừa, kém hoặc không biệt hóa\n- Ba khác biệt đại thể lành – ác? :: Lành: vỏ bao, chèn ép, đồng nhất; ác: không vỏ bao, xâm lấn, không đồng nhất (xuất huyết, hoại tử)\n- Tên u lành và u ác của mô sụn? :: Chondroma (u sụn); sarcôm sụn\n- Carcinôm và sarcôm di căn theo đường nào trước? :: Carcinôm: lymphô; sarcôm: máu\n- Borrmann và Duke dùng cho ung thư nào? :: Borrmann dạ dày; Duke ruột già\n- Chuỗi tổn thương của biểu mô gai từ tiền ung đến ung thư? :: Chuyển sản gai → loạn sản nhẹ/vừa/nặng → carcinôm tại chỗ → xâm lấn\n- Hai thành phần của mọi bướu? :: Mô chủ (tế bào u) và mô đệm (liên kết + mạch)"}, {"kind": "foundation", "disease": "", "short": "Giao tiếp và giảm nhẹ", "group": "Điều trị và chăm sóc", "section": 2, "order": 3, "khung": [], "id": "ung-thu-giao-tiep-cham-soc-giam-nhe", "title": "Giao tiếp, báo tin xấu và chăm sóc giảm nhẹ", "layer": "dieutri", "module": "ung-buou", "tags": ["giao tiếp", "báo tin xấu", "đồng thuận", "thủ thuật", "đau do ung thư", "chăm sóc giảm nhẹ", "phẫu thuật giảm nhẹ", "opioid", "thang WHO", "thân nhân"], "source": "ĐC Y5 tr.1, 3–4, 6; Y5 tr.6, 48, 62, 87, 104, 120, 124, 146, 193, 249–250, 253, 262, 264, 269, 319–320, 343; SY5 tr.152, 295; QĐ1514 tr.65, 98–105, 199, 316, 571, 576, 663, 680, 686, 708, 724, 735", "body": "> [!key] Giao tiếp, báo tin xấu và chăm sóc giảm nhẹ trong một nhìn\n> - Mục tiêu MT16: tôn trọng và đồng cảm với bệnh nhân và thân nhân trong các thủ thuật, bệnh nặng, bệnh tử vong {{ĐC Y5 tr.4}}\n> - Buổi CSGN trong đề cương gắn MT 1, 5, 8, 15, 16, 17, không riêng MT16 {{ĐC Y5 tr.6}}\n> - Tài liệu có quy định **đồng thuận** ở một số thủ thuật và thuốc phóng xạ: giải thích lợi hại, có giấy cam kết {{QĐ1514 tr.PDF 680}} {{QĐ1514 tr.PDF 724}}\n> - Chăm sóc giảm nhẹ (CSGN) là lựa chọn khi bệnh nhân không chịu nổi hóa trị, thể trạng kém hoặc xơ gan nặng {{Y5 tr.120}} {{Y5 tr.319}} {{Y5 tr.320}}\n> - Đau do ung thư điều trị theo **thang WHO 3 bậc**, opioid dùng sau cùng {{QĐ1514 tr.PDF 101}}\n> - Quy trình báo tin xấu, mẫu lời nói và chăm sóc hấp hối: **tài liệu không nêu**\n\n> [!warn] Nguồn thiếu một chương\n> - Lịch đề cương có buổi \"Chăm sóc giảm nhẹ ung thư\": e-learning 1 tiết, tự học 2 tiết, MT 1, 5, 8, 15, 16, 17 {{ĐC Y5 tr.6}}\n> - Bản trích TEXT UNG BƯỚU Y5 đã đọc đủ các trang và **không có chương này**. Slide Y5 chỉ nhắc CSGN trong một mục phòng ngừa {{SY5 tr.152}}\n> - Phần CSGN dưới đây ghép từ các bài bệnh của Y5 và Bài 15 \"Đau do ung thư\" của QĐ1514 {{QĐ1514 tr.PDF 98}}; cần đối chiếu bài giảng gốc trước khi thi\n\n### Mục tiêu và khung học\n- Mục tiêu chung: tôn trọng bệnh nhân, thân nhân, đồng nghiệp và pháp luật {{ĐC Y5 tr.1}}\n- CĐR C8: giao tiếp và phối hợp với người bệnh, người thân, đồng nghiệp {{ĐC Y5 tr.3}}\n- CĐR C10: tuân thủ quy định pháp lý và chuẩn đạo đức nghề nghiệp, đi kèm MT16 {{ĐC Y5 tr.4}}\n\n### Giao tiếp và báo tin xấu\n- Hỏi bệnh: phải tạo cho bệnh nhân trạng thái tâm lý tốt, hợp tác để trả lời chính xác {{QĐ1514 tr.PDF 105}}\n- Người bệnh ung thư: 90% mệt mỏi, 80% sút cân, chán ăn, lo lắng hốt hoảng; 80–85% đau ở các mức độ {{QĐ1514 tr.PDF 98}}\n- Đau ung thư là \"chứng đau tổng hợp tâm – thể\", nên kết hợp tâm lý liệu pháp {{QĐ1514 tr.PDF 100}}\n- Mục tiêu học của các bài Y5: tư vấn cho bệnh nhân về theo dõi sau điều trị, cách phòng ngừa và phát hiện sớm {{Y5 tr.104}} {{Y5 tr.253}} {{Y5 tr.269}}\n- Tài liệu không nêu: cách báo chẩn đoán ung thư, chuẩn bị trước khi báo, kiểm tra mức hiểu của bệnh nhân, cách làm việc với người nhà\n\n### Đồng thuận\n| Tình huống | Tài liệu ghi | Nguồn |\n|---|---|---|\n| Ung thư thực quản | Nhiều người không đồng ý cắt thực quản sau khi được tư vấn về chảy máu, dò miệng nối, nhiễm trùng trung thất, suy hô hấp | {{Y5 tr.249}} |\n| Thực quản không mổ được hoặc bệnh nhân không đồng ý mổ | Hóa–xạ trị đồng thời triệt để | {{Y5 tr.250}} |\n| Ung thư âm đạo giai đoạn II–IVA | Hóa–xạ trị đồng thời hay xạ trị đơn thuần; nguồn ghi một điều kiện chung cho cả hai: tổng trạng và chức năng gan, thận không cho phép hóa trị, hoặc bệnh nhân không đồng ý hóa trị. Nguồn không tách điều kiện cho từng phương án | {{Y5 tr.87}} |\n| U thận không mổ được hoặc bệnh nhân không đồng ý mổ | Xạ trị định vị thân (SBRT) | {{QĐ1514 tr.PDF 316}} |\n| Thuốc phóng xạ 131I | Giải thích tình hình bệnh và lợi hại; người bệnh làm giấy cam kết tự nguyện | {{QĐ1514 tr.PDF 680}} {{QĐ1514 tr.PDF 686}} |\n| Cấy hạt phóng xạ tiền liệt tuyến | Bệnh nhân và gia đình đồng ý chấp nhận kỹ thuật | {{QĐ1514 tr.PDF 708}} |\n| Tiêm phóng xạ khoang màng phổi; 131I-Rituximab | Giải thích để có đồng ý của bệnh nhân hoặc người nhà; ký cam kết điều trị | {{QĐ1514 tr.PDF 724}} {{QĐ1514 tr.PDF 735}} |\n\n- Tài liệu không nêu: mẫu giấy cam kết chung cho phẫu thuật và hóa trị; người ký khi bệnh nhân không đủ năng lực\n\n### Thái độ khi làm thủ thuật\n| Thủ thuật | Tài liệu ghi về đau hoặc gây tê | Nguồn |\n|---|---|---|\n| Nạo sinh thiết lòng tử cung (ung thư nội mạc) | Gây đau nhiều, phải giảm đau đúng mức | {{Y5 tr.48}} |\n| Sinh thiết cổ tử cung bằng kềm | Không cần gây tê hay gây mê, vùng này không có thần kinh cảm giác đau | {{Y5 tr.62}} |\n| Sinh thiết u khoang miệng qua ống soi | Cần gây tê; u thâm nhiễm hoặc ở sâu có thể phải gây mê đặc biệt | {{QĐ1514 tr.PDF 199}} |\n\n- Ho ra máu nhẹ: trước hết \"động viên, giải thích người bệnh và người nhà người bệnh\", nằm nghỉ yên tĩnh {{QĐ1514 tr.PDF 65}}\n- Nguyên tắc đầu tiên khi điều trị đau: \"tôn trọng và tiếp nhận những than phiền đau của bệnh nhân\" {{QĐ1514 tr.PDF 100}}\n- Tài liệu không nêu: lời trấn an cụ thể khi làm thủ thuật, cách nói khi thủ thuật thất bại hoặc có biến chứng\n\n### Chăm sóc giảm nhẹ: khi nào\n- Theo nguồn, ngoài điều trị đặc hiệu, phải điều trị triệu chứng cơ năng, thực tổn, rối loạn tâm lý, đặc biệt đau, để nâng cao chất lượng sống {{QĐ1514 tr.PDF 98}}\n- Slide xếp CSGN vào **phòng ngừa cấp 3**, cùng điều trị hỗ trợ và liệu pháp trúng đích. Tài liệu không giải thích cơ sở của cách xếp này {{SY5 tr.152}}\n- Ung thư phổi không tế bào nhỏ giai đoạn muộn: CSGN có trung vị sống còn 16–17 tuần, OS 1 năm 10–15%; hóa trị nâng OS 1 năm lên trên 35% {{Y5 tr.120}}\n- Chọn CSGN khi không chịu được hóa trị do tổng trạng kém hoặc nhiều bệnh nội khoa đi kèm {{Y5 tr.120}}\n- Ung thư phổi tế bào nhỏ không đáp ứng hóa trị bước một: thử nghiệm lâm sàng hoặc CSGN tích cực {{Y5 tr.124}}\n- Ung thư thực quản di căn xa: điều trị toàn thân nếu thể trạng tốt; CSGN nếu thể trạng kém, không dung nạp hóa trị {{Y5 tr.250}}\n- Ung thư âm đạo giai đoạn IVB: hóa trị hoặc CSGN {{Y5 tr.87}}\n- Ung thư đầu cổ tái phát và/hoặc di căn xa không điều trị triệt để được: hóa trị giảm nhẹ, miễn dịch và/hoặc CSGN {{Y5 tr.146}}\n- Ung thư gan BCLC giai đoạn D (ECOG 3–4, Child-Pugh C): CSGN {{Y5 tr.319}}. Xơ gan nặng có thể tử vong dù điều trị nào, CSGN là thích hợp nhất {{Y5 tr.320}}\n- Đánh giá thể trạng: [[ung-thu-the-trang-kps-ecog|KPS và ECOG]]\n\n### Phẫu thuật và xạ trị giảm nhẹ\n- Dạ dày di căn xa: phẫu thuật giảm nhẹ chỉ để điều trị chảy máu (cắt dạ dày) hoặc tắc nghẽn (cắt dạ dày hoặc nối vị tràng) {{Y5 tr.262}}\n- ==Phẫu thuật giảm nhẹ có tỉ lệ biến chứng và tử vong cao==, chỉ cân nhắc ở người cấp cứu vì chảy máu hoặc tắc nghẽn {{Y5 tr.264}}\n- Tiền liệt tuyến tiến triển (mục 7.3): cắt đốt qua niệu đạo giúp giảm triệu chứng tắc nghẽn đường tiểu; xạ giảm đau di căn xương; xạ chống chèn ép tủy sống là tình huống cấp cứu; xạ cầm máu khi tiểu máu đại thể {{Y5 tr.343}}\n- Xạ trị giảm nhẹ trong di căn xương và di căn não {{SY5 tr.295}}\n\n### Đau do ung thư: thang WHO và liều (QĐ1514 Bài 15)\n- Đau gặp ở 80–85% bệnh nhân ung thư {{QĐ1514 tr.PDF 98}}\n- Nguyên tắc: đánh giá đúng mức đau và triệu chứng kèm; chọn phác đồ phù hợp; điều trị rối loạn đi kèm; phối hợp đa phương thức {{QĐ1514 tr.PDF 100}}\n- Mục tiêu: ngủ được không đau; không đau hoặc giảm đau khi nghỉ; giảm đau khi hoạt động {{QĐ1514 tr.PDF 100}}\n- Thứ tự thuốc: thuốc không opioid dùng trước, opioid dùng sau cùng; đường uống ưu tiên; đường tiêm chỉ định trong đau cấp tính; truyền tĩnh mạch duy trì phải chuẩn độ bằng bơm tiêm tự động {{QĐ1514 tr.PDF 101}}\n- Thang WHO: bậc 1 thuốc không opioid; bậc 2 opioid yếu; bậc 3 opioid mạnh đường uống hoặc tiêm, có thể kèm thuốc chống viêm và thuốc hỗ trợ {{QĐ1514 tr.PDF 101}}\n\n| Thuốc | Liều theo nguồn | Nguồn |\n|---|---|---|\n| Paracetamol | Người lớn 0,5–1 g/lần, mỗi 4–6 giờ; ==tối đa 4.000 mg/ngày==; độc với gan | {{QĐ1514 tr.PDF 101}} |\n| Tramadol | 50–100 mg/lần, mỗi 4–6 giờ; tối đa 400 mg/ngày | {{QĐ1514 tr.PDF 102}} |\n| Ultracet (tramadol 37,5 mg + paracetamol 325 mg) | 1–2 viên mỗi 4–6 giờ; tối đa 8 viên/ngày | {{QĐ1514 tr.PDF 101}} |\n| Codein | 30–60 mg/lần, 3–4 giờ/lần | {{QĐ1514 tr.PDF 102}} |\n| Morphin uống | Viên 10, 20, 30 mg; khởi đầu 10 mg rồi tăng theo độ đau. MS Contin khởi đầu 30 mg mỗi 12 giờ | {{QĐ1514 tr.PDF 102}} |\n| Morphin tiêm dưới da hoặc bắp | 10 mg, 1–2 lần/ngày | {{QĐ1514 tr.PDF 102}} |\n| Durogesic (fentanyl dán) | 25 và 50 mcg/giờ; thay mỗi 72 giờ; mỗi lần tăng 25 mcg/giờ; đánh giá sau 3 ngày | {{QĐ1514 tr.PDF 102}} |\n| Oxycodone | ER 10 mg mỗi 12 giờ, tăng 25–50% khi cần; IR 5 mg mỗi 4–6 giờ khi đau đột xuất | {{QĐ1514 tr.PDF 103}} |\n\n- Quy đổi tương đương (bảng 1): morphin tiêm 10 mg ≈ uống 30 mg (liều lặp lại) hoặc 60 mg (liều duy nhất); oxycodone tiêm 15 mg ≈ uống 30 mg; hydromorphone tiêm 1,5 mg ≈ uống 7,5 mg; methadone tiêm 10 mg ≈ uống 20 mg; codein tiêm 130 mg ≈ uống 200 mg {{QĐ1514 tr.PDF 103}}\n- Durogesic khởi đầu: người chưa dùng opioid, khoảng 135 mg morphin uống/ngày rồi chuyển sang 25 mcg/giờ; người đã dung nạp opioid tính theo 3 bước {{QĐ1514 tr.PDF 102}}. Bảng 2: morphin uống dưới 135 mg/ngày → 25 mcg/giờ; 135–224 mg → 50 mcg/giờ {{QĐ1514 tr.PDF 103}}\n- Liều trên 300 mcg/giờ: một số bệnh nhân cần phương pháp bổ sung hoặc thay thế opioid {{QĐ1514 tr.PDF 102}}\n- Thuốc hỗ trợ: methylprednisolon 40 mg tiêm/truyền 1–2 lần/ngày; amitriptylin 25 mg 1–2 viên/ngày; gabapentin tối đa 3.600 mg/ngày; pregabalin 75 mg 2 lần/ngày; acid zoledronic 4 mg truyền tĩnh mạch 21–28 ngày/lần khi đau do di căn xương {{QĐ1514 tr.PDF 104}}\n- Xạ trị giảm đau: 2 Gy × 20 buổi, 3 Gy × 10 buổi, hoặc 4 Gy × 5 buổi {{QĐ1514 tr.PDF 104}}. Thuốc phóng xạ hướng xương: 32P 1–1,5 mCi/10 kg; 153Sm 1–3 mCi/kg; 89Sr 0,05–1 mCi/kg {{QĐ1514 tr.PDF 104}}; theo dõi ức chế tủy {{QĐ1514 tr.PDF 105}}\n- Đánh giá đau: thang VAS 0–10, NRS 0–100, hoặc bậc WHO 1–3; bệnh nhân tự chấm điểm {{QĐ1514 tr.PDF 105}}\n\n> [!warn] Hai ý dễ nhầm trong cùng một nguồn\n> - \"Không dùng các thuốc opioid ngay từ đầu\" {{QĐ1514 tr.PDF 100}}\n> - Với người chưa dùng opioid: \"nên sử dụng opioid tương đương 135mg morphin uống/ngày rồi chuyển qua Durogesic 25mcg/giờ\" {{QĐ1514 tr.PDF 102}}\n> - Tài liệu không nói cách hòa giải hai ý này. Durogesic được ghi cho đau mạn, đau dai dẳng cần opioid dài ngày {{QĐ1514 tr.PDF 102}}. Bài này ghi cả hai, không chọn đáp án\n\n### Hỗ trợ thân nhân\n- Điều trị đau cần \"sự hợp tác tốt của bệnh nhân và gia đình\" để chỉnh liều và theo dõi tác dụng phụ {{QĐ1514 tr.PDF 101}}\n- Ho ra máu nhẹ: giải thích cho người bệnh và người nhà {{QĐ1514 tr.PDF 65}}\n- Xạ trị u não trẻ em: cần phối hợp tốt giữa bệnh nhân, người nhà và nhân viên y tế {{QĐ1514 tr.PDF 663}}\n- U thần kinh đệm ở trẻ em: theo dõi đa ngành, lo vấn đề xã hội lâu dài cho gia đình và trẻ, có chăm sóc tâm lý xã hội {{QĐ1514 tr.PDF 571}}\n- U nguyên tủy bào ở trẻ em: đội ngũ đa chuyên khoa có chuyên gia tâm lý, tổ chức xã hội và tình nguyện viên {{QĐ1514 tr.PDF 576}}\n- Cắt thanh quản toàn phần: nhóm dễ chấp nhận mở khí quản hơn gồm người lớn tuổi, tổng trạng kém, ít được nâng đỡ tâm lý xã hội; thiếu hỗ trợ cộng đồng gây khó giao tiếp sau mổ {{Y5 tr.193}}\n- Người muốn có con: tư vấn trữ phôi hoặc trữ trứng trước hóa trị {{Y5 tr.6}}\n- Tài liệu không nêu: hỗ trợ người nhà khi bệnh nặng lên, đau buồn sau khi mất người bệnh; dịch vụ hỗ trợ tâm lý xã hội cho người lớn (nguồn chỉ nêu điều trị rối loạn tâm lý và tâm lý liệu pháp kết hợp trong điều trị đau {{QĐ1514 tr.PDF 98}} {{QĐ1514 tr.PDF 100}})\n\n### Điểm hay thi\n> [!warn]\n> - Đau do ung thư: nguyên tắc đầu tiên là tôn trọng và tiếp nhận than phiền đau {{QĐ1514 tr.PDF 100}}\n> - Thuốc không opioid dùng trước; opioid dùng sau cùng {{QĐ1514 tr.PDF 101}}\n> - Paracetamol tối đa 4.000 mg/ngày ở người lớn {{QĐ1514 tr.PDF 101}}\n> - Phẫu thuật giảm nhẹ dạ dày: biến chứng và tử vong cao, chỉ cân nhắc khi cấp cứu {{Y5 tr.264}}\n> - Bệnh nhân không đồng ý mổ thực quản: hóa–xạ trị đồng thời triệt để {{Y5 tr.250}}\n> - Thủ thuật gây đau (nạo buồng tử cung) cần giảm đau đúng mức {{Y5 tr.48}}\n\n### Tài liệu không nêu\n- Quy trình báo tin xấu, mẫu lời nói, cách đo mức hiểu của bệnh nhân\n- Mẫu giấy cam kết chung cho phẫu thuật và hóa trị; người ký khi bệnh nhân không đủ năng lực\n- Không có mốc ECOG/KPS chung để chuyển sang CSGN; chỉ có ECOG 3–4 và Child-Pugh C trong BCLC giai đoạn D ung thư gan {{Y5 tr.319}}; các bệnh khác chỉ nêu \"tổng trạng kém\" và \"không dung nạp hóa trị\"\n- Chăm sóc giai đoạn hấp hối, hỗ trợ tang quyến\n- Chương \"Chăm sóc giảm nhẹ ung thư\" riêng của Y5 (xem hộp đầu bài)\n\n### Tự kiểm tra\n- MT16 yêu cầu sinh viên tôn trọng và đồng cảm với ai, trong bối cảnh nào? :: Bệnh nhân và thân nhân, trong các thủ thuật, bệnh nặng và bệnh tử vong\n- Sinh thiết cổ tử cung có cần gây tê không, vì sao? :: Không; vùng này không có thần kinh cảm giác đau\n- Nạo sinh thiết lòng tử cung cần xử trí thế nào về đau? :: Đây là thủ thuật gây đau nhiều, phải giảm đau đúng mức\n- Nguyên tắc đầu tiên khi điều trị đau do ung thư? :: Tôn trọng và tiếp nhận những than phiền đau của bệnh nhân\n- Paracetamol tối đa bao nhiêu mỗi ngày ở người lớn? :: 4.000 mg/ngày; tramadol tối đa 400 mg/ngày\n- Phẫu thuật giảm nhẹ dạ dày được cân nhắc khi nào? :: Chỉ khi cấp cứu vì chảy máu hoặc tắc nghẽn, do biến chứng và tử vong cao\n- BCLC giai đoạn D của ung thư gan có ECOG và Child-Pugh bao nhiêu, điều trị gì? :: ECOG 3–4, Child-Pugh C; chăm sóc giảm nhẹ\n- U thận không mổ được hoặc bệnh nhân không đồng ý mổ, điều trị gì? :: Xạ trị định vị thân (SBRT)\n- Trước khi điều trị bằng thuốc phóng xạ 131I, người bệnh cần làm gì? :: Được giải thích lợi hại, làm giấy cam kết tự nguyện\n- Durogesic khởi đầu ở người chưa dùng opioid như thế nào? :: Khoảng 135 mg morphin uống/ngày rồi chuyển sang 25 mcg/giờ"}, {"kind": "foundation", "disease": "", "short": "Chẩn đoán hình ảnh", "group": "Khái quát cận lâm sàng", "section": 4, "order": 2, "khung": [], "id": "ung-thu-hinh-anh-chan-doan", "title": "Chẩn đoán hình ảnh trong ung thư", "layer": "cls", "module": "ung-buou", "tags": ["hình ảnh", "X-quang", "nhũ ảnh", "siêu âm", "CT", "MRI", "PET-CT", "xạ hình", "BI-RADS"], "source": "Y5 tr. 7–12, 62–63, 106–112, 124, 272–273, 287–289; SY5 tr. 125–126; QĐ3128 tr. 7–8, 27–28, 37–38; QĐ3898 tr. 21–26; QĐ2549 tr. 3, 23; QĐ1514 tr.PDF 243–244, 361", "body": "> [!key] Tóm tắt\n> - Hình ảnh trả lời **ba câu hỏi**: bướu ở đâu (cơ quan mang bướu) · lan đến đâu (T, N, M) · đáp ứng/ tái phát chưa; **không thay thế** mô bệnh học {{SY5 tr.126, 128}}\n> - Chọn phương tiện theo bệnh: vú (nhũ ảnh, siêu âm, MRI) · cổ tử cung (MRI bướu, PET/CT hạch) · trực tràng (MRI chậu) · phổi (CT, PET-CT)\n> - Nhớ mốc: **MRI** tốt nhất bướu cổ tử cung; **PET/CT** tốt nhất hạch cổ tử cung; **CT** thấy ==99%== di căn gan đại tràng; **PET-CT** nốt phổi nhạy ==96%==, đặc hiệu ==75%==\n> - Tổng quan xuyên bệnh: [[ung-thu-cls-vai-tro]]; lấy mô: [[ung-thu-noi-soi-lay-benh-pham]]; chọn theo tình huống: [[ung-thu-cls-chon-phuong-tien]]\n\n### Phương tiện hình ảnh theo SY5\n- Hình ảnh học: **X-quang, siêu âm, CT, MRI, PET, xạ hình** {{SY5 tr.125}}\n- Xác định cơ quan mang bướu sâu: X-quang, CT (phổi); siêu âm, CT, MRI (gan); CT, MRI, nội soi (ống tiêu hóa); CT, MRI (thần kinh trung ương) {{SY5 tr.126}}\n- cTNM = khám lâm sàng + hình ảnh; ví dụ ung thư trực tràng: đánh giá T, N bằng nội soi và CT, MRI {{SY5 tr.139–140}}\n\n@@tabs\n@@tab X-quang\n#### X-quang ngực\n- **Nguyên lý/ kỹ thuật**: chụp thẳng và nghiêng {{QĐ1514 tr.PDF 243}}\n- **Vai trò**:\n  - Phổi: đám mờ, tràn dịch màng phổi; xác định vị trí, hình thái, kích thước; đánh giá khả năng phẫu thuật {{QĐ1514 tr.PDF 243}}\n  - Phát hiện **tình cờ** (khối mờ nhỏ khi khám sức khỏe) {{SY5 tr.122}}\n  - Giai đoạn: loại trừ di căn phổi ở vú, cổ tử cung, đại trực tràng {{QĐ3128 tr.7; Y5 tr.63, 288}}\n  - Chẩn đoán phân biệt: nghi viêm phổi → chụp lại sau kháng sinh 1 tháng; tràn dịch màng phổi → chụp lại sau chọc hết dịch {{QĐ1514 tr.PDF 244}}\n  - Sàng lọc phổi: X-quang ± tế bào học đờm **không** giảm tử vong {{Y5 tr.106}}\n- **Nhược**: chỉ thấy tổn thương nhìn được; khối nghi ngờ vẫn cần CT ngực để khảo sát nốt khác, hạch, xâm lấn thành ngực {{Y5 tr.110}}\n- **Khác**: X-quang bụng không chuẩn bị chỉ cho đại trực tràng cấp cứu (tắc ruột, thủng) {{QĐ2549 tr.3}}; X-quang xương vùng đau khi nghi di căn {{Y5 tr.111}}\n- Theo bệnh: [Ung thư phổi · 5.3](#/n/ung-thu-phoi/5) · [Ung thư đại trực tràng · 5.3](#/n/ung-thu-daitruc-trang/5)\n\n#### Nhũ ảnh (X-quang tuyến vú)\n- **Nguyên lý/ kỹ thuật**: nén vú bằng tấm ép nhựa để dàn đều mô, giảm liều tia X; mỗi vú **2 tư thế CC và MLO**; chụp trong tuần đầu sau sạch kinh {{QĐ3898 tr.22}}. Mô đặc/ khó chẩn đoán: nhũ ảnh số có cản quang, 3D (tomosynthesis), chụp ống dẫn sữa cản quang {{QĐ3128 tr.7}}\n- **Vai trò**:\n  - **Sàng lọc**: biện pháp duy nhất được chứng minh giảm tử vong; thấy ung thư sớm hơn lâm sàng **1,5–4 năm**; mỗi năm từ 40 tuổi (nguy cơ trung bình) {{QĐ3898 tr.21}}\n  - **Chẩn đoán**: khối tăng đậm độ, vi vôi hóa, xáo trộn cấu trúc, dạng hình sao (tua gai) {{Y5 tr.7}}; khi có triệu chứng: sờ u, tiết dịch núm vú, tụt núm vú, đau vú, hạch nách {{QĐ3898 tr.22}}\n  - **Theo dõi**: nhũ ảnh hằng năm sau điều trị {{QĐ3128 tr.27–28}}\n- **Giá trị sàng lọc (SY5)**: giảm tử suất, chi phí–hiệu quả; nhạy ≈ ==70%==, đặc hiệu ==75%== {{SY5 tr.54}}\n- **Nhược**: ==âm tính không loại trừ== ung thư (~10% khối sờ thấy không thấy, nhất là mô dày) {{Y5 tr.7}}; khó với mô đặc, sát thành ngực, túi ngực; tia ion hóa; khó phân biệt lành/ác {{QĐ3898 tr.24}}\n- **Chống chỉ định**: viêm tấy, áp xe, vỡ loét; tuần đầu sau mổ/sinh thiết vú. Túi ngực: kỹ thuật **Eklund** {{QĐ3898 tr.22}}\n- Theo bệnh: [Ung thư vú · 5.3](#/n/ung-thu-vu/5) · tầm soát: [[ung-thu-tam-soat-nguyen-tac]]\n\n@@fold! BI-RADS (nhũ ảnh, siêu âm, MRI đều dùng chung)\n| BI-RADS | Ý nghĩa | Khả năng ác tính | Khuyến cáo |\n|---|---|---|---|\n| 0 | Chưa hoàn tất | – | Thêm hình ảnh khác / so phim cũ |\n| 1 | Bình thường | 0% | Kiểm tra định kỳ |\n| 2 | Lành tính | 0% | Kiểm tra định kỳ |\n| 3 | Có khả năng lành tính | <2% | Theo dõi **6 tháng** |\n| 4 | Nghi ác tính (4A >2–10%; 4B >10–<50%; 4C >50–<95%) | 2–95% | **Sinh thiết** |\n| 5 | Rất nghi ung thư | >95% | **Sinh thiết** |\n| 6 | Đã xác định ung thư | 100% | Điều trị |\n{{Y5 tr.9; QĐ3898 tr.23}}\n@@end\n@@tab Siêu âm\n- **Nguyên lý/ kỹ thuật**: không dùng bức xạ, an toàn khi lặp lại, ít tốn tài nguyên; vú: 3D, đàn hồi, quét thể tích tự động {{QĐ3898 tr.24; QĐ3128 tr.7}}\n- **Vai trò**:\n  - **Vú – chẩn đoán**: phân biệt nang và đặc; <35 tuổi; mô đặc; túi ngực; viêm, áp xe; chảy dịch núm vú; hướng dẫn sinh thiết. Ác tính: nốt đặc giảm âm, trục đứng, giới hạn không rõ, bờ gai, tăng sinh mạch {{Y5 tr.9; QĐ3898 tr.24–25}}\n  - **Vú – hạch nách**: vỏ dày, ổ dãn vỏ >2,5 mm, mất rốn hạch; có thể chọc hút kim dưới siêu âm trước sinh thiết hạch cửa {{Y5 tr.10}}\n  - **Vú – sàng lọc**: {r|không dùng đơn độc}; thêm vào nhũ ảnh khi mô vú đặc (BI-RADS C/D) {{QĐ3898 tr.23–24}}\n  - **Siêu âm bụng**: cổ tử cung (bướu, xâm lấn thân tử cung, bàng quang, hạch, gan, thận ứ nước, dịch ổ bụng) {{Y5 tr.63}}; đại trực tràng (gan, ổ bụng; nhạy kém CT) {{QĐ2549 tr.3}}; phổi, vú: tìm di căn {{QĐ1514 tr.PDF 243; QĐ3128 tr.7}}\n  - **Theo dõi**: vú, siêu âm vú hằng năm sau điều trị giai đoạn I–III {{QĐ3128 tr.28}}\n- **Nhược**: phụ thuộc người làm; sát thành ngực, vi vôi hóa nhỏ, tổn thương lan rộng/ đa ổ khó đánh giá {{QĐ3898 tr.25}}\n- Theo bệnh: [Ung thư vú · 5.3](#/n/ung-thu-vu/5) · [Ung thư cổ tử cung · 5.3](#/n/ung-thu-cotucung/5)\n\n#### Siêu âm qua trực tràng (nội trực tràng)\n- **Vai trò**: đánh giá mức xâm lấn T và hạch cạnh trực tràng của **ung thư trực tràng**; độ chính xác T ==87%==, N ==74%== (phân tích gộp) {{Y5 tr.288}} {{QĐ2549 tr.3}}\n- **Ưu**: chính xác hơn CT về bướu và hạch cạnh trực tràng; dụng cụ nhỏ, linh hoạt, rẻ, không cần gây mê, làm ở phòng khám/ tại giường/ phòng mổ {{Y5 tr.288}}\n- **Nhược**: độ chính xác thay đổi, phụ thuộc người thực hiện; MRI có phạm vi rộng hơn, ít phụ thuộc người, khảo sát được cả bướu gây hẹp {{Y5 tr.288–289}}\n- Theo bệnh: [Ung thư đại trực tràng · 5.3](#/n/ung-thu-daitruc-trang/5)\n@@tab CT\n- **Nguyên lý/ kỹ thuật**: thường có tiêm cản quang (ngực + bụng thấy rõ hai thượng thận trong ung thư phổi) {{Y5 tr.111}}\n- **Vai trò**:\n  - **Phổi – chẩn đoán/ giai đoạn**: khối u, hạch trung thất, mức lan; hướng dẫn sinh thiết xuyên thành ngực {{QĐ1514 tr.PDF 243–244}}\n  - **Phổi – theo dõi**: CT ngực mỗi 6 tháng × 2 năm (giai đoạn sớm); giai đoạn IV: mỗi 2–3 chu kỳ hóa trị {{Y5 tr.124}}\n  - **Cổ tử cung**: CT/MRI bụng chậu cản quang, khuyến cáo thường quy; hạch nhạy ==50–60%==, đặc hiệu ==90–95%== (tương đương MRI) {{Y5 tr.63}}\n  - **Đại tràng**: CT bụng-chậu + X-quang/CT ngực; thấy ==99%== di căn gan, 33% di căn phúc mạc; hạch nghi ngờ: >8 mm, tròn, bờ không đều {{Y5 tr.273}}\n  - **Vú giai đoạn III–IV**: CT ngực, bụng, chậu; CT sọ não khi nghi di căn {{QĐ3128 tr.37–38, 7}}\n  - **Theo dõi đại trực tràng**: CT ngực/bụng/tiểu khung 3–6 tháng/lần × 2 năm đầu {{QĐ2549 tr.23}}\n- **Nhược**: đại tràng: đánh giá xâm lấn T trước mổ khó, nhạy thấp (trừ T4 ==86%==); trực tràng: xâm lấn nhạy/đặc hiệu/chính xác 78%/63%/73%, hạch 52%/78%/66% → **không** dùng đơn độc đánh giá bướu nguyên phát {{Y5 tr.273, 287–288}}\n- Theo bệnh: [Ung thư phổi · 5.3](#/n/ung-thu-phoi/5) · [Ung thư đại trực tràng · 5.3](#/n/ung-thu-daitruc-trang/5) · [Ung thư cổ tử cung · 5.3](#/n/ung-thu-cotucung/5)\n@@tab MRI\n- **Nguyên lý/ kỹ thuật**: vú, tiêm **gadolinium** tăng tương phản, nhạy theo mức tăng sinh mạch của bướu {{Y5 tr.10}}\n- **Vai trò**:\n  - **Vú – chẩn đoán/ lập kế hoạch**: không tương hợp lâm sàng–nhũ ảnh–siêu âm; ung thư tiềm ẩn (hạch nách di căn chưa rõ nguyên phát); đa ổ, đa trung tâm; khối sót sau cắt rộng; phân biệt tái phát với sẹo; trước bảo tồn, trước tân bổ trợ; túi độn {{Y5 tr.10; QĐ3128 tr.7}}\n  - **Vú – sàng lọc**: chỉ nhóm nguy cơ cao (BRCA1/2, xạ ngực 10–30 tuổi, LCIS/ADH), hoặc ≥40 tuổi nhưng mô đặc/ túi ngực; nhạy hơn nhũ ảnh nhưng đặc hiệu thấp {{QĐ3898 tr.26}}\n  - **Vú – đáp ứng**: đánh giá đáp ứng và kiểu đáp ứng sau tân hỗ trợ {{Y5 tr.10}}\n  - **Cổ tử cung**: ==xét nghiệm tốt nhất== đánh giá bướu và xâm lấn tại chỗ {{Y5 tr.63; QĐ1514 tr.PDF 365}}\n  - **Trực tràng**: MRI chậu đánh giá diện cắt bên (≤1 mm, MERCURY), mạc treo, mạch, hạch; chọn điều trị trước mổ; đánh giá sau hóa-xạ {{Y5 tr.288–289}}\n  - **Gan, thần kinh**: đại tràng: MRI khi chưa rõ tổn thương gan {{QĐ2549 tr.3}}; phổi: MRI sọ não cho số lượng, kích thước, kế hoạch dao gamma {{QĐ1514 tr.PDF 243}}\n- **Nhược**: giá cao, bắt buộc cản từ, dương giả, đọc lâu; ~5% ung thư xâm lấn bắt thuốc ít/ chậm; âm giả với carcinôm nhầy, tiểu thùy, DCIS, sau hóa trị {{Y5 tr.10}}. Chống chỉ định: máy tạo nhịp, van tim/ clip kim loại không tương thích, suy thận nặng, dị ứng cản từ, sợ không gian kín; **thai: không tiêm cản từ** {{QĐ3898 tr.26}}\n- Phổi: **không** chụp MRI não thường quy ở người không triệu chứng {{Y5 tr.111}}\n- Theo bệnh: [Ung thư vú · 5.3](#/n/ung-thu-vu/5) · [Ung thư cổ tử cung · 5.3](#/n/ung-thu-cotucung/5) · [Ung thư đại trực tràng · 5.3](#/n/ung-thu-daitruc-trang/5)\n@@tab PET và PET-CT\n- **Nguyên lý**: chụp khối u theo nguyên tắc **chuyển hóa** với F18-FDG {{QĐ2549 tr.3}}\n- **Vai trò**:\n  - **Phổi – nốt đơn độc**: PET-CT nhạy ==96%==, đặc hiệu ==75%==, giá trị tiên đoán dương và âm ~90% {{Y5 tr.110}}\n  - **Phổi – giai đoạn**: PET-CT + soi trung thất chính xác hơn; QĐ1514: phát hiện sớm, đánh giá giai đoạn, đáp ứng, tái phát, mô phỏng xạ trị, chọn vị trí sinh thiết {{Y5 tr.111; QĐ1514 tr.PDF 243}}\n  - **Cổ tử cung**: tốt nhất đánh giá hạch (nhạy >80%, đặc hiệu >95%) và di căn xa; chỉ định khi nghi di căn xa hoặc đã có hạch {{Y5 tr.63}}\n  - **Đại trực tràng**: di căn khi chẩn đoán ban đầu; tái phát (chính xác ==87%== sau mổ, xạ); đáp ứng bệnh học sau hóa-xạ trước mổ {{Y5 tr.289}}; khi CEA tăng mà hình ảnh âm tính {{QĐ2549 tr.23}}\n  - **Vú**: đánh giá giai đoạn, tái phát, di căn, mô phỏng xạ trị; dùng tùy điều kiện ở giai đoạn III–IV {{QĐ3128 tr.8, 37–38}}\n- **Nhược**: dương giả (lao, bệnh mô bào); âm giả (tổn thương <1 cm, ung thư chuyển hóa thấp như phế quản-phế nang) {{Y5 tr.110}}; NSCLC giai đoạn IV: **không** có vai trò PET-CT khi theo dõi {{Y5 tr.124}}\n- Theo bệnh: [Ung thư phổi · 5.3](#/n/ung-thu-phoi/5) · [Ung thư cổ tử cung · 5.3](#/n/ung-thu-cotucung/5) · [Ung thư đại trực tràng · 5.3](#/n/ung-thu-daitruc-trang/5)\n@@tab Xạ hình, y học hạt nhân\n- **Nguyên lý/ kỹ thuật**: SPECT hoặc SPECT/CT với đồng vị đánh dấu; xạ hình xương 99mTc-MDP {{QĐ3128 tr.7}}\n- **Vai trò**:\n  - **Xạ hình xương**: đánh giá di căn xương, chẩn đoán giai đoạn trước điều trị, theo dõi đáp ứng, tái phát; thấy di căn xương **sớm hơn** CT, MRI, dù chưa có triệu chứng (vú) {{QĐ3128 tr.7}}\n  - Cổ tử cung, phổi: khi đau xương nghi di căn {{Y5 tr.63, 111}}; đại trực tràng: xạ hình xương (Tc99m-MDP), gan (Tc99m-SC) {{QĐ2549 tr.3}}\n  - **Hạch cửa (vú)**: 99mTc-nanocolloid với đầu dò gamma hoặc xạ hình {{QĐ3128 tr.8}}\n  - **Xạ hình thận chức năng** 99mTc-DTPA: trước và sau điều trị (vú, cổ tử cung, phổi) {{QĐ3128 tr.7; QĐ1514 tr.PDF 243, 361}}\n  - Xạ hình khối u 99mTc-MIBI (vú) {{QĐ3128 tr.7}}; hình miễn dịch phóng xạ bằng kháng thể đơn dòng, SPECT (đại trực tràng) {{QĐ2549 tr.3}}\n- **Ưu/ nhược**: tài liệu không nêu thêm ngoài việc xạ hình xương thấy di căn sớm hơn CT, MRI\n- Theo bệnh: [Ung thư vú · 5.3](#/n/ung-thu-vu/5) · [Ung thư cổ tử cung · 5.3](#/n/ung-thu-cotucung/5) · [Ung thư phổi · 5.3](#/n/ung-thu-phoi/5)\n@@end\n\n### So sánh nhanh: phương tiện mạnh nhất cho từng mục đích\n| Mục đích | Phương tiện | Nguồn |\n|---|---|---|\n| Sàng lọc ung thư vú | Nhũ ảnh (± siêu âm nếu mô đặc); MRI cho nguy cơ cao | {{QĐ3898 tr.21, 23, 26}} |\n| Hạch nách (vú) | Siêu âm ± chọc hút kim | {{Y5 tr.10}} |\n| Bướu tại chỗ, cổ tử cung | MRI | {{Y5 tr.63}} |\n| Hạch và di căn xa, cổ tử cung | PET/CT | {{Y5 tr.63}} |\n| T, diện cắt bên, trực tràng | MRI chậu (hơn siêu âm qua trực tràng, hơn CT) | {{Y5 tr.288–289}} |\n| Di căn gan, đại tràng | CT bụng-chậu (==99%==); MRI hoặc PET khi chưa rõ | {{Y5 tr.273}} |\n| Nốt phổi đơn độc | CT cản quang + PET-CT (nhạy ==96%==) | {{Y5 tr.110}} |\n| Di căn xương | Xạ hình xương (sớm hơn CT, MRI) | {{QĐ3128 tr.7}} |\n| Tái phát đại tràng khi CEA tăng, hình ảnh âm | PET/CT | {{QĐ2549 tr.23}} |\n| Sàng lọc ung thư phổi (nhóm nguy cơ cao) | CT liều thấp (không phải X-quang) | {{Y5 tr.106}} |\n\n> [!warn] Hình ảnh chỉ gợi ý bản chất mô học khi đặc điểm điển hình, **không thay thế** bằng chứng mô học; ngoại lệ HCC (MRI ± AFP ± viêm gan B, C) {{SY5 tr.128, 133}}. Kết quả GPB không tương hợp lâm sàng, hình ảnh → hội chẩn lại {{SY5 tr.136}}\n\n### Điểm hay thi\n> [!warn] Bẫy thường gặp\n> - Nhũ ảnh: 2 tư thế **CC, MLO**; **âm tính không loại trừ** ung thư; BI-RADS 3 theo dõi **6 tháng**, 4–5 **sinh thiết**.\n> - Siêu âm vú **không** dùng đơn độc để sàng lọc; hạch nách nghi ngờ khi vỏ dày, ổ dãn >2,5 mm, mất rốn hạch.\n> - **MRI vú**: nhạy cao nhưng đặc hiệu thấp (dương giả → sinh thiết thừa); sàng lọc chỉ nhóm nguy cơ cao; thai không tiêm cản từ.\n> - Cổ tử cung: **MRI** tốt nhất cho bướu; **PET/CT** tốt nhất cho hạch và di căn xa; CT và MRI hạch ngang nhau (nhạy 50–60%).\n> - Trực tràng: **MRI chậu** đánh giá diện cắt bên (≤1 mm); siêu âm qua trực tràng T ==87%==, N ==74%==; CT không dùng đơn độc.\n> - Phổi: PET-CT nốt đơn độc nhạy ==96%==, đặc hiệu ==75%==; dương giả lao/ mô bào; NSCLC giai đoạn IV theo dõi **không** PET-CT.\n> - Xạ hình xương thấy di căn xương **sớm hơn** CT, MRI.\n> - X-quang ngực ± đờm **không** sàng lọc được ung thư phổi; CT liều thấp cho nhóm nguy cơ cao."}, {"kind": "foundation", "disease": "", "short": "Hội chẩn liên chuyên khoa", "group": "Điều trị và chăm sóc", "section": 2, "order": 4, "khung": [], "id": "ung-thu-hoi-chan-lien-chuyen-khoa", "title": "Hội chẩn và phối hợp liên chuyên khoa", "layer": "dieutri", "module": "ung-buou", "tags": ["hội chẩn", "liên chuyên khoa", "đa chuyên khoa", "đa mô thức", "vai trò chuyên khoa", "trình bệnh", "kết luận hội chẩn", "ung bướu"], "source": "Y5 tr.11–12, 22–23, 64, 120, 142–146, 162, 193–195, 222, 234, 249, 251, 261, 277, 292–298, 341; SY5 tr.131–136, 269; QĐ1514 tr.PDF 98, 107, 193, 488; ĐC Y5 tr.4 (MT15, MT17)", "body": "> [!key] Hội chẩn liên chuyên khoa trong một nhìn\n> - Hội chẩn đa chuyên khoa ảnh hưởng đến quyết định chẩn đoán và điều trị ở **phần lớn bệnh nhân mới được chẩn đoán** {{Y5 tr.142}}\n> - Đầu cổ, thực quản, trực tràng đều là **điều trị đa mô thức** (phẫu, xạ, hóa, toàn thân) {{Y5 tr.144}} {{Y5 tr.249}} {{Y5 tr.292}}; riêng đầu cổ, trình tự và lựa chọn mô thức **cần có hội chẩn liên chuyên khoa** {{Y5 tr.144}}\n> - Trước điều trị phải có **chẩn đoán và giai đoạn chính xác**; lý tưởng là có mô bệnh học trước khi lập kế hoạch {{Y5 tr.292}} {{SY5 tr.132}}\n> - Kết quả GPB không tương hợp với lâm sàng và hình ảnh học thì **xem lại và hội chẩn lại** {{SY5 tr.136}}\n\n### Mục tiêu học tập\n- **MT17: hợp tác tốt với đồng nghiệp trong cách làm việc liên chuyên khoa** {{ĐC Y5 tr.4}}\n- Liên quan **MT15**: tuân thủ nguyên tắc điều trị, nhất là **phối hợp đa mô thức, liên chuyên khoa** {{ĐC Y5 tr.4}}\n- Sau bài: nêu vai trò từng chuyên khoa; trình bệnh và ghi kết luận hội chẩn; trình tự điều trị đa mô thức theo giai đoạn\n\n### Vai trò từng chuyên khoa\n| Chuyên khoa | Vai trò trong hội chẩn |\n|---|---|\n| **Phẫu thuật (ngoại)** | Điều trị bước đầu cho giai đoạn tiến triển tại chỗ, thường kèm tạo hình để giữ chức năng (ung thư hốc miệng III–IV) {{Y5 tr.162}}; cắt dạ dày hoặc đại tràng cần đánh giá giai đoạn bởi nhóm đa chuyên khoa {{Y5 tr.261}} {{Y5 tr.277}}; nếu nghi ngờ bảo tồn cơ thắt trực tràng thì cần ý kiến phẫu thuật viên có kinh nghiệm trước mọi điều trị trước mổ {{Y5 tr.294}} |\n| **Hóa trị (ung bướu nội khoa)** | Hóa trị dẫn đầu, hóa-xạ đồng thời hoặc hóa trị trước/sau mổ tùy giai đoạn {{Y5 tr.144}} {{Y5 tr.261}}; hóa trị giảm nhẹ hoặc liệu pháp miễn dịch cho tái phát, di căn không điều trị triệt để {{Y5 tr.146}}; hóa trị hỗ trợ trực tràng: cân nhắc từng ca theo hội chẩn, chưa có bằng chứng chắc chắn {{Y5 tr.298}} |\n| **Xạ trị** | Xạ bổ túc sau mổ khi nguy cơ tái cao: diện cắt không an toàn hoặc dương tính, xâm lấn thần kinh, xâm lấn khoang lymphô-mạch máu, xâm lấn ngoài vỏ bao hạch {{Y5 tr.144}}; xạ triệt để cho người bệnh có bệnh nội khoa kèm không thể phẫu thuật {{Y5 tr.144}}; xạ giảm nhẹ di căn xương, di căn não (ung thư vú) {{Y5 tr.23}} |\n| **Chẩn đoán hình ảnh** | Hình ảnh hướng dẫn sinh thiết {{Y5 tr.12}}; đánh giá đáp ứng (đầu cổ): khám lâm sàng khoảng 6 tuần sau xạ, hình ảnh đầy đủ sau 12 tuần, chụp quá sớm (nhất là PET/CT) dễ dương tính giả {{Y5 tr.146}}; chuẩn hóa báo cáo để tạo \"tiếng nói chung\" (tuyến giáp) {{Y5 tr.222}} |\n| **Giải phẫu bệnh** | Mô bệnh học là tiêu chuẩn vàng chẩn đoán xác định {{SY5 tr.131}}; đọc kết quả sinh thiết lõi kim {{Y5 tr.11}}; hóa mô miễn dịch và hội chẩn chuyên gia khi chưa xác định được nguyên phát (ung thư chưa rõ nguyên phát) {{QĐ1514 tr.PDF 488}}; khi cần sinh thiết lại thì hội chẩn giải phẫu bệnh với lâm sàng {{Y5 tr.64}} |\n| **Dinh dưỡng** | Can thiệp dinh dưỡng sớm từ lúc chẩn đoán đến suốt đời; 20% người bệnh ung thư tử vong do suy dinh dưỡng {{QĐ1514 tr.PDF 107}}; phát hiện và xử trí vấn đề dinh dưỡng, nói nuốt, răng miệng, tâm lý (ung thư hốc miệng) {{Y5 tr.162}}; tái khám ung thư thực quản có tham vấn dinh dưỡng {{Y5 tr.251}} |\n| **Chăm sóc giảm nhẹ** (chuyên khoa: tài liệu không nêu) | Điều trị triệu chứng và rối loạn tâm lý, đặc biệt đau, để nâng cao chất lượng sống {{QĐ1514 tr.PDF 98}}; giai đoạn cuối không còn khả năng phẫu thuật hoặc hóa-xạ trị: chăm sóc giảm nhẹ (ung thư tuyến nước bọt) {{QĐ1514 tr.PDF 193}}; người bệnh tổng trạng kém hoặc nhiều bệnh nội khoa không chịu nổi hóa trị (ung thư phổi không tế bào nhỏ) {{Y5 tr.120}} |\n| **Nha sĩ, phục hồi chức năng, tâm lý** | Nha sĩ, phục hình răng, chuyên gia phục hồi chức năng đầu cổ, bác sĩ tâm lý {{Y5 tr.142}}; đội phục hồi giọng nói là then chốt trong mọi tiểu ban liên chuyên khoa ung thư thanh quản {{Y5 tr.194}} |\n| **Sản khoa, sơ sinh** | Ung thư vú khi mang thai: phẫu thuật viên, hóa trị, xạ trị phối hợp với sản khoa, sơ sinh và tâm lý để cân bằng lợi ích cho mẹ và con {{Y5 tr.22}} |\n\n### Trình tự điều trị đa mô thức\n1. **Chẩn đoán và giai đoạn chính xác trước khi chọn điều trị** (ung thư trực tràng): đây là bước đầu tiên và quan trọng nhất, giúp tránh điều trị quá tay hoặc không đủ {{Y5 tr.292}}\n2. **Tái phát tại chỗ**: đánh giá tìm di căn xa trước điều trị ở người bệnh tổng trạng tốt, bệnh còn khu trú {{Y5 tr.146}}\n3. **Đặt mục tiêu**: tại chỗ–tại vùng là khỏi bệnh; di căn xa là kéo dài sống còn và duy trì chất lượng sống {{SY5 tr.269}}\n4. **Chọn mô thức theo giai đoạn** (bảng dưới)\n5. **Hội chẩn liên chuyên khoa** để quyết định trình tự và lựa chọn phẫu trị, xạ trị, hóa trị {{Y5 tr.144}}\n6. **Theo dõi sau điều trị** (ung thư thanh quản): ê-kíp gồm phẫu thuật viên, xạ trị, ung bướu nội khoa, nha sĩ, phục hồi chức năng; theo dõi tích cực 2–4 năm đầu vì 80–90% tái phát trong thời gian này {{Y5 tr.195}}. Ung thư đầu cổ: lập và gửi kế hoạch chăm sóc, tóm tắt bệnh án cho người bệnh và bác sĩ gia đình trong 6 tháng sau khi kết thúc điều trị {{Y5 tr.146}}\n\n#### Theo giai đoạn (ung thư đầu cổ, carcinôm tế bào gai)\n| Tình huống | Hướng đa mô thức | Nguồn |\n|---|---|---|\n| Khu trú, giai đoạn I–II | Phẫu trị hoặc xạ trị đơn thuần; nguy cơ cao thì phối hợp cả hai | {{Y5 tr.143}} |\n| Tiến xa tại chỗ–tại vùng, III–IVB | Đa mô thức gồm xạ trị và hóa trị; ưu tiên tiếp cận bảo tồn chức năng | {{Y5 tr.143}} {{Y5 tr.144}} |\n| Tái phát tại chỗ, di căn xa | Hóa trị giảm nhẹ, miễn dịch và/hoặc chăm sóc giảm nhẹ; ít trường hợp tái phát khu trú có thể phẫu hoặc xạ lại | {{Y5 tr.143}} {{Y5 tr.146}} |\n\n#### Ví dụ theo cơ quan\n| Cơ quan | Điểm đa mô thức và hội chẩn | Nguồn |\n|---|---|---|\n| Thanh quản, III–IV | Tiếp cận đa chuyên khoa trước điều trị gồm phẫu, hóa, xạ; chọn lựa theo vị trí, giai đoạn, thể trạng, tâm sinh lý, kinh nghiệm ê-kíp và dịch vụ phục hồi | {{Y5 tr.193}} |\n| Thực quản | Phẫu thuật và xạ trị là 2 phương thức chính kiểm soát tại chỗ–tại vùng, kèm điều trị toàn thân; chọn theo giai đoạn, mô học, thể trạng | {{Y5 tr.249}} |\n| Dạ dày, đại tràng | Phẫu thuật giữ vai trò chính; hóa trị trước hoặc sau mổ tùy giai đoạn; đánh giá giai đoạn bởi nhóm đa chuyên khoa là rất cần thiết | {{Y5 tr.261}} {{Y5 tr.277}} |\n| Trực tràng | Đa mô thức; đánh giá giai đoạn chính xác là bước đầu; hóa trị hỗ trợ cá thể hóa theo ý kiến hội chẩn | {{Y5 tr.292}} {{Y5 tr.298}} |\n| Tuyến tiền liệt, nguy cơ cao | Xạ trị ngoài kết hợp điều trị nội tiết 2–3 năm là lựa chọn ưu tiên; phẫu thuật tận gốc (nếu chọn) bàn kỹ trong hội chẩn đa chuyên khoa | {{Y5 tr.341}} |\n| Ung thư vú | \"Tailor's therapy\": theo yếu tố tiên lượng, tình trạng kinh nguyệt, bệnh kèm và mong muốn của người bệnh | {{SY5 tr.269}} |\n\n### Trình bệnh và ghi kết luận hội chẩn\n> [!tip] Ba nguồn phải tương hợp: lâm sàng, hình ảnh và tế bào học hoặc mô học\n> - FNA lệch với lâm sàng và hình ảnh thì cần làm thêm sinh thiết lõi kim, sinh thiết trọn bướu {{Y5 tr.11}}\n> - Kết quả GPB không tương hợp với lâm sàng và hình ảnh thì xem lại và hội chẩn lại {{SY5 tr.136}}\n> - Khi cả ba tương hợp lành tính thì xuất độ ung thư 0–0,6%; tương hợp ác tính thì 99% (ung thư vú) {{Y5 tr.11}}\n\n@@tabs\n@@tab Trình bệnh\n- Tài liệu không nêu mẫu trình bệnh (thứ tự, thời lượng, người trình bày). Các yếu tố nguồn cho là cần đưa vào quyết định:\n  - Vị trí bướu nguyên phát và mức độ lan rộng {{Y5 tr.144}}\n  - Giai đoạn, kết quả mô bệnh học; hình ảnh và GPB có tương hợp với lâm sàng không {{SY5 tr.136}}\n  - Tuổi, bệnh nội khoa kèm, thể trạng, tâm lý, mong muốn của người bệnh {{Y5 tr.144}} {{Y5 tr.193}}\n  - Kết cục chức năng và biến chứng của từng mô thức điều trị {{Y5 tr.144}}\n  - Kinh nghiệm, kỹ thuật và dịch vụ phục hồi chức năng sẵn có tại trung tâm {{Y5 tr.144}} {{Y5 tr.193}}\n  - Ung thư vú: tình trạng kinh nguyệt hiện tại và yếu tố tiên lượng {{SY5 tr.269}}\n- Thành phần cố định của hội chẩn, tần suất họp: — tài liệu không nêu\n- Vai trò điều dưỡng, dược sĩ trong hội chẩn: — tài liệu không nêu\n@@tab Ghi kết luận\n- Nội dung kết luận theo nguồn: trình tự điều trị và lựa chọn phẫu trị, xạ trị, hóa trị {{Y5 tr.144}}\n- Hóa trị hỗ trợ sau mổ trực tràng: quyết định theo ý kiến hội chẩn về điều trị đa mô thức {{Y5 tr.298}}\n- Thời điểm phẫu thuật phòng ngừa ở trẻ có đột biến RET (ung thư tuyến giáp dạng tủy di truyền): dựa trên đội ngũ đa chuyên khoa và tham vấn cha mẹ {{Y5 tr.234}}\n- Mẫu biên bản, người chủ trì, người ghi và ký, cách lưu hồ sơ: — tài liệu không nêu\n- Gợi ý của bài (không phải nội dung nguồn): đưa kết luận vào phần Điều trị và tóm tắt theo giai đoạn của bệnh án: [[ung-thu-cach-lam-benh-an|Cách làm bệnh án ung thư]]\n@@end\n\n### Điểm hay thi\n> [!warn]\n> - Hội chẩn liên chuyên khoa quyết định **trình tự** và **lựa chọn** phẫu, xạ, hóa ở tiến xa tại chỗ–tại vùng {{Y5 tr.144}}\n> - Đánh giá giai đoạn chính xác là bước đầu tiên và quan trọng nhất (ung thư trực tràng) {{Y5 tr.292}}\n> - Ung thư đầu cổ: điều trị tại trung tâm nhiều kinh nghiệm cho sống còn 5 năm ==69% so với 51%==, không giải thích được bằng khác biệt yếu tố tiên lượng {{Y5 tr.142}}\n> - Đánh giá đáp ứng bằng hình ảnh không làm quá sớm; PET/CT trước 12 tuần dễ dương tính giả (đầu cổ) {{Y5 tr.146}}\n\n> [!warn] Hai ý cần cân nhắc cùng lúc, không ghi một chiều\n> - Đầu cổ tiến xa: ưu tiên tiếp cận bảo tồn chức năng {{Y5 tr.143}}\n> - Thanh quản: bảo tồn cải thiện chức năng nhưng **không cải thiện sống còn** so với cắt toàn phần; cắt toàn phần cho sống còn và chất lượng sống cao hơn ở T3 hoặc T4a {{Y5 tr.193}}\n\n### Tự kiểm tra\n- Hội chẩn liên chuyên khoa ảnh hưởng đến điều gì ở phần lớn bệnh nhân mới được chẩn đoán? :: Quyết định chẩn đoán và điều trị\n- Khi kết quả GPB không tương hợp với lâm sàng và hình ảnh học, thầy thuốc làm gì? :: Xem lại, hội chẩn lại GPB, hình ảnh và xét nghiệm; nghĩ đến bệnh lý khác để chẩn đoán phân biệt\n- Bước đầu tiên và quan trọng nhất để chọn điều trị ung thư trực tràng là gì? :: Đánh giá giai đoạn bệnh chính xác\n- Mục tiêu điều trị ở giai đoạn tại chỗ–tại vùng và khi đã di căn xa khác nhau thế nào? :: Tại chỗ–tại vùng là khỏi bệnh; di căn xa là kéo dài sống còn và duy trì chất lượng sống\n- Hội chẩn cần quyết định những gì ở ung thư tiến xa tại chỗ–tại vùng? :: Trình tự điều trị và lựa chọn phẫu trị, xạ trị, hóa trị"}, {"kind": "foundation", "disease": "", "short": "Cận u – chèn ép – cấp cứu", "group": "Khái quát triệu chứng học", "section": 3, "order": 3, "khung": [], "id": "ung-thu-hoi-chung-can-u-va-chen-ep", "title": "Hội chứng cận u, chèn ép và biến chứng cấp thường gặp", "layer": "trieuchung", "module": "ung-buou", "tags": ["hội chứng cận u", "SIADH", "tăng canxi máu", "chèn ép tĩnh mạch chủ trên", "chèn ép tủy", "tăng áp lực nội sọ", "cấp cứu ung thư"], "source": "Y5 tr. 106–110, 112; QĐ1514 tr. PDF 16–20, 23–24, 37–38, 53–54, 58–60, 64–65, 68–72, 76–77, 81–82, 88, 124, 242–243, 552", "body": "> [!key] Tóm tắt\n> - Triệu chứng của ung thư phổi do **3 nguồn**: bướu nguyên phát, cơ quan di căn, **hội chứng cận u**. {{Y5 tr.109}}\n> - Y5 (theo mô học phổi): **SCLC → SIADH, tăng đông**; **tế bào gai → tăng canxi máu**; **tuyến → phì đại xương khớp, tăng đông, tăng canxi, nữ hóa tuyến vú**. {{Y5 tr.106–107}}\n> - **Chèn ép** thường gặp: **TM chủ trên**, **trung thất**, **tủy sống**, **não** (tăng áp lực nội sọ); cùng các **biến chứng cấp** (ho ra máu, XHTH, tăng canxi máu, ly giải u...). {{QĐ1514 tr.PDF 53, 58, 68}}\n> - Nguồn **không có định nghĩa** \"hội chứng cận u\" và không nêu cơ chế từng hội chứng, trừ danh sách chất do u tiết ở QĐ1514. {{QĐ1514 tr.PDF 243}}\n> - Tổng quát: [[ung-thu-trieu-chung-khai-quat]]; ví dụ áp dụng: [Ung thư phổi · 5.2](#/n/ung-thu-phoi/4).\n\n### 1. Hội chứng cận ung thư\n@@tabs\n@@tab Y5: theo mô học phổi\n| Mô học | Hội chứng cận u |\n|---|---|\n| **SCLC** (UTPTBN, ==15%== ca) | **SIADH** thường gặp nhất; **tăng đông** cũng thường gặp; hội chứng **ACTH** không thường gặp; **Eaton-Lambert** hiếm hơn; tăng canxi máu **hiếm** dù di căn xương nhiều nơi {{Y5 tr.106}} |\n| **Carcinôm tế bào gai** (==20–25%== NSCLC) | **Tăng canxi máu** do peptide liên quan hormon cận giáp **thường gặp nhất**; phì đại xương khớp đôi khi; tăng bạch cầu đa nhân hoặc tăng đông có thể thấy {{Y5 tr.107}} |\n| **Carcinôm tuyến** (==50–60%== NSCLC) | **Phì đại xương khớp**, tăng đông, tăng canxi máu, **nữ hóa tuyến vú** {{Y5 tr.107}} |\n@@tab QĐ1514: danh sách và chất do u tiết\n| Hội chứng | Mô tả theo nguồn |\n|---|---|\n| **Ngón tay dùi trống** | Nêu trong danh sách |\n| \"Đái tháo nhạt\" | Do khối u bài tiết chất giống **ADH** |\n| **Cushing** | Chất giống **ACTH** |\n| **Tăng canxi máu** | Chất giống **PTH** |\n| Vú to, giọng cao, teo tinh hoàn | Chất giống **gonadotropin** |\n| **Giả nhược cơ**, **viêm da cơ** | Viêm da cơ: bệnh tự miễn gặp trong một số ung thư |\n{{QĐ1514 tr.PDF 243}}\n@@end\n\n> [!warn] Mâu thuẫn nguồn (để thi theo Y5)\n> - QĐ1514 ghi cận ung thư \"thường gặp hơn trong NSCLC\" và nêu **đái tháo nhạt**; Y5 ghi **SIADH** thường nhất ở **SCLC**. {{QĐ1514 tr.PDF 243}} {{Y5 tr.106}}\n> - Bảng 2 Y5 in \"Viêm da–cơ (hội chứng Eaton-Lambert)\" cùng một dòng; phần chữ Y5 gọi Eaton-Lambert là hội chứng nhược cơ của SCLC. {{Y5 tr.106, 110}}\n> - Y5 và QĐ1514 **không nêu** biểu hiện lâm sàng/ xét nghiệm của SIADH hay Cushing: \"tài liệu không nêu\".\n\n#### Các hội chứng cận u/ chuyển hóa khác trong QĐ1514\n| Hội chứng | Biểu hiện, ngưỡng | Ung thư thường gặp |\n|---|---|---|\n| **Tăng canxi máu** | Gặp ==20–30%== bệnh nhân ung thư; calci toàn phần ≥ ==2,6–2,7== mmol/l hoặc calci ion hóa > ==1,3== mmol/l; lâm sàng khi > ==3== mmol/l {{QĐ1514 tr.PDF 23}} | U hệ tạo huyết; u tiết peptid giống PTH (buồng trứng, thận, phổi, vú, đầu cổ, bàng quang); **đa u tủy**; **di căn xương** {{QĐ1514 tr.PDF 24}} |\n| **Thuyên tắc huyết khối tĩnh mạch** | Gặp ==20%==; nguy cơ tăng ==4–7== lần; có thể là triệu chứng **nhiều tháng đến nhiều năm trước** khi chẩn đoán ung thư {{QĐ1514 tr.PDF 88}} | Mọi ung thư (vị trí, giai đoạn, mô học ảnh hưởng nguy cơ) |\n| **Hạ đường huyết** | Hôn mê không rõ nguyên nhân ở bệnh nhân ung thư giai đoạn muộn; đường máu thường < ==2,8== mmol/l {{QĐ1514 tr.PDF 19–20}} | **Ung thư tụy** hoặc di căn tụy tăng tiết insulin; giai đoạn cuối {{QĐ1514 tr.PDF 20}} |\n| **Suy mòn** | Mất liên tục khối cơ ± mỡ; xem [[ung-thu-trieu-chung-khai-quat]] {{QĐ1514 tr.PDF 108}} | Gặp ==8–84%==; tiêu hóa, đầu cổ nhiều |\n| Rung giật mắt – co giật chi | \"Hội chứng cận u\" của **u nguyên bào thần kinh** (trẻ em) {{QĐ1514 tr.PDF 552}} | U nguyên bào thần kinh |\n\n> [!red] Tăng canxi máu là cấp cứu: **không dùng digoxin** (dễ ngừng tim đột ngột). Triệu chứng không đặc hiệu (mệt, rối loạn tiêu hóa, đổi hành vi) nên hay chẩn đoán sai nếu không **định lượng calci máu**. {{QĐ1514 tr.PDF 23}}\n\n@@fold Lâm sàng tăng canxi máu {{QĐ1514 tr.PDF 23}}\n- **Thần kinh**: đau cơ, chuột rút, liệt gốc chi, trầm cảm, đau đầu, ngủ gà, hôn mê\n- **Tiêu hóa**: chán ăn, buồn nôn, đau bụng (có thể dữ dội như viêm tụy cấp), táo bón\n- **Tim mạch**: huyết áp cao, rối loạn nhịp; điện tim PR kéo dài, QT ngắn\n- **Thận**: đái nhiều, mất nước; có thể thiểu niệu, vô niệu do lắng đọng calci\n@@end\n\n### 2. Hội chứng chèn ép\n@@tabs\n@@tab Tĩnh mạch chủ trên\n- Nguyên nhân: bướu xâm lấn hoặc chèn ép từ ngoài (phổi phải, hạch, u trung thất) hoặc huyết khối {{QĐ1514 tr.PDF 68}}\n- Cơ năng: **khó thở** (phổ biến nhất), đau ngực, ho, nuốt khó, **căng tức đầu tăng khi cúi/ nằm** {{QĐ1514 tr.PDF 68}}\n- Thực thể: **phù mặt, cổ, phù áo khoác, phù tay**, tuần hoàn bàng hệ, giãn TM cổ ngực; có thể phù não (đau đầu, lẫn, co giật, hôn mê) {{QĐ1514 tr.PDF 68}}\n- Ung thư hay gặp: **phổi**, u trung thất, thực quản, thanh quản–hạ họng, NHL, **vú**, hạch di căn {{QĐ1514 tr.PDF 69}}\n- Xử trí tóm tắt: oxy; stent TM trước rồi xạ; ung thư nhạy hóa chất (SCLC, NHL, u tế bào mầm, vú) hóa trị ngay {{QĐ1514 tr.PDF 69–70}}\n@@tab Trung thất – hạch rốn phổi\n| Cấu trúc bị chèn | Biểu hiện |\n|---|---|\n| TM chủ trên | Phù áo khoác, TM cổ nổi, tuần hoàn bàng hệ |\n| Thực quản | Khó nuốt, nuốt đau (Y5: nuốt nghẹn) |\n| Thần kinh quặt ngược trái | **Khàn tiếng**, giọng đôi |\n| Giao cảm cổ | Khe mắt hẹp, đồng tử co, gò má đỏ: **Horner** |\n| Thần kinh phế vị | Hồi hộp, tim nhanh |\n| Thần kinh hoành | Nấc, đau vùng hoành, khó thở |\n| Đám rối cánh tay | Đau vai lan mặt trong cánh tay, rối loạn cảm giác |\n| Ống ngực chủ | Tràn dưỡng chấp màng phổi |\n{{QĐ1514 tr.PDF 242}} {{Y5 tr.109}}\n- Thêm: tràn dịch màng phổi, tràn dịch màng tim, rối loạn nhịp; **bướu Pancoast** (đỉnh phổi): đau vai nhiều do xâm lấn đám rối cánh tay, hủy xương sườn 1 {{Y5 tr.112}}\n@@tab Tủy sống (di căn cột sống)\n- Ung thư thường di căn cột sống: **tuyến tiền liệt, phổi, vú**, thận, NHL, đa u tủy; ==3–5%== bệnh nhân chết vì ung thư có di căn cột sống {{QĐ1514 tr.PDF 58, 60}}\n- **Đau** là biểu hiện đầu tiên (==80–90%==), xuất hiện **nhiều tuần trước** thiếu hụt thần kinh; sau đó rối loạn cảm giác, vận động, cơ tròn {{QĐ1514 tr.PDF 58}}\n- **Hội chứng đuôi ngựa**: đau kiểu rễ hai chân, yếu hai chân, mất cảm giác hai chân, rối loạn cơ tròn {{QĐ1514 tr.PDF 59}}\n- Đa số được chẩn đoán khi **không còn đi lại được** → nghi ngờ thì **MRI toàn bộ cột sống** sớm nhất, trong ==24 giờ== {{QĐ1514 tr.PDF 58–59}}\n- Có thể là **biểu hiện đầu tiên** của ung thư (bướu nguyên phát phát hiện sau) {{QĐ1514 tr.PDF 58}}\n@@tab Não: tăng áp lực nội sọ\n- Giai đoạn sớm: **đau đầu tăng dần**, từng cơn buổi sáng, kèm nôn (nôn vọt gợi ý hố sau); rối loạn ý thức; phù gai thị; động kinh; **tam chứng Cushing** (tăng huyết áp, mạch chậm, rối loạn nhịp thở) {{QĐ1514 tr.PDF 53}}\n- Muộn (tụt não): hôn mê tiến triển nhanh, rối loạn thần kinh thực vật, giãn đồng tử; **Glasgow < 8** = hôn mê sâu {{QĐ1514 tr.PDF 53–54}}\n- **Di căn não**: đau đầu ==40–50%==; dấu thần kinh khu trú ==20–40%==; đổi tính cách ==30–35%==; động kinh mới ==10–20%==; đột quỵ ==5–10%== {{QĐ1514 tr.PDF 124}}\n@@end\n\n> [!red] Cần xử trí ngay\n> - **Phù áo khoác + TM cổ nổi + khó thở** (chèn ép TM chủ trên).\n> - **Đau lưng + yếu chân/ rối loạn cơ tròn** (chèn ép tủy): chụp MRI trong 24 giờ.\n> - **Đau đầu + nôn + rối loạn ý thức**, tam chứng Cushing, giãn đồng tử (tăng áp lực nội sọ/ tụt não). {{QĐ1514 tr.PDF 53, 58–59, 68}}\n\n### 3. Biến chứng cấp thường gặp (nhận diện nhanh)\n| Biến chứng | Nhận diện | Ung thư/ nguyên nhân hay gặp |\n|---|---|---|\n| **Ho ra máu** | Ít < ==50== ml/24 giờ; trung bình ==50–200==; nặng > ==200==, > ==500== nguy kịch; **sét đánh** {{QĐ1514 tr.PDF 64}} | Đầu mặt cổ (hạ họng, thanh quản, khí quản); phổi (rốn phổi, xâm lấn mạch lớn); thực quản, trung thất {{QĐ1514 tr.PDF 65}} |\n| **XHTH do ung thư** | Nôn máu, phân đen (trên); phân máu đỏ (dưới); da xanh; nặng: HA tâm thu < ==90== mmHg, mất > ==500== ml {{QĐ1514 tr.PDF 71–72}} | Thực quản, dạ dày–ruột, đường mật, gan (giãn vỡ TM thực quản), **đại trực tràng**, ống hậu môn {{QĐ1514 tr.PDF 72}} |\n| **Tràn dịch đa màng** | Màng phổi, tim, bụng, dưới nhện (giai đoạn tiến triển); TDMP: khó thở, đau tức ngực, hội chứng 3 giảm {{QĐ1514 tr.PDF 37}} | Phổi (tuyến), **vú**, lymphoma, u trung mô, tiêu hóa, buồng trứng, tử cung {{QĐ1514 tr.PDF 38}} |\n| **Suy hô hấp cấp** | PaO2 < ==55== mmHg (FiO2 ≥ ==0,6==) hoặc PaCO2 > ==45== và pH < ==7,35== {{QĐ1514 tr.PDF 82}} | Bít tắc đường thở (khoang miệng, thanh quản, hạ họng, phế quản, trung thất); tổn thương phế nang; ngoài phổi: não, tủy, thành ngực, chèn ép {{QĐ1514 tr.PDF 81}} |\n| **Suy thận cấp** | Thiểu niệu, vô niệu, phù, ure–creatinin tăng, tăng kali {{QĐ1514 tr.PDF 76}} | **Sau thận**: u/ hạch chèn đường bài xuất (đại trực tràng, thận, buồng trứng, **cổ tử cung**, sau phúc mạc, bàng quang, tuyến tiền liệt); trước thận: mất máu, XHTH {{QĐ1514 tr.PDF 77}} |\n| **Hội chứng ly giải u** | Buồn nôn, tiêu chảy, thiểu/ vô niệu, co giật, rối loạn nhịp; acid uric ≥ ==8== mg/dl, K ≥ ==6== mmol/l, phospho ≥ ==4,5== mg/dl (người lớn), calci ≤ ==7== mg/dl {{QĐ1514 tr.PDF 16}} | **NHL ác tính cao**, bạch cầu cấp, u lớn/ nhạy trị liệu; xảy ra sau điều trị gây độc tế bào hoặc tự phát {{QĐ1514 tr.PDF 16–17}} |\n\n@@fold Liên hệ vào các trang bệnh\n- **Phổi**: cận u (SIADH, tăng canxi...), hội chứng trung thất, chèn ép TM chủ trên, ho ra máu → [Ung thư phổi · 5.2](#/n/ung-thu-phoi/4); khung [STT 41](#/khung/41), [STT 46](#/khung/46)\n- **Cổ tử cung**: suy thận sau thận, dò, xuất huyết âm đạo nhiều → [Ung thư cổ tử cung · 5.2](#/n/ung-thu-cotucung/4); khung [STT 87](#/khung/87)\n- **Đại trực tràng**: XHTH, tắc ruột, thủng u → [Ung thư đại trực tràng · 5.2](#/n/ung-thu-daitruc-trang/4); khung [STT 57](#/khung/57)\n- **Vú**: tràn dịch màng phổi ác tính, di căn xương/ não/ cột sống → [Ung thư vú · 5.2](#/n/ung-thu-vu/4)\n- Cơ chế xâm lấn, di căn: [[ung-thu-xam-lan-di-can]]; bảng tra triệu chứng: [[ung-thu-trieu-chung-theo-co-quan]]\n@@end\n\n### Điểm hay thi\n> [!warn]\n> - Ung thư phổi: **SCLC = SIADH** (thường nhất) và tăng đông; **tế bào gai = tăng canxi máu** (PTH-rP); **tuyến = phì đại xương khớp/ ngón tay dùi trống, nữ hóa tuyến vú**.\n> - QĐ1514 và Y5 khác nhau về hội chứng nào hay gặp ở NSCLC/ SCLC: nhớ cả hai, thi theo Y5.\n> - **Tăng canxi máu** là cấp cứu: ngưỡng calci toàn phần ≥ 2,6–2,7 mmol/l; không dùng **digoxin**.\n> - **Chèn ép TM chủ trên**: phù áo khoác, TM cổ nổi, khó thở; nguyên nhân hàng đầu **ung thư phổi**; SCLC nhạy hóa chất nên hóa trị ngay.\n> - **Chèn ép tủy**: đau đến trước (80–90%), MRI trong 24 giờ; hội chứng đuôi ngựa.\n> - **Tam chứng Cushing** (tăng HA, mạch chậm, rối loạn nhịp thở) = tăng áp lực nội sọ.\n> - Ho ra máu: > 200 ml/24 giờ là nặng; > 500 ml nguy kịch.\n> - **Thuyên tắc huyết khối tĩnh mạch** có thể xuất hiện **trước** khi phát hiện ung thư."}, {"kind": "foundation", "disease": "", "short": "Liệu pháp miễn dịch", "group": "Giải phẫu bệnh, xâm lấn, di căn, miễn dịch", "section": 0, "order": 5, "khung": [], "id": "ung-thu-mien-dich-tri-lieu", "title": "Liệu pháp miễn dịch trong ung thư — cơ sở và các nhóm điều trị", "layer": "nen", "module": "ung-buou", "tags": ["mien-dich-tri-lieu", "checkpoint", "pd-1", "ctla-4", "cytokine", "vaccine", "msi"], "source": "Y2 tr. 58–63; SY2 tr. 322, 385–392", "body": "> [!key] Ý chính\n> - Miễn dịch trị liệu = phương thức điều trị **thứ năm** (sau phẫu thuật, hóa trị, xạ trị, nhắm trúng đích) {{Y2 tr.59}}.\n> - Hai hướng: **thụ động** (kháng thể đơn dòng, ACT, cytokine) và **chủ động** (vaccine, virus ly giải bướu, **ức chế chốt miễn dịch**) {{SY2 tr.387}}.\n> - Chốt đã vào lâm sàng: **CTLA-4** và **PD-1/PD-L1**.\n> - Chủ yếu cho bệnh **tiến xa**; ưu điểm đặc hiệu, ít tác dụng phụ; nhóm **MSI-H/dMMR** đáp ứng pembrolizumab.\n> - Cơ sở: [[ung-thu-mien-dich]].\n\n### 1. Cơ sở và phân loại\n- Miễn dịch tự nhiên thất bại + không đặc hiệu → huấn luyện, điều khiển hệ miễn dịch chống bướu đặc hiệu; dựa trên chu kỳ miễn dịch chống bướu {{SY2 tr.385–386}}.\n\n| | Thụ động | Chủ động |\n|---|---|---|\n| Nội dung | Kháng thể đơn dòng · truyền T nuôi cấy (**ACT**) · cytokine | Vaccine (tế bào tua, tế bào dị ghép, peptide) · virus ly giải bướu · ức chế chốt miễn dịch |\n{{SY2 tr.387}} {{Y2 tr.59}}\n- **Kích hoạt**: tiêm kháng nguyên bướu, tăng trình diện, ACT, virus ly giải bướu, kháng thể chống TNF. **Gỡ ức chế**: cyclophosphamide, kháng thể giảm Treg, ức chế CTLA-4/PD-1 {{Y2 tr.59}}.\n- Ví dụ theo thời kỳ {{SY2 tr.388}}: IFN-α/IL-2 (thận, melanoma) · Rituxan (lymphôm nang) · Herceptin (vú) · Provenge (tuyến tiền liệt) · Yervoy (melanoma).\n\n### 2. Các nhóm thuốc\n@@tabs\n@@tab Kháng thể đơn dòng\n- Gắn đích đặc hiệu: kích thích miễn dịch, đánh dấu tế bào ung thư, ức chế đường tăng trưởng.\n- Dùng: bạch cầu, vú, tiêu hóa, đầu cổ {{Y2 tr.60}}.\n@@tab Ức chế chốt miễn dịch\n- Bướu tận dụng \"điểm dừng\" để tránh bị phát hiện. **CTLA-4** (trên T) và **PD-1** (ức chế T) → ức chế chúng \"giải phóng hàng rào\" tăng đáp ứng T.\n- SY2: PD-1 trên T gắn **PD-L1** trên tế bào ung thư → T bất hoạt; kháng PD-1 chặn tương tác {{Y2 tr.60}} {{SY2 tr.391–392}}.\n@@tab Cytokine\n- IFN và interleukin; hay dùng **IL-2** và **IFN-α**.\n- IL-2 = yếu tố tăng trưởng T; liều cao: đáp ứng hoàn toàn ==4–6%== ở ung thư tế bào thận, bạch cầu {{Y2 tr.60}}.\n@@tab Vaccine điều trị\n- Mục đích **không ngừa bệnh** mà tạo đáp ứng chủ động chống tế bào ung thư (tiêm/truyền TM).\n- Bướu đặc: kháng nguyên đa dạng → khó; đa phần pha II–III, chưa FDA chấp thuận {{Y2 tr.60–61}}.\n@@end\n\n### 3. Chỉ định, ưu – nhược, tác dụng phụ {{Y2 tr.61–62}}\n- **Chỉ định**: chủ yếu giai đoạn tiến xa; đang thử phối hợp hóa/phẫu/xạ trị. Kháng thể đơn dòng dùng trong bạch cầu, gan, phổi, tuyến tiền liệt.\n- {g|Ưu}: đặc hiệu, tác dụng toàn thân, ít tác dụng phụ, thường an toàn.\n- {o|Trở ngại}: phụ thuộc khối bướu và khả năng đáp ứng; biểu hiện gen sinh ung không đồng nhất; bướu tiết yếu tố ức chế miễn dịch.\n- **Tác dụng phụ**: kích ứng da nơi tiêm; cảm cúm (sốt, ớn lạnh, chóng mặt, nôn, đau đầu, nhức mỏi, khó thở); rối loạn nhịp/huyết áp; phù, viêm dị ứng, tắc xoang, tiêu chảy, nhiễm trùng.\n\n### 4. Ứng dụng lâm sàng theo nguồn {{Y2 tr.62–63}}\n| Bệnh | Nội dung theo Y2 |\n|---|---|\n| **NSCLC** | Ức chế PD-1/PD-L1 FDA chấp thuận bước 1 hoặc sau, đơn trị/phối hợp hóa trị |\n| – KEYNOTE-024 | Pembrolizumab vs hóa trị platin: PFS ==10,3 vs 6 tháng== (PD-L1 > 50%) |\n| – CheckMate 026 | Nivolumab: PFS 9,7 vs 5,8 tháng |\n| – KEYNOTE-010 | Pembrolizumab: OS 12,6 vs docetaxel 8,5 tháng |\n| – CheckMate 017/057, OAK | Nivolumab, atezolizumab tốt hơn docetaxel |\n| – KEYNOTE-189 / 407 | Pembro + pemetrexed + carboplatin (không vảy) / pembro + paclitaxel + carboplatin (vảy): cải thiện PFS |\n| **Melanôm ác** | **Ipilimumab** (kháng CTLA-4) FDA **2011**, đáp ứng đến 60%; nivolumab, pembrolizumab (PD-1) 2014 |\n| **Tiêu hóa** | Nói chung không hiệu quả (biến cố ở dạ dày, tụy); **MSI-H** (dạ dày, đại tràng): pembrolizumab bước sau; đại trực tràng tiến triển sau 5-FU, oxaliplatin, irinotecan có thể dùng |\n| **Buồng trứng tái phát** | dMMR/MSI → pembrolizumab; KEYNOTE-158 (233 BN, 27 loại ung thư): 15 BN buồng trứng đáp ứng 33%, 3 đáp ứng hoàn toàn |\n\n> [!warn] Lưu ý ôn thi\n> Y2 mô tả cả liệu pháp cũ (IL-2, IFN) lẫn thuốc chốt miễn dịch; số liệu thử nghiệm (KEYNOTE, CheckMate) chỉ để biết, không phải phác đồ BYT. Chưa có văn bản BYT về miễn dịch trị liệu trong phần tài liệu này; phác đồ cụ thể xem [Ung thư phổi](#/n/ung-thu-phoi/7) và [Ung thư đại–trực tràng](#/n/ung-thu-daitruc-trang/7).\n\n> [!ext] Bổ sung (tham khảo, không phải văn bản BYT; CHƯA tra cứu nguồn gốc, cần kiểm tra lại)\n> Thuốc ức chế chốt miễn dịch có thể gây **tác dụng phụ qua trung gian miễn dịch** (viêm đại tràng, viêm phổi, viêm gan, bệnh nội tiết) cần nhận biết và xử trí sớm. *Nguồn: NCI, Immunotherapy to Treat Cancer, https://www.cancer.gov/about-cancer/treatment/types/immunotherapy*\n\n### Điểm hay thi\n> [!warn] Bẫy thường gặp\n> - Miễn dịch trị liệu là **phương thức thứ 5**.\n> - Vaccine điều trị ≠ vaccine phòng ngừa (HPV, HBV).\n> - Ipilimumab = **CTLA-4** (2011, melanôm); pembrolizumab/nivolumab = **PD-1**; atezolizumab = **PD-L1**.\n> - **MSI-H/dMMR** là dấu ấn dùng pembrolizumab (dạ dày, đại trực tràng, buồng trứng).\n> - IL-2: yếu tố tăng trưởng T, đáp ứng hoàn toàn 4–6% (thận, bạch cầu).\n\n### Tự kiểm tra\n- Miễn dịch trị liệu là phương thức điều trị thứ mấy? :: Thứ năm, sau phẫu thuật, hóa trị, xạ trị, điều trị đích\n- Hai chốt miễn dịch ứng dụng lâm sàng? :: CTLA-4 và PD-1 (PD-L1)\n- Cytokine hay dùng nhất và tác dụng của IL-2? :: IL-2, IFN-α; IL-2 là yếu tố tăng trưởng T, đáp ứng hoàn toàn 4–6% ở thận, bạch cầu\n- Mục đích vaccine điều trị? :: Tạo đáp ứng miễn dịch chủ động chống tế bào ung thư, không ngừa bệnh\n- Ipilimumab đích gì, FDA năm nào? :: Kháng CTLA-4; 2011 (melanôm)\n- Giai đoạn nào hay dùng liệu pháp miễn dịch? :: Chủ yếu giai đoạn tiến xa\n- Nhóm tiêu hóa nào dùng pembrolizumab? :: MSI-H (dạ dày, đại tràng), bước sau\n- Trở ngại của liệu pháp miễn dịch? :: Phụ thuộc khối bướu/đáp ứng, gen không đồng nhất, bướu tiết yếu tố ức chế\n- KEYNOTE-024 so sánh gì, kết quả? :: Pembrolizumab vs hóa trị platin (PD-L1 > 50%): PFS 10,3 vs 6 tháng\n- Cơ chế PD-1/PD-L1? :: PD-1 trên T gắn PD-L1 trên tế bào ung thư làm T bất hoạt; kháng PD-1 chặn tương tác\n- Kể hai nhóm thụ động và chủ động. :: Thụ động: KT đơn dòng, ACT, cytokine; chủ động: vaccine, virus ly giải bướu, ức chế chốt"}, {"kind": "foundation", "disease": "", "short": "Miễn dịch học ung thư", "group": "Giải phẫu bệnh, xâm lấn, di căn, miễn dịch", "section": 0, "order": 4, "khung": [], "id": "ung-thu-mien-dich", "title": "Miễn dịch học ung thư — mối tương quan chủ–bướu", "layer": "nen", "module": "ung-buou", "tags": ["mien-dich", "giam-sat-mien-dich", "hieu-chinh-mien-dich", "thoat-mien-dich", "checkpoint", "treg"], "source": "Y2 tr. 53–58, 63; SY2 tr. 339–393", "body": "> [!key] Ý chính\n> - Hệ miễn dịch vừa **giám sát** vừa **định hình** bướu; thoái triển tự phát hiếm (≈ ==1/100.000==) {{Y2 tr.53}}.\n> - **Hiệu chỉnh miễn dịch (3E)**: Thải loại → Cân bằng → Đào thoát {{Y2 tr.56–58}}.\n> - Tế bào ung thư thoát bằng: mất kháng nguyên/MHC I, né NK–đại thực bào, giết T (Fas-L), kháng bổ thể, **chốt PD-1/PD-L1, CTLA-4**, thu hút **Treg**, viêm mạn.\n> - Ứng dụng điều trị: [[ung-thu-mien-dich-tri-lieu]].\n\n### 1. Hệ miễn dịch chống bướu\n| | Thành phần {{Y2 tr.55}} {{SY2 tr.349–353}} |\n|---|---|\n| **Bẩm sinh** (tuyến đầu) | Tế bào tua gai, **NK**, đại thực bào, bạch cầu trung tính, ái toan, tương bào |\n| **Thích nghi** | Lympho B, **T CD4+** (helper), **T CD8+** (CTL); hoạt hóa qua tế bào trình diện kháng nguyên (APC) |\n- **Chu kỳ miễn dịch chống bướu** {{SY2 tr.352}}: phóng thích kháng nguyên → trình diện + hoạt hóa T (tế bào tua) → T di chuyển đến bướu → thâm nhiễm bướu → nhận diện → giết (→ phóng thích thêm kháng nguyên).\n- Cân bằng chủ–bướu {{SY2 tr.354}}: **ức chế** (chốt ức chế trên T, Treg, đại thực bào) ⇄ **tăng cường** (vaccine, trình diện kháng nguyên, hóa/xạ trị).\n\n> [!tip] Mẹo nhớ\n> T sơ khai cần **2 tín hiệu**: (1) TCR–kháng nguyên/MHC; (2) đồng kích thích **CD28–B7 (CD80/CD86)**. Thiếu tín hiệu 2 → không hoạt hóa {{Y2 tr.56}}.\n\n### 2. Kháng nguyên bướu {{Y2 tr.56}} {{SY2 tr.344–348}}\n- Mỗi ngày > 20.000 tổn thương DNA được sửa; tế bào ác tính có thể > 11.000 đột biến (SY2: 10–500 đột biến làm đổi protein/bướu).\n- **TAA**: sản phẩm gen sinh ung, gen đè nén bướu, protein quá biểu hiện/bất thường; kháng nguyên virus; thay đổi glycolipid/glycoprotein; trình diện cùng MHC.\n\n| Loại | Ví dụ |\n|---|---|\n| Biệt hóa | Melan-A/MART-1, tyrosinase, gp-100 |\n| Đột biến | p53 bất thường |\n| Khuếch đại | HER-2/neu |\n| Kháng nguyên ung thư | MAGE, NY-ESO-1 |\n| Virus | EBV, HPV |\n- Điều kiện nhận diện: đột biến tạo protein lạ; xử lý nội bào + đưa ra màng; T nhận qua **MHC + TCR** nguyên vẹn {{SY2 tr.348}}.\n\n### 3. Giám sát và hiệu chỉnh miễn dịch\n- **Giám sát miễn dịch** (immunosurveillance; Burnet, Thomas): theo dõi liên tục vi sinh vật, tế bào bình thường và tế bào ung thư {{SY2 tr.356}}.\n- Bằng chứng mối tương quan {{SY2 tr.355}}: bướu có nhiều tế bào miễn dịch bao quanh; ung thư tăng ở **suy giảm miễn dịch, ghép tạng, người già**; miễn dịch mạnh có thể thoái lui.\n\n@@tabs\n@@tab 1. Thải loại\n- Miễn dịch bẩm sinh phá bướu; tế bào tua trình diện cho **T CD4+** → hoạt hóa **T CD8+** tiêu diệt.\n- Thành công thì dừng tại đây.\n@@tab 2. Cân bằng\n- Tế bào bị hủy nhiều nhưng dòng **đột biến chống lại tấn công** sống sót; bất ổn di truyền tạo quần thể mới.\n- Bằng chứng ở người: **lây ung thư từ người hiến tạng sang người nhận**.\n- 3 kết cục: bị loại hẳn · duy trì vĩnh viễn trong cân bằng · thoát sang đào thoát. Có thời gian trễ dài trước khi có bệnh lâm sàng.\n@@tab 3. Đào thoát\n- Tế bào sống sót thoát kiểm soát → bướu lớn, phát hiện lâm sàng; do tổn thương trình diện kháng nguyên hoặc hệ quả liệu pháp miễn dịch.\n@@end\n{{Y2 tr.56–58}} {{SY2 tr.357–358}}\n\n### 4. Cơ chế tế bào ung thư thoát miễn dịch {{SY2 tr.359–384}}\n| # | Cơ chế | Chi tiết |\n|---|---|---|\n| 1 | **Giảm kháng nguyên bề mặt** | Biến thể mất kháng nguyên; đột biến/giảm **MHC I** → T không nhận; tiết TGF-β ức chế miễn dịch |\n| 2 | **Né NK + đại thực bào** | NK giết khi **mất MHC I** hoặc có protein stress gắn **NKG2D**; \"ngụy trang\" bằng tiểu cầu. Đại thực bào: **calreticulin = \"eat me\"**, **CD47 = \"don't eat me\"** (ung thư tăng CD47; hồng cầu già giảm CD47 nên bị ăn) |\n| 3 | **Phản công** | **Fas-L** gắn Fas trên T → T chết lập trình; **TGF-β** (ức chế T, gây chết tế bào tua/đại thực bào); **IL-10** bảo vệ khỏi CTL và đại thực bào |\n| 4 | **Kháng nội tại** | mCRPs (**CD46, CD55, CD59**) chống bổ thể; chốt kiểm soát **PD-1/PD-L1, CTLA-4/CD28** làm T bất hoạt |\n| 5 | **Thu hút Treg** | Tiết **CCL22** gắn CCR4 của Treg; TGF-β; Treg (CD25, FOXP3) ức chế T CD4 và CD8 |\n| 6 | **Vi môi trường – viêm** | Viêm cấp (TNF-α, IL-6, IL-8) → viêm mạn gây tổn thương DNA; TGF-β gây **EMT**; IFN-γ, IL-10, IL-17 phá biểu mô, tăng sinh mạch; **CAF** (nguyên bào sợi) tiết yếu tố thúc tăng trưởng, di căn; IDO, PD-L1 |\n- Giải thích vì sao **viêm mạn** (dạ dày, ruột, đường mật) tăng nguy cơ ung thư.\n\n> [!warn] Kết luận của nguồn {{Y2 tr.63}} {{SY2 tr.393}}\n> Cơ thể có giám sát miễn dịch, tế bào ung thư **thoát giám sát và hiệu chỉnh lại** hệ miễn dịch; có thể điều khiển hệ miễn dịch chống bướu đặc hiệu và mạnh → [[ung-thu-mien-dich-tri-lieu]].\n\n@@fold Lịch sử liệu pháp miễn dịch {{Y2 tr.54}}\n- Busch (1868): tiêm hồng cầu → bướu thoái triển; Fehleisen (1882): *Streptococcus pyogenes*; **William Coley (1891)**: vi khuẩn bất hoạt (\"độc tố Coley\") ở sarcôm xương; Old (1959, mô hình chuột) → Morales (1976): **BCG** trong ung thư bàng quang. Coley và Old: \"cha đẻ\" liệu pháp miễn dịch.\n@@end\n\n> [!ext] Bổ sung (tham khảo; CHƯA tra cứu nguồn gốc, cần kiểm tra lại)\n> Khái niệm immunoediting (3E) do Schreiber và cs. hệ thống hóa; chốt miễn dịch PD-1/CTLA-4 là cơ sở giải Nobel Y học 2018 (Allison, Honjo). *Nguồn: NCI Dictionary, nobelprize.org*\n\n### Điểm hay thi\n> [!warn] Bẫy thường gặp\n> - Thứ tự 3E: **thải loại → cân bằng → đào thoát**; bằng chứng người ở cân bằng = lây qua ghép tạng.\n> - NK giết tế bào **mất MHC I**; T cần MHC I (CD8). Mất MHC I → né T nhưng dễ bị NK.\n> - CRT = eat me; CD47 = don't eat me.\n> - Fas-L trên bướu → T chết (bướu \"phản công\"); CCL22–CCR4 → Treg.\n> - Tín hiệu đồng kích thích: **CD28–B7**; chốt ức chế: **CTLA-4, PD-1**.\n\n### Tự kiểm tra\n- Ba giai đoạn hiệu chỉnh miễn dịch? :: Thải loại, cân bằng, đào thoát\n- Bằng chứng ở người cho giai đoạn cân bằng theo Y2? :: Lây ung thư từ người hiến tạng sang người nhận\n- Tín hiệu đồng kích thích để hoạt hóa T sơ khai? :: CD28 trên T gắn B7 (CD80, CD86) trên APC\n- Năm loại kháng nguyên bướu? :: Biệt hóa, đột biến (p53), khuếch đại (HER-2/neu), kháng nguyên ung thư (MAGE, NY-ESO-1), virus (EBV, HPV)\n- NK giết tế bào ung thư khi nào? :: Khi mất MHC I hoặc có protein stress gắn NKG2D\n- CRT và CD47 là gì? :: CRT: \"eat me\"; CD47: \"don't eat me\"\n- Ung thư dùng Fas ligand để làm gì? :: Gắn Fas trên T, gây T chết lập trình\n- Ung thư thu hút Treg thế nào? :: Tiết CCL22 gắn CCR4 của Treg, kèm TGF-β; Treg ức chế CD4, CD8\n- Vì sao viêm mạn tăng nguy cơ ung thư? :: Cytokine tiền viêm gây tổn thương DNA, TGF-β gây EMT, IFN-γ/IL-10/IL-17 phá biểu mô và tăng sinh mạch\n- Ba kết cục của bướu ở giai đoạn cân bằng? :: Bị loại bỏ, duy trì vĩnh viễn trong cân bằng, hoặc thoát sang đào thoát\n- Ba nhóm bệnh nhân ung thư tăng cao gợi ý vai trò miễn dịch? :: Suy giảm miễn dịch, ghép tạng, người lớn tuổi\n- Hai thành phần miễn dịch thích nghi chính? :: Lympho B và lympho T (CD4+ helper, CD8+ CTL)"}, {"kind": "foundation", "disease": "", "short": "Nguyên lý điều trị", "group": "Điều trị và chăm sóc", "section": 2, "order": 1, "khung": [], "id": "ung-thu-nguyen-ly-dieu-tri", "title": "Nguyên lý các mô thức điều trị ung thư", "layer": "dieutri", "module": "ung-buou", "tags": ["điều trị", "phẫu thuật", "xạ trị", "hóa trị", "nội tiết", "điều trị đích", "miễn dịch", "triệt căn", "bổ trợ", "tân bổ trợ", "giảm nhẹ", "đa mô thức"], "source": "Y5 tr.18–23 (ung thư vú, mục 10–13); Y5 tr.116–117 (phổi); Y5 tr.128, 143, 146 (đầu cổ); Y5 tr.207–208 (vòm hầu); Y5 tr.249 (thực quản); Y5 tr.291–292 (đại trực tràng); SY5 tr.269–270, 282–283, 287, 292 (ung thư vú); QĐ1514 tr.PDF 122, 126, 138, 167–168, 193, 212; ĐC Y5 tr.2, 4 (MT4, MT15)", "body": "> [!key] Nguyên lý điều trị ung thư trong một nhìn\n> - Có **6 mô thức** (cách nhóm của bài): phẫu thuật, xạ trị, hóa trị, nội tiết, điều trị đích, miễn dịch; chi tiết ở mục 2\n> - Mục đích: **triệt căn**, **bổ trợ**, **tân bổ trợ**, **giảm nhẹ**. Tại chỗ tại vùng mục tiêu là **khỏi bệnh**; đã di căn xa là **kéo dài sống còn, giữ chất lượng sống** {{SY5 tr.269}}\n> - Nguyên tắc chung là **điều trị đa mô thức**, phối hợp nhiều phương pháp và liên chuyên khoa {{Y5 tr.23}} {{ĐC Y5 tr.4}}\n> - Cá thể hóa theo yếu tố tiên lượng, kinh nguyệt, bệnh kèm và mong muốn bệnh nhân {{SY5 tr.269}}\n\n### Mục tiêu học tập\n- **MT4 (kiến thức)**: Giải thích được nguyên lý của các mô thức điều trị ung thư {{ĐC Y5 tr.2}}\n- Phạm vi bài: mục 1 và nguyên lý ở mục 2 thuộc MT4; chỉ định cụ thể trong mục 2 thuộc **MT5** {{ĐC Y5 tr.2}}; mục 3 thuộc **MT8** {{ĐC Y5 tr.2}}; mục 4 thuộc **MT15** {{ĐC Y5 tr.4}}\n\n### 1. Mục đích điều trị\n\n| Mục đích | Hiểu theo nguồn | Ví dụ |\n|---|---|---|\n| **Triệt căn** | Điều trị nhằm **khỏi bệnh** | Cắt toàn bộ tuyến nước bọt có u ác tính là triệt căn, khỏi được ở giai đoạn sớm {{QĐ1514 tr.PDF 193}}; tại chỗ tại vùng mục tiêu là khỏi bệnh {{Y5 tr.18}} |\n| **Bổ trợ** | Điều trị **sau** khi đã lấy bướu và hạch, diệt di căn vi thể | Hóa trị hỗ trợ là tiêu chuẩn khi bướu lớn hơn 1 cm hoặc có hạch di căn {{Y5 tr.20}}; xạ trị sau đoạn nhũ khi có nguy cơ tái phát {{SY5 tr.283}} |\n| **Tân bổ trợ** | Điều trị **trước** phẫu thuật hoặc trước xạ trị tại chỗ, để hạ giai đoạn | Hóa trị tân hỗ trợ tạo thuận lợi cho bảo tồn hoặc mổ được {{Y5 tr.21}}; xạ trị tân bổ trợ trước phẫu thuật (ung thư xoang mặt) {{QĐ1514 tr.PDF 212}} |\n| **Giảm nhẹ** | Kéo dài sống, giảm triệu chứng, không nhằm khỏi bệnh | Di căn xa: kéo dài sống còn và duy trì chất lượng sống {{Y5 tr.18}}; khi không còn mổ hay hóa xạ trị được thì chăm sóc giảm nhẹ {{QĐ1514 tr.PDF 193}}; đầu cổ tái phát hoặc di căn xa không điều trị triệt để được: hóa trị giảm nhẹ, miễn dịch hoặc chăm sóc giảm nhẹ {{Y5 tr.146}} |\n\n> [!tip] Hai cách gọi cho cùng một nhóm: Y5 dùng **hỗ trợ / tân hỗ trợ**, QĐ1514 dùng **bổ trợ / tân bổ trợ** {{Y5 tr.20}} {{QĐ1514 tr.PDF 212}}\n\n### 2. Sáu mô thức điều trị\n\n@@tabs\n@@tab Phẫu thuật\n- Vai trò chủ yếu trong xử lý **bướu và hạch vùng** ở giai đoạn tại chỗ {{Y5 tr.18}}\n- Nguyên tắc: an toàn về ung thư, đảm bảo thẩm mỹ, hạn chế biến chứng, và **cung cấp dữ liệu cho điều trị tiếp theo** (hóa, xạ, nội tiết) {{SY5 tr.270}}\n- Bảo tồn vú **luôn đi kèm xạ trị**; đoạn nhũ là lựa chọn khi có chống chỉ định bảo tồn {{Y5 tr.18}} {{Y5 tr.19}}\n- Vòm hầu: phẫu thuật không phải điều trị đầu tay, vì vị trí sâu, gần thần kinh và mạch máu {{Y5 tr.207}}\n@@tab Xạ trị\n- Mục tiêu: **giảm tái phát tại chỗ tại vùng**, tăng sống còn, hạn chế biến chứng {{SY5 tr.282}}\n- Sau bảo tồn vú: xạ toàn bộ tuyến vú, có thể tăng cường vào nền bướu {{Y5 tr.20}}\n- Sau đoạn nhũ: khi di căn từ 4 hạch trở lên, bướu T3–T4 hoặc diện cắt dương tính {{SY5 tr.283}}\n- Vòm hầu: xạ trị là mô thức chính quan trọng nhất {{Y5 tr.207}}; vòm mũi họng: phương pháp cơ bản {{QĐ1514 tr.PDF 167}}\n- Di căn xương và di căn não: xạ trị giảm nhẹ {{Y5 tr.23}}\n@@tab Hóa trị\n- Ung thư vú là **bệnh toàn thân**; hóa trị giảm tái phát, giảm di căn, tăng sống còn {{SY5 tr.287}}\n- Mục tiêu: tiêu diệt **di căn vi thể**, tăng sống còn toàn bộ và sống còn không tái phát {{Y5 tr.20}}\n- Ba vai trò: **tân hỗ trợ** (trước mổ), **hỗ trợ** (sau mổ), **triệu chứng** {{SY5 tr.287}}\n- Vòm hầu: hóa xạ trị đồng thời là lựa chọn ở giai đoạn II, thường quy ở giai đoạn III, IVA {{Y5 tr.208}}\n- Phác đồ và liều của từng bệnh: xem [Điều trị ung thư vú](#/n/ung-thu-vu/7)\n@@tab Nội tiết\n- Chỉ định khi bướu có **thụ thể nội tiết dương tính**; không hiệu quả khi thụ thể âm tính {{Y5 tr.20}}\n- Nhóm thuốc: điều hòa chọn lọc thụ thể estrogen (SERM, ví dụ tamoxifen), **ức chế aromatase**, đồng vận GnRH; cắt hoặc ức chế buồng trứng {{Y5 tr.20}} {{SY5 tr.292}}\n- Thời gian điều trị nội tiết: ==5 năm== {{Y5 tr.20}}\n- Vai trò: nội tiết hỗ trợ, nội tiết tân hỗ trợ, nội tiết triệu chứng {{SY5 tr.292}}\n- Bệnh nhân cao tuổi, nhiều bệnh nội khoa nặng, bướu luminal A: có thể nội tiết tân hỗ trợ thay hóa trị {{Y5 tr.21}}\n@@tab Điều trị đích\n- Nhắm vào thụ thể HER2 trên bề mặt tế bào bướu; HER2 quá mức ở **khoảng 20–30%** ung thư vú giai đoạn sớm {{Y5 tr.21}}\n- Trastuzumab (kháng thể đơn dòng gắn HER2) cải thiện sống còn khi phối hợp anthracycline và paclitaxel, ở bệnh nhân hạch nách di căn nguy cơ cao {{Y5 tr.21}}\n- Độc tính trên tim khoảng **2–3%** sau 2 năm khi phối hợp trastuzumab với anthracycline {{Y5 tr.21}}\n- Ung thư vú di căn, ER/PR dương và HER2 âm: ức chế mTOR, ức chế CDK4/6 {{Y5 tr.23}}\n- Phổi không tế bào nhỏ: đột biến EGFR, chuyển vị ALK, tái sắp xếp ROS1 hoặc đột biến NTRK thì nhắm đích {{Y5 tr.117}}\n- U thần kinh đệm ác tính tái phát: bevacizumab {{QĐ1514 tr.PDF 122}}\n@@tab Miễn dịch\n- Cơ chế: tế bào ung thư ngăn tế bào lympho T; kháng PD-1 hoặc kháng PD-L1 giải phóng đáp ứng miễn dịch chống ung thư {{QĐ1514 tr.PDF 138}}\n- Phổi không tế bào nhỏ: củng cố bằng ức chế điểm kiểm soát sau hóa-xạ trị đồng thời nếu bệnh không tiến triển {{Y5 tr.116}}\n- Phổi: điều trị miễn dịch khi PD-L1 **trên 50%** {{Y5 tr.117}}\n- Vòm mũi họng biểu mô vảy tái phát hoặc di căn, PD-L1 dương tính: pembrolizumab {{QĐ1514 tr.PDF 168}}\n- Đầu cổ tái phát, di căn: liệu pháp miễn dịch có thể kéo dài thời gian lui bệnh ở một số trường hợp {{Y5 tr.143}}\n- U thần kinh đệm: còn đang trong giai đoạn thử nghiệm lâm sàng {{QĐ1514 tr.PDF 138}}\n@@end\n\n### 3. Đa mô thức theo giai đoạn\n\nVí dụ chọn mô thức theo giai đoạn trong nguồn là ung thư phổi không tế bào nhỏ:\n\n| Giai đoạn | Hướng điều trị | Nguồn |\n|---|---|---|\n| I | Phẫu thuật; xạ trị nếu không thể hoặc không muốn mổ | {{Y5 tr.116}} |\n| II | Phẫu thuật và hóa trị hỗ trợ; xạ trị nếu không thể mổ | {{Y5 tr.116}} |\n| IIIA | Hóa trị tiền phẫu rồi mổ; nếu không mổ được thì hóa-xạ trị | {{Y5 tr.116}} |\n| IIIB–C | Hóa-xạ trị đồng thời; sau đó có thể củng cố bằng ức chế điểm kiểm soát miễn dịch | {{Y5 tr.116}} |\n| IV | Hóa trị platinum nếu không có đột biến; có đột biến thì nhắm đích; PD-L1 trên 50% thì miễn dịch | {{Y5 tr.116}} {{Y5 tr.117}} |\n\nCác ví dụ khác trong nguồn:\n- Đầu cổ: phối hợp đa mô thức và phục hồi chức năng; giai đoạn III, IVA, IVB thường xạ trị kết hợp hóa trị, ưu tiên bảo tồn chức năng {{Y5 tr.128}} {{Y5 tr.143}}\n- Vòm hầu: xạ trị chính, hóa xạ trị đồng thời là lựa chọn từ giai đoạn II {{Y5 tr.207}} {{Y5 tr.208}}\n- Thực quản: đa mô thức, kết hợp phẫu thuật, xạ trị và điều trị toàn thân {{Y5 tr.249}}\n- Đại trực tràng: điều trị đa mô thức; xạ trị và hóa-xạ trị có vai trò ở bệnh tiến xa tại chỗ {{Y5 tr.291–292}}\n\n### 4. Quan điểm đa mô thức\n\n- **Cá thể hóa** (tailor's therapy): theo yếu tố tiên lượng, theo kinh nguyệt, bệnh kèm và mong muốn bệnh nhân {{SY5 tr.269}}\n- Trước điều trị xác định **M0 hay M1**, phân nhóm sinh học (HER2, thụ thể nội tiết, tam âm), yếu tố tiên lượng và kinh nguyệt {{Y5 tr.18}}\n- Chỉ định xạ trị và toàn thân bổ trợ tùy yếu tố tiên lượng và tiên đoán đáp ứng {{Y5 tr.18}}\n- Phẫu thuật cung cấp dữ liệu cho điều trị tiếp theo (hóa, xạ, nội tiết) {{SY5 tr.270}}\n- Tân hỗ trợ ưu tiên cho HER2 dương tính, tam âm hoặc nhiều hạch di căn, vì nhóm này hưởng lợi nhiều nhất {{Y5 tr.21}}\n- Đáp ứng hoàn toàn về giải phẫu bệnh sau tân hỗ trợ là dấu hiệu tốt cho tiên lượng sống còn {{Y5 tr.21}}\n- Chọn hóa trị theo từng bệnh nhân, cân nhắc độc tính và hiệu quả {{SY5 tr.287}}\n- Đã di căn xa: chọn phương pháp ít độc tính {{Y5 tr.23}}\n- Thai kỳ: phối hợp liên chuyên khoa giữa phẫu thuật, hóa trị, xạ trị, sản khoa, sơ sinh và tâm lý {{Y5 tr.22}}\n\n### Điểm hay thi\n\n> [!warn] Mâu thuẫn khuyến cáo: hóa-xạ trị tiền phẫu ung thư đại trực tràng\n> - Y5 ghi: một số hướng dẫn khuyên hóa-xạ trị tiền phẫu cho **tất cả** bệnh nhân giai đoạn II và III {{Y5 tr.292}}\n> - Cũng theo Y5, ESMO chỉ chọn lọc bệnh nhân dựa trên MRI vùng chậu {{Y5 tr.292}}\n> - Ghi cả hai khuyến cáo; không tự chọn một khi nguồn chưa thống nhất\n\n> [!warn] Nội tiết, đích và miễn dịch phụ thuộc dấu ấn sinh học\n> - Nội tiết không hiệu quả khi thụ thể nội tiết âm tính {{Y5 tr.20}}\n> - Phổi: nhắm đích khi có đột biến; miễn dịch khi PD-L1 trên 50% {{Y5 tr.117}}\n\n> [!warn] Trastuzumab: độc tính tim khi phối hợp anthracycline; có thể gây thiểu ối nên không dùng trong thai kỳ {{Y5 tr.21}} {{Y5 tr.22}}\n\n> [!red] Di căn não: xử lý gấp chèn ép và phù não là ưu tiên hàng đầu, vì đây là nguyên nhân gây tử vong cao {{QĐ1514 tr.PDF 126}}\n\n### Tự kiểm tra\n- Bốn mục đích điều trị ung thư theo bài là gì? :: Triệt căn, bổ trợ, tân bổ trợ, giảm nhẹ.\n- Mục tiêu điều trị ung thư vú tại chỗ tại vùng và khi đã di căn xa? :: Tại chỗ tại vùng là khỏi bệnh; di căn xa là kéo dài sống còn và duy trì chất lượng sống.\n- Hóa trị tân hỗ trợ dùng để làm gì? :: Hạ giai đoạn bướu, tạo điều kiện bảo tồn hoặc mổ được; hạch nách có thể chuyển âm tính.\n- Nội tiết được chỉ định khi nào và trong bao lâu? :: Khi thụ thể nội tiết dương tính; thời gian điều trị 5 năm.\n- Ung thư phổi không tế bào nhỏ giai đoạn IV chọn mô thức theo gì? :: Platinum nếu không có đột biến; nhắm đích nếu có EGFR, ALK, ROS1 hoặc NTRK; miễn dịch nếu PD-L1 trên 50%.\n- Mô thức chính của ung thư vòm hầu là gì? :: Xạ trị; phẫu thuật không phải điều trị đầu tay."}, {"kind": "foundation", "disease": "", "short": "Nguyên nhân vật lý, sinh học, di truyền", "group": "Nguyên nhân", "section": 0, "order": 7, "khung": [], "id": "ung-thu-nguyen-nhan-vat-ly-sinh-hoc-di-truyen", "title": "Nguyên nhân ung thư — tác nhân vật lý, sinh học, di truyền và phòng ngừa", "layer": "nen", "module": "ung-buou", "tags": ["ung thư", "nguyên nhân", "tia UV", "bức xạ ion hóa", "H. pylori", "HBV", "HPV", "di truyền", "Knudson", "FAP", "BRCA", "phòng ngừa"], "source": "Y2 tr. 1, 22–29; SY2 tr. 121–139, 141, 145–148", "body": "> [!key]\n> - **Vật lý**: UV-B → dimer pyrimidine; UV-A → gốc tự do; bức xạ ion hóa → hại DNA trực tiếp/gián tiếp\n> - **Sinh học**: ==17,9%== ung thư liên quan nhiễm trùng (IARC 2002): H. pylori, HBV/HCV, HPV (E6 phá p53, E7 bất hoạt Rb)\n> - **Di truyền**: ==5–10%== (Y2) hoặc ~10% (SY2); mô hình \"2 cú đánh\": Rb, APC (FAP), BRCA1/2\n> - ==30–50%== ung thư có thể phòng ngừa (UICC 2010)\n\nPhần tiếp của [[ung-thu-nguyen-nhan]] (hóa chất, thuốc lá, dinh dưỡng)..\n\n## 1. Tác nhân vật lý\n@@tabs\n@@tab Tia cực tím (UV)\n- Gây ung thư da ở cộng đồng phơi nhiễm cao, nhất là **da trắng** (người Úc gốc Caucasian); đèn tử ngoại, giường tắm nắng nhân tạo cũng gây {{Y2 tr.23}}\n\n| Loại | Bước sóng | Cơ chế |\n|---|---|---|\n| UV-A | 320–400 nm | Không tạo dimer; **oxy hóa** → gốc tự do (peroxide, superoxide, hydroxyl) hại DNA |\n| UV-B | 290–320 nm | Tạo **dimer pyrimidine** và sản phẩm quang học 6-4 → DNA bị bẻ cong, tổng hợp DNA/RNA bất thường |\n| UV-C | 240–290 nm | Phần lớn bị **tầng ozone** hấp thu |\n\n- Y2 ghi UV-B \"290–320 mm\", hiểu là nm\n- Tác động lớp sừng: **urocanic acid** trans → **cis**; dạng cis ức chế miễn dịch (phóng thích cytokine, suy giảm tế bào **Langerhans**)\n- Đột biến gen + ức chế miễn dịch (hiệp đồng) → ung thư da {{Y2 tr.24}} {{SY2 tr.122–125}}\n- Khô da sắc tố (sửa chữa DNA lỗi): [[ung-thu-sua-chua-dna]]\n@@tab Bức xạ ion hóa\n- Tia điện từ (X, gamma), hạt (electron, proton, neutron, alpha) hoặc ion carbon; **bứt electron** khỏi nguyên tử\n- **Trực tiếp**: năng lượng tia hại DNA · **gián tiếp**: oxy hóa nước → gốc tự do (OH) độc cho DNA\n- **Chernobyl (1986)**: iod phóng xạ → tăng ung thư **tuyến giáp** ở trẻ nhỏ, thanh niên\n- **Xạ trị** có thể gây **ung thư thứ hai**, nhất là trẻ em/người trẻ; mô nhạy cảm: {o|tủy xương (bạch cầu), tuyến giáp, vú, phổi} {{Y2 tr.24}}\n@@end\n\n## 2. Tác nhân sinh học\n- IARC 2002: ==17,9%== ung thư người liên quan nhiễm trùng (virút, vi khuẩn, ký sinh trùng) {{Y2 tr.25}}\n\n> [!warn] Nguồn không thống nhất\n> Y2 tr.25: **17,9%** (IARC 2002) nhưng Y2 tr.1 nêu khoảng **20%** cho virút và vi khuẩn. Chọn 17,9% khi hỏi số cụ thể IARC.\n\n@@tabs\n@@tab H. pylori\n- Xoắn khuẩn Gram âm ở niêm mạc dạ dày; **80%** cộng sinh lành tính trong **2/3** dân số thế giới; còn lại viêm loét mạn, một số nhỏ → ung thư dạ dày\n- Độc tố **CagA** và **VacA**: ngoài viêm còn ức chế protein đè nén bướu, ức chế miễn dịch, biến đổi bộ xương TB, ức chế gen sửa DNA → mất ổn định bộ gen\n- Slide xếp nhóm 1 IARC {{Y2 tr.25}} {{SY2 tr.127–128}}\n@@tab HBV, HCV\n| Vùng | Ung thư gan liên quan |\n|---|---|\n| Âu–Mỹ | 60% HCV; 20% HBV và nghiện rượu |\n| Châu Phi, châu Á | 60% HBV; 20% HCV + yếu tố khác (rượu, aflatoxin) |\n\n- Slide: tác nhân gồm HBV, HCV, aflatoxin, rượu, xơ gan, gan đọng sắt; Đông Nam Á, Trung Quốc: HBV 60–90% {{SY2 tr.130}}\n- HBV: DNA hòa nhập bộ gen → NST mất ổn định, rối loạn phân bào/biệt hóa; virút có 7 protein đặc hiệu\n- **HBx**: ức chế p53, sửa DNA, apoptosis; hoạt hóa MAPK, JAK, STAT → kích thích sao chép, phân bào {{Y2 tr.25–26}}\n@@tab HPV\n- Virút DNA không vỏ bao, **>120 type**: 30–40 type vùng hậu môn–sinh dục; 15–20 type **không** sinh ung (HPV 6, 11: mụn cóc); 15–20 type **sinh ung** ({r|HPV 16, 18} quan trọng nhất ung thư cổ tử cung)\n\n| Protein | Chức năng |\n|---|---|\n| **E6** | Phá hủy p53 của ký chủ |\n| **E7** | Bất hoạt Rb của ký chủ |\n| **E2** | Giúp nhân đôi virút; **kiềm chế E6, E7** |\n| L1, L2 | Protein vỏ (chính, phụ) |\n\n- Hòa nhập bộ gen ký chủ → **gen E2 đứt** → E6, E7 tăng → mất p53, Rb {{Y2 tr.26}} {{SY2 tr.132–134}}\n- Bệnh: [Ung thư cổ tử cung](#/n/ung-thu-cotucung/3)\n@@tab Tác nhân khác\n| Tác nhân | Ung thư |\n|---|---|\n| EBV | Lymphôm Burkitt; carcinôm kém biệt hóa khẩu hầu |\n| HTLV1 | Bệnh bạch cầu |\n| HSV8 | Sarcôm Kaposi |\n| HIV | Lymphôm không Hodgkin |\n| Sán máng (Schistosoma) | Ung thư bàng quang |\n\n{{Y2 tr.26}}\n@@end\n\n> [!ext] Bổ sung ngoài tài liệu (diễn đạt lại)\n> IARC xếp H. pylori, HBV, HCV, HPV, EBV, HIV, HTLV-1, HHV-8 và sán máng *S. haematobium* vào **nhóm 1** (chắc chắn gây ung thư ở người). {{+IARC Monographs}} Nguồn: https://monographs.iarc.who.int/agents-classified-by-the-iarc/\n\n## 3. Cơ địa di truyền\n- Khoảng ==5–10%== ung thư (Y2 tr.27) hoặc ~10% (SY2 tr.136)\n- Sinh ra đã mang **1 alen đột biến** ở mọi TB; chỉ cần đột biến alen còn lại (**mất dị hợp tử**) → ung thư\n\n### Giả thuyết \"2 cú đánh\" Knudson (1971)\n- Bằng chứng: **bướu nguyên bào võng mạc**\n- **Di truyền**: cha/mẹ mang Rb đột biến, con ==50%== nhận (cú 1, mọi TB) → cú 2 ngẫu nhiên; bướu thường **<5 tuổi**\n- **Mắc phải (sporadic)**: cú 1 và cú 2 phải trong **cùng một TB** → rất hiếm\n- Chi tiết so sánh 2 thể: [[ung-thu-oncogene-gen-uc-che-u]] {{Y2 tr.27–28}}\n\n> [!warn] Nguồn không thống nhất: tỷ lệ thể di truyền của bướu nguyên bào võng mạc\n> SY2 tr.137: **10–15%**; bài cơ chế ([[ung-thu-oncogene-gen-uc-che-u]], Y2 tr.6, SY2 tr.28): **1/3**. Ghi cả hai, nêu nguồn khi trả lời.\n\n| Hội chứng | Gen, NST | Đặc điểm |\n|---|---|---|\n| Bướu nguyên bào võng mạc | **Rb**, 13q; mất chức năng 2 alen | Trẻ nhỏ; đốm trắng đồng tử (\"mắt mèo\"); soi đáy mắt thấy bướu {{SY2 tr.137}} |\n| **FAP** | **APC**, NST **5** (1 alen di truyền) | 1% ung thư đại tràng; hàng trăm–nghìn polyp; ==100%== thành ung thư; tuổi TB **20–25** {{Y2 tr.28}} {{SY2 tr.139}} |\n| **HBOCS** (vú–buồng trứng) | **BRCA1** 17q21, **BRCA2** 13q12.3 | Vú di truyền <10%, buồng trứng <10%; sửa gãy chuỗi đôi DNA bằng tái tổ hợp đồng dạng {{SY2 tr.138}} |\n| Lynch | Gen sửa chữa lỗi ghép cặp | Xem [[ung-thu-sua-chua-dna]] |\n\n- APC: gen đè nén bướu, ức chế tăng trưởng và gắn kết giữa các TB\n- Ví dụ slide: Angelina Jolie (BRCA1) đoạn nhũ 2 bên rồi cắt 2 buồng trứng dự phòng {{SY2 tr.138}}\n- Bệnh: [Ung thư vú](#/n/ung-thu-vu/3), [Ung thư đại trực tràng](#/n/ung-thu-daitruc-trang/3)\n\n## 4. Điều kiện thuận lợi: viêm mạn, béo phì\n- Viêm **cấp** có lợi (bảo vệ); viêm **kéo dài** → TB, mô tổn thương dễ ác tính hóa\n- Béo phì thúc đẩy viêm mạn\n- Ví dụ: trào ngược dạ dày–thực quản (Barrett) → ung thư thực quản; viêm loét đại tràng mạn; viêm gan {{SY2 tr.141}} {{Y2 tr.22}}\n- Béo phì chi tiết: [[ung-thu-nguyen-nhan]]\n\n## 5. Phòng ngừa (UICC 2010)\n> [!key] \"Ung thư có thể phòng ngừa được\": ==30–50%== ca ngăn được bằng tránh yếu tố nguy cơ {{Y2 tr.28}}\n\n@@fold! Biện pháp cụ thể\n- {g|Không hút thuốc}, hạn chế rượu; tránh béo phì, tập thể dục\n- Vệ sinh răng miệng, sinh dục, quan hệ tình dục an toàn; cắt da quy đầu từ nhỏ nếu hẹp/dài\n- Ăn rau quả tươi, ngũ cốc nhiều xơ, giảm béo; tránh muối, muối chua, mắm, chiên xào quá nóng, nướng, đóng hộp, thực phẩm mốc\n- Bảo hộ lao động (phóng xạ, tia X, UV, hóa chất, bụi gỗ, bụi công nghiệp); không phơi nắng quá mức\n- Nhà nước: quy chế khí thải/chất thải, giảm khí thải giao thông, nước sạch, an toàn thực phẩm, giảm hóa chất nông nghiệp\n- {g|Tiêm ngừa viêm gan B từ sơ sinh; ngừa HPV cho bé gái}\n@@end\n\n- **Ung thư di truyền**: tiên đoán nguy cơ (số người thân mắc, thân trực hệ, tuổi mắc) → tham vấn di truyền, xét nghiệm gen → tầm soát tích cực hoặc dự phòng (lối sống, thuốc, phẫu thuật như cắt đoạn đại tràng phòng ngừa)\n- Xem [[ung-thu-phong-ngua]]\n\n> [!key] Kết luận nguồn\n> Tác nhân sinh ung hoạt hóa oncogen, ức chế gen đè nén bướu, bất hoạt gen sửa DNA, vô hiệu hóa apoptosis. Hầu hết cần phơi nhiễm **lâu dài** + tương tác miễn dịch (trừ phóng xạ tai nạn: cấp tính). Khó quy một ca cho một nguyên nhân duy nhất. Tư vấn nguy cơ di truyền phải chuyên nghiệp để tránh hệ lụy tâm lý xã hội {{Y2 tr.29}} {{SY2 tr.145–147}}\n\n### Điểm hay thi\n> [!warn]\n> - UV-B = dimer pyrimidine; UV-A = gốc tự do; UV-C bị ozone hấp thu\n> - Mô nhạy ung thư thứ hai sau xạ: tủy xương, giáp, vú, phổi\n> - HPV: **E6 → p53**, **E7 → Rb**; E2 đứt → E6, E7 tăng; type 16, 18\n> - HBx ức chế p53; H. pylori: CagA, VacA\n> - FAP: APC, NST 5, 100% ung thư; BRCA1 17q21, BRCA2 13q12.3\n> - Bẫy số: 17,9% vs ~20%; di truyền 5–10% vs ~10%; Rb di truyền 1/3 vs 10–15%\n\n### Tự kiểm tra\n- Tia UV nào tạo dimer pyrimidine, tia nào tạo gốc tự do? :: UV-B tạo dimer pyrimidine; UV-A gây oxy hóa, gốc tự do\n- Mô nhạy cảm với ung thư thứ hai sau xạ trị? :: Tủy xương (bạch cầu), tuyến giáp, vú, phổi\n- Hai độc tố của H. pylori? :: CagA và VacA\n- Protein HBx của HBV làm gì? :: Ức chế p53, sửa DNA, apoptosis; hoạt hóa MAPK, JAK, STAT\n- Vai trò E6, E7 của HPV và type chính gây ung thư cổ tử cung? :: E6 phá p53, E7 bất hoạt Rb; HPV 16, 18\n- Vì sao E6, E7 tăng khi HPV hòa nhập bộ gen? :: Gen E2 (ức chế E6, E7) bị đứt, mất chức năng\n- Phát biểu giả thuyết hai cú đánh và ví dụ? :: Cần đột biến cả 2 alen; bướu nguyên bào võng mạc (Rb)\n- FAP: gen, NST, tỷ lệ chuyển thành ung thư? :: APC, NST 5, 100%\n- BRCA1 và BRCA2 nằm ở đâu, chức năng gì? :: 17q21 và 13q12.3; sửa gãy chuỗi đôi DNA bằng tái tổ hợp đồng dạng\n- Tỷ lệ ung thư liên quan nhiễm trùng theo IARC 2002? :: 17,9%\n- Vắc xin phòng ngừa được nêu? :: Viêm gan B từ sơ sinh; HPV cho bé gái\n- Tỷ lệ ung thư có thể phòng ngừa theo UICC 2010? :: 30–50%"}, {"kind": "foundation", "disease": "", "short": "", "group": "Nguyên nhân", "section": 0, "order": 6, "khung": [], "id": "ung-thu-nguyen-nhan", "title": "Nguyên nhân ung thư — phân loại, hóa chất và lối sống", "layer": "nen", "module": "ung-buou", "tags": ["ung thư", "nguyên nhân", "IARC", "hóa chất sinh ung", "thuốc lá", "rượu", "thực phẩm", "béo phì", "nghề nghiệp"], "source": "Y2 tr. 15–23; SY2 tr. 87–120, 140–144", "body": "> [!key]\n> - Yếu tố **bên ngoài** (môi trường, lối sống) ==70–80%==; bên trong (cơ địa) ==~10%== {{Y2 tr.15}}\n> - IARC xếp nhóm **1, 2A, 2B, 3, 4**; nhóm 1 ≠ mức nguy cơ ngang nhau\n> - Hóa chất: **gây độc gen** (DNA adduct) vs **không gây độc gen** (tăng phân bào, cản apoptosis)\n> - **Thuốc lá** phổ biến nhất; béo phì liên quan 13 loại ung thư (rõ nhất nội mạc tử cung RR 7,1)\n\nPhần vật lý, sinh học, di truyền, phòng ngừa: [[ung-thu-nguyen-nhan-vat-ly-sinh-hoc-di-truyen]]. Cơ chế: [[ung-thu-co-che-sinh-ung]], [[ung-thu-sua-chua-dna]]. Phòng ngừa: [[ung-thu-phong-ngua]].\n\n### 1. Phân loại tác nhân\n- Slide: ngoài môi trường (hóa học, vật lý/bức xạ ion hóa, sinh học: virút, vi khuẩn, ký sinh trùng) · bên trong (di truyền) · **thuận lợi** (béo phì, viêm mạn) {{SY2 tr.89}}\n- Xác định nguyên nhân: dịch tễ mô tả/phân tích · đoàn hệ (có/không tiếp xúc) · thực nghiệm động vật {{SY2 tr.90}}\n- Nguy cơ phụ thuộc thời gian, mức tiếp xúc, tích lũy, hiệp đồng {{SY2 tr.94}}\n\n| IARC | Ý nghĩa |\n|---|---|\n| 1 | Bằng chứng xác thực |\n| 2A | Hầu như chắc chắn gây ung thư |\n| 2B | Có thể |\n| 3 | Không phân loại |\n| 4 | Không thể gây ung thư |\n\n{{Y2 tr.15, 19}} {{SY2 tr.91, 93}}\n> [!warn] Nhóm 1 chỉ nói **mức bằng chứng**, không nói mức nguy cơ: thịt chế biến và thuốc lá đều nhóm 1.\n\n### 2. Các giai đoạn sinh ung (Y2 tr.15–16)\nKhơi mào (DNA adduct, hoạt hóa sinh ung/bất hoạt đè nén) → tổn thương tiền ung (chọn lọc dòng) → tạo thành ung thư (thêm đột biến, xâm lấn, di căn) → ung thư lâm sàng. Bảng chi tiết: [[ung-thu-co-che-sinh-ung]].\n\n### 3. Tác nhân hóa học\n@@tabs\n@@tab Gây độc gen\n- PAH, chất alkyl, amin thơm, amide; vài chất tác động trực tiếp, đa số là **tiền sinh ung** cần chuyển hóa\n- Chất sinh ung gắn cộng hóa trị DNA → **DNA adduct** → liên kết chéo 2 chuỗi, liên kết 2 base lân cận, mất cặp nucleotid; không sửa được → đột biến\n- Ví dụ: **aflatoxin** → cytochrome P450 → epoxide → adduct ở TB gan; **trichloroethylene** → β-lyase ở thận → ung thư thận {{Y2 tr.16–17}} {{SY2 tr.96–98}}\n@@tab Không gây độc gen\n- Không hại trực tiếp DNA; tác động biểu hiện gen, cân bằng nội môi, thụ thể, tăng phân bào, cản apoptosis\n- **Mitogen** (không đủ thời gian sửa đột biến) và **gây độc tế bào** (chết → tái lập dân số → đột biến sau tăng sinh)\n- Cơ chế chưa rõ, khó phát hiện, cần thử trên động vật; slide: viêm, ức chế miễn dịch, hoạt hóa receptor, câm lặng ngoài gen, oxidative stress {{Y2 tr.17}} {{SY2 tr.99–101}}\n@@end\n\n### 4. Tác nhân gặp ở đâu\n| Tác nhân | Điểm chính |\n|---|---|\n| **Thuốc lá** | Phổ biến nhất; >15 loại ung thư. Y2: >4000 hóa chất, 72 chất sinh ung; SY2: ~7000 chất độc hại, ~72 sinh ung. 70% tai mũi họng, 40% bàng quang, 30% tụy (SY2 thêm 90% phổi). Bỏ 5 năm → nguy cơ ung thư phổi giảm 50%. Đột biến G-A, G-T; liên quan KRAS, p53 |\n| Chất nhóm 1 trong khói thuốc | Arsenic, benzene, cadmium, benzo[a]pyrene, chromium, formaldehyde, NNK, nickel, N'-nitrosonornicotine |\n| **Rượu** | Gan, thực quản, hầu họng, thanh quản, vú, ĐTT. Nước phát triển 75% ung thư hầu họng–thực quản do rượu + thuốc lá cộng gộp. **Acetaldehyde** tạo adduct; slide: gen **ALDH2** (aa 478; LL không hoạt tính) liên quan ung thư thực quản |\n| Ô nhiễm không khí | **PM2,5** (<2,5 µm, bằng 1/20 sợi tóc, vào sâu phổi); NO2, SO2, CO, O3, PAH. Hà Nội 2017: 42,6; TP.HCM 29,6; WHO 10 µg/m3. Gãy chuỗi đơn, đột biến p53, methyl hóa gen |\n| Da cam/dioxin | Xác đáng: sarcôm mô mềm, lymphôm Hodgkin và không Hodgkin, CLL; còn hô hấp, tiền liệt, bàng quang, đa u tủy |\n| Thịt đỏ, thịt chế biến | Thịt đỏ nhóm 2 (SY2: 2A); chế biến nhóm 1. 100 g thịt đỏ/ngày +17%; 50 g chế biến/ngày +18% (IARC) |\n| **Nitrosamin** | Muối mặn, muối chua, mắm, jambon, xông khói, xúc xích, lạp xưởng; từ nitrit, nitrat |\n| Phụ gia | Vàng ô (Auramin O) nhuộm da gà, măng tươi (2016), IARC nhóm 1 |\n| **Aflatoxin** | Nấm *Aspergillus flavus* trong ngũ cốc mốc; ung thư gan; bền nhiệt, rửa/chế biến không loại được |\n| Benzo[a]pyrene (PAH) | Đốt cháy không hoàn toàn 300–600 °C; quay, nướng; P-450 → epoxide gắn DNA; thức ăn nướng trực tiếp nhóm 1 (slide) |\n| Thức ăn quá nóng >65 °C | Kích thích nhiệt lặp lại → ung thư thực quản |\n| Nhai trầu, cau, vôi, thuốc lào | Ung thư khoang miệng; arecoline tăng collagen liên kết chéo; tannin, catechin giảm đại thực bào → xơ hóa niêm mạc; thuốc lào có nitrosamin |\n| Nghề nghiệp | 2–8% ung thư (Y2) |\n\n{{Y2 tr.17–21}} {{SY2 tr.102–120}}\n\n@@fold Hóa chất nghề nghiệp (bảng)\n| Tác nhân | Ngành | Ung thư |\n|---|---|---|\n| p-Aminodiphenyl | Hóa chất | Bàng quang |\n| Asbestos | Xây dựng, ma sát | Màng phổi, phúc mạc, phế quản |\n| Arsenic | Khai thác đồng | Da, phế quản, gan |\n| Alkyl | Hóa chất | Phế quản |\n| Benzen | Cao su, hóa dầu | Tủy xương |\n| Benzidine, β-naphthylamine | Dệt, nhuộm | Bàng quang |\n| Nickel | Chiết xuất nickel | Xoang mũi, phế quản |\n| Vinyl clorua (PVC) | Hóa chất | Gan |\n| Bụi gỗ | Xưởng gỗ | Xoang mũi |\n\n- Thêm: nickel, crôm (xi mạ) → phổi; cadmium, vinyl clorua, trichloren, arsen → gan; cao su, thuộc da, in, dệt (aniline) → bàng quang\n- **Amiăng**: gần 50% tử vong ung thư nghề nghiệp; VN còn dùng nhiều (tấm lợp). Slide: benzene không có ngưỡng an toàn; ca đêm liên quan ung thư vú {{Y2 tr.20–21}} {{SY2 tr.112–113}}\n@@end\n\n### 5. Lối sống\n@@tabs\n@@tab Béo phì\n- WHO: thừa cân BMI ==25–29,9==; béo phì ==≥30== kg/m2\n- IARC 2016: liên quan **13 loại** ung thư\n\n| Ung thư | RR |\n|---|---|\n| Nội mạc tử cung | **7,1** |\n| Thực quản (carcinôm tuyến) | 4,8 |\n| Tâm vị dạ dày, gan, thận | 1,8 |\n| Tụy, màng não, đa u tủy | 1,5 |\n| Đại trực tràng, túi mật | 1,3 |\n| Vú hậu mãn kinh, buồng trứng | 1,1 |\n\n- Cơ chế: **viêm mạn** · mỡ tạo thừa **estrogen** (vú, NMTC, buồng trứng) · tăng **insulin, IGF-1** (đại tràng, thận, tiền liệt, NMTC) · adipokine (leptin tăng, adiponectin giảm) · mTOR, AMPK\n- Ung thư không liên quan béo phì thường chịu ảnh hưởng mạnh của thuốc lá {{Y2 tr.21–22}} {{SY2 tr.141–143}}\n@@tab Thể lực\n- Lối sống tĩnh tại tăng nguy cơ **13 loại**; chứng cứ rõ ở vú, đại tràng, NMTC\n- Giảm nguy cơ (nhiều vs ít hoạt động): vú ==12%==, đại tràng ==16%==, NMTC ==20%==\n- Cơ chế: giảm insulin/estrogen/yếu tố tăng trưởng · ngừa béo phì, kháng insulin · giảm viêm · tăng miễn dịch · đổi chuyển hóa acid mật · tăng nhanh lưu thông thức ăn (đại tràng) {{Y2 tr.22–23}}\n@@end\n\n### Điểm hay thi\n> [!warn]\n> - 10% bên trong vs 70–80% bên ngoài; 5 nhóm IARC\n> - Genotoxic (DNA adduct) vs non-genotoxic (mitogen, gây độc TB)\n> - Bỏ thuốc 5 năm giảm 50% nguy cơ phổi; aflatoxin bền nhiệt; nitrosamin trong đồ muối\n> - Béo phì: NMTC 7,1 cao nhất; thể lực giảm vú 12%, đại tràng 16%, NMTC 20%\n> - Số liệu thuốc lá Y2 (>4000/72) khác SY2 (~7000/~72)\n\n### Tự kiểm tra\n- Tỷ lệ ung thư do tác nhân bên trong và do môi trường, lối sống? :: Bên trong ~10%; bên ngoài 70–80%\n- Năm nhóm IARC? :: 1 xác thực, 2A hầu như chắc chắn, 2B có thể, 3 không phân loại, 4 không thể\n- Hóa chất gây độc gen tác động DNA bằng cách nào? :: Tạo DNA adduct (sau chuyển hóa tiền sinh ung thành chất sinh ung)\n- Hóa chất không gây độc gen tác động thế nào? :: Không hại trực tiếp DNA; tăng phân bào, cản apoptosis, ảnh hưởng biểu hiện gen\n- Bỏ thuốc bao lâu giảm 50% nguy cơ ung thư phổi? :: 5 năm\n- Aflatoxin do nấm nào, gây ung thư gì? :: Aspergillus flavus; ung thư gan; bền nhiệt\n- Chất sinh ung trong thực phẩm muối mặn, muối chua, mắm, thịt chế biến? :: Nitrosamin (từ nitrit, nitrat)\n- Ung thư liên quan béo phì mạnh nhất? :: Nội mạc tử cung (RR 7,1)\n- Tập thể lực giảm nguy cơ ung thư nào, bao nhiêu %? :: Vú 12%, đại tràng 16%, NMTC 20%\n- BMI thừa cân và béo phì theo WHO? :: 25–29,9 và ≥30 kg/m2\n- Ngưỡng thức ăn nóng làm tăng nguy cơ ung thư thực quản? :: Trên 65 °C"}, {"kind": "foundation", "disease": "", "short": "Nội soi và lấy bệnh phẩm", "group": "Khái quát cận lâm sàng", "section": 4, "order": 3, "khung": [], "id": "ung-thu-noi-soi-lay-benh-pham", "title": "Nội soi và các thủ thuật lấy bệnh phẩm", "layer": "cls", "module": "ung-buou", "tags": ["nội soi", "sinh thiết", "FNA", "kim lõi", "VABB", "tế bào học", "Pap", "soi cổ tử cung", "khoét chóp", "soi phế quản"], "source": "SY5 tr. 125, 131–133, 147; Y2 tr. 43; Y5 tr. 10–12, 62, 73, 106, 110–111, 272, 287; QĐ3128 tr. 8, 11, 38; QĐ3898 tr. 31–33; QĐ2549 tr. 2–3, 23; QĐ1514 tr.PDF 243–244, 361", "body": "> [!key] Tóm tắt\n> - Mục tiêu: có **bằng chứng mô học/ tế bào học** trước điều trị, lý tưởng là sinh thiết **trước** khi lập kế hoạch {{SY5 tr.132}}; ==mô bệnh học là tiêu chuẩn vàng== {{SY5 tr.131}}\n> - Thủ thuật gồm: **nội soi** (đại trực tràng, phế quản, soi cổ tử cung, soi trung thất…), **sinh thiết** (kềm, kim lõi, VABB, mở, xuyên thành ngực) và **tế bào học** (Pap, FNA, đờm, dịch màng phổi)\n> - Vú: **kim lõi** cho ER, PR, HER2; ở nơi thiếu nhà tế bào học giỏi ưu tiên kim lõi hơn FNA; FNA không phân biệt xâm nhập với tại chỗ {{QĐ3128 tr.11}}\n> - Phổi: FNA không làm được hóa mô miễn dịch; kim lõi hoặc mẫu lớn cho nhiều thông tin hơn {{Y5 tr.106}}\n> - Cổ tử cung: sinh thiết kềm ở **bờ** tổn thương, không cần gây tê; **khoét chóp** vừa chẩn đoán vừa điều trị tại chỗ {{Y5 tr.62, 73}}\n> - Đọc kết quả, hóa mô miễn dịch, sinh thiết lỏng: [[ung-thu-chan-doan-giai-phau-benh]]; cơ sở GPB: [[ung-thu-giai-phau-benh]]\n\n### Nguyên tắc chung (SY5)\n- Phương tiện sinh thiết: **trọn bướu**, **lõi kim (core)**, **kềm bấm qua nội soi** {{SY5 tr.132}}\n- Có tình huống chưa có mô trước mổ, chỉ có **tế bào học** (FNAC, rút dịch); ví dụ FNA hạt giáp ra carcinôm nhú + siêu âm gợi ý → có thể mổ {{SY5 tr.132}}\n- Ngoại lệ không bắt buộc sinh thiết trước: u thần kinh trung ương (GPB sau mổ), một số ung thư trẻ em, **HCC** điển hình (MRI ± AFP ± viêm gan B, C); sinh thiết gan khi hình ảnh/ diễn tiến không điển hình {{SY5 tr.133}}\n- GPB không tương hợp lâm sàng, hình ảnh → xem lại, hội chẩn lại, nghĩ bệnh khác {{SY5 tr.136}}\n- **Khai thác tối đa bệnh phẩm mổ**; nội dung chẩn đoán có thể làm trước, trong hoặc sau mổ {{SY5 tr.147}}\n- Tế bào học: dễ thực hiện nhưng **thường chỉ hữu dụng khi dương tính**; có ích để sàng lọc, hướng dẫn chẩn đoán, xác định nơi di căn {{Y2 tr.43}}\n\n@@tabs\n@@tab Nội soi\n| Thủ thuật | Bệnh | Vai trò | Chỉ định / lưu ý | Nguồn |\n|---|---|---|---|---|\n| **Nội soi đại trực tràng ống mềm** | Đại trực tràng | Vị trí, đặc điểm tổn thương, **sinh thiết**; thấy UT đồng thời (~3%) hoặc polyp | Khi nghi ngờ trên lâm sàng; soi **toàn bộ đến manh tràng** loại trừ UT đồng thời 2–8% | {{Y5 tr.272, 287; QĐ2549 tr.2–3}} |\n| Nội soi đại tràng (sàng lọc, giám sát) | Đại trực tràng | Sàng lọc mỗi ==10 năm== (soi sigma mỗi 5 năm); ưu tiên vì **cắt được polyp**; test khác dương tính → nội soi | Giám sát: trong năm đầu nếu chưa soi đủ; sau đó 3–5 năm/lần đến 75 tuổi | {{SY5 tr.60–62; QĐ2549 tr.23}} |\n| **Soi trực tràng ống cứng** | Trực tràng | Sinh thiết; giới hạn gần–xa so với rìa hậu môn; chu vi; liên quan âm đạo, tiền liệt tuyến, túi cùng phúc mạc | Quyết định khả năng cắt rộng tại chỗ; thăm trực tràng **không đủ** để xếp giai đoạn | {{Y5 tr.287}} |\n| **Nội soi phế quản** (ống mềm) | Phổi, tổn thương trung tâm | Thể sùi, chít hẹp; sinh thiết hoặc chải-rửa chẩn đoán GPB ==97%== | Sinh thiết trực tiếp hoặc xuyên thành phế quản | {{Y5 tr.110; QĐ1514 tr.PDF 243}} |\n| **Soi trung thất**, nội soi lồng ngực | Phổi | Sinh thiết hạch trung thất, bướu trung tâm → xếp giai đoạn; kết hợp PET-CT chính xác hơn | Chuẩn bị mổ | {{Y5 tr.111}} |\n| **Soi cổ tử cung** (Schiller, acid acetic) | Cổ tử cung | Nhìn phóng đại, định hướng sinh thiết; Lugol: vùng không bắt màu nâu → sinh thiết; acid acetic: vùng trắng đục → sinh thiết | Khi Pap ≥ ASC-H, HPV 16/18 (+) hoặc nghi ngờ khi khám | {{Y5 tr.73; QĐ1514 tr.PDF 361}} |\n| Nạo sinh thiết cổ trong | Cổ tử cung | Đánh giá chính xác độ lan rộng | Pap cổ trong bất thường hoặc tổn thương lan lên cổ trong | {{Y5 tr.73}} |\n| **Khoét chóp** | Cổ tử cung | Chẩn đoán CIN 3 hay ung thư tại chỗ; khoét đủ thì điều trị đủ | Phải lấy vùng chuyển tiếp; nếu xâm lấn qua màng đáy → điều trị tiếp | {{Y5 tr.73}} |\n| Soi bàng quang, soi trực tràng | Cổ tử cung | Đánh giá xâm lấn cơ quan kế cận | Nghi xâm lấn (tiểu máu, mót rặn, dò) hoặc giai đoạn IIIB | {{Y5 tr.63}} |\n@@tab Sinh thiết\n#### Vú\n| Kỹ thuật | Đặc điểm | Chỉ định / lưu ý | Nguồn |\n|---|---|---|---|\n| **FNA** | Kim 21–27G, ống tiêm 10–20 ml; nhanh, đơn giản; chính xác ==77–99%== tùy nhà tế bào học | Khối vú, hạch nách; **không** phân biệt tại chỗ/ xâm lấn; không loại trừ ung thư; tin cậy khi **tương hợp** lâm sàng–hình ảnh | {{Y5 tr.11; QĐ3128 tr.8}} |\n| **Sinh thiết kim lõi** | Kim 14–18G, cắt mẫu mô; chính xác cao, hiếm dương giả; âm giả <1% | Khi không tương hợp lâm sàng–hình ảnh; trước hóa trị tân hỗ trợ hoặc đoạn nhũ; cho **ER, PR, HER2** | {{Y5 tr.11; QĐ3128 tr.8}} |\n| **VABB** (hút chân không) | Lấy nhiều mẫu; nhạy 70–100%, đặc hiệu 85–100%; kim 14G + 5 mẫu chính xác ==99%==; kim 8G, 11G chính xác hơn | Dưới hướng dẫn siêu âm, nhũ ảnh hoặc MRI; giá cao | {{Y5 tr.12}} |\n| **Sinh thiết mở** | Trọn bướu (excisional) hoặc một phần (incisional) | Khi FNA/ kim lõi không xác định; bướu nhỏ vị trí khó; bướu quá to thì sinh thiết một phần | {{Y5 tr.12}} |\n| Tổn thương **không sờ thấy** | Định vị dưới siêu âm, nhũ ảnh, MRI: VABB hoặc mổ hở định vị bằng chất màu, **dây kim**, đồng vị phóng xạ | BI-RADS IV trở lên; chụp bệnh phẩm kiểm tra rìa | {{Y5 tr.12; QĐ3128 tr.8}} |\n| Sinh thiết tức thì trong mổ | QĐ3128 chỉ liệt kê | Tài liệu không mô tả thêm | {{QĐ3128 tr.8}} |\n\n@@fold Sinh thiết mở sau kim lõi khi nào?\n1. Không lấy được mẫu có vôi hóa ác tính/ nghi ngờ\n2. Tăng sản không điển hình biểu mô ống tuyến vú (ADH)\n3. Carcinôm tiểu thùy tại chỗ đa dạng (pleomorphic LCIS)\n4. Thiếu tương hợp giữa hình ảnh và mô học\n5. Sẹo tỏa tia (radial scar)\n6. Sang thương dạng nhú\n{{Y5 tr.12}}\n@@end\n- **Tam tương hợp** (lâm sàng, hình ảnh, tế bào học): cùng lành tính → xuất độ ung thư 0–0,6%; cùng ác tính → tới ==99%== {{Y5 tr.11}}\n- Nghi bệnh **Paget**: sinh thiết tổn thương vú (nếu có) + sinh thiết da phức hợp quầng–núm vú, đủ độ sâu {{QĐ3128 tr.8}}\n- Sinh thiết **ổ di căn đầu tiên** (giai đoạn IV) và xét lại ER/PR/HER2; tái phát, di căn nên sinh thiết mỗi khi có thể {{QĐ3128 tr.8, 38}}\n- Sơ đồ QĐ3898: BI-RADS 4–5 → kim lõi hoặc VABB hoặc định vị kim dây; thay đổi da cũng sinh thiết ± da/ núm vú {{QĐ3898 tr.31, 33}}\n- Theo bệnh: [Ung thư vú · 5.3](#/n/ung-thu-vu/5) · [Ung thư vú · 5.4](#/n/ung-thu-vu/6)\n\n#### Cổ tử cung\n- **Kềm bấm** trực tiếp tổn thương; sùi, loét, nhiễm cứng khi khám → sinh thiết **ngay**; lấy mô ở **bờ** tổn thương, tránh vùng hoại tử {{Y5 tr.62}}\n- **Không cần gây tê, gây mê** (vùng không có thần kinh cảm giác đau); chảy máu → nhét gạc; kết quả không phù hợp mà vẫn nghi → **sinh thiết lại** {{Y5 tr.62}}\n- Nếu khối u không rõ: kiểm tra ống cổ tử cung, nạo hoặc hút ống cổ để lấy bệnh phẩm {{QĐ1514 tr.PDF 360}}\n- Theo bệnh: [Ung thư cổ tử cung · 5.3](#/n/ung-thu-cotucung/5) · [Ung thư cổ tử cung · 5.4](#/n/ung-thu-cotucung/6)\n\n#### Phổi\n- **Ngoại vi**: sinh thiết xuyên thành ngực dưới hướng dẫn CT hoặc màn huỳnh quang (FNA hoặc lõi kim), hoặc mở ngực; **trung tâm**: soi phế quản {{Y5 tr.110–111}}\n- FNA qua soi phế quản/ xuyên thành ngực: khó xác định loại mô học, **không** làm được hóa mô miễn dịch; kim lõi hoặc sinh thiết một phần cho nhiều thông tin hơn {{Y5 tr.106}}\n- **Không** sinh thiết được u phổi → sinh thiết hạch thượng đòn hoặc tổn thương di căn + hóa mô miễn dịch xác định nguồn gốc phổi {{QĐ1514 tr.PDF 244}}\n- Nốt phổi đơn độc **tăng kích thước** → sinh thiết (FNA hoặc lõi kim xuyên thành ngực, hoặc mở ngực); tổn thương trung tâm: soi phế quản {{Y5 tr.110}}\n- Theo bệnh: [Ung thư phổi · 5.3](#/n/ung-thu-phoi/5) · [Ung thư phổi · 5.4](#/n/ung-thu-phoi/6)\n\n#### Đại trực tràng\n- Sinh thiết **qua nội soi** là đường chính; mô bệnh học quyết định chẩn đoán {{QĐ2549 tr.3–4}}\n- Sau mổ triệt căn: độ mô học, T, số hạch vét **≥ 12**, diện cắt, xâm lấn thần kinh/mạch; giai đoạn II: MSI hoặc MMR; di căn: KRAS, NRAS, BRAF {{QĐ2549 tr.3}}\n- Theo bệnh: [Ung thư đại trực tràng · 5.3](#/n/ung-thu-daitruc-trang/5) · [Ung thư đại trực tràng · 5.4](#/n/ung-thu-daitruc-trang/6)\n@@tab Tế bào học\n| Phương pháp | Bệnh | Vai trò | Lưu ý | Nguồn |\n|---|---|---|---|---|\n| **Pap** (phết cổ tử cung–âm đạo) | Cổ tử cung | **Sàng lọc** phát hiện tổn thương tiền ung và ung thư sớm; đọc theo **Bethesda** | Không phải chẩn đoán; bất thường (≥ ASC-H) → soi cổ tử cung + sinh thiết | {{Y5 tr.72–73; QĐ1514 tr.PDF 360–361}} |\n| **FNA** khối vú, hạch nách, dịch núm vú | Vú | Tế bào học; hạch nách chọc hút dưới siêu âm trước sinh thiết hạch cửa | Chính xác ==77–99%==; cần nhà tế bào học giỏi | {{Y5 tr.10–11; QĐ3128 tr.8}} |\n| Đờm, dịch màng phổi, dịch rửa phế quản, tế bào hạch thượng đòn | Phổi | Tìm tế bào ung thư | Dùng khi không sinh thiết được u | {{QĐ1514 tr.PDF 244}} |\n| Dịch tràn (màng phổi, bụng), phết âm đạo, dịch phế quản | Chung | Tế bào tróc tự nhiên và chọc hút dịch | Dễ làm, chỉ hữu dụng khi dương tính | {{Y2 tr.43}} |\n@@end\n\n### So sánh FNA và sinh thiết kim lõi (vú)\n| | FNA | Kim lõi |\n|---|---|---|\n| Kim | 21–27G | 14–18G |\n| Mẫu | Tế bào | Mô (đọc bởi bác sĩ giải phẫu bệnh) |\n| ER, PR, HER2 | Tài liệu không nêu | **Có thể làm** |\n| Hạn chế | **Không** phân biệt tại chỗ/ xâm lấn; có âm giả, dương giả | Âm giả <1%; có thể chẩn đoán chưa đúng mức với ADH, tổn thương nhú, sẹo tỏa tia, carcinôm tại chỗ |\n| Nơi thiếu nhà tế bào học | Hạn chế | {g|**Ưu tiên**} |\n{{Y5 tr.11; QĐ3128 tr.11}}\n\n> [!doc] QĐ3128 tr.11 (chẩn đoán xác định ung thư vú)\n> Mô bệnh học có tế bào biểu mô ác tính; sinh thiết kim lõi hoặc FNA đều dùng được; FNA cần nhà giải phẫu bệnh–tế bào có kinh nghiệm và không phân biệt xâm nhập/ không xâm nhập; **nơi không có chuyên gia: nên sinh thiết kim lõi hơn FNA**; kim lõi còn đánh giá thụ thể nội tiết và HER2.\n\n### Chọn thủ thuật theo vị trí bướu (tóm tắt)\n| Vị trí bướu | Thủ thuật thường dùng |\n|---|---|\n| Nhìn/ sờ được (da, vú, cổ tử cung…) | Khám lâm sàng, sinh thiết kềm hoặc kim {{SY5 tr.126, 132}} |\n| Ống tiêu hóa | Nội soi + sinh thiết (kềm bấm qua nội soi) {{SY5 tr.126, 132}} |\n| Phổi ngoại vi / trung tâm | Xuyên thành ngực dưới CT / soi phế quản {{Y5 tr.111}} |\n| Hạch di căn / bướu di căn phát hiện đầu tiên | Khám + cận lâm sàng để truy tìm nguyên phát {{SY5 tr.127}}; sinh thiết hạch/ ổ di căn {{QĐ1514 tr.PDF 244}} |\n| Tổn thương vú không sờ thấy | Sinh thiết định vị (siêu âm, nhũ ảnh, MRI) {{Y5 tr.12}} |\n\n> [!ext] Tài liệu của người dùng (SY5, Y5, QĐ cho 4 bệnh này) **không nêu EBUS** và **không nêu** siêu âm nội soi hướng dẫn sinh thiết; bài này không bổ sung từ nguồn ngoài.\n\n### Điểm hay thi\n> [!warn] Bẫy thường gặp\n> - Chẩn đoán xác định = **mô bệnh học**; tế bào học dễ làm nhưng chỉ hữu dụng khi **dương tính**.\n> - Vú: **FNA** không phân biệt xâm nhập với tại chỗ và không loại trừ ung thư; thiếu nhà tế bào học → **kim lõi** (cho ER/PR/HER2).\n> - Kim lõi 14–18G; FNA 21–27G; VABB chính xác tới ==99%== (kim 14G, 5 mẫu).\n> - Tam tương hợp lành tính: ung thư 0–0,6%; tam tương hợp ác tính: tới 99%; không tương hợp → thêm kim lõi/ mổ.\n> - Cổ tử cung: sinh thiết ở **bờ** tổn thương, tránh hoại tử, **không gây tê**; **khoét chóp** vừa chẩn đoán vừa điều trị (CIN 3/ung thư tại chỗ).\n> - Phổi: soi phế quản chẩn đoán ==97%== tổn thương trung tâm; FNA phổi không làm được hóa mô miễn dịch; không sinh thiết được u → sinh thiết hạch thượng đòn/ di căn.\n> - Đại trực tràng: soi toàn bộ loại trừ UT đồng thời 2–8%; số hạch vét **≥ 12**; HCC là ngoại lệ không bắt buộc sinh thiết khi hình ảnh điển hình.\n> - Sinh thiết mở sau kim lõi: không lấy được vôi hóa, ADH, LCIS đa dạng, không tương hợp, sẹo tỏa tia, tổn thương nhú."}, {"kind": "foundation", "disease": "", "short": "", "group": "Cơ chế", "section": 0, "order": 3, "khung": [], "id": "ung-thu-oncogene-gen-uc-che-u", "title": "Tiền gen sinh ung, gen sinh ung và gen đè nén bướu", "layer": "nen", "module": "ung-buou", "tags": ["ung thư", "oncogene", "RAS", "RET", "Rb", "p53", "gen đè nén bướu", "Knudson", "mất dị hợp tử"], "source": "Y2 tr. 3–7, 78–82; SY2 tr. 15–33, 428–492", "body": "> [!key]\n> - Tiền gen sinh ung (bình thường, lo tăng sinh) → **tăng chức năng** → gen sinh ung = {b|tay ga}\n> - Gen đè nén bướu = {b|tay thắng}: phải **mất cả 2 alen** mới mất chức năng (mất dị hợp tử)\n> - **Rb**: giữ E2F, chặn G1/S; Knudson \"2 cú đánh\" giải thích bướu nguyên bào võng mạc\n> - **p53** \"thần hộ mệnh bộ gen\": dừng chu kỳ, sửa DNA, apoptosis; đột biến >50% ung thư\n\n## 1. Tiền gen sinh ung và gen sinh ung\n- Tiền gen sinh ung có ở TB bình thường, liên quan tăng sinh; đột biến **tăng hoạt động** → gen sinh ung mã hóa protein sinh ung {{Y2 tr.3}} {{SY2 tr.16}}\n- Protein sinh ung có thể là bất kỳ thành phần nào của đường truyền tín hiệu: yếu tố tăng trưởng (EGF, TGF, FGF...), thụ thể, yếu tố dẫn truyền, protein G, thành phần chu kỳ TB, yếu tố sao chép\n\n> [!tip] 4 cơ chế hoạt hóa {{Y2 tr.3}} {{SY2 tr.17}}\n> **Chuyển vị** gen (nằm sau vùng khởi động mới) · **chèn** đoạn gen sinh ung từ virút · **khuếch đại** gen (biểu hiện quá mức) · **đột biến điểm**\n\n@@tabs\n@@tab RAS (dẫn truyền)\n- Ở mặt trong màng, nhận tín hiệu từ thụ thể yếu tố tăng trưởng → nhân\n- Đột biến RAS: ==15–20%== ung thư người; dạng thường gặp: đột biến điểm\n\n| Ung thư | Tỷ lệ đột biến RAS |\n|---|---|\n| Tuyến tụy, đường mật | ~90% |\n| Đại tràng, nội mạc tử cung, tuyến giáp | ~50% |\n| Tuyến phổi, bạch cầu dòng tủy | ~30% |\n\n- RAS-**GDP** = bất hoạt; RAS-**GTP** = hoạt hóa → MAP kinase, RAF-1 → yếu tố sao chép → phân bào\n- Bình thường hoạt hóa **thoáng qua** (GTPase nội sinh thủy phân GTP→GDP); RAS đột biến **mất khả năng thủy phân GTP** → hoạt hóa liên tục {{Y2 tr.4}} {{SY2 tr.18–19}}\n@@tab RET (thụ thể)\n- Thụ thể cho TB thần kinh đệm, giúp sống còn khi phát triển thần kinh; biểu hiện ở TB C cận nang giáp, tủy thượng thận, tiền thân phó giáp\n- **Tăng** chức năng → ung thư\n- **Mất** chức năng → bệnh **Hirschsprung** (phình đại tràng bẩm sinh): đám rối thần kinh ruột không phát triển → táo bón kéo dài, tắc ruột {{Y2 tr.4}} {{SY2 tr.20–21}}\n@@end\n\n## 2. Gen đè nén bướu và mất dị hợp tử\n- Mã hóa protein **kìm hãm phân bào**; tên gọi bị cho là dùng chưa chuẩn (chức năng sinh lý là điều hòa tăng trưởng)\n- Ung thư cần **tăng ga + gỡ thắng**\n- Mỗi gen 2 alen → ==phải bất hoạt cả 2 alen== mới mất chức năng\n- Cách mất: đột biến điểm · mất đoạn DNA (mất cả gen kế cận) · lỗi tách đôi NST → mất cả NST {{Y2 tr.5}} {{SY2 tr.23, 29}}\n- Phát hiện đầu tiên qua **bướu nguyên bào võng mạc** (1/20.000 trẻ): đột biến Rb, **NST 13**\n\n### Gen Rb\n- Rb hoạt hóa: gắn và bất hoạt **E2F** → TB dừng ở G1, không vào S (điểm kiểm soát **G1/S**)\n- Rb bất hoạt: E2F gắn promoter **Cyclin E** → tăng Cyclin E → phức Cdk2–cyclin E → tăng sinh {{Y2 tr.5–6}} {{SY2 tr.24–25}}\n\n### \"2 cú đánh\" của Knudson (1971)\n| Đặc điểm | Thể di truyền | Thể đơn lẻ |\n|---|---|---|\n| Tỷ lệ (Y2, SY2 tr.28) | 1/3 | 2/3 |\n| Cú 1 | Có sẵn từ giao tử, **mọi TB** mang | Xảy ra ở 1 nguyên bào võng mạc |\n| Tuổi | Thường nhũ nhi | 2–5 tuổi |\n| Số mắt | Thường **2 bên** | **1 bên** |\n| Ung thư khác | Sarcôm xương, sarcôm phần mềm, mêlanôm | Không |\n\n{{Y2 tr.6}} {{SY2 tr.26–28}}\n\n> [!warn] Nguồn không thống nhất\n> Tỷ lệ thể di truyền: **1/3** (Y2 tr.6; SY2 tr.28) nhưng slide Nguyên nhân ghi **10–15%** (SY2 tr.137). Y2 tr.27: con người mang đột biến có 50% nhận đột biến, bướu thường trước 5 tuổi. Xem [[ung-thu-nguyen-nhan-vat-ly-sinh-hoc-di-truyen]].\n\n### Phân loại gen đè nén bướu\n- **Gác cổng (gatekeepers)**: Rb/E2F, APC/Beta-catenin; chặn TB qua điểm kiểm soát hoặc đẩy vào apoptosis {{Y2 tr.7}}\n- **Chăm sóc bộ gen (caretakers)**: giữ toàn vẹn bộ gen, sửa lỗi NST/nhân đôi (vd BRCA) {{Y2 tr.7}} {{SY2 tr.30}}\n- Slide gọi nhóm đầu là \"Thúc đẩy (Promoter)\", điều hòa trực tiếp gen sinh ung {{SY2 tr.30}} (khác cách gọi Y2)\n\n## 3. Gen p53\n- Gen đè nén bướu **được biết nhiều nhất**, liên quan ==>50% ung thư==; \"người canh gác/thần hộ mệnh của bộ gen\"\n- Tổn thương sửa được → kéo dài **G1** trước khi vào S; không sửa được → **apoptosis** (cả đường ngoại sinh và nội sinh) {{Y2 tr.7, 81}} {{SY2 tr.31}}\n- Điều hòa: p53 gắn **MDM2** → ubiquitin–proteasome (bán hủy rất ngắn); khi cần tách MDM2 → P21/CIP1 (chu kỳ) hoặc BAX (chết TB) {{Y2 tr.81–82}}\n\n@@fold Cách bất hoạt p53 và đặc điểm đột biến\n- Bất hoạt: đột biến điểm (vô nghĩa) · mất đoạn NST 17 · protein virút gắn và giáng hóa · MDM2 giáng hóa {{Y2 tr.81}} {{SY2 tr.31}}\n- Một trong những gen đột biến nhiều nhất; gần nửa số bệnh nhân ung thư **buồng trứng, đại–trực tràng, đầu–cổ**\n- Mất chức năng chủ yếu ở **exon 5–8**; p53 đột biến bán hủy **dài hơn** và ngăn p53 bình thường {{Y2 tr.82}}\n- Điều trị đang nghiên cứu: phục hồi p53 đột biến hoặc ức chế MDM2 (slide thêm PRIMA-1) {{SY2 tr.484–486}}\n@@end\n\n> [!warn] Một mình KRAS hay một mình p53 chưa đủ gây ung thư; thực tế nhiều gen cùng đột biến {{Y2 tr.82}} {{SY2 tr.487}}\n\nCơ chế apoptosis và p53: [[ung-thu-telomere-chet-te-bao]]. Tyrosine kinase, HER2, EGFR, KRAS: [[ung-thu-sinh-hoc-phan-tu]].\n\n### Điểm hay thi\n> [!warn]\n> - RAS: GTP hoạt hóa; đột biến → **không thủy phân GTP**\n> - RET: tăng chức năng = ung thư; **mất** chức năng = Hirschsprung\n> - Rb → E2F → G1/S; Rb ở **NST 13**\n> - Knudson: thể di truyền thường 2 mắt, nhũ nhi, ung thư khác đi kèm; đơn lẻ 1 mắt, 2–5 tuổi\n> - Gác cổng vs chăm sóc bộ gen; p53 exon 5–8\n\n### Tự kiểm tra\n- Tiền gen sinh ung đột biến theo hướng nào thì thành gen sinh ung? :: Tăng hoạt động (tăng chức năng)\n- Bốn cơ chế hoạt hóa tiền gen sinh ung? :: Chuyển vị, chèn đoạn từ virút, khuếch đại gen, đột biến điểm\n- RAS gắn GDP hay GTP thì hoạt hóa; vì sao RAS đột biến hoạt hóa liên tục? :: GTP; mất khả năng thủy phân GTP\n- Đột biến mất chức năng RET gây bệnh gì? :: Hirschsprung (phình đại tràng bẩm sinh)\n- Vì sao phải bất hoạt cả 2 alen gen đè nén bướu? :: Mỗi gen có 2 bản sao cùng chức năng\n- Rb hoạt hóa kìm hãm TB ở điểm nào, gắn yếu tố gì? :: G1/S; gắn và bất hoạt E2F\n- Thể di truyền vs đơn lẻ của bướu nguyên bào võng mạc? :: Di truyền: thường 2 mắt, nhũ nhi, kèm ung thư khác; đơn lẻ: 1 mắt, 2–5 tuổi, không kèm\n- Hai nhóm gen đè nén bướu theo Y2? :: Gác cổng (Rb/E2F, APC/Beta-catenin) và chăm sóc bộ gen\n- Chức năng bình thường của p53? :: Dừng chu kỳ, tham gia sửa DNA, thúc đẩy apoptosis khi tổn thương không sửa được\n- Đột biến mất chức năng p53 chủ yếu ở exon nào? :: Exon 5–8"}, {"kind": "foundation", "disease": "", "short": "", "group": "Triệu chứng và chẩn đoán chung", "section": 4, "order": 3, "khung": [], "id": "ung-thu-phan-giai-doan-tnm", "title": "Phân giai đoạn ung thư theo TNM (nguyên tắc chung)", "layer": "cls", "module": "ung-buou", "tags": ["TNM", "giai đoạn", "cTNM", "pTNM", "ypTNM", "diện cắt", "R0", "R1", "R2"], "source": "SY5 tr. 137–141; Y2 tr. 34–36; NCI (nguồn ngoài)", "body": "> [!key] Tóm tắt\n> - Giai đoạn do 3 yếu tố: **T** (bướu), **N** (hạch), **M** (di căn xa) {{SY5 tr.137}}\n> - **cTNM** (trước điều trị, chọn phương pháp) ≠ **pTNM** (sau mổ, chọn điều trị bổ trợ + tiên lượng)\n> - Đã xếp hạng thì ==không đổi== dù bệnh tiến triển {{Y2 tr.35}}\n> - Tài liệu **không có** bảng T/N/M chung; mỗi ung thư có bảng riêng\n\n### Ý nghĩa\n- Xếp đúng giai đoạn → kế hoạch điều trị phù hợp; **tiên lượng phụ thuộc giai đoạn** {{SY5 tr.137}}\n- Các trung tâm dùng chung tiêu chuẩn → trao đổi thông tin, hợp tác nghiên cứu toàn cầu\n- Cách đánh giá T, N **khác nhau tùy loại ung thư**\n\n### Lịch sử\n- **1943**: Pierre Denoix (Pháp) đề xướng TNM; sau đó UICC và AJCC cùng dùng\n- **1987**: UICC và AJCC thống nhất xây dựng chung hệ thống TNM {{SY5 tr.138}}\n\n### Định nghĩa T, N, M (Y2)\n| | Ý nghĩa |\n|---|---|\n| **T** | Sự lan rộng của bướu nguyên phát |\n| **N** | Tình trạng hạch lymphô trên vùng/cạnh vùng |\n| **M** | Có hoặc không di căn xa |\n- Theo quy ước, TNM đòi hỏi xác định **bản chất mô học** của bướu\n- Xếp hạng dựa trên nhận định **trước khi quyết định điều trị** (khám, hình ảnh, nội soi, xét nghiệm), không dựa vào mổ thám sát trước đó\n- Bổ sung tiên lượng: độ xâm nhập theo chiều sâu (dạ dày, đại tràng, trực tràng, bàng quang), xâm nhập hạch vi thể, mức lan di căn (pTNM) {{Y2 tr.34–35}}\n\n### Ký hiệu và diện cắt\n@@tabs\n@@tab Tiền tố TNM\n| Ký hiệu | Ý nghĩa |\n|---|---|\n| **cTNM** | Lâm sàng (khám + hình ảnh) |\n| **pTNM** | Sau mổ, có bằng chứng giải phẫu bệnh |\n| **ypTNM** | Sau điều trị tân hỗ trợ (hóa trị hay hóa-xạ trị) |\n| **usTNM** | Đánh giá bằng siêu âm |\n| **rTNM** | Bướu tái phát |\n{{SY5 tr.139}}\n- Y2 giải chữ P của pTNM là \"Post-Operative\"; slide Y5 ghi \"pathological\" {{Y2 tr.35}}\n@@tab Diện cắt R\n| Mức | Ý nghĩa |\n|---|---|\n| **R0** | Diện cắt không có tế bào bướu |\n| **R1** | Còn tế bào bướu trên **vi thể** |\n| **R2** | Diện cắt ngang bướu, thấy **bằng mắt thường** |\n{{SY5 tr.139}}\n@@tab cTNM vs pTNM\n| | cTNM | pTNM |\n|---|---|---|\n| Thời điểm | Trước điều trị | Sau phẫu thuật |\n| Cơ sở | Lâm sàng + cận lâm sàng (vai trò mỗi phương tiện tùy bệnh; vd ung thư trực tràng: nội soi, CT, MRI đánh giá T, N) | Mô tả đại thể của phẫu thuật viên trong mổ + giải phẫu bệnh |\n| Mục đích | Chọn phương pháp điều trị | Chọn điều trị bổ trợ, tiên lượng |\n- Phẫu thuật viên mô tả kỹ bướu/hạch (vị trí, kích thước, mức xâm lấn; vị trí, số lượng, tính chất hạch) và **báo cáo trung thực** đã lấy trọn hay chưa {{SY5 tr.140–141}}\n@@end\n\n### Giai đoạn 0–IV (Y2)\n- Ung thư diễn ra theo trình tự: lan tại chỗ → xâm nhập mạch lymphô → di căn tạng khác\n- Dùng rộng cho cổ tử cung, thân tử cung, buồng trứng (**FIGO**); Hodgkin và NHL (**Ann Arbor**)\n- Giai đoạn 0 chữa lành ~100%; giai đoạn IV tử vong gần 100% (theo Y2)\n\n| GĐ | Mô tả |\n|---|---|\n| 0 | Tại chỗ: không phá màng đáy, không xâm nhập, không lan vùng/di căn xa |\n| I | Bướu nguyên phát nhỏ, không hạch, không di căn xa |\n| II | Ăn lan tại chỗ hơn, xâm nhập hạch tối thiểu |\n| III | Tràn ngập cơ quan và/hoặc hạch quan trọng |\n| IV | Không mổ được do ăn lan quá rộng; có/không hạch vùng; hoặc di căn xa |\n{{Y2 tr.35}}\n\n@@fold Ký hiệu bổ sung và hệ khác (Y2)\n- **G** (độ biệt hóa): G1 rõ; G2 vừa; G3 kém/không biệt hóa; GX không đánh giá được\n- Hạch mô học: N(−)/N(+); sau mổ pN0–pN3\n- Mô tế bào học (vd 4 type Hodgkin: ưu thế lymphô bào, xơ cục, hỗn hợp tế bào, nghèo lymphô bào)\n- **Duke** (1932, 4 nhóm) – **Astler–Coller** (1954, biến đổi) cho đại trực tràng; **Borrmann** (đại thể) cho dạ dày {{Y2 tr.35–36}}\n@@end\n\n> [!warn] Tài liệu chưa có\n> Bảng T1–T4, N1–N3, M0–M1 và nhóm giai đoạn **chung**; phiên bản AJCC/UICC áp dụng chung. Xem bảng riêng từng ung thư, vd ung thư vú (AJCC 8th ở Y5), [Ung thư phổi](#/n/ung-thu-phoi/4).\n\n> [!ext] Bổ sung ngoài tài liệu (NCI, cancer.gov)\n> - T: kích thước/mức lan của bướu chính (TX–T4, số lớn = to/lan rộng hơn); N: số/mức hạch vùng có ung thư (NX–N3); M: M0 không, M1 có di căn xa, MX không đánh giá được {{+NCI}}\n> - Giai đoạn 0 = tế bào bất thường chưa xâm lấn mô lân cận; I–III = bướu to/lan rộng dần; **IV = di căn xa**\n> - Giai đoạn đã gán lúc chẩn đoán **không đổi** dù bệnh tiến triển (khớp Y2)\n> - Một số ung thư (u não, ung thư máu) dùng hệ phân loại khác; hệ thống cho **sổ ghi nhận ung thư**: tại chỗ / khu trú / vùng / xa\n> - Nguồn: https://www.cancer.gov/about-cancer/diagnosis-staging/staging (tóm lược lại bằng lời mình)\n\n### Điểm hay thi\n> [!warn]\n> - T, N, M là gì; 1943 Denoix; 1987 UICC–AJCC thống nhất\n> - cTNM (trước điều trị) vs pTNM (sau mổ); ypTNM sau điều trị tân hỗ trợ; rTNM tái phát; usTNM siêu âm\n> - **R0/R1/R2**: không tế bào / vi thể / đại thể\n> - TNM cần xác định mô học; xếp xong thì không đổi\n> - Giai đoạn 0 = tại chỗ (không phá màng đáy); G1–G3 là độ biệt hóa\n\n### Tự kiểm tra\n- Ba yếu tố quy định giai đoạn? :: T, N, M\n- Ai đề xướng TNM, năm nào? :: Pierre Denoix, 1943\n- Năm UICC và AJCC thống nhất TNM? :: 1987\n- cTNM khác pTNM? :: cTNM trước điều trị (lâm sàng + hình ảnh) để chọn điều trị; pTNM sau mổ có GPB để chọn điều trị bổ trợ và tiên lượng\n- ypTNM? :: Sau điều trị tân hỗ trợ bằng hóa hay hóa-xạ trị\n- rTNM, usTNM? :: Bướu tái phát; đánh giá bằng siêu âm\n- R0, R1, R2? :: Không tế bào bướu; còn tế bào vi thể; ngang bướu thấy bằng mắt\n- Theo quy ước TNM đòi hỏi gì? :: Xác định bản chất mô học của bướu\n- Xếp hạng TNM xong, bệnh tiến triển thì sao? :: Không thay đổi (Y2)\n- Giai đoạn 0 (Y2)? :: Ung thư tại chỗ, không phá màng đáy, không xâm nhập, không lan vùng hay di căn xa\n- G1, G2, G3? :: Biệt hóa rõ, vừa, kém/không biệt hóa\n- Hệ phân loại giai đoạn dùng cho cổ tử cung/buồng trứng và lymphôm? :: FIGO; Ann Arbor"}, {"kind": "foundation", "disease": "", "short": "Phòng ngừa: thuốc, vắc-xin, phẫu thuật", "group": "Phòng ngừa và tầm soát", "section": 0, "order": 7, "khung": [], "id": "ung-thu-phong-ngua-thuoc-vacxin-phau-thuat", "title": "Phòng ngừa ung thư bằng thuốc, vắc-xin và phẫu thuật", "layer": "nen", "module": "ung-buou", "tags": ["phong-ngua", "hoa-phong-ngua", "tamoxifen", "hpv", "vacxin", "phau-thuat-phong-ngua", "brca", "fap"], "source": "Y2 tr. 85, 92–95; SY5 tr. 193–202; QĐ 3898/QĐ-BYT (2025) tr.PDF 16", "body": "> [!key] Ý chính\n> - **Hóa phòng ngừa**: tamoxifen/raloxifen (vú), NSAIDs/aspirin (đại trực tràng).\n> - **Vắc-xin**: HPV (type 16, 18 ≈ 70% ung thư cổ tử cung), HBV (80% ung thư gan nguyên phát).\n> - **Phẫu thuật phòng ngừa** chỉ cho người mang gen **độ thấm cao** (BRCA, FAP, Lynch, CDH1, RET…).\n> - Chưa phổ biến ở Việt Nam, chỉ cho nhóm nguy cơ **đặc biệt** {{Y2 tr.95}}.\n> - Phần chung: [[ung-thu-phong-ngua]].\n\n### 1. Thuốc (hóa phòng ngừa)\n@@tabs\n@@tab Ung thư vú\n- **SERMs**: {p|tamoxifen}, {p|raloxifen} (đồng vận + đối vận thụ thể estrogen) {{Y2 tr.93}} {{SY5 tr.195–196}}.\n- **BCPT**: tamoxifen ↓ ==50%== ung thư vú thụ thể nội tiết (+) ở nữ > 35 tuổi, tiền căn LCIS, Gail 5 năm > 1,66%; {r|tăng ung thư nội mạc tử cung và thuyên tắc mạch}.\n- **STAR** (hậu mãn kinh): tỷ lệ ung thư vú xâm lấn như nhau. Tamoxifen: vấn đề phụ khoa, vận mạch; raloxifen: giảm chức năng tình dục, cơ xương khớp, tăng cân. **FDA chỉ chấp nhận raloxifen cho hậu mãn kinh**; chưa có báo cáo ở người mang BRCA.\n- SY5: nguy cơ cao **tiền mãn kinh** → tamoxifen; **hậu mãn kinh** → raloxifen, anastrozole (kháng aromatase, giảm ung thư vú ER+).\n@@tab Đại trực tràng (NSAIDs)\n- Giảm ung thư tiêu hóa, chủ yếu đại trực tràng; COX2 quá biểu hiện trong polyp tuyến; **COXIB** cho FAP (≥ 18 tuổi).\n- **Aspirin liều thấp**: phòng tim mạch + ung thư đại tràng ở 50–59 tuổi, nguy cơ tim mạch > 10%/10 năm, sống thêm > 10 năm, không nguy cơ chảy máu {{SY5 tr.195, 197}}.\n@@end\n\n> [!doc] QĐ 3898/QĐ-BYT (2025) về tamoxifen {{QĐ3898 tr.16}}\n> Thuốc ức chế aromatase (đã mãn kinh) hoặc tamoxifen (trước/sau mãn kinh) có thể giảm nguy cơ ung thư vú, nhưng tamoxifen liên quan **ung thư nội mạc tử cung, huyết khối, ra máu âm đạo, bốc hỏa** → lợi ích **chưa vượt trội** nguy cơ ở phụ nữ khỏe mạnh. Phù hợp Y2/SY5 (BCPT).\n\n### 2. Vắc-xin\n| | Nội dung |\n|---|---|\n| **HPV** {{Y2 tr.93}} | > 120 type; ≈ 40 type nhiễm sinh dục, môi, họng; nhiễm dai dẳng type sinh ung → ung thư **hậu môn, cổ tử cung, dương vật, âm hộ, âm đạo, hầu họng**; **type 16, 18 ≈ 70%** ung thư cổ tử cung |\n| Loại vaccine | Nhị giá (Cervarix), tứ giá (Gardasil) còn dùng nhiều nước kể cả VN; **Gardasil 9** (6, 11, 16, 18, 31, 33, 45, 52, 58) FDA chấp nhận; Hoa Kỳ ngưng nhị/tứ giá từ 10/2016 |\n| **HBV** {{Y2 tr.93}} | Viêm gan B gây **80%** ung thư gan nguyên phát; vaccine hiệu quả **95%**; tiêm sơ sinh trong TCMR từ **2005** |\n- Lịch tiêm HPV: tài liệu phần này không nêu (xem [Ung thư cổ tử cung](#/n/ung-thu-cotucung/8)).\n\n### 3. Phẫu thuật phòng ngừa {{Y2 tr.93}} {{SY5 tr.198–200}}\n> [!key] Điều kiện để phẫu thuật có lợi\n> Đột biến độ thấm cao · biết rõ diễn tiến tự nhiên · test đột biến **đáng tin cậy** · mổ giảm tối đa nguy cơ · nguy cơ mổ tối thiểu · thay thế được chức năng cơ quan cắt · có theo dõi sau mổ · tư vấn kỹ trước mổ.\n\n| Hội chứng | Gen | Phẫu thuật |\n|---|---|---|\n| Ung thư vú–buồng trứng di truyền (HBOC) | **BRCA1/2** | Đoạn nhũ; cắt 2 phần phụ |\n| Ung thư dạ dày lan tỏa di truyền (HDGC) | **CDH1** | Cắt dạ dày |\n| Đa polyp tuyến gia đình (FAP) | **APC** | Cắt đại tràng |\n| Lynch (HNPCC) | MMR/MSI | Cắt đại tràng |\n| MEN | **RET** | Cắt giáp toàn phần (ung thư giáp tủy) |\n| Tinh hoàn ẩn | — | Đưa tinh hoàn xuống bìu |\n\n@@fold! Đoạn nhũ phòng ngừa {{Y2 tr.93–94}}\n- Cắt **hai bên** ở BRCA: giảm gần ==90%== nguy cơ ung thư vú.\n- Ít được chọn hơn cắt phần phụ (thiếu dữ kiện lợi ích sống còn, lo thẩm mỹ/tình dục, thích tầm soát chặt).\n- QĐ 3898: cắt tuyến vú là lựa chọn thích hợp cho nguy cơ cao (BRCA1/2), cần thảo luận kỹ với chuyên gia tư vấn, phẫu thuật viên, gia đình {{QĐ3898 tr.16}}.\n@@end\n@@fold! Cắt 2 phần phụ phòng ngừa {{Y2 tr.94}}\n- Cho **BRCA1/2, Lynch**; BRCA tiền mãn kinh: ↓ **90–95%** ung thư buồng trứng và **50%** ung thư vú; cải thiện sống còn.\n- Khuyến cáo tuổi **35–40**, sau khi sinh đủ con; cắt cả vòi Fallop; GPB kỹ phát hiện 4–8% ung thư tiềm ẩn.\n- Còn nguy cơ thấp ung thư phúc mạc nguyên phát; hormon thay thế sau mổ còn tranh cãi (ngắn hạn điều trị triệu chứng: báo cáo không tăng nguy cơ, thiếu dữ liệu dài hạn).\n@@end\n@@fold! Cắt đại tràng phòng ngừa (FAP) {{Y2 tr.94}}\n- Hàng trăm nghìn polyp → chắc chắn ung thư nếu không xử trí.\n- Lựa chọn: (1) cắt toàn bộ đại trực tràng + **túi hồi tràng–hậu môn (J-pouch)**; (2) cắt toàn bộ đại tràng, nối hồi–trực tràng; (3) cắt đại trực tràng, mở hậu môn nhân tạo hồi tràng.\n- Giữ trực tràng: nội soi trực tràng thường xuyên; túi hồi tràng: theo dõi mỗi **2 năm**.\n@@end\n\n> [!doc] Thay thế/đi kèm mổ giảm nguy cơ ở người mang BRCA {{QĐ3898 tr.26–28}}\n> Nguy cơ cao: khám lâm sàng 6–12 tháng/lần, X-quang vú + MRI vú hằng năm, cân nhắc tư vấn giảm nguy cơ (cắt tuyến vú, tamoxifen) và tư vấn di truyền → [[ung-thu-tam-soat-nguyen-tac]].\n\n### Điểm hay thi\n> [!warn] Bẫy thường gặp\n> - Tamoxifen: ↑ **ung thư nội mạc tử cung + huyết khối**; FDA chỉ duyệt **raloxifen** cho hậu mãn kinh.\n> - HPV **16, 18 ≈ 70%** cổ tử cung; Gardasil 9 thêm 31, 33, 45, 52, 58.\n> - HBV: **80%** ung thư gan nguyên phát, vaccine 95%, TCMR từ 2005.\n> - Đoạn nhũ 2 bên ↓ ~90%; cắt phần phụ BRCA ↓ 90–95% buồng trứng, 50% vú, làm tuổi **35–40**.\n> - FAP → **APC** → cắt đại tràng; HDGC → **CDH1** → cắt dạ dày; MEN → **RET** → cắt giáp.\n\n### Tự kiểm tra\n- Hai thuốc hóa phòng ngừa ung thư vú trong Y2? :: Tamoxifen và raloxifen (SERMs)\n- Biến cố nặng của tamoxifen? :: Ung thư nội mạc tử cung và thuyên tắc mạch\n- FDA chỉ chấp nhận raloxifen cho đối tượng nào? :: Phụ nữ hậu mãn kinh\n- Type HPV chiếm 70% ung thư cổ tử cung; Gardasil 9 ngừa type nào? :: 16 và 18; Gardasil 9: 6, 11, 16, 18, 31, 33, 45, 52, 58\n- Viêm gan B gây bao nhiêu % ung thư gan nguyên phát? :: 80%\n- Đoạn nhũ phòng ngừa 2 bên giảm nguy cơ ung thư vú bao nhiêu? :: Gần 90%\n- Cắt 2 phần phụ ở BRCA tiền mãn kinh giảm bao nhiêu, tuổi nào? :: ↓ 90–95% buồng trứng, 50% vú; tuổi 35–40, sau khi sinh đủ con\n- Phẫu thuật phòng ngừa cho FAP và HDGC? :: FAP (APC): cắt đại tràng; HDGC (CDH1): cắt dạ dày\n- Điều kiện để phẫu thuật phòng ngừa có lợi? :: Đột biến độ thấm cao, test đáng tin cậy, giảm tối đa nguy cơ, nguy cơ mổ thấp, thay thế được chức năng, theo dõi sau mổ, tư vấn kỹ\n- Nhận định của QĐ 3898 về tamoxifen ở phụ nữ khỏe mạnh? :: Lợi ích chưa vượt trội nguy cơ (ung thư nội mạc, huyết khối, ra máu âm đạo, bốc hỏa)\n- Aspirin liều thấp phòng ung thư đại tràng ở ai? :: 50–59 tuổi, nguy cơ tim mạch > 10%/10 năm, sống > 10 năm, không nguy cơ chảy máu"}, {"kind": "foundation", "disease": "", "short": "Phòng ngừa ung thư", "group": "Phòng ngừa và tầm soát", "section": 0, "order": 6, "khung": [], "id": "ung-thu-phong-ngua", "title": "Phòng ngừa ung thư — các bậc phòng ngừa và yếu tố nguy cơ thay đổi được", "layer": "nen", "module": "ung-buou", "tags": ["phong-ngua", "yeu-to-nguy-co", "thuoc-la", "ruou-bia", "dinh-duong", "beo-phi", "the-thao", "anh-nang", "mpower"], "source": "Y2 tr. 83–92, 95; SY5 tr. 29, 150–193, 203; QĐ 3898/QĐ-BYT (2025) tr.PDF 16", "body": "> [!key] Ý chính\n> - Khoảng ==50%== ung thư phòng được bằng cách tránh yếu tố nguy cơ (WHA lần 17, 2017) {{Y2 tr.83}}; WHO: 1/3 phòng được, 1/3 tầm soát sớm {{SY5 tr.29}}.\n> - 3 bậc: **cấp 1** (tránh nguy cơ, vaccine) · **cấp 2** (tầm soát) · **cấp 3** (sau chẩn đoán).\n> - Nhóm yếu tố thay đổi được: **thuốc lá, rượu bia, dinh dưỡng, béo phì/ít vận động, ánh nắng, nghề nghiệp, môi trường, nhiễm trùng**.\n> - Kết luận: giảm tiếp xúc tác nhân sinh ung là chiến lược dài lâu **kinh tế nhất** {{Y2 tr.95}}.\n> - Phòng bằng thuốc/phẫu thuật: [[ung-thu-phong-ngua-thuoc-vacxin-phau-thuat]]; tầm soát: [[ung-thu-tam-soat-nguyen-tac]].\n\n### 1. Các bậc phòng ngừa {{Y2 tr.83}} {{SY5 tr.152}}\n| Bậc | Nội dung | Ví dụ |\n|---|---|---|\n| **Cấp 1** | Tránh/giảm tiếp xúc tác nhân sinh ung | Cai thuốc lá, ăn hợp lý, vận động, tiêm vaccine |\n| **Cấp 2** | Phát hiện tiền ung/ung thư rất sớm (tiền lâm sàng) | Cắt polyp tuyến qua nội soi, Pap |\n| **Cấp 3** | Sau chẩn đoán: tăng chất lượng sống, kéo dài sự sống | Điều trị hỗ trợ, nhắm đích, chăm sóc giảm nhẹ {{SY5}} |\n\n### 2. Đánh giá yếu tố nguy cơ {{Y2 tr.84–85}} {{SY5 tr.155–160}}\n- Thu thập tiền sử bệnh bản thân, gia đình, nghề nghiệp, lối sống.\n- **Thay đổi được**: hút thuốc, ăn uống, nắng… · **Không thay đổi được**: gen/gia đình, giới, chủng tộc, tuổi, hormon.\n- Trẻ ung thư sống sót: nguy cơ ung thư thứ hai tăng. Sinh ung phụ thuộc thời gian, mức độ, tích lũy, tác động hiệp đồng.\n- IARC nhóm 1 (thịt chế biến, thuốc lá) = **mức bằng chứng**, không có nghĩa nguy cơ tương đương {{SY5 tr.155}}.\n- **Di truyền** ≈ ==10%== ung thư (BRCA1/2…): chỉ xét nghiệm gen khi tiền sử gợi ý + **tư vấn di truyền**; ưu tiên làm trước ở người đã mắc. **Gia đình** 15–20% (chung phơi nhiễm).\n- 3 hướng hoạt động: lối sống · xác định nhóm nguy cơ cao để tầm soát · phòng bằng thuốc {{Y2 tr.85}}.\n\n> [!warn] Mô hình Gail (ung thư vú): ngưỡng nguy cơ cao khác nhau giữa nguồn\n> - Biến số: tuổi, chủng tộc, tuổi có kinh, tuổi sinh con đầu, số người thân ung thư vú, số lần sinh thiết, tăng sản không điển hình. Hạn chế: không tính buồng trứng/họ hàng cấp 2; kém chính xác ở không da trắng {{Y2 tr.85}}.\n> - **SY5**: nguy cơ 5 năm > ==1,66%== = cao {{SY5 tr.158}}.\n> - **QĐ 3898/2025**: 5 năm ≥ ==1,7%== hoặc suốt đời ≥ 20% = nguy cơ cao {{QĐ3898 tr.15–16}}.\n\n> [!doc] QĐ 3898/QĐ-BYT (2025), Hướng dẫn sàng lọc phát hiện sớm ung thư vú — mục \"Dự phòng\" {{QĐ3898 tr.16}}\n> - Khả năng phòng cấp 1 ung thư vú còn **hạn chế** (nhiều yếu tố không đổi được: tuổi, kinh sớm, mãn kinh muộn).\n> - Nên: hạn chế rượu, thuốc lá; **nuôi con bằng sữa mẹ**; tránh béo phì, ăn cân bằng, tập luyện; hạn chế nội tiết thay thế (estrogen + progesteron); không sinh con đầu muộn/không sinh.\n> - Thuốc ức chế aromatase (đã mãn kinh) hoặc tamoxifen có thể giảm nguy cơ, nhưng lợi ích chưa vượt các nguy cơ ở phụ nữ khỏe mạnh; cắt tuyến vú cho nhóm nguy cơ cao (BRCA1/2) sau tư vấn kỹ.\n> - Yếu tố: BRCA1 nguy cơ suốt đời 55–72%, BRCA2 45–69%; rượu +10%; ít vận động +9%; mật độ vú đặc D so A cao gấp 4–6 lần (tr.11–14). Chi tiết: [Ung thư vú](#/n/ung-thu-vu/8).\n\n### 3. Thuốc lá {{Y2 tr.86–87}}\n- **Việt Nam**: cứ 2 nam trưởng thành có 1 người hút (GATS 2015); khoảng 16 triệu người.\n- Gây ≈ 1/3 tử vong ung thư (Hoa Kỳ); phổi hay gặp nhất; còn máu, đầu cổ, thực quản, gan, tụy, dạ dày, tử cung, thận, đại tràng, bàng quang. Khói thuốc **72** chất sinh ung; thuốc lá không khói ≥ 28.\n\n@@tabs\n@@tab MPOWER (WHO)\n- **M**onitor theo dõi · **P**rotect khỏi khói thụ động · **O**ffer hỗ trợ cai · **W**arn cảnh báo tác hại · **E**nforce cấm quảng cáo/khuyến mại/tài trợ · **R**aise tax tăng thuế.\n@@tab Lợi ích cai thuốc\n| Thời gian ngưng | Nguy cơ ung thư phổi |\n|---|---|\n| 10 năm | Giảm còn **một nửa** so với đang hút |\n| > 30 năm | Còn ≈ **10%** |\n- Miệng, hầu họng, thực quản giảm đáng kể; bàng quang, cổ tử cung giảm nhanh sau vài năm.\n@@tab Hỗ trợ cai\n- {p|Thay thế nicotin} (dán, xịt mũi, kẹo, ngậm, hít): tăng gấp đôi tỷ lệ thành công.\n- {p|Bupropion}: tăng gấp đôi khi đơn trị; {r|tránh nếu tiền sử co giật, rối loạn ăn uống}. Tư vấn + bupropion: thành công sau 9 tuần 60% (ĐH Y Dược TPHCM, 2005).\n- {p|Varenicline}: giảm thèm và sảng khoái; {o|thận trọng trầm cảm, ý định tự tử}.\n@@end\n\n### 4. Rượu bia {{Y2 tr.87}} {{SY5 tr.165–167}}\n- **VN 2018**: người > 15 tuổi uống 8,3 lít cồn nguyên chất/năm. Rượu lâu dài ≈ 4% tử vong do ung thư; mỗi ngày uống tăng nguy cơ ung thư 6% ở nữ (đầu cổ, thực quản, trực tràng, gan, vú).\n- **WHO**: nam ≤ ==2 đơn vị==, nữ ≤ ==1 đơn vị==/ngày, uống < 5 ngày/tuần. **1 đơn vị = 10 g cồn** ≈ ¾ lon bia 330 ml 5% ≈ ly vang 100 ml 13,5% ≈ chén rượu mạnh 30 ml 40%.\n- {o|SY5: không có ngưỡng rượu bia nào an toàn.}\n- **Chuyển hóa**: ethanol →(ADH) acetaldehyde →(ALDH2) acetat. ALDH2: GG mạnh, LG trung bình, **LL không hoạt tính** → đỏ mặt, tim nhanh, nôn, nhức đầu, **tăng nguy cơ ung thư thực quản**; 30–40% người châu Á. \"Đỏ mặt sau 1 ly bia 180 ml\": nhạy 90%, đặc hiệu 88%.\n\n### 5. Dinh dưỡng\n> [!key] \"Nguyên tắc số 5\" {{SY5 tr.177}}\n> 1. Rau củ quả **500 g/ngày**, **5 loại**\n> 2. Thịt đỏ ≤ **500 g/tuần**\n> 3. Giảm chế biến nhiệt độ cao\n> 4. Hạn chế béo, mặn, ngọt: muối < 5 g/ngày, đường < 5% năng lượng (25 g/ngày), béo bão hòa < 10%\n> 5. Khẩu phần đa dạng.\n\n> [!warn] Mâu thuẫn số liệu giữa các nguồn\n> - **Muối**: Y2 ≤ ==6 g/ngày== (≈ 1 muỗng cà phê) vs SY5 < ==5 g/ngày==.\n> - **Chất béo tổng**: Y2 20–30% năng lượng vs SY5 (Hoa Kỳ) 20–35%.\n> - **Thịt đỏ**: Quỹ NCUT thế giới ≤ 3 phần/tuần, 340–510 g (Y2) vs 350–500 g (SY5).\n> - **IARC thịt đỏ**: Y2 ghi \"nhóm IIA\" (= 2A); thịt chế biến nhóm I.\n\n@@fold! Chi tiết từng nhóm thực phẩm {{Y2 tr.88–90}} {{SY5 tr.169–175}}\n- **Rau củ quả**: hóa chất thực vật chống oxy hóa; chất xơ phòng ung thư đại tràng (VDD: ≥ 18–20 g/ngày). **Ăn cầu vồng**: đỏ (lycopene, tiền liệt) · vàng–cam (beta-carotene) · trắng (allyl sulfide) · xanh lá (indole, lutein) · xanh dương–tím (anthocyanin). Người Việt chỉ ≈ 250 g rau-quả/ngày (62,5% nhu cầu).\n- **Ngũ cốc nguyên hạt**, gạo lứt; {r|tránh ngũ cốc mốc} (aflatoxin → ung thư gan, không mất khi nấu).\n- **Thịt**: 100 g thịt đỏ/ngày ↑ **17%** nguy cơ đại trực tràng; 50 g thịt chế biến/ngày ↑ **18%** (nitrit, nitrat). Anh: > 90 g/ngày nên giảm còn 70 g; Úc: ≤ 700 g thịt sống hoặc 455 g thịt chín/tuần.\n- **Nhiệt độ cao**: nướng/quay lửa trực tiếp → **PAH, HCA** (HCA từ creatinin–acid amin–đường; PAH từ khói). Nên nấu, luộc, hấp. Giảm HCA: tẩm ướp, cắt mỏng, lật liên tục, bỏ phần cháy, không nướng quá chín (well-done ↑ **3,5 lần** HCA so với medium rare), ăn kèm rau.\n- **Béo/mặn/ngọt**: béo bão hòa ≤ 10%, hạn chế trans-fat; mỗi 5% năng lượng béo bão hòa ↑ 4% tử vong ung thư. **Mặn → ung thư dạ dày** (tăng độc lực HP, tổn thương niêm mạc). **Đường**: chưa có bằng chứng trực tiếp nhưng gây béo phì (↑ nguy cơ **13** loại ung thư); WHO < 10% calorie, tốt nhất < 5%.\n- Không thực phẩm nào phòng hoàn toàn: ăn đa dạng.\n@@end\n\n### 6. Béo phì và vận động {{Y2 tr.90–91}} {{SY5 tr.178–182}}\n- Thừa cân/béo phì: 14% tử vong ung thư ở nam, 20% ở nữ; chiếm 10–40% ung thư **đại trực tràng, nội mạc tử cung, vú hậu mãn kinh, thực quản, thận**. Phẫu thuật giảm cân ↓ ≈ 60% tử vong ung thư.\n- Cơ chế: kháng insulin/tăng insulin, viêm mạn, adipokin (leptin, adiponectin), stress tế bào; vận động cải thiện nhạy insulin, giảm viêm, hormon steroid.\n- Tĩnh tại ≈ 5% tử vong ung thư; **150 phút/tuần** hoạt động vừa phải ↓ 21–25% ung thư vú, đại tràng. Rõ nhất: vú, đại tràng, nội mạc tử cung.\n- **WHO**: người lớn 150–300 phút/tuần trung bình **hoặc** 75–150 phút mạnh + kéo giãn cơ ≥ 2 ngày/tuần; trẻ ≥ 60 phút/ngày. Đứng dậy mỗi 20 phút; xem TV < 7 giờ/tuần.\n\n### 7. Ánh nắng {{Y2 tr.91}} {{SY5 tr.184–186}}\n| Ung thư da | Liên quan nắng |\n|---|---|\n| Carcinôm tế bào **gai** | Phơi nắng **thường xuyên** (lao động ngoài trời) |\n| **Mêlanôm** | Nắng UV mạnh; ×2 nếu tiền sử bỏng nắng |\n| Carcinôm tế bào **đáy** | Phơi nắng **kéo dài, không liên tục** |\n- Tránh nắng **10–16 giờ**, áo dài tay, nón, kính râm; kem chống nắng **SPF > 30**, phổ UVA + UVB, lặp lại mỗi 1,5–2 giờ hoặc sau bơi/đổ mồ hôi; không giường tắm nắng (WHO cấm < 18 tuổi).\n- Kem chống nắng giảm carcinôm gai; không hiệu quả với tế bào đáy; chưa đánh giá với mêlanôm → **tránh nắng vẫn là chủ yếu**.\n\n> [!warn] Mâu thuẫn: thời điểm thoa kem chống nắng\n> Y2: **30 phút** trước khi ra nắng; SY5 tr.185: **15 phút**. Thi theo nguồn đề.\n\n### 8. Hormon thay thế {{Y2 tr.91–92}} {{SY5 tr.189}}\n- Estrogen nội sinh kéo dài (kinh sớm, mãn kinh muộn, không sinh/sinh đầu muộn) ↑ ung thư vú.\n- **WHI**: estrogen **đơn thuần** không tăng nguy cơ ung thư vú (trung vị 7,1 năm); **estrogen + progestin** tăng, còn vài năm sau ngưng; còn tăng đậm độ mô vú (+6% vs 1%), giảm độ nhạy nhũ ảnh.\n\n### 9. Nghề nghiệp, môi trường, nhiễm trùng\n@@tabs\n@@tab Nghề nghiệp\n- **Amiăng** (phổi, trung biểu mô, buồng trứng), **benzo[a]pyrene** (phổi), **amin thơm** (bàng quang). VN là 1 trong 6 nước còn dùng nhiều amiăng (fibro-xi măng); quy hoạch 2020–2030 chấm dứt amiăng trắng {{Y2 tr.92}}.\n- SY5 tr.190–192: phổi (asbestos, diesel, radon, arsenic, chromium, nickel); gan-mật (trichloroethylene, vinyl chloride); da (bức xạ mặt trời, dầu khoáng); vòm hầu (formaldehyde); vú (**làm ca đêm**); leukemia (benzen, formaldehyde). WHO: không có ngưỡng benzene an toàn.\n- Biện pháp: thay chất độc hại → kỹ thuật (che chắn, cách ly) → hành chính → giáo dục lao động.\n@@tab Ô nhiễm môi trường\n- Theo WHO 1/4 ca tử vong liên quan ô nhiễm. **PM2.5** các thành phố lớn VN vượt chuẩn WHO (10 μg/m³); tiêu chuẩn VN 25 μg/m³ {{Y2 tr.88}}.\n- Biện pháp: kiểm soát nguồn, năng lượng sạch, đô thị xanh, phân loại rác, loại thực phẩm bẩn.\n@@tab Bệnh truyền nhiễm\n- ≈ **17%** ung thư liên quan nhiễm trùng: **HPV** (cổ tử cung), **HBV/HCV** (gan), **H. pylori** (dạ dày) {{Y2 tr.92}} {{SY5 tr.193}}.\n- Biện pháp: tình dục an toàn/bao cao su, tiêm HPV/HBV, điều trị triệt để viêm gan B, C, tiệt trừ HP (kháng sinh + PPI), vệ sinh ăn uống.\n@@end\n\n> [!ext] Bổ sung (tham khảo; CHƯA tra cứu nguồn gốc, cần kiểm tra lại)\n> WHO/IARC: khoảng 1/3 ung thư liên quan yếu tố nguy cơ có thể thay đổi (thuốc lá, rượu, dinh dưỡng, ít vận động, nhiễm trùng); IARC xếp thịt chế biến nhóm 1, thịt đỏ nhóm 2A (2015). *Nguồn: WHO Cancer fact sheet; IARC Monographs Vol. 114, https://www.who.int/news-room/fact-sheets/detail/cancer*\n\n### Điểm hay thi\n> [!warn] Bẫy thường gặp\n> - Cấp 1 = tránh nguy cơ/vaccine; cấp 2 = **tầm soát**; cấp 3 = sau chẩn đoán.\n> - Muối **6 g** (Y2) vs **5 g** (SY5); kem chống nắng **30** (Y2) vs **15** phút (SY5).\n> - 1 đơn vị cồn = **10 g**; WHO nam 2, nữ 1 đơn vị/ngày.\n> - Ngưng thuốc lá 10 năm: nguy cơ phổi **còn 1/2**; > 30 năm: **còn 10%**.\n> - Bupropion: tránh khi **co giật/rối loạn ăn uống**; varenicline: thận trọng **trầm cảm, tự sát**.\n> - WHI: **estrogen + progestin** mới tăng ung thư vú (estrogen đơn thuần không).\n> - Di truyền ≈ 10%; gia đình 15–20%. Gail: SY5 > 1,66% vs QĐ 3898 ≥ 1,7% (hoặc suốt đời ≥ 20%).\n\n### Tự kiểm tra\n- Ba bậc phòng ngừa ung thư? :: Cấp 1 tránh nguy cơ/vaccine; cấp 2 tầm soát; cấp 3 sau chẩn đoán (chất lượng sống, kéo dài sống)\n- MPOWER gồm gì? :: Monitor, Protect, Offer, Warn, Enforce, Raise tax\n- Ngưng thuốc lá 10 và > 30 năm: nguy cơ ung thư phổi còn bao nhiêu? :: Một nửa; 10%\n- Một đơn vị cồn tương đương? :: 10 g cồn nguyên chất (≈ ¾ lon bia 330 ml 5%, ly vang 100 ml 13,5%, chén rượu mạnh 30 ml 40%)\n- Giới hạn rượu bia WHO khuyến cáo? :: Nam ≤ 2, nữ ≤ 1 đơn vị/ngày, uống < 5 ngày/tuần\n- Phân loại IARC thịt đỏ và thịt chế biến theo Y2? :: Thịt đỏ nhóm IIA; thịt chế biến nhóm I\n- Mức vận động WHO người lớn? :: 150–300 phút/tuần trung bình hoặc 75–150 phút mạnh\n- Muối khuyến cáo theo Y2 và SY5? :: Y2 ≤ 6 g/ngày; SY5 < 5 g/ngày\n- Liên quan ánh nắng và 3 loại ung thư da? :: Gai: thường xuyên; mêlanôm: UV mạnh/bỏng nắng; đáy: kéo dài không liên tục\n- Hormon thay thế nào tăng ung thư vú (WHI)? :: Estrogen–progestin; estrogen đơn thuần thì không\n- Tỷ lệ ung thư di truyền và gia đình? :: ≈ 10% di truyền (BRCA1/2…); 15–20% gia đình\n- Ngưỡng Gail nguy cơ cao theo QĐ 3898? :: 5 năm ≥ 1,7% hoặc suốt đời ≥ 20%"}, {"kind": "foundation", "disease": "", "short": "Sinh học phân tử ung thư", "group": "Cơ chế", "section": 0, "order": 8, "khung": [], "id": "ung-thu-sinh-hoc-phan-tu", "title": "Sinh học phân tử của bệnh lý ung thư", "layer": "nen", "module": "ung-buou", "tags": ["ung thư", "tyrosine kinase", "EGFR", "HER2", "KRAS", "gen tổ hợp", "BCR-ABL", "EML4-ALK", "p53", "điều trị đích"], "source": "Y2 tr. 78–82; SY2 tr. 428–492", "body": "> [!key]\n> - Hai rối loạn quyết định: **rối loạn tăng sinh** + **rối loạn chết TB theo lập trình**\n> - Bất thường hay gặp nhất: **thụ thể tyrosine kinase** (4 vùng chức năng)\n> - 3 kiểu bất thường gen: **khuếch đại** (HER2), **đột biến** (EGFR, KRAS), **gen tổ hợp** (BCR-ABL, EML4-ALK) + thay đổi ngoài gen\n> - Ung thư là bệnh **nhiều gen**; mỗi kiểu bất thường gợi ý một hướng điều trị đích\n\n## 1. Đại cương\n- **Mục tiêu**: phân tích tương tác phân tử trong đường truyền tín hiệu tăng sinh; xác định bất thường thụ thể tyrosine kinase và protein trung gian; giải thích mất chức năng gen đè nén bướu → rối loạn chết TB {{Y2 tr.78}} {{SY2 tr.429}}\n- Ung thư = hiện tượng **tiến hóa của TB**: tích lũy đột biến → mất kiểm soát tăng sinh và chết lập trình (\"bất tử\"); kèm lẩn tránh ức chế tăng sinh, lẩn miễn dịch, xâm nhập, di căn, tân tạo mạch\n\n## 2. Tăng sinh bình thường và truyền tín hiệu\n- TB bình thường nuôi cấy thiếu tín hiệu từ TB khác sẽ **chết** sau vài chu kỳ\n- Con đường chính: phối tử (ligand) gắn phần ngoại bào thụ thể → đổi cấu hình → hoạt hóa (thường có hoạt tính men) → phân tử trung gian → **yếu tố phiên mã** vào nhân → RNA → protein tăng sinh\n\n@@tabs\n@@tab Tyrosine kinase\n| Vùng | Vai trò |\n|---|---|\n| Ngoại bào | Gắn phối tử (vd EGF gắn EGFR) |\n| Xuyên màng | Qua màng |\n| Cận màng | Giữ thụ thể **không hoạt động** khi chưa có phối tử (slide: điều hòa hoạt động) |\n| Nội bào | Hoạt tính **tyrosine kinase** |\n\n- Chưa gắn ligand: thụ thể đơn độc; gắn ligand → **bắt cặp đôi**, tự phosphoryl hóa tyrosine nội bào → hoạt hóa yếu tố phía dưới → yếu tố phiên mã {{SY2 tr.435–445}}\n@@tab Điều hòa âm, thụ thể khác\n- Điều hòa âm tín hiệu: **PTEN** (slide thêm MKP1); PTEN không hoạt động trong nhiều ung thư → tăng sinh quá mức\n- Thụ thể nhân: vd **estrogen** → ER → tăng sinh biểu mô tuyến vú\n- Slide: thụ thể bề mặt có 3 nhóm (kênh ion, kết hợp protein G, kết hợp men) + thụ thể nội bào cho phân tử nhỏ kỵ nước {{Y2 tr.78–79}}\n@@end\n\n## 3. Các dạng bất thường gen gây rối loạn tăng sinh\n| Dạng | Bản chất | Ví dụ | Điều trị đích (nguồn nêu) |\n|---|---|---|---|\n| **Khuếch đại gen** | Tăng bản sao → tăng mRNA, protein | **HER2** (ERBB2, NST 17) ==~20%== ung thư vú; EGFR (NST 7): đại–trực tràng, đầu–cổ; C-MYC (NST 8): lymphôm, vú | Kháng thể đơn dòng kháng HER2; phát hiện bằng **FISH, IHC** (slide) |\n| **Đột biến gen** (điểm, thêm, mất) | Đổi cấu trúc protein; tiền gen sinh ung → **tăng chức năng** | **EGFR**: ~một nửa BN ung thư phổi không TB nhỏ châu Á, đột biến vùng nội bào → tự hoạt hóa; **KRAS** (NST 12) | **TKI** phân tử nhỏ vào TB, tác động đúng vị trí đột biến |\n| **Gen tổ hợp** (fusion) | 2 gen nối → gen/protein mới hoặc tăng hoạt tính (chuyển vị, đảo đoạn, mất đoạn) | **BCR-ABL** t(9;22): bạch cầu mạn dòng tủy; **EML4-ALK** (đảo đoạn NST 2): ung thư phổi | TKI cho BCR-ABL (slide: imatinib, FDA duyệt) |\n| **Ngoài gen** (epigenetic) | Đổi mức biểu hiện protein | [[ung-thu-bieu-sinh]] | Nguồn này không nêu |\n\n{{Y2 tr.79–80}} {{SY2 tr.447–458}}\n\n@@fold! KRAS\n- Tiền gen sinh ung trên **NST 12**, đột biến tăng chức năng gặp ở hầu hết ung thư với tỷ lệ khác nhau\n- Là phân tử truyền tín hiệu **trung gian**: đột biến → tự hoạt hóa, không phụ thuộc thụ thể bề mặt → {o|kháng liệu pháp bất hoạt thụ thể bề mặt}\n- Thường nhất ở **codon 12 và 13**\n- RAS nói chung: xem [[ung-thu-oncogene-gen-uc-che-u]]\n@@end\n\n@@fold! Gen tổ hợp BCR-ABL, EML4-ALK và các gen khác\n- **BCR-ABL**: ABL (NST 9) bình thường có tyrosine kinase nội bào yếu; chuyển vị 9–22 → BCR làm vùng khởi động → phiên mã ABL mạnh → kích thích truyền tín hiệu → tăng sinh quá mức\n- **EML4-ALK**: tỷ lệ nhỏ ung thư phổi; 2 gen cùng nhánh ngắn NST 2, phiên mã ngược chiều; đảo đoạn → EML4 thành vùng khởi động tăng phiên mã ALK\n- Khác: PML-RARA (bạch cầu cấp dòng tủy), TMPRSS2-ERG (tuyến tiền liệt), CCDC6-RET (tuyến giáp), EWSR1-FLI1 (sarcôm Ewing)\n- Gen tổ hợp có thể là **dấu ấn chẩn đoán xác định** và đích điều trị\n@@end\n\n> [!tip] Chọn hướng ức chế (câu clicker SY2 tr.446, 459; đáp án suy từ nội dung)\n> Chặn phối tử gắn thụ thể chỉ hiệu quả khi **thụ thể biểu hiện quá mức**. Không hiệu quả khi đột biến vùng nội bào, gen tổ hợp hoặc KRAS đột biến (tín hiệu không còn phụ thuộc phối tử).\n\n> [!ext] Bổ sung ngoài tài liệu (diễn đạt lại)\n> NCI xếp các thuốc nhắm đích gồm kháng thể đơn dòng (ngoại bào) và TKI phân tử nhỏ (nội bào); trastuzumab nhắm HER2, imatinib nhắm BCR-ABL. {{+NCI Targeted Therapy}} Nguồn: https://www.cancer.gov/about-cancer/treatment/types/targeted-therapies. Thuốc/liều áp dụng theo văn bản BYT, xem [Ung thư vú](#/n/ung-thu-vu/7), [Ung thư phổi](#/n/ung-thu-phoi/7).\n\n## 4. Rối loạn chết TB theo lập trình\n- Cơ sở (hoại tử vs apoptosis, caspase, Bcl): [[ung-thu-telomere-chet-te-bao]]\n- **Ngoại sinh**: TNFα, FasL, TRAIL → thụ thể → procaspase 8, 10 → caspase 8, 10 → caspase 3, 6, 7\n- **Nội sinh**: BAX, BAK tăng tính thấm ty thể → cytochrome c → caspase 9 → caspase 3, 6, 7\n- Ung thư: đột biến **caspase 3, 8** (dạ dày, phổi, đại tràng); procaspase 3 biểu hiện nhiều nhưng không thành caspase 3 hoạt động ở hầu hết ung thư {{Y2 tr.80–81}}\n- Slide: hoại tử; chết lập trình type I (apoptosis, anoikis); type II (tự tiêu autophagy); mitotic catastrophe {{SY2 tr.462}}\n\n## 5. Gen đè nén bướu p53\n- \"Thần hộ mệnh của bộ gen\": sửa được → kéo dài G1; không sửa được → chết lập trình\n- p53 gắn **MDM2** → ubiquitin–proteasome; điều hòa chu kỳ qua **P21/CIP1**, chết TB qua **BAX**\n- Slide: p53 → p21 → ức chế CDK, G1 arrest; Rb gắn E2F; p53 → BAX, PUMA, NOXA → apoptosis. **p53 đột biến** → mất dừng chu kỳ, sửa DNA, apoptosis; {r|kháng hóa trị} {{SY2 tr.474–479}}\n- Gần nửa ung thư buồng trứng, đại–trực tràng, đầu–cổ; **exon 5–8**; p53 đột biến bán hủy dài, ức chế p53 bình thường\n- Hướng nghiên cứu: phục hồi p53 đột biến; ức chế MDM2 (ức chế tương tác MDM2–p53, adenovirus mã hóa p53, ức chế MDM2 E3 ligase, chất tái hoạt hóa như PRIMA-1) {{SY2 tr.482}}\n- Câu slide: \"đột biến p53 làm giảm hoặc mất chức năng gen\" đúng; không đặc trưng riêng buồng trứng {{SY2 tr.483}}\n- Chi tiết: [[ung-thu-oncogene-gen-uc-che-u]]\n\n## 6. Ung thư là bệnh nhiều gen\n- Khởi phát là quá trình **tích lũy đột biến**; chỉ KRAS hoặc chỉ p53 chưa đủ; khảo sát gen thấy nhiều gen cùng đột biến → điều trị đích phức tạp {{Y2 tr.82}}\n- Phần lớn ung thư **không** di truyền (nguyên nhân di truyền: [[ung-thu-nguyen-nhan-vat-ly-sinh-hoc-di-truyen]])\n- Nghiên cứu phân tử giúp chẩn đoán, tiên lượng, điều trị đích; CA Cancer J Clin 2013 đề xuất phân loại theo đặc điểm phân tử thay vì cơ quan {{SY2 tr.487–491}}\n- Ứng dụng: [[ung-thu-dau-an-sinh-hoc]]\n\n### Điểm hay thi\n> [!warn]\n> - Bốn vùng thụ thể tyrosine kinase; PTEN = điều hòa **âm**\n> - HER2 ~20% ung thư vú, NST 17 → kháng thể đơn dòng; EGFR đột biến → TKI\n> - KRAS: NST 12, codon 12, 13, kháng ức chế thụ thể bề mặt\n> - BCR-ABL (t9;22) CML; EML4-ALK (NST 2) phổi\n> - p53: exon 5–8, bán hủy dài, MDM2; ung thư nhiều gen\n\n### Tự kiểm tra\n- Bốn vùng chức năng của thụ thể tyrosine kinase? :: Ngoại bào (gắn phối tử), xuyên màng, cận màng, nội bào (hoạt tính men)\n- Yếu tố điều hòa âm tín hiệu tăng sinh, ví dụ? :: PTEN\n- HER2 khuếch đại ở bao nhiêu % ung thư vú, NST nào, điều trị? :: ~20%; NST 17; kháng thể đơn dòng\n- Đột biến EGFR ở ung thư phổi không TB nhỏ châu Á và điều trị? :: Khoảng một nửa BN; thụ thể tự hoạt hóa không cần phối tử; dùng TKI\n- KRAS thường đột biến ở codon nào, vì sao kháng liệu pháp ức chế thụ thể bề mặt? :: Codon 12, 13; KRAS tự hoạt hóa, không phụ thuộc thụ thể\n- Gen tổ hợp BCR-ABL hình thành từ đâu, trong bệnh nào? :: Chuyển vị NST 9 và 22; bạch cầu mạn dòng tủy\n- EML4-ALK hình thành thế nào? :: Đảo đoạn nhánh ngắn NST 2, EML4 làm vùng khởi động tăng phiên mã ALK; ung thư phổi\n- Kể gen tổ hợp khác và bệnh? :: PML-RARA (bạch cầu cấp dòng tủy), TMPRSS2-ERG (tuyến tiền liệt), CCDC6-RET (giáp), EWSR1-FLI1 (sarcôm Ewing)\n- Vì sao p53 gọi là thần hộ mệnh của bộ gen? :: Điều khiển chu kỳ, cho sửa DNA hoặc đẩy vào apoptosis khi tổn thương không sửa được\n- P53 đột biến chủ yếu ở exon nào, đặc điểm protein đột biến? :: Exon 5–8; bán hủy dài hơn, ngăn p53 bình thường hoạt động\n- Hai rối loạn quyết định của ung thư? :: Rối loạn tăng sinh và rối loạn chết TB theo lập trình"}, {"kind": "foundation", "disease": "", "short": "", "group": "Cơ chế", "section": 0, "order": 2, "khung": [], "id": "ung-thu-sua-chua-dna", "title": "Tổn thương DNA và các cơ chế sửa chữa", "layer": "nen", "module": "ung-buou", "tags": ["ung thư", "tổn thương DNA", "đột biến", "sửa chữa DNA", "MMR", "hội chứng Lynch", "khô da sắc tố", "BRCA"], "source": "Y2 tr. 1–3; SY2 tr. 5–14", "body": "> [!key]\n> - Tổn thương DNA **không tránh khỏi**: khoảng ==10^4–10^6 tổn thương/ngày== {{Y2 tr.2}}\n> - Có hệ thống sửa chữa riêng cho từng loại tổn thương; hỏng sửa chữa → đột biến tích lũy → bệnh\n> - Gãy 2 nhánh: **HR (BRCA1/2)** hoặc NHEJ; bắt cặp sai: **MMR (MLH1, MSH2)**; UV: **NER**\n> - Lỗi sửa chữa → hội chứng Lynch (MMR), khô da sắc tố (NER), ung thư vú–buồng trứng (BRCA)\n\nThuộc nhóm cơ chế sinh ung: [[ung-thu-co-che-sinh-ung]]. Nhóm gen khác: [[ung-thu-oncogene-gen-uc-che-u]]. Tác nhân: [[ung-thu-nguyen-nhan]].\n\n### Nguyên nhân tổn thương DNA {{Y2 tr.1–2}}\n- Sai sót khi nhân đôi · sản phẩm chuyển hóa của cơ thể\n- Tác nhân ngoài: **vật lý** (tia X, UV) · **hóa học** (khói thuốc lá, nitrosamine trong muối chua, mắm) · **sinh học** (virút, vi khuẩn)\n- Virút/vi khuẩn liên quan ==~20%== ung thư: HBV, HCV (gan); HPV (cổ tử cung, hậu môn); xoắn khuẩn môn vị (dạ dày)\n\n### Phân loại đột biến gen\n| Theo | Các loại |\n|---|---|\n| Cấu trúc | **Thêm** nucleotide (bảo tồn / lệch khung) · **mất** (bảo tồn / lệch khung) · **thay** (im lặng, sai nghĩa, vô nghĩa) · phức tạp |\n| Chức năng | Tăng chức năng · mất chức năng |\n| Biến cố (slide) | Mất/thêm/thay nucleotide; mất đoạn, đảo đoạn, chuyển vị, nhân đoạn, thay đoạn |\n\n{{SY2 tr.7–8}} {{Y2 tr.2}}\n- Hậu quả: tích lũy → protein sai chức năng → bệnh; đột biến ở **tế bào mầm** có thể di truyền\n- Ví dụ slide: bệnh lão nhi (progeria) – gen lặn, đột biến điểm **LMNA**, lão hóa sớm {{SY2 tr.9}}\n\n### Các cơ chế sửa chữa\nNguyên tắc: sửa bazơ đơn giản, hoặc **cắt đoạn hỏng rồi lấy nhánh đối diện làm khuôn** (bổ sung) {{Y2 tr.2}} {{SY2 tr.10}}\n\n| Tác nhân | Tổn thương | Cơ chế sửa | Protein | Bệnh liên quan |\n|---|---|---|---|---|\n| Thuốc alkyl hóa | Alkyl hóa bazơ nitơ | Đảo ngược trực tiếp | MGMT | Bướu thần kinh đệm |\n| Tia X, gốc oxy hóa | Gãy 1 nhánh | SSBR; cắt bazơ (BER) | PARP1 | Slide không ghi bệnh riêng |\n| Tia cực tím | Liên kết đôi giữa các pyrimidine | Cắt nucleotide (**NER**) | ERCC1, ERCC4 | Khô da sắc tố |\n| Sai sót nhân đôi | Bắt cặp sai; thêm/mất bazơ | Sửa bắt cặp sai (**MMR**) | MLH1, MSH2 | Ung thư đại tràng |\n| Tia X, UV, thuốc chống bướu | Liên kết chéo 2 nhánh; gãy 2 nhánh | **DSBR**: tái tổ hợp đồng nhất (HR), nối tận không đồng nhất (NHEJ) | HR: BRCA1, BRCA2; NHEJ: KU70/80, DNA-PK | Ung thư vú, buồng trứng |\n\n{{SY2 tr.11}} (đọc từ ảnh trang)\n\n### Hai bệnh ví dụ\n@@tabs\n@@tab Hội chứng Lynch\n- Ung thư đại trực tràng di truyền **không polyp**: ==2–5%== UTĐTT {{Y2 tr.3}}\n- Gen **trội**; mất chức năng MMR: **MSH2, MSH6, MLH1, PMS2**\n- Còn gây ung thư nội mạc tử cung, dạ dày, ruột non, tụy, tuyến tiền liệt, da...\n- MMR bình thường: MSH6/MSH2 dò DNA, thấy bắt cặp sai (vd A–C) → huy động MLH1, PMS2 → tháo xoắn, cắt đoạn sai → polymerase tổng hợp theo nhánh đối diện → ligase nối {{SY2 tr.12}}\n@@tab Khô da sắc tố\n- Hiếm: ==1/250.000== trẻ (Mỹ); gen **lặn**\n- Mất chức năng protein sửa tổn thương do UV/ánh nắng (NER)\n- Dễ ung thư da: carcinôm tế bào đáy, tế bào gai, mêlanôm {{SY2 tr.13}}\n@@end\n\n> [!tip] Nhớ nhanh\n> UV → **NER** → khô da sắc tố · bắt cặp sai → **MMR** → Lynch · gãy 2 nhánh → **HR/BRCA** → vú, buồng trứng ([Ung thư vú](#/n/ung-thu-vu/3))\n\n### Tóm tắt nhóm gen (SY2 tr.14)\n- Sửa chữa DNA: mất chức năng · Sinh ung: tăng · Đè nén bướu: mất · Apoptosis: tăng hoặc mất. Xem [[ung-thu-telomere-chet-te-bao]].\n\n### Điểm hay thi\n> [!warn]\n> - Ghép đúng **tác nhân – cơ chế – protein – bệnh** (bảng trên)\n> - Lynch: gen **trội**, 2–5% UTĐTT, thiếu MMR; khô da sắc tố: gen **lặn**\n> - HR liên quan BRCA1/2; NHEJ liên quan KU70/80, DNA-PK\n> - Cột \"gãy 1 nhánh\" ở slide không gán bệnh rõ ràng, đừng tự gán\n\n### Tự kiểm tra\n- Mỗi ngày cơ thể có khoảng bao nhiêu tổn thương DNA? :: Khoảng 10^4 đến 10^6\n- Đột biến theo chức năng gồm những loại nào? :: Tăng chức năng và mất chức năng\n- Cơ chế nào xử lý bắt cặp sai khi nhân đôi, protein nào? :: MMR; MSH2, MSH6, MLH1, PMS2\n- Hội chứng Lynch chiếm bao nhiêu % UTĐTT, kiểu di truyền? :: 2–5%; gen trội\n- Tổn thương do UV được sửa bằng gì, thiếu gây bệnh gì? :: NER (ERCC1, ERCC4); khô da sắc tố\n- Sửa gãy 2 nhánh gồm hai cơ chế nào, protein nào gắn ung thư vú, buồng trứng? :: HR và NHEJ; BRCA1, BRCA2 (HR)\n- Khô da sắc tố di truyền kiểu nào, tần suất? :: Gen lặn; 1/250.000 trẻ (Mỹ)\n- MGMT sửa tổn thương gì, bệnh liên quan ở slide? :: Alkyl hóa bazơ nitơ (đảo ngược trực tiếp); bướu thần kinh đệm\n- Progeria: gen và kiểu di truyền? :: LMNA, đột biến điểm, gen lặn"}, {"kind": "foundation", "disease": "", "short": "Nguyên tắc tầm soát ung thư", "group": "Phòng ngừa và tầm soát", "section": 0, "order": 8, "khung": [], "id": "ung-thu-tam-soat-nguyen-tac", "title": "Tầm soát ung thư — nguyên tắc và khuyến cáo (cổ tử cung, vú, đại trực tràng)", "layer": "nen", "module": "ung-buou", "tags": ["tam-soat", "sang-loc", "phong-ngua-cap-2", "pap", "hpv", "nhu-anh", "noi-soi-dai-trang", "do-nhay", "do-dac-hieu", "qd-3898", "qd-2549"], "source": "SY5 tr. 28–64; SY2 tr. 295, 308–313; Y2 tr. 83; QĐ 3898/QĐ-BYT (2025); QĐ 2549/QĐ-BYT (2018)", "body": "> [!key] Ý chính\n> - **Tầm soát** = phát hiện ở giai đoạn **tiền ung thư/tiền lâm sàng** (phòng ngừa **cấp 2**); mục tiêu quan trọng nhất: ==giảm tử suất==.\n> - Ung thư tầm soát tốt: tiền ung kéo dài + có xét nghiệm hiệu quả + điều trị tốt tổn thương tiền ung → **cổ tử cung, vú, đại trực tràng**.\n> - Độ nhạy/độ đặc hiệu **không** phụ thuộc tần suất bệnh; giá trị dự đoán dương/âm **có**.\n> - Vú: nay có **QĐ 3898/2025** (BYT) → bắt đầu từ **40 tuổi** (nguy cơ trung bình); đại trực tràng: QĐ 2549/2018 **không có mục tầm soát** → dùng ACS (SY5).\n> - Phần phòng ngừa chung: [[ung-thu-phong-ngua]].\n\n### 1. Định nghĩa và mục tiêu {{SY5 tr.31–32}}\n- Tầm soát: tìm ung thư ở giai đoạn **tiền ung thư** (can thiệp rất hiệu quả, ngăn tiến triển). Cấp 1 = ngừa nguyên nhân.\n- Mục tiêu: giảm tần suất và **giảm tử suất**.\n- Diễn tiến: tiền ung → ung thư **tiền lâm sàng** (không triệu chứng: tầm soát/phát hiện sớm) → ung thư lâm sàng (triệu chứng báo động → chẩn đoán) {{SY2 tr.295}}.\n\n### 2. Điều kiện và chương trình tầm soát {{SY5 tr.33–38}}\n- Ung thư tầm soát tốt: **(1)** tiền ung kéo dài, **(2)** phương tiện hiệu quả, **(3)** điều trị tốt tổn thương tiền ung.\n- Chương trình: cho cộng đồng; xác định nhóm nguy cơ (↑ độ phủ); xét nghiệm dễ, an toàn, rẻ; **điều trị tổn thương tiền ung (tránh mất dấu)**; ưu tiên theo gánh nặng.\n- VN (Globocan 2018): thường gặp gan, phổi, dạ dày, vú, trực tràng, vòm hầu, bạch cầu, đại tràng, giáp, cổ tử cung. Phòng nguyên nhân: gan, phổi, cổ tử cung · tầm soát: **vú, cổ tử cung, đại trực tràng** · phát hiện sớm: giáp, vú.\n\n### 3. Giá trị xét nghiệm tầm soát {{SY5 tr.39–41}}\n| | Có bệnh | Không bệnh |\n|---|---|---|\n| XN (+) | a (dương thật) | b (dương giả) |\n| XN (−) | c (âm giả) | d (âm thật) |\n- **Độ nhạy** = a/(a+c) · **Độ đặc hiệu** = d/(b+d) · **GTDĐ dương** = a/(a+b) · **GTDĐ âm** = d/(c+d).\n- Nhạy/đặc hiệu **không** phụ thuộc tần suất; GTDĐ **phụ thuộc**. Nhạy cao: ít bỏ sót nhưng nguy cơ **chẩn đoán quá lố**.\n- Phải chứng minh giảm tần suất và đặc biệt **tử suất**; chi phí tầm soát < chi phí điều trị nếu không tầm soát.\n\n### 4. Tầm soát ung thư cổ tử cung {{SY5 tr.42–50}} {{SY2 tr.308–313}}\n- **Diễn tiến**: nhiễm HPV (20–25 tuổi) → kéo dài → CIN 1 → CIN 2/3 hay AIS (32–35) → ung thư (40–60); một số tự sạch nhiễm. Tầm soát giảm tần suất và tử suất **40–80%**.\n\n| Xét nghiệm | Đặc điểm |\n|---|---|\n| **Pap** (1939) | An toàn, rẻ; nhạy ==37–84%==, đặc hiệu ==86–100%==; Bethesda, **≥ ASC-H → soi cổ tử cung** |\n| **HPV-DNA** | Nhạy **> 90%**, GTDĐ âm rất cao; dương tính cao ở người trẻ; tự lấy mẫu; phối hợp Pap = \"bộ đôi\" |\n| **VIA** (acid acetic) | Nhạy 65–96%, đặc hiệu 64–98%; rẻ, có ngay, ít mất dấu; nhược: dương giả → điều trị quá mức |\n\n@@tabs\n@@tab ACS/ACOG 2012\n- Phụ nữ đã quan hệ tình dục; bắt đầu **21 tuổi**.\n- 21–29: **Pap mỗi 3 năm** · 30–65: Pap mỗi 3 năm **hoặc** HPV + tế bào học mỗi 5 năm · ngưng sau 65 nếu tiền căn đủ.\n@@tab WHO theo nguồn lực\n- Hạn chế: mỗi nữ nhóm nguy cơ **1 lần/đời** quanh 40 tuổi; dư nguồn lực: 10 năm/5 năm một lần cho nữ **35–55**.\n- Hướng dẫn 2016 (ACS, WHO): **tối đa** HPV 25–64 mỗi 5 năm (9 lần) · **nâng cao** HPV 30–64 (30, 34, 44, 54, 64) · **hạn chế** HPV 30–49 mỗi 10 năm (2–3 lần) · **cơ bản** HPV (hoặc VIA nếu chưa có HPV) 30–49, VAT (Visual assessment for treatment).\n@@end\n- SY2: Pap có từ thập niên 1920, rộng rãi từ 1950; xét nghiệm tầm soát hiệu quả nhất từ trước đến nay. → [Ung thư cổ tử cung – dự phòng, tầm soát](#/n/ung-thu-cotucung/8) · [Ung thư cổ tử cung](#/n/ung-thu-cotucung/8).\n\n### 5. Tầm soát ung thư vú\n> [!doc] QĐ 3898/QĐ-BYT (2025), \"Hướng dẫn sàng lọc phát hiện sớm ung thư vú\" (Cục Bà mẹ và Trẻ em; áp dụng toàn quốc)\n> **Phân nhóm** (tr.PDF 15–16): *Nguy cơ cao* nếu có 1 trong: người thân bậc 1 mắc UTV · đột biến gen (BRCA1/2, PTEN, TP53, CDH1, PALB2, STK11) · tiền sử UTV · LCIS hoặc quá sản không điển hình · xạ trị ngực lúc 10–30 tuổi (hoặc Gail 5 năm ≥ 1,7%/suốt đời ≥ 20%). Còn lại = *nguy cơ trung bình*.\n> **Chỉ điểm CA15-3, CEA không có giá trị** trong sàng lọc (tr.17).\n\n@@tabs\n@@tab Lịch sàng lọc (QĐ 3898)\n| Đối tượng | Lịch {{QĐ3898 tr.27–28}} |\n|---|---|\n| **Trung bình 25–39 tuổi** | Tự khám vú hằng tháng + khám lâm sàng **1–3 năm/lần** |\n| **Trung bình 40–70 tuổi** | Mỗi **1 năm**: khám lâm sàng + **X-quang vú** (+ **siêu âm** nếu mô vú đặc) |\n| **> 70 tuổi** | Dừng khi tuổi thọ kỳ vọng < 10 năm hoặc không thể điều trị |\n| **Nguy cơ cao** | Từ **25 tuổi**, hằng năm; khám lâm sàng 6–12 tháng/lần, X-quang vú, có thể **MRI** vú |\n| Xạ trị ngực 10–30 tuổi | X-quang + MRI hằng năm, bắt đầu **8 năm sau xạ trị**, không trước 25 tuổi |\n| Gia đình/gen | X-quang bắt đầu **10 năm trước tuổi mắc của người trẻ nhất** (không trước 30, chậm nhất 40); MRI tương tự (không trước 25) |\n| LCIS / quá sản không điển hình | X-quang từ lúc chẩn đoán (không trước 30); cân nhắc MRI |\n@@tab Phương tiện\n| Phương tiện | Theo QĐ 3898 {{QĐ3898 tr.17–26}} |\n|---|---|\n| **Tự khám vú** | Hằng tháng, **sau sạch kinh 5 ngày**, từ **25 tuổi**; không thay thế sàng lọc |\n| **Khám lâm sàng** | Từ tuyến ban đầu, BS được đào tạo; hạch ≤ 1 cm mềm di động hiếm ác tính, **hạch thượng đòn to = bất thường** |\n| **X-quang vú** | **Duy nhất chứng minh giảm tử vong**; thấy ung thư sớm 1,5–4 năm; CC + MLO; kỹ thuật **Eklund** nếu túi ngực; CCĐ: viêm/áp xe/vỡ loét, tuần đầu sau mổ/sinh thiết; hạn chế: mô đặc, sát thành ngực, ion hóa |\n| **Siêu âm** | **Không đơn độc**; ↑ nhạy, ↓ đặc hiệu; chỉ định mô đặc, túi ngực, nguy cơ cao < 30 tuổi; không bức xạ, ít tốn kém |\n| **MRI** | Nhạy hơn X-quang, đặc hiệu thấp (dương giả, chẩn đoán quá mức); cho **nguy cơ cao**, mô đặc/túi ngực ≥ 40 tuổi; CCĐ: kim loại không tương thích, suy thận nặng, dị ứng thuốc đối quang, thai (nếu tiêm) |\n- **BI-RADS** (tr.23): 0 đánh giá thêm · 1 bình thường · 2 lành tính · **3** khả năng lành cao (< 2%, theo dõi 6 tháng) · **4** nghi ác (4A/B/C → sinh thiết) · **5** nguy cơ cao (sinh thiết) · 6 đã xác định ung thư. Mô vú đặc **BI-RADS C/D** → thêm siêu âm.\n@@end\n\n@@fold SY5 (ACS 2015) và các số liệu cũ {{SY5 tr.51–56}}\n- Nguy cơ: mọi phụ nữ > 40, đặc biệt tiền căn gia đình. Nước đang phát triển hạn chế nguồn lực: siêu âm.\n- BSE (từ 1978): **không giảm tử suất** → \"tự nhận thức tuyến vú\" (BSA) từ 20 tuổi · CBE: chưa chứng minh giảm tử suất, có lợi giáo dục · **Nhũ ảnh**: giảm tử suất, chi phí–hiệu quả, nhạy ≈ **70%**, đặc hiệu ≈ **75%** · Siêu âm: ưu thế mô đặc, phụ thuộc người đọc, không thấy vôi hóa li ti.\n- **ACS 2015**: 40–44 có thể bắt đầu hằng năm; **45–54 hằng năm**; ≥ 55 mỗi 2 năm hoặc tiếp tục hằng năm; tiếp tục khi khỏe và sống thêm > 10 năm; **không khuyến cáo khám lâm sàng** ở nguy cơ trung bình.\n@@end\n\n> [!warn] Khác biệt giữa nguồn (vú) — thi theo nguồn đề, ưu tiên văn bản BYT cho thực hành VN\n> - **Tuổi bắt đầu nhũ ảnh**: QĐ 3898 = **40 tuổi** (mỗi năm; dựa tuổi mắc Việt Nam cao nhất 40–59, <40 chỉ 13,5%) vs SY5/ACS 2015 = **45 tuổi** (40–44 tùy chọn).\n> - **Tần suất sau 55**: QĐ 3898 = mỗi **1 năm** đến 70 tuổi vs ACS = mỗi **2 năm** từ 55.\n> - **Tuổi dừng**: QĐ 3898 = > 70 nếu sống < 10 năm vs ACS = tiếp tục nếu sống thêm > 10 năm.\n> - **Tự khám/khám lâm sàng**: QĐ 3898 **khuyến cáo** (tự khám từ 25, CBE 1–3 năm ở 25–39, hằng năm từ 40) vs SY5 **không giảm tử suất**, CBE không khuyến cáo nguy cơ trung bình.\n> - **Siêu âm**: QĐ 3898 phối hợp khi mô đặc/hạn chế nguồn lực vs SY5 chưa xem là phương tiện tầm soát ở nước phát triển.\n> - **Gail**: SY5 > 1,66% vs QĐ 3898 ≥ 1,7%.\n\n→ [Ung thư vú – dự phòng, sàng lọc](#/n/ung-thu-vu/8) · [Ung thư vú](#/n/ung-thu-vu/5) (cận lâm sàng) · [Ung thư vú](#/n/ung-thu-vu/8).\n\n### 6. Tầm soát ung thư đại trực tràng\n> [!doc] QĐ 2549/QĐ-BYT (19/4/2018), \"Hướng dẫn chẩn đoán và điều trị ung thư đại – trực tràng\"\n> - Văn bản **không có mục sàng lọc/tầm soát cộng đồng** (đã tìm toàn văn); lịch tầm soát dưới đây lấy từ SY5 (ACS).\n> - **Yếu tố nguy cơ** (tr.PDF 2): ăn nhiều thịt, mỡ động vật, ít xơ, thiếu vitamin A, B, C, E, canxi; benzopyren, nitrosamin · **tiền ung**: viêm đại trực tràng chảy máu (UC), **Crohn**, **polyp** · **di truyền**: **Lynch**, **FAP**, Peutz-Jeghers, Gardner.\n> - **Triệu chứng gợi ý cần soi** (tr.2): rối loạn lưu thông ruột, **đi ngoài nhầy máu (hay gặp nhất)**, đau bụng, thiếu máu, gầy sút.\n> - **Soi đại trực tràng ống mềm** là phương pháp quan trọng để chẩn đoán (tr.2–3).\n> - **Theo dõi sau điều trị** (tr.PDF 23): soi trong năm đầu nếu chưa soi trước mổ, sau đó **3–5 năm/lần đến 75 tuổi**; u tuyến tiến triển lặp lại sau **1 năm**, không tiến triển sau **3 năm**, rồi 5 năm/lần.\n\n- **Nguy cơ** {{SY5 tr.57}}: > 50 tuổi (SY5 tr.57), tiền căn gia đình, polyp, hội chứng di truyền. Diễn tiến: biểu mô bình thường → tăng sinh → u tuyến nhỏ → u tuyến lớn → carcinôm (APC, K-ras, p53, mất 18q, ↑ COX-2).\n- **Hai nhóm xét nghiệm**: tìm cả **polyp + ung thư** (nội soi, X-quang; **nội soi ưu tiên vì cắt được polyp**) · chủ yếu tìm ung thư (máu ẩn phân: ít sang chấn, ít phát hiện polyp).\n\n| Xét nghiệm (ACS, người bình thường 45–75 tuổi) {{SY5 tr.61–62}} | Tần suất |\n|---|---|\n| FOBT/hóa miễn dịch phân (FIT)/máu ẩn nhạy cao | Mỗi **1 năm** |\n| DNA phân đa đích | Mỗi **3 năm** |\n| Soi đại tràng sigma | Mỗi **5 năm** |\n| X-quang đại tràng đối quang kép | Mỗi 5 năm |\n| CT đại tràng (nội soi ảo) | Mỗi 5 năm |\n| **Nội soi toàn bộ đại tràng** | Mỗi **10 năm** |\n- Mọi xét nghiệm khác dương tính → **nội soi đại tràng**. ≥ 45 tuổi tầm soát định kỳ; khỏe + sống thêm > 10 năm: đến **75**; 76–85 tùy từng người; > 85 không khuyến khích. **Nguy cơ cao**: chủ yếu nội soi, bắt đầu sớm hơn, thường xuyên hơn.\n\n> [!warn] Mâu thuẫn tuổi bắt đầu (đại trực tràng)\n> SY5 tr.57 ghi nguy cơ **> 50 tuổi**, nhưng khuyến cáo ACS cùng bài (tr.61–62) bắt đầu từ **45 tuổi**. QĐ 2549 không nêu tuổi tầm soát. Theo dõi sau điều trị (QĐ 2549) dừng ở **75 tuổi**, trùng mốc ACS.\n\n→ [Ung thư đại trực tràng – dự phòng, tầm soát](#/n/ung-thu-daitruc-trang/8) · [Ung thư đại–trực tràng](#/n/ung-thu-daitruc-trang/8)\n\n### 7. Trở ngại và kết luận {{SY5 tr.63–64}}\n- Độ phủ thấp (ngại, bất tiện, kinh tế → truyền thông, y tế địa phương) · xét nghiệm kém nhạy (đào tạo) · **mất dấu** · điều trị tiền ung chưa hiệu quả → phối hợp y tế cơ sở và chuyên sâu.\n- Ưu tiên VN: **cổ tử cung, vú, đại trực tràng**.\n\n> [!ext] Bổ sung (tham khảo, không phải văn bản BYT; CHƯA tra cứu nguồn gốc, cần kiểm tra lại)\n> Khuyến cáo quốc tế về tuổi bắt đầu thay đổi theo thời gian (ví dụ USPSTF hạ tuổi bắt đầu tầm soát đại trực tràng xuống 45 tuổi năm 2021 và nhũ ảnh xuống 40 tuổi, mỗi 2 năm, năm 2024). Chỉ để so sánh. *Nguồn: USPSTF, https://www.uspreventiveservicestaskforce.org*\n\n### Điểm hay thi\n> [!warn] Bẫy thường gặp\n> - Tầm soát = **cấp 2**; mục tiêu quan trọng nhất **giảm tử suất**.\n> - Độ nhạy/đặc hiệu **không** phụ thuộc tần suất; **GTDĐ có** phụ thuộc.\n> - Cổ tử cung: bắt đầu **21 tuổi** (ACS/ACOG); 21–29 Pap/3 năm; 30–65 Pap/3 năm hoặc HPV+TB học/5 năm.\n> - Vú: QĐ 3898 = từ **40 tuổi** (X-quang mỗi năm); ACS 2015 = **45**. Chỉ X-quang vú **chứng minh giảm tử vong**; CA15-3, CEA **vô giá trị** tầm soát.\n> - Siêu âm vú **không đơn độc**; MRI cho **nguy cơ cao**, nhạy cao đặc hiệu thấp.\n> - Đại trực tràng: nội soi **ưu tiên** (cắt polyp); FIT mỗi **năm**; nội soi mỗi **10 năm**; đến 75 tuổi.\n> - QĐ 2549 **không** có lịch tầm soát đại trực tràng.\n\n### Tự kiểm tra\n- Định nghĩa tầm soát và mục tiêu quan trọng nhất? :: Phát hiện ở giai đoạn tiền ung thư; giảm tử suất\n- Ba điều kiện để ung thư tầm soát tốt? :: Tiền ung kéo dài, có phương tiện hiệu quả, điều trị tốt tổn thương tiền ung\n- Công thức độ nhạy và độ đặc hiệu? :: Độ nhạy = a/(a+c); độ đặc hiệu = d/(b+d)\n- Chỉ số nào phụ thuộc tần suất bệnh? :: Giá trị dự đoán dương và âm\n- Khuyến cáo ACS/ACOG 2012 tầm soát cổ tử cung? :: Từ 21 tuổi; 21–29 Pap/3 năm; 30–65 Pap/3 năm hoặc HPV + TB học/5 năm; ngưng sau 65\n- Độ nhạy, đặc hiệu của Pap theo SY5? :: Nhạy 37–84%, đặc hiệu 86–100%\n- Lịch sàng lọc ung thư vú nguy cơ trung bình theo QĐ 3898/2025? :: 25–39: tự khám + khám lâm sàng 1–3 năm/lần; 40–70: hằng năm khám + X-quang vú (+ siêu âm nếu mô đặc); > 70 dừng nếu sống < 10 năm\n- Phương tiện duy nhất chứng minh giảm tử vong ung thư vú? :: X-quang tuyến vú (nhũ ảnh)\n- Phụ nữ mang BRCA có người thân mắc UTV lúc 35 tuổi: X-quang vú bắt đầu khi nào? :: Từ 30 tuổi (10 năm trước người trẻ nhất, không trước 30); MRI không trước 25\n- Khác biệt tuổi bắt đầu nhũ ảnh giữa QĐ 3898 và ACS 2015? :: QĐ 3898: 40 tuổi hằng năm; ACS 2015: 45 (40–44 tùy chọn)\n- Lịch ACS tầm soát đại trực tràng 45–75 tuổi? :: FIT/FOBT mỗi năm; DNA phân 3 năm; nội soi toàn bộ 10 năm; CT hoặc sigma 5 năm\n- Vì sao nội soi được ưu tiên? :: Tìm được cả polyp và ung thư, cắt polyp được\n- Theo QĐ 2549, theo dõi nội soi sau điều trị ung thư đại tràng? :: Sau 1 năm; sau đó 3–5 năm/lần đến 75 tuổi; u tuyến tiến triển lặp lại sau 1 năm"}, {"kind": "foundation", "disease": "", "short": "", "group": "Cơ chế", "section": 0, "order": 4, "khung": [], "id": "ung-thu-telomere-chet-te-bao", "title": "Telomere, telomerase và chết tế bào theo lập trình (apoptosis)", "layer": "nen", "module": "ung-buou", "tags": ["ung thư", "telomere", "telomerase", "apoptosis", "caspase", "Bcl-2", "p53", "hoại tử"], "source": "Y2 tr. 7–11, 80–82; SY2 tr. 34–53, 460–480", "body": "> [!key]\n> - **Telomere** (lặp ==TTAGGG==) ngắn dần mỗi lần phân bào → giới hạn Hayflick; TB ung thư **tái hoạt hóa telomerase** → phân bào vô hạn\n> - **Apoptosis**: chết có điều hòa, qua **caspase**; 2 đường: ngoại sinh (thụ thể chết → caspase 8) và nội sinh (ty thể, cytochrome c → caspase 9)\n> - Ung thư **kháng apoptosis**: mất cân bằng Bcl, giảm caspase, đột biến p53\n\n## 1. Telomere và telomerase\n- Vấn đề: đầu tận NST tự do có thể dính NST kế cận (tổ hợp NST = một dạng đột biến); mỗi lần nhân đôi mất một phần nhỏ đầu tận {{Y2 tr.7}} {{SY2 tr.35}}\n- **Telomere**: phần tận cùng NST, trình tự giàu G lặp **TTAGGG**, không mã hóa protein nên bị bào mòn không mất thông tin; phức hệ protein (capping) bọc đầu như đầu dây giày {{Y2 tr.7–8}} {{SY2 tr.36}}\n- TB bình thường: telomere ngắn dần → ngừng sinh sản, bị đẩy vào chết theo lập trình = **giới hạn Hayflick** {{Y2 tr.8}}\n- **Telomerase**: men sao chép ngược (ribonucleoprotein), dùng **RNA đơn làm khuôn** gắn TTAGGG vào đầu tận → kéo dài telomere {{SY2 tr.38}}\n\n| Loại tế bào | Telomerase |\n|---|---|\n| Tế bào mầm (trứng, tinh trùng) | Có, đủ nồng độ duy trì độ dài telomere |\n| Tế bào gốc | Có nhưng không đủ duy trì như TB mầm |\n| TB sinh dưỡng bình thường | **Không** → ngắn dần, ngừng tăng trưởng, lão hóa, chết |\n| TB ung thư | Thường **tái hoạt hóa mạnh** → giữ độ dài → phân bào vô hạn |\n\n{{Y2 tr.8–9}} {{SY2 tr.39}}\n- Ứng dụng (nghiên cứu): ức chế telomerase để giới hạn TB ung thư; hoặc hoạt hóa telomerase ở TB miễn dịch {{Y2 tr.9}} {{SY2 tr.41}}\n- Slide nêu **6 đặc tính** TB ung thư: duy trì tín hiệu phân bào · thoát ức chế tăng trưởng · kháng chết TB · phân bào không giới hạn · tăng sinh mạch · xâm lấn và di căn {{SY2 tr.40}}\n\n## 2. Apoptosis (chết tế bào theo lập trình)\n- Tên Hy Lạp \"lá vàng rụng\"; Kerr mô tả đầu tiên; loại TB không cần/mất chức năng (vd đuôi nòng nọc), tạo khe ngón, loại neuron thừa {{Y2 tr.9, 81}}\n- Người trưởng thành giữ cân bằng với tăng sinh\n\n> [!warn] Số lượng TB chết mỗi ngày: Y2 ghi ==50–70 triệu==; slide (SY2 tr.43) ghi \"50–70 triệu tỷ\". Hai nguồn chưa thống nhất.\n\n### So sánh với hoại tử\n| Apoptosis | Hoại tử |\n|---|---|\n| Có vai trò ty thể, cytochrome C | Không |\n| Không thoát men tiêu thể | Có thoát men tiêu thể |\n| TB co lại, bào tương/màng chia mảnh, nhân chia nhỏ, thể chết lập trình | TB phồng, màng vỡ, nhân mất |\n| DNA bị chẻ nhỏ | Không |\n| Hoạt hóa men tiêu đạm đặc hiệu | Không |\n| **Điều hòa được** | Không |\n| Bị TB xung quanh tiêu hủy, không hại mô quanh | Đại bào, bạch cầu đa nhân tiêu hủy; thoát chất gây **viêm** |\n\n{{Y2 tr.9–10, 81}} {{SY2 tr.44–45}}\n\n### Caspase và hai con đường\n- Caspase: protease có **cysteine** ở vị trí hoạt động, cắt protein đích tại **aspartic acid**; vừa khơi mào vừa thực thi {{Y2 tr.10}} {{SY2 tr.46}}\n- Slide nêu thêm đường thứ 3 (lưới nội bào, ít biết)\n\n| | Ngoại sinh (thụ thể chết) | Nội sinh (ty thể) |\n|---|---|---|\n| Khởi đầu | Phối tử (TNFα, FasL, TRAIL) gắn Fas, TNFR1 | Tổn thương gen không sửa được, thiếu oxy, Ca2+ bào tương cao, stress oxy hóa |\n| Diễn tiến | TRADD, FADD → phức hợp **DISC** → pro-caspase 8 (10) → caspase 8 (10) | Bax, Bak, Bad, Bid... tăng tính thấm ty thể → **cytochrome c** → caspase **9** |\n| Kết thúc | Caspase **3, 6, 7** giết TB | Caspase 3, 6, 7 |\n\n- Họ **Bcl**: tiền chết (Bax, Bak, Bad, Bcl-Xs, Bid, Bik, Bim, Hrk) · chống chết (Bcl-2, Bcl-XL, Bcl-W, Bfl-1, Mcl-1) {{Y2 tr.10, 81}} {{SY2 tr.47–50}}\n\n## 3. Rối loạn apoptosis trong ung thư\n- Suy dẫn truyền tín hiệu: giảm thụ thể/tín hiệu chết, hoặc thụ thể \"mồi\" không có miền chết\n- Mất cân bằng Bcl: giảm protein tiền chết **hoặc** tăng chống chết\n- Giảm caspase hoặc đột biến p53 {{Y2 tr.11}} {{SY2 tr.51}}\n- Đột biến caspase 3, 8 ở một số ung thư dạ dày, phổi, đại tràng; **procaspase 3 biểu hiện nhiều nhưng không thành caspase 3 hoạt động** ở hầu hết ung thư {{Y2 tr.81}} {{SY2 tr.470–472}}\n- p53 mã hóa Bax; p53 mất → mất Bax → không apoptosis. Gen apoptosis có thể là sinh ung (Bcl-2) hoặc đè nén bướu (PTEN, p53) {{Y2 tr.11}}\n\n> [!tip] Ví dụ CLL\n> t(14;18) hoạt hóa **Bcl-2** → TB ác tính tăng sinh bình thường nhưng **không chết** → tích lũy chậm, hợp diễn tiến mạn {{Y2 tr.11}} {{SY2 tr.53}}\n\n### Điểm hay thi\n> [!warn]\n> - TTAGGG; telomerase dùng **RNA** làm khuôn; TB bình thường không có, TB ung thư tái hoạt hóa\n> - Bảng so sánh apoptosis vs hoại tử (ty thể, men tiêu thể, viêm, điều hòa)\n> - Nội sinh: cytochrome c → caspase **9**; ngoại sinh: DISC → caspase **8**; chốt: 3, 6, 7\n> - Phân biệt nhóm tiền chết (Bax, Bak) và chống chết (Bcl-2, Bcl-XL)\n\n### Tự kiểm tra\n- Trình tự lặp của telomere? :: TTAGGG\n- Vì sao TB ung thư phân bào vô hạn? :: Telomerase tái hoạt hóa nên giữ nguyên chiều dài telomere\n- Telomerase là men gì, dùng khuôn gì? :: Men sao chép ngược (ribonucleoprotein), RNA đơn làm khuôn\n- Giới hạn Hayflick? :: Số lần phân bào có giới hạn do telomere ngắn dần\n- Ba điểm khác apoptosis và hoại tử? :: Apoptosis: có ty thể/cytochrome C, không thoát men tiêu thể, DNA chẻ nhỏ, điều hòa được, không gây viêm\n- Chất nào từ ty thể khởi đầu đường nội sinh, hoạt hóa caspase nào? :: Cytochrome c; caspase 9\n- Đường ngoại sinh khởi đầu thế nào, caspase nào trước? :: Phối tử gắn Fas/TNFR → DISC → caspase 8\n- Hai nhóm protein họ Bcl, mỗi nhóm 2 ví dụ? :: Tiền chết: Bax, Bak; chống chết: Bcl-2, Bcl-XL\n- Cơ chế apoptosis bất thường trong CLL? :: t(14;18) hoạt hóa Bcl-2 → TB không chết, tích lũy chậm\n- Caspase là loại men gì? :: Protease có cysteine, cắt tại aspartic acid"}, {"kind": "foundation", "disease": "", "short": "", "group": "Triệu chứng và chẩn đoán chung", "section": 3, "order": 5, "khung": [], "id": "ung-thu-the-trang-kps-ecog", "title": "Đánh giá thể trạng bệnh nhân ung thư (KPS, WHO/ECOG)", "layer": "cls", "module": "ung-buou", "tags": ["KPS", "ECOG", "thể trạng", "performance status"], "source": "SY5 tr. 145–146 (bảng KPS/ECOG đọc từ ảnh)", "body": "> [!key] Tóm tắt\n> - Hai thang đánh giá hoạt động cơ thể: **KPS** (0–100) và **WHO/ECOG** (0–5) {{SY5 tr.145}}\n> - Tương quan: ==ECOG 0–1 ≈ KPS 80–100; ECOG 2 ≈ KPS 60–70; ECOG 3–4 ≈ KPS 10–50==\n> - Thể trạng là một phần của đánh giá toàn diện để chọn điều trị phù hợp từng bệnh nhân\n\n### Vì sao cần đánh giá\n- Cần biết: thể trạng, **bệnh đi kèm**, tuổi, **thời gian kỳ vọng sống thêm**, thói quen lối sống {{SY5 tr.145}}\n- Mục đích: điều trị phù hợp **cơ địa và tình trạng** từng bệnh nhân\n- Nằm trong quy trình chẩn đoán: [[ung-thu-tiep-can-chan-doan]]\n\n### Bảng tương quan\n| WHO/ECOG | KPS |\n|---|---|\n| 0–1 | 80–100 |\n| 2 | 60–70 |\n| 3–4 | 10–50 |\n(slide ghi dấu \"#\", hiểu là tương đương) {{SY5 tr.145}}\n\n@@tabs\n@@tab KPS (Karnofsky)\n| Điểm | Mô tả |\n|---|---|\n| 100 | Bình thường; không than phiền; không biểu hiện bệnh |\n| 90 | Sinh hoạt bình thường; ít dấu hiệu/triệu chứng |\n| 80 | Cần gắng sức để hoạt động bình thường; vài dấu hiệu/triệu chứng |\n| 70 | Tự chăm sóc được; **không thể** hoạt động bình thường hoặc làm việc |\n| 60 | Thỉnh thoảng cần trợ giúp, tự chăm sóc phần lớn nhu cầu |\n| 50 | Cần trợ giúp đáng kể và chăm sóc y tế thường xuyên |\n| 40 | Yếu; cần giúp đỡ và chăm sóc đặc biệt |\n| 30 | Bệnh nặng; có chỉ định nhập viện dù chưa đe dọa tử vong |\n| 20 | Bệnh rất nặng; cần nhập viện; điều trị nâng đỡ tích cực |\n| 10 | Hấp hối; diễn tiến nhanh đến tử vong |\n| 0 | Tử vong |\n@@tab WHO/ECOG\n| Điểm | Mô tả |\n|---|---|\n| 0 | Không triệu chứng; hoạt động bình thường như trước bệnh |\n| 1 | Có triệu chứng nhưng **đi lại bình thường**; hạn chế việc nặng, làm được việc nhẹ (việc nhà, văn phòng) |\n| 2 | Có triệu chứng, **< 50%** thời gian ngày nằm nghỉ; đi lại, tự chăm sóc được nhưng không làm việc; thức > 50% thời gian |\n| 3 | Có triệu chứng, **> 50%** thời gian nghỉ trên giường nhưng không liệt giường; tự chăm sóc một phần; nằm/ngồi > 50% thời gian thức |\n| 4 | **Nằm liệt giường**; bệnh rất nặng, không tự chăm sóc |\n| 5 | Tử vong |\n@@end\n{{SY5 tr.146}}\n\n> [!tip] Mẹo nhớ\n> ECOG 0–1 = còn **đi làm được** (KPS ≥ 80); ECOG 2 = **tự chăm sóc nhưng không làm việc** (KPS 60–70); ECOG ≥ 3 = **> 50% thời gian nằm** (KPS ≤ 50).\n\n### Điểm hay thi\n> [!warn]\n> - Ba mốc tương quan ECOG–KPS (0–1/80–100; 2/60–70; 3–4/10–50)\n> - ECOG 2 (< 50% nằm) khác ECOG 3 (> 50% nằm); ECOG 4 = liệt giường; ECOG 5 = tử vong\n> - KPS 70: tự chăm sóc được nhưng không làm việc; KPS 50: cần chăm sóc y tế thường xuyên; KPS 30: có chỉ định nhập viện\n> - Ngoài thang điểm còn cần: bệnh đi kèm, tuổi, thời gian kỳ vọng sống, lối sống\n\n### Tự kiểm tra\n- Hai thang đánh giá thể trạng? :: KPS (Karnofsky) và WHO/ECOG\n- ECOG 0–1 tương ứng KPS? :: 80–100\n- ECOG 2 tương ứng KPS? :: 60–70\n- ECOG 3–4 tương ứng KPS? :: 10–50\n- ECOG 2 mô tả? :: Có triệu chứng, nằm nghỉ < 50% thời gian ngày; tự chăm sóc nhưng không làm việc\n- ECOG 3 mô tả? :: Có triệu chứng, nghỉ trên giường > 50% nhưng không liệt giường; tự chăm sóc một phần\n- ECOG 4 là gì? :: Nằm liệt giường, không tự chăm sóc\n- ECOG 5? :: Tử vong\n- KPS 70? :: Tự chăm sóc được; không thể hoạt động bình thường hoặc làm việc\n- KPS 100? :: Bình thường, không than phiền, không biểu hiện bệnh\n- KPS 30? :: Bệnh nặng, có chỉ định nhập viện dù chưa đe dọa tử vong\n- Ngoài thể trạng cần biết yếu tố gì? :: Bệnh đi kèm, tuổi, thời gian kỳ vọng sống thêm, thói quen lối sống"}, {"kind": "foundation", "disease": "", "short": "", "group": "Triệu chứng và chẩn đoán chung", "section": 4, "order": 2, "khung": [], "id": "ung-thu-tiep-can-chan-doan", "title": "Tiếp cận chẩn đoán ung thư", "layer": "trieuchung", "module": "ung-buou", "tags": ["chẩn đoán ung thư", "sinh thiết", "giải phẫu bệnh", "giai đoạn", "nhóm nguy cơ"], "source": "SY5 tr. 117–149 (PGS. Cung Thị Tuyết Anh; ThS. Quan Anh Tiến; ThS. Đoàn Trọng Nghĩa); SY5 tr. 65–81 cho tab triệu chứng", "body": "> [!key] Tóm tắt\n> - Quy trình: **lâm sàng → cận lâm sàng; không xâm lấn → xâm lấn** {{SY5 tr.119}}\n> - **5 nội dung chẩn đoán**: cơ quan mang bướu · bản chất mô học · giai đoạn · đặc tính sinh học · nhóm nguy cơ (+ đánh giá thể trạng)\n> - ==Mô bệnh học là tiêu chuẩn vàng== chẩn đoán xác định\n> - Tiền căn, yếu tố nguy cơ, dấu ấn máu **không** dùng để chẩn đoán/tầm soát ung thư\n\n### Bác sĩ cần biết gì ở ca nghi ung thư\n1. Bướu khởi phát ở **cơ quan** nào?\n2. **Bản chất mô học**: có thật sự ác tính, hay lành, hay bệnh khác?\n3. Nếu ung thư: **giai đoạn** lan tràn?\n4. **Đặc tính sinh học**?\n5. **Nguy cơ thất bại** điều trị? {{SY5 tr.120}}\n\n### Triệu chứng → hướng nghĩ tới ung thư\n@@tabs\n@@tab Bảy triệu chứng báo động\n| Triệu chứng | Nghĩ tới |\n|---|---|\n| Đổi thói quen ruột, máu trong phân | Đại trực tràng |\n| Tiểu khó/buốt/ra máu | Bàng quang, tuyến tiền liệt |\n| Loét không lành (da, lưỡi, miệng, sẹo cũ) | Ung thư da, lưỡi, hốc miệng |\n| Xuất huyết âm đạo sau giao hợp/mãn kinh | Cổ tử cung |\n| Chảy máu/tiết dịch núm vú; khối ở vú | Vú |\n| Chảy máu mũi | Vòm hầu, hốc mũi (phân biệt bệnh huyết học) |\n| Khó tiêu, đau thượng vị | Dạ dày |\n| Nuốt vướng/đau; nuốt nghẹn tăng dần | Amiđan, hạ hầu; thực quản |\n| Nốt ruồi lớn nhanh, đổi màu, loét, chảy máu | Tài liệu không nêu tên bệnh |\n| Ho dai dẳng (nam > 40, hút thuốc) | Phổi |\n| Khàn tiếng > 3 tuần | Thanh quản |\nChi tiết: [[ung-thu-bay-trieu-chung]] {{SY5 tr.69–80}}\n@@tab Biểu hiện không điển hình\n- Sụt cân không rõ nguyên nhân, sốt tái đi tái lại, xanh xao, mệt, đau kéo dài\n- **Hạch/bướu di căn** chưa thấy nguyên phát: hạch cổ, trên đòn, bẹn ác tính\n- Đau lưng rồi **yếu dần hai chi dưới**\n- Phát hiện **tình cờ**: khối mờ nhỏ ở phổi, tổn thương nghi bướu gan\n{{SY5 tr.122}}\n@@end\n> [!warn] Mọi triệu chứng trên cũng gặp ở bệnh lành: vì vậy cần **khám để xác định hoặc loại trừ**, không kết luận từ triệu chứng.\n\n### Phương tiện chẩn đoán\n| Nhóm | Nội dung |\n|---|---|\n| Hỏi bệnh | Thời điểm khởi phát, diễn tiến, quá trình khám và điều trị |\n| Khám | Tổn thương (vị trí, kích thước, hình dạng, màu, mật độ, giới hạn, di động, đau); hạch vùng; toàn thân (cơ quan hay di căn); tổng trạng |\n| Hình ảnh | X-quang, siêu âm, CT, MRI, PET, xạ hình |\n| Xét nghiệm | Sinh hóa, miễn dịch |\n| Giải phẫu bệnh | Tế bào học, mô học |\n| Sinh học phân tử | Hóa mô miễn dịch, khảo sát gen |\n| Thủ thuật | Nội soi, chọc hút, sinh thiết, phẫu thuật |\n{{SY5 tr.123–125}}\n\n### Năm nội dung chẩn đoán\n@@tabs\n@@tab 1. Cơ quan mang bướu\n- Nhìn/sờ được → **khám lâm sàng** (da, vú, môi, hốc miệng, cổ tử cung, giáp…)\n- Bướu sâu → cận lâm sàng: phổi (X-quang, CT); gan (siêu âm, CT, MRI); ống tiêu hóa (CT, MRI, nội soi); thần kinh trung ương (CT, MRI)\n- Hạch/bướu di căn phát hiện đầu tiên → **truy tìm bướu nguyên phát**. Slide đặt 2 tình huống (nữ 30 tuổi hạch nách phải 2 cm sượng cứng; nam 60 tuổi đau cột sống thắt lưng, X-quang đặc xương L4), tài liệu không nêu đáp án\n{{SY5 tr.126–127}}\n@@tab 2. Bản chất mô học\n- Lâm sàng/hình ảnh có thể gợi ý nhưng **không thay thế bằng chứng mô học**\n- Tiền căn, thói quen, nghề, dịch tễ, yếu tố nguy cơ {r|không dùng để chẩn đoán ung thư}\n- ==Mô bệnh học = tiêu chuẩn vàng==; GPB còn xác định carcinôm hay sarcôm, loại, độ ác tính (vd 3 mức độ Nottingham ở carcinôm ống tuyến vú xâm nhiễm không đặc hiệu)\n- Lý tưởng: có chẩn đoán GPB **trước** điều trị\n- Sinh thiết: trọn bướu, **lõi kim (core)**, kềm bấm qua nội soi\n- Trước mổ có thể chỉ có **tế bào học** (FNAC, rút dịch): vd FNA hạt giáp ra carcinôm giáp dạng nhú + siêu âm gợi ý → có thể phẫu thuật\n- **Ngoại lệ**:\n  - U thần kinh trung ương: lâm sàng + MRI gợi ý, GPB chính xác sau mổ\n  - Một số ung thư trẻ em điều trị chưa cần mô bệnh học\n  - **HCC**: dựa MRI ± AFP tăng ± tiền căn viêm gan B, C; sinh thiết khi hình ảnh/diễn tiến không điển hình\n- {o|GPB không tương hợp lâm sàng, hình ảnh} → xem lại, hội chẩn lại, nghĩ bệnh lý khác (lành hoặc ác) để chẩn đoán phân biệt\n- Dấu ấn máu: đa số kém nhạy/đặc hiệu; tầm soát bằng dấu ấn là **sai** → [[ung-thu-dau-an-sinh-hoc]]\n{{SY5 tr.128–136}}\n@@tab 3. Giai đoạn\n- Do **T, N, M** quyết định; cách đánh giá T, N tùy loại ung thư\n- Chi tiết: [[ung-thu-phan-giai-doan-tnm]]; lan tràn: [[ung-thu-xam-lan-di-can]] {{SY5 tr.137}}\n@@tab 4. Đặc tính sinh học\n- Khác nhau từng bệnh nhân; xét nghiệm ở mức **phân tử**\n- Mục đích: phân loại bướu, chọn điều trị, tiên đoán đáp ứng, tiên lượng\n- Ví dụ biomarker–thuốc đích: [[ung-thu-dau-an-sinh-hoc]]; nền tảng [[ung-thu-sinh-hoc-phan-tu]] {{SY5 tr.142–143}}\n@@tab 5. Nhóm nguy cơ\n- Tổng hợp 4 yếu tố trên (+ đặc tính sinh học) → nhóm nguy cơ tái phát/di căn → **điều trị cá thể hóa**\n- Ví dụ ung thư **tuyến tiền liệt** khu trú:\n\n| Nhóm | Tiêu chuẩn |\n|---|---|\n| Thấp | T1, T2a **và** Gleason ≤ 6 **và** PSA < 10 ng/ml |\n| Trung bình | T2b ± Gleason 7 ± PSA 10–20 ng/ml |\n| Cao | ≥ T2c **hoặc** Gleason 8–10 **hoặc** PSA > 20 ng/ml |\n{{SY5 tr.144}}\n@@end\n\n### Đánh giá thể trạng\n- Cần biết thể trạng, bệnh đi kèm, tuổi, thời gian kỳ vọng sống, lối sống; dùng KPS và WHO/ECOG → [[ung-thu-the-trang-kps-ecog]] {{SY5 tr.145}}\n\n### Kết luận của bài giảng\n- Làm **đầy đủ** nội dung chẩn đoán, từ lâm sàng đến cận lâm sàng; **không tùy tiện** dùng phương tiện, dựa trên bệnh học và diễn tiến tự nhiên\n- Có thể thực hiện trước, trong hoặc sau mổ; **khai thác tối đa bệnh phẩm mổ**\n- Thông tin sinh học cần cho điều trị cá thể hóa; theo phác đồ/guidelines từng ung thư {{SY5 tr.147}}\n- Ví dụ áp dụng: [Ung thư phổi](#/n/ung-thu-phoi/4); GPB cơ sở: [[ung-thu-giai-phau-benh]]\n\n### Điểm hay thi\n> [!warn]\n> - Tiêu chuẩn vàng = **mô bệnh học**; yếu tố nguy cơ/tiền căn **không** chẩn đoán ung thư\n> - Tầm soát bằng dấu ấn sinh học máu là **sai**\n> - 5 nội dung chẩn đoán; nhóm nguy cơ tuyến tiền liệt (cao: ≥ T2c hoặc Gleason 8–10 hoặc PSA > 20)\n> - Ngoại lệ không bắt buộc sinh thiết trước: HCC điển hình trên hình ảnh, u thần kinh trung ương, một số ung thư trẻ em\n> - GPB không hợp lâm sàng → hội chẩn lại, nghĩ bệnh khác\n> - Quan niệm \"ung thư phải sụt cân mới nghĩ tới\" là sai\n\n### Tự kiểm tra\n- Hướng đi của quy trình chẩn đoán? :: Từ lâm sàng đến cận lâm sàng, từ không xâm lấn đến xâm lấn\n- Tiêu chuẩn vàng chẩn đoán xác định? :: Mô bệnh học (giải phẫu bệnh)\n- Tiền căn, yếu tố nguy cơ có dùng chẩn đoán ung thư được không? :: Không\n- Các phương tiện sinh thiết? :: Trọn bướu, lõi kim (core biopsy), kềm bấm qua nội soi\n- Khi nào chỉ có tế bào học trước mổ? :: Chọc hút kim nhỏ (FNAC) hoặc rút dịch; vd FNA giáp ra carcinôm nhú + siêu âm gợi ý thì có thể mổ\n- HCC chẩn đoán dựa vào đâu, khi nào sinh thiết? :: MRI ± AFP tăng ± viêm gan B, C; sinh thiết khi hình ảnh/diễn tiến không điển hình\n- Tầm soát bằng dấu ấn máu? :: Sai, nhiều hệ lụy (nhạy/đặc hiệu thấp)\n- GPB không tương hợp lâm sàng, hình ảnh thì làm gì? :: Xem lại, hội chẩn lại, nghĩ bệnh lý khác để chẩn đoán phân biệt\n- 5 nội dung chẩn đoán? :: Cơ quan mang bướu; mô học; giai đoạn; đặc tính sinh học; nhóm nguy cơ\n- Nhóm nguy cơ cao tuyến tiền liệt khu trú? :: ≥ T2c hoặc Gleason 8–10 hoặc PSA > 20 ng/ml\n- Hạch/bướu di căn là biểu hiện đầu tiên thì làm gì? :: Truy tìm bướu nguyên phát bằng khám và cận lâm sàng hợp lý\n- Biểu hiện không điển hình của ung thư? :: Sụt cân, sốt tái diễn, xanh xao, mệt, đau kéo dài; hạch/bướu di căn; đau lưng yếu hai chân; phát hiện tình cờ"}, {"kind": "foundation", "disease": "", "short": "Triệu chứng học: khái quát", "group": "Khái quát triệu chứng học", "section": 3, "order": 1, "khung": [], "id": "ung-thu-trieu-chung-khai-quat", "title": "Triệu chứng học ung thư: khái quát", "layer": "trieuchung", "module": "ung-buou", "tags": ["triệu chứng học", "biểu hiện ung thư", "hạch vùng", "di căn", "toàn thân", "hội chứng cận u", "dấu hiệu báo động"], "source": "SY5 tr. 8–9, 25, 65–81, 119–122, 127; Y2 tr. 66–67, 71–77; Y5 tr. 106–110, 272; QĐ1514 tr. PDF 37–38, 58–60, 98–99, 108–109, 124, 242–243, 487; 128VĐ mục 64, 75, 114; các trang bệnh (mục 4)", "body": "> [!key] Tóm tắt\n> - Ung thư biểu hiện qua **4 con đường**: bướu **tại chỗ** → **hạch vùng** → **di căn xa** → **toàn thân/cận u**. {{SY5 tr.8, 25}}\n> - **Xâm lấn tại chỗ** là nguyên nhân chính gây triệu chứng và cũng gây tử vong quan trọng; **di căn xa** là nguyên nhân chính gây tử vong. {{Y2 tr.66, 77}}\n> - Không có triệu chứng **đặc hiệu**: triệu chứng thường chung với bệnh lành, nên phải **khám để xác định hay loại trừ**. {{SY5 tr.81}} {{Y5 tr.109}}\n> - Chờ có sụt cân, chán ăn mới nghĩ tới ung thư là sai: lúc đó thường đã muộn. {{SY5 tr.119}}\n> - Chi tiết từng bệnh: tab \"Triệu chứng học\" của trang bệnh; bảng tra theo triệu chứng: [[ung-thu-trieu-chung-theo-co-quan]].\n\n### 1. Bốn nhóm biểu hiện\n| Nhóm | Cơ chế | Biểu hiện điển hình |\n|---|---|---|\n| (a) Tại chỗ | Bướu phát triển, **xâm lấn**, chèn ép | Khối, loét, chảy máu, tắc nghẽn, thủng/dò, đau {{SY5 tr.8}} |\n| (b) Hạch vùng | Di căn theo **bạch mạch** | Hạch to, cứng, dính; phù bạch huyết {{Y2 tr.72–73, 77}} |\n| (c) Di căn xa | Theo **máu**, xoang hốc tự nhiên | Theo cơ quan: phổi, gan, xương, não, màng {{Y2 tr.77}} |\n| (d) Toàn thân – (e) cận u | Bướu và cơ thể tương tác; chất do bướu tiết | Sụt cân, mệt, sốt, thiếu máu; hội chứng cận u {{SY5 tr.122}} {{Y5 tr.109}} |\n\nCơ chế xâm lấn, di căn: [[ung-thu-xam-lan-di-can]]. Cách phân giai đoạn: [[ung-thu-phan-giai-doan-tnm]].\n\n### 2. (a) Biểu hiện tại chỗ\n- **Khối/ chỗ dày lên**: vú (nữ, **đặc biệt > 30 tuổi**), bụng, tay chân, thành bụng, thành ngực, cổ, nách, bẹn {{SY5 tr.75}}\n- **Loét không lành**: da (mặt, thân, núm vú, hậu môn sinh dục, **sẹo phỏng cũ**), niêm mạc hốc miệng {{SY5 tr.71}}\n- **Chảy máu/ tiết dịch bất thường**: âm đạo, đi cầu ra máu, núm vú, mũi {{SY5 tr.73–74}}\n- **Tắc nghẽn → nhiễm trùng, suy chức năng**; **thủng → dò, nhiễm trùng** {{SY5 tr.8}}\n- **Đau**: ==80–85%== bệnh nhân ung thư có đau ở các mức độ {{QĐ1514 tr.PDF 98}}\n  - Nguyên nhân: xâm lấn phá hủy mô quanh, chèn ép thần kinh, phá hủy xương, loét hoại tử niêm mạc, chèn ép ống bài xuất {{QĐ1514 tr.PDF 98–99}}\n  - Đau có thể là **triệu chứng khởi đầu** giúp phát hiện ung thư {{QĐ1514 tr.PDF 99}}\n\n@@fold! Xâm lấn tại chỗ gây gì theo từng cơ quan {{Y2 tr.67}}\n| Cơ quan | Hậu quả |\n|---|---|\n| **Gan** | **Suy gan** (hay gây tử vong); tắc đường mật → vàng da, rối loạn đông máu, chảy máu; vỡ bướu → xuất huyết ổ bụng |\n| **Não, màng não** | **Tăng áp lực nội sọ** (nhức đầu, buồn nôn, nôn); dấu thần kinh định vị: yếu liệt, liệt dây sọ |\n| **Hầu họng** | Nuốt khó, đau, nghẹn; ăn kém → suy kiệt; chảy máu → thiếu máu |\n| **Thanh quản** | Khan tiếng, khó thở; bướu hoại tử rơi vào đường thở → viêm phổi |\n| **Dạ dày, đại trực tràng** | Chảy máu tiêu hóa, tắc nghẽn, thủng ruột, rơi tế bào vào ổ bụng |\n| **Cổ tử cung** | Siết niệu quản → **suy thận sau thận**; dò bàng quang–âm đạo, dò âm đạo–trực tràng |\n@@end\n\n> [!tip] Tam chứng xâm lấn tại chỗ của ung thư cổ tử cung: **phù chân (phù bạch huyết) – thận ứ nước – đau**. {{SY5 tr.9}}\n\n### 3. (b) Hạch vùng\n- **Hạch di căn**: tròn, **sượng, cứng, dính nhau/dính mô**; hạch ≤ 1 cm, mềm, di động, nhất là hai bên: hiếm ác tính; **hạch thượng đòn sờ được là bất thường** (khám vú) {{Y5 tr.7}} {{QĐ3898 tr.21}}\n- **Hạch vùng theo cơ quan**: vú → nách + vú trong; cổ tử cung → chậu; phổi → trung thất {{Y2 tr.72}}\n- **Đầu cổ**: ung thư môi, hốc miệng thường di căn hạch cổ nhóm I–III; khẩu hầu, hạ hầu, thanh quản: nhóm II–IV {{128VĐ 114}}\n- **Hạch Virchow** = hạch trên đòn **trái**; nhiều ung thư xếp như di căn xa {{Y2 tr.72}}\n- Hậu quả: đau chèn ép; **phù bạch huyết** (hạch bẹn, chậu, cạnh ĐM chủ bụng → phù chân; hạch nách → phù tay); hạch bẹn vỡ da, xâm lấn bó mạch đùi → chảy máu {{Y2 tr.77}}\n\n> [!warn] Hạch ở vùng cổ, trên đòn, bẹn **có thể là biểu hiện đầu tiên** (chưa thấy bướu nguyên phát) → phải **truy tìm bướu nguyên phát**. {{SY5 tr.122, 127}} Mọi khối ở cổ ở người lớn, nhất là kéo dài > 2 tuần, cần xem là nghi ác tính đến khi loại trừ. {{128VĐ 114}}\n\n### 4. (c) Di căn xa theo cơ quan\n| Cơ quan | Biểu hiện | Ghi chú |\n|---|---|---|\n| **Phổi** | Suy hô hấp (nặng); di căn phổi đối bên thường **không triệu chứng** | Cơ quan di căn xa nhiều nhất {{Y2 tr.77}} {{QĐ1514 tr.PDF 243}} |\n| **Gan** | Đau hạ sườn phải, vàng da, lú lẫn; gan to; suy gan | Ung thư tiêu hóa di căn gan {{Y5 tr.109}} {{QĐ2549 tr.2}} |\n| **Xương** | Đau tăng khi vận động/ mang vật nặng, **tăng về đêm**; gãy xương bệnh lý; chèn ép tủy | Hạn chế vận động, liệt chi {{Y5 tr.109}} {{Y2 tr.77}} |\n| **Não** | Lú lẫn, động kinh, giảm vận động/ cảm giác; **tăng áp lực nội sọ**, tụt não | Đau đầu ==40–50%==; dấu thần kinh khu trú ==20–40%==; động kinh mới ==10–20%== {{QĐ1514 tr.PDF 124}} |\n| **Cột sống** | Đau trước (==80–90%==), rồi rối loạn cảm giác, vận động, cơ tròn | Có thể là **biểu hiện đầu tiên** của ung thư {{QĐ1514 tr.PDF 58}} |\n| **Phúc mạc, màng phổi** | **Báng bụng** tăng dần; **tràn dịch màng phổi** (khó thở, đau tức ngực) | Gieo rắc theo xoang tự nhiên {{Y2 tr.77}} {{QĐ1514 tr.PDF 37}} |\n| **Da** | Nốt di căn da thành ngực | {{QĐ1514 tr.PDF 243}} |\n\n- **Tình huống đặc biệt**: bỗng đau lưng rồi **yếu dần hai chi dưới** (chèn ép tủy); khối mờ ở phổi hoặc tổn thương gan phát hiện **tình cờ** khi khám sức khỏe {{SY5 tr.122}}\n- **Ung thư chưa rõ nguyên phát**: khoảng ==5–10%== ca; hay biểu hiện ở **gan, phổi, xương, hạch**; triệu chứng không đặc hiệu (chán ăn, sụt cân) {{QĐ1514 tr.PDF 487}}\n- Chi tiết ổ di căn từng bệnh: [Ung thư phổi · 5.2](#/n/ung-thu-phoi/4), [Ung thư vú · 5.2](#/n/ung-thu-vu/4), [Ung thư đại trực tràng · 5.2](#/n/ung-thu-daitruc-trang/4), [Ung thư cổ tử cung · 5.2](#/n/ung-thu-cotucung/4)\n\n### 5. (d) Biểu hiện toàn thân\n- **Mệt mỏi** ==90%==; **sút cân, chán ăn, lo lắng** ==80%== bệnh nhân ung thư {{QĐ1514 tr.PDF 98}}\n- Lý do đến khám không điển hình: **sụt cân không rõ nguyên nhân**, sốt tái đi tái lại, **xanh xao**, mệt mỏi, đau nhức kéo dài {{SY5 tr.122}}\n- **Sụt cân không chủ ý**: dấu hiệu quan trọng; sụt **> 5%** trọng lượng trong 6–12 tháng có ý nghĩa lâm sàng, cần đánh giá {{128VĐ 75}} [Khung STT 99](#/khung/99)\n- **Suy mòn** (cachexia): mất liên tục khối cơ ± mỡ, **không hồi phục** bằng hỗ trợ dinh dưỡng thông thường; gặp ==8–84%== tùy loại ung thư, nhiều ở tiêu hóa và đầu cổ {{QĐ1514 tr.PDF 108}}\n- **Thiếu máu**: mất máu mạn (đại tràng phải: **thiếu máu thiếu sắt**; hầu họng: chảy máu từ tổn thương) {{Y5 tr.272}} {{Y2 tr.67}}\n- **Thể trạng** quyết định chọn điều trị: [[ung-thu-the-trang-kps-ecog]]\n\n> [!warn] Bẫy: sụt cân/chán ăn thường là dấu hiệu **muộn**; ung thư giai đoạn sớm có thể **hoàn toàn không triệu chứng** (phát hiện nhờ tầm soát). {{SY5 tr.119}}\n\n### 6. (e) Hội chứng cận u (tóm tắt)\n- Triệu chứng của ung thư phổi có thể do: **bướu nguyên phát**, **cơ quan di căn**, hoặc **hội chứng cận u**. {{Y5 tr.109}}\n- Hay nêu: tăng canxi máu, SIADH, tăng đông, ngón tay dùi trống/ phì đại xương khớp, nữ hóa tuyến vú, Cushing, Eaton-Lambert, viêm da cơ. {{Y5 tr.106–110}} {{QĐ1514 tr.PDF 243}}\n- Bảng hội chứng – cơ chế – ung thư hay gặp, cùng các hội chứng chèn ép: [[ung-thu-hoi-chung-can-u-va-chen-ep]].\n\n### 7. (f) Dấu hiệu báo động\n> [!red] Báo động ung thư (cần khám sớm)\n> - **7 triệu chứng báo động** (CAUTION, ACS): đổi thói quen ruột/ bàng quang; loét không lành; chảy máu/ tiết dịch bất thường; chỗ dày/ khối u; khó tiêu/ nuốt khó; đổi nốt ruồi; ho dai dẳng/ khàn tiếng. {{SY5 tr.68}} Chi tiết: [[ung-thu-bay-trieu-chung]]\n> - **Hạch** cổ, trên đòn, bẹn ác tính; **sụt cân không rõ nguyên nhân**; đau lưng + yếu dần hai chân. {{SY5 tr.122}}\n\n> [!red] Báo động cấp cứu (xử trí ngay)\n> - **Ho ra máu** > 200 ml/24 giờ; ho ra máu sét đánh. {{QĐ1514 tr.PDF 64}}\n> - **Phù áo khoác, tĩnh mạch cổ nổi**, khó thở (chèn ép TM chủ trên). {{QĐ1514 tr.PDF 68}}\n> - **Đau lưng + rối loạn vận động/ cơ tròn** (chèn ép tủy): MRI trong ==24 giờ==. {{QĐ1514 tr.PDF 59}}\n> - **Nôn máu, phân đen, sốc mất máu**; **xuất huyết âm đạo nhiều**; **vô niệu**; **dò** phân/ nước tiểu ra âm đạo. {{QĐ1514 tr.PDF 71}} {{Y5 tr.61}}\n> - Tăng áp lực nội sọ (đau đầu, nôn, rối loạn ý thức), tăng canxi máu, hội chứng ly giải u: xem [[ung-thu-hoi-chung-can-u-va-chen-ep]].\n\n- Tài liệu **không nêu tiêu chí chuyển tuyến chung** cho ung thư. Riêng vú: nghi ngờ ác tính → chuyển chuyên gia + hình ảnh/ lấy mẫu {{QĐ3898 tr.29}}\n\n### 8. Liên hệ sang từng bệnh\n| Bệnh | Triệu chứng chính | Tab chi tiết |\n|---|---|---|\n| Ung thư vú | **Cục ở vú** không đau; tiết dịch núm vú; da cam, tụt núm; hạch nách/ thượng đòn {{QĐ3898 tr.19}} | [Ung thư vú · 5.2](#/n/ung-thu-vu/4) · [Khung STT 85](#/khung/85) |\n| Ung thư cổ tử cung | **Xuất huyết âm đạo bất thường**; huyết trắng hôi; muộn: dò, suy thận, phù chân {{Y5 tr.61}} | [Ung thư cổ tử cung · 5.2](#/n/ung-thu-cotucung/4) · [Khung STT 87](#/khung/87) |\n| Ung thư đại trực tràng | **Đổi thói quen đi tiêu**, nhầy máu, thiếu máu; mót rặn (trực tràng) {{QĐ2549 tr.2}} {{Y5 tr.272}} | [Ung thư đại trực tràng · 5.2](#/n/ung-thu-daitruc-trang/4) · [Khung STT 61](#/khung/61) |\n| Ung thư phổi | **Không đặc hiệu**; ho, ho ra máu, khó thở; hạch/ di căn; cận u {{Y5 tr.109}} | [Ung thư phổi · 5.2](#/n/ung-thu-phoi/4) · [Khung STT 41](#/khung/41) |\n\n### Điểm hay thi\n> [!warn]\n> - Triệu chứng ung thư do **xâm lấn tại chỗ** là chính; **di căn xa** là nguyên nhân tử vong chính (phổi → suy hô hấp, gan → suy gan, não → tăng áp lực nội sọ).\n> - Quan niệm \"ung thư phải có chán ăn, sụt cân\" là **sai**; ung thư sớm thường không triệu chứng.\n> - Biểu hiện **không điển hình**: sụt cân, sốt tái phát, xanh xao, mệt, đau kéo dài; **hạch/ bướu di căn** chưa thấy nguyên phát; đau lưng rồi yếu hai chân; phát hiện tình cờ.\n> - **Hạch Virchow** = hạch trên đòn **trái**; hạch di căn: cứng, sượng, dính; hạch thượng đòn sờ được là bất thường.\n> - Ung thư di căn cột sống: **đau là triệu chứng đầu tiên** (80–90%), có thể trước nhiều tuần; chụp MRI sớm.\n> - **Suy mòn**: mất cơ ± mỡ, không hồi phục bằng dinh dưỡng thông thường.\n> - Cổ tử cung xâm lấn tại chỗ: tam chứng phù chân – thận ứ nước – đau; tử vong thường do **suy thận sau thận**.\n> - Ung thư phổi: không có triệu chứng đặc hiệu, nên thường chẩn đoán muộn."}, {"kind": "foundation", "disease": "", "short": "Triệu chứng → ung thư (bảng)", "group": "Khái quát triệu chứng học", "section": 3, "order": 2, "khung": [], "id": "ung-thu-trieu-chung-theo-co-quan", "title": "Từ triệu chứng đến ung thư: bảng theo cơ quan/hệ", "layer": "trieuchung", "module": "ung-buou", "tags": ["triệu chứng", "ung thư", "bảng tra", "khung 128 vấn đề", "chẩn đoán phân biệt", "báo động"], "source": "SY5 tr. 68–80, 122; Y5 tr. 6–7, 61, 106–112, 272, 286; Y2 tr. 67, 72, 77; QĐ1514 tr. PDF 37–38, 58, 65, 68–72, 77, 124–125; QĐ2549 tr. 2; QĐ3898 tr. 19–21, 29; 128VĐ mục 64, 70, 72, 75, 79, 114; khung QĐ 22", "body": "> [!key] Cách dùng bảng\n> - Đọc theo **triệu chứng đến khám** → ung thư cần nghĩ tới → vì sao → mở trang bệnh (nếu có) và vấn đề khung thi.\n> - Triệu chứng nào cũng **thường gặp hơn ở bệnh lành**; bảng chỉ nêu ung thư **cần loại trừ**, không thay chẩn đoán. {{SY5 tr.81}}\n> - Chẩn đoán xác định = **mô bệnh học**; quy trình: [[ung-thu-tiep-can-chan-doan]]. Phần tổng quát: [[ung-thu-trieu-chung-khai-quat]], bảy triệu chứng: [[ung-thu-bay-trieu-chung]].\n> - Chỉ **4 bệnh có trang riêng** (vú, cổ tử cung, đại trực tràng, phổi). Ung thư khác chỉ được **gọi tên** trong nguồn, ghi \"—\" ở cột trang bệnh.\n> - Dấu † ở cột Khung = liên kết khung do **người soạn gợi ý** theo tên vấn đề (xem hộp cuối bài).\n\n@@tabs\n@@tab Tiêu hóa – ổ bụng\n| Triệu chứng / dấu hiệu | Nghĩ tới ung thư | Vì sao | Trang bệnh | Khung STT |\n|---|---|---|---|---|\n| **Đi cầu ra máu**, máu lẫn trong phân | **Đại trực tràng** (phân biệt trĩ, viêm, dò) | Bướu chảy máu; trực tràng: tiêu máu, mót rặn {{SY5 tr.69, 73}} {{Y5 tr.286}} | [Ung thư đại trực tràng · 5.2](#/n/ung-thu-daitruc-trang/4) | [57](#/khung/57), [64](#/khung/64) |\n| **Đổi thói quen ruột**: táo bón/ tiêu chảy kéo dài, xen kẽ, **mót rặn kéo dài**; phân nhỏ | Đại tràng (trái), trực tràng | U trái: giảm khẩu kính phân, tắc ruột; **hẹp lòng ruột (u ác tính)** là một cơ chế táo bón {{Y5 tr.272}} {{128VĐ 72}} | [Ung thư đại trực tràng · 5.2](#/n/ung-thu-daitruc-trang/4) | [61](#/khung/61) |\n| **Thiếu máu thiếu sắt**, mệt, sụt cân, đau bụng; đại tràng phải thường **im lặng** | Đại tràng phải | U phải chảy máu rỉ rả, ít gây tắc {{Y5 tr.272}} | [Ung thư đại trực tràng · 5.2](#/n/ung-thu-daitruc-trang/4) | [7†](#/khung/7), [57](#/khung/57) |\n| **Nôn máu**, phân đen | Thực quản, dạ dày–ruột, đường mật; gan có giãn vỡ tĩnh mạch thực quản | Tổn thương mạch của khối u {{QĐ1514 tr.PDF 71}} | — | [56†](#/khung/56) |\n| Khó tiêu, đầy bụng, đau thượng vị | **Dạ dày** (phân biệt viêm, loét) | {{SY5 tr.77}} | — | [52†](#/khung/52) |\n| Nuốt vướng, nuốt đau; **nuốt nghẹn tăng dần** | Amiđan, hạ hầu; **thực quản** | Bướu hầu họng tắc đường tiêu hóa trên {{SY5 tr.77}} {{Y2 tr.67}} | — | [50†](#/khung/50) |\n| **Khối ở bụng** (tự sờ thấy hoặc tình cờ hình ảnh) | U gan, u ổ bụng: lymphoma/ sarcoma, bướu tiêu hóa (dạ dày, đại tràng, tụy, gan), phụ khoa (buồng trứng, tử cung), nguyên bào thần kinh | Nhiều cơ quan chồng lấp; phân biệt lành/ ác {{128VĐ 64}} | ĐTT: sờ u qua thành bụng {{QĐ2549 tr.2}} | [54](#/khung/54) |\n| Vàng da, **gan to**, đau hạ sườn phải | **Di căn gan** (phổi, đại trực tràng) hoặc u gan | Gan nhận máu cửa từ ống tiêu hóa; bướu xâm lấn gan, tắc mật {{Y5 tr.109}} {{QĐ2549 tr.2}} {{Y2 tr.67}} | [phổi](#/n/ung-thu-phoi/4), [đại trực tràng](#/n/ung-thu-daitruc-trang/4) | [62†](#/khung/62) |\n| **Báng bụng** | Gieo rắc phúc mạc | Di căn theo xoang tự nhiên, báng bụng tăng dần {{Y2 tr.77}} | ĐTT: báng bụng, gan to {{QĐ2549 tr.2}} | [53†](#/khung/53) |\n@@tab Hô hấp – đầu cổ\n| Triệu chứng / dấu hiệu | Nghĩ tới ung thư | Vì sao | Trang bệnh | Khung STT |\n|---|---|---|---|---|\n| **Ho dai dẳng**, ho khan kéo dài; **nam > 40, hút thuốc**; kháng sinh không đáp ứng | **Phổi** | Ho dai dẳng ở nam, hút thuốc → phổi; giai đoạn sớm âm thầm {{SY5 tr.79}} {{QĐ1514 tr.PDF 242}} | [Ung thư phổi · 5.2](#/n/ung-thu-phoi/4) | [40](#/khung/40) |\n| **Ho ra máu** | Phổi (u rốn phổi, xâm lấn mạch lớn); ung thư đầu mặt cổ (hạ họng, thanh quản, khí quản); thực quản, u trung thất vỡ vào khí phế quản | Bướu chảy máu trong lòng phế quản {{QĐ1514 tr.PDF 65}} | [Ung thư phổi · 5.2](#/n/ung-thu-phoi/4) | [41](#/khung/41) |\n| **Khàn tiếng > 3 tuần** (nam, hút thuốc, rượu) | **Thanh quản**; phổi (hạch trung thất chèn thần kinh quặt ngược) | Bướu ảnh hưởng dây thanh; thần kinh quặt ngược bị liệt {{SY5 tr.79}} {{Y5 tr.109}} | [Ung thư phổi · 5.2](#/n/ung-thu-phoi/4) | [39†](#/khung/39) |\n| **Bất thường X quang ngực**: nốt/ khối, hạch trung thất, tràn dịch | Ung thư phổi; di căn phổi | Có thể phát hiện **tình cờ** {{Y5 tr.109}} {{SY5 tr.122}} | [Ung thư phổi · 5.2](#/n/ung-thu-phoi/4) | [47](#/khung/47) |\n| **Tràn dịch màng phổi** | Phổi, **vú**; lymphoma, u trung mô, ống tiêu hóa, buồng trứng, tử cung | Tế bào ung thư xâm nhiễm màng phổi, tiết dịch hoặc tắc mạch {{QĐ1514 tr.PDF 37–38}} | [Ung thư phổi · 5.2](#/n/ung-thu-phoi/4) | [46](#/khung/46) |\n| Phù áo khoác, tĩnh mạch cổ nổi, khó thở | **Chèn ép TM chủ trên**: phổi, u trung thất, thực quản, thanh quản–hạ họng, NHL, vú | Bướu hoặc hạch chèn ép/ xâm lấn tĩnh mạch {{QĐ1514 tr.PDF 68–69}} | [Ung thư phổi · 5.2](#/n/ung-thu-phoi/4) | — |\n| **Thở rít**, ho, khó thở, viêm phổi tái diễn | Phổi (bướu trung tâm tắc phế quản) | {{Y5 tr.109}} | [Ung thư phổi · 5.2](#/n/ung-thu-phoi/4) | [43†](#/khung/43) |\n| Đau vai nhiều | Bướu đỉnh phổi (Pancoast) | Xâm lấn đám rối cánh tay, hủy xương sườn 1 {{Y5 tr.112}} | [Ung thư phổi · 5.2](#/n/ung-thu-phoi/4) | — |\n| **Chảy máu mũi** | Bệnh huyết học; vòm hầu; hốc mũi | {{SY5 tr.74}} | — | [6†](#/khung/6) |\n| **Khối ở cổ** (kéo dài > 2 tuần ở người lớn) | Tuyến giáp; hạch di căn từ ung thư tế bào gai đầu cổ; lymphoma; tuyến nước bọt | Mọi khối cổ nên xem nghi ác tính đến khi loại trừ {{128VĐ 114}} | — | [96](#/khung/96) |\n@@tab Vú – phụ khoa\n| Triệu chứng / dấu hiệu | Nghĩ tới ung thư | Vì sao | Trang bệnh | Khung STT |\n|---|---|---|---|---|\n| **Cục ở vú**, thường không đau; nữ **> 30 tuổi** | **Vú** | Tự sờ thấy cục ở vú là biểu hiện thường gặp nhất {{SY5 tr.75, 235}} {{QĐ3898 tr.19}} | [Ung thư vú · 5.2](#/n/ung-thu-vu/4) | [85](#/khung/85) |\n| **Chảy máu/ tiết dịch núm vú** | Vú (phân biệt viêm ống dẫn sữa, bướu nhú trong ống) | Chảy dịch máu núm vú là dấu nghi ngờ ác tính {{SY5 tr.74}} {{QĐ3898 tr.29}} | [Ung thư vú · 5.2](#/n/ung-thu-vu/4) | [85](#/khung/85) |\n| Da **sần da cam**, tụt núm, co kéo da; đỏ da vú **không đau, không nóng** | Vú (thể viêm: đỏ da lan rộng) | Xâm lấn da, bạch mạch {{QĐ3898 tr.20}} | [Ung thư vú · 5.2](#/n/ung-thu-vu/4) | [85](#/khung/85) |\n| **Hạch nách/ thượng đòn** cứng, sượng, dính | Vú (hạch vùng) | Hạch vùng của vú: nách + vú trong {{Y5 tr.7}} {{Y2 tr.72}} | [Ung thư vú · 5.2](#/n/ung-thu-vu/4) | [85](#/khung/85) |\n| **Xuất huyết âm đạo**: sau giao hợp, sau mãn kinh, giữa kỳ kinh, rong kinh/ rong huyết | **Cổ tử cung** | Triệu chứng hay gặp nhất; có thể không triệu chứng giai đoạn sớm {{SY5 tr.73}} {{Y5 tr.61}} | [Ung thư cổ tử cung · 5.2](#/n/ung-thu-cotucung/4) | [87](#/khung/87) |\n| **Huyết trắng** rỉ rả, về sau hôi, lẫn máu | Cổ tử cung | Hoại tử/ bội nhiễm bướu {{Y5 tr.61}} | [Ung thư cổ tử cung · 5.2](#/n/ung-thu-cotucung/4) | [89†](#/khung/89) |\n| **Khối vùng chậu** | Cổ tử cung lan chu cung, vách chậu, hạch chậu; nội mạc, buồng trứng, trực tràng xâm lấn | Xâm lấn sang bên (chu cung, vách chậu) thường gặp và nguy hiểm nhất {{Y5 tr.58}}; các nguyên nhân khác của khối vùng chậu {{128VĐ 96}} | [Ung thư cổ tử cung · 5.2](#/n/ung-thu-cotucung/4) | [91](#/khung/91) |\n| **Phù chân**, tiểu ít/ vô niệu; **dò** phân hoặc nước tiểu ra âm đạo | Cổ tử cung muộn | Siết niệu quản → thận ứ nước, suy thận; thủng vách {{Y5 tr.61}} {{Y2 tr.67}} | [Ung thư cổ tử cung · 5.2](#/n/ung-thu-cotucung/4) | [70†](#/khung/70) |\n| **Không triệu chứng** (khám định kỳ) | Vú, cổ tử cung, đại trực tràng | Sớm thường im lặng: phát hiện nhờ tầm soát | [vú](#/n/ung-thu-vu/8), [cổ tử cung](#/n/ung-thu-cotucung/8), [đại trực tràng](#/n/ung-thu-daitruc-trang/8) | [85](#/khung/85), [92](#/khung/92), [64](#/khung/64) |\n@@tab Tiết niệu – da\n| Triệu chứng / dấu hiệu | Nghĩ tới ung thư | Vì sao | Trang bệnh | Khung STT |\n|---|---|---|---|---|\n| **Tiểu ra máu**, tiểu khó, buốt, gắt, không hết | **Bàng quang**; **tuyến tiền liệt** (đái xẹp không hoàn toàn) | {{SY5 tr.69–70}} | — | [67†](#/khung/67), [66†](#/khung/66) |\n| Suy thận cấp, vô niệu (tắc nghẽn sau thận) | Bướu/ hạch chèn đường bài xuất: đại trực tràng, thận, buồng trứng, **cổ tử cung**, sau phúc mạc, bàng quang, tuyến tiền liệt | {{QĐ1514 tr.PDF 77}} | [Ung thư cổ tử cung · 5.2](#/n/ung-thu-cotucung/4) | [65†](#/khung/65), [70†](#/khung/70) |\n| **Khối ở bẹn bìu** | **Tinh hoàn** (trong nhóm nguyên nhân khối bìu) | {{128VĐ 79}} | — | [59](#/khung/59) |\n| **Hạch bẹn** to | Ung thư sinh dục ngoài (dương vật, âm hộ), da chi dưới | Hạch bẹn là nơi thất bại chính của nhóm này {{Y2 tr.77}} | — | [59](#/khung/59) |\n| **Vết loét không lành**: da mặt, thân, núm vú, hậu môn sinh dục, **sẹo phỏng cũ**; lưỡi, hốc miệng | Ung thư **lưỡi**, **da mặt**, da trên sẹo cũ | {{SY5 tr.71–72}} | — | — |\n| **Nốt ruồi** lớn nhanh, đổi màu, ngứa, loét, chảy máu khi đụng | Tài liệu **không nêu tên bệnh** | {{SY5 tr.76}} | — | — |\n@@tab Xương – thần kinh – toàn thân\n| Triệu chứng / dấu hiệu | Nghĩ tới ung thư | Vì sao | Trang bệnh | Khung STT |\n|---|---|---|---|---|\n| **Đau xương** tăng khi vận động/ mang vật nặng, **tăng về đêm**; gãy xương bệnh lý | **Di căn xương**: phổi, vú, tuyến tiền liệt, lymphoma, dạ dày | Xương nhiều máu, có tĩnh mạch Batson; đau khi vận động gợi ý mất vững cột sống {{Y2 tr.69–70}} {{Y5 tr.109}} {{QĐ1514 tr.PDF 58}} | [phổi](#/n/ung-thu-phoi/4), [vú](#/n/ung-thu-vu/4) | [108](#/khung/108), [31†](#/khung/31) |\n| **Đau lưng rồi yếu dần hai chân**, rối loạn cơ tròn | **Chèn ép tủy** do di căn cột sống | Đau đến trước nhiều tuần; MRI sớm {{SY5 tr.122}} {{QĐ1514 tr.PDF 58}} | — | [18†](#/khung/18) |\n| **Đau đầu**, nôn, lú lẫn, **động kinh mới**, liệt khu trú | **Di căn não** (phổi, vú...) | Tăng áp lực nội sọ, dấu thần kinh khu trú {{Y5 tr.109}} {{QĐ1514 tr.PDF 124–125}} | [phổi](#/n/ung-thu-phoi/4), [vú](#/n/ung-thu-vu/4) | [15†](#/khung/15), [20†](#/khung/20) |\n| **Sụt cân** không rõ nguyên nhân | Ung thư ống tiêu hóa, tụy, gan mật; bệnh ác tính ngoài tiêu hóa | Dấu ung thư; sụt > 5% trong 6–12 tháng cần đánh giá {{128VĐ 75}} | — | [99](#/khung/99) |\n| Sốt tái đi tái lại, **xanh xao**, mệt, đau nhức kéo dài | **Không đặc hiệu**: nguồn không nêu tên ung thư | Biểu hiện không điển hình {{SY5 tr.122}} | — | — |\n| **Đau do ung thư** | Mọi ung thư (nhất là di căn xương) | Xâm lấn, chèn ép thần kinh, phá hủy xương {{QĐ1514 tr.PDF 98–99}} | — | [108](#/khung/108) |\n| **Bất thường bạch cầu** | Bệnh bạch cầu, lymphoma | Nhóm bất thường ác tính của bạch cầu {{128VĐ 8}} | — | [8](#/khung/8) |\n@@end\n\n> [!red] Triệu chứng cần xử trí ngay (đã có trong nguồn)\n> - **Ho ra máu nhiều**, **phù áo khoác/ TM cổ nổi**, **đau lưng + yếu chân** → chi tiết [[ung-thu-hoi-chung-can-u-va-chen-ep]].\n> - **Xuất huyết âm đạo nhiều gây thiếu máu cấp**, vô niệu, dò → [Ung thư cổ tử cung · 5.2](#/n/ung-thu-cotucung/4). {{Y5 tr.61}}\n> - **Nôn máu/ phân đen/ sốc mất máu**; tắc ruột, thủng u (đại trực tràng) → [Ung thư đại trực tràng · 5.2](#/n/ung-thu-daitruc-trang/4). {{QĐ1514 tr.PDF 71}} {{Y5 tr.272}}\n\n> [!ext] Người soạn gợi ý (không có trong nguồn)\n> - Dấu † ở cột Khung (STT 6, 7, 15, 18, 20, 31, 39, 43, 50, 52, 53, 56, 62, 65, 66, 67, 70, 89) là liên kết do **người soạn gợi ý** theo tên vấn đề trong khung, vì cùng triệu chứng; nguồn ung bướu **không** gắn các STT này với ung thư.\n> - Khung có ghi chú ung thư cho STT 8, 41, 47, 54, 59, 64, 85, 91, 92, 96, 99, 108; STT 40, 46, 57, 61, 87 do trang bệnh đã liên kết sẵn.\n> - Nội dung \"triệu chứng → ung thư\" và \"vì sao\" đều lấy từ nguồn; chỗ nào nguồn không nêu bệnh thì ghi \"—\" hoặc \"tài liệu không nêu\".\n\n### Điểm hay thi\n> [!warn]\n> - **Xuất huyết âm đạo** sau giao hợp/ sau mãn kinh → cổ tử cung; **nuốt nghẹn tăng dần** → thực quản; **khàn tiếng > 3 tuần** → thanh quản; **ho dai dẳng** nam > 40 hút thuốc → phổi.\n> - **Cục ở vú** nữ > 30 tuổi phải nghi ung thư; chảy **dịch máu** núm vú một bên là dấu nghi ngờ.\n> - **Hạch thượng đòn** sờ được là bất thường; hạch Virchow ở bên **trái**.\n> - Đại tràng **phải** thiếu máu thiếu sắt, im lặng; đại tràng **trái** đổi thói quen, phân nhỏ, tắc ruột; **trực tràng** tiêu máu, mót rặn.\n> - **Tràn dịch màng phổi ác tính** trong ung thư phổi = M1a; nguyên nhân hay gặp: ung thư biểu mô tuyến phổi, tuyến vú.\n> - Chảy máu mũi: nhớ nhóm **bệnh huyết học** trước ung thư vòm hầu, hốc mũi.\n> - Đau lưng + yếu dần hai chân: **chèn ép tủy** (di căn cột sống), cần MRI sớm.\n> - Triệu chứng chung với bệnh lành: không kết luận từ triệu chứng, cần **khám xác định hay loại trừ**."}, {"kind": "foundation", "disease": "", "short": "Xâm lấn và di căn", "group": "Giải phẫu bệnh, xâm lấn, di căn, miễn dịch", "section": 0, "order": 3, "khung": [], "id": "ung-thu-xam-lan-di-can", "title": "Sự xâm lấn và di căn của ung thư", "layer": "nen", "module": "ung-buou", "tags": ["xam-lan", "di-can", "hach", "thuyet-co-hoc", "hat-giong-va-dat", "hach-tren-don", "virchow"], "source": "Y2 tr. 38–42, 64–77; SY2 tr. 297–299, 394–427; SY5 tr. 1–27", "body": "> [!key] Ý chính\n> - **Xâm lấn** (mô bướu ăn vào mô lân cận, phá vỏ bao + màng đáy) khác **chèn ép** (chỉ to ra, vỏ bao còn nguyên) {{Y2 tr.64}}.\n> - **Di căn** = *tăng trưởng* của ung thư ở nơi xa; tế bào trong máu/lymphô chưa chắc đã là di căn {{Y2 tr.67}} {{SY5 tr.10}}.\n> - 3 đường: **lymphô** (hạch), **máu** (di căn xa, đường chính), **xoang/hốc tự nhiên** (gieo rắc) {{Y2 tr.67}}.\n> - **Hạt giống và đất** (Paget 1889): đường cơ học chỉ đưa tế bào tới; cơ quan đích có hợp \"đất\" mới thành ổ di căn {{Y2 tr.73}}.\n> - Hậu quả: xâm lấn tại chỗ gây phần lớn triệu chứng; di căn xa gây tử vong do suy cơ quan.\n\n### 1. Xâm lấn tại chỗ\n#### 1.1 Bốn cơ chế {{Y2 tr.64–65}} {{SY5 tr.4–5}}\n1. **Tăng áp lực** tại bướu (to nhanh) đẩy tế bào vào mô quanh.\n2. **Giảm cadherin** (E-cadherin ở desmosome) → mất gắn bó giữa tế bào, dễ tách rời. {{Y2 tr.38}}: lực dính của carcinôm gai giảm ≈ 4 lần (thiếu Ca++, có enzym phân giải).\n3. **Giảm gắn mô nền/màng đáy** (integrin–laminin, fibronectin): bướu/nguyên bào sợi tiết ==MMP==, hyaluronidase, protease, collagenase {{Y2 tr.40}}.\n4. **Di chuyển bằng chân giả kiểu amíp** vào mô nền.\n\n- Hay lan dọc **bờ cơ quan, bao thần kinh, bao mạch** (ít cản trở nhất); ít xâm nhập: sụn, vách động mạch, vách thần kinh, cân cơ {{Y2 tr.39}}.\n\n#### 1.2 Ăn lan và rào cản giải phẫu {{Y2 tr.65–66}} {{SY5 tr.6–7}}\n- Rào cản: lớp cơ dày, xương/màng xương, sụn, cân, mạc, vỏ bao cơ quan, thanh mạc ruột. Mô lỏng lẻo, không rào cản → dễ ăn lan.\n- Yếu tố ảnh hưởng: loại GPB (carcinôm tuyến/gai, sarcôm, mêlanôm…), vị trí bướu, rào cản tự nhiên {{SY5 tr.7}}.\n\n| Ung thư | Rào cản / ý nghĩa |\n|---|---|\n| Nội mạc tử cung | Lớp cơ tử cung → lâu mới xâm lấn qua cơ + thanh mạc; phát hiện sớm, tiên lượng tốt |\n| Cổ tử cung | Gần bàng quang/trực tràng nhưng ít xâm lấn trực tràng (vách âm đạo–trực tràng chắc); hay lan âm đạo, thân tử cung, chu cung |\n| Sarcôm cơ vân | Lan trong cùng khoang giải phẫu trước |\n| Xương | Khó vượt màng xương |\n| Vú | Cân ngực là rào cản với cơ thành ngực |\n| Tiêu hóa | Đoạn không có thanh mạc dễ ra ngoài (thực quản sớm hơn dạ dày, đại tràng) |\n| Thanh môn | Sụn thanh quản {{SY5 tr.7}} |\n\n#### 1.3 Hậu quả xâm lấn tại chỗ {{Y2 tr.66–67}} {{SY5 tr.8–9}}\n- Chảy máu, đau, **tắc nghẽn** (→ nhiễm trùng), **thủng** (dò, nhiễm trùng); là nguyên nhân chính gây triệu chứng và tử vong.\n@@fold Theo cơ quan\n- **Gan**: suy gan (hay gây tử vong); tắc đường mật → vàng da, rối loạn đông máu; vỡ bướu → xuất huyết ổ bụng.\n- **Não/màng não**: tăng áp lực nội sọ (nhức đầu, buồn nôn, nôn), dấu thần kinh định vị.\n- **Hầu họng**: nuốt khó/đau/nghẹn, suy kiệt, thiếu máu. **Thanh quản**: khan tiếng, khó thở; bướu hoại tử rơi vào đường thở → viêm phổi.\n- **Dạ dày, đại trực tràng**: chảy máu tiêu hóa, tắc, thủng, rơi tế bào vào ổ bụng.\n- **Cổ tử cung**: siết niệu quản → {r|suy thận sau thận} (nguyên nhân tử vong thường gặp nhất nếu không điều trị); dò bàng quang–âm đạo, dò âm đạo–trực tràng. SY5: tam chứng **phù chân – thận ứ nước – đau** {{SY5 tr.9}}.\n@@end\n\n### 2. Di căn\n#### 2.1 Thuyết cơ học: ba đường {{Y2 tr.67}} {{SY5 tr.11}}\n- **Lymphô** (di căn hạch) · **máu** (di căn xa, chính) · **xoang/hốc tự nhiên**. Hai đường đầu khó tách vì lymphô đổ vào máu ở ống ngực và có nối mạch–lymphô trong hạch {{Y2 tr.39}}.\n\n@@tabs\n@@tab Đường máu\n**Dòng thác** {{Y2 tr.68}}:\n1. Xâm lấn quanh bướu, giảm kết dính, tách khỏi màng đáy.\n2. Vào lòng mạch, **sống sót trong tuần hoàn** (lực cơ học, tế bào miễn dịch); tế bào đơn độc khó sống → kết khối/huyết khối bướu.\n3. **Kẹt ở mao mạch** cơ quan xa, thoát mạch.\n4. **Phát triển** ở cơ quan xa: bước quan trọng nhất, chỉ tỷ lệ nhỏ hoàn tất (ổ di căn trải qua thời kỳ vô mạch → tạo mạch nhờ TAF; ≈ ==0,01%== tế bào tróc thành ổ di căn {{Y2 tr.40}} {{Y2 tr.50}}).\n\n- SY2: 6 bước: tách khỏi cộng đồng → xâm lấn mô liên kết → vào lòng mạch (intravasation) → thoát NK/miễn dịch → gắn nội mô → thoát mạch (extravasation) {{SY2 tr.298}}.\n- **Tĩnh mạch** dễ bị xâm lấn hơn động mạch (thành mỏng, áp lực thấp); **mao mạch** là nơi kẹt dễ nhất.\n@@tab Vì sao phổi, gan, xương, não\n| Cơ quan | Giải thích {{Y2 tr.69–70}} {{SY5 tr.16–18}} |\n|---|---|\n| **Phổi** | Tĩnh mạch → tim phải → ĐM phổi → mao mạch phổi dày đặc: nơi di căn xa **nhiều nhất**; nốt \"bong bóng bay\", nhiều ở hai đáy |\n| **Gan** | Nhận máu tĩnh mạch cửa → ung thư tiêu hóa (đại trực tràng, dạ dày) kẹt ở xoang gan; có thể theo ĐM gan |\n| **Xương** | Máu và mao mạch nhiều; **tĩnh mạch Batson** (xương, thân sống, chậu, liên sườn) → tuyến tiền liệt, vú di căn thẳng vào xương |\n| **Não** | Nhiều mao mạch tận, nhiều máu |\n- Tế bào qua mao mạch phổi → tĩnh mạch phổi → tim trái → đại tuần hoàn (gan, xương, não, thận, thượng thận).\n- Tuyến tiền liệt: đám rối trước xương cùng → cột sống thấp, xương chậu.\n@@tab 4 kiểu theo dẫn lưu tĩnh mạch\n- **I (phổi)**: phổi → TM phổi → tim trái → gan, não, xương, thận, thượng thận.\n- **II (gan)**: gan → TM trên gan → chủ dưới → tim phải → phổi.\n- **III (chủ)**: tử cung, thận… → TM chủ → phổi.\n- **IV (cửa)**: ống tiêu hóa → gan → phổi → đại tuần hoàn.\n- Hiếm di căn: lách, vú, ống tiêu hóa, cơ vân {{Y2 tr.40–41}}.\n@@end\n\n#### 2.2 Di căn hạch {{Y2 tr.71–73}} {{SY5 tr.12–15}}\n- Tế bào (kèm EMT) theo dòng dịch vào mao mạch lymphô (khe giữa tế bào nội mạc; khoảng hở Archard {{Y2 tr.40}}) → xoang vỏ hạch qua mạch **tới**.\n- Số phận: kẹt → ổ di căn hạch · sang hạch khác qua mạch **đi** (di căn **nhảy cóc**) · xuyên hạch vào máu (→ nguy cơ di căn xa tăng) · bị hủy · ngủ yên.\n- Carcinôm, mêlanôm di căn hạch nhiều; sarcôm ít hơn.\n- Hạch vùng theo bó mạch: **vú → nách + vú trong**; **cổ tử cung → chậu**; **phổi → trung thất**.\n- Hạch **bẹn**: sinh dục ngoài, chi dưới; hạch **cạnh ĐM chủ bụng**: vùng chậu.\n\n> [!red] Hạch Virchow (Troisier) = hạch trên đòn TRÁI\n> - Trạm cuối ống ngực trước khi đổ vào TM dưới đòn trái; ống ngực dẫn lưu toàn bộ cơ quan dưới cơ hoành, nửa ngực–đầu cổ–chi trên trái.\n> - Có hạch này → rất có thể đã vào đại tuần hoàn; nhiều ung thư xếp **như di căn xa** {{Y2 tr.72}}.\n> - Hạch vùng = lan tràn tại vùng; di căn xa = lan toàn thân {{Y2 tr.40}}.\n\n#### 2.3 Di căn theo xoang, hốc tự nhiên {{Y2 tr.42, 73}} {{SY5 tr.11}}\n- **Phúc mạc** (gieo rắc thường gặp nhất; rồi màng phổi, màng tim, dưới màng nhện, khớp): dạ dày, đại tràng xuyên thanh mạc; **buồng trứng** → báng bụng, mạc nối lớn bắt tế bào, rơi xuống chậu (khối Bloomberg (theo nguồn) sờ qua thăm khám) → mổ buồng trứng lấy cả **mạc nối lớn**. Dạ dày → buồng trứng.\n- **Phổi** → màng phổi tạng → tràn dịch màng phổi, nốt gieo rắc.\n- **Não/màng não** gieo rắc theo dịch não tủy (nguyên tủy bào).\n- Hiếm: ghép theo dụng cụ mổ/đường kim sinh thiết.\n\n#### 2.4 Hạt giống và đất (Paget 1889) {{Y2 tr.73–75}} {{SY5 tr.21–22}}\n- Cùng đường cơ học nhưng khuynh hướng khác nhau (tuyến tiền liệt → xương; bàng quang ít di căn xa) → thuyết cơ học đơn thuần không đủ.\n- Tế bào tới nơi vẫn khó mọc do miễn dịch + vi môi trường không hợp; dễ thành khối nếu vi môi trường/nguồn gốc mô tương đồng (gan nhiều yếu tố tăng trưởng; xương hợp tuyến tiền liệt).\n\n| Ung thư | Nơi di căn hay gặp |\n|---|---|\n| Vú | Xương, phổi (màng phổi), gan; ít: não, thượng thận. ER(+) → xương; ER(−) → tạng |\n| Phổi tế bào nhỏ | Gan, não, thượng thận, tụy, phổi đối bên, xương |\n| Phổi không tế bào nhỏ | Phổi đối bên, não; thượng thận, gan, xương |\n| Tuyến tiền liệt | Xương, tổn thương **tạo cốt bào** (vú: hủy xương) |\n| Đại tràng | Gan (cửa), phúc mạc, phổi |\n| Tụy | Gan, phổi, mô quanh |\n| Buồng trứng | Gieo rắc khoang phúc mạc |\n| Sarcôm | Chủ yếu phổi |\n| Glioma | Hiếm ra ngoài; xâm lấn tại hệ thần kinh trung ương |\n| Nguyên bào thần kinh | Xương, gan, phổi; đôi khi tự thoái triển |\n- Mêlanôm di căn nhiều nội tạng; carcinôm gai hướng phổi {{Y2 tr.74, 76}}.\n\n#### 2.5 Mô hình động sinh học phân tử {{Y2 tr.74–76}} {{SY5 tr.23–24}}\n- **3 nhóm gen**: (1) **sinh bướu** (cần nhưng chưa đủ) · (2) **tiến triển di căn** (chọn lọc ở bướu nguyên phát, thêm chức năng di căn) · (3) **độc lực di căn** (chọn bởi cơ quan xa, không vai trò ở bướu nguyên phát; giúp thoát \"ngủ đông\").\n- Tế bào mới tới thường **ngủ đông** → di căn xa có thể xuất hiện rất lâu sau điều trị đầu {{Y2 tr.75}} → lý do **tái khám dài hạn** dù diện cắt âm tính.\n\n### 3. Thời điểm, tái phát {{Y2 tr.41–42}}\n- Không có quy luật giữa kích thước bướu và thời điểm di căn; **CUPS** (carcinoma unknown primary site) = di căn xa khi nguyên phát chưa có triệu chứng.\n- Ổ di căn so với nguyên phát: thường giống (giáp thể nhú qua hạch cổ; thận tế bào sáng qua xương), có thể kém biệt hóa hơn, hiếm biệt hóa hơn.\n- **Tái phát thật** = tại chỗ, thường trên sẹo mổ (không lấy hết phần ngoại biên); vài tuần đến vài năm.\n\n### 4. Hậu quả của di căn {{Y2 tr.77}} {{SY5 tr.25}}\n| Vị trí | Hậu quả |\n|---|---|\n| Phổi / gan / não | Suy hô hấp / suy gan / tăng áp lực nội sọ, tụt não (nguyên nhân tử vong chính) |\n| Xương | Đau, hạn chế vận động, liệt chi, chèn ép tủy |\n| Phúc mạc | Báng bụng tăng dần |\n| Hạch | Thất bại điều trị; đau chèn ép; phù bạch huyết (bẹn/chậu/cạnh ĐM chủ → phù chân; nách → phù tay); vỡ da; xâm lấn bó mạch đùi → chảy máu tử vong |\n- Hạch bẹn: thất bại chính của ung thư sinh dục ngoài; hạch cạnh ĐM chủ bụng: ung thư vùng chậu (cổ tử cung, nội mạc, buồng trứng, bàng quang, trực tràng).\n- Phẫu/xạ trị tại chỗ–vùng tốt; di căn khó vì tế bào lan nhiều nơi, tồn tại lâu, hóa trị thường không đủ.\n\n@@fold Ca lâm sàng minh họa (cổ tử cung) {{SY2 tr.399–424}}\n- Nữ 35 tuổi, Pap bất thường → CIN độ cao, không điều trị → 16 tháng sau chảy máu âm đạo, sùi 2,5 cm, **carcinôm gai xâm lấn grad 2** → cắt tử cung toàn bộ + 2 phần phụ + nạo hạch chậu (2/12 dương) + hóa xạ đồng thời.\n- > 4 năm sau: ho khan, hạch trên đòn trái 1,5 cm, hạch cạnh ĐM chủ bụng 4 cm, thận ứ nước, đa nốt hai phổi (di căn hạch + phổi), suy thận do chèn ép niệu quản.\n- Câu hỏi của slide: vì sao di căn hạch chậu; vì sao tổn thương mới sau nhiều năm; vì sao phải tái khám dù diện cắt âm tính.\n@@end\n\n> [!ext] Bổ sung (tham khảo; CHƯA tra cứu nguồn gốc, cần kiểm tra lại)\n> Di căn phụ thuộc cả vi môi trường bướu (tế bào mô đệm, viêm, miễn dịch) và hiện tượng \"ngủ đông\" tế bào di căn; xem thêm tổng quan NCI \"Metastatic Cancer\". *Nguồn: NCI, https://www.cancer.gov/types/metastatic-cancer*\n\n### Điểm hay thi\n> [!warn] Bẫy thường gặp\n> - Xâm lấn ≠ chèn ép; bướu lành chỉ chèn ép.\n> - Phổi: cơ quan di căn xa **nhiều nhất**; gan: nơi di căn **hay gặp nhất của ung thư tiêu hóa** (tĩnh mạch cửa).\n> - **Tĩnh mạch Batson** → vú, tuyến tiền liệt di căn xương (tiền liệt: tạo cốt bào).\n> - **Virchow** = hạch trên đòn **trái**, trạm cuối ống ngực.\n> - Paget **1889**, hạt giống và đất; di căn xa có thể rất muộn do tế bào ngủ đông.\n> - Cổ tử cung: tử vong thường do **suy thận sau thận** (siết niệu quản).\n> - Buồng trứng: gieo rắc phúc mạc → cắt mạc nối lớn; lymphô trước ở carcinôm, máu ở sarcôm.\n\n### Tự kiểm tra\n- Xâm lấn khác chèn ép ở điểm nào? :: Xâm lấn: tế bào bướu xâm nhiễm mô lân cận (phá vỏ bao, màng đáy); chèn ép: chỉ to ra, vỏ bao còn nguyên\n- Nêu 4 cơ chế xâm lấn tại chỗ. :: Tăng áp lực bướu; giảm cadherin; giảm gắn mô nền (MMP, enzym); di chuyển chân giả kiểu amíp\n- Ba đường di căn? :: Lymphô, máu, xoang/hốc tự nhiên\n- Vì sao phổi là nơi di căn xa nhiều nhất? :: Tế bào theo tĩnh mạch về tim phải, kẹt ở mao mạch phổi dày đặc\n- Vì sao ung thư tiêu hóa hay di căn gan? :: Theo tĩnh mạch cửa, kẹt ở xoang gan\n- Vì sao vú và tuyến tiền liệt hay di căn xương? :: Xương nhiều máu, mao mạch; tĩnh mạch Batson nối thẳng\n- Hạch Virchow ở đâu, ý nghĩa? :: Hạch trên đòn trái, trạm cuối ống ngực; thường coi như di căn xa\n- Thuyết hạt giống và đất do ai, năm nào? :: Stephen Paget, 1889\n- Ba nhóm gen trong mô hình động di căn? :: Sinh bướu, tiến triển di căn, độc lực di căn\n- Hậu quả chính khi cổ tử cung xâm lấn tại chỗ? :: Siết niệu quản → suy thận sau thận; dò bàng quang/trực tràng–âm đạo; phù chân, thận ứ nước, đau\n- Vì sao ung thư buồng trứng cắt mạc nối lớn? :: Mạc nối bắt tế bào gieo rắc phúc mạc\n- Di căn máu của ung thư vú ER dương hướng tới đâu? :: Xương"}, {"kind": "sources", "disease": "", "short": "", "group": "", "section": 0, "order": 0, "khung": [], "id": "nguon-tai-lieu", "title": "Nguồn tài liệu của module Ung bướu", "layer": "nen", "module": "ung-buou", "tags": ["nguồn", "tài liệu"], "source": "Các tài liệu trong thư mục Tài liệu/Ung bướu/", "body": "### Giáo trình và tài liệu gốc\n- **Giáo trình Y5**: Bài giảng Ung bướu học lâm sàng, tập 1 và 2, Bộ môn Ung thư ĐH Y Dược TP.HCM, 2020. **Tài liệu khác**: DeVita, Lawrence, Rosenberg (eds), *Cancer: Principles and Practice of Oncology*, 11th ed., 2019, Wolters Kluwer. {{ĐC Y5 tr.1}}\n- **Tài liệu Y2**: Rubin's Pathology: Clinical Pathologic Foundations of Medicine, 6th ed., 2012 (Rubin, Strayer). {{ĐC Y2 tr.4}}\n- **Tài liệu của người dùng trong kho** (`Tài liệu/Ung bướu/`): Đề cương Y5 (tr.1–13), Đề cương Y2 (tr.1–5), TEXT UNG BƯỚU Y5, Text elearning Y2, Slide tổng hợp Y2/Y5, QĐ 1514/QĐ-BYT, Phác đồ BYT (3128, 3898, 2549).\n- **Khung thi**: QĐ 22/QĐ-HĐYKQG ngày 21/4/2026 (`data/qd22.json`, trọng số mục 4.1 tr.7) và sách \"Các vấn đề lâm sàng thiết yếu\" (`data/khung-data.js`).\n- Chữ trích từ file `_work/decuong-y5.txt`, `_work/decuong-y2.txt`; các bảng (MT, blueprint, lịch) đối chiếu bằng ảnh trang PDF.\n- **Ngoài tài liệu**: chỉ có phần \"Gợi ý thêm\" trong trang [[ung-buou-tong-quan|Tổng quan module]] (người soạn gợi ý, chưa kiểm chứng); không dùng nguồn ngoài khác.\n\n### Văn bản Bộ Y tế đã dùng\n- **QĐ 1514/QĐ-BYT** (01/04/2020): Hướng dẫn chẩn đoán và điều trị một số bệnh ung bướu (Bài 33 ung thư phổi tế bào nhỏ, Bài 44 ung thư cổ tử cung…).\n- **QĐ 3128/QĐ-BYT** (17/07/2020): Hướng dẫn chẩn đoán và điều trị ung thư vú.\n- **QĐ 3898/QĐ-BYT** (2025): Hướng dẫn sàng lọc phát hiện sớm ung thư vú.\n- **QĐ 2549/QĐ-BYT** (19/04/2018): Hướng dẫn chẩn đoán và điều trị ung thư đại – trực tràng.\n- **QĐ 22/QĐ-HĐYKQG** (21/04/2026): danh mục 128 vấn đề cốt lõi và test blueprint (khung thi hành nghề).\n- Chưa có văn bản Bộ Y tế cho ung thư phổi không tế bào nhỏ trong tài liệu đã cung cấp."}, {"kind": "overview", "disease": "", "short": "", "group": "", "section": 0, "order": 0, "khung": [], "id": "ung-buou-tong-quan", "title": "Tổng quan module Ung bướu", "layer": "nen", "module": "ung-buou", "tags": ["ung bướu", "tổng quan", "giới thiệu", "mục tiêu", "danh mục bệnh"], "source": "Đề cương chi tiết Module Ung bướu Y5 (khóa 2025–2031) và Y2; QĐ 22/QĐ-HĐYKQG (danh mục vấn đề)", "body": "> [!key] Ung bướu trong một nhìn\n> - **Y2 (nền tảng)**: hiểu vì sao tế bào trở thành ung thư: cơ chế, nguyên nhân, u lành – ác, xâm lấn – di căn, miễn dịch. {{ĐC Y2 tr.1}}\n> - **Y5 (lâm sàng)**: diễn tiến tự nhiên, bệnh cảnh lâm sàng, nguyên tắc chẩn đoán và xử trí ung thư thường gặp ở Việt Nam. {{ĐC Y5 tr.1}}\n> - **Trọng tâm**: khám **tầm soát và phát hiện sớm** ung thư vú, cổ tử cung, đại trực tràng. {{ĐC Y5 tr.1}}\n> - Khung học: 1 Tổng quan → 2 Nền tảng → 3 Triệu chứng học → 4 Cận lâm sàng → 5 Bệnh học (chi tiết) → 6 Cấp cứu → 7 Bệnh án → 8 Tóm tắt.\n\n### 1. Giới thiệu chuyên khoa\n- {b|Bướu}: bệnh của rối loạn sinh sản tế bào; tăng sinh thoát khỏi sự kiểm soát của cơ thể. {{ĐC Y2 tr.1}}\n- {b|Ung thư}: bướu ác tính, xâm lấn mô quanh và di căn, đe dọa tính mạng. {{ĐC Y2 tr.1}}\n- **Chuyên khoa Ung bướu** nghiên cứu cơ chế và nguyên nhân sinh ung thư, diễn tiến tự nhiên, phòng ngừa và tầm soát, chẩn đoán và điều trị đa mô thức (phẫu, xạ, hóa, điều trị đích, miễn dịch…).\n- **Hai giai đoạn học**:\n  - Y2: nền tảng sinh học và bệnh học: cơ chế (gen sinh ung, gen đè nén bướu, chết tế bào theo lập trình), nguyên nhân (hóa, vật lý, sinh học, di truyền), đặc điểm u lành – ác, mối tương quan chủ – bướu, xâm lấn – di căn. {{ĐC Y2 tr.1}}\n  - Y5: bệnh học lâm sàng các ung thư thường gặp, từ tiếp cận triệu chứng, cận lâm sàng, chẩn đoán đến điều trị và dự phòng. {{ĐC Y5 tr.1}}\n- **Ung thư thường gặp tại Việt Nam** (theo đề cương): {b|gan, phổi, dạ dày, đại trực tràng, vòm hầu, tuyến tiền liệt, vú, cổ tử cung, nội mạc tử cung, tuyến giáp}. {{ĐC Y5 tr.1}}\n- **Liên quan chuyên khoa khác**: giải phẫu bệnh, sinh học phân tử, chẩn đoán hình ảnh, huyết học. {{ĐC Y5 tr.1}}\n\n### 2. Mục tiêu học tập (17 MT của đề cương Y5)\n> [!note] Đúng 17 mục tiêu MT1–MT17 của đề cương Y5 (mục 3 \"Mục tiêu môn học\", tr.1–4), giữ nghĩa theo đề cương. Nhóm: **Kiến thức** MT1–6 · **Kỹ năng** MT7–11 · **Thái độ** MT12–17. Dưới mỗi MT là các bài đã có trong module. Số § là tab của trang bệnh: §3 = 5.1 Tổng quan, §4 = 5.2 Triệu chứng, §5 = 5.3 Cận lâm sàng, §6 = 5.4 Chẩn đoán, §7 = 5.5 Điều trị, §8 = 5.7 Tiên lượng – Dự phòng, §9 = Tóm tắt.\n\n> [!warn] Trong bản đề cương, trang 3–4 có nhãn nhóm \"Kiến thức\" lặp lại trước MT9 và MT13, không khớp với nhãn \"Kỹ năng\" (trước MT7) và \"Thái độ\" (trước MT12). Tổng quan này nhóm theo nhãn \"Kỹ năng\" và \"Thái độ\" của đề cương.\n\nKiến thức nền Y2 (tăng sản – chuyển sản – loạn sản, gen sinh ung, nguyên nhân, diễn tiến) không tách thành MT riêng: [Giải phẫu bệnh ung thư](#/n/ung-thu-giai-phau-benh), [Cơ chế sinh ung thư](#/n/ung-thu-co-che-sinh-ung), [Nguyên nhân ung thư](#/n/ung-thu-nguyen-nhan).\n\n#### Kiến thức (MT1–MT6)\n- **MT1** Giải thích mối liên quan của chuyên ngành ung thư với các chuyên ngành khác (giải phẫu bệnh, sinh học phân tử, chẩn đoán hình ảnh). {{ĐC Y5 tr.1–2}}\n  - **Học ở:** [Giải phẫu bệnh ung thư](#/n/ung-thu-giai-phau-benh) · [Chẩn đoán giải phẫu bệnh](#/n/ung-thu-chan-doan-giai-phau-benh) · [Sinh học phân tử bệnh lý ung thư](#/n/ung-thu-sinh-hoc-phan-tu) · [Chẩn đoán hình ảnh trong ung thư](#/n/ung-thu-hinh-anh-chan-doan) · [Cận lâm sàng trong ung thư: vai trò](#/n/ung-thu-cls-vai-tro)\n- **MT2** Giải thích diễn tiến tự nhiên của một số ung thư thường gặp tại cộng đồng. {{ĐC Y5 tr.2}}\n  - **Học ở:** §3 \"Diễn tiến tự nhiên – lan tràn\" của 13 trang bệnh: [vú](#/n/ung-thu-vu/3) · [CTC](#/n/ung-thu-cotucung/3) · [NMTC](#/n/ung-thu-noi-mac-tu-cung/3) · [buồng trứng](#/n/ung-thu-buong-trung/3) · [ĐTT](#/n/ung-thu-daitruc-trang/3) · [dạ dày](#/n/ung-thu-da-day/3) · [gan](#/n/ung-thu-gan/3) · [phổi](#/n/ung-thu-phoi/3) · [TTL](#/n/ung-thu-tien-liet/3) · [hốc miệng](#/n/ung-thu-hoc-mieng-luoi/3) · [tuyến giáp](#/n/ung-thu-tuyen-giap/3) · [vòm hầu](#/n/ung-thu-vom-hau/3) · [thanh quản](#/n/ung-thu-thanh-quan/3). Nền tảng: [Sự xâm lấn và di căn](#/n/ung-thu-xam-lan-di-can).\n- **MT3** Vận dụng các nguyên tắc chẩn đoán và các phương tiện cận lâm sàng vào chẩn đoán các ung thư thường gặp tại cộng đồng. {{ĐC Y5 tr.2}}\n  - **Học ở:** nguyên tắc: [Tiếp cận chẩn đoán ung thư](#/n/ung-thu-tiep-can-chan-doan) · [Chọn phương tiện cận lâm sàng theo tình huống](#/n/ung-thu-cls-chon-phuong-tien) · [Nội soi và lấy bệnh phẩm](#/n/ung-thu-noi-soi-lay-benh-pham).\n  - §5 Cận lâm sàng của 13 trang bệnh: [vú](#/n/ung-thu-vu/5) · [CTC](#/n/ung-thu-cotucung/5) · [NMTC](#/n/ung-thu-noi-mac-tu-cung/5) · [buồng trứng](#/n/ung-thu-buong-trung/5) · [ĐTT](#/n/ung-thu-daitruc-trang/5) · [dạ dày](#/n/ung-thu-da-day/5) · [gan](#/n/ung-thu-gan/5) · [phổi](#/n/ung-thu-phoi/5) · [TTL](#/n/ung-thu-tien-liet/5) · [hốc miệng](#/n/ung-thu-hoc-mieng-luoi/5) · [tuyến giáp](#/n/ung-thu-tuyen-giap/5) · [vòm hầu](#/n/ung-thu-vom-hau/5) · [thanh quản](#/n/ung-thu-thanh-quan/5).\n  - §6 Chẩn đoán – chẩn đoán phân biệt của 13 trang bệnh: [vú](#/n/ung-thu-vu/6) · [CTC](#/n/ung-thu-cotucung/6) · [NMTC](#/n/ung-thu-noi-mac-tu-cung/6) · [buồng trứng](#/n/ung-thu-buong-trung/6) · [ĐTT](#/n/ung-thu-daitruc-trang/6) · [dạ dày](#/n/ung-thu-da-day/6) · [gan](#/n/ung-thu-gan/6) · [phổi](#/n/ung-thu-phoi/6) · [TTL](#/n/ung-thu-tien-liet/6) · [hốc miệng](#/n/ung-thu-hoc-mieng-luoi/6) · [tuyến giáp](#/n/ung-thu-tuyen-giap/6) · [vòm hầu](#/n/ung-thu-vom-hau/6) · [thanh quản](#/n/ung-thu-thanh-quan/6).\n- **MT4** Giải thích được nguyên lý của các mô thức điều trị ung thư. {{ĐC Y5 tr.2}}\n  - **Học ở:** [Nguyên lý các mô thức điều trị ung thư](#/n/ung-thu-nguyen-ly-dieu-tri) (mục đích điều trị, sáu mô thức, đa mô thức theo giai đoạn) · [Liệu pháp miễn dịch – cơ sở và các nhóm điều trị](#/n/ung-thu-mien-dich-tri-lieu) · [Sinh học phân tử – tín hiệu tăng sinh và điều trị đích](#/n/ung-thu-sinh-hoc-phan-tu) · §7.2 \"Các phương pháp\" (phẫu, xạ, hóa, đích, miễn dịch) của 13 trang bệnh: [vú](#/n/ung-thu-vu/7) · [CTC](#/n/ung-thu-cotucung/7) · [NMTC](#/n/ung-thu-noi-mac-tu-cung/7) · [buồng trứng](#/n/ung-thu-buong-trung/7) · [ĐTT](#/n/ung-thu-daitruc-trang/7) · [dạ dày](#/n/ung-thu-da-day/7) · [gan](#/n/ung-thu-gan/7) · [phổi](#/n/ung-thu-phoi/7) · [TTL](#/n/ung-thu-tien-liet/7) · [hốc miệng](#/n/ung-thu-hoc-mieng-luoi/7) · [tuyến giáp](#/n/ung-thu-tuyen-giap/7) · [vòm hầu](#/n/ung-thu-vom-hau/7) · [thanh quản](#/n/ung-thu-thanh-quan/7).\n- **MT5** Áp dụng được nguyên tắc điều trị để đưa ra hướng xử trí một số ung thư thường gặp tại cộng đồng. {{ĐC Y5 tr.2}}\n  - **Học ở:** §7 \"Điều trị\" (7.1 mục tiêu, 7.2 phương pháp, 7.3 phác đồ – y lệnh) của 13 trang bệnh: [vú](#/n/ung-thu-vu/7) · [CTC](#/n/ung-thu-cotucung/7) · [NMTC](#/n/ung-thu-noi-mac-tu-cung/7) · [buồng trứng](#/n/ung-thu-buong-trung/7) · [ĐTT](#/n/ung-thu-daitruc-trang/7) · [dạ dày](#/n/ung-thu-da-day/7) · [gan](#/n/ung-thu-gan/7) · [phổi](#/n/ung-thu-phoi/7) · [TTL](#/n/ung-thu-tien-liet/7) · [hốc miệng](#/n/ung-thu-hoc-mieng-luoi/7) · [tuyến giáp](#/n/ung-thu-tuyen-giap/7) · [vòm hầu](#/n/ung-thu-vom-hau/7) · [thanh quản](#/n/ung-thu-thanh-quan/7). Nền tảng: [Cách làm bệnh án ung thư](#/n/ung-thu-cach-lam-benh-an) (phần điều trị và tiên lượng).\n- **MT6** Áp dụng được các nguyên tắc tầm soát và phát hiện sớm ung thư vú, cổ tử cung, đại trực tràng tại cộng đồng. {{ĐC Y5 tr.2}}\n  - **Học ở:** [Tầm soát ung thư: nguyên tắc và khuyến cáo](#/n/ung-thu-tam-soat-nguyen-tac) · [Chọn phương tiện cận lâm sàng theo tình huống](#/n/ung-thu-cls-chon-phuong-tien) · §8 \"Dự phòng\" (có tầm soát): [Ung thư vú](#/n/ung-thu-vu/8) · [Ung thư cổ tử cung](#/n/ung-thu-cotucung/8) · [Ung thư đại trực tràng](#/n/ung-thu-daitruc-trang/8).\n\n#### Kỹ năng (MT7–MT11)\n- **MT7** Khám lâm sàng và ra chỉ định xét nghiệm cận lâm sàng để chẩn đoán một số ung thư thường gặp tại cộng đồng. {{ĐC Y5 tr.2}}\n  - **Học ở:** [Triệu chứng học ung thư: khái quát](#/n/ung-thu-trieu-chung-khai-quat) · [Từ triệu chứng đến ung thư theo cơ quan](#/n/ung-thu-trieu-chung-theo-co-quan) · [Cách làm bệnh án ung thư](#/n/ung-thu-cach-lam-benh-an) (phần khám và cận lâm sàng).\n  - §4 Triệu chứng học (có khám thực thể) của 13 trang bệnh: [vú](#/n/ung-thu-vu/4) · [CTC](#/n/ung-thu-cotucung/4) · [NMTC](#/n/ung-thu-noi-mac-tu-cung/4) · [buồng trứng](#/n/ung-thu-buong-trung/4) · [ĐTT](#/n/ung-thu-daitruc-trang/4) · [dạ dày](#/n/ung-thu-da-day/4) · [gan](#/n/ung-thu-gan/4) · [phổi](#/n/ung-thu-phoi/4) · [TTL](#/n/ung-thu-tien-liet/4) · [hốc miệng](#/n/ung-thu-hoc-mieng-luoi/4) · [tuyến giáp](#/n/ung-thu-tuyen-giap/4) · [vòm hầu](#/n/ung-thu-vom-hau/4) · [thanh quản](#/n/ung-thu-thanh-quan/4).\n  - §5 Cận lâm sàng (chỉ định theo tình huống) của 13 trang bệnh: xem danh sách ở MT3.\n- **MT8** Chỉ định đúng các hướng điều trị theo giai đoạn một số ung thư thường gặp. {{ĐC Y5 tr.2}}\n  - **Học ở:** [Phân giai đoạn ung thư theo TNM](#/n/ung-thu-phan-giai-doan-tnm) · §7 (7.2 theo giai đoạn, 7.3 phác đồ) của 13 trang bệnh: [vú](#/n/ung-thu-vu/7) · [CTC](#/n/ung-thu-cotucung/7) · [NMTC](#/n/ung-thu-noi-mac-tu-cung/7) · [buồng trứng](#/n/ung-thu-buong-trung/7) · [ĐTT](#/n/ung-thu-daitruc-trang/7) · [dạ dày](#/n/ung-thu-da-day/7) · [gan](#/n/ung-thu-gan/7) · [phổi](#/n/ung-thu-phoi/7) · [TTL](#/n/ung-thu-tien-liet/7) · [hốc miệng](#/n/ung-thu-hoc-mieng-luoi/7) · [tuyến giáp](#/n/ung-thu-tuyen-giap/7) · [vòm hầu](#/n/ung-thu-vom-hau/7) · [thanh quản](#/n/ung-thu-thanh-quan/7).\n- **MT9** Nhận biết được các hình ảnh nghi ngờ ác tính trên X quang, CT scan các ung thư thường gặp. {{ĐC Y5 tr.3}}\n  - **Học ở:** [Chẩn đoán hình ảnh trong ung thư](#/n/ung-thu-hinh-anh-chan-doan) (BI-RADS, dấu hiệu trên CT) · [Cận lâm sàng trong ung thư: vai trò](#/n/ung-thu-cls-vai-tro) · §5 \"Chẩn đoán hình ảnh\" có dấu hiệu nghi ác tính: [vú](#/n/ung-thu-vu/5) (BI-RADS, nhũ ảnh) · [phổi](#/n/ung-thu-phoi/5) (X quang ngực, CT ngực) · [gan §6](#/n/ung-thu-gan/6) (hình ảnh điển hình CT/MRI: tăng quang thì động mạch, thoát thuốc thì tĩnh mạch cửa) · [buồng trứng](#/n/ung-thu-buong-trung/5) (dấu gợi ý ác trên CT) · [ĐTT](#/n/ung-thu-daitruc-trang/5) (hạch nghi di căn trên CT) · [hốc miệng](#/n/ung-thu-hoc-mieng-luoi/5) (CT cản quang) · [thanh quản](#/n/ung-thu-thanh-quan/5) (CT lát mỏng: xâm lấn sụn, hạch cổ) · [tuyến giáp](#/n/ung-thu-tuyen-giap/5) (siêu âm: đặc điểm nghi ác và TIRADS; CT/MRI không phân biệt được lành – ác).\n  - Các trang còn lại có CT/MRI ở §5 nhưng chủ yếu đánh giá lan rộng và di căn, chưa rà riêng dấu hiệu nghi ác tính: [CTC §5](#/n/ung-thu-cotucung/5) · [NMTC §5](#/n/ung-thu-noi-mac-tu-cung/5) · [dạ dày §5](#/n/ung-thu-da-day/5) · [TTL §5](#/n/ung-thu-tien-liet/5) · [vòm hầu §5](#/n/ung-thu-vom-hau/5).\n- **MT10** Thực hiện được chuyển đúng tuyến chuyên khoa các trường hợp nghi ngờ ung thư cần xác định chẩn đoán. {{ĐC Y5 tr.3}}\n  - **Học ở:** [Chuyển tuyến chuyên khoa khi nghi ung thư](#/n/ung-thu-chuyen-tuyen) (tình huống nghi ngờ và việc cần làm; tuyến chuyên khoa và điều kiện cơ sở; ghi rõ những điểm tài liệu không nêu). Ý rải rác thêm: [Ung thư vú §4](#/n/ung-thu-vu/4) (nghi ngờ ác tính thì chuyển chuyên gia kèm hình ảnh hoặc lấy mẫu) · [Ung thư vú §8](#/n/ung-thu-vu/8) (cơ sở thiếu phương tiện: có tổn thương nghi ngờ thì chuyển chuyên khoa).\n- **MT11** Làm được hoàn chỉnh bệnh án ung thư. {{ĐC Y5 tr.3}}\n  - **Học ở:** [Cách làm bệnh án ung thư](#/n/ung-thu-cach-lam-benh-an) (mục **7 Bệnh án**: 9 phần bệnh án; ghi tóm tắt theo giai đoạn).\n\n#### Thái độ (MT12–MT17)\n- **MT12** Ý thức được ung thư là vấn đề sức khỏe quan trọng và có thể phòng ngừa, chẩn đoán sớm. {{ĐC Y5 tr.3}}\n  - **Học ở:** [Phòng ngừa ung thư: các bậc phòng ngừa](#/n/ung-thu-phong-ngua) · [Phòng ngừa bằng thuốc, vắc-xin, phẫu thuật](#/n/ung-thu-phong-ngua-thuoc-vacxin-phau-thuat) · [Nguyên nhân, tác nhân và phòng ngừa](#/n/ung-thu-nguyen-nhan-vat-ly-sinh-hoc-di-truyen) · [Tầm soát ung thư: nguyên tắc](#/n/ung-thu-tam-soat-nguyen-tac) · [Bảy triệu chứng báo động](#/n/ung-thu-bay-trieu-chung) (phát hiện sớm) · §8 \"Dự phòng\" của 13 trang bệnh: [vú](#/n/ung-thu-vu/8) · [CTC](#/n/ung-thu-cotucung/8) · [NMTC](#/n/ung-thu-noi-mac-tu-cung/8) · [buồng trứng](#/n/ung-thu-buong-trung/8) · [ĐTT](#/n/ung-thu-daitruc-trang/8) · [dạ dày](#/n/ung-thu-da-day/8) · [gan](#/n/ung-thu-gan/8) · [phổi](#/n/ung-thu-phoi/8) · [TTL](#/n/ung-thu-tien-liet/8) · [hốc miệng](#/n/ung-thu-hoc-mieng-luoi/8) · [tuyến giáp](#/n/ung-thu-tuyen-giap/8) · [vòm hầu](#/n/ung-thu-vom-hau/8) · [thanh quản](#/n/ung-thu-thanh-quan/8).\n- **MT13** Cảnh giác với các triệu chứng báo động ung thư. {{ĐC Y5 tr.4}}\n  - **Học ở:** [Bảy triệu chứng báo động](#/n/ung-thu-bay-trieu-chung) · [Triệu chứng học ung thư: khái quát](#/n/ung-thu-trieu-chung-khai-quat) (mục dấu hiệu báo động) · [Từ triệu chứng đến ung thư theo cơ quan](#/n/ung-thu-trieu-chung-theo-co-quan) · [Hội chứng cận u, chèn ép và biến chứng cấp](#/n/ung-thu-hoi-chung-can-u-va-chen-ep) · [mục 6 Cấp cứu](#/m/ung-buou/6) · §4 \"Triệu chứng học\" của 13 trang bệnh: [vú](#/n/ung-thu-vu/4) · [CTC](#/n/ung-thu-cotucung/4) · [NMTC](#/n/ung-thu-noi-mac-tu-cung/4) · [buồng trứng](#/n/ung-thu-buong-trung/4) · [ĐTT](#/n/ung-thu-daitruc-trang/4) · [dạ dày](#/n/ung-thu-da-day/4) · [gan](#/n/ung-thu-gan/4) · [phổi](#/n/ung-thu-phoi/4) · [TTL](#/n/ung-thu-tien-liet/4) · [hốc miệng](#/n/ung-thu-hoc-mieng-luoi/4) · [tuyến giáp](#/n/ung-thu-tuyen-giap/4) · [vòm hầu](#/n/ung-thu-vom-hau/4) · [thanh quản](#/n/ung-thu-thanh-quan/4).\n- **MT14** Tuân thủ các nguyên tắc chẩn đoán ung thư, nhất là sự tương hợp giữa lâm sàng và các xét nghiệm. {{ĐC Y5 tr.4}}\n  - **Học ở:** [Tiếp cận chẩn đoán ung thư](#/n/ung-thu-tiep-can-chan-doan) (GPB không tương hợp lâm sàng, hình ảnh thì xem lại, hội chẩn lại) · [Chẩn đoán giải phẫu bệnh](#/n/ung-thu-chan-doan-giai-phau-benh) · [Nội soi và lấy bệnh phẩm](#/n/ung-thu-noi-soi-lay-benh-pham) · §6 \"Chẩn đoán – chẩn đoán phân biệt\" của 13 trang bệnh: [vú](#/n/ung-thu-vu/6) · [CTC](#/n/ung-thu-cotucung/6) · [NMTC](#/n/ung-thu-noi-mac-tu-cung/6) · [buồng trứng](#/n/ung-thu-buong-trung/6) · [ĐTT](#/n/ung-thu-daitruc-trang/6) · [dạ dày](#/n/ung-thu-da-day/6) · [gan](#/n/ung-thu-gan/6) · [phổi](#/n/ung-thu-phoi/6) · [TTL](#/n/ung-thu-tien-liet/6) · [hốc miệng](#/n/ung-thu-hoc-mieng-luoi/6) · [tuyến giáp](#/n/ung-thu-tuyen-giap/6) · [vòm hầu](#/n/ung-thu-vom-hau/6) · [thanh quản](#/n/ung-thu-thanh-quan/6).\n- **MT15** Tuân thủ các nguyên tắc điều trị ung thư, nhất là phối hợp đa mô thức, liên chuyên khoa. {{ĐC Y5 tr.4}}\n  - **Học ở:** [Cách làm bệnh án ung thư](#/n/ung-thu-cach-lam-benh-an) (tiến xa tại vùng: đa mô thức, liên chuyên khoa) · §7 \"Điều trị\" có nêu đa mô thức hoặc hội chẩn: [ĐTT §7](#/n/ung-thu-daitruc-trang/7) (điều trị đa mô thức và hội chẩn) · [hốc miệng §7](#/n/ung-thu-hoc-mieng-luoi/7) (giai đoạn III–IV đa mô thức) · [vòm hầu §7](#/n/ung-thu-vom-hau/7) (xạ trị là chính, hóa xạ đồng thời từ giai đoạn II) · [TTL §7](#/n/ung-thu-tien-liet/7) (hội chẩn đa chuyên khoa) · [thanh quản §7](#/n/ung-thu-thanh-quan/7) (cần đội ngũ đa chuyên khoa).\n- **MT16** Tôn trọng và đồng cảm với bệnh nhân và thân nhân bệnh nhân trong các thủ thuật, bệnh nặng, bệnh tử vong. {{ĐC Y5 tr.4}}\n  - **Học ở:** [Giao tiếp, báo tin xấu và chăm sóc giảm nhẹ](#/n/ung-thu-giao-tiep-cham-soc-giam-nhe) (giao tiếp và báo tin xấu, thái độ khi làm thủ thuật, chăm sóc giảm nhẹ, hỗ trợ thân nhân). Ý rải rác thêm: [Ung thư vú §7](#/n/ung-thu-vu/7) (cá thể hóa theo ý muốn bệnh nhân, tâm lý, thẩm mỹ) · [Ung thư gan §7](#/n/ung-thu-gan/7) (nhiều bệnh nhân tử vong dù điều trị gì, cần chăm sóc giảm nhẹ).\n- **MT17** Hợp tác tốt với đồng nghiệp trong cách làm việc liên chuyên khoa. {{ĐC Y5 tr.4}}\n  - **Học ở:** [Hội chẩn và phối hợp liên chuyên khoa](#/n/ung-thu-hoi-chan-lien-chuyen-khoa) (vai trò từng chuyên khoa, trình tự điều trị đa mô thức, trình bệnh và ghi kết luận hội chẩn). Ý rải rác thêm: [Cách làm bệnh án ung thư](#/n/ung-thu-cach-lam-benh-an) (tiến xa tại vùng: liên chuyên khoa) · [Tiếp cận chẩn đoán ung thư](#/n/ung-thu-tiep-can-chan-doan) (GPB không tương hợp thì hội chẩn lại) · [CTC §6](#/n/ung-thu-cotucung/6) (hội chẩn khi chẩn đoán phân biệt) · [ĐTT §7](#/n/ung-thu-daitruc-trang/7) · [dạ dày §7](#/n/ung-thu-da-day/7) (đánh giá giai đoạn bởi nhóm đa chuyên khoa) · [TTL §7](#/n/ung-thu-tien-liet/7) (hội chẩn đa chuyên khoa) · [thanh quản §7](#/n/ung-thu-thanh-quan/7) · [hốc miệng §8](#/n/ung-thu-hoc-mieng-luoi/8) (đánh giá đa chuyên khoa).\n\n> [!tip] Tình trạng: **17/17 MT** có bài riêng hoặc phần trong bài bệnh. Bốn MT vừa bổ sung bài riêng: MT4 (nguyên lý điều trị), MT10 (chuyển tuyến), MT16 (giao tiếp, thủ thuật, chăm sóc giảm nhẹ), MT17 (hội chẩn).\n\n### 3. Các bệnh và vấn đề cần học\n@@tabs\n@@tab Bệnh có trang (13/13)\n| Bệnh | Khung thi (STT) | Mở |\n|---|---|---|\n| [Ung thư vú](#/n/ung-thu-vu) | [85](#/khung/85) | [5.1 Tổng quan](#/n/ung-thu-vu/3) · [5.5 Điều trị](#/n/ung-thu-vu/7) · [Tóm tắt](#/n/ung-thu-vu/9) |\n| [Ung thư cổ tử cung](#/n/ung-thu-cotucung) | [92](#/khung/92), [87](#/khung/87), [91](#/khung/91) | [5.1 Tổng quan](#/n/ung-thu-cotucung/3) · [5.5 Điều trị](#/n/ung-thu-cotucung/7) · [Tóm tắt](#/n/ung-thu-cotucung/9) |\n| [Ung thư nội mạc tử cung](#/n/ung-thu-noi-mac-tu-cung) | [87](#/khung/87), [89](#/khung/89), [91](#/khung/91) | [5.1 Tổng quan](#/n/ung-thu-noi-mac-tu-cung/3) · [5.5 Điều trị](#/n/ung-thu-noi-mac-tu-cung/7) · [Tóm tắt](#/n/ung-thu-noi-mac-tu-cung/9) |\n| [Ung thư buồng trứng](#/n/ung-thu-buong-trung) | [53](#/khung/53), [54](#/khung/54), [55](#/khung/55), [87](#/khung/87), [91](#/khung/91), [99](#/khung/99) | [5.1 Tổng quan](#/n/ung-thu-buong-trung/3) · [5.5 Điều trị](#/n/ung-thu-buong-trung/7) · [Tóm tắt](#/n/ung-thu-buong-trung/9) |\n| [Ung thư đại trực tràng](#/n/ung-thu-daitruc-trang) | [64](#/khung/64), [57](#/khung/57), [61](#/khung/61) | [5.1 Tổng quan](#/n/ung-thu-daitruc-trang/3) · [5.5 Điều trị](#/n/ung-thu-daitruc-trang/7) · [Tóm tắt](#/n/ung-thu-daitruc-trang/9) |\n| [Ung thư dạ dày](#/n/ung-thu-da-day) | [7](#/khung/7), [49](#/khung/49), [50](#/khung/50), [52](#/khung/52), [54](#/khung/54), [56](#/khung/56), [99](#/khung/99) | [5.1 Tổng quan](#/n/ung-thu-da-day/3) · [5.5 Điều trị](#/n/ung-thu-da-day/7) · [Tóm tắt](#/n/ung-thu-da-day/9) |\n| [Ung thư gan](#/n/ung-thu-gan) | [53](#/khung/53), [54](#/khung/54), [55](#/khung/55), [56](#/khung/56), [62](#/khung/62), [63](#/khung/63), [99](#/khung/99) | [5.1 Tổng quan](#/n/ung-thu-gan/3) · [5.5 Điều trị](#/n/ung-thu-gan/7) · [Tóm tắt](#/n/ung-thu-gan/9) |\n| [Ung thư phổi](#/n/ung-thu-phoi) | [41](#/khung/41), [47](#/khung/47), [40](#/khung/40), [46](#/khung/46) | [5.1 Tổng quan](#/n/ung-thu-phoi/3) · [5.5 Điều trị](#/n/ung-thu-phoi/7) · [Tóm tắt](#/n/ung-thu-phoi/9) |\n| [Ung thư tuyến tiền liệt](#/n/ung-thu-tien-liet) | [65](#/khung/65), [66](#/khung/66), [67](#/khung/67), [99](#/khung/99) | [5.1 Tổng quan](#/n/ung-thu-tien-liet/3) · [5.5 Điều trị](#/n/ung-thu-tien-liet/7) · [Tóm tắt](#/n/ung-thu-tien-liet/9) |\n| [Ung thư hốc miệng (lưỡi)](#/n/ung-thu-hoc-mieng-luoi) | [23](#/khung/23), [50](#/khung/50), [96](#/khung/96), [105](#/khung/105) | [5.1 Tổng quan](#/n/ung-thu-hoc-mieng-luoi/3) · [5.5 Điều trị](#/n/ung-thu-hoc-mieng-luoi/7) · [Tóm tắt](#/n/ung-thu-hoc-mieng-luoi/9) |\n| [Ung thư tuyến giáp](#/n/ung-thu-tuyen-giap) | [95](#/khung/95), [96](#/khung/96) | [5.1 Tổng quan](#/n/ung-thu-tuyen-giap/3) · [5.5 Điều trị](#/n/ung-thu-tuyen-giap/7) · [Tóm tắt](#/n/ung-thu-tuyen-giap/9) |\n| [Ung thư vòm hầu](#/n/ung-thu-vom-hau) | [15](#/khung/15), [23](#/khung/23), [38](#/khung/38), [96](#/khung/96) | [5.1 Tổng quan](#/n/ung-thu-vom-hau/3) · [5.5 Điều trị](#/n/ung-thu-vom-hau/7) · [Tóm tắt](#/n/ung-thu-vom-hau/9) |\n| [Ung thư thanh quản](#/n/ung-thu-thanh-quan) | [38](#/khung/38), [39](#/khung/39), [40](#/khung/40), [41](#/khung/41), [43](#/khung/43), [44](#/khung/44), [50](#/khung/50), [96](#/khung/96) | [5.1 Tổng quan](#/n/ung-thu-thanh-quan/3) · [5.5 Điều trị](#/n/ung-thu-thanh-quan/7) · [Tóm tắt](#/n/ung-thu-thanh-quan/9) |\n\n> [!note] Đủ 13 bệnh theo đề cương, mỗi bệnh có trang trong `benh/`. Cột Khung thi lấy từ khung 128 vấn đề (QĐ 22) đã gắn cho từng trang.\n\n@@tab Chưa có trang\n- Ngoài 13 bệnh trên, các chủ đề chưa có trang được ghi trong cột \"Bệnh/trang liên quan\" của hai bảng khung 128 vấn đề bên dưới (bạch cầu – lymphoma, u tinh hoàn, phúc mạc, thực quản, u đường niệu, u đầu tụy – đường mật, kiểm soát đau).\n\n> [!warn] Đề cương Y5 dùng \"ung thư đại tràng\" và \"ung thư trực tràng\" như hai chủ đề riêng; trang bệnh ở đây gộp thành \"đại trực tràng\" theo khung 128 vấn đề.\n@@end\n\n#### Vấn đề trong khung 128 liên quan ung bướu\n> [!note] Ung bướu không có đề mục riêng trong khung 128 vấn đề; các vấn đề ung thư nằm rải trong các hệ cơ quan.\n\n\n@@tabs\n@@tab Nhãn Ung bướu sẵn có\n> [!note] 12 vấn đề dưới đây được đánh dấu liên quan ung bướu theo cách phân loại gợi ý; chưa có tài liệu nào xác nhận danh sách này.\n\n| STT | Tên vấn đề | Hệ (đề mục) | Bệnh/ trang liên quan |\n|---|---|---|---|\n| [Khung STT 8](#/khung/8) | Bất thường tế bào bạch cầu | 2 Máu – Lưới – Bạch huyết | Bệnh bạch cầu, lymphoma (chưa có trang bệnh) |\n| [Khung STT 41](#/khung/41) | Ho ra máu | 8 Hô hấp | [Ung thư phổi – Triệu chứng](#/n/ung-thu-phoi/4) |\n| [Khung STT 47](#/khung/47) | Bất thường X quang ngực | 8 Hô hấp | [Ung thư phổi – Cận lâm sàng](#/n/ung-thu-phoi/5) |\n| [Khung STT 54](#/khung/54) | Khối ở bụng | 9 Tiêu hóa | U gan: [Ung thư gan – Triệu chứng](#/n/ung-thu-gan/4); u ổ bụng khác (chưa có trang) |\n| [Khung STT 59](#/khung/59) | Khối ở bẹn bìu | 9 Tiêu hóa | U tinh hoàn (chưa có trang bệnh) |\n| [Khung STT 64](#/khung/64) | Tầm soát ung thư đại trực tràng | 9 Tiêu hóa | [Ung thư đại trực tràng – Dự phòng](#/n/ung-thu-daitruc-trang/8) |\n| [Khung STT 85](#/khung/85) | Khối ở vú – Tầm soát ung thư vú | 12 Sinh dục, Vú, SKSS | [Ung thư vú – Triệu chứng](#/n/ung-thu-vu/4), [Dự phòng](#/n/ung-thu-vu/8) |\n| [Khung STT 91](#/khung/91) | Khối vùng chậu | 12 Sinh dục, Vú, SKSS | [Ung thư buồng trứng – Triệu chứng](#/n/ung-thu-buong-trung/4), [Ung thư nội mạc tử cung – Triệu chứng](#/n/ung-thu-noi-mac-tu-cung/4), [Ung thư cổ tử cung – Triệu chứng](#/n/ung-thu-cotucung/4) (một phần) |\n| [Khung STT 92](#/khung/92) | Tầm soát ung thư cổ tử cung | 12 Sinh dục, Vú, SKSS | [Ung thư cổ tử cung – Dự phòng](#/n/ung-thu-cotucung/8) |\n| [Khung STT 96](#/khung/96) | Khối ở cổ | 13 Nội tiết – Dinh dưỡng – CH | [Ung thư tuyến giáp – Triệu chứng](#/n/ung-thu-tuyen-giap/4), [Ung thư vòm hầu – Triệu chứng](#/n/ung-thu-vom-hau/4), [Ung thư thanh quản – Triệu chứng](#/n/ung-thu-thanh-quan/4), [Ung thư hốc miệng – Triệu chứng](#/n/ung-thu-hoc-mieng-luoi/4) (hạch cổ) |\n| [Khung STT 99](#/khung/99) | Sụt cân / suy dinh dưỡng / tư vấn chế độ ăn | 13 Nội tiết – Dinh dưỡng – CH | Sụt cân là dấu hiệu nghi ung thư: [[ung-thu-bay-trieu-chung]] |\n| [Khung STT 108](#/khung/108) | Kiểm soát đau | 14 Rối loạn đa cơ quan | Đau do ung thư; liên quan CSGN trong Y5 (chưa có trang) |\n\n@@tab Gợi ý thêm (của người soạn)\n> [!ext] Các STT dưới đây do **người soạn trang gợi ý**, ngoài danh sách nhãn có sẵn; **ngoài tài liệu**, dựa trên việc triệu chứng có thể do ung thư. Chưa kiểm tra nội dung sách 128VĐ từng mục; cần bạn xác nhận trước khi dùng.\n\n| STT | Tên vấn đề | Lý do gợi ý (ung thư cần nghĩ tới) | Trang liên quan |\n|---|---|---|---|\n| [Khung STT 7](#/khung/7) | Thiếu máu | Mất máu rỉ rả (đại trực tràng); thâm nhiễm tủy | [Ung thư đại trực tràng – Triệu chứng](#/n/ung-thu-daitruc-trang/4) |\n| [Khung STT 39](#/khung/39) | Khàn tiếng | Ung thư thanh quản (có CBL trong Y5) | [Ung thư thanh quản – Triệu chứng](#/n/ung-thu-thanh-quan/4) |\n| [Khung STT 40](#/khung/40) | Ho đàm – ho khan | Ung thư phổi | [Ung thư phổi – Triệu chứng](#/n/ung-thu-phoi/4) |\n| [Khung STT 46](#/khung/46) | Tràn dịch màng phổi | Tràn dịch ác tính | [Ung thư phổi – Triệu chứng](#/n/ung-thu-phoi/4) |\n| [Khung STT 50](#/khung/50) | Nghẹn, nuốt khó | Ung thư thực quản/ dạ dày | [Ung thư dạ dày – Triệu chứng](#/n/ung-thu-da-day/4); thực quản: chưa có trang |\n| [Khung STT 53](#/khung/53) | Báng bụng (cổ trướng) | Ung thư gan, buồng trứng, phúc mạc | [Ung thư gan – Triệu chứng](#/n/ung-thu-gan/4) · [Ung thư buồng trứng – Triệu chứng](#/n/ung-thu-buong-trung/4); phúc mạc: chưa có trang |\n| [Khung STT 57](#/khung/57) | Xuất huyết tiêu hóa dưới | Ung thư đại trực tràng | [Ung thư đại trực tràng – Triệu chứng](#/n/ung-thu-daitruc-trang/4) |\n| [Khung STT 61](#/khung/61) | Táo bón, thay đổi thói quen đi tiêu | Ung thư đại trực tràng | [Ung thư đại trực tràng – Triệu chứng](#/n/ung-thu-daitruc-trang/4) |\n| [Khung STT 62](#/khung/62) | Vàng da | U đầu tụy, đường mật, gan | Chưa có trang |\n| [Khung STT 66](#/khung/66) | Rối loạn đi tiểu | Ung thư tuyến tiền liệt (có CBL trong Y5) | [Ung thư tuyến tiền liệt – Triệu chứng](#/n/ung-thu-tien-liet/4) |\n| [Khung STT 67](#/khung/67) | Tiểu máu | U đường niệu | Chưa có trang |\n| [Khung STT 87](#/khung/87) | Xuất huyết âm đạo – tử cung bất thường | Ung thư cổ tử cung, nội mạc tử cung | [Ung thư nội mạc tử cung – Triệu chứng](#/n/ung-thu-noi-mac-tu-cung/4) · [Ung thư cổ tử cung – Triệu chứng](#/n/ung-thu-cotucung/4) |\n| [Khung STT 107](#/khung/107) | Tầm soát bệnh không triệu chứng – khám sức khỏe định kỳ | Tầm soát ung thư nói chung | [[ung-thu-tam-soat-nguyen-tac]] |\n@@end"}];
